<?php

declare(strict_types=1);

namespace PortLibs\Pandoc;

use PortLibs\MarkerPDF\PdfMetadataExtractor;
use PortLibs\MarkerPDF\PdfDocumentFacts;
use PortLibs\MarkerPDF\PdfTextExtractor;

final class PdfReader
{
    private const DEFAULT_MAX_TEXT_BYTES = PHP_INT_MAX;
    private const DEFAULT_FAST_MODE_BYTES = 0;
    private const PDF_CODE_BLOCK_PREFIX = "\x1EPDF-CODE\x1F";
    private const PDF_MAP_LABEL_PREFIX = "\x1EPDF-MAP-LABEL\x1F";
    private const PDF_NUMBERED_HEADING_PREFIX = "\x1EPDF-NUMBERED-HEADING\x1F";
    private const PDF_NUMBERED_SUBHEADING_PREFIX = "\x1EPDF-NUMBERED-SUBHEADING\x1F";
    private const PDF_DISPLAY_HEADING_PREFIX = "\x1EPDF-DISPLAY-HEADING\x1F";
    private const PDF_LAYOUT_LABEL_PREFIX = "\x1EPDF-LAYOUT-LABEL\x1F";
    private const PDF_FRONT_MATTER_PREFIX = "\x1EPDF-FRONT-MATTER\x1F";
    private const PDF_LINE_BLOCK_PREFIX = "\x1EPDF-LINE-BLOCK\x1F";
    private const PDF_OUTPUT_PAGE_PROOF_ATTR = 'sourcePdfOutputPageProof';
    private const MAX_PDF_CLIPPED_ARTIFACT_MEDIA_ANCHOR_PROOFS = 64;
    private const MAX_PDF_LIST_MARKER_ANCHOR_OCCURRENCES = 16;
    private const PDF_PAGE_RASTER_TARGET_SCALE = 2.0;
    private const MAX_PDF_PAGE_RASTER_PIXELS = 16000000;
    private const MAX_PDF_PAGE_RASTER_DIMENSION = 8192;
    private const PDF_RTL_SHAPING_CLUSTER_START = "\u{F0000}";
    private const PDF_RTL_SHAPING_CLUSTER_END = "\u{F0001}";
    // A temporary word joiner preserves a compact source/geometry identifier
    // through the later, deliberately conservative prose-spacing pass.
    private const PDF_SOURCE_COMPACT_IDENTIFIER_BOUNDARY = "\u{2060}";
    private int $lowConfidenceGeometryTableCandidates = 0;
    private int $lineOrientedRegionCount = 0;
    private int $interGlyphSpacingRepairCount = 0;
    private int $controlCharacterRepairCount = 0;
    private int $controlCharacterBulletRepairCount = 0;
    private int $inferredHeadingBoundaryCount = 0;
    private int $frontMatterRecordCount = 0;
    private int $inlineMarkerRecordCount = 0;
    private int $formulaRegionCount = 0;
    private int $rotatedRegionCount = 0;
    private int $rotatedRegionPreservedCount = 0;
    private int $runningFurnitureRegionRemovedCount = 0;
    private int $geometryLayoutHypothesisCount = 0;
    private int $geometryLayoutHypothesisTruncatedCount = 0;
    private int $independentColumnHypothesisCount = 0;
    /** @var list<array<string, mixed>> */
    private array $geometryLayoutHypotheses = [];
    /** @var array<int, list<AstNode>> */
    private array $independentColumnBlocksByPage = [];

    /** @var array<int,list<AstNode>> */
    private array $sourceProofCandidateBlocksByPage = [];
    /** @var array<string, mixed>|null */
    private ?array $lastGeometryLayoutHypothesis = null;
    /** @var array<string, mixed> */
    private array $documentLayoutProfile = [];
    /** @var array<int, list<array{text:string,key:string,orientation:string,start:int,end:int,fragments:list<string>}>> */
    private array $rotatedTextRegionsByPage = [];
    /** @var array<int, list<array{text:string,key:string,orientation:string,start:int,end:int,fragments:list<string>}>> */
    private array $tableExcludedRotatedTextRegionsByPage = [];
    /** @var array<string, true> */
    private array $interGlyphSpacingRepairKeys = [];
    /** @var list<array{run:int,stages:list<array<string,mixed>>}> */
    private array $semanticPipelineTrace = [];
    /** @var list<array<string,mixed>> */
    private array $sourceOrderProofDiagnostics = [];
    /** @var array<string,array<string,mixed>> */
    private array $removedPageNumberFurnitureProofsBySourceId = [];
    /** @var array<string,array<string,mixed>> */
    private array $deferredSinglePageNumberFurnitureProofsBySourceId = [];
    /** @var array<string,array<string,mixed>> */
    private array $sourcePdfOverprintedDuplicateArtifactProofsBySourceId = [];
    /** @var array<string,array<string,mixed>|false> */
    private array $sourcePdfChartCipherArtifactProofsBySourceId = [];
    /** @var array<string,array<string,mixed>> */
    private array $sourcePdfMapGlyphLadderArtifactProofsBySourceId = [];
    /** @var array<string,true> */
    private array $sourcePdfChartCipherArtifactProjectionDigests = [];
    /** @var array<string,array<string,mixed>|false> */
    private array $sourceOccurrenceIdentityByWholeProofDigest = [];
    /** @var array<int, true> */
    private array $layoutLabelSourceIndexes = [];
    /** @var list<array<string,mixed>> */
    private array $pdfInlineFontStyleProofCandidates = [];
    /** @var list<array<string,mixed>> */
    private array $pdfCrossPageListContinuationOrderProofCandidates = [];
    /** @var list<array<string,mixed>> */
    private array $pdfSemanticEmailDelimiterRepairProofCandidates = [];
    /** @var list<array<string,mixed>> */
    private array $positionedPdfTableBandHomologyTemplates = [];
    /** @var list<array<string,mixed>> */
    private array $positionedPdfDisplayTokenRepairProofs = [];
    private string $sourceSha256 = '';

    /**
     * @param array{maxTextBytes?: int, startPage?: int, pdfStartPage?: int, start_page?: int, maxPages?: int, pdfMaxPages?: int, max_pages?: int, password?: string, pdfPassword?: string, geometryTables?: bool, pdfGeometryTables?: bool, extractGeometryTables?: bool, pdfRepairProseText?: bool, repairProseText?: bool, pdfFastTextOnly?: bool, fastTextOnly?: bool, pdfFastModeBytes?: int, pdfFastMaxPages?: int, maxPositionedTextRuns?: int, pdfMaxPositionedTextRuns?: int, pdfCollectImagePlacements?: bool, collectPdfImagePlacements?: bool, pdfCollectFormXObjectPlacements?: bool, collectPdfFormXObjectPlacements?: bool, pdfDocumentFacts?: PdfDocumentFacts|array<string,mixed>, pdfReaderStructuralMetadata?: array<string,mixed>, pdfReaderMetadata?: array<string,mixed>, __pdfMemoryCheckpointPreloadClass?: class-string} $options
     */
    public function __construct(private readonly array $options = [])
    {
    }

    public function read(string $pdfBytes): AstNode
    {
        return $this->readPdf($pdfBytes);
    }

    /**
     * Read a caller-owned PDF buffer and release it after every parser-backed
     * query is complete. File-backed imports use this path so the source bytes
     * do not remain resident while the final source-binding graph is built.
     */
    public function readOwned(string &$pdfBytes): AstNode
    {
        return $this->readPdf($pdfBytes);
    }

    private function readPdf(string &$pdfBytes): AstNode
    {
        $this->sourceSha256 = hash('sha256', $pdfBytes);
        $this->lowConfidenceGeometryTableCandidates = 0;
        $this->lineOrientedRegionCount = 0;
        $this->interGlyphSpacingRepairCount = 0;
        $this->controlCharacterRepairCount = 0;
        $this->controlCharacterBulletRepairCount = 0;
        $this->inferredHeadingBoundaryCount = 0;
        $this->frontMatterRecordCount = 0;
        $this->inlineMarkerRecordCount = 0;
        $this->formulaRegionCount = 0;
        $this->rotatedRegionCount = 0;
        $this->rotatedRegionPreservedCount = 0;
        $this->runningFurnitureRegionRemovedCount = 0;
        $this->geometryLayoutHypothesisCount = 0;
        $this->geometryLayoutHypothesisTruncatedCount = 0;
        $this->independentColumnHypothesisCount = 0;
        $this->geometryLayoutHypotheses = [];
        $this->independentColumnBlocksByPage = [];
        $this->sourceProofCandidateBlocksByPage = [];
        $this->lastGeometryLayoutHypothesis = null;
        $this->documentLayoutProfile = [];
        $this->rotatedTextRegionsByPage = [];
        $this->tableExcludedRotatedTextRegionsByPage = [];
        $this->interGlyphSpacingRepairKeys = [];
        $this->semanticPipelineTrace = [];
        $this->sourceOrderProofDiagnostics = [];
        $this->removedPageNumberFurnitureProofsBySourceId = [];
        $this->deferredSinglePageNumberFurnitureProofsBySourceId = [];
        $this->sourcePdfOverprintedDuplicateArtifactProofsBySourceId = [];
        $this->sourcePdfChartCipherArtifactProofsBySourceId = [];
        $this->sourcePdfMapGlyphLadderArtifactProofsBySourceId = [];
        $this->sourcePdfChartCipherArtifactProjectionDigests = [];
        $this->sourceOccurrenceIdentityByWholeProofDigest = [];
        $this->layoutLabelSourceIndexes = [];
        $this->pdfInlineFontStyleProofCandidates = [];
        $this->pdfCrossPageListContinuationOrderProofCandidates = [];
        $this->pdfSemanticEmailDelimiterRepairProofCandidates = [];
        $this->positionedPdfTableBandHomologyTemplates = [];
        $this->positionedPdfDisplayTokenRepairProofs = [];

        if (!class_exists(PdfTextExtractor::class)) {
            throw new \RuntimeException('PDF reading needs PortLibs\\MarkerPDF\\PdfTextExtractor.');
        }
        // Compile the aggregate fidelity audit while the request is still
        // nearly empty; its packed inventory is used only after geometry
        // state is freed.
        class_exists(PdfTextFidelityLedger::class);
        $suppliedDocumentFacts = $this->suppliedDocumentFacts($pdfBytes);
        $this->documentLayoutProfile = $this->documentLayoutProfileFromFacts($suppliedDocumentFacts);
        $suppliedStructuralMetadata = $this->options['pdfReaderStructuralMetadata'] ?? null;
        $structuralMetadata = is_array($suppliedStructuralMetadata)
            ? $this->structuralMetadataFromDocumentMetadata($pdfBytes, $suppliedStructuralMetadata)
            : $this->structuralMetadata($pdfBytes);
        if ($suppliedDocumentFacts !== null) {
            $structuralMetadata['pdfFactsProvider'] = $suppliedDocumentFacts->provider();
            $structuralMetadata['pdfFactsSourceSha256'] = $suppliedDocumentFacts->source()['sha256'];
        }
        $fastTextOnly = $suppliedDocumentFacts === null
            && $this->fastTextOnlyMode($pdfBytes, $structuralMetadata);
        if (!$fastTextOnly) {
            $suppliedReaderMetadata = $this->options['pdfReaderMetadata'] ?? null;
            $structuralMetadata = $this->withReaderMetadata(
                $structuralMetadata,
                $pdfBytes,
                is_array($suppliedReaderMetadata) ? $suppliedReaderMetadata : null
            );
        }
        $maxTextBytes = max(0, (int) ($this->options['maxTextBytes'] ?? self::DEFAULT_MAX_TEXT_BYTES));
        $extractorOptions = $this->options;
        unset($extractorOptions['pdfDocumentFacts']);
        if ($fastTextOnly
            && $this->pdfMaxPages() === null
            && array_key_exists('pdfFastMaxPages', $this->options)
            && (int) $this->options['pdfFastMaxPages'] > 0
        ) {
            $extractorOptions['pdfMaxPages'] = (int) $this->options['pdfFastMaxPages'];
        }
        if (!$fastTextOnly && $this->needsPositionedPdfText() && !$this->hasExplicitPositionedTextRunLimit()) {
            $resolvedPages = max(0, (int) ($structuralMetadata['pdfEstimatedPages'] ?? 0));
            $selectedPageLimit = $this->pdfMaxPagesFromOptions($extractorOptions);
            $pageBudget = $selectedPageLimit === null
                ? $resolvedPages
                : min($resolvedPages > 0 ? $resolvedPages : $selectedPageLimit, $selectedPageLimit);
            $extractorOptions['pdfMaxPositionedTextRuns'] = $this->automaticPositionedTextRunLimit(
                $maxTextBytes,
                $pageBudget
            );
        }
        $extractor = new PdfTextExtractor($extractorOptions);
        $pageInventory = $suppliedDocumentFacts !== null
            ? $suppliedDocumentFacts->inventory()
            : $this->pdfPageInventory($extractor, $pdfBytes, $structuralMetadata, $extractorOptions);
        $pdfPageRasterGeometry = [];
        $geometryTablesEnabled = !$fastTextOnly && $this->geometryTablesEnabled();
        $proseRepairEnabled = !$fastTextOnly && $this->proseTextRepairEnabled();
        // Complete object-graph-heavy diagnostics before retaining import
        // facts, so its allocator pages do not overlap geometry records.
        $diagnostics = $suppliedDocumentFacts !== null
            ? $this->diagnosticsFromDocumentFacts($suppliedDocumentFacts)
            : ($fastTextOnly ? $this->fastTextOnlyDiagnostics() : $extractor->diagnostics($pdfBytes));
        $this->releaseTransientPdfMemory();
        $importFacts = $suppliedDocumentFacts !== null
            ? $this->collectPdfImportFactsFromDocumentFacts(
                $suppliedDocumentFacts,
                $maxTextBytes,
                !$fastTextOnly,
                !$fastTextOnly && ($geometryTablesEnabled || $proseRepairEnabled || $this->collectPdfImagePlacements() || $this->collectPdfFormXObjectPlacements()),
                $geometryTablesEnabled,
                false
            )
            : $this->collectPdfImportFacts(
                $extractor,
                $pdfBytes,
                $maxTextBytes,
                !$fastTextOnly,
                !$fastTextOnly && ($geometryTablesEnabled || $proseRepairEnabled || $this->collectPdfImagePlacements() || $this->collectPdfFormXObjectPlacements()),
                $geometryTablesEnabled,
                false
            );
        $limitedTextLineItems = $importFacts['limitedTextLineItems'];
        // This inventory is enriched in place below. Remove the container's
        // reference before that mutation so PHP does not retain an unchanged
        // copy of every source-line record at the geometry peak.
        unset($importFacts['limitedTextLineItems']);
        $pdfTextLineCount = $importFacts['textLineCount'];
        $pdfTextBytes = $importFacts['textBytes'];
        $pdfTextInsertedBytes = $this->pdfTextLineItemsByteLength($limitedTextLineItems);
        $pdfTextRunCount = $importFacts['textRunCount'];
        $limitedPositionedRuns = $importFacts['limitedPositionedTextRuns'];
        // The run inventory is enriched in place below. As with source lines,
        // release the container reference first so PHP does not copy every
        // positioned record when the first exact-source field is attached.
        unset($importFacts['limitedPositionedTextRuns']);
        $deferredPositionedTextRunsFile = $importFacts['deferredPositionedTextRunsFile'] ?? null;
        unset($importFacts['deferredPositionedTextRunsFile']);
        $pdfPositionedTextRunCount = $importFacts['positionedTextRunCount'];
        $pdfPositionedTextRunsLimited = $importFacts['positionedTextRunsLimited'];
        $pdfPositionedTextBytesLimited = $importFacts['positionedTextBytesLimited'];
        $filledRectangles = $importFacts['filledRectangles'];
        $pdfFilledRectangleCount = count($filledRectangles);
        unset($importFacts);
        if (!$this->collectPdfImagePlacements() && !$this->collectPdfFormXObjectPlacements()) {
            // Geometry enrichment no longer needs parser caches. Release them
            // before building its transient page/stream proof inventories.
            unset($extractor);
            $this->releaseTransientPdfMemory();
        }
        if (is_resource($deferredPositionedTextRunsFile)) {
            try {
                $limitedPositionedRuns = $this->restoreDeferredPdfRecordArray(
                    $deferredPositionedTextRunsFile,
                    'collected positioned text runs'
                );
            } finally {
                fclose($deferredPositionedTextRunsFile);
            }
        }
        unset($deferredPositionedTextRunsFile);
        $pdfPositionedTextInsertedRunCount = count($limitedPositionedRuns);
        $this->withPdfSourceOccurrenceGeometry(
            $limitedTextLineItems,
            $limitedPositionedRuns
        );
        $this->markSourcePdfOverprintedDuplicateArtifacts($limitedTextLineItems);
        $this->markSourcePdfChartCipherArtifacts($limitedTextLineItems);
        $this->markSourcePdfFacingFolioAndChoiceMatrixRepairs(
            $limitedTextLineItems,
            $limitedPositionedRuns
        );
        $this->markSourcePdfCrossLaneDuplicateDisplayArtifacts(
            $limitedTextLineItems,
            $limitedPositionedRuns
        );
        $this->markSourcePdfInlineStandaloneMarkerOccurrences($limitedTextLineItems);
        $this->markSourcePdfLayoutLabelOccurrences(
            $limitedTextLineItems
        );
        $nestedCalloutIconSourceIndexes = [];
        foreach ($this->sourcePdfStampedNestedCautionCalloutProofs(
            $limitedTextLineItems
        ) as $proof) {
            foreach ($proof['iconAtoms'] as $atom) {
                $nestedCalloutIconSourceIndexes[(int) $atom['sourceGlobalIndex']] = true;
            }
        }
        if ($nestedCalloutIconSourceIndexes !== []) {
            $limitedPositionedRuns = array_values(array_filter(
                $limitedPositionedRuns,
                function (array $run) use ($nestedCalloutIconSourceIndexes): bool {
                    $ranges = $this->pdfPositionedExactSourceRanges($run);
                    if ($ranges === []) {
                        return true;
                    }
                    foreach ($ranges as $range) {
                        if (!isset($nestedCalloutIconSourceIndexes[(int) $range['sourceIndex']])) {
                            return true;
                        }
                    }

                    return false;
                }
            ));
        }
        unset($nestedCalloutIconSourceIndexes);
        $duplicateTerminalPeriodEvidence =
            $this->pdfDuplicateStandaloneTerminalPeriodEvidence($limitedTextLineItems);
        if ($duplicateTerminalPeriodEvidence !== []) {
            $duplicateTerminalPeriodSourceIndexes = [];
            foreach ($limitedTextLineItems as $lineIndex => &$lineItem) {
                $sourceId = is_string($lineItem['id'] ?? null) ? $lineItem['id'] : '';
                if ($sourceId !== '' && isset($duplicateTerminalPeriodEvidence[$sourceId])) {
                    $lineItem['sourcePdfDuplicateTerminalPeriodArtifactEvidence'] =
                        $duplicateTerminalPeriodEvidence[$sourceId];
                    $duplicateTerminalPeriodSourceIndexes[$lineIndex] = true;
                }
            }
            unset($lineItem);
            $limitedPositionedRuns = array_values(array_filter(
                $limitedPositionedRuns,
                function (array $run) use ($duplicateTerminalPeriodSourceIndexes): bool {
                    if ($this->pdfSourceOccurrenceComparableText(
                        (string) ($run['text'] ?? '')
                    ) !== '.') {
                        return true;
                    }
                    $ranges = $this->pdfPositionedExactSourceRanges($run);
                    if ($ranges === []) {
                        return true;
                    }
                    foreach ($ranges as $range) {
                        if (!isset(
                            $duplicateTerminalPeriodSourceIndexes[(int) $range['sourceIndex']]
                        )) {
                            return true;
                        }
                    }

                    return false;
                }
            ));
            unset($duplicateTerminalPeriodSourceIndexes);
        }
        unset($duplicateTerminalPeriodEvidence);
        $decorativeBraceEvidence = $this->pdfDecorativeBracePairEvidence($limitedTextLineItems);
        if ($decorativeBraceEvidence !== []) {
            $decorativeBraceSourceIndexes = [];
            foreach ($limitedTextLineItems as $lineIndex => &$lineItem) {
                $sourceId = is_string($lineItem['id'] ?? null) ? $lineItem['id'] : '';
                if ($sourceId !== '' && isset($decorativeBraceEvidence[$sourceId])) {
                    $lineItem['sourcePdfDecorativeBraceEvidence'] = $decorativeBraceEvidence[$sourceId];
                    $decorativeBraceSourceIndexes[$lineIndex] = true;
                }
            }
            unset($lineItem);
            $limitedPositionedRuns = array_values(array_filter(
                $limitedPositionedRuns,
                function (array $run) use ($decorativeBraceSourceIndexes): bool {
                    $compact = preg_replace('/\s+/u', '', (string) ($run['text'] ?? '')) ?? '';
                    if (!in_array($compact, ['{', '}'], true)) {
                        return true;
                    }
                    $ranges = $this->pdfPositionedExactSourceRanges($run);
                    if ($ranges === []) {
                        return true;
                    }
                    foreach ($ranges as $range) {
                        if (!isset($decorativeBraceSourceIndexes[(int) $range['sourceIndex']])) {
                            return true;
                        }
                    }

                    return false;
                }
            ));
            unset($decorativeBraceSourceIndexes);
        }
        unset($decorativeBraceEvidence);
        // Media-enabled imports retain the extractor for later placement
        // facts; text/layout-only imports released it before enrichment.
        $this->releaseTransientPdfMemory();
        $linkAnnotations = is_array($diagnostics['linkAnnotations'] ?? null) ? $diagnostics['linkAnnotations'] : [];
        $textAnnotations = is_array($diagnostics['textAnnotations'] ?? null) ? $diagnostics['textAnnotations'] : [];
        $fileAttachmentAnnotations = is_array($diagnostics['fileAttachmentAnnotations'] ?? null) ? $diagnostics['fileAttachmentAnnotations'] : [];
        $popupAnnotations = is_array($diagnostics['popupAnnotations'] ?? null) ? $diagnostics['popupAnnotations'] : [];
        $appearanceAnnotations = is_array($diagnostics['appearanceAnnotations'] ?? null) ? $diagnostics['appearanceAnnotations'] : [];
        // Tagged structure is document-global. For a bounded facts range use
        // only StructElem records carrying parser-verified /Pg/MCR provenance;
        // ambiguous unscoped tags continue through page text/geometry instead
        // of being guessed into this slice or duplicated across child pages.
        $partialPageRange = $pageInventory['startPage'] !== 1
            || count($pageInventory['pageNumbers']) !== $pageInventory['totalPages'];
        $taggedStructureBlockFacts = is_array($diagnostics['taggedStructureBlocks'] ?? null)
            ? $diagnostics['taggedStructureBlocks']
            : [];
        $taggedTableFacts = is_array($diagnostics['taggedTables'] ?? null)
            ? $diagnostics['taggedTables']
            : [];
        $taggedStructureItemFacts = is_array($diagnostics['taggedStructureItems'] ?? null)
            ? $diagnostics['taggedStructureItems']
            : [];
        $hasTaggedStructureFacts = $taggedStructureBlockFacts !== []
            || $taggedTableFacts !== []
            || $taggedStructureItemFacts !== [];
        $pdfDiagnosticWarnings = is_array($diagnostics['warnings'] ?? null)
            ? array_values(array_map(
                static fn (mixed $warning): string => (string) $warning,
                $diagnostics['warnings']
            ))
            : [];
        $pdfDiagnosticPageExtractionIssues = is_array(
            $diagnostics['pageExtractionIssues'] ?? null
        ) ? $diagnostics['pageExtractionIssues'] : [];
        $pdfDiagnosticTextVisibility = is_array($diagnostics['textVisibility'] ?? null)
            ? $diagnostics['textVisibility']
            : [
                'policy' => 'visibility-evidence-unavailable',
                'complete' => false,
                'unresolvedReasons' => ['visibility-evidence-unavailable'],
            ];
        $deferredDiagnosticsMetadataFile = $this->deferPdfDispositionMap(
            $diagnostics,
            'diagnostics metadata'
        );
        unset($diagnostics);
        $this->releaseTransientPdfMemory();
        if ($hasTaggedStructureFacts && $partialPageRange) {
            $rangeStartPage = max(1, (int) $pageInventory['startPage']);
            $rangeEndPage = max($rangeStartPage, (int) ($pageInventory['endPage'] ?? $rangeStartPage));
            $taggedStructureBlockFacts = $this->taggedStructuresForPageRange(
                $taggedStructureBlockFacts,
                $rangeStartPage,
                $rangeEndPage
            );
            $taggedTableFacts = $this->taggedStructuresForPageRange(
                $taggedTableFacts,
                $rangeStartPage,
                $rangeEndPage
            );
            $taggedStructureItemFacts = $this->taggedStructuresForPageRange(
                $taggedStructureItemFacts,
                $rangeStartPage,
                $rangeEndPage
            );
        }
        // Materialize the redundant plain-text view only after occurrence
        // geometry has consumed its candidate map. Keeping this zval list out
        // of that peak preserves allocator headroom without changing either
        // line order or the enriched source records used later.
        $limitedLines = array_column($limitedTextLineItems, 'text');
        if ($hasTaggedStructureFacts) {
            $taggedStructureCoverage = $this->taggedStructureBlockCoverage(
                $taggedStructureBlockFacts,
                $limitedLines
            );
            $taggedStructureBlocks = ($taggedStructureCoverage['complete'] ?? false) === true
                ? $this->blocksFromTaggedStructureBlocks(
                    $taggedStructureBlockFacts,
                    $limitedLines
                )
                : [];
            // A partial structure tree is useful evidence only for the exact
            // source occurrences it covers. Keep those regions for a final AST
            // overlay, while allowing uncovered pages/regions to continue through
            // geometry tables, column ordering, prose repair, lists, and code.
            // Treating any non-empty tagged result as document-global authority
            // silently discarded all of those stronger local signals.
            $partialTaggedRegions = $taggedStructureBlocks === []
                ? $this->partialTaggedRegionsFromCoverage($taggedStructureCoverage)
                : [];
            $taggedTableBlocks = $taggedStructureBlocks !== []
                ? $taggedStructureBlocks
                : $this->blocksFromTaggedTables($taggedTableFacts, $limitedLines);
            $taggedBlocks = $taggedTableBlocks !== []
                ? $taggedTableBlocks
                : $this->blocksFromTaggedStructureItems(
                    $taggedStructureItemFacts,
                    $limitedLines
                );
            if ($taggedBlocks !== []) {
                $partialTaggedRegions = [];
            }
        } else {
            $taggedStructureCoverage = [
                'complete' => false,
                'regions' => [],
                'groupCount' => 0,
                'failureReason' => null,
                'failedGroupIndex' => null,
                'candidateCount' => null,
            ];
            $taggedStructureBlocks = [];
            $partialTaggedRegions = [];
            $taggedTableBlocks = [];
            $taggedBlocks = [];
        }
        $limitedLineCount = count($limitedLines);
        $deferredSourceTextLineItemsFile = null;
        if ($taggedBlocks === [] && $proseRepairEnabled && $limitedPositionedRuns !== []) {
            // Source records are not needed while geometry is reconstructed,
            // yet each associative record otherwise overlaps the much larger
            // positioned-run and row graphs. Spill this immutable input for
            // the short geometry phase and restore it before reconciliation.
            $deferredSourceTextLineItemsFile = $this->deferPdfRecordArray(
                $limitedTextLineItems,
                'source text facts'
            );
            unset($limitedTextLineItems, $limitedLines);
            $this->releaseTransientPdfMemory();
        }
        $positionedLineItems = [];
        $positionedLines = [];
        $positionedRunsAreGlyphFragments = false;
        $deferredPositionedLineItemsFile = null;
        if ($taggedBlocks === [] && $proseRepairEnabled && $limitedPositionedRuns !== []) {
            $positionedRunsAreGlyphFragments = $this->positionedRunsArePredominantlyGlyphFragments(
                $limitedPositionedRuns,
                $limitedLineCount
            );
            if (count($limitedPositionedRuns) >= 4096) {
                $deferredPositionedLineItemsFile = $this->deferPositionedProseLineItemsFromTextRuns(
                    $limitedPositionedRuns
                );
            } else {
                $positionedLineItems = $this->positionedProseLineItemsFromTextRuns($limitedPositionedRuns);
                $positionedLines = $this->positionedLineItemTexts($positionedLineItems);
            }
        }
        // Classify perpendicular edge regions before table inference.
        // Otherwise the same margin fragments can masquerade as a narrow
        // second column and turn ordinary prose into a false geometry table.
        $geometryTableBlocksByPage = [];
        $pdfTableContinuations = [];
        $pdfLogicalTableFamilies = [];
        $tablePositionedRuns = $this->positionedTextRunsWithoutEdgeOrientationRegions($limitedPositionedRuns);
        // Orientation classification above is needed before table inference,
        // but retaining its complete reconstructed prose beside glyph runs,
        // table rows, and table ASTs pushes dense PDFs over shared-hosting
        // limits. Rebuild it after table materialization, when the transient
        // rows have been released. This is deterministic and changes neither
        // facts nor output; it only separates the two allocation peaks.
