            'pdfProcessedPageNumbers' => $pageInventory['pageNumbers'],
            'pdfHasMorePages' => $pageInventory['hasMorePages'],
            'pdfNextPage' => $pageInventory['nextPage'],
            'pdfPageLimitApplied' => $effectivePdfMaxPages !== null,
            'pdfMaxPages' => $effectivePdfMaxPages,
            'pdfTextRepair' => $pdfTextRepair,
            'pdfTextRepairSource' => $pdfTextRepairSource,
            'pdfDetectedTables' => $this->countNodesOfType($blocks, 'table'),
            'pdfDetectedCodeBlocks' => $this->countNodesOfType($blocks, 'code_block'),
            'pdfLineOrientedRegions' => $this->lineOrientedRegionCount,
            'pdfInterGlyphSpacingRepairs' => $this->interGlyphSpacingRepairCount,
            'pdfControlCharacterRepairs' => $this->controlCharacterRepairCount,
            'pdfControlCharacterBulletRepairs' => $this->controlCharacterBulletRepairCount,
            'pdfInferredHeadingBoundaries' => $this->inferredHeadingBoundaryCount,
            'pdfFrontMatterRecords' => $this->frontMatterRecordCount,
            'pdfInlineMarkerRecords' => $this->inlineMarkerRecordCount,
            'pdfFormulaRegions' => $this->formulaRegionCount,
            'pdfRotatedRegions' => $this->rotatedRegionCount,
            'pdfRotatedRegionsPreserved' => $this->rotatedRegionPreservedCount,
            'pdfRunningFurnitureRegionsRemoved' => $this->runningFurnitureRegionRemovedCount,
            'pdfSemanticPipeline' => $this->semanticPipelineTrace,
            'pdfGeometryTables' => $geometryTableCount,
            'pdfGeometryTablesEnabled' => $geometryTablesEnabled,
            'pdfGeometryTableLowConfidenceCandidates' => $this->lowConfidenceGeometryTableCandidates,
            'pdfGeometryLayoutHypothesisCount' => $this->geometryLayoutHypothesisCount,
            'pdfGeometryLayoutHypothesisTruncatedCount' => $this->geometryLayoutHypothesisTruncatedCount,
            'pdfGeometryLayoutHypotheses' => $this->geometryLayoutHypotheses,
            'pdfIndependentColumnRegions' => $this->independentColumnHypothesisCount,
            'pdfDocumentLayoutProfile' => $this->documentLayoutProfile,
            'pdfDocumentLayoutProfileDigest' => is_string($this->documentLayoutProfile['profileDigest'] ?? null)
                ? $this->documentLayoutProfile['profileDigest']
                : null,
            'pdfDocumentLayoutProfileComplete' => ($this->documentLayoutProfile['complete'] ?? false) === true,
            'pdfTableReconstruction' => $pdfTableReconstruction,
            'pdfTableContinuations' => $pdfTableContinuations,
            'pdfLogicalTableFamilies' => $pdfLogicalTableFamilies,
            'pdfLogicalTableFamilyCount' => count($pdfLogicalTableFamilies),
            'pdfLogicalTableInstanceCount' => array_sum(array_map(
                static fn (array $family): int => count(is_array($family['instances'] ?? null) ? $family['instances'] : []),
                $pdfLogicalTableFamilies
            )),
            'pdfLogicalTableFamilyPhysicalParts' => array_sum(array_map(
                static fn (array $family): int => max(0, (int) ($family['physicalParts'] ?? 0)),
                $pdfLogicalTableFamilies
            )),
            'pdfLogicalTableCount' => $this->pdfLogicalTableCount($blocks),
            'pdfDiagnostics' => $diagnostics,
            'pdfWarnings' => $pdfWarnings,
            'pdfEncryptionDecrypted' => $diagnostics['encryptionDecrypted'] ?? false,
            'pdfEncryptionHandler' => $diagnostics['encryptionHandler'] ?? null,
            'pdfEncryptionPasswordType' => $diagnostics['encryptionPasswordType'] ?? null,
            'pdfEncryptionPermissions' => $diagnostics['encryptionPermissions'] ?? null,
            'pdfEncryptionAllowsContentExtraction' => $diagnostics['encryptionAllowsContentExtraction'] ?? null,
            'pdfUnsupportedFilters' => $diagnostics['unsupportedFilters'],
            'pdfFailedStreams' => $diagnostics['failedStreams'],
            'pdfMalformedXrefOffsets' => $diagnostics['malformedXrefOffsets'],
            'pdfMalformedXrefStreams' => $diagnostics['malformedXrefStreams'],
            'pdfMalformedObjectStreams' => $diagnostics['malformedObjectStreams'],
            'pdfMissingUnicodeFonts' => $diagnostics['missingUnicodeFonts'],
            'pdfMissingUnicodeFontEncodings' => $diagnostics['missingUnicodeFontEncodings'],
            'pdfSuppressedGlyphRuns' => $diagnostics['suppressedGlyphRuns'],
            'pdfPartiallyMappedGlyphRuns' => $diagnostics['partiallyMappedGlyphRuns'] ?? 0,
            'pdfUnrecoverableActualTextRuns' => $diagnostics['unrecoverableActualTextRuns'] ?? 0,
            'pdfIgnoredXObjectSubtypes' => $diagnostics['ignoredXObjectSubtypes'],
            'pdfIgnoredXObjectCount' => $diagnostics['ignoredXObjectCount'],
            'pdfTaggedRoleMap' => $diagnostics['taggedRoleMap'] ?? [],
            'pdfTaggedStructureRoles' => $diagnostics['taggedStructureRoles'] ?? [],
            'pdfTaggedStructureLanguages' => $diagnostics['taggedStructureLanguages'] ?? [],
            'pdfTaggedClassMap' => $diagnostics['taggedClassMap'] ?? [],
            'pdfTaggedStructureAttributes' => $diagnostics['taggedStructureAttributes'] ?? [],
            'pdfTaggedStructureItems' => $diagnostics['taggedStructureItems'] ?? [],
            'pdfTaggedStructureBlocks' => $diagnostics['taggedStructureBlocks'] ?? [],
            'pdfTaggedTables' => $diagnostics['taggedTables'] ?? [],
            'pdfTaggedRegionArbitration' => $pdfTaggedRegionArbitration,
            'pdfTaggedRegionArbitrationComplete' => $pdfTaggedRegionArbitrationComplete,
            'pdfTaggedRegionArbitratedCount' => $pdfTaggedRegionArbitratedCount,
            'pdfTaggedArbitrationMode' => $pdfTaggedArbitrationMode,
            'pdfTaggedAttributeOwners' => $diagnostics['taggedAttributeOwners'] ?? [],
            'pdfTaggedStructElementCount' => $diagnostics['taggedStructElementCount'] ?? 0,
            'pdfLinkAnnotations' => $linkAnnotations,
            'pdfTextAnnotations' => $textAnnotations,
            'pdfFileAttachmentAnnotations' => $fileAttachmentAnnotations,
            'pdfPopupAnnotations' => $popupAnnotations,
            'pdfAppearanceAnnotations' => $appearanceAnnotations,
            'pdfAppliedLinkAnnotations' => $appliedLinkAnnotations,
            'pdfPageAnchors' => $pdfPageAnchors,
            'pdfImagePlacements' => $pdfImagePlacements,
            'pdfFormXObjectPlacements' => $pdfFormXObjectPlacements,
            'pdfClippedDisplayArtifactMediaAnchorProofs' => $pdfClippedDisplayArtifactMediaAnchorProofs,
            'pdfClippedDisplayArtifactMediaAnchorProofTruncatedCount' =>
                $pdfClippedDisplayArtifactMediaAnchorProofTruncatedCount,
            'pdfPlacedImageCandidates' => count(array_filter(
                $pdfImagePlacements,
                static fn (array $placement): bool =>
                    PdfImagePlacementAnchorer::placementIsEligible($placement)
                    && (is_string($placement['precedingText'] ?? null)
                        || is_string($placement['followingText'] ?? null))
            )),
            'pdfPageExtractionIssues' => $diagnostics['pageExtractionIssues'],
            'pdfPagesWithExtractionIssues' => $diagnostics['pagesWithExtractionIssues'],
        ]);

        return new AstNode('document', ['meta' => $metadata], $blocks);
    }

    /**
     * PHP retains allocator pages after large extraction buffers are unset.
     * Releasing those pages between independent PDF passes keeps bounded
     * imports within the memory limits common on shared hosting.
     */
    private function releaseTransientPdfMemory(): void
    {
        if (function_exists('gc_mem_caches')) {
            gc_mem_caches();
        }
    }

    /**
     * Run conversion-specific preparation while the PDF reader has allocator
     * slack between its two geometry-heavy phases.
     */
    private function runPdfMemoryCheckpointPreparation(): void
    {
        $class = $this->options['__pdfMemoryCheckpointPreloadClass'] ?? null;
        if (is_string($class) && $class !== '') {
            class_exists($class);
        }
    }

    /**
     * Spill an immutable list of PDF fact records without first constructing
     * one serialized copy of the complete list. Dense PDFs can contain tens
     * of thousands of small associative arrays; encoding and writing each
     * record independently keeps the spill operation's transient allocation
     * proportional to the largest record rather than the complete document.
     *
     * @param list<array<string, mixed>> $records
     * @return resource
     */
    private function deferPdfRecordArray(array $records, string $label): mixed
    {
        $stream = tmpfile();
        if ($stream === false) {
            throw new \RuntimeException(sprintf('Could not defer PDF %s.', $label));
        }

        try {
            foreach ($records as $record) {
                $this->writePdfRecordToTempStream($stream, $record, $label);
            }

            if (!fflush($stream) || !rewind($stream)) {
                throw new \RuntimeException(sprintf('Could not rewind deferred PDF %s.', $label));
            }

            return $stream;
        } catch (\Throwable $error) {
            fclose($stream);
            throw $error;
        }
    }

    /**
     * @param array<string,array<string,mixed>|string> $records
     * @return resource
     */
    private function deferPdfDispositionMap(array $records, string $label): mixed
    {
        $stream = tmpfile();
        if ($stream === false) {
            throw new \RuntimeException(sprintf('Could not defer PDF %s.', $label));
        }

        try {
            $orderProofs = [];
            foreach ($records as $record) {
                $orderProof = is_array($record)
                    && is_array($record['orderProof'] ?? null)
                        ? $record['orderProof']
                        : null;
                $scopeId = is_array($orderProof)
                    && is_string($orderProof['scopeId'] ?? null)
                        ? $orderProof['scopeId']
                        : '';
                if ($scopeId === '') {
                    continue;
                }
                if (isset($orderProofs[$scopeId]) && $orderProofs[$scopeId] !== $orderProof) {
                    throw new \RuntimeException(sprintf('PDF %s had conflicting order proofs.', $label));
                }
                $orderProofs[$scopeId] = $orderProof;
            }
            foreach ($orderProofs as $scopeId => $orderProof) {
                $this->writePdfRecordToTempStream($stream, [
                    'sourceId' => "\0pdf-order-proof:" . $scopeId,
                    'record' => $orderProof,
                ], $label);
            }
            foreach ($records as $sourceId => $record) {
                if (is_array($record)
                    && is_array($record['orderProof'] ?? null)
                    && is_string($record['orderProof']['scopeId'] ?? null)
                    && isset($orderProofs[$record['orderProof']['scopeId']])) {
                    $scopeId = $record['orderProof']['scopeId'];
                    unset($record['orderProof']);
                    $record["\0pdfOrderProofKey"] = $scopeId;
                }
                $this->writePdfRecordToTempStream($stream, [
                    'sourceId' => $sourceId,
                    'record' => $record,
                ], $label);
            }
            if (!fflush($stream) || !rewind($stream)) {
                throw new \RuntimeException(sprintf('Could not rewind deferred PDF %s.', $label));
            }

            return $stream;
        } catch (\Throwable $error) {
            fclose($stream);
            throw $error;
        }
    }

    /**
     * @param resource $stream
     * @return array<string,array<string,mixed>|string>
     */
    private function restoreDeferredPdfDispositionMap(mixed $stream, string $label): array
    {
        if (!rewind($stream)) {
            throw new \RuntimeException(sprintf('Could not read deferred PDF %s.', $label));
        }

        $records = [];
        $orderProofs = [];
        while (($entry = $this->readPdfRecordFromTempStream($stream, $label)) !== null) {
            $sourceId = is_string($entry['sourceId'] ?? null) ? $entry['sourceId'] : '';
            $record = $entry['record'] ?? null;
            if (str_starts_with($sourceId, "\0pdf-order-proof:")) {
                $scopeId = substr($sourceId, strlen("\0pdf-order-proof:"));
                if ($scopeId === '' || isset($orderProofs[$scopeId]) || !is_array($record)) {
                    throw new \RuntimeException(sprintf('Deferred PDF %s was invalid.', $label));
                }
                $orderProofs[$scopeId] = $record;
                continue;
            }
            if ($sourceId === ''
                || isset($records[$sourceId])
                || (!is_array($record) && !is_string($record))) {
                throw new \RuntimeException(sprintf('Deferred PDF %s was invalid.', $label));
            }
            if (is_array($record) && array_key_exists("\0pdfOrderProofKey", $record)) {
                $scopeId = is_string($record["\0pdfOrderProofKey"])
                    ? $record["\0pdfOrderProofKey"]
                    : '';
                unset($record["\0pdfOrderProofKey"]);
                if ($scopeId === '' || !isset($orderProofs[$scopeId])) {
                    throw new \RuntimeException(sprintf('Deferred PDF %s was invalid.', $label));
                }
                $record['orderProof'] = $orderProofs[$scopeId];
            }
            $records[$sourceId] = $record;
        }

        return $records;
    }

    /** @param resource $stream @return array<string,mixed> */
    private function restoreDeferredPdfMetadataMap(mixed $stream, string $label): array
    {
        if (!rewind($stream)) {
            throw new \RuntimeException(sprintf('Could not read deferred PDF %s.', $label));
        }

        $records = [];
        while (($entry = $this->readPdfRecordFromTempStream($stream, $label)) !== null) {
            $key = is_string($entry['sourceId'] ?? null) ? $entry['sourceId'] : '';
            if ($key === '' || array_key_exists($key, $records) || !array_key_exists('record', $entry)) {
                throw new \RuntimeException(sprintf('Deferred PDF %s was invalid.', $label));
            }
            $records[$key] = $entry['record'];
        }

        return $records;
    }

    /**
     * @param resource $stream
     * @param array<string, mixed> $record
     */
    private function writePdfRecordToTempStream(mixed $stream, array $record, string $label): void
    {
        $encoded = serialize($record);
        $length = strlen($encoded);
        if ($length > 0xffffffff) {
            throw new \RuntimeException(sprintf('A deferred PDF %s record was too large.', $label));
        }

        $this->writeAllToPdfTempStream($stream, pack('N', $length), $label);
        $this->writeAllToPdfTempStream($stream, $encoded, $label);
    }

    /** @param resource $stream */
    private function writeAllToPdfTempStream(mixed $stream, string $bytes, string $label): void
    {
        $offset = 0;
        $length = strlen($bytes);
        while ($offset < $length) {
            $remaining = $offset === 0 ? $bytes : substr($bytes, $offset);
            $written = fwrite($stream, $remaining);
            if ($written === false || $written === 0) {
                throw new \RuntimeException(sprintf('Could not write deferred PDF %s.', $label));
            }
            $offset += $written;
        }
    }

    /**
     * Restore records one at a time so the returned list is never accompanied
     * by a second, document-sized serialized buffer.
     *
     * @param resource $stream
     * @return list<array<string, mixed>>
     */
    private function restoreDeferredPdfRecordArray(mixed $stream, string $label): array
    {
        if (!rewind($stream)) {
            throw new \RuntimeException(sprintf('Could not read deferred PDF %s.', $label));
        }

        $records = [];
        while (($record = $this->readPdfRecordFromTempStream($stream, $label)) !== null) {
            $records[] = $record;
        }

        return $records;
    }

    /**
     * @param resource $stream
     * @return array<string, mixed>|null
     */
    private function readPdfRecordFromTempStream(mixed $stream, string $label): ?array
    {
        $header = fread($stream, 4);
        if ($header === false) {
            throw new \RuntimeException(sprintf('Could not read deferred PDF %s.', $label));
        }
        if ($header === '') {
            return feof($stream) ? null : $this->readPdfRecordFromTempStream($stream, $label);
        }
        while (strlen($header) < 4) {
            $chunk = fread($stream, 4 - strlen($header));
            if ($chunk === false || $chunk === '') {
                throw new \RuntimeException(sprintf('Deferred PDF %s was truncated.', $label));
            }
            $header .= $chunk;
        }

        $unpacked = unpack('Nlength', $header);
        $length = is_array($unpacked) ? ($unpacked['length'] ?? null) : null;
        if (!is_int($length) || $length < 0) {
            throw new \RuntimeException(sprintf('Deferred PDF %s had an invalid record length.', $label));
        }

        $encoded = '';
        while (strlen($encoded) < $length) {
            $chunk = fread($stream, $length - strlen($encoded));
            if ($chunk === false || $chunk === '') {
                throw new \RuntimeException(sprintf('Deferred PDF %s was truncated.', $label));
            }
            $encoded .= $chunk;
        }

        $record = unserialize($encoded, ['allowed_classes' => false]);
        if (!is_array($record)) {
            throw new \RuntimeException(sprintf('Deferred PDF %s contained an invalid record.', $label));
        }

        return $record;
    }

    /**
     * Consume shared PDF facts as they are decoded. The reader ultimately
     * needs only a bounded prefix of text and positioned runs, while raw text
     * is retained only when prose repair needs cross-run evidence.
     *
     * @return array{
     *     limitedTextLineItems: list<array{page: int, stream: int, text: string}>,
     *     textLineCount: int,
     *     textBytes: int,
     *     rawRuns: list<string>,
     *     textRunCount: int,
     *     limitedPositionedTextRuns: list<array<string, mixed>>,
     *     positionedTextRunCount: int,
     *     positionedTextRunsLimited: bool,
     *     positionedTextBytesLimited: bool,
     *     filledRectangles: list<array<string, mixed>>
     * }
     */
    private function collectPdfImportFacts(
        PdfTextExtractor $extractor,
        string $pdfBytes,
        int $maxTextBytes,
        bool $includeTextRuns,
        bool $includePositionedTextRuns,
        bool $includeFilledRectangles,
        bool $retainRawRuns
    ): array {
        $limitedTextLineItemValues = [];
        $textLineCount = 0;
        $textBytes = 0;
        $textSourceIndex = 0;
        $limitedTextBytes = 0;
        $textLimitReached = $maxTextBytes <= 0;
        $rawRuns = [];
        $textRunCount = 0;
        $limitedPositionedTextRuns = [];
        $deferredPositionedTextRunsFile = null;
        $positionedInsertedRunCount = 0;
        $positionedTextRunCount = 0;
        $positionedBytes = 0;
        $positionedLimitReached = $maxTextBytes <= 0;
        $positionedTextRunsLimited = false;
        $filledRectangles = [];

        foreach ($extractor->streamImportFacts(
            $pdfBytes,
            $includeTextRuns,
            $includePositionedTextRuns,
            $includeFilledRectangles
        ) as $facts) {
            $positionedTextRunsLimited = $positionedTextRunsLimited
                || (($facts['positionedTextRunsLimited'] ?? false) === true);
            foreach ($facts['textLineItems'] as $item) {
                $normalizedItem = $this->normalizePdfTextLineItem($item, $textSourceIndex);
                $textSourceIndex++;
                if ($normalizedItem === null) {
                    continue;
                }

                $textBytes += strlen($normalizedItem['text']) + ($textLineCount === 0 ? 0 : 1);
                $textLineCount++;
                if (!$textLimitReached && !$this->appendLimitedPdfTextLineItemValues(
                    $limitedTextLineItemValues,
                    $limitedTextBytes,
                    $normalizedItem,
                    $maxTextBytes
                )) {
                    $textLimitReached = true;
                }
            }

            foreach ($facts['textRuns'] as $run) {
                $textRunCount++;
                if ($retainRawRuns) {
                    $rawRuns[] = $run;
                }
            }

            foreach ($facts['positionedTextRuns'] as $run) {
                $positionedTextRunCount++;
                $text = isset($run['text']) ? (string) $run['text'] : '';
                if ($text === '') {
                    continue;
                }
                $nextBytes = strlen($text) + ($positionedInsertedRunCount === 0 ? 0 : 1);
                if (!$positionedLimitReached && $positionedBytes + $nextBytes <= $maxTextBytes) {
                    $run = $this->compactPdfPositionedTextRun($run);
                    if (is_resource($deferredPositionedTextRunsFile)) {
                        $this->writePdfRecordToTempStream(
                            $deferredPositionedTextRunsFile,
                            $run,
                            'collected positioned text runs'
                        );
                    } else {
                        $limitedPositionedTextRuns[] = $run;
                        if (count($limitedPositionedTextRuns) >= 2048) {
                            $deferredPositionedTextRunsFile = $this->deferPdfRecordArray(
                                $limitedPositionedTextRuns,
                                'collected positioned text runs'
                            );
                            if (fseek($deferredPositionedTextRunsFile, 0, SEEK_END) !== 0) {
                                throw new \RuntimeException('Could not append collected positioned text runs.');
                            }
                            $limitedPositionedTextRuns = [];
                        }
                    }
                    $positionedBytes += $nextBytes;
                    $positionedInsertedRunCount++;
                } elseif (!$positionedLimitReached) {
                    $positionedLimitReached = true;
                }
            }

            foreach ($facts['filledRectangles'] as $rectangle) {
                $filledRectangles[] = $rectangle;
            }
        }
        unset($facts);

        $limitedTextLineItems = [];
        for ($index = 0, $count = count($limitedTextLineItemValues); $index < $count; $index += 3) {
            $normalizedItem = $this->normalizePdfTextLineItem([
                'page' => (int) $limitedTextLineItemValues[$index],
                'stream' => (int) $limitedTextLineItemValues[$index + 1],
                'text' => (string) $limitedTextLineItemValues[$index + 2],
            ], intdiv($index, 3));
            if ($normalizedItem !== null) {
                $limitedTextLineItems[] = $normalizedItem;
            }
        }
        unset($limitedTextLineItemValues);

        return [
            'limitedTextLineItems' => $limitedTextLineItems,
            'textLineCount' => $textLineCount,
            'textBytes' => $textBytes,
            'rawRuns' => $rawRuns,
            'textRunCount' => $textRunCount,
            'limitedPositionedTextRuns' => $limitedPositionedTextRuns,
            'deferredPositionedTextRunsFile' => $deferredPositionedTextRunsFile,
            'positionedTextRunCount' => $positionedTextRunCount,
            'positionedTextRunsLimited' => $positionedTextRunsLimited,
            'positionedTextBytesLimited' => $positionedLimitReached
                && $positionedTextRunCount > $positionedInsertedRunCount,
            'filledRectangles' => $filledRectangles,
        ];
    }

    private function suppliedDocumentFacts(string $pdfBytes): ?PdfDocumentFacts
    {
        $value = $this->options['pdfDocumentFacts'] ?? null;
        if ($value === null) {
            return null;
        }
        $facts = $value instanceof PdfDocumentFacts
            ? $value
            : (is_array($value) ? PdfDocumentFacts::fromArray($value) : null);
        if ($facts === null || !hash_equals($facts->source()['sha256'], hash('sha256', $pdfBytes))) {
            throw new \RuntimeException('Supplied PDF document facts did not match the source PDF.');
        }

        return $facts;
    }

    /** @return array<string, mixed> */
    private function documentLayoutProfileFromFacts(?PdfDocumentFacts $facts): array
    {
        if ($facts === null) {
            return [];
        }
        $profile = $facts->structure()['documentProfile'] ?? null;
        if (!is_array($profile)) {
            return [];
        }
        $sourceSha256 = $profile['sourceSha256'] ?? null;
        $profileDigest = $profile['profileDigest'] ?? null;
        if (!is_string($sourceSha256)
            || !hash_equals($facts->source()['sha256'], $sourceSha256)
            || !is_string($profileDigest)
            || preg_match('/^[a-f0-9]{64}$/', $profileDigest) !== 1
            || !is_array($profile['pageEvidence'] ?? null)) {
            throw new \RuntimeException('Supplied PDF document layout profile was invalid.');
        }

        $digestPayload = $profile;
        unset($digestPayload['profileDigest']);
        $encoded = json_encode(
            $digestPayload,
            JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_PRESERVE_ZERO_FRACTION
        );
        $expectedDigest = hash('sha256', is_string($encoded) ? $encoded : serialize($digestPayload));
        if (!hash_equals($expectedDigest, $profileDigest)) {
            throw new \RuntimeException('Supplied PDF document layout profile digest did not verify.');
        }

        return $profile;
    }

    /**
     * Rehydrate the exact extraction-shaped inputs consumed by the existing
     * document-level semantic pipeline. Browser observations remain attached
     * to PdfDocumentFacts for later processors; native facts preserve current
     * output while avoiding a second page-parser pass at finalization.
     *
     * @return array{
     *     limitedTextLineItems: list<array{page: int, stream: int, text: string}>,
     *     textLineCount: int,
     *     textBytes: int,
     *     rawRuns: list<string>,
     *     textRunCount: int,
     *     limitedPositionedTextRuns: list<array<string, mixed>>,
     *     positionedTextRunCount: int,
     *     positionedTextRunsLimited: bool,
     *     positionedTextBytesLimited: bool,
     *     filledRectangles: list<array<string, mixed>>
     * }
     */
    private function collectPdfImportFactsFromDocumentFacts(
        PdfDocumentFacts $documentFacts,
        int $maxTextBytes,
        bool $includeTextRuns,
        bool $includePositionedTextRuns,
        bool $includeFilledRectangles,
        bool $retainRawRuns
    ): array {
        $limitedTextLineItems = [];
        $textLineCount = 0;
        $textBytes = 0;
        $textSourceIndex = 0;
        $limitedTextBytes = 0;
        $textLimitReached = $maxTextBytes <= 0;
        $rawRuns = [];
        $textRunCount = 0;
        $limitedPositionedTextRuns = [];
        $positionedTextRunCount = 0;
        $positionedBytes = 0;
        $positionedLimitReached = $maxTextBytes <= 0;
        $positionedTextRunsLimited = false;
        $filledRectangles = [];

        foreach ($documentFacts->pages() as $page) {
            $text = $page->text();
            foreach ($text['lines'] ?? [] as $item) {
                if (!is_array($item)) {
                    continue;
                }
                $normalizedItem = $this->normalizePdfTextLineItem($item, $textSourceIndex);
                $textSourceIndex++;
                if ($normalizedItem === null) {
                    continue;
                }
                $textBytes += strlen($normalizedItem['text']) + ($textLineCount === 0 ? 0 : 1);
                $textLineCount++;
                if (!$textLimitReached && !$this->appendLimitedPdfTextLineItem(
                    $limitedTextLineItems,
                    $limitedTextBytes,
                    $normalizedItem,
                    $maxTextBytes
                )) {
                    $textLimitReached = true;
                }
            }
            if ($includeTextRuns) {
                foreach ($text['runs'] ?? [] as $run) {
                    if (!is_array($run) || !is_string($run['text'] ?? null) || $run['text'] === '') {
                        continue;
                    }
                    $textRunCount++;
                    if ($retainRawRuns) {
                        $rawRuns[] = $run['text'];
                    }
                }
            }
            if ($includePositionedTextRuns) {
                foreach ($text['spans'] ?? [] as $run) {
                    if (!is_array($run) || !is_string($run['text'] ?? null) || $run['text'] === '') {
                        continue;
                    }
                    $positionedTextRunCount++;
                    if (!$positionedLimitReached && !$this->appendLimitedPositionedTextRun(
                        $limitedPositionedTextRuns,
                        $positionedBytes,
                        $run,
                        $maxTextBytes
                    )) {
                        $positionedLimitReached = true;
                    }
                }
                $positionedTextRunsLimited = $positionedTextRunsLimited
                    || (($text['positionedRunsLimited'] ?? false) === true);
            }
            if ($includeFilledRectangles) {
                foreach ($page->graphics()['filledRectangles'] ?? [] as $rectangle) {
                    if (is_array($rectangle)) {
                        $filledRectangles[] = $rectangle;
                    }
                }
            }
        }

        return [
            'limitedTextLineItems' => $limitedTextLineItems,
            'textLineCount' => $textLineCount,
            'textBytes' => $textBytes,
            'rawRuns' => $rawRuns,
            'textRunCount' => $textRunCount,
            'limitedPositionedTextRuns' => $limitedPositionedTextRuns,
            'positionedTextRunCount' => $positionedTextRunCount,
            'positionedTextRunsLimited' => $positionedTextRunsLimited,
            'positionedTextBytesLimited' => $positionedLimitReached
                && $positionedTextRunCount > count($limitedPositionedTextRuns),
            'filledRectangles' => $filledRectangles,
        ];
    }

    /** @return array<string, mixed> */
    private function diagnosticsFromDocumentFacts(PdfDocumentFacts $documentFacts): array
    {
        $data = $documentFacts->toArray();
        $defaults = $this->fastTextOnlyDiagnostics();
        $defaults['warnings'] = [];
        $diagnostics = array_replace(
            $defaults,
            is_array($data['diagnostics'] ?? null) ? $data['diagnostics'] : [],
            is_array($data['structure'] ?? null) ? $data['structure'] : []
        );
        if (is_array($diagnostics['textVisibility'] ?? null)) {
            $diagnostics['textVisibility'] = $this->pdfTextVisibilityForDocumentFactsRange(
                $diagnostics['textVisibility'],
                array_map(
                    static fn ($page): int => $page->pageNumber(),
                    $documentFacts->pages()
                )
            );
        }
        $annotationKeys = [
            'links' => 'linkAnnotations',
            'text' => 'textAnnotations',
            'fileAttachments' => 'fileAttachmentAnnotations',
            'popups' => 'popupAnnotations',
            'appearances' => 'appearanceAnnotations',
        ];
        $issues = [];
        foreach ($documentFacts->pages() as $page) {
            foreach ($annotationKeys as $pageKey => $diagnosticKey) {
                foreach ($page->annotations()[$pageKey] ?? [] as $annotation) {
                    if (is_array($annotation)) {
                        $diagnostics[$diagnosticKey][] = $annotation;
                    }
                }
            }
            array_push($issues, ...$page->issues());
        }
        $diagnostics['pageExtractionIssues'] = $issues;
        $diagnostics['pagesWithExtractionIssues'] = count(array_unique(array_map(
            static fn (array $issue): int => max(1, (int) ($issue['page'] ?? 1)),
            $issues
        )));

        return $diagnostics;
    }

    /**
     * Document diagnostics are computed once for an extracted range, while a
     * durable importer may later split those facts into smaller page ranges.
     * Localize the page-indexed visibility evidence before it participates in
     * semantic completeness so one page cannot inherit another page's paint
     * risk. Missing or unscoped evidence remains incomplete.
     *
     * @param array<string,mixed> $visibility
     * @param list<int> $pageNumbers
     * @return array<string,mixed>
     */
    private function pdfTextVisibilityForDocumentFactsRange(
        array $visibility,
        array $pageNumbers
    ): array {
        $digest = static function (array $value): string {
            $encoded = json_encode(
                $value,
                JSON_UNESCAPED_SLASHES
                    | JSON_UNESCAPED_UNICODE
                    | JSON_PRESERVE_ZERO_FRACTION
            );

            return hash('sha256', is_string($encoded) ? $encoded : serialize($value));
        };
        $invalid = static function (
            array $value,
            string $reason
        ) use ($digest): array {
            // An invalid parent receipt must not reach the later-paint
            // reconciler in a shape which it could independently bless.
            // Replace its derived counters with one explicit unresolved
            // evidence unit and an internally consistent empty risk set.
            $value['complete'] = false;
            $value['rangeLocalizationComplete'] = false;
            $value['rangeLocalizationFailureReason'] = $reason;
            $value['pages'] = [];
            foreach ([
                'visibleRuns',
                'visibleOutputRuns',
                'suppressedNonPaintingRuns',
                'suppressedRenderingModeRuns',
                'suppressedZeroAlphaRuns',
                'suppressedOptionalContentRuns',
                'suppressedOutsidePageRuns',
                'suppressedNonPaintingActualTextRuns',
                'suppressedAccessibilityReplacementRuns',
                'unresolvedClippingRuns',
                'unresolvedOcclusionRiskRuns',
                'laterPaintRiskCount',
                'laterPaintRiskRecordedCount',
                'laterPaintRiskUnboundCount',
                'laterPaintRiskTruncatedCount',
            ] as $key) {
                $value[$key] = 0;
            }
            $value['unresolvedRuns'] = 1;
            $value['unresolvedReasons'] = ['range-visibility-evidence-invalid'];
            $value['unresolvedReasonCounts'] = ['range-visibility-evidence-invalid' => 1];
            $value['laterPaintRisks'] = [];
            $value['laterPaintRisksDigest'] = $digest([]);

            return $value;
        };
        $countKeys = [
            'visibleRuns',
            'visibleOutputRuns',
            'suppressedNonPaintingRuns',
            'suppressedRenderingModeRuns',
            'suppressedZeroAlphaRuns',
            'suppressedOptionalContentRuns',
            'suppressedOutsidePageRuns',
            'suppressedNonPaintingActualTextRuns',
            'suppressedAccessibilityReplacementRuns',
            'unresolvedRuns',
            'unresolvedClippingRuns',
            'unresolvedOcclusionRiskRuns',
            'laterPaintRiskCount',
            'laterPaintRiskRecordedCount',
            'laterPaintRiskUnboundCount',
            'laterPaintRiskTruncatedCount',
        ];
        $normalizedReasonCounts = static function (
            mixed $counts,
            mixed $reasons
        ): ?array {
            if (!is_array($counts) || !is_array($reasons) || !array_is_list($reasons)) {
                return null;
            }
            $normalized = [];
            foreach ($counts as $reason => $count) {
                if (!is_string($reason)
                    || $reason === ''
                    || !is_int($count)
                    || $count < 1) {
                    return null;
                }
                $normalized[$reason] = $count;
            }
            ksort($normalized, SORT_STRING);

            return $reasons === array_keys($normalized) ? $normalized : null;
        };
        $stateIsInternallyComplete = static function (
            array $state,
            array $reasonCounts
        ): bool {
            $reasonCountTotal = array_sum($reasonCounts);

            return is_bool($state['complete'] ?? null)
                && $state['visibleRuns'] === $state['visibleOutputRuns']
                && $state['suppressedNonPaintingRuns']
                    === $state['suppressedRenderingModeRuns']
                        + $state['suppressedZeroAlphaRuns']
                        + $state['suppressedOptionalContentRuns']
                && $state['suppressedNonPaintingActualTextRuns']
                    === $state['suppressedAccessibilityReplacementRuns']
                && $state['unresolvedClippingRuns']
                    === ($reasonCounts['unresolved-clipping-path'] ?? 0)
                && $state['unresolvedOcclusionRiskRuns']
                    === ($reasonCounts['later-paint-occlusion'] ?? 0)
                && $state['laterPaintRiskCount'] === $state['unresolvedOcclusionRiskRuns']
                && $state['laterPaintRiskCount']
                    === $state['laterPaintRiskRecordedCount']
                        + $state['laterPaintRiskUnboundCount']
                        + $state['laterPaintRiskTruncatedCount']
                // Occlusion risks are unresolved visibility evidence but are
                // deliberately inventoried outside unresolvedRuns so the
                // later-paint reconciler can resolve them independently.
                && $reasonCountTotal
                    === $state['unresolvedRuns']
                        + $state['unresolvedOcclusionRiskRuns']
                && (($state['unresolvedRuns'] === 0
                        && $state['unresolvedOcclusionRiskRuns'] === 0)
                    ? $reasonCounts === []
                    : $reasonCounts !== [])
                && $state['complete']
                    === ($state['unresolvedRuns'] === 0
                        && $state['unresolvedOcclusionRiskRuns'] === 0);
        };

        if (($visibility['policy'] ?? null) !== 'visible-painted-text-v1') {
            return $invalid($visibility, 'range-visibility-policy-invalid');
        }
        if (!is_array($visibility['pages'] ?? null)
            || !array_is_list($visibility['pages'])
            || !is_array($visibility['laterPaintRisks'] ?? null)
            || !array_is_list($visibility['laterPaintRisks'])
            || $pageNumbers === []) {
            return $invalid($visibility, 'range-visibility-inventory-invalid');
        }

        $selectedPages = [];
        foreach ($pageNumbers as $page) {
            if (!is_int($page) || $page < 1 || isset($selectedPages[$page])) {
                return $invalid($visibility, 'range-page-selection-invalid');
            }
            $selectedPages[$page] = true;
        }
        foreach ($countKeys as $key) {
            if (!is_int($visibility[$key] ?? null) || $visibility[$key] < 0) {
                return $invalid($visibility, 'range-visibility-aggregate-counter-invalid');
            }
        }
        $aggregateReasonCounts = $normalizedReasonCounts(
            $visibility['unresolvedReasonCounts'] ?? null,
            $visibility['unresolvedReasons'] ?? null
        );
        if ($aggregateReasonCounts === null
            || !$stateIsInternallyComplete($visibility, $aggregateReasonCounts)) {
            return $invalid($visibility, 'range-visibility-aggregate-state-invalid');
        }

        $riskInventoryDigest = $visibility['laterPaintRisksDigest'] ?? null;
        if (!is_string($riskInventoryDigest)
            || preg_match('/^[a-f0-9]{64}$/D', $riskInventoryDigest) !== 1
            || !hash_equals($riskInventoryDigest, $digest($visibility['laterPaintRisks']))
            || count($visibility['laterPaintRisks'])
                !== $visibility['laterPaintRiskRecordedCount']) {
            return $invalid($visibility, 'range-later-paint-risk-inventory-invalid');
        }

        $pageSummariesByPage = [];
        $aggregateCountsFromPages = array_fill_keys($countKeys, 0);
        $aggregateReasonCountsFromPages = [];
        foreach ($visibility['pages'] as $summary) {
            $page = is_array($summary) && is_int($summary['page'] ?? null)
                ? $summary['page']
                : null;
            if ($page === null || $page < 1 || isset($pageSummariesByPage[$page])) {
                return $invalid($visibility, 'range-page-visibility-summary-invalid');
            }
            foreach ($countKeys as $key) {
                if (!is_int($summary[$key] ?? null) || $summary[$key] < 0) {
                    return $invalid($visibility, 'range-page-visibility-counter-invalid');
                }
                $aggregateCountsFromPages[$key] += $summary[$key];
            }
            $summaryReasonCounts = $normalizedReasonCounts(
                $summary['unresolvedReasonCounts'] ?? null,
                $summary['unresolvedReasons'] ?? null
            );
            if ($summaryReasonCounts === null
                || !$stateIsInternallyComplete($summary, $summaryReasonCounts)
                || !is_string($summary['laterPaintRisksDigest'] ?? null)
                || preg_match('/^[a-f0-9]{64}$/D', $summary['laterPaintRisksDigest']) !== 1) {
                return $invalid($visibility, 'range-page-visibility-state-invalid');
            }
            foreach ($summaryReasonCounts as $reason => $count) {
                $aggregateReasonCountsFromPages[$reason] =
                    ($aggregateReasonCountsFromPages[$reason] ?? 0) + $count;
            }
            $pageSummariesByPage[$page] = $summary;
        }
        ksort($aggregateReasonCountsFromPages, SORT_STRING);
        $aggregateCounterMismatch = false;
        foreach ($countKeys as $key) {
            if ($aggregateCountsFromPages[$key] !== $visibility[$key]) {
                $aggregateCounterMismatch = true;
                break;
            }
        }
        if ($aggregateCounterMismatch
            || $aggregateReasonCountsFromPages !== $aggregateReasonCounts) {
            return $invalid($visibility, 'range-visibility-page-aggregate-mismatch');
        }

        $risksByPage = [];
        $riskIds = [];
        $riskDigests = [];
        foreach ($visibility['laterPaintRisks'] as $risk) {
            $riskPage = is_array($risk) && is_int($risk['page'] ?? null)
                ? $risk['page']
                : null;
            $riskId = is_array($risk) && is_string($risk['id'] ?? null)
                ? $risk['id']
                : '';
            $riskDigest = is_array($risk) && is_string($risk['riskDigest'] ?? null)
                ? $risk['riskDigest']
                : '';
            if ($riskPage === null
                || !isset($pageSummariesByPage[$riskPage])
                || $riskId === ''
                || isset($riskIds[$riskId])
                || preg_match('/^[a-f0-9]{64}$/D', $riskDigest) !== 1
                || isset($riskDigests[$riskDigest])
                || !is_string($risk['sourceSha256'] ?? null)
                || preg_match('/^[a-f0-9]{64}$/D', $risk['sourceSha256']) !== 1) {
                return $invalid($visibility, 'range-later-paint-risk-record-invalid');
            }
            $riskPayload = $risk;
            unset($riskPayload['id'], $riskPayload['riskDigest']);
            if (!hash_equals($riskDigest, $digest($riskPayload))
                || $riskId !== 'pdf-later-paint-risk-' . substr($riskDigest, 0, 32)
                || ($this->sourceSha256 !== ''
                    && !hash_equals($this->sourceSha256, $risk['sourceSha256']))) {
                return $invalid($visibility, 'range-later-paint-risk-record-invalid');
            }
            $riskIds[$riskId] = true;
            $riskDigests[$riskDigest] = true;
            $risksByPage[$riskPage][] = $risk;
        }
        foreach ($pageSummariesByPage as $page => $summary) {
            $pageRisks = $risksByPage[$page] ?? [];
            if (count($pageRisks) !== $summary['laterPaintRiskRecordedCount']
                || !hash_equals($summary['laterPaintRisksDigest'], $digest($pageRisks))) {
                return $invalid($visibility, 'range-page-later-paint-risk-inventory-invalid');
            }
        }

        $pageSummaries = [];
        foreach (array_keys($selectedPages) as $page) {
            if (!isset($pageSummariesByPage[$page])) {
                return $invalid($visibility, 'range-page-visibility-summary-missing');
            }
            $pageSummaries[] = $pageSummariesByPage[$page];
        }
        if (count($selectedPages) === count($pageSummariesByPage)
            && array_diff_key($selectedPages, $pageSummariesByPage) === []) {
            return $visibility;
        }

        $rangeCounts = array_fill_keys($countKeys, 0);
        $rangeReasonCounts = [];
        $rangeRisks = [];
        foreach ($pageSummaries as $summary) {
            foreach ($countKeys as $key) {
                $rangeCounts[$key] += $summary[$key];
            }
            foreach ($summary['unresolvedReasonCounts'] as $reason => $count) {
                $rangeReasonCounts[$reason] = ($rangeReasonCounts[$reason] ?? 0) + $count;
            }
            array_push($rangeRisks, ...($risksByPage[$summary['page']] ?? []));
        }
        ksort($rangeReasonCounts, SORT_STRING);
        foreach ($rangeCounts as $key => $count) {
            $visibility[$key] = $count;
        }
        $visibility['pages'] = $pageSummaries;
        $visibility['complete'] = $rangeCounts['unresolvedRuns'] === 0
            && $rangeCounts['unresolvedOcclusionRiskRuns'] === 0;
        $visibility['unresolvedReasons'] = array_keys($rangeReasonCounts);
        $visibility['unresolvedReasonCounts'] = $rangeReasonCounts;
        $visibility['laterPaintRisks'] = $rangeRisks;
        $visibility['laterPaintRisksDigest'] = $digest($rangeRisks);

        return $visibility;
    }

    /** @return list<array<string, mixed>> */
    private function graphicFacts(PdfDocumentFacts $documentFacts, string $key): array
    {
        $facts = [];
        foreach ($documentFacts->pages() as $page) {
            foreach ($page->graphics()[$key] ?? [] as $fact) {
                if (!is_array($fact)) {
                    continue;
                }
                $nativeId = $fact['provenance']['nativeId'] ?? null;
                if (is_string($nativeId) && $nativeId !== '') {
                    $fact['factId'] = $fact['id'] ?? null;
                    $fact['id'] = $nativeId;
                }
                $facts[] = $fact;
            }
        }

        return $facts;
    }

    private function geometryTablesEnabled(): bool
    {
        foreach (['pdfGeometryTables', 'geometryTables', 'extractGeometryTables'] as $key) {
            if (array_key_exists($key, $this->options)) {
                return (bool) $this->options[$key];
            }
        }

        return true;
    }

    private function proseTextRepairEnabled(): bool
    {
        foreach (['pdfRepairProseText', 'repairProseText'] as $key) {
            if (array_key_exists($key, $this->options)) {
                return (bool) $this->options[$key];
            }
        }

        return false;
    }

    private function collectPdfImagePlacements(): bool
    {
        foreach (['pdfCollectImagePlacements', 'collectPdfImagePlacements'] as $key) {
            if (array_key_exists($key, $this->options)) {
                return (bool) $this->options[$key];
            }
        }

        return false;
    }

    private function collectPdfFormXObjectPlacements(): bool
    {
        foreach (['pdfCollectFormXObjectPlacements', 'collectPdfFormXObjectPlacements'] as $key) {
            if (array_key_exists($key, $this->options)) {
                return (bool) $this->options[$key];
            }
        }

        return false;
    }

    /**
     * @param list<array<string, mixed>> $placements
     * @param list<array<string, mixed>> $layouts
     * @param list<array<string, mixed>> $sourceLineItems
     * @return list<array<string, mixed>>
     */
    private function imagePlacementsWithTextAnchors(
        array $placements,
        array $layouts,
        array $sourceLineItems = []
    ): array {
        if ($placements === []) {
            return [];
        }

        return PdfImagePlacementAnchorer::anchor(
            $placements,
            $layouts,
            $sourceLineItems,
            $this->length(...),
            $this->pdfPositionedExactSourceRanges(...),
            $this->pdfSourceOccurrenceComparableText(...),
            $this->pdfTextWithoutSemanticPrefixes(...),
            $this->sourcePdfSourceItemHasExactGeometry(...)
        );
    }

    /**
     * The later-paint reconciler reads dispositions only for each bounded
     * artifact risk and the complete display counterpart named by that
     * artifact's evidence. Preserve exactly those records before the source
     * ledger consumes the full bound-disposition graph. Malformed or missing
     * evidence deliberately yields an incomplete subset and therefore keeps
     * the reconciler fail-closed.
     *
     * @param array<string,mixed> $visibility
     * @param list<array<string,mixed>|string> $sourceLineItems
     * @param array<string,array<string,mixed>|string> $boundDispositions
     * @return array<string,array<string,mixed>|string>
     */
    private function pdfVisibilityReconciliationDispositionSubset(
        array $visibility,
        array $sourceLineItems,
        array $boundDispositions
    ): array {
        if (($visibility['complete'] ?? false) === true) {
            return [];
        }
        $risks = is_array($visibility['laterPaintRisks'] ?? null)
            ? $visibility['laterPaintRisks']
            : [];
        $subset = [];
        foreach ($risks as $risk) {
            $sourceIndex = is_array($risk) && is_int($risk['sourceOccurrenceIndex'] ?? null)
                ? $risk['sourceOccurrenceIndex']
                : -1;
            $sourceItem = $sourceIndex >= 0 ? ($sourceLineItems[$sourceIndex] ?? null) : null;
            $sourceId = is_array($sourceItem) && is_string($sourceItem['id'] ?? null)
                ? $sourceItem['id']
                : '';
            if ($sourceId === '' || !array_key_exists($sourceId, $boundDispositions)) {
                continue;
            }
            $artifactDisposition = $boundDispositions[$sourceId];
            $subset[$sourceId] = $artifactDisposition;
            $counterpartId = is_array($artifactDisposition)
                && is_array($artifactDisposition['evidence'] ?? null)
                && is_array(
                    $artifactDisposition['evidence']['completeDisplayCounterpart'] ?? null
                )
                && is_string(
                    $artifactDisposition['evidence']['completeDisplayCounterpart'][
                        'sourceOccurrenceId'
                    ] ?? null
                )
                    ? $artifactDisposition['evidence']['completeDisplayCounterpart'][
                        'sourceOccurrenceId'
                    ]
                    : '';
            if ($counterpartId !== ''
                && array_key_exists($counterpartId, $boundDispositions)) {
                $subset[$counterpartId] = $boundDispositions[$counterpartId];
            }
        }

        return $subset;
    }

    /**
     * @param list<array<string,mixed>|string> $sourceLineItems
     * @param list<AstNode> $blocks
     * @param array<string,array<string,mixed>|string> $boundDispositions
     * @param list<array<string,mixed>> $laterPaintRisks
     * @param list<array<string,mixed>> $imagePlacements
     * @return array{proofs:list<array<string,mixed>>,truncatedCount:int}
     */
    private function pdfClippedDisplayArtifactMediaAnchorProofs(
        array $sourceLineItems,
        array $blocks,
        array $boundDispositions,
        array $laterPaintRisks,
        array $imagePlacements
    ): array {
        $empty = ['proofs' => [], 'truncatedCount' => 0];
        if ($sourceLineItems === []
            || $blocks === []
            || $boundDispositions === []
            || $laterPaintRisks === []
            || $imagePlacements === []) {
            return $empty;
        }

        $hasCandidateDisposition = false;
        foreach ($boundDispositions as $artifactDisposition) {
            $evidence = is_array($artifactDisposition)
                && is_array($artifactDisposition['evidence'] ?? null)
                    ? $artifactDisposition['evidence']
                    : null;
            $counterpart = is_array($evidence)
                && is_array($evidence['completeDisplayCounterpart'] ?? null)
                    ? $evidence['completeDisplayCounterpart']
                    : null;
            if (is_array($artifactDisposition)
                && ($artifactDisposition['disposition'] ?? null) === 'artifact'
                && is_array($evidence)
                && ($evidence['method'] ?? null) === 'whole-source-clipped-display-artifact'
                && is_array($counterpart)
                && is_string($counterpart['sourceOccurrenceId'] ?? null)
                && $counterpart['sourceOccurrenceId'] !== '') {
                $hasCandidateDisposition = true;
                break;
            }
        }
        if (!$hasCandidateDisposition) {
            return $empty;
        }

        return PdfClippedDisplayMediaAnchorProofBuilder::build(
            $this->sourceSha256,
            self::MAX_PDF_CLIPPED_ARTIFACT_MEDIA_ANCHOR_PROOFS,
            $sourceLineItems,
            $blocks,
            $boundDispositions,
            $laterPaintRisks,
            $imagePlacements,
            $this->pdfSourceOccurrenceComparableText(...)
        );
    }

    private function needsPositionedPdfText(): bool
    {
        return $this->geometryTablesEnabled()
            || $this->proseTextRepairEnabled()
            || $this->collectPdfImagePlacements()
            || $this->collectPdfFormXObjectPlacements();
    }

    private function hasExplicitPositionedTextRunLimit(): bool
    {
        foreach (['pdfMaxPositionedTextRuns', 'maxPositionedTextRuns'] as $key) {
            if (array_key_exists($key, $this->options) && $this->options[$key] !== null && $this->options[$key] !== '') {
                return true;
            }
        }

        return false;
    }

    private function automaticPositionedTextRunLimit(int $maxTextBytes, int $pageCount): int
    {
        // Bound geometry by the resolved page range, not by compressed source
        // bytes. A fixed whole-document cap clipped ordinary long PDFs, while
        // 1,000 runs per selected page comfortably covers glyph-fragmented
        // prose without making a pathological page unbounded.
        $pageBound = max(20_000, min(250_000, max(1, $pageCount) * 1_000));
        if ($maxTextBytes === PHP_INT_MAX) {
            return $pageBound;
        }

        return min($pageBound, max(5_000, intdiv(max(1, $maxTextBytes), 4)));
    }

    private function pdfMaxPages(): ?int
    {
        return $this->pdfMaxPagesFromOptions($this->options);
    }

    /** @param array<string, mixed> $options */
    private function pdfMaxPagesFromOptions(array $options): ?int
    {
        foreach (['pdfMaxPages', 'maxPages', 'max_pages'] as $key) {
            if (!array_key_exists($key, $options) || $options[$key] === null || $options[$key] === '') {
                continue;
            }
            $value = (int) $options[$key];

            return $value > 0 ? $value : null;
        }

        return null;
    }

    /** @param array<string, mixed> $options */
    private function pdfStartPageFromOptions(array $options): int
    {
        foreach (['pdfStartPage', 'startPage', 'start_page'] as $key) {
            if (!array_key_exists($key, $options) || $options[$key] === null || $options[$key] === '') {
                continue;
            }

            return max(1, (int) $options[$key]);
        }

        return 1;
    }

    /**
     * Retain only the compact normative geometry needed to ask an external
     * renderer for a whole-page raster. Inferred letter-size geometry is not
     * authoritative enough to bind returned pixels to a physical PDF page.
     *
     * @return list<array<string,mixed>>
     */
    private function pdfPageRasterGeometry(
        ?PdfDocumentFacts $documentFacts,
        ?PdfTextExtractor $extractor,
        string $pdfBytes
    ): array {
        if ($documentFacts !== null) {
            $geometry = [];
            foreach ($documentFacts->pages() as $page) {
                $row = $page->geometry();
                $row['page_number'] = $page->pageNumber();
                if ($page->pageObject() !== null) {
                    $row['object_id'] = $page->pageObject();
                }
                $geometry[] = $row;
            }

            return $geometry;
        }

        if ($extractor === null) {
            return [];
        }
        try {
            return $extractor->extractPageGeometry($pdfBytes);
        } catch (\Throwable) {
            return [];
        }
    }

    /**
     * A request is an immutable capability for exactly one source page. The
     * consumer recomputes the same digest before accepting any raster bytes;
     * page number alone is never sufficient authority.
     *
     * @param list<int> $pagesNeedingImageRepresentation
     * @param list<array<string,mixed>> $geometryRows
     * @return list<array<string,mixed>>
     */
    private function pdfPageRasterRequests(
        array $pagesNeedingImageRepresentation,
        array $geometryRows
    ): array {
        if ($pagesNeedingImageRepresentation === []) {
            return [];
        }
        $needed = array_fill_keys($pagesNeedingImageRepresentation, true);
        $requestsByPage = [];
        foreach ($geometryRows as $geometry) {
            if (!is_array($geometry)) {
                continue;
            }
            $page = $geometry['page_number'] ?? null;
            $pageObject = $geometry['object_id'] ?? null;
            $box = $geometry['bbox'] ?? null;
            $boxSource = $geometry['bboxSource'] ?? null;
            $rotation = $geometry['rotation'] ?? null;
            if (!is_int($page)
                || !isset($needed[$page])
                || isset($requestsByPage[$page])
                || !is_int($pageObject)
                || $pageObject < 1
                || !is_array($box)
                || !array_is_list($box)
                || count($box) !== 4
                || !in_array($boxSource, ['CropBox', 'MediaBox'], true)
                || ($geometry['bboxInferred'] ?? true) !== false
                || !is_int($rotation)
                || !in_array($rotation, [0, 90, 180, 270], true)) {
                continue;
            }
            $normalizedBox = [];
            foreach ($box as $coordinate) {
                if (!is_numeric($coordinate) || !is_finite((float) $coordinate)) {
                    continue 2;
                }
                $normalizedBox[] = (float) $coordinate;
            }
            [$x1, $y1, $x2, $y2] = $normalizedBox;
            $pageWidth = $x2 - $x1;
            $pageHeight = $y2 - $y1;
            if ($pageWidth <= 0.000001 || $pageHeight <= 0.000001) {
                continue;
            }
            $displayWidth = in_array($rotation, [90, 270], true) ? $pageHeight : $pageWidth;
            $displayHeight = in_array($rotation, [90, 270], true) ? $pageWidth : $pageHeight;
            $scale = min(
                self::PDF_PAGE_RASTER_TARGET_SCALE,
                self::MAX_PDF_PAGE_RASTER_DIMENSION / $displayWidth,
                self::MAX_PDF_PAGE_RASTER_DIMENSION / $displayHeight,
                sqrt(self::MAX_PDF_PAGE_RASTER_PIXELS / ($displayWidth * $displayHeight))
            );
            if (!is_finite($scale) || $scale <= 0.0) {
                continue;
            }
            $width = max(1, (int) ceil($displayWidth * $scale));
            $height = max(1, (int) ceil($displayHeight * $scale));
            if ($width > self::MAX_PDF_PAGE_RASTER_DIMENSION
                || $height > self::MAX_PDF_PAGE_RASTER_DIMENSION
                || $width * $height > self::MAX_PDF_PAGE_RASTER_PIXELS) {
                continue;
            }

            $request = [
                'version' => 1,
                'method' => 'pdfjs-whole-page-raster',
                'sourceSha256' => $this->sourceSha256,
                'page' => $page,
                'pageObject' => $pageObject,
                'pageBox' => $normalizedBox,
                'pageBoxSource' => $boxSource,
                'pageRotation' => $rotation,
                'width' => $width,
                'height' => $height,
                'mimeType' => 'image/png',
            ];
            $requestDigest = $this->pdfPageRasterRequestDigest($request);
            $request['id'] = 'pdf-page-raster-' . substr($requestDigest, 0, 32);
            $request['requestDigest'] = $requestDigest;
            $requestsByPage[$page] = $request;
        }
        ksort($requestsByPage, SORT_NUMERIC);

        return array_values($requestsByPage);
    }

    /** @param array<string,mixed> $request */
    private function pdfPageRasterRequestDigest(array $request): string
    {
        $box = array_map(
            static fn (mixed $value): string => sprintf('%.6F', (float) $value),
            array_values(is_array($request['pageBox'] ?? null) ? $request['pageBox'] : [])
        );

        return hash('sha256', implode("\n", [
            'pdf-page-raster-request-v1',
            'method=' . (string) ($request['method'] ?? ''),
            'sourceSha256=' . (string) ($request['sourceSha256'] ?? ''),
            'page=' . (string) ($request['page'] ?? ''),
            'pageObject=' . (string) ($request['pageObject'] ?? ''),
            'pageBox=' . implode(',', $box),
            'pageBoxSource=' . (string) ($request['pageBoxSource'] ?? ''),
            'pageRotation=' . (string) ($request['pageRotation'] ?? ''),
            'width=' . (string) ($request['width'] ?? ''),
            'height=' . (string) ($request['height'] ?? ''),
            'mimeType=' . (string) ($request['mimeType'] ?? ''),
        ]));
    }

    /**
     * @param array<string, mixed> $structuralMetadata
     * @param array<string, mixed> $extractorOptions
     * @return array{totalPages: int, startPage: int, endPage: int|null, pageNumbers: list<int>, hasMorePages: bool, nextPage: int|null}
     */
    private function pdfPageInventory(
        PdfTextExtractor $extractor,
        string $pdfBytes,
        array $structuralMetadata,
        array $extractorOptions
    ): array {
        try {
            return $extractor->extractPageInventory($pdfBytes);
        } catch (\Throwable) {
            $totalPages = max(0, (int) ($structuralMetadata['pdfEstimatedPages'] ?? 0));
            $startPage = $this->pdfStartPageFromOptions($extractorOptions);
            $maxPages = $this->pdfMaxPagesFromOptions($extractorOptions);
            $availablePages = $totalPages >= $startPage ? $totalPages - $startPage + 1 : 0;
            $selectedCount = $maxPages === null ? $availablePages : min($availablePages, $maxPages);
            $pageNumbers = $selectedCount > 0
                ? range($startPage, $startPage + $selectedCount - 1)
                : [];
            $endPage = $pageNumbers === [] ? null : $pageNumbers[count($pageNumbers) - 1];
            $hasMorePages = $endPage !== null && $endPage < $totalPages;

            return [
                'totalPages' => $totalPages,
                'startPage' => $startPage,
                'endPage' => $endPage,
                'pageNumbers' => $pageNumbers,
                'hasMorePages' => $hasMorePages,
                'nextPage' => $hasMorePages ? $endPage + 1 : null,
            ];
        }
    }

    /**
     * @param array<string, mixed> $structuralMetadata
     */
    private function fastTextOnlyMode(string $pdfBytes, array $structuralMetadata): bool
    {
        foreach (['pdfFastTextOnly', 'fastTextOnly'] as $key) {
            if (array_key_exists($key, $this->options)) {
                return (bool) $this->options[$key];
            }
        }

        $threshold = (int) ($this->options['pdfFastModeBytes'] ?? self::DEFAULT_FAST_MODE_BYTES);
        if ($threshold > 0 && strlen($pdfBytes) >= $threshold) {
            return true;
        }

        return false;
    }

    /**
     * @return array<string, mixed>
     */
    private function fastTextOnlyDiagnostics(): array
    {
        return [
            'warnings' => ['Large PDF imported in bounded text-only mode; expensive geometry, annotation, and tagged-structure diagnostics were skipped.'],
            'unsupportedFilters' => [],
            'failedStreams' => 0,
            'malformedXrefOffsets' => [],
            'malformedXrefStreams' => 0,
            'malformedObjectStreams' => 0,
            'missingUnicodeFonts' => [],
            'missingUnicodeFontEncodings' => [],
            'suppressedGlyphRuns' => 0,
            'partiallyMappedGlyphRuns' => 0,
            'unrecoverableActualTextRuns' => 0,
            'ignoredXObjectSubtypes' => [],
            'ignoredXObjectCount' => 0,
            'taggedRoleMap' => [],
            'taggedStructureRoles' => [],
            'taggedStructureLanguages' => [],
            'taggedClassMap' => [],
            'taggedStructureAttributes' => [],
            'taggedStructureItems' => [],
            'taggedStructureBlocks' => [],
            'taggedTables' => [],
            'taggedAttributeOwners' => [],
            'taggedStructElementCount' => 0,
            'linkAnnotations' => [],
            'textAnnotations' => [],
            'fileAttachmentAnnotations' => [],
            'popupAnnotations' => [],
            'appearanceAnnotations' => [],
            'pageExtractionIssues' => [],
            'pagesWithExtractionIssues' => [],
            'encryptionDecrypted' => false,
            'encryptionHandler' => null,
            'encryptionPasswordType' => null,
            'encryptionPermissions' => null,
            'encryptionAllowsContentExtraction' => null,
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private function structuralMetadata(string $pdfBytes): array
    {
        return $this->structuralMetadataFromDocumentMetadata(
            $pdfBytes,
            $this->documentStructuralMetadata($pdfBytes)
        );
    }

    /**
     * @param array<string, mixed> $documentMetadata
     * @return array<string, mixed>
     */
    private function structuralMetadataFromDocumentMetadata(string $pdfBytes, array $documentMetadata): array
    {
        $metadata = [
            'pdfHeader' => preg_match('/%PDF-\d\.\d/', substr($pdfBytes, 0, 64), $match) === 1 ? $match[0] : 'unknown',
        ];
        $metadata['pdfEstimatedPages'] = max(0, (int) ($documentMetadata['page_count'] ?? 0));
        $metadata['pdfObjectCount'] = max(0, (int) ($documentMetadata['object_count'] ?? 0));
        $metadata['pdfStreamCount'] = max(0, (int) ($documentMetadata['stream_count'] ?? 0));
        $metadata['pdfEncrypted'] = (($documentMetadata['encryption']['is_encrypted'] ?? false) === true);
        if (($documentMetadata['page_count_limited'] ?? false) === true) {
            $metadata['pdfPageCountLimited'] = true;
        }

        return $metadata;
    }

    /**
     * Add small, bounded document metadata only after fast-mode selection.
     * PDF Info retains the long-standing precedence over XMP for this reader.
     *
     * @param array<string, mixed> $metadata
     * @return array<string, mixed>
     */
    private function withReaderMetadata(array $metadata, string $pdfBytes, ?array $suppliedDocumentMetadata = null): array
    {
        $documentMetadata = $suppliedDocumentMetadata ?? $this->documentMetadata($pdfBytes);
        $info = is_array($documentMetadata['info'] ?? null) ? $documentMetadata['info'] : [];

        $title = $this->metadataString($info, 'Title');
        if ($title === '') {
            $title = $this->metadataString($documentMetadata, 'title');
        }
        if ($title !== '') {
            $metadata['title'] = $title;
            $metadata['titleInlines'] = [new AstNode('text', ['text' => $title])];
        }

        $infoAuthor = $this->metadataString($info, 'Author');
        $author = $infoAuthor === ''
            ? ''
            : $this->firstMetadataString(preg_split('/\s*;\s*/', $infoAuthor, -1, PREG_SPLIT_NO_EMPTY) ?: []);
        if ($author === '') {
            $author = $this->firstMetadataString($documentMetadata['authors'] ?? null);
        }
        if ($author !== '') {
            $metadata['author'] = $author;
        }

        foreach ([
            'Creator' => ['creator_tool', 'creator'],
            'Producer' => ['producer', 'producer'],
            'CreationDate' => ['created_at', 'created'],
        ] as $infoKey => [$documentKey, $metadataKey]) {
            $value = $this->metadataString($info, $infoKey);
            if ($value === '') {
                $value = $this->metadataString($documentMetadata, $documentKey);
            }
            if ($value !== '') {
                $metadata[$metadataKey] = $value;
            }
        }

        return $metadata;
    }

    /**
     * @param list<array<string, mixed>> $items
     * @return list<array<string, mixed>>
     */
    private function normalizePdfTextLineItems(array $items): array
    {
        $normalized = [];
        foreach ($items as $index => $item) {
            $normalizedItem = $this->normalizePdfTextLineItem($item, $index);
            if ($normalizedItem !== null) {
                $normalized[] = $normalizedItem;
            }
        }

        return $normalized;
    }

    /**
     * @param array<string, mixed> $item
     * @return array<string, mixed>|null
     */
    private function normalizePdfTextLineItem(array $item, int $index): ?array
    {
        $line = isset($item['text']) ? (string) $item['text'] : '';
        $line = $this->normalizePdfTextEncoding($line, true);
        $line = str_replace("\0", '', $line);
        $line = preg_replace('/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/u', ' ', $line) ?? $line;
        $line = trim($line);
        if ($line === '') {
            return null;
        }

        $page = max(1, (int) ($item['page'] ?? $index + 1));
        $stream = max(1, (int) ($item['stream'] ?? $index + 1));
        $identity = [
            'source' => $this->sourceSha256,
            'page' => $page,
            'pageObject' => is_int($item['pageObject'] ?? null) ? $item['pageObject'] : null,
            'stream' => $stream,
            'index' => $index,
            'text' => $line,
        ];
        $encodedIdentity = json_encode(
            $identity,
            JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_PRESERVE_ZERO_FRACTION
        );
        $id = is_string($item['id'] ?? null) && $item['id'] !== ''
            ? $item['id']
            : 'line-' . substr(hash('sha256', is_string($encodedIdentity) ? $encodedIdentity : serialize($identity)), 0, 24);
        $normalized = [
            'id' => $id,
            'page' => $page,
            'stream' => $stream,
            'text' => $line,
        ];
        if (is_array($item['provenance'] ?? null)) {
            $normalized['provenance'] = $item['provenance'];
        } else {
            $normalized['provenance'] = [
                'provider' => 'native-direct',
                'kind' => 'line',
                'page' => $page,
                'stream' => $stream,
                'index' => $index,
            ];
        }
        foreach (['pageObject', 'contentStream', 'contentStreamObject', 'lineIndex', 'mcid'] as $key) {
            if (array_key_exists($key, $item)) {
                $normalized[$key] = $item[$key];
            }
        }

        return $normalized;
    }

    /**
     * Attach one compact, occurrence-local geometry record to each source
     * text line while positioned runs are still available. Native extraction
     * marks the first painted run of each ordinary source line with the
     * `line-break` provenance used below. A baseline fallback covers supplied
     * browser facts that preserve geometry but omit that native marker.
     *
     * Matching is page-, stream-, occurrence-, and character-specific. A
     * repeated spelling therefore cannot borrow the bbox of another copy on
     * the same page.
     *
     * @param list<array<string, mixed>> $lineItems
     * @param list<array<string, mixed>> $positionedRuns
     */
    private function withPdfSourceOccurrenceGeometry(array &$lineItems, array &$positionedRuns): void
    {
        if ($lineItems === [] || $positionedRuns === []) {
            return;
        }

        // Some content streams paint both columns on one baseline while the
        // text extractor exposes two source line records. Prove those partial
        // occurrence bboxes through the complete page/stream character
        // sequence: only an exact byte-for-byte source/positioned stream match
        // authorizes slicing run geometry by source occurrence offsets.
        $positionedStreams = [];
        foreach ($positionedRuns as $runIndex => $run) {
            if (!is_array($run)
                || !is_string($run['text'] ?? null)
                || trim($run['text']) === ''
                || !$this->pdfLayoutHasGeometry($run)) {
                continue;
            }
            $comparable = $this->pdfSourceOccurrenceComparableText($run['text']);
            if ($comparable === '') {
                continue;
            }
            $page = max(1, (int) ($run['page'] ?? 1));
            $stream = max(1, (int) ($run['stream'] ?? 1));
            $key = $page . "\0" . $stream;
            if (!isset($positionedStreams[$key])) {
                $positionedStreams[$key] = ['text' => '', 'spans' => []];
            }
            $start = strlen($positionedStreams[$key]['text']);
            $positionedStreams[$key]['text'] .= $comparable;
            // This inventory can contain tens of thousands of glyph runs.
            // Store one flat integer triple per run and read geometry from the
            // canonical run only when its stream is matched. Even packed
            // nested arrays would retain one PHP allocation per glyph.
            $positionedStreams[$key]['spans'][] = $runIndex;
            $positionedStreams[$key]['spans'][] = $start;
            $positionedStreams[$key]['spans'][] = $start + strlen($comparable);
        }
        $sourceStreams = [];
        foreach ($lineItems as $index => $item) {
            $text = is_string($item['text'] ?? null) ? $item['text'] : '';
            $comparable = $this->pdfSourceOccurrenceComparableText($text);
            if ($comparable === '') {
                continue;
            }
            $page = max(1, (int) ($item['page'] ?? 1));
            $stream = max(1, (int) ($item['stream'] ?? 1));
            $key = $page . "\0" . $stream;
            if (!isset($sourceStreams[$key])) {
                $sourceStreams[$key] = ['text' => '', 'ranges' => []];
            }
            $start = strlen($sourceStreams[$key]['text']);
            $sourceStreams[$key]['text'] .= $comparable;
            $sourceStreams[$key]['ranges'][] = $index;
            $sourceStreams[$key]['ranges'][] = $start;
            $sourceStreams[$key]['ranges'][] = $start + strlen($comparable);
            $sourceStreams[$key]['ranges'][] = $page;
            $sourceStreams[$key]['ranges'][] = $stream;
        }
        while ($sourceStreams !== []) {
            $key = array_key_first($sourceStreams);
            if (!is_string($key)) {
                break;
            }
            $sourceStream = $sourceStreams[$key];
            $positionedStream = $positionedStreams[$key] ?? null;
            unset($sourceStreams[$key], $positionedStreams[$key]);
            if (!is_array($positionedStream)
                || !is_string($sourceStream['text'] ?? null)
                || !is_string($positionedStream['text'] ?? null)
                || !hash_equals($sourceStream['text'], $positionedStream['text'])
                || !is_array($sourceStream['ranges'] ?? null)
                || !is_array($positionedStream['spans'] ?? null)) {
                continue;
            }
            $spans = $positionedStream['spans'];
            $spanOffset = 0;
            $ranges = $sourceStream['ranges'];
            unset($positionedStream, $sourceStream);
            $rangeCount = count($ranges);
            for ($rangeOffset = 0; $rangeOffset < $rangeCount; $rangeOffset += 5) {
                $rangeIndex = (int) $ranges[$rangeOffset];
                $rangeStart = (int) $ranges[$rangeOffset + 1];
                $rangeEnd = (int) $ranges[$rangeOffset + 2];
                while (isset($spans[$spanOffset + 2])
                    && (int) $spans[$spanOffset + 2] <= $rangeStart) {
                    $spanOffset += 3;
                }
                $bounds = null;
                $orientation = null;
                for ($candidateOffset = $spanOffset; isset($spans[$candidateOffset + 2]); $candidateOffset += 3) {
                    $runIndex = $spans[$candidateOffset];
                    $runStart = (int) $spans[$candidateOffset + 1];
                    $runEnd = (int) $spans[$candidateOffset + 2];
                    if ($runStart >= $rangeEnd) {
                        break;
                    }
                    if ($runEnd <= $rangeStart
                        || !is_int($runIndex)
                        || !isset($positionedRuns[$runIndex])) {
                        continue;
                    }
                    $run = $positionedRuns[$runIndex];
                    $runX1 = (float) $run['x1'];
                    $runY1 = (float) $run['y1'];
                    $runX2 = (float) $run['x2'];
                    $runY2 = (float) $run['y2'];
                    $runOrientation = $this->pdfSourceProfileOrientation($run);
                    unset($run);
                    $overlapStart = max($runStart, $rangeStart);
                    $overlapEnd = min($runEnd, $rangeEnd);
                    if ($overlapEnd > $overlapStart) {
                        $this->appendPdfPositionedExactSourceRange(
                            $positionedRuns[$runIndex],
                            $rangeIndex,
                            $overlapStart - $rangeStart,
                            $overlapEnd - $rangeStart
                        );
                    }
                    if ($bounds === null) {
                        $bounds = [
                            'page' => (int) $ranges[$rangeOffset + 3],
                            'stream' => (int) $ranges[$rangeOffset + 4],
                            'x1' => $runX1,
                            'y1' => $runY1,
                            'x2' => $runX2,
                            'y2' => $runY2,
                        ];
                        $orientation = $runOrientation;
                    } else {
                        $bounds['x1'] = min($bounds['x1'], $runX1);
                        $bounds['y1'] = min($bounds['y1'], $runY1);
                        $bounds['x2'] = max($bounds['x2'], $runX2);
                        $bounds['y2'] = max($bounds['y2'], $runY2);
                        if ($orientation !== $runOrientation) {
                            $orientation = '';
                        }
                    }
                }
                if ($bounds !== null && isset($lineItems[$rangeIndex])) {
                    $bounds['orientation'] = $orientation ?? '';
                    $lineItems[$rangeIndex]['sourceGeometry'] = $bounds;
                    $lineItems[$rangeIndex]['sourceGeometryMethod'] = 'exact-page-stream-character-offset';
                }
            }
            unset($spans, $ranges);
        }

        unset($positionedStreams, $sourceStreams);

        // The exact stream proof already supplied every source bbox. Avoid
        // rebuilding a second document-wide geometry candidate inventory in
        // the overwhelmingly common fully matched case.
        $needsFallback = false;
        foreach ($lineItems as $item) {
            $text = is_string($item['text'] ?? null) ? $item['text'] : '';
            if ($this->pdfSourceOccurrenceComparableText($text) !== ''
                && !is_array($item['sourceGeometry'] ?? null)) {
                $needsFallback = true;
                break;
            }
        }
        if (!$needsFallback) {
            return;
        }

        $candidatesByKey = [];
        $runEvidencePart = static function (
            array $run,
            int $runIndex,
            int $start,
            int $end
        ): string {
            $evidence = [
                'runIndex' => $runIndex,
                'start' => $start,
                'end' => $end,
                'textDigest' => hash('sha256', (string) ($run['text'] ?? '')),
                'x1' => (float) ($run['x1'] ?? 0.0),
                'y1' => (float) ($run['y1'] ?? 0.0),
                'x2' => (float) ($run['x2'] ?? 0.0),
                'y2' => (float) ($run['y2'] ?? 0.0),
                'fontResource' => is_string($run['fontResource'] ?? null)
                    ? $run['fontResource']
                    : null,
                'baseFont' => is_string($run['baseFont'] ?? null)
                    ? $run['baseFont']
                    : null,
                'fontSubtype' => is_string($run['fontSubtype'] ?? null)
                    ? $run['fontSubtype']
                    : null,
                'textOrigin' => is_string($run['textOrigin'] ?? null)
                    ? $run['textOrigin']
                    : null,
            ];

            return json_encode(
                $evidence,
                JSON_UNESCAPED_SLASHES
                    | JSON_UNESCAPED_UNICODE
                    | JSON_PRESERVE_ZERO_FRACTION
            ) ?: serialize($evidence);
        };
        $current = null;
        $flush = function () use (&$current, &$candidatesByKey): void {
            if (!is_array($current) || ($current['comparable'] ?? '') === '') {
                $current = null;

                return;
            }
            $matchKey = (int) $current['page'] . "\0"
                . (int) $current['stream'] . "\0"
                . hash('sha256', (string) $current['comparable']);
            $current['projection'] = $current['comparable'];
            $current['projectionDigest'] = hash('sha256', $current['comparable']);
            $current['runEvidenceDigest'] = hash(
                'sha256',
                implode("\0", $current['runEvidenceParts'] ?? [])
            );
            unset(
                $current['comparable'],
                $current['baseline'],
                $current['fontSize'],
                $current['runEvidenceParts']
            );
            $candidatesByKey[$matchKey][] = $current;
            $current = null;
        };

        foreach ($positionedRuns as $runIndex => $run) {
            if (!is_array($run)
                || !is_string($run['text'] ?? null)
                || trim($run['text']) === ''
                || !$this->pdfLayoutHasGeometry($run)) {
                continue;
            }
            $page = max(1, (int) ($run['page'] ?? 1));
            $stream = max(1, (int) ($run['stream'] ?? 1));
            $baseline = is_numeric($run['textY1'] ?? null)
                ? (float) $run['textY1']
                : (((float) $run['y1'] + (float) $run['y2']) / 2.0);
            $fontSize = max(1.0, (float) ($run['fontSize'] ?? 1.0));
            $boundarySource = is_string($run['wordBoundarySource'] ?? null)
                ? $run['wordBoundarySource']
                : null;
            $differentSource = is_array($current)
                && ($page !== (int) $current['page'] || $stream !== (int) $current['stream']);
            $explicitLineBreak = is_array($current) && $boundarySource === 'line-break';
            $unmarkedBaselineBreak = is_array($current)
                && $boundarySource === null
                && abs($baseline - (float) $current['baseline'])
                    > max(3.0, max($fontSize, (float) $current['fontSize']) * 0.55);
            if ($differentSource || $explicitLineBreak || $unmarkedBaselineBreak) {
                $flush();
            }

            $runComparable = $this->pdfSourceOccurrenceComparableText((string) $run['text']);
            if (!is_array($current)) {
                $runEnd = strlen($runComparable);
                $current = [
                    'page' => $page,
                    'stream' => $stream,
                    'x1' => (float) $run['x1'],
                    'y1' => (float) $run['y1'],
                    'x2' => (float) $run['x2'],
                    'y2' => (float) $run['y2'],
                    'orientation' => $this->pdfSourceProfileOrientation($run),
                    'comparable' => $runComparable,
                    'baseline' => $baseline,
                    'fontSize' => $fontSize,
                    'spans' => [$runIndex, 0, $runEnd],
                    'runEvidenceParts' => [
                        $runEvidencePart($run, $runIndex, 0, $runEnd),
                    ],
                ];
                continue;
            }

            $current['x1'] = min((float) $current['x1'], (float) $run['x1']);
            $current['y1'] = min((float) $current['y1'], (float) $run['y1']);
            $current['x2'] = max((float) $current['x2'], (float) $run['x2']);
            $current['y2'] = max((float) $current['y2'], (float) $run['y2']);
            $orientation = $this->pdfSourceProfileOrientation($run);
            if (($current['orientation'] ?? '') !== $orientation) {
                $current['orientation'] = '';
            }
            $runStart = strlen((string) $current['comparable']);
            $current['comparable'] .= $runComparable;
            $runEnd = strlen((string) $current['comparable']);
            $current['spans'][] = $runIndex;
            $current['spans'][] = $runStart;
            $current['spans'][] = $runEnd;
            $current['runEvidenceParts'][] = $runEvidencePart(
                $run,
                $runIndex,
                $runStart,
                $runEnd
            );
            $current['baseline'] = $baseline;
            $current['fontSize'] = max((float) $current['fontSize'], $fontSize);
        }
        $flush();

        if ($candidatesByKey === []) {
            return;
        }

        $sourceIndexesByMatchKey = [];
        foreach ($lineItems as $sourceIndex => $item) {
            if (is_array($item['sourceGeometry'] ?? null)) {
                continue;
            }
            $text = is_string($item['text'] ?? null) ? $item['text'] : '';
            $comparable = $this->pdfSourceOccurrenceComparableText($text);
            if ($comparable === '') {
                continue;
            }
            $matchKey = max(1, (int) ($item['page'] ?? 1)) . "\0"
                . max(1, (int) ($item['stream'] ?? 1)) . "\0"
                . hash('sha256', $comparable);
            $sourceIndexesByMatchKey[$matchKey][] = $sourceIndex;
        }

        foreach ($sourceIndexesByMatchKey as $matchKey => $sourceIndexes) {
            $candidates = $candidatesByKey[$matchKey] ?? null;
            // Repeated spellings are safe only when the complete local
            // occurrence multiplicity agrees. A missing or extra painted row
            // leaves every peer unsigned instead of shifting later ranges.
            if (!is_array($candidates) || count($candidates) !== count($sourceIndexes)) {
                continue;
            }
            foreach ($sourceIndexes as $occurrence => $sourceIndex) {
                $candidate = $candidates[$occurrence] ?? null;
                if (!is_array($candidate) || !isset($lineItems[$sourceIndex])) {
                    continue;
                }
                $item = &$lineItems[$sourceIndex];
                $projection = $this->pdfSourceOccurrenceComparableText(
                    (string) ($item['text'] ?? '')
                );
                $candidateProjection = is_string($candidate['projection'] ?? null)
                    ? $candidate['projection']
                    : '';
                $spans = is_array($candidate['spans'] ?? null)
                    ? $candidate['spans']
                    : [];
                $bounds = [
                    'page' => (int) ($candidate['page'] ?? 0),
                    'stream' => (int) ($candidate['stream'] ?? 0),
                    'x1' => (float) ($candidate['x1'] ?? 0.0),
                    'y1' => (float) ($candidate['y1'] ?? 0.0),
                    'x2' => (float) ($candidate['x2'] ?? 0.0),
                    'y2' => (float) ($candidate['y2'] ?? 0.0),
                    'orientation' => (string) ($candidate['orientation'] ?? ''),
                ];
                $item['sourceGeometry'] = $bounds;
                if ($projection === ''
                    || !hash_equals($projection, $candidateProjection)
                    || !$this->pdfSourceBoundsAreValid($bounds)
                    || $bounds['orientation'] !== 'horizontal'
                    || count($spans) < 3
                    || count($spans) % 3 !== 0) {
                    unset($item);
                    continue;
                }
                $expectedStart = 0;
                $ranges = [];
                for ($spanOffset = 0; $spanOffset < count($spans); $spanOffset += 3) {
                    $runIndex = $spans[$spanOffset] ?? null;
                    $sourceStart = $spans[$spanOffset + 1] ?? null;
                    $sourceEnd = $spans[$spanOffset + 2] ?? null;
                    if (!is_int($runIndex)
                        || !is_int($sourceStart)
                        || !is_int($sourceEnd)
                        || $sourceStart !== $expectedStart
                        || $sourceEnd <= $sourceStart
                        || !isset($positionedRuns[$runIndex])) {
                        $ranges = [];
                        break;
                    }
                    $ranges[] = [$runIndex, $sourceStart, $sourceEnd];
                    $expectedStart = $sourceEnd;
                }
                $sourceId = is_string($item['id'] ?? null) ? $item['id'] : '';
                $globalSourceIndex = is_int($item['sourcePdfGlobalSourceIndex'] ?? null)
                    ? $item['sourcePdfGlobalSourceIndex']
                    : $sourceIndex;
                if ($ranges === []
                    || $expectedStart !== strlen($projection)
                    || $this->sourceSha256 === ''
                    || $sourceId === '') {
                    unset($item);
                    continue;
                }
                foreach ($ranges as [$runIndex, $sourceStart, $sourceEnd]) {
                    $existing = $this->pdfPositionedExactSourceRanges(
                        $positionedRuns[$runIndex]
                    );
                    if ($existing === []) {
                        $this->appendPdfPositionedExactSourceRange(
                            $positionedRuns[$runIndex],
                            $globalSourceIndex,
                            $sourceStart,
                            $sourceEnd
                        );
                    } else {
                        $positionedRuns[$runIndex]['sourcePdfExactSourceRanges'] = [
                            ...$existing,
                            [
                                'sourceIndex' => $globalSourceIndex,
                                'sourceStart' => $sourceStart,
                                'sourceEnd' => $sourceEnd,
                            ],
                        ];
                        unset(
                            $positionedRuns[$runIndex]['sourcePdfExactSourceIndex'],
                            $positionedRuns[$runIndex]['sourcePdfExactSourceStart'],
                            $positionedRuns[$runIndex]['sourcePdfExactSourceEnd']
                        );
                    }
                }
                $identity = [
                    'version' => 1,
                    'method' => 'exact-line-local-page-stream-character-offset',
                    'sourceSha256' => $this->sourceSha256,
                    'sourceOccurrenceId' => $sourceId,
                    'globalSourceIndex' => $globalSourceIndex,
                    'page' => $bounds['page'],
                    'stream' => $bounds['stream'],
                    'projectionDigest' => hash('sha256', $projection),
                    'projectionLength' => strlen($projection),
                    'sourceRange' => [0, strlen($projection)],
                    'runCount' => count($ranges),
                    'runEvidenceDigest' => (string) ($candidate['runEvidenceDigest'] ?? ''),
                    'sourceBounds' => $this->pdfSourceEvidenceBounds($bounds),
                ];
                $encoded = json_encode(
                    $identity,
                    JSON_UNESCAPED_SLASHES
                        | JSON_UNESCAPED_UNICODE
                        | JSON_PRESERVE_ZERO_FRACTION
                );
                $item['sourceGeometryMethod'] = 'exact-page-stream-character-offset';
                $item['sourcePdfLineLocalExactProof'] = $identity + [
                    'proofDigest' => hash(
                        'sha256',
                        is_string($encoded) ? $encoded : serialize($identity)
                    ),
                ];
                unset($item);
            }
        }
    }

    /**
     * Keep the uncommon repair implementation unloaded unless immutable source
     * facts and exact positioned-run evidence can still satisfy one of its two
     * producer-independent proofs.
     *
     * @param list<array<string,mixed>> $lineItems
     * @param list<array<string,mixed>> $positionedRuns
     */
    private function markSourcePdfFacingFolioAndChoiceMatrixRepairs(
        array &$lineItems,
        array $positionedRuns
    ): void {
        if (!$this->shouldLoadSourcePdfFacingFolioAndChoiceMatrixRepair(
            $lineItems,
            $positionedRuns
        )) {
            return;
        }

        PdfFacingFolioChoiceMatrixRepair::mark(
            $lineItems,
            $positionedRuns,
            $this->sourceSha256,
            $this->sourcePdfSourceItemHasExactGeometry(...),
            $this->pdfSourceOccurrenceComparableText(...),
            $this->pdfLayoutHasGeometry(...),
            $this->pdfSourceProfileOrientation(...),
            $this->pdfPositionedExactSourceRanges(...),
            $this->pdfSourceEvidenceBounds(...)
        );
    }

    /**
     * Facing-folio source text is sufficient only when an exact horizontal run
     * binds to it. A choice-matrix lookalike must additionally bind a leading
     * ActualText whitespace replacement and its matching symbolic glyph to the
     * same candidate label occurrence. This excludes chart-cipher two-glyph
     * rows without compiling the specialized repair helper.
     *
     * @param list<array<string,mixed>> $lineItems
     * @param list<array<string,mixed>> $positionedRuns
     */
    private function shouldLoadSourcePdfFacingFolioAndChoiceMatrixRepair(
        array $lineItems,
        array $positionedRuns
    ): bool {
        if ($lineItems === [] || $positionedRuns === [] || $this->sourceSha256 === '') {
            return false;
        }

        $facingSourceIndexes = [];
        $choiceLabelSourceIndexes = [];
        foreach ($lineItems as $sourceIndex => $item) {
            if (!$this->sourcePdfSourceItemHasExactGeometry($item)) {
                continue;
            }
            $globalSourceIndex = is_int($item['sourcePdfGlobalSourceIndex'] ?? null)
                ? $item['sourcePdfGlobalSourceIndex']
                : $sourceIndex;
            $text = is_string($item['text'] ?? null) ? $item['text'] : '';
            if (preg_match(
                '/\A\s*(\d{1,4})\s+(\d{1,4})(?!\d)(.+)\z/us',
                $text,
                $folioMatch
            ) === 1) {
                $leftFolio = $folioMatch[1];
                $rightFolio = $folioMatch[2];
                $title = trim($folioMatch[3]);
                $titleComparable = $this->pdfSourceOccurrenceComparableText($title);
                $sourceComparable = $this->pdfSourceOccurrenceComparableText($text);
                if ($title !== ''
                    && strlen($titleComparable) >= 12
                    && preg_match_all('/\p{L}+/u', $title, $titleWords) >= 3
                    && hash_equals(
                        $leftFolio . $rightFolio . $titleComparable,
                        $sourceComparable
                    )
                    && abs((int) $rightFolio - (int) $leftFolio) === 1) {
                    $facingSourceIndexes[$globalSourceIndex] = true;
                }
            }

            $marker = $lineItems[$sourceIndex + 1] ?? null;
            if (!is_array($marker)
                || !$this->sourcePdfSourceItemHasExactGeometry($marker)
                || (int) ($marker['page'] ?? 0) !== (int) ($item['page'] ?? 0)
                || (int) ($marker['stream'] ?? 0) !== (int) ($item['stream'] ?? 0)) {
                continue;
            }
            $labelComparable = $this->pdfSourceOccurrenceComparableText($text);
            $markerComparable = $this->pdfSourceOccurrenceComparableText(
                (string) ($marker['text'] ?? '')
            );
            preg_match_all('/\X/u', $markerComparable, $markerGraphemes);
            $graphemes = $markerGraphemes[0] ?? [];
            if (strlen($labelComparable) >= 4
                && count($graphemes) === 2
                && preg_match('/[\p{L}\p{N}\s]/u', implode('', $graphemes)) !== 1) {
                $choiceLabelSourceIndexes[$globalSourceIndex] = true;
            }
        }
        if ($facingSourceIndexes === [] && $choiceLabelSourceIndexes === []) {
            return false;
        }

        $actualTextEvidence = [];
        $symbolicEvidence = [];
        foreach ($positionedRuns as $run) {
            if (!is_array($run)
                || !$this->pdfLayoutHasGeometry($run)
                || $this->pdfSourceProfileOrientation($run) !== 'horizontal') {
                continue;
            }
            foreach ($this->pdfPositionedExactSourceRanges($run) as $range) {
                $sourceIndex = $range['sourceIndex'];
                if (isset($facingSourceIndexes[$sourceIndex])) {
                    return true;
                }
                if (!isset($choiceLabelSourceIndexes[$sourceIndex])) {
                    continue;
                }
                $runComparable = $this->pdfSourceOccurrenceComparableText(
                    (string) ($run['text'] ?? '')
                );
                if ($runComparable === ''
                    || preg_match('/\A\X\z/u', $runComparable) !== 1) {
                    continue;
                }
                $sourceStart = $range['sourceStart'];
                $sourceEnd = $range['sourceEnd'];
                if (($run['textOrigin'] ?? null) === 'actual-text-replacement'
                    && ($run['actualTextPaintedWhitespaceOnly'] ?? null) === true
                    && $sourceStart === 0) {
                    $evidenceKey = $sourceEnd . "\0" . $runComparable;
                    if (isset($symbolicEvidence[$sourceIndex][$evidenceKey])) {
                        return true;
                    }
                    $actualTextEvidence[$sourceIndex][$evidenceKey] = true;
                }
                if (($run['fontSymbolic'] ?? null) === true) {
                    $evidenceKey = $sourceStart . "\0" . $runComparable;
                    if (isset($actualTextEvidence[$sourceIndex][$evidenceKey])) {
                        return true;
                    }
                    $symbolicEvidence[$sourceIndex][$evidenceKey] = true;
                }
            }
        }

        return false;
    }

    /**
     * @param list<array<string,mixed>> $layouts
     * @param list<array<string,mixed>> $sourceItems
     * @return list<array<string,mixed>>
     */
    private function pdfSourceLayoutsWithFacingFolioAndChoiceMatrixProjections(
        array $layouts,
        array $sourceItems
    ): array {
        $this->pdfSourceLayoutsWithFacingFolioAndChoiceMatrixProjectionsInPlace(
            $layouts,
            $sourceItems
        );

        return $layouts;
    }

    /**
     * @param list<array<string,mixed>> $layouts
     * @param list<array<string,mixed>> $sourceItems
     */
    private function pdfSourceLayoutsWithFacingFolioAndChoiceMatrixProjectionsInPlace(
        array &$layouts,
        array $sourceItems
    ): void {
        $hasProjectionReceipt = false;
        foreach ($sourceItems as $sourceItem) {
            if (is_array($sourceItem['sourcePdfFacingFolioBoundaryRepair'] ?? null)
                || is_array($sourceItem['sourcePdfChoiceMatrixBoundaryRepair'] ?? null)) {
                $hasProjectionReceipt = true;
                break;
            }
        }
        if (!$hasProjectionReceipt) {
            return;
        }

        PdfFacingFolioChoiceMatrixRepair::apply(
            $layouts,
            $sourceItems,
            $this->sourceSha256,
            $this->sourcePdfSourceItemHasExactGeometry(...),
            $this->pdfSourceOccurrenceComparableText(...),
            $this->pdfLayoutHasGeometry(...),
            $this->pdfSourceProfileOrientation(...),
            $this->pdfPositionedExactSourceRanges(...),
            $this->pdfSourceEvidenceBounds(...)
        );
    }

    /**
     * @param array<string,mixed> $proof
     * @param array<string,mixed> $item
     */
    private function sourcePdfBoundaryProjectionProofMatchesItem(
        array $proof,
        array $item,
        int $sourceIndex
    ): bool {
        return PdfFacingFolioChoiceMatrixRepair::proofMatches(
            $proof,
            $item,
            $sourceIndex,
            $this->sourceSha256,
            $this->sourcePdfSourceItemHasExactGeometry(...),
            $this->pdfSourceOccurrenceComparableText(...),
            $this->pdfLayoutHasGeometry(...),
            $this->pdfSourceProfileOrientation(...),
            $this->pdfPositionedExactSourceRanges(...),
            $this->pdfSourceEvidenceBounds(...)
        );
    }

    /** @param array<string,mixed> $proof */
    private function sourcePdfSignedProofDigestMatches(array $proof): bool
    {
        $declared = $proof['proofDigest'] ?? null;
        if (!is_string($declared) || preg_match('/\A[0-9a-f]{64}\z/D', $declared) !== 1) {
            return false;
        }
        unset($proof['proofDigest']);
        $encoded = json_encode(
            $proof,
            JSON_UNESCAPED_SLASHES
                | JSON_UNESCAPED_UNICODE
                | JSON_PRESERVE_ZERO_FRACTION
        );

        return hash_equals(
            $declared,
            hash('sha256', is_string($encoded) ? $encoded : serialize($proof))
        );
    }

    /**
     * A form can style every field label like a small title. Title case is not
     * outline evidence when geometry instead proves several stacked labels in
     * one narrow lane, each aligned with substantive entry text to its right.
     * Mark those page-local labels before source/positioned arbitration can
     * discard their bboxes. The final text remains editable as paragraphs.
     *
     * Repeated horizontal text in the same top/bottom slot is also running
     * furniture rather than a new section on every page. Its spelling is
     * irrelevant: identity uses normalized text, page-edge slot, and relative
     * height, and requires occurrences on at least two pages.
     *
     * A consecutive exact source run can likewise be diagram furniture when
     * its uniformly sized boxes repeatedly reverse vertical direction across
     * a broad region and a complete exact caption sits immediately below it.
     * That source-bound role keeps every callout editable without promoting
     * its accidental title shape into the document outline.
     *
     * @param list<array<string, mixed>> $lineItems
     */
    private function markSourcePdfLayoutLabelOccurrences(array &$lineItems): void
    {
        $this->layoutLabelSourceIndexes = [];
        if ($lineItems === []) {
            return;
        }

        foreach ($this->sourcePdfSourceOrderRunningHeaderProofs($lineItems) as $index => $proof) {
            $this->layoutLabelSourceIndexes[$index] = true;
            $lineItems[$index]['sourcePdfSourceOrderRunningHeaderProof'] = $proof;
        }
        foreach ($this->sourcePdfExactSpatialLabelClusterProofs($lineItems) as $index => $proof) {
            $this->layoutLabelSourceIndexes[$index] = true;
            $lineItems[$index]['sourcePdfSpatialLabelClusterProof'] = $proof;
        }
        foreach ($this->sourcePdfExactNestedCautionCalloutProofs($lineItems) as $proof) {
            foreach ($proof['iconAtoms'] as $atom) {
                $index = (int) $atom['sourceIndex'];
                if (!isset($lineItems[$index])) {
                    continue;
                }
                $lineItems[$index]['sourcePdfNestedCautionCalloutRole'] = $atom['role'];
                $lineItems[$index]['sourcePdfNestedCautionCalloutProof'] = $proof;
            }
            $labelIndex = (int) $proof['label']['sourceIndex'];
            if (isset($lineItems[$labelIndex])) {
                $this->layoutLabelSourceIndexes[$labelIndex] = true;
                $lineItems[$labelIndex]['sourcePdfNestedCautionCalloutRole'] = 'label';
                $lineItems[$labelIndex]['sourcePdfNestedCautionCalloutProof'] = $proof;
            }
            foreach ($proof['proseRows'] as $row) {
                $index = (int) $row['sourceIndex'];
                if (!isset($lineItems[$index])) {
                    continue;
                }
                $lineItems[$index]['sourcePdfNestedCautionCalloutRole'] = 'prose-row';
                $lineItems[$index]['sourcePdfNestedCautionCalloutProof'] = $proof;
            }
        }

        $recordsByPage = [];
        foreach ($lineItems as $index => $item) {
            $geometry = is_array($item['sourceGeometry'] ?? null)
                && $this->pdfSourceBoundsAreValid($item['sourceGeometry'])
                ? $this->pdfSourceEvidenceBounds($item['sourceGeometry'])
                : null;
            $text = trim((string) ($item['text'] ?? ''));
            if ($geometry === null || $text === '') {
                continue;
            }
            $page = max(1, (int) ($item['page'] ?? 1));
            $recordsByPage[$page][] = [
                'index' => (int) $index,
                'stream' => max(1, (int) ($item['stream'] ?? 1)),
                'text' => $text,
                'bounds' => $geometry,
                'orientation' => (string) ($item['sourceGeometry']['orientation'] ?? ''),
            ];
        }
        if ($recordsByPage === []) {
            foreach ($this->layoutLabelSourceIndexes as $index => $_) {
                if (isset($lineItems[$index])) {
                    $lineItems[$index]['sourcePdfLayoutLabel'] = true;
                }
            }

            return;
        }

        $pageEvidence = [];
        foreach ($recordsByPage as $page => $records) {
            $evidence = $this->sourcePdfLayoutLabelPageEvidence($records);
            if ($evidence !== null) {
                $pageEvidence[$page] = $evidence;
            }
        }

        foreach ($this->sourcePdfOutlineIneligibleLayoutLabelIndexes(
            $lineItems,
            $recordsByPage,
            $pageEvidence
        ) as $index => $_) {
            $this->layoutLabelSourceIndexes[$index] = true;
        }

        foreach ($recordsByPage as $page => $records) {
            $evidence = $pageEvidence[$page] ?? null;
            if (!is_array($evidence) || !$this->sourcePdfPageHasFormLabelLane($records, $evidence)) {
                continue;
            }
            foreach ($records as $record) {
                $text = $record['text'];
                if (!$this->repairedLineLooksLikeSectionLabel($text)) {
                    continue;
                }
                $bounds = $record['bounds'];
                $height = max(0.0, (float) $bounds['y2'] - (float) $bounds['y1']);
                $width = max(0.0, (float) $bounds['x2'] - (float) $bounds['x1']);
                // A genuinely prominent short heading can occur inside a
                // form page. Preserve it when its bbox is both substantially
                // taller than the local line rhythm and geometrically sane.
                // Huge transformed boxes are not font evidence.
                $prominent = $height >= $evidence['medianHeight'] * 1.65
                    && $height <= $evidence['height'] * 0.10
                    && $width <= $evidence['width'] * 0.80;
                if (!$prominent) {
                    $this->layoutLabelSourceIndexes[$record['index']] = true;
                }
            }
        }

        // A compact label painted inside an oversized symbol is callout
        // furniture, even when its all-capital spelling resembles a heading.
        // Require exact same-page/source geometry and full containment by a
        // symbol-only occurrence; nearby prose and standalone display text
        // cannot satisfy this evidence.
        foreach ($recordsByPage as $records) {
            $symbolContainers = array_values(array_filter(
                $records,
                static function (array $record): bool {
                    $text = trim((string) ($record['text'] ?? ''));

                    return $text !== ''
                        && preg_match('/^[\p{S}\p{P}]+$/u', $text) === 1;
                }
            ));
            if ($symbolContainers === []) {
                continue;
            }
            foreach ($records as $record) {
                if (!$this->repairedLineLooksLikeSectionLabel($record['text'])) {
                    continue;
                }
                $bounds = $record['bounds'];
                $height = max(0.0, (float) $bounds['y2'] - (float) $bounds['y1']);
                if ($height <= 0.0) {
                    continue;
                }
                foreach ($symbolContainers as $container) {
                    $containerBounds = $container['bounds'];
                    $containerHeight = max(
                        0.0,
                        (float) $containerBounds['y2'] - (float) $containerBounds['y1']
                    );
                    if ($container['index'] === $record['index']
                        || $container['stream'] !== $record['stream']
                        || $containerHeight < $height * 2.0
                        || (float) $bounds['x1'] < (float) $containerBounds['x1'] - 0.5
                        || (float) $bounds['y1'] < (float) $containerBounds['y1'] - 0.5
                        || (float) $bounds['x2'] > (float) $containerBounds['x2'] + 0.5
                        || (float) $bounds['y2'] > (float) $containerBounds['y2'] + 0.5) {
                        continue;
                    }
                    $this->layoutLabelSourceIndexes[$record['index']] = true;
                    break;
                }
            }
        }

        $edgeCandidates = [];
        foreach ($recordsByPage as $page => $records) {
            $evidence = $pageEvidence[$page] ?? null;
            if (!is_array($evidence)) {
                continue;
            }
            foreach ($records as $record) {
                if (!$this->repairedLineLooksLikeSectionLabel($record['text'])) {
                    continue;
                }
                $bounds = $record['bounds'];
                $centerX = ((float) $bounds['x1'] + (float) $bounds['x2']) / 2.0;
                $centerY = ((float) $bounds['y1'] + (float) $bounds['y2']) / 2.0;
                $topDistance = ((float) $evidence['y2'] - $centerY) / $evidence['height'];
                $bottomDistance = ($centerY - (float) $evidence['y1']) / $evidence['height'];
                $edge = $topDistance <= 0.08
                    ? 'top'
                    : ($bottomDistance <= 0.08 ? 'bottom' : null);
                if ($edge === null) {
                    continue;
                }
                $fingerprint = $this->pdfComparableLineText($record['text']);
                $fingerprint = preg_replace('/^\p{N}{1,4}|\p{N}{1,4}$/u', '', $fingerprint) ?? $fingerprint;
                if ($this->length($fingerprint) < 4) {
                    continue;
                }
                $xSlot = (int) round((($centerX - $evidence['x1']) / $evidence['width']) * 12.0);
                $recordHeight = max(0.0, (float) $bounds['y2'] - (float) $bounds['y1']);
                $heightSlot = (int) round(($recordHeight / $evidence['medianHeight']) * 2.0);
                $key = $edge . "\0" . $xSlot . "\0" . $heightSlot . "\0" . $fingerprint;
                $edgeCandidates[$key][$page][] = $record['index'];
            }
        }
        foreach ($edgeCandidates as $pages) {
            if (count($pages) < 2) {
                continue;
            }
            foreach ($pages as $indexes) {
                foreach ($indexes as $index) {
                    $this->layoutLabelSourceIndexes[(int) $index] = true;
                }
            }
        }

        foreach ($this->layoutLabelSourceIndexes as $index => $_) {
            if (isset($lineItems[$index])) {
                $lineItems[$index]['sourcePdfLayoutLabel'] = true;
            }
        }
    }

    /**
     * Recover a running-header role when source order supplies evidence that
     * occurrence geometry cannot. A candidate must be the first significant
     * source occurrence on consecutive physical pages,
     * carry the same short tagged ordinal shape with ordinals increasing in
     * lockstep with the pages, and be followed immediately by the same exact
     * significant companion in the same page/stream. The proof is bound to
     * the source hash and every participating occurrence; spelling alone can
     * never authorize the role.
     *
     * @param list<array<string,mixed>> $lineItems
     * @return array<int,array<string,mixed>>
     */
    private function sourcePdfSourceOrderRunningHeaderProofs(array $lineItems): array
    {
        if (preg_match('/^[a-f0-9]{64}$/D', $this->sourceSha256) !== 1) {
            return [];
        }

        $significantIndexes = [];
        $significantPositionByIndex = [];
        $firstSignificantIndexByPage = [];
        foreach ($lineItems as $index => $item) {
            $text = is_string($item['text'] ?? null) ? $item['text'] : '';
            if ($this->pdfSourceOccurrenceComparableText($text) === '') {
                continue;
            }
            $index = (int) $index;
            $page = max(1, (int) ($item['page'] ?? 1));
            $significantPositionByIndex[$index] = count($significantIndexes);
            $significantIndexes[] = $index;
            if (!isset($firstSignificantIndexByPage[$page])) {
                $firstSignificantIndexByPage[$page] = $index;
            }
        }

        $groups = [];
        foreach ($firstSignificantIndexByPage as $page => $index) {
            $item = $lineItems[$index] ?? null;
            if (!is_array($item)) {
                continue;
            }
            $ordinalLabel = $this->sourcePdfSourceOrderRunningHeaderOrdinalLabel(
                (string) ($item['text'] ?? '')
            );
            if ($ordinalLabel === null) {
                continue;
            }

            $significantPosition = $significantPositionByIndex[$index] ?? null;
            $companionIndex = is_int($significantPosition)
                ? ($significantIndexes[$significantPosition + 1] ?? null)
                : null;
            $companion = is_int($companionIndex)
                ? ($lineItems[$companionIndex] ?? null)
                : null;
            $stream = max(1, (int) ($item['stream'] ?? 1));
            if (!is_array($companion)
                || max(1, (int) ($companion['page'] ?? 1)) !== $page
                || max(1, (int) ($companion['stream'] ?? 1)) !== $stream) {
                continue;
            }

            $companionText = (string) ($companion['text'] ?? '');
            $companionProjection = $this->pdfSourceOccurrenceComparableText($companionText);
            if ($this->length($this->pdfComparableLineText($companionText)) < 8) {
                continue;
            }

            $groupKey = $ordinalLabel['stemFingerprint'] . "\0"
                . $ordinalLabel['tagFingerprint'] . "\0"
                . $ordinalLabel['delimiter'] . "\0"
                . hash('sha256', $companionProjection);
            $groups[$groupKey][] = [
                'sourceIndex' => $index,
                'sourceGlobalIndex' => is_int($item['sourcePdfGlobalSourceIndex'] ?? null)
                    ? $item['sourcePdfGlobalSourceIndex']
                    : $index,
                'sourceOccurrenceId' => is_string($item['id'] ?? null)
                    ? $item['id']
                    : '',
                'page' => $page,
                'stream' => $stream,
                'ordinal' => $ordinalLabel['ordinal'],
                'projectionDigest' => hash(
                    'sha256',
                    $this->pdfSourceOccurrenceComparableText((string) ($item['text'] ?? ''))
                ),
                'companionSourceIndex' => $companionIndex,
                'companionGlobalSourceIndex' => is_int(
                    $companion['sourcePdfGlobalSourceIndex'] ?? null
                ) ? $companion['sourcePdfGlobalSourceIndex'] : $companionIndex,
                'companionOccurrenceId' => is_string($companion['id'] ?? null)
                    ? $companion['id']
                    : '',
                'companionProjectionDigest' => hash('sha256', $companionProjection),
                'stemDigest' => hash('sha256', $ordinalLabel['stemFingerprint']),
                'ordinalTagDigest' => hash(
                    'sha256',
                    $ordinalLabel['tagFingerprint'] . "\0" . $ordinalLabel['delimiter']
                ),
            ];
        }

        $proofs = [];
        foreach ($groups as $members) {
            if (count($members) < 2) {
                continue;
            }
            usort(
                $members,
                static fn (array $left, array $right): int =>
                    [$left['page'], $left['sourceIndex']]
                    <=> [$right['page'], $right['sourceIndex']]
            );

            $sequenceIsExact = true;
            for ($memberIndex = 1, $count = count($members); $memberIndex < $count; $memberIndex++) {
                $previous = $members[$memberIndex - 1];
                $current = $members[$memberIndex];
                if ($current['page'] !== $previous['page'] + 1
                    || $current['ordinal'] !== $previous['ordinal'] + 1
                    || $current['sourceGlobalIndex'] <= $previous['sourceGlobalIndex']) {
                    $sequenceIsExact = false;
                    break;
                }
            }
            if (!$sequenceIsExact) {
                continue;
            }

            $identity = [
                'version' => 1,
                'method' => 'recurring-first-source-slot-terminal-ordinal-with-companion',
                'sourceSha256' => $this->sourceSha256,
                'stemDigest' => $members[0]['stemDigest'],
                'ordinalTagDigest' => $members[0]['ordinalTagDigest'],
                'companionProjectionDigest' => $members[0]['companionProjectionDigest'],
                'peers' => array_map(
                    static fn (array $member): array => [
                        'sourceIndex' => $member['sourceIndex'],
                        'sourceGlobalIndex' => $member['sourceGlobalIndex'],
                        'sourceOccurrenceId' => $member['sourceOccurrenceId'],
                        'page' => $member['page'],
                        'stream' => $member['stream'],
                        'ordinal' => $member['ordinal'],
                        'projectionDigest' => $member['projectionDigest'],
                        'companionSourceIndex' => $member['companionSourceIndex'],
                        'companionGlobalSourceIndex' => $member['companionGlobalSourceIndex'],
                        'companionOccurrenceId' => $member['companionOccurrenceId'],
                        'companionProjectionDigest' => $member['companionProjectionDigest'],
                    ],
                    $members
                ),
            ];
            $encoded = json_encode(
                $identity,
                JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_PRESERVE_ZERO_FRACTION
            );
            $proof = $identity + [
                'proofDigest' => hash(
                    'sha256',
                    is_string($encoded) ? $encoded : serialize($identity)
                ),
            ];
            foreach ($members as $member) {
                $proofs[$member['sourceIndex']] = $proof;
            }
        }

        return $proofs;
    }

    /**
     * @return array{stemFingerprint:string,tagFingerprint:string,delimiter:string,ordinal:int}|null
     */
    private function sourcePdfSourceOrderRunningHeaderOrdinalLabel(string $text): ?array
    {
        $text = trim($this->normalizePdfTextEncoding($text));
        if (preg_match(
            '/^(.+?\p{L})\h+(\p{L}{1,3})\h*([.:#])\h*([0-9]{1,4})$/u',
            $text,
            $matches
        ) !== 1) {
            return null;
        }

        $stem = trim($matches[1]);
        $stemFingerprint = $this->pdfComparableLineText($stem);
        $wordCount = count($this->pdfLineWordTokens($stem));
        $ordinal = (int) $matches[4];
        if ($wordCount < 3
            || $wordCount > 12
            || $this->length($stemFingerprint) < 16
            || $ordinal < 1) {
            return null;
        }

        return [
            'stemFingerprint' => $stemFingerprint,
            'tagFingerprint' => $this->pdfComparableLineText($matches[2]),
            'delimiter' => $matches[3],
            'ordinal' => $ordinal,
        ];
    }

    /**
     * A diagram can expose its overlay labels as a consecutive source run even
     * though their exact rectangles jump around the illustrated region. When
     * that entire compact run has one line-height rhythm and is followed by a
     * complete caption below it, the source order is positive evidence for an
     * editable layout-label role and negative evidence for document outline
     * membership. The proof is occurrence- and geometry-bound; label spelling
     * and title casing never participate in the decision.
     *
     * @param list<array<string,mixed>> $lineItems
     * @return array<int,array<string,mixed>>
     */
    private function sourcePdfExactSpatialLabelClusterProofs(array $lineItems): array
    {
        if (preg_match('/^[a-f0-9]{64}$/D', $this->sourceSha256) !== 1
            || count($lineItems) < 10) {
            return [];
        }

        $proofs = [];
        $run = [];
        $flush = function () use (&$proofs, &$run, $lineItems): void {
            if ($run === []) {
                return;
            }
            $proof = $this->sourcePdfExactSpatialLabelClusterProof($run, $lineItems);
            if ($proof !== null) {
                foreach ($run as $member) {
                    $proofs[$member['sourceIndex']] = $proof;
                }
            }
            $run = [];
        };

        foreach ($lineItems as $sourceIndex => $item) {
            $candidate = $this->sourcePdfExactSpatialLabelCandidate(
                $item,
                (int) $sourceIndex
            );
            if ($candidate === null) {
                $flush();
                continue;
            }
            $previous = $run === [] ? null : $run[array_key_last($run)];
            if (is_array($previous)
                && ($candidate['page'] !== $previous['page']
                    || $candidate['stream'] !== $previous['stream']
                    || $candidate['sourceIndex'] !== $previous['sourceIndex'] + 1
                    || $candidate['sourceGlobalIndex'] !== $previous['sourceGlobalIndex'] + 1)) {
                $flush();
            }
            $run[] = $candidate;
        }
        $flush();

        return $proofs;
    }

    /**
     * @param array<string,mixed> $item
     * @return array{
     *   sourceIndex:int,
     *   sourceGlobalIndex:int,
     *   sourceOccurrenceId:string,
     *   page:int,
     *   stream:int,
     *   projectionDigest:string,
     *   geometryDigest:string,
     *   bounds:array{x1:float,y1:float,x2:float,y2:float},
     *   height:float
     * }|null
     */
    private function sourcePdfExactSpatialLabelCandidate(array $item, int $sourceIndex): ?array
    {
        $text = trim((string) ($item['text'] ?? ''));
        $sourceOccurrenceId = is_string($item['id'] ?? null) ? $item['id'] : '';
        $declaredGlobalIndex = $item['sourcePdfGlobalSourceIndex'] ?? null;
        $sourceGlobalIndex = $declaredGlobalIndex === null
            ? $sourceIndex
            : (is_int($declaredGlobalIndex) ? $declaredGlobalIndex : null);
        $page = (int) ($item['page'] ?? 0);
        $stream = (int) ($item['stream'] ?? 0);
        $geometry = is_array($item['sourceGeometry'] ?? null)
            ? $item['sourceGeometry']
            : null;
        $projection = $this->pdfSourceOccurrenceComparableText($text);
        if ($sourceOccurrenceId === ''
            || $sourceGlobalIndex === null
            || $sourceGlobalIndex < 0
            || $page < 1
            || $stream < 1
            || $geometry === null
            || !$this->sourcePdfSourceItemHasExactGeometry($item)
            || (int) ($geometry['page'] ?? 0) !== $page
            || (int) ($geometry['stream'] ?? 0) !== $stream
            || $projection === ''
            || $this->length($projection) < 2
            || !$this->lineLooksLikePdfDiagramLabel($text)
            || $this->lineHasPdfListBlockEvidence($text)
            || $this->lineLooksLikeUrlOnly($text)
            || $this->lineLooksLikeCompletePdfCaption($text)
            || $this->pdfLineStartsWithSemanticPrefix($text)) {
            return null;
        }

        $bounds = $this->pdfSourceEvidenceBounds($geometry);
        $bounds = [
            'x1' => min($bounds['x1'], $bounds['x2']),
            'y1' => min($bounds['y1'], $bounds['y2']),
            'x2' => max($bounds['x1'], $bounds['x2']),
            'y2' => max($bounds['y1'], $bounds['y2']),
        ];
        $height = $bounds['y2'] - $bounds['y1'];
        if ($height <= 0.0 || $bounds['x2'] <= $bounds['x1']) {
            return null;
        }

        return [
            'sourceIndex' => $sourceIndex,
            'sourceGlobalIndex' => $sourceGlobalIndex,
            'sourceOccurrenceId' => $sourceOccurrenceId,
            'page' => $page,
            'stream' => $stream,
            'projectionDigest' => hash('sha256', $projection),
            'geometryDigest' => $this->sourcePdfExactGeometryProofDigest($geometry),
            'bounds' => $bounds,
            'height' => $height,
        ];
    }

    /**
     * @param list<array{
     *   sourceIndex:int,
     *   sourceGlobalIndex:int,
     *   sourceOccurrenceId:string,
     *   page:int,
     *   stream:int,
     *   projectionDigest:string,
     *   geometryDigest:string,
     *   bounds:array{x1:float,y1:float,x2:float,y2:float},
     *   height:float
     * }> $members
     * @param list<array<string,mixed>> $lineItems
     * @return array<string,mixed>|null
     */
    private function sourcePdfExactSpatialLabelClusterProof(
        array $members,
        array $lineItems
    ): ?array {
        $memberCount = count($members);
        if ($memberCount < 8 || $memberCount > 64) {
            return null;
        }

        $heights = array_column($members, 'height');
        $medianHeight = max(0.01, $this->median($heights));
        $heightTolerance = max(0.75, $medianHeight * 0.15);
        foreach ($heights as $height) {
            if (abs((float) $height - $medianHeight) > $heightTolerance) {
                return null;
            }
        }

        $verticalSigns = [];
        $verticalStepTolerance = max(0.75, $medianHeight * 0.12);
        for ($index = 1; $index < $memberCount; $index++) {
            $step = (float) $members[$index]['bounds']['y1']
                - (float) $members[$index - 1]['bounds']['y1'];
            if (abs($step) <= $verticalStepTolerance) {
                continue;
            }
            $verticalSigns[] = $step < 0.0 ? -1 : 1;
        }
        $verticalDirectionChanges = 0;
        for ($index = 1, $count = count($verticalSigns); $index < $count; $index++) {
            if ($verticalSigns[$index] !== $verticalSigns[$index - 1]) {
                $verticalDirectionChanges++;
            }
        }
        if ($verticalDirectionChanges < 2) {
            return null;
        }

        $x1 = min(array_column(array_column($members, 'bounds'), 'x1'));
        $y1 = min(array_column(array_column($members, 'bounds'), 'y1'));
        $x2 = max(array_column(array_column($members, 'bounds'), 'x2'));
        $y2 = max(array_column(array_column($members, 'bounds'), 'y2'));
        $horizontalSpan = $x2 - $x1;
        $verticalSpan = $y2 - $y1;
        if ($horizontalSpan < max(72.0, $medianHeight * 7.0)
            || $verticalSpan < max(80.0, $medianHeight * 8.0)) {
            return null;
        }

        $lastMember = $members[array_key_last($members)];
        $captionAnchors = [];
        $expectedGlobalIndex = $lastMember['sourceGlobalIndex'] + 1;
        for ($sourceIndex = $lastMember['sourceIndex'] + 1, $limit = min(
            count($lineItems),
            $lastMember['sourceIndex'] + 4
        ); $sourceIndex < $limit; $sourceIndex++, $expectedGlobalIndex++) {
            $item = $lineItems[$sourceIndex] ?? null;
            $geometry = is_array($item['sourceGeometry'] ?? null)
                ? $item['sourceGeometry']
                : null;
            $text = is_array($item) ? trim((string) ($item['text'] ?? '')) : '';
            $declaredGlobalIndex = is_array($item)
                ? ($item['sourcePdfGlobalSourceIndex'] ?? null)
                : null;
            $sourceGlobalIndex = $declaredGlobalIndex === null
                ? $sourceIndex
                : (is_int($declaredGlobalIndex) ? $declaredGlobalIndex : null);
            if (!is_array($item)
                || !$this->sourcePdfSourceItemHasExactGeometry($item)
                || $geometry === null
                || (int) ($item['page'] ?? 0) !== $lastMember['page']
                || (int) ($item['stream'] ?? 0) !== $lastMember['stream']
                || $sourceGlobalIndex !== $expectedGlobalIndex
                || !$this->lineLooksLikeCompletePdfCaption($text)) {
                break;
            }
            $bounds = $this->pdfSourceEvidenceBounds($geometry);
            $bounds = [
                'x1' => min($bounds['x1'], $bounds['x2']),
                'y1' => min($bounds['y1'], $bounds['y2']),
                'x2' => max($bounds['x1'], $bounds['x2']),
                'y2' => max($bounds['y1'], $bounds['y2']),
            ];
            $minimumClearance = max(2.0, $medianHeight * 0.25);
            $horizontalOverlap = min($x2, $bounds['x2']) - max($x1, $bounds['x1']);
            if ($bounds['y2'] > $y1 - $minimumClearance || $horizontalOverlap <= 0.0) {
                break;
            }
            $sourceOccurrenceId = is_string($item['id'] ?? null) ? $item['id'] : '';
            $projection = $this->pdfSourceOccurrenceComparableText($text);
            if ($sourceOccurrenceId === '' || $projection === '') {
                break;
            }
            $captionAnchors[] = [
                'sourceIndex' => $sourceIndex,
                'sourceGlobalIndex' => $sourceGlobalIndex,
                'sourceOccurrenceId' => $sourceOccurrenceId,
                'projectionDigest' => hash('sha256', $projection),
                'geometryDigest' => $this->sourcePdfExactGeometryProofDigest($geometry),
                'bounds' => $bounds,
            ];
        }
        if ($captionAnchors === []) {
            return null;
        }

        $proofMembers = array_map(
            static fn (array $member): array => [
                'sourceIndex' => $member['sourceIndex'],
                'sourceGlobalIndex' => $member['sourceGlobalIndex'],
                'sourceOccurrenceId' => $member['sourceOccurrenceId'],
                'projectionDigest' => $member['projectionDigest'],
                'geometryDigest' => $member['geometryDigest'],
                'bounds' => $member['bounds'],
            ],
            $members
        );
        $proof = [
            'version' => 1,
            'method' => 'exact-source-spatial-label-cluster-before-caption',
            'sourceSha256' => $this->sourceSha256,
            'page' => $lastMember['page'],
            'sourceStream' => $lastMember['stream'],
            'members' => $proofMembers,
            'captionAnchors' => $captionAnchors,
            'spatialEvidence' => [
                'medianHeight' => round($medianHeight, 2),
                'horizontalSpan' => round($horizontalSpan, 2),
                'verticalSpan' => round($verticalSpan, 2),
                'verticalDirectionChanges' => $verticalDirectionChanges,
            ],
        ];
        $encoded = json_encode(
            $proof,
            JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_PRESERVE_ZERO_FRACTION
        );
        $proof['proofDigest'] = hash(
            'sha256',
            is_string($encoded) ? $encoded : serialize($proof)
        );

        return $proof;
    }

    /**
     * @param list<array<string,mixed>> $lineItems
     * @return list<array<string,mixed>>
     */
    private function sourcePdfExactNestedCautionCalloutProofs(array $lineItems): array
    {
        if (!$this->sourcePdfHasExactNestedCautionCalloutWindow($lineItems)) {
            return [];
        }

        return $this->invokePdfNestedCautionCalloutRepair(
            'sourcePdfExactNestedCautionCalloutProofs',
            [$lineItems]
        );
    }

    /**
     * A necessary, allocation-light window check keeps the uncommon detector
     * out of ordinary imports. Every accepted candidate has five adjacent
     * exact-geometry source occurrences: symbol, punctuation, compact
     * uppercase label, and at least two substantive prose rows.
     *
     * @param list<array<string,mixed>> $lineItems
     */
    private function sourcePdfHasExactNestedCautionCalloutWindow(array $lineItems): bool
    {
        if (preg_match('/^[a-f0-9]{64}$/D', $this->sourceSha256) !== 1
            || count($lineItems) < 5) {
            return false;
        }

        $isCompactUppercase = function (string $text): bool {
            $text = trim($this->normalizePdfTextEncoding($text));
            $wordCount = count($this->pdfLineWordTokens($text));

            return $this->length($text) >= 3
                && $this->length($text) <= 28
                && $wordCount >= 1
                && $wordCount <= 3
                && preg_match('/\p{L}/u', $text) === 1
                && preg_match('/\p{Ll}/u', $text) !== 1
                && preg_match('/^[\p{Lu}\p{Lt}\p{N}\h&\/-]+$/u', $text) === 1;
        };
        $isSubstantiveRow = function (string $text): bool {
            $text = trim($this->normalizePdfTextEncoding($text));
            $wordCount = count($this->pdfLineWordTokens($text));

            return $this->length($text) >= 18
                && $this->length($text) <= 200
                && $wordCount >= 4
                && $wordCount <= 40
                && preg_match('/\p{Ll}/u', $text) === 1
                && !$this->lineHasPdfListBlockEvidence($text)
                && !$this->lineLooksLikeUrlOnly($text)
                && !$this->pdfLineStartsWithSemanticPrefix($text);
        };

        for ($sourceIndex = 0, $count = count($lineItems);
            $sourceIndex + 4 < $count;
            $sourceIndex++) {
            $window = array_slice($lineItems, $sourceIndex, 5);
            if (count($window) !== 5
                || array_filter($window, 'is_array') !== $window) {
                continue;
            }

            $page = (int) ($window[0]['page'] ?? 0);
            $stream = (int) ($window[0]['stream'] ?? 0);
            $globalStart = $window[0]['sourcePdfGlobalSourceIndex'] ?? $sourceIndex;
            if ($page < 1 || $stream < 1 || !is_int($globalStart)) {
                continue;
            }

            foreach ($window as $offset => $item) {
                $itemIndex = $sourceIndex + $offset;
                $globalIndex = $item['sourcePdfGlobalSourceIndex'] ?? $itemIndex;
                $geometry = is_array($item['sourceGeometry'] ?? null)
                    ? $item['sourceGeometry']
                    : null;
                if (!is_string($item['id'] ?? null)
                    || $item['id'] === ''
                    || (int) ($item['page'] ?? 0) !== $page
                    || (int) ($item['stream'] ?? 0) !== $stream
                    || !is_int($globalIndex)
                    || $globalIndex !== $globalStart + $offset
                    || $geometry === null
                    || !$this->sourcePdfSourceItemHasExactGeometry($item)
                    || (int) ($geometry['page'] ?? 0) !== $page
                    || (int) ($geometry['stream'] ?? 0) !== $stream
                    || !in_array(
                        (string) ($geometry['orientation'] ?? ''),
                        ['', 'horizontal'],
                        true
                    )) {
                    continue 2;
                }
            }

            $symbol = trim((string) ($window[0]['text'] ?? ''));
            $punctuation = trim((string) ($window[1]['text'] ?? ''));
            $label = (string) ($window[2]['text'] ?? '');
            if (preg_match('/^\p{S}$/u', $symbol) !== 1
                || preg_match('/^\p{P}$/u', $punctuation) !== 1
                || !$isCompactUppercase($label)
                || !$isSubstantiveRow((string) ($window[3]['text'] ?? ''))
                || !$isSubstantiveRow((string) ($window[4]['text'] ?? ''))) {
                continue;
            }

            return true;
        }

        return false;
    }

    /**
     * Accept a detected proof downstream only when every declared member still
     * carries the detector-stamped proof and its exact semantic role.
     *
     * @param list<array<string,mixed>> $lineItems
     * @return list<array<string,mixed>>
     */
    private function sourcePdfStampedNestedCautionCalloutProofs(array $lineItems): array
    {
        $candidates = [];
        foreach ($lineItems as $item) {
            $role = $item['sourcePdfNestedCautionCalloutRole'] ?? null;
            $proof = $item['sourcePdfNestedCautionCalloutProof'] ?? null;
            $digest = is_array($proof) ? ($proof['proofDigest'] ?? null) : null;
            if (!in_array(
                $role,
                ['decorative-symbol', 'decorative-punctuation', 'label', 'prose-row'],
                true
            )
                || !is_string($digest)
                || preg_match('/^[a-f0-9]{64}$/D', $digest) !== 1
                || ($proof['sourceSha256'] ?? null) !== $this->sourceSha256) {
                continue;
            }
            $candidates[$digest] ??= $proof;
        }

        $proofs = [];
        foreach ($candidates as $digest => $proof) {
            $expectedRoles = [];
            foreach (is_array($proof['iconAtoms'] ?? null) ? $proof['iconAtoms'] : [] as $atom) {
                if (is_int($atom['sourceIndex'] ?? null)
                    && in_array(
                        $atom['role'] ?? null,
                        ['decorative-symbol', 'decorative-punctuation'],
                        true
                    )) {
                    $expectedRoles[$atom['sourceIndex']] = $atom['role'];
                }
            }
            $label = is_array($proof['label'] ?? null) ? $proof['label'] : [];
            if (is_int($label['sourceIndex'] ?? null)) {
                $expectedRoles[$label['sourceIndex']] = 'label';
            }
            foreach (is_array($proof['proseRows'] ?? null) ? $proof['proseRows'] : [] as $row) {
                if (is_int($row['sourceIndex'] ?? null)) {
                    $expectedRoles[$row['sourceIndex']] = 'prose-row';
                }
            }
            if (count($expectedRoles) < 5) {
                continue;
            }

            foreach ($expectedRoles as $sourceIndex => $role) {
                $item = $lineItems[$sourceIndex] ?? null;
                $stampedProof = is_array($item)
                    && is_array($item['sourcePdfNestedCautionCalloutProof'] ?? null)
                    ? $item['sourcePdfNestedCautionCalloutProof']
                    : null;
                if (!is_array($item)
                    || ($item['sourcePdfNestedCautionCalloutRole'] ?? null) !== $role
                    || $stampedProof !== $proof
                    || ($stampedProof['proofDigest'] ?? null) !== $digest) {
                    continue 2;
                }
            }
            $proofs[] = $proof;
        }

        return $proofs;
    }

    /** @param list<mixed> $arguments */
    private function invokePdfNestedCautionCalloutRepair(
        string $method,
        array $arguments
    ): mixed {
        return PdfNestedCautionCalloutRepair::invoke(
            $method,
            $arguments,
            $this->sourceSha256,
            $this->pdfSourceOccurrenceComparableText(...),
            $this->sourcePdfSourceItemHasExactGeometry(...),
            $this->pdfSourceEvidenceBounds(...),
            $this->sourcePdfExactGeometryProofDigest(...),
            $this->normalizePdfTextEncoding(...),
            $this->pdfLineWordTokens(...),
            $this->length(...),
            $this->lineHasPdfListBlockEvidence(...),
            $this->lineLooksLikeUrlOnly(...),
            $this->pdfLineStartsWithSemanticPrefix(...),
            $this->median(...),
            $this->sourcePdfSignedProofDigestMatches(...),
            $this->pdfPositionedExactSourceRanges(...),
            $this->sourcePdfStampedNestedCautionCalloutProofs(...)
        );
    }

    /**
     * Derive editable layout-label roles from local geometry which is
     * incompatible with document-outline semantics: high-entropy spatial map
     * text, exact photo-credit companions, and a same-size footer tagline
     * continuing the final prose baseline. Spelling never identifies a role.
     *
     * @param list<array<string,mixed>> $lineItems
     * @param array<int,list<array{index:int,stream:int,text:string,bounds:array<string,float>,orientation:string}>> $recordsByPage
     * @param array<int,array{x1:float,y1:float,x2:float,y2:float,width:float,height:float,medianHeight:float}> $pageEvidence
     * @return array<int,true>
     */
    private function sourcePdfOutlineIneligibleLayoutLabelIndexes(
        array $lineItems,
        array $recordsByPage,
        array $pageEvidence
    ): array {
        $indexes = [];

        foreach ($recordsByPage as $page => $records) {
            $evidence = $pageEvidence[$page] ?? null;
            if (!is_array($evidence)) {
                continue;
            }
            $nonHorizontal = array_values(array_filter(
                $records,
                static fn (array $record): bool =>
                    ($record['orientation'] ?? '') !== ''
                        && ($record['orientation'] ?? '') !== 'horizontal'
            ));
            $orientationBuckets = [];
            $shortFragments = 0;
            foreach ($nonHorizontal as $record) {
                $orientationBuckets[(string) $record['orientation']] = true;
                $letters = preg_replace('/[^\p{L}\p{M}]+/u', '', $record['text']) ?? '';
                if ($this->length($letters) <= 2) {
                    $shortFragments++;
                }
            }
            $spatialPage = count($nonHorizontal) >= 8
                && count($orientationBuckets) >= 6
                // A sustained map-label layer repeats many glyphs along the
                // same orientations and is emitted as one editable region.
                // Individual outline exclusions apply only to a compact,
                // high-entropy spatial tail with mostly unique directions.
                && count($orientationBuckets) / count($nonHorizontal) >= 0.70
                && $shortFragments >= 6
                && $shortFragments / count($nonHorizontal) >= 0.50;
            if ($spatialPage) {
                foreach ($records as $record) {
                    if (!$this->repairedLineLooksLikeSectionLabel($record['text'])) {
                        continue;
                    }
                    $height = max(
                        0.0,
                        (float) $record['bounds']['y2'] - (float) $record['bounds']['y1']
                    );
                    $centerY = (
                        (float) $record['bounds']['y1'] + (float) $record['bounds']['y2']
                    ) / 2.0;
                    $nonHorizontalLabel = ($record['orientation'] ?? '') !== ''
                        && ($record['orientation'] ?? '') !== 'horizontal';
                    $smallExtremeEdgeLabel = ($record['orientation'] ?? '') === 'horizontal'
                        && $height <= $evidence['medianHeight'] * 1.10
                        && $centerY <= $evidence['y1'] + $evidence['height'] * 0.03;
                    if ($nonHorizontalLabel || $smallExtremeEdgeLabel) {
                        $indexes[$record['index']] = true;
                    }
                }
            }
        }

        return $indexes;
    }

    /**
     * @param list<array{index:int,stream:int,text:string,bounds:array<string,float>,orientation:string}> $records
     * @return array{x1:float,y1:float,x2:float,y2:float,width:float,height:float,medianHeight:float}|null
     */
    private function sourcePdfLayoutLabelPageEvidence(array $records): ?array
    {
        if (count($records) < 4) {
            return null;
        }
        $x1s = $x2s = $y1s = $y2s = $heights = [];
        foreach ($records as $record) {
            $bounds = $record['bounds'];
            $x1s[] = (float) $bounds['x1'];
            $x2s[] = (float) $bounds['x2'];
            $y1s[] = (float) $bounds['y1'];
            $y2s[] = (float) $bounds['y2'];
            $height = (float) $bounds['y2'] - (float) $bounds['y1'];
            if ($height > 0.0) {
                $heights[] = $height;
            }
        }
        if ($heights === []) {
            return null;
        }
        $x1 = $this->pdfRobustQuantile($x1s, 0.02);
        $x2 = $this->pdfRobustQuantile($x2s, 0.98);
        $y1 = $this->pdfRobustQuantile($y1s, 0.02);
        $y2 = $this->pdfRobustQuantile($y2s, 0.98);
        $width = $x2 - $x1;
        $height = $y2 - $y1;
        if ($width <= 0.0 || $height <= 0.0) {
            return null;
        }
        $rhythmHeights = array_values(array_filter(
            $heights,
            static fn (float $lineHeight): bool => $lineHeight <= $height * 0.08
        ));
        if ($rhythmHeights === []) {
            $rhythmHeights = $heights;
        }

        return [
            'x1' => $x1,
            'y1' => $y1,
            'x2' => $x2,
            'y2' => $y2,
            'width' => $width,
            'height' => $height,
            'medianHeight' => max(1.0, $this->median($rhythmHeights)),
        ];
    }

    /**
     * @param list<float> $values
     */
    private function pdfRobustQuantile(array $values, float $quantile): float
    {
        sort($values, SORT_NUMERIC);
        if ($values === []) {
            return 0.0;
        }
        $index = (int) round(max(0.0, min(1.0, $quantile)) * (count($values) - 1));

        return (float) $values[$index];
    }

    /**
     * @param list<array{index:int,stream:int,text:string,bounds:array<string,float>,orientation:string}> $records
     * @param array{x1:float,y1:float,x2:float,y2:float,width:float,height:float,medianHeight:float} $evidence
     */
    private function sourcePdfPageHasFormLabelLane(array $records, array $evidence): bool
    {
        $candidates = [];
        foreach ($records as $record) {
            $text = $record['text'];
            $bounds = $record['bounds'];
            $letters = preg_replace('/[^\p{L}\p{M}]+/u', '', $text) ?? '';
            $height = max(0.0, (float) $bounds['y2'] - (float) $bounds['y1']);
            $width = max(0.0, (float) $bounds['x2'] - (float) $bounds['x1']);
            if ($this->length($letters) < 3
                || $this->length($text) > 42
                || count($this->pdfLineWordTokens($text)) > 5
                || preg_match('/[.!?;]\s*$/u', $text) === 1
                || !in_array($record['orientation'], ['', 'horizontal'], true)
                || (float) $bounds['x1'] > $evidence['x1'] + $evidence['width'] * 0.18
                || $width > $evidence['width'] * 0.22
                || $height > $evidence['medianHeight'] * 1.75) {
                continue;
            }
            $candidates[] = $record;
        }
        if (count($candidates) < 5) {
            return false;
        }

        usort($candidates, static fn (array $left, array $right): int =>
            ((float) $right['bounds']['y1'] <=> (float) $left['bounds']['y1'])
                ?: ((float) $left['bounds']['x1'] <=> (float) $right['bounds']['x1'])
        );
        $parent = array_keys($candidates);
        $find = static function (int $index) use (&$find, &$parent): int {
            if ($parent[$index] !== $index) {
                $parent[$index] = $find($parent[$index]);
            }

            return $parent[$index];
        };
        $union = static function (int $left, int $right) use (&$parent, $find): void {
            $leftRoot = $find($left);
            $rightRoot = $find($right);
            if ($leftRoot !== $rightRoot) {
                $parent[$rightRoot] = $leftRoot;
            }
        };
        foreach ($candidates as $leftIndex => $left) {
            $leftCenterY = ((float) $left['bounds']['y1'] + (float) $left['bounds']['y2']) / 2.0;
            foreach (array_slice($candidates, $leftIndex + 1, null, true) as $rightIndex => $right) {
                $rightCenterY = ((float) $right['bounds']['y1'] + (float) $right['bounds']['y2']) / 2.0;
                $verticalStep = abs($leftCenterY - $rightCenterY);
                if ($verticalStep > $evidence['medianHeight'] * 1.65) {
                    continue;
                }
                if ($verticalStep < $evidence['medianHeight'] * 0.35
                    || abs((float) $left['bounds']['x1'] - (float) $right['bounds']['x1'])
                        > max(5.0, $evidence['medianHeight'] * 0.65)) {
                    continue;
                }
                $union((int) $leftIndex, (int) $rightIndex);
            }
        }

        $clusters = [];
        foreach ($candidates as $index => $candidate) {
            $clusters[$find((int) $index)][] = $candidate;
        }
        $alignedClusters = 0;
        $alignedMembers = 0;
        $largestAlignedCluster = 0;
        foreach ($clusters as $cluster) {
            if (count($cluster) < 2) {
                continue;
            }
            $clusterX2 = max(array_map(static fn (array $record): float => (float) $record['bounds']['x2'], $cluster));
            $clusterY1 = min(array_map(static fn (array $record): float => (float) $record['bounds']['y1'], $cluster));
            $clusterY2 = max(array_map(static fn (array $record): float => (float) $record['bounds']['y2'], $cluster));
            $hasRightBody = false;
            foreach ($records as $record) {
                $text = $record['text'];
                $bounds = $record['bounds'];
                if ($this->length($text) < 24
                    || count($this->pdfLineWordTokens($text)) < 4
                    || (float) $bounds['x1'] < $clusterX2 + max(8.0, $evidence['medianHeight'] * 0.65)
                    || (float) $bounds['x1'] < $evidence['x1'] + $evidence['width'] * 0.12
                    || (float) $bounds['y2'] < $clusterY1 - $evidence['medianHeight'] * 0.55
                    || (float) $bounds['y1'] > $clusterY2 + $evidence['medianHeight'] * 0.55) {
                    continue;
                }
                $hasRightBody = true;
                break;
            }
            if ($hasRightBody) {
                $alignedClusters++;
                $alignedMembers += count($cluster);
                $largestAlignedCluster = max($largestAlignedCluster, count($cluster));
            }
        }

        // Two-line brochure side-headings can also recur beside prose. A
        // form lane needs substantially more independent field-entry rows,
        // including at least one label that spans three or more visual lines.
        return $alignedClusters >= 3
            && $alignedMembers >= 7
            && $largestAlignedCluster >= 3;
    }

    private function pdfSourceOccurrenceComparableText(string $text): string
    {
        $text = $this->normalizePdfTextEncoding($text);
        if (class_exists('Normalizer')) {
            $normalized = \Normalizer::normalize($text, \Normalizer::FORM_C);
            if (is_string($normalized)) {
                $text = $normalized;
            }
        }

        return preg_replace('/[\s\p{Cc}\p{Cf}]+/u', '', $text) ?? '';
    }

    /**
     * Keep the overwhelmingly common singleton proof inside one run bucket.
     * Three scalar hash entries force compact glyph records onto PHP's next
     * hash-table tier; a fixed-width internal value preserves the same three
     * unsigned offsets until positionedRun() emits the established public
     * scalar shape. Crossing runs remain the ordinary associative range list.
     *
     * @param array<string,mixed> $run
     */
    private function appendPdfPositionedExactSourceRange(
        array &$run,
        int $sourceIndex,
        int $sourceStart,
        int $sourceEnd
    ): void {
        if ($sourceIndex < 0
            || $sourceStart < 0
            || $sourceEnd <= $sourceStart
            || $sourceIndex > 0xffffffff
            || $sourceStart > 0xffffffff
            || $sourceEnd > 0xffffffff) {
            return;
        }
        $declaresRanges = array_key_exists('sourcePdfExactSourceRanges', $run)
            || isset(
                $run['sourcePdfExactSourceIndex'],
                $run['sourcePdfExactSourceStart'],
                $run['sourcePdfExactSourceEnd']
            );
        if (!$declaresRanges) {
            $run['sourcePdfExactSourceRanges'] = pack(
                'N3',
                $sourceIndex,
                $sourceStart,
                $sourceEnd
            );

            return;
        }

        $existing = $this->pdfPositionedExactSourceRanges($run);
        if ($existing === []) {
            return;
        }
        $run['sourcePdfExactSourceRanges'] = [
            ...$existing,
            [
                'sourceIndex' => $sourceIndex,
                'sourceStart' => $sourceStart,
                'sourceEnd' => $sourceEnd,
            ],
        ];
        unset(
            $run['sourcePdfExactSourceIndex'],
            $run['sourcePdfExactSourceStart'],
            $run['sourcePdfExactSourceEnd']
        );
    }

    /** @return array{sourceIndex:int,sourceStart:int,sourceEnd:int}|null */
    private function unpackPdfPositionedExactSourceRange(string $packed): ?array
    {
        if (strlen($packed) !== 12) {
            return null;
        }
        $range = unpack('NsourceIndex/NsourceStart/NsourceEnd', $packed);
        if (!is_array($range)
            || !is_int($range['sourceIndex'] ?? null)
            || !is_int($range['sourceStart'] ?? null)
            || !is_int($range['sourceEnd'] ?? null)
            || $range['sourceEnd'] <= $range['sourceStart']) {
            return null;
        }

        return [
            'sourceIndex' => $range['sourceIndex'],
            'sourceStart' => $range['sourceStart'],
            'sourceEnd' => $range['sourceEnd'],
        ];
    }

    /**
     * Return exact occurrence-local significant-byte ranges retained from the
     * page/stream character alignment. A packed singleton is used on ordinary
     * raw runs; reconstructed visual lines carry the equivalent scalar or
     * ordered-list shape.
     *
     * @param array<string,mixed> $item
     * @return list<array{sourceIndex:int,sourceStart:int,sourceEnd:int}>
     */
    private function pdfPositionedExactSourceRanges(array $item): array
    {
        $declaredRanges = $item['sourcePdfExactSourceRanges'] ?? null;
        if (is_string($declaredRanges)) {
            $packedRange = $this->unpackPdfPositionedExactSourceRange($declaredRanges);
            $candidates = $packedRange === null ? [] : [$packedRange];
        } else {
            $candidates = is_array($declaredRanges)
                ? $declaredRanges
                : (isset(
                $item['sourcePdfExactSourceIndex'],
                $item['sourcePdfExactSourceStart'],
                $item['sourcePdfExactSourceEnd']
            ) ? [[
                'sourceIndex' => $item['sourcePdfExactSourceIndex'],
                'sourceStart' => $item['sourcePdfExactSourceStart'],
                'sourceEnd' => $item['sourcePdfExactSourceEnd'],
            ]] : []);
        }
        $ranges = [];
        foreach ($candidates as $candidate) {
            if (!is_array($candidate)
                || !is_int($candidate['sourceIndex'] ?? null)
                || !is_int($candidate['sourceStart'] ?? null)
                || !is_int($candidate['sourceEnd'] ?? null)
                || $candidate['sourceIndex'] < 0
                || $candidate['sourceStart'] < 0
                || $candidate['sourceEnd'] <= $candidate['sourceStart']) {
                return [];
            }
            $ranges[] = [
                'sourceIndex' => $candidate['sourceIndex'],
                'sourceStart' => $candidate['sourceStart'],
                'sourceEnd' => $candidate['sourceEnd'],
            ];
        }

        return $ranges;
    }

    /**
     * @param list<array<string,mixed>> $items
     * @return list<array{sourceIndex:int,sourceStart:int,sourceEnd:int}>
     */
    private function pdfPositionedExactSourceRangesForItems(array $items): array
    {
        $ranges = [];
        foreach ($items as $item) {
            foreach ($this->pdfPositionedExactSourceRanges($item) as $range) {
                $lastIndex = array_key_last($ranges);
                if ($lastIndex !== null
                    && $ranges[$lastIndex]['sourceIndex'] === $range['sourceIndex']
                    && $ranges[$lastIndex]['sourceEnd'] === $range['sourceStart']) {
                    $ranges[$lastIndex]['sourceEnd'] = $range['sourceEnd'];
                    continue;
                }
                $ranges[] = $range;
            }
        }

        return $ranges;
    }

    /** @param array<string, mixed> $run */
    private function pdfSourceProfileOrientation(array $run): string
    {
        if (is_string($run['direction'] ?? null) && $run['direction'] !== '') {
            return $run['direction'];
        }
        $rotation = ((int) round((float) ($run['rotation'] ?? 0.0)) % 360 + 360) % 360;

        return $rotation === 0 ? 'horizontal' : 'rotated-' . $rotation;
    }

    /**
     * Identify a duplicate period painted as its own full baseline before a
     * section heading. The source occurrence is an artifact only when the
     * immediately preceding exact line already ends in that period and four
     * consecutive occurrences prove the aligned prose/period/heading/body
     * stack.
     *
     * @param list<array<string,mixed>> $lineItems
     * @return array<string,array<string,mixed>> Evidence keyed by source id.
     */
    private function pdfDuplicateStandaloneTerminalPeriodEvidence(array $lineItems): array
    {
        $evidence = [];
        for ($index = 1, $count = count($lineItems) - 2; $index < $count; $index++) {
            $previous = $lineItems[$index - 1];
            $candidate = $lineItems[$index];
            $following = $lineItems[$index + 1];
            $followingBody = $lineItems[$index + 2];
            $normalized = [];
            foreach ([
                $index - 1 => $previous,
                $index => $candidate,
                $index + 1 => $following,
                $index + 2 => $followingBody,
            ] as $localIndex => $item) {
                $id = is_string($item['id'] ?? null) ? $item['id'] : '';
                $page = (int) ($item['page'] ?? 0);
                $stream = (int) ($item['stream'] ?? 0);
                $declaredGlobalIndex = $item['sourcePdfGlobalSourceIndex'] ?? null;
                $globalIndex = is_int($declaredGlobalIndex)
                    ? $declaredGlobalIndex
                    : $localIndex;
                $geometry = is_array($item['sourceGeometry'] ?? null)
                    ? $item['sourceGeometry']
                    : null;
                if ($id === ''
                    || $page < 1
                    || $stream < 1
                    || ($declaredGlobalIndex !== null
                        && (!is_int($declaredGlobalIndex)
                            || $declaredGlobalIndex !== $localIndex))
                    || ($item['sourceGeometryMethod'] ?? null)
                        !== 'exact-page-stream-character-offset'
                    || $geometry === null
                    || !$this->pdfSourceBoundsAreValid($geometry)
                    || (int) ($geometry['page'] ?? 0) !== $page
                    || (int) ($geometry['stream'] ?? 0) !== $stream
                    || ($geometry['orientation'] ?? null) !== 'horizontal') {
                    $normalized = [];
                    break;
                }
                $normalized[] = [
                    'id' => $id,
                    'page' => $page,
                    'stream' => $stream,
                    'globalIndex' => $globalIndex,
                    'text' => (string) ($item['text'] ?? ''),
                    'bounds' => $this->pdfSourceEvidenceBounds($geometry),
                ];
            }
            if (count($normalized) !== 4) {
                continue;
            }
            [$previousItem, $candidateItem, $followingItem, $followingBodyItem] = $normalized;
            if ($candidateItem['page'] !== $previousItem['page']
                || $followingItem['page'] !== $candidateItem['page']
                || $followingBodyItem['page'] !== $followingItem['page']
                || $candidateItem['stream'] !== $previousItem['stream']
                || $followingItem['stream'] !== $candidateItem['stream']
                || $followingBodyItem['stream'] !== $followingItem['stream']
                || $candidateItem['globalIndex'] !== $previousItem['globalIndex'] + 1
                || $followingItem['globalIndex'] !== $candidateItem['globalIndex'] + 1
                || $followingBodyItem['globalIndex'] !== $followingItem['globalIndex'] + 1
                || $this->pdfSourceOccurrenceComparableText($candidateItem['text']) !== '.'
                || preg_match('/(?<!\.)\.\s*$/u', $previousItem['text']) !== 1
                || !$this->repairedLineLooksLikeSectionLabel($followingItem['text'])
                || $this->repairedLineLooksLikeSectionLabel($followingBodyItem['text'])
                || preg_match('/^\s*\p{Lu}/u', $followingBodyItem['text']) !== 1
                || preg_match('/\p{Ll}/u', $followingBodyItem['text']) !== 1) {
                continue;
            }
            $previousWordCount = preg_match_all(
                '/[\p{L}\p{M}\p{N}]+/u',
                $previousItem['text']
            );
            $followingWordCount = preg_match_all(
                '/[\p{L}\p{M}\p{N}]+/u',
                $followingItem['text']
            );
            $followingBodyWordCount = preg_match_all(
                '/[\p{L}\p{M}\p{N}]+/u',
                $followingBodyItem['text']
            );
            if (!is_int($previousWordCount)
                || $previousWordCount < 5
                || !is_int($followingWordCount)
                || $followingWordCount < 2
                || !is_int($followingBodyWordCount)
                || $followingBodyWordCount < 5) {
                continue;
            }

            $previousBounds = $previousItem['bounds'];
            $candidateBounds = $candidateItem['bounds'];
            $followingBounds = $followingItem['bounds'];
            $followingBodyBounds = $followingBodyItem['bounds'];
            $heights = array_map(
                static fn (array $bounds): float => max(
                    0.0,
                    (float) $bounds['y2'] - (float) $bounds['y1']
                ),
                [$previousBounds, $candidateBounds, $followingBounds, $followingBodyBounds]
            );
            $minimumHeight = min($heights);
            $maximumHeight = max($heights);
            $geometryTolerance = max(0.5, $minimumHeight * 0.08);
            $candidateWidth = (float) $candidateBounds['x2'] - (float) $candidateBounds['x1'];
            $previousWidth = (float) $previousBounds['x2'] - (float) $previousBounds['x1'];
            $followingWidth = (float) $followingBounds['x2'] - (float) $followingBounds['x1'];
            $followingBodyWidth = (float) $followingBodyBounds['x2']
                - (float) $followingBodyBounds['x1'];
            if ($minimumHeight <= 0.0
                || $maximumHeight - $minimumHeight > $geometryTolerance
                || abs((float) $previousBounds['x1'] - (float) $candidateBounds['x1'])
                    > $geometryTolerance
                || abs((float) $candidateBounds['x1'] - (float) $followingBounds['x1'])
                    > $geometryTolerance
                || abs((float) $followingBounds['x1'] - (float) $followingBodyBounds['x1'])
                    > $geometryTolerance
                || abs((float) $previousBounds['y1'] - (float) $candidateBounds['y2'])
                    > $geometryTolerance
                || abs((float) $candidateBounds['y1'] - (float) $followingBounds['y2'])
                    > $geometryTolerance
                || (float) $followingBounds['y1'] < (float) $followingBodyBounds['y2'] - $geometryTolerance
                || (float) $followingBounds['y1'] - (float) $followingBodyBounds['y2']
                    > $maximumHeight * 0.5
                || $candidateWidth <= 0.0
                || $candidateWidth > $maximumHeight * 1.2
                || $previousWidth < $maximumHeight * 4.0
                || $followingWidth < $maximumHeight * 4.0
                || $followingBodyWidth < $maximumHeight * 4.0) {
                continue;
            }

            $identity = [
                'version' => 1,
                'method' => 'exact-adjacent-duplicate-standalone-terminal-period',
                'sourceSha256' => $this->sourceSha256,
                'sourceOccurrenceId' => $candidateItem['id'],
                'sourceGlobalIndex' => $candidateItem['globalIndex'],
                'predecessorSourceOccurrenceId' => $previousItem['id'],
                'followingSourceOccurrenceId' => $followingItem['id'],
                'followingBodySourceOccurrenceId' => $followingBodyItem['id'],
                'sourceBounds' => $candidateBounds,
                'predecessorBounds' => $previousBounds,
                'followingBounds' => $followingBounds,
                'followingBodyBounds' => $followingBodyBounds,
                'punctuationDigest' => hash('sha256', '.'),
                'predecessorProjectionDigest' => hash(
                    'sha256',
                    $this->pdfSourceOccurrenceComparableText($previousItem['text'])
                ),
                'followingProjectionDigest' => hash(
                    'sha256',
                    $this->pdfSourceOccurrenceComparableText($followingItem['text'])
                ),
                'followingBodyProjectionDigest' => hash(
                    'sha256',
                    $this->pdfSourceOccurrenceComparableText($followingBodyItem['text'])
                ),
            ];
            $encoded = json_encode(
                $identity,
                JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_PRESERVE_ZERO_FRACTION
            );
            $evidence[$candidateItem['id']] = $identity + [
                'proofDigest' => hash(
                    'sha256',
                    is_string($encoded) ? $encoded : serialize($identity)
                ),
            ];
        }

        return $evidence;
    }

    /**
     * Identify only recurring, oversized brace pairs which geometrically
     * enclose ordinary text. A brace-only source record is not enough: code,
     * math, and literal examples can legitimately place braces on their own
     * lines. Requiring exact occurrence bboxes, a balanced visual pair, at
     * least two enclosed text lines, and a second similarly sized pair in the
     * same page/stream makes this a layout fact rather than a punctuation
     * guess.
     *
     * @param list<array<string,mixed>> $lineItems
     * @return array<string,array<string,mixed>> Evidence keyed by source id.
     */
    private function pdfDecorativeBracePairEvidence(array $lineItems): array
    {
        $braceItems = [];
        $textItems = [];
        foreach ($lineItems as $item) {
            $id = is_string($item['id'] ?? null) ? $item['id'] : '';
            $text = is_string($item['text'] ?? null) ? $item['text'] : '';
            $geometry = is_array($item['sourceGeometry'] ?? null)
                && $this->pdfSourceBoundsAreValid($item['sourceGeometry'])
                ? $this->pdfSourceEvidenceBounds($item['sourceGeometry'])
                : null;
            if ($id === ''
                || $geometry === null
                || ($item['sourceGeometryMethod'] ?? null) !== 'exact-page-stream-character-offset') {
                continue;
            }
            $compact = preg_replace('/\s+/u', '', $text) ?? '';
            $normalized = [
                'id' => $id,
                'page' => max(1, (int) ($item['page'] ?? 1)),
                'stream' => max(1, (int) ($item['stream'] ?? 1)),
                'text' => $text,
                'compact' => $compact,
                'bounds' => $geometry,
            ];
            if (in_array($compact, ['{}', '{', '}'], true)) {
                $braceItems[$id] = $normalized;
                continue;
            }
            if (preg_match('/[\p{L}\p{N}]/u', $text) === 1) {
                $textItems[] = $normalized;
            }
        }
        if ($braceItems === []) {
            return [];
        }

        $pairs = [];
        foreach ($braceItems as $item) {
            if ($item['compact'] !== '{}') {
                continue;
            }
            $pairs[] = [
                'memberIds' => [$item['id']],
                'page' => $item['page'],
                'stream' => $item['stream'],
                'bounds' => $item['bounds'],
                'sourceShape' => 'balanced-single-occurrence',
            ];
        }

        $usedClosers = [];
        foreach ($braceItems as $open) {
            if ($open['compact'] !== '{') {
                continue;
            }
            $openBounds = $open['bounds'];
            $openHeight = max(1.0, (float) $openBounds['y2'] - (float) $openBounds['y1']);
            $best = null;
            foreach ($braceItems as $close) {
                if ($close['compact'] !== '}'
                    || isset($usedClosers[$close['id']])
                    || $close['page'] !== $open['page']
                    || $close['stream'] !== $open['stream']) {
                    continue;
                }
                $closeBounds = $close['bounds'];
                $closeHeight = max(1.0, (float) $closeBounds['y2'] - (float) $closeBounds['y1']);
                $heightTolerance = max(2.0, max($openHeight, $closeHeight) * 0.06);
                if ((float) $closeBounds['x1'] <= (float) $openBounds['x1']
                    || abs((float) $openBounds['y1'] - (float) $closeBounds['y1']) > $heightTolerance
                    || abs((float) $openBounds['y2'] - (float) $closeBounds['y2']) > $heightTolerance
                    || abs($openHeight - $closeHeight) > $heightTolerance) {
                    continue;
                }
                $score = abs((float) $openBounds['y1'] - (float) $closeBounds['y1'])
                    + abs((float) $openBounds['y2'] - (float) $closeBounds['y2'])
                    + max(0.0, (float) $closeBounds['x1'] - (float) $openBounds['x2']) / 1000.0;
                if ($best === null || $score < $best['score']) {
                    $best = ['item' => $close, 'score' => $score];
                }
            }
            if ($best === null) {
                continue;
            }
            $close = $best['item'];
            $usedClosers[$close['id']] = true;
            $pairs[] = [
                'memberIds' => [$open['id'], $close['id']],
                'page' => $open['page'],
                'stream' => $open['stream'],
                'bounds' => [
                    'x1' => min((float) $openBounds['x1'], (float) $close['bounds']['x1']),
                    'y1' => min((float) $openBounds['y1'], (float) $close['bounds']['y1']),
                    'x2' => max((float) $openBounds['x2'], (float) $close['bounds']['x2']),
                    'y2' => max((float) $openBounds['y2'], (float) $close['bounds']['y2']),
                ],
                'sourceShape' => 'matched-single-brace-occurrences',
            ];
        }

        $provenPairs = [];
        foreach ($pairs as $pair) {
            $bounds = $pair['bounds'];
            $width = max(1.0, (float) $bounds['x2'] - (float) $bounds['x1']);
            $height = max(1.0, (float) $bounds['y2'] - (float) $bounds['y1']);
            if ($height < 36.0 || $width < $height * 1.35) {
                continue;
            }
            $inset = min(8.0, $width * 0.03);
            $enclosedIds = [];
            foreach ($textItems as $textItem) {
                if ($textItem['page'] !== $pair['page'] || $textItem['stream'] !== $pair['stream']) {
                    continue;
                }
                $textBounds = $textItem['bounds'];
                $textHeight = max(1.0, (float) $textBounds['y2'] - (float) $textBounds['y1']);
                $centerY = ((float) $textBounds['y1'] + (float) $textBounds['y2']) / 2.0;
                if ($height < $textHeight * 2.5
                    || (float) $textBounds['x1'] < (float) $bounds['x1'] + $inset
                    || (float) $textBounds['x2'] > (float) $bounds['x2'] - $inset
                    || $centerY < (float) $bounds['y1']
                    || $centerY > (float) $bounds['y2']) {
                    continue;
                }
                $enclosedIds[] = $textItem['id'];
            }
            if (count($enclosedIds) < 2) {
                continue;
            }
            $pair['width'] = $width;
            $pair['height'] = $height;
            $pair['enclosedOccurrenceIds'] = $enclosedIds;
            $provenPairs[] = $pair;
        }

        $evidence = [];
        foreach ($provenPairs as $pairIndex => $pair) {
            $recurringPairIndexes = [];
            foreach ($provenPairs as $candidateIndex => $candidate) {
                if ($candidate['page'] !== $pair['page'] || $candidate['stream'] !== $pair['stream']) {
                    continue;
                }
                if (abs((float) $candidate['height'] - (float) $pair['height']) > max(3.0, (float) $pair['height'] * 0.10)
                    || abs((float) $candidate['width'] - (float) $pair['width']) > max(12.0, (float) $pair['width'] * 0.20)) {
                    continue;
                }
                if ($candidateIndex !== $pairIndex) {
                    $pairBounds = $pair['bounds'];
                    $candidateBounds = $candidate['bounds'];
                    $centerDelta = max(
                        abs(
                            ((float) $pairBounds['x1'] + (float) $pairBounds['x2']) / 2.0
                                - ((float) $candidateBounds['x1'] + (float) $candidateBounds['x2']) / 2.0
                        ),
                        abs(
                            ((float) $pairBounds['y1'] + (float) $pairBounds['y2']) / 2.0
                                - ((float) $candidateBounds['y1'] + (float) $candidateBounds['y2']) / 2.0
                        )
                    );
                    if ($centerDelta < max(12.0, min((float) $pair['width'], (float) $pair['height']) * 0.25)) {
                        // Duplicate text/paint layers at one location do not
                        // prove that this visual convention recurs.
                        continue;
                    }
                }
                $recurringPairIndexes[] = $candidateIndex;
            }
            if (count($recurringPairIndexes) < 2) {
                continue;
            }
            $identity = [
                'page' => $pair['page'],
                'stream' => $pair['stream'],
                'memberIds' => $pair['memberIds'],
                'bounds' => $pair['bounds'],
                'enclosedOccurrenceIds' => $pair['enclosedOccurrenceIds'],
            ];
            $encoded = json_encode(
                $identity,
                JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_PRESERVE_ZERO_FRACTION
            );
            $pairEvidence = [
                'method' => 'exact-recurring-oversized-brace-pair-enclosing-text',
                'sourceShape' => $pair['sourceShape'],
                'pairDigest' => hash('sha256', is_string($encoded) ? $encoded : serialize($identity)),
                'pairBounds' => $pair['bounds'],
                'pairWidth' => $pair['width'],
                'pairHeight' => $pair['height'],
                'enclosedOccurrenceIds' => $pair['enclosedOccurrenceIds'],
                'enclosedOccurrenceCount' => count($pair['enclosedOccurrenceIds']),
                'recurringPairCount' => count($recurringPairIndexes),
            ];
            foreach ($pair['memberIds'] as $memberId) {
                $evidence[$memberId] = $pairEvidence + [
                    'sourceBounds' => $braceItems[$memberId]['bounds'],
                ];
            }
        }

        return $evidence;
    }

    /**
     * Bind a display-token insertion back to one exact consecutive source
     * sequence. The insertion must occur at an occurrence boundary and the
     * repaired projection must be present on the proved output page, so a
     * signed visual repair cannot authorize an unrelated source mutation.
     *
     * @param list<array<string,mixed>> $lineItems
     * @param list<AstNode> $blocks
     * @param array<int,array{start:int,end:int,projection:string,leafEnds:list<int>}> $finalOutputPageProofs
     * @return array<string,array<string,mixed>>
     */
    private function positionedPdfDisplayTokenRepairDispositions(
        array $lineItems,
        array $blocks,
        array $finalOutputPageProofs
    ): array {
        if ($this->positionedPdfDisplayTokenRepairProofs === []) {
            return [];
        }
        $outputProofCounts = [];
        $visit = function (array $nodes) use (&$visit, &$outputProofCounts): void {
            foreach ($nodes as $node) {
                $proof = $node->attr('sourcePdfDisplayTokenRepairProof');
                if (is_array($proof)
                    && is_string($proof['proofDigest'] ?? null)
                    && is_string($proof['repairedText'] ?? null)
                    && hash_equals(
                        (string) $node->attr('text', ''),
                        $proof['repairedText']
                    )) {
                    $outputProofCounts[$proof['proofDigest']] =
                        ($outputProofCounts[$proof['proofDigest']] ?? 0) + 1;
                }
                if ($node->children() !== []) {
                    $visit($node->children());
                }
            }
        };
        $visit($blocks);

        $itemsByPage = [];
        foreach ($lineItems as $index => $item) {
            $page = max(1, (int) ($item['page'] ?? 1));
            $itemsByPage[$page][] = ['index' => $index, 'item' => $item];
        }

        $dispositions = [];
        foreach ($this->positionedPdfDisplayTokenRepairProofs as $proof) {
            if (!$this->positionedPdfDisplayTokenRepairProofIsValid($proof)
                || ($outputProofCounts[$proof['proofDigest']] ?? 0) !== 1) {
                continue;
            }
            $page = (int) $proof['page'];
            $sourceText = (string) $proof['sourceText'];
            $repairedText = (string) $proof['repairedText'];
            $sourceProjection = $this->pdfSourceOccurrenceComparableText($sourceText);
            $repairedProjection = $this->pdfSourceOccurrenceComparableText($repairedText);
            $pageOutputProof = $finalOutputPageProofs[$page] ?? null;
            if ($sourceProjection === ''
                || $repairedProjection === ''
                || !is_array($pageOutputProof)
                || !is_string($pageOutputProof['projection'] ?? null)
                || substr_count($pageOutputProof['projection'], $repairedProjection) !== 1) {
                continue;
            }

            $pageItems = $itemsByPage[$page] ?? [];
            $matches = [];
            foreach ($pageItems as $start => $record) {
                $projection = '';
                $stream = null;
                $sequence = [];
                for ($index = $start; $index < count($pageItems); $index++) {
                    $item = $pageItems[$index]['item'];
                    $itemStream = is_numeric($item['stream'] ?? null)
                        ? (int) $item['stream']
                        : null;
                    if ($stream !== null && $itemStream !== null && $itemStream !== $stream) {
                        break;
                    }
                    $stream ??= $itemStream;
                    $part = $this->pdfSourceOccurrenceComparableText(
                        (string) ($item['text'] ?? '')
                    );
                    if ($part === '') {
                        continue;
                    }
                    $projection .= $part;
                    $sequence[] = $pageItems[$index];
                    if (strlen($projection) >= strlen($sourceProjection)) {
                        if (hash_equals($sourceProjection, $projection)) {
                            $matches[] = $sequence;
                        }
                        break;
                    }
                }
            }
            if (count($matches) !== 1) {
                continue;
            }

            $prefix = $this->pdfSourceOccurrenceComparableText(substr(
                $sourceText,
                0,
                (int) $proof['insertionOffset']
            ));
            $cumulative = '';
            $target = null;
            foreach ($matches[0] as $record) {
                if (hash_equals($prefix, $cumulative)) {
                    $target = $record;
                    break;
                }
                $cumulative .= $this->pdfSourceOccurrenceComparableText(
                    (string) ($record['item']['text'] ?? '')
                );
            }
            $targetItem = is_array($target['item'] ?? null) ? $target['item'] : null;
            $targetId = is_array($targetItem) && is_string($targetItem['id'] ?? null)
                ? $targetItem['id']
                : '';
            if ($targetId === '' || isset($dispositions[$targetId])) {
                continue;
            }
            $targetProjection = (string) $proof['insertedText']
                . (string) ($targetItem['text'] ?? '');
            $projectedSequence = '';
            foreach ($matches[0] as $record) {
                $projectedSequence .= $this->pdfSourceOccurrenceComparableText(
                    $record['index'] === $target['index']
                        ? $targetProjection
                        : (string) ($record['item']['text'] ?? '')
                );
            }
            if (!hash_equals($repairedProjection, $projectedSequence)) {
                continue;
            }
            $sourceIds = array_values(array_filter(array_map(
                static fn (array $record): string => is_string($record['item']['id'] ?? null)
                    ? $record['item']['id']
                    : '',
                $matches[0]
            )));
            if (count($sourceIds) !== count($matches[0])) {
                continue;
            }
            $dispositions[$targetId] = [
                'disposition' => 'boundary-repair',
                'reason' => 'One accepted same-font display heading supplies the unique missing leading title glyph at an exact source-occurrence boundary.',
                'evidence' => $proof + [
                    'sourceOccurrenceIds' => $sourceIds,
                    'targetSourceOccurrenceId' => $targetId,
                    'outputPageProjectionDigest' => hash('sha256', $pageOutputProof['projection']),
                ],
                'textProjection' => $targetProjection,
                'allowOrderChange' => false,
            ];
        }

        return $dispositions;
    }

    /** @param array<string,mixed> $proof */
    private function positionedPdfDisplayTokenRepairProofIsValid(array $proof): bool
    {
        $digest = is_string($proof['proofDigest'] ?? null) ? $proof['proofDigest'] : '';
        $unsigned = $proof;
        unset($unsigned['proofDigest']);
        $encoded = json_encode(
            $unsigned,
            JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_PRESERVE_ZERO_FRACTION
        );
        $sourceText = is_string($proof['sourceText'] ?? null) ? $proof['sourceText'] : '';
        $repairedText = is_string($proof['repairedText'] ?? null) ? $proof['repairedText'] : '';
        $insertedText = is_string($proof['insertedText'] ?? null) ? $proof['insertedText'] : '';
        $offset = is_int($proof['insertionOffset'] ?? null) ? $proof['insertionOffset'] : -1;

        return ($proof['version'] ?? null) === 1
            && ($proof['role'] ?? null) === 'display-heading-leading-token-repair'
            && is_string($proof['sourceSha256'] ?? null)
            && hash_equals($this->sourceSha256, $proof['sourceSha256'])
            && is_int($proof['page'] ?? null)
            && $proof['page'] >= 1
            && is_int($proof['supportPage'] ?? null)
            && $proof['supportPage'] >= 1
            && $proof['supportPage'] !== $proof['page']
            && $sourceText !== ''
            && $repairedText !== ''
            && $insertedText !== ''
            && $this->length($insertedText) === 1
            && $offset >= 0
            && $offset <= strlen($sourceText)
            && hash_equals(
                $repairedText,
                substr($sourceText, 0, $offset)
                    . $insertedText
                    . substr($sourceText, $offset)
            )
            && ($proof['sourceTextDigest'] ?? null) === hash('sha256', $sourceText)
            && ($proof['repairedTextDigest'] ?? null) === hash('sha256', $repairedText)
            && $digest !== ''
            && hash_equals(
                $digest,
                hash('sha256', is_string($encoded) ? $encoded : serialize($unsigned))
            );
    }

    /**
     * Admit one missing mailbox delimiter only when the semantic repair kept
     * an exact whole-occurrence range and the resulting projection occurs
     * exactly once in the final AST. Duplicate receipts from repeated
     * compositor passes collapse; conflicting receipts fail closed.
     *
     * @param list<array<string,mixed>> $lineItems
     * @param list<AstNode> $blocks
     * @param array<string,array<string,mixed>> $dispositions
     * @return array<string,array<string,mixed>>
     */
    private function pdfDispositionsWithSemanticEmailDelimiterRepairs(
        array $lineItems,
        array $blocks,
        array $dispositions
    ): array {
        if ($this->pdfSemanticEmailDelimiterRepairProofCandidates === []
            || $blocks === []) {
            return $dispositions;
        }
        $finalProjection = $this->pdfSignificantProjectionFromBlocks($blocks);
        if ($finalProjection === '') {
            return $dispositions;
        }

        $candidatesBySourceIndex = [];
        foreach ($this->pdfSemanticEmailDelimiterRepairProofCandidates as $candidate) {
            $proofDigest = is_string($candidate['proofDigest'] ?? null)
                ? $candidate['proofDigest']
                : '';
            $payload = $candidate;
            unset($payload['proofDigest']);
            $sourceIndex = is_int($candidate['sourceIndex'] ?? null)
                ? $candidate['sourceIndex']
                : -1;
            if (($candidate['version'] ?? null) !== 1
                || ($candidate['method'] ?? null)
                    !== 'exact-semantic-email-delimiter-insertion'
                || ($candidate['sourceSha256'] ?? null) !== $this->sourceSha256
                || $sourceIndex < 0
                || $sourceIndex >= count($lineItems)
                || $proofDigest === ''
                || !hash_equals($proofDigest, hash('sha256', json_encode(
                    $payload,
                    JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE
                ) ?: ''))) {
                continue;
            }
            $coreIdentity = $candidate;
            unset($coreIdentity['proofDigest'], $coreIdentity['semanticProofDigest']);
            $coreDigest = hash('sha256', json_encode(
                $coreIdentity,
                JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE
            ) ?: '');
            $candidatesBySourceIndex[$sourceIndex][$coreDigest][] = $candidate;
        }

        foreach ($candidatesBySourceIndex as $sourceIndex => $candidatesByDigest) {
            if (count($candidatesByDigest) !== 1) {
                continue;
            }
            $candidateGroup = array_values($candidatesByDigest)[0];
            $candidate = $candidateGroup[0] ?? null;
            if (!is_array($candidate)) {
                continue;
            }
            $item = $lineItems[$sourceIndex] ?? null;
            if (!is_array($item)
                || !$this->sourcePdfSourceItemHasExactGeometry($item)
                || !is_array($candidate['exactSourceRanges'] ?? null)) {
                continue;
            }
            $sourceProjection = $this->pdfSourceOccurrenceComparableText(
                (string) ($item['text'] ?? '')
            );
            $ranges = array_values($candidate['exactSourceRanges']);
            usort($ranges, static fn (array $left, array $right): int =>
                ((int) ($left['sourceStart'] ?? -1)
                    <=> (int) ($right['sourceStart'] ?? -1))
                    ?: ((int) ($left['sourceEnd'] ?? -1)
                        <=> (int) ($right['sourceEnd'] ?? -1))
            );
            $cursor = 0;
            foreach ($ranges as $range) {
                if (!is_array($range)
                    || ($range['sourceIndex'] ?? null) !== $sourceIndex
                    || !is_int($range['sourceStart'] ?? null)
                    || !is_int($range['sourceEnd'] ?? null)
                    || $range['sourceStart'] !== $cursor
                    || $range['sourceEnd'] <= $cursor
                    || $range['sourceEnd'] > strlen($sourceProjection)) {
                    continue 2;
                }
                $cursor = $range['sourceEnd'];
            }
            $outputProjection = is_string($candidate['outputProjection'] ?? null)
                ? $candidate['outputProjection']
                : '';
            $outputText = is_string($candidate['outputText'] ?? null)
                ? $candidate['outputText']
                : '';
            $insertionOffset = is_int($candidate['insertionOffset'] ?? null)
                ? $candidate['insertionOffset']
                : -1;
            if ($sourceProjection === ''
                || $cursor !== strlen($sourceProjection)
                || !hash_equals(
                    (string) ($candidate['sourceProjectionDigest'] ?? ''),
                    hash('sha256', $sourceProjection)
                )
                || $outputProjection === ''
                || !hash_equals(
                    (string) ($candidate['outputProjectionDigest'] ?? ''),
                    hash('sha256', $outputProjection)
                )
                || $this->pdfSourceOccurrenceComparableText($outputText)
                    !== $outputProjection
                || $insertionOffset < 0
                || $insertionOffset >= strlen($outputProjection)
                || $outputProjection[$insertionOffset] !== '@'
                || !hash_equals(
                    $sourceProjection,
                    substr($outputProjection, 0, $insertionOffset)
                        . substr($outputProjection, $insertionOffset + 1)
                )
                || substr_count($finalProjection, $outputProjection) !== 1) {
                continue;
            }
            $id = is_string($item['id'] ?? null) ? $item['id'] : '';
            if ($id === '') {
                continue;
            }
            $existing = is_array($dispositions[$id] ?? null)
                ? $dispositions[$id]
                : [];
            $existingKind = (string) ($existing['disposition'] ?? 'emitted');
            if (!in_array($existingKind, ['emitted', 'boundary-repair'], true)) {
                continue;
            }
            $existingEvidence = is_array($existing['evidence'] ?? null)
                ? $existing['evidence']
                : [];
            $dispositions[$id] = array_replace($existing, [
                'disposition' => 'boundary-repair',
                'reason' => 'An exact front-matter mailbox proof restores the single required delimiter between the local part and DNS domain.',
                'evidence' => array_replace($existingEvidence, [
                    'method' => 'exact-semantic-email-delimiter-insertion',
                    'sourceBounds' => $this->pdfSourceEvidenceBounds(
                        $item['sourceGeometry']
                    ),
                    'insertionOffset' => $insertionOffset,
                    'semanticProofDigest' => $candidate['semanticProofDigest'],
                    'proofDigest' => $candidate['proofDigest'],
                ]),
                'textProjection' => $outputText,
                'allowOrderChange' => (bool) ($existing['allowOrderChange'] ?? false),
            ]);
        }

        return $dispositions;
    }

    /**
     * Apply only transformations with local decision evidence. A candidate
     * which was not actually transformed remains detectable because its
     * emitted inventory or ordered-conservation gate will fail.
     *
     * @param list<array<string, mixed>> $lineItems
     * @param list<AstNode> $blocks
     * @param list<int> $geometryOrderPages
     * @param list<array<string,mixed>> $geometryOrderLayouts Consumed once the exact page proofs are built.
     * @param array<int,array{start:int,end:int,projection:string,leafEnds:list<int>}> $finalOutputPageProofs
     * @param array<string,mixed>|null $finalOutputRangeProof
     * @param list<array<string,mixed>> $candidateProofSourceLayouts
     * @return array<string, array<string, mixed>>
     */
    private function explicitPdfSourceDispositions(
        array $lineItems,
        array $blocks = [],
        array $geometryOrderPages = [],
        array &$geometryOrderLayouts = [],
        array $finalOutputPageProofs = [],
        ?array $finalOutputRangeProof = null,
        array $candidateProofSourceLayouts = []
    ): array
    {
        $dispositions = $this->positionedPdfDisplayTokenRepairDispositions(
            $lineItems,
            $blocks,
            $finalOutputPageProofs
        );
        $dispositions = $this->pdfDispositionsWithSemanticEmailDelimiterRepairs(
            $lineItems,
            $blocks,
            $dispositions
        );
        $finalProjection = $this->pdfSignificantProjectionFromBlocks($blocks);
        foreach ($lineItems as $item) {
            $id = is_string($item['id'] ?? null) ? $item['id'] : '';
            $proof = is_array($item['sourcePdfOverprintedDuplicateArtifactEvidence'] ?? null)
                ? $item['sourcePdfOverprintedDuplicateArtifactEvidence']
                : null;
            if ($id === ''
                || $proof === null
                || ($proof['artifact']['sourceOccurrenceId'] ?? null) !== $id
                || !$this->sourcePdfOverprintedDuplicateArtifactProofMatchesSourceItems(
                    $proof,
                    $lineItems
                )) {
                continue;
            }
            $retainedId = $proof['retained']['sourceOccurrenceId'] ?? null;
            $retained = null;
            foreach ($lineItems as $candidate) {
                if (($candidate['id'] ?? null) === $retainedId) {
                    $retained = $candidate;
                    break;
                }
            }
            $projection = is_array($retained)
                ? $this->pdfSourceOccurrenceComparableText(
                    (string) ($retained['text'] ?? '')
                )
                : '';
            $proofPage = (int) ($proof['page'] ?? 0);
            $retainedOutputProjection = $proofPage >= 1
                && is_string($finalOutputPageProofs[$proofPage]['projection'] ?? null)
                    ? $finalOutputPageProofs[$proofPage]['projection']
                    : $finalProjection;
            if ($projection === ''
                || !hash_equals(
                    (string) ($proof['projectionDigest'] ?? ''),
                    hash('sha256', $projection)
                )
                || substr_count($retainedOutputProjection, $projection) !== 1) {
                continue;
            }
            $dispositions[$id] = [
                'disposition' => 'artifact',
                'reason' => 'A signed exact-geometry receipt proves this adjacent URL occurrence is a redundant overprint of the retained source occurrence.',
                'evidence' => $proof,
                'allowOrderChange' => false,
            ];
        }
        $validatedChartCipherProofsBySourceId =
            $this->sourcePdfChartCipherArtifactProofs($lineItems);
        foreach ($lineItems as $item) {
            $id = is_string($item['id'] ?? null) ? $item['id'] : '';
            $proof = $id !== ''
                && is_array($this->sourcePdfChartCipherArtifactProofsBySourceId[$id] ?? null)
                    ? $this->sourcePdfChartCipherArtifactProofsBySourceId[$id]
                    : null;
            $validatedProof = $id !== ''
                ? ($validatedChartCipherProofsBySourceId[$id] ?? null)
                : null;
            if ($id === ''
                || !is_array($proof)
                || !is_array($validatedProof)
                || $validatedProof !== $proof
                || !$this->sourcePdfSignedProofDigestMatches($proof)
                || !in_array($id, $proof['sourceOccurrenceIds'] ?? [], true)
                || ($item['sourcePdfChartCipherArtifactEvidence'] ?? null) !== $proof) {
                continue;
            }
            $dispositions[$id] = [
                'disposition' => 'artifact',
                'reason' => 'A signed exact same-stream source-run receipt proves this occurrence belongs to a sustained substituted chart-font cipher rather than editable prose.',
                'evidence' => $proof,
                'allowOrderChange' => false,
            ];
        }
        unset($validatedChartCipherProofsBySourceId);
        $uniqueMapGlyphLadderProofs = [];
        foreach ($this->sourcePdfMapGlyphLadderArtifactProofsBySourceId as $proof) {
            if (is_array($proof) && is_string($proof['proofDigest'] ?? null)) {
                $uniqueMapGlyphLadderProofs[$proof['proofDigest']] = $proof;
            }
        }
        foreach ($uniqueMapGlyphLadderProofs as $proof) {
            if (!$this->sourcePdfMapGlyphLadderArtifactProofMatchesSourceItems(
                $proof,
                $lineItems
            )) {
                continue;
            }
            foreach ($proof['sourceOccurrenceIds'] as $sourceId) {
                if (($this->sourcePdfMapGlyphLadderArtifactProofsBySourceId[
                    $sourceId
                ] ?? null) !== $proof) {
                    continue;
                }
                $dispositions[$sourceId] = [
                    'disposition' => 'artifact',
                    'reason' => 'A signed exact source-run receipt binds this occurrence to a greater-than-sixteen glyph ladder inside an independently positioned sustained map-label region.',
                    'evidence' => $proof,
                    'allowOrderChange' => false,
                ];
            }
        }
        unset($uniqueMapGlyphLadderProofs);
        unset($finalProjection);
        $independentColumnRegions = [];
        foreach ($this->geometryLayoutHypotheses as $hypothesis) {
            if (!is_array($hypothesis)
                || ($hypothesis['selected'] ?? null) !== 'independent-columns'
                || !is_numeric($hypothesis['columnMinusTableMargin'] ?? null)
                || (float) $hypothesis['columnMinusTableMargin'] < 0.12
                || !is_array($hypothesis['bounds'] ?? null)
                || !$this->pdfSourceBoundsAreValid($hypothesis['bounds'])) {
                continue;
            }
            $page = max(1, (int) ($hypothesis['page'] ?? 1));
            if (!isset($this->sourceProofCandidateBlocksByPage[$page])
                && !isset($this->independentColumnBlocksByPage[$page])) {
                // A scored hypothesis is diagnostic evidence, not authority
                // to reorder source occurrences.  Only a candidate which
                // passed the complete page binding gate may activate it.
                continue;
            }
            $independentColumnRegions[$page][] = [
                'hypothesis' => 'independent-columns',
                'columnMinusTableMargin' => (float) $hypothesis['columnMinusTableMargin'],
                'bounds' => $hypothesis['bounds'],
                'featureDigest' => hash(
                    'sha256',
                    json_encode($hypothesis['features'] ?? [], JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE) ?: ''
                ),
            ];
        }
        foreach ($independentColumnRegions as &$regions) {
            usort(
                $regions,
                static fn (array $left, array $right): int =>
                    (float) $right['columnMinusTableMargin'] <=> (float) $left['columnMinusTableMargin']
            );
        }
        unset($regions);
        $wrappedHyphenBoundaryRepairs = $this->pdfSourceWrappedHyphenBoundaryRepairs(
            $lineItems,
            $geometryOrderLayouts,
            $blocks,
            $finalOutputPageProofs,
            $finalOutputRangeProof,
            $dispositions
        );
        $misorderedDiacriticRepairs =
            $this->pdfSourceMisorderedDiacriticBoundaryRepairs(
                $lineItems,
                $blocks,
                $finalOutputPageProofs
            );
        foreach ($lineItems as $item) {
            $page = max(1, (int) ($item['page'] ?? 1));
            $id = is_string($item['id'] ?? null) ? $item['id'] : '';
            $sourceGeometry = is_array($item['sourceGeometry'] ?? null)
                ? $item['sourceGeometry']
                : null;
            if ($id === '' || $sourceGeometry === null) {
                continue;
            }
            $evidence = null;
            foreach ($independentColumnRegions[$page] ?? [] as $candidate) {
                if (!$this->pdfSourceGeometryIntersectsBounds(
                    $sourceGeometry,
                    is_array($candidate['bounds'] ?? null) ? $candidate['bounds'] : []
                )) {
                    continue;
                }
                $evidence = $candidate + [
                    'sourceBounds' => $this->pdfSourceEvidenceBounds($sourceGeometry),
                    'localGeometryMatch' => 'bbox-intersection',
                ];
                break;
            }
            if (!is_array($evidence)) {
                continue;
            }
            $text = (string) ($item['text'] ?? '');
            $projection = $this->pdfIndependentColumnSemanticTextProjection($text);
            $semanticDelimiter = $projection !== $text;
            $dispositions[$id] = [
                'disposition' => $semanticDelimiter ? 'semantic-structure' : 'boundary-repair',
                'reason' => $semanticDelimiter
                    ? 'A high-margin independent-column region represents recurring cue delimiters as block structure.'
                    : 'A high-margin independent-column region proves column-major reading order.',
                'evidence' => $evidence + ['semanticCueDelimiter' => $semanticDelimiter],
                'textProjection' => $projection,
                'allowOrderChange' => true,
            ];
        }
        unset($independentColumnRegions);

        // These projections were already applied to source-derived layouts
        // before semantic parsing. Revalidate the signed receipt against the
        // immutable source occurrence before teaching the fidelity ledger how
        // the omitted folios or matrix glyphs are represented.
        foreach ($lineItems as $sourceIndex => $item) {
            $id = is_string($item['id'] ?? null) ? $item['id'] : '';
            $proof = is_array($item['sourcePdfFacingFolioBoundaryRepair'] ?? null)
                ? $item['sourcePdfFacingFolioBoundaryRepair']
                : (is_array($item['sourcePdfChoiceMatrixBoundaryRepair'] ?? null)
                    ? $item['sourcePdfChoiceMatrixBoundaryRepair']
                    : null);
            if ($id === ''
                || $proof === null
                || !$this->sourcePdfBoundaryProjectionProofMatchesItem(
                    $proof,
                    $item,
                    $sourceIndex
                )) {
                continue;
            }
            $existing = is_array($dispositions[$id] ?? null)
                ? $dispositions[$id]
                : [];
            $existingEvidence = is_array($existing['evidence'] ?? null)
                ? $existing['evidence']
                : [];
            $role = (string) ($proof['role'] ?? 'facing-folio-title');
            if ($role === 'choice-matrix-marker-row') {
                $dispositions[$id] = [
                    'disposition' => 'artifact',
                    'reason' => 'A signed recurring choice-matrix proof binds this source row to aligned painted choice marks rather than list content.',
                    'evidence' => $existingEvidence + [
                        'choiceMatrixBoundaryRepair' => $proof,
                    ],
                ];
                continue;
            }
            $reason = $role === 'choice-matrix-label'
                ? 'A signed recurring choice-matrix proof removes only the exact accessibility/symbol prefix from this label.'
                : 'A signed spread-edge proof removes two consecutive facing folios while preserving the exact intervening title.';
            $dispositions[$id] = array_replace($existing, [
                'disposition' => 'boundary-repair',
                'reason' => $reason,
                'evidence' => $existingEvidence + [
                    'lineLocalBoundaryRepair' => $proof,
                ],
                'textProjection' => (string) $proof['textProjection'],
                'allowOrderChange' => (bool) ($existing['allowOrderChange'] ?? false),
            ]);
        }

        // Some producers paint a spacing accent as its own source occurrence
        // immediately over the base glyph which starts the next occurrence.
        // Recompose only an exact same-stream geometry triple. The accent is
        // represented by the following base projection, while the final page
        // conservation and binding gates still have to find those exact bytes.
        foreach ($misorderedDiacriticRepairs as $repair) {
            $markId = $repair['markId'];
            $baseId = $repair['baseId'];
            $markExisting = is_array($dispositions[$markId] ?? null)
                ? $dispositions[$markId]
                : [];
            $baseExisting = is_array($dispositions[$baseId] ?? null)
                ? $dispositions[$baseId]
                : [];
            $markKind = (string) ($markExisting['disposition'] ?? 'emitted');
            $baseKind = (string) ($baseExisting['disposition'] ?? 'emitted');
            if (!in_array($markKind, ['emitted', 'boundary-repair'], true)
                || !in_array($baseKind, ['emitted', 'boundary-repair'], true)) {
                continue;
            }
            $baseProjection = is_string($baseExisting['textProjection'] ?? null)
                ? $baseExisting['textProjection']
                : $repair['baseText'];
            if (!str_starts_with($baseProjection, $repair['baseCharacter'])) {
                continue;
            }
            $baseProjection = $repair['composedCharacter']
                . substr($baseProjection, strlen($repair['baseCharacter']));
            $baseEvidence = is_array($baseExisting['evidence'] ?? null)
                ? $baseExisting['evidence']
                : [];
            $baseEvidence['misorderedDiacriticBoundaryRepair'] = $repair['evidence'] + [
                'composedProjectionDigest' => hash('sha256', $baseProjection),
            ];
            $baseReason = trim((string) ($baseExisting['reason'] ?? ''));
            $dispositions[$markId] = [
                'disposition' => 'artifact',
                'reason' => 'An exact same-stream geometry triple proves this standalone spacing accent is represented by the following recomposed base glyph.',
                'evidence' => $repair['evidence'] + [
                    'role' => 'spacing-mark',
                ],
            ];
            $dispositions[$baseId] = array_replace($baseExisting, [
                'disposition' => 'boundary-repair',
                'reason' => $baseReason !== ''
                    ? $baseReason . ' The preceding exact spacing accent is recomposed onto this base glyph.'
                    : 'The preceding exact spacing accent is recomposed onto this base glyph.',
                'evidence' => $baseEvidence,
                'textProjection' => $baseProjection,
                'allowOrderChange' => (bool) ($baseExisting['allowOrderChange'] ?? false),
            ]);
        }
        unset($misorderedDiacriticRepairs);

        // A document profile can identify repeated edge text, but that
        // classification alone does not prove that the final AST removed the
        // corresponding source occurrence. Accept running-furniture only from
        // signed transformation receipts produced by the exact removal stage,
        // then rebind every peer endpoint to the immutable source inventory.
        foreach ($this->removedPageNumberFurnitureProofsBySourceId as $id => $proof) {
            if (isset($dispositions[$id])
                || !$this->pdfRepeatedPageNumberFurnitureProofMatchesSourceItems(
                    $proof,
                    $id,
                    $lineItems
                )) {
                continue;
            }
            $dispositions[$id] = [
                'disposition' => 'running-furniture',
                'reason' => ($proof['method'] ?? null)
                    === 'exact-single-page-bottom-footer-companion-page-number-removal'
                    ? 'A signed semantic-stage receipt binds this isolated numeric folio to the far-right bottom slot opposite one exact long footer companion.'
                    : 'A signed semantic-stage receipt binds this isolated numeric folio to one exact bottom-slot occurrence on each of multiple source pages.',
                'evidence' => $proof,
            ];
        }

        // List markers are source characters, but in the AST their meaning is
        // carried by the ordered/bullet list node. Remove a marker from the
        // accounting projection only after an exact emitted list-item text of
        // the same kind is available, consuming that proof once so repeated
        // spellings cannot bless an unrelated source occurrence.
        foreach ($this->pdfExactCompactEmbeddedOrderedMarkerProjections(
            $lineItems,
            $blocks
        ) as $id => $repair) {
            $existing = is_array($dispositions[$id] ?? null)
                ? $dispositions[$id]
                : [];
            $kind = (string) ($existing['disposition'] ?? 'emitted');
            $sourceText = $repair['sourceText'];
            $existingProjection = is_string($existing['textProjection'] ?? null)
                ? $existing['textProjection']
                : $sourceText;
            if (!in_array($kind, ['emitted', 'boundary-repair'], true)
                || !hash_equals($sourceText, $existingProjection)) {
                continue;
            }
            $existingEvidence = is_array($existing['evidence'] ?? null)
                ? $existing['evidence']
                : [];
            $existingReason = trim((string) ($existing['reason'] ?? ''));
            $dispositions[$id] = array_replace($existing, [
                'disposition' => 'semantic-structure',
                'reason' => $existingReason !== ''
                    ? $existingReason . ' The compact ordinal is represented by one exact page-local ordered-list item.'
                    : 'The compact ordinal is represented by one exact page-local ordered-list item.',
                'evidence' => $existingEvidence + [
                    'compactEmbeddedOrderedMarker' => $repair['evidence'],
                ],
                'textProjection' => $repair['textProjection'],
                'allowOrderChange' => (bool) ($existing['allowOrderChange'] ?? false),
            ]);
        }

        $structuralMarkerCounts = $this->pdfStructuralListMarkerCounts($blocks);
        $sourceMarkerCounts = ['ordered' => 0, 'bullet' => 0];
        $sourceMarkersById = [];
        $bulletMarkerPattern = '/(?:^|(?<=\s))([*\x{2022}\x{25CF}\x{25AA}\x{25A0}\x{2043}])(?=\s|$)/u';
        // A marker occupying the start (or all) of a source occurrence may
        // use any ordinal. Inside prose, accept only compact ordinals: a
        // four-digit token such as "signed for 2022. Form" is year
        // punctuation, not evidence for an unrelated structural list item.
        $orderedMarkerPattern = '/(?:^\s*\d+[.)](?=\s|$)|(?<=\s)\d{1,3}[.)](?=\s))/u';
        foreach ($lineItems as $item) {
            $id = is_string($item['id'] ?? null) ? $item['id'] : '';
            $text = is_string($item['text'] ?? null) ? $item['text'] : '';
            if ($id === '' || $text === '') {
                continue;
            }
            $bulletCount = preg_match_all($bulletMarkerPattern, $text);
            $orderedCount = preg_match_all($orderedMarkerPattern, $text);
            $bulletCount = is_int($bulletCount) ? $bulletCount : 0;
            $orderedCount = is_int($orderedCount) ? $orderedCount : 0;
            if ($bulletCount > 0 || $orderedCount > 0) {
                $sourceMarkersById[$id] = [
                    'bullet' => $bulletCount,
                    'ordered' => $orderedCount,
                ];
                $sourceMarkerCounts['bullet'] += $bulletCount;
                $sourceMarkerCounts['ordered'] += $orderedCount;
            }
        }
        $cardinalityProved = [];
        foreach (['bullet', 'ordered'] as $kind) {
            $cardinalityProved[$kind] = $sourceMarkerCounts[$kind] > 0
                && $sourceMarkerCounts[$kind] === $structuralMarkerCounts[$kind];
        }
        if ($cardinalityProved['bullet'] || $cardinalityProved['ordered']) {
            $proofIdentity = [
                'sourceSha256' => $this->sourceSha256,
                'sourceMarkerCounts' => $sourceMarkerCounts,
                'structuralMarkerCounts' => $structuralMarkerCounts,
                'sourceOccurrenceIds' => array_keys($sourceMarkersById),
            ];
            $proofEncoded = json_encode(
                $proofIdentity,
                JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE
            );
            $proofDigest = hash(
                'sha256',
                is_string($proofEncoded) ? $proofEncoded : serialize($proofIdentity)
            );
            foreach ($lineItems as $item) {
                $id = is_string($item['id'] ?? null) ? $item['id'] : '';
                $markerCounts = $sourceMarkersById[$id] ?? null;
                if ($id === '' || !is_array($markerCounts)) {
                    continue;
                }
                $sourceText = is_string($item['text'] ?? null) ? $item['text'] : '';
                if (preg_match(
                    '/\A\s*(?:\d+[.)]|[*\x{2022}\x{25CF}\x{25AA}\x{25A0}\x{2043}])\s*\z/uD',
                    $sourceText
                ) === 1) {
                    // Equal document-wide totals do not identify which final
                    // list item owns a marker-only occurrence. Leave it
                    // literal here; the occurrence-local anchor proof below
                    // will project it to structure only when one exact live
                    // target exists.
                    continue;
                }
                $existing = is_array($dispositions[$id] ?? null)
                    ? $dispositions[$id]
                    : [];
                $existingKind = (string) ($existing['disposition'] ?? 'emitted');
                if (!in_array($existingKind, ['emitted', 'boundary-repair', 'semantic-structure'], true)) {
                    continue;
                }
                $hasProvedMarker = false;
                $hasUnprovedMarker = false;
                foreach (['bullet', 'ordered'] as $kind) {
                    if (($markerCounts[$kind] ?? 0) < 1) {
                        continue;
                    }
                    if ($cardinalityProved[$kind]) {
                        $hasProvedMarker = true;
                    } else {
                        $hasUnprovedMarker = true;
                    }
                }
                if (!$hasProvedMarker || $hasUnprovedMarker) {
                    // A different marker kind may have proved document-wide
                    // cardinality.  It must not pre-empt this occurrence's
                    // narrower exact list-item proof while leaving its own
                    // marker characters in the text projection.
                    continue;
                }
                $projection = is_string($existing['textProjection'] ?? null)
                    ? $existing['textProjection']
                    : (string) ($item['text'] ?? '');
                $removedCounts = ['bullet' => 0, 'ordered' => 0];
                if ($cardinalityProved['bullet'] && $markerCounts['bullet'] > 0) {
                    $projection = preg_replace(
                        '/(?:^|(?<=\s))[*\x{2022}\x{25CF}\x{25AA}\x{25A0}\x{2043}](?=\s|$)\s*/u',
                        '',
                        $projection,
                        -1,
                        $removedCounts['bullet']
                    ) ?? $projection;
                }
                if ($cardinalityProved['ordered'] && $markerCounts['ordered'] > 0) {
                    $projection = preg_replace(
                        '/(?:^\s*\d+[.)](?=\s|$)|(?<=\s)\d{1,3}[.)](?=\s))\s*/u',
                        '',
                        $projection,
                        -1,
                        $removedCounts['ordered']
                    ) ?? $projection;
                }
                if ($removedCounts['bullet'] !== ($cardinalityProved['bullet'] ? $markerCounts['bullet'] : 0)
                    || $removedCounts['ordered'] !== ($cardinalityProved['ordered'] ? $markerCounts['ordered'] : 0)) {
                    continue;
                }
                $existingEvidence = is_array($existing['evidence'] ?? null)
                    ? $existing['evidence']
                    : [];
                $dispositions[$id] = array_replace($existing, [
                    'disposition' => 'semantic-structure',
                    'reason' => 'Every exact source list marker of this kind has one final structural list-item counterpart; this occurrence maps its marker characters to that structure.',
                    'evidence' => $existingEvidence + [
                        'method' => 'exact-source-structural-list-marker-cardinality',
                        'sourceMarkerCounts' => $sourceMarkerCounts,
                        'structuralMarkerCounts' => $structuralMarkerCounts,
                        'occurrenceMarkerCounts' => $removedCounts,
                        'proofDigest' => $proofDigest,
                    ],
                    'textProjection' => $projection,
                    'allowOrderChange' => (bool) ($existing['allowOrderChange'] ?? false),
                ]);
            }
        }

        $listItems = $this->pdfStructuralListItemInventory($blocks);
        foreach ($lineItems as $item) {
            $id = is_string($item['id'] ?? null) ? $item['id'] : '';
            if ($id === '' || isset($dispositions[$id])) {
                continue;
            }
            $sourceText = is_string($item['text'] ?? null) ? $item['text'] : '';
            $listItem = $this->listItem($sourceText);
            if ($listItem === null) {
                continue;
            }
            [$ordered, $projection] = $listItem;
            $kind = $ordered ? 'ordered' : 'bullet';
            $key = $this->pdfSourceOccurrenceComparableText($projection);
            $visibleProjection = $this->pdfStructuralOccurrenceComparableText($projection);
            if ($key === '' || $visibleProjection === '') {
                continue;
            }
            $matchedIndex = null;
            $matchedAsPrefix = false;
            foreach ($listItems[$kind] as $index => $structuralItem) {
                if (($structuralItem['significant'] ?? null) === $key
                    || ($structuralItem['visible'] ?? null) === $visibleProjection) {
                    $matchedIndex = $index;
                    break;
                }
                // Prose repair can join following source lines to the first
                // paragraph in a list item. The marker-bearing occurrence is
                // still exact when its complete normalized remainder is the
                // item prefix and ends on a real word boundary.
                if (str_starts_with(
                    (string) ($structuralItem['visible'] ?? ''),
                    $visibleProjection . ' '
                )) {
                    $matchedIndex = $index;
                    $matchedAsPrefix = true;
                    break;
                }
            }
            if ($matchedIndex === null) {
                continue;
            }
            unset($listItems[$kind][$matchedIndex]);
            $dispositions[$id] = [
                'disposition' => 'semantic-structure',
                'reason' => $matchedAsPrefix
                    ? 'The exact source list-item remainder is the complete initial segment of one structural list item, which represents its marker.'
                    : 'The exact source list item is emitted under a matching structural list node, which represents its marker.',
                'evidence' => [
                    'method' => $matchedAsPrefix
                        ? 'exact-structural-list-item-prefix-occurrence'
                        : 'exact-structural-list-item-occurrence',
                    'listType' => $kind,
                    'projectionDigest' => hash('sha256', $key),
                ],
                'textProjection' => $projection,
                'allowOrderChange' => false,
            ];
        }
        unset(
            $listItems,
            $structuralMarkerCounts,
            $sourceMarkerCounts,
            $sourceMarkersById,
            $cardinalityProved,
            $proofIdentity,
            $proofEncoded,
            $proofDigest
        );

        // Project a terminal hyphen only from the exact directional layout
        // pair that the prose merger consumed. The pair is re-bound to the
        // original source occurrence IDs below; a merely adjacent spelling
        // elsewhere in the document cannot authorize this repair. Soft
        // hyphens without such a pair remain visible separators.
        foreach ($lineItems as $item) {
            $id = is_string($item['id'] ?? null) ? $item['id'] : '';
            $sourceText = is_string($item['text'] ?? null) ? $item['text'] : '';
            $boundaryRepair = is_array($wrappedHyphenBoundaryRepairs[$id] ?? null)
                ? $wrappedHyphenBoundaryRepairs[$id]
                : null;
            if ($id === '' || ($boundaryRepair === null && !str_contains($sourceText, "\u{00AD}"))) {
                continue;
            }
            $existing = is_array($dispositions[$id] ?? null)
                ? $dispositions[$id]
                : [];
            $kind = (string) ($existing['disposition'] ?? 'boundary-repair');
            if (!in_array($kind, ['emitted', 'boundary-repair', 'semantic-structure'], true)) {
                continue;
            }
            $projection = is_string($existing['textProjection'] ?? null)
                ? $existing['textProjection']
                : $sourceText;
            $existingEvidence = is_array($existing['evidence'] ?? null)
                ? $existing['evidence']
                : [];
            $lineEndCount = 0;
            $semanticLineEndCount = 0;
            $appliedBoundaryRepair = null;
            if ($boundaryRepair !== null) {
                $separator = is_string($boundaryRepair['separator'] ?? null)
                    ? $boundaryRepair['separator']
                    : '';
                $replacement = is_string($boundaryRepair['replacement'] ?? null)
                    ? $boundaryRepair['replacement']
                    : '';
                if ($separator !== '' && str_ends_with($projection, $separator)) {
                    $projection = substr($projection, 0, -strlen($separator)) . $replacement;
                    $appliedBoundaryRepair = $boundaryRepair;
                    $lineEndCount = ($boundaryRepair['suppressionKind'] ?? null) === 'discretionary-soft-hyphen'
                        ? 1
                        : 0;
                    $semanticLineEndCount = ($boundaryRepair['suppressionKind'] ?? null) === 'semantic-soft-hyphen'
                        ? 1
                        : 0;
                }
            }
            if ($boundaryRepair !== null
                && $appliedBoundaryRepair === null
                && !str_contains($sourceText, "\u{00AD}")) {
                continue;
            }
            $hardHyphenCount = substr_count($projection, "\u{00AD}");
            $projection = str_replace("\u{00AD}", '-', $projection);
            $reason = $appliedBoundaryRepair !== null
                ? (($appliedBoundaryRepair['suppressionKind'] ?? null) === 'semantic-soft-hyphen'
                    ? 'An exact directional source/layout pair preserves this terminal soft hyphen as a visible semantic separator.'
                    : 'An exact directional source/layout pair proves this terminal PDF hyphen is a discretionary wrapped boundary.')
                : 'PDF soft hyphens without an exact directional discretionary pair remain visible separators.';
            $evidence = $existingEvidence;
            if ($appliedBoundaryRepair !== null && is_array($appliedBoundaryRepair['evidence'] ?? null)) {
                if ($evidence === []) {
                    $evidence = $appliedBoundaryRepair['evidence'];
                }
                $evidence['wrappedHyphenBoundaryRepair'] = $appliedBoundaryRepair['evidence'] + [
                    'composedProjectionDigest' => hash('sha256', $projection),
                ];
            }
            if (str_contains($sourceText, "\u{00AD}")) {
                $evidence['softHyphenRepair'] = [
                    'method' => $appliedBoundaryRepair !== null
                        ? 'exact-directional-source-wrapped-hyphen-boundary'
                        : 'unicode-soft-hyphen-visible-separator',
                    'hardHyphenCount' => $hardHyphenCount,
                    'lineEndJoinCount' => $lineEndCount,
                    'semanticLineEndHyphenCount' => $semanticLineEndCount,
                    'projectionDigest' => hash(
                        'sha256',
                        $this->pdfSourceOccurrenceComparableText($projection)
                    ),
                ];
            }
            $existingReason = trim((string) ($existing['reason'] ?? ''));
            $dispositions[$id] = array_replace($existing, [
                'disposition' => $kind === 'semantic-structure' ? $kind : 'boundary-repair',
                'reason' => $existingReason !== '' ? $existingReason . ' ' . $reason : $reason,
                'evidence' => $evidence,
                'textProjection' => $projection,
                'allowOrderChange' => (bool) ($existing['allowOrderChange'] ?? false),
            ]);
        }
        unset($wrappedHyphenBoundaryRepairs);

        // Numbered section labels may become heading structure rather than
        // list items. Account for the marker only when the remainder of the
        // same source occurrence exactly matches one final heading, consuming
        // that structural occurrence once. This prevents a coincidental
        // heading elsewhere from authorizing arbitrary punctuation removal.
        $headings = $this->pdfStructuralHeadingInventory($blocks);
        foreach ($lineItems as $item) {
            $id = is_string($item['id'] ?? null) ? $item['id'] : '';
            if ($id === '' || isset($dispositions[$id])) {
                continue;
            }
            $sourceText = is_string($item['text'] ?? null) ? $item['text'] : '';
            if (preg_match('/^\s*((?:\d+(?:\.\d+)*)[.)])\s+(.+)$/u', $sourceText, $match) !== 1) {
                continue;
            }
            $marker = $match[1];
            $projection = trim($match[2]);
            $key = $this->pdfSourceOccurrenceComparableText($projection);
            if ($key === '' || (int) ($headings[$key] ?? 0) < 1) {
                continue;
            }
            $headings[$key]--;
            if ($headings[$key] < 1) {
                unset($headings[$key]);
            }
            $dispositions[$id] = [
                'disposition' => 'semantic-structure',
                'reason' => 'The exact remainder of this numbered source label is emitted by one matching heading node, which represents its marker.',
                'evidence' => [
                    'method' => 'exact-structural-numbered-heading-occurrence',
                    'markerDigest' => hash('sha256', $marker),
                    'projectionDigest' => hash('sha256', $key),
                ],
                'textProjection' => $projection,
                'allowOrderChange' => false,
            ];
        }
        unset($headings);

        // A standalone marker has no emitted text bytes of its own. Attach a
        // separate structural edge only when its immediate same-stream source
        // successor is the exact initial source edge of one uniquely matching
        // top-level list item with the expected kind and ordinal. The full
        // item digest lets the binding ledger revalidate the live AST target;
        // document-wide marker cardinality alone is deliberately insufficient.
        foreach ($this->pdfExactStandaloneListMarkerSemanticStructureProofs(
            $lineItems,
            $blocks,
            $dispositions,
            $geometryOrderLayouts,
            $finalOutputPageProofs,
            $candidateProofSourceLayouts
        ) as $id => $semanticStructureProof) {
            $existing = is_array($dispositions[$id] ?? null)
                ? $dispositions[$id]
                : [];
            $existingEvidence = is_array($existing['evidence'] ?? null)
                ? $existing['evidence']
                : [];
            $existingReason = trim((string) ($existing['reason'] ?? ''));
            if (($existingEvidence['method'] ?? null)
                !== 'exact-source-structural-list-marker-cardinality') {
                $existingEvidence = [
                    'method' => 'exact-standalone-list-marker-to-item',
                    'listType' => $semanticStructureProof['listType'],
                    'markerDigest' => $semanticStructureProof['markerDigest'],
                    'anchorSourceOccurrenceId' => $semanticStructureProof['anchorSourceOccurrenceId'],
                    'itemProjectionDigest' => $semanticStructureProof['itemProjectionDigest'],
                ];
                if (($semanticStructureProof['version'] ?? null) === 2) {
                    $existingEvidence['anchorSourceOccurrenceIds'] =
                        $semanticStructureProof['anchorSourceOccurrenceIds'];
                    $existingEvidence['anchorProjectionDigest'] =
                        $semanticStructureProof['anchorProjectionDigest'];
                }
            }
            $dispositions[$id] = array_replace($existing, [
                'disposition' => 'semantic-structure',
                'reason' => $existingReason !== ''
                    ? $existingReason
                    : 'This standalone source list marker maps through its immediate same-stream anchor to one exact final structural list item.',
                'evidence' => $existingEvidence,
                'textProjection' => '',
                'allowOrderChange' => false,
                'semanticStructureProof' => $semanticStructureProof,
            ]);
            // Structural marker characters do not participate in a textual
            // permutation, even when their bbox lies inside an accepted
            // independent-column region. Keep the surrounding text scope,
            // but make this exact list edge neutral to it.
            $dispositions[$id]['allowOrderChange'] = false;
            unset($dispositions[$id]['orderProof']);
        }

        // Two icon atoms are omitted only when the immutable source inventory
        // independently recreates the complete nested-symbol admonition
        // proof. The retained uppercase label and prose rows continue through
        // ordinary exact output binding; only the decorative symbol and its
        // nested punctuation receive an artifact disposition.
        foreach ($this->sourcePdfStampedNestedCautionCalloutProofs($lineItems) as $proof) {
            if (!$this->sourcePdfSignedProofDigestMatches($proof)) {
                continue;
            }
            foreach ($proof['iconAtoms'] as $atom) {
                $sourceIndex = is_int($atom['sourceIndex'] ?? null)
                    ? $atom['sourceIndex']
                    : null;
                $item = is_int($sourceIndex) ? ($lineItems[$sourceIndex] ?? null) : null;
                $id = is_array($item) && is_string($item['id'] ?? null)
                    ? $item['id']
                    : '';
                $existing = $id !== '' && is_array($dispositions[$id] ?? null)
                    ? $dispositions[$id]
                    : [];
                $existingKind = (string) ($existing['disposition'] ?? 'emitted');
                if (!is_array($item)
                    || $id === ''
                    || $id !== ($atom['sourceOccurrenceId'] ?? null)
                    || !in_array(
                        $existingKind,
                        ['emitted', 'boundary-repair', 'semantic-structure'],
                        true
                    )) {
                    continue;
                }
                $evidence = [
                    'version' => 1,
                    'method' => 'signed-exact-nested-symbol-callout-icon-atom',
                    'sourceSha256' => $this->sourceSha256,
                    'page' => $proof['page'],
                    'sourceStream' => $proof['sourceStream'],
                    'atomRole' => $atom['role'],
                    'atom' => $atom,
                    'retainedProjectionDigest' => $proof['retainedProjectionDigest'],
                    'calloutProof' => $proof,
                ];
                $encoded = json_encode(
                    $evidence,
                    JSON_UNESCAPED_SLASHES
                        | JSON_UNESCAPED_UNICODE
                        | JSON_PRESERVE_ZERO_FRACTION
                );
                $evidence['proofDigest'] = hash(
                    'sha256',
                    is_string($encoded) ? $encoded : serialize($evidence)
                );
                $dispositions[$id] = [
                    'disposition' => 'artifact',
                    'reason' => 'A signed exact same-stream nested-symbol callout proof identifies this atom as decorative icon paint while preserving the adjacent label and complete prose lane.',
                    'evidence' => $evidence,
                    'allowOrderChange' => false,
                ];
            }
        }

        // A literal brace remains source text unless recurrence, exact bboxes,
        // oversized paired geometry, and enclosed text jointly prove it is a
        // visual callout ornament. This deliberately leaves unmatched code,
        // math, and prose braces available to ordinary exact binding.
        foreach ($this->pdfDecorativeBracePairEvidence($lineItems) as $id => $evidence) {
            if (isset($dispositions[$id])) {
                continue;
            }
            $dispositions[$id] = [
                'disposition' => 'artifact',
                'reason' => 'An exact, recurring oversized brace pair encloses multiple smaller text lines in the same page and content stream, proving a visual callout ornament.',
                'evidence' => $evidence,
            ];
        }

        // A period-only line remains literal unless four consecutive exact
        // source occurrences prove the duplicate terminal-punctuation stack
        // which was removed before prose repair. Recompute the proof from the
        // immutable inventory here so an attached layout flag is never enough
        // to authorize an artifact disposition.
        foreach ($this->pdfDuplicateStandaloneTerminalPeriodEvidence($lineItems) as $id => $evidence) {
            $existing = is_array($dispositions[$id] ?? null)
                ? $dispositions[$id]
                : [];
            $existingKind = (string) ($existing['disposition'] ?? 'emitted');
            if (!in_array(
                $existingKind,
                ['emitted', 'boundary-repair', 'semantic-structure'],
                true
            )) {
                continue;
            }
            $dispositions[$id] = [
                'disposition' => 'artifact',
                'reason' => 'An exact standalone period duplicates the preceding terminal period on a consecutive aligned line stack immediately before a proved section heading and body.',
                'evidence' => $evidence,
            ];
        }

        // An incomplete oversized display run is omitted only after its exact
        // source occurrence, whole-range proof, and local geometry were bound
        // before semantic filtering. This disposition keeps those source
        // characters explicit in the ledger instead of either reintroducing
        // the clipped fragment or silently dropping it.
        foreach ($lineItems as $sourceIndex => $item) {
            $id = is_string($item['id'] ?? null) ? $item['id'] : '';
            $evidence = is_array($item['sourcePdfClippedDisplayArtifactEvidence'] ?? null)
                ? $item['sourcePdfClippedDisplayArtifactEvidence']
                : null;
            if ($id === ''
                || $evidence === null
                || !$this->pdfClippedDisplayArtifactEvidenceMatchesSourceItem(
                    $evidence,
                    $item,
                    (int) $sourceIndex,
                    $lineItems
                )) {
                continue;
            }
            $existing = is_array($dispositions[$id] ?? null)
                ? $dispositions[$id]
                : [];
            $existingKind = (string) ($existing['disposition'] ?? 'emitted');
            if (!in_array($existingKind, ['emitted', 'boundary-repair', 'semantic-structure'], true)) {
                continue;
            }
            $dispositions[$id] = [
                'disposition' => 'artifact',
                'reason' => 'A whole exact source occurrence has source-matched geometry proving an oversized, initially clipped display fragment rather than complete semantic text.',
                'evidence' => $evidence,
            ];
        }

        // A decorative display phrase can share two source records with an
        // unrelated prose lane. The earlier geometry pass signs the complete
        // three-occurrence graph and keeps only the right-lane ranges in the
        // candidate layouts. Rebind that proof here so source reconciliation
        // neither restores the redundant display prefix nor loses the prose
        // suffixes which occupy the same source records.
        foreach ($lineItems as $sourceIndex => $item) {
            $id = is_string($item['id'] ?? null) ? $item['id'] : '';
            $role = is_string($item['sourcePdfCrossLaneDisplayArtifactRole'] ?? null)
                ? $item['sourcePdfCrossLaneDisplayArtifactRole']
                : '';
            $evidence = is_array($item['sourcePdfCrossLaneDisplayArtifactEvidence'] ?? null)
                ? $item['sourcePdfCrossLaneDisplayArtifactEvidence']
                : null;
            if ($id === ''
                || !in_array($role, ['whole-display-artifact', 'display-prefix-projection'], true)
                || $evidence === null
                || !$this->pdfCrossLaneDisplayArtifactEvidenceMatchesSourceItems(
                    $evidence,
                    $lineItems
                )) {
                continue;
            }
            $existing = is_array($dispositions[$id] ?? null)
                ? $dispositions[$id]
                : [];
            $existingKind = (string) ($existing['disposition'] ?? 'emitted');
            if (!in_array($existingKind, ['emitted', 'boundary-repair', 'semantic-structure'], true)) {
                continue;
            }
            if ($role === 'whole-display-artifact') {
                $dispositions[$id] = [
                    'disposition' => 'artifact',
                    'reason' => 'A signed exact three-occurrence lane graph proves this short lead belongs only to a duplicated display phrase.',
                    'evidence' => $evidence,
                ];
                continue;
            }

            $rows = array_values(array_filter(
                $evidence['splitRows'],
                static fn (array $row): bool => ($row['sourceIndex'] ?? null) === $sourceIndex
            ));
            if (count($rows) !== 1
                || !is_string($rows[0]['retainedText'] ?? null)
                || $this->pdfSourceOccurrenceComparableText($rows[0]['retainedText']) === '') {
                continue;
            }
            $existingEvidence = is_array($existing['evidence'] ?? null)
                ? $existing['evidence']
                : [];
            $existingReason = trim((string) ($existing['reason'] ?? ''));
            $dispositions[$id] = array_replace($existing, [
                'disposition' => $existingKind === 'semantic-structure'
                    ? 'semantic-structure'
                    : 'boundary-repair',
                'reason' => ($existingReason !== '' ? $existingReason . ' ' : '')
                    . 'A signed exact split-range proof removes the duplicated left display prefix while retaining the complete right-lane prose suffix.',
                'evidence' => $existingEvidence + [
                    'crossLaneDisplayArtifactProjection' => $evidence,
                ],
                'textProjection' => $rows[0]['retainedText'],
                'allowOrderChange' => (bool) ($existing['allowOrderChange'] ?? false),
            ]);
        }

        // Four compact atoms may represent two translated copies of one map
        // label while the complete semantic sentence is retained elsewhere.
        // Revalidate the signed A-B-B-A graph here before classifying any of
        // the exact source occurrences as redundant display artifacts.
        foreach ($lineItems as $item) {
            $id = is_string($item['id'] ?? null) ? $item['id'] : '';
            $evidence = is_array($item['sourcePdfMirroredMapPairArtifactEvidence'] ?? null)
                ? $item['sourcePdfMirroredMapPairArtifactEvidence']
                : null;
            if ($id === ''
                || ($item['sourcePdfMirroredMapPairArtifactRole'] ?? null)
                    !== 'mirrored-duplicate-map-pair-artifact'
                || $evidence === null
                || !$this->pdfMirroredDuplicateMapPairEvidenceMatchesSourceItems(
                    $evidence,
                    $lineItems
                )) {
                continue;
            }
            $existing = is_array($dispositions[$id] ?? null)
                ? $dispositions[$id]
                : [];
            $existingKind = (string) ($existing['disposition'] ?? 'emitted');
            if (!in_array(
                $existingKind,
                ['emitted', 'boundary-repair', 'semantic-structure'],
                true
            )) {
                continue;
            }
            $dispositions[$id] = [
                'disposition' => 'artifact',
                'reason' => 'A signed exact four-occurrence A-B-B-A graph proves two rigidly translated compact map-label copies while one unique longer prose occurrence preserves the semantic phrase.',
                'evidence' => $evidence,
            ];
        }

        if ($blocks === []) {
            return $dispositions;
        }
        $this->pdfDispositionsWithExactVisualPanelReplacements(
            $lineItems,
            $blocks,
            $dispositions,
            $geometryOrderPages,
            $finalOutputPageProofs
        );
        $this->pdfDispositionsWithExactIndependentColumnOrderProofs(
                $lineItems,
                $dispositions
            );

        $this->pdfDispositionsWithExactSideTableContinuationOrderProofs(
            $lineItems,
            $dispositions,
            $finalOutputPageProofs
        );

        $this->pdfDispositionsWithExactCrossPageListContinuationOrderProofs(
            $lineItems,
            $blocks,
            $dispositions
        );

        $this->pdfDispositionsWithExactGeometryPageOrderProofs(
            $lineItems,
            $blocks,
            $dispositions,
            $geometryOrderPages,
            $geometryOrderLayouts,
            $finalOutputPageProofs
        );

        return $dispositions;
    }

    /**
     * Some compact PDF prose encodes a sequential embedded list as
     * `prefix=4.Item ... prefix=5.Item`. Project the ordinal punctuation only
     * when every source marker belongs to one consecutive same-stream run and
     * one unique ordered list on that exact page has the same start, length,
     * and occurrence-local item prefixes. A coincidental year or ordinal on a
     * different page therefore cannot authorize a projection.
     *
     * @param list<array<string,mixed>> $lineItems
     * @param list<AstNode> $blocks
     * @return array<string,array{
     *     sourceText:string,
     *     textProjection:string,
     *     evidence:array<string,mixed>
     * }>
     */
    private function pdfExactCompactEmbeddedOrderedMarkerProjections(
        array $lineItems,
        array $blocks
    ): array {
        if (count($lineItems) < 2 || $blocks === []) {
            return [];
        }
        $idCounts = [];
        foreach ($lineItems as $item) {
            $id = is_string($item['id'] ?? null) ? $item['id'] : '';
            if ($id !== '') {
                $idCounts[$id] = ($idCounts[$id] ?? 0) + 1;
            }
        }

        $candidatesByPageStream = [];
        foreach ($lineItems as $sourceIndex => $item) {
            $id = is_string($item['id'] ?? null) ? $item['id'] : '';
            $text = is_string($item['text'] ?? null) ? $item['text'] : '';
            $page = max(1, (int) ($item['page'] ?? 1));
            $stream = $item['stream'] ?? null;
            if ($id === ''
                || ($idCounts[$id] ?? 0) !== 1
                || $text === ''
                || !is_int($stream)
                || $stream < 1
                || preg_match(
                    '/\A(?<prefix>.+?[\p{P}\p{S}])(?<ordinal>[1-9]\d{0,2})[.)](?<remainder>\S[\s\S]*)\z/uD',
                    $text,
                    $match
                ) !== 1) {
                continue;
            }
            $remainderSignificant = $this->pdfSourceOccurrenceComparableText(
                $match['remainder']
            );
            if ($remainderSignificant === '') {
                continue;
            }
            $candidatesByPageStream[$page . ':' . $stream][] = [
                'sourceIndex' => $sourceIndex,
                'id' => $id,
                'page' => $page,
                'stream' => $stream,
                'sourceText' => $text,
                'prefix' => $match['prefix'],
                'prefixSignificant' => $this->pdfSourceOccurrenceComparableText(
                    $match['prefix']
                ),
                'ordinal' => (int) $match['ordinal'],
                'remainderSignificant' => $remainderSignificant,
                'textProjection' => $match['prefix'] . $match['remainder'],
            ];
        }
        if ($candidatesByPageStream === []) {
            return [];
        }

        $repairs = [];
        foreach ($candidatesByPageStream as $candidates) {
            $runs = [];
            $run = [];
            foreach ($candidates as $candidate) {
                $previous = $run === [] ? null : $run[array_key_last($run)];
                if ($previous !== null
                    && ($candidate['ordinal'] !== $previous['ordinal'] + 1
                        || $candidate['sourceIndex'] <= $previous['sourceIndex']
                        || !hash_equals(
                            $previous['prefixSignificant'],
                            $candidate['prefixSignificant']
                        ))) {
                    if (count($run) >= 2) {
                        $runs[] = $run;
                    }
                    $run = [];
                }
                $run[] = $candidate;
            }
            if (count($run) >= 2) {
                $runs[] = $run;
            }

            foreach ($runs as $candidateRun) {
                $page = $candidateRun[0]['page'];
                // Authorization concerns the actual final AST, not an
                // alternate page-layout candidate retained for a different
                // source-order proof. Exact full item spans below make the
                // final list unique across the complete document.
                $pageBlocks = $blocks;
                if ($pageBlocks === []) {
                    continue;
                }
                $matches = [];
                foreach ($pageBlocks as $blockIndex => $block) {
                    if (!$block instanceof AstNode || $block->type !== 'ordered_list') {
                        continue;
                    }
                    $start = (int) $block->attr('start', 1);
                    $items = array_values(array_filter(
                        $block->children,
                        static fn (mixed $child): bool => $child instanceof AstNode
                            && $child->type === 'list_item'
                    ));
                    if ($start !== $candidateRun[0]['ordinal']
                        || count($items) !== count($candidateRun)) {
                        continue;
                    }
                    $itemDigests = [];
                    $itemSourceSpans = [];
                    foreach ($items as $offset => $item) {
                        $itemSignificant = $this->pdfSourceOccurrenceComparableText(
                            $this->pdfStructuralListItemVisibleText($item)
                        );
                        $candidate = $candidateRun[$offset];
                        $sourceProjection = $candidate['remainderSignificant'];
                        $sourceIndexes = [$candidate['sourceIndex']];
                        $nextCandidate = $candidateRun[$offset + 1] ?? null;
                        $sourceEndIndex = $candidate['sourceIndex'];
                        if ($itemSignificant === ''
                            || $sourceProjection === ''
                            || !str_starts_with($itemSignificant, $sourceProjection)) {
                            continue 2;
                        }
                        if (is_array($nextCandidate)) {
                            for ($sourceIndex = $candidate['sourceIndex'] + 1;
                                $sourceIndex < $nextCandidate['sourceIndex'];
                                $sourceIndex++) {
                                $sourceItem = $lineItems[$sourceIndex] ?? null;
                                $sourceItemId = is_array($sourceItem)
                                    && is_string($sourceItem['id'] ?? null)
                                        ? $sourceItem['id']
                                        : '';
                                $projection = is_array($sourceItem)
                                    ? $this->pdfSourceOccurrenceComparableText(
                                        (string) ($sourceItem['text'] ?? '')
                                    )
                                    : '';
                                if (!is_array($sourceItem)
                                    || $sourceItemId === ''
                                    || ($idCounts[$sourceItemId] ?? 0) !== 1
                                    || (int) ($sourceItem['page'] ?? 0) !== $page
                                    || (int) ($sourceItem['stream'] ?? 0)
                                        !== $candidate['stream']
                                    || $projection === '') {
                                    continue 3;
                                }
                                $sourceProjection .= $projection;
                                $sourceIndexes[] = $sourceIndex;
                                $sourceEndIndex = $sourceIndex;
                            }
                            $sourceProjection .= $nextCandidate['prefixSignificant'];
                            $sourceIndexes[] = $nextCandidate['sourceIndex'];
                            $sourceEndIndex = $nextCandidate['sourceIndex'];
                        } else {
                            $matchedFinalEdge = hash_equals(
                                $sourceProjection,
                                $itemSignificant
                            );
                            for ($sourceIndex = $candidate['sourceIndex'] + 1,
                                $sourceCount = count($lineItems);
                                !$matchedFinalEdge && $sourceIndex < $sourceCount;
                                $sourceIndex++) {
                                $sourceItem = $lineItems[$sourceIndex] ?? null;
                                $sourceItemId = is_array($sourceItem)
                                    && is_string($sourceItem['id'] ?? null)
                                        ? $sourceItem['id']
                                        : '';
                                $projection = is_array($sourceItem)
                                    ? $this->pdfSourceOccurrenceComparableText(
                                        (string) ($sourceItem['text'] ?? '')
                                    )
                                    : '';
                                if (!is_array($sourceItem)
                                    || $sourceItemId === ''
                                    || ($idCounts[$sourceItemId] ?? 0) !== 1
                                    || (int) ($sourceItem['page'] ?? 0) !== $page
                                    || (int) ($sourceItem['stream'] ?? 0)
                                        !== $candidate['stream']
                                    || $projection === ''
                                    || !str_starts_with(
                                        $itemSignificant,
                                        $sourceProjection . $projection
                                    )) {
                                    break;
                                }
                                $sourceProjection .= $projection;
                                $sourceIndexes[] = $sourceIndex;
                                $sourceEndIndex = $sourceIndex;
                                $matchedFinalEdge = hash_equals(
                                    $sourceProjection,
                                    $itemSignificant
                                );
                            }
                            if (!$matchedFinalEdge) {
                                continue 2;
                            }
                        }
                        if (!hash_equals($sourceProjection, $itemSignificant)) {
                            continue 2;
                        }
                        $itemDigests[] = hash('sha256', $itemSignificant);
                        $itemSourceSpans[] = [
                            'sourceStartIndex' => $candidate['sourceIndex'],
                            'sourceEndIndex' => $sourceEndIndex,
                            'sourceIndexes' => $sourceIndexes,
                            'projectionDigest' => hash('sha256', $sourceProjection),
                        ];
                    }
                    $matches[] = [
                        'blockIndex' => $blockIndex,
                        'itemDigests' => $itemDigests,
                        'itemSourceSpans' => $itemSourceSpans,
                    ];
                }
                if (count($matches) !== 1) {
                    continue;
                }

                $identity = [
                    'version' => 1,
                    'method' => 'exact-source-span-compact-embedded-ordered-list',
                    'sourceSha256' => $this->sourceSha256,
                    'page' => $page,
                    'stream' => $candidateRun[0]['stream'],
                    'startOrdinal' => $candidateRun[0]['ordinal'],
                    'sourceOccurrenceIds' => array_column($candidateRun, 'id'),
                    'sourceIndexes' => array_column($candidateRun, 'sourceIndex'),
                    'prefixDigest' => hash(
                        'sha256',
                        $candidateRun[0]['prefixSignificant']
                    ),
                    'markerDigests' => array_map(
                        static fn (array $candidate): string => hash(
                            'sha256',
                            $candidate['ordinal'] . '.'
                        ),
                        $candidateRun
                    ),
                    'itemProjectionDigests' => $matches[0]['itemDigests'],
                    'itemSourceSpans' => $matches[0]['itemSourceSpans'],
                ];
                $encoded = json_encode(
                    $identity,
                    JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE
                );
                $evidence = $identity + [
                    'proofDigest' => hash(
                        'sha256',
                        is_string($encoded) ? $encoded : serialize($identity)
                    ),
                ];
                foreach ($candidateRun as $candidate) {
                    if (isset($repairs[$candidate['id']])) {
                        unset($repairs[$candidate['id']]);
                        continue;
                    }
                    $repairs[$candidate['id']] = [
                        'sourceText' => $candidate['sourceText'],
                        'textProjection' => $candidate['textProjection'],
                        'evidence' => $evidence + [
                            'ordinal' => $candidate['ordinal'],
                            'sourceTextDigest' => hash('sha256', $candidate['sourceText']),
                            'textProjectionDigest' => hash(
                                'sha256',
                                $candidate['textProjection']
                            ),
                        ],
                    ];
                }
            }
        }

        return $repairs;
    }

    /**
     * A folded brochure can retain decorative title text in a visual panel
     * while excluding it from linear reading order. Permit that replacement
     * only when one unique subset of short right-panel occurrences, all with
     * exact source bboxes, is the complete character difference at a real AST
     * leaf boundary. Body omissions and ambiguous subsets remain unresolved.
     *
     * @param list<array<string,mixed>> $lineItems
     * @param list<AstNode> $blocks
     * @param array<string,array<string,mixed>> $dispositions
     * @param list<array<string,mixed>> $geometryOrderLayouts Consumed once the exact page proofs are built.
     * @param array<int,array{start:int,end:int,projection:string,leafEnds:list<int>}> $finalOutputPageProofs
     * @param list<int> $geometryOrderPages
     * @param array<int,array{start:int,end:int,projection:string,leafEnds:list<int>}> $finalOutputPageProofs
     * @return array<string,array<string,mixed>>
     */
    private function pdfDispositionsWithExactVisualPanelReplacements(
        array $lineItems,
        array $blocks,
        array &$dispositions,
        array $geometryOrderPages,
        array $finalOutputPageProofs = []
    ): array {
        $evidencedPages = [];
        foreach ($geometryOrderPages as $page) {
            $page = (int) $page;
            if ($page > 0) {
                $evidencedPages[$page] = true;
            }
        }
        if ($evidencedPages === []) {
            return $dispositions;
        }

        $contributorSourceIndexesByPage = [];
        $pageBounds = [];
        $pageHeights = [];
        foreach ($lineItems as $item) {
            $id = is_string($item['id'] ?? null) ? $item['id'] : '';
            $text = is_string($item['text'] ?? null) ? $item['text'] : '';
            if ($id === '' || $this->pdfSourceOccurrenceComparableText($text) === '') {
                // PDF fonts may encode alignment blanks as Unicode spacing
                // characters such as U+2007. They have no source-significant
                // bytes and therefore are not output/order contributors.
                continue;
            }
            $explicit = is_array($dispositions[$id] ?? null)
                ? $dispositions[$id]
                : null;
            $kind = is_array($explicit)
                ? (string) ($explicit['disposition'] ?? 'emitted')
                : 'emitted';
            if (!in_array($kind, ['emitted', 'boundary-repair', 'semantic-structure'], true)) {
                continue;
            }
            $projection = is_array($explicit)
                && is_string($explicit['textProjection'] ?? null)
                    ? $explicit['textProjection']
                    : $text;
            $significant = $this->pdfSourceOccurrenceComparableText($projection);
            if ($significant === '') {
                continue;
            }
            $page = max(1, (int) ($item['page'] ?? 1));
            $bounds = is_array($item['sourceGeometry'] ?? null)
                && $this->pdfSourceBoundsAreValid($item['sourceGeometry'])
                    ? $this->pdfSourceEvidenceBounds($item['sourceGeometry'])
                    : null;
            $wordCount = preg_match_all('/[\p{L}\p{M}]+/u', $projection);
            $contributorsByPage[$page][] = [
                'id' => $id,
                'significant' => $significant,
                'sourceBounds' => $bounds,
                'wordCount' => is_int($wordCount) ? $wordCount : 0,
            ];
            if ($bounds === null) {
                continue;
            }
            $pageHeights[$page][] = abs($bounds['y2'] - $bounds['y1']);
            if (!isset($pageBounds[$page])) {
                $pageBounds[$page] = $bounds;
            } else {
                $pageBounds[$page]['x1'] = min($pageBounds[$page]['x1'], $bounds['x1']);
                $pageBounds[$page]['y1'] = min($pageBounds[$page]['y1'], $bounds['y1']);
                $pageBounds[$page]['x2'] = max($pageBounds[$page]['x2'], $bounds['x2']);
                $pageBounds[$page]['y2'] = max($pageBounds[$page]['y2'], $bounds['y2']);
            }
        }
        if ($contributorsByPage === []) {
            return $dispositions;
        }
        ksort($contributorsByPage, SORT_NUMERIC);
        if ($finalOutputPageProofs === [] && count($contributorsByPage) === 1) {
            $page = (int) array_key_first($contributorsByPage);
            $wholeOutputProof = $this->pdfWholeOutputPageProof($blocks);
            if ($wholeOutputProof !== null) {
                $finalOutputPageProofs[$page] = $wholeOutputProof;
            }
        }
        $finalOutputPageProofs = $this->pdfValidatedFinalOutputPageProofs(
            $blocks,
            $finalOutputPageProofs
        );
        if ($finalOutputPageProofs === []) {
            return $dispositions;
        }

        $replacementProofs = [];
        foreach ($contributorsByPage as $page => $contributors) {
            $sourceProjection = implode('', array_column($contributors, 'significant'));
            $sourceInventory = $this->pdfExactCharacterInventory($sourceProjection);
            $pageOutputProof = $this->pdfNormalizedOutputPageProof(
                $finalOutputPageProofs,
                (int) $page
            );
            if ($pageOutputProof === null) {
                return $dispositions;
            }
            $pageOutput = $pageOutputProof['projection'];
            $emittedInventory = $this->pdfExactCharacterInventory($pageOutput);
            if ($sourceInventory === $emittedInventory) {
                continue;
            }
            if (!isset($evidencedPages[(int) $page]) || !isset($pageBounds[$page])) {
                return $dispositions;
            }
            $heights = $pageHeights[$page] ?? [];
            sort($heights, SORT_NUMERIC);
            $medianHeight = $heights === [] ? 0.0 : (float) $heights[intdiv(count($heights), 2)];
            $pageWidth = max(0.0, $pageBounds[$page]['x2'] - $pageBounds[$page]['x1']);
            if ($medianHeight <= 0.0 || $pageWidth <= 0.0) {
                return $dispositions;
            }
            $rightPanelX = $pageBounds[$page]['x1'] + (0.65 * $pageWidth);
            $candidates = [];
            foreach ($contributors as $contributor) {
                $bounds = $contributor['sourceBounds'];
                $significant = $contributor['significant'];
                if (!is_array($bounds)
                    || $bounds['x1'] < $rightPanelX
                    || strlen($significant) < 8
                    || strlen($significant) > 160
                    || $contributor['wordCount'] < 2) {
                    continue;
                }
                $containedInOutput = str_contains($pageOutput, $significant);
                $height = abs($bounds['y2'] - $bounds['y1']);
                if ($containedInOutput && $height < $medianHeight * 1.75) {
                    continue;
                }
                $candidates[] = $contributor + [
                    'inventory' => $this->pdfExactCharacterInventory($significant),
                    'height' => $height,
                    'containedInOutput' => $containedInOutput,
                ];
            }
            if ($candidates === [] || count($candidates) > 16) {
                return $dispositions;
            }

            $remaining = $this->pdfExactCharacterInventoryDifference(
                $sourceInventory,
                $emittedInventory
            );
            if ($remaining === null || $remaining === []) {
                return $dispositions;
            }
            $solutions = $this->pdfCharacterInventoryCandidateSubsets($remaining, $candidates);
            if (count($solutions) !== 1) {
                return $dispositions;
            }
            $selected = [];
            foreach ($solutions[0] as $candidateIndex) {
                $candidate = $candidates[$candidateIndex] ?? null;
                if (!is_array($candidate)) {
                    return $dispositions;
                }
                $selected[] = $candidate;
            }
            $replacementProofs[(int) $page] = [
                'selected' => $selected,
                'pageBounds' => $pageBounds[$page],
                'medianHeight' => $medianHeight,
                'emittedProjection' => $pageOutput,
            ];
        }
        if ($replacementProofs === []) {
            return $dispositions;
        }

        foreach ($replacementProofs as $page => $proof) {
            $selectedIds = array_column($proof['selected'], 'id');
            $proofIdentity = [
                'sourceSha256' => $this->sourceSha256,
                'page' => $page,
                'pageBounds' => $proof['pageBounds'],
                'sourceOccurrenceIds' => $selectedIds,
                'emittedProjectionSha256' => hash('sha256', $proof['emittedProjection']),
            ];
            $encoded = json_encode(
                $proofIdentity,
                JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_PRESERVE_ZERO_FRACTION
            );
            $proofDigest = hash(
                'sha256',
                is_string($encoded) ? $encoded : serialize($proofIdentity)
            );
            foreach ($proof['selected'] as $candidate) {
                $dispositions[$candidate['id']] = [
                    'disposition' => 'visual-replacement',
                    'reason' => 'A uniquely conserved source-only title occurrence belongs to the isolated right-hand visual panel and is represented by that panel composition rather than duplicated in linear output.',
                    'evidence' => [
                        'method' => 'unique-right-panel-visual-title-inventory',
                        'page' => $page,
                        'pageBounds' => $proof['pageBounds'],
                        'sourceBounds' => $candidate['sourceBounds'],
                        'localGeometryMatch' => 'right-panel-bbox',
                        'heightToPageMedianRatio' => round(
                            $candidate['height'] / $proof['medianHeight'],
                            4
                        ),
                        'sourceTextContainedInOutput' => $candidate['containedInOutput'],
                        'proofDigest' => $proofDigest,
                    ],
                ];
            }
        }

        return $dispositions;
    }

    /**
     * @param array<string,int> $minuend
     * @param array<string,int> $subtrahend
     * @return array<string,int>|null
     */
    private function pdfExactCharacterInventoryDifference(array $minuend, array $subtrahend): ?array
    {
        foreach ($subtrahend as $character => $count) {
            if (($minuend[$character] ?? 0) < $count) {
                return null;
            }
            $minuend[$character] -= $count;
            if ($minuend[$character] === 0) {
                unset($minuend[$character]);
            }
        }
        ksort($minuend, SORT_STRING);

        return $minuend;
    }

    /**
     * @param array<string,int> $left
     * @param array<string,int> $right
     * @return array{leftOnly:array<string,int>,rightOnly:array<string,int>}
     */
    private function pdfExactCharacterInventoryDelta(array $left, array $right): array
    {
        $leftOnly = [];
        $rightOnly = [];
        foreach (array_unique(array_merge(array_keys($left), array_keys($right))) as $character) {
            $difference = ($left[$character] ?? 0) - ($right[$character] ?? 0);
            if ($difference > 0) {
                $leftOnly[$character] = $difference;
            } elseif ($difference < 0) {
                $rightOnly[$character] = -$difference;
            }
        }
        ksort($leftOnly, SORT_STRING);
        ksort($rightOnly, SORT_STRING);

        return ['leftOnly' => $leftOnly, 'rightOnly' => $rightOnly];
    }

    /**
     * A source stream can paint the last few words of a left-column sentence
     * immediately before a right-column side table, even though those words
     * visibly continue below the table. Authorize only that already-bounded
     * transformation: an exact complete-sentence prefix remains before the
     * table, the short unfinished suffix moves after every consecutive table
     * and caption occurrence, and the unique geometry-proved lower-case
     * continuation follows it.
     *
     * The emitted byte order is derived only from immutable source text and
     * exact occurrence geometry. The final page projection is consulted as a
     * validation gate, never as a permutation solver. The source ledger later
     * rechecks that these ranges partition every scope occurrence exactly once
     * and reproduce the final output byte for byte.
     *
     * @param list<array<string,mixed>> $lineItems
     * @param array<string,array<string,mixed>> $dispositions
     * @param array<int,array{start:int,end:int,projection:string,leafEnds:list<int>}> $finalOutputPageProofs
     * @return array<string,array<string,mixed>>
     */
    private function pdfDispositionsWithExactSideTableContinuationOrderProofs(
        array $lineItems,
        array &$dispositions,
        array $finalOutputPageProofs
    ): array {
        $lineItems = array_values($lineItems);
        if (count($lineItems) < 4
            || $finalOutputPageProofs === []
            || preg_match('/^[a-f0-9]{64}$/D', $this->sourceSha256) !== 1) {
            return $dispositions;
        }

        $sourceLines = array_map(
            static fn (array $item): string => (string) ($item['text'] ?? ''),
            $lineItems
        );
        $candidates = [];
        $claimsBySourceId = [];
        for ($tableStart = 1, $sourceCount = count($lineItems);
            $tableStart < $sourceCount;
            $tableStart++) {
            $stackedTable = $this->stackedTableRowsAt($sourceLines, $tableStart);
            if ($stackedTable['rows'] === [] || $stackedTable['consumed'] < 4) {
                continue;
            }
            $tableEnd = $tableStart + $stackedTable['consumed'] - 1;
            $previousIndex = $tableStart - 1;
            if ($tableEnd >= $sourceCount) {
                continue;
            }

            $sourceTail = $this->sourcePdfExactSideTableContinuationTail(
                (string) ($lineItems[$previousIndex]['text'] ?? '')
            );
            if ($sourceTail === null) {
                continue;
            }

            $continuationIndexes = [];
            $searchEnd = min($sourceCount - 1, $tableEnd + 8);
            for ($candidateIndex = $tableEnd + 3;
                $candidateIndex <= $searchEnd;
                $candidateIndex++) {
                if ($this->sourcePdfSourceItemsProveExactSideTableContinuation(
                    $lineItems,
                    $previousIndex,
                    $tableStart,
                    $tableEnd,
                    $candidateIndex
                )) {
                    $continuationIndexes[] = $candidateIndex;
                }
            }
            if (count($continuationIndexes) !== 1) {
                continue;
            }
            $continuationIndex = $continuationIndexes[0];

            $records = [];
            $sourceOccurrenceIds = [];
            $geometryDigests = [];
            $scopeBounds = null;
            $page = null;
            $stream = null;
            $valid = true;
            for ($sourceIndex = $previousIndex;
                $sourceIndex <= $continuationIndex;
                $sourceIndex++) {
                $item = $lineItems[$sourceIndex] ?? null;
                $id = is_array($item) && is_string($item['id'] ?? null)
                    ? $item['id']
                    : '';
                $explicit = $id !== '' && is_array($dispositions[$id] ?? null)
                    ? $dispositions[$id]
                    : [];
                $kind = (string) ($explicit['disposition'] ?? 'emitted');
                $projectionText = is_string($explicit['textProjection'] ?? null)
                    ? $explicit['textProjection']
                    : (string) ($item['text'] ?? '');
                $sourceSignificant = $this->pdfSourceOccurrenceComparableText(
                    (string) ($item['text'] ?? '')
                );
                $projectionSignificant = $this->pdfSourceOccurrenceComparableText(
                    $projectionText
                );
                $itemPage = is_array($item) && is_int($item['page'] ?? null)
                    ? $item['page']
                    : 0;
                $itemStream = is_array($item) && is_int($item['stream'] ?? null)
                    ? $item['stream']
                    : 0;
                $geometry = is_array($item['sourceGeometry'] ?? null)
                    ? $item['sourceGeometry']
                    : null;
                if (!is_array($item)
                    || $id === ''
                    || isset($records[$id])
                    || !in_array($kind, ['emitted', 'boundary-repair'], true)
                    || ($explicit['allowOrderChange'] ?? false) === true
                    || is_array($explicit['orderProof'] ?? null)
                    || $sourceSignificant === ''
                    || !hash_equals($sourceSignificant, $projectionSignificant)
                    || $itemPage < 1
                    || $itemStream < 1
                    || ($page !== null && $itemPage !== $page)
                    || ($stream !== null && $itemStream !== $stream)
                    || ($item['sourceGeometryMethod'] ?? null)
                        !== 'exact-page-stream-character-offset'
                    || !is_array($geometry)
                    || !$this->sourcePdfSourceItemHasExactGeometry($item)) {
                    $valid = false;
                    break;
                }
                $page = $itemPage;
                $stream = $itemStream;
                $sourceBounds = $this->pdfSourceEvidenceBounds($geometry);
                $sourceBounds = [
                    'x1' => min($sourceBounds['x1'], $sourceBounds['x2']),
                    'y1' => min($sourceBounds['y1'], $sourceBounds['y2']),
                    'x2' => max($sourceBounds['x1'], $sourceBounds['x2']),
                    'y2' => max($sourceBounds['y1'], $sourceBounds['y2']),
                ];
                if ($scopeBounds === null) {
                    $scopeBounds = $sourceBounds;
                } else {
                    $scopeBounds['x1'] = min($scopeBounds['x1'], $sourceBounds['x1']);
                    $scopeBounds['y1'] = min($scopeBounds['y1'], $sourceBounds['y1']);
                    $scopeBounds['x2'] = max($scopeBounds['x2'], $sourceBounds['x2']);
                    $scopeBounds['y2'] = max($scopeBounds['y2'], $sourceBounds['y2']);
                }
                $records[$id] = [
                    'index' => $sourceIndex,
                    'significant' => $projectionSignificant,
                    'sourceBounds' => $sourceBounds,
                ];
                $sourceOccurrenceIds[] = $id;
                $geometryDigests[] = $this->sourcePdfExactGeometryProofDigest($geometry);
            }
            if (!$valid
                || !is_int($page)
                || !is_int($stream)
                || !is_array($scopeBounds)) {
                continue;
            }

            $previousId = $sourceOccurrenceIds[0] ?? '';
            $previousSignificant = (string) ($records[$previousId]['significant'] ?? '');
            $projectedTail = $this->sourcePdfExactSideTableContinuationTail(
                (string) (($dispositions[$previousId]['textProjection'] ?? null)
                    ?? ($lineItems[$previousIndex]['text'] ?? ''))
            );
            $prefixSignificant = $projectedTail === null
                ? ''
                : $this->pdfSourceOccurrenceComparableText($projectedTail['prefix']);
            $tailSignificant = $projectedTail === null
                ? ''
                : $this->pdfSourceOccurrenceComparableText($projectedTail['tail']);
            if ($projectedTail === null
                || $prefixSignificant === ''
                || $tailSignificant === ''
                || !hash_equals(
                    $this->pdfSourceOccurrenceComparableText($sourceTail['prefix']),
                    $prefixSignificant
                )
                || !hash_equals(
                    $this->pdfSourceOccurrenceComparableText($sourceTail['tail']),
                    $tailSignificant
                )
                || !hash_equals(
                    $previousSignificant,
                    $prefixSignificant . $tailSignificant
                )) {
                continue;
            }

            $emittedSourceRanges = [[
                'sourceOccurrenceId' => $previousId,
                'sourceStart' => 0,
                'sourceEnd' => strlen($prefixSignificant),
            ]];
            for ($sourceIndex = $tableStart;
                $sourceIndex < $continuationIndex;
                $sourceIndex++) {
                $id = (string) ($lineItems[$sourceIndex]['id'] ?? '');
                $significant = (string) ($records[$id]['significant'] ?? '');
                if ($id === '' || $significant === '') {
                    $valid = false;
                    break;
                }
                $emittedSourceRanges[] = [
                    'sourceOccurrenceId' => $id,
                    'sourceStart' => 0,
                    'sourceEnd' => strlen($significant),
                ];
            }
            if (!$valid) {
                continue;
            }
            $emittedSourceRanges[] = [
                'sourceOccurrenceId' => $previousId,
                'sourceStart' => strlen($prefixSignificant),
                'sourceEnd' => strlen($previousSignificant),
            ];
            $continuationId = (string) ($lineItems[$continuationIndex]['id'] ?? '');
            $continuationSignificant = (string) (
                $records[$continuationId]['significant'] ?? ''
            );
            if ($continuationId === '' || $continuationSignificant === '') {
                continue;
            }
            $emittedSourceRanges[] = [
                'sourceOccurrenceId' => $continuationId,
                'sourceStart' => 0,
                'sourceEnd' => strlen($continuationSignificant),
            ];

            $emittedProjection = '';
            foreach ($emittedSourceRanges as $range) {
                $recordSignificant = (string) (
                    $records[$range['sourceOccurrenceId']]['significant'] ?? ''
                );
                $emittedProjection .= substr(
                    $recordSignificant,
                    $range['sourceStart'],
                    $range['sourceEnd'] - $range['sourceStart']
                );
            }
            $sourceProjection = implode('', array_map(
                static fn (string $id): string => (string) (
                    $records[$id]['significant'] ?? ''
                ),
                $sourceOccurrenceIds
            ));
            $pageProof = $this->pdfNormalizedOutputPageProof(
                $finalOutputPageProofs,
                $page
            );
            if ($emittedProjection === ''
                || hash_equals($emittedProjection, $sourceProjection)
                || $pageProof === null
                || substr_count($pageProof['projection'], $emittedProjection) !== 1) {
                continue;
            }

            $identity = [
                'version' => 1,
                'method' => 'exact-source-side-table-continuation-range-order',
                'sourceSha256' => $this->sourceSha256,
                'page' => $page,
                'stream' => $stream,
                'previousSourceIndex' => $previousIndex,
                'tableSourceStart' => $tableStart,
                'tableSourceEnd' => $tableEnd,
                'continuationSourceIndex' => $continuationIndex,
                'sourceOccurrenceIds' => $sourceOccurrenceIds,
                'emittedSourceRanges' => $emittedSourceRanges,
                'emittedProjectionDigest' => hash('sha256', $emittedProjection),
                'geometryDigests' => $geometryDigests,
            ];
            $encoded = json_encode(
                $identity,
                JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE
            );
            $candidateKey = hash(
                'sha256',
                is_string($encoded) ? $encoded : serialize($identity)
            );
            $proof = [
                'scopeId' => 'pdf-side-table-order-scope-' . substr($candidateKey, 0, 32),
                'sourceOccurrenceIds' => $sourceOccurrenceIds,
                'emittedTextProjection' => $emittedProjection,
                'emittedSourceRanges' => $emittedSourceRanges,
            ];
            $candidates[$candidateKey] = [
                'page' => $page,
                'sourceOccurrenceIds' => $sourceOccurrenceIds,
                'sourceIndexesById' => array_combine(
                    $sourceOccurrenceIds,
                    array_map(
                        static fn (string $id): int => (int) $records[$id]['index'],
                        $sourceOccurrenceIds
                    )
                ) ?: [],
                'proof' => $proof,
                'proofDigest' => $candidateKey,
                'bounds' => $scopeBounds,
                'sourceBoundsById' => array_map(
                    static fn (string $id): array => $records[$id]['sourceBounds'],
                    array_combine($sourceOccurrenceIds, $sourceOccurrenceIds) ?: []
                ),
            ];
            foreach ($sourceOccurrenceIds as $id) {
                $claimsBySourceId[$id] = ($claimsBySourceId[$id] ?? 0) + 1;
            }
            $tableStart = $tableEnd;
        }

        $acceptedPages = [];
        foreach ($candidates as $candidate) {
            foreach ($candidate['sourceOccurrenceIds'] as $id) {
                if (($claimsBySourceId[$id] ?? 0) !== 1) {
                    continue 2;
                }
            }
            foreach ($candidate['sourceOccurrenceIds'] as $id) {
                $existing = is_array($dispositions[$id] ?? null)
                    ? $dispositions[$id]
                    : [];
                $existingEvidence = is_array($existing['evidence'] ?? null)
                    ? $existing['evidence']
                    : [];
                $dispositions[$id] = array_replace($existing, [
                    'disposition' => (string) ($existing['disposition'] ?? 'emitted'),
                    'reason' => 'Exact source geometry proves one local sentence suffix continues after the consecutive side table and caption range.',
                    'evidence' => array_replace($existingEvidence, [
                        'hypothesis' => 'side-table-continuation-order',
                        'page' => $candidate['page'],
                        'localGeometryMatch' =>
                            'complete-exact-side-table-source-range-order',
                        'proofDigest' => $candidate['proofDigest'],
                        'bounds' => $candidate['bounds'],
                        'sourceBounds' => $candidate['sourceBoundsById'][$id],
                        'featureDigest' => $candidate['proofDigest'],
                    ]),
                    'textProjection' => is_string($existing['textProjection'] ?? null)
                        ? $existing['textProjection']
                        : (string) (
                            $lineItems[$candidate['sourceIndexesById'][$id] ?? -1]['text']
                                ?? ''
                        ),
                    'allowOrderChange' => true,
                    'orderProof' => $candidate['proof'],
                ]);
            }
            $acceptedPages[$candidate['page']] = true;
        }
        if ($acceptedPages !== []) {
            $this->sourceOrderProofDiagnostics[] = [
                'status' => 'accepted',
                'method' => 'exact-side-table-continuation-source-range-order',
                'pages' => array_map('intval', array_keys($acceptedPages)),
            ];
        }

        return $dispositions;
    }

    /**
     * @param array<string,int> $target
     * @param list<array{inventory:array<string,int>}> $candidates
     * @return list<list<int>> Zero, one, or two solutions.
     */
    private function pdfCharacterInventoryCandidateSubsets(array $target, array $candidates): array
    {
        $solutions = [];
        $search = function (int $index, array $remaining, array $selected) use (
            &$search,
            &$solutions,
            $candidates
        ): void {
            if (count($solutions) > 1) {
                return;
            }
            if ($remaining === []) {
                $solutions[] = $selected;
                return;
            }
            for ($candidateIndex = $index; $candidateIndex < count($candidates); $candidateIndex++) {
                $inventory = $candidates[$candidateIndex]['inventory'] ?? null;
                if (!is_array($inventory)
                    || !$this->pdfCharacterInventoryCanConsume($remaining, $inventory)) {
                    continue;
                }
                $next = $remaining;
                $this->pdfConsumeCharacterInventory($next, $inventory);
                ksort($next, SORT_STRING);
                $nextSelected = $selected;
                $nextSelected[] = $candidateIndex;
                $search($candidateIndex + 1, $next, $nextSelected);
                if (count($solutions) > 1) {
                    return;
                }
            }
        };
        $search(0, $target, []);

        return $solutions;
    }

    /**
     * Bind the stable-moved page-leading list continuation to one contiguous
     * immutable source scope. Marker-only occurrences remain represented by
     * their existing structural dispositions; every textual contributor gets
     * the same exact occurrence permutation proof used by the output binder.
     *
     * @param list<array<string,mixed>> $lineItems
     * @param list<AstNode> $blocks
     * @param array<string,array<string,mixed>> $dispositions
     * @return array<string,array<string,mixed>>
     */
    private function pdfDispositionsWithExactCrossPageListContinuationOrderProofs(
        array $lineItems,
        array $blocks,
        array &$dispositions
    ): array {
        if ($this->pdfCrossPageListContinuationOrderProofCandidates === []
            || $blocks === []) {
            return $dispositions;
        }
        $finalProjection = $this->pdfSignificantProjectionFromBlocks($blocks);
        if ($finalProjection === '') {
            return $dispositions;
        }

        foreach ($this->pdfCrossPageListContinuationOrderProofCandidates as $candidate) {
            $proofDigest = is_string($candidate['proofDigest'] ?? null)
                ? $candidate['proofDigest']
                : '';
            $payload = $candidate;
            unset($payload['proofDigest']);
            $scopeStart = is_int($candidate['scopeSourceStart'] ?? null)
                ? $candidate['scopeSourceStart']
                : -1;
            $scopeEnd = is_int($candidate['scopeSourceEnd'] ?? null)
                ? $candidate['scopeSourceEnd']
                : -1;
            if (($candidate['version'] ?? null) !== 1
                || ($candidate['method'] ?? null)
                    !== 'exact-cross-page-open-list-continuation-order'
                || ($candidate['sourceSha256'] ?? null) !== $this->sourceSha256
                || $proofDigest === ''
                || !hash_equals($proofDigest, hash('sha256', json_encode(
                    $payload,
                    JSON_UNESCAPED_SLASHES
                        | JSON_UNESCAPED_UNICODE
                        | JSON_PRESERVE_ZERO_FRACTION
                ) ?: ''))
                || $scopeStart < 0
                || $scopeEnd < $scopeStart
                || $scopeEnd >= count($lineItems)
                || !is_array($candidate['sourceOccurrenceIds'] ?? null)
                || !is_array($candidate['sourceProjectionDigests'] ?? null)
                || !is_array($candidate['emittedSourceIndexOrder'] ?? null)
                || (int) ($candidate['barrierMarkerCount'] ?? 0) < 3
                || (int) ($candidate['continuationMarkerCount'] ?? 0) < 3) {
                continue;
            }

            $sourceIds = [];
            $projectionDigests = [];
            $requiredSourceIndexes = [];
            for ($sourceIndex = $scopeStart; $sourceIndex <= $scopeEnd; $sourceIndex++) {
                $item = $lineItems[$sourceIndex] ?? null;
                $projection = is_array($item)
                    ? $this->pdfSourceOccurrenceComparableText(
                        (string) ($item['text'] ?? '')
                    )
                    : '';
                if ($projection === '') {
                    continue;
                }
                $id = is_array($item) && is_string($item['id'] ?? null)
                    ? $item['id']
                    : '';
                if ($id === '' || !$this->sourcePdfSourceItemHasExactGeometry($item)) {
                    continue 2;
                }
                $requiredSourceIndexes[] = $sourceIndex;
                $sourceIds[] = $id;
                $projectionDigests[] = hash('sha256', $projection);
            }
            if ($sourceIds !== array_values($candidate['sourceOccurrenceIds'])
                || $projectionDigests
                    !== array_values($candidate['sourceProjectionDigests'])) {
                continue;
            }
            $emittedSourceIndexOrder = array_values($candidate['emittedSourceIndexOrder']);
            if (array_filter(
                $emittedSourceIndexOrder,
                static fn (mixed $sourceIndex): bool => !is_int($sourceIndex)
            ) !== []) {
                continue;
            }
            $sortedEmitted = $emittedSourceIndexOrder;
            sort($sortedEmitted, SORT_NUMERIC);
            if ($sortedEmitted !== $requiredSourceIndexes
                || count($emittedSourceIndexOrder) !== count(array_unique(
                    $emittedSourceIndexOrder,
                    SORT_NUMERIC
                ))) {
                continue;
            }

            $anchorSourceIndex = $candidate['anchorSourceIndex'] ?? null;
            $continuationSourceIndex = $candidate['continuationSourceIndex'] ?? null;
            $anchor = is_int($anchorSourceIndex)
                ? ($lineItems[$anchorSourceIndex] ?? null)
                : null;
            $continuation = is_int($continuationSourceIndex)
                ? ($lineItems[$continuationSourceIndex] ?? null)
                : null;
            if (!is_array($anchor)
                || !is_array($continuation)
                || $continuationSourceIndex !== $anchorSourceIndex + 1
                || ($candidate['anchorSourceOccurrenceId'] ?? null)
                    !== ($anchor['id'] ?? null)
                || ($candidate['continuationSourceOccurrenceId'] ?? null)
                    !== ($continuation['id'] ?? null)
                || (int) ($candidate['anchorPage'] ?? 0) !== (int) ($anchor['page'] ?? 0)
                || (int) ($candidate['continuationPage'] ?? 0)
                    !== (int) ($continuation['page'] ?? 0)
                || (int) ($continuation['page'] ?? 0) !== (int) ($anchor['page'] ?? 0) + 1
                || ($candidate['anchorBounds'] ?? null)
                    !== $this->pdfSourceEvidenceBounds($anchor['sourceGeometry'])
                || ($candidate['continuationBounds'] ?? null)
                    !== $this->pdfSourceEvidenceBounds($continuation['sourceGeometry'])) {
                continue;
            }

            $contributorsBySourceIndex = [];
            $scopeBoundsByPage = [];
            foreach ($requiredSourceIndexes as $sourceIndex) {
                $item = $lineItems[$sourceIndex];
                $id = (string) $item['id'];
                $page = max(1, (int) ($item['page'] ?? 1));
                $sourceBounds = $this->pdfSourceEvidenceBounds($item['sourceGeometry']);
                if (!isset($scopeBoundsByPage[$page])) {
                    $scopeBoundsByPage[$page] = $sourceBounds;
                } else {
                    $scopeBoundsByPage[$page]['x1'] = min(
                        $scopeBoundsByPage[$page]['x1'],
                        $sourceBounds['x1']
                    );
                    $scopeBoundsByPage[$page]['y1'] = min(
                        $scopeBoundsByPage[$page]['y1'],
                        $sourceBounds['y1']
                    );
                    $scopeBoundsByPage[$page]['x2'] = max(
                        $scopeBoundsByPage[$page]['x2'],
                        $sourceBounds['x2']
                    );
                    $scopeBoundsByPage[$page]['y2'] = max(
                        $scopeBoundsByPage[$page]['y2'],
                        $sourceBounds['y2']
                    );
                }
                $existing = is_array($dispositions[$id] ?? null)
                    ? $dispositions[$id]
                    : [];
                $kind = (string) ($existing['disposition'] ?? 'emitted');
                if ($kind === 'unresolved'
                    && is_array($existing['evidence'] ?? null)
                    && in_array(
                        (string) ($existing['evidence']['requestedDisposition'] ?? ''),
                        ['emitted', 'boundary-repair', 'semantic-structure'],
                        true
                    )) {
                    $kind = (string) $existing['evidence']['requestedDisposition'];
                }
                if (!in_array($kind, ['emitted', 'boundary-repair', 'semantic-structure'], true)) {
                    continue 2;
                }
                $projection = is_string($existing['textProjection'] ?? null)
                    ? $existing['textProjection']
                    : (string) ($item['text'] ?? '');
                $significant = $this->pdfSourceOccurrenceComparableText($projection);
                if ($significant === '') {
                    if ($this->pdfDispositionHasExactSemanticStructureProof($existing)) {
                        continue;
                    }
                    continue 2;
                }
                $contributorsBySourceIndex[$sourceIndex] = [
                    'id' => $id,
                    'kind' => $kind,
                    'projection' => $projection,
                    'significant' => $significant,
                    'existing' => $existing,
                    'page' => $page,
                    'sourceBounds' => $sourceBounds,
                ];
            }
            if ($contributorsBySourceIndex === []) {
                continue;
            }
            $naturalContributors = array_values($contributorsBySourceIndex);
            $emittedContributors = [];
            foreach ($emittedSourceIndexOrder as $sourceIndex) {
                if (isset($contributorsBySourceIndex[$sourceIndex])) {
                    $emittedContributors[] = $contributorsBySourceIndex[$sourceIndex];
                }
            }
            if (count($emittedContributors) !== count($naturalContributors)) {
                continue;
            }
            $emittedProjection = implode('', array_column(
                $emittedContributors,
                'significant'
            ));
            if ($emittedProjection === ''
                || substr_count($finalProjection, $emittedProjection) !== 1) {
                continue;
            }

            $naturalIds = array_column($naturalContributors, 'id');
            $emittedIds = array_column($emittedContributors, 'id');
            $sourcePages = array_values(array_unique(array_map(
                static fn (array $contributor): int => (int) $contributor['page'],
                $naturalContributors
            ), SORT_NUMERIC));
            sort($sourcePages, SORT_NUMERIC);
            if (count($sourcePages) < 2) {
                continue;
            }
            $scopeIdentity = [
                'sourceSha256' => $this->sourceSha256,
                'candidateProofDigest' => $proofDigest,
                'sourceOccurrenceIds' => $naturalIds,
                'emittedSourceOccurrenceIds' => $emittedIds,
                'sourcePages' => $sourcePages,
                'emittedProjectionDigest' => hash('sha256', $emittedProjection),
            ];
            $scopeId = 'pdf-cross-page-list-order-scope-' . substr(hash(
                'sha256',
                json_encode(
                    $scopeIdentity,
                    JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE
                ) ?: ''
            ), 0, 32);
            $orderProof = [
                'scopeId' => $scopeId,
                'sourceOccurrenceIds' => $naturalIds,
                'emittedTextProjection' => $emittedProjection,
                'sourcePages' => $sourcePages,
                'emittedSourceOccurrenceIds' => $emittedIds,
            ];
            foreach ($naturalContributors as $contributor) {
                $id = $contributor['id'];
                $existing = $contributor['existing'];
                $existingEvidence = is_array($existing['evidence'] ?? null)
                    ? $existing['evidence']
                    : [];
                $dispositions[$id] = array_replace($existing, [
                    'disposition' => $contributor['kind'],
                    'reason' => trim((string) ($existing['reason'] ?? '')) !== ''
                        ? (string) $existing['reason']
                        : 'A signed exact cross-page open-list continuation scope proves this occurrence\'s emitted order.',
                    'evidence' => array_replace($existingEvidence, [
                        'hypothesis' => 'cross-page-open-list-continuation-order',
                        'page' => $contributor['page'],
                        'localGeometryMatch' =>
                            'complete-exact-cross-page-source-occurrence-order',
                        'bounds' => $scopeBoundsByPage[$contributor['page']],
                        'sourceBounds' => $contributor['sourceBounds'],
                        'featureDigest' => $proofDigest,
                        'crossPageListContinuationOrder' => $candidate,
                    ]),
                    'textProjection' => $contributor['projection'],
                    'allowOrderChange' => true,
                    'orderProof' => $orderProof,
                ]);
            }
            $this->sourceOrderProofDiagnostics[] = [
                'status' => 'accepted',
                'method' => 'exact-cross-page-open-list-continuation-order',
                'pages' => [
                    (int) $candidate['anchorPage'],
                    (int) $candidate['continuationPage'],
                ],
                'sourceOccurrenceCount' => count($naturalIds),
            ];
        }

        return $dispositions;
    }

    /**
     * Geometry reconstruction deliberately changes the source stream order on
     * some pages: table cells become visual rows and independently positioned
     * prose becomes reading-order blocks. Authorize that change only for an
     * exact page-local source set whose projected character inventory equals
     * the corresponding final-output slice. The source records remain
     * contiguous and every occurrence supplies its own intersecting bbox, so
     * this is a mapped local proof rather than document-wide bag matching.
     *
     * @param list<array<string,mixed>> $lineItems
     * @param list<AstNode> $blocks
     * @param array<string,array<string,mixed>> $dispositions
     * @param list<int> $geometryOrderPages
     * @param list<array<string,mixed>> $geometryOrderLayouts
     * @param array<int,array{start:int,end:int,projection:string,leafEnds:list<int>}> $finalOutputPageProofs
     * @return array<string,array<string,mixed>>
     */
    private function pdfDispositionsWithExactGeometryPageOrderProofs(
        array $lineItems,
        array $blocks,
        array &$dispositions,
        array $geometryOrderPages,
        array &$geometryOrderLayouts,
        array $finalOutputPageProofs = []
    ): array {
        $fail = function (string $reason, array $evidence = []) use (&$dispositions): array {
            $this->sourceOrderProofDiagnostics[] = ['status' => 'rejected', 'reason' => $reason] + $evidence;

            return $dispositions;
        };
        $evidencedPages = [];
        foreach ($geometryOrderPages as $page) {
            $page = (int) $page;
            if ($page > 0) {
                $evidencedPages[$page] = true;
            }
        }
        $contributorsByPage = [];
        $pageBounds = [];
        $sourceIdsByPageIndex = [];
        foreach ($lineItems as $globalSourceIndex => $item) {
            $id = is_string($item['id'] ?? null) ? $item['id'] : '';
            $text = is_string($item['text'] ?? null) ? $item['text'] : '';
            $page = max(1, (int) ($item['page'] ?? 1));
            $sourceIndex = count($sourceIdsByPageIndex[$page] ?? []);
            $sourceIdsByPageIndex[$page][$sourceIndex] = $id;
            if ($id === '' || $this->pdfSourceOccurrenceComparableText($text) === '') {
                // Keep the raw page-local index above, but do not require an
                // output edge for a Unicode spacing-only source occurrence.
                continue;
            }
            $disposition = is_array($dispositions[$id] ?? null)
                ? $dispositions[$id]
                : null;
            $kind = is_array($disposition)
                ? (string) ($disposition['disposition'] ?? 'emitted')
                : 'emitted';
            if ($kind === 'unresolved'
                && is_array($disposition['evidence'] ?? null)
                && in_array(
                    (string) ($disposition['evidence']['requestedDisposition'] ?? ''),
                    ['emitted', 'boundary-repair', 'semantic-structure'],
                    true
                )) {
                $kind = (string) $disposition['evidence']['requestedDisposition'];
            }
            if (!in_array($kind, ['emitted', 'boundary-repair', 'semantic-structure'], true)) {
                continue;
            }
            $projection = is_array($disposition)
                && is_string($disposition['textProjection'] ?? null)
                    ? $disposition['textProjection']
                    : $text;
            $significant = $this->pdfSourceOccurrenceComparableText($projection);
            if ($significant === '') {
                if (is_array($disposition)
                    && $this->pdfDispositionHasExactSemanticStructureProof($disposition)) {
                    // This source record maps to a live list/list-item edge,
                    // not to an output byte range. It is neutral to the page
                    // text permutation and is revalidated by the ledger.
                    continue;
                }
                return $fail('empty-output-disposition-projection', ['page' => $page, 'sourceOccurrenceId' => $id]);
            }
            $sourceGeometry = is_array($item['sourceGeometry'] ?? null)
                && $this->pdfSourceBoundsAreValid($item['sourceGeometry'])
                    ? $this->pdfSourceEvidenceBounds($item['sourceGeometry'])
                    : null;
            $contributorSourceIndexesByPage[$page][] = $globalSourceIndex;
            if ($sourceGeometry !== null) {
                if (!isset($pageBounds[$page])) {
                    $pageBounds[$page] = $sourceGeometry;
                } else {
                    $pageBounds[$page]['x1'] = min($pageBounds[$page]['x1'], $sourceGeometry['x1']);
                    $pageBounds[$page]['y1'] = min($pageBounds[$page]['y1'], $sourceGeometry['y1']);
                    $pageBounds[$page]['x2'] = max($pageBounds[$page]['x2'], $sourceGeometry['x2']);
                    $pageBounds[$page]['y2'] = max($pageBounds[$page]['y2'], $sourceGeometry['y2']);
                }
            }
        }
        if ($contributorSourceIndexesByPage === []) {
            return $fail('no-output-source-contributors');
        }
        ksort($contributorSourceIndexesByPage, SORT_NUMERIC);
        if ($finalOutputPageProofs === [] && count($contributorSourceIndexesByPage) === 1) {
            $page = (int) array_key_first($contributorSourceIndexesByPage);
            $wholeOutputProof = $this->pdfWholeOutputPageProof($blocks);
            if ($wholeOutputProof !== null) {
                $finalOutputPageProofs[$page] = $wholeOutputProof;
            }
        }
        $finalOutputPageProofs = $this->pdfValidatedFinalOutputPageProofs(
            $blocks,
            $finalOutputPageProofs
        );

        $pageProofs = [];
        foreach ($contributorSourceIndexesByPage as $page => $contributorSourceIndexes) {
            $contributors = [];
            foreach ($contributorSourceIndexes as $globalSourceIndex) {
                $item = $lineItems[$globalSourceIndex];
                $id = (string) $item['id'];
                $text = (string) $item['text'];
                $disposition = is_array($dispositions[$id] ?? null)
                    ? $dispositions[$id]
                    : null;
                $kind = is_array($disposition)
                    ? (string) ($disposition['disposition'] ?? 'emitted')
                    : 'emitted';
                if ($kind === 'unresolved'
                    && is_array($disposition['evidence'] ?? null)
                    && in_array(
                        (string) ($disposition['evidence']['requestedDisposition'] ?? ''),
                        ['emitted', 'boundary-repair', 'semantic-structure'],
                        true
                    )) {
                    $kind = (string) $disposition['evidence']['requestedDisposition'];
                }
                $projection = is_array($disposition)
                    && is_string($disposition['textProjection'] ?? null)
                        ? $disposition['textProjection']
                        : $text;
                $sourceGeometry = is_array($item['sourceGeometry'] ?? null)
                    && $this->pdfSourceBoundsAreValid($item['sourceGeometry'])
                        ? $this->pdfSourceEvidenceBounds($item['sourceGeometry'])
                        : null;
                $contributors[] = [
                    'id' => $id,
                    'sourceIndex' => $globalSourceIndex,
                    'kind' => $kind,
                    'projection' => $projection,
                    'significant' => $this->pdfSourceOccurrenceComparableText($projection),
                    'sourceSignificant' => $this->pdfSourceOccurrenceComparableText($text),
                    'sourceBounds' => $sourceGeometry,
                    'exactProjectionMap' => is_array($disposition)
                        ? $this->pdfCrossLaneDisplayDispositionProjectionMap(
                            $globalSourceIndex,
                            $item,
                            $disposition,
                            $lineItems
                        )
                        : null,
                ];
            }
            $hasExistingExactOrderScope = false;
            foreach ($contributors as $contributor) {
                $existingDisposition = $dispositions[$contributor['id']] ?? null;
                if (is_array($existingDisposition)
                    && is_array($existingDisposition['orderProof'] ?? null)) {
                    $hasExistingExactOrderScope = true;
                    break;
                }
            }
            $pageOutputProof = $this->pdfNormalizedOutputPageProof(
                $finalOutputPageProofs,
                (int) $page
            );
            if ($pageOutputProof === null) {
                if ($hasExistingExactOrderScope) {
                    $this->sourceOrderProofDiagnostics[] = [
                        'status' => 'trace',
                        'method' => 'page-local-geometry-order',
                        'page' => (int) $page,
                        'reason' => 'existing-exact-order-scope-retained',
                    ];
                    continue;
                }
                if (!isset($evidencedPages[(int) $page])) {
                    continue;
                }
                return $fail('page-output-projection-is-unavailable', [
                    'page' => (int) $page,
                ]);
            }
            $sourceProjection = implode('', array_column($contributors, 'significant'));
            $length = strlen($sourceProjection);
            $emittedProjection = $pageOutputProof['projection'];
            $sourceInventory = $this->pdfExactCharacterInventory($sourceProjection);
            $emittedInventory = $this->pdfExactCharacterInventory($emittedProjection);
            if ($sourceInventory !== $emittedInventory) {
                $inventoryDelta = $this->pdfExactCharacterInventoryDelta(
                    $sourceInventory,
                    $emittedInventory
                );
                return $fail('page-projection-character-inventory-mismatch', [
                    'page' => (int) $page,
                    'sourceBytes' => $length,
                    'emittedBytes' => strlen($emittedProjection),
                    'sourceSha256' => hash('sha256', $sourceProjection),
                    'emittedSha256' => hash('sha256', $emittedProjection),
                    'sourceOnlyCharacterCounts' => $inventoryDelta['leftOnly'],
                    'emittedOnlyCharacterCounts' => $inventoryDelta['rightOnly'],
                ]);
            }
            $pageLeafEnds = array_fill_keys($pageOutputProof['leafEnds'], true);
            if (!isset($pageLeafEnds[strlen($emittedProjection)])) {
                // A paragraph may legitimately continue across a PDF page.
                // The page-local proof below still has to reconstruct every
                // projected source byte in exact emitted order; an AST leaf
                // boundary is only a preferred occurrence tie-breaker, not
                // authority for the page permutation itself.
                $this->sourceOrderProofDiagnostics[] = [
                    'status' => 'trace',
                    'method' => 'page-local-geometry-order',
                    'page' => (int) $page,
                    'reason' => 'page-boundary-inside-final-output-leaf',
                    'sourceBytes' => $length,
                ];
            }
            if (hash_equals($sourceProjection, $emittedProjection)) {
                continue;
            }
            if ($hasExistingExactOrderScope) {
                $this->sourceOrderProofDiagnostics[] = [
                    'status' => 'trace',
                    'method' => 'page-local-geometry-order',
                    'page' => (int) $page,
                    'reason' => 'existing-exact-order-scope-retained',
                ];
                continue;
            }
            if (!isset($pageBounds[$page])) {
                return $fail('changed-page-has-no-exact-source-geometry', ['page' => (int) $page]);
            }
            foreach ($contributors as $contributor) {
                if (!is_array($contributor['sourceBounds'] ?? null)) {
                    return $fail('changed-page-source-occurrence-has-no-exact-geometry', [
                        'page' => (int) $page,
                        'sourceOccurrenceId' => $contributor['id'] ?? null,
                    ]);
                }
            }
            $sourceIds = array_column($contributors, 'id');
            $emittedSourceRanges = $this->pdfExactLayoutEmittedSourceRangeOrder(
                (int) $page,
                $emittedProjection,
                $contributors,
                $geometryOrderLayouts
            );
            $emittedSourceIds = null;
            $hasPositionedSourceRangeEvidence = $this->pdfPageHasExactPositionedSourceRangeEvidence(
                (int) $page,
                $geometryOrderLayouts
            );
            $geometryEvidenceMethod = $emittedSourceRanges !== null
                ? 'complete-exact-positioned-source-range-order'
                : null;
            if ($emittedSourceRanges === null) {
                $emittedSourceIds = $this->pdfExactLayoutEmittedSourceOccurrenceOrder(
                    (int) $page,
                    $emittedProjection,
                    $contributors,
                    $sourceIdsByPageIndex[(int) $page] ?? [],
                    $geometryOrderLayouts
                );
                if ($emittedSourceIds !== null) {
                    $geometryEvidenceMethod = 'complete-exact-positioned-source-occurrence-order';
                }
            }
            if ($emittedSourceRanges === null
                && $emittedSourceIds === null
                && !isset($evidencedPages[(int) $page])) {
                $emittedSourceIds = $this->pdfExactRowMajorGeometryOccurrenceOrder(
                    $emittedProjection,
                    $contributors
                );
                if ($emittedSourceIds !== null) {
                    $geometryEvidenceMethod = 'complete-exact-row-major-source-geometry-order';
                }
            }
            if ($emittedSourceRanges === null && $emittedSourceIds === null) {
                $emittedSourceIds = $this->pdfUniqueExactEmittedSourceOccurrenceOrder(
                $emittedProjection,
                $contributors,
                $pageLeafEnds
                );
                if ($emittedSourceIds !== null
                    && !isset($evidencedPages[(int) $page])
                    && $hasPositionedSourceRangeEvidence) {
                    $geometryEvidenceMethod =
                        'partial-exact-positioned-ranges-plus-unique-occurrence-order';
                }
            }
            if ($emittedSourceRanges === null && $emittedSourceIds === null) {
                // A geometry cell may join several adjacent source-stream
                // fragments into one AST text leaf. Accept that only when the
                // complete occurrence permutation is still unique without
                // using the leaf boundary as a tie breaker.
                $emittedSourceIds = $this->pdfUniqueExactEmittedSourceOccurrenceOrder(
                    $emittedProjection,
                    $contributors,
                    []
                );
                if ($emittedSourceIds !== null
                    && !isset($evidencedPages[(int) $page])
                    && $hasPositionedSourceRangeEvidence) {
                    $geometryEvidenceMethod =
                        'partial-exact-positioned-ranges-plus-unique-occurrence-order';
                }
            }
            if ($emittedSourceRanges === null && $emittedSourceIds === null) {
                // Repeated equal values have two textually indistinguishable
                // permutations. Resolve only when the occurrence bboxes
                // themselves produce the exact final row-major projection.
                $emittedSourceIds = $this->pdfExactRowMajorGeometryOccurrenceOrder(
                    $emittedProjection,
                    $contributors
                );
                if ($emittedSourceIds !== null) {
                    $geometryEvidenceMethod = 'complete-exact-row-major-source-geometry-order';
                }
            }
            $tokenInterleaving = false;
            if ($emittedSourceRanges === null && $emittedSourceIds === null) {
                // A single painted baseline can contain fragments from two
                // columns, so one source occurrence may contribute several
                // separated output ranges. Use the ledger's bounded exact
                // token solver and proceed only when it proves one complete
                // interleaving; inventory equality by itself is insufficient.
                $sourceOccurrenceProjections = [];
                foreach ($contributors as $contributor) {
                    $sourceOccurrenceProjections[$contributor['id']] = $contributor['significant'];
                }
                $tokenInterleaving = PdfSourceTokenInterleavingValidator::hasUniqueTokenInterleavingOrderProof(
                    $sourceOccurrenceProjections,
                    $emittedProjection
                );
                if (!$tokenInterleaving) {
                    if (!isset($evidencedPages[(int) $page]) && $geometryEvidenceMethod === null) {
                        return $fail('changed-page-has-no-selected-or-exact-range-geometry-evidence', [
                            'page' => (int) $page,
                        ]);
                    }
                    return $fail('changed-page-has-no-unique-occurrence-or-token-output-order', [
                        'page' => (int) $page,
                        'sourceOccurrenceCount' => count($contributors),
                    ]);
                }
                $this->sourceOrderProofDiagnostics[] = [
                    'status' => 'trace',
                    'method' => 'unique-token-interleaving-output-order',
                    'page' => (int) $page,
                    'sourceOccurrenceCount' => count($contributors),
                ];
                if (!isset($evidencedPages[(int) $page])
                    && $hasPositionedSourceRangeEvidence) {
                    $geometryEvidenceMethod =
                        'partial-exact-positioned-ranges-plus-unique-token-interleaving';
                }
            }
            if (!isset($evidencedPages[(int) $page]) && $geometryEvidenceMethod === null) {
                return $fail('changed-page-has-no-selected-or-exact-range-geometry-evidence', [
                    'page' => (int) $page,
                ]);
            }
            $proofIdentity = [
                'sourceSha256' => $this->sourceSha256,
                'page' => (int) $page,
                'bounds' => $pageBounds[$page],
                'sourceOccurrenceIds' => $sourceIds,
                'emittedProjectionSha256' => hash('sha256', $emittedProjection),
                'mappingMethod' => $emittedSourceRanges !== null
                    ? 'exact-positioned-source-subrange-order'
                    : ($tokenInterleaving
                        ? 'unique-token-interleaving'
                        : 'whole-source-occurrence-order'),
            ];
            $encoded = json_encode(
                $proofIdentity,
                JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_PRESERVE_ZERO_FRACTION
            );
            $proof = [
                'scopeId' => 'pdf-page-order-scope-' . substr(hash(
                    'sha256',
                    is_string($encoded) ? $encoded : serialize($proofIdentity)
                ), 0, 32),
                'sourceOccurrenceIds' => $sourceIds,
                'emittedTextProjection' => $emittedProjection,
            ];
            if ($emittedSourceIds !== null) {
                $proof['emittedSourceOccurrenceIds'] = $emittedSourceIds;
            }
            if ($emittedSourceRanges !== null) {
                $proof['emittedSourceRanges'] = $emittedSourceRanges;
            }
            $pageProofs[(int) $page] = [
                'proof' => $proof,
                'bounds' => $pageBounds[$page],
                'contributorSourceIndexes' => array_column($contributors, 'sourceIndex'),
                'geometryEvidenceMethod' => $geometryEvidenceMethod
                    ?? 'selected-geometry-order-page',
            ];
        }
        if ($pageProofs === []) {
            return $fail('no-changed-page-output-projection-required');
        }

        $acceptedPages = array_keys($pageProofs);
        // Every page-order decision is now captured by the compact immutable
        // proof records. The complete enriched layout graph is not read while
        // those records are copied into dispositions, so surrender the
        // caller-owned workset before that final append phase.
        $geometryOrderLayouts = [];
        unset(
            $contributorSourceIndexesByPage,
            $sourceIdsByPageIndex,
            $pageBounds,
            $finalOutputPageProofs,
            $contributors,
            $contributor,
            $pageOutputProof,
            $sourceProjection,
            $sourceInventory,
            $emittedInventory,
            $pageLeafEnds,
            $sourceOccurrenceProjections,
            $fail
        );
        $this->releaseTransientPdfMemory();
        foreach ($pageProofs as $page => $pageProof) {
            foreach ($pageProof['contributorSourceIndexes'] as $globalSourceIndex) {
                $item = $lineItems[$globalSourceIndex];
                $id = (string) $item['id'];
                $existing = is_array($dispositions[$id] ?? null)
                    ? $dispositions[$id]
                    : [];
                $existingEvidence = is_array($existing['evidence'] ?? null)
                    ? $existing['evidence']
                    : [];
                $kind = (string) ($existing['disposition'] ?? 'emitted');
                if ($kind === 'unresolved'
                    && is_array($existing['evidence'] ?? null)
                    && in_array(
                        (string) ($existing['evidence']['requestedDisposition'] ?? ''),
                        ['emitted', 'boundary-repair', 'semantic-structure'],
                        true
                    )) {
                    $kind = (string) $existing['evidence']['requestedDisposition'];
                }
                $projection = is_string($existing['textProjection'] ?? null)
                    ? $existing['textProjection']
                    : (string) $item['text'];
                $sourceBounds = $this->pdfSourceEvidenceBounds($item['sourceGeometry']);
                $kind = $kind === 'emitted'
                    ? 'boundary-repair'
                    : $kind;
                $dispositions[$id] = array_replace($existing, [
                    'disposition' => $kind,
                    'reason' => 'Exact source occurrence geometry maps this page-local item to the selected visual-order output.',
                    'evidence' => $existingEvidence + [
                        'hypothesis' => 'page-local-geometry-order',
                        'page' => $page,
                        'bounds' => $pageProof['bounds'],
                        'sourceBounds' => $sourceBounds,
                        'featureDigest' => hash(
                            'sha256',
                            'page-local-geometry-order\0' . $page . '\0' . $this->sourceSha256
                        ),
                        'localGeometryMatch' => $pageProof['geometryEvidenceMethod'],
                    ],
                    'textProjection' => $projection,
                    'allowOrderChange' => true,
                    'orderProof' => $pageProof['proof'],
                ]);
            }
            unset($pageProofs[$page]);
        }
        unset(
            $pageProofs,
            $pageProof,
            $item,
            $existing,
            $existingEvidence,
            $sourceBounds
        );

        $this->sourceOrderProofDiagnostics[] = [
            'status' => 'accepted',
            'method' => 'page-local-geometry-order',
            'pages' => $acceptedPages,
        ];

        return $dispositions;
    }

    /** @param list<string> $leaves */
    private function appendPdfSourceBindingLeafText(AstNode $node, array &$leaves): void
    {
        if ($node->children === []) {
            $significant = $this->pdfSourceOccurrenceComparableText(
                (string) $node->attr('text', '')
            );
            if ($significant !== '') {
                $leaves[] = $significant;
            }

            return;
        }
        foreach ($node->children as $child) {
            $this->appendPdfSourceBindingLeafText($child, $leaves);
        }
    }

    /** @param list<AstNode> $blocks */
    private function pdfSignificantProjectionFromBlocks(array $blocks): string
    {
        $leaves = [];
        foreach ($blocks as $block) {
            $this->appendPdfSourceBindingLeafText($block, $leaves);
        }

        return implode('', $leaves);
    }

    /**
     * Structural alternatives may reorder or regroup text, but neither may
     * invent nor drop a significant visible character.  Leaf traversal avoids
     * counting the redundant `text` attribute on containers as a second copy.
     *
     * @param list<AstNode> $left
     * @param list<AstNode> $right
     */
    private function pdfAstBlocksHaveEqualSignificantCharacterInventory(
        array $left,
        array $right
    ): bool {
        $projection = static function (PdfReader $reader, array $blocks): string {
            $leaves = [];
            foreach ($blocks as $block) {
                if ($block instanceof AstNode) {
                    $reader->appendPdfSourceBindingLeafText($block, $leaves);
                }
            }

            return implode('', $leaves);
        };

        return $this->pdfExactCharacterInventory($projection($this, $left))
            === $this->pdfExactCharacterInventory($projection($this, $right));
    }

    /**
     * Consume the exact page/stream character provenance retained on
     * positioned visual lines. Unlike the whole-occurrence proof below, one
     * source record may contribute several separated ranges when a content
     * stream painted parallel columns on the same baseline. Every source byte
     * must appear exactly once and the declared visual-order concatenation
     * must equal the final page projection byte for byte.
     *
     * @param list<array{
     *     id:string,
     *     sourceIndex:int,
     *     significant:string,
     *     sourceSignificant:string,
     *     exactProjectionMap?:list<array{
     *         sourceStart:int,
     *         sourceEnd:int,
     *         projectionStart:int,
     *         projectionEnd:int
     *     }>|null
     * }> $contributors
     * @param list<array<string,mixed>> $layouts
     * @return list<array{sourceOccurrenceId:string,sourceStart:int,sourceEnd:int}>|null
     */
    private function pdfExactLayoutEmittedSourceRangeOrder(
        int $page,
        string $emittedProjection,
        array $contributors,
        array $layouts
    ): ?array {
        $contributorsBySourceIndex = [];
        foreach ($contributors as $contributor) {
            $sourceIndex = $contributor['sourceIndex'] ?? null;
            if (!is_int($sourceIndex) || isset($contributorsBySourceIndex[$sourceIndex])) {
                return null;
            }
            $contributorsBySourceIndex[$sourceIndex] = $contributor;
        }

        $orderedRanges = [];
        foreach ($layouts as $layout) {
            if (max(1, (int) ($layout['page'] ?? 1)) !== $page) {
                continue;
            }
            foreach ($this->pdfPositionedExactSourceRanges($layout) as $range) {
                if (!isset($contributorsBySourceIndex[$range['sourceIndex']])) {
                    continue;
                }
                $lastIndex = array_key_last($orderedRanges);
                if ($lastIndex !== null
                    && $orderedRanges[$lastIndex]['sourceIndex'] === $range['sourceIndex']
                    && $orderedRanges[$lastIndex]['sourceEnd'] === $range['sourceStart']) {
                    $orderedRanges[$lastIndex]['sourceEnd'] = $range['sourceEnd'];
                    continue;
                }
                $orderedRanges[] = $range;
            }
        }
        if ($orderedRanges === []) {
            $this->sourceOrderProofDiagnostics[] = [
                'status' => 'trace',
                'method' => 'exact-positioned-source-subrange-order',
                'page' => $page,
                'mappedSourceRangeCount' => 0,
                'sourceOccurrenceCount' => count($contributors),
            ];

            return null;
        }

        $coverageBySourceIndex = [];
        foreach ($orderedRanges as $range) {
            $contributor = $contributorsBySourceIndex[$range['sourceIndex']];
            $sourceSignificant = (string) ($contributor['sourceSignificant'] ?? '');
            if ($sourceSignificant === ''
                || $range['sourceStart'] < 0
                || $range['sourceEnd'] <= $range['sourceStart']
                || $range['sourceEnd'] > strlen($sourceSignificant)) {
                $this->sourceOrderProofDiagnostics[] = [
                    'status' => 'trace',
                    'method' => 'exact-positioned-source-subrange-order',
                    'page' => $page,
                    'failureReason' => 'positioned-source-range-is-outside-occurrence',
                    'sourceOccurrenceId' => $contributor['id'] ?? null,
                ];
                return null;
            }
            $coverageBySourceIndex[$range['sourceIndex']][] = [
                'start' => $range['sourceStart'],
                'end' => $range['sourceEnd'],
            ];
        }
        $projectionMapsBySourceIndex = [];
        foreach ($contributorsBySourceIndex as $sourceIndex => $contributor) {
            $sourceSignificant = (string) ($contributor['sourceSignificant'] ?? '');
            $significant = (string) ($contributor['significant'] ?? '');
            if ($sourceSignificant === '') {
                $this->sourceOrderProofDiagnostics[] = [
                    'status' => 'trace',
                    'method' => 'exact-positioned-source-subrange-order',
                    'page' => $page,
                    'mappedSourceRangeCount' => count($orderedRanges),
                    'sourceOccurrenceCount' => count($contributors),
                    'sourceProjectionMatchesDisposition' => false,
                    'sourceOccurrenceId' => $contributor['id'] ?? null,
                ];

                return null;
            }
            $coverage = $coverageBySourceIndex[$sourceIndex] ?? [];
            usort($coverage, static fn (array $left, array $right): int =>
                ($left['start'] <=> $right['start']) ?: ($left['end'] <=> $right['end'])
            );
            $cursor = null;
            foreach ($coverage as $range) {
                if (($cursor !== null && $range['start'] < $cursor)
                    || $range['end'] <= $range['start']) {
                    $this->sourceOrderProofDiagnostics[] = [
                        'status' => 'trace',
                        'method' => 'exact-positioned-source-subrange-order',
                        'page' => $page,
                        'failureReason' => 'positioned-source-ranges-overlap-within-occurrence',
                        'sourceOccurrenceId' => $contributor['id'] ?? null,
                        'previousSourceEnd' => $cursor,
                        'actualSourceStart' => $range['start'],
                    ];
                    return null;
                }
                $cursor = $range['end'];
            }

            // Unchanged source occurrences need no character edit matrix.
            // Exact, gap-free range coverage is the equivalent identity map,
            // and an empty internal map lets the ordered-range pass below
            // project those byte offsets directly. This avoids retaining one
            // four-field PHP array per character for ordinary PDF prose.
            if (hash_equals($sourceSignificant, $significant)) {
                $coverageCursor = 0;
                foreach ($coverage as $range) {
                    if ($range['start'] !== $coverageCursor) {
                        $this->sourceOrderProofDiagnostics[] = [
                            'status' => 'trace',
                            'method' => 'exact-positioned-source-subrange-order',
                            'page' => $page,
                            'failureReason' => 'identity-source-range-coverage-has-gap',
                            'sourceOccurrenceId' => $contributor['id'] ?? null,
                            'expectedSourceStart' => $coverageCursor,
                            'actualSourceStart' => $range['start'],
                        ];

                        return null;
                    }
                    $coverageCursor = $range['end'];
                }
                if ($coverageCursor !== strlen($sourceSignificant)) {
                    $this->sourceOrderProofDiagnostics[] = [
                        'status' => 'trace',
                        'method' => 'exact-positioned-source-subrange-order',
                        'page' => $page,
                        'failureReason' => 'identity-source-range-coverage-is-incomplete',
                        'sourceOccurrenceId' => $contributor['id'] ?? null,
                        'expectedSourceEnd' => strlen($sourceSignificant),
                        'actualSourceEnd' => $coverageCursor,
                    ];

                    return null;
                }
                $projectionMapsBySourceIndex[$sourceIndex] = [];
                continue;
            }

            $projectionMap = is_array($contributor['exactProjectionMap'] ?? null)
                ? $contributor['exactProjectionMap']
                : $this->pdfUniqueSourceProjectionEditMap(
                    $sourceSignificant,
                    $significant
                );
            if ($projectionMap === null) {
                $this->sourceOrderProofDiagnostics[] = [
                    'status' => 'trace',
                    'method' => 'exact-positioned-source-subrange-order',
                    'page' => $page,
                    'mappedSourceRangeCount' => count($orderedRanges),
                    'sourceOccurrenceCount' => count($contributors),
                    'sourceProjectionMatchesDisposition' => false,
                    'sourceOccurrenceId' => $contributor['id'] ?? null,
                ];

                return null;
            }
            $projectionMapsBySourceIndex[$sourceIndex] = $projectionMap;
            foreach ($projectionMap as $mappedCharacter) {
                $coveringRangeCount = 0;
                foreach ($coverage as $range) {
                    if ($range['start'] <= $mappedCharacter['sourceStart']
                        && $range['end'] >= $mappedCharacter['sourceEnd']) {
                        $coveringRangeCount++;
                    }
                }
                if ($coveringRangeCount !== 1) {
                    $this->sourceOrderProofDiagnostics[] = [
                        'status' => 'trace',
                        'method' => 'exact-positioned-source-subrange-order',
                        'page' => $page,
                        'failureReason' => 'projected-character-has-no-unique-positioned-source-range',
                        'sourceOccurrenceId' => $contributor['id'] ?? null,
                        'coveringRangeCount' => $coveringRangeCount,
                    ];
                    return null;
                }
            }
        }

        $projection = '';
        $declaredRanges = [];
        foreach ($orderedRanges as $range) {
            $contributor = $contributorsBySourceIndex[$range['sourceIndex']];
            $projectionMap = $projectionMapsBySourceIndex[$range['sourceIndex']];
            if ($projectionMap === []) {
                $projection .= substr(
                    (string) $contributor['significant'],
                    $range['sourceStart'],
                    $range['sourceEnd'] - $range['sourceStart']
                );
                $declaredRanges[] = [
                    'sourceOccurrenceId' => (string) $contributor['id'],
                    'sourceStart' => $range['sourceStart'],
                    'sourceEnd' => $range['sourceEnd'],
                ];
                continue;
            }
            $projectedRanges = [];
            foreach ($projectionMap as $mappedCharacter) {
                if ($mappedCharacter['sourceStart'] < $range['sourceStart']
                    || $mappedCharacter['sourceEnd'] > $range['sourceEnd']) {
                    continue;
                }
                $lastIndex = array_key_last($projectedRanges);
                if ($lastIndex !== null
                    && $projectedRanges[$lastIndex]['end'] === $mappedCharacter['projectionStart']) {
                    $projectedRanges[$lastIndex]['end'] = $mappedCharacter['projectionEnd'];
                    continue;
                }
                $projectedRanges[] = [
                    'start' => $mappedCharacter['projectionStart'],
                    'end' => $mappedCharacter['projectionEnd'],
                ];
            }
            foreach ($projectedRanges as $projectedRange) {
                $projection .= substr(
                    (string) $contributor['significant'],
                    $projectedRange['start'],
                    $projectedRange['end'] - $projectedRange['start']
                );
                $declaredRanges[] = [
                    'sourceOccurrenceId' => (string) $contributor['id'],
                    'sourceStart' => $projectedRange['start'],
                    'sourceEnd' => $projectedRange['end'],
                ];
            }
        }
        $matches = hash_equals($emittedProjection, $projection);
        $this->sourceOrderProofDiagnostics[] = [
            'status' => 'trace',
            'method' => 'exact-positioned-source-subrange-order',
            'page' => $page,
            'mappedSourceRangeCount' => count($declaredRanges),
            'sourceOccurrenceCount' => count($contributors),
            'projectionMatches' => $matches,
            'projectionSha256' => hash('sha256', $projection),
            'emittedSha256' => hash('sha256', $emittedProjection),
        ];

        return $matches ? $declaredRanges : null;
    }

    /**
     * Map every projected Unicode code point to its sole source character or
     * boundary under a unique minimum edit script. This carries already
     * authorized occurrence-local transformations (for example a removed list
     * marker or a discretionary-hyphen replacement) across a positioned range
     * boundary without turning the spelling into a document-wide rule. More
     * than one optimal edit path remains ambiguous and is rejected.
     *
     * @return list<array{sourceStart:int,sourceEnd:int,projectionStart:int,projectionEnd:int}>|null
     */
    private function pdfUniqueSourceProjectionEditMap(
        string $source,
        string $projection
    ): ?array {
        if ($source === '' || $projection === '') {
            return null;
        }
        $sourceMatched = preg_match_all('/./us', $source, $sourceMatches, PREG_OFFSET_CAPTURE);
        $projectionMatched = preg_match_all('/./us', $projection, $projectionMatches, PREG_OFFSET_CAPTURE);
        if ($sourceMatched === false
            || $projectionMatched === false
            || $sourceMatched === 0
            || $projectionMatched === 0) {
            return null;
        }

        $sourceCharacters = $sourceMatches[0];
        $projectionCharacters = $projectionMatches[0];
        $sourceCount = count($sourceCharacters);
        $projectionCount = count($projectionCharacters);
        if ($sourceCount > 0xffff
            || $projectionCount > 0xffff
            || $sourceCount * $projectionCount > 250000) {
            return null;
        }

        // PHP integer matrices spend a hash bucket and zval per edit cell;
        // even a modest paragraph can therefore consume several MiB while
        // the document proof graph is live. Distances here are bounded by the
        // 16-bit character-count guard above, so store each row as unsigned
        // network-order words and retain the exact same dynamic program.
        $firstRow = '';
        for ($projectionIndex = 0; $projectionIndex <= $projectionCount; $projectionIndex++) {
            $firstRow .= pack('n', $projectionIndex);
        }
        $distance = [$firstRow];
        for ($sourceIndex = 1; $sourceIndex <= $sourceCount; $sourceIndex++) {
            $previousRow = $distance[$sourceIndex - 1];
            $row = pack('n', $sourceIndex);
            $leftDistance = $sourceIndex;
            for ($projectionIndex = 1; $projectionIndex <= $projectionCount; $projectionIndex++) {
                $substitutionCost = $sourceCharacters[$sourceIndex - 1][0]
                    === $projectionCharacters[$projectionIndex - 1][0]
                        ? 0
                        : 1;
                $previousOffset = $projectionIndex * 2;
                $upperDistance = (ord($previousRow[$previousOffset]) << 8)
                    | ord($previousRow[$previousOffset + 1]);
                $diagonalOffset = ($projectionIndex - 1) * 2;
                $diagonalDistance = (ord($previousRow[$diagonalOffset]) << 8)
                    | ord($previousRow[$diagonalOffset + 1]);
                $cellDistance = min(
                    $upperDistance + 1,
                    $leftDistance + 1,
                    $diagonalDistance + $substitutionCost
                );
                $row .= pack('n', $cellDistance);
                $leftDistance = $cellDistance;
            }
            $distance[$sourceIndex] = $row;
        }
        unset($firstRow, $previousRow, $row);

        $distanceAt = static function (array &$rows, int $source, int $projection): int {
            $offset = $projection * 2;

            return (ord($rows[$source][$offset]) << 8)
                | ord($rows[$source][$offset + 1]);
        };

        $mapped = [];
        $sourceIndex = $sourceCount;
        $projectionIndex = $projectionCount;
        while ($sourceIndex > 0 || $projectionIndex > 0) {
            $choices = [];
            if ($sourceIndex > 0 && $projectionIndex > 0) {
                $cost = $sourceCharacters[$sourceIndex - 1][0]
                    === $projectionCharacters[$projectionIndex - 1][0]
                        ? 0
                        : 1;
                if ($distanceAt($distance, $sourceIndex, $projectionIndex)
                    === $distanceAt(
                        $distance,
                        $sourceIndex - 1,
                        $projectionIndex - 1
                    ) + $cost) {
                    $choices[] = 'diagonal';
                }
            }
            if ($sourceIndex > 0
                && $distanceAt($distance, $sourceIndex, $projectionIndex)
                    === $distanceAt(
                        $distance,
                        $sourceIndex - 1,
                        $projectionIndex
                    ) + 1) {
                $choices[] = 'delete';
            }
            if ($projectionIndex > 0
                && $distanceAt($distance, $sourceIndex, $projectionIndex)
                    === $distanceAt(
                        $distance,
                        $sourceIndex,
                        $projectionIndex - 1
                    ) + 1) {
                $choices[] = 'insert';
            }
            if (count($choices) !== 1) {
                return null;
            }
            if ($choices[0] === 'delete') {
                $sourceIndex--;
                continue;
            }

            [$projectionCharacter, $projectionStart] = $projectionCharacters[$projectionIndex - 1];
            if ($choices[0] === 'diagonal') {
                [$sourceCharacter, $sourceStart] = $sourceCharacters[$sourceIndex - 1];
                $mapped[] = [
                    'sourceStart' => (int) $sourceStart,
                    'sourceEnd' => (int) $sourceStart + strlen((string) $sourceCharacter),
                    'projectionStart' => (int) $projectionStart,
                    'projectionEnd' => (int) $projectionStart + strlen((string) $projectionCharacter),
                ];
                $sourceIndex--;
                $projectionIndex--;
                continue;
            }

            $anchorIndex = $sourceIndex < $sourceCount
                ? $sourceIndex
                : $sourceIndex - 1;
            if (!isset($sourceCharacters[$anchorIndex])) {
                return null;
            }
            [$anchorCharacter, $anchorStart] = $sourceCharacters[$anchorIndex];
            $mapped[] = [
                'sourceStart' => (int) $anchorStart,
                'sourceEnd' => (int) $anchorStart + strlen((string) $anchorCharacter),
                'projectionStart' => (int) $projectionStart,
                'projectionEnd' => (int) $projectionStart + strlen((string) $projectionCharacter),
            ];
            $projectionIndex--;
        }

        usort($mapped, static fn (array $left, array $right): int =>
            ($left['projectionStart'] <=> $right['projectionStart'])
                ?: ($left['projectionEnd'] <=> $right['projectionEnd'])
        );

        return $mapped;
    }

    /**
     * The source/positioned reconciliation retains page-local source indexes
     * on every geometry-selected layout item. Consume those occurrence IDs in
     * final visual order and accept them only when their complete projection
     * equals the emitted page byte-for-byte.
     *
     * @param list<array{id:string,significant:string}> $contributors
     * @param array<int,string> $sourceIdsByIndex
     * @param list<array<string,mixed>> $layouts
     * @return list<string>|null
     */
    private function pdfExactLayoutEmittedSourceOccurrenceOrder(
        int $page,
        string $emittedProjection,
        array $contributors,
        array $sourceIdsByIndex,
        array $layouts
    ): ?array {
        $contributorsById = [];
        foreach ($contributors as $contributor) {
            $contributorsById[$contributor['id']] = $contributor;
        }
        $order = [];
        $seen = [];
        foreach ($layouts as $layout) {
            if (max(1, (int) ($layout['page'] ?? 1)) !== $page) {
                continue;
            }
            $indexes = [];
            if (is_array($layout['sourcePdfSourceIndexes'] ?? null)) {
                foreach ($layout['sourcePdfSourceIndexes'] as $sourceIndex) {
                    if (is_int($sourceIndex) || (is_string($sourceIndex) && ctype_digit($sourceIndex))) {
                        $indexes[] = (int) $sourceIndex;
                    }
                }
            } elseif (isset($layout['sourcePdfSourceIndex'])) {
                $start = (int) $layout['sourcePdfSourceIndex'];
                $end = max($start, (int) ($layout['sourcePdfSourceIndexEnd'] ?? $start));
                for ($sourceIndex = $start; $sourceIndex <= $end; $sourceIndex++) {
                    $indexes[] = $sourceIndex;
                }
            }
            foreach ($indexes as $sourceIndex) {
                $id = $sourceIdsByIndex[$sourceIndex] ?? null;
                if (!is_string($id) || !isset($contributorsById[$id]) || isset($seen[$id])) {
                    continue;
                }
                $seen[$id] = true;
                $order[] = $id;
            }
        }
        if (count($order) !== count($contributors)) {
            $this->sourceOrderProofDiagnostics[] = [
                'status' => 'trace',
                'method' => 'layout-source-occurrence-order',
                'page' => $page,
                'mappedOccurrenceCount' => count($order),
                'sourceOccurrenceCount' => count($contributors),
            ];
            return null;
        }
        $projection = '';
        foreach ($order as $id) {
            $projection .= $contributorsById[$id]['significant'];
        }

        if (hash_equals($emittedProjection, $projection)) {
            return $order;
        }
        $this->sourceOrderProofDiagnostics[] = [
            'status' => 'trace',
            'method' => 'layout-source-occurrence-order',
            'page' => $page,
            'mappedOccurrenceCount' => count($order),
            'sourceOccurrenceCount' => count($contributors),
            'projectionMatches' => false,
            'projectionSha256' => hash('sha256', $projection),
            'emittedSha256' => hash('sha256', $emittedProjection),
        ];

        return null;
    }

    /**
     * Resolve a geometry scope to whole source occurrences, preferring real
     * AST text-leaf boundaries. Requiring one complete permutation prevents a
     * digit run such as adjacent table cells `1`, `10`, and `100` from being
     * segmented according to spelling alone. A caller may retry without leaf
     * boundaries for one final leaf composed from several source fragments.
     *
     * @param list<array{id:string,significant:string}> $contributors
     * @param array<int,true> $leafEnds
     * @return list<string>|null
     */
    private function pdfUniqueExactEmittedSourceOccurrenceOrder(
        string $emittedProjection,
        array $contributors,
        array $leafEnds
    ): ?array {
        $recordsByText = [];
        foreach ($contributors as $index => $contributor) {
            $id = is_string($contributor['id'] ?? null) ? $contributor['id'] : '';
            $significant = is_string($contributor['significant'] ?? null)
                ? $contributor['significant']
                : '';
            if ($id === '' || $significant === '') {
                return null;
            }
            $recordsByText['s:' . $significant][] = $contributor + ['_sourceIndex' => $index];
        }

        $solutionCount = 0;
        $solutions = [];
        $candidateCount = 0;
        $solutionLimitExceeded = false;
        $remainingCounts = [];
        foreach ($recordsByText as $textKey => $records) {
            $remainingCounts[$textKey] = count($records);
        }
        $order = [];
        // Most exact page permutations have one possible source spelling at
        // every emitted cursor. Resolve that deterministic path iteratively;
        // a hundred ordinary source rows should not require a hundred nested
        // PHP call frames. Only a genuine textual branch enters backtracking.
        $greedyCounts = $remainingCounts;
        $greedyOrder = [];
        $greedyCursor = 0;
        $greedyAmbiguous = false;
        $greedyDeadEnd = false;
        for ($remainingTotal = count($contributors); $remainingTotal > 0; $remainingTotal--) {
            $matchingKey = null;
            foreach ($greedyCounts as $textKey => $count) {
                if ($count <= 0) {
                    continue;
                }
                $text = substr((string) $textKey, 2);
                $end = $greedyCursor + strlen($text);
                if (($leafEnds !== [] && !isset($leafEnds[$end]))
                    || !hash_equals(
                        $text,
                        substr($emittedProjection, $greedyCursor, strlen($text))
                    )) {
                    continue;
                }
                if ($matchingKey !== null) {
                    $greedyAmbiguous = true;
                    break 2;
                }
                $matchingKey = $textKey;
            }
            if ($matchingKey === null) {
                $greedyDeadEnd = true;
                break;
            }
            $candidateCount++;
            $greedyCounts[$matchingKey]--;
            $greedyOrder[] = $matchingKey;
            $greedyCursor += strlen(substr((string) $matchingKey, 2));
        }
        if (!$greedyAmbiguous
            && !$greedyDeadEnd
            && $greedyCursor === strlen($emittedProjection)
            && count($greedyOrder) === count($contributors)) {
            $solutionCount = 1;
            $solutions[] = $greedyOrder;
        }
        unset($greedyCounts, $greedyOrder);

        $matchingKeysAt = function (int $cursor) use (
            &$remainingCounts,
            $emittedProjection,
            $leafEnds
        ): array {
            $matches = [];
            foreach ($remainingCounts as $textKey => $count) {
                if ($count <= 0) {
                    continue;
                }
                $text = substr((string) $textKey, 2);
                $end = $cursor + strlen($text);
                if (($leafEnds !== [] && !isset($leafEnds[$end]))
                    || !hash_equals($text, substr($emittedProjection, $cursor, strlen($text)))) {
                    continue;
                }
                $matches[] = $textKey;
            }

            return $matches;
        };
        if ($solutionCount === 0 && $greedyAmbiguous) {
            $candidateCount = 0;
            // Explicit depth-first frames preserve the recursive search order
            // and limits without retaining one PHP VM frame per source row.
            $stack = [[
                'cursor' => 0,
                'remainingTotal' => count($contributors),
                'choices' => $matchingKeysAt(0),
                'nextChoice' => 0,
                'arrivalKey' => null,
            ]];
            while ($stack !== []
                && !$solutionLimitExceeded
                && $candidateCount <= 100000) {
                $frameIndex = array_key_last($stack);
                if ($frameIndex === null) {
                    break;
                }
                $frame = $stack[$frameIndex];
                if ($frame['remainingTotal'] === 0) {
                    if ($frame['cursor'] === strlen($emittedProjection)) {
                        $solutionCount++;
                        $solutions[] = $order;
                        if ($solutionCount >= 64) {
                            $solutionLimitExceeded = true;
                        }
                    }
                    array_pop($stack);
                    $arrivalKey = $frame['arrivalKey'];
                    if (is_string($arrivalKey)) {
                        array_pop($order);
                        $remainingCounts[$arrivalKey]++;
                    }
                    continue;
                }
                $choiceIndex = $frame['nextChoice'];
                $choice = $frame['choices'][$choiceIndex] ?? null;
                if (!is_string($choice)) {
                    array_pop($stack);
                    $arrivalKey = $frame['arrivalKey'];
                    if (is_string($arrivalKey)) {
                        array_pop($order);
                        $remainingCounts[$arrivalKey]++;
                    }
                    continue;
                }
                $stack[$frameIndex]['nextChoice']++;
                $candidateCount++;
                $remainingCounts[$choice]--;
                $order[] = $choice;
                $nextCursor = $frame['cursor'] + strlen(substr($choice, 2));
                $nextRemainingTotal = $frame['remainingTotal'] - 1;
                $stack[] = [
                    'cursor' => $nextCursor,
                    'remainingTotal' => $nextRemainingTotal,
                    'choices' => $nextRemainingTotal === 0
                        ? []
                        : $matchingKeysAt($nextCursor),
                    'nextChoice' => 0,
                    'arrivalKey' => $choice,
                ];
            }
            unset($stack);
        }

        if ($candidateCount <= 100000 && !$solutionLimitExceeded && $solutionCount >= 1) {
            $idsByText = [];
            foreach ($recordsByText as $textKey => $records) {
                if (count($records) > 1) {
                    foreach ($records as $record) {
                        if (!is_array($record['sourceBounds'] ?? null)
                            || !$this->pdfSourceBoundsAreValid($record['sourceBounds'])) {
                            return null;
                        }
                    }
                    usort($records, static fn (array $left, array $right): int =>
                        ((((float) $right['sourceBounds']['y1'] + (float) $right['sourceBounds']['y2']) / 2.0)
                            <=> (((float) $left['sourceBounds']['y1'] + (float) $left['sourceBounds']['y2']) / 2.0))
                            ?: ((float) $left['sourceBounds']['x1'] <=> (float) $right['sourceBounds']['x1'])
                            ?: ((int) $left['_sourceIndex'] <=> (int) $right['_sourceIndex'])
                    );
                    for ($index = 1; $index < count($records); $index++) {
                        $previous = $records[$index - 1]['sourceBounds'];
                        $current = $records[$index]['sourceBounds'];
                        if ($previous === $current) {
                            return null;
                        }
                    }
                }
                $idsByText[$textKey] = array_column($records, 'id');
            }

            $materializedSolutions = [];
            foreach ($solutions as $textSolution) {
                $offsets = [];
                $solution = [];
                foreach ($textSolution as $textKey) {
                    $offset = $offsets[$textKey] ?? 0;
                    $id = $idsByText[$textKey][$offset] ?? null;
                    if (!is_string($id)) {
                        return null;
                    }
                    $solution[] = $id;
                    $offsets[$textKey] = $offset + 1;
                }
                if (count($solution) !== count($contributors)) {
                    return null;
                }
                $materializedSolutions[] = $solution;
            }
            if (count($materializedSolutions) === 1) {
                return $materializedSolutions[0];
            }

            $geometryRecords = [];
            foreach ($contributors as $index => $contributor) {
                $bounds = is_array($contributor['sourceBounds'] ?? null)
                    ? $contributor['sourceBounds']
                    : null;
                if ($bounds === null || !$this->pdfSourceBoundsAreValid($bounds)) {
                    $geometryRecords = [];
                    break;
                }
                $geometryRecords[] = [
                    'id' => $contributor['id'],
                    'centerY' => ((float) $bounds['y1'] + (float) $bounds['y2']) / 2.0,
                    'x1' => (float) $bounds['x1'],
                    'sourceIndex' => $index,
                ];
            }
            if ($geometryRecords !== []) {
                usort($geometryRecords, static fn (array $left, array $right): int =>
                    ((float) $right['centerY'] <=> (float) $left['centerY'])
                        ?: ((float) $left['x1'] <=> (float) $right['x1'])
                        ?: ((int) $left['sourceIndex'] <=> (int) $right['sourceIndex'])
                );
                $rank = [];
                foreach ($geometryRecords as $index => $record) {
                    $rank[$record['id']] = $index;
                }
                $scores = [];
                foreach ($materializedSolutions as $solutionIndex => $solution) {
                    $inversions = 0;
                    for ($left = 0; $left < count($solution); $left++) {
                        for ($right = $left + 1; $right < count($solution); $right++) {
                            if (($rank[$solution[$left]] ?? PHP_INT_MAX)
                                > ($rank[$solution[$right]] ?? PHP_INT_MAX)) {
                                $inversions++;
                            }
                        }
                    }
                    $scores[$solutionIndex] = $inversions;
                }
                $minimum = min($scores);
                $winners = array_keys(array_filter(
                    $scores,
                    static fn (int $score): bool => $score === $minimum
                ));
                if (count($winners) === 1) {
                    $this->sourceOrderProofDiagnostics[] = [
                        'status' => 'trace',
                        'method' => 'geometry-tiebroken-emitted-source-occurrence-order',
                        'solutionCount' => count($materializedSolutions),
                        'selectedInversionCount' => $minimum,
                    ];

                    return $materializedSolutions[$winners[0]];
                }
            }
        }
        $this->sourceOrderProofDiagnostics[] = [
            'status' => 'trace',
            'method' => 'exact-emitted-source-occurrence-order',
            'leafBoundariesRequired' => $leafEnds !== [],
            'candidateCount' => $candidateCount,
            'solutionCount' => $solutionCount,
            'limitExceeded' => $candidateCount > 100000 || $solutionLimitExceeded,
        ];

        return null;
    }

    /**
     * @param list<array{id:string,significant:string,sourceBounds:array<string,float>}> $contributors
     * @return list<string>|null
     */
    private function pdfExactRowMajorGeometryOccurrenceOrder(
        string $emittedProjection,
        array $contributors
    ): ?array {
        $records = [];
        foreach ($contributors as $index => $contributor) {
            $bounds = is_array($contributor['sourceBounds'] ?? null)
                ? $contributor['sourceBounds']
                : null;
            if ($bounds === null || !$this->pdfSourceBoundsAreValid($bounds)) {
                return null;
            }
            $records[] = $contributor + [
                '_sourceIndex' => $index,
                '_centerY' => ((float) $bounds['y1'] + (float) $bounds['y2']) / 2.0,
                '_height' => abs((float) $bounds['y2'] - (float) $bounds['y1']),
            ];
        }
        usort($records, static fn (array $left, array $right): int =>
            ((float) $right['_centerY'] <=> (float) $left['_centerY'])
                ?: ((float) $left['sourceBounds']['x1'] <=> (float) $right['sourceBounds']['x1'])
                ?: ((int) $left['_sourceIndex'] <=> (int) $right['_sourceIndex'])
        );

        $rows = [];
        foreach ($records as $record) {
            $rowIndex = array_key_last($rows);
            $row = $rowIndex === null ? null : $rows[$rowIndex];
            $tolerance = max(
                3.0,
                ((float) ($row['height'] ?? 0.0) + (float) $record['_height']) * 0.28
            );
            if (!is_array($row)
                || abs((float) $row['centerY'] - (float) $record['_centerY']) > $tolerance) {
                $rows[] = [
                    'centerY' => (float) $record['_centerY'],
                    'height' => (float) $record['_height'],
                    'records' => [$record],
                ];
                continue;
            }
            $rows[$rowIndex]['records'][] = $record;
            $count = count($rows[$rowIndex]['records']);
            $rows[$rowIndex]['centerY'] = (
                ((float) $rows[$rowIndex]['centerY'] * ($count - 1))
                + (float) $record['_centerY']
            ) / $count;
            $rows[$rowIndex]['height'] = max(
                (float) $rows[$rowIndex]['height'],
                (float) $record['_height']
            );
        }

        $order = [];
        $projection = '';
        foreach ($rows as $row) {
            usort($row['records'], static fn (array $left, array $right): int =>
                ((float) $left['sourceBounds']['x1'] <=> (float) $right['sourceBounds']['x1'])
                    ?: ((int) $left['_sourceIndex'] <=> (int) $right['_sourceIndex'])
            );
            foreach ($row['records'] as $record) {
                $order[] = $record['id'];
                $projection .= $record['significant'];
            }
        }

        if (hash_equals($emittedProjection, $projection)) {
            return $order;
        }
        $this->sourceOrderProofDiagnostics[] = [
            'status' => 'trace',
            'method' => 'row-major-geometry-occurrence-order',
            'sourceOccurrenceCount' => count($contributors),
            'projectionMatches' => false,
            'projectionSha256' => hash('sha256', $projection),
            'emittedSha256' => hash('sha256', $emittedProjection),
        ];

        return null;
    }

    /**
     * Replace the region-bounded inventory allowance with the exact production
     * order-proof contract. A selected column region may reorder only the
     * contiguous source occurrence set whose character inventory equals the
     * exact emitted page projection between unchanged prefix/suffix text.
     *
     * Multiple independent regions on one page remain unresolved until their
     * output nodes carry distinct geometric region IDs; assigning the shared
     * page output to either region would be a guess.
     *
     * @param list<array<string,mixed>> $lineItems
     * @param array<string,array<string,mixed>> $dispositions
     * @return array<string,array<string,mixed>>
     */
    private function pdfDispositionsWithExactIndependentColumnOrderProofs(
        array $lineItems,
        array &$dispositions
    ): array {
        $scopesByPage = [];
        foreach ($lineItems as $item) {
            $id = is_string($item['id'] ?? null) ? $item['id'] : '';
            $disposition = $id === '' ? null : ($dispositions[$id] ?? null);
            if (!is_array($disposition)
                || ($disposition['allowOrderChange'] ?? false) !== true
                || !is_array($disposition['evidence'] ?? null)) {
                continue;
            }
            $evidence = $disposition['evidence'];
            $page = max(1, (int) ($item['page'] ?? 1));
            $identity = [
                'page' => $page,
                'hypothesis' => $evidence['hypothesis'] ?? null,
                'bounds' => $evidence['bounds'] ?? null,
                'featureDigest' => $evidence['featureDigest'] ?? null,
            ];
            $encoded = json_encode(
                $identity,
                JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_PRESERVE_ZERO_FRACTION
            );
            $scopeKey = hash('sha256', is_string($encoded) ? $encoded : serialize($identity));
            $scopesByPage[$page][$scopeKey]['identity'] = $identity;
            $scopesByPage[$page][$scopeKey]['sourceOccurrenceIds'][] = $id;
        }

        foreach ($scopesByPage as $page => $pageScopes) {
            if (count($pageScopes) !== 1) {
                foreach ($pageScopes as $scope) {
                    $this->unresolvedPdfIndependentColumnOrderScope(
                        $dispositions,
                        $scope['sourceOccurrenceIds'] ?? [],
                        'multiple-independent-column-scopes-share-one-page-output'
                    );
                }
                continue;
            }
            $scope = $pageScopes[array_key_first($pageScopes)];
            $scopeIds = array_values(array_filter(
                $scope['sourceOccurrenceIds'] ?? [],
                static fn (mixed $id): bool => is_string($id) && $id !== ''
            ));
            $pageBlocks = $this->sourceProofCandidateBlocksByPage[(int) $page]
                ?? $this->independentColumnBlocksByPage[(int) $page]
                ?? [];
            if ($scopeIds === [] || $pageBlocks === []) {
                $this->unresolvedPdfIndependentColumnOrderScope(
                    $dispositions,
                    $scopeIds,
                    'independent-column-page-output-is-unavailable'
                );
                continue;
            }

            $contributors = [];
            foreach ($lineItems as $item) {
                if (max(1, (int) ($item['page'] ?? 1)) !== (int) $page) {
                    continue;
                }
                $id = is_string($item['id'] ?? null) ? $item['id'] : '';
                if ($id === '') {
                    continue;
                }
                $disposition = $dispositions[$id] ?? null;
                $kind = is_array($disposition)
                    ? (string) ($disposition['disposition'] ?? 'emitted')
                    : 'emitted';
                if (!in_array($kind, ['emitted', 'boundary-repair', 'semantic-structure'], true)) {
                    continue;
                }
                if (is_array($disposition)
                    && $this->pdfDispositionHasExactSemanticStructureProof($disposition)) {
                    // A structural marker between two textual contributors
                    // must not split an otherwise contiguous order scope.
                    continue;
                }
                $contributors[] = [
                    'id' => $id,
                    'projection' => is_array($disposition)
                        && is_string($disposition['textProjection'] ?? null)
                            ? $disposition['textProjection']
                            : (string) ($item['text'] ?? ''),
                ];
            }
            $contributorIds = array_column($contributors, 'id');
            $scopeStart = array_search($scopeIds[0], $contributorIds, true);
            if (!is_int($scopeStart)
                || array_slice($contributorIds, $scopeStart, count($scopeIds)) !== $scopeIds) {
                $this->unresolvedPdfIndependentColumnOrderScope(
                    $dispositions,
                    $scopeIds,
                    'independent-column-source-occurrences-are-not-contiguous'
                );
                continue;
            }

            $emitted = '';
            foreach ($pageBlocks as $block) {
                if ($block instanceof AstNode) {
                    $emitted .= $this->pdfSourceOccurrenceComparableText(
                        $this->pdfAstNodeVisibleText($block)
                    );
                }
            }
            $sourceProjection = '';
            foreach (array_slice($contributors, $scopeStart, count($scopeIds)) as $contributor) {
                $sourceProjection .= $this->pdfSourceOccurrenceComparableText($contributor['projection']);
            }
            $exactContributorText = [];
            foreach ($contributors as $contributorIndex => $contributor) {
                if ($contributorIndex >= $scopeStart
                    && $contributorIndex < $scopeStart + count($scopeIds)) {
                    continue;
                }
                $exactContributorText[] = $this->pdfSourceOccurrenceComparableText(
                    $contributor['projection']
                );
            }
            $projection = $this->pdfUniqueInterleavedOrderScopeProjection(
                $emitted,
                $exactContributorText,
                $sourceProjection
            );
            if ($projection === null) {
                $this->unresolvedPdfIndependentColumnOrderScope(
                    $dispositions,
                    $scopeIds,
                    'independent-column-output-has-no-unique-exact-scope-projection'
                );
                continue;
            }

            $scopeIdentity = $scope['identity'];
            $scopeIdentity['sourceSha256'] = $this->sourceSha256;
            $encodedScope = json_encode(
                $scopeIdentity,
                JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_PRESERVE_ZERO_FRACTION
            );
            $proof = [
                'scopeId' => 'pdf-order-scope-' . substr(hash(
                    'sha256',
                    is_string($encodedScope) ? $encodedScope : serialize($scopeIdentity)
                ), 0, 32),
                'sourceOccurrenceIds' => $scopeIds,
                'emittedTextProjection' => $projection,
            ];
            foreach ($scopeIds as $id) {
                $dispositions[$id]['orderProof'] = $proof;
            }
        }

        return $dispositions;
    }

    /**
     * @param array<string,array<string,mixed>> $dispositions
     * @param list<string> $sourceIds
     * @return array<string,array<string,mixed>>
     */
    private function unresolvedPdfIndependentColumnOrderScope(
        array &$dispositions,
        array $sourceIds,
        string $failureReason
    ): array {
        foreach ($sourceIds as $id) {
            if (!isset($dispositions[$id])) {
                continue;
            }
            $requested = (string) ($dispositions[$id]['disposition'] ?? 'boundary-repair');
            $evidence = is_array($dispositions[$id]['evidence'] ?? null)
                ? $dispositions[$id]['evidence']
                : [];
            $dispositions[$id] = [
                'disposition' => 'unresolved',
                'reason' => 'The selected independent-column region has no unique exact source-to-output order proof.',
                'evidence' => $evidence + [
                    'requestedDisposition' => $requested,
                    'orderProofFailureReason' => $failureReason,
                ],
                'textProjection' => $dispositions[$id]['textProjection'] ?? null,
                'allowOrderChange' => false,
            ];
        }

        return $dispositions;
    }

    /** @return array<string,int> */
    private function pdfExactCharacterInventory(string $text): array
    {
        if (preg_match('//u', $text) !== 1) {
            return [];
        }
        $inventory = [];
        $offset = 0;
        $length = strlen($text);
        while ($offset < $length) {
            $leading = ord($text[$offset]);
            $characterBytes = $leading < 0x80
                ? 1
                : (($leading & 0xe0) === 0xc0
                    ? 2
                    : (($leading & 0xf0) === 0xe0 ? 3 : 4));
            $character = substr($text, $offset, $characterBytes);
            $inventory[$character] = ($inventory[$character] ?? 0) + 1;
            $offset += $characterBytes;
        }
        ksort($inventory, SORT_STRING);

        return $inventory;
    }

    /**
     * Remove the unchanged source occurrences from the emitted page in their
     * exact relative order. The remaining characters are the selected region's
     * emitted projection. More than one valid removal is ambiguous and fails
     * closed; equal inventory alone is never enough.
     *
     * @param list<string> $exactTexts
     */
    private function pdfUniqueInterleavedOrderScopeProjection(
        string $emitted,
        array $exactTexts,
        string $sourceProjection
    ): ?string {
        $scopeInventory = $this->pdfExactCharacterInventory($sourceProjection);
        $solutionCount = 0;
        $solution = null;
        $candidateCount = 0;
        $search = function (
            int $exactIndex,
            int $cursor,
            array $remaining,
            string $projection
        ) use (
            &$search,
            &$solutionCount,
            &$solution,
            &$candidateCount,
            $emitted,
            $exactTexts
        ): void {
            if ($solutionCount > 1 || $candidateCount > 256) {
                return;
            }
            if ($exactIndex >= count($exactTexts)) {
                $tail = substr($emitted, $cursor);
                $tailInventory = $this->pdfExactCharacterInventory($tail);
                if (!$this->pdfCharacterInventoryCanConsume($remaining, $tailInventory)) {
                    return;
                }
                $this->pdfConsumeCharacterInventory($remaining, $tailInventory);
                if ($remaining !== []) {
                    return;
                }
                $solutionCount++;
                $solution = $projection . $tail;

                return;
            }
            $exact = $exactTexts[$exactIndex];
            if ($exact === '') {
                $search($exactIndex + 1, $cursor, $remaining, $projection);

                return;
            }
            $offset = $cursor;
            while (($found = strpos($emitted, $exact, $offset)) !== false) {
                $candidateCount++;
                if ($candidateCount > 256) {
                    return;
                }
                $gap = substr($emitted, $cursor, $found - $cursor);
                $gapInventory = $this->pdfExactCharacterInventory($gap);
                if ($this->pdfCharacterInventoryCanConsume($remaining, $gapInventory)) {
                    $nextRemaining = $remaining;
                    $this->pdfConsumeCharacterInventory($nextRemaining, $gapInventory);
                    $search(
                        $exactIndex + 1,
                        $found + strlen($exact),
                        $nextRemaining,
                        $projection . $gap
                    );
                }
                $offset = $found + 1;
            }
        };
        $search(0, 0, $scopeInventory, '');

        return $solutionCount === 1 ? $solution : null;
    }

    /** @param array<string,int> $available @param array<string,int> $needed */
    private function pdfCharacterInventoryCanConsume(array $available, array $needed): bool
    {
        foreach ($needed as $character => $count) {
            if (($available[$character] ?? 0) < $count) {
                return false;
            }
        }

        return true;
    }

    /** @param array<string,int> $available @param array<string,int> $needed */
    private function pdfConsumeCharacterInventory(array &$available, array $needed): void
    {
        foreach ($needed as $character => $count) {
            $remaining = ($available[$character] ?? 0) - $count;
            if ($remaining > 0) {
                $available[$character] = $remaining;
            } else {
                unset($available[$character]);
            }
        }
    }

    /**
     * @param list<AstNode> $blocks
     * @return array{
     *   ordered:list<array{significant:string,visible:string}>,
     *   bullet:list<array{significant:string,visible:string}>
     * }
     */
    private function pdfStructuralListItemInventory(array $blocks): array
    {
        $inventory = ['ordered' => [], 'bullet' => []];
        $visit = function (AstNode $node) use (&$visit, &$inventory): void {
            $kind = match ($node->type) {
                'ordered_list' => 'ordered',
                'bullet_list' => 'bullet',
                default => null,
            };
            if ($kind !== null) {
                foreach ($node->children as $item) {
                    if (!$item instanceof AstNode || $item->type !== 'list_item') {
                        continue;
                    }
                    $text = $this->pdfStructuralListItemVisibleText($item);
                    $significant = $this->pdfSourceOccurrenceComparableText($text);
                    $visible = $this->pdfStructuralOccurrenceComparableText($text);
                    if ($significant !== '' && $visible !== '') {
                        $inventory[$kind][] = [
                            'significant' => $significant,
                            'visible' => $visible,
                        ];
                    }
                }
            }
            foreach ($node->children as $child) {
                if ($child instanceof AstNode) {
                    $visit($child);
                }
            }
        };
        foreach ($blocks as $block) {
            $visit($block);
        }

        return $inventory;
    }

    /**
     * Preserve the exact inline adjacency recorded by each list-item block.
     * Link decoration can split one word between a link and its following text
     * node; recursively joining every child with a space would manufacture a
     * boundary and prevent an otherwise exact source anchor from identifying
     * that item. Direct block text remains the authoritative visible string.
     */
    private function pdfStructuralListItemVisibleText(AstNode $item): string
    {
        $parts = [];
        foreach ($item->children as $block) {
            $text = $block->attr('text');
            if (!is_string($text)) {
                $text = $this->pdfAstNodeVisibleText($block);
            }
            if ($text !== '') {
                $parts[] = $text;
            }
        }

        return implode(' ', $parts);
    }

    /**
     * Build occurrence-local structural edges for marker-only source records.
     * A prefix is permitted because one list item may span several exact
     * source occurrences (including a proven wrapped-word boundary), but the
     * immediate anchor must still identify exactly one top-level direct item
     * of the expected kind and ordinal. A complete one-for-one group of
     * identical anchors may defer only its otherwise indistinguishable target
     * identity to the final exact source-edge binding.
     *
     * @param list<array<string,mixed>> $lineItems
     * @param list<AstNode> $blocks
     * @param array<string,array<string,mixed>> $dispositions
     * @return array<string,array{
     *   version:int,
     *   method:string,
     *   listType:string,
     *   markerOrdinal:?int,
     *   markerDigest:string,
     *   anchorSourceOccurrenceId:string,
     *   itemProjectionDigest:string
     * }>
     */
    private function pdfExactStandaloneListMarkerSemanticStructureProofs(
        array $lineItems,
        array $blocks,
        array $dispositions,
        array $geometryOrderLayouts = [],
        array $finalOutputPageProofs = [],
        array $candidateProofSourceLayouts = []
    ): array {
        $targets = $this->pdfTopLevelStructuralListItemInventory($blocks);
        if ($targets === [] || count($lineItems) < 2) {
            return [];
        }

        $proofs = [];
        $consumedTargets = [];
        $lineItems = array_values($lineItems);
        $lineItems = $this->pdfLineItemsWithExactListPresentationRepairReceipts(
            $lineItems,
            $geometryOrderLayouts,
            $blocks,
            $finalOutputPageProofs,
            $targets
        );
        $validatedFinalOutputPageProofs = $this->pdfValidatedFinalOutputPageProofs(
            $blocks,
            $finalOutputPageProofs
        );
        $compositeLayoutAnchorPrefixes =
            $this->pdfExactCompositeListLayoutAnchorPrefixes(
                $lineItems,
                $dispositions,
                $candidateProofSourceLayouts,
                $targets,
                $validatedFinalOutputPageProofs
            );
        for ($sourceIndex = 0; $sourceIndex + 1 < count($lineItems); $sourceIndex++) {
            $item = $lineItems[$sourceIndex];
            $id = is_string($item['id'] ?? null) ? $item['id'] : '';
            $text = is_string($item['text'] ?? null) ? $item['text'] : '';
            if ($id === '' || $text === '') {
                continue;
            }

            $kind = null;
            $markerOrdinal = null;
            if (preg_match('/^\s*(\d+)[.)]\s*$/u', $text, $orderedMatch) === 1) {
                $kind = 'ordered';
                $markerOrdinal = (int) $orderedMatch[1];
                if ($markerOrdinal < 1) {
                    continue;
                }
            } elseif (preg_match('/^\s*([*\x{2022}\x{25CF}\x{25AA}\x{25A0}\x{2043}])\s*$/u', $text) === 1) {
                $kind = 'bullet';
            }
            if ($kind === null) {
                continue;
            }
            if ($this->sourcePdfHasExactInlineStandaloneMarkerEvidence($item)
                || $this->sourcePdfInlineStandaloneMarkerProofAt($lineItems, $sourceIndex) !== null) {
                // A literal dense-table cell must never borrow a structural
                // edge from a similarly spelled list item elsewhere.
                continue;
            }

            $disposition = is_array($dispositions[$id] ?? null)
                ? $dispositions[$id]
                : [];
            $dispositionKind = (string) ($disposition['disposition'] ?? 'emitted');
            $markerProjection = is_string($disposition['textProjection'] ?? null)
                ? $disposition['textProjection']
                : $text;
            if (!in_array($dispositionKind, ['emitted', 'boundary-repair', 'semantic-structure'], true)
                || ($markerProjection !== ''
                    && !hash_equals(
                        $this->pdfSourceOccurrenceComparableText($text),
                        $this->pdfSourceOccurrenceComparableText($markerProjection)
                    ))) {
                continue;
            }

            $anchor = $lineItems[$sourceIndex + 1];
            $anchorId = is_string($anchor['id'] ?? null) ? $anchor['id'] : '';
            $anchorText = is_string($anchor['text'] ?? null) ? $anchor['text'] : '';
            if ($anchorId === '' || $anchorId === $id || $anchorText === ''
                || !isset($item['page'], $item['stream'], $anchor['page'], $anchor['stream'])
                || (int) $item['page'] < 1
                || (int) $item['stream'] < 1
                || (int) $item['page'] !== (int) $anchor['page']
                || (int) $item['stream'] !== (int) $anchor['stream']) {
                continue;
            }
            $anchorDisposition = is_array($dispositions[$anchorId] ?? null)
                ? $dispositions[$anchorId]
                : [];
            $anchorKind = (string) ($anchorDisposition['disposition'] ?? 'emitted');
            if (!in_array($anchorKind, ['emitted', 'boundary-repair'], true)) {
                continue;
            }
            $anchorProjection = is_string($anchorDisposition['textProjection'] ?? null)
                ? $anchorDisposition['textProjection']
                : $anchorText;
            $anchorSignificant = $this->pdfSourceOccurrenceComparableText($anchorProjection);
            $anchorVisible = $this->pdfStructuralOccurrenceComparableText($anchorProjection);
            $anchorStrictVisible = $this->pdfStrictStructuralVisibleText($anchorProjection);
            if ($anchorSignificant === ''
                || $anchorVisible === ''
                || $anchorStrictVisible === '') {
                continue;
            }
            $strictAnchorPrefixes = [];
            foreach ([
                $this->pdfExactOrdinaryListItemAnchorPrefix(
                    $lineItems,
                    $sourceIndex + 1,
                    $dispositions
                ),
                $this->pdfExactWrappedListItemAnchorPrefix(
                    $lineItems,
                    $sourceIndex + 1,
                    $dispositions
                ),
            ] as $prefix) {
                if (is_array($prefix)) {
                    $strictAnchorPrefixes[] = $prefix;
                }
            }

            $matches = [];
            $presentationRepairAnchorPrefixes = [];
            foreach ($strictAnchorPrefixes as $strictAnchorPrefix) {
                if (is_array($strictAnchorPrefix['presentationRepairReceipt'] ?? null)) {
                    $presentationRepairAnchorPrefixes[] = $strictAnchorPrefix;
                }
            }
            $presentationRepairPrefixMatched = false;
            foreach ($targets as $targetKey => $target) {
                if (isset($consumedTargets[$targetKey])
                    || $target['listType'] !== $kind
                    || $target['markerOrdinal'] !== $markerOrdinal) {
                    continue;
                }
                // A version-1 proof carries no presentation-repair receipt,
                // so its complete target must equal both the significant and
                // strict visible source projection. Any layout-authorized
                // spacing repair must take the receipt-backed prefix path.
                $targetStrictVisible = is_string($target['strictVisible'] ?? null)
                    ? $target['strictVisible']
                    : '';
                $exactAnchorMatch = hash_equals(
                    $target['significant'],
                    $anchorSignificant
                ) && $targetStrictVisible !== ''
                    && hash_equals($targetStrictVisible, $anchorStrictVisible);
                $strictPrefixMatch = false;
                foreach ($strictAnchorPrefixes as $strictAnchorPrefix) {
                    if ($this->pdfExactListItemAnchorPrefixMatches(
                        $target,
                        $strictAnchorPrefix
                    )) {
                        $strictPrefixMatch = true;
                        if (!$exactAnchorMatch && is_array(
                            $strictAnchorPrefix['presentationRepairReceipt'] ?? null
                        )) {
                            $presentationRepairPrefixMatched = true;
                        }
                        break;
                    }
                }
                if (!$exactAnchorMatch && !$strictPrefixMatch) {
                    continue;
                }
                $matches[$targetKey] = $target;
            }
            if (count($matches) === 1
                && $this->pdfStandaloneAsteriskHasExactFormulaPrefix(
                    $lineItems,
                    $sourceIndex,
                    $dispositions,
                    $matches[array_key_first($matches)]
                )) {
                // The one exact two-occurrence match is a formula region, so
                // the ambiguous ASCII asterisk stays visible unless the
                // page-local literal-marker recovery proves otherwise.
                continue;
            }
            $targetIdentity = $this->pdfExactStandaloneListMarkerTargetIdentity(
                $lineItems,
                $dispositions,
                $id,
                $kind,
                $markerOrdinal,
                $anchorSignificant,
                $anchorVisible,
                $targets,
                $matches
            );
            $deferredTargetIdentity = $targetIdentity['memberCount'] > 1
                && $targetIdentity['canDefer'];
            $baseTargetIsValid = !$presentationRepairPrefixMatched
                && !($targetIdentity['memberCount'] < 1
                || ($targetIdentity['memberCount'] > 1 && !$deferredTargetIdentity)
                || ($targetIdentity['memberCount'] === 1 && count($matches) !== 1));
            $extendedAnchorPrefix = null;
            if (!$baseTargetIsValid) {
                $candidateAnchorPrefixes = array_merge(
                    $presentationRepairAnchorPrefixes,
                    $this->pdfExactExtendedListItemAnchorPrefixes(
                        $lineItems,
                        $sourceIndex + 1,
                        $dispositions
                    )
                );
                if (is_array($compositeLayoutAnchorPrefixes[$sourceIndex] ?? null)) {
                    $candidateAnchorPrefixes[] =
                        $compositeLayoutAnchorPrefixes[$sourceIndex];
                }
                foreach ($candidateAnchorPrefixes as $candidatePrefix) {
                    $candidateMatches = [];
                    foreach ($targets as $targetKey => $target) {
                        if (isset($consumedTargets[$targetKey])
                            || $target['listType'] !== $kind
                            || $target['markerOrdinal'] !== $markerOrdinal
                            || !$this->pdfExactListItemAnchorPrefixMatches(
                                $target,
                                $candidatePrefix
                            )) {
                            continue;
                        }
                        $candidateMatches[$targetKey] = $target;
                    }
                    if (count($candidateMatches) !== 1) {
                        continue;
                    }
                    $candidateTargetKey = array_key_first($candidateMatches);
                    $ownerCount = is_string($candidateTargetKey)
                        ? $this->pdfExactListMarkerTargetOwnerCount(
                            $lineItems,
                            $dispositions,
                            $kind,
                            $markerOrdinal,
                            $candidateTargetKey,
                            $targets,
                            $compositeLayoutAnchorPrefixes
                        )
                        : 0;
                    if (!is_string($candidateTargetKey) || $ownerCount !== 1) {
                        continue;
                    }
                    $matches = $candidateMatches;
                    $extendedAnchorPrefix = $candidatePrefix;
                    $deferredTargetIdentity = false;
                    break;
                }
                if ($extendedAnchorPrefix === null) {
                    continue;
                }
            }
            $targetKey = array_key_first($matches);
            $target = $matches[$targetKey];
            if (!$deferredTargetIdentity) {
                $consumedTargets[$targetKey] = true;
            }
            $proofs[$id] = [
                'version' => $extendedAnchorPrefix === null ? 1 : 2,
                'method' => 'exact-standalone-list-marker-to-item',
                'listType' => $kind,
                'markerOrdinal' => $markerOrdinal,
                'markerDigest' => hash(
                    'sha256',
                    $this->pdfSourceOccurrenceComparableText($text)
                ),
                'anchorSourceOccurrenceId' => $anchorId,
                'itemProjectionDigest' => hash('sha256', $target['significant']),
            ];
            if ($extendedAnchorPrefix !== null) {
                $proofs[$id]['anchorSourceOccurrenceIds'] = $extendedAnchorPrefix['sourceOccurrenceIds'];
                $proofs[$id]['anchorProjectionDigest'] = hash(
                    'sha256',
                    $extendedAnchorPrefix['significant']
                );
                if (is_array(
                    $extendedAnchorPrefix['compositeLayoutPresentationReceipt'] ?? null
                )) {
                    $proofs[$id]['compositeLayoutPresentationReceipt'] =
                        $extendedAnchorPrefix['compositeLayoutPresentationReceipt'];
                } elseif (is_array(
                    $extendedAnchorPrefix['presentationRepairReceipt'] ?? null
                )) {
                    $proofs[$id]['presentationRepairReceipt'] =
                        $extendedAnchorPrefix['presentationRepairReceipt'];
                }
            }
        }

        return $proofs;
    }

    /**
     * @param list<array<string,mixed>> $lineItems
     * @param array<string,array<string,mixed>> $dispositions
     * @param array<string,mixed> $target
     */
    private function pdfStandaloneAsteriskHasExactFormulaPrefix(
        array $lineItems,
        int $markerIndex,
        array $dispositions,
        array $target
    ): bool {
        $marker = $lineItems[$markerIndex] ?? null;
        $anchor = $lineItems[$markerIndex + 1] ?? null;
        $following = $lineItems[$markerIndex + 2] ?? null;
        if (!is_array($marker)
            || !is_array($anchor)
            || !is_array($following)
            || !hash_equals('*', (string) ($marker['text'] ?? ''))) {
            return false;
        }
        $targetVisible = is_string($target['strictVisible'] ?? null)
            ? $target['strictVisible']
            : '';
        $anchorProjection = is_string(
            $dispositions[(string) ($anchor['id'] ?? '')]['textProjection'] ?? null
        ) ? $dispositions[(string) $anchor['id']]['textProjection'] : (string) ($anchor['text'] ?? '');
        $followingProjection = is_string(
            $dispositions[(string) ($following['id'] ?? '')]['textProjection'] ?? null
        ) ? $dispositions[(string) $following['id']]['textProjection'] : (string) ($following['text'] ?? '');
        $ordinaryPrefix = $this->pdfExactOrdinaryListItemAnchorPrefix(
            $lineItems,
            $markerIndex + 1,
            $dispositions
        );
        $anchorStrictVisible = $this->pdfStrictStructuralVisibleText($anchorProjection);
        if ($targetVisible === ''
            || !is_array($ordinaryPrefix)
            || !hash_equals(
                (string) ($target['significant'] ?? ''),
                (string) ($ordinaryPrefix['significant'] ?? '')
            )
            || !hash_equals($targetVisible, (string) ($ordinaryPrefix['visible'] ?? ''))
            || (hash_equals(
                    (string) ($target['significant'] ?? ''),
                    $this->pdfSourceOccurrenceComparableText($anchorProjection)
                )
                && hash_equals($targetVisible, $anchorStrictVisible))
            || !hash_equals((string) ($anchor['text'] ?? ''), $anchorProjection)
            || !hash_equals((string) ($following['text'] ?? ''), $followingProjection)
            || (int) ($anchor['page'] ?? 0) < 1
            || (int) ($anchor['stream'] ?? 0) < 1
            || (int) ($anchor['page'] ?? 0) !== (int) ($following['page'] ?? 0)
            || (int) ($anchor['stream'] ?? 0) !== (int) ($following['stream'] ?? 0)) {
            return false;
        }
        $records = [];
        foreach ([[$anchor, $anchorProjection], [$following, $followingProjection]] as [$item, $projection]) {
            $geometry = is_array($item['sourceGeometry'] ?? null)
                ? $item['sourceGeometry']
                : null;
            if (($item['sourceGeometryMethod'] ?? null)
                    !== 'exact-page-stream-character-offset'
                || !is_array($geometry)
                || !$this->pdfSourceBoundsAreValid($geometry)
                || ($geometry['orientation'] ?? null) !== 'horizontal') {
                return false;
            }
            $records[] = [
                'text' => $projection,
                'layout' => [
                    'page' => (int) $item['page'],
                    'x1' => (float) $geometry['x1'],
                    'y1' => (float) $geometry['y1'],
                    'x2' => (float) $geometry['x2'],
                    'y2' => (float) $geometry['y2'],
                    'fontSize' => max(
                        1.0,
                        abs((float) $geometry['y2'] - (float) $geometry['y1'])
                    ),
                ],
            ];
        }
        $processor = new PdfFormulaSemanticProcessor();
        $formulaRecords = $processor->process($records);
        $formulaRecord = count($formulaRecords) === 1 ? $formulaRecords[0] : null;

        return $processor->regionCount() === 1
            && is_array($formulaRecord)
            && (($formulaRecord['layout']['sourcePdfRegionRole'] ?? null) === 'formula')
            && hash_equals(
                (string) ($target['significant'] ?? ''),
                $this->pdfSourceOccurrenceComparableText(
                    (string) ($formulaRecord['text'] ?? '')
                )
            );
    }

    /**
     * A significant-only multi-occurrence list prefix may cross repaired
     * presentation spacing only when every source carrier is one immutable
     * whole occurrence and the final page proof places the unique structural
     * target bytes on that same page. The receipt is transient: the public
     * semantic edge still binds the exact source IDs and final item digest.
     *
     * @param list<array<string,mixed>> $lineItems
     * @param list<array<string,mixed>> $layouts
     * @param list<AstNode> $blocks
     * @param array<int,array{start:int,end:int,projection:string,leafEnds:list<int>}> $finalOutputPageProofs
     * @param array<string,array<string,mixed>> $targets
     * @return list<array<string,mixed>>
     */
    private function pdfLineItemsWithExactListPresentationRepairReceipts(
        array $lineItems,
        array $layouts,
        array $blocks,
        array $finalOutputPageProofs,
        array $targets
    ): array {
        if ($lineItems === [] || $layouts === [] || $finalOutputPageProofs === []) {
            return $lineItems;
        }
        // Presentation receipts are consumed only by the bounded standalone
        // marker anchor scans below. Indexing every source/layout occurrence
        // duplicated proof-rich records which could never participate in one
        // of those scans.
        $neededSourceIndexes = [];
        $lineItemCount = count($lineItems);
        foreach ($lineItems as $markerIndex => $markerItem) {
            $markerText = is_string($markerItem['text'] ?? null)
                ? $markerItem['text']
                : '';
            if (preg_match(
                '/^\s*(?:\d+[.)]|[*\x{2022}\x{25CF}\x{25AA}\x{25A0}\x{2043}])\s*$/u',
                $markerText
            ) !== 1) {
                continue;
            }
            $limit = min(
                $lineItemCount,
                $markerIndex + self::MAX_PDF_LIST_MARKER_ANCHOR_OCCURRENCES + 3
            );
            for ($sourceIndex = $markerIndex + 1; $sourceIndex < $limit; $sourceIndex++) {
                $neededSourceIndexes[$sourceIndex] = true;
            }
        }
        if ($neededSourceIndexes === []) {
            return $lineItems;
        }
        $finalOutputPageProofs = $this->pdfValidatedFinalOutputPageProofs(
            $blocks,
            $finalOutputPageProofs
        );
        if ($finalOutputPageProofs === []) {
            return $lineItems;
        }

        $output = '';
        foreach ($blocks as $block) {
            $leaves = [];
            $this->appendPdfSourceBindingLeafText($block, $leaves);
            $output .= implode('', $leaves);
        }
        if ($output === '') {
            return $lineItems;
        }
        $targetAuthorizationsByPage = [];
        foreach ($targets as $target) {
            $significant = is_string($target['significant'] ?? null)
                ? $target['significant']
                : '';
            $strictVisible = is_string($target['strictVisible'] ?? null)
                ? $target['strictVisible']
                : '';
            if ($significant === ''
                || $strictVisible === ''
                || substr_count($output, $significant) !== 1) {
                continue;
            }
            $targetStart = strpos($output, $significant);
            if (!is_int($targetStart)) {
                continue;
            }
            $targetEnd = $targetStart + strlen($significant);
            foreach ($finalOutputPageProofs as $page => $pageProof) {
                if ($targetStart < $pageProof['start']
                    || $targetEnd > $pageProof['end']
                    || !hash_equals(
                        $significant,
                        substr(
                            $pageProof['projection'],
                            $targetStart - $pageProof['start'],
                            strlen($significant)
                        )
                    )) {
                    continue;
                }
                $authorization = [
                    'significantDigest' => hash('sha256', $significant),
                    'strictVisibleDigest' => hash('sha256', $strictVisible),
                ];
                $authorizationKey = $authorization['significantDigest']
                    . "\0"
                    . $authorization['strictVisibleDigest'];
                $targetAuthorizationsByPage[(int) $page][$authorizationKey] =
                    $authorization;
                break;
            }
        }
        if ($targetAuthorizationsByPage === []) {
            return $lineItems;
        }

        $neededSourceIds = [];
        $neededGlobalIndexes = [];
        foreach (array_keys($neededSourceIndexes) as $sourceIndex) {
            $sourceItem = $lineItems[$sourceIndex] ?? null;
            if (!is_array($sourceItem)) {
                continue;
            }
            $sourceId = is_string($sourceItem['id'] ?? null) ? $sourceItem['id'] : '';
            if ($sourceId !== '') {
                $neededSourceIds[$sourceId] = true;
            }
            $globalSourceIndex = is_int($sourceItem['sourcePdfGlobalSourceIndex'] ?? null)
                ? $sourceItem['sourcePdfGlobalSourceIndex']
                : $sourceIndex;
            $neededGlobalIndexes[$globalSourceIndex] = true;
        }
        $layoutsById = [];
        $singleOccurrenceUnionLayoutsByGlobalIndex = [];
        foreach ($layouts as $layoutIndex => $layout) {
            $sourceId = is_string($layout['id'] ?? null) ? $layout['id'] : '';
            if ($sourceId !== '' && isset($neededSourceIds[$sourceId])) {
                $layoutsById[$sourceId][] = $layoutIndex;
                continue;
            }
            $unionProof = is_array(
                $layout['sourcePdfWholeExactOccurrenceProof'] ?? null
            ) ? $layout['sourcePdfWholeExactOccurrenceProof'] : null;
            $occurrences = is_array($unionProof['occurrences'] ?? null)
                ? $unionProof['occurrences']
                : null;
            $ranges = is_array($unionProof['ranges'] ?? null)
                ? $unionProof['ranges']
                : null;
            $globalSourceIndex = is_array($occurrences)
                && array_is_list($occurrences)
                && count($occurrences) === 1
                && is_array($occurrences[0] ?? null)
                && is_int($occurrences[0]['sourceIndex'] ?? null)
                && is_array($ranges)
                && array_is_list($ranges)
                && count($ranges) === 1
                    ? $occurrences[0]['sourceIndex']
                    : null;
            if (is_int($globalSourceIndex)
                && $globalSourceIndex >= 0
                && isset($neededGlobalIndexes[$globalSourceIndex])) {
                $singleOccurrenceUnionLayoutsByGlobalIndex[$globalSourceIndex][] =
                    $layoutIndex;
            }
        }
        foreach ($lineItems as $sourceIndex => &$item) {
            if (!isset($neededSourceIndexes[$sourceIndex])) {
                continue;
            }
            $sourceId = is_string($item['id'] ?? null) ? $item['id'] : '';
            $globalSourceIndex = is_int($item['sourcePdfGlobalSourceIndex'] ?? null)
                ? $item['sourcePdfGlobalSourceIndex']
                : $sourceIndex;
            $sourceProjection = $this->pdfSourceOccurrenceComparableText(
                (string) ($item['text'] ?? '')
            );
            $page = (int) ($item['page'] ?? 0);
            $stream = (int) ($item['stream'] ?? 0);
            $idCandidateIndexes = $sourceId !== '' ? ($layoutsById[$sourceId] ?? []) : [];
            if ($sourceProjection === ''
                || $sourceId === ''
                || $page < 1
                || $stream < 1
                || count($idCandidateIndexes) > 1) {
                continue;
            }
            $layout = null;
            if (count($idCandidateIndexes) === 1) {
                $candidate = $layouts[$idCandidateIndexes[0]];
                $proof = is_array(
                    $candidate['sourcePdfWholeExactSourceOccurrenceProof'] ?? null
                ) ? $candidate['sourcePdfWholeExactSourceOccurrenceProof'] : null;
                if ($proof !== null
                    && (int) ($candidate['page'] ?? 0) === $page
                    && (int) ($candidate['sourceStream'] ?? 0) === $stream
                    && ($proof['globalSourceIndex'] ?? null) === $globalSourceIndex
                    && ($proof['sourceOccurrenceId'] ?? null) === $sourceId
                    && $this->repairedPdfWholeExactSourceOccurrenceProofMatchesLayout(
                        $candidate,
                        $sourceProjection
                    )) {
                    $layout = $candidate;
                }
            } else {
                $unionCandidates = [];
                foreach (($singleOccurrenceUnionLayoutsByGlobalIndex[$globalSourceIndex]
                    ?? []) as $candidateLayoutIndex) {
                    $candidate = $layouts[$candidateLayoutIndex];
                    if ($this->pdfLayoutIsExactSingleSourceOccurrenceUnion(
                        $candidate,
                        $globalSourceIndex,
                        $sourceIndex,
                        $page,
                        $stream,
                        $sourceProjection
                    )) {
                        $unionCandidates[] = $candidate;
                    }
                }
                if (count($unionCandidates) === 1) {
                    $layout = $unionCandidates[0];
                }
            }
            // Source authority comes exclusively from the unique exact
            // carrier proved above. The shared prose finalizer may improve
            // only that carrier's visible spelling: its result must already
            // be canonical strict-visible text and must retain the carrier's
            // significant bytes exactly.
            $finalizedLayoutVisibleProjection = is_array($layout)
                ? $this->repairGluedProseLine((string) ($layout['text'] ?? ''))
                : '';
            $layoutVisibleProjection = $finalizedLayoutVisibleProjection !== ''
                ? $this->pdfStrictStructuralVisibleText(
                    $finalizedLayoutVisibleProjection
                )
                : '';
            if (!is_array($layout)
                || $finalizedLayoutVisibleProjection === ''
                || $layoutVisibleProjection === ''
                || !hash_equals(
                    $finalizedLayoutVisibleProjection,
                    $layoutVisibleProjection
                )
                || !hash_equals(
                    $sourceProjection,
                    $this->pdfSourceOccurrenceComparableText(
                        $layoutVisibleProjection
                    )
                )
                || !isset($finalOutputPageProofs[$page])
                || !isset($targetAuthorizationsByPage[$page])) {
                continue;
            }
            ksort($targetAuthorizationsByPage[$page], SORT_STRING);
            $authorizedTargets = array_values(
                $targetAuthorizationsByPage[$page]
            );
            $receipt = [
                'version' => 1,
                'method' => 'exact-whole-source-list-presentation-occurrence',
                'sourceSha256' => $this->sourceSha256,
                'sourceOccurrenceId' => $sourceId,
                'globalSourceIndex' => $globalSourceIndex,
                'page' => $page,
                'stream' => $stream,
                'projectionDigest' => hash('sha256', $sourceProjection),
                'visibleProjection' => $layoutVisibleProjection,
                'visibleProjectionDigest' => hash(
                    'sha256',
                    $layoutVisibleProjection
                ),
                'finalPageProjectionDigest' => hash(
                    'sha256',
                    $finalOutputPageProofs[$page]['projection']
                ),
                'authorizedTargets' => $authorizedTargets,
            ];
            $receipt['proofDigest'] = hash('sha256', json_encode(
                $receipt,
                JSON_UNESCAPED_SLASHES
                    | JSON_UNESCAPED_UNICODE
                    | JSON_PRESERVE_ZERO_FRACTION
            ) ?: '');
            // The receipt validator intentionally refuses to infer an index
            // from an ID. Retain the exact live index used to mint this
            // transient receipt, including the list-offset fallback for
            // compact source items which did not carry the field themselves.
            $item['sourcePdfGlobalSourceIndex'] = $globalSourceIndex;
            $item['sourcePdfExactListPresentationRepairReceipt'] = $receipt;
        }
        unset($item);

        return $lineItems;
    }

    /**
     * An id-less repaired geometry layout may still identify one immutable
     * source occurrence through its complete occurrence-union proof. Admit
     * only the degenerate one-occurrence union: the sole live global/local
     * index, page, stream, significant digest, and full range must all agree.
     * The caller separately requires this candidate to be unique.
     *
     * @param array<string,mixed> $layout
     */
    private function pdfLayoutIsExactSingleSourceOccurrenceUnion(
        array $layout,
        int $globalSourceIndex,
        int $localSourceIndex,
        int $page,
        int $stream,
        string $sourceProjection
    ): bool {
        $proof = is_array($layout)
            && is_array($layout['sourcePdfWholeExactOccurrenceProof'] ?? null)
            ? $layout['sourcePdfWholeExactOccurrenceProof']
            : null;
        $occurrences = is_array($proof['occurrences'] ?? null)
            ? $proof['occurrences']
            : null;
        $ranges = is_array($proof['ranges'] ?? null) ? $proof['ranges'] : null;
        $occurrence = is_array($occurrences)
            && array_is_list($occurrences)
            && count($occurrences) === 1
            && is_array($occurrences[0] ?? null)
                ? $occurrences[0]
                : null;
        $expectedRange = [
            'sourceIndex' => $globalSourceIndex,
            'sourceStart' => 0,
            'sourceEnd' => strlen($sourceProjection),
        ];
        $layoutProjection = $this->pdfSourceOccurrenceComparableText(
            (string) ($layout['text'] ?? '')
        );
        return (($layout['id'] ?? null) === null || ($layout['id'] ?? null) === '')
            && $sourceProjection !== ''
            && hash_equals($sourceProjection, $layoutProjection)
            && $proof !== null
            && ($proof['page'] ?? null) === $page
            && (($proof['layoutStream'] ?? null) === null
                || ($proof['layoutStream'] ?? null) === $stream)
            && is_array($occurrence)
            && ($occurrence['sourceIndex'] ?? null) === $globalSourceIndex
            && ($occurrence['sourceLocalIndex'] ?? null) === $localSourceIndex
            && ($occurrence['page'] ?? null) === $page
            && ($occurrence['stream'] ?? null) === $stream
            && ($occurrence['significantBytes'] ?? null) === strlen($sourceProjection)
            && is_string($occurrence['significantDigest'] ?? null)
            && hash_equals(
                $occurrence['significantDigest'],
                hash('sha256', $sourceProjection)
            )
            && is_array($ranges)
            && array_is_list($ranges)
            && $ranges === [$expectedRange]
            && (int) ($layout['page'] ?? 0) === $page
            && (!array_key_exists('sourceStream', $layout)
                || $layout['sourceStream'] === null
                || (is_numeric($layout['sourceStream'])
                    && (int) $layout['sourceStream'] === $stream))
            && $this->repairedPdfWholeExactOccurrenceProofMatchesLayout(
                $layout,
                $sourceProjection
            );
    }

    /**
     * Revalidate one immutable source occurrence's signed presentation
     * receipt before another proof embeds it as nested evidence.
     *
     * @param array<string,mixed> $item
     * @return array<string,mixed>|null
     */
    private function pdfValidatedWholeSourceListPresentationOccurrenceReceipt(
        array $item
    ): ?array {
        $receipt = is_array($item['sourcePdfExactListPresentationRepairReceipt'] ?? null)
            ? $item['sourcePdfExactListPresentationRepairReceipt']
            : null;
        if ($receipt === null
            || ($receipt['version'] ?? null) !== 1
            || ($receipt['method'] ?? null)
                !== 'exact-whole-source-list-presentation-occurrence'
            || !is_string($receipt['sourceSha256'] ?? null)
            || !hash_equals($this->sourceSha256, $receipt['sourceSha256'])
            || !is_string($receipt['sourceOccurrenceId'] ?? null)
            || $receipt['sourceOccurrenceId'] === ''
            || ($item['id'] ?? null) !== $receipt['sourceOccurrenceId']
            || !is_int($receipt['globalSourceIndex'] ?? null)
            || $receipt['globalSourceIndex'] < 0
            || !is_int($item['sourcePdfGlobalSourceIndex'] ?? null)
            || $item['sourcePdfGlobalSourceIndex']
                !== $receipt['globalSourceIndex']
            || !is_int($receipt['page'] ?? null)
            || $receipt['page'] < 1
            || !is_int($receipt['stream'] ?? null)
            || $receipt['stream'] < 1
            || (int) ($item['page'] ?? 0) !== $receipt['page']
            || (int) ($item['stream'] ?? 0) !== $receipt['stream']
            || !is_string($receipt['projectionDigest'] ?? null)
            || preg_match('/^[a-f0-9]{64}$/D', $receipt['projectionDigest']) !== 1
            || !is_string($receipt['visibleProjection'] ?? null)
            || $receipt['visibleProjection'] === ''
            || !is_string($receipt['visibleProjectionDigest'] ?? null)
            || preg_match('/^[a-f0-9]{64}$/D', $receipt['visibleProjectionDigest']) !== 1
            || !is_string($receipt['finalPageProjectionDigest'] ?? null)
            || preg_match('/^[a-f0-9]{64}$/D', $receipt['finalPageProjectionDigest']) !== 1
            || !is_array($receipt['authorizedTargets'] ?? null)
            || !array_is_list($receipt['authorizedTargets'])
            || $receipt['authorizedTargets'] === []
            || !is_string($receipt['proofDigest'] ?? null)
            || preg_match('/^[a-f0-9]{64}$/D', $receipt['proofDigest']) !== 1) {
            return null;
        }
        $sourceProjection = $this->pdfSourceOccurrenceComparableText(
            (string) ($item['text'] ?? '')
        );
        if ($sourceProjection === ''
            || !hash_equals(
                $receipt['projectionDigest'],
                hash('sha256', $sourceProjection)
            )
            || !hash_equals(
                $receipt['visibleProjection'],
                $this->pdfStrictStructuralVisibleText($receipt['visibleProjection'])
            )
            || !hash_equals(
                $sourceProjection,
                $this->pdfSourceOccurrenceComparableText(
                    $receipt['visibleProjection']
                )
            )
            || !hash_equals(
                $receipt['visibleProjectionDigest'],
                hash('sha256', $receipt['visibleProjection'])
            )) {
            return null;
        }
        $canonicalTargets = [];
        foreach ($receipt['authorizedTargets'] as $authorizedTarget) {
            $significantDigest = is_array($authorizedTarget)
                ? ($authorizedTarget['significantDigest'] ?? null)
                : null;
            $strictVisibleDigest = is_array($authorizedTarget)
                ? ($authorizedTarget['strictVisibleDigest'] ?? null)
                : null;
            if (!is_string($significantDigest)
                || preg_match('/^[a-f0-9]{64}$/D', $significantDigest) !== 1
                || !is_string($strictVisibleDigest)
                || preg_match('/^[a-f0-9]{64}$/D', $strictVisibleDigest) !== 1
                || count($authorizedTarget) !== 2) {
                return null;
            }
            $canonicalTargets[$significantDigest . "\0" . $strictVisibleDigest] = [
                'significantDigest' => $significantDigest,
                'strictVisibleDigest' => $strictVisibleDigest,
            ];
        }
        ksort($canonicalTargets, SORT_STRING);
        if ($receipt['authorizedTargets'] !== array_values($canonicalTargets)) {
            return null;
        }
        $payload = $receipt;
        unset($payload['proofDigest']);
        if (!hash_equals($receipt['proofDigest'], hash('sha256', json_encode(
            $payload,
            JSON_UNESCAPED_SLASHES
                | JSON_UNESCAPED_UNICODE
                | JSON_PRESERVE_ZERO_FRACTION
        ) ?: ''))) {
            return null;
        }

        return $receipt;
    }

    /**
     * @param list<array<string,mixed>> $items
     * @return array<string,mixed>|null
     */
    private function pdfExactListPresentationRepairChainReceipt(
        array $items,
        string $prefixProjection
    ): ?array {
        if (count($items) < 2 || $prefixProjection === '') {
            return null;
        }
        $sourceOccurrenceIds = [];
        $globalSourceIndexes = [];
        $visibleProjections = [];
        $sourceProjection = '';
        $page = null;
        $stream = null;
        $finalPageProjectionDigest = null;
        $authorizedTargets = null;
        foreach ($items as $itemIndex => $item) {
            $receipt = is_array($item['sourcePdfExactListPresentationRepairReceipt'] ?? null)
                ? $item['sourcePdfExactListPresentationRepairReceipt']
                : null;
            if ($receipt === null
                || ($receipt['version'] ?? null) !== 1
                || ($receipt['method'] ?? null)
                    !== 'exact-whole-source-list-presentation-occurrence'
                || !is_string($receipt['sourceSha256'] ?? null)
                || !hash_equals($this->sourceSha256, $receipt['sourceSha256'])
                || !is_string($receipt['sourceOccurrenceId'] ?? null)
                || $receipt['sourceOccurrenceId'] === ''
                || ($item['id'] ?? null) !== $receipt['sourceOccurrenceId']
                || !is_int($receipt['globalSourceIndex'] ?? null)
                || $receipt['globalSourceIndex'] < 0
                || !is_int($receipt['page'] ?? null)
                || $receipt['page'] < 1
                || !is_int($receipt['stream'] ?? null)
                || $receipt['stream'] < 1
                || (int) ($item['page'] ?? 0) !== $receipt['page']
                || (int) ($item['stream'] ?? 0) !== $receipt['stream']
                || !is_string($receipt['projectionDigest'] ?? null)
                || preg_match('/^[a-f0-9]{64}$/D', $receipt['projectionDigest']) !== 1
                || !is_string($receipt['visibleProjection'] ?? null)
                || $receipt['visibleProjection'] === ''
                || !is_string($receipt['visibleProjectionDigest'] ?? null)
                || preg_match(
                    '/^[a-f0-9]{64}$/D',
                    $receipt['visibleProjectionDigest']
                ) !== 1
                || !is_string($receipt['finalPageProjectionDigest'] ?? null)
                || preg_match('/^[a-f0-9]{64}$/D', $receipt['finalPageProjectionDigest']) !== 1
                || !is_array($receipt['authorizedTargets'] ?? null)
                || !array_is_list($receipt['authorizedTargets'])
                || $receipt['authorizedTargets'] === []
                || !is_string($receipt['proofDigest'] ?? null)
                || preg_match('/^[a-f0-9]{64}$/D', $receipt['proofDigest']) !== 1) {
                return null;
            }
            $itemProjection = $this->pdfSourceOccurrenceComparableText(
                (string) ($item['text'] ?? '')
            );
            if ($itemProjection === ''
                || !hash_equals(
                    $receipt['projectionDigest'],
                    hash('sha256', $itemProjection)
                )
                || !hash_equals(
                    $receipt['visibleProjection'],
                    $this->pdfStrictStructuralVisibleText(
                        $receipt['visibleProjection']
                    )
                )
                || !hash_equals(
                    $itemProjection,
                    $this->pdfSourceOccurrenceComparableText(
                        $receipt['visibleProjection']
                    )
                )
                || !hash_equals(
                    $receipt['visibleProjectionDigest'],
                    hash('sha256', $receipt['visibleProjection'])
                )) {
                return null;
            }
            $canonicalTargets = [];
            foreach ($receipt['authorizedTargets'] as $authorizedTarget) {
                $significantDigest = is_array($authorizedTarget)
                    ? ($authorizedTarget['significantDigest'] ?? null)
                    : null;
                $strictVisibleDigest = is_array($authorizedTarget)
                    ? ($authorizedTarget['strictVisibleDigest'] ?? null)
                    : null;
                if (!is_string($significantDigest)
                    || preg_match('/^[a-f0-9]{64}$/D', $significantDigest) !== 1
                    || !is_string($strictVisibleDigest)
                    || preg_match('/^[a-f0-9]{64}$/D', $strictVisibleDigest) !== 1
                    || count($authorizedTarget) !== 2) {
                    return null;
                }
                $canonicalTargets[$significantDigest . "\0" . $strictVisibleDigest] = [
                    'significantDigest' => $significantDigest,
                    'strictVisibleDigest' => $strictVisibleDigest,
                ];
            }
            ksort($canonicalTargets, SORT_STRING);
            if ($receipt['authorizedTargets'] !== array_values($canonicalTargets)) {
                return null;
            }
            $payload = $receipt;
            unset($payload['proofDigest']);
            if (!hash_equals($receipt['proofDigest'], hash('sha256', json_encode(
                $payload,
                JSON_UNESCAPED_SLASHES
                    | JSON_UNESCAPED_UNICODE
                    | JSON_PRESERVE_ZERO_FRACTION
            ) ?: ''))) {
                return null;
            }
            if ($itemIndex > 0
                && $receipt['globalSourceIndex']
                    !== $globalSourceIndexes[$itemIndex - 1] + 1) {
                return null;
            }
            if ($page !== null
                && ($receipt['page'] !== $page
                    || $receipt['stream'] !== $stream
                    || !hash_equals(
                        $receipt['finalPageProjectionDigest'],
                        $finalPageProjectionDigest
                    )
                    || $receipt['authorizedTargets'] !== $authorizedTargets)) {
                return null;
            }
            $page = $receipt['page'];
            $stream = $receipt['stream'];
            $finalPageProjectionDigest = $receipt['finalPageProjectionDigest'];
            $authorizedTargets = $receipt['authorizedTargets'];
            $sourceOccurrenceIds[] = $receipt['sourceOccurrenceId'];
            $globalSourceIndexes[] = $receipt['globalSourceIndex'];
            $visibleProjections[] = $receipt['visibleProjection'];
            $sourceProjection .= $itemProjection;
        }
        if (!hash_equals($prefixProjection, $sourceProjection)
            || count(array_unique($sourceOccurrenceIds)) !== count($sourceOccurrenceIds)
            || !is_int($page)
            || !is_int($stream)
            || !is_string($finalPageProjectionDigest)
            || !is_array($authorizedTargets)) {
            return null;
        }
        $significantBoundaryOffsets = [];
        $visibleBoundarySpaces = [];
        $visiblePrefix = '';
        $significantOffset = 0;
        foreach ($items as $itemIndex => $item) {
            $itemProjection = $this->pdfSourceOccurrenceComparableText(
                (string) ($item['text'] ?? '')
            );
            if ($itemIndex > 0) {
                $visiblePrefix .= $visibleBoundarySpaces[$itemIndex - 1]
                    ? ' '
                    : '';
            }
            $visiblePrefix .= $visibleProjections[$itemIndex];
            $significantOffset += strlen($itemProjection);
            if ($itemIndex + 1 >= count($items)) {
                continue;
            }
            $followingText = (string) ($items[$itemIndex + 1]['text'] ?? '');
            $significantBoundaryOffsets[] = $significantOffset;
            $visibleBoundarySpaces[] = preg_match(
                '/^[,.;:!?\)\]\}]/u',
                ltrim($followingText)
            ) !== 1;
        }
        if ($visiblePrefix === ''
            || !hash_equals(
                $visiblePrefix,
                $this->pdfStrictStructuralVisibleText($visiblePrefix)
            )
            || !hash_equals(
                $prefixProjection,
                $this->pdfSourceOccurrenceComparableText($visiblePrefix)
            )) {
            return null;
        }
        $receipt = [
            'version' => 1,
            'method' => 'exact-consecutive-list-presentation-repair-prefix',
            'sourceSha256' => $this->sourceSha256,
            'page' => $page,
            'stream' => $stream,
            'sourceOccurrenceIds' => $sourceOccurrenceIds,
            'globalSourceIndexes' => $globalSourceIndexes,
            'prefixProjectionDigest' => hash('sha256', $prefixProjection),
            'visiblePrefix' => $visiblePrefix,
            'visiblePrefixDigest' => hash('sha256', $visiblePrefix),
            'finalPageProjectionDigest' => $finalPageProjectionDigest,
            'authorizedTargets' => $authorizedTargets,
            'significantBoundaryOffsets' => $significantBoundaryOffsets,
            'visibleBoundarySpaces' => $visibleBoundarySpaces,
        ];
        $receipt['proofDigest'] = hash('sha256', json_encode(
            $receipt,
            JSON_UNESCAPED_SLASHES
                | JSON_UNESCAPED_UNICODE
                | JSON_PRESERVE_ZERO_FRACTION
        ) ?: '');

        return $receipt;
    }

    /** @param list<array<string,mixed>> $layouts */
    private function pdfPageHasExactPositionedSourceRangeEvidence(int $page, array $layouts): bool
    {
        foreach ($layouts as $layout) {
            if (max(1, (int) ($layout['page'] ?? 1)) === $page
                && $this->pdfPositionedExactSourceRanges($layout) !== []) {
                return true;
            }
        }

        return false;
    }

    /**
     * Extend the already grounded ordinary two-occurrence prefix only through
     * consecutive, exact same-stream output occurrences. Each returned prefix
     * names every source edge that the binding ledger must later observe at
     * the beginning of the chosen live list item. The bound prevents a long
     * or hostile stream from turning structural disambiguation into an
     * unbounded scan.
     *
     * @param list<array<string,mixed>> $lineItems
     * @param array<string,array<string,mixed>> $dispositions
     * @return list<array{
     *   significant:string,
     *   visible:string,
     *   visiblePrefixRequired:bool,
     *   sourceOccurrenceIds:list<string>,
     *   presentationRepairReceipt?:array<string,mixed>
     * }>
     */
    private function pdfExactExtendedListItemAnchorPrefixes(
        array $lineItems,
        int $anchorIndex,
        array $dispositions
    ): array {
        $base = $this->pdfExactOrdinaryListItemAnchorPrefix(
            $lineItems,
            $anchorIndex,
            $dispositions
        );
        $anchor = $lineItems[$anchorIndex] ?? null;
        $following = $lineItems[$anchorIndex + 1] ?? null;
        if (!is_array($base) || !is_array($anchor) || !is_array($following)) {
            return [];
        }
        $followingId = is_string($following['id'] ?? null) ? $following['id'] : '';
        $followingText = is_string($following['text'] ?? null) ? $following['text'] : '';
        $followingDisposition = is_array($dispositions[$followingId] ?? null)
            ? $dispositions[$followingId]
            : [];
        $followingProjection = is_string($followingDisposition['textProjection'] ?? null)
            ? $followingDisposition['textProjection']
            : $followingText;
        if ($followingId === '' || !hash_equals($followingText, $followingProjection)) {
            return [];
        }
        $page = isset($anchor['page']) ? (int) $anchor['page'] : 0;
        $stream = isset($anchor['stream']) ? (int) $anchor['stream'] : 0;
        $sourceIds = [];
        foreach ([$anchor, $following] as $record) {
            $sourceId = is_string($record['id'] ?? null) ? $record['id'] : '';
            if ($sourceId === '' || isset($sourceIds[$sourceId])) {
                return [];
            }
            $sourceIds[$sourceId] = true;
        }

        $significant = $base['significant'];
        $visible = $base['visible'];
        $prefixes = [];
        $lineItemCount = count($lineItems);
        for ($offset = 2;
            $offset < self::MAX_PDF_LIST_MARKER_ANCHOR_OCCURRENCES
                && $anchorIndex + $offset < $lineItemCount;
            $offset++) {
            $record = $lineItems[$anchorIndex + $offset];
            $sourceId = is_string($record['id'] ?? null) ? $record['id'] : '';
            $sourceText = is_string($record['text'] ?? null) ? $record['text'] : '';
            if ($sourceId === ''
                || isset($sourceIds[$sourceId])
                || $sourceText === ''
                || (int) ($record['page'] ?? 0) !== $page
                || (int) ($record['stream'] ?? 0) !== $stream
                || preg_match('/^\s*(?:\d+[.)]|[*\x{2022}\x{25CF}\x{25AA}\x{25A0}\x{2043}])\s*$/u', $sourceText) === 1) {
                break;
            }
            $disposition = is_array($dispositions[$sourceId] ?? null)
                ? $dispositions[$sourceId]
                : [];
            $kind = (string) ($disposition['disposition'] ?? 'emitted');
            $projection = is_string($disposition['textProjection'] ?? null)
                ? $disposition['textProjection']
                : $sourceText;
            if (!in_array($kind, ['emitted', 'boundary-repair'], true)
                || !hash_equals($sourceText, $projection)) {
                break;
            }
            $recordSignificant = $this->pdfSourceOccurrenceComparableText($projection);
            $recordVisible = $this->pdfStructuralOccurrenceComparableText($projection);
            if ($recordSignificant === '' || $recordVisible === '') {
                break;
            }
            $visibleSeparator = preg_match('/^[,.;:!?\)\]\}]/u', ltrim($projection)) === 1
                ? ''
                : ' ';
            $significant .= $recordSignificant;
            $visible .= $visibleSeparator . $recordVisible;
            $sourceIds[$sourceId] = true;
            $presentationRepairReceipt = $this->pdfExactListPresentationRepairChainReceipt(
                array_slice($lineItems, $anchorIndex, $offset + 1),
                $significant
            );
            $prefix = [
                'significant' => $significant,
                'visible' => is_array($presentationRepairReceipt)
                    && is_string($presentationRepairReceipt['visiblePrefix'] ?? null)
                        ? $presentationRepairReceipt['visiblePrefix']
                        : $visible,
                'visiblePrefixRequired' => $presentationRepairReceipt === null,
                'sourceOccurrenceIds' => array_keys($sourceIds),
            ];
            if ($presentationRepairReceipt !== null) {
                $prefix['presentationRepairReceipt'] = $presentationRepairReceipt;
            }
            $prefixes[] = $prefix;
        }

        return $prefixes;
    }

    /**
     * Retain only the bounded candidate carriers which could later establish
     * a composite list presentation. The full repair-layout vector is large
     * and has completed all other work before final binding.
     *
     * @param list<array<string,mixed>> $layouts
     * @param list<array<string,mixed>> $sourceItems
     * @return list<array<string,mixed>>
     */
    private function pdfCompositeListPresentationCandidateLayouts(
        array $layouts,
        array $sourceItems = []
    ): array
    {
        $candidates = [];
        foreach ($layouts as $layout) {
            if (!is_array($layout)
                || $this->listItem($this->pdfTextWithoutSemanticPrefixes(
                    (string) ($layout['text'] ?? '')
                )) === null) {
                continue;
            }
            $proof = is_array($layout['sourcePdfWholeExactOccurrenceProof'] ?? null)
                ? $layout['sourcePdfWholeExactOccurrenceProof']
                : ($sourceItems !== []
                    ? $this->pdfSourceLayoutWholeExactOccurrenceProof(
                        $layout,
                        $sourceItems
                    )
                    : null);
            $occurrences = is_array($proof['occurrences'] ?? null)
                ? $proof['occurrences']
                : [];
            if (($proof['version'] ?? null) !== 1
                || ($proof['method'] ?? null)
                    !== 'source-inventory-whole-occurrence-union'
                || count($occurrences) < 2
                || count($occurrences)
                    > self::MAX_PDF_LIST_MARKER_ANCHOR_OCCURRENCES + 1) {
                continue;
            }
            $layout['sourcePdfExactSourceRanges'] = $proof['ranges'];
            $layout['sourcePdfWholeExactOccurrenceProof'] = $proof;
            $candidates[] = $layout;
        }

        return $candidates;
    }

    /**
     * A repaired list line may visibly join adjacent painted fragments even
     * though the immutable source occurrences have no presentation boundary
     * of their own. Admit that spelling only when one retained positioned
     * layout has a revalidated whole-occurrence union beginning at the exact
     * standalone marker and covering consecutive, complete same-stream
     * occurrences. The exact parsed layout remainder remains a required
     * visible prefix; individual overlapping bboxes never authorize this
     * repair by themselves.
     *
     * @param list<array<string,mixed>> $lineItems
     * @param array<string,array<string,mixed>> $dispositions
     * @param list<array<string,mixed>> $candidateProofSourceLayouts
     * @param array<string,array<string,mixed>> $targets
     * @param array<int,array{start:int,end:int,projection:string,leafEnds:list<int>}> $finalOutputPageProofs
     * @return array<int,array{
     *   significant:string,
     *   visible:string,
     *   visiblePrefixRequired:bool,
     *   sourceOccurrenceIds:list<string>,
     *   compositeLayoutPresentationReceipt:array<string,mixed>
     * }>
     */
    private function pdfExactCompositeListLayoutAnchorPrefixes(
        array $lineItems,
        array $dispositions,
        array $candidateProofSourceLayouts,
        array $targets,
        array $finalOutputPageProofs
    ): array {
        if ($lineItems === []
            || $candidateProofSourceLayouts === []
            || $targets === []
            || $finalOutputPageProofs === []) {
            return [];
        }

        $localIndexByGlobalIndex = [];
        foreach ($lineItems as $localIndex => $lineItem) {
            $globalIndex = is_int($lineItem['sourcePdfGlobalSourceIndex'] ?? null)
                ? $lineItem['sourcePdfGlobalSourceIndex']
                : $localIndex;
            $localIndexByGlobalIndex[$globalIndex] = array_key_exists(
                $globalIndex,
                $localIndexByGlobalIndex
            ) ? null : $localIndex;
        }

        $prefixes = [];
        $ambiguousMarkerIndexes = [];
        foreach ($candidateProofSourceLayouts as $layout) {
            if (!is_array($layout)) {
                continue;
            }
            $layoutText = $this->pdfTextWithoutSemanticPrefixes(
                (string) ($layout['text'] ?? '')
            );
            $parsedListItem = $this->listItem($layoutText);
            $carrierProjection = $this->pdfSourceOccurrenceComparableText($layoutText);
            $proof = is_array($layout['sourcePdfWholeExactOccurrenceProof'] ?? null)
                ? $layout['sourcePdfWholeExactOccurrenceProof']
                : null;
            $occurrences = is_array($proof['occurrences'] ?? null)
                ? array_values($proof['occurrences'])
                : [];
            if ($parsedListItem === null
                || $carrierProjection === ''
                || !$this->repairedPdfWholeExactOccurrenceProofMatchesLayout(
                    $layout,
                    $carrierProjection
                )
                || $proof === null
                || count($occurrences) < 2
                || count($occurrences) > self::MAX_PDF_LIST_MARKER_ANCHOR_OCCURRENCES + 1) {
                continue;
            }

            [$ordered, $layoutRemainder, $layoutOrdinal] = $parsedListItem;
            $listType = $ordered ? 'ordered' : 'bullet';
            $page = (int) ($proof['page'] ?? 0);
            $stream = null;
            $records = [];
            $valid = $page >= 1;
            foreach ($occurrences as $offset => $occurrence) {
                $globalIndex = is_array($occurrence)
                    && is_int($occurrence['sourceIndex'] ?? null)
                        ? $occurrence['sourceIndex']
                        : null;
                $localIndex = is_int($globalIndex)
                    && array_key_exists($globalIndex, $localIndexByGlobalIndex)
                    && is_int($localIndexByGlobalIndex[$globalIndex])
                        ? $localIndexByGlobalIndex[$globalIndex]
                        : null;
                $record = is_int($localIndex) ? ($lineItems[$localIndex] ?? null) : null;
                $recordText = is_array($record) && is_string($record['text'] ?? null)
                    ? $record['text']
                    : '';
                $recordSignificant = $this->pdfSourceOccurrenceComparableText($recordText);
                $recordStream = is_array($record) ? (int) ($record['stream'] ?? 0) : 0;
                if (!is_array($occurrence)
                    || !is_array($record)
                    || !is_int($localIndex)
                    || ($occurrence['sourceLocalIndex'] ?? null) !== $localIndex
                    || ($offset > 0
                        && $localIndex !== $records[$offset - 1]['localIndex'] + 1)
                    || (int) ($record['page'] ?? 0) !== $page
                    || $recordStream < 1
                    || ($occurrence['page'] ?? null) !== $page
                    || ($occurrence['stream'] ?? null) !== $recordStream
                    || ($stream !== null && $recordStream !== $stream)
                    || $recordSignificant === ''
                    || ($occurrence['significantBytes'] ?? null) !== strlen($recordSignificant)
                    || !is_string($occurrence['significantDigest'] ?? null)
                    || !hash_equals(
                        $occurrence['significantDigest'],
                        hash('sha256', $recordSignificant)
                    )) {
                    $valid = false;
                    break;
                }
                $stream = $recordStream;
                $records[] = [
                    'localIndex' => $localIndex,
                    'globalIndex' => $globalIndex,
                    'record' => $record,
                    'text' => $recordText,
                    'significant' => $recordSignificant,
                ];
            }
            if (!$valid || !is_int($stream) || count($records) !== count($occurrences)) {
                continue;
            }

            $marker = $records[0];
            $markerId = is_string($marker['record']['id'] ?? null)
                ? $marker['record']['id']
                : '';
            if ($markerId === ''
                || ($listType === 'ordered'
                    ? preg_match('/^\s*(\d+)[.)]\s*$/u', $marker['text'], $match) !== 1
                        || !is_int($layoutOrdinal)
                        || (int) $match[1] !== $layoutOrdinal
                    : preg_match('/^\s*([*\x{2022}\x{25CF}\x{25AA}\x{25A0}\x{2043}])\s*$/u', $marker['text']) !== 1
                        || $layoutOrdinal !== null)) {
                continue;
            }

            $anchorIds = [];
            $anchorSignificant = '';
            $anchorSourceStrictVisible = '';
            $allSourceIds = [$markerId];
            $globalSourceIndexes = [$marker['globalIndex']];
            foreach (array_slice($records, 1) as $record) {
                $sourceId = is_string($record['record']['id'] ?? null)
                    ? $record['record']['id']
                    : '';
                $disposition = is_array($dispositions[$sourceId] ?? null)
                    ? $dispositions[$sourceId]
                    : [];
                $kind = (string) ($disposition['disposition'] ?? 'emitted');
                $projection = is_string($disposition['textProjection'] ?? null)
                    ? $disposition['textProjection']
                    : $record['text'];
                if ($sourceId === ''
                    || in_array($sourceId, $allSourceIds, true)
                    || !in_array($kind, ['emitted', 'boundary-repair'], true)
                    || !hash_equals($record['text'], $projection)) {
                    $valid = false;
                    break;
                }
                $anchorIds[] = $sourceId;
                $allSourceIds[] = $sourceId;
                $globalSourceIndexes[] = $record['globalIndex'];
                $anchorSignificant .= $record['significant'];
                $anchorSourceStrictVisible .= $this->pdfStrictStructuralVisibleText(
                    $record['text']
                );
            }
            $visibleRemainder = $this->pdfStrictStructuralVisibleText(
                (string) $layoutRemainder
            );
            $visibleLayout = $this->pdfStrictStructuralVisibleText($layoutText);
            $markerIndex = $marker['localIndex'];
            $layoutRepairsAnchorPresentation = !hash_equals(
                $anchorSourceStrictVisible,
                $visibleRemainder
            );
            if (!$valid
                || count($anchorIds) < 1
                || count($anchorIds) > self::MAX_PDF_LIST_MARKER_ANCHOR_OCCURRENCES
                || $visibleRemainder === ''
                || $visibleLayout === ''
                || $anchorSourceStrictVisible === ''
                || !hash_equals(
                    $anchorSignificant,
                    $this->pdfSourceOccurrenceComparableText($visibleRemainder)
                )
                || isset($ambiguousMarkerIndexes[$markerIndex])) {
                continue;
            }

            $lastRecord = $records[array_key_last($records)];
            $followingLineItem = $lineItems[$lastRecord['localIndex'] + 1] ?? null;
            $followingId = is_array($followingLineItem)
                && is_string($followingLineItem['id'] ?? null)
                    ? $followingLineItem['id']
                    : '';
            $followingText = is_array($followingLineItem)
                && is_string($followingLineItem['text'] ?? null)
                    ? $followingLineItem['text']
                    : '';
            $followingDisposition = is_array($dispositions[$followingId] ?? null)
                ? $dispositions[$followingId]
                : [];
            $followingKind = (string) ($followingDisposition['disposition'] ?? 'emitted');
            $followingProjection = is_string(
                $followingDisposition['textProjection'] ?? null
            ) ? $followingDisposition['textProjection'] : $followingText;
            $followingSignificant = $this->pdfSourceOccurrenceComparableText(
                $followingProjection
            );
            $followingRawVisible = $this->pdfStrictStructuralVisibleText(
                $followingProjection
            );
            $followingIsExact = is_array($followingLineItem)
                && $followingId !== ''
                && (int) ($followingLineItem['page'] ?? 0) === $page
                && (int) ($followingLineItem['stream'] ?? 0) === $stream
                && in_array($followingKind, ['emitted', 'boundary-repair'], true)
                && hash_equals($followingText, $followingProjection)
                && $followingSignificant !== ''
                && $followingRawVisible !== '';
            $followingPresentationRepairReceipt = $followingIsExact
                ? $this->pdfValidatedWholeSourceListPresentationOccurrenceReceipt(
                    $followingLineItem
                )
                : null;
            if ($followingPresentationRepairReceipt !== null
                && (($followingPresentationRepairReceipt['globalSourceIndex'] ?? null)
                        !== $lastRecord['globalIndex'] + 1
                    || !hash_equals(
                        (string) $followingPresentationRepairReceipt[
                            'finalPageProjectionDigest'
                        ],
                        hash('sha256', $finalOutputPageProofs[$page]['projection'])
                    )
                    || hash_equals(
                        $followingRawVisible,
                        (string) $followingPresentationRepairReceipt['visibleProjection']
                    ))) {
                $followingPresentationRepairReceipt = null;
            }
            if (!$layoutRepairsAnchorPresentation
                && $followingPresentationRepairReceipt === null) {
                // A composite carrier whose anchor spelling is already exact
                // is useful only when its immediately following immutable
                // occurrence carries a separately validated presentation
                // repair. Otherwise this path would add no evidenced repair.
                continue;
            }
            $followingPresentationAuthorizedTargets = [];
            foreach (($followingPresentationRepairReceipt['authorizedTargets'] ?? [])
                as $authorization) {
                $followingPresentationAuthorizedTargets[
                    $authorization['significantDigest']
                        . "\0"
                        . $authorization['strictVisibleDigest']
                ] = true;
            }

            $authorizedTargets = [];
            $receiptBoundaryInitialized = false;
            $receiptContinuationBoundarySpace = null;
            $receiptFollowingId = null;
            $receiptFollowingProjectionDigest = null;
            $receiptFollowingPresentationRepairReceipt = null;
            foreach ($targets as $target) {
                $targetStrictVisible = is_string($target['strictVisible'] ?? null)
                    ? $target['strictVisible']
                    : '';
                if (($target['listType'] ?? null) !== $listType
                    || ($target['markerOrdinal'] ?? null) !== $layoutOrdinal
                    || ($target['compositeLayoutPresentationEligible'] ?? false) !== true
                    || !is_string($target['significant'] ?? null)
                    || $target['significant'] === ''
                    || !is_string($target['visible'] ?? null)
                    || $targetStrictVisible === ''
                    || !str_starts_with($target['significant'], $anchorSignificant)
                    || !str_starts_with($targetStrictVisible, $visibleRemainder)
                    || !isset($finalOutputPageProofs[$page])) {
                    continue;
                }
                $authorization = [
                    'significantDigest' => hash('sha256', $target['significant']),
                    'strictVisibleDigest' => hash('sha256', $targetStrictVisible),
                ];
                $authorizationKey = $authorization['significantDigest']
                    . "\0"
                    . $authorization['strictVisibleDigest'];
                $continuationBoundarySpace = null;
                $targetFollowingId = null;
                $targetFollowingProjectionDigest = null;
                $targetFollowingPresentationRepairReceipt = null;
                if (hash_equals($target['significant'], $anchorSignificant)) {
                    if (!hash_equals($targetStrictVisible, $visibleRemainder)) {
                        continue;
                    }
                } else {
                    if (!$followingIsExact
                        || !str_starts_with(
                            $target['significant'],
                            $anchorSignificant . $followingSignificant
                        )) {
                        continue;
                    }
                    $continuationBoundarySpace = preg_match(
                        '/^[,.;:!?\)\]\}]/u',
                        ltrim($followingProjection)
                    ) !== 1;
                    $targetFollowingVisible = $followingRawVisible;
                    if ($followingPresentationRepairReceipt !== null
                        && isset(
                            $followingPresentationAuthorizedTargets[$authorizationKey]
                        )) {
                        $targetFollowingVisible = (string)
                            $followingPresentationRepairReceipt['visibleProjection'];
                        $targetFollowingPresentationRepairReceipt =
                            $followingPresentationRepairReceipt;
                    }
                    $expectedVisiblePrefix = $visibleRemainder
                        . ($continuationBoundarySpace ? ' ' : '')
                        . $targetFollowingVisible;
                    if (!$this->pdfStructuralVisibleTextHasExactSignificantBoundaries(
                        $targetStrictVisible,
                        $target['significant'],
                        [strlen($anchorSignificant)],
                        [$continuationBoundarySpace]
                    ) || !str_starts_with(
                        $targetStrictVisible,
                        $expectedVisiblePrefix
                    )) {
                        continue;
                    }
                    $targetFollowingId = $followingId;
                    $targetFollowingProjectionDigest = hash(
                        'sha256',
                        $followingSignificant
                    );
                }
                $targetOccurrenceCount = 0;
                foreach ($finalOutputPageProofs as $proofPage => $pageProof) {
                    $pageCount = substr_count(
                        (string) ($pageProof['projection'] ?? ''),
                        $target['significant']
                    );
                    if ((int) $proofPage !== $page && $pageCount > 0) {
                        $targetOccurrenceCount += $pageCount;
                        continue;
                    }
                    $targetOccurrenceCount += $pageCount;
                }
                if ($targetOccurrenceCount !== 1
                    || substr_count(
                        $finalOutputPageProofs[$page]['projection'],
                        $target['significant']
                    ) !== 1) {
                    continue;
                }
                if ($receiptBoundaryInitialized
                    && ($receiptContinuationBoundarySpace !== $continuationBoundarySpace
                        || $receiptFollowingId !== $targetFollowingId
                        || $receiptFollowingProjectionDigest
                            !== $targetFollowingProjectionDigest
                        || $receiptFollowingPresentationRepairReceipt
                            !== $targetFollowingPresentationRepairReceipt)) {
                    continue;
                }
                $receiptBoundaryInitialized = true;
                $receiptContinuationBoundarySpace = $continuationBoundarySpace;
                $receiptFollowingId = $targetFollowingId;
                $receiptFollowingProjectionDigest = $targetFollowingProjectionDigest;
                $receiptFollowingPresentationRepairReceipt =
                    $targetFollowingPresentationRepairReceipt;
                $authorizedTargets[$authorizationKey] = $authorization;
            }
            ksort($authorizedTargets, SORT_STRING);
            $authorizedTargets = array_values($authorizedTargets);
            if ($authorizedTargets === []) {
                continue;
            }

            $receipt = [
                'version' => 1,
                'method' => 'exact-composite-list-layout-presentation-prefix',
                'sourceSha256' => $this->sourceSha256,
                'page' => $page,
                'stream' => $stream,
                'listType' => $listType,
                'markerOrdinal' => $layoutOrdinal,
                'sourceOccurrenceIds' => $allSourceIds,
                'globalSourceIndexes' => $globalSourceIndexes,
                'sourceSignificantDigest' => hash('sha256', $carrierProjection),
                'anchorSignificantDigest' => hash('sha256', $anchorSignificant),
                'layoutVisibleProjection' => $visibleLayout,
                'layoutVisibleProjectionDigest' => hash('sha256', $visibleLayout),
                'anchorVisibleProjection' => $visibleRemainder,
                'anchorVisibleProjectionDigest' => hash('sha256', $visibleRemainder),
                'finalPageProjectionDigest' => hash(
                    'sha256',
                    $finalOutputPageProofs[$page]['projection']
                ),
                'authorizedTargets' => $authorizedTargets,
                'continuationBoundarySpace' => $receiptContinuationBoundarySpace,
                'followingSourceOccurrenceId' => $receiptFollowingId,
                'followingProjectionDigest' => $receiptFollowingProjectionDigest,
                'wholeOccurrenceUnionProof' => $proof,
            ];
            if ($receiptFollowingPresentationRepairReceipt !== null) {
                $receipt['followingPresentationRepairReceipt'] =
                    $receiptFollowingPresentationRepairReceipt;
            }
            $receipt['proofDigest'] = hash('sha256', json_encode(
                $receipt,
                JSON_UNESCAPED_SLASHES
                    | JSON_UNESCAPED_UNICODE
                    | JSON_PRESERVE_ZERO_FRACTION
            ) ?: '');
            $prefix = [
                'significant' => $anchorSignificant,
                'visible' => $visibleRemainder,
                'visiblePrefixRequired' => true,
                'sourceOccurrenceIds' => $anchorIds,
                'compositeLayoutPresentationReceipt' => $receipt,
            ];
            if (isset($prefixes[$markerIndex])) {
                unset($prefixes[$markerIndex]);
                $ambiguousMarkerIndexes[$markerIndex] = true;
                continue;
            }
            $prefixes[$markerIndex] = $prefix;
        }

        return $prefixes;
    }

    /**
     * Count source markers whose strongest bounded exact prefix identifies the
     * same target. This is independent of processing order, so two markers
     * can never resolve by racing to consume one structural item.
     *
     * @param list<array<string,mixed>> $lineItems
     * @param array<string,array<string,mixed>> $dispositions
     * @param array<string,array{listType:string,markerOrdinal:?int,significant:string,visible:string}> $targets
     */
    private function pdfExactListMarkerTargetOwnerCount(
        array $lineItems,
        array $dispositions,
        string $kind,
        ?int $markerOrdinal,
        string $targetKey,
        array $targets,
        array $compositeLayoutAnchorPrefixes = []
    ): int {
        $ownerCount = 0;
        $lineItems = array_values($lineItems);
        for ($sourceIndex = 0; $sourceIndex + 1 < count($lineItems); $sourceIndex++) {
            $marker = $lineItems[$sourceIndex];
            $markerId = is_string($marker['id'] ?? null) ? $marker['id'] : '';
            $markerText = is_string($marker['text'] ?? null) ? $marker['text'] : '';
            $peerKind = null;
            $peerOrdinal = null;
            if (preg_match('/^\s*(\d+)[.)]\s*$/u', $markerText, $match) === 1) {
                $peerKind = 'ordered';
                $peerOrdinal = (int) $match[1];
            } elseif (preg_match('/^\s*([*\x{2022}\x{25CF}\x{25AA}\x{25A0}\x{2043}])\s*$/u', $markerText) === 1) {
                $peerKind = 'bullet';
            }
            if ($markerId === ''
                || $peerKind !== $kind
                || $peerOrdinal !== $markerOrdinal
                || $this->sourcePdfHasExactInlineStandaloneMarkerEvidence($marker)
                || $this->sourcePdfInlineStandaloneMarkerProofAt($lineItems, $sourceIndex) !== null) {
                continue;
            }
            $markerDisposition = is_array($dispositions[$markerId] ?? null)
                ? $dispositions[$markerId]
                : [];
            $markerDispositionKind = (string) ($markerDisposition['disposition'] ?? 'emitted');
            $markerProjection = is_string($markerDisposition['textProjection'] ?? null)
                ? $markerDisposition['textProjection']
                : $markerText;
            if (!in_array($markerDispositionKind, ['emitted', 'boundary-repair', 'semantic-structure'], true)
                || ($markerProjection !== ''
                    && !hash_equals(
                        $this->pdfSourceOccurrenceComparableText($markerText),
                        $this->pdfSourceOccurrenceComparableText($markerProjection)
                    ))) {
                continue;
            }

            $anchor = $lineItems[$sourceIndex + 1];
            $anchorId = is_string($anchor['id'] ?? null) ? $anchor['id'] : '';
            $anchorText = is_string($anchor['text'] ?? null) ? $anchor['text'] : '';
            if ($anchorId === ''
                || $anchorId === $markerId
                || $anchorText === ''
                || (int) ($marker['page'] ?? 0) < 1
                || (int) ($marker['stream'] ?? 0) < 1
                || (int) ($anchor['page'] ?? 0) !== (int) $marker['page']
                || (int) ($anchor['stream'] ?? 0) !== (int) $marker['stream']) {
                continue;
            }
            $anchorDisposition = is_array($dispositions[$anchorId] ?? null)
                ? $dispositions[$anchorId]
                : [];
            $anchorDispositionKind = (string) ($anchorDisposition['disposition'] ?? 'emitted');
            $anchorProjection = is_string($anchorDisposition['textProjection'] ?? null)
                ? $anchorDisposition['textProjection']
                : $anchorText;
            if (!in_array($anchorDispositionKind, ['emitted', 'boundary-repair'], true)) {
                continue;
            }
            $prefixGroups = [[[
                'significant' => $this->pdfSourceOccurrenceComparableText($anchorProjection),
                'visible' => $this->pdfStructuralOccurrenceComparableText($anchorProjection),
                'visiblePrefixRequired' => false,
            ]]];
            $twoOccurrencePrefixes = [];
            foreach ([
                $this->pdfExactOrdinaryListItemAnchorPrefix($lineItems, $sourceIndex + 1, $dispositions),
                $this->pdfExactWrappedListItemAnchorPrefix($lineItems, $sourceIndex + 1, $dispositions),
            ] as $prefix) {
                if (is_array($prefix)) {
                    $twoOccurrencePrefixes[] = $prefix;
                }
            }
            if ($twoOccurrencePrefixes !== []) {
                $prefixGroups[] = $twoOccurrencePrefixes;
            }
            foreach ($this->pdfExactExtendedListItemAnchorPrefixes(
                $lineItems,
                $sourceIndex + 1,
                $dispositions
            ) as $prefix) {
                $prefixGroups[] = [$prefix];
            }
            if (is_array($compositeLayoutAnchorPrefixes[$sourceIndex] ?? null)) {
                $prefixGroups[] = [$compositeLayoutAnchorPrefixes[$sourceIndex]];
            }

            $bestMatches = [];
            foreach ($prefixGroups as $prefixGroup) {
                $prefixMatches = [];
                foreach ($prefixGroup as $prefix) {
                    if (($prefix['significant'] ?? '') === '' || ($prefix['visible'] ?? '') === '') {
                        continue;
                    }
                    foreach ($targets as $candidateKey => $target) {
                        if ($target['listType'] === $kind
                            && $target['markerOrdinal'] === $markerOrdinal
                            && $this->pdfExactListItemAnchorPrefixMatches($target, $prefix)) {
                            $prefixMatches[$candidateKey] = true;
                        }
                    }
                }
                if ($prefixMatches !== []) {
                    $bestMatches = $prefixMatches;
                }
            }
            if (count($bestMatches) === 1 && isset($bestMatches[$targetKey])) {
                $ownerCount++;
            }
        }

        return $ownerCount;
    }

    /**
     * Permit the binding ledger to distinguish identical list items only when
     * the reader can prove a complete one-for-one group. Same-page peers are
     * admissible because the later ledger binds their distinct source anchors
     * to distinct live list-item IDs; page identity alone neither proves nor
     * disproves that mapping. Source
     * peers compete only when their exact local anchor or grounded two-line
     * prefix can reach at least one of the current occurrence's targets. This
     * keeps a shared first line from conflating otherwise distinct list items.
     * Every deferred target must equal the immediate anchor in full;
     * prefix-only ambiguity is never deferred. The ledger subsequently
     * requires each exact anchor edge to enter one distinct live list item and
     * rejects ambiguity or reuse.
     *
     * @param list<array<string,mixed>> $lineItems
     * @param array<string,array<string,mixed>> $dispositions
     * @param array<string,array{
     *   listType:string,
     *   markerOrdinal:?int,
     *   significant:string,
     *   visible:string
     * }> $targets
     * @param array<string,array{
     *   listType:string,
     *   markerOrdinal:?int,
     *   significant:string,
     *   visible:string
     * }> $currentMatches
     * @return array{memberCount:int,canDefer:bool}
     */
    private function pdfExactStandaloneListMarkerTargetIdentity(
        array $lineItems,
        array $dispositions,
        string $markerId,
        string $kind,
        ?int $markerOrdinal,
        string $anchorSignificant,
        string $anchorVisible,
        array $targets,
        array $currentMatches
    ): array {
        if ($markerId === '') {
            return ['memberCount' => 0, 'canDefer' => false];
        }

        $groupIsExact = $currentMatches !== [];
        $targetVisible = null;
        foreach ($currentMatches as $target) {
            if (!hash_equals($target['significant'], $anchorSignificant)) {
                $groupIsExact = false;
                break;
            }
            if ($targetVisible === null) {
                $targetVisible = $target['visible'];
            } elseif (!hash_equals($target['visible'], $targetVisible)) {
                // Equal significant characters with different complete visible
                // targets are not one interchangeable target group.
                $groupIsExact = false;
                break;
            }
        }
        $currentTargetKeys = array_fill_keys(array_keys($currentMatches), true);
        ksort($currentTargetKeys, SORT_STRING);

        $matchingMarkerIds = [];
        $matchingAnchorIds = [];
        $memberCount = 0;
        $lineItems = array_values($lineItems);
        for ($sourceIndex = 0; $sourceIndex + 1 < count($lineItems); $sourceIndex++) {
            $item = $lineItems[$sourceIndex];
            $id = is_string($item['id'] ?? null) ? $item['id'] : '';
            $text = is_string($item['text'] ?? null) ? $item['text'] : '';
            if ($id === '' || $text === '') {
                continue;
            }

            $peerKind = null;
            $peerOrdinal = null;
            if (preg_match('/^\s*(\d+)[.)]\s*$/u', $text, $orderedMatch) === 1) {
                $peerKind = 'ordered';
                $peerOrdinal = (int) $orderedMatch[1];
            } elseif (preg_match('/^\s*([*\x{2022}\x{25CF}\x{25AA}\x{25A0}\x{2043}])\s*$/u', $text) === 1) {
                $peerKind = 'bullet';
            }
            if ($peerKind !== $kind || $peerOrdinal !== $markerOrdinal) {
                continue;
            }

            $disposition = is_array($dispositions[$id] ?? null)
                ? $dispositions[$id]
                : [];
            $dispositionKind = (string) ($disposition['disposition'] ?? 'emitted');
            $markerProjection = is_string($disposition['textProjection'] ?? null)
                ? $disposition['textProjection']
                : $text;
            if (!in_array($dispositionKind, ['emitted', 'boundary-repair', 'semantic-structure'], true)
                || ($markerProjection !== ''
                    && !hash_equals(
                        $this->pdfSourceOccurrenceComparableText($text),
                        $this->pdfSourceOccurrenceComparableText($markerProjection)
                    ))) {
                continue;
            }

            $anchor = $lineItems[$sourceIndex + 1];
            $anchorId = is_string($anchor['id'] ?? null) ? $anchor['id'] : '';
            $anchorText = is_string($anchor['text'] ?? null) ? $anchor['text'] : '';
            if ($anchorId === '' || $anchorId === $id || $anchorText === ''
                || !isset($item['page'], $item['stream'], $anchor['page'], $anchor['stream'])
                || (int) $item['page'] < 1
                || (int) $item['stream'] < 1
                || (int) $item['page'] !== (int) $anchor['page']
                || (int) $item['stream'] !== (int) $anchor['stream']) {
                continue;
            }
            $anchorDisposition = is_array($dispositions[$anchorId] ?? null)
                ? $dispositions[$anchorId]
                : [];
            $anchorKind = (string) ($anchorDisposition['disposition'] ?? 'emitted');
            $anchorProjection = is_string($anchorDisposition['textProjection'] ?? null)
                ? $anchorDisposition['textProjection']
                : $anchorText;
            if (!in_array($anchorKind, ['emitted', 'boundary-repair'], true)
                || !hash_equals(
                    $this->pdfSourceOccurrenceComparableText($anchorProjection),
                    $anchorSignificant
                )
                || !hash_equals(
                    $this->pdfStructuralOccurrenceComparableText($anchorProjection),
                    $anchorVisible
                )) {
                continue;
            }

            $strictAnchorPrefixes = [];
            foreach ([
                $this->pdfExactOrdinaryListItemAnchorPrefix(
                    $lineItems,
                    $sourceIndex + 1,
                    $dispositions
                ),
                $this->pdfExactWrappedListItemAnchorPrefix(
                    $lineItems,
                    $sourceIndex + 1,
                    $dispositions
                ),
            ] as $prefix) {
                if (is_array($prefix)) {
                    $strictAnchorPrefixes[] = $prefix;
                }
            }

            $peerTargetKeys = [];
            $peerExactTargetKeys = [];
            $peerUsesPrefix = false;
            foreach ($targets as $targetKey => $target) {
                if ($target['listType'] !== $kind
                    || $target['markerOrdinal'] !== $markerOrdinal) {
                    continue;
                }
                $exactMatch = is_string($targetVisible)
                    && hash_equals($target['significant'], $anchorSignificant)
                    && hash_equals($target['visible'], $targetVisible);
                $prefixMatch = false;
                foreach ($strictAnchorPrefixes as $strictAnchorPrefix) {
                    if ($this->pdfExactListItemAnchorPrefixMatches(
                        $target,
                        $strictAnchorPrefix
                    )) {
                        $prefixMatch = true;
                        break;
                    }
                }
                if (!$exactMatch && !$prefixMatch) {
                    continue;
                }
                $peerTargetKeys[$targetKey] = true;
                if (!$exactMatch) {
                    $peerUsesPrefix = true;
                    continue;
                }
                $peerExactTargetKeys[$targetKey] = true;
            }
            if (array_intersect_key($peerTargetKeys, $currentTargetKeys) === []) {
                continue;
            }

            $memberCount++;
            if ($peerUsesPrefix
                || isset($matchingMarkerIds[$id])
                || isset($matchingAnchorIds[$anchorId])) {
                $groupIsExact = false;
            }
            $matchingMarkerIds[$id] = true;
            $matchingAnchorIds[$anchorId] = true;

            ksort($peerExactTargetKeys, SORT_STRING);
            if ($peerExactTargetKeys !== $currentTargetKeys) {
                $groupIsExact = false;
            }
        }

        return [
            'memberCount' => $memberCount,
            'canDefer' => $memberCount > 1
                && $groupIsExact
                && isset($matchingMarkerIds[$markerId])
                && count($matchingMarkerIds) === $memberCount
                && count($matchingAnchorIds) === $memberCount
                && array_intersect_key($matchingMarkerIds, $matchingAnchorIds) === []
                && count($currentTargetKeys) === $memberCount,
        ];
    }

    /**
     * @param array<string,mixed> $receipt
     * @param array<string,mixed> $prefix
     * @param array{significant:string,visible:string} $target
     */
    private function pdfExactListPresentationRepairReceiptAuthorizesTarget(
        array $receipt,
        array $prefix,
        array $target
    ): bool {
        $sourceOccurrenceIds = $receipt['sourceOccurrenceIds'] ?? null;
        $globalSourceIndexes = $receipt['globalSourceIndexes'] ?? null;
        $authorizedTargets = $receipt['authorizedTargets'] ?? null;
        $significantBoundaryOffsets = $receipt['significantBoundaryOffsets'] ?? null;
        $visibleBoundarySpaces = $receipt['visibleBoundarySpaces'] ?? null;
        if (($receipt['version'] ?? null) !== 1
            || ($receipt['method'] ?? null)
                !== 'exact-consecutive-list-presentation-repair-prefix'
            || !is_string($receipt['sourceSha256'] ?? null)
            || !hash_equals($this->sourceSha256, $receipt['sourceSha256'])
            || !is_int($receipt['page'] ?? null)
            || $receipt['page'] < 1
            || !is_int($receipt['stream'] ?? null)
            || $receipt['stream'] < 1
            || !is_array($sourceOccurrenceIds)
            || !array_is_list($sourceOccurrenceIds)
            || count($sourceOccurrenceIds) < 2
            || !is_array($globalSourceIndexes)
            || !array_is_list($globalSourceIndexes)
            || count($globalSourceIndexes) !== count($sourceOccurrenceIds)
            || !is_string($receipt['prefixProjectionDigest'] ?? null)
            || preg_match('/^[a-f0-9]{64}$/D', $receipt['prefixProjectionDigest']) !== 1
            || !is_string($receipt['visiblePrefix'] ?? null)
            || $receipt['visiblePrefix'] === ''
            || !is_string($receipt['visiblePrefixDigest'] ?? null)
            || preg_match('/^[a-f0-9]{64}$/D', $receipt['visiblePrefixDigest']) !== 1
            || !is_string($receipt['finalPageProjectionDigest'] ?? null)
            || preg_match('/^[a-f0-9]{64}$/D', $receipt['finalPageProjectionDigest']) !== 1
            || !is_array($authorizedTargets)
            || !array_is_list($authorizedTargets)
            || $authorizedTargets === []
            || !is_array($significantBoundaryOffsets)
            || !array_is_list($significantBoundaryOffsets)
            || count($significantBoundaryOffsets) !== count($sourceOccurrenceIds) - 1
            || !is_array($visibleBoundarySpaces)
            || !array_is_list($visibleBoundarySpaces)
            || count($visibleBoundarySpaces) !== count($significantBoundaryOffsets)
            || !is_string($receipt['proofDigest'] ?? null)
            || preg_match('/^[a-f0-9]{64}$/D', $receipt['proofDigest']) !== 1
            || !is_string($prefix['significant'] ?? null)
            || $prefix['significant'] === ''
            || !is_string($prefix['visible'] ?? null)
            || !hash_equals($receipt['visiblePrefix'], $prefix['visible'])
            || !hash_equals(
                $receipt['visiblePrefixDigest'],
                hash('sha256', $receipt['visiblePrefix'])
            )
            || !is_array($prefix['sourceOccurrenceIds'] ?? null)
            || $prefix['sourceOccurrenceIds'] !== $sourceOccurrenceIds
            || !hash_equals(
                $receipt['prefixProjectionDigest'],
                hash('sha256', $prefix['significant'])
            )) {
            return false;
        }

        $seenSourceIds = [];
        foreach ($sourceOccurrenceIds as $sourceIndex => $sourceOccurrenceId) {
            if (!is_string($sourceOccurrenceId)
                || $sourceOccurrenceId === ''
                || isset($seenSourceIds[$sourceOccurrenceId])
                || !is_int($globalSourceIndexes[$sourceIndex] ?? null)
                || $globalSourceIndexes[$sourceIndex] < 0
                || ($sourceIndex > 0
                    && $globalSourceIndexes[$sourceIndex]
                        !== $globalSourceIndexes[$sourceIndex - 1] + 1)) {
                return false;
            }
            $seenSourceIds[$sourceOccurrenceId] = true;
        }
        $previousBoundaryOffset = 0;
        foreach ($significantBoundaryOffsets as $boundaryIndex => $boundaryOffset) {
            if (!is_int($boundaryOffset)
                || $boundaryOffset <= $previousBoundaryOffset
                || $boundaryOffset >= strlen($prefix['significant'])
                || !is_bool($visibleBoundarySpaces[$boundaryIndex] ?? null)) {
                return false;
            }
            $previousBoundaryOffset = $boundaryOffset;
        }
        $canonicalTargets = [];
        foreach ($authorizedTargets as $authorizedTarget) {
            $significantDigest = is_array($authorizedTarget)
                ? ($authorizedTarget['significantDigest'] ?? null)
                : null;
            $strictVisibleDigest = is_array($authorizedTarget)
                ? ($authorizedTarget['strictVisibleDigest'] ?? null)
                : null;
            if (!is_string($significantDigest)
                || preg_match('/^[a-f0-9]{64}$/D', $significantDigest) !== 1
                || !is_string($strictVisibleDigest)
                || preg_match('/^[a-f0-9]{64}$/D', $strictVisibleDigest) !== 1
                || count($authorizedTarget) !== 2) {
                return false;
            }
            $canonicalTargets[$significantDigest . "\0" . $strictVisibleDigest] = [
                'significantDigest' => $significantDigest,
                'strictVisibleDigest' => $strictVisibleDigest,
            ];
        }
        ksort($canonicalTargets, SORT_STRING);
        $targetAuthorizationKey = hash('sha256', $target['significant'])
            . "\0"
            . hash('sha256', (string) ($target['strictVisible'] ?? ''));
        if ($authorizedTargets !== array_values($canonicalTargets)
            || !isset($canonicalTargets[$targetAuthorizationKey])
            || !str_starts_with(
                (string) ($target['strictVisible'] ?? ''),
                $receipt['visiblePrefix']
            )) {
            return false;
        }
        $payload = $receipt;
        unset($payload['proofDigest']);
        if (!hash_equals($receipt['proofDigest'], hash('sha256', json_encode(
            $payload,
            JSON_UNESCAPED_SLASHES
                | JSON_UNESCAPED_UNICODE
                | JSON_PRESERVE_ZERO_FRACTION
        ) ?: ''))) {
            return false;
        }

        return true;
    }

    /**
     * Whitespace repair may occur inside an immutable source occurrence, but
     * it may not create or erase the boundary between two occurrences. This
     * keeps a split word such as `informa` + `tion` from masquerading as an
     * ordinary line join while permitting source-local presentation spacing.
     *
     * @param list<int> $significantBoundaryOffsets
     * @param list<bool> $visibleBoundarySpaces
     */
    private function pdfStructuralVisibleTextHasExactSignificantBoundaries(
        string $visible,
        string $significant,
        array $significantBoundaryOffsets,
        array $visibleBoundarySpaces
    ): bool {
        $strictVisible = $this->pdfStrictStructuralVisibleText($visible);
        if ($strictVisible === ''
            || !hash_equals($strictVisible, $visible)
            || $significant === ''
            || !hash_equals(
                $significant,
                $this->pdfSourceOccurrenceComparableText($strictVisible)
            )) {
            return false;
        }
        $characters = preg_split('//u', $strictVisible, -1, PREG_SPLIT_NO_EMPTY);
        if (!is_array($characters)) {
            return false;
        }
        $significantOffset = 0;
        $separatorAtSignificantOffset = [];
        foreach ($characters as $character) {
            if ($this->pdfSourceOccurrenceComparableText($character) === '') {
                $separatorAtSignificantOffset[$significantOffset] =
                    ($separatorAtSignificantOffset[$significantOffset] ?? '')
                        . $character;
                continue;
            }
            $significantOffset += strlen(
                $this->pdfSourceOccurrenceComparableText($character)
            );
        }
        if ($significantOffset !== strlen($significant)) {
            return false;
        }
        foreach ($significantBoundaryOffsets as $boundaryIndex => $boundaryOffset) {
            $expectedSeparator = ($visibleBoundarySpaces[$boundaryIndex] ?? null) === true
                ? ' '
                : '';
            if (!is_bool($visibleBoundarySpaces[$boundaryIndex] ?? null)
                || !hash_equals(
                    $expectedSeparator,
                    $separatorAtSignificantOffset[$boundaryOffset] ?? ''
                )) {
                return false;
            }
        }

        return true;
    }

    /**
     * Significant characters identify a structural target, but an ordinary
     * line join has no authority to erase a visible word boundary. Only a
     * prefix backed by an independently revalidated boundary repair may bind
     * across a different visible projection.
     *
     * @param array{significant:string,visible:string} $target
     * @param array{
     *   significant:string,
     *   visible:string,
     *   visiblePrefixRequired:bool,
     *   sourceOccurrenceIds?:list<string>,
     *   presentationRepairReceipt?:array<string,mixed>
     * } $prefix
     */
    private function pdfExactListItemAnchorPrefixMatches(
        array $target,
        array $prefix
    ): bool {
        if (($target['significant'] ?? '') === ''
            || ($target['visible'] ?? '') === ''
            || ($prefix['significant'] ?? '') === ''
            || ($prefix['visible'] ?? '') === ''
            || !str_starts_with($target['significant'], $prefix['significant'])) {
            return false;
        }
        if (($prefix['visiblePrefixRequired'] ?? null) === false) {
            $presentationRepairReceipt = $prefix['presentationRepairReceipt'] ?? null;
            return !is_array($presentationRepairReceipt)
                || $this->pdfExactListPresentationRepairReceiptAuthorizesTarget(
                    $presentationRepairReceipt,
                    $prefix,
                    $target
                );
        }

        $compositeReceipt = is_array(
            $prefix['compositeLayoutPresentationReceipt'] ?? null
        ) ? $prefix['compositeLayoutPresentationReceipt'] : null;
        if ($compositeReceipt !== null) {
            $authorizedTargets = is_array(
                $compositeReceipt['authorizedTargets'] ?? null
            ) ? $compositeReceipt['authorizedTargets'] : [];
            $canonicalTargets = [];
            foreach ($authorizedTargets as $authorizedTarget) {
                $significantDigest = is_array($authorizedTarget)
                    ? ($authorizedTarget['significantDigest'] ?? null)
                    : null;
                $strictVisibleDigest = is_array($authorizedTarget)
                    ? ($authorizedTarget['strictVisibleDigest'] ?? null)
                    : null;
                if (!is_string($significantDigest)
                    || preg_match('/^[a-f0-9]{64}$/D', $significantDigest) !== 1
                    || !is_string($strictVisibleDigest)
                    || preg_match('/^[a-f0-9]{64}$/D', $strictVisibleDigest) !== 1
                    || count($authorizedTarget) !== 2) {
                    return false;
                }
                $canonicalTargets[$significantDigest . "\0" . $strictVisibleDigest] = [
                    'significantDigest' => $significantDigest,
                    'strictVisibleDigest' => $strictVisibleDigest,
                ];
            }
            ksort($canonicalTargets, SORT_STRING);
            $targetStrictVisible = is_string($target['strictVisible'] ?? null)
                ? $target['strictVisible']
                : '';
            $targetAuthorizationKey = hash('sha256', $target['significant'])
                . "\0"
                . hash('sha256', $targetStrictVisible);
            if ($authorizedTargets !== array_values($canonicalTargets)
                || !isset($canonicalTargets[$targetAuthorizationKey])
                || $targetStrictVisible === ''
                || !hash_equals(
                    (string) ($compositeReceipt['anchorVisibleProjection'] ?? ''),
                    $prefix['visible']
                )
                || !str_starts_with($targetStrictVisible, $prefix['visible'])) {
                return false;
            }
            $boundarySpace = $compositeReceipt['continuationBoundarySpace'] ?? null;
            if (hash_equals($target['significant'], $prefix['significant'])) {
                return $boundarySpace === null
                    && hash_equals($targetStrictVisible, $prefix['visible']);
            }

            return is_bool($boundarySpace)
                && $this->pdfStructuralVisibleTextHasExactSignificantBoundaries(
                    $targetStrictVisible,
                    $target['significant'],
                    [strlen($prefix['significant'])],
                    [$boundarySpace]
                );
        }

        return ($prefix['visiblePrefixRequired'] ?? null) === true
            && str_starts_with($target['visible'], $prefix['visible']);
    }

    /**
     * Ground an ordinary multi-line list-item prefix in two immediate source
     * occurrences. The binding ledger independently requires those exact two
     * occurrence edges to lead the live list item; using both prevents a short
     * first line from authorizing an unrelated structural target.
     *
     * @param list<array<string,mixed>> $lineItems
     * @param array<string,array<string,mixed>> $dispositions
     * @return array{
     *   significant:string,
     *   visible:string,
     *   visiblePrefixRequired:bool,
     *   sourceOccurrenceIds:list<string>,
     *   presentationRepairReceipt?:array<string,mixed>
     * }|null
     */
    private function pdfExactOrdinaryListItemAnchorPrefix(
        array $lineItems,
        int $anchorIndex,
        array $dispositions
    ): ?array {
        $anchor = $lineItems[$anchorIndex] ?? null;
        $following = $lineItems[$anchorIndex + 1] ?? null;
        if (!is_array($anchor) || !is_array($following)) {
            return null;
        }
        $anchorId = is_string($anchor['id'] ?? null) ? $anchor['id'] : '';
        $followingId = is_string($following['id'] ?? null) ? $following['id'] : '';
        $anchorText = is_string($anchor['text'] ?? null) ? $anchor['text'] : '';
        $followingText = is_string($following['text'] ?? null) ? $following['text'] : '';
        if ($anchorId === '' || $followingId === '' || $anchorId === $followingId
            || $anchorText === '' || $followingText === ''
            || !isset($anchor['page'], $anchor['stream'], $following['page'], $following['stream'])
            || (int) $anchor['page'] < 1
            || (int) $anchor['stream'] < 1
            || (int) $anchor['page'] !== (int) $following['page']
            || (int) $anchor['stream'] !== (int) $following['stream']) {
            return null;
        }

        $anchorDisposition = is_array($dispositions[$anchorId] ?? null)
            ? $dispositions[$anchorId]
            : [];
        $followingDisposition = is_array($dispositions[$followingId] ?? null)
            ? $dispositions[$followingId]
            : [];
        $anchorKind = (string) ($anchorDisposition['disposition'] ?? 'emitted');
        $followingKind = (string) ($followingDisposition['disposition'] ?? 'emitted');
        if (!in_array($anchorKind, ['emitted', 'boundary-repair'], true)
            || !in_array($followingKind, ['emitted', 'boundary-repair'], true)) {
            return null;
        }
        $anchorProjection = is_string($anchorDisposition['textProjection'] ?? null)
            ? $anchorDisposition['textProjection']
            : $anchorText;
        $followingProjection = is_string($followingDisposition['textProjection'] ?? null)
            ? $followingDisposition['textProjection']
            : $followingText;
        if (!hash_equals($anchorText, $anchorProjection)) {
            return null;
        }
        $anchorSignificant = $this->pdfSourceOccurrenceComparableText($anchorProjection);
        $followingSignificant = $this->pdfSourceOccurrenceComparableText($followingProjection);
        $anchorVisible = $this->pdfStructuralOccurrenceComparableText($anchorProjection);
        $followingVisible = $this->pdfStructuralOccurrenceComparableText($followingProjection);
        if ($anchorSignificant === '' || $followingSignificant === ''
            || $anchorVisible === '' || $followingVisible === '') {
            return null;
        }
        $visibleSeparator = preg_match(
            '/^[,.;:!?\)\]\}]/u',
            ltrim($followingProjection)
        ) === 1 ? '' : ' ';

        $significant = $anchorSignificant . $followingSignificant;
        $presentationRepairReceipt = $this->pdfExactListPresentationRepairChainReceipt(
            [$anchor, $following],
            $significant
        );
        $prefix = [
            'significant' => $significant,
            'visible' => is_array($presentationRepairReceipt)
                && is_string($presentationRepairReceipt['visiblePrefix'] ?? null)
                    ? $presentationRepairReceipt['visiblePrefix']
                    : $anchorVisible . $visibleSeparator . $followingVisible,
            'visiblePrefixRequired' => $presentationRepairReceipt === null,
            'sourceOccurrenceIds' => [$anchorId, $followingId],
        ];
        if ($presentationRepairReceipt !== null) {
            $prefix['presentationRepairReceipt'] = $presentationRepairReceipt;
        }

        return $prefix;
    }

    /**
     * A non-equal list-item prefix is exact only when the anchor ends at a
     * locally proven wrapped-word boundary and the next source occurrence is
     * the proof-bound continuation. Revalidate the evidence rather than
     * treating a short coincidental prefix as an item identity.
     *
     * @param list<array<string,mixed>> $lineItems
     * @param array<string,array<string,mixed>> $dispositions
     * @return array{
     *   significant:string,
     *   visible:string,
     *   visiblePrefixRequired:bool,
     *   sourceOccurrenceIds:list<string>
     * }|null
     */
    private function pdfExactWrappedListItemAnchorPrefix(
        array $lineItems,
        int $anchorIndex,
        array $dispositions
    ): ?array {
        $anchor = $lineItems[$anchorIndex] ?? null;
        $following = $lineItems[$anchorIndex + 1] ?? null;
        if (!is_array($anchor) || !is_array($following)) {
            return null;
        }
        $anchorId = is_string($anchor['id'] ?? null) ? $anchor['id'] : '';
        $followingId = is_string($following['id'] ?? null) ? $following['id'] : '';
        $anchorText = is_string($anchor['text'] ?? null) ? $anchor['text'] : '';
        $followingText = is_string($following['text'] ?? null) ? $following['text'] : '';
        if ($anchorId === '' || $followingId === '' || $anchorId === $followingId
            || $anchorText === '' || $followingText === ''
            || !isset($anchor['page'], $anchor['stream'], $following['page'], $following['stream'])
            || (int) $anchor['page'] < 1
            || (int) $anchor['stream'] < 1
            || (int) $anchor['page'] !== (int) $following['page']
            || (int) $anchor['stream'] !== (int) $following['stream']) {
            return null;
        }

        $anchorDisposition = is_array($dispositions[$anchorId] ?? null)
            ? $dispositions[$anchorId]
            : [];
        $followingDisposition = is_array($dispositions[$followingId] ?? null)
            ? $dispositions[$followingId]
            : [];
        $repair = is_array($anchorDisposition['evidence']['wrappedHyphenBoundaryRepair'] ?? null)
            ? $anchorDisposition['evidence']['wrappedHyphenBoundaryRepair']
            : null;
        $sourceIds = is_array($repair['sourceOccurrenceIds'] ?? null)
            ? $repair['sourceOccurrenceIds']
            : [];
        $globalIndexes = is_array($repair['sourceGlobalIndexes'] ?? null)
            ? $repair['sourceGlobalIndexes']
            : [];
        if ($repair === null
            || ($repair['method'] ?? null) !== 'exact-directional-source-wrapped-hyphen-boundary'
            || ($sourceIds['preceding'] ?? null) !== $anchorId
            || ($sourceIds['following'] ?? null) !== $followingId
            || ($globalIndexes['preceding'] ?? null) !== $anchorIndex
            || ($globalIndexes['following'] ?? null) !== $anchorIndex + 1
            || (int) ($repair['page'] ?? 0) !== (int) $anchor['page']
            || (int) ($repair['stream'] ?? 0) !== (int) $anchor['stream']
            || !in_array(
                $repair['suppressionKind'] ?? null,
                [
                    'discretionary-hard-hyphen',
                    'discretionary-soft-hyphen',
                    'semantic-soft-hyphen',
                ],
                true
            )
            || !is_string($repair['originalDigest'] ?? null)
            || !hash_equals($repair['originalDigest'], hash('sha256', $anchorText))
            || !is_string($repair['followingOriginalDigest'] ?? null)
            || !hash_equals($repair['followingOriginalDigest'], hash('sha256', $followingText))) {
            return null;
        }

        $anchorProjection = is_string($anchorDisposition['textProjection'] ?? null)
            ? $anchorDisposition['textProjection']
            : '';
        $followingKind = (string) ($followingDisposition['disposition'] ?? 'emitted');
        $followingProjection = is_string($followingDisposition['textProjection'] ?? null)
            ? $followingDisposition['textProjection']
            : $followingText;
        if ($anchorProjection === ''
            || !in_array($followingKind, ['emitted', 'boundary-repair'], true)
            || $followingProjection === ''
            || !is_string($repair['projectedDigest'] ?? null)
            || !hash_equals($repair['projectedDigest'], hash('sha256', $anchorProjection))) {
            return null;
        }

        $significant = $this->pdfSourceOccurrenceComparableText(
            $anchorProjection . $followingProjection
        );
        $visible = $this->pdfStructuralOccurrenceComparableText($anchorProjection)
            . $this->pdfStructuralOccurrenceComparableText($followingProjection);

        return $significant !== '' && $visible !== ''
            ? [
                'significant' => $significant,
                'visible' => $visible,
                'visiblePrefixRequired' => false,
                'sourceOccurrenceIds' => [$anchorId, $followingId],
            ]
            : null;
    }

    /**
     * @param list<AstNode> $blocks
     * @return array<string,array{
     *   listType:string,
     *   markerOrdinal:?int,
     *   significant:string,
     *   visible:string
     * }>
     */
    private function pdfTopLevelStructuralListItemInventory(array $blocks): array
    {
        $inventory = [];
        foreach ($blocks as $blockIndex => $block) {
            if (!$block instanceof AstNode
                || !in_array($block->type, ['ordered_list', 'bullet_list'], true)) {
                continue;
            }
            $kind = $block->type === 'ordered_list' ? 'ordered' : 'bullet';
            $start = $kind === 'ordered' ? (int) $block->attr('start', 1) : 1;
            if ($start < 1) {
                continue;
            }
            $directItemIndex = 0;
            foreach ($block->children as $childIndex => $item) {
                if (!$item instanceof AstNode || $item->type !== 'list_item') {
                    continue;
                }
                $text = $this->pdfStructuralListItemVisibleText($item);
                $significant = $this->pdfSourceOccurrenceComparableText($text);
                $visible = $this->pdfStructuralOccurrenceComparableText($text);
                $strictVisible = $this->pdfStrictStructuralVisibleText($text);
                if ($significant !== '' && $visible !== '' && $strictVisible !== '') {
                    $visibleBlockCount = 0;
                    foreach ($item->children as $itemBlock) {
                        if ($itemBlock instanceof AstNode
                            && $this->pdfStructuralOccurrenceComparableText(
                                $this->pdfAstNodeVisibleText($itemBlock)
                            ) !== '') {
                            $visibleBlockCount++;
                        }
                    }
                    $inventory[$blockIndex . ':' . $childIndex] = [
                        'listType' => $kind,
                        'markerOrdinal' => $kind === 'ordered'
                            ? $start + $directItemIndex
                            : null,
                        'significant' => $significant,
                        'visible' => $visible,
                        'strictVisible' => $strictVisible,
                        'compositeLayoutPresentationEligible' =>
                            $visibleBlockCount === 1,
                    ];
                }
                $directItemIndex++;
            }
        }

        return $inventory;
    }

    /** @param array<string,mixed> $disposition */
    private function pdfDispositionHasExactSemanticStructureProof(array $disposition): bool
    {
        $proof = is_array($disposition['semanticStructureProof'] ?? null)
            ? $disposition['semanticStructureProof']
            : null;
        if ($proof === null
            || ($disposition['disposition'] ?? null) !== 'semantic-structure'
            || ($disposition['textProjection'] ?? null) !== ''
            || ($disposition['allowOrderChange'] ?? null) !== false
            || isset($disposition['orderProof'])
            || !in_array($proof['version'] ?? null, [1, 2], true)
            || ($proof['method'] ?? null) !== 'exact-standalone-list-marker-to-item'
            || !in_array($proof['listType'] ?? null, ['ordered', 'bullet'], true)
            || !is_string($proof['markerDigest'] ?? null)
            || preg_match('/\A[0-9a-f]{64}\z/D', $proof['markerDigest']) !== 1
            || !is_string($proof['anchorSourceOccurrenceId'] ?? null)
            || $proof['anchorSourceOccurrenceId'] === ''
            || !is_string($proof['itemProjectionDigest'] ?? null)
            || preg_match('/\A[0-9a-f]{64}\z/D', $proof['itemProjectionDigest']) !== 1
            || !array_key_exists('markerOrdinal', $proof)) {
            return false;
        }

        if (($proof['version'] ?? null) === 2) {
            $anchorIds = $proof['anchorSourceOccurrenceIds'] ?? null;
            $compositeReceipt = is_array(
                $proof['compositeLayoutPresentationReceipt'] ?? null
            ) ? $proof['compositeLayoutPresentationReceipt'] : null;
            $presentationReceipt = is_array(
                $proof['presentationRepairReceipt'] ?? null
            ) ? $proof['presentationRepairReceipt'] : null;
            $receiptSourceIds = is_array($compositeReceipt['sourceOccurrenceIds'] ?? null)
                ? $compositeReceipt['sourceOccurrenceIds']
                : null;
            $hasShortCompositeReceipt = $compositeReceipt !== null
                && ($compositeReceipt['version'] ?? null) === 1
                && ($compositeReceipt['method'] ?? null)
                    === 'exact-composite-list-layout-presentation-prefix'
                && ($compositeReceipt['listType'] ?? null) === ($proof['listType'] ?? null)
                && ($compositeReceipt['markerOrdinal'] ?? null)
                    === ($proof['markerOrdinal'] ?? null)
                && is_array($receiptSourceIds)
                && array_is_list($receiptSourceIds)
                && array_slice($receiptSourceIds, 1) === $anchorIds
                && is_array($compositeReceipt['wholeOccurrenceUnionProof'] ?? null)
                && is_string($compositeReceipt['proofDigest'] ?? null)
                && preg_match(
                    '/\A[0-9a-f]{64}\z/D',
                    $compositeReceipt['proofDigest']
                ) === 1;
            $presentationReceiptIsValid = $presentationReceipt !== null
                && $compositeReceipt === null
                && ($presentationReceipt['version'] ?? null) === 1
                && ($presentationReceipt['method'] ?? null)
                    === 'exact-consecutive-list-presentation-repair-prefix'
                && ($presentationReceipt['sourceOccurrenceIds'] ?? null) === $anchorIds
                && is_string($presentationReceipt['proofDigest'] ?? null)
                && preg_match(
                    '/\A[0-9a-f]{64}\z/D',
                    $presentationReceipt['proofDigest']
                ) === 1;
            $minimumAnchorCount = $hasShortCompositeReceipt
                ? 1
                : ($presentationReceiptIsValid ? 2 : 3);
            if (!is_array($anchorIds)
                || !array_is_list($anchorIds)
                || count($anchorIds) < $minimumAnchorCount
                || count($anchorIds) > self::MAX_PDF_LIST_MARKER_ANCHOR_OCCURRENCES
                || ($anchorIds[0] ?? null) !== $proof['anchorSourceOccurrenceId']
                || count(array_unique($anchorIds, SORT_STRING)) !== count($anchorIds)
                || !is_string($proof['anchorProjectionDigest'] ?? null)
                || preg_match('/\A[0-9a-f]{64}\z/D', $proof['anchorProjectionDigest']) !== 1
                || ($presentationReceipt !== null && !$presentationReceiptIsValid)
                || ($compositeReceipt !== null && $presentationReceipt !== null)) {
                return false;
            }
            foreach ($anchorIds as $anchorId) {
                if (!is_string($anchorId) || $anchorId === '') {
                    return false;
                }
            }
        } elseif (isset($proof['anchorSourceOccurrenceIds'])
            || isset($proof['anchorProjectionDigest'])
            || isset($proof['compositeLayoutPresentationReceipt'])
            || isset($proof['presentationRepairReceipt'])) {
            return false;
        }

        return $proof['listType'] === 'ordered'
            ? is_int($proof['markerOrdinal']) && $proof['markerOrdinal'] >= 1
            : $proof['markerOrdinal'] === null;
    }

    /** @param list<AstNode> $blocks @return array{ordered:int,bullet:int} */
    private function pdfStructuralListMarkerCounts(array $blocks): array
    {
        $counts = ['ordered' => 0, 'bullet' => 0];
        $visit = function (AstNode $node) use (&$visit, &$counts): void {
            $kind = match ($node->type) {
                'ordered_list' => 'ordered',
                'bullet_list' => 'bullet',
                default => null,
            };
            if ($kind !== null) {
                foreach ($node->children as $item) {
                    if ($item instanceof AstNode && $item->type === 'list_item') {
                        $counts[$kind]++;
                    }
                }
            }
            foreach ($node->children as $child) {
                if ($child instanceof AstNode) {
                    $visit($child);
                }
            }
        };
        foreach ($blocks as $block) {
            $visit($block);
        }

        return $counts;
    }

    private function pdfStructuralOccurrenceComparableText(string $text): string
    {
        $text = $this->normalizePdfTextEncoding($text);
        if (class_exists('Normalizer')) {
            $normalized = \Normalizer::normalize($text, \Normalizer::FORM_C);
            if (is_string($normalized)) {
                $text = $normalized;
            }
        }

        return trim(preg_replace('/[\s\p{Cc}\p{Cf}]+/u', ' ', $text) ?? '');
    }

    private function pdfStrictStructuralVisibleText(string $text): string
    {
        $text = $this->normalizePdfTextEncoding($text);
        if (class_exists('Normalizer')) {
            $normalized = \Normalizer::normalize($text, \Normalizer::FORM_C);
            if (is_string($normalized)) {
                $text = $normalized;
            }
        }

        return trim($text);
    }

    /**
     * @param list<AstNode> $blocks
     * @return array<string,int>
     */
    private function pdfStructuralHeadingInventory(array $blocks): array
    {
        $inventory = [];
        $visit = function (AstNode $node) use (&$visit, &$inventory): void {
            if ($node->type === 'heading') {
                $key = $this->pdfSourceOccurrenceComparableText($this->pdfAstNodeVisibleText($node));
                if ($key !== '') {
                    $inventory[$key] = ($inventory[$key] ?? 0) + 1;
                }
            }
            foreach ($node->children as $child) {
                if ($child instanceof AstNode) {
                    $visit($child);
                }
            }
        };
        foreach ($blocks as $block) {
            $visit($block);
        }

        return $inventory;
    }

    /** @param array<string, mixed> $bounds */
    private function pdfSourceBoundsAreValid(array $bounds): bool
    {
        foreach (['x1', 'y1', 'x2', 'y2'] as $key) {
            if (!is_numeric($bounds[$key] ?? null)) {
                return false;
            }
        }

        return true;
    }

    /** @param array<string, mixed> $geometry @param array<string, mixed> $bounds */
    private function pdfSourceGeometryIntersectsBounds(array $geometry, array $bounds): bool
    {
        foreach (['x1', 'y1', 'x2', 'y2'] as $key) {
            if (!is_numeric($geometry[$key] ?? null) || !is_numeric($bounds[$key] ?? null)) {
                return false;
            }
        }
        $geometryX1 = min((float) $geometry['x1'], (float) $geometry['x2']);
        $geometryY1 = min((float) $geometry['y1'], (float) $geometry['y2']);
        $geometryX2 = max((float) $geometry['x1'], (float) $geometry['x2']);
        $geometryY2 = max((float) $geometry['y1'], (float) $geometry['y2']);
        $boundsX1 = min((float) $bounds['x1'], (float) $bounds['x2']);
        $boundsY1 = min((float) $bounds['y1'], (float) $bounds['y2']);
        $boundsX2 = max((float) $bounds['x1'], (float) $bounds['x2']);
        $boundsY2 = max((float) $bounds['y1'], (float) $bounds['y2']);

        return max($geometryX1, $boundsX1) <= min($geometryX2, $boundsX2)
            && max($geometryY1, $boundsY1) <= min($geometryY2, $boundsY2);
    }

    /** @param array<string, mixed> $geometry @return array{x1:float,y1:float,x2:float,y2:float} */
    private function pdfSourceEvidenceBounds(array $geometry): array
    {
        return [
            'x1' => round((float) ($geometry['x1'] ?? 0.0), 2),
            'y1' => round((float) ($geometry['y1'] ?? 0.0), 2),
            'x2' => round((float) ($geometry['x2'] ?? 0.0), 2),
            'y2' => round((float) ($geometry['y2'] ?? 0.0), 2),
        ];
    }

    private function pdfDocumentProfileComparableText(string $text): string
    {
        $text = preg_replace('/\s+/u', ' ', trim($text)) ?? trim($text);
        if (class_exists('Normalizer')) {
            $normalized = \Normalizer::normalize($text, \Normalizer::FORM_C);
            if (is_string($normalized)) {
                $text = $normalized;
            }
        }

        return function_exists('mb_strtolower') ? mb_strtolower($text, 'UTF-8') : strtolower($text);
    }

    private function pdfIndependentColumnSemanticTextProjection(string $text): string
    {
        $projected = preg_replace_callback(
            '/(?<![\p{L}\p{N}])([\p{Lu}\p{Lt}][\p{Lu}\p{Lt}\p{M}\p{N}\x{2019}\' .\-]{0,39})\h*:\h*(?=\p{L})/u',
            static fn (array $match): string => rtrim((string) $match[1]) . ' ',
            $text
        );

        return is_string($projected) ? $projected : $text;
    }

    /**
     * A source occurrence proves textual page representation only when the
     * final binding ledger maps it to emitted output. Evidenced dispositions
     * such as running furniture account for source content, but do not make
     * an otherwise empty physical page present in the result.
     *
     * @param array<string,mixed> $sourceDisposition
     * @return list<int>
     */
    private function pdfOutputRepresentedPageNumbers(array $sourceDisposition): array
    {
        $pages = [];
        foreach ((is_array($sourceDisposition['sourceEdges'] ?? null)
            ? $sourceDisposition['sourceEdges']
            : []) as $sourceEdge) {
            if (!is_array($sourceEdge) || ($sourceEdge['target'] ?? null) !== 'output') {
                continue;
            }
            $pages[max(1, (int) ($sourceEdge['page'] ?? 1))] = true;
        }
        $pageNumbers = array_keys($pages);
        sort($pageNumbers, SORT_NUMERIC);

        return $pageNumbers;
    }

    /**
     * @param list<array{page: int, stream: int, text: string}> $items
     */
    private function pdfTextLineItemsByteLength(array $items): int
    {
        $bytes = 0;
        foreach ($items as $index => $item) {
            $bytes += strlen($item['text']);
            if ($index > 0) {
                ++$bytes;
            }
        }

        return $bytes;
    }

    /**
     * Compatibility helper for internal callers that only need normalized
     * strings rather than source page and stream provenance.
     *
     * @param list<string> $lines
     * @return list<string>
     */
    private function normalizeLines(array $lines): array
    {
        $items = [];
        foreach ($lines as $index => $line) {
            $items[] = ['page' => 1, 'stream' => $index + 1, 'text' => $line];
        }

        return array_column($this->normalizePdfTextLineItems($items), 'text');
    }

    private function normalizePdfTextEncoding(string $text, bool $recordControlRepairs = false): string
    {
        $text = $this->repairPdfControlLigatures($text);
        if ($text !== '' && preg_match('//u', $text) !== 1) {
            $decoded = @iconv('Windows-1252', 'UTF-8//IGNORE', $text);
            if (!is_string($decoded) || $decoded === '') {
                $decoded = @iconv('UTF-8', 'UTF-8//IGNORE', $text);
            }
            if (is_string($decoded)) {
                $text = $this->repairPdfControlLigatures($decoded);
            }
        }

        return $this->sanitizePdfTextControls($text, $recordControlRepairs);
    }

    /**
     * C0/C1 controls are never valid visible PDF prose. Preserve a word
     * boundary for isolated corruption; a repeated identical control at a
     * token boundary is bounded structural evidence for one missing list
     * marker, so it becomes a single bullet. Properly decoded WinAnsi bullet
     * bytes have already become U+2022 above and never enter this fallback.
     */
    private function sanitizePdfTextControls(string $text, bool $recordRepairs): string
    {
        if ($text === '') {
            return '';
        }

        $controlClass = '[\x{0000}-\x{0008}\x{000B}\x{000C}\x{000E}-\x{001F}\x{007F}-\x{009F}]';
        $controlCount = preg_match_all('/' . $controlClass . '/u', $text);
        if ($controlCount === false || $controlCount === 0) {
            return $text;
        }
        if ($recordRepairs) {
            $this->controlCharacterRepairCount += $controlCount;
        }

        $bulletRepairs = 0;
        $text = preg_replace_callback(
            '/(^|[ \t])(' . $controlClass . '{2,})[ \t]*(?=[\p{L}\p{N}])/u',
            static function (array $match) use (&$bulletRepairs): string {
                $characters = preg_split('//u', $match[2], -1, PREG_SPLIT_NO_EMPTY) ?: [];
                if (count($characters) >= 2 && count(array_unique($characters)) === 1) {
                    $bulletRepairs++;
                    return $match[1] . "\u{2022} ";
                }

                return $match[1] . ' ';
            },
            $text
        ) ?? $text;
        if ($recordRepairs) {
            $this->controlCharacterBulletRepairCount += $bulletRepairs;
        }

        return preg_replace('/' . $controlClass . '+/u', ' ', $text) ?? $text;
    }

    private function repairPdfControlLigatures(string $text): string
    {
        if (!str_contains($text, "\x02")) {
            return $text;
        }

        return preg_replace('/((?<=\p{L})\x02(?=\p{Ll})|\x02(?=\p{Ll}))/u', 'fi', $text) ?? $text;
    }

    /**
     * @param list<array{page: int, stream: int, text: string}> $items
     * @return list<array{page: int, stream: int, text: string}>
     */
    private function limitPdfTextLineItems(array $items, int $maxBytes): array
    {
        $limited = [];
        $bytes = 0;
        foreach ($items as $item) {
            if (!$this->appendLimitedPdfTextLineItem($limited, $bytes, $item, $maxBytes)) {
                break;
            }
        }

        return $limited;
    }

    /**
     * @param list<array{page: int, stream: int, text: string}> $items
     * @param array{page: int, stream: int, text: string} $item
     */
    private function appendLimitedPdfTextLineItem(array &$items, int &$bytes, array $item, int $maxBytes): bool
    {
        if ($maxBytes <= 0) {
            return false;
        }

        $line = $item['text'];
        $nextBytes = strlen($line) + ($items === [] ? 0 : 1);
        if ($bytes + $nextBytes > $maxBytes) {
            return false;
        }

        $items[] = $item;
        $bytes += $nextBytes;

        return true;
    }

    /**
     * Keep source line facts flat while the streaming extractor has a page's
     * object graph resident. Associative records are rebuilt after extraction,
     * avoiding thousands of per-record hash tables at the extractor's peak.
     *
     * @param list<int|string> $values
     * @param array{page: int, stream: int, text: string} $item
     */
    private function appendLimitedPdfTextLineItemValues(
        array &$values,
        int &$bytes,
        array $item,
        int $maxBytes
    ): bool {
        if ($maxBytes <= 0) {
            return false;
        }

        $line = $item['text'];
        $nextBytes = strlen($line) + ($values === [] ? 0 : 1);
        if ($bytes + $nextBytes > $maxBytes) {
            return false;
        }

        $values[] = $item['page'];
        $values[] = $item['stream'];
        $values[] = $line;
        $bytes += $nextBytes;

        return true;
    }

    /**
     * @param list<array<string, mixed>> $runs
     * @return list<array<string, mixed>>
     */
    private function limitPositionedTextRuns(array $runs, int $maxBytes): array
    {
        $limited = [];
        $bytes = 0;
        foreach ($runs as $run) {
            if (!$this->appendLimitedPositionedTextRun($limited, $bytes, $run, $maxBytes)) {
                break;
            }
        }

        return $limited;
    }

    /**
     * @param list<array<string, mixed>> $runs
     * @param array<string, mixed> $run
     */
    private function appendLimitedPositionedTextRun(array &$runs, int &$bytes, array $run, int $maxBytes): bool
    {
        if ($maxBytes <= 0) {
            return false;
        }

        $text = isset($run['text']) ? (string) $run['text'] : '';
        if ($text === '') {
            return true;
        }

        $nextBytes = strlen($text) + ($runs === [] ? 0 : 1);
        if ($bytes + $nextBytes > $maxBytes) {
            return false;
        }

        $runs[] = $this->compactPdfPositionedTextRun($run);
        $bytes += $nextBytes;

        return true;
    }

    /**
     * Rebuild retained runs at the compact PHP hash-table tier. Page rotation
     * is already folded into the painted text rotation, pageObject is not a
     * positioned-run identity surface, and an omitted zero rotation is
     * exactly the fallback used by every consumer. Nonzero rotation evidence
     * remains explicit.
     *
     * @param array<string,mixed> $run
     * @return array<string,mixed>
     */
    private function compactPdfPositionedTextRun(array $run): array
    {
        $defaultHorizontalAxis = is_numeric($run['axisX'] ?? null)
            && is_numeric($run['axisY'] ?? null)
            && (float) $run['axisX'] === 1.0
            && (float) $run['axisY'] === 0.0;
        $boundarySource = is_string($run['wordBoundarySource'] ?? null)
            ? $run['wordBoundarySource']
            : null;
        $derivedWordBoundary = $this->pdfDerivedWordBoundaryBefore($boundarySource);
        $compact = [];
        foreach ($run as $key => $value) {
            if ($key === 'pageRotation'
                || $key === 'pageObject'
                || ($defaultHorizontalAxis && ($key === 'axisX' || $key === 'axisY'))
                || ($key === 'wordBoundaryBefore'
                    && $derivedWordBoundary !== null
                    && (bool) $value === $derivedWordBoundary)
                || ($key === 'rotation' && is_numeric($value) && (float) $value === 0.0)) {
                continue;
            }
            $compact[$key] = $value;
        }

        return $compact;
    }

    private function pdfDerivedWordBoundaryBefore(?string $source): ?bool
    {
        return match ($source) {
            'tj-layout', 'line-break', 'text-position-layout' => true,
            'none', 'text-position-continuation' => false,
            default => null,
        };
    }

    /**
     * @param list<array<string, mixed>> $runs
     * @return list<string>
     */
    private function linesFromPositionedTextRuns(array $runs): array
    {
        return $this->positionedLineItemTexts($this->positionedProseLineItemsFromTextRuns($runs));
    }

    /**
     * @param list<array{text: string}> $items
     * @return list<string>
     */
    private function positionedLineItemTexts(array $items): array
    {
        return array_map(static fn (array $item): string => $item['text'], $items);
    }

    /**
     * @param list<array<string,mixed>> $sourceItems
     * @param list<string> $lines
     */
    private function pdfSourceLineItemsMatchLines(array $sourceItems, array $lines): bool
    {
        if (count($sourceItems) !== count($lines)) {
            return false;
        }
        foreach ($sourceItems as $index => $sourceItem) {
            if ((string) ($sourceItem['text'] ?? '') !== $lines[$index]) {
                return false;
            }
        }

        return true;
    }

    /**
     * The ordinary text layer generally preserves words and whitespace better
     * than glyph-level positioning. When positioning can independently match
     * those lines, retain the text layer and borrow only its visual order.
     *
     * @param list<array{page: int, stream: int, text: string}> $sourceItems
     * @param list<array{text: string, page: int, x1: float, y1: float, x2: float, y2: float, fontSize: float, code?: bool, codeText?: string}> $positionedItems
     * @return array{items: list<array<string, mixed>>, geometryPages: int, geometryPageNumbers:list<int>}
     */
    private function sourceTextLineItemsInVisualOrder(
        array $sourceItems,
        array $positionedItems,
        bool $positionedItemsAreFrontMatterClassified = false
    ): array
    {
        if ($sourceItems === []) {
            return ['items' => [], 'geometryPages' => 0, 'geometryPageNumbers' => []];
        }

        if (!$positionedItemsAreFrontMatterClassified) {
            $positionedItems = $this->classifyPdfFrontMatterItems($positionedItems);
        }

        $sourceIndexesByPage = [];
        foreach ($sourceItems as $globalSourceIndex => $item) {
            // Positioned occurrence ranges retain the document-global source
            // index assigned before records are grouped by page. Preserve
            // that identity so a page-local matcher can resolve those ranges
            // without assuming that every page starts at source index zero.
            $sourceIndexesByPage[$item['page']][] = $globalSourceIndex;
        }
        $positionedIndexesByPage = [];
        foreach ($positionedItems as $positionedIndex => $item) {
            $positionedIndexesByPage[$item['page']][] = $positionedIndex;
        }

        $ordered = [];
        $geometryPages = 0;
        $geometryPageNumbers = [];
        foreach ($sourceIndexesByPage as $page => $pageSourceIndexes) {
            // A prior page can leave branch-specific candidates live because
            // PHP variables are function-scoped. Release them before the next
            // page is materialized so two page worksets never overlap.
            unset(
                $pageSourceItems,
                $pagePositionedItems,
                $positionedBodyColumns,
                $match,
                $geometryItems,
                $inventoryCompleteGeometryItems,
                $positionedColumnItems,
                $positionedBodyItems,
                $inventoryCompletePositionedItems,
                $pageFallbackItems
            );
            $pageSourceItems = [];
            foreach ($pageSourceIndexes as $globalSourceIndex) {
                $sourceItem = $sourceItems[$globalSourceIndex];
                $sourceItem['sourcePdfGlobalSourceIndex'] = $globalSourceIndex;
                $pageSourceItems[] = $sourceItem;
            }
            $pageOutputStart = count($ordered);
            $pageSourceItems = $this->removeSourcePdfOrientationRegionItems(
                $pageSourceItems,
                $this->rotatedTextRegionsByPage[(int) $page] ?? []
            );
            if ($pageSourceItems === []) {
                continue;
            }
            $pagePositionedItems = [];
            foreach ($positionedIndexesByPage[$page] ?? [] as $positionedIndex) {
                $pagePositionedItems[] = $positionedItems[$positionedIndex];
            }
            $positionedBodyColumns = $this->sourcePdfStableTextColumns($pagePositionedItems);
            $hasStablePositionedBodyColumns = $this->sourcePdfColumnsLookLikeParallelBodyColumns(
                $positionedBodyColumns
            );
            if ($hasStablePositionedBodyColumns) {
                // Match source lines only after geometry has reassembled
                // independently positioned fragments on the same baseline.
                // Otherwise a formula suffix can make its surrounding body
                // line look like an unrelated interrupted flow.
                $pagePositionedItems = $this->composePositionedPdfInlineFragmentsWithinStableColumns(
                    $pagePositionedItems,
                    $positionedBodyColumns
                );
            }
            // Apply occurrence-exact complementary composition to the page
            // candidate itself, not only to the matcher's private copy. A
            // later independent-column branch may select positioned rows
            // directly; it must not reintroduce the pre-composition local
            // permutation after the source-matched path already proved it.
            $pagePositionedItems = $this->combineComplementaryPositionedPdfExactSourceRanges(
                $pagePositionedItems,
                $pageSourceItems
            );
            if ($this->sourcePdfPageContainsReferenceList($pageSourceItems)) {
                foreach ($this->sourcePdfReferenceItemsInSourceOrder($pageSourceItems, $pagePositionedItems) as $item) {
                    $ordered[] = $item;
                }
                $this->appendSourcePdfPreservedOrientationItems(
                    $ordered,
                    $pagePositionedItems,
                    $pageOutputStart
                );
                continue;
            }
            $match = $this->matchSourcePdfLinesToPositionedItems(
                $pageSourceItems,
                $pagePositionedItems
            );
            $hasCode = $this->positionedPdfPageContainsCode($pagePositionedItems);
            $hasTextTable = $this->sourcePdfPageContainsTextTable($pageSourceItems);
            $geometryLooksUsable = $this->positionedPdfPageGeometryLooksUsable($pagePositionedItems);
            $geometryItems = [];
            if ($geometryLooksUsable) {
                $geometryMatchIsReliable = $this->sourcePdfLineGeometryMatchIsReliable($pageSourceItems, $match['sourceIndexes']);
                $geometryItems = $this->sourcePdfItemsInVisualOrder(
                    $pageSourceItems,
                    $match,
                    !$geometryMatchIsReliable
                );
                $inventoryCompleteGeometryItems = $this->sourcePdfPageItemsWithCompleteExactSourceInventory(
                    $pageSourceItems,
                    $geometryItems
                );
                $geometryInventoryComplete = $inventoryCompleteGeometryItems !== null;
                if ($inventoryCompleteGeometryItems !== null) {
                    $geometryItems = $inventoryCompleteGeometryItems;
                }
                $hasStableBodyColumns = $this->sourcePdfGeometryOrderHasStableBodyColumns($geometryItems);
                $preservesTextTable = !$hasTextTable || $this->sourcePdfGeometryOrderPreservesTextTable($geometryItems);
                $preservesCode = !$hasCode || $this->sourcePdfGeometryOrderPreservesPositionedCode(
                    $geometryItems,
                    $pagePositionedItems
                );
                if (!$hasCode
                    && !$hasTextTable
                    && !$geometryMatchIsReliable
                    && ($this->sourcePdfGeometryBodyColumnCount($geometryItems) >= 3
                        || $hasStablePositionedBodyColumns)
                    && $this->positionedPdfPageTextLooksUsable($pageSourceItems, $pagePositionedItems)) {
                    // Keep the original positioned inventory available for the
                    // orientation supplement below; stable-column ordering may
                    // consume its input once the column hypothesis is proven.
                    $positionedColumnItems = $pagePositionedItems;
                    $positionedColumnItems = $this->orderSourcePdfItemsWithinStableColumns(
                        $positionedColumnItems
                    );
                    $positionedBodyItems = $this->sourcePdfPageItemsWithCompleteExactSourceInventory(
                        $pageSourceItems,
                        $positionedColumnItems
                    );
                    if ($positionedBodyItems !== null) {
                        $geometryPages++;
                        $geometryPageNumbers[(int) $page] = true;
                        foreach ($this->markPositionedPdfParagraphBoundaries($positionedBodyItems) as $item) {
                            $ordered[] = $item;
                        }
                        $this->appendSourcePdfPreservedOrientationItems(
                            $ordered,
                            $pagePositionedItems,
                            $pageOutputStart
                        );
                        continue;
                    }
                }
                if ($geometryInventoryComplete
                    && ($geometryMatchIsReliable || $hasStableBodyColumns)
                    && $preservesTextTable
                    && $preservesCode) {
                    $geometryPages++;
                    $geometryPageNumbers[(int) $page] = true;
                    foreach ($this->markPositionedPdfParagraphBoundaries($geometryItems) as $item) {
                        $ordered[] = $item;
                    }
                    $this->appendSourcePdfPreservedOrientationItems(
                        $ordered,
                        $pagePositionedItems,
                        $pageOutputStart
                    );
                    continue;
                }
            }

            if (!$hasCode && !$hasTextTable && $geometryLooksUsable
                && $this->positionedPdfPageTextLooksUsable($pageSourceItems, $pagePositionedItems)) {
                $inventoryCompletePositionedItems = $this->sourcePdfPageItemsWithCompleteExactSourceInventory(
                    $pageSourceItems,
                    $pagePositionedItems
                );
                if ($inventoryCompletePositionedItems !== null) {
                    $geometryPages++;
                    $geometryPageNumbers[(int) $page] = true;
                    foreach ($inventoryCompletePositionedItems as $item) {
                        $ordered[] = $item;
                    }
                    $this->appendSourcePdfPreservedOrientationItems(
                        $ordered,
                        $pagePositionedItems,
                        $pageOutputStart
                    );
                    continue;
                }
            }

            $pageMapLabelGeometryEvidence = $this->positionedPdfPageMapLabelGeometryEvidence(
                $pagePositionedItems
            );
            $pageFallbackItems = $pageMapLabelGeometryEvidence === null
                ? $this->sourcePdfExactMatchedItemsInSourceFallbackOrder(
                    $pageSourceItems,
                    $geometryItems
                )
                : array_map(
                    fn (array $sourceItem, int $sourceIndex): array =>
                        $this->sourcePdfExactGeometryFallbackLineItem($sourceItem, $sourceIndex)
                            ?? $this->sourcePdfLineItem($sourceItem),
                    $pageSourceItems,
                    array_keys($pageSourceItems)
                );
            foreach ($pageFallbackItems as $fallbackItem) {
                if ($pageMapLabelGeometryEvidence !== null) {
                    // The source carrier has no trustworthy per-line bounds,
                    // but the independently decoded positioned layer proves
                    // that this page is dominated by a sustained map-label
                    // region. Carry that page-local proof forward so repair
                    // can retain the exact source inventory as one editable
                    // line block instead of certifying hundreds of glyph
                    // fragments as paragraphs or table cells.
                    $fallbackItem['sourcePdfPageMapLabelGeometryEvidence'] = $pageMapLabelGeometryEvidence;
                }
                $ordered[] = $fallbackItem;
            }
            unset($pageFallbackItems);
            $this->appendSourcePdfPreservedOrientationItems(
                $ordered,
                $pagePositionedItems,
                $pageOutputStart
            );
        }

        // The post-order passes need only the completed inventory and the two
        // immutable source carriers. Page buckets and the final iteration's
        // matching candidates otherwise remain live until this method returns
        // and overlap the whole-document proof scans at their high-water mark.
        unset(
            $sourceIndexesByPage,
            $positionedIndexesByPage,
            $page,
            $pageSourceIndexes,
            $pageSourceItems,
            $pagePositionedItems,
            $pageOutputStart,
            $positionedBodyColumns,
            $hasStablePositionedBodyColumns,
            $match,
            $hasCode,
            $hasTextTable,
            $geometryLooksUsable,
            $geometryItems,
            $geometryMatchIsReliable,
            $inventoryCompleteGeometryItems,
            $geometryInventoryComplete,
            $hasStableBodyColumns,
            $preservesTextTable,
            $preservesCode,
            $positionedColumnItems,
            $positionedBodyItems,
            $inventoryCompletePositionedItems,
            $pageMapLabelGeometryEvidence,
            $pageFallbackItems,
            $fallbackItem,
            $item,
            $globalSourceIndex,
            $positionedIndex,
            $sourceItem
        );
        $ordered = $this->promoteSourcePdfExactGeometryPanelTitles($ordered);
        $this->releaseTransientPdfMemory();
        $this->prioritizeSourcePdfVerifiedCrossColumnContinuationPagesInPlace(
            $ordered,
            $sourceItems
        );
        // A terminal hard hyphen is ambiguous in isolation. Mark only the
        // source/layout pair that proves a conventional wrapped continuation;
        // the repair stage will consume this occurrence-local marker rather
        // than turning a word shape into a document-wide replacement rule.
        $ordered = $this->logicalTextFromVisualRtlItems($ordered, $positionedItems);
        $ordered = $this->restoreSourcePdfCrossPageListContinuationRuns(
            $ordered,
            $sourceItems
        );

        return [
            'items' => $ordered,
            'geometryPages' => $geometryPages,
            'geometryPageNumbers' => array_keys($geometryPageNumbers),
        ];
    }

    /**
     * A continuation page can finish the list at the bottom of a left-hand
     * module even when the first page's right-hand module is painted before
     * it in physical page order. Stable-move only a page-leading bullet run
     * whose first exact source range immediately succeeds an open bullet item
     * on the prior page while every intervening visual record belongs to one
     * earlier, disjoint exact source interval. The resulting cross-page order
     * is retained as a signed contiguous-source scope for the final ledger.
     *
     * @param list<array<string,mixed>> $items
     * @param list<array<string,mixed>> $sourceItems
     * @return list<array<string,mixed>>
     */
    private function restoreSourcePdfCrossPageListContinuationRuns(
        array $items,
        array $sourceItems
    ): array {
        if (count($items) < 8 || count($sourceItems) < 8) {
            return $items;
        }

        $itemCount = count($items);
        for ($pageStart = 1; $pageStart < $itemCount; $pageStart++) {
            $page = max(1, (int) ($items[$pageStart]['page'] ?? 1));
            $previousPage = max(1, (int) ($items[$pageStart - 1]['page'] ?? 1));
            if ($page <= $previousPage) {
                continue;
            }
            $firstRanges = $this->pdfCrossPageListExactLayoutRanges(
                $items[$pageStart],
                $sourceItems
            );
            if ($firstRanges === null
                || !$this->pdfLineStartsWithBulletMarker((string) ($items[$pageStart]['text'] ?? ''))) {
                continue;
            }
            $firstSourceIndex = $firstRanges[0]['sourceIndex'];
            if ($firstSourceIndex < 1) {
                continue;
            }

            $runEnd = $pageStart;
            $markerCount = 0;
            $openListItem = false;
            $previousRangeEnd = null;
            while ($runEnd < $itemCount
                && max(1, (int) ($items[$runEnd]['page'] ?? 1)) === $page) {
                $ranges = $this->pdfCrossPageListExactLayoutRanges(
                    $items[$runEnd],
                    $sourceItems
                );
                if ($ranges === null) {
                    break;
                }
                $startsMarker = $this->pdfLineStartsWithBulletMarker(
                    (string) ($items[$runEnd]['text'] ?? '')
                );
                $rangeStart = $ranges[0]['sourceIndex'];
                if (!$startsMarker
                    && (!$openListItem
                        || $previousRangeEnd === null
                        || $rangeStart !== $previousRangeEnd + 1)) {
                    break;
                }
                if ($startsMarker) {
                    $markerCount++;
                }
                $text = rtrim((string) ($items[$runEnd]['text'] ?? ''));
                $openListItem = preg_match('/[.!?;:][\p{Pe}\p{Pf}]*\s*$/u', $text) !== 1;
                $previousRangeEnd = $ranges[array_key_last($ranges)]['sourceIndex'];
                $runEnd++;
            }
            if ($markerCount < 3 || $runEnd === $pageStart) {
                continue;
            }
            $runCoverage = $this->pdfCrossPageListExactCoverage(
                array_slice($items, $pageStart, $runEnd - $pageStart),
                $sourceItems
            );
            if ($runCoverage === null
                || $runCoverage['sourceIndexes'][0] !== $firstSourceIndex) {
                continue;
            }
            $runLastSourceIndex = $runCoverage['sourceIndexes'][array_key_last(
                $runCoverage['sourceIndexes']
            )];

            $anchorMatches = [];
            for ($candidateIndex = 0; $candidateIndex < $pageStart; $candidateIndex++) {
                $ranges = $this->pdfCrossPageListExactLayoutRanges(
                    $items[$candidateIndex],
                    $sourceItems
                );
                if ($ranges === null) {
                    continue;
                }
                $last = $ranges[array_key_last($ranges)];
                $sourceProjection = $this->pdfSourceOccurrenceComparableText(
                    (string) ($sourceItems[$last['sourceIndex']]['text'] ?? '')
                );
                if ($last['sourceIndex'] === $firstSourceIndex - 1
                    && $last['sourceEnd'] === strlen($sourceProjection)) {
                    $anchorMatches[] = $candidateIndex;
                }
            }
            if (count($anchorMatches) !== 1) {
                continue;
            }
            $anchorIndex = $anchorMatches[0];
            if ($anchorIndex >= $pageStart - 1) {
                continue;
            }

            $openMarkerIndex = null;
            for ($candidateIndex = $anchorIndex; $candidateIndex >= max(0, $anchorIndex - 2); $candidateIndex--) {
                if ($this->pdfLineStartsWithBulletMarker(
                    (string) ($items[$candidateIndex]['text'] ?? '')
                )) {
                    $openMarkerIndex = $candidateIndex;
                    break;
                }
            }
            if ($openMarkerIndex === null) {
                continue;
            }
            $openCoverage = $this->pdfCrossPageListExactCoverage(
                array_slice($items, $openMarkerIndex, $anchorIndex - $openMarkerIndex + 1),
                $sourceItems
            );
            $barrierItems = array_slice(
                $items,
                $anchorIndex + 1,
                $pageStart - $anchorIndex - 1
            );
            $barrierCoverage = $this->pdfCrossPageListExactCoverage(
                $barrierItems,
                $sourceItems
            );
            $barrierMarkerCount = count(array_filter(
                $barrierItems,
                fn (array $item): bool => $this->pdfLineStartsWithBulletMarker(
                    (string) ($item['text'] ?? '')
                )
            ));
            if ($openCoverage === null
                || $barrierCoverage === null
                || $barrierMarkerCount < 3
                || $barrierCoverage['sourceIndexes'][array_key_last(
                    $barrierCoverage['sourceIndexes']
                )] >= $openCoverage['sourceIndexes'][0]) {
                continue;
            }
            $anchorSource = $sourceItems[$firstSourceIndex - 1] ?? null;
            $continuationSource = $sourceItems[$firstSourceIndex] ?? null;
            if (!is_array($anchorSource)
                || !is_array($continuationSource)
                || (int) ($continuationSource['page'] ?? 0)
                    !== (int) ($anchorSource['page'] ?? 0) + 1
                || !$this->sourcePdfSourceItemHasExactGeometry($anchorSource)
                || !$this->sourcePdfSourceItemHasExactGeometry($continuationSource)) {
                continue;
            }

            $continuationRun = array_slice($items, $pageStart, $runEnd - $pageStart);
            array_splice($items, $pageStart, count($continuationRun));
            array_splice($items, $anchorIndex + 1, 0, $continuationRun);

            $scopeStart = $barrierCoverage['sourceIndexes'][0];
            $scope = $this->pdfCrossPageListContinuationOrderScope(
                $items,
                $sourceItems,
                $scopeStart,
                $runLastSourceIndex,
                $firstSourceIndex - 1,
                $firstSourceIndex,
                $barrierMarkerCount,
                $markerCount
            );
            if ($scope === null) {
                // The move is authorized only together with its complete
                // contiguous-source order scope.
                array_splice($items, $anchorIndex + 1, count($continuationRun));
                array_splice($items, $pageStart, 0, $continuationRun);
                continue;
            }
            $this->pdfCrossPageListContinuationOrderProofCandidates[] = $scope;
            foreach ($items as &$item) {
                $ranges = $this->pdfCrossPageListExactLayoutRanges($item, $sourceItems);
                if ($ranges === null) {
                    continue;
                }
                foreach ($ranges as $range) {
                    if ($range['sourceIndex'] >= $scopeStart
                        && $range['sourceIndex'] <= $runLastSourceIndex) {
                        $item['sourcePdfCrossPageListContinuationOrderProof'] = $scope;
                        break;
                    }
                }
            }
            unset($item);

            return $items;
        }

        return $items;
    }

    private function pdfLineStartsWithBulletMarker(string $text): bool
    {
        return preg_match(
            '/^\s*[*\x{2022}\x{25CF}\x{25AA}\x{25A0}\x{2043}]\s+/u',
            $this->pdfTextWithoutSemanticPrefixes($text)
        ) === 1;
    }

    /**
     * @param array<string,mixed> $layout
     * @param list<array<string,mixed>> $sourceItems
     * @return list<array{sourceIndex:int,sourceStart:int,sourceEnd:int}>|null
     */
    private function pdfCrossPageListExactLayoutRanges(
        array $layout,
        array $sourceItems
    ): ?array {
        $ranges = $this->pdfPositionedExactSourceRanges($layout);
        if ($ranges === []) {
            return null;
        }
        $projection = '';
        foreach ($ranges as $range) {
            $sourceItem = $sourceItems[$range['sourceIndex']] ?? null;
            $sourceProjection = is_array($sourceItem)
                ? $this->pdfSourceOccurrenceComparableText((string) ($sourceItem['text'] ?? ''))
                : '';
            if ($sourceProjection === ''
                || $range['sourceStart'] < 0
                || $range['sourceEnd'] <= $range['sourceStart']
                || $range['sourceEnd'] > strlen($sourceProjection)) {
                return null;
            }
            $projection .= substr(
                $sourceProjection,
                $range['sourceStart'],
                $range['sourceEnd'] - $range['sourceStart']
            );
        }
        $layoutProjection = $this->pdfSourceOccurrenceComparableText(
            $this->pdfTextWithoutSemanticPrefixes((string) ($layout['text'] ?? ''))
        );

        return $layoutProjection !== '' && hash_equals($projection, $layoutProjection)
            ? $ranges
            : null;
    }

    /**
     * @param list<array<string,mixed>> $layouts
     * @param list<array<string,mixed>> $sourceItems
     * @return array{sourceIndexes:list<int>}|null
     */
    private function pdfCrossPageListExactCoverage(
        array $layouts,
        array $sourceItems
    ): ?array {
        if ($layouts === []) {
            return null;
        }
        $segmentsBySourceIndex = [];
        $sourceIndexOrder = [];
        foreach ($layouts as $layout) {
            $ranges = $this->pdfCrossPageListExactLayoutRanges($layout, $sourceItems);
            if ($ranges === null) {
                return null;
            }
            foreach ($ranges as $range) {
                $sourceIndex = $range['sourceIndex'];
                if (!isset($segmentsBySourceIndex[$sourceIndex])) {
                    $sourceIndexOrder[] = $sourceIndex;
                }
                $segmentsBySourceIndex[$sourceIndex][] = [
                    'start' => $range['sourceStart'],
                    'end' => $range['sourceEnd'],
                ];
            }
        }
        if ($sourceIndexOrder === []
            || $sourceIndexOrder !== range(
                $sourceIndexOrder[0],
                $sourceIndexOrder[array_key_last($sourceIndexOrder)]
            )) {
            return null;
        }
        foreach ($sourceIndexOrder as $sourceIndex) {
            $sourceProjection = $this->pdfSourceOccurrenceComparableText(
                (string) ($sourceItems[$sourceIndex]['text'] ?? '')
            );
            $segments = $segmentsBySourceIndex[$sourceIndex];
            usort($segments, static fn (array $left, array $right): int =>
                ($left['start'] <=> $right['start']) ?: ($left['end'] <=> $right['end'])
            );
            $cursor = 0;
            foreach ($segments as $segment) {
                if ($segment['start'] !== $cursor || $segment['end'] <= $cursor) {
                    return null;
                }
                $cursor = $segment['end'];
            }
            if ($sourceProjection === '' || $cursor !== strlen($sourceProjection)) {
                return null;
            }
        }

        return ['sourceIndexes' => $sourceIndexOrder];
    }

    /**
     * @param list<array<string,mixed>> $layouts
     * @param list<array<string,mixed>> $sourceItems
     * @return array<string,mixed>|null
     */
    private function pdfCrossPageListContinuationOrderScope(
        array $layouts,
        array $sourceItems,
        int $scopeStart,
        int $scopeEnd,
        int $anchorSourceIndex,
        int $continuationSourceIndex,
        int $barrierMarkerCount,
        int $continuationMarkerCount
    ): ?array {
        if ($scopeStart < 0
            || $scopeEnd < $scopeStart
            || $anchorSourceIndex + 1 !== $continuationSourceIndex
            || $continuationSourceIndex > $scopeEnd) {
            return null;
        }
        $segmentsBySourceIndex = [];
        $emittedSourceIndexOrder = [];
        foreach ($layouts as $layout) {
            $ranges = $this->pdfCrossPageListExactLayoutRanges($layout, $sourceItems);
            if ($ranges === null) {
                continue;
            }
            foreach ($ranges as $range) {
                $sourceIndex = $range['sourceIndex'];
                if ($sourceIndex < $scopeStart || $sourceIndex > $scopeEnd) {
                    continue;
                }
                if (!isset($segmentsBySourceIndex[$sourceIndex])) {
                    $emittedSourceIndexOrder[] = $sourceIndex;
                }
                $segmentsBySourceIndex[$sourceIndex][] = [
                    'start' => $range['sourceStart'],
                    'end' => $range['sourceEnd'],
                ];
            }
        }
        $sourceOccurrenceIds = [];
        $sourceProjectionDigests = [];
        for ($sourceIndex = $scopeStart; $sourceIndex <= $scopeEnd; $sourceIndex++) {
            $sourceItem = $sourceItems[$sourceIndex] ?? null;
            $projection = is_array($sourceItem)
                ? $this->pdfSourceOccurrenceComparableText((string) ($sourceItem['text'] ?? ''))
                : '';
            $id = is_array($sourceItem) && is_string($sourceItem['id'] ?? null)
                ? $sourceItem['id']
                : '';
            if ($projection === '') {
                continue;
            }
            $segments = $segmentsBySourceIndex[$sourceIndex] ?? [];
            usort($segments, static fn (array $left, array $right): int =>
                ($left['start'] <=> $right['start']) ?: ($left['end'] <=> $right['end'])
            );
            $cursor = 0;
            foreach ($segments as $segment) {
                if ($segment['start'] !== $cursor || $segment['end'] <= $cursor) {
                    return null;
                }
                $cursor = $segment['end'];
            }
            if ($id === ''
                || $cursor !== strlen($projection)
                || !$this->sourcePdfSourceItemHasExactGeometry($sourceItem)) {
                return null;
            }
            $sourceOccurrenceIds[] = $id;
            $sourceProjectionDigests[] = hash('sha256', $projection);
        }
        $requiredSourceIndexes = array_values(array_filter(
            range($scopeStart, $scopeEnd),
            fn (int $sourceIndex): bool => $this->pdfSourceOccurrenceComparableText(
                (string) ($sourceItems[$sourceIndex]['text'] ?? '')
            ) !== ''
        ));
        if ($emittedSourceIndexOrder === []
            || count($emittedSourceIndexOrder) !== count(array_unique(
                $emittedSourceIndexOrder,
                SORT_NUMERIC
            ))) {
            return null;
        }
        $sortedEmitted = $emittedSourceIndexOrder;
        sort($sortedEmitted, SORT_NUMERIC);
        if ($sortedEmitted !== $requiredSourceIndexes) {
            return null;
        }

        $anchor = $sourceItems[$anchorSourceIndex];
        $continuation = $sourceItems[$continuationSourceIndex];
        $proof = [
            'version' => 1,
            'method' => 'exact-cross-page-open-list-continuation-order',
            'sourceSha256' => $this->sourceSha256,
            'scopeSourceStart' => $scopeStart,
            'scopeSourceEnd' => $scopeEnd,
            'sourceOccurrenceIds' => $sourceOccurrenceIds,
            'sourceProjectionDigests' => $sourceProjectionDigests,
            'emittedSourceIndexOrder' => $emittedSourceIndexOrder,
            'anchorSourceIndex' => $anchorSourceIndex,
            'anchorSourceOccurrenceId' => (string) $anchor['id'],
            'anchorBounds' => $this->pdfSourceEvidenceBounds($anchor['sourceGeometry']),
            'continuationSourceIndex' => $continuationSourceIndex,
            'continuationSourceOccurrenceId' => (string) $continuation['id'],
            'continuationBounds' => $this->pdfSourceEvidenceBounds(
                $continuation['sourceGeometry']
            ),
            'anchorPage' => (int) $anchor['page'],
            'continuationPage' => (int) $continuation['page'],
            'barrierMarkerCount' => $barrierMarkerCount,
            'continuationMarkerCount' => $continuationMarkerCount,
        ];
        $proof['proofDigest'] = hash('sha256', json_encode(
            $proof,
            JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_PRESERVE_ZERO_FRACTION
        ) ?: '');

        return $proof;
    }

    /**
     * A page-wide geometry hypothesis can fail because one unrelated visual
     * item is unresolved. That must veto reordering the page, but it must not
     * discard a different carrier whose complete exact ranges prove the text
     * of one source-order line. Project only those local carriers back into
     * immutable source order; every other occurrence remains an ordinary
     * exact-geometry fallback.
     *
     * @param list<array<string,mixed>> $sourceItems
     * @param list<array<string,mixed>> $geometryItems
     * @return list<array<string,mixed>>
     */
    private function sourcePdfExactMatchedItemsInSourceFallbackOrder(
        array $sourceItems,
        array $geometryItems
    ): array {
        $tableSourceGroups = $this->sourcePdfTableSourceGroups($sourceItems);
        $matchedItemsBySourceIndex = [];
        $ambiguousSourceIndexes = [];
        foreach ($geometryItems as $candidate) {
            if (!$this->sourcePdfItemHasExactPositionedText($candidate)) {
                continue;
            }
            $candidateSourceIndex = $candidate['sourcePdfSourceIndex'] ?? null;
            if (!is_int($candidateSourceIndex) || $candidateSourceIndex < 0) {
                continue;
            }
            if (isset($matchedItemsBySourceIndex[$candidateSourceIndex])) {
                unset($matchedItemsBySourceIndex[$candidateSourceIndex]);
                $ambiguousSourceIndexes[$candidateSourceIndex] = true;
                continue;
            }
            if (!isset($ambiguousSourceIndexes[$candidateSourceIndex])) {
                $matchedItemsBySourceIndex[$candidateSourceIndex] = $candidate;
            }
        }

        $items = [];
        for ($sourceIndex = 0, $sourceCount = count($sourceItems); $sourceIndex < $sourceCount;) {
            $sourceItem = $sourceItems[$sourceIndex];
            $candidate = $matchedItemsBySourceIndex[$sourceIndex] ?? null;
            $coverage = is_array($candidate) && $this->sourcePdfItemHasExactPositionedText($candidate)
                ? $this->sourcePdfExactRangeCoverage(
                    $sourceItems,
                    $this->pdfPositionedExactSourceRanges($candidate),
                    (int) ($sourceItem['page'] ?? 0),
                    true
                )
                : null;
            $coverageIndexes = is_array($coverage['localIndexes'] ?? null)
                ? $coverage['localIndexes']
                : [];
            $coverageEnd = $coverageIndexes === []
                ? null
                : $coverageIndexes[array_key_last($coverageIndexes)];
            $candidateProjection = is_array($candidate)
                ? $this->pdfSourceOccurrenceComparableText((string) ($candidate['text'] ?? ''))
                : '';
            $candidateText = is_array($candidate) ? (string) ($candidate['text'] ?? '') : '';
            $sourceText = (string) ($sourceItem['text'] ?? '');
            $coverageProjection = is_array($coverage)
                ? (string) ($coverage['projection'] ?? '')
                : '';
            $multipleOccurrences = count($coverageIndexes) > 1;
            $coversTableSource = count(array_filter(
                $coverageIndexes,
                static fn (int $index): bool => isset($tableSourceGroups[$index])
            )) > 0;

            if ($coverageIndexes !== []
                && $coverageIndexes[0] === $sourceIndex
                && is_int($coverageEnd)
                && $coverageEnd >= $sourceIndex
                && $candidateProjection !== ''
                && hash_equals($coverageProjection, $candidateProjection)
                && !$coversTableSource
                // An unchanged one-occurrence carrier contributes no new
                // separator proof. Keeping the ordinary exact fallback also
                // preserves its established structural/list classification.
                && ($multipleOccurrences || !hash_equals($sourceText, $candidateText))
                && (!$multipleOccurrences
                    || ($candidate['sourcePdfExactRangeFragmentSequence'] ?? false) === true)) {
                $fallback = $this->sourcePdfExactGeometryFallbackLineItem($sourceItem, $sourceIndex);
                if ($fallback !== null) {
                    if ($multipleOccurrences) {
                        // A composite carrier represents every listed range;
                        // retaining the first occurrence's scalar ID/global
                        // identity would falsely collapse that union back to
                        // one source record.
                        unset(
                            $candidate['id'],
                            $candidate['sourcePdfGlobalSourceIndex'],
                            $candidate['sourcePdfExactGeometryFallback'],
                            $candidate['sourceGeometry'],
                            $candidate['sourceGeometryMethod']
                        );
                        $candidate['sourcePdfSourceIndex'] = $sourceIndex;
                        $candidate['sourcePdfSourceIndexEnd'] = $coverageEnd;
                        $candidate['sourcePdfSourceIndexes'] = $coverageIndexes;
                        $candidate['sourcePdfGlobalSourceIndexes'] = array_map(
                            static fn (int $index): int => is_int(
                                $sourceItems[$index]['sourcePdfGlobalSourceIndex'] ?? null
                            )
                                ? $sourceItems[$index]['sourcePdfGlobalSourceIndex']
                                : $index,
                            $coverageIndexes
                        );
                        // The carrier came from visual-order matching, whose
                        // sourceOrder values describe paint atoms. Once it is
                        // projected into fallback order those values must use
                        // the fallback's immutable occurrence namespace, or a
                        // later stable sort can displace the proved carrier.
                        $candidate['sourceOrderStart'] = $candidate['sourcePdfGlobalSourceIndexes'][0];
                        $candidate['sourceOrderEnd'] = $candidate['sourcePdfGlobalSourceIndexes'][
                            array_key_last($candidate['sourcePdfGlobalSourceIndexes'])
                        ];
                        $candidate['sourcePdfFallbackOrderProjection'] = true;
                        $candidate['sourcePdfProtectedSemanticContent'] = true;
                        $items[] = $candidate;
                    } else {
                        // Preserve the exact source occurrence identity and
                        // geometry while borrowing only the carrier's proved
                        // intra-occurrence separators.
                        $projected = array_replace($fallback, $candidate);
                        foreach ([
                            'id',
                            'sourcePdfGlobalSourceIndex',
                            'sourceOrderStart',
                            'sourceOrderEnd',
                            'sourcePdfSourceIndex',
                            'sourcePdfSourceIndexEnd',
                            'sourcePdfSourceIndexes',
                            'sourcePdfExactSourceRanges',
                            'sourceGeometry',
                            'sourceGeometryMethod',
                            'sourceStream',
                            'sourcePdfExactGeometryFallback',
                            'sourceUnmatchedFallback',
                            'sourcePdfProtectedSemanticContent',
                        ] as $identityField) {
                            if (array_key_exists($identityField, $fallback)) {
                                $projected[$identityField] = $fallback[$identityField];
                            } else {
                                unset($projected[$identityField]);
                            }
                        }
                        $projected['sourcePdfFallbackOrderProjection'] = true;
                        $items[] = $projected;
                    }
                    $sourceIndex = $coverageEnd + 1;
                    continue;
                }
            }

            $items[] = $this->sourcePdfExactGeometryFallbackLineItem($sourceItem, $sourceIndex)
                ?? $this->sourcePdfLineItem($sourceItem);
            $sourceIndex++;
        }

        return $items;
    }

    /**
     * A damaged map text layer can be too fragmented for exact per-line
     * reconciliation even though the independent positioned layer clearly
     * describes one sustained spatial label region. Record only that
     * page-level fact; it does not lend invented coordinates to any source
     * occurrence or authorize reordering its exact character stream.
     *
     * @param list<array<string, mixed>> $positionedItems
     * @return array{kind:string,page:int,positionedRecordCount:int,mapLabelRecordCount:int,sourceSha256:string}|null
     */
    private function positionedPdfPageMapLabelGeometryEvidence(array $positionedItems): ?array
    {
        $records = [];
        $page = null;
        foreach ($positionedItems as $item) {
            if (!$this->pdfLayoutHasGeometry($item)) {
                continue;
            }
            $itemPage = (int) ($item['page'] ?? 0);
            if ($itemPage < 1 || ($page !== null && $itemPage !== $page)) {
                return null;
            }
            $page = $itemPage;
            $records[] = [
                'text' => (string) ($item['text'] ?? ''),
                'layout' => $item,
            ];
        }
        $recordCount = count($records);
        if ($page === null || $recordCount < 8) {
            return null;
        }

        $classified = $this->removeLowCoherencePdfMapRegions($records);
        $mapLabelCount = count(array_filter(
            $classified,
            static fn (array $record): bool => str_starts_with(
                (string) ($record['text'] ?? ''),
                self::PDF_MAP_LABEL_PREFIX
            )
        ));
        if ($mapLabelCount < 8 || $mapLabelCount / $recordCount < 0.72) {
            return null;
        }

        return [
            'kind' => 'positioned-sustained-map-label-region',
            'page' => $page,
            'positionedRecordCount' => $recordCount,
            'mapLabelRecordCount' => $mapLabelCount,
            'sourceSha256' => $this->sourceSha256,
        ];
    }

    /**
     * Restore source occurrences whose exact stream-aligned geometry survived
     * even though heuristic matching did not. A repaired page is accepted
     * only when every significant source occurrence is represented exactly
     * once and the page-wide UTF-8 character inventory is unchanged.
     * Positioned supplements deliberately cannot satisfy this proof.
     *
     * @param list<array<string, mixed>> $sourceItems
     * @param list<array<string, mixed>> $items
     * @return list<array<string, mixed>>|null
     */
    private function sourcePdfPageItemsWithCompleteExactSourceInventory(
        array $sourceItems,
        array $items
    ): ?array {
        $evidence = $this->sourcePdfPageCandidateSourceInventoryEvidence($sourceItems, $items);
        if ($evidence === null || $evidence['partialSourceIndexes'] !== []) {
            return null;
        }

        $restored = false;
        foreach ($sourceItems as $sourceIndex => $sourceItem) {
            $significant = $this->pdfSourceOccurrenceComparableText(
                (string) ($sourceItem['text'] ?? '')
            );
            if ($significant === '' || isset($evidence['sourceIndexes'][$sourceIndex])) {
                continue;
            }
            $fallback = $this->sourcePdfExactGeometryFallbackLineItem(
                $sourceItem,
                $sourceIndex
            );
            if ($fallback === null) {
                return null;
            }
            $items[] = $fallback;
            $restored = true;
        }

        if ($restored) {
            $items = $this->orderSourcePdfItemsWithinStableColumns($items);
            // Exact-geometry fallbacks which do not land inside a stable body
            // column are deliberately retained as floating page inventory.
            // Reapply the existing occurrence-local continuation proof after
            // that ordering pass so an immediately adjacent comma/lower-case
            // source continuation is not left at the page tail.
            $items = $this->restoreSourcePdfAdjacentVisualContinuations(
                $items,
                $sourceItems
            );
        }
        // A recursive column hypothesis can isolate an indented sentence
        // tail even though its complete exact ranges and paint order make it
        // the unique punctuation continuation of the preceding carrier.
        // Repair that one occurrence only after the whole page inventory has
        // proved that every significant source byte is represented once.
        $items = $this->restoreSourcePdfExactPaintedPunctuationContinuations(
            $sourceItems,
            $items
        );
        $evidence = $this->sourcePdfPageCandidateSourceInventoryEvidence($sourceItems, $items);
        if ($evidence === null || $evidence['partialSourceIndexes'] !== []) {
            return null;
        }

        $requiredSourceIndexes = [];
        $sourceProjection = '';
        foreach ($sourceItems as $sourceIndex => $sourceItem) {
            $significant = $this->pdfSourceOccurrenceComparableText(
                (string) ($sourceItem['text'] ?? '')
            );
            if ($significant === '') {
                continue;
            }
            $requiredSourceIndexes[$sourceIndex] = true;
            $sourceProjection .= $significant;
        }
        if (array_keys($requiredSourceIndexes) !== array_keys($evidence['sourceIndexes'])
            || $this->pdfExactCharacterInventory($sourceProjection)
                !== $this->pdfExactCharacterInventory($evidence['projection'])) {
            return null;
        }

        foreach ($items as &$item) {
            $item['sourcePdfPageExactInventoryPreserved'] = true;
        }
        unset($item);

        return $items;
    }

    /**
     * A positioned-only repair source has no source-matched fallback records
     * mixed into it. Admit that candidate only when its parser-derived exact
     * ranges cover every significant immutable source occurrence once on each
     * page and conserve the complete page character inventory. Unlike the
     * geometry-order helper above, this gate must not restore a missing source
     * occurrence: any loss selects the immutable source-order fallback instead.
     *
     * @param list<array<string,mixed>> $sourceItems
     * @param list<array<string,mixed>> $positionedItems
     * @return list<array<string,mixed>>|null
     */
    private function positionedProseItemsWithCompleteExactSourceInventory(
        array $sourceItems,
        array $positionedItems
    ): ?array {
        if ($sourceItems === [] || $positionedItems === []) {
            return null;
        }

        $sourceByPage = [];
        $sourceByGlobalIndex = [];
        foreach (array_values($sourceItems) as $globalSourceIndex => $sourceItem) {
            if (!is_array($sourceItem)) {
                return null;
            }
            $declaredGlobalSourceIndex = $sourceItem['sourcePdfGlobalSourceIndex'] ?? null;
            if ($declaredGlobalSourceIndex !== null
                && (!is_int($declaredGlobalSourceIndex)
                    || $declaredGlobalSourceIndex !== $globalSourceIndex)) {
                return null;
            }
            $page = max(1, (int) ($sourceItem['page'] ?? 1));
            $sourceItem['sourcePdfGlobalSourceIndex'] = $globalSourceIndex;
            $sourceByPage[$page][] = $sourceItem;
            $sourceByGlobalIndex[$globalSourceIndex] = $sourceItem;
        }

        $strictPositionedByPage = [];
        foreach ($positionedItems as $positionedItem) {
            if (!is_array($positionedItem)) {
                return null;
            }
            $significant = $this->pdfSourceOccurrenceComparableText(
                (string) ($positionedItem['text'] ?? '')
            );
            if ($significant === '') {
                continue;
            }
            $page = max(1, (int) ($positionedItem['page'] ?? 1));
            if (!isset($sourceByPage[$page])) {
                return null;
            }
            $ranges = $this->pdfPositionedExactSourceRanges($positionedItem);
            if ($ranges === []) {
                return null;
            }
            foreach ($ranges as $range) {
                $sourceItem = $sourceByGlobalIndex[$range['sourceIndex']] ?? null;
                $sourceGeometry = is_array($sourceItem['sourceGeometry'] ?? null)
                    ? $sourceItem['sourceGeometry']
                    : null;
                if (!is_array($sourceItem)
                    || (int) ($sourceItem['page'] ?? 0) !== $page
                    || !$this->sourcePdfSourceItemHasExactGeometry($sourceItem)
                    || (int) ($sourceGeometry['page'] ?? 0) !== $page
                    || (int) ($sourceGeometry['stream'] ?? 0)
                        !== (int) ($sourceItem['stream'] ?? 0)
                    || (isset($positionedItem['sourceStream'])
                        && (int) $positionedItem['sourceStream']
                            !== (int) ($sourceItem['stream'] ?? 0))) {
                    return null;
                }
            }

            // Force the shared evidence checker through the parser-derived
            // byte ranges. Scalar source-index hints are useful to source-
            // matched fallbacks, but are not sufficient proof for selecting
            // a wholly positioned document source.
            $strictPositionedItem = $positionedItem;
            $strictPositionedItem['sourcePdfExactSourceRanges'] = $ranges;
            unset(
                $strictPositionedItem['sourcePdfSourceIndexes'],
                $strictPositionedItem['sourcePdfSourceIndex'],
                $strictPositionedItem['sourcePdfSourceIndexEnd'],
                $strictPositionedItem['sourcePdfExactSourceIndex'],
                $strictPositionedItem['sourcePdfExactSourceStart'],
                $strictPositionedItem['sourcePdfExactSourceEnd']
            );
            $strictPositionedByPage[$page][] = $strictPositionedItem;
        }

        foreach ($sourceByPage as $page => $pageSourceItems) {
            $requiredSourceIndexes = [];
            $sourceProjection = '';
            foreach ($pageSourceItems as $sourceIndex => $sourceItem) {
                $significant = $this->pdfSourceOccurrenceComparableText(
                    (string) ($sourceItem['text'] ?? '')
                );
                if ($significant === '') {
                    continue;
                }
                $requiredSourceIndexes[$sourceIndex] = true;
                $sourceProjection .= $significant;
            }
            if ($requiredSourceIndexes === []) {
                continue;
            }
            $evidence = $this->sourcePdfPageCandidateSourceInventoryEvidence(
                $pageSourceItems,
                $strictPositionedByPage[$page] ?? []
            );
            if ($evidence === null
                || $evidence['partialSourceIndexes'] !== []
                || array_keys($requiredSourceIndexes) !== array_keys($evidence['sourceIndexes'])
                || $this->pdfExactCharacterInventory($sourceProjection)
                    !== $this->pdfExactCharacterInventory($evidence['projection'])) {
                return null;
            }
        }

        foreach ($positionedItems as &$positionedItem) {
            $positionedItem['sourcePdfPageExactInventoryPreserved'] = true;
            $positionedItem['sourcePdfPositionedOnlyExactInventoryPreserved'] = true;
        }
        unset($positionedItem);

        return $positionedItems;
    }

    /**
     * @param list<array<string, mixed>> $sourceItems
     * @param list<array<string, mixed>> $items
     * @return array{sourceIndexes: array<int, true>,partialSourceIndexes:array<int,true>,projection:string}|null
     */
    private function sourcePdfPageCandidateSourceInventoryEvidence(
        array $sourceItems,
        array $items
    ): ?array {
        $coveredRangesBySourceIndex = [];
        $projection = '';
        foreach ($items as $item) {
            $significant = $this->pdfSourceOccurrenceComparableText(
                (string) ($item['text'] ?? '')
            );
            if ($significant === '') {
                continue;
            }
            if (($item['sourceSupplementalPositioned'] ?? false) === true
                || ($item['sourceShortSupplementalCandidate'] ?? false) === true) {
                return null;
            }

            $itemSourceRanges = $this->sourcePdfPageCandidateSourceRanges(
                $sourceItems,
                $item
            );
            if ($itemSourceRanges === null || $itemSourceRanges === []) {
                return null;
            }
            $sourceItemProjection = '';
            foreach ($itemSourceRanges as $sourceRange) {
                $sourceIndex = $sourceRange['sourceIndex'];
                if (!isset($sourceItems[$sourceIndex])) {
                    return null;
                }
                $sourceSignificant = $this->pdfSourceOccurrenceComparableText(
                    (string) ($sourceItems[$sourceIndex]['text'] ?? '')
                );
                $sourceItemProjection .= substr(
                    $sourceSignificant,
                    $sourceRange['sourceStart'],
                    $sourceRange['sourceEnd'] - $sourceRange['sourceStart']
                );
                $coveredRangesBySourceIndex[$sourceIndex][] = $sourceRange;
            }
            if ($this->pdfExactCharacterInventory($significant)
                !== $this->pdfExactCharacterInventory($sourceItemProjection)) {
                return null;
            }
            $projection .= $significant;
        }
        $sourceIndexes = [];
        $partialSourceIndexes = [];
        foreach ($coveredRangesBySourceIndex as $sourceIndex => $sourceRanges) {
            usort($sourceRanges, static fn (array $left, array $right): int =>
                ($left['sourceStart'] <=> $right['sourceStart'])
                    ?: ($left['sourceEnd'] <=> $right['sourceEnd'])
            );
            $cursor = 0;
            foreach ($sourceRanges as $sourceRange) {
                if ($sourceRange['sourceStart'] !== $cursor) {
                    return null;
                }
                $cursor = $sourceRange['sourceEnd'];
            }
            $sourceLength = strlen($this->pdfSourceOccurrenceComparableText(
                (string) ($sourceItems[$sourceIndex]['text'] ?? '')
            ));
            if ($cursor === $sourceLength) {
                $sourceIndexes[$sourceIndex] = true;
            } else {
                $partialSourceIndexes[$sourceIndex] = true;
            }
        }
        ksort($sourceIndexes, SORT_NUMERIC);
        ksort($partialSourceIndexes, SORT_NUMERIC);

        return [
            'sourceIndexes' => $sourceIndexes,
            'partialSourceIndexes' => $partialSourceIndexes,
            'projection' => $projection,
        ];
    }

    /**
     * @param list<array<string, mixed>> $sourceItems
     * @param array<string, mixed> $item
     * @return list<array{sourceIndex:int,sourceStart:int,sourceEnd:int}>|null
     */
    private function sourcePdfPageCandidateSourceRanges(array $sourceItems, array $item): ?array
    {
        $ranges = [];
        if (is_array($item['sourcePdfSourceIndexes'] ?? null)) {
            foreach ($item['sourcePdfSourceIndexes'] as $sourceIndex) {
                if (!is_int($sourceIndex) || !isset($sourceItems[$sourceIndex])) {
                    return null;
                }
                $sourceLength = strlen($this->pdfSourceOccurrenceComparableText(
                    (string) ($sourceItems[$sourceIndex]['text'] ?? '')
                ));
                if ($sourceLength > 0) {
                    $ranges[] = [
                        'sourceIndex' => $sourceIndex,
                        'sourceStart' => 0,
                        'sourceEnd' => $sourceLength,
                    ];
                }
            }
        } elseif (is_int($item['sourcePdfSourceIndex'] ?? null)) {
            $start = $item['sourcePdfSourceIndex'];
            $end = is_int($item['sourcePdfSourceIndexEnd'] ?? null)
                ? $item['sourcePdfSourceIndexEnd']
                : $start;
            if ($end < $start || !isset($sourceItems[$start], $sourceItems[$end])) {
                return null;
            }
            foreach (range($start, $end) as $sourceIndex) {
                $sourceLength = strlen($this->pdfSourceOccurrenceComparableText(
                    (string) ($sourceItems[$sourceIndex]['text'] ?? '')
                ));
                if ($sourceLength > 0) {
                    $ranges[] = [
                        'sourceIndex' => $sourceIndex,
                        'sourceStart' => 0,
                        'sourceEnd' => $sourceLength,
                    ];
                }
            }
        } else {
            $localIndexByGlobalIndex = [];
            foreach ($sourceItems as $localIndex => $sourceItem) {
                $globalIndex = is_int($sourceItem['sourcePdfGlobalSourceIndex'] ?? null)
                    ? $sourceItem['sourcePdfGlobalSourceIndex']
                    : $localIndex;
                if (isset($localIndexByGlobalIndex[$globalIndex])) {
                    return null;
                }
                $localIndexByGlobalIndex[$globalIndex] = $localIndex;
            }
            foreach ($this->pdfPositionedExactSourceRanges($item) as $sourceRange) {
                $sourceIndex = $localIndexByGlobalIndex[$sourceRange['sourceIndex']] ?? null;
                $sourceItem = is_int($sourceIndex) ? ($sourceItems[$sourceIndex] ?? null) : null;
                $sourceLength = is_array($sourceItem)
                    ? strlen($this->pdfSourceOccurrenceComparableText(
                        (string) ($sourceItem['text'] ?? '')
                    ))
                    : 0;
                if (!is_array($sourceItem)
                    || !$this->sourcePdfSourceItemHasExactGeometry($sourceItem)
                    || (int) ($sourceItem['page'] ?? 0) !== (int) ($item['page'] ?? 0)
                    || $sourceRange['sourceStart'] < 0
                    || $sourceRange['sourceEnd'] <= $sourceRange['sourceStart']
                    || $sourceRange['sourceEnd'] > $sourceLength) {
                    return null;
                }
                $ranges[] = [
                    'sourceIndex' => $sourceIndex,
                    'sourceStart' => $sourceRange['sourceStart'],
                    'sourceEnd' => $sourceRange['sourceEnd'],
                ];
            }
        }

        return $ranges === [] ? null : $ranges;
    }

    /**
     * @param list<array<string, mixed>> $sourceItems
     * @param array<string, mixed> $item
     * @return array{start:int,end:int,page:int,stream:int}|null
     */
    private function sourcePdfPageItemExactOccurrenceRangeIdentity(
        array $sourceItems,
        array $item
    ): ?array {
        $ranges = $this->sourcePdfPageCandidateSourceRanges($sourceItems, $item);
        if ($ranges === null || $ranges === []) {
            return null;
        }

        $sourceProjection = '';
        $sourceIndexes = [];
        $page = null;
        $stream = null;
        foreach ($ranges as $rangeIndex => $range) {
            $sourceIndex = $range['sourceIndex'];
            $sourceItem = $sourceItems[$sourceIndex] ?? null;
            if (!is_array($sourceItem)) {
                return null;
            }
            $sourceSignificant = $this->pdfSourceOccurrenceComparableText(
                (string) ($sourceItem['text'] ?? '')
            );
            $sourcePage = is_int($sourceItem['page'] ?? null)
                ? $sourceItem['page']
                : null;
            $sourceStream = is_int($sourceItem['stream'] ?? null)
                ? $sourceItem['stream']
                : null;
            if ($sourceSignificant === ''
                || $sourcePage === null
                || $sourceStream === null
                || $sourceStream < 1
                || ($item['page'] ?? null) !== $sourcePage
                || $range['sourceStart'] !== 0
                || $range['sourceEnd'] !== strlen($sourceSignificant)
                || ($rangeIndex > 0
                    && $sourceIndex !== $sourceIndexes[$rangeIndex - 1] + 1)
                || ($page !== null && $sourcePage !== $page)
                || ($stream !== null && $sourceStream !== $stream)) {
                return null;
            }
            $sourceIndexes[] = $sourceIndex;
            $sourceProjection .= $sourceSignificant;
            $page = $sourcePage;
            $stream = $sourceStream;
        }

        $itemProjection = $this->pdfSourceOccurrenceComparableText(
            (string) ($item['text'] ?? '')
        );
        if ($sourceIndexes === []
            || $page === null
            || $stream === null
            || !hash_equals($sourceProjection, $itemProjection)) {
            return null;
        }

        return [
            'start' => $sourceIndexes[0],
            'end' => $sourceIndexes[array_key_last($sourceIndexes)],
            'page' => $page,
            'stream' => $stream,
        ];
    }

    /**
     * Reattach a displaced punctuation-leading painted carrier only when its
     * complete ordered ranges are the unique immediate source successor and
     * its paint atoms are contiguous with the preceding exact carrier.
     *
     * @param list<array<string, mixed>> $sourceItems
     * @param list<array<string, mixed>> $items
     * @return list<array<string, mixed>>
     */
    private function restoreSourcePdfExactPaintedPunctuationContinuations(
        array $sourceItems,
        array $items
    ): array {
        if (count($items) < 3) {
            return $items;
        }

        $identities = array_map(
            fn (array $item): ?array => $this->sourcePdfPageItemExactOccurrenceRangeIdentity(
                $sourceItems,
                $item
            ),
            $items
        );
        $count = count($items);
        for ($index = 0; $index < $count - 1; $index++) {
            $identity = $identities[$index] ?? null;
            if (!is_array($identity)) {
                continue;
            }

            $candidateIndexes = [];
            for ($candidateIndex = $index + 1; $candidateIndex < $count; $candidateIndex++) {
                $candidateIdentity = $identities[$candidateIndex] ?? null;
                if (!is_array($candidateIdentity)
                    || $candidateIdentity['start'] !== $identity['end'] + 1
                    || $candidateIdentity['page'] !== $identity['page']
                    || $candidateIdentity['stream'] !== $identity['stream']) {
                    continue;
                }
                $left = array_replace($items[$index], [
                    'sourceStream' => $identity['stream'],
                    'sourcePdfSourceIndex' => $identity['start'],
                    'sourcePdfSourceIndexEnd' => $identity['end'],
                ]);
                $right = array_replace($items[$candidateIndex], [
                    'sourceStream' => $candidateIdentity['stream'],
                    'sourcePdfSourceIndex' => $candidateIdentity['start'],
                    'sourcePdfSourceIndexEnd' => $candidateIdentity['end'],
                    'sourcePdfExactRangeFragmentSequence' => true,
                ]);
                if ($this->positionedPdfExactSourceAdjacentPunctuationFragments(
                    $left,
                    $right
                )) {
                    $candidateIndexes[] = $candidateIndex;
                }
            }
            if (count($candidateIndexes) !== 1 || $candidateIndexes[0] === $index + 1) {
                continue;
            }

            $candidateIndex = $candidateIndexes[0];
            $candidate = $items[$candidateIndex];
            unset($candidate['forceBlockBreakBefore']);
            $candidate['sourcePdfCrossPanelContinuation'] = true;
            $candidate['sourcePdfExactPaintedPunctuationContinuation'] = true;
            $candidateIdentity = $identities[$candidateIndex];
            array_splice($items, $candidateIndex, 1);
            array_splice($identities, $candidateIndex, 1);
            array_splice($items, $index + 1, 0, [$candidate]);
            array_splice($identities, $index + 1, 0, [$candidateIdentity]);
            $count = count($items);
        }

        return $items;
    }

    /**
     * @param array<string, mixed> $sourceItem
     * @return array<string, mixed>|null
     */
    private function sourcePdfExactGeometryFallbackLineItem(
        array $sourceItem,
        int $sourceIndex
    ): ?array {
        $geometry = is_array($sourceItem['sourceGeometry'] ?? null)
            ? $sourceItem['sourceGeometry']
            : null;
        if (!$this->sourcePdfSourceItemHasExactGeometry($sourceItem) || $geometry === null) {
            return null;
        }

        $significant = $this->pdfSourceOccurrenceComparableText(
            (string) ($sourceItem['text'] ?? '')
        );
        if ($significant === '') {
            return null;
        }
        $globalSourceIndex = is_int($sourceItem['sourcePdfGlobalSourceIndex'] ?? null)
            ? $sourceItem['sourcePdfGlobalSourceIndex']
            : $sourceIndex;
        $item = array_replace($this->sourcePdfLineItem($sourceItem), [
            'x1' => (float) $geometry['x1'],
            'y1' => (float) $geometry['y1'],
            'x2' => (float) $geometry['x2'],
            'y2' => (float) $geometry['y2'],
            'textX1' => (float) $geometry['x1'],
            'textY1' => (float) $geometry['y1'],
            'textX2' => (float) $geometry['x2'],
            'textY2' => (float) $geometry['y2'],
            'fontSize' => max(1.0, (float) $geometry['y2'] - (float) $geometry['y1']),
            'sourceOrderStart' => $globalSourceIndex,
            'sourceOrderEnd' => $globalSourceIndex,
            'sourcePdfSourceIndex' => $sourceIndex,
            'sourcePdfSourceIndexEnd' => $sourceIndex,
            'sourcePdfSourceIndexes' => [$sourceIndex],
            'sourcePdfExactSourceRanges' => [[
                'sourceIndex' => $globalSourceIndex,
                'sourceStart' => 0,
                'sourceEnd' => strlen($significant),
            ]],
            'sourceGeometry' => $geometry,
            'sourceGeometryMethod' => 'exact-page-stream-character-offset',
            'sourcePdfExactGeometryFallback' => true,
            'sourcePdfProtectedSemanticContent' => true,
            'sourceUnmatchedFallback' => true,
        ]);

        return $item;
    }

    /** @param array<string, mixed> $sourceItem */
    private function sourcePdfSourceItemHasExactGeometry(array $sourceItem): bool
    {
        $geometry = is_array($sourceItem['sourceGeometry'] ?? null)
            ? $sourceItem['sourceGeometry']
            : null;

        return ($sourceItem['sourceGeometryMethod'] ?? null) === 'exact-page-stream-character-offset'
            && $geometry !== null
            && $this->pdfSourceBoundsAreValid($geometry)
            && ($geometry['orientation'] ?? null) === 'horizontal';
    }

    /** @param array<string, mixed> $sourceItem */
    private function sourcePdfSourceItemHasExactNearHorizontalGeometry(array $sourceItem): bool
    {
        if ($this->sourcePdfSourceItemHasExactGeometry($sourceItem)) {
            return true;
        }
        $geometry = is_array($sourceItem['sourceGeometry'] ?? null)
            ? $sourceItem['sourceGeometry']
            : null;
        $orientation = is_array($geometry) && is_string($geometry['orientation'] ?? null)
            ? $geometry['orientation']
            : '';
        if (($sourceItem['sourceGeometryMethod'] ?? null)
                !== 'exact-page-stream-character-offset'
            || $geometry === null
            || !$this->pdfSourceBoundsAreValid($geometry)
            || preg_match('/^rotated-([0-9]+(?:\.[0-9]+)?)$/D', $orientation, $match) !== 1) {
            return false;
        }
        $rotation = fmod((float) $match[1], 360.0);
        $distanceFromHorizontal = min($rotation, 360.0 - $rotation);

        return $distanceFromHorizontal <= 2.0;
    }

    /**
     * An inferred neighbor layout cannot claim to be an exact positioned
     * match. It may still carry an occurrence-local wrapped continuation when
     * both immutable source records identify the exact emitted carriers and
     * their own page/stream character geometry proves the line rhythm.
     *
     * @param array<string, mixed> $previous
     * @param array<string, mixed> $following
     * @param array<string, mixed> $sourcePrevious
     * @param array<string, mixed> $sourceFollowing
     */
    private function sourcePdfItemsHaveExactGeometryWrappedContinuation(
        array $previous,
        array $following,
        array $sourcePrevious,
        array $sourceFollowing,
        int $previousSourceIndex,
        int $followingSourceIndex
    ): bool {
        foreach ([
            [$previous, $sourcePrevious, $previousSourceIndex],
            [$following, $sourceFollowing, $followingSourceIndex],
        ] as [$item, $sourceItem, $sourceIndex]) {
            $globalSourceIndex = $sourceItem['sourcePdfGlobalSourceIndex'] ?? null;
            $itemSourceIndex = $item['sourcePdfSourceIndex'] ?? $sourceIndex;
            if (!is_int($globalSourceIndex)
                || !is_int($item['sourcePdfGlobalSourceIndex'] ?? null)
                || $item['sourcePdfGlobalSourceIndex'] !== $globalSourceIndex
                || !is_int($itemSourceIndex)
                || $itemSourceIndex !== $sourceIndex
                || (int) ($item['sourcePdfSourceIndexEnd'] ?? $sourceIndex) !== $sourceIndex
                || !is_int($sourceItem['page'] ?? null)
                || ($item['page'] ?? null) !== $sourceItem['page']
                || !is_int($sourceItem['stream'] ?? null)
                || $sourceItem['stream'] < 1
                || ($item['sourceStream'] ?? null) !== $sourceItem['stream']
                || (string) ($sourceItem['text'] ?? '') === ''
                || !hash_equals((string) $sourceItem['text'], (string) ($item['text'] ?? ''))
                || !$this->sourcePdfSourceItemHasExactGeometry($sourceItem)) {
                return false;
            }
        }

        $sourceLayout = static function (array $sourceItem): array {
            $geometry = $sourceItem['sourceGeometry'];

            return [
                'page' => $sourceItem['page'],
                'x1' => (float) $geometry['x1'],
                'y1' => (float) $geometry['y1'],
                'x2' => (float) $geometry['x2'],
                'y2' => (float) $geometry['y2'],
                'fontSize' => max(1.0, (float) $geometry['y2'] - (float) $geometry['y1']),
            ];
        };

        return $this->repairedPdfLayoutContinuesWrappedLine(
            $sourceLayout($sourcePrevious),
            $sourceLayout($sourceFollowing)
        );
    }

    /**
     * A multi-fragment rotated region is removed from the ordinary source
     * stream before matching so its fragments cannot puncture body words.
     * If it is not repeated furniture, put its already reconstructed visual
     * line back once, after the primary page flow.
     *
     * @param list<array<string, mixed>> $ordered
     * @param list<array<string, mixed>> $positionedItems
     */
    private function appendSourcePdfPreservedOrientationItems(
        array &$ordered,
        array $positionedItems,
        int $pageOutputStart
    ): void {
        $existing = [];
        foreach (array_slice($ordered, $pageOutputStart) as $item) {
            $key = $this->pdfComparableLineText((string) ($item['text'] ?? ''));
            if ($key !== '') {
                $existing[$key] = true;
            }
        }
        foreach ($positionedItems as $item) {
            if (($item['pdfPrimaryOrientation'] ?? true) === true) {
                continue;
            }
            $key = $this->pdfComparableLineText((string) ($item['text'] ?? ''));
            if ($key === '' || isset($existing[$key])) {
                continue;
            }
            $item['forceBlockBreakBefore'] = true;
            $ordered[] = $item;
            $existing[$key] = true;
        }
    }

    /**
     * Apply the same semantic processor before layout ordering and after text
     * cleaning. Keeping one classifier prevents those two phases from
     * drifting into different definitions of a front-matter region.
     *
     * @param list<array<string,mixed>> $items
     * @return list<array<string,mixed>>
     */
    private function classifyPdfFrontMatterItems(array $items): array
    {
        $classifiedCount = 0;
        $sawOrdinaryItem = false;
        $classifiedItemsFormPrefix = true;
        foreach ($items as $item) {
            if (($item['sourcePdfFrontMatter'] ?? false) === true) {
                $classifiedCount++;
                if ($sawOrdinaryItem) {
                    $classifiedItemsFormPrefix = false;
                    break;
                }
                continue;
            }
            $sawOrdinaryItem = true;
        }
        if ($classifiedCount > 0 && $classifiedItemsFormPrefix) {
            $this->frontMatterRecordCount = max(
                $this->frontMatterRecordCount,
                $classifiedCount
            );

            return $items;
        }

        $processor = new PdfFrontMatterSemanticProcessor();
        $records = array_map(
            static fn (array $item): array => [
                'text' => (string) ($item['text'] ?? ''),
                'layout' => $item,
            ],
            $items
        );
        $processed = $processor->process($records);
        $this->frontMatterRecordCount = max($this->frontMatterRecordCount, $processor->recordCount());

        return array_map(static function (array $record): array {
            $layout = is_array($record['layout'] ?? null) ? $record['layout'] : [];
            $layout['text'] = (string) ($record['text'] ?? '');

            return $layout;
        }, $processed);
    }

    /**
     * A source-order fallback can place a real side table between the final
     * words at the bottom of the left body column and their continuation in
     * the right body column. Stamp only that exact occurrence pair while the
     * immutable source inventory and its character-offset geometry are both
     * available. The prose merger can then carry the short unfinished suffix
     * across the confirmed table without weakening generic tail trimming.
     *
     * @param list<array<string, mixed>> $items
     * @param list<array{page: int, stream: int, text: string}> $sourceItems
     * @param list<array<string, mixed>> $positionedItems
     * @return list<array<string, mixed>>
     */
    private function markSourcePdfExactSideTableContinuationPairs(
        array $items,
        array $sourceItems,
        array $positionedItems
    ): array {
        $this->markSourcePdfExactSideTableContinuationPairsInPlace(
            $items,
            $sourceItems,
            $positionedItems
        );

        return $items;
    }

    /**
     * @param list<array<string,mixed>> $items
     * @param list<array{page: int, stream: int, text: string}> $sourceItems
     * @param list<array<string,mixed>> $positionedItems
     */
    private function markSourcePdfExactSideTableContinuationPairsInPlace(
        array &$items,
        array $sourceItems,
        array $positionedItems
    ): void {
        if (count($items) < 4 || count($sourceItems) < 4 || $this->sourceSha256 === '') {
            return;
        }

        $itemIndexesByGlobalSourceIndex = [];
        $continuationEndpointsByGlobalSourceIndex = [];
        foreach ($items as $itemIndex => $item) {
            $globalSourceIndex = $item['sourcePdfGlobalSourceIndex'] ?? null;
            if (($item['sourcePdfExactGeometryFallback'] ?? false) === true
                && is_int($globalSourceIndex)) {
                $itemIndexesByGlobalSourceIndex[$globalSourceIndex][] = $itemIndex;
            }
            $endpoint = $this->sourcePdfExactSideTableContinuationEndpoint($item, $sourceItems);
            if ($endpoint !== null) {
                $continuationEndpointsByGlobalSourceIndex[$endpoint['start']][] = [
                    'itemIndex' => $itemIndex,
                    'endpoint' => $endpoint,
                ];
            }
        }
        if ($itemIndexesByGlobalSourceIndex === [] || $continuationEndpointsByGlobalSourceIndex === []) {
            return;
        }

        $sourceLines = array_map(
            static fn (array $sourceItem): string => (string) ($sourceItem['text'] ?? ''),
            $sourceItems
        );
        $usedSourceIndexes = [];
        for ($tableStart = 1, $sourceCount = count($sourceItems); $tableStart < $sourceCount; $tableStart++) {
            $stackedTable = $this->stackedTableRowsAt($sourceLines, $tableStart);
            if ($stackedTable['rows'] === [] || $stackedTable['consumed'] < 4) {
                continue;
            }
            $tableEnd = $tableStart + $stackedTable['consumed'] - 1;
            $previousSourceIndex = $tableStart - 1;
            if ($tableEnd >= $sourceCount
                || isset($usedSourceIndexes[$previousSourceIndex])
                || count($itemIndexesByGlobalSourceIndex[$previousSourceIndex] ?? []) !== 1) {
                continue;
            }

            $tail = $this->sourcePdfExactSideTableContinuationTail(
                (string) ($sourceItems[$previousSourceIndex]['text'] ?? '')
            );
            if ($tail === null) {
                continue;
            }

            $candidateSourceIndexes = [];
            $searchEnd = min($sourceCount - 1, $tableEnd + 8);
            for ($candidateSourceIndex = $tableEnd + 3; $candidateSourceIndex <= $searchEnd; $candidateSourceIndex++) {
                if ($this->sourcePdfSourceItemsProveExactSideTableContinuation(
                    $sourceItems,
                    $previousSourceIndex,
                    $tableStart,
                    $tableEnd,
                    $candidateSourceIndex
                )) {
                    $candidateSourceIndexes[] = $candidateSourceIndex;
                }
            }
            if (count($candidateSourceIndexes) !== 1) {
                continue;
            }

            $candidateSourceIndex = $candidateSourceIndexes[0];
            if (isset($usedSourceIndexes[$candidateSourceIndex])
                || count($continuationEndpointsByGlobalSourceIndex[$candidateSourceIndex] ?? []) !== 1) {
                continue;
            }
            $previousItemIndex = $itemIndexesByGlobalSourceIndex[$previousSourceIndex][0];
            $candidateEndpointEntry = $continuationEndpointsByGlobalSourceIndex[$candidateSourceIndex][0];
            $candidateItemIndex = $candidateEndpointEntry['itemIndex'];
            $candidateEndpoint = $candidateEndpointEntry['endpoint'];
            if (!$this->sourcePdfItemIsExactGeometryFallbackForGlobalSource(
                $items[$previousItemIndex],
                $sourceItems[$previousSourceIndex],
                $previousSourceIndex
            )) {
                continue;
            }

            if ($candidateEndpoint['start'] === $candidateEndpoint['end']) {
                $positionedWhitespaceText = $this->sourcePdfExactOccurrenceTextWithPositionedSeparators(
                    (string) $sourceItems[$candidateSourceIndex]['text'],
                    $candidateSourceIndex,
                    $positionedItems,
                    $sourceItems
                );
                if ($positionedWhitespaceText !== null) {
                    $items[$candidateItemIndex]['text'] = $positionedWhitespaceText;
                    $candidateEndpoint = $this->sourcePdfExactSideTableContinuationEndpoint(
                        $items[$candidateItemIndex],
                        $sourceItems
                    );
                    if ($candidateEndpoint === null) {
                        continue;
                    }
                }
            }

            $previousProjection = $this->pdfSourceOccurrenceComparableText(
                (string) $sourceItems[$previousSourceIndex]['text']
            );
            $tailProjection = $this->pdfSourceOccurrenceComparableText($tail['tail']);
            if ($previousProjection === '' || $tailProjection === '') {
                continue;
            }

            $proof = [
                'version' => 3,
                'method' => 'exact-source-side-table-continuation',
                'sourceSha256' => $this->sourceSha256,
                'page' => (int) $sourceItems[$previousSourceIndex]['page'],
                'stream' => (int) $sourceItems[$previousSourceIndex]['stream'],
                'previousSourceIndex' => $previousSourceIndex,
                'tableSourceStart' => $tableStart,
                'tableSourceEnd' => $tableEnd,
                'candidatePredecessorSourceIndex' => $candidateSourceIndex - 1,
                'continuationSourceIndex' => $candidateSourceIndex,
                'continuationSourceEnd' => $candidateEndpoint['end'],
                'previousProjectionDigest' => hash('sha256', $previousProjection),
                'tailProjectionDigest' => hash('sha256', $tailProjection),
                'continuationProjectionDigest' => $candidateEndpoint['projectionDigest'],
                'continuationExactRanges' => $candidateEndpoint['exactRanges'],
                'previousGeometryDigest' => $this->sourcePdfExactGeometryProofDigest(
                    $sourceItems[$previousSourceIndex]['sourceGeometry']
                ),
                'continuationGeometryDigest' => $candidateEndpoint['geometryDigest'],
            ];
            $proof['proofDigest'] = hash('sha256', json_encode(
                $proof,
                JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE
            ) ?: '');
            $items[$previousItemIndex]['sourcePdfExactSideTableContinuationAfter'] = $proof;
            $items[$candidateItemIndex]['sourcePdfExactSideTableContinuationBefore'] = $proof;
            $usedSourceIndexes[$previousSourceIndex] = true;
            $usedSourceIndexes[$candidateSourceIndex] = true;
        }

    }

    /**
     * @param array<string,mixed> $item
     * @param list<array<string,mixed>> $sourceItems
     * @return array{start:int,end:int,projectionDigest:string,geometryDigest:string,exactRanges:list<array{sourceIndex:int,sourceStart:int,sourceEnd:int,projectionDigest:string}>}|null
     */
    private function sourcePdfExactSideTableContinuationEndpoint(
        array $item,
        array $sourceItems
    ): ?array {
        $ranges = $this->pdfPositionedExactSourceRanges($item);
        if ($ranges === [] || !$this->pdfLayoutHasGeometry($item)) {
            return null;
        }
        $indexes = array_column($ranges, 'sourceIndex');
        foreach ($indexes as $offset => $sourceIndex) {
            if (!is_int($sourceIndex)
                || ($offset > 0 && $sourceIndex !== $indexes[$offset - 1] + 1)) {
                return null;
            }
        }
        $start = $indexes[0];
        $end = $indexes[array_key_last($indexes)];
        $projection = '';
        $exactRanges = [];
        $page = null;
        $stream = null;
        foreach ($ranges as $range) {
            $sourceItem = $sourceItems[$range['sourceIndex']] ?? null;
            $sourceProjection = is_array($sourceItem)
                ? $this->pdfSourceOccurrenceComparableText((string) ($sourceItem['text'] ?? ''))
                : '';
            if ($sourceProjection === ''
                || $range['sourceStart'] !== 0
                || $range['sourceEnd'] !== strlen($sourceProjection)) {
                return null;
            }
            $sourcePage = (int) ($sourceItem['page'] ?? 0);
            $sourceStream = (int) ($sourceItem['stream'] ?? 0);
            if ($sourcePage < 1
                || $sourceStream < 1
                || ($page !== null && $sourcePage !== $page)
                || ($stream !== null && $sourceStream !== $stream)) {
                return null;
            }
            $page = $sourcePage;
            $stream = $sourceStream;
            $projection .= $sourceProjection;
            $exactRanges[] = [
                'sourceIndex' => $range['sourceIndex'],
                'sourceStart' => 0,
                'sourceEnd' => strlen($sourceProjection),
                'projectionDigest' => hash('sha256', $sourceProjection),
            ];
        }
        if ($page !== (int) ($item['page'] ?? 0)
            || $stream !== (int) ($item['sourceStream'] ?? 0)
            || !hash_equals(
                $projection,
                $this->pdfSourceOccurrenceComparableText((string) ($item['text'] ?? ''))
            )) {
            return null;
        }
        if (count($ranges) === 1) {
            if (!$this->sourcePdfItemIsExactGeometryFallbackForGlobalSource(
                $item,
                $sourceItems[$start],
                $start
            )) {
                return null;
            }
        } elseif (($item['sourcePdfFallbackOrderProjection'] ?? false) !== true
            || ($item['sourcePdfExactRangeFragmentSequence'] ?? false) !== true
            || ($item['sourcePdfExactPositionedText'] ?? false) !== true
            || array_values($item['sourcePdfGlobalSourceIndexes'] ?? []) !== $indexes) {
            return null;
        }
        $geometry = [
            'page' => $page,
            'stream' => $stream,
            'x1' => (float) $item['x1'],
            'y1' => (float) $item['y1'],
            'x2' => (float) $item['x2'],
            'y2' => (float) $item['y2'],
            'orientation' => 'horizontal',
        ];

        return [
            'start' => $start,
            'end' => $end,
            'projectionDigest' => hash('sha256', $projection),
            'geometryDigest' => $this->sourcePdfExactGeometryProofDigest($geometry),
            'exactRanges' => $exactRanges,
        ];
    }

    /**
     * Project only the whitespace separators proved inside one complete
     * source occurrence by a unique exact positioned carrier. A composite
     * carrier may cover adjacent source records; range order converts its
     * compact offsets back to this occurrence without importing any of the
     * neighboring text.
     *
     * @param list<array<string,mixed>> $positionedItems
     * @param list<array<string,mixed>> $sourceItems
     */
    private function sourcePdfExactOccurrenceTextWithPositionedSeparators(
        string $sourceText,
        int $globalSourceIndex,
        array $positionedItems,
        array $sourceItems
    ): ?string {
        $sourceProjection = $this->pdfSourceOccurrenceComparableText($sourceText);
        if ($sourceProjection === '') {
            return null;
        }

        $candidates = [];
        foreach ($positionedItems as $positionedItem) {
            $ranges = $this->pdfPositionedExactSourceRanges($positionedItem);
            $separators = $this->positionedSourceVerifiedBoundarySeparators($positionedItem);
            if ($ranges === [] || $separators === []) {
                continue;
            }

            $rangeProjection = '';
            $targetCompactOffset = null;
            $targetCompactLength = null;
            foreach ($ranges as $range) {
                $rangeSourceIndex = $range['sourceIndex'];
                $rangeSourceItem = $sourceItems[$rangeSourceIndex] ?? null;
                $rangeSourceProjection = is_array($rangeSourceItem)
                    ? $this->pdfSourceOccurrenceComparableText(
                        (string) ($rangeSourceItem['text'] ?? '')
                    )
                    : '';
                if ($rangeSourceProjection === ''
                    || $range['sourceStart'] < 0
                    || $range['sourceEnd'] <= $range['sourceStart']
                    || $range['sourceEnd'] > strlen($rangeSourceProjection)) {
                    $rangeProjection = '';
                    break;
                }
                $rangeSlice = substr(
                    $rangeSourceProjection,
                    $range['sourceStart'],
                    $range['sourceEnd'] - $range['sourceStart']
                );
                if ($rangeSourceIndex === $globalSourceIndex) {
                    if ($targetCompactOffset !== null
                        || $range['sourceStart'] !== 0
                        || $range['sourceEnd'] !== strlen($sourceProjection)
                        || !hash_equals($sourceProjection, $rangeSlice)) {
                        $rangeProjection = '';
                        break;
                    }
                    $targetCompactOffset = $this->length($rangeProjection);
                    $targetCompactLength = $this->length($sourceProjection);
                }
                $rangeProjection .= $rangeSlice;
            }
            $positionedProjection = $this->pdfSourceOccurrenceComparableText(
                (string) ($positionedItem['text'] ?? '')
            );
            if ($rangeProjection === ''
                || $targetCompactOffset === null
                || $targetCompactLength === null
                || !hash_equals($rangeProjection, $positionedProjection)) {
                continue;
            }

            $localSeparators = [];
            $targetEnd = $targetCompactOffset + $targetCompactLength;
            foreach ($separators as $offset => $separator) {
                if ($offset > $targetCompactOffset && $offset < $targetEnd) {
                    $localSeparators[$offset - $targetCompactOffset] = $separator;
                }
            }
            if ($localSeparators === []) {
                continue;
            }
            $candidate = $this->sourcePdfLineTextWithProvenPositionedSeparators(
                $sourceText,
                $sourceText,
                $localSeparators
            );
            if (!hash_equals(
                $sourceProjection,
                $this->pdfSourceOccurrenceComparableText($candidate)
            )) {
                continue;
            }
            $candidates[] = $candidate;
        }

        return count($candidates) === 1 ? $candidates[0] : null;
    }

    /** @return array{prefix:string,tail:string}|null */
    private function sourcePdfExactSideTableContinuationTail(string $text): ?array
    {
        $text = trim($text);
        $prefix = $this->completePdfSentencePrefix($text);
        if ($text === '' || $prefix === '' || !str_starts_with($text, $prefix)) {
            return null;
        }
        $tail = trim(substr($text, strlen($prefix)));
        $tailWords = $this->pdfLineWordTokens($tail);
        if ($tail === ''
            || count($this->pdfLineWordTokens($prefix)) < 5
            || count($tailWords) < 1
            || count($tailWords) > 4
            || $this->length($tail) > 48
            || preg_match('/^[^\p{L}\p{N}]*\p{Lu}/u', $tail) !== 1
            || preg_match('/[.!?;:]\s*$/u', $tail) === 1
            || preg_match('/[-\x{00AD}\x{2010}-\x{2015}]\s*$/u', $tail) === 1
            || $this->lineHasPdfListBlockEvidence($tail)
            || $this->lineLooksLikeUrlOnly($tail)) {
            return null;
        }

        return ['prefix' => $prefix, 'tail' => $tail];
    }

    /**
     * @param list<array{page: int, stream: int, text: string}> $sourceItems
     */
    private function sourcePdfSourceItemsProveExactSideTableContinuation(
        array $sourceItems,
        int $previousSourceIndex,
        int $tableStart,
        int $tableEnd,
        int $candidateSourceIndex
    ): bool {
        $previous = $sourceItems[$previousSourceIndex] ?? null;
        $candidate = $sourceItems[$candidateSourceIndex] ?? null;
        $candidatePredecessor = $sourceItems[$candidateSourceIndex - 1] ?? null;
        if (!is_array($previous)
            || !is_array($candidate)
            || !is_array($candidatePredecessor)
            || !$this->sourcePdfSourceItemHasExactGeometry($previous)
            || !$this->sourcePdfSourceItemHasExactGeometry($candidate)
            || !$this->sourcePdfSourceItemHasExactGeometry($candidatePredecessor)
            || ($previous['page'] ?? null) !== ($candidate['page'] ?? null)
            || ($previous['stream'] ?? null) !== ($candidate['stream'] ?? null)
            || ($candidatePredecessor['page'] ?? null) !== ($candidate['page'] ?? null)
            || ($candidatePredecessor['stream'] ?? null) !== ($candidate['stream'] ?? null)) {
            return false;
        }

        $candidateText = ltrim((string) ($candidate['text'] ?? ''));
        if ($candidateText === ''
            || preg_match('/^[^\p{L}\p{N}]*\p{Ll}/u', $candidateText) !== 1
            || count($this->pdfLineWordTokens($candidateText)) < 3
            || $this->length($this->pdfComparableLineText($candidateText)) < 18
            || preg_match('/[.!?]\s*$/u', rtrim((string) ($candidatePredecessor['text'] ?? ''))) !== 1) {
            return false;
        }

        $previousGeometry = $previous['sourceGeometry'];
        $candidateGeometry = $candidate['sourceGeometry'];
        $predecessorGeometry = $candidatePredecessor['sourceGeometry'];
        $fontSize = max(
            1.0,
            (float) $previousGeometry['y2'] - (float) $previousGeometry['y1'],
            (float) $candidateGeometry['y2'] - (float) $candidateGeometry['y1']
        );
        if (abs(
            ((float) $previousGeometry['y2'] - (float) $previousGeometry['y1'])
            - ((float) $candidateGeometry['y2'] - (float) $candidateGeometry['y1'])
        ) > max(1.25, $fontSize * 0.20)
            || (float) $candidateGeometry['x1'] - (float) $previousGeometry['x1'] < max(120.0, $fontSize * 10.0)
            || (float) $candidateGeometry['y1'] - (float) $previousGeometry['y1'] < max(48.0, $fontSize * 4.0)) {
            return false;
        }

        $captionFontSize = max(
            1.0,
            (float) $predecessorGeometry['y2'] - (float) $predecessorGeometry['y1'],
            (float) $candidateGeometry['y2'] - (float) $candidateGeometry['y1']
        );
        $captionGap = (float) $predecessorGeometry['y1'] - (float) $candidateGeometry['y1'];
        if (abs((float) $predecessorGeometry['x1'] - (float) $candidateGeometry['x1']) > max(24.0, $captionFontSize * 3.0)
            || $captionGap < max(24.0, $captionFontSize * 2.8)
            || $captionGap > max(96.0, $captionFontSize * 12.0)) {
            return false;
        }

        $tableNearCandidateColumn = false;
        for ($sourceIndex = $tableStart; $sourceIndex <= $tableEnd; $sourceIndex++) {
            $tableItem = $sourceItems[$sourceIndex] ?? null;
            if (!is_array($tableItem)
                || !$this->sourcePdfSourceItemHasExactGeometry($tableItem)
                || ($tableItem['page'] ?? null) !== ($candidate['page'] ?? null)
                || ($tableItem['stream'] ?? null) !== ($candidate['stream'] ?? null)) {
                return false;
            }
            $tableGeometry = $tableItem['sourceGeometry'];
            if ((float) $tableGeometry['y1'] <= (float) $candidateGeometry['y1'] + max(24.0, $fontSize * 2.0)) {
                return false;
            }
            if (abs((float) $tableGeometry['x1'] - (float) $candidateGeometry['x1']) <= max(48.0, $fontSize * 5.0)) {
                $tableNearCandidateColumn = true;
            }
        }
        if (!$tableNearCandidateColumn) {
            return false;
        }

        for ($sourceIndex = $tableEnd + 1; $sourceIndex < $candidateSourceIndex; $sourceIndex++) {
            $sideItem = $sourceItems[$sourceIndex] ?? null;
            if (!is_array($sideItem)
                || !$this->sourcePdfSourceItemHasExactGeometry($sideItem)
                || ($sideItem['page'] ?? null) !== ($candidate['page'] ?? null)
                || ($sideItem['stream'] ?? null) !== ($candidate['stream'] ?? null)
                || (float) $sideItem['sourceGeometry']['x1']
                    < (float) $candidateGeometry['x1'] - max(24.0, $fontSize * 3.0)) {
                return false;
            }
        }

        return true;
    }

    /**
     * @param array<string,mixed> $item
     * @param array<string,mixed> $sourceItem
     */
    private function sourcePdfItemIsExactGeometryFallbackForGlobalSource(
        array $item,
        array $sourceItem,
        int $globalSourceIndex
    ): bool {
        $sourceProjection = $this->pdfSourceOccurrenceComparableText(
            (string) ($sourceItem['text'] ?? '')
        );
        $itemProjection = $this->pdfSourceOccurrenceComparableText(
            (string) ($item['text'] ?? '')
        );
        $ranges = $this->pdfPositionedExactSourceRanges($item);
        $sourceGeometry = is_array($sourceItem['sourceGeometry'] ?? null)
            ? $sourceItem['sourceGeometry']
            : null;

        return ($item['sourcePdfExactGeometryFallback'] ?? false) === true
            && is_int($item['sourcePdfGlobalSourceIndex'] ?? null)
            && $item['sourcePdfGlobalSourceIndex'] === $globalSourceIndex
            && $sourceProjection !== ''
            && hash_equals($sourceProjection, $itemProjection)
            && ($item['page'] ?? null) === ($sourceItem['page'] ?? null)
            && ($item['sourceStream'] ?? null) === ($sourceItem['stream'] ?? null)
            && ($item['sourceGeometryMethod'] ?? null) === 'exact-page-stream-character-offset'
            && $this->sourcePdfSourceItemHasExactGeometry($sourceItem)
            && is_array($item['sourceGeometry'] ?? null)
            && $sourceGeometry === $item['sourceGeometry']
            && count($ranges) === 1
            && $ranges[0]['sourceIndex'] === $globalSourceIndex
            && $ranges[0]['sourceStart'] === 0
            && $ranges[0]['sourceEnd'] === strlen($sourceProjection);
    }

    /** @param array<string,mixed> $geometry */
    private function sourcePdfExactGeometryProofDigest(array $geometry): string
    {
        $payload = [
            'page' => (int) ($geometry['page'] ?? 0),
            'stream' => (int) ($geometry['stream'] ?? 0),
            'x1' => (float) ($geometry['x1'] ?? 0.0),
            'y1' => (float) ($geometry['y1'] ?? 0.0),
            'x2' => (float) ($geometry['x2'] ?? 0.0),
            'y2' => (float) ($geometry['y2'] ?? 0.0),
            'orientation' => (string) ($geometry['orientation'] ?? ''),
        ];

        return hash('sha256', json_encode(
            $payload,
            JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE
        ) ?: '');
    }

    /**
     * Resolve one page-local source occurrence only from a whole exact range.
     * This is a read-only identity view for positioned page inventories which
     * deliberately do not stamp scalar source identities onto their carriers.
     *
     * @param array<string,mixed> $item
     * @param list<array<string,mixed>> $pageSourceItems
     * @param array<int,int|null> $localIndexByGlobalIndex
     */
    private function sourcePdfWholeExactRangeOccurrenceProof(
        array $item,
        array $pageSourceItems,
        array $localIndexByGlobalIndex
    ): ?array {
        $ranges = $this->pdfPositionedExactSourceRanges($item);
        if (count($ranges) !== 1
            || !$this->pdfLayoutHasGeometry($item)
            || $this->sourceSha256 === '') {
            return null;
        }
        $range = $ranges[0];
        $localIndex = $localIndexByGlobalIndex[$range['sourceIndex']] ?? null;
        $sourceItem = is_int($localIndex) ? ($pageSourceItems[$localIndex] ?? null) : null;
        if (!is_array($sourceItem)
            || !is_int($sourceItem['sourcePdfGlobalSourceIndex'] ?? null)
            || $sourceItem['sourcePdfGlobalSourceIndex'] !== $range['sourceIndex']
            || !is_int($sourceItem['page'] ?? null)
            || ($item['page'] ?? null) !== $sourceItem['page']
            || !is_int($sourceItem['stream'] ?? null)
            || $sourceItem['stream'] < 1
            || (isset($item['sourceStream'])
                && (int) $item['sourceStream'] !== $sourceItem['stream'])
            || !$this->sourcePdfSourceItemHasExactGeometry($sourceItem)) {
            return null;
        }
        $sourceProjection = $this->pdfSourceOccurrenceComparableText(
            (string) ($sourceItem['text'] ?? '')
        );
        $itemProjection = $this->pdfSourceOccurrenceComparableText(
            (string) ($item['text'] ?? '')
        );
        if ($sourceProjection === ''
            || !hash_equals($sourceProjection, $itemProjection)
            || $range['sourceStart'] !== 0
            || $range['sourceEnd'] !== strlen($sourceProjection)) {
            return null;
        }
        $sourceGeometry = is_array($sourceItem['sourceGeometry'] ?? null)
            ? $sourceItem['sourceGeometry']
            : [];
        $itemGeometry = [
            'page' => $sourceItem['page'],
            'stream' => $sourceItem['stream'],
            'x1' => (float) $item['x1'],
            'y1' => (float) $item['y1'],
            'x2' => (float) $item['x2'],
            'y2' => (float) $item['y2'],
            'orientation' => 'horizontal',
        ];
        $geometryDigest = $this->sourcePdfExactGeometryProofDigest($sourceGeometry);
        if (!hash_equals($geometryDigest, $this->sourcePdfExactGeometryProofDigest($itemGeometry))) {
            return null;
        }

        $proof = [
            'version' => 1,
            'method' => 'whole-exact-range-source-geometry-occurrence',
            'sourceSha256' => $this->sourceSha256,
            'page' => $sourceItem['page'],
            'stream' => $sourceItem['stream'],
            'globalSourceIndex' => $range['sourceIndex'],
            'localSourceIndex' => $localIndex,
            'exactRange' => $range,
            'projectionDigest' => hash('sha256', $sourceProjection),
            'geometryDigest' => $geometryDigest,
        ];
        $proof['proofDigest'] = hash('sha256', json_encode(
            $proof,
            JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE
        ) ?: '');

        return ['localSourceIndex' => $localIndex, 'proof' => $proof];
    }

    /**
     * @param array<string,mixed> $previousOccurrence
     * @param array<string,mixed> $followingOccurrence
     * @return array<string,mixed>|null
     */
    private function sourcePdfWholeExactRangeWrappedHyphenPairProof(
        array $previousOccurrence,
        array $followingOccurrence
    ): ?array {
        $previous = $previousOccurrence['proof'] ?? null;
        $following = $followingOccurrence['proof'] ?? null;
        if (!is_array($previous)
            || !is_array($following)
            || ($previous['sourceSha256'] ?? null) !== $this->sourceSha256
            || ($following['sourceSha256'] ?? null) !== $this->sourceSha256
            || ($previous['page'] ?? null) !== ($following['page'] ?? null)
            || ($previous['stream'] ?? null) !== ($following['stream'] ?? null)
            || !is_int($previous['localSourceIndex'] ?? null)
            || !is_int($following['localSourceIndex'] ?? null)
            || $following['localSourceIndex'] !== $previous['localSourceIndex'] + 1
            || !is_int($previous['globalSourceIndex'] ?? null)
            || !is_int($following['globalSourceIndex'] ?? null)
            || $following['globalSourceIndex'] !== $previous['globalSourceIndex'] + 1) {
            return null;
        }

        $proof = [
            'version' => 1,
            'method' => 'whole-exact-range-wrapped-hyphen-pair',
            'sourceSha256' => $this->sourceSha256,
            'page' => $previous['page'],
            'stream' => $previous['stream'],
            'previous' => $previous,
            'following' => $following,
        ];
        $proof['proofDigest'] = hash('sha256', json_encode(
            $proof,
            JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE
        ) ?: '');

        return $proof;
    }

    /**
     * @param array<string,mixed> $previous
     * @param array<string,mixed> $following
     * @param array<string,mixed>|null $proof
     */
    private function stampSourcePdfWholeExactRangeWrappedHyphenPairProof(
        array &$previous,
        array &$following,
        ?array $proof
    ): void {
        if ($proof === null) {
            return;
        }
        $previous['sourcePdfWholeExactRangeWrappedHyphenProofAfter'] = $proof;
        $following['sourcePdfWholeExactRangeWrappedHyphenProofBefore'] = $proof;
    }

    /**
     * Identify hard-hyphen joins at the exact adjacent source/layout pair
     * where they occur. A corpus token or character-transition count is only
     * evidence for that pair; it is never retained as a reusable text hint.
     *
     * @param list<array<string, mixed>> $items
     * @param list<array{page: int, stream: int, text: string}> $sourceItems
     * @return list<array<string, mixed>>
     */
    private function markSourcePdfLocalWrappedHyphenJoins(array $items, array $sourceItems): array
    {
        $this->markSourcePdfLocalWrappedHyphenJoinsInPlace($items, $sourceItems);

        return $items;
    }

    /**
     * @param list<array<string, mixed>> $items
     * @param list<array{page: int, stream: int, text: string}> $sourceItems
     */
    private function markSourcePdfLocalWrappedHyphenJoinsInPlace(
        array &$items,
        array $sourceItems
    ): void {
        if (count($items) < 2 || $sourceItems === []) {
            return;
        }

        $standaloneHyphenProofs = [];
        foreach ($sourceItems as $sourceIndex => $_sourceItem) {
            $proof = $this->sourcePdfStandaloneWrappedWordHyphenProofAt(
                $sourceItems,
                $sourceIndex
            );
            if ($proof !== null) {
                $standaloneHyphenProofs[(string) $proof['hyphenId']] = $proof;
            }
        }
        if ($standaloneHyphenProofs !== []) {
            $proofsByFollowingId = [];
            foreach ($standaloneHyphenProofs as $proof) {
                $proofsByFollowingId[(string) $proof['followingId']] = $proof;
            }
            foreach ($items as &$item) {
                $sourceId = is_string($item['id'] ?? null) ? $item['id'] : '';
                if (isset($standaloneHyphenProofs[$sourceId])) {
                    $proof = $standaloneHyphenProofs[$sourceId];
                    $item['sourcePdfStandaloneWrappedWordHyphenEvidence'] = $proof;
                    $item['sourcePdfStandaloneWrappedWordHyphenPairAfter'] = $proof['pair'];
                }
                if (isset($proofsByFollowingId[$sourceId])) {
                    $item['sourcePdfStandaloneWrappedWordHyphenPairBefore'] = $proofsByFollowingId[$sourceId]['pair'];
                }
            }
            unset($item);
        }

        $sourceIndexesByPage = [];
        $knownTokens = [];
        $trigramCounts = [];
        $hyphenEvidenceQueries = $this->pdfLocalHyphenEvidenceQueries($sourceItems);
        $requiredJoinedTokens = $hyphenEvidenceQueries['joinedTokens'];
        $requiredTrigrams = $hyphenEvidenceQueries['trigrams'];
        unset($hyphenEvidenceQueries);
        $sourceGlobalIndexCounts = [];
        foreach ($sourceItems as $globalSourceIndex => $sourceItem) {
            $resolvedGlobalSourceIndex = is_int($sourceItem['sourcePdfGlobalSourceIndex'] ?? null)
                ? $sourceItem['sourcePdfGlobalSourceIndex']
                : $globalSourceIndex;
            $sourceGlobalIndexCounts[$resolvedGlobalSourceIndex] =
                ($sourceGlobalIndexCounts[$resolvedGlobalSourceIndex] ?? 0) + 1;
        }
        foreach ($sourceItems as $globalSourceIndex => $sourceItem) {
            $page = (int) ($sourceItem['page'] ?? 0);
            $sourceIndexesByPage[$page][] = $globalSourceIndex;
            $sourceText = $this->normalizePdfTextEncoding((string) ($sourceItem['text'] ?? ''));
            if (preg_match_all(
                '/(?<![\p{L}\p{M}\p{N}])([\p{L}][\p{L}\p{M}\p{N}]*)(?![\p{L}\p{M}\p{N}])/u',
                $sourceText,
                $lineMatches
            ) !== false) {
                foreach ($lineMatches[1] as $token) {
                    $normalized = $this->pdfLowercaseToken($token);
                    if (isset($requiredJoinedTokens[$normalized])) {
                        $knownTokens[$normalized] = true;
                    }
                    if ($requiredTrigrams !== []) {
                        $this->addPdfLocalHyphenTrigramCounts(
                            $normalized,
                            $trigramCounts,
                            $requiredTrigrams
                        );
                    }
                }
            }
        }
        $knownHyphenatedTokens = $this->pdfKnownSourceSemanticHyphenatedTokens($sourceItems);

        $materializedSourcePage = null;
        $pageSourceItems = [];
        $localIndexByGlobalIndex = [];
        for ($index = 0, $count = count($items) - 1; $index < $count; $index++) {
            $previous = &$items[$index];
            $following = &$items[$index + 1];
            $page = (int) ($previous['page'] ?? 0);
            if ($materializedSourcePage !== $page) {
                $pageSourceItems = [];
                $localIndexByGlobalIndex = [];
                foreach ($sourceIndexesByPage[$page] ?? [] as $localIndex => $globalSourceIndex) {
                    $sourceItem = $sourceItems[$globalSourceIndex];
                    if (!is_int($sourceItem['sourcePdfGlobalSourceIndex'] ?? null)) {
                        $sourceItem['sourcePdfGlobalSourceIndex'] = $globalSourceIndex;
                    }
                    $resolvedGlobalSourceIndex = $sourceItem['sourcePdfGlobalSourceIndex'];
                    $localIndexByGlobalIndex[$resolvedGlobalSourceIndex] =
                        ($sourceGlobalIndexCounts[$resolvedGlobalSourceIndex] ?? 0) === 1
                            ? $localIndex
                            : null;
                    $pageSourceItems[] = $sourceItem;
                }
                $materializedSourcePage = $page;
            }
            $previousSourceIndex = $previous['sourcePdfSourceIndexEnd'] ?? $previous['sourcePdfSourceIndex'] ?? null;
            $followingSourceIndex = $following['sourcePdfSourceIndex'] ?? null;
            if (!is_int($previousSourceIndex) && is_int($previous['sourcePdfGlobalSourceIndex'] ?? null)) {
                $previousSourceIndex = $localIndexByGlobalIndex[$previous['sourcePdfGlobalSourceIndex']]
                    ?? null;
            }
            if (!is_int($followingSourceIndex) && is_int($following['sourcePdfGlobalSourceIndex'] ?? null)) {
                $followingSourceIndex = $localIndexByGlobalIndex[$following['sourcePdfGlobalSourceIndex']]
                    ?? null;
            }
            $previousWholeExactRangeOccurrence = is_int($previousSourceIndex)
                ? null
                : $this->sourcePdfWholeExactRangeOccurrenceProof(
                    $previous,
                    $pageSourceItems,
                    $localIndexByGlobalIndex
                );
            $followingWholeExactRangeOccurrence = is_int($followingSourceIndex)
                ? null
                : $this->sourcePdfWholeExactRangeOccurrenceProof(
                    $following,
                    $pageSourceItems,
                    $localIndexByGlobalIndex
                );
            $previousWholeExactRangeSourceIndex = is_array($previousWholeExactRangeOccurrence)
                ? ($previousWholeExactRangeOccurrence['localSourceIndex'] ?? null)
                : null;
            $followingWholeExactRangeSourceIndex = is_array($followingWholeExactRangeOccurrence)
                ? ($followingWholeExactRangeOccurrence['localSourceIndex'] ?? null)
                : null;
            $previousSourceIndex ??= $previousWholeExactRangeSourceIndex;
            $followingSourceIndex ??= $followingWholeExactRangeSourceIndex;
            if (!is_int($previousSourceIndex)
                || !is_int($followingSourceIndex)
                || $followingSourceIndex !== $previousSourceIndex + 1
                || $page !== (int) ($following['page'] ?? 0)) {
                unset($previous, $following);
                continue;
            }

            $sourcePreviousItem = $pageSourceItems[$previousSourceIndex] ?? null;
            $sourceFollowingItem = $pageSourceItems[$followingSourceIndex] ?? null;
            if (!is_array($sourcePreviousItem)
                || !is_array($sourceFollowingItem)
                || ($sourcePreviousItem['stream'] ?? null) !== ($sourceFollowingItem['stream'] ?? null)) {
                unset($previous, $following);
                continue;
            }
            $rangeOnlyPairProof = is_array($previousWholeExactRangeOccurrence)
                && is_array($followingWholeExactRangeOccurrence)
                && $previousWholeExactRangeSourceIndex === $previousSourceIndex
                && $followingWholeExactRangeSourceIndex === $followingSourceIndex
                    ? $this->sourcePdfWholeExactRangeWrappedHyphenPairProof(
                        $previousWholeExactRangeOccurrence,
                        $followingWholeExactRangeOccurrence
                    )
                    : null;
            $rangeOnlyPositionedPair = is_array($rangeOnlyPairProof);
            $positionedPair = (($this->sourcePdfItemHasExactPositionedText($previous)
                    || ($previous['sourceFootnotePrefixedGeometry'] ?? false) === true)
                && $this->sourcePdfItemHasExactPositionedText($following)
                || $rangeOnlyPositionedPair)
                && $this->repairedPdfLayoutContinuesWrappedLine($previous, $following);
            $exactSourceGeometryPair = $this->sourcePdfItemsHaveExactGeometryWrappedContinuation(
                $previous,
                $following,
                $sourcePreviousItem,
                $sourceFollowingItem,
                $previousSourceIndex,
                $followingSourceIndex
            );
            if (!$positionedPair && !$exactSourceGeometryPair) {
                unset($previous, $following);
                continue;
            }
            if ($exactSourceGeometryPair) {
                $previous['sourcePdfSourceIndex'] ??= $previousSourceIndex;
                $following['sourcePdfSourceIndex'] ??= $followingSourceIndex;
            }

            $sourcePrevious = (string) $sourcePreviousItem['text'];
            $sourceFollowing = (string) $sourceFollowingItem['text'];
            if (preg_match('/^\s*([\p{L}\p{M}]+)(?![\p{L}\p{M}\p{N}])/u', $sourceFollowing, $continuationMatch) !== 1) {
                unset($previous, $following);
                continue;
            }

            $pair = $rangeOnlyPositionedPair
                ? 'whole-exact-range-wrapped-hyphen' . "\0" . $rangeOnlyPairProof['proofDigest']
                : $page . "\0" . (string) ($sourcePreviousItem['stream'] ?? '') . "\0" . $previousSourceIndex . "\0" . $followingSourceIndex;
            // Whitespace before a terminal dash proves punctuation rather
            // than a word fragment. Preserve that separator only at this
            // source/layout occurrence (for example, a bibliography lead
            // followed by a URL on the next visual line).
            if (preg_match('/\s[-\x{2010}\x{2011}]\s*$/u', $sourcePrevious) === 1) {
                if ($positionedPair) {
                    $previous['sourcePdfTerminalDashSeparatorPairAfter'] = $pair;
                    $following['sourcePdfTerminalDashSeparatorPairBefore'] = $pair;
                }
                unset($previous, $following);
                continue;
            }
            if (preg_match('/([\p{L}\p{M}]+)(\x{00AD}|[-\x{2010}\x{2011}])\s*$/u', rtrim($sourcePrevious), $prefixMatch) !== 1) {
                unset($previous, $following);
                continue;
            }

            $prefix = $prefixMatch[1];
            $hyphen = $prefixMatch[2];
            $continuation = $continuationMatch[1];
            $hyphenated = $this->pdfLowercaseToken($prefix . '-' . $continuation);
            // A soft hyphen normally names a discretionary break. When the
            // same complete compound occurs intact elsewhere in this source,
            // however, the document itself proves that the separator is part
            // of the semantic token. Retain that decision on this exact
            // wrapped occurrence; the final source ledger must still bind it
            // to the corresponding emitted hard hyphen.
            if ($hyphen === "\u{00AD}") {
                if (isset($knownHyphenatedTokens[$hyphenated])) {
                    $previous['sourcePdfWrappedSemanticHyphenPairAfter'] = $pair;
                    $following['sourcePdfWrappedSemanticHyphenPairBefore'] = $pair;
                    $this->stampSourcePdfWholeExactRangeWrappedHyphenPairProof(
                        $previous,
                        $following,
                        $rangeOnlyPairProof
                    );
                } elseif ($positionedPair) {
                    $previous['sourcePdfWrappedHyphenPairAfter'] = $pair;
                    $following['sourcePdfWrappedHyphenPairBefore'] = $pair;
                    $this->stampSourcePdfWholeExactRangeWrappedHyphenPairProof(
                        $previous,
                        $following,
                        $rangeOnlyPairProof
                    );
                }
                unset($previous, $following);
                continue;
            }
            if (($previous['sourcePdfReferenceEntry'] ?? false) === true
                || ($following['sourcePdfReferenceEntry'] ?? false) === true) {
                // A bibliography line is a literal citation occurrence. Its
                // exact positioned carrier repeats the painted hard hyphen;
                // an unhyphenated spelling elsewhere in the document is not
                // occurrence-local evidence that this citation character may
                // be deleted. Keep the visible separator while ordinary soft
                // hyphen and non-reference proofs retain their existing path.
                unset($previous, $following);
                continue;
            }
            if (!$positionedPair && !$exactSourceGeometryPair) {
                unset($previous, $following);
                continue;
            }
            $joined = $this->pdfLowercaseToken($prefix . $continuation);
            if (isset($knownHyphenatedTokens[$hyphenated])
                || (!isset($knownTokens[$joined])
                    && !$this->pdfLocalCorpusCharacterEvidenceSupportsHyphenJoin($prefix, $continuation, $trigramCounts))) {
                unset($previous, $following);
                continue;
            }

            $previous['sourcePdfWrappedHyphenPairAfter'] = $pair;
            $following['sourcePdfWrappedHyphenPairBefore'] = $pair;
            $this->stampSourcePdfWholeExactRangeWrappedHyphenPairProof(
                $previous,
                $following,
                $rangeOnlyPairProof
            );
            unset($previous, $following);
        }

    }

    /**
     * Prove the uncommon three-occurrence spelling used by some PDFs for a
     * word split across visual baselines: alphabetic prefix, standalone hard
     * hyphen on that same baseline, then a lower-case continuation directly
     * below in the same lane. This is intentionally much stricter than list
     * recognition; exact source geometry and stable occurrence identities are
     * mandatory for all three records.
     *
     * @param list<array<string, mixed>> $sourceItems
     * @return array{kind:string,pair:string,sourceSha256:string,page:int,stream:int,precedingId:string,hyphenId:string,followingId:string}|null
     */
    private function sourcePdfStandaloneWrappedWordHyphenProofAt(
        array $sourceItems,
        int $hyphenIndex
    ): ?array {
        $preceding = $sourceItems[$hyphenIndex - 1] ?? null;
        $hyphen = $sourceItems[$hyphenIndex] ?? null;
        $following = $sourceItems[$hyphenIndex + 1] ?? null;
        if (!is_array($preceding)
            || !is_array($hyphen)
            || !is_array($following)
            || trim((string) ($hyphen['text'] ?? '')) !== '-'
            || preg_match('/^[\p{L}\p{M}]{2,}$/u', trim((string) ($preceding['text'] ?? ''))) !== 1
            || preg_match('/^\p{Ll}[\p{L}\p{M}]*$/u', trim((string) ($following['text'] ?? ''))) !== 1
            || !$this->sourcePdfSourceItemHasExactGeometry($preceding)
            || !$this->sourcePdfSourceItemHasExactGeometry($hyphen)
            || !$this->sourcePdfSourceItemHasExactGeometry($following)) {
            return null;
        }

        $page = (int) ($hyphen['page'] ?? 0);
        $stream = $hyphen['stream'] ?? null;
        if ($page < 1
            || !is_int($stream)
            || $page !== (int) ($preceding['page'] ?? 0)
            || $page !== (int) ($following['page'] ?? 0)
            || $stream !== ($preceding['stream'] ?? null)
            || $stream !== ($following['stream'] ?? null)) {
            return null;
        }

        $precedingGeometry = $preceding['sourceGeometry'];
        $hyphenGeometry = $hyphen['sourceGeometry'];
        $followingGeometry = $following['sourceGeometry'];
        $height = max(
            1.0,
            (float) $precedingGeometry['y2'] - (float) $precedingGeometry['y1'],
            (float) $hyphenGeometry['y2'] - (float) $hyphenGeometry['y1'],
            (float) $followingGeometry['y2'] - (float) $followingGeometry['y1']
        );
        $sameBaselineTolerance = max(0.75, $height * 0.22);
        $horizontalGap = (float) $hyphenGeometry['x1'] - (float) $precedingGeometry['x2'];
        $verticalStep = (float) $precedingGeometry['y1'] - (float) $followingGeometry['y1'];
        if (abs((float) $precedingGeometry['y1'] - (float) $hyphenGeometry['y1']) > $sameBaselineTolerance
            || $horizontalGap < -$height * 0.80
            || $horizontalGap > $height * 0.60
            || (float) $hyphenGeometry['x2'] <= (float) $precedingGeometry['x1']
            || (float) $hyphenGeometry['x2'] - (float) $hyphenGeometry['x1'] > $height * 1.25
            || $verticalStep < $height * 0.35
            || $verticalStep > $height * 1.80
            || abs((float) $precedingGeometry['x1'] - (float) $followingGeometry['x1']) > $height * 0.85) {
            return null;
        }

        $precedingId = is_string($preceding['id'] ?? null) ? $preceding['id'] : '';
        $hyphenId = is_string($hyphen['id'] ?? null) ? $hyphen['id'] : '';
        $followingId = is_string($following['id'] ?? null) ? $following['id'] : '';
        if ($this->sourceSha256 === ''
            || $precedingId === ''
            || $hyphenId === ''
            || $followingId === ''
            || count(array_unique([$precedingId, $hyphenId, $followingId])) !== 3) {
            return null;
        }

        $pair = hash('sha256', implode("\0", [
            $this->sourceSha256,
            (string) $page,
            (string) $stream,
            $precedingId,
            $hyphenId,
            $followingId,
        ]));

        return [
            'kind' => 'exact-standalone-wrapped-word-hyphen',
            'pair' => $pair,
            'sourceSha256' => $this->sourceSha256,
            'page' => $page,
            'stream' => $stream,
            'precedingId' => $precedingId,
            'hyphenId' => $hyphenId,
            'followingId' => $followingId,
        ];
    }

    /**
     * A dense numeric table row can paint a literal marker in its own
     * text-showing operation. Source adjacency alone then resembles a list
     * marker followed by an item, even though exact geometry places ordinary
     * content on both sides of the marker on the same baseline. Preserve that
     * occurrence as text instead of manufacturing list structure.
     *
     * @param list<array<string,mixed>> $sourceItems
     */
    private function markSourcePdfInlineStandaloneMarkerOccurrences(array &$sourceItems): void
    {
        foreach ($sourceItems as $sourceIndex => &$sourceItem) {
            $proof = $this->sourcePdfInlineStandaloneMarkerProofAt($sourceItems, $sourceIndex);
            if ($proof !== null) {
                // A single immutable digest survives the several source and
                // layout copies made by geometry reconstruction without
                // multiplying a nested proof array across the dense page.
                $sourceItem['sourcePdfInlineStandaloneMarkerEvidence'] = $proof['digest'];
            }
        }
        unset($sourceItem);
    }

    /** @param array<string,mixed> $item */
    private function sourcePdfHasExactInlineStandaloneMarkerEvidence(array $item): bool
    {
        $digest = $item['sourcePdfInlineStandaloneMarkerEvidence'] ?? null;

        return is_string($digest) && preg_match('/\A[0-9a-f]{64}\z/D', $digest) === 1;
    }

    /**
     * Require an exact numeric table cell: numeric predecessor and successor,
     * at least five contiguous numeric cells on its baseline, and numeric
     * same-column peers on both adjacent baselines. This is deliberately much
     * narrower than a generic inline triad so a real list in a neighboring
     * column cannot be flattened merely because another atom is to its left.
     *
     * @param list<array<string,mixed>> $sourceItems
     * @return array{version:int,kind:string,digest:string,sourceSha256:string,page:int,stream:int,precedingId:string,markerId:string,followingId:string}|null
     */
    private function sourcePdfInlineStandaloneMarkerProofAt(array $sourceItems, int $markerIndex): ?array
    {
        $preceding = $sourceItems[$markerIndex - 1] ?? null;
        $marker = $sourceItems[$markerIndex] ?? null;
        $following = $sourceItems[$markerIndex + 1] ?? null;
        if (!is_array($preceding)
            || !is_array($marker)
            || !is_array($following)
            || trim((string) ($marker['text'] ?? '')) !== '*'
            || !$this->positionedCellIsNumericValue(trim((string) ($preceding['text'] ?? '')))
            || !$this->positionedCellIsNumericValue(trim((string) ($following['text'] ?? '')))
            || !$this->sourcePdfSourceItemHasExactGeometry($preceding)
            || !$this->sourcePdfSourceItemHasExactGeometry($marker)
            || !$this->sourcePdfSourceItemHasExactGeometry($following)) {
            return null;
        }

        $page = (int) ($marker['page'] ?? 0);
        $stream = $marker['stream'] ?? null;
        $precedingId = is_string($preceding['id'] ?? null) ? $preceding['id'] : '';
        $markerId = is_string($marker['id'] ?? null) ? $marker['id'] : '';
        $followingId = is_string($following['id'] ?? null) ? $following['id'] : '';
        if ($this->sourceSha256 === ''
            || $page < 1
            || !is_int($stream)
            || $page !== (int) ($preceding['page'] ?? 0)
            || $page !== (int) ($following['page'] ?? 0)
            || $stream !== ($preceding['stream'] ?? null)
            || $stream !== ($following['stream'] ?? null)
            || $precedingId === ''
            || $markerId === ''
            || $followingId === ''
            || count(array_unique([$precedingId, $markerId, $followingId])) !== 3) {
            return null;
        }

        $precedingGeometry = $preceding['sourceGeometry'];
        $markerGeometry = $marker['sourceGeometry'];
        $followingGeometry = $following['sourceGeometry'];
        $height = max(
            1.0,
            (float) $precedingGeometry['y2'] - (float) $precedingGeometry['y1'],
            (float) $markerGeometry['y2'] - (float) $markerGeometry['y1'],
            (float) $followingGeometry['y2'] - (float) $followingGeometry['y1']
        );
        $baselineTolerance = max(0.75, $height * 0.22);
        $overlapTolerance = max(0.5, $height * 0.12);
        $maximumCellGap = max(24.0, $height * 4.0);
        $leftGap = (float) $markerGeometry['x1'] - (float) $precedingGeometry['x2'];
        $rightGap = (float) $followingGeometry['x1'] - (float) $markerGeometry['x2'];
        if (abs((float) $precedingGeometry['y1'] - (float) $markerGeometry['y1']) > $baselineTolerance
            || abs((float) $followingGeometry['y1'] - (float) $markerGeometry['y1']) > $baselineTolerance
            || $leftGap < -$overlapTolerance
            || $rightGap < -$overlapTolerance
            || $leftGap > $maximumCellGap
            || $rightGap > $maximumCellGap
            || (float) $precedingGeometry['x1'] >= (float) $markerGeometry['x1']
            || (float) $followingGeometry['x2'] <= (float) $markerGeometry['x2']) {
            return null;
        }

        $baselineItems = [];
        foreach ($sourceItems as $sourceIndex => $candidate) {
            if (!is_array($candidate)
                || (int) ($candidate['page'] ?? 0) !== $page
                || ($candidate['stream'] ?? null) !== $stream
                || !$this->sourcePdfSourceItemHasExactGeometry($candidate)) {
                continue;
            }
            $geometry = $candidate['sourceGeometry'];
            if (abs((float) $geometry['y1'] - (float) $markerGeometry['y1']) > $baselineTolerance) {
                continue;
            }
            $baselineItems[] = [
                'sourceIndex' => $sourceIndex,
                'text' => trim((string) ($candidate['text'] ?? '')),
                'geometry' => $geometry,
            ];
        }
        usort($baselineItems, static fn (array $left, array $right): int =>
            ((float) $left['geometry']['x1'] <=> (float) $right['geometry']['x1'])
                ?: ($left['sourceIndex'] <=> $right['sourceIndex'])
        );
        $markerPosition = null;
        foreach ($baselineItems as $position => $candidate) {
            if ($candidate['sourceIndex'] === $markerIndex) {
                $markerPosition = $position;
                break;
            }
        }
        if ($markerPosition === null) {
            return null;
        }
        $rowStart = $markerPosition;
        while ($rowStart > 0) {
            $left = $baselineItems[$rowStart - 1]['geometry'];
            $right = $baselineItems[$rowStart]['geometry'];
            if ((float) $right['x1'] - (float) $left['x2'] > $maximumCellGap) {
                break;
            }
            $rowStart--;
        }
        $rowEnd = $markerPosition;
        while ($rowEnd + 1 < count($baselineItems)) {
            $left = $baselineItems[$rowEnd]['geometry'];
            $right = $baselineItems[$rowEnd + 1]['geometry'];
            if ((float) $right['x1'] - (float) $left['x2'] > $maximumCellGap) {
                break;
            }
            $rowEnd++;
        }
        $row = array_slice($baselineItems, $rowStart, $rowEnd - $rowStart + 1);
        if (count($row) < 5) {
            return null;
        }
        $markerCells = 0;
        foreach ($row as $cell) {
            if ($cell['sourceIndex'] === $markerIndex) {
                $markerCells++;
                continue;
            }
            if (!$this->positionedCellIsNumericValue($cell['text'])) {
                return null;
            }
        }
        if ($markerCells !== 1) {
            return null;
        }

        $hasUpperPeer = false;
        $hasLowerPeer = false;
        $columnTolerance = max(2.0, $height * 0.35);
        $maximumRowStep = max(18.0, $height * 2.5);
        foreach ($sourceItems as $candidate) {
            if (!is_array($candidate)
                || (int) ($candidate['page'] ?? 0) !== $page
                || ($candidate['stream'] ?? null) !== $stream
                || !$this->sourcePdfSourceItemHasExactGeometry($candidate)
                || !$this->positionedCellIsNumericValue(trim((string) ($candidate['text'] ?? '')))) {
                continue;
            }
            $geometry = $candidate['sourceGeometry'];
            if (abs((float) $geometry['x2'] - (float) $markerGeometry['x2']) > $columnTolerance) {
                continue;
            }
            $step = (float) $geometry['y1'] - (float) $markerGeometry['y1'];
            if (abs($step) <= $baselineTolerance || abs($step) > $maximumRowStep) {
                continue;
            }
            $hasUpperPeer = $hasUpperPeer || $step > 0.0;
            $hasLowerPeer = $hasLowerPeer || $step < 0.0;
        }
        if (!$hasUpperPeer || !$hasLowerPeer) {
            return null;
        }

        $digest = hash('sha256', implode("\0", [
            'exact-dense-numeric-row-marker-cell',
            $this->sourceSha256,
            (string) $page,
            (string) $stream,
            $precedingId,
            $markerId,
            $followingId,
        ]));

        return [
            'version' => 1,
            'kind' => 'exact-dense-numeric-row-marker-cell',
            'digest' => $digest,
            'sourceSha256' => $this->sourceSha256,
            'page' => $page,
            'stream' => $stream,
            'precedingId' => $precedingId,
            'markerId' => $markerId,
            'followingId' => $followingId,
        ];
    }

    /**
     * Rebind the exact three-occurrence shape produced when a PDF paints the
     * end of a word, then a spacing accent, then the base glyph in a separate
     * text record. Geometry and immutable occurrence identity are mandatory;
     * a matching spelling elsewhere is not evidence for this boundary.
     *
     * @param list<array<string,mixed>> $sourceItems
     * @param list<AstNode> $blocks
     * @param array<int,array{start:int,end:int,projection:string,leafEnds:list<int>}> $finalOutputPageProofs
     * @return list<array{
     *     markId:string,
     *     baseId:string,
     *     baseText:string,
     *     baseCharacter:string,
     *     composedCharacter:string,
     *     evidence:array<string,mixed>
     * }>
     */
    private function pdfSourceMisorderedDiacriticBoundaryRepairs(
        array $sourceItems,
        array $blocks = [],
        array $finalOutputPageProofs = []
    ): array {
        if (count($sourceItems) < 3 || $blocks === []) {
            return [];
        }
        $spacingMarks = [
            "\u{00A8}",
            "\u{00AF}",
            "\u{00B4}",
            "\u{00B8}",
            "\u{02C7}",
            "\u{02D8}",
            "\u{02D9}",
            "\u{02DA}",
            "\u{02DC}",
        ];
        $hasCandidate = false;
        for ($index = 1, $last = count($sourceItems) - 1; $index < $last; $index++) {
            $previous = $sourceItems[$index - 1] ?? null;
            $mark = $sourceItems[$index] ?? null;
            $base = $sourceItems[$index + 1] ?? null;
            if (!is_array($previous) || !is_array($mark) || !is_array($base)) {
                continue;
            }

            $previousText = is_string($previous['text'] ?? null) ? $previous['text'] : '';
            $markText = is_string($mark['text'] ?? null) ? $mark['text'] : '';
            $baseText = is_string($base['text'] ?? null) ? $base['text'] : '';
            if (in_array($markText, $spacingMarks, true)
                && preg_match('/\p{L}\z/uD', $previousText) === 1
                && preg_match('/\A\p{L}/uD', $baseText) === 1) {
                $hasCandidate = true;
                break;
            }
        }
        if (!$hasCandidate) {
            return [];
        }

        return PdfMisorderedDiacriticBoundaryRepair::repairs(
            sourceItems: $sourceItems,
            blocks: $blocks,
            finalOutputPageProofs: $finalOutputPageProofs,
            sourceSha256: $this->sourceSha256,
            validatedFinalOutputPageProofs: fn (array $proofBlocks, array $proofs): array =>
                $this->pdfValidatedFinalOutputPageProofs($proofBlocks, $proofs),
            wholeOutputPageProof: fn (array $proofBlocks): ?array =>
                $this->pdfWholeOutputPageProof($proofBlocks),
            normalizedOutputPageProof: fn (array $proofs, int $page): ?array =>
                $this->pdfNormalizedOutputPageProof($proofs, $page),
            sourceOccurrenceComparableText: fn (string $text): string =>
                $this->pdfSourceOccurrenceComparableText($text),
            sourceBoundsAreValid: fn (array $bounds): bool =>
                $this->pdfSourceBoundsAreValid($bounds),
            sourceEvidenceBounds: fn (array $geometry): array =>
                $this->pdfSourceEvidenceBounds($geometry)
        );

    }

    /**
     * Re-bind directional wrapped-hyphen layout markers to the immutable
     * source occurrence inventory. Layout indexes are page-local, while the
     * source ledger and exact positioned ranges retain document-global
     * identities; both must identify the same unique pair before any source
     * character can be projected away.
     *
     * @param list<array<string, mixed>> $sourceItems
     * @param list<array<string, mixed>> $layouts
     * @param list<AstNode> $blocks
     * @param array<int,array{start:int,end:int,projection:string,leafEnds:list<int>}> $finalOutputPageProofs
     * @param array<string,mixed>|null $finalOutputRangeProof
     * @param array<string,array<string,mixed>> $existingDispositions
     * @return array<string, array{
     *     separator:string,
     *     replacement:string,
     *     suppressionKind:string,
     *     evidence:array<string,mixed>
     * }>
     */
    private function pdfSourceWrappedHyphenBoundaryRepairs(
        array $sourceItems,
        array $layouts,
        array $blocks = [],
        array $finalOutputPageProofs = [],
        ?array $finalOutputRangeProof = null,
        array $existingDispositions = []
    ): array
    {
        if (count($sourceItems) < 2 || count($layouts) < 2) {
            return [];
        }

        $sourceByPage = [];
        $sourceItemsByPage = [];
        $localSourceIndexByGlobalByPage = [];
        $sourceIdCounts = [];
        $knownTokens = [];
        $trigramCounts = [];
        $hyphenEvidenceQueries = $this->pdfLocalHyphenEvidenceQueries($sourceItems);
        $requiredJoinedTokens = $hyphenEvidenceQueries['joinedTokens'];
        $requiredTrigrams = $hyphenEvidenceQueries['trigrams'];
        unset($hyphenEvidenceQueries);
        foreach ($sourceItems as $globalIndex => $sourceItem) {
            $page = max(1, (int) ($sourceItem['page'] ?? 1));
            $pageLocalIndex = count($sourceByPage[$page] ?? []);
            $resolvedGlobalIndex = is_int($sourceItem['sourcePdfGlobalSourceIndex'] ?? null)
                ? $sourceItem['sourcePdfGlobalSourceIndex']
                : $globalIndex;
            // Exact-range carriers stamp the resolved immutable source index.
            // Keep the page-local source copy on the same identity even when
            // the extractor omitted the optional convenience field.
            $sourceItem['sourcePdfGlobalSourceIndex'] = $resolvedGlobalIndex;
            $id = is_string($sourceItem['id'] ?? null) ? $sourceItem['id'] : '';
            if ($id !== '') {
                $sourceIdCounts[$id] = ($sourceIdCounts[$id] ?? 0) + 1;
            }
            $sourceByPage[$page][$pageLocalIndex] = [
                'item' => $sourceItem,
                'id' => $id,
                'globalIndex' => $resolvedGlobalIndex,
                'pageLocalIndex' => $pageLocalIndex,
            ];
            $sourceItemsByPage[$page][$pageLocalIndex] = $sourceItem;
            if (isset($localSourceIndexByGlobalByPage[$page][$resolvedGlobalIndex])) {
                $localSourceIndexByGlobalByPage[$page][$resolvedGlobalIndex] = null;
            } else {
                $localSourceIndexByGlobalByPage[$page][$resolvedGlobalIndex] = $pageLocalIndex;
            }
            $sourceText = $this->normalizePdfTextEncoding((string) ($sourceItem['text'] ?? ''));
            if (preg_match_all(
                '/(?<![\p{L}\p{M}\p{N}])([\p{L}][\p{L}\p{M}\p{N}]*)(?![\p{L}\p{M}\p{N}])/u',
                $sourceText,
                $lineMatches
            ) !== false) {
                foreach ($lineMatches[1] as $token) {
                    $normalized = $this->pdfLowercaseToken($token);
                    if (isset($requiredJoinedTokens[$normalized])) {
                        $knownTokens[$normalized] = true;
                    }
                    if ($requiredTrigrams !== []) {
                        $this->addPdfLocalHyphenTrigramCounts(
                            $normalized,
                            $trigramCounts,
                            $requiredTrigrams
                        );
                    }
                }
            }
        }
        $knownHyphenatedTokens = $this->pdfKnownSourceSemanticHyphenatedTokens($sourceItems);

        $repairs = [];
        $blockedPrecedingIds = [];
        for ($layoutIndex = 0, $count = count($layouts) - 1; $layoutIndex < $count; $layoutIndex++) {
            $previousLayout = $layouts[$layoutIndex];
            $followingLayout = $layouts[$layoutIndex + 1];
            if (!is_array($previousLayout) || !is_array($followingLayout)) {
                continue;
            }

            $pairKinds = [];
            $invalidDirectionalMarker = false;
            foreach ([
                'discretionary' => [
                    'sourcePdfWrappedHyphenPairAfter',
                    'sourcePdfWrappedHyphenPairBefore',
                ],
                'semantic' => [
                    'sourcePdfWrappedSemanticHyphenPairAfter',
                    'sourcePdfWrappedSemanticHyphenPairBefore',
                ],
            ] as $pairKind => [$afterKey, $beforeKey]) {
                $after = $previousLayout[$afterKey] ?? null;
                $before = $followingLayout[$beforeKey] ?? null;
                $afterPresent = is_string($after) && $after !== '';
                $beforePresent = is_string($before) && $before !== '';
                if (!$afterPresent && !$beforePresent) {
                    continue;
                }
                if (!$afterPresent || !$beforePresent || !hash_equals($after, $before)) {
                    $invalidDirectionalMarker = true;
                    break;
                }
                $pairKinds[] = ['kind' => $pairKind, 'pair' => $after];
            }
            if ($invalidDirectionalMarker || count($pairKinds) !== 1) {
                continue;
            }

            $wholeExactRangeBinding =
                $this->pdfSourceWholeExactRangeWrappedHyphenBinding(
                    $previousLayout,
                    $followingLayout,
                    $pairKinds[0]['pair'],
                    $sourceItemsByPage,
                    $localSourceIndexByGlobalByPage
                );
            if ($wholeExactRangeBinding !== null) {
                $previousRange = $wholeExactRangeBinding['previousRange'];
                $followingRange = $wholeExactRangeBinding['followingRange'];
                $page = $wholeExactRangeBinding['page'];
                $stream = $wholeExactRangeBinding['stream'];
            } else {
                $previousRange = $this->pdfSourceLayoutPageLocalOccurrenceRange($previousLayout);
                $followingRange = $this->pdfSourceLayoutPageLocalOccurrenceRange($followingLayout);
                $page = max(1, (int) ($previousLayout['page'] ?? 1));
                $stream = $previousLayout['sourceStream'] ?? null;
                if ($previousRange === null
                    || $followingRange === null
                    || !is_int($stream)
                    || $page !== max(1, (int) ($followingLayout['page'] ?? 1))
                    || $stream !== ($followingLayout['sourceStream'] ?? null)
                    || $followingRange['start'] !== $previousRange['end'] + 1) {
                    continue;
                }
            }

            $previousSource = $sourceByPage[$page][$previousRange['end']] ?? null;
            $followingSource = $sourceByPage[$page][$followingRange['start']] ?? null;
            if (!is_array($previousSource) || !is_array($followingSource)) {
                continue;
            }
            $previousItem = is_array($previousSource['item'] ?? null) ? $previousSource['item'] : [];
            $followingItem = is_array($followingSource['item'] ?? null) ? $followingSource['item'] : [];
            $previousId = is_string($previousSource['id'] ?? null) ? $previousSource['id'] : '';
            $followingId = is_string($followingSource['id'] ?? null) ? $followingSource['id'] : '';
            if ($previousId === ''
                || $followingId === ''
                || $previousId === $followingId
                || ($sourceIdCounts[$previousId] ?? 0) !== 1
                || ($sourceIdCounts[$followingId] ?? 0) !== 1
                || (int) ($previousItem['page'] ?? 0) !== $page
                || (int) ($followingItem['page'] ?? 0) !== $page
                || (int) ($previousItem['stream'] ?? 0) !== $stream
                || (int) ($followingItem['stream'] ?? 0) !== $stream) {
                continue;
            }

            $pair = $pairKinds[0]['pair'];
            $expectedPair = $wholeExactRangeBinding !== null
                ? $wholeExactRangeBinding['pair']
                : $page . "\0" . $stream . "\0"
                    . $previousRange['end'] . "\0" . $followingRange['start'];
            if (!hash_equals($expectedPair, $pair)) {
                continue;
            }

            $previousText = is_string($previousItem['text'] ?? null) ? $previousItem['text'] : '';
            $followingText = is_string($followingItem['text'] ?? null) ? $followingItem['text'] : '';
            if (preg_match(
                '/([\p{L}\p{M}]+)(\x{00AD}|[-\x{2010}\x{2011}])$/u',
                $previousText,
                $terminal,
                PREG_OFFSET_CAPTURE
            ) !== 1 || preg_match(
                '/^\s*([\p{L}\p{M}]+)/u',
                $followingText,
                $wordStart,
                PREG_OFFSET_CAPTURE
            ) !== 1) {
                continue;
            }
            $prefix = (string) $terminal[1][0];
            $separator = (string) $terminal[2][0];
            $separatorStart = (int) $terminal[2][1];
            $continuation = (string) $wordStart[1][0];
            $continuationStart = (int) $wordStart[1][1];
            if ($separatorStart + strlen($separator) !== strlen($previousText)) {
                continue;
            }

            $hyphenated = $this->pdfLowercaseToken($prefix . '-' . $continuation);
            $joined = $this->pdfLowercaseToken($prefix . $continuation);
            $semanticCompound = isset($knownHyphenatedTokens[$hyphenated]);
            $pairKind = $pairKinds[0]['kind'];
            $softHyphen = $separator === "\u{00AD}";
            if ($pairKind === 'semantic') {
                // A hard hyphen is already visible source punctuation. It is
                // never a semantic "repair" and, crucially, can never be
                // suppressed under a soft-hyphen marker.
                if (!$softHyphen || !$semanticCompound) {
                    continue;
                }
                $replacement = '-';
                $suppressionKind = 'semantic-soft-hyphen';
            } elseif ($softHyphen) {
                if ($semanticCompound) {
                    continue;
                }
                $replacement = '';
                $suppressionKind = 'discretionary-soft-hyphen';
            } else {
                if ($semanticCompound
                    || (!isset($knownTokens[$joined])
                        && !$this->pdfLocalCorpusCharacterEvidenceSupportsHyphenJoin(
                            $prefix,
                            $continuation,
                            $trigramCounts
                        ))) {
                    continue;
                }
                $replacement = '';
                $suppressionKind = 'discretionary-hard-hyphen';
            }

            $projectedText = substr($previousText, 0, $separatorStart) . $replacement;
            $precedingGlobalIndex = (int) $previousSource['globalIndex'];
            $followingGlobalIndex = (int) $followingSource['globalIndex'];
            $precedingExactRanges = array_values(array_filter(
                $this->pdfPositionedExactSourceRanges($previousLayout),
                static fn (array $range): bool => (int) ($range['sourceIndex'] ?? -1) === $precedingGlobalIndex
            ));
            $followingExactRanges = array_values(array_filter(
                $this->pdfPositionedExactSourceRanges($followingLayout),
                static fn (array $range): bool => (int) ($range['sourceIndex'] ?? -1) === $followingGlobalIndex
            ));
            $evidence = [
                'method' => 'exact-directional-source-wrapped-hyphen-boundary',
                'page' => $page,
                'stream' => $stream,
                'sourceOccurrenceIds' => [
                    'preceding' => $previousId,
                    'following' => $followingId,
                ],
                'sourcePageLocalIndexes' => [
                    'preceding' => $previousRange['end'],
                    'following' => $followingRange['start'],
                ],
                'sourceGlobalIndexes' => [
                    'preceding' => $precedingGlobalIndex,
                    'following' => $followingGlobalIndex,
                ],
                'sourceByteRanges' => [
                    'precedingTerminalSeparator' => [
                        'sourceIndex' => $precedingGlobalIndex,
                        'sourceStart' => $separatorStart,
                        'sourceEnd' => $separatorStart + strlen($separator),
                    ],
                    'followingWordStart' => [
                        'sourceIndex' => $followingGlobalIndex,
                        'sourceStart' => $continuationStart,
                        'sourceEnd' => $continuationStart + strlen($continuation),
                    ],
                ],
                'originalDigest' => hash('sha256', $previousText),
                'projectedDigest' => hash('sha256', $projectedText),
                'followingOriginalDigest' => hash('sha256', $followingText),
                'pairDigest' => hash('sha256', $pair),
                'suppressionKind' => $suppressionKind,
            ];
            if ($precedingExactRanges !== [] || $followingExactRanges !== []) {
                $evidence['layoutExactSourceRanges'] = [
                    'preceding' => $precedingExactRanges,
                    'following' => $followingExactRanges,
                ];
            }
            $precedingProvenanceIndex = $previousItem['provenance']['index'] ?? null;
            $followingProvenanceIndex = $followingItem['provenance']['index'] ?? null;
            if (is_int($precedingProvenanceIndex) || is_int($followingProvenanceIndex)) {
                $evidence['sourceProvenanceIndexes'] = [
                    'preceding' => is_int($precedingProvenanceIndex) ? $precedingProvenanceIndex : null,
                    'following' => is_int($followingProvenanceIndex) ? $followingProvenanceIndex : null,
                ];
            }

            if (isset($blockedPrecedingIds[$previousId])) {
                continue;
            }
            if (isset($repairs[$previousId])) {
                // One immutable occurrence cannot have two outgoing boundary
                // decisions. Reject both instead of accepting layout order as
                // an accidental tie-breaker.
                unset($repairs[$previousId]);
                $blockedPrecedingIds[$previousId] = true;
                continue;
            }
            $repairs[$previousId] = [
                'separator' => $separator,
                'replacement' => $replacement,
                'suppressionKind' => $suppressionKind,
                'evidence' => $evidence,
            ];
        }

        // A directional layout marker proves which source boundary could be
        // discretionary; it does not by itself prove that the selected final
        // page representation actually consumed the glyph. Require the exact
        // page output to have a matching hard-hyphen deficit. An incomplete
        // subset is ambiguous and remains literal.
        if ($repairs !== [] && $blocks !== []) {
            $pages = [];
            $sourceProjectionByPage = [];
            $sourceRangeProjection = '';
            foreach ($sourceItems as $sourceItem) {
                $sourceId = is_string($sourceItem['id'] ?? null)
                    ? $sourceItem['id']
                    : '';
                $existingDisposition = $sourceId !== ''
                    && is_array($existingDispositions[$sourceId] ?? null)
                        ? (string) ($existingDispositions[$sourceId]['disposition'] ?? '')
                        : '';
                if ($existingDisposition !== ''
                    && !in_array(
                        $existingDisposition,
                        ['emitted', 'boundary-repair', 'semantic-structure'],
                        true
                    )) {
                    continue;
                }
                $page = max(1, (int) ($sourceItem['page'] ?? 1));
                $pages[$page] = true;
                $projection = $this->pdfSourceOccurrenceComparableText(
                    (string) ($sourceItem['text'] ?? '')
                );
                $sourceProjectionByPage[$page] = ($sourceProjectionByPage[$page] ?? '')
                    . $projection;
                $sourceRangeProjection .= $projection;
            }
            $outputProofs = $this->pdfValidatedFinalOutputPageProofs(
                $blocks,
                $finalOutputPageProofs
            );
            if ($outputProofs === [] && count($pages) === 1) {
                $page = (int) array_key_first($pages);
                $wholeProof = $this->pdfWholeOutputPageProof($blocks);
                if ($wholeProof !== null) {
                    $outputProofs[$page] = $wholeProof;
                }
            }
            $repairIdsByPageSeparator = [];
            foreach ($repairs as $id => $repair) {
                if (($repair['suppressionKind'] ?? null) !== 'discretionary-hard-hyphen'
                    || !is_string($repair['separator'] ?? null)
                    || $repair['separator'] === '') {
                    continue;
                }
                $page = (int) ($repair['evidence']['page'] ?? 0);
                if ($page > 0) {
                    $repairIdsByPageSeparator[$page][$repair['separator']][] = $id;
                }
            }
            $locallyProvedRepairs = $repairs;
            $rangeProofUsed = false;
            if ($outputProofs === [] && count($pages) > 1) {
                $rangeProof = $this->pdfValidatedFinalOutputRangeProof(
                    $blocks,
                    $finalOutputRangeProof
                );
                if ($rangeProof !== null) {
                    $rangeProofUsed = true;
                    $repairIdsBySeparator = [];
                    foreach ($repairIdsByPageSeparator as $page => $idsBySeparator) {
                        foreach ($idsBySeparator as $separator => $ids) {
                            foreach ($ids as $id) {
                                $repairIdsBySeparator[$separator][] = [
                                    'id' => $id,
                                    'page' => (int) $page,
                                ];
                            }
                        }
                    }
                    foreach ($repairIdsBySeparator as $separator => $repairRefs) {
                        $ids = array_column($repairRefs, 'id');
                        $sourceCount = substr_count($sourceRangeProjection, $separator);
                        $outputCount = substr_count($rangeProof['projection'], $separator);
                        $accounting = $this->pdfWrappedHyphenSeparatorAccounting(
                            $locallyProvedRepairs,
                            $separator
                        );
                        $hardCandidatesAreExact = array_all(
                            $ids,
                            static fn (string $id): bool =>
                                ($accounting['repairDeltas'][$id] ?? null) === 1
                        );
                        if (!$hardCandidatesAreExact
                            || $sourceCount - $outputCount
                                !== $accounting['expectedDelta']) {
                            foreach ($ids as $id) {
                                unset($repairs[$id]);
                            }
                            continue;
                        }
                        $candidatePages = array_values(array_unique(array_map(
                            static fn (array $repairRef): int => $repairRef['page'],
                            $repairRefs
                        )));
                        sort($candidatePages, SORT_NUMERIC);
                        $identity = [
                            'version' => 1,
                            'method' => 'exact-final-range-hard-hyphen-cardinality',
                            'sourceSha256' => $this->sourceSha256,
                            'separatorDigest' => hash('sha256', $separator),
                            'sourceCount' => $sourceCount,
                            'outputCount' => $outputCount,
                            'observedSeparatorDelta' => $sourceCount - $outputCount,
                            'expectedSeparatorDelta' => $accounting['expectedDelta'],
                            'repairSourceOccurrenceIds' => array_values($ids),
                            'accountedRepairSourceOccurrenceIds' => array_keys(
                                $accounting['repairDeltas']
                            ),
                            'repairSeparatorDeltas' => $accounting['repairDeltas'],
                            'candidatePages' => $candidatePages,
                            'localPairDigests' => $accounting['localPairDigests'],
                            'outputRangeProofDigest' => $rangeProof['proofDigest'],
                            'outputProjectionDigest' => hash(
                                'sha256',
                                $rangeProof['projection']
                            ),
                        ];
                        $encoded = json_encode(
                            $identity,
                            JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE
                        );
                        $identity['proofDigest'] = hash(
                            'sha256',
                            is_string($encoded) ? $encoded : serialize($identity)
                        );
                        foreach ($ids as $id) {
                            $repairs[$id]['evidence']['finalRangeHyphenCardinality'] = $identity;
                        }
                    }
                }
            }
            foreach ($rangeProofUsed ? [] : $repairIdsByPageSeparator as $page => $idsBySeparator) {
                $outputProof = $this->pdfNormalizedOutputPageProof($outputProofs, (int) $page);
                if ($outputProof === null) {
                    foreach ($idsBySeparator as $ids) {
                        foreach ($ids as $id) {
                            unset($repairs[$id]);
                        }
                    }
                    continue;
                }
                foreach ($idsBySeparator as $separator => $ids) {
                    $sourceCount = substr_count(
                        $sourceProjectionByPage[(int) $page] ?? '',
                        $separator
                    );
                    $outputCount = substr_count($outputProof['projection'], $separator);
                    $deficit = $sourceCount - $outputCount;
                    $accounting = $this->pdfWrappedHyphenSeparatorAccounting(
                        $locallyProvedRepairs,
                        $separator,
                        (int) $page
                    );
                    $hardCandidatesAreExact = array_all(
                        $ids,
                        static fn (string $id): bool =>
                            ($accounting['repairDeltas'][$id] ?? null) === 1
                    );
                    if (!$hardCandidatesAreExact
                        || $deficit !== $accounting['expectedDelta']) {
                        foreach ($ids as $id) {
                            unset($repairs[$id]);
                        }
                        continue;
                    }
                    $identity = [
                        'version' => 1,
                        'method' => 'exact-final-page-hard-hyphen-cardinality',
                        'sourceSha256' => $this->sourceSha256,
                        'page' => (int) $page,
                        'separatorDigest' => hash('sha256', $separator),
                        'sourceCount' => $sourceCount,
                        'outputCount' => $outputCount,
                        'observedSeparatorDelta' => $deficit,
                        'expectedSeparatorDelta' => $accounting['expectedDelta'],
                        'repairSourceOccurrenceIds' => array_values($ids),
                        'accountedRepairSourceOccurrenceIds' => array_keys(
                            $accounting['repairDeltas']
                        ),
                        'repairSeparatorDeltas' => $accounting['repairDeltas'],
                        'localPairDigests' => $accounting['localPairDigests'],
                        'outputProjectionDigest' => hash(
                            'sha256',
                            $outputProof['projection']
                        ),
                    ];
                    $encoded = json_encode(
                        $identity,
                        JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE
                    );
                    $identity['proofDigest'] = hash(
                        'sha256',
                        is_string($encoded) ? $encoded : serialize($identity)
                    );
                    foreach ($ids as $id) {
                        $repairs[$id]['evidence']['finalPageHyphenCardinality'] = $identity;
                    }
                }
            }
        }

        return $repairs;
    }

    /**
     * Count how every locally proved wrapped-boundary transformation changes
     * one visible separator inventory. A semantic soft-hyphen repair can add
     * an ASCII hyphen while a discretionary hard repair removes one; both
     * deltas must be present in the same page/range cardinality receipt.
     *
     * @param array<string,array<string,mixed>> $repairs
     * @return array{
     *     expectedDelta:int,
     *     repairDeltas:array<string,int>,
     *     localPairDigests:array<string,string>
     * }
     */
    private function pdfWrappedHyphenSeparatorAccounting(
        array $repairs,
        string $separator,
        ?int $page = null
    ): array {
        $expectedDelta = 0;
        $repairDeltas = [];
        $localPairDigests = [];
        foreach ($repairs as $id => $repair) {
            $evidence = is_array($repair['evidence'] ?? null)
                ? $repair['evidence']
                : [];
            if ($page !== null && (int) ($evidence['page'] ?? 0) !== $page) {
                continue;
            }
            $sourceSeparator = is_string($repair['separator'] ?? null)
                ? $this->pdfSourceOccurrenceComparableText($repair['separator'])
                : '';
            $outputSeparator = is_string($repair['replacement'] ?? null)
                ? $this->pdfSourceOccurrenceComparableText($repair['replacement'])
                : '';
            $delta = substr_count($sourceSeparator, $separator)
                - substr_count($outputSeparator, $separator);
            if ($delta === 0) {
                continue;
            }
            $expectedDelta += $delta;
            $repairDeltas[$id] = $delta;
            $localIdentity = [
                'sourceSha256' => $this->sourceSha256,
                'sourceOccurrenceIds' => $evidence['sourceOccurrenceIds'] ?? null,
                'sourceGlobalIndexes' => $evidence['sourceGlobalIndexes'] ?? null,
                'sourceByteRanges' => $evidence['sourceByteRanges'] ?? null,
                'originalDigest' => $evidence['originalDigest'] ?? null,
                'projectedDigest' => $evidence['projectedDigest'] ?? null,
                'followingOriginalDigest' => $evidence['followingOriginalDigest'] ?? null,
                'pairDigest' => $evidence['pairDigest'] ?? null,
                'suppressionKind' => $evidence['suppressionKind'] ?? null,
                'separatorDigest' => hash('sha256', $sourceSeparator),
                'replacementDigest' => hash('sha256', $outputSeparator),
                'separatorDelta' => $delta,
            ];
            $encoded = json_encode(
                $localIdentity,
                JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE
            );
            $localPairDigests[$id] = hash(
                'sha256',
                is_string($encoded) ? $encoded : serialize($localIdentity)
            );
        }

        return [
            'expectedDelta' => $expectedDelta,
            'repairDeltas' => $repairDeltas,
            'localPairDigests' => $localPairDigests,
        ];
    }

    /**
     * Candidate-page reconstruction may retain only a whole exact source
     * range instead of the older scalar page-local source index. Rebuild the
     * stamped pair proof against the current immutable source and layout
     * inventories before allowing that carrier to authorize a hyphen repair.
     *
     * @param array<string,mixed> $previousLayout
     * @param array<string,mixed> $followingLayout
     * @param array<int,list<array<string,mixed>>> $sourceItemsByPage
     * @param array<int,array<int,int|null>> $localSourceIndexByGlobalByPage
     * @return array{
     *     page:int,
     *     stream:int,
     *     previousRange:array{start:int,end:int},
     *     followingRange:array{start:int,end:int},
     *     pair:string
     * }|null
     */
    private function pdfSourceWholeExactRangeWrappedHyphenBinding(
        array $previousLayout,
        array $followingLayout,
        string $pair,
        array $sourceItemsByPage,
        array $localSourceIndexByGlobalByPage
    ): ?array {
        $previousProof = $previousLayout['sourcePdfWholeExactRangeWrappedHyphenProofAfter']
            ?? null;
        $followingProof = $followingLayout['sourcePdfWholeExactRangeWrappedHyphenProofBefore']
            ?? null;
        if (!is_array($previousProof)
            || !is_array($followingProof)
            || $previousProof !== $followingProof
            || ($previousProof['version'] ?? null) !== 1
            || ($previousProof['method'] ?? null)
                !== 'whole-exact-range-wrapped-hyphen-pair'
            || !is_int($previousProof['page'] ?? null)
            || $previousProof['page'] < 1
            || !is_int($previousProof['stream'] ?? null)
            || $previousProof['stream'] < 1) {
            return null;
        }

        $page = $previousProof['page'];
        $pageSourceItems = $sourceItemsByPage[$page] ?? [];
        $localByGlobal = $localSourceIndexByGlobalByPage[$page] ?? [];
        if ($pageSourceItems === [] || $localByGlobal === []) {
            return null;
        }
        $rebindOccurrence = function (
            array $layout,
            mixed $stamped
        ) use ($page, $pageSourceItems, $localByGlobal): ?array {
            if (!is_array($stamped)
                || ($stamped['version'] ?? null) !== 1
                || ($stamped['method'] ?? null)
                    !== 'whole-exact-range-source-geometry-occurrence'
                || ($stamped['sourceSha256'] ?? null) !== $this->sourceSha256
                || ($stamped['page'] ?? null) !== $page
                || !is_int($stamped['stream'] ?? null)
                || $stamped['stream'] < 1
                || !is_int($stamped['globalSourceIndex'] ?? null)
                || $stamped['globalSourceIndex'] < 0
                || !is_int($stamped['localSourceIndex'] ?? null)
                || $stamped['localSourceIndex'] < 0) {
                return null;
            }
            $globalIndex = $stamped['globalSourceIndex'];
            $localIndex = $stamped['localSourceIndex'];
            if (!array_key_exists($globalIndex, $localByGlobal)
                || $localByGlobal[$globalIndex] !== $localIndex) {
                return null;
            }
            $sourceItem = $pageSourceItems[$localIndex] ?? null;
            if (!is_array($sourceItem)
                || ($sourceItem['sourcePdfGlobalSourceIndex'] ?? null) !== $globalIndex
                || ($sourceItem['page'] ?? null) !== $page
                || ($sourceItem['stream'] ?? null) !== $stamped['stream']
                || !$this->sourcePdfSourceItemHasExactGeometry($sourceItem)
                || ($layout['page'] ?? null) !== $page
                || (isset($layout['sourceStream'])
                    && $layout['sourceStream'] !== $stamped['stream'])
                || !$this->pdfLayoutHasGeometry($layout)) {
                return null;
            }
            $sourceProjection = $this->pdfSourceOccurrenceComparableText(
                (string) ($sourceItem['text'] ?? '')
            );
            $layoutProjection = $this->pdfSourceOccurrenceComparableText(
                (string) ($layout['text'] ?? '')
            );
            $expectedRange = [
                'sourceIndex' => $globalIndex,
                'sourceStart' => 0,
                'sourceEnd' => strlen($sourceProjection),
            ];
            $layoutRanges = $this->pdfPositionedExactSourceRanges($layout);
            if ($sourceProjection === ''
                || !hash_equals($sourceProjection, $layoutProjection)
                || ($stamped['exactRange'] ?? null) !== $expectedRange
                || count($layoutRanges) !== 1
                || !in_array(
                    $layoutRanges[0]['sourceIndex'],
                    [$globalIndex, $localIndex],
                    true
                )
                || $layoutRanges[0]['sourceStart'] !== 0
                || $layoutRanges[0]['sourceEnd'] !== strlen($sourceProjection)) {
                return null;
            }
            $sourceGeometry = is_array($sourceItem['sourceGeometry'] ?? null)
                ? $sourceItem['sourceGeometry']
                : [];
            $layoutGeometry = [
                'page' => $page,
                'stream' => $stamped['stream'],
                'x1' => (float) $layout['x1'],
                'y1' => (float) $layout['y1'],
                'x2' => (float) $layout['x2'],
                'y2' => (float) $layout['y2'],
                'orientation' => 'horizontal',
            ];
            $geometryDigest = $this->sourcePdfExactGeometryProofDigest($sourceGeometry);
            if (!hash_equals(
                $geometryDigest,
                $this->sourcePdfExactGeometryProofDigest($layoutGeometry)
            )) {
                return null;
            }

            $expected = [
                'version' => 1,
                'method' => 'whole-exact-range-source-geometry-occurrence',
                'sourceSha256' => $this->sourceSha256,
                'page' => $page,
                'stream' => $stamped['stream'],
                'globalSourceIndex' => $globalIndex,
                'localSourceIndex' => $localIndex,
                'exactRange' => $expectedRange,
                'projectionDigest' => hash('sha256', $sourceProjection),
                'geometryDigest' => $geometryDigest,
            ];
            $expected['proofDigest'] = hash('sha256', json_encode(
                $expected,
                JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE
            ) ?: '');
            if ($expected !== $stamped) {
                return null;
            }

            return ['localSourceIndex' => $localIndex, 'proof' => $expected];
        };
        $previousOccurrence = $rebindOccurrence(
            $previousLayout,
            $previousProof['previous'] ?? null
        );
        $followingOccurrence = $rebindOccurrence(
            $followingLayout,
            $previousProof['following'] ?? null
        );
        if ($previousOccurrence === null || $followingOccurrence === null) {
            return null;
        }
        $expectedProof = $this->sourcePdfWholeExactRangeWrappedHyphenPairProof(
            $previousOccurrence,
            $followingOccurrence
        );
        if ($expectedProof === null || $expectedProof !== $previousProof) {
            return null;
        }
        $expectedPair = 'whole-exact-range-wrapped-hyphen' . "\0"
            . $expectedProof['proofDigest'];
        if (!hash_equals($expectedPair, $pair)) {
            return null;
        }

        $previousLocalIndex = $expectedProof['previous']['localSourceIndex'] ?? null;
        $followingLocalIndex = $expectedProof['following']['localSourceIndex'] ?? null;
        if (!is_int($previousLocalIndex)
            || !is_int($followingLocalIndex)
            || $followingLocalIndex !== $previousLocalIndex + 1) {
            return null;
        }

        return [
            'page' => $page,
            'stream' => $previousProof['stream'],
            'previousRange' => [
                'start' => $previousLocalIndex,
                'end' => $previousLocalIndex,
            ],
            'followingRange' => [
                'start' => $followingLocalIndex,
                'end' => $followingLocalIndex,
            ],
            'pair' => $expectedPair,
        ];
    }

    /**
     * @param array<string,mixed> $layout
     * @return array{start:int,end:int}|null
     */
    private function pdfSourceLayoutPageLocalOccurrenceRange(array $layout): ?array
    {
        $indexes = [];
        if (is_array($layout['sourcePdfSourceIndexes'] ?? null)) {
            foreach ($layout['sourcePdfSourceIndexes'] as $index) {
                if (!is_int($index) || $index < 0) {
                    return null;
                }
                $indexes[] = $index;
            }
            if ($indexes === []) {
                return null;
            }
            foreach ($indexes as $offset => $index) {
                if ($offset > 0 && $index !== $indexes[$offset - 1] + 1) {
                    return null;
                }
            }
            if (isset($layout['sourcePdfSourceIndex'])
                && (!is_int($layout['sourcePdfSourceIndex']) || $layout['sourcePdfSourceIndex'] !== $indexes[0])) {
                return null;
            }
            if (isset($layout['sourcePdfSourceIndexEnd'])
                && (!is_int($layout['sourcePdfSourceIndexEnd'])
                    || $layout['sourcePdfSourceIndexEnd'] !== $indexes[array_key_last($indexes)])) {
                return null;
            }

            return ['start' => $indexes[0], 'end' => $indexes[array_key_last($indexes)]];
        }

        $start = $layout['sourcePdfSourceIndex'] ?? null;
        $end = $layout['sourcePdfSourceIndexEnd'] ?? $start;
        if (!is_int($start) || !is_int($end) || $start < 0 || $end < $start) {
            return null;
        }

        return ['start' => $start, 'end' => $end];
    }

    /**
     * Collect semantic compounds exactly as painted within one source line.
     * All PDF hyphen glyph variants share one comparison form, but the
     * returned evidence remains document-local and never becomes a vocabulary
     * or cross-document spelling rule.
     *
     * @param list<array<string, mixed>> $sourceItems
     * @return array<string, true>
     */
    private function pdfKnownSourceSemanticHyphenatedTokens(array $sourceItems): array
    {
        $known = [];
        foreach ($sourceItems as $sourceItem) {
            $text = $this->normalizePdfTextEncoding((string) ($sourceItem['text'] ?? ''));
            if (preg_match_all(
                '/(?<![\p{L}\p{M}\p{N}])([\p{L}\p{M}\p{N}]+(?:[-\x{00AD}\x{2010}\x{2011}][\p{L}\p{M}\p{N}]+)+)(?![\p{L}\p{M}\p{N}])/u',
                $text,
                $matches
            ) === false) {
                continue;
            }
            foreach ($matches[1] as $token) {
                $token = str_replace(["\u{00AD}", "\u{2010}", "\u{2011}"], '-', $token);
                $known[$this->pdfLowercaseToken($token)] = true;
            }
        }

        return $known;
    }

    private function pdfLowercaseToken(string $token): string
    {
        return function_exists('mb_strtolower') ? mb_strtolower($token, 'UTF-8') : strtolower($token);
    }

    /**
     * @param array<string,int> $counts
     * @param array<string,true>|null $requiredTrigrams
     */
    private function addPdfLocalHyphenTrigramCounts(
        string $token,
        array &$counts,
        ?array $requiredTrigrams = null
    ): void
    {
        if (preg_match_all('/(?=(\p{L}{3}))/u', $token, $matches) === false) {
            return;
        }
        foreach ($matches[1] as $trigram) {
            if ($requiredTrigrams !== null && !isset($requiredTrigrams[$trigram])) {
                continue;
            }
            $counts[$trigram] = ($counts[$trigram] ?? 0) + 1;
        }
    }

    /**
     * The corpus evidence check reads only the two trigrams which straddle an
     * observed hard-hyphen boundary. Count that bounded query set instead of a
     * document-wide trigram vocabulary.
     *
     * @param list<array<string,mixed>> $sourceItems
     * @return array{joinedTokens:array<string,true>,trigrams:array<string,true>}
     */
    private function pdfLocalHyphenEvidenceQueries(array $sourceItems): array
    {
        $joinedTokens = [];
        $trigrams = [];
        for ($index = 0, $count = count($sourceItems) - 1; $index < $count; $index++) {
            $previous = $sourceItems[$index];
            $following = $sourceItems[$index + 1];
            if (($previous['page'] ?? null) !== ($following['page'] ?? null)
                || ($previous['stream'] ?? null) !== ($following['stream'] ?? null)
                || preg_match(
                    '/([\p{L}\p{M}]+)[-\x{2010}\x{2011}]\s*$/u',
                    rtrim((string) ($previous['text'] ?? '')),
                    $prefixMatch
                ) !== 1
                || preg_match(
                    '/^\s*([\p{L}\p{M}]+)(?![\p{L}\p{M}\p{N}])/u',
                    (string) ($following['text'] ?? ''),
                    $continuationMatch
                ) !== 1) {
                continue;
            }
            $joinedTokens[$this->pdfLowercaseToken(
                $prefixMatch[1] . $continuationMatch[1]
            )] = true;
            foreach ($this->pdfLocalHyphenBoundaryTrigrams(
                $prefixMatch[1],
                $continuationMatch[1]
            ) as $trigram) {
                $trigrams[$trigram] = true;
            }
        }

        return [
            'joinedTokens' => $joinedTokens,
            'trigrams' => $trigrams,
        ];
    }

    /** @return list<string> */
    private function pdfLocalHyphenBoundaryTrigrams(string $prefix, string $continuation): array
    {
        $prefix = $this->pdfLowercaseToken($prefix);
        $continuation = $this->pdfLowercaseToken($continuation);
        if (preg_match('/(\p{L}{2})$/u', $prefix, $leftMatch) !== 1
            || preg_match('/^(\p{L}{2})/u', $continuation, $rightMatch) !== 1
            || preg_match('/(\p{L})$/u', $leftMatch[1], $leftTail) !== 1
            || preg_match('/^(\p{L})/u', $rightMatch[1], $rightHead) !== 1) {
            return [];
        }

        return [
            $leftMatch[1] . $rightHead[1],
            $leftTail[1] . $rightMatch[1],
        ];
    }

    /**
     * @param array<string, int> $trigramCounts
     */
    private function pdfLocalCorpusCharacterEvidenceSupportsHyphenJoin(
        string $prefix,
        string $continuation,
        array $trigramCounts
    ): bool {
        $trigrams = $this->pdfLocalHyphenBoundaryTrigrams($prefix, $continuation);
        if (count($trigrams) !== 2) {
            return false;
        }

        return ($trigramCounts[$trigrams[0]] ?? 0) >= 3
            && ($trigramCounts[$trigrams[1]] ?? 0) >= 3;
    }

    /**
     * A bibliography's source sequence is the most reliable way to keep an
     * entry together across columns. Retain that sequence, but borrow matched
     * positions for later confidence checks: a source-only fragment that is
     * visibly stranded far inside a reference line is not safe prose.
     *
     * @param list<array{page: int, stream: int, text: string}> $sourceItems
     * @param list<array<string, mixed>> $positionedItems
     * @return list<array<string, mixed>>
     */
    private function sourcePdfReferenceItemsInSourceOrder(array $sourceItems, array $positionedItems): array
    {
        $match = $this->matchSourcePdfLinesToPositionedItems($sourceItems, $positionedItems);
        $items = [];
        $referenceStarted = false;
        foreach ($sourceItems as $index => $sourceItem) {
            $referenceStarted = $referenceStarted || $this->lineLooksLikePdfReferenceEntry($sourceItem['text']);
            $matchedItem = $match['itemsBySourceIndex'][$index] ?? null;
            // Directly matched lines may already contain a local, evidence-
            // backed separator repair. A reference page keeps source order,
            // not source spelling, so retain that exact matched occurrence.
            // Fragment composites still expand through the individual source
            // records below to avoid duplicating their shared source line.
            $item = is_array($matchedItem) && !isset($matchedItem['sourcePdfSourceIndexes'])
                ? $matchedItem
                : $this->sourcePdfLineItem($sourceItem, $matchedItem);
            if ($referenceStarted) {
                $item['sourcePdfReferenceEntry'] = true;
                if (is_array($matchedItem)) {
                    $item = $this->markSourcePdfVerifiedGeometryText($item, $matchedItem);
                    $item['text'] = $this->sourcePdfReferenceTextWithLocalPunctuationSeparators(
                        (string) ($item['text'] ?? ''),
                        (string) ($matchedItem['text'] ?? '')
                    );
                }
            }

            $previousItemIndex = array_key_last($items);
            $previousSourceItem = $index > 0 ? ($sourceItems[$index - 1] ?? null) : null;
            if ($previousItemIndex !== null
                && is_array($previousSourceItem)
                && ($items[$previousItemIndex]['sourcePdfReferenceEntry'] ?? false) === true
                && ($item['sourcePdfReferenceEntry'] ?? false) === true
                && ($previousSourceItem['page'] ?? null) === ($sourceItem['page'] ?? null)
                && ($previousSourceItem['stream'] ?? null) === ($sourceItem['stream'] ?? null)
                && preg_match('/[-\x{2010}\x{2011}]\s*$/u', (string) ($previousSourceItem['text'] ?? '')) === 1
                && $this->lineLooksLikeUrlOnly((string) ($sourceItem['text'] ?? ''))
                && $this->repairedPdfLayoutContinuesWrappedLine($items[$previousItemIndex], $item)) {
                $pair = (string) ($sourceItem['page'] ?? '') . "\0" . (string) ($sourceItem['stream'] ?? '') . "\0reference\0" . ($index - 1) . "\0" . $index;
                $items[$previousItemIndex]['sourcePdfTerminalDashSeparatorPairAfter'] = $pair;
                $item['sourcePdfTerminalDashSeparatorPairBefore'] = $pair;
            }
            $items[] = $item;
        }

        return $items;
    }

    /**
     * Reference entries sometimes omit spaces around parenthetical labels in
     * their source stream. Apply only structural punctuation separators and
     * only after the exact source record matched one positioned visual line;
     * no vocabulary or title-shaped text is involved.
     */
    private function sourcePdfReferenceTextWithLocalPunctuationSeparators(string $sourceText, string $positionedText): string
    {
        if ($this->pdfComparableLineText($sourceText) === ''
            || $this->pdfComparableLineText($sourceText) !== $this->pdfComparableLineText($positionedText)) {
            return $sourceText;
        }

        $text = preg_replace('/([\p{L}\p{N}])(?=\()/u', '$1 ', $sourceText) ?? $sourceText;

        return preg_replace('/(\))(?=[\p{L}\p{N}])/u', '$1 ', $text) ?? $text;
    }

    /**
     * @param list<array<string, mixed>> $items
     */
    private function sourcePdfGeometryOrderHasStableBodyColumns(array $items): bool
    {
        $counts = [];
        foreach ($items as $item) {
            if (($item['sourceStructuredGeometry'] ?? false) !== true
                || !isset($item['sourceGeometryColumn'])) {
                continue;
            }
            $column = (int) $item['sourceGeometryColumn'];
            $counts[$column] = ($counts[$column] ?? 0) + 1;
        }
        if (count($counts) < 2 || count($counts) > 4) {
            return false;
        }

        foreach ($counts as $count) {
            if ($count < 8) {
                return false;
            }
        }

        return true;
    }

    /**
     * @param list<array<string, mixed>> $items
     */
    private function sourcePdfGeometryBodyColumnCount(array $items): int
    {
        $columns = [];
        foreach ($items as $item) {
            if (($item['sourceStructuredGeometry'] ?? false) !== true
                || !isset($item['sourceGeometryColumn'])) {
                continue;
            }
            $columns[(int) $item['sourceGeometryColumn']] = true;
        }

        return count($columns);
    }

    /**
     * A bibliography is an ordered sequence even when its visual layout uses
     * two columns. Source order keeps each numbered entry and its wrapped
     * continuation together, whereas column reconstruction can otherwise
     * separate their titles from publication details.
     *
     * @param list<array{page: int, stream: int, text: string}> $sourceItems
     */
    private function sourcePdfPageContainsReferenceList(array $sourceItems): bool
    {
        $entries = 0;
        foreach ($sourceItems as $item) {
            if ($this->lineLooksLikePdfReferenceEntry($item['text'])) {
                $entries++;
            }
        }

        return $entries >= 3;
    }

    /**
     * Keep a source-ordered page when the existing text-table recognizer can
     * reconstruct a real table there. Reordering every visual line first
     * destroys the stacked-cell sequence that makes table recovery possible.
     *
     * @param list<array{page: int, stream: int, text: string}> $sourceItems
     */
    private function sourcePdfPageContainsTextTable(array $sourceItems): bool
    {
        $lines = array_column($sourceItems, 'text');
        if ($lines === []) {
            return false;
        }
        $repaired = $this->repairProseTextLines(
            $lines,
            $this->looksLikeProseRepairCandidate($lines),
            []
        );

        return $this->countNodesOfType($this->blocksFromLines($repaired), 'table') > 0;
    }

    /**
     * A page can contain a real table beside ordinary prose. Preserve the
     * source table recognizer only when visual ordering would lose that table;
     * otherwise geometry can still keep the prose columns independent.
     *
     * @param list<array<string, mixed>> $items
     */
    private function sourcePdfGeometryOrderPreservesTextTable(array $items): bool
    {
        $items = $this->markPositionedPdfParagraphBoundaries($items);
        $lines = $this->positionedLineItemTexts($items);
        $repaired = $this->repairProseTextLines(
            $lines,
            $this->looksLikeProseRepairCandidate($lines),
            $items
        );

        return $this->countNodesOfType($this->blocksFromLines($repaired), 'table') > 0;
    }

    /**
     * Geometry must not reorder a code-bearing page unless the later code
     * injector can still recover every sustained monospaced listing.
     *
     * @param list<array<string, mixed>> $items
     * @param list<array<string, mixed>> $positionedItems
     */
    private function sourcePdfGeometryOrderPreservesPositionedCode(
        array $items,
        array $positionedItems
    ): bool {
        $codeBlocks = $this->positionedCodeBlocksFromLineItems($positionedItems);
        if ($codeBlocks === []) {
            return true;
        }

        $items = $this->markPositionedPdfParagraphBoundaries($items);
        $lines = $this->positionedLineItemTexts($items);
        $repaired = $this->repairProseTextLines(
            $lines,
            $this->looksLikeProseRepairCandidate($lines),
            $items
        );
        $injected = $this->injectPositionedCodeBlocks($repaired, $codeBlocks);

        return $this->countNodesOfType($this->blocksFromLines($injected), 'code_block') >= count($codeBlocks);
    }

    /**
     * Geometry-derived code blocks carry their own column alignment. Retain
     * ordinary source order on those pages so the existing code-span injector
     * can replace the complete listing atomically.
     *
     * @param list<array<string, mixed>> $positionedItems
     */
    private function positionedPdfPageContainsCode(array $positionedItems): bool
    {
        foreach ($positionedItems as $item) {
            if (($item['code'] ?? false) === true) {
                return true;
            }
        }

        return false;
    }

    /**
     * @param list<array{page: int, stream: int, text: string}> $sourceItems
     * @param list<array<string, mixed>> $positionedItems
     */
    private function positionedPdfPageTextLooksUsable(array $sourceItems, array $positionedItems): bool
    {
        if ($positionedItems === [] || !$this->positionedPdfPageGeometryLooksUsable($positionedItems)) {
            return false;
        }

        return $this->positionedProseLinesLookUsable(
            $this->positionedLineItemTexts($positionedItems),
            array_column($sourceItems, 'text')
        );
    }

    /**
     * Form XObjects can occasionally expose readable text with a broken
     * coordinate transform. In that case several independent visual lines
     * collapse to the same baseline and start position. Treat that geometry as
     * untrustworthy rather than using it to reorder otherwise usable text.
     *
     * @param list<array<string, mixed>> $items
     */
    private function positionedPdfPageGeometryLooksUsable(array $items): bool
    {
        if (count($items) < 3) {
            return true;
        }

        $fontSizes = [];
        foreach ($items as $item) {
            if (!$this->pdfLayoutHasGeometry($item)) {
                return false;
            }
            $fontSizes[] = max(1.0, (float) $item['fontSize']);
        }
        $fontSize = $this->median($fontSizes);
        $baselineTolerance = max(0.35, min(2.0, $fontSize * 0.10));
        $startTolerance = max(3.0, $fontSize * 0.50);
        $baselineGroups = [];
        foreach ($items as $item) {
            $baseline = (float) $item['y1'];
            $groupIndex = null;
            foreach ($baselineGroups as $index => $group) {
                if (abs($baseline - $group['baseline']) <= $baselineTolerance) {
                    $groupIndex = $index;
                    break;
                }
            }
            if ($groupIndex === null) {
                $baselineGroups[] = ['baseline' => $baseline, 'items' => [$item]];
                continue;
            }
            $baselineGroups[$groupIndex]['items'][] = $item;
        }

        foreach ($baselineGroups as $group) {
            if (count($group['items']) < 3) {
                continue;
            }
            $startGroups = [];
            foreach ($group['items'] as $item) {
                $start = (float) $item['x1'];
                $groupIndex = null;
                foreach ($startGroups as $index => $startGroup) {
                    if (abs($start - $startGroup['start']) <= $startTolerance) {
                        $groupIndex = $index;
                        break;
                    }
                }
                if ($groupIndex === null) {
                    $startGroups[] = ['start' => $start, 'items' => [$item]];
                    continue;
                }
                $startGroups[$groupIndex]['items'][] = $item;
            }
            foreach ($startGroups as $startGroup) {
                if (count($startGroup['items']) >= 3) {
                    return false;
                }
            }
        }

        return true;
    }

    /**
     * @param list<array{page: int, stream: int, text: string}> $sourceItems
     * @param list<array{text: string, page: int, x1: float, y1: float, x2: float, y2: float, fontSize: float, code?: bool, codeText?: string}> $positionedItems
     * @return array{items: list<array<string, mixed>>, sourceIndexes: array<int, true>, itemsBySourceIndex: array<int, array<string, mixed>>, visualEntries: list<array{item: array<string, mixed>, sourceIndex: int|null}>}
     */
    private function matchSourcePdfLinesToPositionedItems(
        array $sourceItems,
        array $positionedItems
    ): array
    {
        $sourceIndexesByKey = [];
        $sourceIndexesByComparablePrefix = [];
        $sourceIndexesByCompactPrefix = [];
        foreach ($sourceItems as $index => $item) {
            $key = $this->pdfComparableLineText($item['text']);
            if ($key !== '') {
                $sourceIndexesByKey[$key][] = $index;
            }
            if ($this->length($key) >= 8) {
                $sourceIndexesByComparablePrefix[substr($key, 0, 8)][] = $index;
            }
            if ($this->length($key) >= 1 && $this->length($key) <= 3) {
                $sourceIndexesByCompactPrefix[substr($key, 0, 1)][] = $index;
            }
        }

        $positionedItems = $this->combineComplementaryPositionedPdfExactSourceRanges(
            $positionedItems,
            $sourceItems
        );
        $positionedItems = $this->combineAdjacentPositionedPdfFragmentsMatchingSourceLines(
            $positionedItems,
            $sourceItems,
            $sourceIndexesByKey,
            $sourceIndexesByComparablePrefix,
            $sourceIndexesByCompactPrefix
        );

        $nextSourceIndexByKey = [];
        $matchedItems = [];
        $matchedSourceIndexes = [];
        $matchedItemsBySourceIndex = [];
        $visualEntries = [];
        $shortSupplementalCandidates = [];
        $previousWasSupplementalPositionedItem = false;
        $consumedPositionedIndexes = [];
        $exactOccurrenceKeys = [];
        foreach ($positionedItems as $positionedIndex => $positionedItem) {
            if (isset($consumedPositionedIndexes[$positionedIndex])) {
                continue;
            }
            $key = $this->pdfComparableLineText($positionedItem['text']);
            $sourceIndex = null;
            $footnotePrefixedSourceMatch = false;
            if ($this->length($key) >= 3 && isset($sourceIndexesByKey[$key])) {
                $offset = $nextSourceIndexByKey[$key] ?? 0;
                $sourceIndexes = $sourceIndexesByKey[$key];
                while (isset($sourceIndexes[$offset]) && isset($matchedSourceIndexes[$sourceIndexes[$offset]])) {
                    $offset++;
                }
                if (isset($sourceIndexes[$offset])) {
                    $sourceIndex = $sourceIndexes[$offset];
                    $nextSourceIndexByKey[$key] = $offset + 1;
                }
            }
            if ($sourceIndex === null
                && $this->length($key) >= 1
                && $this->length($key) <= 2
                && isset($sourceIndexesByKey[$key])) {
                $sourceIndex = $this->sourcePdfShortExactSourceIndexMatchingPositionedLine(
                    $sourceItems,
                    $sourceIndexesByKey[$key],
                    $matchedSourceIndexes,
                    $matchedItemsBySourceIndex,
                    $positionedItem
                );
            }

            if ($sourceIndex === null) {
                $sourceIndex = $this->sourcePdfFootnotePrefixedSourceIndexMatchingPositionedLine(
                    $sourceItems,
                    $matchedSourceIndexes,
                    $positionedItem
                );
                $footnotePrefixedSourceMatch = $sourceIndex !== null;
            }

            $exactRangeIndexes = $this->sourcePdfExactRangeIndexesMatchingPositionedLine(
                $sourceItems,
                $matchedSourceIndexes,
                $positionedItem
            );
            $preferExactOccurrence = isset($exactOccurrenceKeys[$key]);
            if (count($exactRangeIndexes) === 1
                && $sourceIndex !== null
                && $sourceIndex !== $exactRangeIndexes[0]) {
                $heuristicSignificant = $this->pdfSourceOccurrenceComparableText(
                    (string) ($sourceItems[$sourceIndex]['text'] ?? '')
                );
                $exactSignificant = $this->pdfSourceOccurrenceComparableText(
                    (string) ($sourceItems[$exactRangeIndexes[0]]['text'] ?? '')
                );
                if ($heuristicSignificant !== ''
                    && $exactSignificant !== ''
                    && !hash_equals($heuristicSignificant, $exactSignificant)) {
                    // A complete occurrence-local range is stronger when the
                    // punctuation-insensitive key has conflated genuinely
                    // different source spellings. Keep that evidence policy
                    // for later occurrences of the same key so a run of dash
                    // variants cannot alternate between two identity rules.
                    $exactOccurrenceKeys[$key] = true;
                    $preferExactOccurrence = true;
                }
            }
            if ($preferExactOccurrence && count($exactRangeIndexes) === 1) {
                $sourceIndex = $exactRangeIndexes[0];
                $footnotePrefixedSourceMatch = false;
            } elseif ($preferExactOccurrence && count($exactRangeIndexes) > 1) {
                $sourceIndex = null;
                $footnotePrefixedSourceMatch = false;
            }
            $exactRangeCarrierHasOnlyNonStructuralInlineExtras = false;
            if (count($exactRangeIndexes) > 1
                && $sourceIndex !== null
                && in_array($sourceIndex, $exactRangeIndexes, true)) {
                $exactRangeCarrierHasOnlyNonStructuralInlineExtras = true;
                foreach ($exactRangeIndexes as $exactRangeIndex) {
                    if ($exactRangeIndex === $sourceIndex) {
                        continue;
                    }
                    $exactRangeText = trim((string) (
                        $sourceItems[$exactRangeIndex]['text'] ?? ''
                    ));
                    if ($exactRangeText === ''
                        || $this->length($exactRangeText) > 3
                        || preg_match('/^[\p{M}\p{P}\p{S}]+$/u', $exactRangeText) !== 1
                        || $this->lineIsStandalonePdfListMarker($exactRangeText)) {
                        $exactRangeCarrierHasOnlyNonStructuralInlineExtras = false;
                        break;
                    }
                }
            }
            if ($exactRangeCarrierHasOnlyNonStructuralInlineExtras) {
                // A carrier whose complete positioned ranges and separators
                // prove several contiguous source occurrences is stronger
                // than a punctuation-insensitive key which happens to match
                // only its prose component. Keep short inline punctuation,
                // symbols, and combining marks with that visual line, while
                // leaving numeric footnotes and structural list markers to
                // their dedicated occurrence-local processors.
                $sourceIndex = null;
                $footnotePrefixedSourceMatch = false;
            }
            $exactRangeFragmentIndexes = $sourceIndex === null
                ? $exactRangeIndexes
                : [];
            $fragmentIndexes = $exactRangeFragmentIndexes;
            if ($fragmentIndexes === []) {
                $fragmentIndexes = $sourceIndex === null
                    ? $this->sourcePdfFragmentIndexesMatchingPositionedLine(
                        $sourceItems,
                        $matchedSourceIndexes,
                        $key,
                        $sourceIndexesByComparablePrefix,
                        $sourceIndexesByCompactPrefix,
                        $positionedItem
                    )
                    : [];
            }
            if ($fragmentIndexes !== []) {
                $firstSourceIndex = $fragmentIndexes[0];
                $sourceItem = $this->sourcePdfJoinedFragmentLineItem(
                    $sourceItems,
                    $fragmentIndexes,
                    $positionedItem
                );
                if ($sourceItem === null) {
                    continue;
                }
                $item = $this->sourcePdfLineItem($sourceItem, $positionedItem);
                $item = $this->markSourcePdfVerifiedGeometryText($item, $positionedItem);
                $item['sourcePdfSourceIndexes'] = $fragmentIndexes;
                $item['sourcePdfSourceIndexEnd'] = $fragmentIndexes[array_key_last($fragmentIndexes)];
                if ($exactRangeFragmentIndexes !== []) {
                    // Exact page/stream character alignment is stronger than
                    // a heuristic table-cell grouping for this one visual
                    // line. Retain that provenance through table restoration.
                    $item['sourcePdfExactRangeFragmentSequence'] = true;
                }
                foreach ($fragmentIndexes as $fragmentIndex) {
                    $matchedSourceIndexes[$fragmentIndex] = true;
                }
                $matchedItems[] = $item;
                $matchedItemsBySourceIndex[$firstSourceIndex] = $item;
                $visualEntries[] = ['item' => $item, 'sourceIndex' => $firstSourceIndex];
                $previousWasSupplementalPositionedItem = false;
                continue;
            }

            $inlineSiblingIndexes = $this->positionedPdfInlineContinuationSiblingIndexes(
                $positionedItems,
                $positionedIndex
            );
            $inlineText = $inlineSiblingIndexes === []
                ? null
                : $this->positionedPdfInlineContinuationText(
                    $positionedItem,
                    $positionedItems,
                    $inlineSiblingIndexes
                );
            if ($inlineText !== null) {
                $inlineKey = $this->pdfComparableLineText($inlineText);
                $inlineFragmentIndexes = $inlineKey === $key
                    ? []
                    : $this->sourcePdfFragmentIndexesMatchingPositionedLine(
                        $sourceItems,
                        $matchedSourceIndexes,
                        $inlineKey,
                        $sourceIndexesByComparablePrefix,
                        $sourceIndexesByCompactPrefix
                    );
                if ($inlineFragmentIndexes !== []) {
                    $firstSourceIndex = $inlineFragmentIndexes[0];
                    $positionedLayout = $this->positionedPdfCompositeInlineContinuationLayout(
                        $positionedItem,
                        $positionedItems,
                        $inlineSiblingIndexes
                    );
                    $positionedLayout['text'] = $inlineText;
                    $sourceItem = $this->sourcePdfJoinedFragmentLineItem(
                        $sourceItems,
                        $inlineFragmentIndexes,
                        $positionedLayout
                    );
                    if ($sourceItem === null) {
                        continue;
                    }
                    $item = $this->sourcePdfLineItem($sourceItem, $positionedLayout);
                    $item = $this->markSourcePdfVerifiedGeometryText($item, $positionedLayout);
                    $item['sourcePdfSourceIndexes'] = $inlineFragmentIndexes;
                    $item['sourcePdfSourceIndexEnd'] = $inlineFragmentIndexes[array_key_last($inlineFragmentIndexes)];
                    foreach ($inlineFragmentIndexes as $fragmentIndex) {
                        $matchedSourceIndexes[$fragmentIndex] = true;
                    }
                    foreach ($inlineSiblingIndexes as $inlineSiblingIndex) {
                        $consumedPositionedIndexes[$inlineSiblingIndex] = true;
                    }
                    $matchedItems[] = $item;
                    $matchedItemsBySourceIndex[$firstSourceIndex] = $item;
                    $visualEntries[] = ['item' => $item, 'sourceIndex' => $firstSourceIndex];
                    $previousWasSupplementalPositionedItem = false;
                    continue;
                }
            }

            if ($sourceIndex !== null) {
                $matchedSourceIndexes[$sourceIndex] = true;
                // Preserve the source line's own separators here. The
                // positioned layer is authoritative for visual order, but a
                // line whose font advances are only estimated can omit normal
                // spaces. Exact source-fragment reconciliation below handles
                // proven intra-word boundaries occurrence by occurrence.
                $item = $this->sourcePdfLineItem($sourceItems[$sourceIndex], $positionedItem);
                $boundarySeparators = $this->positionedSourceVerifiedBoundarySeparators($positionedItem);
                if ($this->sourcePdfCanApplyProvenPositionedSeparators(
                    $sourceItems,
                    $sourceIndex,
                    $positionedItem,
                    $matchedItemsBySourceIndex
                )) {
                    $item['text'] = $this->sourcePdfLineTextWithProvenPositionedSeparators(
                        (string) $item['text'],
                        (string) ($positionedItem['text'] ?? ''),
                        $boundarySeparators
                    );
                }
                $item = $this->markSourcePdfVerifiedGeometryText($item, $positionedItem);
                if ($footnotePrefixedSourceMatch) {
                    $item['sourceFootnotePrefixedGeometry'] = true;
                }
                $matchedItems[] = $item;
                $matchedItemsBySourceIndex[$sourceIndex] = $item;
                $visualEntries[] = ['item' => $item, 'sourceIndex' => $sourceIndex];
                $previousWasSupplementalPositionedItem = false;
                continue;
            }

            $partialFragmentIndexes = $this->sourcePdfFragmentIndexesExtendingPositionedLine(
                $sourceItems,
                $matchedSourceIndexes,
                $key,
                $sourceIndexesByComparablePrefix
            );
            if ($partialFragmentIndexes !== [] && $inlineText !== null) {
                $firstSourceIndex = $partialFragmentIndexes[0];
                $sourceItem = $this->sourcePdfJoinedFragmentLineItem(
                    $sourceItems,
                    $partialFragmentIndexes,
                    array_replace(
                        $this->positionedPdfCompositeInlineContinuationLayout(
                            $positionedItem,
                            $positionedItems,
                            $inlineSiblingIndexes
                        ),
                        ['text' => $inlineText]
                    )
                );
                if ($sourceItem === null) {
                    continue;
                }
                $positionedLayout = $this->positionedPdfCompositeInlineContinuationLayout(
                    $positionedItem,
                    $positionedItems,
                    $inlineSiblingIndexes
                );
                $item = $this->sourcePdfLineItem($sourceItem, $positionedLayout);
                $item['sourceVerifiedGeometryText'] = true;
                $item['sourceVerifiedPartialInlineGeometry'] = true;
                $item['sourcePdfSourceIndexes'] = $partialFragmentIndexes;
                $item['sourcePdfSourceIndexEnd'] = $partialFragmentIndexes[array_key_last($partialFragmentIndexes)];
                foreach ($partialFragmentIndexes as $fragmentIndex) {
                    $matchedSourceIndexes[$fragmentIndex] = true;
                }
                foreach ($inlineSiblingIndexes as $inlineSiblingIndex) {
                    $consumedPositionedIndexes[$inlineSiblingIndex] = true;
                }
                $matchedItems[] = $item;
                $matchedItemsBySourceIndex[$firstSourceIndex] = $item;
                $visualEntries[] = ['item' => $item, 'sourceIndex' => $firstSourceIndex];
                $previousWasSupplementalPositionedItem = false;
                continue;
            }

            if ($this->positionedPdfLineCanSupplementSource($positionedItem)) {
                $item = $positionedItem;
                $item['sourceSupplementalPositioned'] = true;
                if ($this->positionedPdfLineHasRecoverableSentenceSuffix($positionedItem)) {
                    // The leading visual run is damaged, but punctuation
                    // exposes a complete body sentence after it.
                    $item['sourceSupplementalRecoverableSentenceSuffix'] = true;
                    $item['sourceInterruptedColumnRegion'] = true;
                    $item['forceBlockBreakBefore'] = true;
                }
                if ($this->positionedPdfLineSubstantiallyOverlapsSource($positionedItem, $sourceItems)) {
                    if ($this->lineLooksLikeUrlOnly((string) ($positionedItem['text'] ?? ''))) {
                        $item['sourceSupplementalUrlOverlap'] = true;
                    } else {
                        $item['sourceSupplementalSourceOverlap'] = true;
                    }
                }
                if (!$previousWasSupplementalPositionedItem) {
                    $item['forceBlockBreakBefore'] = true;
                }
                $visualEntries[] = ['item' => $item, 'sourceIndex' => null];
                $previousWasSupplementalPositionedItem = true;
                continue;
            }
            $shortSupplementalCandidates[] = $positionedItem;
            $previousWasSupplementalPositionedItem = false;
        }

        foreach ($shortSupplementalCandidates as $positionedItem) {
            $item = $positionedItem;
            $item['sourceSupplementalPositioned'] = true;
            $item['sourceShortSupplementalCandidate'] = true;
            $visualEntries[] = ['item' => $item, 'sourceIndex' => null];
        }

        return [
            'items' => $matchedItems,
            'sourceIndexes' => $matchedSourceIndexes,
            'itemsBySourceIndex' => $matchedItemsBySourceIndex,
            'visualEntries' => $visualEntries,
        ];
    }

    /**
     * Match a positioned line through the exact occurrence-local byte ranges
     * produced only after a complete page/stream text alignment. This path is
     * intentionally independent of line length and permits adjacent source
     * records to cross /Contents operands on the same page.
     *
     * @param list<array<string, mixed>> $sourceItems
     * @param array<int, true> $matchedSourceIndexes
     * @param array<string, mixed> $positionedItem
     * @return list<int>
     */
    private function sourcePdfExactRangeIndexesMatchingPositionedLine(
        array $sourceItems,
        array $matchedSourceIndexes,
        array $positionedItem
    ): array {
        $coverage = $this->sourcePdfExactRangeCoverage(
            $sourceItems,
            $this->pdfPositionedExactSourceRanges($positionedItem),
            (int) ($positionedItem['page'] ?? 0),
            true
        );
        if ($coverage === null || $coverage['localIndexes'] === []) {
            return [];
        }
        foreach ($coverage['localIndexes'] as $sourceIndex) {
            if (isset($matchedSourceIndexes[$sourceIndex])) {
                return [];
            }
        }
        if ($coverage['projection'] !== $this->pdfSourceOccurrenceComparableText(
            (string) ($positionedItem['text'] ?? '')
        ) || $this->sourcePdfFragmentSeparatorsFromPositionedText(
            $sourceItems,
            $coverage['localIndexes'],
            $positionedItem
        ) === null) {
            return [];
        }

        return $coverage['localIndexes'];
    }

    /**
     * Validate complete significant-byte coverage for source occurrences.
     * When contiguity is required, both document-global and page-local source
     * identities must advance by one and the exact glyph boxes must progress
     * horizontally. No stream-equality condition is imposed: a page may use
     * an array of /Contents streams for one painted line.
     *
     * @param list<array<string, mixed>> $sourceItems
     * @param list<array{sourceIndex:int,sourceStart:int,sourceEnd:int}> $ranges
     * @return array{localIndexes:list<int>,globalIndexes:list<int>,ranges:list<array{sourceIndex:int,sourceStart:int,sourceEnd:int}>,projection:string}|null
     */
    private function sourcePdfExactRangeCoverage(
        array $sourceItems,
        array $ranges,
        int $page,
        bool $requireContiguous
    ): ?array {
        if ($ranges === [] || $page < 1) {
            return null;
        }
        $localIndexByGlobalIndex = [];
        foreach ($sourceItems as $localIndex => $sourceItem) {
            $globalIndex = is_int($sourceItem['sourcePdfGlobalSourceIndex'] ?? null)
                ? $sourceItem['sourcePdfGlobalSourceIndex']
                : $localIndex;
            if (isset($localIndexByGlobalIndex[$globalIndex])) {
                return null;
            }
            $localIndexByGlobalIndex[$globalIndex] = $localIndex;
        }

        $rangesByGlobalIndex = [];
        foreach ($ranges as $range) {
            $globalIndex = $range['sourceIndex'];
            if (!isset($localIndexByGlobalIndex[$globalIndex])) {
                return null;
            }
            $rangesByGlobalIndex[$globalIndex][] = $range;
        }
        ksort($rangesByGlobalIndex, SORT_NUMERIC);

        $localIndexes = [];
        $globalIndexes = [];
        $normalizedRanges = [];
        $projection = '';
        $previousGlobalIndex = null;
        $previousLocalIndex = null;
        $previousX = null;
        $previousX2 = null;
        $previousHeight = null;
        foreach ($rangesByGlobalIndex as $globalIndex => $sourceRanges) {
            $localIndex = $localIndexByGlobalIndex[$globalIndex];
            $sourceItem = $sourceItems[$localIndex] ?? null;
            $geometry = is_array($sourceItem['sourceGeometry'] ?? null)
                ? $sourceItem['sourceGeometry']
                : null;
            if (!is_array($sourceItem)
                || (int) ($sourceItem['page'] ?? 0) !== $page
                || ($sourceItem['sourceGeometryMethod'] ?? null) !== 'exact-page-stream-character-offset'
                || $geometry === null
                || !$this->pdfSourceBoundsAreValid($geometry)
                || ($geometry['orientation'] ?? null) !== 'horizontal') {
                return null;
            }

            usort($sourceRanges, static fn (array $left, array $right): int =>
                ($left['sourceStart'] <=> $right['sourceStart'])
                    ?: ($left['sourceEnd'] <=> $right['sourceEnd'])
            );
            $cursor = 0;
            foreach ($sourceRanges as $range) {
                if ($range['sourceStart'] !== $cursor) {
                    return null;
                }
                $cursor = $range['sourceEnd'];
            }
            $significant = $this->pdfSourceOccurrenceComparableText(
                (string) ($sourceItem['text'] ?? '')
            );
            if ($significant === '' || $cursor !== strlen($significant)) {
                return null;
            }

            if ($requireContiguous) {
                $geometryHeight = max(
                    0.0,
                    (float) $geometry['y2'] - (float) $geometry['y1']
                );
                $overlayBacktrackTolerance = max(
                    0.75,
                    min(
                        1.5,
                        min($previousHeight ?? $geometryHeight, $geometryHeight) * 0.125
                    )
                );
                if (($previousGlobalIndex !== null && $globalIndex !== $previousGlobalIndex + 1)
                    || ($previousLocalIndex !== null && $localIndex !== $previousLocalIndex + 1)
                    // Superscripts and combining marks can be painted just
                    // inside the following base glyph. Admit only this small,
                    // glyph-relative overlay when the right edge still
                    // advances, while retaining exact adjacency, orientation,
                    // projection, and separator requirements.
                    || ($previousX !== null
                        && (float) $geometry['x1'] < $previousX - $overlayBacktrackTolerance)
                    || ($previousX !== null
                        && (float) $geometry['x1'] < $previousX - 0.75
                        && ($previousX2 === null
                            || (float) $geometry['x2'] <= $previousX2 + 0.25))) {
                    return null;
                }
                $previousHeight = $geometryHeight;
            }
            $previousGlobalIndex = $globalIndex;
            $previousLocalIndex = $localIndex;
            $previousX = (float) $geometry['x1'];
            $previousX2 = (float) $geometry['x2'];
            $localIndexes[] = $localIndex;
            $globalIndexes[] = $globalIndex;
            $normalizedRanges[] = [
                'sourceIndex' => $globalIndex,
                'sourceStart' => 0,
                'sourceEnd' => strlen($significant),
            ];
            $projection .= $significant;
        }

        return [
            'localIndexes' => $localIndexes,
            'globalIndexes' => $globalIndexes,
            'ranges' => $normalizedRanges,
            'projection' => $projection,
        ];
    }

    /**
     * One visual line can be split into complementary positioned records when
     * a glyph is painted with a different text matrix. Compose only adjacent
     * records whose full exact-source ranges interleave, whose aggregate
     * character inventory equals one contiguous source sequence, and whose
     * geometry overlaps locally. This is provenance, never URL vocabulary.
     *
     * @param list<array<string, mixed>> $positionedItems
     * @param list<array<string, mixed>> $sourceItems
     * @return list<array<string, mixed>>
     */
    private function combineComplementaryPositionedPdfExactSourceRanges(
        array $positionedItems,
        array $sourceItems
    ): array {
        $combined = [];
        for ($index = 0, $count = count($positionedItems); $index < $count; $index++) {
            $item = $positionedItems[$index];
            $next = $positionedItems[$index + 1] ?? null;
            $candidate = is_array($next)
                ? $this->complementaryPositionedPdfExactSourceRangeItem(
                    $item,
                    $next,
                    $sourceItems
                )
                : null;
            if ($candidate === null) {
                $combined[] = $item;
                continue;
            }
            $combined[] = $candidate;
            $index++;
        }

        return $combined;
    }

    /**
     * @param array<string, mixed> $left
     * @param array<string, mixed> $right
     * @param list<array<string, mixed>> $sourceItems
     * @return array<string, mixed>|null
     */
    private function complementaryPositionedPdfExactSourceRangeItem(
        array $left,
        array $right,
        array $sourceItems
    ): ?array {
        if (!$this->pdfLayoutHasGeometry($left)
            || !$this->pdfLayoutHasGeometry($right)
            || ($left['code'] ?? false) === true
            || ($right['code'] ?? false) === true
            || (int) ($left['page'] ?? 0) !== (int) ($right['page'] ?? 0)) {
            return null;
        }
        $page = (int) $left['page'];
        $leftCoverage = $this->sourcePdfExactRangeCoverage(
            $sourceItems,
            $this->pdfPositionedExactSourceRanges($left),
            $page,
            false
        );
        $rightCoverage = $this->sourcePdfExactRangeCoverage(
            $sourceItems,
            $this->pdfPositionedExactSourceRanges($right),
            $page,
            false
        );
        if ($leftCoverage === null
            || $rightCoverage === null
            || $leftCoverage['projection'] !== $this->pdfSourceOccurrenceComparableText(
                (string) ($left['text'] ?? '')
            )
            || $rightCoverage['projection'] !== $this->pdfSourceOccurrenceComparableText(
                (string) ($right['text'] ?? '')
            )) {
            return null;
        }

        $ownersByGlobalIndex = [];
        foreach ([0 => $leftCoverage, 1 => $rightCoverage] as $owner => $coverage) {
            foreach ($coverage['globalIndexes'] as $globalIndex) {
                if (isset($ownersByGlobalIndex[$globalIndex])) {
                    return null;
                }
                $ownersByGlobalIndex[$globalIndex] = $owner;
            }
        }
        ksort($ownersByGlobalIndex, SORT_NUMERIC);
        $ownerSequence = array_values($ownersByGlobalIndex);
        $ownerTransitions = 0;
        for ($index = 1, $count = count($ownerSequence); $index < $count; $index++) {
            if ($ownerSequence[$index] !== $ownerSequence[$index - 1]) {
                $ownerTransitions++;
            }
        }
        if ($ownerTransitions < 2) {
            return null;
        }

        $unionCoverage = $this->sourcePdfExactRangeCoverage(
            $sourceItems,
            array_merge($leftCoverage['ranges'], $rightCoverage['ranges']),
            $page,
            true
        );
        if ($unionCoverage === null) {
            return null;
        }
        $leftSignificant = $this->pdfSourceOccurrenceComparableText(
            (string) ($left['text'] ?? '')
        );
        $rightSignificant = $this->pdfSourceOccurrenceComparableText(
            (string) ($right['text'] ?? '')
        );
        if ($this->pdfExactCharacterInventory($leftSignificant . $rightSignificant)
            !== $this->pdfExactCharacterInventory($unionCoverage['projection'])) {
            return null;
        }

        $fontSize = max(
            1.0,
            (float) ($left['fontSize'] ?? 0.0),
            (float) ($right['fontSize'] ?? 0.0)
        );
        if (abs((float) ($left['fontSize'] ?? 0.0) - (float) ($right['fontSize'] ?? 0.0))
            > max(1.5, $fontSize * 0.25)) {
            return null;
        }
        $horizontalGap = max((float) $left['x1'], (float) $right['x1'])
            - min((float) $left['x2'], (float) $right['x2']);
        if ($horizontalGap > max(4.0, $fontSize * 0.50)) {
            return null;
        }
        $leftCenter = ((float) $left['y1'] + (float) $left['y2']) / 2.0;
        $rightCenter = ((float) $right['y1'] + (float) $right['y2']) / 2.0;
        $sameBaseline = abs($leftCenter - $rightCenter) <= max(2.5, $fontSize * 0.35);
        $leftIsSingleton = count($leftCoverage['localIndexes']) === 1
            && $this->length($leftSignificant) === 1;
        $rightIsSingleton = count($rightCoverage['localIndexes']) === 1
            && $this->length($rightSignificant) === 1;
        $singleton = $leftIsSingleton ? $left : ($rightIsSingleton ? $right : null);
        $carrier = $leftIsSingleton ? $right : $left;
        if (!$sameBaseline) {
            if ($singleton === null) {
                return null;
            }
            $verticalOverlap = min((float) $singleton['y2'], (float) $carrier['y2'])
                - max((float) $singleton['y1'], (float) $carrier['y1']);
            $minimumHeight = min(
                (float) $singleton['y2'] - (float) $singleton['y1'],
                (float) $carrier['y2'] - (float) $carrier['y1']
            );
            if ($minimumHeight <= 0.0
                || $verticalOverlap < $minimumHeight * 0.25
                || abs((float) $singleton['x1'] - (float) $carrier['x1'])
                    > max(0.75, $fontSize * 0.15)
                || (float) $singleton['x2'] > (float) $carrier['x1'] + max(2.0, $fontSize)) {
                return null;
            }
        }

        $sourceText = '';
        foreach ($unionCoverage['localIndexes'] as $sourceIndex) {
            $sourceText .= (string) ($sourceItems[$sourceIndex]['text'] ?? '');
        }
        $composedText = $sourceText;
        if ($singleton !== null) {
            $singletonCoverage = $leftIsSingleton ? $leftCoverage : $rightCoverage;
            $carrierCoverage = $leftIsSingleton ? $rightCoverage : $leftCoverage;
            $singletonGlobalIndex = $singletonCoverage['globalIndexes'][0] ?? null;
            if (is_int($singletonGlobalIndex)) {
                $compactInsertionOffset = 0;
                foreach ($carrierCoverage['globalIndexes'] as $carrierGlobalIndex) {
                    if ($carrierGlobalIndex >= $singletonGlobalIndex) {
                        break;
                    }
                    $carrierLocalOffset = array_search(
                        $carrierGlobalIndex,
                        $carrierCoverage['globalIndexes'],
                        true
                    );
                    $carrierLocalIndex = is_int($carrierLocalOffset)
                        ? ($carrierCoverage['localIndexes'][$carrierLocalOffset] ?? null)
                        : null;
                    if (is_int($carrierLocalIndex) && isset($sourceItems[$carrierLocalIndex])) {
                        $compactInsertionOffset += $this->length(
                            $this->pdfSourceOccurrenceComparableText(
                                (string) ($sourceItems[$carrierLocalIndex]['text'] ?? '')
                            )
                        );
                    }
                }
                $positionedInsertion = $this->pdfTextWithCompactInsertion(
                    (string) ($carrier['text'] ?? ''),
                    $compactInsertionOffset,
                    (string) ($singleton['text'] ?? '')
                );
                if ($this->pdfSourceOccurrenceComparableText($positionedInsertion)
                    === $unionCoverage['projection']) {
                    $composedText = $positionedInsertion;
                }
            }
        }
        $candidate = array_replace($carrier, [
            'text' => $composedText,
            'sourceOrderStart' => min(
                (int) ($left['sourceOrderStart'] ?? 0),
                (int) ($right['sourceOrderStart'] ?? 0)
            ),
            'sourceOrderEnd' => max(
                (int) ($left['sourceOrderEnd'] ?? 0),
                (int) ($right['sourceOrderEnd'] ?? 0)
            ),
            'startsWithWhitespace' => false,
            'endsWithWhitespace' => false,
            'hasWordBoundaryBefore' => false,
            'wordBoundaryBefore' => false,
            'wordBoundarySource' => null,
            'sourceVerifiedBoundarySeparators' => [],
            'sourceCompactBoundaryOffsets' => [],
            'sourcePdfExactSourceRanges' => $unionCoverage['ranges'],
            'sourceCompositeComplementaryExactRanges' => true,
        ]);
        unset(
            $candidate['sourcePdfExactSourceIndex'],
            $candidate['sourcePdfExactSourceStart'],
            $candidate['sourcePdfExactSourceEnd'],
            $candidate['codeGeometryBoundaryOffsets']
        );

        $joinedSourceItem = $this->sourcePdfJoinedFragmentLineItem(
            $sourceItems,
            $unionCoverage['localIndexes'],
            $candidate
        );
        if ($joinedSourceItem === null) {
            return null;
        }
        // The source sequence owns the characters, while the already-proven
        // positioned carrier can still supply occurrence-local word gaps
        // such as the separator before a parenthetical language label.
        $candidate['text'] = $joinedSourceItem['text'];

        return $this->sourcePdfExactRangeIndexesMatchingPositionedLine(
            $sourceItems,
            [],
            $candidate
        ) === [] ? null : $candidate;
    }

    private function pdfTextWithCompactInsertion(string $text, int $offset, string $insertion): string
    {
        $characters = preg_split('//u', $text, -1, PREG_SPLIT_NO_EMPTY);
        if (!is_array($characters) || $offset < 0 || trim($insertion) === '') {
            return $text;
        }
        $result = '';
        $compactOffset = 0;
        $inserted = false;
        foreach ($characters as $character) {
            if (!$inserted
                && preg_match('/^\s$/u', $character) !== 1
                && $compactOffset === $offset) {
                $result .= trim($insertion);
                $inserted = true;
            }
            $result .= $character;
            if (preg_match('/^\s$/u', $character) !== 1) {
                $compactOffset++;
            }
        }
        if (!$inserted && $compactOffset === $offset) {
            $result .= trim($insertion);
        }

        return $result;
    }

    /**
     * A one- or two-character string is too ambiguous to match globally: a
     * repeated column label could otherwise be assigned to the wrong visual
     * copy. It is nevertheless an exact, recoverable record when the visual
     * run is one source-order atom and either has one source candidate on the
     * page or a directly adjacent matched source-order anchor. This is about
     * provenance and position, never the characters in the label.
     *
     * @param list<array{page: int, stream: int, text: string}> $sourceItems
     * @param list<int> $sourceIndexes
     * @param array<int, true> $matchedSourceIndexes
     * @param array<int, array<string, mixed>> $matchedItemsBySourceIndex
     * @param array<string, mixed> $positionedItem
     */
    private function sourcePdfShortExactSourceIndexMatchingPositionedLine(
        array $sourceItems,
        array $sourceIndexes,
        array $matchedSourceIndexes,
        array $matchedItemsBySourceIndex,
        array $positionedItem
    ): ?int {
        if (!isset($positionedItem['sourceOrderStart'], $positionedItem['sourceOrderEnd'])
            || (int) $positionedItem['sourceOrderStart'] !== (int) $positionedItem['sourceOrderEnd']) {
            return null;
        }

        $candidates = [];
        foreach ($sourceIndexes as $sourceIndex) {
            $sourceItem = $sourceItems[$sourceIndex] ?? null;
            if (!is_array($sourceItem)
                || isset($matchedSourceIndexes[$sourceIndex])
                || ($sourceItem['page'] ?? null) !== ($positionedItem['page'] ?? null)) {
                continue;
            }
            $candidates[] = $sourceIndex;
        }
        if (count($candidates) === 1) {
            return $candidates[0];
        }
        if ($candidates === []) {
            return null;
        }

        $positionedStart = (int) $positionedItem['sourceOrderStart'];
        $anchored = [];
        foreach ($candidates as $sourceIndex) {
            $sourceItem = $sourceItems[$sourceIndex] ?? null;
            if (!is_array($sourceItem)) {
                continue;
            }
            foreach ([$sourceIndex - 1, $sourceIndex + 1] as $neighborIndex) {
                $neighborSource = $sourceItems[$neighborIndex] ?? null;
                $neighborItem = $matchedItemsBySourceIndex[$neighborIndex] ?? null;
                if (!is_array($neighborSource)
                    || !is_array($neighborItem)
                    || ($neighborSource['page'] ?? null) !== ($sourceItem['page'] ?? null)
                    || ($neighborSource['stream'] ?? null) !== ($sourceItem['stream'] ?? null)
                    || !isset($neighborItem['sourceOrderStart'], $neighborItem['sourceOrderEnd'])) {
                    continue;
                }

                $isPreviousAnchor = $neighborIndex < $sourceIndex
                    && (int) $neighborItem['sourceOrderEnd'] < $positionedStart;
                $isFollowingAnchor = $neighborIndex > $sourceIndex
                    && (int) $neighborItem['sourceOrderStart'] > $positionedStart;
                if ($isPreviousAnchor || $isFollowingAnchor) {
                    $anchored[] = $sourceIndex;
                    break;
                }
            }
        }

        return count($anchored) === 1 ? $anchored[0] : null;
    }

    /**
     * A footnote marker can be emitted as its own source-text item while the
     * positioned layer keeps it immediately before the surrounding prose on a
     * shared baseline. Match the prose suffix only when both layers expose the
     * same adjacent marker. This is source/geometry provenance, not a guess
     * based on the words in the sentence.
     *
     * @param list<array{page: int, stream: int, text: string}> $sourceItems
     * @param array<int, true> $matchedSourceIndexes
     * @param array<string, mixed> $positionedItem
     */
    private function sourcePdfFootnotePrefixedSourceIndexMatchingPositionedLine(
        array $sourceItems,
        array $matchedSourceIndexes,
        array $positionedItem
    ): ?int {
        $positionedText = trim((string) ($positionedItem['text'] ?? ''));
        if (preg_match('/^([0-9]{1,3})\s+(.+)$/u', $positionedText, $matches) !== 1) {
            return null;
        }

        $marker = $this->pdfComparableLineText($matches[1]);
        $suffix = $this->pdfComparableLineText($matches[2]);
        if ($marker === '' || $suffix === '' || $this->length($suffix) < 4) {
            return null;
        }

        foreach ($sourceItems as $index => $sourceItem) {
            if (isset($matchedSourceIndexes[$index])
                || $this->pdfComparableLineText($sourceItem['text']) !== $suffix
                || !isset($sourceItems[$index - 1])) {
                continue;
            }

            $markerItem = $sourceItems[$index - 1];
            if ($this->pdfComparableLineText($markerItem['text']) !== $marker
                || !$this->sourcePdfItemsShareStream($markerItem, $sourceItem)) {
                continue;
            }

            return $index;
        }

        return null;
    }

    /**
     * A text stream can split one visual line at an inline style boundary.
     * The individual positioned fragments then cannot match the source line
     * that contains both fragments, so its fallback geometry is borrowed from
     * a neighbor and a genuine paragraph indent is lost. Recombine only a
     * locally contiguous, same-baseline sequence whose combined text exactly
     * matches a source line; this is layout and provenance evidence rather
     * than a guess based on vocabulary.
     *
     * @param list<array<string, mixed>> $positionedItems
     * @param list<array{page: int, stream: int, text: string}> $sourceItems
     * @param array<string, list<int>> $sourceIndexesByKey
     * @param array<string, list<int>> $sourceIndexesByComparablePrefix
     * @param array<string, list<int>> $sourceIndexesByCompactPrefix
     * @return list<array<string, mixed>>
     */
    private function combineAdjacentPositionedPdfFragmentsMatchingSourceLines(
        array $positionedItems,
        array $sourceItems,
        array $sourceIndexesByKey,
        array $sourceIndexesByComparablePrefix,
        array $sourceIndexesByCompactPrefix
    ): array {
        $combined = [];
        $count = count($positionedItems);
        for ($index = 0; $index < $count; $index++) {
            $item = $positionedItems[$index];
            if (!$this->pdfLayoutHasGeometry($item)
                || ($item['code'] ?? false) === true
                || !isset($item['sourceOrderStart'], $item['sourceOrderEnd'])) {
                $combined[] = $item;
                continue;
            }

            $candidate = $item;
            $matchedEnd = null;
            for ($end = $index + 1; $end < min($count, $index + 4); $end++) {
                $next = $positionedItems[$end];
                if (!$this->positionedPdfFragmentsCanComposeSourceLine($candidate, $next)) {
                    break;
                }

                $candidate = $this->composePositionedPdfSourceLineFragments($candidate, $next);
                if ($candidate === null) {
                    break;
                }
                $key = $this->pdfComparableLineText((string) ($candidate['text'] ?? ''));
                $hasDirectSourceLine = $this->length($key) >= 12 && isset($sourceIndexesByKey[$key]);
                $hasSourceFragmentSequence = !$hasDirectSourceLine
                    && $this->sourcePdfFragmentIndexesMatchingPositionedLine(
                        $sourceItems,
                        [],
                    $key,
                    $sourceIndexesByComparablePrefix,
                    $sourceIndexesByCompactPrefix,
                    $candidate
                ) !== [];
                if ($hasDirectSourceLine || $hasSourceFragmentSequence) {
                    $matchedEnd = $end;
                    break;
                }
            }

            if ($matchedEnd === null) {
                $combined[] = $item;
                continue;
            }

            $combined[] = $candidate;
            $index = $matchedEnd;
        }

        return $combined;
    }

    /**
     * Styled run boundaries normally leave a short, terminal lead such as a
     * label or inline subhead before the next fragment resumes body text. Do
     * not compose arbitrary long same-baseline fragments: figures and tables
     * use that geometry too, and their source order is not prose order.
     *
     * @param array<string, mixed> $item
     */
    private function positionedPdfFragmentLooksLikeShortTerminalLead(array $item): bool
    {
        $text = trim((string) ($item['text'] ?? ''));
        $wordCount = count($this->pdfLineWordTokens($text));

        return $wordCount >= 2
            && $wordCount <= 6
            && $this->length($text) <= 72
            && !$this->lineHasPdfListBlockEvidence($text)
            && preg_match('/[.!?:]\s*$/u', $text) === 1;
    }

    /**
     * Bibliographic entries often split publisher or product names across
     * styled fragments on one baseline. The bracketed numeric marker is a
     * structural reference signal, and an exact source-line match still gates
     * the composition, so this does not broaden ordinary prose joining.
     *
     * @param array<string, mixed> $item
     */
    private function positionedPdfFragmentLooksLikeReferenceLead(array $item): bool
    {
        $text = trim((string) ($item['text'] ?? ''));

        return $this->length($text) <= 72
            && count($this->pdfLineWordTokens($text)) <= 6
            && preg_match('/^\[\d{1,3}\]\s+[^\s]+/u', $text) === 1;
    }

    /**
     * @param array<string, mixed> $left
     * @param array<string, mixed> $right
     */
    private function positionedPdfFragmentsCanComposeSourceLine(array $left, array $right): bool
    {
        if (!$this->pdfLayoutHasGeometry($left)
            || !$this->pdfLayoutHasGeometry($right)
            || ($left['code'] ?? false) === true
            || ($right['code'] ?? false) === true
            || !isset($left['sourceOrderEnd'], $right['sourceOrderStart'])
            || (int) ($left['page'] ?? 0) !== (int) ($right['page'] ?? 0)) {
            return false;
        }
        if ($this->positionedPdfFragmentSeparator($left, $right) === null) {
            return false;
        }

        $leftOrderEnd = (int) $left['sourceOrderEnd'];
        $rightOrderStart = (int) $right['sourceOrderStart'];
        if ($rightOrderStart <= $leftOrderEnd || $rightOrderStart - $leftOrderEnd > 12) {
            return false;
        }

        $fontSize = max(1.0, (float) $left['fontSize'], (float) $right['fontSize']);
        if (abs((float) $left['fontSize'] - (float) $right['fontSize']) > max(1.5, $fontSize * 0.25)) {
            return false;
        }

        $leftCenter = ((float) $left['y1'] + (float) $left['y2']) / 2.0;
        $rightCenter = ((float) $right['y1'] + (float) $right['y2']) / 2.0;
        if (abs($leftCenter - $rightCenter) > max(2.5, $fontSize * 0.35)
            || (float) $right['x1'] < (float) $left['x1'] - max(2.0, $fontSize * 0.25)) {
            return false;
        }

        $gap = (float) $right['x1'] - (float) $left['x2'];
        $compactInlineContinuation = $this->positionedPdfFragmentIsCompactInlineContinuation($right);

        return $gap >= -max(
            18.0,
            $fontSize * ($compactInlineContinuation ? 6.0 : 3.0)
        )
            && $gap <= max(36.0, $fontSize * 4.0);
    }

    /**
     * Font metrics for a superscript or short inline token can overlap the
     * preceding run's bounding box even though both runs share a baseline and
     * source order. The caller still requires an exact source match before
     * composing the pair, so this only broadens the geometric tolerance for
     * a compact continuation rather than arbitrary overlapping labels.
     *
     * @param array<string, mixed> $item
     */
    private function positionedPdfFragmentIsCompactInlineContinuation(array $item): bool
    {
        $text = trim((string) ($item['text'] ?? ''));
        $compact = $this->pdfComparableLineText($text);
        $tokens = $this->pdfLineWordTokens($text);

        return $compact !== ''
            && $this->length($compact) <= 8
            && (count($tokens) <= 1
                || (count($tokens) <= 2
                    && (preg_match('/[\p{N}\p{P}]/u', $text) === 1
                        || preg_match('/^\p{Lu}{1,3}\b/u', $tokens[0] ?? '') === 1)));
    }

    /**
     * @param array<string, mixed> $left
     * @param array<string, mixed> $right
     */
    private function positionedPdfFragmentSeparator(array $left, array $right): ?string
    {
        $leftText = rtrim((string) ($left['text'] ?? ''));
        $rightText = ltrim((string) ($right['text'] ?? ''));
        if ($leftText === '' || $rightText === '') {
            return '';
        }
        if (($left['endsWithWhitespace'] ?? false) === true
            || ($right['startsWithWhitespace'] ?? false) === true) {
            return ' ';
        }
        if (($right['hasWordBoundaryBefore'] ?? false) !== true) {
            return null;
        }

        $leftEnd = (float) ($left['textX2'] ?? $left['x2'] ?? 0.0);
        $rightStart = (float) ($right['textX1'] ?? $right['x1'] ?? 0.0);

        return $this->positionedBoundarySeparator(
            $rightStart - $leftEnd,
            max(1.0, (float) ($left['fontSize'] ?? 0.0), (float) ($right['fontSize'] ?? 0.0)),
            (bool) ($left['endsWithWhitespace'] ?? false),
            (bool) ($right['startsWithWhitespace'] ?? false),
            true,
            (bool) ($right['wordBoundaryBefore'] ?? false),
            is_string($right['wordBoundarySource'] ?? null)
                ? $right['wordBoundarySource']
                : null
        );
    }

    /**
     * @param array<string, mixed> $left
     * @param array<string, mixed> $right
     * @return array<string, mixed>|null
     */
    private function composePositionedPdfSourceLineFragments(array $left, array $right): ?array
    {
        $separator = $this->positionedPdfFragmentSeparator($left, $right);
        if ($separator === null) {
            return null;
        }

        $leftTextX2 = (float) ($left['textX2'] ?? $left['x2'] ?? 0.0);
        $rightTextX1 = (float) ($right['textX1'] ?? $right['x1'] ?? 0.0);
        $fontSize = max(1.0, (float) ($left['fontSize'] ?? 0.0), (float) ($right['fontSize'] ?? 0.0));
        $sourceVerifiedBoundarySeparators = $this->positionedJoinedSourceVerifiedBoundarySeparators(
            $left,
            $right,
            $rightTextX1 - $leftTextX2,
            $fontSize,
            (bool) ($left['endsWithWhitespace'] ?? false),
            (bool) ($right['startsWithWhitespace'] ?? false),
            (bool) ($right['hasWordBoundaryBefore'] ?? false),
            (bool) ($right['wordBoundaryBefore'] ?? false),
            is_string($right['wordBoundarySource'] ?? null)
                ? $right['wordBoundarySource']
                : null
        );
        $sourceCompactBoundaryOffsets = $this->positionedJoinedSourceCompactBoundaryOffsets(
            $left,
            $right,
            $rightTextX1 - $leftTextX2,
            $fontSize,
            (bool) ($left['endsWithWhitespace'] ?? false),
            (bool) ($right['startsWithWhitespace'] ?? false),
            (bool) ($right['hasWordBoundaryBefore'] ?? false),
            (bool) ($right['wordBoundaryBefore'] ?? false),
            is_string($right['wordBoundarySource'] ?? null)
                ? $right['wordBoundarySource']
                : null
        );

        $composed = array_replace($left, [
            'text' => rtrim((string) ($left['text'] ?? '')) . $separator . ltrim((string) ($right['text'] ?? '')),
            'x1' => min((float) $left['x1'], (float) $right['x1']),
            'y1' => min((float) $left['y1'], (float) $right['y1']),
            'x2' => max((float) $left['x2'], (float) $right['x2']),
            'y2' => max((float) $left['y2'], (float) $right['y2']),
            'textX1' => min((float) ($left['textX1'] ?? $left['x1']), (float) ($right['textX1'] ?? $right['x1'])),
            'textY1' => min((float) ($left['textY1'] ?? $left['y1']), (float) ($right['textY1'] ?? $right['y1'])),
            'textX2' => max((float) ($left['textX2'] ?? $left['x2']), (float) ($right['textX2'] ?? $right['x2'])),
            'textY2' => max((float) ($left['textY2'] ?? $left['y2']), (float) ($right['textY2'] ?? $right['y2'])),
            'fontSize' => $fontSize,
            'sourceOrderStart' => min((int) $left['sourceOrderStart'], (int) $right['sourceOrderStart']),
            'sourceOrderEnd' => max((int) $left['sourceOrderEnd'], (int) $right['sourceOrderEnd']),
            'startsWithWhitespace' => (bool) ($left['startsWithWhitespace'] ?? false),
            'endsWithWhitespace' => (bool) ($right['endsWithWhitespace'] ?? false),
            'hasWordBoundaryBefore' => (bool) ($left['hasWordBoundaryBefore'] ?? false),
            'wordBoundaryBefore' => (bool) ($left['wordBoundaryBefore'] ?? false),
            'wordBoundarySource' => $left['wordBoundarySource'] ?? null,
            'sourceVerifiedBoundarySeparators' => $sourceVerifiedBoundarySeparators,
            'sourceCompactBoundaryOffsets' => $sourceCompactBoundaryOffsets,
            'sourceCompositePositionedFragments' => true,
        ]);
        $exactSourceRanges = $this->pdfPositionedExactSourceRangesForItems([$left, $right]);
        if ($exactSourceRanges !== []) {
            $composed['sourcePdfExactSourceRanges'] = $exactSourceRanges;
        }

        return $composed;
    }

    /**
     * The text layer can split one painted visual line at font, size, or
     * glyph-run boundaries. Match only a short, contiguous source sequence
     * whose normalized text exactly covers one positioned visual line. This
     * recovers the source layer's whitespace without using vocabulary or
     * document-specific rules.
     *
     * @param list<array{page: int, stream: int, text: string}> $sourceItems
     * @param array<int, true> $matchedSourceIndexes
     * @param array<string, list<int>> $sourceIndexesByComparablePrefix
     * @return list<int>
     */
    private function sourcePdfFragmentIndexesMatchingPositionedLine(
        array $sourceItems,
        array $matchedSourceIndexes,
        string $positionedKey,
        array $sourceIndexesByComparablePrefix,
        array $sourceIndexesByCompactPrefix = [],
        ?array $positionedItem = null
    ): array {
        $shortInlineContinuation = $this->length($positionedKey) < 16
            && preg_match('/^\d{1,3}\p{Ll}/u', $positionedKey) === 1;
        $locallyBoundShortSequence = $this->positionedPdfItemHasLocallyBoundShortSourceSequence(
            $positionedItem
        );
        $formulaProcessor = new PdfFormulaSemanticProcessor();
        $formulaSequence = $formulaProcessor->positionedItemLooksLikeFormula($positionedItem);
        if ($this->length($positionedKey) < 16
            && !$shortInlineContinuation
            && !$locallyBoundShortSequence
            && !$formulaSequence) {
            return [];
        }

        $prefix = substr($positionedKey, 0, 8);
        $startIndexes = ($shortInlineContinuation || $locallyBoundShortSequence || $formulaSequence)
            ? array_keys($sourceItems)
            : ($sourceIndexesByComparablePrefix[$prefix] ?? []);
        if ($startIndexes === [] && !$shortInlineContinuation && $this->length($positionedKey) >= 24) {
            $startIndexes = $sourceIndexesByCompactPrefix[substr($positionedKey, 0, 1)] ?? [];
        }
        foreach ($startIndexes as $startIndex) {
            if (isset($matchedSourceIndexes[$startIndex])) {
                continue;
            }

            $sourceStream = $sourceItems[$startIndex]['stream'];
            $joinedKey = '';
            $indexes = [];
            for ($index = $startIndex; $index < count($sourceItems) && $index < $startIndex + 24; $index++) {
                if (isset($matchedSourceIndexes[$index])
                    || $sourceItems[$index]['stream'] !== $sourceStream
                    || ($index > $startIndex && preg_match('/[.!?]\s*$/u', $sourceItems[$index - 1]['text']) === 1)) {
                    break;
                }

                $fragmentKey = $this->pdfComparableLineText($sourceItems[$index]['text']);
                if ($fragmentKey === '') {
                    if ($indexes !== []
                        && $this->sourcePdfFragmentIsInlineIgnorableGlyph($sourceItems[$index]['text'])) {
                        $indexes[] = $index;
                        continue;
                    }
                    break;
                }
                if (!str_starts_with($positionedKey, $joinedKey . $fragmentKey)) {
                    break;
                }

                $joinedKey .= $fragmentKey;
                $indexes[] = $index;
                if (count($indexes) >= 2 && $joinedKey === $positionedKey) {
                    if ((!$shortInlineContinuation
                            && $this->sourcePdfLongFragmentSequenceMatchesPositionedLine($sourceItems, $indexes, $positionedKey))
                        || $this->sourcePdfShortFragmentSequenceMatchesPositionedLine($sourceItems, $indexes, $positionedKey)
                        || ($locallyBoundShortSequence
                            && $this->sourcePdfLocallyBoundShortFragmentSequenceMatchesPositionedLine(
                                $sourceItems,
                                $indexes,
                                $positionedItem
                            ))
                        || ($formulaSequence
                            && $formulaProcessor->sourceFragmentsMatchPositionedFormula(
                                $sourceItems,
                                $indexes,
                                $positionedItem
                            ))) {
                        $indexes = $this->sourcePdfFragmentIndexesWithLeadingListMarker(
                            $sourceItems,
                            $indexes,
                            $matchedSourceIndexes
                        );

                        return $this->sourcePdfFragmentIndexesWithTrailingPunctuation(
                            $sourceItems,
                            $indexes,
                            $matchedSourceIndexes
                        );
                    }
                }
            }
        }

        return [];
    }

    /**
     * A visual item that covers a small, consecutive source-order range can
     * prove a compact source sequence even when its normalized text is too
     * short for the ordinary global fragment index. Limit this to four
     * adjacent atoms; larger sequences are handled by the established long
     * fragment path and are too broad to treat as a local styled split.
     *
     * @param array<string, mixed>|null $positionedItem
     */
    private function positionedPdfItemHasLocallyBoundShortSourceSequence(?array $positionedItem): bool
    {
        if (!is_array($positionedItem)
            || !isset($positionedItem['sourceOrderStart'], $positionedItem['sourceOrderEnd'])) {
            return false;
        }

        $span = (int) $positionedItem['sourceOrderEnd'] - (int) $positionedItem['sourceOrderStart'] + 1;

        return $span >= 2 && $span <= 4;
    }

    /**
     * A styled prefix can be emitted as one or two source atoms while the
     * following atom holds the rest of the visual line. The exact compact
     * equality has already been checked by the caller. Require the visual
     * source-order span to contain exactly this short contiguous sequence and
     * at least one compact atom, so ordinary nearby prose lines never enter
     * this recovery path.
     *
     * @param list<array{page: int, stream: int, text: string}> $sourceItems
     * @param list<int> $indexes
     * @param array<string, mixed>|null $positionedItem
     */
    private function sourcePdfLocallyBoundShortFragmentSequenceMatchesPositionedLine(
        array $sourceItems,
        array $indexes,
        ?array $positionedItem
    ): bool {
        if (!$this->positionedPdfItemHasLocallyBoundShortSourceSequence($positionedItem)
            || count($indexes) < 2
            || count($indexes) > 4
            || (int) $positionedItem['sourceOrderEnd'] - (int) $positionedItem['sourceOrderStart'] + 1 !== count($indexes)) {
            return false;
        }

        $hasCompactAtom = false;
        foreach ($indexes as $index) {
            $compact = $this->pdfComparableLineText((string) ($sourceItems[$index]['text'] ?? ''));
            if ($compact === '') {
                return false;
            }
            $hasCompactAtom = $hasCompactAtom || $this->length($compact) <= 2;
        }

        return $hasCompactAtom;
    }

    private function sourcePdfFragmentIsInlineIgnorableGlyph(string $text): bool
    {
        $text = trim($text);

        return $text !== ''
            && $this->length($text) <= 3
            // Fonts often isolate contribution marks, math accents, and
            // other inline symbols into their own text-showing operators.
            // This method only keeps them inside a longer sequence whose
            // complete source text must still match one positioned line.
            && preg_match('/^[\p{M}\p{S}]+$/u', $text) === 1;
    }

    /**
     * A small superscript can be emitted as its own source record while the
     * following lower-case words share its visual baseline. Accept that short
     * sequence only when it is exactly represented by the positioned line.
     * This keeps ordinary short labels and list markers out of source-line
     * reconciliation.
     *
     * @param list<array{page: int, stream: int, text: string}> $sourceItems
     * @param list<int> $indexes
     */
    private function sourcePdfShortFragmentSequenceMatchesPositionedLine(
        array $sourceItems,
        array $indexes,
        string $positionedKey
    ): bool {
        if (count($indexes) !== 2
            || preg_match('/^\d{1,3}\p{Ll}/u', $positionedKey) !== 1) {
            return false;
        }

        $first = trim($sourceItems[$indexes[0]]['text']);
        $second = ltrim($sourceItems[$indexes[1]]['text']);

        return preg_match('/^\d{1,3}$/u', $first) === 1
            && preg_match('/^\p{Ll}/u', $second) === 1;
    }

    /**
     * A source text layer may split inline notation into individual glyph runs
     * while the positioned layer exposes the complete visual line. Extend the
     * ordinary short-sequence match only when every extra interior record is a
     * compact inline fragment and both layers agree exactly after normalization.
     *
     * @param list<array{page: int, stream: int, text: string}> $sourceItems
     * @param list<int> $indexes
     */
    private function sourcePdfLongFragmentSequenceMatchesPositionedLine(
        array $sourceItems,
        array $indexes,
        string $positionedKey
    ): bool {
        if (count($indexes) <= 4 || $this->length($positionedKey) < 24) {
            return count($indexes) <= 4;
        }

        $first = $this->pdfComparableLineText($sourceItems[$indexes[0]]['text']);
        $last = $this->pdfComparableLineText($sourceItems[$indexes[array_key_last($indexes)]]['text']);
        if (max($this->length($first), $this->length($last)) < 8) {
            $hasSubstantialFragment = false;
            foreach ($indexes as $index) {
                if ($this->length($this->pdfComparableLineText($sourceItems[$index]['text'])) >= 12) {
                    $hasSubstantialFragment = true;
                    break;
                }
            }
            if (!$hasSubstantialFragment) {
                return false;
            }
        }

        $compactInteriorFragments = 0;
        $substantialInteriorFragments = 0;
        foreach (array_slice($indexes, 1, -1) as $index) {
            $sourceText = $sourceItems[$index]['text'];
            $fragment = $this->pdfComparableLineText($sourceText);
            if ($fragment === '') {
                if ($this->sourcePdfFragmentIsInlineIgnorableGlyph($sourceText)) {
                    $compactInteriorFragments++;
                    continue;
                }
                return false;
            }
            if ($this->length($fragment) <= 3) {
                $compactInteriorFragments++;
                continue;
            }
            $substantialInteriorFragments++;
        }

        // A font switch can split a word into a compact accent or superscript
        // plus a normal text run. The positioned visual line gives an exact
        // whole-line match, and the compact interior token proves this is an
        // inline split rather than a sequence of ordinary source lines.
        return $compactInteriorFragments > 0 && $substantialInteriorFragments <= 2;
    }

    /**
     * A bullet can be emitted as a standalone source record immediately
     * before a formula-split list item. Keep it with the verified item so the
     * downstream block parser can preserve the list structure.
     *
     * @param list<array{page: int, stream: int, text: string}> $sourceItems
     * @param list<int> $indexes
     * @param array<int, true> $matchedSourceIndexes
     * @return list<int>
     */
    private function sourcePdfFragmentIndexesWithLeadingListMarker(
        array $sourceItems,
        array $indexes,
        array $matchedSourceIndexes
    ): array {
        $firstIndex = $indexes[0];
        $previousIndex = $firstIndex - 1;
        if (!isset($sourceItems[$previousIndex])
            || isset($matchedSourceIndexes[$previousIndex])
            || $sourceItems[$previousIndex]['page'] !== $sourceItems[$firstIndex]['page']
            || $sourceItems[$previousIndex]['stream'] !== $sourceItems[$firstIndex]['stream']
            || !$this->lineIsStandalonePdfListMarker($sourceItems[$previousIndex]['text'])
            || $this->sourcePdfHasExactInlineStandaloneMarkerEvidence($sourceItems[$previousIndex])
            || $this->sourcePdfInlineStandaloneMarkerProofAt($sourceItems, $previousIndex) !== null) {
            return $indexes;
        }

        array_unshift($indexes, $previousIndex);

        return $indexes;
    }

    /**
     * Some text streams emit terminal punctuation as its own record. It has
     * no comparable key, but it is structurally part of the matched source
     * line and must not later surface as an orphaned positioned fragment.
     *
     * @param list<array{page: int, stream: int, text: string}> $sourceItems
     * @param list<int> $indexes
     * @param array<int, true> $matchedSourceIndexes
     * @return list<int>
     */
    private function sourcePdfFragmentIndexesWithTrailingPunctuation(
        array $sourceItems,
        array $indexes,
        array $matchedSourceIndexes
    ): array {
        $lastIndex = $indexes[array_key_last($indexes)];
        $last = $sourceItems[$lastIndex];
        for ($index = $lastIndex + 1; isset($sourceItems[$index]) && $index <= $lastIndex + 2; $index++) {
            if (isset($matchedSourceIndexes[$index])
                || $sourceItems[$index]['page'] !== $last['page']
                || $sourceItems[$index]['stream'] !== $last['stream']) {
                break;
            }
            $text = trim($sourceItems[$index]['text']);
            if (preg_match('/^[,.;:!?\)\]\}]+$/u', $text) !== 1) {
                break;
            }
            $indexes[] = $index;
        }

        return $indexes;
    }

    /**
     * A positioned body line can end immediately before a run of inline
     * notation. Recover the complete source sequence only when that sequence
     * starts with the positioned text, ends at a source sentence boundary, and
     * has the same compact-fragment evidence as an exact long match.
     *
     * @param list<array{page: int, stream: int, text: string}> $sourceItems
     * @param array<int, true> $matchedSourceIndexes
     * @param array<string, list<int>> $sourceIndexesByComparablePrefix
     * @return list<int>
     */
    private function sourcePdfFragmentIndexesExtendingPositionedLine(
        array $sourceItems,
        array $matchedSourceIndexes,
        string $positionedKey,
        array $sourceIndexesByComparablePrefix
    ): array {
        if ($this->length($positionedKey) < 24) {
            return [];
        }

        $startIndexes = $sourceIndexesByComparablePrefix[substr($positionedKey, 0, 8)] ?? [];
        foreach ($startIndexes as $startIndex) {
            if (isset($matchedSourceIndexes[$startIndex])) {
                continue;
            }

            $sourceStream = $sourceItems[$startIndex]['stream'];
            $joinedKey = '';
            $indexes = [];
            $extendsPositionedText = false;
            for ($index = $startIndex; $index < count($sourceItems) && $index < $startIndex + 24; $index++) {
                if (isset($matchedSourceIndexes[$index])
                    || $sourceItems[$index]['stream'] !== $sourceStream
                    || ($index > $startIndex && preg_match('/[.!?]\s*$/u', $sourceItems[$index - 1]['text']) === 1)) {
                    break;
                }

                $fragmentKey = $this->pdfComparableLineText($sourceItems[$index]['text']);
                if ($fragmentKey === '') {
                    break;
                }
                $candidateKey = $joinedKey . $fragmentKey;
                if (!str_starts_with($candidateKey, $positionedKey)
                    && !str_starts_with($positionedKey, $candidateKey)) {
                    break;
                }

                $joinedKey = $candidateKey;
                $indexes[] = $index;
                $extendsPositionedText = $extendsPositionedText
                    || ($joinedKey !== $positionedKey && str_starts_with($joinedKey, $positionedKey));
                if (!$extendsPositionedText
                    || preg_match('/[.!?]\s*$/u', $sourceItems[$index]['text']) !== 1) {
                    continue;
                }

                if (count($indexes) > 4
                    && $this->sourcePdfLongFragmentSequenceMatchesPositionedLine(
                        $sourceItems,
                        $indexes,
                        $joinedKey
                    )) {
                    return $indexes;
                }
                break;
            }
        }

        return [];
    }

    /**
     * The text runs for one visual line can be emitted out of visual-list
     * order. A source-order-adjacent sibling on the same baseline proves that
     * a prefix line really continues through inline notation.
     *
     * @param list<array<string, mixed>> $positionedItems
     * @return list<int>
     */
    private function positionedPdfInlineContinuationSiblingIndexes(array $positionedItems, int $positionedIndex): array
    {
        $item = $positionedItems[$positionedIndex] ?? null;
        if (!is_array($item)
            || !$this->pdfLayoutHasGeometry($item)
            || !isset($item['sourceOrderStart'], $item['sourceOrderEnd'])) {
            return [];
        }

        $fontSize = max(1.0, (float) $item['fontSize']);
        $sourceOrderEnd = (int) $item['sourceOrderEnd'];
        $minimumExtension = (float) $item['x2'] + max(8.0, $fontSize);
        $maximumX2 = (float) $item['x2'];
        $hasCompactInlineSibling = false;
        $siblings = [];
        foreach ($positionedItems as $index => $candidate) {
            if ($index === $positionedIndex
                || !$this->pdfLayoutHasGeometry($candidate)
                || !isset($candidate['sourceOrderStart'], $candidate['sourceOrderEnd'])
                || ($candidate['page'] ?? null) !== ($item['page'] ?? null)
                || (float) $candidate['x1'] < (float) $item['x1'] - max(4.0, $fontSize * 0.5)
                || abs(((float) $candidate['y1'] + (float) $candidate['y2']) / 2.0 - ((float) $item['y1'] + (float) $item['y2']) / 2.0) > max(2.5, $fontSize * 0.35)) {
                continue;
            }

            // Source-order adjacency and a shared baseline are not enough by
            // themselves: a nearby map label can otherwise absorb the first
            // body line on that row. Keep the same bounded inline gap used
            // when composing source-verified positioned fragments.
            $candidateFontSize = max($fontSize, (float) ($candidate['fontSize'] ?? 0.0));
            if ((float) $candidate['x1'] - $maximumX2 > max(36.0, $candidateFontSize * 4.0)) {
                continue;
            }

            $candidateStart = (int) $candidate['sourceOrderStart'];
            $candidateEnd = (int) $candidate['sourceOrderEnd'];
            if ($candidateEnd <= (int) $item['sourceOrderEnd']
                || $candidateStart > $sourceOrderEnd + 48) {
                continue;
            }

            $siblings[] = $index;
            $sourceOrderEnd = max($sourceOrderEnd, $candidateEnd);
            $maximumX2 = max($maximumX2, (float) $candidate['x2']);
            $hasCompactInlineSibling = $hasCompactInlineSibling
                || $this->positionedPdfFragmentIsCompactInlineContinuation($candidate);
        }

        return $sourceOrderEnd > (int) $item['sourceOrderEnd']
            && ($maximumX2 >= $minimumExtension || $hasCompactInlineSibling)
            ? $siblings
            : [];
    }

    /**
     * @param array<string, mixed> $item
     * @param list<array<string, mixed>> $positionedItems
     * @param list<int> $siblingIndexes
     */
    private function positionedPdfInlineContinuationText(array $item, array $positionedItems, array $siblingIndexes): ?string
    {
        $fragments = [$item];
        foreach ($siblingIndexes as $index) {
            $sibling = $positionedItems[$index] ?? null;
            if (is_array($sibling)) {
                $fragments[] = $sibling;
            }
        }
        usort($fragments, static function (array $left, array $right): int {
            return ((float) $left['x1'] <=> (float) $right['x1'])
                ?: ((int) ($left['sourceOrderStart'] ?? 0) <=> (int) ($right['sourceOrderStart'] ?? 0));
        });

        $text = '';
        $previous = null;
        foreach ($fragments as $fragment) {
            $fragmentText = trim((string) ($fragment['text'] ?? ''));
            if ($fragmentText === '') {
                continue;
            }
            if ($previous !== null) {
                $separator = $this->positionedPdfFragmentSeparator($previous, $fragment);
                if ($separator === null) {
                    return null;
                }
                $text = rtrim($text) . $separator;
            }
            $text .= ltrim($fragmentText);
            $previous = $fragment;
        }

        return $text;
    }

    /**
     * @param array<string, mixed> $item
     * @param list<array<string, mixed>> $positionedItems
     * @param list<int> $siblingIndexes
     * @return array<string, mixed>
     */
    private function positionedPdfCompositeInlineContinuationLayout(array $item, array $positionedItems, array $siblingIndexes): array
    {
        $sourceRangeItems = [$item];
        foreach ($siblingIndexes as $index) {
            $sibling = $positionedItems[$index] ?? null;
            if (!is_array($sibling) || !$this->pdfLayoutHasGeometry($sibling)) {
                continue;
            }
            $sourceRangeItems[] = $sibling;
            $item['x1'] = min((float) $item['x1'], (float) $sibling['x1']);
            $item['y1'] = min((float) $item['y1'], (float) $sibling['y1']);
            $item['x2'] = max((float) $item['x2'], (float) $sibling['x2']);
            $item['y2'] = max((float) $item['y2'], (float) $sibling['y2']);
            $item['fontSize'] = max((float) $item['fontSize'], (float) $sibling['fontSize']);
            $item['sourceOrderStart'] = min((int) $item['sourceOrderStart'], (int) $sibling['sourceOrderStart']);
            $item['sourceOrderEnd'] = max((int) $item['sourceOrderEnd'], (int) $sibling['sourceOrderEnd']);
        }
        usort($sourceRangeItems, static fn (array $left, array $right): int =>
            ((float) ($left['x1'] ?? 0.0) <=> (float) ($right['x1'] ?? 0.0))
                ?: ((int) ($left['sourceOrderStart'] ?? 0) <=> (int) ($right['sourceOrderStart'] ?? 0))
        );
        $exactSourceRanges = $this->pdfPositionedExactSourceRangesForItems($sourceRangeItems);
        if ($exactSourceRanges !== []) {
            $item['sourcePdfExactSourceRanges'] = $exactSourceRanges;
        }

        return $item;
    }

    /**
     * @param array<string, mixed> $item
     * @param array<string, mixed> $positionedItem
     * @return array<string, mixed>
     */
    private function markSourcePdfVerifiedGeometryText(array $item, array $positionedItem): array
    {
        $sourceKey = $this->pdfComparableLineText((string) ($item['text'] ?? ''));
        $positionedKey = $this->pdfComparableLineText((string) ($positionedItem['text'] ?? ''));
        if ($sourceKey === '' || $sourceKey !== $positionedKey) {
            return $item;
        }

        // Retain exact source-to-positioned provenance even for a short line.
        // The broader geometry-text marker below deliberately excludes short
        // labels because they are weak evidence on their own. A neighboring
        // source/layout pair, however, can use an exact short continuation as
        // one part of its occurrence-local proof without making it a general
        // text or vocabulary rule.
        $item['sourcePdfExactPositionedText'] = true;
        if ($this->length($sourceKey) < 24
            || count($this->pdfLineWordTokens((string) ($item['text'] ?? ''))) < 4) {
            return $item;
        }

        $item['sourceVerifiedGeometryText'] = true;

        return $item;
    }

    /**
     * A full source/positioned text match is retained separately from the
     * longer-prose geometry marker. This lets an adjacent wrapped pair use a
     * short, exact continuation as local provenance while other layout logic
     * keeps its stricter long-line threshold.
     *
     * @param array<string, mixed> $item
     */
    private function sourcePdfItemHasExactPositionedText(array $item): bool
    {
        return ($item['sourceVerifiedGeometryText'] ?? false) === true
            || ($item['sourcePdfExactPositionedText'] ?? false) === true;
    }

    /**
     * @param list<array{page: int, stream: int, text: string}> $sourceItems
     * @param list<int> $indexes
     * @return array{page: int, stream: int, text: string}|null
     */
    private function sourcePdfJoinedFragmentLineItem(
        array $sourceItems,
        array $indexes,
        ?array $matchingPositionedItem = null
    ): ?array
    {
        $first = $sourceItems[$indexes[0]];
        $reconciliation = $this->sourcePdfFragmentSeparatorsFromPositionedText(
            $sourceItems,
            $indexes,
            $matchingPositionedItem
        );
        if ($reconciliation === null) {
            return null;
        }
        $text = '';
        foreach ($indexes as $index) {
            $fragment = $reconciliation['fragments'][$index] ?? trim($sourceItems[$index]['text']);
            if ($fragment === '') {
                continue;
            }
            $needsSpace = $reconciliation['separators'][$index] ?? false;
            if ($text !== '' && $needsSpace) {
                $text .= ' ';
            }
            if ($text !== '' && ($reconciliation['compactIdentifierBoundaryBefore'][$index] ?? false) === true) {
                $text .= self::PDF_SOURCE_COMPACT_IDENTIFIER_BOUNDARY;
            }
            $text .= $fragment;
        }

        return [
            'page' => $first['page'],
            'stream' => $first['stream'],
            'text' => $text,
        ];
    }

    /**
     * Reconcile one contiguous source-fragment sequence with the one
     * positioned visual line it matched. This is deliberately
     * occurrence-local: an `all` + `owed` boundary may be compact in one line
     * and spaced in the next.
     *
     * The positioned line's verified boundary map is applied to the matching
     * compact source occurrence before inter-fragment whitespace is derived.
     * That lets a source fragment contain `ati` while the local visual run
     * proves `at i`, and independently lets the following superscript `2`
     * remain touching. The positioned text is never used as a wholesale text
     * replacement: its compact characters must exactly equal this source
     * sequence and only verified separator offsets are restored.
     *
     * @param list<array{page: int, stream: int, text: string}> $sourceItems
     * @param list<int> $indexes
     * @param array<string, mixed>|null $matchingPositionedItem
     * @return array{fragments: array<int, string>, separators: array<int, bool>, compactIdentifierBoundaryBefore: array<int, true>}|null
     *         `separators[index]` means a space precedes that source index.
     */
    private function sourcePdfFragmentSeparatorsFromPositionedText(
        array $sourceItems,
        array $indexes,
        ?array $matchingPositionedItem
    ): ?array {
        if ($matchingPositionedItem === null) {
            return null;
        }

        $target = $this->pdfExactLayoutText((string) ($matchingPositionedItem['text'] ?? ''));
        if ($target === '') {
            return null;
        }

        $fragments = [];
        $sourceLayout = '';
        $fragmentCompactOffsets = [];
        $sourceCompact = '';
        foreach ($indexes as $index) {
            $fragment = $this->pdfExactLayoutText((string) ($sourceItems[$index]['text'] ?? ''));
            $sourceLayout .= $this->pdfLayoutTextPreservingEdgeWhitespace(
                (string) ($sourceItems[$index]['text'] ?? '')
            );
            if ($fragment !== '') {
                $fragments[$index] = $fragment;
                $fragmentCompactOffsets[$index] = $this->length($sourceCompact);
                $sourceCompact .= preg_replace('/\s+/u', '', $fragment) ?? $fragment;
            }
        }
        $targetCompact = preg_replace('/\s+/u', '', $target) ?? $target;
        $trailingSourceDotLeader = '';
        $lastFragmentIndex = array_key_last($fragments);
        if ($lastFragmentIndex !== null
            && preg_match('/((?:\h+\.){2,}\h*)$/u', $fragments[$lastFragmentIndex], $leaderMatch) === 1
            && !str_ends_with($targetCompact, preg_replace('/\s+/u', '', $leaderMatch[1]) ?? $leaderMatch[1])) {
            // A spaced dot leader is layout furniture, not part of the
            // positioned prose line. Match the exact preceding characters,
            // but retain the source leader in the joined output so source
            // disposition remains lossless. Requiring two whitespace-led
            // dots deliberately excludes sentence periods and ellipses.
            $trailingSourceDotLeader = $leaderMatch[1];
            $fragments[$lastFragmentIndex] = substr(
                $fragments[$lastFragmentIndex],
                0,
                -strlen($trailingSourceDotLeader)
            );
            $sourceCompact = substr(
                $sourceCompact,
                0,
                -strlen(preg_replace('/\s+/u', '', $trailingSourceDotLeader) ?? $trailingSourceDotLeader)
            );
        }
        if ($fragments === [] || $sourceCompact === '' || $sourceCompact !== $targetCompact) {
            return null;
        }

        // Inline delimiters are a source-level structural boundary. A
        // superscript or styled formula atom can be painted with a different
        // advance from the surrounding prose, so its visual gap is not a
        // reliable instruction to rewrite the source's own notation. Keep
        // only the exact delimited occurrence protected; ordinary words and
        // all other source fragments still use the matched positioned line.
        $protectedDelimiterOffsets = $this->sourcePdfDelimitedNotationSeparatorOffsets($sourceLayout);
        foreach ($protectedDelimiterOffsets as $offset => $_) {
            if ($offset <= 0 || $offset >= $this->length($sourceCompact)) {
                unset($protectedDelimiterOffsets[$offset]);
            }
        }

        $positionedBoundarySeparators = $this->positionedSourceVerifiedBoundarySeparators($matchingPositionedItem);
        $boundarySeparators = [];
        foreach ($positionedBoundarySeparators as $offset => $separator) {
            if ($offset > 0
                && $offset < $this->length($sourceCompact)
                && !isset($protectedDelimiterOffsets[$offset])) {
                $boundarySeparators[$offset] = $separator;
            }
        }

        // A compact boundary candidate is deliberately more constrained than
        // an ordinary geometry separator: it must be the exact seam of this
        // short, source-order-bound fragment sequence, and the sequence must
        // otherwise contain a source-proven word gap. That preserves a split
        // prefix inside prose without gluing two nearby independent labels.
        if ($this->sourcePdfLocallyBoundShortFragmentSequenceMatchesPositionedLine(
            $sourceItems,
            $indexes,
            $matchingPositionedItem
        ) && preg_match('/\S\s+\S/u', $sourceLayout) === 1) {
            $fragmentBoundaryOffsets = array_fill_keys(array_values($fragmentCompactOffsets), true);
            foreach ($this->positionedSourceCompactBoundaryOffsets($matchingPositionedItem) as $offset => $_) {
                if (isset($fragmentBoundaryOffsets[$offset])
                    && !isset($protectedDelimiterOffsets[$offset])
                    && ($positionedBoundarySeparators[$offset] ?? null) === ' ') {
                    $boundarySeparators[$offset] = '';
                }
            }
        }

        // Apply a local geometry decision to the fragments that contain its
        // compact boundary. Decisions that land exactly between two source
        // fragments are intentionally deferred to the separator derivation
        // below, so this pass cannot introduce a cross-occurrence rewrite.
        foreach ($fragments as $index => $fragment) {
            $start = $fragmentCompactOffsets[$index];
            $length = $this->length(preg_replace('/\s+/u', '', $fragment) ?? $fragment);
            $fragmentSeparators = [];
            foreach ($boundarySeparators as $offset => $separator) {
                if ($offset > $start && $offset < $start + $length) {
                    $fragmentSeparators[$offset - $start] = $separator;
                }
            }
            if ($fragmentSeparators !== []) {
                $fragments[$index] = $this->sourcePdfLineTextWithProvenPositionedSeparators(
                    $fragment,
                    $fragment,
                    $fragmentSeparators
                );
            }
        }

        // A positioned producer can expose ordinary whitespace imprecisely at
        // a style or superscript boundary. Normalize only those offsets for
        // which its own extractor provenance is explicit, then use the
        // remaining visual whitespace solely to choose separators between the
        // already-verified source fragments.
        if ($boundarySeparators !== []) {
            $target = $this->sourcePdfLineTextWithProvenPositionedSeparators(
                $target,
                $target,
                $boundarySeparators
            );
        }
        if ($protectedDelimiterOffsets !== []) {
            // The visual text may contain a normal word gap immediately
            // after a closing delimiter even though the source item records
            // one structural notation run. Normalize that one local span
            // before matching, rather than replacing the whole line.
            $target = $this->sourcePdfLineTextWithProvenPositionedSeparators(
                $target,
                $target,
                array_fill_keys(array_keys($protectedDelimiterOffsets), '')
            );
        }

        // Preserve whitespace already present inside a source fragment, but
        // permit the positioned extractor to omit it. Captured groups cover
        // only inter-fragment boundaries: a non-whitespace character there
        // means this is not the same source composition.
        $pattern = '/^';
        $separatorIndexes = [];
        foreach ($fragments as $index => $fragment) {
            if ($separatorIndexes !== []) {
                $pattern .= '(\s*)';
                $separatorIndexes[] = $index;
            } else {
                $separatorIndexes[] = $index;
            }
            $pattern .= str_replace(' ', '\s*', preg_quote($fragment, '/'));
        }
        $pattern .= '$/u';
        if (preg_match($pattern, $target, $matches) !== 1) {
            return null;
        }

        $separators = [];
        $capture = 1;
        foreach (array_slice($separatorIndexes, 1) as $index) {
            $separators[$index] = ($matches[$capture] ?? '') !== '';
            $capture++;
        }

        // At a protected source-fragment seam retain the source's local
        // structural separator rule. This covers a formula atom emitted as a
        // separate styled fragment without changing similarly spelled prose
        // elsewhere in the document.
        $previousIndex = null;
        foreach ($fragments as $index => $fragment) {
            if ($previousIndex !== null
                && isset($protectedDelimiterOffsets[$fragmentCompactOffsets[$index] ?? -1])) {
                $separators[$index] = $this->sourcePdfJoinedFragmentsNeedSpace(
                    $fragments[$previousIndex],
                    $fragment
                );
            }
            $previousIndex = $index;
        }

        $compactIdentifierBoundaryBefore = [];
        $previousIndex = null;
        foreach ($fragments as $index => $fragment) {
            if ($previousIndex !== null
                && ($separators[$index] ?? false) === false
                && $this->sourcePdfFragmentBoundaryIsCompactIdentifier(
                    (string) ($sourceItems[$previousIndex]['text'] ?? ''),
                    (string) ($sourceItems[$index]['text'] ?? ''),
                    (int) ($fragmentCompactOffsets[$index] ?? -1),
                    $positionedBoundarySeparators
                )) {
                $compactIdentifierBoundaryBefore[$index] = true;
            }
            $previousIndex = $index;
        }

        if ($trailingSourceDotLeader !== '' && $lastFragmentIndex !== null) {
            $fragments[$lastFragmentIndex] .= $trailingSourceDotLeader;
        }

        return [
            'fragments' => $fragments,
            'separators' => $separators,
            'compactIdentifierBoundaryBefore' => $compactIdentifierBoundaryBefore,
        ];
    }

    /**
     * A later prose pass has to split ambiguous `word42` text, but it must
     * not undo a compact identifier whose exact source fragment and matching
     * positioned boundary both establish the join. Limit that protection to
     * a punctuation-leading identifier fragment with no preceding source
     * word in that record: a detached or inline `R` + `42` remains ambiguous
     * and is intentionally left to the prose pass.
     *
     * @param array<int, string> $positionedBoundarySeparators
     */
    private function sourcePdfFragmentBoundaryIsCompactIdentifier(
        string $previousSourceText,
        string $nextSourceText,
        int $compactOffset,
        array $positionedBoundarySeparators
    ): bool {
        if ($compactOffset <= 0
            || ($positionedBoundarySeparators[$compactOffset] ?? null) !== '') {
            return false;
        }

        $previous = rtrim($this->pdfLayoutTextPreservingEdgeWhitespace($previousSourceText));
        $next = ltrim($this->pdfLayoutTextPreservingEdgeWhitespace($nextSourceText));
        if (preg_match('/\p{L}$/u', $previous) !== 1
            || preg_match('/^\d{2,}/u', $next) !== 1) {
            return false;
        }

        return preg_match('/^\s*[^\p{L}\p{N}]+\p{L}+\s*$/u', $previous) === 1;
    }

    /**
     * Preserve spaces while comparing a source fragment sequence with one
     * positioned visual line. Unlike the ordinary comparable-text key, this
     * intentionally distinguishes "New York" from "NewYork" so a direct
     * character match can prove that a source-stream boundary is intra-word.
     */
    private function pdfExactLayoutText(string $text): string
    {
        return trim($this->pdfLayoutTextPreservingEdgeWhitespace($text));
    }

    /**
     * Keep literal edge whitespace while normalizing a source fragment. This
     * is used only to identify attached delimiter notation before the normal
     * compact comparison removes whitespace.
     */
    private function pdfLayoutTextPreservingEdgeWhitespace(string $text): string
    {
        $text = $this->normalizePdfTextEncoding($text);
        $text = str_replace(["\u{00AD}", "\u{2010}", "\u{2011}"], '-', $text);
        $text = str_replace("\u{00A0}", ' ', $text);

        return preg_replace('/\s+/u', ' ', $text) ?? $text;
    }

    /**
     * Find compact-character boundaries that belong to an attached
     * parenthesized, bracketed, or braced source notation run. Text inside a
     * normal parenthetical is deliberately excluded unless the opening
     * delimiter directly follows an identifier or number in the source.
     *
     * @return array<int, true> Compact-character offset => true.
     */
    private function sourcePdfDelimitedNotationSeparatorOffsets(string $sourceLayout): array
    {
        $characters = preg_split('//u', $sourceLayout, -1, PREG_SPLIT_NO_EMPTY);
        if (!is_array($characters) || $characters === []) {
            return [];
        }

        $compactOffsets = [];
        $compactLength = 0;
        foreach ($characters as $index => $character) {
            if (preg_match('/^\s$/u', $character) === 1) {
                continue;
            }
            $compactOffsets[$index] = $compactLength;
            $compactLength++;
        }

        $opens = ['(' => ')', '[' => ']', '{' => '}'];
        $stack = [];
        $offsets = [];
        foreach ($characters as $index => $character) {
            if (isset($opens[$character])) {
                $previous = $characters[$index - 1] ?? null;
                if (!is_string($previous)
                    || !isset($compactOffsets[$index - 1])
                    || preg_match('/^[\p{L}\p{N}]$/u', $previous) !== 1) {
                    continue;
                }
                $stack[] = [
                    'closing' => $opens[$character],
                    'start' => $compactOffsets[$index - 1],
                ];
                continue;
            }
            if ($stack === [] || !isset($compactOffsets[$index])) {
                continue;
            }

            $lastIndex = array_key_last($stack);
            $opening = $stack[$lastIndex];
            if ($character !== $opening['closing']) {
                continue;
            }
            array_pop($stack);
            $closingOffset = $compactOffsets[$index];
            for ($offset = $opening['start'] + 1; $offset <= $closingOffset; $offset++) {
                $offsets[$offset] = true;
            }

            $next = $characters[$index + 1] ?? null;
            if (is_string($next)
                && isset($compactOffsets[$index + 1])
                && preg_match('/^[\p{L}\p{N}]$/u', $next) === 1) {
                $offsets[$closingOffset + 1] = true;
            }
        }

        return $offsets;
    }

    /**
     * Recover an inter-fragment separator from syntax only when a local
     * delimiter run explicitly withheld it from geometry. This is the former
     * source-stream fallback, deliberately free of vocabulary or casing
     * rules.
     */
    private function sourcePdfJoinedFragmentsNeedSpace(string $previous, string $next): bool
    {
        $previous = rtrim($previous);
        $next = ltrim($next);
        if ($this->lineLooksLikeUrlOnly($previous)
            && !preg_match('/[\/-]$/u', $previous)
            && $this->lineLooksLikeBareDomain($next)) {
            return true;
        }
        if (preg_match('/[-\x{2010}-\x{2015}\/(\[{]\s*$/u', $previous) === 1
            || preg_match('/^\s*[\)\]\},.!?;:]/u', $next) === 1) {
            return false;
        }
        if (preg_match('/^[\p{M}\p{Sk}]+$/u', $next) === 1
            || preg_match('/[\p{M}\p{Sk}]$/u', $previous) === 1) {
            return false;
        }
        if (preg_match('/^\p{N}{1,3}$/u', $previous) === 1 && preg_match('/^\p{Ll}/u', $next) === 1) {
            return true;
        }
        if (preg_match('/[\p{L}]$/u', $previous) === 1 && preg_match('/^\p{N}/u', $next) === 1) {
            return false;
        }
        if (preg_match('/\p{N}$/u', $previous) === 1 && preg_match('/^\p{L}/u', $next) === 1) {
            return false;
        }

        return true;
    }

    private function lineLooksLikeBareDomain(string $text): bool
    {
        return preg_match('/^[A-Za-z0-9](?:[A-Za-z0-9-]*\.)+[A-Za-z]{2,}(?:[\/?#][^\s]*)?$/u', trim($text)) === 1;
    }

    /**
     * The normal text layer is preferred for spacing, but a substantial
     * positioned caption can be the only readable representation of a visual
     * text run. Preserve only complete-looking lines, never short labels or
     * glyph fragments from diagrams.
     *
     * @param array<string, mixed> $item
     */
    private function positionedPdfLineCanSupplementSource(array $item): bool
    {
        if (($item['code'] ?? false) === true || $this->lineIsOnlyPdfNoise((string) ($item['text'] ?? ''))) {
            return false;
        }
        $text = trim((string) ($item['text'] ?? ''));

        return $this->length($text) >= 28 && count($this->pdfLineWordTokens($text)) >= 5;
    }

    /**
     * A formula or diagram can be painted immediately before a normal body
     * sentence on the same positioned line. The source text layer often
     * exposes only the damaged prefix. Keep the visual line only when its
     * punctuation provides an independently recoverable sentence suffix.
     *
     * @param array<string, mixed> $item
     */
    private function positionedPdfLineHasRecoverableSentenceSuffix(array $item): bool
    {
        if (!$this->pdfLayoutHasGeometry($item) || ($item['code'] ?? false) === true) {
            return false;
        }

        $text = ltrim((string) ($item['text'] ?? ''));
        if ($text === ''
            || $this->lineIsOnlyPdfNoise($text)
            || preg_match('/^[^\p{L}\p{N}]/u', $text) !== 1
            || preg_match('/[.!?]\s*((?:(?:[\(\[]\s*)?(?:\p{N}+\s*[\)\]]\s*)?)?\p{Lu}[\s\S]*)$/u', $text, $matches) !== 1) {
            return false;
        }

        return count($this->pdfLineWordTokens($matches[1])) >= 5;
    }

    /**
     * A source text layer can omit a colored, italic, or subset-font fragment
     * from an otherwise ordinary body line. Accept a short positioned fallback
     * only inside an already-established parallel body flow. The shared font,
     * baseline band, and horizontal span keep diagram labels and detached
     * figure text out of this path.
     *
     * @param array<string, mixed> $item
     * @param list<array<string, mixed>> $matchedItems
     */
    private function positionedPdfShortLineCanSupplementMatchedBodyFlow(array $item, array $matchedItems): bool
    {
        if (!$this->pdfLayoutHasGeometry($item)
            || ($item['code'] ?? false) === true) {
            return false;
        }

        $text = trim((string) ($item['text'] ?? ''));
        $wordCount = count($this->pdfLineWordTokens($text));
        $terminal = preg_match('/[.!?;:]\s*$/u', $text) === 1;
        if ($text === ''
            || $this->lineIsOnlyPdfNoise($text)
            || ($this->lineLooksLikePdfDiagramLabel($text) && $this->length($text) < 10)
            || $this->length($text) < 4
            || ($wordCount === 0)) {
            return false;
        }

        foreach ($matchedItems as $neighbor) {
            if (!$this->pdfLayoutHasGeometry($neighbor)
                || ($neighbor['page'] ?? null) !== ($item['page'] ?? null)
                || ($neighbor['code'] ?? false) === true) {
                continue;
            }

            $fontSize = max(1.0, (float) $item['fontSize'], (float) $neighbor['fontSize']);
            if (abs((float) $item['fontSize'] - (float) $neighbor['fontSize']) > max(1.5, $fontSize * 0.22)) {
                continue;
            }

            $verticalDistance = abs((float) $item['y1'] - (float) $neighbor['y1']);
            $horizontalTolerance = max(16.0, $fontSize * 2.0);
            $withinNeighborSpan = (float) $item['x1'] >= (float) $neighbor['x1'] - $horizontalTolerance
                && (float) $item['x1'] <= (float) $neighbor['x2'] + $horizontalTolerance;
            if (!$withinNeighborSpan || $verticalDistance > max(18.0, $fontSize * 2.2)) {
                continue;
            }

            if ($wordCount > 1 || $terminal || $this->length($text) >= 10) {
                return true;
            }

            $adjacentOnBaseline = $verticalDistance <= max(1.5, $fontSize * 0.35)
                && (float) $item['x1'] >= (float) $neighbor['x2'] - $horizontalTolerance
                && (float) $item['x1'] - (float) $neighbor['x2'] <= $horizontalTolerance;
            if ($adjacentOnBaseline) {
                return true;
            }
        }

        return false;
    }

    /**
     * Some PDFs omit an entire source-text run, so no exact source neighbor is
     * available to corroborate it. In a verified parallel body-column layout,
     * nearby positioned text with the same font is sufficient geometric proof
     * of the flow. The wide column-span allowance covers a line split into two
     * positioned fragments on the same baseline.
     *
     * @param array<string, mixed> $item
     * @param list<array{x: float, width: float, fontSize: float, count: int}> $columns
     * @param list<array<string, mixed>> $positionedItems
     */
    private function positionedPdfShortLineCanSupplementStableBodyColumn(
        array $item,
        array $columns,
        array $positionedItems
    ): bool {
        if (!$this->pdfLayoutHasGeometry($item) || ($item['code'] ?? false) === true) {
            return false;
        }

        $text = trim((string) ($item['text'] ?? ''));
        if ($text === ''
            || $this->lineIsOnlyPdfNoise($text)
            || ($this->lineLooksLikePdfDiagramLabel($text) && $this->length($text) < 10)
            || $this->length($text) < 4
            || count($this->pdfLineWordTokens($text)) === 0) {
            return false;
        }

        $column = null;
        foreach ($columns as $candidate) {
            $fontSize = max(1.0, (float) $item['fontSize'], $candidate['fontSize']);
            if (abs((float) $item['fontSize'] - $candidate['fontSize']) > max(1.5, $fontSize * 0.22)) {
                continue;
            }
            $leftTolerance = max(16.0, $fontSize * 2.0);
            if ((float) $item['x1'] < $candidate['x'] - $leftTolerance
                || (float) $item['x1'] > $candidate['x'] + $candidate['width'] * 0.85) {
                continue;
            }
            $column = $candidate;
            break;
        }
        if ($column === null) {
            return false;
        }

        foreach ($positionedItems as $neighbor) {
            if ($neighbor === $item
                || !$this->pdfLayoutHasGeometry($neighbor)
                || ($neighbor['page'] ?? null) !== ($item['page'] ?? null)
                || ($neighbor['code'] ?? false) === true) {
                continue;
            }

            $fontSize = max(1.0, (float) $item['fontSize'], (float) $neighbor['fontSize'], $column['fontSize']);
            if (abs((float) $item['fontSize'] - (float) $neighbor['fontSize']) > max(1.5, $fontSize * 0.22)
                || abs((float) $item['y1'] - (float) $neighbor['y1']) > max(24.0, $fontSize * 2.5)) {
                continue;
            }
            if ((float) $neighbor['x1'] < $column['x'] - max(16.0, $fontSize * 2.0)
                || (float) $neighbor['x1'] > $column['x'] + $column['width'] * 0.85) {
                continue;
            }
            if ($this->lineIsOnlyPdfNoise((string) ($neighbor['text'] ?? ''))
                || count($this->pdfLineWordTokens((string) ($neighbor['text'] ?? ''))) === 0) {
                continue;
            }

            return true;
        }

        return false;
    }

    /**
     * Positioning can sometimes join text from adjacent regions onto one
     * baseline. Record substantial source overlap now; later geometry decides
     * whether the positioned line has a credible visual place to supplement.
     *
     * @param array<string, mixed> $positionedItem
     * @param list<array{page: int, stream: int, text: string}> $sourceItems
     */
    private function positionedPdfLineSubstantiallyOverlapsSource(array $positionedItem, array $sourceItems): bool
    {
        $positionedText = $this->pdfComparableLineText((string) ($positionedItem['text'] ?? ''));
        $positionedLength = $this->length($positionedText);
        if ($positionedLength < 16) {
            return false;
        }

        foreach ($sourceItems as $sourceItem) {
            $sourceText = $this->pdfComparableLineText($sourceItem['text']);
            $sourceLength = $this->length($sourceText);
            if ($sourceLength < 16) {
                continue;
            }
            if (!str_contains($positionedText, $sourceText) && !str_contains($sourceText, $positionedText)) {
                continue;
            }

            if ($this->lineLooksLikeUrlOnly((string) ($positionedItem['text'] ?? ''))
                && $positionedLength >= 20
                && str_contains($sourceText, $positionedText)) {
                return true;
            }

            if (min($positionedLength, $sourceLength) / max($positionedLength, $sourceLength) >= 0.72) {
                return true;
            }
        }

        foreach ($sourceItems as $sourceItem) {
            if ($this->sourcePdfComparableTextIsCoveredBySupplementalPositioning(
                (string) ($sourceItem['text'] ?? ''),
                (string) ($positionedItem['text'] ?? '')
            )) {
                return true;
            }
        }

        return false;
    }

    /**
     * Geometry-confirmed lines are emitted in visual order. For a missing
     * positioned line, keep an immediately adjacent hyphenated continuation
     * with its known neighbor rather than appending it to the end of the page.
     * This preserves wrapped words and URLs while leaving uncertain fragments
     * isolated instead of guessing where they belong.
     *
     * @param list<array{page: int, stream: int, text: string}> $sourceItems
     * @param array{items: list<array<string, mixed>>, sourceIndexes: array<int, true>, itemsBySourceIndex: array<int, array<string, mixed>>, visualEntries: list<array{item: array<string, mixed>, sourceIndex: int|null}>} $match
     * @return list<array<string, mixed>>
     */
    private function sourcePdfItemsInVisualOrder(
        array $sourceItems,
        array &$match,
        bool $includeUnmatchedPositionedSupplements = true
    ): array
    {
        $tableSourceGroups = $this->sourcePdfTableSourceGroups($sourceItems);
        $before = [];
        $after = [];
        $fallback = [];
        foreach ($sourceItems as $index => $sourceItem) {
            if (isset($match['sourceIndexes'][$index])) {
                continue;
            }

            $nextIndex = $index + 1;
            $shortCommaLead = isset($sourceItems[$nextIndex], $match['itemsBySourceIndex'][$nextIndex])
                && $this->sourcePdfItemsShareStream($sourceItem, $sourceItems[$nextIndex])
                && $this->sourcePdfShortCommaLeadPrecedesKnownLayout(
                    $sourceItem['text'],
                    $sourceItems[$nextIndex]['text']
                );
            if (isset($sourceItems[$nextIndex], $match['itemsBySourceIndex'][$nextIndex])
                && $this->sourcePdfItemsShareStream($sourceItem, $sourceItems[$nextIndex])
                && ($this->sourcePdfLinesAreWrappedContinuation($sourceItem['text'], $sourceItems[$nextIndex]['text'])
                    || $shortCommaLead)) {
                $item = $this->sourcePdfLineItemBeforeKnownLayout(
                    $sourceItem,
                    $match['itemsBySourceIndex'][$nextIndex]
                );
                if ($shortCommaLead) {
                    $item['sourceShortCommaLead'] = true;
                }
                $before[$nextIndex][] = $this->sourcePdfAttachSourceItemProvenance($item, $index, $tableSourceGroups);
                continue;
            }

            $previousIndex = $index - 1;
            if (isset($sourceItems[$previousIndex], $match['itemsBySourceIndex'][$previousIndex])
                && $this->sourcePdfItemsShareStream($sourceItems[$previousIndex], $sourceItem)
                && $this->sourcePdfLinesAreWrappedContinuation($sourceItems[$previousIndex]['text'], $sourceItem['text'])) {
                $item = $this->sourcePdfLineItemAfterKnownLayout(
                    $sourceItem,
                    $match['itemsBySourceIndex'][$previousIndex]
                );
                $after[$previousIndex][] = $this->sourcePdfAttachSourceItemProvenance($item, $index, $tableSourceGroups);
                continue;
            }

            // A source text-showing operator can lack an origin altogether.
            // Preserve it only when the immediately adjacent source records
            // on both sides are matched, share its stream, and occupy
            // consecutive, vertically ordered visual slots. This supplies a
            // local placement proof without admitting isolated figure labels
            // merely because the page otherwise has usable geometry.
            if (isset(
                $sourceItems[$previousIndex],
                $sourceItems[$nextIndex],
                $match['itemsBySourceIndex'][$previousIndex],
                $match['itemsBySourceIndex'][$nextIndex]
            ) && $this->sourcePdfItemsShareStream($sourceItems[$previousIndex], $sourceItem)
                && $this->sourcePdfItemsShareStream($sourceItem, $sourceItems[$nextIndex])
                && $this->sourcePdfMatchedLayoutsSandwichSourceOnlyItem(
                    $sourceItem,
                    $match['itemsBySourceIndex'][$previousIndex],
                    $match['itemsBySourceIndex'][$nextIndex],
                    $previousIndex,
                    $nextIndex,
                    $match['visualEntries']
                )) {
                $item = $this->sourcePdfLineItemBetweenKnownLayouts(
                    $sourceItem,
                    $match['itemsBySourceIndex'][$previousIndex],
                    $match['itemsBySourceIndex'][$nextIndex]
                );
                $after[$previousIndex][] = $this->sourcePdfAttachSourceItemProvenance($item, $index, $tableSourceGroups);
                continue;
            }

            $hasExactSourceGeometry = $this->sourcePdfSourceItemHasExactGeometry($sourceItem);
            if (!isset($tableSourceGroups[$index])
                && !$hasExactSourceGeometry
                && $this->sourcePdfUnmatchedLineLooksLikeFloatingFragment($sourceItem['text'])) {
                continue;
            }
            $fallbackItem = $hasExactSourceGeometry
                ? $this->sourcePdfExactGeometryFallbackLineItem($sourceItem, $index)
                : $this->sourcePdfLineItem($sourceItem, null, true);
            if ($fallbackItem === null) {
                continue;
            }
            // These source-only entries have no trustworthy visual location.
            // Keep them available for prose, but let the later coherence pass
            // discard a sustained cluster of unplaceable diagram labels.
            $fallbackItem['sourceUnmatchedFallback'] = true;
            $fallback[] = $this->sourcePdfAttachSourceItemProvenance($fallbackItem, $index, $tableSourceGroups);
        }

        $ordered = [];
        foreach ($match['visualEntries'] as $entry) {
            if (!$includeUnmatchedPositionedSupplements
                && $entry['sourceIndex'] === null
                && (($entry['item']['sourceSupplementalSourceOverlap'] ?? false) !== true)
                && (($entry['item']['sourceSupplementalRecoverableSentenceSuffix'] ?? false) !== true)) {
                continue;
            }
            $sourceIndex = $entry['sourceIndex'];
            if ($sourceIndex === null) {
                $ordered[] = $entry['item'];
                continue;
            }
            foreach ($before[$sourceIndex] ?? [] as $item) {
                $ordered[] = $item;
            }
            $ordered[] = $this->sourcePdfAttachSourceItemProvenance(
                $match['itemsBySourceIndex'][$sourceIndex],
                $sourceIndex,
                $tableSourceGroups
            );
            foreach ($after[$sourceIndex] ?? [] as $item) {
                $ordered[] = $item;
            }
        }
        // Matching has been fully projected into the ordered/fallback records.
        // Consume its document-shaped indexes before the geometry passes add
        // per-record attributes; the caller does not reuse the match result.
        $match = [];
        unset($before, $after, $tableSourceGroups);

        [$ordered, $fallback] = $this->restoreSourcePdfPartialSupplementalLines($ordered, $fallback);
        if (!$includeUnmatchedPositionedSupplements) {
            $fallback = array_values(array_filter(
                $fallback,
                fn (array $item): bool => ($item['sourcePdfExactGeometryFallback'] ?? false) === true
                    || $this->sourcePdfUnmatchedFallbackCanStandAlone($item)
            ));
        }
        $ordered = $this->removeSourcePdfItemsCoveredBySupplementalPositioning($ordered);
        $ordered = $this->removeSourcePdfSupplementalRowDuplicates($ordered);
        $ordered = $this->orderSourcePdfItemsWithinStableColumns($ordered);
        $ordered = $this->removeSourcePdfInferredCrossColumnDuplicates($ordered);
        $ordered = $this->removeSourcePdfNearBaselinePrefixDuplicates($ordered);
        $ordered = $this->retainSourcePdfShortPositionedBodySupplements($ordered);
        $ordered = $this->removeSourcePdfNearBaselinePrefixDuplicates($ordered);
        $ordered = $this->removeSourcePdfSupplementalOverlaysThatInterruptSourceWrap($ordered);
        if ($this->sourcePdfGeometryOrderHasStableBodyColumns($ordered)) {
            $fallback = array_values(array_filter(
                $fallback,
                fn (array $item): bool => isset($item['sourcePdfTableGroup'])
                    || ($item['code'] ?? false) === true
                    || ($item['sourcePdfExactGeometryFallback'] ?? false) === true
                    || $this->lineLooksLikeUrlOnly((string) ($item['text'] ?? ''))
            ));
        }
        $fallback = $this->removeSourcePdfFallbackCoveredBySupplementalPositioning($fallback, $ordered);
        $complexGeometryPage = count(array_filter(
            $ordered,
            static fn (array $item): bool => ($item['sourceComplexGeometryPage'] ?? false) === true
        )) > 0;
        $detachedDiagramEvidencePage = $this->sourcePdfPageHasDetachedDiagramEvidence($ordered, $fallback);
        if ($complexGeometryPage) {
            foreach ($fallback as &$item) {
                $item['sourceComplexGeometryPage'] = true;
            }
            unset($item);
        }
        if ($detachedDiagramEvidencePage) {
            foreach ($ordered as &$item) {
                $item['sourceDetachedDiagramEvidencePage'] = true;
            }
            unset($item);
            foreach ($fallback as &$item) {
                $item['sourceDetachedDiagramEvidencePage'] = true;
            }
            unset($item);
        }

        $combined = $this->restoreSourcePdfAdjacentVisualContinuations(array_merge($ordered, $fallback), $sourceItems);
        $combined = $this->restoreSourcePdfTableItemSequences($combined, $sourceItems);
        $combined = $this->restoreSourcePdfStandaloneListMarkerPrefixes($combined, $sourceItems);

        $combined = $this->markSourcePdfOrphanedInferredContinuations($combined, $sourceItems);

        return $this->propagateSourcePdfUnresolvedInterruptedFlows($combined);
    }

    /**
     * A PDF may paint a two-column panel before painting its larger title. When
     * every panel line and the title have occurrence-exact geometry, promote
     * only that title ahead of the immediately preceding panel. This is a local
     * layout proof: it does not reorder the page or infer headings from words.
     *
     * @param list<array<string,mixed>> $items
     * @return list<array<string,mixed>>
     */
    private function promoteSourcePdfExactGeometryPanelTitles(array $items): array
    {
        for ($index = 1; $index < count($items); $index++) {
            $candidate = $items[$index];
            if (($candidate['sourcePdfExactGeometryFallback'] ?? false) !== true
                || ($candidate['sourcePdfExactGeometryPanelTitle'] ?? false) === true
                || !$this->pdfLayoutHasGeometry($candidate)
                || ($candidate['code'] ?? false) === true) {
                continue;
            }

            $text = trim((string) ($candidate['text'] ?? ''));
            $wordCount = count($this->pdfLineWordTokens($text));
            $fontSize = max(1.0, (float) $candidate['fontSize']);
            $width = (float) $candidate['x2'] - (float) $candidate['x1'];
            if ($text === ''
                || $wordCount < 2
                || $wordCount > 10
                || preg_match('/[.!?;:]\s*$/u', $text) === 1
                || $width < $fontSize * 4.0) {
                continue;
            }

            $minimumX = (float) $candidate['x1'] - max(8.0, $fontSize);
            $maximumX = (float) $candidate['x2'] + max(120.0, $width * 2.0);
            $maximumPanelY = (float) $candidate['y1'] + max(1.0, $fontSize * 0.15);
            $start = $index;
            while ($start > 0) {
                $entry = $items[$start - 1];
                if (($entry['page'] ?? null) !== ($candidate['page'] ?? null)
                    || !$this->pdfLayoutHasGeometry($entry)
                    || ($entry['code'] ?? false) === true
                    || (float) $entry['x1'] < $minimumX
                    || (float) $entry['x1'] > $maximumX
                    || (float) $entry['y2'] > $maximumPanelY
                    || (float) $entry['fontSize'] > $fontSize * 0.90) {
                    break;
                }
                $start--;
            }

            $panel = array_slice($items, $start, $index - $start);
            if (count($panel) < 16) {
                continue;
            }
            $exactCount = count(array_filter(
                $panel,
                fn (array $entry): bool => ($entry['sourcePdfExactGeometryFallback'] ?? false) === true
                    || $this->sourcePdfItemHasExactPositionedText($entry)
            ));
            if ($exactCount !== count($panel)) {
                continue;
            }

            $columns = $this->sourcePdfStableTextColumns($panel);
            if (count($columns) !== 2 || !$this->sourcePdfColumnsLookLikeParallelBodyColumns($columns)) {
                continue;
            }
            $panelFontSize = $this->median(array_map(
                static fn (array $entry): float => max(1.0, (float) $entry['fontSize']),
                $panel
            ));
            $panelTop = max(array_map(
                static fn (array $entry): float => (float) $entry['y2'],
                $panel
            ));
            $leftColumnX = min(array_column($columns, 'x'));
            if ($fontSize < $panelFontSize * 1.25
                || (float) $candidate['y1'] < $panelTop
                || (float) $candidate['y1'] - $panelTop > $fontSize * 2.0
                || abs((float) $candidate['x1'] - (float) $leftColumnX) > $fontSize * 2.0) {
                continue;
            }

            $candidate['sourcePdfExactGeometryPanelTitle'] = true;
            $candidate['forceBlockBreakBefore'] = true;
            array_splice($items, $index, 1);
            array_splice($items, $start, 0, [$candidate]);
            $index = $start;
        }

        return $items;
    }

    /**
     * A PDF text stream can emit a list marker as its own source record even
     * when the positioned row has lost that glyph. Source adjacency then
     * provides stronger list evidence than the reconstructed row alone.
     * Attach the marker only to its immediate same-stream successor and drop
     * the standalone duplicate, preserving ordinary nearby prose unchanged.
     *
     * @param list<array<string, mixed>> $items
     * @param list<array{page: int, stream: int, text: string}> $sourceItems
     * @return list<array<string, mixed>>
     */
    private function restoreSourcePdfStandaloneListMarkerPrefixes(array $items, array $sourceItems): array
    {
        $markerSourceIndexesBySuccessor = [];
        foreach ($sourceItems as $sourceIndex => $sourceItem) {
            $marker = trim($sourceItem['text']);
            if (!$this->lineIsStandalonePdfListMarker($marker)) {
                continue;
            }
            if ($this->sourcePdfHasExactInlineStandaloneMarkerEvidence($sourceItem)
                || $this->sourcePdfInlineStandaloneMarkerProofAt($sourceItems, $sourceIndex) !== null) {
                // Exact same-baseline content on both sides proves a literal
                // inline/table atom rather than a leading structural marker.
                continue;
            }
            if ($marker === '-'
                && $this->sourcePdfStandaloneWrappedWordHyphenProofAt($sourceItems, $sourceIndex) !== null) {
                // Exact triad geometry proves this occurrence is the painted
                // end of a wrapped word, not a structural bullet. Leave the
                // carrier and its provenance intact for the repair pass.
                continue;
            }

            $successorIndex = $sourceIndex + 1;
            if (!isset($sourceItems[$successorIndex])
                || $sourceItems[$successorIndex]['page'] !== $sourceItem['page']
                || $sourceItems[$successorIndex]['stream'] !== $sourceItem['stream']
                || trim($sourceItems[$successorIndex]['text']) === '') {
                continue;
            }

            $markerSourceIndexesBySuccessor[$successorIndex][] = [
                'sourceIndex' => $sourceIndex,
                'marker' => $marker,
            ];
        }
        if ($markerSourceIndexesBySuccessor === []) {
            return $items;
        }

        $prefixedMarkerSourceIndexes = [];
        foreach ($items as &$item) {
            if (isset($item['sourcePdfTableGroup'])) {
                continue;
            }
            $sourceStart = $item['sourcePdfSourceIndex'] ?? null;
            if (!is_int($sourceStart)) {
                continue;
            }
            foreach ($markerSourceIndexesBySuccessor as $successorIndex => $markers) {
                if ($successorIndex !== $sourceStart) {
                    continue;
                }
                $text = ltrim((string) ($item['text'] ?? ''));
                if ($text === '' || $this->listItem($text) !== null) {
                    continue;
                }
                foreach ($markers as $markerEntry) {
                    $text = $markerEntry['marker'] . ' ' . $text;
                    $prefixedMarkerSourceIndexes[(int) $markerEntry['sourceIndex']] = true;
                }
                $item['text'] = $text;
                $item['sourceStandaloneListMarkerPrefix'] = true;
                $item['forceBlockBreakBefore'] = true;
            }
        }
        unset($item);
        if ($prefixedMarkerSourceIndexes === []) {
            return $items;
        }

        return array_values(array_filter(
            $items,
            static function (array $item) use ($prefixedMarkerSourceIndexes): bool {
                $sourceIndex = $item['sourcePdfSourceIndex'] ?? null;

                return !is_int($sourceIndex) || !isset($prefixedMarkerSourceIndexes[$sourceIndex]);
            }
        ));
    }

    /**
     * A positioned text layer can omit a trailing styled run while the source
     * layer retains the full line. Restore that source text only when the
     * positioned fragment is a substantial prefix or suffix and its adjacent
     * source line proves the same visual baseline. This avoids treating a
     * similarly worded line elsewhere on a page as a replacement.
     *
     * @param list<array<string, mixed>> $ordered
     * @param list<array<string, mixed>> $fallback
     * @return array{0: list<array<string, mixed>>, 1: list<array<string, mixed>>}
     */
    private function restoreSourcePdfPartialSupplementalLines(array $ordered, array $fallback): array
    {
        $consumedFallback = [];
        foreach ($ordered as $orderedIndex => &$positioned) {
            if (($positioned['sourceSupplementalPositioned'] ?? false) !== true
                || !$this->pdfLayoutHasGeometry($positioned)
                || isset($positioned['sourcePdfTableGroup'])) {
                continue;
            }

            $bestFallbackIndex = null;
            $bestCoverage = 0.0;
            foreach ($fallback as $fallbackIndex => $source) {
                if (isset($consumedFallback[$fallbackIndex])
                    || !isset($source['sourcePdfSourceIndex'], $source['sourceStream'])
                    || isset($source['sourcePdfTableGroup'])
                    || ($source['page'] ?? null) !== ($positioned['page'] ?? null)
                    || (isset($positioned['sourceStream'])
                        && ($source['sourceStream'] ?? null) !== ($positioned['sourceStream'] ?? null))) {
                    continue;
                }

                $coverage = $this->sourcePdfTextCoverageForPartialSupplemental(
                    (string) ($source['text'] ?? ''),
                    (string) ($positioned['text'] ?? '')
                );
                if ($coverage <= $bestCoverage
                    || !$this->sourcePdfFallbackNeighborsSupplementalLayout($source, $positioned, $ordered)) {
                    continue;
                }

                $bestFallbackIndex = $fallbackIndex;
                $bestCoverage = $coverage;
            }

            if ($bestFallbackIndex === null) {
                continue;
            }

            $source = $fallback[$bestFallbackIndex];
            $positioned['text'] = (string) $source['text'];
            $positioned['sourceStream'] = $source['sourceStream'];
            $positioned['sourcePdfSourceIndex'] = $source['sourcePdfSourceIndex'];
            if (isset($source['sourcePdfSourceIndexEnd'])) {
                $positioned['sourcePdfSourceIndexEnd'] = $source['sourcePdfSourceIndexEnd'];
            }
            unset(
                $positioned['sourceSupplementalPositioned'],
                $positioned['sourceSupplementalBodyFlow'],
                $positioned['sourceSupplementalSourceOverlap'],
                $positioned['sourceSupplementalUrlOverlap'],
                $positioned['sourceShortSupplementalCandidate']
            );
            $positioned['sourceRecoveredPartialSupplemental'] = true;
            $ordered[$orderedIndex] = $positioned;
            $consumedFallback[$bestFallbackIndex] = true;
        }
        unset($positioned);

        if ($consumedFallback === []) {
            return [$ordered, $fallback];
        }

        return [
            $ordered,
            array_values(array_filter(
                $fallback,
                static fn (array $_source, int $index): bool => !isset($consumedFallback[$index]),
                ARRAY_FILTER_USE_BOTH
            )),
        ];
    }

    private function sourcePdfTextCoverageForPartialSupplemental(string $sourceText, string $positionedText): float
    {
        $source = $this->pdfComparableLineText($sourceText);
        $positioned = $this->pdfComparableLineText($positionedText);
        $sourceLength = $this->length($source);
        $positionedLength = $this->length($positioned);
        if ($sourceLength < 18
            || $positionedLength < 18
            || $sourceLength < $positionedLength
            || (!str_starts_with($source, $positioned) && !str_ends_with($source, $positioned))) {
            return 0.0;
        }

        $coverage = $positionedLength / $sourceLength;

        return $coverage >= 0.55 ? $coverage : 0.0;
    }

    /**
     * @param array<string, mixed> $source
     * @param array<string, mixed> $positioned
     * @param list<array<string, mixed>> $ordered
     */
    private function sourcePdfFallbackNeighborsSupplementalLayout(array $source, array $positioned, array $ordered): bool
    {
        $sourceIndex = (int) $source['sourcePdfSourceIndex'];
        foreach ($ordered as $neighbor) {
            if (($neighbor['sourceSupplementalPositioned'] ?? false) === true
                || !$this->pdfLayoutHasGeometry($neighbor)
                || ($neighbor['page'] ?? null) !== ($source['page'] ?? null)
                || ($neighbor['sourceStream'] ?? null) !== ($source['sourceStream'] ?? null)
                || !isset($neighbor['sourcePdfSourceIndex'])) {
                continue;
            }

            $neighborStart = (int) $neighbor['sourcePdfSourceIndex'];
            $neighborEnd = (int) ($neighbor['sourcePdfSourceIndexEnd'] ?? $neighborStart);
            $sourcePrecedesNeighbor = $neighborStart === $sourceIndex + 1;
            $sourceFollowsNeighbor = $neighborEnd === $sourceIndex - 1;
            if (!$sourcePrecedesNeighbor && !$sourceFollowsNeighbor) {
                continue;
            }

            $fontSize = max(1.0, (float) $positioned['fontSize'], (float) $neighbor['fontSize']);
            if (abs((float) $positioned['fontSize'] - (float) $neighbor['fontSize']) > max(1.5, $fontSize * 0.25)
                || abs((float) $positioned['x1'] - (float) $neighbor['x1']) > max(16.0, $fontSize * 1.5)) {
                continue;
            }

            $verticalStep = $sourcePrecedesNeighbor
                ? (float) $positioned['y1'] - (float) $neighbor['y1']
                : (float) $neighbor['y1'] - (float) $positioned['y1'];
            if ($verticalStep >= $fontSize * 0.30 && $verticalStep <= $fontSize * 2.80) {
                return true;
            }
        }

        return false;
    }

    /**
     * A short source-only continuation can be assigned a neighboring line's
     * geometry. When the source sequence before it has a substantial missing
     * span, that inferred placement cannot establish a complete prose flow.
     * Mark only this narrow shape and nearby positioned overlays in the same
     * lane; normal matched lines, captions, tables, and code remain intact.
     *
     * @param list<array<string, mixed>> $items
     * @param list<array{page: int, stream: int, text: string}> $sourceItems
     * @return list<array<string, mixed>>
     */
    private function markSourcePdfOrphanedInferredContinuations(array $items, array $sourceItems): array
    {
        $previousByFlow = [];
        $pendingPunctuationOrphans = [];
        $markedBounds = [];
        foreach ($items as $index => &$item) {
            if (!$this->pdfLayoutHasGeometry($item)
                || ($item['sourceStructuredGeometry'] ?? false) !== true
                || isset($item['sourcePdfTableGroup'])
                || ($item['code'] ?? false) === true
                || !isset($item['sourcePdfSourceIndex'], $item['sourceStream'], $item['sourceGeometryColumn'])) {
                continue;
            }

            $flow = implode(':', [
                (string) ($item['page'] ?? 0),
                (string) $item['sourceStream'],
                (string) $item['sourceGeometryColumn'],
            ]);
            $previousIndex = $previousByFlow[$flow] ?? null;
            $text = ltrim((string) ($item['text'] ?? ''));
            $startsContinuation = preg_match('/^(?:[^\p{L}\p{N}]*\p{Ll}|[,.;:\)\]\}])/u', $text) === 1;
            $short = count($this->pdfLineWordTokens($text)) <= 4;
            $inferred = ($item['sourceInferredNeighborLayout'] ?? false) === true;
            $orphaned = false;
            $inheritsPunctuationOrphan = false;
            if ($previousIndex !== null) {
                $previous = $items[$previousIndex];
                $inlineInferredFragment = $inferred
                    && ($previous['page'] ?? null) === ($item['page'] ?? null)
                    && ($previous['sourceGeometryColumn'] ?? null) === ($item['sourceGeometryColumn'] ?? null)
                    && abs((float) $previous['y1'] - (float) $item['y1'])
                        <= max(2.0, max((float) $previous['fontSize'], (float) $item['fontSize'], 1.0) * 0.45);
                if ($inlineInferredFragment) {
                    // A short source-only formula fragment can borrow a
                    // neighbor's line box while the positioned text already
                    // carries the complete visual line. It is not a broken
                    // column flow and must not trim the verified prose above.
                    $item['sourceInlineInferredFragment'] = true;
                    continue;
                }
                $previousEnd = (int) ($previous['sourcePdfSourceIndexEnd'] ?? $previous['sourcePdfSourceIndex']);
                $sourceIndex = (int) $item['sourcePdfSourceIndex'];
                $skippedSource = $sourceIndex > $previousEnd + 1
                    && ($previous['sourceSupplementalPositioned'] ?? false) !== true
                    && $this->sourcePdfSkippedSequenceContainsSubstantialText(
                        $sourceItems,
                        $previousEnd + 1,
                        $sourceIndex - 1,
                        (int) ($item['page'] ?? 0),
                        (int) $item['sourceStream']
                    );
                $continuesMarkedFlow = ($previous['sourceOrphanedInferredContinuation'] ?? false) === true
                    && $this->pdfComparableLineText((string) ($previous['text'] ?? '')) !== ''
                    && $startsContinuation
                    && $this->repairedPdfLayoutContinuesWrappedLine($previous, $item);
                $inheritsPunctuationOrphan = ($pendingPunctuationOrphans[$flow] ?? false) === true
                    && $startsContinuation
                    && $this->repairedPdfLayoutContinuesWrappedLine($previous, $item);
                $orphaned = ($inferred && $startsContinuation && $short && $skippedSource)
                    || ($inferred && $startsContinuation && $short && $continuesMarkedFlow)
                    || $inheritsPunctuationOrphan;
            }
            unset($pendingPunctuationOrphans[$flow]);

            if ($orphaned) {
                $item['sourceOrphanedInferredContinuation'] = true;
                $item['sourceOrphanedMissingSourceText'] = $skippedSource || $inheritsPunctuationOrphan;
                $item['sourceInterruptedColumnRegion'] = true;
                $item['forceBlockBreakBefore'] = true;
                if ($this->pdfComparableLineText((string) ($item['text'] ?? '')) === '') {
                    $pendingPunctuationOrphans[$flow] = true;
                }
                $bounds = $markedBounds[$flow] ?? [
                    'minY' => (float) $item['y1'],
                    'maxY' => (float) $item['y1'],
                    'fontSize' => max(1.0, (float) $item['fontSize']),
                ];
                $bounds['minY'] = min($bounds['minY'], (float) $item['y1']);
                $bounds['maxY'] = max($bounds['maxY'], (float) $item['y1']);
                $bounds['fontSize'] = max($bounds['fontSize'], (float) $item['fontSize']);
                $markedBounds[$flow] = $bounds;
            }
            $previousByFlow[$flow] = $index;
        }
        unset($item);

        if ($markedBounds === []) {
            return $items;
        }

        foreach ($items as &$item) {
            if (($item['sourceSupplementalPositioned'] ?? false) !== true
                || isset($item['sourcePdfTableGroup'])
                || ($item['code'] ?? false) === true
                || !$this->pdfLayoutHasGeometry($item)
                || !isset($item['sourceGeometryColumn'])) {
                continue;
            }
            $page = (string) ($item['page'] ?? 0);
            foreach ($markedBounds as $flow => $bounds) {
                [$flowPage, $_stream, $column] = explode(':', $flow, 3);
                if ($flowPage !== $page || (int) $column !== (int) $item['sourceGeometryColumn']) {
                    continue;
                }
                $tolerance = max(18.0, $bounds['fontSize'] * 2.0);
                if ((float) $item['y1'] >= $bounds['minY'] - $tolerance
                    && (float) $item['y1'] <= $bounds['maxY'] + $tolerance) {
                    $item['sourceOrphanedInferredContinuation'] = true;
                    $item['sourceInterruptedColumnRegion'] = true;
                    $item['forceBlockBreakBefore'] = true;
                    break;
                }
            }
        }
        unset($item);

        return $items;
    }

    /**
     * @param list<array{page: int, stream: int, text: string}> $sourceItems
     */
    private function sourcePdfSkippedSequenceContainsSubstantialText(
        array $sourceItems,
        int $start,
        int $end,
        int $page,
        int $stream
    ): bool {
        $characters = 0;
        $words = 0;
        for ($index = $start; $index <= $end; $index++) {
            $source = $sourceItems[$index] ?? null;
            if ($source === null
                || (int) ($source['page'] ?? 0) !== $page
                || (int) ($source['stream'] ?? 0) !== $stream) {
                continue;
            }
            $text = trim((string) ($source['text'] ?? ''));
            $characters += $this->length($this->pdfComparableLineText($text));
            $words += count($this->pdfLineWordTokens($text));
        }

        return $characters >= 12 || $words >= 3;
    }

    /**
     * A figure or state-machine diagram can begin with an inferred punctuation
     * fragment and then continue with compact assignment labels. That pattern
     * proves a damaged display flow, not ordinary prose. Once both pieces of
     * evidence occur in one visual lane, mark the bounded flow through its
     * next forced block boundary. A nearby unfinished predecessor is marked
     * too, preventing it from becoming fabricated prose after cleanup.
     *
     * @param list<array<string, mixed>> $items
     * @return list<array<string, mixed>>
     */
    private function propagateSourcePdfUnresolvedInterruptedFlows(array $items): array
    {
        $candidateFlows = [];
        $activeFlows = [];
        $activeLanes = [];
        foreach ($items as $index => $item) {
            if (!$this->pdfLayoutHasGeometry($item)
                || ($item['sourceStructuredGeometry'] ?? false) !== true
                || isset($item['sourcePdfTableGroup'])
                || ($item['code'] ?? false) === true
                || !isset($item['sourceGeometryColumn'])) {
                continue;
            }

            $lane = implode(':', [
                (string) ($item['page'] ?? 0),
                (string) $item['sourceGeometryColumn'],
            ]);
            $hasSourceFlow = isset($item['sourceStream']);
            $text = ltrim((string) ($item['text'] ?? ''));
            $startsWithOrphanedPunctuation = ($item['sourceInterruptedColumnRegion'] ?? false) === true
                && ($item['sourceInferredNeighborLayout'] ?? false) === true
                && preg_match('/^[,.;:\)\]\}]/u', $text) === 1;
            if (isset($activeLanes[$lane])) {
                if ($hasSourceFlow
                    && !$startsWithOrphanedPunctuation
                    && ($item['forceBlockBreakBefore'] ?? false) === true) {
                    unset($activeLanes[$lane]);
                    foreach ($activeFlows as $activeFlow => $_active) {
                        if (str_starts_with($activeFlow, $lane . ':')) {
                            unset($activeFlows[$activeFlow]);
                        }
                    }
                } else {
                    $items[$index]['sourceUnresolvedInterruptedFlow'] = true;
                    $items[$index]['sourceInterruptedColumnRegion'] = true;
                    if (!$hasSourceFlow) {
                        continue;
                    }
                }
            }
            if (!$hasSourceFlow) {
                continue;
            }

            $flow = implode(':', [
                (string) ($item['page'] ?? 0),
                (string) $item['sourceStream'],
                (string) $item['sourceGeometryColumn'],
            ]);

            if (isset($activeFlows[$flow])) {
                if (!$startsWithOrphanedPunctuation && ($item['forceBlockBreakBefore'] ?? false) === true) {
                    unset($activeFlows[$flow]);
                    unset($activeLanes[$lane]);
                    continue;
                }
                $items[$index]['sourceUnresolvedInterruptedFlow'] = true;
                $items[$index]['sourceInterruptedColumnRegion'] = true;
                continue;
            }

            if ($startsWithOrphanedPunctuation) {
                $candidateFlows[$flow] = ['indexes' => [$index]];
            } elseif (isset($candidateFlows[$flow])) {
                if (($item['forceBlockBreakBefore'] ?? false) === true
                    && ($item['sourceOrphanedInferredContinuation'] ?? false) !== true) {
                    unset($candidateFlows[$flow]);
                    continue;
                }
                $candidateFlows[$flow]['indexes'][] = $index;
                if (count($candidateFlows[$flow]['indexes']) > 12) {
                    unset($candidateFlows[$flow]);
                    continue;
                }
            } else {
                continue;
            }

            if (!isset($candidateFlows[$flow]) || !$this->sourcePdfTextContainsCompactAssignmentLabel($text)) {
                continue;
            }

            $candidateIndexes = $candidateFlows[$flow]['indexes'];
            foreach ($candidateIndexes as $candidateIndex) {
                $items[$candidateIndex]['sourceUnresolvedInterruptedFlow'] = true;
                $items[$candidateIndex]['sourceInterruptedColumnRegion'] = true;
            }
            $firstCandidateIndex = $candidateIndexes[0];
            $previous = $items[$firstCandidateIndex - 1] ?? null;
            if ($previous !== null
                && $this->sourcePdfRecordSharesVisualFlow($previous, $items[$firstCandidateIndex])
                && preg_match('/[.!?;:]\s*$/u', rtrim((string) ($previous['text'] ?? ''))) !== 1
                && $this->completePdfSentencePrefix((string) ($previous['text'] ?? '')) === '') {
                $previous['sourceUnresolvedInterruptedFlow'] = true;
                $previous['sourceInterruptedColumnRegion'] = true;
                $items[$firstCandidateIndex - 1] = $previous;
            }
            $activeFlows[$flow] = true;
            $activeLanes[$lane] = true;
            unset($candidateFlows[$flow]);
        }

        return $items;
    }

    private function sourcePdfTextContainsCompactAssignmentLabel(string $text): bool
    {
        return preg_match('/(?:^|[^\p{L}\p{N}])\p{L}{1,3}\s*=\s*\p{N}+(?=[^\p{L}\p{N}]|$)/u', $text) === 1;
    }

    /**
     * @param array<string, mixed> $left
     * @param array<string, mixed> $right
     */
    private function sourcePdfRecordSharesVisualFlow(array $left, array $right): bool
    {
        return $this->pdfLayoutHasGeometry($left)
            && $this->pdfLayoutHasGeometry($right)
            && ($left['page'] ?? null) === ($right['page'] ?? null)
            && ($left['sourceStream'] ?? null) === ($right['sourceStream'] ?? null)
            && ($left['sourceGeometryColumn'] ?? null) === ($right['sourceGeometryColumn'] ?? null)
            && !isset($left['sourcePdfTableGroup'])
            && ($left['code'] ?? false) !== true;
    }

    /**
     * A content stream can paint one normal body line out of visual order when
     * a page also contains map panels or sidebars. Restore only immediately
     * adjacent source records when their geometry proves they are consecutive
     * lines in the same body lane. This does not use sentence vocabulary and
     * leaves independently positioned columns untouched.
     *
     * @param list<array<string, mixed>> $items
     * @param list<array{page: int, stream: int, text: string}> $sourceItems
     * @return list<array<string, mixed>>
     */
    private function restoreSourcePdfAdjacentVisualContinuations(array $items, array $sourceItems = []): array
    {
        $sourceSuccessorCounts = [];
        foreach ($items as $candidate) {
            if (!isset($candidate['page'], $candidate['sourceStream'])
                || !is_int($candidate['sourcePdfSourceIndex'] ?? null)) {
                continue;
            }
            $key = implode("\0", [
                (string) $candidate['page'],
                (string) $candidate['sourceStream'],
                (string) $candidate['sourcePdfSourceIndex'],
            ]);
            $sourceSuccessorCounts[$key] = ($sourceSuccessorCounts[$key] ?? 0) + 1;
        }
        $count = count($items);
        for ($index = 0; $index < $count; $index++) {
            $item = $items[$index];
            if (!$this->pdfLayoutHasGeometry($item)
                || isset($item['sourcePdfTableGroup'], $item['sourceSupplementalPositioned'])
                || !isset($item['sourcePdfSourceIndex'], $item['sourceStream'])) {
                continue;
            }

            $expectedSourceIndex = (int) ($item['sourcePdfSourceIndexEnd'] ?? $item['sourcePdfSourceIndex']) + 1;
            $immediate = $items[$index + 1] ?? null;
            if (is_array($immediate)
                && $this->sourcePdfItemsShareVerifiedCrossColumnContinuationProof($item, $immediate)) {
                $interveningMinorPanel = false;
                for ($followingIndex = $index + 2; $followingIndex < $count; $followingIndex++) {
                    $candidate = $items[$followingIndex];
                    if (($candidate['sourcePdfSourceIndex'] ?? null) !== $expectedSourceIndex) {
                        continue;
                    }
                    $interveningMinorPanel = isset($sourceItems[$expectedSourceIndex])
                        && $this->sourcePdfItemIsExactMinorFontPanelSuccessor(
                            $candidate,
                            $sourceItems[$expectedSourceIndex],
                            $expectedSourceIndex
                        );
                    break;
                }
                if ($interveningMinorPanel) {
                    // Content order may place a footnote marker immediately
                    // after the body tail even though exact column geometry
                    // proves that the next body column continues first. Do
                    // not move that panel back inside the bound visual edge.
                    continue;
                }
            }
            if (is_array($immediate)
                && ($immediate['sourcePdfSourceIndex'] ?? null) === $expectedSourceIndex
                && ($immediate['page'] ?? null) === ($item['page'] ?? null)
                && ($immediate['sourceStream'] ?? null) === ($item['sourceStream'] ?? null)
                && ($this->sourcePdfItemsAreAdjacentVisualContinuation(
                    $item,
                    $immediate,
                    $expectedSourceIndex
                ) || ($sourceItems !== []
                    && $this->sourcePdfItemsAreAdjacentSourceContinuation(
                        $item,
                        $immediate,
                        $expectedSourceIndex,
                        $sourceItems
                    )))) {
                // The ordinary body successor is already adjacent. A source-
                // adjacent small panel is not enough for this shortcut: the
                // body continuation may be a later exact occurrence across
                // that panel.
                continue;
            }
            $expectedKey = implode("\0", [
                (string) $item['page'],
                (string) $item['sourceStream'],
                (string) $expectedSourceIndex,
            ]);
            if (($sourceSuccessorCounts[$expectedKey] ?? 0) !== 1) {
                // A missing or duplicate successor cannot establish a unique
                // occurrence-local move. Leave the visual order untouched.
                continue;
            }
            $candidateIndex = null;
            $sourceContinuation = false;
            $crossPanelContinuationProof = null;
            for ($followingIndex = $index + 2; $followingIndex < $count; $followingIndex++) {
                $candidate = $items[$followingIndex];
                $isVisualContinuation = $this->sourcePdfItemsAreAdjacentVisualContinuation(
                    $item,
                    $candidate,
                    $expectedSourceIndex
                );
                $isSourceContinuation = !$isVisualContinuation
                    && $sourceItems !== []
                    && $this->sourcePdfItemsAreAdjacentSourceContinuation(
                        $item,
                        $candidate,
                        $expectedSourceIndex,
                        $sourceItems
                    );
                $positionedColumnWrapProof = !$isVisualContinuation
                    && !$isSourceContinuation
                    && $sourceItems !== []
                    ? $this->sourcePdfExactPositionedColumnWrapContinuationProof(
                        $item,
                        $candidate,
                        $expectedSourceIndex,
                        $sourceItems,
                        $items,
                        $followingIndex
                    )
                    : null;
                $isPanelSeparatedContinuation = !$isVisualContinuation
                    && !$isSourceContinuation
                    && $positionedColumnWrapProof === null
                    && $sourceItems !== []
                    && $this->sourcePdfItemsArePanelSeparatedSourceContinuation(
                        $item,
                        $candidate,
                        $sourceItems,
                        $items
                    );
                if (!$isVisualContinuation
                    && !$isSourceContinuation
                    && $positionedColumnWrapProof === null
                    && !$isPanelSeparatedContinuation) {
                    continue;
                }
                if ($isPanelSeparatedContinuation) {
                    $candidateKey = implode("\0", [
                        (string) $candidate['page'],
                        (string) $candidate['sourceStream'],
                        (string) $candidate['sourcePdfSourceIndex'],
                    ]);
                    if (($sourceSuccessorCounts[$candidateKey] ?? 0) !== 1) {
                        // A panel-crossing target is not the immediate source
                        // successor, so validate its own occurrence key too.
                        // Duplicate candidates make the move ambiguous.
                        continue;
                    }
                }
                $candidateIndex = $followingIndex;
                $sourceContinuation = $isSourceContinuation
                    || $positionedColumnWrapProof !== null
                    || $isPanelSeparatedContinuation;
                $crossPanelContinuationProof = $positionedColumnWrapProof;
                break;
            }
            if ($candidateIndex === null) {
                continue;
            }

            $continuationBlock = [$items[$candidateIndex]];
            if (is_array($crossPanelContinuationProof)) {
                $memberProofs = $crossPanelContinuationProof['continuationMembers'] ?? null;
                if (!is_array($memberProofs) || !array_is_list($memberProofs) || $memberProofs === []) {
                    continue;
                }
                $continuationBlock = array_slice($items, $candidateIndex, count($memberProofs));
                if (count($continuationBlock) !== count($memberProofs)) {
                    continue;
                }
                foreach ($continuationBlock as $memberOrdinal => $member) {
                    if (($member['id'] ?? null)
                        !== ($memberProofs[$memberOrdinal]['sourceOccurrenceId'] ?? null)) {
                        continue 2;
                    }
                }
            }
            if ($sourceContinuation) {
                unset($continuationBlock[0]['forceBlockBreakBefore']);
                $continuationBlock[0]['sourcePdfCrossPanelContinuation'] = true;
            }
            if (is_array($crossPanelContinuationProof)) {
                $items[$index]['sourcePdfCrossPanelContinuationTail'] = true;
                $items[$index]['sourcePdfCrossPanelContinuationProof'] = $crossPanelContinuationProof;
                foreach ($continuationBlock as $memberOrdinal => &$member) {
                    $member['sourcePdfCrossPanelContinuationProof'] = $crossPanelContinuationProof;
                    $member['sourcePdfCrossPanelContinuationMemberOrdinal'] = $memberOrdinal;
                }
                unset($member);
            }
            array_splice($items, $candidateIndex, count($continuationBlock));
            array_splice($items, $index + 1, 0, $continuationBlock);
            $count = count($items);
        }

        return $items;
    }

    /**
     * Bind a deferred minor-font successor to its immutable source occurrence
     * before allowing it to remain outside a proved body-column edge. A copied
     * role flag or a similar marker elsewhere cannot satisfy the exact range
     * and source-geometry equality.
     *
     * @param array<string,mixed> $item
     * @param array<string,mixed> $sourceItem
     */
    private function sourcePdfItemIsExactMinorFontPanelSuccessor(
        array $item,
        array $sourceItem,
        int $sourceIndex
    ): bool {
        if (($item['sourceMinorFontFlow'] ?? false) !== true
            || !$this->sourcePdfSourceItemHasExactGeometry($sourceItem)
            || !$this->sourcePdfItemMatchesWholeExactSourceRangeOccurrence(
                $item,
                $sourceItem,
                $sourceIndex
            )) {
            return false;
        }
        $sourceGeometry = $sourceItem['sourceGeometry'];
        $itemGeometry = [
            'page' => (int) $sourceItem['page'],
            'stream' => (int) $sourceItem['stream'],
            'x1' => (float) $item['x1'],
            'y1' => (float) $item['y1'],
            'x2' => (float) $item['x2'],
            'y2' => (float) $item['y2'],
            'orientation' => 'horizontal',
        ];

        return hash_equals(
            $this->sourcePdfExactGeometryProofDigest($sourceGeometry),
            $this->sourcePdfExactGeometryProofDigest($itemGeometry)
        );
    }

    /**
     * @param array<string, mixed> $previous
     * @param array<string, mixed> $candidate
     */
    private function sourcePdfItemsAreAdjacentVisualContinuation(
        array $previous,
        array $candidate,
        int $expectedSourceIndex
    ): bool {
        if (!$this->pdfLayoutHasGeometry($previous)
            || !$this->pdfLayoutHasGeometry($candidate)
            || isset($candidate['sourcePdfTableGroup'], $candidate['sourceSupplementalPositioned'])
            || ($candidate['sourcePdfSourceIndex'] ?? null) !== $expectedSourceIndex
            || ($candidate['page'] ?? null) !== ($previous['page'] ?? null)
            || ($candidate['sourceStream'] ?? null) !== ($previous['sourceStream'] ?? null)
            || preg_match('/[.!?;:]\s*$/u', rtrim((string) ($previous['text'] ?? ''))) === 1
            || $this->lineHasPdfListBlockEvidence((string) ($previous['text'] ?? ''))
            || $this->lineHasPdfListBlockEvidence((string) ($candidate['text'] ?? ''))) {
            return false;
        }

        $fontSize = max(1.0, (float) $previous['fontSize'], (float) $candidate['fontSize']);
        $verticalStep = (float) $previous['y1'] - (float) $candidate['y1'];
        if ($verticalStep < $fontSize * 0.30 || $verticalStep > $fontSize * 2.4) {
            return false;
        }

        return abs((float) $previous['x1'] - (float) $candidate['x1']) <= max(16.0, $fontSize * 2.0);
    }

    /**
     * @param array<string, mixed> $previous
     * @param array<string, mixed> $candidate
     */
    private function sourcePdfItemsAreAdjacentSourceContinuation(
        array $previous,
        array $candidate,
        int $expectedSourceIndex,
        array $sourceItems
    ): bool {
        if (isset($previous['sourcePdfTableGroup'], $candidate['sourcePdfTableGroup'])
            || ($previous['sourceSupplementalPositioned'] ?? false) === true
            || ($candidate['sourceSupplementalPositioned'] ?? false) === true
            || !isset($previous['sourcePdfSourceIndex'], $previous['sourceStream'])
            || ($candidate['sourcePdfSourceIndex'] ?? null) !== $expectedSourceIndex
            || ($candidate['page'] ?? null) !== ($previous['page'] ?? null)
            || ($candidate['sourceStream'] ?? null) !== ($previous['sourceStream'] ?? null)
            || preg_match('/[.!?;:]\s*$/u', rtrim((string) ($previous['text'] ?? ''))) === 1
            || $this->lineHasPdfListBlockEvidence((string) ($previous['text'] ?? ''))
            || $this->lineHasPdfListBlockEvidence((string) ($candidate['text'] ?? ''))
            || $this->lineLooksLikeUrlOnly((string) ($previous['text'] ?? ''))
            || $this->lineLooksLikeUrlOnly((string) ($candidate['text'] ?? ''))) {
            return false;
        }

        $previousStart = (int) $previous['sourcePdfSourceIndex'];
        $previousEnd = (int) ($previous['sourcePdfSourceIndexEnd'] ?? $previousStart);
        $candidateStart = (int) $candidate['sourcePdfSourceIndex'];
        $candidateEnd = (int) ($candidate['sourcePdfSourceIndexEnd'] ?? $candidateStart);
        if ($previousStart !== $previousEnd
            || $candidateStart !== $candidateEnd
            || !isset($sourceItems[$previousStart], $sourceItems[$candidateStart])
            || !$this->sourcePdfItemMatchesWholeExactSourceOccurrence(
                $previous,
                $sourceItems[$previousStart],
                $previousStart,
                false
            )
            || !$this->sourcePdfItemMatchesWholeExactSourceOccurrence(
                $candidate,
                $sourceItems[$candidateStart],
                $candidateStart,
                true
            )) {
            return false;
        }

        return preg_match('/^[^\p{L}\p{N}]*\p{Ll}/u', ltrim((string) ($candidate['text'] ?? ''))) === 1;
    }

    /**
     * Bind a whole-source positioned line at the bottom of one body column to
     * its exact lower-case successor at the top of the next. This complements
     * the exact-geometry-fallback path above: some PDFs expose both endpoints
     * as positioned carriers while painting an unrelated footer panel between
     * them. Source adjacency is accepted only with a narrow horizontal column
     * step, a substantial vertical wrap, comparable typography, and immutable
     * source occurrence identities for both endpoints.
     *
     * @param array<string,mixed> $previous
     * @param array<string,mixed> $candidate
     * @param list<array<string,mixed>> $sourceItems
     * @param list<array<string,mixed>> $items
     * @return array<string,mixed>|null
     */
    private function sourcePdfExactPositionedColumnWrapContinuationProof(
        array $previous,
        array $candidate,
        int $expectedSourceIndex,
        array $sourceItems,
        array $items,
        int $candidateVisualIndex
    ): ?array {
        if (!$this->pdfLayoutHasGeometry($previous)
            || !$this->pdfLayoutHasGeometry($candidate)
            || isset($previous['sourcePdfTableGroup'], $candidate['sourcePdfTableGroup'])
            || ($previous['sourceSupplementalPositioned'] ?? false) === true
            || ($candidate['sourceSupplementalPositioned'] ?? false) === true
            || ($previous['sourcePdfExactPositionedText'] ?? false) !== true
            || ($candidate['sourcePdfExactPositionedText'] ?? false) !== true
            || ($previous['sourceVerifiedGeometryText'] ?? false) !== true
            || ($candidate['sourceVerifiedGeometryText'] ?? false) !== true
            || ($previous['pdfPrimaryOrientation'] ?? false) !== true
            || ($candidate['pdfPrimaryOrientation'] ?? false) !== true
            || !is_numeric($previous['pdfTextRotation'] ?? null)
            || !is_numeric($candidate['pdfTextRotation'] ?? null)
            || abs((float) $previous['pdfTextRotation']) > 0.0001
            || abs((float) $candidate['pdfTextRotation']) > 0.0001
            || ($previous['code'] ?? false) === true
            || ($candidate['code'] ?? false) === true
            || !in_array((string) ($previous['pdfTextOrientation'] ?? 'horizontal'), ['', 'horizontal', 'r0'], true)
            || !in_array((string) ($candidate['pdfTextOrientation'] ?? 'horizontal'), ['', 'horizontal', 'r0'], true)
            || !isset(
                $previous['sourceOrderStart'],
                $previous['sourceOrderEnd'],
                $candidate['sourceOrderStart'],
                $candidate['sourceOrderEnd']
            )
            || !isset($previous['sourcePdfSourceIndex'], $previous['sourceStream'])
            || ($candidate['sourcePdfSourceIndex'] ?? null) !== $expectedSourceIndex
            || ($candidate['page'] ?? null) !== ($previous['page'] ?? null)
            || ($candidate['sourceStream'] ?? null) !== ($previous['sourceStream'] ?? null)
            || preg_match('/[.!?;:]\s*$/u', rtrim((string) ($previous['text'] ?? ''))) === 1
            || preg_match('/^[^\p{L}\p{N}]*\p{Ll}/u', ltrim((string) ($candidate['text'] ?? ''))) !== 1
            || $this->length($this->pdfComparableLineText((string) ($previous['text'] ?? ''))) < 24
            || $this->length($this->pdfComparableLineText((string) ($candidate['text'] ?? ''))) < 24
            || count($this->pdfLineWordTokens((string) ($previous['text'] ?? ''))) < 4
            || count($this->pdfLineWordTokens((string) ($candidate['text'] ?? ''))) < 4
            || $this->lineHasPdfListBlockEvidence((string) ($previous['text'] ?? ''))
            || $this->lineHasPdfListBlockEvidence((string) ($candidate['text'] ?? ''))
            || $this->lineLooksLikeUrlOnly((string) ($previous['text'] ?? ''))
            || $this->lineLooksLikeUrlOnly((string) ($candidate['text'] ?? ''))) {
            return null;
        }

        $previousStart = (int) $previous['sourcePdfSourceIndex'];
        $previousEnd = (int) ($previous['sourcePdfSourceIndexEnd'] ?? $previousStart);
        $candidateStart = (int) $candidate['sourcePdfSourceIndex'];
        $candidateEnd = (int) ($candidate['sourcePdfSourceIndexEnd'] ?? $candidateStart);
        $previousSource = $sourceItems[$previousStart] ?? null;
        if ($previousStart !== $previousEnd
            || $candidateStart !== $candidateEnd
            || $candidateStart !== $previousEnd + 1
            || !is_array($previousSource)
            || !$this->sourcePdfPositionedColumnWrapGeometryMatches($previous, $candidate)
            || (int) $candidate['sourceOrderStart'] !== (int) $previous['sourceOrderEnd'] + 1) {
            return null;
        }

        $predecessorEndpoint = $this->sourcePdfPositionedContinuationProofEndpoint(
            $previous,
            $previousSource,
            $previousStart,
            true
        );
        if ($predecessorEndpoint === null) {
            return null;
        }

        $continuationMembers = [];
        $priorMember = null;
        $terminalMemberFound = false;
        for ($offset = 0; $offset < 8; $offset++) {
            $memberIndex = $candidateVisualIndex + $offset;
            $memberSourceIndex = $candidateStart + $offset;
            $member = $items[$memberIndex] ?? null;
            $memberSource = $sourceItems[$memberSourceIndex] ?? null;
            if (!is_array($member) || !is_array($memberSource)) {
                break;
            }
            $endpoint = $this->sourcePdfPositionedContinuationProofEndpoint(
                $member,
                $memberSource,
                $memberSourceIndex,
                $offset === 0
            );
            if ($endpoint === null) {
                break;
            }
            if ($offset === 0) {
                if (($member['id'] ?? null) !== ($candidate['id'] ?? null)) {
                    break;
                }
            } elseif ($priorMember === null
                || !$this->sourcePdfPositionedContinuationRunMembersAreAdjacent(
                    $priorMember,
                    $member
                )) {
                break;
            }
            $continuationMembers[] = $endpoint;
            $priorMember = $member;
            if (preg_match('/[.!?]\s*$/u', rtrim((string) ($member['text'] ?? ''))) === 1) {
                $terminalMemberFound = true;
                break;
            }
        }
        if (!$terminalMemberFound || $continuationMembers === []) {
            return null;
        }

        $proof = [
            'version' => 1,
            'method' => 'whole-source-positioned-column-wrap-continuation',
            'sourceSha256' => $this->sourceSha256,
            'page' => (int) $previous['page'],
            'sourceStream' => (int) $previous['sourceStream'],
            'predecessor' => $predecessorEndpoint,
            'continuationMembers' => $continuationMembers,
        ];
        $proof['proofDigest'] = hash('sha256', json_encode(
            $proof,
            JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_PRESERVE_ZERO_FRACTION
        ) ?: '');

        return $proof;
    }

    /**
     * @param array<string,mixed> $item
     * @param array<string,mixed> $sourceItem
     * @return array<string,mixed>|null
     */
    private function sourcePdfPositionedContinuationProofEndpoint(
        array $item,
        array $sourceItem,
        int $pageLocalSourceIndex,
        bool $requireVerifiedGeometry
    ): ?array {
        if (!$this->pdfLayoutHasGeometry($item)
            || ($item['sourcePdfExactPositionedText'] ?? false) !== true
            || ($requireVerifiedGeometry
                && ($item['sourceVerifiedGeometryText'] ?? false) !== true)
            || ($item['pdfPrimaryOrientation'] ?? false) !== true
            || !is_numeric($item['pdfTextRotation'] ?? null)
            || abs((float) $item['pdfTextRotation']) > 0.0001
            || ($item['code'] ?? false) === true
            || isset($item['sourcePdfTableGroup'])
            || ($item['sourceSupplementalPositioned'] ?? false) === true
            || ($item['forceBlockBreakBefore'] ?? false) === true
            || $this->lineHasPdfListBlockEvidence((string) ($item['text'] ?? ''))
            || $this->lineLooksLikeUrlOnly((string) ($item['text'] ?? ''))
            || !in_array((string) ($item['pdfTextOrientation'] ?? 'horizontal'), ['', 'horizontal', 'r0'], true)
            || !isset($item['sourceOrderStart'], $item['sourceOrderEnd'])
            || !$this->sourcePdfItemMatchesWholeExactSourceOccurrence(
                $item,
                $sourceItem,
                $pageLocalSourceIndex,
                false
            )) {
            return null;
        }
        $sourceId = is_string($sourceItem['id'] ?? null) ? $sourceItem['id'] : '';
        $ranges = $this->pdfPositionedExactSourceRanges($item);
        $globalSourceIndex = is_int($item['sourcePdfGlobalSourceIndex'] ?? null)
            ? $item['sourcePdfGlobalSourceIndex']
            : null;
        $pageLocalSourceIndexEnd = is_int($item['sourcePdfSourceIndexEnd'] ?? null)
            ? $item['sourcePdfSourceIndexEnd']
            : $pageLocalSourceIndex;
        if ($sourceId === ''
            || ($item['id'] ?? null) !== $sourceId
            || count($ranges) !== 1
            || $globalSourceIndex === null
            || $globalSourceIndex !== $ranges[0]['sourceIndex']
            || $pageLocalSourceIndexEnd !== $pageLocalSourceIndex) {
            return null;
        }

        return [
            'sourceOccurrenceId' => $sourceId,
            'pageLocalSourceIndex' => $pageLocalSourceIndex,
            'pageLocalSourceIndexEnd' => $pageLocalSourceIndexEnd,
            'globalSourceIndex' => $globalSourceIndex,
            'range' => $ranges[0],
            'projectionDigest' => hash('sha256', $this->pdfSourceOccurrenceComparableText(
                (string) $item['text']
            )),
            'geometryDigest' => $this->sourcePdfCrossPanelContinuationGeometryDigest($item),
            'sourceOrderStart' => (int) $item['sourceOrderStart'],
            'sourceOrderEnd' => (int) $item['sourceOrderEnd'],
        ];
    }

    /** @param array<string,mixed> $previous @param array<string,mixed> $candidate */
    private function sourcePdfPositionedContinuationRunMembersAreAdjacent(
        array $previous,
        array $candidate
    ): bool {
        if (!$this->pdfLayoutHasGeometry($previous)
            || !$this->pdfLayoutHasGeometry($candidate)
            || ($candidate['page'] ?? null) !== ($previous['page'] ?? null)
            || ($candidate['sourceStream'] ?? null) !== ($previous['sourceStream'] ?? null)
            || (int) ($candidate['sourcePdfSourceIndex'] ?? -1)
                !== (int) ($previous['sourcePdfSourceIndexEnd'] ?? $previous['sourcePdfSourceIndex'] ?? -2) + 1
            || (int) ($candidate['sourceOrderStart'] ?? -1)
                !== (int) ($previous['sourceOrderEnd'] ?? -2) + 1
            || ($candidate['forceBlockBreakBefore'] ?? false) === true) {
            return false;
        }
        $fontSize = max(1.0, (float) $previous['fontSize'], (float) $candidate['fontSize']);
        $verticalStep = (float) $previous['y1'] - (float) $candidate['y1'];

        return abs((float) $candidate['fontSize'] - (float) $previous['fontSize'])
                <= max(1.0, $fontSize * 0.15)
            && abs((float) $candidate['x1'] - (float) $previous['x1'])
                <= max(8.0, $fontSize)
            && $verticalStep >= $fontSize * 0.30
            && $verticalStep <= $fontSize * 2.40;
    }

    /** @param array<string,mixed> $previous @param array<string,mixed> $candidate */
    private function sourcePdfPositionedColumnWrapGeometryMatches(
        array $previous,
        array $candidate
    ): bool {
        if (!$this->pdfLayoutHasGeometry($previous) || !$this->pdfLayoutHasGeometry($candidate)) {
            return false;
        }
        $fontSize = max(1.0, (float) $previous['fontSize'], (float) $candidate['fontSize']);
        $previousWidth = max(1.0, (float) $previous['x2'] - (float) $previous['x1']);
        $candidateWidth = max(1.0, (float) $candidate['x2'] - (float) $candidate['x1']);
        $horizontalGap = (float) $candidate['x1'] - (float) $previous['x2'];

        return abs((float) $previous['fontSize'] - (float) $candidate['fontSize'])
                <= max(1.25, $fontSize * 0.20)
            && $horizontalGap >= -$fontSize * 2.0
            && $horizontalGap <= $fontSize * 4.0
            && (float) $candidate['x1'] > (float) $previous['x1'] + $fontSize * 6.0
            && (float) $candidate['y1'] - (float) $previous['y1']
                >= max(24.0, $fontSize * 3.0)
            && $candidateWidth / $previousWidth >= 0.60
            && $candidateWidth / $previousWidth <= 1.60;
    }

    /** @param array<string,mixed> $layout */
    private function sourcePdfCrossPanelContinuationGeometryDigest(array $layout): string
    {
        $payload = [
            'page' => (int) ($layout['page'] ?? 0),
            'sourceStream' => (int) ($layout['sourceStream'] ?? 0),
            'x1' => (float) ($layout['x1'] ?? 0.0),
            'y1' => (float) ($layout['y1'] ?? 0.0),
            'x2' => (float) ($layout['x2'] ?? 0.0),
            'y2' => (float) ($layout['y2'] ?? 0.0),
            'fontSize' => (float) ($layout['fontSize'] ?? 0.0),
            'pdfTextOrientation' => (string) ($layout['pdfTextOrientation'] ?? ''),
            'pdfTextRotation' => (float) ($layout['pdfTextRotation'] ?? 0.0),
            'pdfPrimaryOrientation' => ($layout['pdfPrimaryOrientation'] ?? false) === true,
        ];

        return hash('sha256', json_encode(
            $payload,
            JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_PRESERVE_ZERO_FRACTION
        ) ?: '');
    }

    /**
     * @param array<string, mixed> $item
     * @param array<string, mixed> $sourceItem
     */
    private function sourcePdfItemMatchesWholeExactSourceOccurrence(
        array $item,
        array $sourceItem,
        int $pageLocalSourceIndex,
        bool $requireExactGeometryFallback
    ): bool {
        if (!$this->sourcePdfItemMatchesWholeExactSourceRangeOccurrence(
            $item,
            $sourceItem,
            $pageLocalSourceIndex
        )) {
            return false;
        }

        if (!$requireExactGeometryFallback) {
            return ($item['sourcePdfExactPositionedText'] ?? false) === true;
        }

        return ($item['sourcePdfExactGeometryFallback'] ?? false) === true
            && ($item['sourceGeometryMethod'] ?? null) === 'exact-page-stream-character-offset'
            && is_array($item['sourceGeometry'] ?? null)
            && $this->pdfSourceBoundsAreValid($item['sourceGeometry'])
            && ($item['sourceGeometry']['orientation'] ?? null) === 'horizontal';
    }

    /**
     * Match the immutable whole-source occurrence fields without accepting a
     * transferable carrier-role flag as proof of exact positioning.
     *
     * @param array<string,mixed> $item
     * @param array<string,mixed> $sourceItem
     */
    private function sourcePdfItemMatchesWholeExactSourceRangeOccurrence(
        array $item,
        array $sourceItem,
        int $pageLocalSourceIndex
    ): bool {
        $sourceSignificant = $this->pdfSourceOccurrenceComparableText(
            (string) ($sourceItem['text'] ?? '')
        );
        $itemSignificant = $this->pdfSourceOccurrenceComparableText(
            (string) ($item['text'] ?? '')
        );
        $globalSourceIndex = is_int($sourceItem['sourcePdfGlobalSourceIndex'] ?? null)
            ? $sourceItem['sourcePdfGlobalSourceIndex']
            : $pageLocalSourceIndex;
        $ranges = $this->pdfPositionedExactSourceRanges($item);
        if ($sourceSignificant === ''
            || !hash_equals($sourceSignificant, $itemSignificant)
            || ($item['page'] ?? null) !== ($sourceItem['page'] ?? null)
            || ($item['sourceStream'] ?? null) !== ($sourceItem['stream'] ?? null)
            || count($ranges) !== 1
            || $ranges[0]['sourceIndex'] !== $globalSourceIndex
            || $ranges[0]['sourceStart'] !== 0
            || $ranges[0]['sourceEnd'] !== strlen($sourceSignificant)) {
            return false;
        }

        return true;
    }

    /**
     * A page footer or side panel may sit in the source stream between the
     * final line of one body column and the lower-case continuation at the
     * top of the next. Continue across that panel only when its smaller text
     * is physically below the body line and the surrounding columns and
     * typography prove the normal multi-column reading flow.
     *
     * @param array<string, mixed> $previous
     * @param array<string, mixed> $candidate
     * @param list<array{page: int, stream: int, text: string}> $sourceItems
     * @param list<array<string, mixed>> $items
     */
    private function sourcePdfItemsArePanelSeparatedSourceContinuation(
        array $previous,
        array $candidate,
        array $sourceItems,
        array $items
    ): bool {
        if (!$this->pdfLayoutHasGeometry($previous)
            || !$this->pdfLayoutHasGeometry($candidate)
            || isset($previous['sourcePdfTableGroup'], $candidate['sourcePdfTableGroup'])
            || ($previous['sourceSupplementalPositioned'] ?? false) === true
            || ($candidate['sourceSupplementalPositioned'] ?? false) === true
            || !isset(
                $previous['sourcePdfSourceIndex'],
                $previous['sourceStream'],
                $previous['sourceGeometryColumn'],
                $candidate['sourcePdfSourceIndex'],
                $candidate['sourceGeometryColumn']
            )
            || ($previous['page'] ?? null) !== ($candidate['page'] ?? null)
            || ($previous['sourceStream'] ?? null) !== ($candidate['sourceStream'] ?? null)
            || (int) $candidate['sourceGeometryColumn'] !== (int) $previous['sourceGeometryColumn'] + 1
            || preg_match('/[.!?;:]\s*$/u', rtrim((string) ($previous['text'] ?? ''))) === 1
            || preg_match('/^[^\p{L}\p{N}]*\p{Ll}/u', ltrim((string) ($candidate['text'] ?? ''))) !== 1
            || $this->lineHasPdfListBlockEvidence((string) ($previous['text'] ?? ''))
            || $this->lineHasPdfListBlockEvidence((string) ($candidate['text'] ?? ''))
            || $this->lineLooksLikeUrlOnly((string) ($previous['text'] ?? ''))
            || $this->lineLooksLikeUrlOnly((string) ($candidate['text'] ?? ''))) {
            return false;
        }

        $previousEnd = (int) ($previous['sourcePdfSourceIndexEnd'] ?? $previous['sourcePdfSourceIndex']);
        $candidateStart = (int) $candidate['sourcePdfSourceIndex'];
        if ($candidateStart <= $previousEnd + 1 || $candidateStart - $previousEnd > 16) {
            return false;
        }
        $previousStart = (int) $previous['sourcePdfSourceIndex'];
        $candidateEnd = (int) ($candidate['sourcePdfSourceIndexEnd'] ?? $candidateStart);
        if ($previousStart !== $previousEnd
            || $candidateStart !== $candidateEnd
            || !isset($sourceItems[$previousStart], $sourceItems[$candidateStart])
            || !$this->sourcePdfItemMatchesWholeExactSourceOccurrence(
                $previous,
                $sourceItems[$previousStart],
                $previousStart,
                false
            )
            || !$this->sourcePdfItemMatchesWholeExactSourceOccurrence(
                $candidate,
                $sourceItems[$candidateStart],
                $candidateStart,
                false
            )) {
            return false;
        }

        $fontSize = max(1.0, (float) $previous['fontSize'], (float) $candidate['fontSize']);
        if (abs((float) $previous['fontSize'] - (float) $candidate['fontSize']) > max(1.25, $fontSize * 0.20)
            || (float) $candidate['y1'] - (float) $previous['y1'] <= max(24.0, $fontSize * 3.0)) {
            return false;
        }

        $interveningSourceCount = 0;
        for ($index = $previousEnd + 1; $index < $candidateStart; $index++) {
            $source = $sourceItems[$index] ?? null;
            if ($source === null
                || ($source['page'] ?? null) !== ($previous['page'] ?? null)
                || ($source['stream'] ?? null) !== ($previous['sourceStream'] ?? null)) {
                return false;
            }
            $interveningSourceCount++;
        }
        if ($interveningSourceCount < 3) {
            return false;
        }

        $panelItems = [];
        foreach ($items as $item) {
            if (!$this->pdfLayoutHasGeometry($item)
                || ($item['page'] ?? null) !== ($previous['page'] ?? null)
                || ($item['sourceStream'] ?? null) !== ($previous['sourceStream'] ?? null)
                || !isset($item['sourcePdfSourceIndex'])) {
                continue;
            }
            $itemStart = (int) $item['sourcePdfSourceIndex'];
            $itemEnd = (int) ($item['sourcePdfSourceIndexEnd'] ?? $itemStart);
            if ($itemEnd < $previousEnd + 1 || $itemStart >= $candidateStart) {
                continue;
            }
            $panelItems[] = $item;
        }
        if (count($panelItems) < 3) {
            return false;
        }

        $panelFontSize = $this->median(array_map(
            static fn (array $item): float => max(1.0, (float) $item['fontSize']),
            $panelItems
        ));
        $panelTop = max(array_map(static fn (array $item): float => (float) $item['y1'], $panelItems));
        if ($panelFontSize > min((float) $previous['fontSize'], (float) $candidate['fontSize']) * 0.90
            || $panelTop > (float) $previous['y1'] - max(12.0, $fontSize * 1.20)) {
            return false;
        }

        foreach ($panelItems as $panel) {
            if (($panel['sourceGeometryColumn'] ?? null) === ($candidate['sourceGeometryColumn'] ?? null)) {
                return false;
            }
        }

        return true;
    }

    /**
     * A source-only line can be placed beside a known neighbor when it looks
     * like a wrapped continuation. Some PDF producers instead concatenate two
     * aligned columns into that source line. When positioned fragments on the
     * same baseline prove both pieces belong to separate columns, prefer those
     * fragments and discard the invented combined line.
     *
     * @param list<array<string, mixed>> $items
     * @return list<array<string, mixed>>
     */
    private function removeSourcePdfInferredCrossColumnDuplicates(array $items): array
    {
        $drop = [];
        foreach ($items as $index => $item) {
            if (($item['sourceInferredNeighborLayout'] ?? false) !== true
                || !$this->pdfLayoutHasGeometry($item)) {
                continue;
            }

            $sourceText = $this->pdfComparableLineText((string) ($item['text'] ?? ''));
            if ($this->length($sourceText) < 12) {
                continue;
            }
            $fontSize = max(1.0, (float) $item['fontSize']);
            foreach ($items as $suffixIndex => $suffix) {
                if ($suffixIndex === $index
                    || ($suffix['sourceSupplementalPositioned'] ?? false) !== true
                    || !$this->pdfLayoutHasGeometry($suffix)
                    || ($suffix['page'] ?? null) !== ($item['page'] ?? null)
                    || abs((float) $suffix['y1'] - (float) $item['y1']) > max(2.0, $fontSize * 0.35)
                    || abs((float) $suffix['x1'] - (float) $item['x1']) > max(8.0, $fontSize * 0.75)) {
                    continue;
                }

                $suffixText = $this->pdfComparableLineText((string) ($suffix['text'] ?? ''));
                if ($this->length($suffixText) < 4
                    || $this->length($sourceText) <= $this->length($suffixText) + 3
                    || !str_ends_with($sourceText, $suffixText)) {
                    continue;
                }

                foreach ($items as $prefixIndex => $prefix) {
                    if ($prefixIndex === $index || $prefixIndex === $suffixIndex
                        || !$this->pdfLayoutHasGeometry($prefix)
                        || ($prefix['page'] ?? null) !== ($item['page'] ?? null)
                        || abs((float) $prefix['y1'] - (float) $item['y1']) > max(2.0, $fontSize * 0.35)
                        || (float) $prefix['x2'] > (float) $item['x1'] - max(12.0, $fontSize * 1.5)) {
                        continue;
                    }

                    $prefixText = $this->pdfComparableLineText((string) ($prefix['text'] ?? ''));
                    if ($this->length($prefixText) >= 4 && str_contains($sourceText, $prefixText)) {
                        $drop[$index] = true;
                        break 2;
                    }
                }
            }
        }

        if ($drop === []) {
            return $items;
        }

        return array_values(array_filter(
            $items,
            static fn (array $_item, int $index): bool => !isset($drop[$index]),
            ARRAY_FILTER_USE_BOTH
        ));
    }

    /**
     * @param list<array{page: int, stream: int, text: string}> $sourceItems
     * @return array<int, int>
     */
    private function sourcePdfTableSourceGroups(array $sourceItems): array
    {
        $lines = array_column($sourceItems, 'text');
        $candidates = [];
        for ($index = 0, $count = count($lines); $index < $count; $index++) {
            $inline = $this->tableRowsAt($lines, $index);
            $stacked = $this->stackedTableRowsAt($lines, $index);
            $candidate = $stacked['consumed'] > $inline['consumed'] ? $stacked : $inline;
            if ($candidate['rows'] === [] || $candidate['consumed'] < 2) {
                continue;
            }
            if ($this->sourcePdfTableCandidateLooksLikeDiagramLabelGrid($candidate)) {
                continue;
            }

            $candidates[] = [
                'start' => $index,
                'consumed' => $candidate['consumed'],
                'score' => $this->sourcePdfTableCandidateScore($candidate),
            ];
        }

        // Stacked-cell PDFs can make a real three-column table look like
        // several wider, shifted candidates when adjacent prose lands in the
        // same source stream. Prefer the densest candidate, then reserve its
        // source range before considering any overlapping alternative.
        usort($candidates, static function (array $left, array $right): int {
            return $right['score'] <=> $left['score']
                ?: $right['consumed'] <=> $left['consumed']
                ?: $left['start'] <=> $right['start'];
        });

        $groups = [];
        $occupied = [];
        $group = 0;
        foreach ($candidates as $candidate) {
            $end = $candidate['start'] + $candidate['consumed'];
            $overlapsExistingGroup = false;
            for ($index = $candidate['start']; $index < $end; $index++) {
                if (isset($occupied[$index])) {
                    $overlapsExistingGroup = true;
                    break;
                }
            }
            if ($overlapsExistingGroup) {
                continue;
            }

            $group++;
            for ($index = $candidate['start']; $index < $end && $index < count($lines); $index++) {
                $groups[$index] = $group;
                $occupied[$index] = true;
            }
        }

        return $groups;
    }

    /**
     * @param array{rows: list<list<string>>, consumed: int} $candidate
     */
    private function sourcePdfTableCandidateScore(array $candidate): float
    {
        $rows = $candidate['rows'];
        $columnCount = max(1, count($rows[0] ?? []));
        $bodyRows = max(0, count($rows) - 1);
        $headerPenalty = 0.0;
        foreach ($rows[0] ?? [] as $headerCell) {
            $headerCell = trim($headerCell);
            if (preg_match('/[.!?;:]/u', $headerCell) === 1) {
                $headerPenalty += 2.0;
            }
            if (count($this->pdfLineWordTokens($headerCell)) > 5) {
                $headerPenalty += 1.0;
            }
        }

        return ($bodyRows / $columnCount) * 100.0 + $bodyRows * 4.0 - $headerPenalty;
    }

    /**
     * A flowchart can expose its labels as a narrow grid of individual glyphs.
     * Such a grid has no numeric/data-like cells and is dominated by one-letter
     * fragments, unlike ordinary compact tables. Reject it before table source
     * provenance protects those fragments from prose cleanup.
     *
     * @param array{rows: list<list<string>>, consumed: int} $candidate
     */
    private function sourcePdfTableCandidateLooksLikeDiagramLabelGrid(array $candidate): bool
    {
        $cells = [];
        foreach ($candidate['rows'] as $row) {
            foreach ($row as $cell) {
                $cell = trim($cell);
                if ($cell !== '') {
                    $cells[] = $cell;
                }
            }
        }
        if (count($cells) < 6) {
            return false;
        }

        $short = 0;
        $singleGlyph = 0;
        $numeric = 0;
        foreach ($cells as $cell) {
            $compact = preg_replace('/[^\p{L}\p{N}]+/u', '', $cell) ?? '';
            $length = $this->length($compact);
            if ($length <= 7 && count($this->pdfLineWordTokens($cell)) <= 2) {
                $short++;
            }
            if ($length === 1 && preg_match('/^\p{L}$/u', $compact) === 1) {
                $singleGlyph++;
            }
            if (preg_match('/\p{N}/u', $compact) === 1) {
                $numeric++;
            }
        }

        return $numeric === 0
            && $short / count($cells) >= 0.80
            && $singleGlyph >= max(3, (int) ceil(count($cells) * 0.25));
    }

    /**
     * @param array<string, mixed> $item
     * @param array<int, int> $tableSourceGroups
     * @return array<string, mixed>
     */
    private function sourcePdfAttachSourceItemProvenance(array $item, int $sourceIndex, array $tableSourceGroups): array
    {
        $item['sourcePdfSourceIndex'] = $sourceIndex;
        if (isset($tableSourceGroups[$sourceIndex])
            && ($item['sourcePdfExactRangeFragmentSequence'] ?? false) !== true) {
            $item['sourcePdfTableGroup'] = $tableSourceGroups[$sourceIndex];
        }

        return $item;
    }

    /**
     * Keep the source stream's cell sequence intact while placing a detected
     * table where its first visual item occurred among the surrounding prose.
     * The geometry of individual table cells is often less reliable than its
     * source order, especially when the PDF has overlapping text layers.
     *
     * @param list<array<string, mixed>> $items
     * @param list<array{page: int, stream: int, text: string}> $sourceItems
     * @return list<array<string, mixed>>
     */
    private function restoreSourcePdfTableItemSequences(array $items, array $sourceItems = []): array
    {
        $groups = [];
        foreach ($items as $index => $item) {
            if (!isset($item['sourcePdfTableGroup'], $item['sourcePdfSourceIndex'])) {
                continue;
            }
            $group = (int) $item['sourcePdfTableGroup'];
            $groups[$group]['firstIndex'] = min($groups[$group]['firstIndex'] ?? $index, $index);
            $groups[$group]['items'][] = $item;
            $sourceStart = (int) $item['sourcePdfSourceIndex'];
            $sourceEnd = (int) ($item['sourcePdfSourceIndexEnd'] ?? $sourceStart);
            $groups[$group]['sourceStart'] = min($groups[$group]['sourceStart'] ?? $sourceStart, $sourceStart);
            $groups[$group]['sourceEnd'] = max($groups[$group]['sourceEnd'] ?? $sourceEnd, $sourceEnd);
        }
        if ($groups === []) {
            return $items;
        }

        $groupsAtIndex = [];
        foreach ($groups as $group => $entry) {
            usort($entry['items'], static fn (array $left, array $right): int => (int) $left['sourcePdfSourceIndex'] <=> (int) $right['sourcePdfSourceIndex']);
            $tableItems = $entry['items'];
            if ($sourceItems !== []
                && isset($entry['sourceStart'], $entry['sourceEnd'])
                && $entry['sourceStart'] >= 0
                && $entry['sourceEnd'] < count($sourceItems)) {
                $tableItems = [];
                for ($sourceIndex = $entry['sourceStart']; $sourceIndex <= $entry['sourceEnd']; $sourceIndex++) {
                    $tableItem = $this->sourcePdfLineItem($sourceItems[$sourceIndex]);
                    $tableItem['sourcePdfSourceIndex'] = $sourceIndex;
                    $tableItem['sourcePdfTableGroup'] = $group;
                    $tableItems[] = $tableItem;
                }
            }
            $groupsAtIndex[$entry['firstIndex']][] = $tableItems;
        }

        $restored = [];
        foreach ($items as $index => $item) {
            foreach ($groupsAtIndex[$index] ?? [] as $tableItems) {
                if ($restored !== []) {
                    $tableItems[0]['forceBlockBreakBefore'] = true;
                }
                foreach ($tableItems as $tableItem) {
                    $restored[] = $tableItem;
                }
            }
            if (isset($item['sourcePdfTableGroup'])) {
                continue;
            }
            $restored[] = $item;
        }

        return $restored;
    }

    /**
     * Prefer a visually complete supplemental line over a clipped source
     * duplicate only when both occupy the same baseline and local text
     * region. A larger horizontal offset is evidence of a neighboring column
     * or figure and must remain independently represented.
     *
     * @param list<array<string, mixed>> $items
     * @return list<array<string, mixed>>
     */
    private function removeSourcePdfItemsCoveredBySupplementalPositioning(array $items): array
    {
        $filtered = [];
        foreach ($items as $item) {
            if (($item['sourcePdfExactGeometryFallback'] ?? false) === true) {
                $filtered[] = $item;
                continue;
            }
            if (($item['sourceSupplementalUrlOverlap'] ?? false) === true) {
                continue;
            }
            if (($item['sourceSupplementalPositioned'] ?? false) === true
                || isset($item['sourcePdfTableGroup'])
                || !$this->pdfLayoutHasGeometry($item)) {
                $filtered[] = $item;
                continue;
            }
            $covered = false;
            foreach ($items as $supplemental) {
                if (($supplemental['sourceSupplementalPositioned'] ?? false) !== true
                    || !$this->pdfLayoutHasGeometry($supplemental)
                    || ($supplemental['page'] ?? null) !== ($item['page'] ?? null)) {
                    continue;
                }
                $fontSize = max((float) $item['fontSize'], (float) $supplemental['fontSize'], 1.0);
                $itemBaseline = ((float) $item['y1'] + (float) $item['y2']) / 2.0;
                $supplementalBaseline = ((float) $supplemental['y1'] + (float) $supplemental['y2']) / 2.0;
                if (abs($itemBaseline - $supplementalBaseline) > max(2.0, $fontSize * 0.60)
                    || abs((float) $item['x1'] - (float) $supplemental['x1']) > max(16.0, $fontSize * 2.0)) {
                    continue;
                }
                $sourceText = (string) ($item['text'] ?? '');
                $supplementalText = (string) ($supplemental['text'] ?? '');
                if ($this->sourcePdfTextIsCoveredBySupplementalPositioning($sourceText, $supplementalText)
                    || $this->sourcePdfShortTextIsCoveredBySupplementalLine($sourceText, $supplementalText)) {
                    $covered = true;
                    break;
                }
            }
            if (!$covered) {
                $filtered[] = $item;
            }
        }

        return $filtered;
    }

    /**
     * A positioned extractor can combine each row of a source-detected table
     * into a supplemental prose line. When several such duplicates share a
     * left edge and baseline rhythm, retain the source table cells and remove
     * only the repeated positioned rows. Isolated supplemental captions stay
     * available to the prose flow.
     *
     * @param list<array<string, mixed>> $items
     * @return list<array<string, mixed>>
     */
    private function removeSourcePdfSupplementalRowDuplicates(array $items): array
    {
        $candidates = [];
        foreach ($items as $index => $item) {
            if (($item['sourceSupplementalPositioned'] ?? false) !== true
                || ($item['sourceSupplementalSourceOverlap'] ?? false) !== true
                || ($item['sourceSupplementalRecoverableSentenceSuffix'] ?? false) === true
                || !$this->pdfLayoutHasGeometry($item)) {
                continue;
            }
            $candidates[] = $index;
        }
        if (count($candidates) < 3) {
            return $items;
        }

        $groups = [];
        foreach ($candidates as $index) {
            $item = $items[$index];
            $groupIndex = null;
            foreach ($groups as $candidateIndex => $group) {
                $anchor = $items[$group[0]];
                if (($anchor['page'] ?? null) !== ($item['page'] ?? null)) {
                    continue;
                }
                $fontSize = max(1.0, (float) $anchor['fontSize'], (float) $item['fontSize']);
                if (abs((float) $anchor['x1'] - (float) $item['x1']) <= max(12.0, $fontSize * 1.5)) {
                    $groupIndex = $candidateIndex;
                    break;
                }
            }
            if ($groupIndex === null) {
                $groups[] = [$index];
            } else {
                $groups[$groupIndex][] = $index;
            }
        }

        $drop = [];
        foreach ($groups as $group) {
            if (count($group) < 3) {
                continue;
            }
            usort($group, fn (int $left, int $right): int => (float) $items[$right]['y1'] <=> (float) $items[$left]['y1']);
            $rhythmPairs = 0;
            foreach ($group as $offset => $index) {
                if (!isset($group[$offset + 1])) {
                    break;
                }
                $next = $items[$group[$offset + 1]];
                $fontSize = max(1.0, (float) $items[$index]['fontSize'], (float) $next['fontSize']);
                $step = (float) $items[$index]['y1'] - (float) $next['y1'];
                if ($step >= $fontSize * 0.35 && $step <= $fontSize * 2.2) {
                    $rhythmPairs++;
                }
            }
            if ($rhythmPairs >= count($group) - 2) {
                foreach ($group as $index) {
                    $drop[$index] = true;
                }
            }
        }

        if ($drop === []) {
            return $items;
        }

        return array_values(array_filter(
            $items,
            static fn (array $_item, int $index): bool => !isset($drop[$index]),
            ARRAY_FILTER_USE_BOTH
        ));
    }

    /**
     * A PDF can contain an overlapping fallback text layer for a visible line.
     * When the two runs occupy the same local baseline and one is substantially
     * covered by the other, retaining both repeats part of a sentence.
     * This is geometry and text-coverage based; it does not inspect document
     * vocabulary or assume a particular language.
     *
     * @param list<array<string, mixed>> $items
     * @return list<array<string, mixed>>
     */
    private function removeSourcePdfNearBaselinePrefixDuplicates(array $items): array
    {
        $drop = [];
        $count = count($items);
        for ($index = 0; $index < $count; $index++) {
            $item = $items[$index];
            if (!$this->sourcePdfNearBaselinePrefixDuplicateCandidate($item)) {
                continue;
            }

            for ($candidateIndex = $index + 1; $candidateIndex < $count; $candidateIndex++) {
                $candidate = $items[$candidateIndex];
                if (!$this->sourcePdfNearBaselinePrefixDuplicateCandidate($candidate)
                    || ($item['page'] ?? null) !== ($candidate['page'] ?? null)) {
                    continue;
                }
                if (($item['sourceGeometryColumn'] ?? null) !== ($candidate['sourceGeometryColumn'] ?? null)
                    && ($item['sourceFloatingGeometry'] ?? false) !== true
                    && ($candidate['sourceFloatingGeometry'] ?? false) !== true) {
                    continue;
                }
                if (isset($item['sourceStream'], $candidate['sourceStream'])
                    && (int) $item['sourceStream'] !== (int) $candidate['sourceStream']) {
                    continue;
                }

                $fontSize = max(1.0, (float) $item['fontSize'], (float) $candidate['fontSize']);
                $horizontalTolerance = max(5.0, $fontSize * 0.60);
                $sameLeftEdge = abs((float) $item['x1'] - (float) $candidate['x1']) <= $horizontalTolerance;
                $oneContainsTheOther = ((float) $item['x1'] <= (float) $candidate['x1'] + $horizontalTolerance
                        && (float) $item['x2'] >= (float) $candidate['x2'] - $horizontalTolerance)
                    || ((float) $candidate['x1'] <= (float) $item['x1'] + $horizontalTolerance
                        && (float) $candidate['x2'] >= (float) $item['x2'] - $horizontalTolerance);
                if (abs((float) $item['y1'] - (float) $candidate['y1']) > max(1.5, $fontSize * 0.35)
                    || (!$sameLeftEdge && !$oneContainsTheOther)) {
                    continue;
                }

                $itemText = $this->pdfComparableLineText((string) ($item['text'] ?? ''));
                $candidateText = $this->pdfComparableLineText((string) ($candidate['text'] ?? ''));
                $itemLength = $this->length($itemText);
                $candidateLength = $this->length($candidateText);
                if (min($itemLength, $candidateLength) < 12) {
                    continue;
                }

                if ($itemText === $candidateText) {
                    $drop[$candidateIndex] = true;
                    continue;
                }

                if ($itemLength < $candidateLength
                    && $this->sourcePdfNearBaselineTextIsCoveredBy(
                        $itemText,
                        $candidateText,
                        $item,
                        $candidate,
                        $fontSize
                    )) {
                    $drop[$index] = true;
                    continue;
                }
                if ($candidateLength < $itemLength
                    && $this->sourcePdfNearBaselineTextIsCoveredBy(
                        $candidateText,
                        $itemText,
                        $candidate,
                        $item,
                        $fontSize
                    )) {
                    $drop[$candidateIndex] = true;
                }
            }
        }

        if ($drop === []) {
            return $items;
        }

        return array_values(array_filter(
            $items,
            static fn (array $_item, int $index): bool => !isset($drop[$index]),
            ARRAY_FILTER_USE_BOTH
        ));
    }

    /**
     * @param array<string, mixed> $shortLayout
     * @param array<string, mixed> $longLayout
     */
    private function sourcePdfNearBaselineTextIsCoveredBy(
        string $shortText,
        string $longText,
        array $shortLayout,
        array $longLayout,
        float $fontSize
    ): bool {
        $shortLength = $this->length($shortText);
        $longLength = $this->length($longText);
        if ($shortLength === 0 || $longLength <= $shortLength || !str_contains($longText, $shortText)) {
            return false;
        }

        $ratio = $shortLength / $longLength;
        $substantial = ($shortLength >= 12 && $ratio >= 0.80)
            || ($shortLength >= 32 && $ratio >= 0.45);
        if (!$substantial) {
            return false;
        }
        if (($shortLayout['sourceInferredNeighborLayout'] ?? false) === true
            || ($longLayout['sourceInferredNeighborLayout'] ?? false) === true) {
            return true;
        }

        $horizontalTolerance = max(8.0, $fontSize);
        return (float) $shortLayout['x1'] >= (float) $longLayout['x1'] - $horizontalTolerance
            && (float) $shortLayout['x2'] <= (float) $longLayout['x2'] + $horizontalTolerance;
    }

    /**
     * @param array<string, mixed> $item
     */
    private function sourcePdfNearBaselinePrefixDuplicateCandidate(array $item): bool
    {
        return $this->pdfLayoutHasGeometry($item)
            && !isset($item['sourcePdfTableGroup'])
            && ($item['sourceSupplementalRecoverableSentenceSuffix'] ?? false) !== true
            && ($item['sourcePdfReferenceEntry'] ?? false) !== true
            && ($item['code'] ?? false) !== true
            && $this->length($this->pdfComparableLineText((string) ($item['text'] ?? ''))) >= 12;
    }

    /**
     * A positioned text layer can paint a diagram label over an ordinary
     * wrapped source line. When the source line has a normal same-column
     * continuation immediately below it, that overlay cannot belong in the
     * source flow. Keep true same-line completions, which have no such source
     * continuation, and discard only the conflicting overlay.
     *
     * @param list<array<string, mixed>> $items
     * @return list<array<string, mixed>>
     */
    private function removeSourcePdfSupplementalOverlaysThatInterruptSourceWrap(array $items): array
    {
        $drop = [];
        foreach ($items as $overlayIndex => $overlay) {
            if (($overlay['sourceSupplementalPositioned'] ?? false) !== true
                || ($overlay['sourceSupplementalSourceOverlap'] ?? false) !== true
                || ($overlay['sourceSupplementalRecoverableSentenceSuffix'] ?? false) === true
                || isset($overlay['sourcePdfTableGroup'])
                || !$this->pdfLayoutHasGeometry($overlay)) {
                continue;
            }

            foreach ($items as $sourceIndex => $source) {
                if ($sourceIndex === $overlayIndex
                    || ($source['sourceSupplementalPositioned'] ?? false) === true
                    || isset($source['sourcePdfTableGroup'])
                    || ($source['code'] ?? false) === true
                    || !$this->pdfLayoutHasGeometry($source)
                    || ($source['page'] ?? null) !== ($overlay['page'] ?? null)
                    || ($source['sourceGeometryColumn'] ?? null) !== ($overlay['sourceGeometryColumn'] ?? null)) {
                    continue;
                }

                $fontSize = max(1.0, (float) $source['fontSize'], (float) $overlay['fontSize']);
                if (abs((float) $source['y1'] - (float) $overlay['y1']) > max(1.5, $fontSize * 0.35)
                    || (float) $overlay['x1'] < (float) $source['x1'] - max(8.0, $fontSize)
                    || (float) $overlay['x2'] > (float) $source['x2'] + max(8.0, $fontSize)
                    || !$this->sourcePdfRecordHasLowercaseWrappedContinuation($items, $sourceIndex)) {
                    continue;
                }

                $drop[$overlayIndex] = true;
                break;
            }
        }

        if ($drop === []) {
            return $items;
        }

        return array_values(array_filter(
            $items,
            static fn (array $_item, int $index): bool => !isset($drop[$index]),
            ARRAY_FILTER_USE_BOTH
        ));
    }

    /**
     * @param list<array<string, mixed>> $items
     */
    private function sourcePdfRecordHasLowercaseWrappedContinuation(array $items, int $sourceIndex): bool
    {
        $source = $items[$sourceIndex] ?? null;
        if (!is_array($source)
            || preg_match('/[.!?;:]\s*$/u', rtrim((string) ($source['text'] ?? ''))) === 1
            || !$this->pdfLayoutHasGeometry($source)) {
            return false;
        }

        for ($index = $sourceIndex + 1, $limit = min(count($items), $sourceIndex + 7); $index < $limit; $index++) {
            $candidate = $items[$index];
            if (($candidate['sourceSupplementalPositioned'] ?? false) === true
                || isset($candidate['sourcePdfTableGroup'])
                || !$this->pdfLayoutHasGeometry($candidate)
                || ($candidate['page'] ?? null) !== ($source['page'] ?? null)
                || ($candidate['sourceGeometryColumn'] ?? null) !== ($source['sourceGeometryColumn'] ?? null)) {
                continue;
            }

            $fontSize = max(1.0, (float) $source['fontSize'], (float) $candidate['fontSize']);
            $verticalStep = (float) $source['y1'] - (float) $candidate['y1'];
            if ($verticalStep < $fontSize * 0.35 || $verticalStep > $fontSize * 1.80
                || abs((float) $source['x1'] - (float) $candidate['x1']) > max(8.0, $fontSize)
                || preg_match('/^[^\p{L}\p{N}]*\p{Ll}/u', ltrim((string) ($candidate['text'] ?? ''))) !== 1) {
                continue;
            }

            return true;
        }

        return false;
    }

    /**
     * The source text layer can retain a clipped duplicate of a positioned
     * repair line. When nearly all of that source-only fragment is present at
     * the same end of a supplemental visual line, keeping both fabricates a
     * repeated phrase. Retain the visually complete representation instead.
     *
     * @param list<array<string, mixed>> $fallback
     * @param list<array<string, mixed>> $ordered
     * @return list<array<string, mixed>>
     */
    private function removeSourcePdfFallbackCoveredBySupplementalPositioning(array $fallback, array $ordered): array
    {
        $filtered = [];
        foreach ($fallback as $fallbackItem) {
            if (($fallbackItem['sourcePdfExactGeometryFallback'] ?? false) === true
                || ($fallbackItem['sourceUnmatchedFallback'] ?? false) !== true
                || isset($fallbackItem['sourcePdfTableGroup'])) {
                $filtered[] = $fallbackItem;
                continue;
            }

            $covered = false;
            foreach ($ordered as $positionedItem) {
                if (($positionedItem['sourceSupplementalPositioned'] ?? false) !== true
                    || ($positionedItem['page'] ?? null) !== ($fallbackItem['page'] ?? null)) {
                    continue;
                }
                if ($this->sourcePdfTextIsCoveredBySupplementalPositioning(
                    (string) ($fallbackItem['text'] ?? ''),
                    (string) ($positionedItem['text'] ?? '')
                )) {
                    $covered = true;
                    break;
                }
            }
            if (!$covered) {
                $filtered[] = $fallbackItem;
            }
        }

        return $filtered;
    }

    private function sourcePdfTextIsCoveredBySupplementalPositioning(string $sourceText, string $positionedText): bool
    {
        $sourceTokens = $this->sourcePdfComparableTokens($sourceText);
        $positionedTokens = $this->sourcePdfComparableTokens($positionedText);
        if (count($positionedTokens) < count($sourceTokens)
            && preg_match('/[.!?;:]\s*$/u', rtrim($sourceText)) === 1) {
            // A positioned prefix can lose a trailing font run. A complete
            // source sentence on the same baseline is stronger evidence than
            // that shorter prefix and must remain available for restoration.
            return false;
        }
        if (count($sourceTokens) < 4 || count($positionedTokens) < 4) {
            return $this->sourcePdfComparableTextIsCoveredBySupplementalPositioning($sourceText, $positionedText);
        }

        $prefix = 0;
        $prefixLimit = min(count($sourceTokens), count($positionedTokens));
        while ($prefix < $prefixLimit && $sourceTokens[$prefix] === $positionedTokens[$prefix]) {
            $prefix++;
        }
        $suffix = 0;
        while ($suffix < $prefixLimit
            && $sourceTokens[count($sourceTokens) - 1 - $suffix] === $positionedTokens[count($positionedTokens) - 1 - $suffix]) {
            $suffix++;
        }

        // A suffix match cannot account for an omitted leading source
        // fragment: it may be a separately painted continuation rather than
        // a duplicate. Only a shared leading sequence can replace a source
        // fallback here; exact full-string containment remains available in
        // the comparable-text check below.
        $overlap = $prefix;
        $matchedTokens = array_slice($sourceTokens, 0, $overlap);
        $matchedCharacters = $this->length(implode('', $matchedTokens));

        if ($overlap >= max(3, (int) ceil(count($sourceTokens) * 0.75))
            && $matchedCharacters >= 18) {
            return true;
        }

        return $this->sourcePdfComparableTextIsCoveredBySupplementalPositioning($sourceText, $positionedText);
    }

    /**
     * A positioned line may preserve a source line whose internal word gaps
     * were lost by font changes or per-glyph text commands. At the same
     * baseline, a long compact substring is stronger evidence than token
     * equality and lets the complete visual line replace its clipped source
     * duplicate without relying on document vocabulary.
     */
    private function sourcePdfComparableTextIsCoveredBySupplementalPositioning(
        string $sourceText,
        string $positionedText
    ): bool {
        $source = $this->pdfComparableLineText($sourceText);
        $positioned = $this->pdfComparableLineText($positionedText);
        $sourceLength = $this->length($source);
        $positionedLength = $this->length($positioned);
        if ($sourceLength < 24 || $positionedLength < $sourceLength) {
            return false;
        }

        return str_contains($positioned, $source)
            && $sourceLength / $positionedLength >= 0.58;
    }

    /**
     * A source text layer may retain only the first few glyphs of a line that
     * is otherwise recovered from positioned text. This is deliberately used
     * only after the caller has established that both entries share a baseline
     * and start position, so a short common word elsewhere on the page cannot
     * cause content to disappear.
     */
    private function sourcePdfShortTextIsCoveredBySupplementalLine(string $sourceText, string $positionedText): bool
    {
        $source = $this->pdfComparableLineText($sourceText);
        $positioned = $this->pdfComparableLineText($positionedText);
        $sourceLength = $this->length($source);
        if ($sourceLength < 3 || $sourceLength > 12 || $this->length($positioned) <= $sourceLength) {
            return false;
        }

        return str_starts_with($positioned, $source) || str_ends_with($positioned, $source);
    }

    /**
     * @return list<string>
     */
    private function sourcePdfComparableTokens(string $text): array
    {
        $tokens = [];
        foreach ($this->pdfLineWordTokens($text) as $token) {
            $normalized = $this->pdfComparableLineText($token);
            if ($normalized !== '') {
                $tokens[] = $normalized;
            }
        }

        return $tokens;
    }

    /**
     * A page with both floating geometry and a sustained source-only label
     * cluster is a diagram-heavy layout. It may still contain ordinary body
     * columns, so later cleanup uses this only for short, detached fragments.
     *
     * @param list<array<string, mixed>> $ordered
     * @param list<array<string, mixed>> $fallback
     */
    private function sourcePdfPageHasDetachedDiagramEvidence(array $ordered, array $fallback): bool
    {
        $floatingGeometry = count(array_filter(
            $ordered,
            static fn (array $item): bool => ($item['sourceFloatingGeometry'] ?? false) === true
        ));
        if ($floatingGeometry < 3 || count($fallback) < 8) {
            return false;
        }

        $compactLabels = 0;
        foreach ($fallback as $item) {
            $text = trim((string) ($item['text'] ?? ''));
            if ($text === ''
                || $this->lineHasPdfListBlockEvidence($text)
                || $this->lineLooksLikeUrlOnly($text)
                || preg_match('/[.!?;:]\s*$/u', $text) === 1) {
                continue;
            }
            $compact = preg_replace('/\s+/u', '', $text) ?? '';
            if ($this->length($compact) <= 18 && count($this->pdfLineWordTokens($text)) <= 4) {
                $compactLabels++;
            }
        }

        return $compactLabels >= 8 && $compactLabels / count($fallback) >= 0.45;
    }

    /**
     * The positioned extractor already provides a useful reading order for
     * ordinary pages. Dense papers can also contain figures whose tiny labels
     * split that order into artificial columns. Rebuild only those pages from
     * stable body-text anchors, leaving every other layout on its existing
     * path.
     *
     * @param list<array<string, mixed>> $items
     * @return list<array<string, mixed>>
     */
    private function orderSourcePdfItemsWithinStableColumns(array &$items): array
    {
        $frontMatter = array_values(array_filter(
            $items,
            static fn (array $item): bool => ($item['sourcePdfFrontMatter'] ?? false) === true
        ));
        $flowItems = $frontMatter === [] ? $items : array_values(array_filter(
            $items,
            static fn (array $item): bool => ($item['sourcePdfFrontMatter'] ?? false) !== true
        ));
        $geometryItems = array_values(array_filter(
            $flowItems,
            fn (array $item): bool => $this->pdfLayoutHasGeometry($item)
        ));
        if (count($geometryItems) < 20) {
            return $items;
        }

        $columns = $this->sourcePdfStableTextColumns($geometryItems);
        if (!$this->sourcePdfColumnsLookLikeParallelBodyColumns($columns)) {
            return $items;
        }
        $medianFontSize = $this->median(array_map(
            static fn (array $item): float => max(1.0, (float) $item['fontSize']),
            $geometryItems
        ));
        // The selected flow owns every non-front-matter record from here.
        // Consume the caller's now-redundant vector and release the geometry
        // view before decorating each item; otherwise every small attribute
        // write triggers a full nested hash copy while the old vector remains
        // resident. Callers that still need their input pass a local copy.
        $items = [];
        unset($geometryItems);

        // A styled inline fragment can begin beyond the normal first-line
        // indent tolerance while still sharing a baseline and source sequence
        // with a body line in the same column. Compose that proven visual
        // line before column assignment so the trailing fragment is not
        // mistaken for detached geometry.
        $flowItems = $this->composePositionedPdfInlineFragmentsWithinStableColumns($flowItems, $columns);

        $columnItems = array_fill(0, count($columns), []);
        $floating = [];
        $floatingGeometryCount = 0;
        $diagramLabelCount = 0;
        $flowItemCount = count($flowItems);
        for ($flowIndex = 0; $flowIndex < $flowItemCount; $flowIndex++) {
            // Decorate the owned flow record in place. A by-value foreach loop
            // keeps the vector element and the loop variable alive together,
            // so every attribute write copies the complete nested hash.
            $item =& $flowItems[$flowIndex];
            if (!$this->pdfLayoutHasGeometry($item)) {
                $floating[] = $item;
                unset($item);
                continue;
            }

            $columnIndex = $this->sourcePdfColumnIndexForItem($item, $columns);
            if ($columnIndex === null
                && ($item['sourceFootnotePrefixedGeometry'] ?? false) === true) {
                $columnIndex = $this->sourcePdfFootnotePrefixedGeometryColumnIndex($item, $flowItems, $columns);
            }
            if ($columnIndex === null) {
                $item['sourceFloatingGeometry'] = true;
                $floating[] = $item;
                $floatingGeometryCount++;
                $text = trim((string) ($item['text'] ?? ''));
                if ((float) $item['fontSize'] < $medianFontSize * 0.68
                    && $this->length($text) <= 36
                    && count($this->pdfLineWordTokens($text)) <= 5
                    && preg_match('/[.!?;:]\s*$/u', $text) !== 1
                    && !$this->lineHasPdfListBlockEvidence($text)
                    && !$this->lineLooksLikeUrlOnly($text)) {
                    $diagramLabelCount++;
                }
                unset($item);
                continue;
            }

            unset($item['forceBlockBreakBefore']);
            $item['sourceStructuredGeometry'] = true;
            $item['sourceGeometryColumn'] = $columnIndex;
            $columnItems[$columnIndex][] = $item;
            unset($item);
        }
        unset($flowItems);

        $complexFigurePage = $floatingGeometryCount >= 4 && $diagramLabelCount >= 5;
        $interruptedFloating = array_values(array_filter(
            $floating,
            fn (array $item): bool => $this->pdfLayoutHasGeometry($item)
                && !$this->sourcePdfFloatingItemCanStandAlone($item, $medianFontSize)
        ));

        $ordered = $frontMatter;
        $previousColumnEntries = null;
        $deferredMinorFontEntries = [];
        foreach ($columnItems as $columnIndex => $entries) {
            usort($entries, static function (array $left, array $right): int {
                return ((float) $right['y1'] <=> (float) $left['y1'])
                    ?: ((float) $left['x1'] <=> (float) $right['x1']);
            });
            $entries = $this->markSourcePdfMinorFontFlows($entries, $medianFontSize);
            $minorFontEntries = array_values(array_filter(
                $entries,
                static fn (array $entry): bool => ($entry['sourceMinorFontFlow'] ?? false) === true
            ));
            if ($minorFontEntries !== []) {
                // A footnote may sit below an unfinished body sentence. Keep
                // it on the page, but defer it until after body columns have
                // been connected so it cannot become a false paragraph tail.
                $deferredMinorFontEntries = array_merge($deferredMinorFontEntries, $minorFontEntries);
                $entries = array_values(array_filter(
                    $entries,
                    static fn (array $entry): bool => ($entry['sourceMinorFontFlow'] ?? false) !== true
                ));
            }
            $entries = $this->markSourcePdfIndentedParagraphBoundaries($entries, $columns[$columnIndex]);
            $entries = $this->markSourcePdfOrphanedColumnFlows(
                $entries,
                $previousColumnEntries,
                $columns[$columnIndex]
            );
            if ($interruptedFloating !== []) {
                $entries = $this->markSourcePdfInterruptedColumnFragments($entries, $interruptedFloating);
                // Floating overlap is established after the first flow pass.
                // Re-run it so normal-baseline continuations inherit the
                // interruption marker instead of becoming detached prose.
                $entries = $this->markSourcePdfOrphanedColumnFlows(
                    $entries,
                    $previousColumnEntries,
                    $columns[$columnIndex]
                );
            }
            $entries = $this->prioritizeSourcePdfVerifiedCrossColumnContinuation(
                $entries,
                $previousColumnEntries
            );
            foreach ($entries as $entry) {
                if ($complexFigurePage) {
                    $entry['sourceComplexGeometryPage'] = true;
                }
                $ordered[] = $entry;
            }
            $previousColumnEntries = $entries;
        }
        foreach ($floating as $entry) {
            if (($entry['sourcePdfExactGeometryFallback'] ?? false) !== true
                && !$this->sourcePdfFloatingItemCanStandAlone($entry, $medianFontSize)) {
                continue;
            }
            if ($complexFigurePage && $this->pdfLayoutHasGeometry($entry)) {
                $entry['sourceComplexGeometryPage'] = true;
            }
            $ordered[] = $entry;
        }
        foreach ($deferredMinorFontEntries as $entry) {
            if ($complexFigurePage && $this->pdfLayoutHasGeometry($entry)) {
                $entry['sourceComplexGeometryPage'] = true;
            }
            $ordered[] = $entry;
        }

        return $ordered;
    }

    /**
     * A positioned line that begins with a source-confirmed footnote marker
     * can continue a body line after the marker itself changes font or rises
     * as superscript. Its suffix may start beyond the usual column width, so
     * assign it only when a normal body line shares its baseline and span.
     *
     * @param array<string, mixed> $item
     * @param list<array<string, mixed>> $items
     * @param list<array{x: float, width: float, fontSize: float, count: int}> $columns
     */
    private function sourcePdfFootnotePrefixedGeometryColumnIndex(array $item, array $items, array $columns): ?int
    {
        if (!$this->pdfLayoutHasGeometry($item)
            || ($item['sourceFootnotePrefixedGeometry'] ?? false) !== true) {
            return null;
        }

        foreach ($items as $neighbor) {
            if ($neighbor === $item
                || !$this->pdfLayoutHasGeometry($neighbor)
                || ($neighbor['code'] ?? false) === true
                || ($neighbor['page'] ?? null) !== ($item['page'] ?? null)) {
                continue;
            }

            $columnIndex = $this->sourcePdfColumnIndexForItem($neighbor, $columns);
            if ($columnIndex === null) {
                continue;
            }
            $fontSize = max(1.0, (float) $item['fontSize'], (float) $neighbor['fontSize']);
            if (abs((float) $item['fontSize'] - (float) $neighbor['fontSize']) > max(1.5, $fontSize * 0.25)
                || abs((float) $item['y1'] - (float) $neighbor['y1']) > max(2.5, $fontSize * 0.35)
                || (float) $item['x1'] < (float) $neighbor['x1'] - max(2.0, $fontSize * 0.25)
                || (float) $item['x1'] > (float) $neighbor['x2'] + max(18.0, $fontSize * 2.0)) {
                continue;
            }

            return $columnIndex;
        }

        return null;
    }

    /**
     * Keep a visual line intact when a PDF paints it as multiple positioned
     * fragments. A fragment is eligible only when a stable body column and
     * the content-stream order both corroborate the local same-baseline
     * geometry. This deliberately never joins fragments assigned to separate
     * columns, even when their physical rows share a baseline.
     *
     * @param list<array<string, mixed>> $items
     * @param list<array{x: float, width: float, fontSize: float, count: int}> $columns
     * @return list<array<string, mixed>>
     */
    private function composePositionedPdfInlineFragmentsWithinStableColumns(array $items, array $columns): array
    {
        $columnIndexes = [];
        foreach ($items as $index => $item) {
            if (!$this->pdfLayoutHasGeometry($item) || ($item['code'] ?? false) === true) {
                continue;
            }
            $columnIndex = $this->sourcePdfColumnIndexForItem($item, $columns);
            if ($columnIndex !== null) {
                $columnIndexes[$index] = $columnIndex;
            }
        }

        // A short trailing styled fragment can start just beyond the normal
        // indent tolerance. Let its already-assigned same-line neighbor carry
        // the column identity, but only under the same bounded layout and
        // source-order evidence required for composition below.
        $changed = true;
        while ($changed) {
            $changed = false;
            foreach ($items as $index => $item) {
                if (isset($columnIndexes[$index])
                    || !$this->pdfLayoutHasGeometry($item)
                    || ($item['code'] ?? false) === true) {
                    continue;
                }
                foreach ($columnIndexes as $neighborIndex => $columnIndex) {
                    $neighbor = $items[$neighborIndex] ?? null;
                    if (!is_array($neighbor)
                        || !$this->positionedPdfInlineFragmentsCanComposeWithinStableColumn(
                            $neighbor,
                            $item,
                            $columns[$columnIndex]
                        )) {
                        continue;
                    }
                    $columnIndexes[$index] = $columnIndex;
                    $changed = true;
                    break;
                }
            }
        }

        $groups = [];
        foreach ($columnIndexes as $index => $columnIndex) {
            $item = $items[$index];
            $fontSize = max(1.0, (float) $item['fontSize']);
            $baseline = ((float) $item['y1'] + (float) $item['y2']) / 2.0;
            $groupIndex = null;
            foreach ($groups[$columnIndex] ?? [] as $candidateIndex => $group) {
                if (abs($baseline - $group['baseline']) <= max(2.5, $fontSize * 0.35)) {
                    $groupIndex = $candidateIndex;
                    break;
                }
            }
            if ($groupIndex === null) {
                $groups[$columnIndex][] = [
                    'baseline' => $baseline,
                    'indexes' => [$index],
                ];
                continue;
            }
            $groups[$columnIndex][$groupIndex]['indexes'][] = $index;
        }

        $consumed = [];
        $composed = [];
        foreach ($groups as $columnIndex => $columnGroups) {
            foreach ($columnGroups as $group) {
                if (count($group['indexes']) < 2) {
                    continue;
                }
                $indexes = $group['indexes'];
                usort($indexes, fn (int $left, int $right): int => ((float) $items[$left]['x1'] <=> (float) $items[$right]['x1'])
                    ?: ((int) ($items[$left]['sourceOrderStart'] ?? 0) <=> (int) ($items[$right]['sourceOrderStart'] ?? 0)));

                $candidate = $items[$indexes[0]];
                $candidateIndexes = [$indexes[0]];
                for ($offset = 1, $count = count($indexes); $offset < $count; $offset++) {
                    $nextIndex = $indexes[$offset];
                    $next = $items[$nextIndex];
                    if (!$this->positionedPdfInlineFragmentsCanComposeWithinStableColumn(
                        $candidate,
                        $next,
                        $columns[$columnIndex]
                    )) {
                        if (count($candidateIndexes) > 1) {
                            $firstIndex = $candidateIndexes[0];
                            $composed[$firstIndex] = $candidate;
                            foreach (array_slice($candidateIndexes, 1) as $consumedIndex) {
                                $consumed[$consumedIndex] = true;
                            }
                        }
                        $candidate = $next;
                        $candidateIndexes = [$nextIndex];
                        continue;
                    }
                    $composedCandidate = $this->composePositionedPdfInlineLayoutFragments($candidate, $next);
                    if ($composedCandidate === null) {
                        if (count($candidateIndexes) > 1) {
                            $firstIndex = $candidateIndexes[0];
                            $composed[$firstIndex] = $candidate;
                            foreach (array_slice($candidateIndexes, 1) as $consumedIndex) {
                                $consumed[$consumedIndex] = true;
                            }
                        }
                        $candidate = $next;
                        $candidateIndexes = [$nextIndex];
                        continue;
                    }
                    $candidate = $composedCandidate;
                    $candidateIndexes[] = $nextIndex;
                }
                if (count($candidateIndexes) > 1) {
                    $firstIndex = $candidateIndexes[0];
                    $composed[$firstIndex] = $candidate;
                    foreach (array_slice($candidateIndexes, 1) as $consumedIndex) {
                        $consumed[$consumedIndex] = true;
                    }
                }
            }
        }

        if ($composed === []) {
            return $items;
        }

        $result = [];
        foreach ($items as $index => $item) {
            if (isset($consumed[$index])) {
                continue;
            }
            $result[] = $composed[$index] ?? $item;
        }

        return $result;
    }

    /**
     * @param array<string, mixed> $first
     * @param array<string, mixed> $second
     * @param array{x: float, width: float, fontSize: float, count: int} $column
     */
    private function positionedPdfInlineFragmentsCanComposeWithinStableColumn(
        array $first,
        array $second,
        array $column
    ): bool {
        if (!$this->pdfLayoutHasGeometry($first)
            || !$this->pdfLayoutHasGeometry($second)
            || ($first['code'] ?? false) === true
            || ($second['code'] ?? false) === true
            || !isset($first['sourceOrderStart'], $first['sourceOrderEnd'], $second['sourceOrderStart'])) {
            return false;
        }
        if ($this->positionedPdfStableColumnFragmentSeparator($first, $second) === null) {
            return false;
        }

        if ((int) ($first['page'] ?? 0) !== (int) ($second['page'] ?? 0)) {
            return false;
        }

        $fontSize = max(1.0, (float) $first['fontSize'], (float) $second['fontSize'], $column['fontSize']);
        if (abs((float) $first['fontSize'] - (float) $second['fontSize']) > max(1.5, $fontSize * 0.25)) {
            return false;
        }

        $firstCenter = ((float) $first['y1'] + (float) $first['y2']) / 2.0;
        $secondCenter = ((float) $second['y1'] + (float) $second['y2']) / 2.0;
        if (abs($firstCenter - $secondCenter) > max(2.5, $fontSize * 0.35)) {
            return false;
        }

        $firstStart = (int) $first['sourceOrderStart'];
        $firstEnd = (int) $first['sourceOrderEnd'];
        $secondStart = (int) $second['sourceOrderStart'];
        if ($secondStart <= $firstEnd || $secondStart - $firstEnd > 48) {
            return false;
        }

        if ((float) $second['x1'] < (float) $first['x1'] - max(2.0, $fontSize * 0.25)) {
            return false;
        }

        $gap = (float) $second['x1'] - (float) $first['x2'];
        $maximumGap = min(36.0, max(18.0, $column['width'] * 0.25));
        if ($gap > $maximumGap
            && $this->positionedPdfExactSourceAdjacentPunctuationFragments($first, $second)) {
            // A right-edge sentence boundary can be separated from a short
            // left-side run by justification or an unpainted form lane. Keep
            // this exception inside the already detected column span; exact
            // adjacency must never bridge into the neighboring column.
            $columnTolerance = max(3.0, $fontSize * 0.40);
            $columnRight = $column['x'] + $column['width'];
            if ((float) $second['x1'] < $column['x'] - $columnTolerance
                || (float) $second['x2'] > $columnRight + $columnTolerance) {
                return false;
            }
            $maximumGap = max($maximumGap, min(160.0, $column['width'] * 0.60));
        }

        return $gap >= -max(24.0, $fontSize * 3.0)
            && $gap <= $maximumGap;
    }

    /**
     * Preserve the ordinary positioned boundary proof first. A PDF may also
     * split the punctuation ending one sentence and the start of the next
     * word into a fully aligned source occurrence painted immediately after
     * the preceding run. That occurrence has no independent word-boundary
     * flag, but exact adjacent source ranges, adjacent paint atoms, one shared
     * stream, and leading punctuation prove a compact join without guessing
     * from the word itself.
     *
     * @param array<string, mixed> $left
     * @param array<string, mixed> $right
     */
    private function positionedPdfStableColumnFragmentSeparator(array $left, array $right): ?string
    {
        $separator = $this->positionedPdfFragmentSeparator($left, $right);
        if ($separator !== null) {
            return $separator;
        }

        return $this->positionedPdfExactSourceAdjacentPunctuationFragments($left, $right)
            ? ''
            : null;
    }

    /**
     * @param array<string, mixed> $left
     * @param array<string, mixed> $right
     */
    private function positionedPdfExactSourceAdjacentPunctuationFragments(array $left, array $right): bool
    {

        $leftSourceStart = $left['sourcePdfSourceIndex'] ?? null;
        $leftSourceEnd = $left['sourcePdfSourceIndexEnd'] ?? $leftSourceStart;
        $rightSourceStart = $right['sourcePdfSourceIndex'] ?? null;
        if (($right['sourcePdfExactRangeFragmentSequence'] ?? false) !== true
            || !is_int($leftSourceStart)
            || !is_int($leftSourceEnd)
            || !is_int($rightSourceStart)
            || $rightSourceStart !== $leftSourceEnd + 1
            || ($left['page'] ?? null) !== ($right['page'] ?? null)
            || ($left['sourceStream'] ?? null) !== ($right['sourceStream'] ?? null)
            || !isset($left['sourceOrderEnd'], $right['sourceOrderStart'])
            || (int) $right['sourceOrderStart'] !== (int) $left['sourceOrderEnd'] + 1
            || $this->pdfPositionedExactSourceRanges($left) === []
            || $this->pdfPositionedExactSourceRanges($right) === []) {
            return false;
        }

        $leftText = rtrim((string) ($left['text'] ?? ''));
        $rightText = ltrim((string) ($right['text'] ?? ''));
        if ($leftText === ''
            || $rightText === ''
            || preg_match('/[.!?;:]$/u', $leftText) === 1
            || preg_match('/^[.,;:!?](?:\s|$)/u', $rightText) !== 1) {
            return false;
        }

        return true;
    }

    /**
     * @param array<string, mixed> $left
     * @param array<string, mixed> $right
     * @return array<string, mixed>|null
     */
    private function composePositionedPdfInlineLayoutFragments(array $left, array $right): ?array
    {
        $leftText = rtrim((string) ($left['text'] ?? ''));
        $rightText = ltrim((string) ($right['text'] ?? ''));
        $separator = $this->positionedPdfStableColumnFragmentSeparator($left, $right);
        if ($separator === null) {
            return null;
        }

        $leftTextX2 = (float) ($left['textX2'] ?? $left['x2'] ?? 0.0);
        $rightTextX1 = (float) ($right['textX1'] ?? $right['x1'] ?? 0.0);
        $fontSize = max(1.0, (float) ($left['fontSize'] ?? 0.0), (float) ($right['fontSize'] ?? 0.0));
        $sourceVerifiedBoundarySeparators = $this->positionedJoinedSourceVerifiedBoundarySeparators(
            $left,
            $right,
            $rightTextX1 - $leftTextX2,
            $fontSize,
            (bool) ($left['endsWithWhitespace'] ?? false),
            (bool) ($right['startsWithWhitespace'] ?? false),
            (bool) ($right['hasWordBoundaryBefore'] ?? false),
            (bool) ($right['wordBoundaryBefore'] ?? false),
            is_string($right['wordBoundarySource'] ?? null)
                ? $right['wordBoundarySource']
                : null
        );
        $sourceCompactBoundaryOffsets = $this->positionedJoinedSourceCompactBoundaryOffsets(
            $left,
            $right,
            $rightTextX1 - $leftTextX2,
            $fontSize,
            (bool) ($left['endsWithWhitespace'] ?? false),
            (bool) ($right['startsWithWhitespace'] ?? false),
            (bool) ($right['hasWordBoundaryBefore'] ?? false),
            (bool) ($right['wordBoundaryBefore'] ?? false),
            is_string($right['wordBoundarySource'] ?? null)
                ? $right['wordBoundarySource']
                : null
        );

        $composed = array_replace($left, [
            'text' => $leftText
                . ($leftText !== '' && $rightText !== '' ? $separator : '')
                . $rightText,
            'x1' => min((float) $left['x1'], (float) $right['x1']),
            'y1' => min((float) $left['y1'], (float) $right['y1']),
            'x2' => max((float) $left['x2'], (float) $right['x2']),
            'y2' => max((float) $left['y2'], (float) $right['y2']),
            'textX1' => min((float) ($left['textX1'] ?? $left['x1']), (float) ($right['textX1'] ?? $right['x1'])),
            'textY1' => min((float) ($left['textY1'] ?? $left['y1']), (float) ($right['textY1'] ?? $right['y1'])),
            'textX2' => max((float) ($left['textX2'] ?? $left['x2']), (float) ($right['textX2'] ?? $right['x2'])),
            'textY2' => max((float) ($left['textY2'] ?? $left['y2']), (float) ($right['textY2'] ?? $right['y2'])),
            'fontSize' => $fontSize,
            'sourceOrderStart' => min((int) $left['sourceOrderStart'], (int) $right['sourceOrderStart']),
            'sourceOrderEnd' => max((int) $left['sourceOrderEnd'], (int) $right['sourceOrderEnd']),
            'startsWithWhitespace' => (bool) ($left['startsWithWhitespace'] ?? false),
            'endsWithWhitespace' => (bool) ($right['endsWithWhitespace'] ?? false),
            'hasWordBoundaryBefore' => (bool) ($left['hasWordBoundaryBefore'] ?? false),
            'wordBoundaryBefore' => (bool) ($left['wordBoundaryBefore'] ?? false),
            'wordBoundarySource' => $left['wordBoundarySource'] ?? null,
            'sourceVerifiedBoundarySeparators' => $sourceVerifiedBoundarySeparators,
            'sourceCompactBoundaryOffsets' => $sourceCompactBoundaryOffsets,
            'sourceInlineLayoutComposite' => true,
        ]);
        $exactSourceRanges = $this->pdfPositionedExactSourceRangesForItems([$left, $right]);
        if ($exactSourceRanges !== []) {
            $composed['sourcePdfExactSourceRanges'] = $exactSourceRanges;
        }
        $leftSourceStart = $left['sourcePdfSourceIndex'] ?? null;
        $leftSourceEnd = $left['sourcePdfSourceIndexEnd'] ?? $leftSourceStart;
        $rightSourceStart = $right['sourcePdfSourceIndex'] ?? null;
        $rightSourceEnd = $right['sourcePdfSourceIndexEnd'] ?? $rightSourceStart;
        if (is_int($leftSourceStart)
            && is_int($leftSourceEnd)
            && is_int($rightSourceStart)
            && is_int($rightSourceEnd)
            && $rightSourceStart === $leftSourceEnd + 1) {
            $composed['sourcePdfSourceIndex'] = $leftSourceStart;
            $composed['sourcePdfSourceIndexEnd'] = $rightSourceEnd;
        }

        return $composed;
    }

    /**
     * A side figure can occupy the top of the next visual column while body
     * prose continues from the prior column below it. Move that continuation
     * ahead of the figure-side records only when an exact source/geometry
     * match proves both the line and its lower-case cross-column continuation.
     *
     * @param list<array<string, mixed>> $entries
     * @param list<array<string, mixed>>|null $previousColumnEntries
     * @return list<array<string, mixed>>
     */
    private function prioritizeSourcePdfVerifiedCrossColumnContinuation(array $entries, ?array $previousColumnEntries): array
    {
        if ($previousColumnEntries === null || $previousColumnEntries === []) {
            return $entries;
        }

        foreach ($entries as $index => $entry) {
            $predecessorIndex = $this->sourcePdfColumnContinuationPredecessorIndex(
                $previousColumnEntries,
                $entry
            );
            if (($entry['sourceVerifiedGeometryText'] ?? false) !== true
                || ($index !== 0
                    && ($entry['forceBlockBreakBefore'] ?? false) !== true
                    && !$this->sourcePdfEntryFollowsSideFigureInterruption($entries, $index))
                || $predecessorIndex === null) {
                continue;
            }
            $predecessor = $previousColumnEntries[$predecessorIndex] ?? null;
            $continuationProof = is_array($predecessor)
                ? $this->sourcePdfVerifiedCrossColumnContinuationProof($predecessor, $entry)
                : null;
            if ($continuationProof === null) {
                continue;
            }

            unset(
                $entry['sourceInterruptedColumnRegion'],
                $entry['sourceUnresolvedInterruptedFlow'],
                $entry['sourceOrphanedInferredContinuation'],
                $entry['forceBlockBreakBefore']
            );
            $entry['sourceCrossColumnContinuation'] = true;
            $entry['sourceCrossColumnPredecessorIndex'] = $predecessorIndex;
            $entry['sourceCrossColumnContinuationProof'] = $continuationProof;
            $entries[$index] = $entry;

            for ($continuationIndex = $index + 1; isset($entries[$continuationIndex]); $continuationIndex++) {
                $continuation = $entries[$continuationIndex];
                if (($continuation['page'] ?? null) !== ($entry['page'] ?? null)
                    || ($continuation['sourceGeometryColumn'] ?? null) !== ($entry['sourceGeometryColumn'] ?? null)
                    || ($continuation['sourceVerifiedGeometryText'] ?? false) !== true
                    || ($continuation['forceBlockBreakBefore'] ?? false) === true
                    || preg_match('/^[^\p{L}\p{N}]*\p{Ll}/u', ltrim((string) ($continuation['text'] ?? ''))) !== 1) {
                    break;
                }
                unset(
                    $continuation['sourceInterruptedColumnRegion'],
                    $continuation['sourceUnresolvedInterruptedFlow'],
                    $continuation['sourceOrphanedInferredContinuation']
                );
                $entries[$continuationIndex] = $continuation;
            }

            return array_merge(array_slice($entries, $index), array_slice($entries, 0, $index));
        }

        return $entries;
    }

    /**
     * Bind the two exact geometry carriers which establish a cross-column
     * paragraph edge. The shared proof lets later source-adjacency recovery
     * distinguish that edge from an intervening footnote in content order.
     *
     * @param array<string,mixed> $previous
     * @param array<string,mixed> $continuation
     * @return array<string,mixed>|null
     */
    private function sourcePdfVerifiedCrossColumnContinuationProof(
        array $previous,
        array $continuation
    ): ?array {
        $previousStart = $previous['sourcePdfSourceIndex'] ?? null;
        $previousEnd = $previous['sourcePdfSourceIndexEnd'] ?? $previousStart;
        $continuationStart = $continuation['sourcePdfSourceIndex'] ?? null;
        $continuationEnd = $continuation['sourcePdfSourceIndexEnd'] ?? $continuationStart;
        $previousColumn = $previous['sourceGeometryColumn'] ?? null;
        $continuationColumn = $continuation['sourceGeometryColumn'] ?? null;
        if (!$this->pdfLayoutHasGeometry($previous)
            || !$this->pdfLayoutHasGeometry($continuation)
            || ($previous['sourceVerifiedGeometryText'] ?? false) !== true
            || ($continuation['sourceVerifiedGeometryText'] ?? false) !== true
            || !is_int($previousStart)
            || !is_int($previousEnd)
            || !is_int($continuationStart)
            || !is_int($continuationEnd)
            || !is_int($previousColumn)
            || !is_int($continuationColumn)
            || $continuationColumn !== $previousColumn + 1
            || ($previous['page'] ?? null) !== ($continuation['page'] ?? null)
            || ($previous['sourceStream'] ?? null) !== ($continuation['sourceStream'] ?? null)) {
            return null;
        }

        $previousProjection = $this->pdfSourceOccurrenceComparableText(
            (string) ($previous['text'] ?? '')
        );
        $continuationProjection = $this->pdfSourceOccurrenceComparableText(
            (string) ($continuation['text'] ?? '')
        );
        if ($previousProjection === '' || $continuationProjection === '') {
            return null;
        }

        $proof = [
            'version' => 1,
            'method' => 'exact-geometry-cross-column-continuation',
            'sourceSha256' => $this->sourceSha256,
            'page' => (int) $previous['page'],
            'sourceStream' => (int) $previous['sourceStream'],
            'previousColumn' => $previousColumn,
            'continuationColumn' => $continuationColumn,
            'previousSourceStart' => $previousStart,
            'previousSourceEnd' => $previousEnd,
            'continuationSourceStart' => $continuationStart,
            'continuationSourceEnd' => $continuationEnd,
            'previousProjectionDigest' => hash('sha256', $previousProjection),
            'continuationProjectionDigest' => hash('sha256', $continuationProjection),
            'previousGeometryDigest' => $this->sourcePdfExactGeometryProofDigest($previous),
            'continuationGeometryDigest' => $this->sourcePdfExactGeometryProofDigest($continuation),
        ];
        $proof['proofDigest'] = hash('sha256', json_encode(
            $proof,
            JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE
        ) ?: '');

        return $proof;
    }

    /** @param array<string,mixed> $previous @param array<string,mixed> $continuation */
    private function sourcePdfItemsShareVerifiedCrossColumnContinuationProof(
        array $previous,
        array $continuation
    ): bool {
        $previousProof = $previous['sourceCrossColumnContinuationProof'] ?? null;
        $continuationProof = $continuation['sourceCrossColumnContinuationProof'] ?? null;
        if (($previous['sourceCrossColumnContinuationTail'] ?? false) !== true
            || ($continuation['sourceCrossColumnContinuation'] ?? false) !== true
            || !is_array($previousProof)
            || !is_array($continuationProof)
            || $previousProof !== $continuationProof) {
            return false;
        }

        $expected = $this->sourcePdfVerifiedCrossColumnContinuationProof(
            $previous,
            $continuation
        );

        return is_array($expected) && $expected === $continuationProof;
    }

    /**
     * A lower-case body line can continue an unfinished paragraph from the
     * previous column below a side figure or table. The large local gap makes
     * it a visual interruption rather than an ordinary wrapped line.
     *
     * @param list<array<string, mixed>> $entries
     */
    private function sourcePdfEntryFollowsSideFigureInterruption(array $entries, int $index): bool
    {
        if ($index < 1 || !isset($entries[$index - 1], $entries[$index])) {
            return false;
        }

        $previous = $entries[$index - 1];
        $current = $entries[$index];
        if (!$this->pdfLayoutHasGeometry($previous)
            || !$this->pdfLayoutHasGeometry($current)
            || ($previous['page'] ?? null) !== ($current['page'] ?? null)
            || ($previous['sourceGeometryColumn'] ?? null) !== ($current['sourceGeometryColumn'] ?? null)
            || ($previous['code'] ?? false) === true
            || ($current['code'] ?? false) === true
            || isset($previous['sourcePdfTableGroup'], $current['sourcePdfTableGroup'])
            || preg_match('/^[^\p{L}\p{N}]*\p{Ll}/u', ltrim((string) ($current['text'] ?? ''))) !== 1) {
            return false;
        }

        $fontSize = max(1.0, (float) $previous['fontSize'], (float) $current['fontSize']);
        $verticalGap = (float) $previous['y1'] - (float) $current['y1'];

        return $verticalGap >= max(24.0, $fontSize * 2.8);
    }

    /**
     * Some PDF readers retain source provenance only after a page has chosen
     * its final geometry path. Re-apply the verified continuation ordering at
     * that boundary so a side figure cannot separate a proven paragraph.
     *
     * @param list<array<string, mixed>> $items
     * @param list<array<string, mixed>> $sourceItems
     * @return list<array<string, mixed>>
     */
    private function prioritizeSourcePdfVerifiedCrossColumnContinuationPages(
        array $items,
        array $sourceItems
    ): array
    {
        $this->prioritizeSourcePdfVerifiedCrossColumnContinuationPagesInPlace(
            $items,
            $sourceItems
        );

        return $items;
    }

    /**
     * @param list<array<string, mixed>> $items
     * @param list<array<string, mixed>> $sourceItems
     */
    private function prioritizeSourcePdfVerifiedCrossColumnContinuationPagesInPlace(
        array &$items,
        array $sourceItems
    ): void
    {
        if (!$this->sourcePdfItemsMayContainVerifiedCrossColumnContinuation($items)) {
            return;
        }

        $pages = [];
        foreach ($items as $itemIndex => $item) {
            $pages[(string) ($item['page'] ?? 0)][] = $item;
            unset($items[$itemIndex]);
        }
        $items = [];
        $sourceIndexesByPage = [];
        foreach ($sourceItems as $globalSourceIndex => $sourceItem) {
            $sourceIndexesByPage[(string) ($sourceItem['page'] ?? 0)][] = $globalSourceIndex;
        }

        $ordered = [];
        foreach ($pages as $page => $pageItems) {
            $frontMatter = [];
            $columns = [];
            $other = [];
            foreach ($pageItems as $item) {
                if (($item['sourcePdfFrontMatter'] ?? false) === true) {
                    $frontMatter[] = $item;
                    continue;
                }
                if (($item['sourcePdfFallbackOrderProjection'] ?? false) !== true
                    && ($item['sourceStructuredGeometry'] ?? false) === true
                    && isset($item['sourceGeometryColumn'])
                    && ($item['sourceMinorFontFlow'] ?? false) !== true) {
                    $columns[(int) $item['sourceGeometryColumn']][] = $item;
                    continue;
                }
                $other[] = $item;
            }
            if (count($columns) < 2) {
                foreach ($frontMatter as $item) {
                    $ordered[] = $item;
                }
                foreach ($pageItems as $item) {
                    if (($item['sourcePdfFrontMatter'] ?? false) !== true) {
                        $ordered[] = $item;
                    }
                }
                unset($pages[$page], $pageItems, $frontMatter, $columns, $other);
                continue;
            }

            ksort($columns, SORT_NUMERIC);
            $previousColumnEntries = null;
            $previousColumn = null;
            $orderedColumns = [];
            $changed = false;
            foreach ($columns as $columnIndex => $entries) {
                $entries = $previousColumn !== null && $columnIndex === $previousColumn + 1
                    ? $this->prioritizeSourcePdfVerifiedCrossColumnContinuation($entries, $previousColumnEntries)
                    : $entries;
                $crossColumnContinuation = array_values(array_filter(
                    $entries,
                    static fn (array $entry): bool => ($entry['sourceCrossColumnContinuation'] ?? false) === true
                ));
                if ($crossColumnContinuation !== []
                    && is_array($previousColumnEntries)
                    && $previousColumnEntries !== []
                    && $orderedColumns !== []) {
                    $tailIndex = $crossColumnContinuation[0]['sourceCrossColumnPredecessorIndex']
                        ?? array_key_last($previousColumnEntries);
                    if (isset($previousColumnEntries[$tailIndex])) {
                        $tail = $previousColumnEntries[$tailIndex];
                        for ($leadIndex = $tailIndex; isset($previousColumnEntries[$leadIndex]); $leadIndex--) {
                            $lead = $previousColumnEntries[$leadIndex];
                            if (($lead['page'] ?? null) !== ($tail['page'] ?? null)
                                || ($lead['sourceGeometryColumn'] ?? null) !== ($tail['sourceGeometryColumn'] ?? null)) {
                                break;
                            }
                            $lead['sourceCrossColumnContinuationLead'] = true;
                            if ($leadIndex === $tailIndex) {
                                $lead['sourceCrossColumnContinuationTail'] = true;
                                $continuationProof =
                                    $crossColumnContinuation[0]['sourceCrossColumnContinuationProof'] ?? null;
                                if (is_array($continuationProof)) {
                                    $lead['sourceCrossColumnContinuationProof'] = $continuationProof;
                                }
                            }
                            $previousColumnEntries[$leadIndex] = $lead;
                            foreach ($orderedColumns as $orderedIndex => $orderedEntry) {
                                if (($orderedEntry['sourcePdfSourceIndex'] ?? null) === ($lead['sourcePdfSourceIndex'] ?? null)
                                    && ($orderedEntry['x1'] ?? null) === ($lead['x1'] ?? null)
                                    && ($orderedEntry['y1'] ?? null) === ($lead['y1'] ?? null)) {
                                    $orderedColumns[$orderedIndex] = $lead;
                                    break;
                                }
                            }
                            if ($leadIndex !== $tailIndex
                                && ($lead['forceBlockBreakBefore'] ?? false) === true) {
                                break;
                            }
                        }
                    }
                }
                foreach ($entries as $entry) {
                    $changed = $changed || (($entry['sourceCrossColumnContinuation'] ?? false) === true);
                    $orderedColumns[] = $entry;
                }
                $previousColumnEntries = $entries;
                $previousColumn = $columnIndex;
            }
            if (!$changed) {
                foreach ($frontMatter as $item) {
                    $ordered[] = $item;
                }
                foreach ($pageItems as $item) {
                    if (($item['sourcePdfFrontMatter'] ?? false) !== true) {
                        $ordered[] = $item;
                    }
                }
                unset(
                    $pages[$page],
                    $pageItems,
                    $frontMatter,
                    $columns,
                    $other,
                    $orderedColumns,
                    $previousColumnEntries
                );
                continue;
            }

            // Rebuilding verified body columns deliberately appends floating
            // inventory afterwards. That must not undo an occurrence-local
            // continuation already established for an exact fallback. Apply
            // the same immediate source/page/stream proof to this page-local
            // result before it leaves the ordering stage.
            $pageSourceItems = [];
            foreach ($sourceIndexesByPage[$page] ?? [] as $globalSourceIndex) {
                $sourceItem = $sourceItems[$globalSourceIndex];
                if (!is_int($sourceItem['sourcePdfGlobalSourceIndex'] ?? null)) {
                    $sourceItem['sourcePdfGlobalSourceIndex'] = $globalSourceIndex;
                }
                $pageSourceItems[] = $sourceItem;
            }
            $pageItems = $this->restoreSourcePdfAdjacentVisualContinuations(
                array_merge($frontMatter, $orderedColumns, $other),
                $pageSourceItems
            );
            foreach ($pageItems as $item) {
                $ordered[] = $item;
            }
            unset(
                $pages[$page],
                $pageItems,
                $pageSourceItems,
                $frontMatter,
                $columns,
                $other,
                $orderedColumns,
                $previousColumnEntries
            );
        }

        $items = $ordered;
    }

    /**
     * Test the proof's necessary pairwise facts before allocating page and
     * column inventories. The full pass remains authoritative whenever one
     * possible pair survives this deliberately broader preflight.
     *
     * @param list<array<string,mixed>> $items
     */
    private function sourcePdfItemsMayContainVerifiedCrossColumnContinuation(
        array $items
    ): bool {
        foreach ($items as $continuationIndex => $continuation) {
            if (($continuation['sourceCrossColumnContinuation'] ?? false) === true) {
                // This marker is produced only after the full pairwise proof.
                // A later page rebuild must honor it even when the compact
                // source-proof fields have already been consumed.
                return true;
            }
            if (($continuation['sourcePdfFrontMatter'] ?? false) === true
                || ($continuation['sourcePdfFallbackOrderProjection'] ?? false) === true
                || ($continuation['sourceStructuredGeometry'] ?? false) !== true
                || !is_int($continuation['sourceGeometryColumn'] ?? null)
                || ($continuation['sourceMinorFontFlow'] ?? false) === true
                || ($continuation['sourceVerifiedGeometryText'] ?? false) !== true
                || !$this->pdfLayoutHasGeometry($continuation)
                || ($continuation['code'] ?? false) === true
                || isset($continuation['sourcePdfTableGroup'])
                || preg_match(
                    '/^[^\p{L}\p{N}]*\p{Ll}/u',
                    ltrim((string) ($continuation['text'] ?? ''))
                ) !== 1
                || count($this->pdfLineWordTokens(
                    (string) ($continuation['text'] ?? '')
                )) < 4) {
                continue;
            }
            $continuationColumn = $continuation['sourceGeometryColumn'];
            $previousInColumn = null;
            foreach ($items as $candidateIndex => $candidate) {
                if ($candidateIndex === $continuationIndex) {
                    break;
                }
                if (($candidate['sourcePdfFrontMatter'] ?? false) !== true
                    && ($candidate['sourcePdfFallbackOrderProjection'] ?? false) !== true
                    && ($candidate['sourceStructuredGeometry'] ?? false) === true
                    && isset($candidate['sourceGeometryColumn'])
                    && (int) $candidate['sourceGeometryColumn'] === $continuationColumn
                    && ($candidate['sourceMinorFontFlow'] ?? false) !== true
                    && ($candidate['page'] ?? null) === ($continuation['page'] ?? null)) {
                    $previousInColumn = $candidate;
                }
            }
            if (is_array($previousInColumn)
                && ($continuation['forceBlockBreakBefore'] ?? false) !== true
                && !$this->sourcePdfEntryFollowsSideFigureInterruption(
                    [$previousInColumn, $continuation],
                    1
                )) {
                continue;
            }
            foreach ($items as $predecessor) {
                if (($predecessor['sourcePdfFrontMatter'] ?? false) === true
                    || ($predecessor['sourcePdfFallbackOrderProjection'] ?? false) === true
                    || ($predecessor['sourceStructuredGeometry'] ?? false) !== true
                    || ($predecessor['sourceGeometryColumn'] ?? null)
                        !== $continuationColumn - 1
                    || ($predecessor['sourceMinorFontFlow'] ?? false) === true
                    || ($predecessor['page'] ?? null) !== ($continuation['page'] ?? null)
                    || $this->sourcePdfColumnContinuationPredecessorIndex(
                        [$predecessor],
                        $continuation
                    ) === null) {
                    continue;
                }
                if ($this->sourcePdfVerifiedCrossColumnContinuationProof(
                    $predecessor,
                    $continuation
                ) !== null) {
                    return true;
                }
            }
        }

        return false;
    }

    /**
     * Short positioned text is useful only after source-only lines have been
     * attached to their neighboring geometry. At that point a real body lane
     * can corroborate the candidate; otherwise discard it rather than leaking
     * figure labels into prose.
     *
     * @param list<array<string, mixed>> $items
     * @return list<array<string, mixed>>
     */
    private function retainSourcePdfShortPositionedBodySupplements(array $items): array
    {
        $hasCandidates = false;
        foreach ($items as $item) {
            if (($item['sourceShortSupplementalCandidate'] ?? false) === true) {
                $hasCandidates = true;
                break;
            }
        }
        if (!$hasCandidates) {
            return $items;
        }

        $geometryItems = array_values(array_filter(
            $items,
            fn (array $item): bool => $this->pdfLayoutHasGeometry($item)
        ));
        $columns = $this->sourcePdfStableTextColumns($geometryItems);
        if (!$this->sourcePdfColumnsLookLikeParallelBodyColumns($columns)) {
            return array_values(array_filter(
                $items,
                static fn (array $item): bool => ($item['sourceShortSupplementalCandidate'] ?? false) !== true
            ));
        }

        $filtered = [];
        foreach ($items as $item) {
            if (($item['sourceShortSupplementalCandidate'] ?? false) !== true) {
                $filtered[] = $item;
                continue;
            }
            if ($this->sourcePdfShortSupplementalDuplicatesVisibleSourceItem($item, $items)) {
                continue;
            }
            if (!$this->positionedPdfShortLineCanSupplementMatchedBodyFlow($item, $items)
                && !$this->positionedPdfShortLineCanSupplementStableBodyColumn($item, $columns, $items)) {
                continue;
            }
            $item['sourceSupplementalBodyFlow'] = true;
            $filtered[] = $item;
        }

        return $filtered;
    }

    /**
     * A small positioned fragment can be part of the same visual row as a
     * complete source-matched line. In that situation it is a duplicate text
     * layer, not omitted body content, even if the surrounding body column is
     * otherwise strong enough to retain short positioned supplements.
     *
     * @param array<string, mixed> $supplement
     * @param list<array<string, mixed>> $items
     */
    private function sourcePdfShortSupplementalDuplicatesVisibleSourceItem(array $supplement, array $items): bool
    {
        if (!$this->pdfLayoutHasGeometry($supplement)) {
            return false;
        }
        $shortText = $this->pdfComparableLineText((string) ($supplement['text'] ?? ''));
        if ($this->length($shortText) < 8) {
            return false;
        }

        foreach ($items as $source) {
            if (($source['sourceSupplementalPositioned'] ?? false) === true
                || !$this->pdfLayoutHasGeometry($source)
                || ($source['page'] ?? null) !== ($supplement['page'] ?? null)
                || ($source['sourceGeometryColumn'] ?? null) !== ($supplement['sourceGeometryColumn'] ?? null)) {
                continue;
            }
            $sourceText = $this->pdfComparableLineText((string) ($source['text'] ?? ''));
            if ($this->length($sourceText) <= $this->length($shortText)
                || !str_contains($sourceText, $shortText)) {
                continue;
            }
            $fontSize = max(1.0, (float) $source['fontSize'], (float) $supplement['fontSize']);
            if (abs((float) $source['y1'] - (float) $supplement['y1']) > max(2.0, $fontSize * 0.40)
                || abs((float) $source['x1'] - (float) $supplement['x1']) > max(8.0, $fontSize)
                || (float) $supplement['x2'] > (float) $source['x2'] + max(8.0, $fontSize)) {
                continue;
            }

            return true;
        }

        return false;
    }

    /**
     * Footnotes and figure-side prose commonly use a smaller font than the
     * body column. Keep them as normal content when complete, but record their
     * lower confidence so an unfinished tail is not emitted as body prose.
     *
     * @param list<array<string, mixed>> $items
     * @return list<array<string, mixed>>
     */
    private function markSourcePdfMinorFontFlows(array $items, float $bodyFontSize): array
    {
        $threshold = max(1.0, $bodyFontSize * 0.93);
        foreach ($items as &$item) {
            if ($this->pdfLayoutHasGeometry($item)
                && (float) $item['fontSize'] < $threshold
                && !isset($item['sourcePdfTableGroup'])
                && ($item['code'] ?? false) !== true) {
                $item['sourceMinorFontFlow'] = true;
            }
        }
        unset($item);

        return $items;
    }

    /**
     * A page can contain a regular prose column beside a table, illustration,
     * or partially extractable formula. A broad vertical range between all
     * detached fragments is not evidence that the entire column is damaged.
     * Instead, mark only a body line that overlaps a detached fragment in the
     * same local visual band. The later flow check can then reject an
     * incomplete run without discarding unrelated prose above or below it.
     *
     * @param list<array<string, mixed>> $items
     * @param list<array<string, mixed>> $floating
     * @return list<array<string, mixed>>
     */
    private function markSourcePdfInterruptedColumnFragments(array $items, array $floating): array
    {
        foreach ($items as &$item) {
            if (isset($item['sourcePdfTableGroup'])
                || ($item['code'] ?? false) === true
                || !$this->pdfLayoutHasGeometry($item)) {
                continue;
            }
            foreach ($floating as $fragment) {
                if ($this->sourcePdfFloatingFragmentInterruptsColumnFlow($item, $fragment)) {
                    $item['sourceInterruptedColumnRegion'] = true;
                    break;
                }
            }
        }
        unset($item);

        return $items;
    }

    /**
     * @param array<string, mixed> $columnItem
     * @param array<string, mixed> $fragment
     */
    private function sourcePdfFloatingFragmentInterruptsColumnFlow(array $columnItem, array $fragment): bool
    {
        if (!$this->pdfLayoutHasGeometry($columnItem) || !$this->pdfLayoutHasGeometry($fragment)) {
            return false;
        }

        $fontSize = max(1.0, (float) $columnItem['fontSize'], (float) $fragment['fontSize']);
        $columnWidth = max(0.0, (float) $columnItem['x2'] - (float) $columnItem['x1']);
        if ($columnWidth < $fontSize * 10.0) {
            return false;
        }

        // A detached item can only interrupt a body line when it occupies the
        // same visual band. A multi-line tolerance turns a clipped text run
        // into false damage evidence for its neighboring prose lines.
        $columnCenter = ((float) $columnItem['y1'] + (float) $columnItem['y2']) / 2.0;
        $fragmentCenter = ((float) $fragment['y1'] + (float) $fragment['y2']) / 2.0;
        if (abs($columnCenter - $fragmentCenter) > max(4.0, $fontSize * 0.90)) {
            return false;
        }

        $horizontalTolerance = max(4.0, $fontSize * 0.75);
        return (float) $fragment['x2'] >= (float) $columnItem['x1'] - $horizontalTolerance
            && (float) $fragment['x1'] <= (float) $columnItem['x2'] + $horizontalTolerance;
    }

    /**
     * Once a page has stable body columns, text outside those anchors has no
     * reliable place in the prose flow. Retain only content that can stand on
     * its own structurally; table cells and code remain source-ordered and a
     * complete caption or display label remains useful independently.
     *
     * @param array<string, mixed> $item
     */
    private function sourcePdfFloatingItemCanStandAlone(array $item, float $medianFontSize): bool
    {
        if (isset($item['sourcePdfTableGroup']) || ($item['code'] ?? false) === true) {
            return true;
        }

        $text = trim((string) ($item['text'] ?? ''));
        if ($text === '') {
            return false;
        }
        if ($this->lineHasPdfListBlockEvidence($text) || $this->lineLooksLikeUrlOnly($text)) {
            return true;
        }
        if ($this->length($text) >= 64
            && count($this->pdfLineWordTokens($text)) >= 12
            && (($item['sourceUnmatchedFallback'] ?? false) === true
                || preg_match('/^[^\p{L}\p{N}]*\p{Lu}/u', $text) === 1)) {
            return true;
        }

        if ($this->pdfLayoutHasGeometry($item)
            && (float) $item['fontSize'] > $medianFontSize * 1.35
            && count($this->pdfLineWordTokens($text)) >= 2) {
            return true;
        }

        return $this->length($text) >= 48
            && count($this->pdfLineWordTokens($text)) >= 8
            && preg_match('/[.!?;:]\s*$/u', $text) === 1;
    }

    /**
     * In typeset prose, wrapped lines return to the column edge while a new
     * paragraph often begins with a small indent. Retain that visual boundary
     * even when the PDF text stream itself has no paragraph marker.
     *
     * @param list<array<string, mixed>> $items
     * @param array{x: float, width: float, fontSize: float, count: int} $column
     * @return list<array<string, mixed>>
     */
    private function markSourcePdfIndentedParagraphBoundaries(array $items, array $column): array
    {
        $count = count($items);
        for ($index = 1; $index < $count; $index++) {
            $previous = $items[$index - 1];
            $current = $items[$index];
            $text = ltrim((string) ($current['text'] ?? ''));
            if ($text === ''
                || ($current['code'] ?? false) === true
                || $this->lineHasPdfListBlockEvidence($text)
                || preg_match('/^[^\p{L}\p{N}]*\p{Lu}/u', $text) !== 1) {
                continue;
            }

            $fontSize = max((float) $previous['fontSize'], (float) $current['fontSize'], $column['fontSize'], 1.0);
            $step = (float) $previous['y1'] - (float) $current['y1'];
            if ($step < $fontSize * 0.30 || $step > $fontSize * 1.80) {
                continue;
            }

            $indent = (float) $current['x1'] - $column['x'];
            if ($indent < $fontSize * 0.80 || $indent > min(32.0, $column['width'] * 0.14)) {
                continue;
            }

            // A list marker can be painted in a glyph run that has no
            // usable text mapping. Its first text line then starts slightly
            // left of its wrapped hanging continuation. The preceding visual
            // gap already marks the list item boundary; do not split its
            // immediately following line into a second paragraph.
            $hangingOffset = (float) $current['x1'] - (float) $previous['x1'];
            if (($previous['forceBlockBreakBefore'] ?? false) === true
                && $hangingOffset >= $fontSize * 0.45
                && $hangingOffset <= $fontSize * 1.75
                && preg_match('/[.!?;:]\s*$/u', rtrim((string) ($previous['text'] ?? ''))) !== 1) {
                continue;
            }

            $items[$index]['forceBlockBreakBefore'] = true;
        }

        return $items;
    }

    /**
     * A stable body column should advance in a regular baseline rhythm. When
     * a new run begins after a clear gap with continuation punctuation or a
     * lower-case letter, the missing material is spatially observable: it is
     * not safe to make that run a new paragraph. Likewise, a wrapped hyphen
     * with no nearby continuation on the same page is a damaged flow rather
     * than a complete block.
     *
     * @param list<array<string, mixed>> $items
     * @param list<array<string, mixed>>|null $previousColumnItems
     * @param array{x: float, width: float, fontSize: float, count: int} $column
     * @return list<array<string, mixed>>
     */
    private function markSourcePdfOrphanedColumnFlows(
        array $items,
        ?array $previousColumnItems = null,
        array $column = []
    ): array
    {
        $count = count($items);
        for ($index = 0; $index < $count; $index++) {
            $item = $items[$index];
            $text = trim((string) ($item['text'] ?? ''));
            if ($text === ''
                || isset($item['sourcePdfTableGroup'])
                || ($item['code'] ?? false) === true
                || $this->lineHasPdfListBlockEvidence($text)
                || !$this->pdfLayoutHasGeometry($item)) {
                continue;
            }

            $previous = $index > 0 ? $items[$index - 1] : null;
            $startsWithOrphanPunctuation = preg_match('/^[,.;:\)\]\}]/u', $text) === 1;
            $startsParentheticalAfterGap = preg_match('/^\(/u', $text) === 1
                && ($previous === null || $this->sourcePdfColumnFlowHasUnexpectedGap($previous, $item));
            $startsUnsafeColumn = $index === 0
                && preg_match('/^[^\p{L}\p{N}]*\p{Ll}/u', $text) === 1
                && !$this->sourcePdfColumnLeadingItemContinuesPreviousColumn($previousColumnItems, $item);
            $startsForcedLowercaseFragment = ($item['forceBlockBreakBefore'] ?? false) === true
                && preg_match('/^[^\p{L}\p{N}]*\p{Ll}/u', $text) === 1;
            $startsWithUnexpectedMissingPrefix = $previous !== null
                && $this->sourcePdfColumnLineStartsWithUnexpectedMissingPrefix($previous, $item, $column);
            $followsEncodingNoise = $previous !== null
                && $this->lineIsOnlyPdfNoise((string) ($previous['text'] ?? ''))
                && preg_match('/^[^\p{L}\p{N}]*\p{Ll}/u', $text) === 1;
            // A lower-case visual continuation immediately after a line whose
            // geometry already proves an interruption belongs to that damaged
            // flow. Do not let a subsequent font-run reconciliation turn it
            // into an independent body paragraph.
            $followsInterruptedFlow = $previous !== null
                && ($previous['sourceInterruptedColumnRegion'] ?? false) === true
                && ($previous['sourceStream'] ?? null) === ($item['sourceStream'] ?? null)
                && ($previous['sourceGeometryColumn'] ?? null) === ($item['sourceGeometryColumn'] ?? null)
                && ($item['forceBlockBreakBefore'] ?? false) !== true
                && !$this->sourcePdfColumnFlowHasUnexpectedGap($previous, $item)
                && preg_match('/^[^\p{L}\p{N}]*\p{Ll}/u', $text) === 1;
            if ($startsWithOrphanPunctuation
                || $startsParentheticalAfterGap
                || $startsUnsafeColumn
                || $startsForcedLowercaseFragment
                || $startsWithUnexpectedMissingPrefix
                || $followsEncodingNoise
                || $followsInterruptedFlow
                || ($previous !== null
                    && $this->sourcePdfColumnFlowHasUnexpectedGap($previous, $item)
                    && preg_match('/^[^\p{L}\p{N}]*\p{Ll}/u', $text) === 1)) {
                $items[$index]['sourceInterruptedColumnRegion'] = true;
                if ($startsWithOrphanPunctuation
                    && $previous !== null
                    && !$this->sourcePdfColumnFlowHasUnexpectedGap($previous, $item)
                    && preg_match('/[.!?;:]\s*$/u', rtrim((string) ($previous['text'] ?? ''))) !== 1) {
                    $items[$index - 1]['sourceInterruptedColumnRegion'] = true;
                }
            }
            if ($startsWithUnexpectedMissingPrefix) {
                if ($previous !== null) {
                    $items[$index - 1]['sourceInterruptedColumnRegion'] = true;
                }
                $items[$index]['forceBlockBreakBefore'] = true;
            }

            if (preg_match('/[-\x{2010}-\x{2015}]\s*$/u', $text) !== 1) {
                continue;
            }
            $next = $items[$index + 1] ?? null;
            if ($next !== null && $this->sourcePdfColumnFlowHasUnexpectedGap($item, $next)) {
                $items[$index]['sourceInterruptedColumnRegion'] = true;
            }
        }

        return $items;
    }

    /**
     * In a regular text column, a lower-case wrapped line normally returns to
     * the column edge. A much larger left gap while the preceding line remains
     * unfinished means glyphs are missing from the beginning of this visual
     * line. It is not a first-line indent because that starts a new, normally
     * capitalized paragraph after a boundary.
     *
     * @param array<string, mixed> $previous
     * @param array<string, mixed> $current
     * @param array{x?: float, width?: float, fontSize?: float, count?: int} $column
     */
    private function sourcePdfColumnLineStartsWithUnexpectedMissingPrefix(
        array $previous,
        array $current,
        array $column
    ): bool {
        if (!$this->pdfLayoutHasGeometry($previous) || !$this->pdfLayoutHasGeometry($current)
            || !isset($column['x'])
            || ($previous['page'] ?? null) !== ($current['page'] ?? null)
            || ($previous['code'] ?? false) === true
            || ($current['code'] ?? false) === true) {
            return false;
        }

        $previousText = rtrim((string) ($previous['text'] ?? ''));
        $currentText = ltrim((string) ($current['text'] ?? ''));
        if ($previousText === '' || $currentText === ''
            || $this->lineHasPdfListBlockEvidence($previousText)
            || $this->lineHasPdfListBlockEvidence($currentText)
            || preg_match('/^[^\p{L}\p{N}]*\p{Ll}/u', $currentText) !== 1
            || preg_match('/[.!?;:]\s*$/u', $previousText) === 1) {
            return false;
        }

        $fontSize = max(
            1.0,
            (float) $previous['fontSize'],
            (float) $current['fontSize'],
            (float) ($column['fontSize'] ?? 1.0)
        );
        $step = (float) $previous['y1'] - (float) $current['y1'];
        if ($step < $fontSize * 0.30 || $step > $fontSize * 1.80) {
            return false;
        }

        $leftGap = (float) $current['x1'] - (float) $column['x'];
        $minimumGap = max(24.0, $fontSize * 2.5, (float) ($column['width'] ?? 0.0) * 0.08);

        // A line-end hyphen is only a safe continuation when the next line
        // returns to the body edge. A lower-case run displaced deep into the
        // column has lost its leading visual content instead.
        return $leftGap > $minimumGap;
    }

    /**
     * @param list<array<string, mixed>>|null $previousColumnItems
     * @param array<string, mixed> $item
     */
    private function sourcePdfColumnLeadingItemContinuesPreviousColumn(?array $previousColumnItems, array $item): bool
    {
        return $this->sourcePdfColumnContinuationPredecessorIndex($previousColumnItems, $item) !== null;
    }

    /**
     * A footnote, caption, or small diagram can be the last physical item in
     * a column even when an unfinished body sentence above it continues in
     * the next column. Find the nearest compatible body line rather than
     * assuming the literal last item is the paragraph tail.
     *
     * @param list<array<string, mixed>>|null $previousColumnItems
     */
    private function sourcePdfColumnContinuationPredecessorIndex(?array $previousColumnItems, array $item): ?int
    {
        if ($previousColumnItems === null
            || $previousColumnItems === []
            || !$this->pdfLayoutHasGeometry($item)
            || ($item['code'] ?? false) === true
            || isset($item['sourcePdfTableGroup'])
            || ($item['sourceVerifiedGeometryText'] ?? false) !== true
            || preg_match('/^[^\p{L}\p{N}]*\p{Ll}/u', ltrim((string) ($item['text'] ?? ''))) !== 1
            || count($this->pdfLineWordTokens((string) ($item['text'] ?? ''))) < 4) {
            return null;
        }

        foreach (array_reverse(array_keys($previousColumnItems)) as $index) {
            $previous = $previousColumnItems[$index];
            if (!$this->pdfLayoutHasGeometry($previous)
                || ($previous['page'] ?? null) !== ($item['page'] ?? null)
                || ($previous['code'] ?? false) === true
                || isset($previous['sourcePdfTableGroup'])
                || ($previous['sourceVerifiedGeometryText'] ?? false) !== true
                || $this->lineHasPdfListBlockEvidence((string) ($previous['text'] ?? ''))
                || preg_match('/[.!?;:]\s*$/u', rtrim((string) ($previous['text'] ?? ''))) === 1
                || count($this->pdfLineWordTokens((string) ($previous['text'] ?? ''))) < 4) {
                continue;
            }

            $fontSize = max(1.0, (float) $previous['fontSize'], (float) $item['fontSize']);
            $smallerFontSize = min((float) $previous['fontSize'], (float) $item['fontSize']);
            if ($smallerFontSize / $fontSize < 0.92
                || abs((float) $previous['fontSize'] - (float) $item['fontSize']) > max(1.25, $fontSize * 0.20)
                || (float) $item['y1'] - (float) $previous['y1'] <= max(24.0, $fontSize * 3.0)) {
                continue;
            }

            return (int) $index;
        }

        return null;
    }

    /**
     * @param array<string, mixed> $upper
     * @param array<string, mixed> $lower
     */
    private function sourcePdfColumnFlowHasUnexpectedGap(array $upper, array $lower): bool
    {
        if (!$this->pdfLayoutHasGeometry($upper) || !$this->pdfLayoutHasGeometry($lower)
            || ($upper['page'] ?? null) !== ($lower['page'] ?? null)) {
            return false;
        }

        $fontSize = max(1.0, (float) $upper['fontSize'], (float) $lower['fontSize']);
        $step = (float) $upper['y1'] - (float) $lower['y1'];

        return $step > max(18.0, $fontSize * 2.6);
    }

    /**
     * @param list<array{x: float, width: float, fontSize: float, count: int}> $columns
     */
    private function sourcePdfColumnsLookLikeParallelBodyColumns(array $columns): bool
    {
        if (count($columns) < 2 || count($columns) > 4) {
            return false;
        }

        $widths = array_column($columns, 'width');
        $fontSize = max(array_column($columns, 'fontSize'));
        $minimumWidth = min($widths);
        $maximumWidth = max($widths);
        if ($minimumWidth < max(100.0, $fontSize * 12.0)
            || $maximumWidth / $minimumWidth > 1.30) {
            return false;
        }

        foreach ($columns as $index => $column) {
            if ($column['count'] < 8) {
                return false;
            }
            if (!isset($columns[$index + 1])) {
                continue;
            }

            $separation = $columns[$index + 1]['x'] - $column['x'];
            if ($separation < $minimumWidth * 0.65 || $separation > $maximumWidth * 1.65) {
                return false;
            }
        }

        return true;
    }

    /**
     * @param list<array<string, mixed>> $items
     * @return list<array{x: float, width: float, fontSize: float, count: int}>
     */
    private function sourcePdfStableTextColumns(array $items): array
    {
        $fontSizes = array_map(
            static fn (array $item): float => max(1.0, (float) $item['fontSize']),
            $items
        );
        $medianFontSize = max(1.0, $this->median($fontSizes));
        $startTolerance = max(18.0, $medianFontSize * 2.0);
        $groups = [];
        foreach ($items as $item) {
            $text = trim((string) ($item['text'] ?? ''));
            if (($item['code'] ?? false) === true
                || (float) $item['fontSize'] < $medianFontSize * 0.78
                || ($this->length($text) < 24 && count($this->pdfLineWordTokens($text)) < 5)) {
                continue;
            }

            $groupIndex = null;
            foreach ($groups as $index => $group) {
                if (abs((float) $item['x1'] - $group['x']) <= $startTolerance) {
                    $groupIndex = $index;
                    break;
                }
            }
            if ($groupIndex === null) {
                $groups[] = ['x' => (float) $item['x1'], 'items' => [$item]];
                continue;
            }
            $groups[$groupIndex]['items'][] = $item;
            $groups[$groupIndex]['x'] = $this->median(array_map(
                static fn (array $entry): float => (float) $entry['x1'],
                $groups[$groupIndex]['items']
            ));
        }

        $columns = [];
        foreach ($groups as $group) {
            $groupItems = $group['items'];
            if (count($groupItems) < 6) {
                continue;
            }
            usort($groupItems, static fn (array $left, array $right): int => (float) $right['y1'] <=> (float) $left['y1']);
            $rhythmPairs = 0;
            foreach ($groupItems as $index => $item) {
                if (!isset($groupItems[$index + 1])) {
                    break;
                }
                $next = $groupItems[$index + 1];
                $fontSize = max((float) $item['fontSize'], (float) $next['fontSize'], $medianFontSize, 1.0);
                $step = (float) $item['y1'] - (float) $next['y1'];
                if ($step >= $fontSize * 0.30 && $step <= $fontSize * 2.4) {
                    $rhythmPairs++;
                }
            }
            if ($rhythmPairs < max(3, (int) ceil((count($groupItems) - 1) * 0.35))) {
                continue;
            }

            $widths = array_map(
                static fn (array $item): float => max(1.0, (float) $item['x2'] - (float) $item['x1']),
                $groupItems
            );
            $width = $this->median($widths);
            if ($width < max(80.0, $medianFontSize * 12.0)) {
                continue;
            }
            $columns[] = [
                'x' => (float) $group['x'],
                'width' => $width,
                'fontSize' => $medianFontSize,
                'count' => count($groupItems),
            ];
        }

        usort($columns, static fn (array $left, array $right): int => $left['x'] <=> $right['x']);

        return $this->sourcePdfMergeIndentedColumnVariants($columns);
    }

    /**
     * A single text column can have a second recurring left edge for
     * first-line indents. Merge only nearby, similarly wide anchor groups so
     * that an indented paragraph does not become a phantom third column.
     *
     * @param list<array{x: float, width: float, fontSize: float, count: int}> $columns
     * @return list<array{x: float, width: float, fontSize: float, count: int}>
     */
    private function sourcePdfMergeIndentedColumnVariants(array $columns): array
    {
        $merged = [];
        foreach ($columns as $column) {
            $lastIndex = array_key_last($merged);
            if ($lastIndex === null) {
                $merged[] = $column;
                continue;
            }

            $last = $merged[$lastIndex];
            $minimumWidth = min($last['width'], $column['width']);
            $maximumWidth = max($last['width'], $column['width']);
            $indentTolerance = max(24.0, min(48.0, $minimumWidth * 0.16), max($last['fontSize'], $column['fontSize']) * 3.0);
            if ($column['x'] - $last['x'] > $indentTolerance || $maximumWidth / $minimumWidth > 1.35) {
                $merged[] = $column;
                continue;
            }

            $count = $last['count'] + $column['count'];
            $merged[$lastIndex] = [
                'x' => min($last['x'], $column['x']),
                'width' => max($last['width'], $column['width']),
                'fontSize' => (($last['fontSize'] * $last['count']) + ($column['fontSize'] * $column['count'])) / $count,
                'count' => $count,
            ];
        }

        return $merged;
    }

    /**
     * @param array<string, mixed> $item
     * @param list<array{x: float, width: float, fontSize: float, count: int}> $columns
     */
    private function sourcePdfColumnIndexForItem(array $item, array $columns): ?int
    {
        $bestIndex = null;
        $bestDistance = INF;
        foreach ($columns as $index => $column) {
            $fontSize = max((float) $item['fontSize'], $column['fontSize'], 1.0);
            $leftTolerance = max(16.0, $fontSize * 2.0);
            $indentTolerance = max(32.0, min(112.0, $column['width'] * 0.50), $fontSize * 4.0);
            $start = (float) $item['x1'];
            if ($start < $column['x'] - $leftTolerance || $start > $column['x'] + $indentTolerance) {
                continue;
            }
            $distance = abs($start - $column['x']);
            if ($distance < $bestDistance) {
                $bestIndex = $index;
                $bestDistance = $distance;
            }
        }

        return $bestIndex;
    }

    /**
     * @param array{page: int, stream: int, text: string} $left
     * @param array{page: int, stream: int, text: string} $right
     */
    private function sourcePdfItemsShareStream(array $left, array $right): bool
    {
        return $left['page'] === $right['page'] && $left['stream'] === $right['stream'];
    }

    private function sourcePdfLinesAreWrappedContinuation(string $previous, string $line): bool
    {
        if (preg_match('/[-\x{2010}-\x{2015}]\s*$/u', rtrim($previous)) === 1
            && preg_match('/^\s*[\p{L}\p{N}]/u', $line) === 1) {
            return true;
        }

        return preg_match('/[.!?]\s*$/u', rtrim($previous)) !== 1
            && preg_match('/^\s*\p{Ll}/u', $line) === 1;
    }

    /**
     * A short source-only phrase with an internal comma cannot stand alone
     * when the immediately following source line starts a capitalized visual
     * continuation. Infer its baseline from that known line rather than
     * dropping the phrase as a floating fragment. This deliberately excludes
     * terminal punctuation, labels, and list markers.
     */
    private function sourcePdfShortCommaLeadPrecedesKnownLayout(string $lead, string $following): bool
    {
        $lead = trim($lead);
        $following = ltrim($following);
        if ($lead === ''
            || $following === ''
            || $this->lineHasPdfListBlockEvidence($lead)
            || $this->lineLooksLikeUrlOnly($lead)
            || count($this->pdfLineWordTokens($lead)) > 4
            || $this->length($lead) > 42
            || preg_match('/^[^\p{L}\p{N}]*\p{Lu}/u', $lead) !== 1
            || preg_match('/,\s*[^\s]/u', $lead) !== 1
            || preg_match('/[.!?;:]\s*$/u', $lead) === 1) {
            return false;
        }

        return preg_match('/^[^\p{L}\p{N}]*\p{Lu}/u', $following) === 1;
    }

    /**
     * On a page where nearly all source text has a visual position, a short
     * unmatched lowercase fragment has no reliable place in reading order. It
     * is safer to omit that floating fragment than append it to an unrelated
     * column or figure caption. Uppercase labels, lists, URLs, and complete
     * sentences remain available to the normal fallback path.
     */
    private function sourcePdfUnmatchedLineLooksLikeFloatingFragment(string $line): bool
    {
        $line = trim($line);
        if ($line === ''
            || $this->lineHasPdfListBlockEvidence($line)
            || $this->lineLooksLikeUrlOnly($line)
            || preg_match('/[.!?;:]\s*$/u', $line) === 1
            || $this->length($line) > 28
            || count($this->pdfLineWordTokens($line)) > 5) {
            return false;
        }

        if (preg_match('/^\p{L}$/u', $line) === 1) {
            return true;
        }

        return preg_match('/^[^\p{L}]*\p{Ll}/u', $line) === 1
            || preg_match('/^\d+\s*[^\p{L}]?\s*\p{Ll}/u', $line) === 1;
    }

    /**
     * Once source lines have a reliable visual correspondence, an unplaced
     * fragment cannot safely be inserted into the reading order. Preserve
     * explicit structured content and independently complete prose, but keep
     * short or wrapped fragments out of the body flow.
     *
     * @param array<string, mixed> $item
     */
    private function sourcePdfUnmatchedFallbackCanStandAlone(array $item): bool
    {
        if (isset($item['sourcePdfTableGroup']) || ($item['code'] ?? false) === true) {
            return true;
        }

        $text = trim((string) ($item['text'] ?? ''));
        if ($this->lineLooksLikeUrlOnly($text) || $this->lineLooksLikeCompletePdfCaption($text)) {
            return true;
        }

        return $this->length($text) >= 48
            && count($this->pdfLineWordTokens($text)) >= 8
            && preg_match('/[.!?;:]\s*$/u', $text) === 1;
    }

    /**
     * @param array{page: int, stream: int, text: string} $sourceItem
     * @param array<string, mixed> $nextItem
     * @return array<string, mixed>
     */
    private function sourcePdfLineItemBeforeKnownLayout(array $sourceItem, array $nextItem): array
    {
        $layout = $this->sourcePdfInferredNeighborLayout($nextItem, 1.0);
        $item = $this->sourcePdfLineItem($sourceItem, $layout);
        $item['sourceInferredNeighborLayout'] = true;

        return $item;
    }

    /**
     * @param array{page: int, stream: int, text: string} $sourceItem
     * @param array<string, mixed> $previousItem
     * @return array<string, mixed>
     */
    private function sourcePdfLineItemAfterKnownLayout(array $sourceItem, array $previousItem): array
    {
        $layout = $this->sourcePdfInferredNeighborLayout($previousItem, -1.0);
        $item = $this->sourcePdfLineItem($sourceItem, $layout);
        $item['sourceInferredNeighborLayout'] = true;

        return $item;
    }

    /**
     * Infer one source-only record between two immediately adjacent visual
     * records. Interpolation is limited to the already-proven local body slot;
     * it is not a page-wide source-order fallback.
     *
     * @param array{page: int, stream: int, text: string} $sourceItem
     * @param array<string, mixed> $previousItem
     * @param array<string, mixed> $nextItem
     * @return array<string, mixed>
     */
    private function sourcePdfLineItemBetweenKnownLayouts(array $sourceItem, array $previousItem, array $nextItem): array
    {
        $layout = [
            'x1' => ((float) $previousItem['x1'] + (float) $nextItem['x1']) / 2.0,
            'y1' => ((float) $previousItem['y1'] + (float) $nextItem['y1']) / 2.0,
            'x2' => ((float) $previousItem['x2'] + (float) $nextItem['x2']) / 2.0,
            'y2' => ((float) $previousItem['y2'] + (float) $nextItem['y2']) / 2.0,
            'fontSize' => max(1.0, (float) $previousItem['fontSize'], (float) $nextItem['fontSize']),
        ];
        $item = $this->sourcePdfLineItem($sourceItem, $layout);
        $item['sourceInferredNeighborLayout'] = true;
        $item['sourceSandwichedNeighborLayout'] = true;

        return $item;
    }

    /**
     * @param array{page: int, stream: int, text: string} $sourceItem
     * @param array<string, mixed> $previousItem
     * @param array<string, mixed> $nextItem
     * @param list<array{item: array<string, mixed>, sourceIndex: int|null}> $visualEntries
     */
    private function sourcePdfMatchedLayoutsSandwichSourceOnlyItem(
        array $sourceItem,
        array $previousItem,
        array $nextItem,
        int $previousSourceIndex,
        int $nextSourceIndex,
        array $visualEntries
    ): bool {
        if ($this->sourcePdfSourceOnlyItemIsAdjacentFootnoteMarker(
            $sourceItem,
            $previousItem,
            $nextItem
        )) {
            return false;
        }

        if (!$this->pdfLayoutHasGeometry($previousItem)
            || !$this->pdfLayoutHasGeometry($nextItem)
            || (int) ($previousItem['page'] ?? 0) !== (int) ($nextItem['page'] ?? 0)) {
            return false;
        }

        $fontSize = max(1.0, (float) $previousItem['fontSize'], (float) $nextItem['fontSize']);
        $previousCenter = ((float) $previousItem['y1'] + (float) $previousItem['y2']) / 2.0;
        $nextCenter = ((float) $nextItem['y1'] + (float) $nextItem['y2']) / 2.0;
        if ($previousCenter <= $nextCenter + max(1.0, $fontSize * 0.15)
            || abs((float) $previousItem['x1'] - (float) $nextItem['x1']) > max(16.0, $fontSize * 2.0)) {
            return false;
        }

        $previousVisualIndex = null;
        $nextVisualIndex = null;
        foreach ($visualEntries as $visualIndex => $entry) {
            if (($entry['sourceIndex'] ?? null) === $previousSourceIndex) {
                $previousVisualIndex = $visualIndex;
            }
            if (($entry['sourceIndex'] ?? null) === $nextSourceIndex) {
                $nextVisualIndex = $visualIndex;
            }
        }

        return $previousVisualIndex !== null
            && $nextVisualIndex === $previousVisualIndex + 1;
    }

    /**
     * A source stream can put a footnote marker before the footnote text,
     * while the positioned layer includes that marker in the footnote line.
     * Never fabricate body geometry for that marker merely because its source
     * neighbors happen to be visually adjacent. Normal numeric body content
     * is still eligible for local interpolation when neither neighbor carries
     * independently verified footnote-prefix provenance.
     *
     * @param array{page: int, stream: int, text: string} $sourceItem
     * @param array<string, mixed> $previousItem
     * @param array<string, mixed> $nextItem
     */
    private function sourcePdfSourceOnlyItemIsAdjacentFootnoteMarker(
        array $sourceItem,
        array $previousItem,
        array $nextItem
    ): bool {
        $marker = trim($sourceItem['text']);
        if (preg_match('/^(?:[0-9]{1,3}|[*†‡])$/u', $marker) !== 1) {
            return false;
        }

        return ($previousItem['sourceFootnotePrefixedGeometry'] ?? false) === true
            || ($nextItem['sourceFootnotePrefixedGeometry'] ?? false) === true;
    }

    /**
     * @param array<string, mixed> $item
     * @return array<string, mixed>
     */
    private function sourcePdfInferredNeighborLayout(array $item, float $direction): array
    {
        $height = max(1.0, (float) $item['y2'] - (float) $item['y1']);
        $step = max($height * 1.05, (float) $item['fontSize'] * 1.10, 1.0) * $direction;
        $item['y1'] += $step;
        $item['y2'] += $step;

        // A neighboring line can lend its box, but never its immutable
        // source occurrence identity. Keeping those fields would make the
        // inferred carrier claim the neighbor's exact bytes and prevent its
        // own stable source ID from receiving a whole-occurrence range later.
        unset(
            $item['id'],
            $item['sourcePdfGlobalSourceIndex'],
            $item['sourcePdfGlobalSourceIndexes'],
            $item['sourcePdfSourceIndex'],
            $item['sourcePdfSourceIndexEnd'],
            $item['sourcePdfSourceIndexes'],
            $item['sourcePdfSourceIds'],
            $item['sourcePdfExactSourceIndex'],
            $item['sourcePdfExactSourceStart'],
            $item['sourcePdfExactSourceEnd'],
            $item['sourcePdfExactSourceRanges'],
            $item['sourcePdfWholeExactOccurrenceProof'],
            $item['sourcePdfStreams'],
            $item['sourceStream'],
            $item['stream'],
            $item['sourceOrderStart'],
            $item['sourceOrderEnd'],
            $item['sourceCompositePositionedFragments'],
            $item['sourceCompositeComplementaryExactRanges'],
            $item['sourcePdfExactRangeFragmentSequence'],
            $item['sourcePdfExactPositionedText'],
            $item['sourcePdfExactGeometryFallback'],
            $item['sourcePdfExactGeometryFallbackLineItem'],
            $item['sourceVerifiedGeometryText'],
            $item['sourceVerifiedPartialInlineGeometry'],
            $item['sourceFootnotePrefixedGeometry']
        );

        return $item;
    }

    /**
     * Matched source lines have clean text and usable visual bounds. A larger
     * than normal baseline step within one text column is a structural
     * paragraph boundary even when the source stream did not encode one.
     *
     * @param list<array<string, mixed>> $items
     * @return list<array<string, mixed>>
     */
    private function markPositionedPdfParagraphBoundaries(array $items): array
    {
        if (count($items) < 3) {
            return $items;
        }

        $baselineSteps = [];
        foreach ($items as $index => $item) {
            if (!isset($items[$index + 1]) || !$this->pdfLayoutHasGeometry($item) || !$this->pdfLayoutHasGeometry($items[$index + 1])) {
                continue;
            }
            $next = $items[$index + 1];
            $fontSize = max((float) $item['fontSize'], (float) $next['fontSize'], 1.0);
            if (abs((float) $item['x1'] - (float) $next['x1']) > max(16.0, $fontSize * 2.0)) {
                continue;
            }
            $step = (float) $item['y1'] - (float) $next['y1'];
            if ($step >= $fontSize * 0.35 && $step <= $fontSize * 2.4) {
                $baselineSteps[] = $step;
            }
        }
        if ($baselineSteps === []) {
            return $items;
        }

        $expectedStep = $this->median($baselineSteps);
        foreach ($items as $index => &$item) {
            if ($index === 0 || !$this->pdfLayoutHasGeometry($item) || !$this->pdfLayoutHasGeometry($items[$index - 1])) {
                continue;
            }
            $previous = $items[$index - 1];
            $fontSize = max((float) $item['fontSize'], (float) $previous['fontSize'], 1.0);
            $step = (float) $previous['y1'] - (float) $item['y1'];
            if ($step > max($expectedStep * 1.20, $fontSize * 1.25)) {
                $item['forceBlockBreakBefore'] = true;
            }
        }
        unset($item);

        // The first visible line of a list item may lose its marker when the
        // marker font has no usable Unicode mapping. A large gap rightly
        // starts that item, but a hanging continuation immediately below it
        // must not become a second forced paragraph boundary.
        for ($index = 1; $index < count($items); $index++) {
            $previous = $items[$index - 1];
            $current = $items[$index];
            if (($previous['forceBlockBreakBefore'] ?? false) !== true
                || ($current['forceBlockBreakBefore'] ?? false) !== true
                || !$this->pdfLayoutHasGeometry($previous)
                || !$this->pdfLayoutHasGeometry($current)
                || ($previous['page'] ?? null) !== ($current['page'] ?? null)
                || ($previous['sourceGeometryColumn'] ?? null) !== ($current['sourceGeometryColumn'] ?? null)
                || isset($previous['sourcePdfTableGroup'], $current['sourcePdfTableGroup'])
                || ($previous['code'] ?? false) === true
                || ($current['code'] ?? false) === true
                || preg_match('/[.!?;:]\s*$/u', rtrim((string) ($previous['text'] ?? ''))) === 1) {
                continue;
            }

            $fontSize = max(1.0, (float) $previous['fontSize'], (float) $current['fontSize']);
            $verticalStep = (float) $previous['y1'] - (float) $current['y1'];
            $hangingOffset = (float) $current['x1'] - (float) $previous['x1'];
            if ($verticalStep < $fontSize * 0.35
                || $verticalStep > $fontSize * 1.80
                || $hangingOffset < $fontSize * 0.45
                || $hangingOffset > $fontSize * 1.75
                || preg_match('/^[^\p{L}\p{N}]*\p{Lu}/u', ltrim((string) ($current['text'] ?? ''))) !== 1) {
                continue;
            }

            unset($items[$index]['forceBlockBreakBefore']);
        }

        return $items;
    }

    /**
     * @param list<array{page: int, stream: int, text: string}> $sourceItems
     * @param array<int, true> $matchedSourceIndexes
     */
    private function sourcePdfLineGeometryMatchIsReliable(array $sourceItems, array $matchedSourceIndexes): bool
    {
        $significantIndexes = [];
        $totalCharacters = 0;
        $matchedCharacters = 0;
        foreach ($sourceItems as $index => $item) {
            $length = $this->length($this->pdfComparableLineText($item['text']));
            if ($length < 8) {
                continue;
            }
            $significantIndexes[] = $index;
            $totalCharacters += $length;
            if (isset($matchedSourceIndexes[$index])) {
                $matchedCharacters += $length;
            }
        }
        if (count($significantIndexes) < 3 || $totalCharacters === 0) {
            return false;
        }

        $matchedLines = count(array_filter(
            $significantIndexes,
            static fn (int $index): bool => isset($matchedSourceIndexes[$index])
        ));

        return $matchedLines / count($significantIndexes) >= 0.75
            && $matchedCharacters / $totalCharacters >= 0.90;
    }

    private function pdfComparableLineText(string $text): string
    {
        $text = $this->normalizePdfTextEncoding($text);
        $text = function_exists('mb_strtolower') ? mb_strtolower($text, 'UTF-8') : strtolower($text);

        return preg_replace('/[^\p{L}\p{N}]+/u', '', $text) ?? '';
    }

    /**
     * @param array{page: int, stream: int, text: string} $sourceItem
     * @param array<string, mixed>|null $positionedItem
     * @return array<string, mixed>
     */
    private function sourcePdfLineItem(
        array $sourceItem,
        ?array $positionedItem = null,
        bool $forceBlockBreakBefore = false,
        bool $usePositionedWhitespace = false
    ): array
    {
        $text = $sourceItem['text'];
        if ($usePositionedWhitespace && $positionedItem !== null) {
            $text = $this->sourcePdfLineTextWithPositionedWhitespace(
                $text,
                (string) ($positionedItem['text'] ?? '')
            );
        }
        $item = [
            'text' => $text,
            'page' => $sourceItem['page'],
            'sourceStream' => $sourceItem['stream'],
        ];
        if (($sourceItem['sourcePdfLayoutLabel'] ?? false) === true) {
            $item['sourcePdfLayoutLabel'] = true;
        }
        if (is_string($sourceItem['id'] ?? null) && $sourceItem['id'] !== '') {
            $item['id'] = $sourceItem['id'];
        }
        // The document-global occurrence index is assigned before source
        // lines are grouped by page.  Keep it on conservative source-order
        // fallbacks so later semantic grouping can prove adjacency without
        // guessing from duplicate text or page-local array positions.
        if (is_int($sourceItem['sourcePdfGlobalSourceIndex'] ?? null)) {
            $item['sourcePdfGlobalSourceIndex'] = $sourceItem['sourcePdfGlobalSourceIndex'];
        }
        // Decorative-brace evidence is an immutable source disposition.  A
        // positioned brace run can be removed before source/geometry matching,
        // so the fallback carrier itself must retain the proof in order for
        // repairProseTextLines() to omit the artifact rather than reintroduce
        // it as punctuation-only prose.
        if (is_array($sourceItem['sourcePdfDecorativeBraceEvidence'] ?? null)) {
            $item['sourcePdfDecorativeBraceEvidence'] = $sourceItem['sourcePdfDecorativeBraceEvidence'];
        }
        if (is_array($sourceItem['sourcePdfDuplicateTerminalPeriodArtifactEvidence'] ?? null)) {
            $item['sourcePdfDuplicateTerminalPeriodArtifactEvidence'] =
                $sourceItem['sourcePdfDuplicateTerminalPeriodArtifactEvidence'];
        }
        if ($this->sourcePdfHasExactInlineStandaloneMarkerEvidence($sourceItem)) {
            $item['sourcePdfInlineStandaloneMarkerEvidence'] = $sourceItem['sourcePdfInlineStandaloneMarkerEvidence'];
        }
        if ($positionedItem !== null) {
            $item['positionedTextCandidate'] = (string) ($positionedItem['text'] ?? '');
            foreach ([
                'x1',
                'y1',
                'x2',
                'y2',
                'fontSize',
                'code',
                'codeText',
                'sourceOrderStart',
                'sourceOrderEnd',
                'sourceCompositePositionedFragments',
                'sourcePdfExactSourceRanges',
                'visualRtlOrder',
                'visualRtlProtectedClusters',
                'logicalRtlTextCandidate',
                'sourcePdfFrontMatter',
                'sourcePdfProtectedSemanticContent',
                'sourcePdfFrontMatterRole',
                'sourcePdfDisplayHeading',
                'sourcePdfLayoutLabel',
                'pdfTextOrientation',
                'pdfTextRotation',
                'pdfPrimaryOrientation',
                'forceBlockBreakBefore',
            ] as $key) {
                if (array_key_exists($key, $positionedItem)) {
                    $item[$key] = $positionedItem[$key];
                }
            }
            if (($item['code'] ?? false) === true && !isset($item['codeText'])) {
                $candidate = (string) ($positionedItem['text'] ?? '');
                $sourceCompact = preg_replace('/\s+/u', '', $this->pdfExactLayoutText($text)) ?? '';
                $candidateCompact = preg_replace('/\s+/u', '', $this->pdfExactLayoutText($candidate)) ?? '';
                if ($sourceCompact !== '' && $sourceCompact === $candidateCompact) {
                    // Code geometry retains indentation and operator spacing
                    // that a PDF's ordinary text layer may omit. Accept it
                    // only after the full non-whitespace character sequence
                    // agrees, so no identifier or punctuation can be lost.
                    $item['codeText'] = $candidate;
                }
            }
        }
        if ($forceBlockBreakBefore) {
            $item['forceBlockBreakBefore'] = true;
        }

        return $item;
    }

    /**
     * Remove only source records that can be reconciled exactly with a
     * geometry-proven perpendicular region. This prevents the ordinary text
     * layer from reintroducing a side label as many tiny, sometimes body-
     * interleaved fragments. Preserved regions are reinserted coherently.
     *
     * @param list<array{page:int,stream:int,text:string}> $sourceItems
     * @param list<array{text:string,key:string,orientation:string,start:int,end:int,fragments:list<string>}> $regions
     * @return list<array{page:int,stream:int,text:string}>
     */
    private function removeSourcePdfOrientationRegionItems(array $sourceItems, array $regions): array
    {
        if ($sourceItems === [] || $regions === []) {
            return $sourceItems;
        }
        $keys = array_map(
            fn (array $item): string => $this->pdfComparableLineText((string) ($item['text'] ?? '')),
            $sourceItems
        );
        $remove = [];
        foreach ($regions as $region) {
            $target = (string) ($region['key'] ?? '');
            if ($target === '') {
                continue;
            }
            $matched = $this->sourcePdfContiguousComparableSequence($keys, $target);
            if ($matched === []) {
                $fragmentKeys = [];
                foreach ($region['fragments'] ?? [] as $fragment) {
                    $key = $this->pdfComparableLineText((string) $fragment);
                    if ($key !== '') {
                        $fragmentKeys[] = $key;
                    }
                }
                if ($fragmentKeys !== []) {
                    $matched = $this->sourcePdfOrientationFragmentSequence($keys, $fragmentKeys);
                }
            }
            foreach ($matched as $index) {
                $remove[$index] = true;
            }
        }
        if ($remove === []) {
            return $sourceItems;
        }

        return array_values(array_filter(
            $sourceItems,
            static fn (array $item, int $index): bool => !isset($remove[$index]),
            ARRAY_FILTER_USE_BOTH
        ));
    }

    /**
     * @param list<string> $sourceKeys
     * @return list<int>
     */
    private function sourcePdfContiguousComparableSequence(array $sourceKeys, string $target): array
    {
        $targetLength = $this->length($target);
        foreach ($sourceKeys as $start => $key) {
            if ($key === '') {
                continue;
            }
            $joined = '';
            $matched = [];
            $endLimit = min(count($sourceKeys), $start + 256);
            for ($index = $start; $index < $endLimit; $index++) {
                $part = $sourceKeys[$index];
                if ($part === '') {
                    continue;
                }
                $joined .= $part;
                $matched[] = $index;
                if ($joined === $target) {
                    return $matched;
                }
                if ($this->length($joined) >= $targetLength || !str_starts_with($target, $joined)) {
                    break;
                }
            }
        }

        return [];
    }

    /**
     * Match every exact painted fragment in order while permitting unrelated
     * source records between them. No partial-word deletion is allowed: one
     * source record must equal one or more complete geometry fragments.
     *
     * @param list<string> $sourceKeys
     * @param list<string> $fragmentKeys
     * @return list<int>
     */
    private function sourcePdfOrientationFragmentSequence(array $sourceKeys, array $fragmentKeys): array
    {
        $sourceCount = count($sourceKeys);
        $fragmentCount = count($fragmentKeys);
        $window = max(64, min(256, $fragmentCount * 8));
        for ($start = 0; $start < $sourceCount; $start++) {
            $fragmentIndex = 0;
            $matched = [];
            $end = min($sourceCount, $start + $window);
            for ($sourceIndex = $start; $sourceIndex < $end && $fragmentIndex < $fragmentCount; $sourceIndex++) {
                $sourceKey = $sourceKeys[$sourceIndex];
                if ($sourceKey === '') {
                    continue;
                }
                $joined = '';
                $consumed = 0;
                for ($candidate = $fragmentIndex; $candidate < $fragmentCount; $candidate++) {
                    $joined .= $fragmentKeys[$candidate];
                    if ($joined === $sourceKey) {
                        $consumed = $candidate - $fragmentIndex + 1;
                        break;
                    }
                    if (!str_starts_with($sourceKey, $joined)) {
                        break;
                    }
                }
                if ($consumed === 0) {
                    continue;
                }
                $matched[] = $sourceIndex;
                $fragmentIndex += $consumed;
            }
            if ($fragmentIndex === $fragmentCount) {
                return $matched;
            }
        }

        return [];
    }

    /**
     * A short, repeated source line can be matched to the wrong visual copy
     * when columns reorder otherwise identical labels. Preserve its source
     * spelling unless neighboring matched records establish the same source
     * ordering. This gates only a local separator override; it does not alter
     * ordinary source/geometry matching or visual order.
     *
     * @param list<array{page: int, stream: int, text: string}> $sourceItems
     * @param array<string, mixed> $positionedItem
     * @param array<int, array<string, mixed>> $matchedItemsBySourceIndex
     */
    private function sourcePdfCanApplyProvenPositionedSeparators(
        array $sourceItems,
        int $sourceIndex,
        array $positionedItem,
        array $matchedItemsBySourceIndex
    ): bool {
        $sourceItem = $sourceItems[$sourceIndex] ?? null;
        if (!is_array($sourceItem)) {
            return false;
        }

        $compact = preg_replace('/\s+/u', '', $this->pdfExactLayoutText((string) $sourceItem['text'])) ?? '';
        if ($compact === '' || $this->length($compact) > 24) {
            return true;
        }

        $duplicateCount = 0;
        foreach ($sourceItems as $candidate) {
            if (($candidate['page'] ?? null) !== $sourceItem['page']
                || ($candidate['stream'] ?? null) !== $sourceItem['stream']) {
                continue;
            }
            $candidateCompact = preg_replace(
                '/\s+/u',
                '',
                $this->pdfExactLayoutText((string) ($candidate['text'] ?? ''))
            ) ?? '';
            if ($candidateCompact === $compact) {
                $duplicateCount++;
                if ($duplicateCount > 1) {
                    break;
                }
            }
        }
        if ($duplicateCount <= 1) {
            return true;
        }

        return $this->sourcePdfDuplicateCompactLineHasMatchedOrderAnchor(
            $sourceItems,
            $sourceIndex,
            $positionedItem,
            $matchedItemsBySourceIndex
        );
    }

    /**
     * @param list<array{page: int, stream: int, text: string}> $sourceItems
     * @param array<string, mixed> $positionedItem
     * @param array<int, array<string, mixed>> $matchedItemsBySourceIndex
     */
    private function sourcePdfDuplicateCompactLineHasMatchedOrderAnchor(
        array $sourceItems,
        int $sourceIndex,
        array $positionedItem,
        array $matchedItemsBySourceIndex
    ): bool {
        if (!isset($positionedItem['sourceOrderStart'], $positionedItem['sourceOrderEnd'])) {
            return false;
        }

        $sourceItem = $sourceItems[$sourceIndex] ?? null;
        if (!is_array($sourceItem)) {
            return false;
        }

        $start = (int) $positionedItem['sourceOrderStart'];
        $end = (int) $positionedItem['sourceOrderEnd'];
        foreach ([$sourceIndex - 1, $sourceIndex + 1] as $neighborIndex) {
            $neighborSource = $sourceItems[$neighborIndex] ?? null;
            $neighborItem = $matchedItemsBySourceIndex[$neighborIndex] ?? null;
            if (!is_array($neighborSource)
                || !is_array($neighborItem)
                || ($neighborSource['page'] ?? null) !== $sourceItem['page']
                || ($neighborSource['stream'] ?? null) !== $sourceItem['stream']
                || !isset($neighborItem['sourceOrderStart'], $neighborItem['sourceOrderEnd'])) {
                continue;
            }

            $neighborStart = (int) $neighborItem['sourceOrderStart'];
            $neighborEnd = (int) $neighborItem['sourceOrderEnd'];
            if (($neighborIndex < $sourceIndex && $neighborEnd < $start)
                || ($neighborIndex > $sourceIndex && $neighborStart > $end)) {
                return true;
            }
        }

        return false;
    }

    private function sourcePdfLineTextWithPositionedWhitespace(string $sourceText, string $positionedText): string
    {
        $sourceCompact = preg_replace('/\s+/u', '', $this->normalizePdfTextEncoding($sourceText)) ?? '';
        $positionedCompact = preg_replace('/\s+/u', '', $this->normalizePdfTextEncoding($positionedText)) ?? '';
        if ($sourceCompact === '' || $sourceCompact !== $positionedCompact) {
            return $sourceText;
        }

        return trim($positionedText);
    }

    /**
     * Restore only separator offsets that a positioned run proved at this
     * exact visual occurrence. The compact strings must agree byte-for-byte
     * after whitespace removal, so this cannot rewrite a similar word on a
     * different source line or replace the line wholesale with geometry text.
     *
     * @param array<int, string> $boundarySeparators Compact-character offset
     *                                                => required separator.
     */
    private function sourcePdfLineTextWithProvenPositionedSeparators(
        string $sourceText,
        string $positionedText,
        array $boundarySeparators
    ): string {
        if ($boundarySeparators === []) {
            return $sourceText;
        }

        $sourceCompact = preg_replace('/\s+/u', '', $this->pdfExactLayoutText($sourceText)) ?? '';
        $positionedCompact = preg_replace('/\s+/u', '', $this->pdfExactLayoutText($positionedText)) ?? '';
        if ($sourceCompact === '' || $sourceCompact !== $positionedCompact) {
            return $sourceText;
        }

        $separators = [];
        foreach ($boundarySeparators as $offset => $separator) {
            if (is_int($offset)
                && $offset > 0
                && $offset < $this->length($sourceCompact)
                && ($separator === '' || $separator === ' ')) {
                $separators[$offset] = $separator;
            }
        }
        if ($separators === []) {
            return $sourceText;
        }

        $characters = preg_split('//u', $sourceText, -1, PREG_SPLIT_NO_EMPTY);
        if (!is_array($characters) || $characters === []) {
            return $sourceText;
        }

        $result = '';
        $pendingWhitespace = '';
        $compactOffset = 0;
        foreach ($characters as $character) {
            if (preg_match('/^\s$/u', $character) === 1) {
                $pendingWhitespace .= $character;
                continue;
            }

            if (array_key_exists($compactOffset, $separators)) {
                if ($separators[$compactOffset] === '') {
                    $pendingWhitespace = '';
                } elseif ($pendingWhitespace === '' && $result !== '') {
                    $result .= ' ';
                }
            }
            $result .= $pendingWhitespace . $character;
            $pendingWhitespace = '';
            $compactOffset++;
        }

        return $result . $pendingWhitespace;
    }

    /**
     * @param list<array{text: string, page?: int, code?: bool}> $items
     * @return list<string>
     */
    private function positionedCodeBlocksFromLineItems(array $items): array
    {
        $blocks = [];
        $lines = [];
        $page = null;
        $flush = static function () use (&$blocks, &$lines, &$page): void {
            $text = rtrim(implode("\n", $lines));
            if ($text !== '') {
                $blocks[] = $text;
            }
            $lines = [];
            $page = null;
        };

        foreach ($items as $item) {
            $itemPage = max(1, (int) ($item['page'] ?? 1));
            if (($item['code'] ?? false) !== true || ($page !== null && $page !== $itemPage)) {
                $flush();
            }
            if (($item['code'] ?? false) !== true) {
                continue;
            }

            $page = $itemPage;
            $lines[] = (string) $item['text'];
        }
        $flush();

        return $blocks;
    }

    /**
     * Geometry can identify a listing even when the ordinary PDF text stream
     * has better prose spacing. Replace only a span whose leading and trailing
     * token sequences match and whose complete token inventory substantially
     * agrees with the geometry-derived listing.
     *
     * @param list<string> $lines
     * @param list<string> $codeBlocks
     * @return list<string>
     */
    private function injectPositionedCodeBlocks(array $lines, array $codeBlocks): array
    {
        if ($lines === [] || $codeBlocks === []) {
            return $lines;
        }

        $document = implode("\n", $lines);
        $replacements = [];
        foreach ($codeBlocks as $index => $codeBlock) {
            $codeProfile = $this->pdfCodeMatchProfile($codeBlock);
            if ($codeProfile['tokenCount'] < 24) {
                continue;
            }

            $match = $this->matchingPdfCodeTokenSpan($document, $codeProfile);
            if ($match === null) {
                continue;
            }

            $placeholder = "\x1EPDF-CODE-ID:" . $index . "\x1F";
            $before = substr($document, 0, $match['start']);
            $after = substr($document, $match['end']);
            if ($before !== '' && !str_ends_with($before, "\n")) {
                $before = rtrim($before) . "\n";
            }
            if ($after !== '' && !str_starts_with($after, "\n")) {
                $after = "\n" . ltrim($after);
            }
            $document = $before . $placeholder . $after;
            $replacements[$placeholder] = self::PDF_CODE_BLOCK_PREFIX . rtrim($codeBlock);
        }

        if ($replacements === []) {
            return $lines;
        }

        $result = [];
        foreach (explode("\n", $document) as $line) {
            if (isset($replacements[$line])) {
                $result[] = $replacements[$line];
                continue;
            }
            $line = trim($line);
            if ($line !== '') {
                $result[] = $line;
            }
        }

        return $result;
    }

    /**
     * Protect a geometry-verified listing before prose cleanup can discard or
     * merge its source lines. This accepts only matches whose token span is
     * line-aligned in the source stream, so nearby prose cannot be replaced
     * by a code block merely because it shares a few identifiers.
     *
     * @param list<string> $lines
     * @param list<array<string, mixed>> $layouts
     * @param list<string> $codeBlocks
     * @return array{lines: list<string>, layouts: list<array<string, mixed>>, remainingCodeBlocks: list<string>}
     */
    private function injectPositionedCodeBlocksIntoRepairSource(
        array $lines,
        array $layouts,
        array $codeBlocks
    ): array {
        $this->injectPositionedCodeBlocksIntoRepairSourceInPlace(
            $lines,
            $layouts,
            $codeBlocks
        );

        return [
            'lines' => $lines,
            'layouts' => $layouts,
            'remainingCodeBlocks' => $codeBlocks,
        ];
    }

    /**
     * @param list<string> $lines
     * @param list<array<string, mixed>> $layouts
     * @param list<string> $codeBlocks
     */
    private function injectPositionedCodeBlocksIntoRepairSourceInPlace(
        array &$lines,
        array &$layouts,
        array &$codeBlocks
    ): void {
        if ($lines === [] || $codeBlocks === []) {
            return;
        }

        if (count($layouts) !== count($lines)) {
            $layouts = array_fill(0, count($lines), []);
        }

        $document = implode("\n", $lines);
        $lineStarts = [];
        $offset = 0;
        foreach ($lines as $line) {
            $lineStarts[] = $offset;
            $offset += strlen($line) + 1;
        }

        $lineIndexAtOffset = static function (int $target) use ($lineStarts): ?int {
            $index = null;
            foreach ($lineStarts as $candidate => $start) {
                if ($start > $target) {
                    break;
                }
                $index = $candidate;
            }

            return $index;
        };

        $replacements = [];
        $remaining = [];
        foreach ($codeBlocks as $codeIndex => $codeBlock) {
            $codeProfile = $this->pdfCodeMatchProfile($codeBlock);
            if ($codeProfile['tokenCount'] < 24) {
                $remaining[] = $codeBlock;
                continue;
            }
            $match = $this->matchingPdfCodeTokenSpan($document, $codeProfile);
            if ($match === null) {
                $remaining[] = $codeBlock;
                continue;
            }

            $startLine = $lineIndexAtOffset($match['start']);
            $endLine = $lineIndexAtOffset(max($match['start'], $match['end'] - 1));
            if ($startLine === null || $endLine === null || $startLine > $endLine) {
                $remaining[] = $codeBlock;
                continue;
            }

            $startColumn = $match['start'] - $lineStarts[$startLine];
            $endColumn = $match['end'] - $lineStarts[$endLine];
            $leading = substr($lines[$startLine], 0, max(0, $startColumn));
            $trailing = substr($lines[$endLine], max(0, $endColumn));
            if (trim($leading) !== '' || trim($trailing) !== '') {
                $remaining[] = $codeBlock;
                continue;
            }

            $overlaps = false;
            foreach ($replacements as $replacement) {
                if ($startLine <= $replacement['endLine'] && $endLine >= $replacement['startLine']) {
                    $overlaps = true;
                    break;
                }
            }
            if ($overlaps) {
                $remaining[] = $codeBlock;
                continue;
            }

            $startLayout = is_array($layouts[$startLine] ?? null) ? $layouts[$startLine] : [];
            $endLayout = is_array($layouts[$endLine] ?? null) ? $layouts[$endLine] : [];
            $startPage = max(1, (int) ($startLayout['page'] ?? 1));
            $endPage = max(1, (int) ($endLayout['page'] ?? $startPage));
            if ($startPage !== $endPage) {
                // Positioned code candidates are page-bounded. A source span
                // crossing pages cannot be the same occurrence.
                $remaining[] = $codeBlock;
                continue;
            }
            $codeLayout = $startLayout;
            $codeLayout['page'] = $startPage;
            $codeLayout['code'] = true;
            $codeLayout['codeText'] = rtrim($codeBlock);
            if (isset($endLayout['sourcePdfSourceIndexEnd'])) {
                $codeLayout['sourcePdfSourceIndexEnd'] = $endLayout['sourcePdfSourceIndexEnd'];
            } elseif (isset($endLayout['sourcePdfSourceIndex'])) {
                $codeLayout['sourcePdfSourceIndexEnd'] = $endLayout['sourcePdfSourceIndex'];
            }

            $replacements[] = [
                'startLine' => $startLine,
                'endLine' => $endLine,
                'text' => self::PDF_CODE_BLOCK_PREFIX . rtrim($codeBlock),
                'layout' => $codeLayout,
            ];
        }

        $codeBlocks = $remaining;
        unset(
            $remaining,
            $document,
            $lineStarts,
            $lineIndexAtOffset,
            $codeProfile,
            $match,
            $startLayout,
            $endLayout,
            $codeLayout,
            $leading,
            $trailing,
            $replacement,
            $codeBlock
        );
        if ($replacements === []) {
            return;
        }

        usort($replacements, static fn (array $left, array $right): int => $right['startLine'] <=> $left['startLine']);
        foreach ($replacements as $replacement) {
            $length = $replacement['endLine'] - $replacement['startLine'] + 1;
            array_splice($lines, $replacement['startLine'], $length, [$replacement['text']]);
            array_splice($layouts, $replacement['startLine'], $length, [$replacement['layout']]);
        }
    }

    /**
     * @return array{
     *   tokenCount:int,
     *   tokenCounts:array<string,int>,
     *   firstAnchor:list<string>,
     *   lastAnchor:list<string>
     * }
     */
    private function pdfCodeMatchProfile(string $text): array
    {
        $tokenCount = 0;
        $tokenCounts = [];
        $firstTokens = [];
        $lastTokens = [];
        foreach ($this->pdfCodeMatchTokenStream($text) as [$token]) {
            $tokenCount++;
            $tokenCounts[$token] = ($tokenCounts[$token] ?? 0) + 1;
            if ($tokenCount <= 10) {
                $firstTokens[] = $token;
            }
            $lastTokens[] = $token;
            if (count($lastTokens) > 10) {
                array_shift($lastTokens);
            }
        }
        $anchorSize = min(10, max(6, (int) floor($tokenCount / 8)));

        return [
            'tokenCount' => $tokenCount,
            'tokenCounts' => $tokenCounts,
            'firstAnchor' => array_slice($firstTokens, 0, $anchorSize),
            'lastAnchor' => array_slice($lastTokens, -$anchorSize),
        ];
    }

    /**
     * @param array{
     *   tokenCount:int,
     *   tokenCounts:array<string,int>,
     *   firstAnchor:list<string>,
     *   lastAnchor:list<string>
     * } $codeProfile
     * @return array{start: int, end: int}|null
     */
    private function matchingPdfCodeTokenSpan(
        string $document,
        array $codeProfile
    ): ?array {
        $codeTokenCount = $codeProfile['tokenCount'];
        if ($codeTokenCount < 24) {
            return null;
        }

        $anchorSize = min(10, max(6, (int) floor($codeTokenCount / 8)));
        $firstAnchor = $codeProfile['firstAnchor'];
        $lastAnchor = $codeProfile['lastAnchor'];
        $firstByteOffsets = [];
        $anchorTokens = [];
        $anchorStarts = [];
        foreach ($this->pdfCodeMatchTokenStream($document) as [$token, $start]) {
            $anchorTokens[] = $token;
            $anchorStarts[] = $start;
            if (count($anchorTokens) > $anchorSize) {
                array_shift($anchorTokens);
                array_shift($anchorStarts);
            }
            if (count($anchorTokens) === $anchorSize && $anchorTokens === $firstAnchor) {
                $firstByteOffsets[] = $anchorStarts[0];
            }
        }
        if ($firstByteOffsets === []) {
            return null;
        }

        $expectedCounts = $codeProfile['tokenCounts'];
        $best = null;
        $bestScore = 0.0;
        foreach ($firstByteOffsets as $firstByteOffset) {
            $segmentCounts = [];
            $segmentTokenCount = 0;
            $overlap = 0;
            $lastWindow = [];
            foreach ($this->pdfCodeMatchTokenStream($document, $firstByteOffset) as [$token, $_start, $end]) {
                $segmentTokenCount++;
                $previousTokenCount = $segmentCounts[$token] ?? 0;
                $segmentCounts[$token] = $previousTokenCount + 1;
                if ($previousTokenCount < ($expectedCounts[$token] ?? 0)) {
                    $overlap++;
                }
                if ($segmentTokenCount > $codeTokenCount * 1.65) {
                    break;
                }

                $lastWindow[] = $token;
                if (count($lastWindow) > $anchorSize) {
                    array_shift($lastWindow);
                }
                $lastAnchorStart = $segmentTokenCount - $anchorSize;
                if ($lastAnchorStart < $anchorSize
                    || count($lastWindow) !== $anchorSize
                    || $lastWindow !== $lastAnchor
                    || $segmentTokenCount < $codeTokenCount * 0.60) {
                    continue;
                }

                $precision = $overlap / $segmentTokenCount;
                $recall = $overlap / $codeTokenCount;
                $score = $overlap === 0
                    ? 0.0
                    : 2.0 * $precision * $recall / ($precision + $recall);
                if ($score < 0.78 || $score <= $bestScore) {
                    continue;
                }
                $bestScore = $score;
                $best = [
                    'start' => $firstByteOffset,
                    'end' => $end,
                ];
            }
        }

        return $best;
    }

    /**
     * @return \Generator<int,array{0:string,1:int,2:int}>
     */
    private function pdfCodeMatchTokenStream(string $text, int $startOffset = 0): \Generator
    {
        $offset = max(0, $startOffset);
        $length = strlen($text);
        while ($offset < $length) {
            $matched = preg_match(
                '/[\p{L}\p{N}_$]+|[^\s\p{L}\p{N}_$]/u',
                $text,
                $match,
                PREG_OFFSET_CAPTURE,
                $offset
            );
            if ($matched !== 1) {
                break;
            }
            $token = (string) ($match[0][0] ?? '');
            $tokenOffset = (int) ($match[0][1] ?? $offset);
            if ($token === '') {
                break;
            }
            $tokenEnd = $tokenOffset + strlen($token);
            $normalized = function_exists('mb_strtolower')
                ? mb_strtolower($token, 'UTF-8')
                : strtolower($token);
            yield [$normalized, $tokenOffset, $tokenEnd];
            $offset = $tokenEnd;
        }
    }

    /**
     * @param list<array<string, mixed>> $runs
     * @return list<array{text: string, page: int, x1: float, y1: float, x2: float, y2: float, fontSize: float}>
     */
    private function positionedProseLineItemsFromTextRuns(array $runs): array
    {
        if ($runs === []) {
            return [];
        }
        if (!$this->positionedTextRunsArePageOrdered($runs)) {
            return $this->positionedProseLineItemsFromRunsByPage(
                $this->positionedRunsByPageFromTextRuns($runs)
            );
        }

        $items = [];
        $pageRuns = [];
        $page = null;
        foreach ($this->positionedRunsWithLiteralWhitespaceProvenance($runs) as $normalized) {
            $runPage = (int) $normalized['page'];
            if ($page !== null && $runPage !== $page) {
                foreach ($this->positionedProseLineItemsForPage($pageRuns) as $item) {
                    $items[] = $item;
                }
                $pageRuns = [];
            }
            $page = $runPage;
            $pageRuns[] = $normalized;
        }
        foreach ($this->positionedProseLineItemsForPage($pageRuns) as $item) {
            $items[] = $item;
        }

        return $this->classifyPositionedPdfOrientationRegions($items);
    }

    /**
     * Reconstruct a dense positioned-text document page by page and retain
     * the compact prose facts in a temporary record stream. Orientation
     * classification uses bounded multi-pass scans of that stream, so a
     * completed page never overlaps the transient row graph for every later
     * page while glyph-level runs are still resident.
     *
     * @param list<array<string, mixed>> $runs
     * @return resource
     */
    private function deferPositionedProseLineItemsFromTextRuns(array &$runs): mixed
    {
        if ($runs === []) {
            return $this->deferPdfRecordArray([], 'positioned prose facts');
        }
        if (!$this->positionedTextRunsArePageOrdered($runs)) {
            return $this->deferPdfRecordArray(
                $this->positionedProseLineItemsFromRunsByPage(
                    $this->positionedRunsByPageFromTextRuns($runs)
                ),
                'positioned prose facts'
            );
        }

        // The caller still needs the original glyph inventory for table
        // inference. Spill it while page prose is reconstructed, then restore
        // it after the transient row graph has been released. Passing by
        // reference ensures the caller does not retain a second owner during
        // that high-water phase.
        $deferredRuns = $this->deferPdfRecordArray(
            $runs,
            'dense positioned text runs'
        );
        $runs = [];
        $this->releaseTransientPdfMemory();
        $unclassified = $this->deferPdfRecordArray([], 'unclassified positioned prose facts');
        try {
            $pageRuns = [];
            $page = null;
            $globalIndex = 0;
            $flushPage = function () use (&$pageRuns, $unclassified): void {
                if ($pageRuns === []) {
                    return;
                }
                $normalizedRuns = [];
                foreach ($this->positionedRunsWithLiteralWhitespaceProvenance($pageRuns) as $normalized) {
                    $normalizedRuns[] = $normalized;
                }
                foreach ($this->positionedProseLineItemsForPage($normalizedRuns) as $item) {
                    $this->writePdfRecordToTempStream(
                        $unclassified,
                        $item,
                        'unclassified positioned prose facts'
                    );
                }
                $pageRuns = [];
            };
            rewind($deferredRuns);
            while (($run = $this->readPdfRecordFromTempStream(
                $deferredRuns,
                'dense positioned text runs'
            )) !== null) {
                $runPage = max(1, (int) ($run['page'] ?? 1));
                if ($page !== null && $runPage !== $page) {
                    $flushPage();
                }
                $page = $runPage;
                $run['_order'] = array_key_exists('_order', $run)
                    ? $run['_order']
                    : $globalIndex;
                $pageRuns[] = $run;
                $globalIndex++;
            }
            $flushPage();
            fflush($unclassified);

            $classified = $this->classifyDeferredPositionedPdfOrientationRegions($unclassified);
            $this->releaseTransientPdfMemory();
            $runs = $this->restoreDeferredPdfRecordArray(
                $deferredRuns,
                'dense positioned text runs'
            );

            return $classified;
        } finally {
            fclose($unclassified);
            fclose($deferredRuns);
        }
    }

    /**
     * Apply the same document-global rotated-furniture decision as the array
     * path using three bounded scans: page bounds, recurring edge candidates,
     * then filtered output and diagnostic descriptors.
     *
     * @param resource $itemsFile
     * @return resource
     */
    private function classifyDeferredPositionedPdfOrientationRegions(mixed $itemsFile): mixed
    {
        $this->rotatedRegionCount = 0;
        $this->rotatedRegionPreservedCount = 0;
        $this->runningFurnitureRegionRemovedCount = 0;
        $this->rotatedTextRegionsByPage = [];
        $this->tableExcludedRotatedTextRegionsByPage = [];

        $boundsByPage = [];
        rewind($itemsFile);
        while (($item = $this->readPdfRecordFromTempStream(
            $itemsFile,
            'unclassified positioned prose facts'
        )) !== null) {
            if (!$this->pdfLayoutHasGeometry($item)) {
                continue;
            }
            $page = max(1, (int) ($item['page'] ?? 1));
            if (!isset($boundsByPage[$page])) {
                $boundsByPage[$page] = [
                    'x1' => (float) $item['x1'],
                    'y1' => (float) $item['y1'],
                    'x2' => (float) $item['x2'],
                    'y2' => (float) $item['y2'],
                ];
                continue;
            }
            $boundsByPage[$page]['x1'] = min($boundsByPage[$page]['x1'], (float) $item['x1']);
            $boundsByPage[$page]['y1'] = min($boundsByPage[$page]['y1'], (float) $item['y1']);
            $boundsByPage[$page]['x2'] = max($boundsByPage[$page]['x2'], (float) $item['x2']);
            $boundsByPage[$page]['y2'] = max($boundsByPage[$page]['y2'], (float) $item['y2']);
        }

        $candidates = [];
        $edgeAligned = [];
        $index = 0;
        rewind($itemsFile);
        while (($item = $this->readPdfRecordFromTempStream(
            $itemsFile,
            'unclassified positioned prose facts'
        )) !== null) {
            if (($item['pdfPrimaryOrientation'] ?? true) !== true) {
                $this->rotatedRegionCount++;
                $page = max(1, (int) ($item['page'] ?? 1));
                $side = isset($boundsByPage[$page])
                    ? $this->positionedPdfOrientationEdgeSide($item, $boundsByPage[$page])
                    : null;
                if ($side !== null) {
                    $edgeAligned[$index] = true;
                }
                $fingerprint = $this->positionedPdfRunningFurnitureFingerprint($item);
                if ($side !== null && $this->length($fingerprint) >= 4) {
                    $key = (string) ($item['pdfTextOrientation'] ?? '') . "\0" . $side . "\0" . $fingerprint;
                    $candidates[$key][$page][] = $index;
                }
            }
            $index++;
        }

        $remove = [];
        foreach ($candidates as $pages) {
            if (count($pages) < 2) {
                continue;
            }
            foreach ($pages as $indexes) {
                foreach ($indexes as $candidateIndex) {
                    $remove[$candidateIndex] = true;
                }
            }
        }

        $keptFile = $this->deferPdfRecordArray([], 'positioned prose facts');
        try {
            $index = 0;
            rewind($itemsFile);
            while (($item = $this->readPdfRecordFromTempStream(
                $itemsFile,
                'unclassified positioned prose facts'
            )) !== null) {
                $page = max(1, (int) ($item['page'] ?? 1));
                $sourceOrderStart = max(0, (int) ($item['sourceOrderStart'] ?? 0));
                $fragments = is_array($item['pdfOrientationSourceFragments'] ?? null)
                    ? array_values(array_filter(
                        $item['pdfOrientationSourceFragments'],
                        static fn (mixed $fragment): bool => is_string($fragment) && $fragment !== ''
                    ))
                    : [];
                $descriptor = [
                    'text' => (string) ($item['text'] ?? ''),
                    'key' => $this->pdfComparableLineText((string) ($item['text'] ?? '')),
                    'orientation' => (string) ($item['pdfTextOrientation'] ?? ''),
                    'start' => $sourceOrderStart,
                    'end' => max($sourceOrderStart, (int) ($item['sourceOrderEnd'] ?? $sourceOrderStart)),
                    'fragments' => $fragments,
                ];
                if (($item['pdfPrimaryOrientation'] ?? true) !== true) {
                    if (isset($remove[$index]) || count($fragments) > 1) {
                        $this->rotatedTextRegionsByPage[$page][] = $descriptor;
                    }
                    if (isset($edgeAligned[$index])) {
                        $this->tableExcludedRotatedTextRegionsByPage[$page][] = $descriptor;
                    }
                }
                if (isset($remove[$index])) {
                    $this->runningFurnitureRegionRemovedCount++;
                    $index++;
                    continue;
                }
                if (($item['pdfPrimaryOrientation'] ?? true) !== true) {
                    $this->rotatedRegionPreservedCount++;
                }
                unset($item['pdfOrientationSourceFragments']);
                $this->writePdfRecordToTempStream($keptFile, $item, 'positioned prose facts');
                $index++;
            }
            fflush($keptFile);
            rewind($keptFile);

            return $keptFile;
        } catch (\Throwable $error) {
            fclose($keptFile);
            throw $error;
        }
    }

    /**
     * PDF page content contexts are emitted in page order. Keep an explicit
     * fallback for callers that provide synthetic or otherwise unordered
     * runs, where a page map is still needed to preserve the prior behavior.
     *
     * @param list<array<string, mixed>> $runs
     */
    private function positionedTextRunsArePageOrdered(array $runs): bool
    {
        $previousPage = 0;
        foreach ($runs as $run) {
            $page = max(1, (int) ($run['page'] ?? 1));
            if ($page < $previousPage) {
                return false;
            }
            $previousPage = $page;
        }

        return true;
    }

    /**
     * Normalize text-showing runs once before consumers derive prose lines,
     * spacing candidates, or table rows from their geometry.
     *
     * @param list<array<string, mixed>> $runs
     * @return array<int, list<array<string, mixed>>>
     */
    private function positionedRunsByPageFromTextRuns(array $runs): array
    {
        $runsByPage = [];
        foreach ($this->positionedRunsWithLiteralWhitespaceProvenance($runs) as $normalized) {
            $runsByPage[$normalized['page']][] = $normalized;
        }

        ksort($runsByPage);

        return $runsByPage;
    }

    /**
     * @param array<int, list<array<string, mixed>>> $runsByPage
     * @return list<array{text: string, page: int, x1: float, y1: float, x2: float, y2: float, fontSize: float}>
     */
    private function positionedProseLineItemsFromRunsByPage(array $runsByPage): array
    {
        if ($runsByPage === []) {
            return [];
        }

        $items = [];
        foreach ($runsByPage as $pageRuns) {
            foreach ($this->positionedProseLineItemsForPage($pageRuns) as $item) {
                $items[] = $item;
            }
        }

        return $this->classifyPositionedPdfOrientationRegions($items);
    }

    /**
     * @param list<array{page: int, text: string, x1: float, y1: float, x2: float, y2: float, textX1: float, textY1: float, textX2: float, textY2: float, fontSize: float}> $runs
     * @return list<string>
     */
    private function positionedProseLinesForPage(array $runs): array
    {
        return $this->positionedLineItemTexts($this->positionedProseLineItemsForPage($runs));
    }

    /**
     * @param list<array{page: int, text: string, x1: float, y1: float, x2: float, y2: float, textX1: float, textY1: float, textX2: float, textY2: float, fontSize: float}> $runs
     * @return list<array{text: string, page: int, x1: float, y1: float, x2: float, y2: float, fontSize: float}>
     */
    private function positionedProseLineItemsForPage(array $runs): array
    {
        if ($runs === []) {
            return [];
        }

        $groups = [];
        foreach ($runs as $run) {
            $groups[$this->positionedPdfOrientationBucket($run)][] = $run;
        }
        if ($groups === []) {
            return [];
        }

        $scores = [];
        foreach ($groups as $key => $groupRuns) {
            $scores[$key] = $this->positionedPdfOrientationGroupScore($groupRuns);
        }
        uksort($groups, static function (string $left, string $right) use ($scores): int {
            return ($scores[$right] <=> $scores[$left]) ?: strcmp($left, $right);
        });
        $primaryKey = (string) array_key_first($groups);
        $primaryRotation = $this->positionedPdfOrientationBucketRotation($primaryKey);
        $partitionedGroups = [$primaryKey => $groups[$primaryKey]];
        foreach ($groups as $key => $groupRuns) {
            if ($key === $primaryKey) {
                continue;
            }
            $rotation = $this->positionedPdfOrientationBucketRotation((string) $key);
            $difference = abs($rotation - $primaryRotation);
            $difference = min($difference, 360.0 - $difference);
            if (abs($difference - 90.0) <= 12.0
                && count($groupRuns) >= 2
                && $this->positionedPdfOrientationGroupScore($groupRuns) >= 4) {
                $partitionedGroups[$key] = $groupRuns;
                continue;
            }
            // Preserve the established reconstruction path for tiny
            // perpendicular marks (notably superscript reference markers)
            // and ordinary skew. They do not constitute a separate region.
            array_push($partitionedGroups[$primaryKey], ...$groupRuns);
        }

        // A page with many unrelated angles is typically a map or diagram.
        // Its existing low-coherence region classifier needs the complete
        // page geometry; turning each angle into an isolated prose flow would
        // instead promote the very labels it is designed to suppress.
        if (count($groups) > 8 || count($partitionedGroups) === 1) {
            $items = $this->positionedProseLineItemsForOrientation($runs);
            foreach ($items as &$item) {
                $item['pdfTextOrientation'] = $primaryKey;
                $item['pdfTextRotation'] = $primaryRotation;
                $item['pdfPrimaryOrientation'] = true;
            }
            unset($item);

            return $items;
        }
        $groups = $partitionedGroups;

        $items = [];
        foreach ($groups as $key => $groupRuns) {
            $basis = $this->positionedPdfOrientationBasis($groupRuns, $key !== $primaryKey);
            $orientedRuns = array_map(
                fn (array $run): array => $this->positionedPdfRunInOrientationSpace($run, $basis),
                $groupRuns
            );
            foreach ($this->positionedProseLineItemsForOrientation($orientedRuns) as $item) {
                $item = $this->positionedPdfItemFromOrientationSpace($item, $basis);
                $item['pdfTextOrientation'] = $key;
                $item['pdfTextRotation'] = $this->positionedPdfOrientationBucketRotation($key);
                $item['pdfPrimaryOrientation'] = $key === $primaryKey;
                if ($key !== $primaryKey) {
                    $item['pdfOrientationSourceFragments'] = $this->positionedPdfOrientationItemFragments(
                        $item,
                        $groupRuns
                    );
                }
                $items[] = $item;
            }
        }

        return $items;
    }

    /**
     * Use a stable angular bucket rather than requiring perfectly orthogonal
     * matrices. Scans and authoring tools commonly leave a small skew in the
     * text matrix even when the intended flow is horizontal or vertical.
     *
     * @param array<string, mixed> $run
     */
    private function positionedPdfOrientationBucket(array $run): string
    {
        $rotation = $this->numericValue($run['rotation'] ?? null);
        if ($rotation === null) {
            $axisX = $this->numericValue($run['axisX'] ?? null) ?? 1.0;
            $axisY = $this->numericValue($run['axisY'] ?? null) ?? 0.0;
            $rotation = rad2deg(atan2($axisY, $axisX));
        }
        $rotation = $this->normalizedPdfTextRotation($rotation);
        $nearest = 0.0;
        $nearestDistance = 360.0;
        foreach ([0.0, 90.0, 180.0, 270.0] as $orthogonal) {
            $distance = abs($rotation - $orthogonal);
            $distance = min($distance, 360.0 - $distance);
            if ($distance < $nearestDistance) {
                $nearest = $orthogonal;
                $nearestDistance = $distance;
            }
        }
        if ($nearestDistance <= 12.0) {
            return 'r' . (string) (int) $nearest;
        }

        $skewBucket = $this->normalizedPdfTextRotation(round($rotation / 12.0) * 12.0);

        return 'r' . rtrim(rtrim(number_format($skewBucket, 3, '.', ''), '0'), '.');
    }

    private function positionedPdfOrientationBucketRotation(string $bucket): float
    {
        if (preg_match('/^r(-?\d+(?:\.\d+)?)$/', $bucket, $matches) !== 1) {
            return 0.0;
        }

        return $this->normalizedPdfTextRotation((float) $matches[1]);
    }

    /**
     * @param list<array<string, mixed>> $runs
     */
    private function positionedPdfOrientationGroupScore(array $runs): int
    {
        $characters = 0;
        foreach ($runs as $run) {
            $characters += $this->positionedCompactTextLength((string) ($run['text'] ?? ''));
        }

        return $characters;
    }

    /**
     * @param list<array<string, mixed>> $runs
     * @return array{uX:float,uY:float,nX:float,nY:float}
     */
    private function positionedPdfOrientationBasis(array $runs, bool $orientFromSourceOrder): array
    {
        $uX = 0.0;
        $uY = 0.0;
        foreach ($runs as $run) {
            $weight = max(1, $this->positionedCompactTextLength((string) ($run['text'] ?? '')));
            $axisX = $this->numericValue($run['axisX'] ?? null) ?? 1.0;
            $axisY = $this->numericValue($run['axisY'] ?? null) ?? 0.0;
            $length = hypot($axisX, $axisY);
            if ($length <= 0.000001) {
                continue;
            }
            $uX += ($axisX / $length) * $weight;
            $uY += ($axisY / $length) * $weight;
        }
        $length = hypot($uX, $uY);
        if ($length <= 0.000001) {
            $uX = 1.0;
            $uY = 0.0;
        } else {
            $uX /= $length;
            $uY /= $length;
        }

        $nX = -$uY;
        $nY = $uX;
        // PDF page coordinates put ordinary top-to-bottom rows at decreasing
        // Y values. For a rotated flow the equivalent direction may use the
        // opposite perpendicular. Pick that sign from the first two distinct
        // source-order baselines, without changing any text or vocabulary.
        if ($orientFromSourceOrder) {
            $ordered = $runs;
            usort($ordered, static fn (array $left, array $right): int =>
                ((int) ($left['order'] ?? 0)) <=> ((int) ($right['order'] ?? 0))
            );
            $previousCross = null;
            $previousTolerance = 0.0;
            foreach ($ordered as $run) {
                $centerX = ((float) ($run['x1'] ?? 0.0) + (float) ($run['x2'] ?? 0.0)) / 2.0;
                $centerY = ((float) ($run['y1'] ?? 0.0) + (float) ($run['y2'] ?? 0.0)) / 2.0;
                $cross = $centerX * $nX + $centerY * $nY;
                $tolerance = max(1.5, (float) ($run['fontSize'] ?? 1.0) * 0.35, $previousTolerance);
                if ($previousCross !== null && abs($cross - $previousCross) > $tolerance) {
                    if ($cross > $previousCross) {
                        $nX *= -1.0;
                        $nY *= -1.0;
                    }
                    break;
                }
                $previousCross = $cross;
                $previousTolerance = $tolerance;
            }
        }

        return [
            'uX' => $uX,
            'uY' => $uY,
            'nX' => $nX,
            'nY' => $nY,
        ];
    }

    /**
     * @param array<string, mixed> $run
     * @param array{uX:float,uY:float,nX:float,nY:float} $basis
     * @return array<string, mixed>
     */
    private function positionedPdfRunInOrientationSpace(array $run, array $basis): array
    {
        $bounds = $this->positionedPdfProjectedBounds(
            (float) $run['x1'],
            (float) $run['y1'],
            (float) $run['x2'],
            (float) $run['y2'],
            $basis
        );
        $textBounds = $this->positionedPdfProjectedBounds(
            (float) ($run['textX1'] ?? $run['x1']),
            (float) ($run['textY1'] ?? $run['y1']),
            (float) ($run['textX2'] ?? $run['x2']),
            (float) ($run['textY2'] ?? $run['y2']),
            $basis
        );
        $run['x1'] = $bounds['x1'];
        $run['y1'] = $bounds['y1'];
        $run['x2'] = $bounds['x2'];
        $run['y2'] = $bounds['y2'];
        $run['textX1'] = $textBounds['x1'];
        $run['textY1'] = $textBounds['y1'];
        $run['textX2'] = $textBounds['x2'];
        $run['textY2'] = $textBounds['y2'];
        $run['axisX'] = 1.0;
        $run['axisY'] = 0.0;
        $run['rotation'] = 0.0;

        return $run;
    }

    /**
     * @param array{uX:float,uY:float,nX:float,nY:float} $basis
     * @return array{x1:float,y1:float,x2:float,y2:float}
     */
    private function positionedPdfProjectedBounds(
        float $x1,
        float $y1,
        float $x2,
        float $y2,
        array $basis
    ): array {
        $along = [];
        $cross = [];
        foreach ([[$x1, $y1], [$x1, $y2], [$x2, $y1], [$x2, $y2]] as [$x, $y]) {
            $along[] = $x * $basis['uX'] + $y * $basis['uY'];
            $cross[] = $x * $basis['nX'] + $y * $basis['nY'];
        }

        return [
            'x1' => min($along),
            'y1' => min($cross),
            'x2' => max($along),
            'y2' => max($cross),
        ];
    }

    /**
     * @param array<string, mixed> $item
     * @param array{uX:float,uY:float,nX:float,nY:float} $basis
     * @return array<string, mixed>
     */
    private function positionedPdfItemFromOrientationSpace(array $item, array $basis): array
    {
        $xValues = [];
        $yValues = [];
        foreach ([
            [(float) $item['x1'], (float) $item['y1']],
            [(float) $item['x1'], (float) $item['y2']],
            [(float) $item['x2'], (float) $item['y1']],
            [(float) $item['x2'], (float) $item['y2']],
        ] as [$along, $cross]) {
            $xValues[] = $along * $basis['uX'] + $cross * $basis['nX'];
            $yValues[] = $along * $basis['uY'] + $cross * $basis['nY'];
        }
        $item['x1'] = min($xValues);
        $item['y1'] = min($yValues);
        $item['x2'] = max($xValues);
        $item['y2'] = max($yValues);

        return $item;
    }

    /**
     * Retain exact rotated run fragments only as reconciliation evidence. The
     * source text layer may expose a side label as dozens of records even
     * though orientation-space reconstruction correctly produces one line.
     *
     * @param array<string, mixed> $item
     * @param list<array<string, mixed>> $runs
     * @return list<string>
     */
    private function positionedPdfOrientationItemFragments(array $item, array $runs): array
    {
        $start = max(0, (int) ($item['sourceOrderStart'] ?? 0));
        $end = max($start, (int) ($item['sourceOrderEnd'] ?? $start));
        $fragments = [];
        foreach ($runs as $run) {
            $runStart = max(0, (int) ($run['order'] ?? 0));
            $runEnd = max($runStart, (int) ($run['lastOrder'] ?? $runStart));
            if ($runEnd < $start || $runStart > $end) {
                continue;
            }
            $text = (string) ($run['text'] ?? '');
            if ($this->pdfComparableLineText($text) !== '') {
                $fragments[] = $text;
            }
        }

        return $fragments;
    }

    /**
     * Repeated perpendicular text at a physical page edge is running
     * furniture. A one-off note, a central watermark, and a wholly rotated
     * document are retained: repetition, edge geometry, and a non-primary
     * orientation are all required before anything is removed.
     *
     * @param list<array<string, mixed>> $items
     * @return list<array<string, mixed>>
     */
    private function classifyPositionedPdfOrientationRegions(array $items): array
    {
        $this->rotatedRegionCount = 0;
        $this->rotatedRegionPreservedCount = 0;
        $this->runningFurnitureRegionRemovedCount = 0;
        $this->rotatedTextRegionsByPage = [];
        $this->tableExcludedRotatedTextRegionsByPage = [];
        if ($items === []) {
            return [];
        }

        $boundsByPage = [];
        foreach ($items as $item) {
            if (!$this->pdfLayoutHasGeometry($item)) {
                continue;
            }
            $page = max(1, (int) ($item['page'] ?? 1));
            if (!isset($boundsByPage[$page])) {
                $boundsByPage[$page] = [
                    'x1' => (float) $item['x1'],
                    'y1' => (float) $item['y1'],
                    'x2' => (float) $item['x2'],
                    'y2' => (float) $item['y2'],
                ];
                continue;
            }
            $boundsByPage[$page]['x1'] = min($boundsByPage[$page]['x1'], (float) $item['x1']);
            $boundsByPage[$page]['y1'] = min($boundsByPage[$page]['y1'], (float) $item['y1']);
            $boundsByPage[$page]['x2'] = max($boundsByPage[$page]['x2'], (float) $item['x2']);
            $boundsByPage[$page]['y2'] = max($boundsByPage[$page]['y2'], (float) $item['y2']);
        }

        $candidates = [];
        $edgeAligned = [];
        foreach ($items as $index => $item) {
            if (($item['pdfPrimaryOrientation'] ?? true) === true) {
                continue;
            }
            $this->rotatedRegionCount++;
            $page = max(1, (int) ($item['page'] ?? 1));
            $side = isset($boundsByPage[$page])
                ? $this->positionedPdfOrientationEdgeSide($item, $boundsByPage[$page])
                : null;
            if ($side !== null) {
                $edgeAligned[$index] = true;
            }
            $fingerprint = $this->positionedPdfRunningFurnitureFingerprint($item);
            if ($side === null || $this->length($fingerprint) < 4) {
                continue;
            }
            $key = (string) ($item['pdfTextOrientation'] ?? '') . "\0" . $side . "\0" . $fingerprint;
            $candidates[$key][$page][] = $index;
        }

        $remove = [];
        foreach ($candidates as $pages) {
            if (count($pages) < 2) {
                continue;
            }
            foreach ($pages as $indexes) {
                foreach ($indexes as $index) {
                    $remove[$index] = true;
                }
            }
        }

        $kept = [];
        foreach ($items as $index => $item) {
            $page = max(1, (int) ($item['page'] ?? 1));
            $sourceOrderStart = max(0, (int) ($item['sourceOrderStart'] ?? 0));
            $fragments = is_array($item['pdfOrientationSourceFragments'] ?? null)
                ? array_values(array_filter(
                    $item['pdfOrientationSourceFragments'],
                    static fn (mixed $fragment): bool => is_string($fragment) && $fragment !== ''
                ))
                : [];
            $descriptor = [
                'text' => (string) ($item['text'] ?? ''),
                'key' => $this->pdfComparableLineText((string) ($item['text'] ?? '')),
                'orientation' => (string) ($item['pdfTextOrientation'] ?? ''),
                'start' => $sourceOrderStart,
                'end' => max($sourceOrderStart, (int) ($item['sourceOrderEnd'] ?? $sourceOrderStart)),
                'fragments' => $fragments,
            ];
            if (($item['pdfPrimaryOrientation'] ?? true) !== true) {
                // A single-run region can still be matched atomically by the
                // established source/geometry reconciler. Pre-removing it
                // would shift source occurrence indexes used by inline
                // markers and footnotes. Multi-fragment regions need explicit
                // reconciliation so their glyphs cannot leak into body text;
                // removed furniture always needs it as well.
                if (isset($remove[$index]) || count($fragments) > 1) {
                    $this->rotatedTextRegionsByPage[$page][] = $descriptor;
                }
                if (isset($edgeAligned[$index])) {
                    $this->tableExcludedRotatedTextRegionsByPage[$page][] = $descriptor;
                }
            }
            if (isset($remove[$index])) {
                $this->runningFurnitureRegionRemovedCount++;
                continue;
            }
            if (($item['pdfPrimaryOrientation'] ?? true) !== true) {
                $this->rotatedRegionPreservedCount++;
            }
            unset($item['pdfOrientationSourceFragments']);
            $kept[] = $item;
        }

        return $kept;
    }

    /**
     * @param array<string, mixed> $item
     * @param array{x1:float,y1:float,x2:float,y2:float} $bounds
     */
    private function positionedPdfOrientationEdgeSide(array $item, array $bounds): ?string
    {
        if (!$this->pdfLayoutHasGeometry($item)) {
            return null;
        }
        $width = max(1.0, $bounds['x2'] - $bounds['x1']);
        $height = max(1.0, $bounds['y2'] - $bounds['y1']);
        $centerX = ((float) $item['x1'] + (float) $item['x2']) / 2.0;
        $centerY = ((float) $item['y1'] + (float) $item['y2']) / 2.0;
        $distances = [
            'left' => ($centerX - $bounds['x1']) / $width,
            'right' => ($bounds['x2'] - $centerX) / $width,
            'bottom' => ($centerY - $bounds['y1']) / $height,
            'top' => ($bounds['y2'] - $centerY) / $height,
        ];
        asort($distances, SORT_NUMERIC);
        $side = (string) array_key_first($distances);

        return ($distances[$side] ?? 1.0) <= 0.15 ? $side : null;
    }

    /** @param array<string, mixed> $item */
    private function positionedPdfRunningFurnitureFingerprint(array $item): string
    {
        $candidates = [$this->pdfComparableLineText((string) ($item['text'] ?? ''))];
        $fragments = [];
        foreach ($item['pdfOrientationSourceFragments'] ?? [] as $fragment) {
            $fragment = $this->pdfComparableLineText((string) $fragment);
            if ($fragment !== '') {
                $fragments[] = $fragment;
            }
        }
        if (count($fragments) > 1) {
            $candidates[] = implode('', $fragments);
            $candidates[] = implode('', array_reverse($fragments));
        }
        foreach ($candidates as &$candidate) {
            // Page numbers commonly trail or lead an otherwise stable running
            // label. Strip only a short boundary number; interior digits
            // remain part of the identity and no language-specific words are
            // involved.
            $candidate = preg_replace('/^\p{N}{1,4}|\p{N}{1,4}$/u', '', $candidate) ?? $candidate;
        }
        unset($candidate);
        $candidates = array_values(array_unique(array_filter(
            $candidates,
            static fn (string $candidate): bool => $candidate !== ''
        )));
        sort($candidates, SORT_STRING);

        return $candidates[0] ?? '';
    }

    /**
     * @param list<array<string, mixed>> $runs
     * @return list<array<string, mixed>>
     */
    private function positionedTextRunsWithoutEdgeOrientationRegions(array $runs): array
    {
        if ($runs === [] || $this->tableExcludedRotatedTextRegionsByPage === []) {
            return $runs;
        }
        $regionsByPage = [];
        foreach ($this->tableExcludedRotatedTextRegionsByPage as $page => $regions) {
            foreach ($regions as $region) {
                $regionsByPage[$page][] = $region;
            }
        }

        $kept = [];
        foreach ($runs as $index => $run) {
            $page = max(1, (int) ($run['page'] ?? 1));
            $removed = false;
            foreach ($regionsByPage[$page] ?? [] as $region) {
                if ($index < $region['start'] || $index > $region['end']
                    || $this->positionedPdfOrientationBucket($run) !== $region['orientation']) {
                    continue;
                }
                $removed = true;
                break;
            }
            if (!$removed) {
                $kept[] = $run;
            }
        }

        return $kept;
    }

    /**
     * Reconstruct one orientation in a local coordinate system where its
     * progression axis is horizontal. The established prose, spacing, code,
     * and column logic can then operate without mixing perpendicular text.
     *
     * @param list<array<string, mixed>> $runs
     * @return list<array<string, mixed>>
     */
    private function positionedProseLineItemsForOrientation(array $runs): array
    {
        if ($runs === []) {
            return [];
        }

        foreach ($runs as &$run) {
            $run['fontSize'] = max(
                1.0,
                (float) ($run['fontSize'] ?? 0.0),
                abs((float) ($run['y2'] ?? 0.0) - (float) ($run['y1'] ?? 0.0)) * 0.8
            );
        }
        unset($run);

        $medianFontSize = max(1.0, $this->positionedRunsMedianFontSize($runs));
        $rowTolerance = max(3.0, $medianFontSize * 0.55);
        $rows = $this->clusterPositionedRows($runs, $rowTolerance);
        $rows = $this->mergePositionedProseRowFragments($rows, $this->positionedRowsBounds($rows));
        $rows = $this->markPositionedCodeListingRows($rows);
        $sustainedVisualRtlLineFlow = $this->positionedRowsHaveSustainedVisualRtlLineFlow($rows);
        $rows = $this->splitPositionedRowsIntoProseFragments($rows);
        $rows = $this->attachWeakSameBaselineFragmentsToPersistentProseLanes($rows, $medianFontSize);
        $rows = $this->orderPositionedProseRows($rows, $medianFontSize);
        $rows = $this->mergeAdjacentPositionedProseRowsOnSameBaseline($rows);
        $rows = $this->markPositionedCodeListingRows($rows);

        $items = [];
        foreach ($rows as $row) {
            $line = $this->positionedRowText($row);
            $keepCodeDelimiter = ($row['code'] ?? false) === true
                && preg_match('/^\s*[}\])]+[;,]?\s*$/u', $line) === 1;
            $exactSourceRanges = $this->pdfPositionedExactSourceRangesForItems($row['runs']);
            $onlyNoise = $this->lineIsOnlyPdfNoise($line);
            $keepExactSourcePunctuation = $onlyNoise
                && $this->positionedPdfNoiseRowHasExactPaintedByteRanges($line, $exactSourceRanges);
            if ($line !== '' && ($keepCodeDelimiter || !$onlyNoise || $keepExactSourcePunctuation)) {
                $bounds = $this->positionedProseRowBounds($row);
                $firstRun = $row['runs'][0];
                $lastRun = $row['runs'][array_key_last($row['runs'])];
                $item = [
                    'text' => (string) ($row['codeText'] ?? $line),
                    'page' => (int) $row['runs'][0]['page'],
                    'x1' => $bounds['x1'],
                    'y1' => $bounds['y1'],
                    'x2' => $bounds['x2'],
                    'y2' => $bounds['y2'],
                    'fontSize' => $this->positionedRowMaxFontSize($row),
                    'code' => (bool) ($row['code'] ?? false),
                    'startsWithWhitespace' => (bool) ($firstRun['startsWithWhitespace'] ?? false),
                    'endsWithWhitespace' => (bool) ($lastRun['endsWithWhitespace'] ?? false),
                    'hasWordBoundaryBefore' => (bool) ($firstRun['hasWordBoundaryBefore'] ?? false),
                    'wordBoundaryBefore' => (bool) ($firstRun['wordBoundaryBefore'] ?? false),
                ];
                if (($row['code'] ?? false) !== true && $item['text'] === $line) {
                    $inlineFontStyleProof = $this->positionedProseRowInlineFontStyleProof(
                        $row,
                        $line,
                        $exactSourceRanges
                    );
                    if ($inlineFontStyleProof !== null) {
                        $item['sourcePdfInlineFontStyleProof'] = $inlineFontStyleProof;
                    }
                }
                if (($row['visualRtlOrder'] ?? false) === true) {
                    $item['visualRtlOrder'] = true;
                    $markedVisualText = '';
                    foreach ($row['runs'] as $run) {
                        $markedVisualText = $this->appendCellText(
                            $markedVisualText,
                            (string) ($run['rtlVisualUnitText'] ?? $run['text'] ?? '')
                        );
                    }
                    $item['logicalRtlTextCandidate'] = $this->logicalTextFromVisualRtlLine($markedVisualText);
                }
                if (is_array($row['visualRtlProtectedClusters'] ?? null)
                    && $row['visualRtlProtectedClusters'] !== []) {
                    $item['visualRtlProtectedClusters'] = $row['visualRtlProtectedClusters'];
                }
                if (is_string($firstRun['wordBoundarySource'] ?? null)) {
                    $item['wordBoundarySource'] = $firstRun['wordBoundarySource'];
                }
                $sourceVerifiedBoundarySeparators = $this->positionedProseRowSourceVerifiedBoundarySeparators($row);
                if ($sourceVerifiedBoundarySeparators !== []) {
                    $item['sourceVerifiedBoundarySeparators'] = $sourceVerifiedBoundarySeparators;
                }
                $sourceCompactBoundaryOffsets = $this->positionedProseRowSourceCompactBoundaryOffsets($row);
                if ($sourceCompactBoundaryOffsets !== []) {
                    $item['sourceCompactBoundaryOffsets'] = $sourceCompactBoundaryOffsets;
                }
                $sourceOrder = $this->positionedProseRowSourceOrderBounds($row);
                if ($sourceOrder !== null) {
                    $item['sourceOrderStart'] = $sourceOrder['start'];
                    $item['sourceOrderEnd'] = $sourceOrder['end'];
                }
                if ($exactSourceRanges !== []) {
                    $item['sourcePdfExactSourceRanges'] = $exactSourceRanges;
                    if ($this->pdfExactSourceRangesAreLayoutLabel($exactSourceRanges)) {
                        $item['sourcePdfLayoutLabel'] = true;
                    }
                }
                $items[] = $item;
            }
        }

        if ($sustainedVisualRtlLineFlow) {
            $items = $this->positionedItemsInProvenVisualRtlRowOrder($items);
            $items = $this->joinPositionedVisualRtlWordShards($items);
        }

        $items = $this->filterPositionedPdfDecorativeItems($items, $medianFontSize);

        foreach ($items as $item) {
            $proof = $item['sourcePdfInlineFontStyleProof'] ?? null;
            if (is_array($proof)) {
                $this->pdfInlineFontStyleProofCandidates[] = $proof;
            }
        }

        return $this->markIsolatedCenteredPdfNumberBoundaries($items, $medianFontSize);
    }

    /**
     * A punctuation-only visual row is not generally safe prose. Preserve it
     * only when the exact page/stream alignment accounts for every painted
     * significant byte; later occurrence matching and the final source binder
     * still decide whether those bytes remain literal or gain local structure.
     *
     * @param list<array{sourceIndex:int,sourceStart:int,sourceEnd:int}> $ranges
     */
    private function positionedPdfNoiseRowHasExactPaintedByteRanges(string $line, array $ranges): bool
    {
        $projection = $this->pdfSourceOccurrenceComparableText($line);
        if ($projection === '' || $ranges === []) {
            return false;
        }

        $coveredBytes = 0;
        foreach ($ranges as $range) {
            $coveredBytes += $range['sourceEnd'] - $range['sourceStart'];
        }

        return $coveredBytes === strlen($projection);
    }

    /**
     * @param list<array{sourceIndex:int,sourceStart:int,sourceEnd:int}> $ranges
     */
    private function pdfExactSourceRangesAreLayoutLabel(array $ranges): bool
    {
        if ($ranges === [] || $this->layoutLabelSourceIndexes === []) {
            return false;
        }
        foreach ($ranges as $range) {
            if (!isset($this->layoutLabelSourceIndexes[(int) ($range['sourceIndex'] ?? -1)])) {
                return false;
            }
        }

        return true;
    }

    /**
     * A justified line can paint its last word with a fresh text matrix far
     * from the rest of the sentence. If that late start happens on several
     * adjacent baselines, a start-only column splitter can mistake those last
     * words for a third reading lane. Real lanes have a vertically recurring
     * left edge and a persistent gutter; a short-lived start bounded by two
     * such edges is instead part of the same-baseline flow immediately to its
     * left. Reattach it before column-major ordering loses that relationship.
     *
     * This operates on prose fragments only. Geometry accepted as a table is
     * still materialized by the table path and never reaches this repair.
     *
     * @param list<array{center: float, runs: list<array<string, mixed>>}> $rows
     * @return list<array{center: float, runs: list<array<string, mixed>>}>
     */
    private function attachWeakSameBaselineFragmentsToPersistentProseLanes(
        array $rows,
        float $medianFontSize
    ): array {
        if (count($rows) < 6) {
            return $rows;
        }

        $startTolerance = max(8.0, $medianFontSize * 1.25);
        $baselineTolerance = max(3.0, $medianFontSize * 0.55);
        $clusters = [];
        $clusterByRow = [];
        foreach ($rows as $rowIndex => $row) {
            if (($row['code'] ?? false) === true || count($row['runs'] ?? []) !== 1) {
                continue;
            }
            $bounds = $this->positionedProseRowBounds($row);
            $matched = null;
            foreach ($clusters as $clusterIndex => $cluster) {
                if (abs($bounds['x1'] - $cluster['center']) <= $startTolerance) {
                    $matched = $clusterIndex;
                    break;
                }
            }
            if ($matched === null) {
                $matched = count($clusters);
                $clusters[] = [
                    'center' => $bounds['x1'],
                    'rows' => [],
                    'minCenter' => (float) $row['center'],
                    'maxCenter' => (float) $row['center'],
                ];
            }
            $count = count($clusters[$matched]['rows']);
            $clusters[$matched]['center'] = (($clusters[$matched]['center'] * $count) + $bounds['x1']) / ($count + 1);
            $clusters[$matched]['rows'][] = $rowIndex;
            $clusters[$matched]['minCenter'] = min($clusters[$matched]['minCenter'], (float) $row['center']);
            $clusters[$matched]['maxCenter'] = max($clusters[$matched]['maxCenter'], (float) $row['center']);
            $clusterByRow[$rowIndex] = $matched;
        }

        $persistent = [];
        foreach ($clusters as $clusterIndex => $cluster) {
            if (count($cluster['rows']) < 3
                || $cluster['maxCenter'] - $cluster['minCenter'] < max(8.0, $medianFontSize * 1.2)) {
                continue;
            }
            $persistent[$clusterIndex] = $cluster;
        }
        if (count($persistent) < 2) {
            return $rows;
        }
        uasort($persistent, static fn (array $left, array $right): int => $left['center'] <=> $right['center']);
        $persistentIndexes = array_keys($persistent);
        $remove = [];

        foreach ($rows as $rowIndex => $row) {
            $clusterIndex = $clusterByRow[$rowIndex] ?? null;
            if ($clusterIndex === null || isset($persistent[$clusterIndex]) || isset($remove[$rowIndex])) {
                continue;
            }
            $weakBounds = $this->positionedProseRowBounds($row);
            $leftClusterIndex = null;
            $rightClusterIndex = null;
            foreach ($persistentIndexes as $candidateIndex) {
                $candidateX = (float) $persistent[$candidateIndex]['center'];
                if ($candidateX < $weakBounds['x1'] - $startTolerance) {
                    $leftClusterIndex = $candidateIndex;
                    continue;
                }
                if ($candidateX > $weakBounds['x1'] + $startTolerance) {
                    $rightClusterIndex = $candidateIndex;
                    break;
                }
            }
            if ($leftClusterIndex === null || $rightClusterIndex === null) {
                continue;
            }

            $leftRowIndex = null;
            foreach ($persistent[$leftClusterIndex]['rows'] as $candidateRowIndex) {
                if (!isset($remove[$candidateRowIndex])
                    && abs((float) $rows[$candidateRowIndex]['center'] - (float) $row['center']) <= $baselineTolerance) {
                    $leftRowIndex = $candidateRowIndex;
                    break;
                }
            }
            $rightRowIndex = null;
            foreach ($persistent[$rightClusterIndex]['rows'] as $candidateRowIndex) {
                if (!isset($remove[$candidateRowIndex])
                    && abs((float) $rows[$candidateRowIndex]['center'] - (float) $row['center']) <= $baselineTolerance) {
                    $rightRowIndex = $candidateRowIndex;
                    break;
                }
            }
            if ($leftRowIndex === null || $rightRowIndex === null) {
                continue;
            }

            $leftBounds = $this->positionedProseRowBounds($rows[$leftRowIndex]);
            $rightBounds = $this->positionedProseRowBounds($rows[$rightRowIndex]);
            $leftGap = $weakBounds['x1'] - $leftBounds['x2'];
            $rightGap = $rightBounds['x1'] - $weakBounds['x2'];
            $weakWidth = max(0.0, $weakBounds['x2'] - $weakBounds['x1']);
            $laneSpan = max(1.0, $rightBounds['x1'] - $leftBounds['x1']);
            if ($leftGap < -$startTolerance
                || $rightGap < max(2.0, $medianFontSize * 0.20)
                || $leftGap > $rightGap + max(12.0, $medianFontSize * 1.5)
                || $weakWidth > $laneSpan * 0.45) {
                continue;
            }

            array_push($rows[$leftRowIndex]['runs'], ...$row['runs']);
            usort(
                $rows[$leftRowIndex]['runs'],
                static fn (array $left, array $right): int => ($left['x1'] <=> $right['x1'])
                    ?: ((int) ($left['order'] ?? 0) <=> (int) ($right['order'] ?? 0))
            );
            $remove[$rowIndex] = true;
        }

        if ($remove === []) {
            return $rows;
        }

        return array_values(array_filter(
            $rows,
            static fn (array $_row, int $index): bool => !isset($remove[$index]),
            ARRAY_FILTER_USE_BOTH
        ));
    }

    /**
     * Keep a centered isolated numeric folio atomic even when it occurs only
     * once, where the repeated-page-furniture remover intentionally cannot
     * discard it. The number remains visible, but neither neighboring reading
     * lane can absorb it into its paragraph.
     *
     * @param list<array<string, mixed>> $items
     * @return list<array<string, mixed>>
     */
    private function markIsolatedCenteredPdfNumberBoundaries(array $items, float $medianFontSize): array
    {
        if (count($items) < 3) {
            return $items;
        }

        $boundsByPage = [];
        foreach ($items as $item) {
            if (!$this->pdfLayoutHasGeometry($item)) {
                continue;
            }
            $page = max(1, (int) $item['page']);
            $boundsByPage[$page]['x1'] = min($boundsByPage[$page]['x1'] ?? (float) $item['x1'], (float) $item['x1']);
            $boundsByPage[$page]['x2'] = max($boundsByPage[$page]['x2'] ?? (float) $item['x2'], (float) $item['x2']);
        }

        foreach ($items as $index => $item) {
            $text = trim((string) ($item['text'] ?? ''));
            if (($item['code'] ?? false) === true
                || preg_match('/^\p{N}{1,4}$/u', $text) !== 1
                || !$this->pdfLayoutHasGeometry($item)) {
                continue;
            }
            $page = max(1, (int) $item['page']);
            $bounds = $boundsByPage[$page] ?? null;
            if (!is_array($bounds)) {
                continue;
            }
            $pageCenter = ((float) $bounds['x1'] + (float) $bounds['x2']) / 2.0;
            $itemCenter = ((float) $item['x1'] + (float) $item['x2']) / 2.0;
            $fontSize = max(1.0, (float) ($item['fontSize'] ?? $medianFontSize));
            if (abs($itemCenter - $pageCenter) > max(24.0, $fontSize * 4.0)) {
                continue;
            }

            $sameBaselineText = false;
            foreach ($items as $otherIndex => $other) {
                if ($otherIndex === $index || !$this->pdfLayoutHasGeometry($other)
                    || (int) $other['page'] !== $page) {
                    continue;
                }
                $verticalOverlap = min((float) $item['y2'], (float) $other['y2'])
                    - max((float) $item['y1'], (float) $other['y1']);
                if ($verticalOverlap >= -max(2.0, $fontSize * 0.20)) {
                    $sameBaselineText = true;
                    break;
                }
            }
            if ($sameBaselineText) {
                continue;
            }

            $items[$index]['forceBlockBreakBefore'] = true;
            if (isset($items[$index + 1]) && (int) ($items[$index + 1]['page'] ?? 0) === $page) {
                $items[$index + 1]['forceBlockBreakBefore'] = true;
            }
        }

        return $items;
    }

    /**
     * @param array{runs: list<array<string, mixed>>} $row
     * @return list<int>
     */
    private function positionedProseRowSourceVerifiedBoundarySeparators(array $row): array
    {
        $separators = [];
        $length = 0;
        foreach ($row['runs'] as $run) {
            foreach ($this->positionedSourceVerifiedBoundarySeparators($run) as $offset => $separator) {
                $separators[$length + $offset] = $separator;
            }
            $length += $this->positionedCompactTextLength((string) ($run['text'] ?? ''));
        }

        foreach ($separators as $offset => $separator) {
            if ($offset <= 0 || $offset >= $length || ($separator !== '' && $separator !== ' ')) {
                unset($separators[$offset]);
            }
        }
        ksort($separators, SORT_NUMERIC);

        return $separators;
    }

    /**
     * @param array{runs: list<array<string, mixed>>} $row
     * @return array<int, true>
     */
    private function positionedProseRowSourceCompactBoundaryOffsets(array $row): array
    {
        $offsets = [];
        $length = 0;
        foreach ($row['runs'] as $run) {
            foreach ($this->positionedSourceCompactBoundaryOffsets($run) as $offset => $_) {
                $offsets[$length + $offset] = true;
            }
            $length += $this->positionedCompactTextLength((string) ($run['text'] ?? ''));
        }

        foreach ($offsets as $offset => $_) {
            if ($offset <= 0 || $offset >= $length) {
                unset($offsets[$offset]);
            }
        }
        ksort($offsets, SORT_NUMERIC);

        return $offsets;
    }

    /**
     * @param array{runs: list<array<string, mixed>>} $row
     * @return array{start: int, end: int}|null
     */
    private function positionedProseRowSourceOrderBounds(array $row): ?array
    {
        $start = null;
        $end = null;
        foreach ($row['runs'] as $run) {
            if (!isset($run['order'])) {
                return null;
            }
            $order = (int) $run['order'];
            $start = min($start ?? $order, $order);
            $end = max($end ?? $order, (int) ($run['lastOrder'] ?? $order));
        }

        return $start === null || $end === null ? null : ['start' => $start, 'end' => $end];
    }

    /**
     * A rotated or malformed display layer can yield a short, oversized text
     * item with an unmatched drawing delimiter. It is not body text and tends
     * to be duplicated by a correctly oriented text layer elsewhere on the
     * page, so exclude it before it can join surrounding prose.
     *
     * @param list<array{text: string, page: int, x1: float, y1: float, x2: float, y2: float, fontSize: float, code: bool}> $items
     * @return list<array{text: string, page: int, x1: float, y1: float, x2: float, y2: float, fontSize: float, code: bool}>
     */
    private function filterPositionedPdfDecorativeItems(array $items, float $medianFontSize): array
    {
        $filtered = [];
        foreach ($items as $item) {
            $text = trim($item['text']);
            $width = max(0.0, $item['x2'] - $item['x1']);
            $height = max(0.0, $item['y2'] - $item['y1']);
            $short = $this->length(preg_replace('/\s+/u', '', $text) ?? '') <= 18
                && count($this->pdfLineWordTokens($text)) <= 3;
            $large = $item['fontSize'] >= max(24.0, $medianFontSize * 4.5);
            $vertical = $height >= max($item['fontSize'] * 1.2, $width * 0.60);
            if (($item['code'] ?? false) !== true
                && $short
                && $large
                && $vertical
                && $this->pdfTextHasUnmatchedDrawingDelimiter($text)) {
                continue;
            }
            $filtered[] = $item;
        }

        return $filtered;
    }

    private function pdfTextHasUnmatchedDrawingDelimiter(string $text): bool
    {
        foreach ([['{', '}'], ['[', ']'], ['(', ')']] as [$open, $close]) {
            if (substr_count($text, $open) !== substr_count($text, $close)) {
                return true;
            }
        }

        return false;
    }

    /**
     * @param list<array{center: float, runs: list<array{page: int, text: string, x1: float, y1: float, x2: float, y2: float, textX1: float, textY1: float, textX2: float, textY2: float, fontSize: float}>}> $rows
     * @param array{x1: float, y1: float, x2: float, y2: float} $pageBounds
     * @return list<array{center: float, runs: list<array{page: int, text: string, x1: float, y1: float, x2: float, y2: float, textX1: float, textY1: float, textX2: float, textY2: float, fontSize: float}>}>
     */
    private function mergePositionedProseRowFragments(array $rows, array $pageBounds): array
    {
        $pageWidth = max(0.0, $pageBounds['x2'] - $pageBounds['x1']);
        foreach ($rows as &$row) {
            $sourceOrdered = $row['runs'];
            usort($sourceOrdered, static fn (array $left, array $right): int => ((int) ($left['order'] ?? 0)) <=> ((int) ($right['order'] ?? 0)));
            $merged = [];
            foreach ($sourceOrdered as $run) {
                $lastIndex = array_key_last($merged);
                if ($lastIndex === null) {
                    $merged[] = $run;
                    continue;
                }

                $last = $merged[$lastIndex];
                $gap = $run['textX1'] - $last['textX2'];
                $fontSize = max($run['fontSize'], $last['fontSize'], 1.0);
                $sourceOrderGap = (int) ($run['order'] ?? 0) - (int) ($last['lastOrder'] ?? $last['order'] ?? 0);
                $visualColumnBoundary = ($run['startsAfterTextBoundary'] ?? false) === true
                    || $sourceOrderGap > 8
                    || (($run['startsWithWhitespace'] ?? false) === true && $gap >= max(8.0, $fontSize * 0.75));
                $sameSourceLine = !$visualColumnBoundary
                    && $gap <= max(6.0, $fontSize)
                    && $gap >= -max(16.0, $fontSize * 1.5);
                // A monospaced listing often uses a deliberately wide grid
                // gap before an inline comment. Keep its two physical runs
                // separate until code-row detection can reconstruct the
                // columns. Otherwise a missing extractor boundary on "//"
                // collapses the gap into ordinary prose and hides the stable
                // pitch that identifies the listing.
                $codeColumnBoundary = !$visualColumnBoundary
                    && $this->positionedProseRunsSpanCodeColumns($last, $run, $gap, $pageWidth);
                $looksLikeLineContinuation = !$visualColumnBoundary
                    && !$codeColumnBoundary
                    && $this->positionedProseRunsLookLikeLineContinuation($last, $run, $gap, $pageWidth);
                if ($sameSourceLine || $looksLikeLineContinuation) {
                    $sourceVerifiedBoundarySeparators = $this->positionedJoinedSourceVerifiedBoundarySeparators(
                        $last,
                        $run,
                        $gap,
                        $fontSize,
                        (bool) ($last['endsWithWhitespace'] ?? false),
                        (bool) ($run['startsWithWhitespace'] ?? false),
                        (bool) ($run['hasWordBoundaryBefore'] ?? false),
                        (bool) ($run['wordBoundaryBefore'] ?? false),
                        is_string($run['wordBoundarySource'] ?? null)
                            ? $run['wordBoundarySource']
                            : null
                    );
                    $sourceCompactBoundaryOffsets = $this->positionedJoinedSourceCompactBoundaryOffsets(
                        $last,
                        $run,
                        $gap,
                        $fontSize,
                        (bool) ($last['endsWithWhitespace'] ?? false),
                        (bool) ($run['startsWithWhitespace'] ?? false),
                        (bool) ($run['hasWordBoundaryBefore'] ?? false),
                        (bool) ($run['wordBoundaryBefore'] ?? false),
                        is_string($run['wordBoundarySource'] ?? null)
                            ? $run['wordBoundarySource']
                            : null
                    );
                    $codeGeometryBoundaryOffsets = $this->positionedJoinedCodeGeometryBoundaryOffsets(
                        $last,
                        $run,
                        $gap,
                        $fontSize
                    );
                    $joinedText = $this->joinPositionedCellText(
                        $last['text'],
                        $run['text'],
                        $gap,
                        $fontSize,
                        (bool) ($last['endsWithWhitespace'] ?? false),
                        (bool) ($run['startsWithWhitespace'] ?? false),
                        (bool) ($run['hasWordBoundaryBefore'] ?? false),
                        (bool) ($run['wordBoundaryBefore'] ?? false),
                        is_string($run['wordBoundarySource'] ?? null)
                            ? $run['wordBoundarySource']
                            : null
                    );
                    $mergedRun = [
                        'page' => $last['page'],
                        'text' => $joinedText,
                        'rtlVisualUnitText' => $this->joinPositionedCellText(
                            (string) ($last['rtlVisualUnitText'] ?? $last['text']),
                            (string) ($run['rtlVisualUnitText'] ?? $run['text']),
                            $gap,
                            $fontSize,
                            (bool) ($last['endsWithWhitespace'] ?? false),
                            (bool) ($run['startsWithWhitespace'] ?? false),
                            (bool) ($run['hasWordBoundaryBefore'] ?? false),
                            (bool) ($run['wordBoundaryBefore'] ?? false),
                            is_string($run['wordBoundarySource'] ?? null)
                                ? $run['wordBoundarySource']
                                : null
                        ),
                        'x1' => min($last['x1'], $run['x1']),
                        'y1' => min($last['y1'], $run['y1']),
                        'x2' => max($last['x2'], $run['x2']),
                        'y2' => max($last['y2'], $run['y2']),
                        'textX1' => min($last['textX1'], $run['textX1']),
                        'textY1' => min($last['textY1'], $run['textY1']),
                        'textX2' => max($last['textX2'], $run['textX2']),
                        'textY2' => max($last['textY2'], $run['textY2']),
                        'fontSize' => max($run['fontSize'], $last['fontSize']),
                        'startsWithWhitespace' => (bool) ($last['startsWithWhitespace'] ?? false),
                        'endsWithWhitespace' => (bool) ($run['endsWithWhitespace'] ?? false),
                        'hasWordBoundaryBefore' => (bool) ($last['hasWordBoundaryBefore'] ?? false),
                        'wordBoundaryBefore' => (bool) ($last['wordBoundaryBefore'] ?? false),
                        'wordBoundarySource' => $last['wordBoundarySource'] ?? null,
                        'sourceVerifiedBoundarySeparators' => $sourceVerifiedBoundarySeparators,
                        'sourceCompactBoundaryOffsets' => $sourceCompactBoundaryOffsets,
                        'codeGeometryBoundaryOffsets' => $codeGeometryBoundaryOffsets,
                        'startsAfterTextBoundary' => (bool) ($last['startsAfterTextBoundary'] ?? false),
                        'order' => min((int) ($last['order'] ?? 0), (int) ($run['order'] ?? 0)),
                        'lastOrder' => max((int) ($last['lastOrder'] ?? $last['order'] ?? 0), (int) ($run['lastOrder'] ?? $run['order'] ?? 0)),
                    ];
                    $inlineFontStyleSpans = $this->positionedInlineFontStyleSpansForJoinedText(
                        $joinedText,
                        [$last, $run]
                    );
                    if ($inlineFontStyleSpans !== []) {
                        $mergedRun['sourcePdfInlineFontStyleSpans'] = $inlineFontStyleSpans;
                    }
                    $exactSourceRanges = $this->pdfPositionedExactSourceRangesForItems([$last, $run]);
                    if ($exactSourceRanges !== []) {
                        $mergedRun['sourcePdfExactSourceRanges'] = $exactSourceRanges;
                    }
                    $merged[$lastIndex] = $mergedRun;
                    continue;
                }

                $merged[] = $run;
            }
            $merged = $this->removeOverprintedPositionedRuns($merged);
            usort($merged, static fn (array $left, array $right): int => ($left['x1'] <=> $right['x1']) ?: (((int) ($left['order'] ?? 0)) <=> ((int) ($right['order'] ?? 0))));
            $row['runs'] = $merged;
        }
        unset($row);

        return $rows;
    }

    /**
     * After column ordering, small styled text runs from one visual line are
     * adjacent again. Recombine only when their baselines and font metrics
     * agree and at least one run is too short to represent a full column line.
     *
     * @param list<array{center: float, runs: list<array<string, mixed>>}> $rows
     * @return list<array{center: float, runs: list<array<string, mixed>>}>
     */
    private function mergeAdjacentPositionedProseRowsOnSameBaseline(array $rows): array
    {
        $merged = [];
        foreach ($rows as $row) {
            $lastIndex = array_key_last($merged);
            if ($lastIndex === null || ($row['code'] ?? false) === true || ($merged[$lastIndex]['code'] ?? false) === true) {
                $merged[] = $row;
                continue;
            }

            $last = $merged[$lastIndex];
            $lastBounds = $this->positionedProseRowBounds($last);
            $rowBounds = $this->positionedProseRowBounds($row);
            $lastPage = (int) ($last['runs'][0]['page'] ?? 1);
            $rowPage = (int) ($row['runs'][0]['page'] ?? 1);
            $fontSize = max($this->positionedRowMaxFontSize($last), $this->positionedRowMaxFontSize($row), 1.0);
            $lastWidth = max(0.0, $lastBounds['x2'] - $lastBounds['x1']);
            $rowWidth = max(0.0, $rowBounds['x2'] - $rowBounds['x1']);
            $gap = $rowBounds['x1'] - $lastBounds['x2'];
            $sameBaseline = abs((float) $last['center'] - (float) $row['center']) <= max(2.5, $fontSize * 0.30);
            // RTL fonts commonly report overlapping visual boxes for adjacent
            // Latin and Arabic runs. Permit a modest em-sized overlap only on
            // a baseline carrying strong RTL script; ordinary LTR pages keep
            // the established narrow overlap tolerance.
            $rtlBaseline = $this->positionedProseRowHasStrongRtlText($last)
                || $this->positionedProseRowHasStrongRtlText($row);
            $overlapTolerance = $rtlBaseline
                ? max(3.0, $fontSize * 0.65)
                : max(2.0, $fontSize * 0.15);
            $nearby = $gap >= -$overlapTolerance && $gap <= max(18.0, $fontSize * 1.5);
            $hasShortFragment = min($lastWidth, $rowWidth) <= $fontSize * 6.5;
            $distinctStyledBaseline = false;
            foreach ($row['runs'] as $run) {
                if ($this->positionedRunStartsDistinctStyledBaseline($run, $last)) {
                    $distinctStyledBaseline = true;
                    break;
                }
            }
            if (!$distinctStyledBaseline) {
                foreach ($last['runs'] as $run) {
                    if ($this->positionedRunStartsDistinctStyledBaseline($run, $row)) {
                        $distinctStyledBaseline = true;
                        break;
                    }
                }
            }

            if ($lastPage !== $rowPage
                || !$sameBaseline
                || !$nearby
                || !$hasShortFragment
                || $distinctStyledBaseline
                || !$this->positionedProseRowsAreContiguousInSourceOrder($last, $row)) {
                $merged[] = $row;
                continue;
            }

            $runs = array_merge($last['runs'], $row['runs']);
            usort($runs, static fn (array $left, array $right): int => ($left['x1'] <=> $right['x1']) ?: (((int) ($left['order'] ?? 0)) <=> ((int) ($right['order'] ?? 0))));
            $merged[$lastIndex] = [
                'center' => ((float) $last['center'] + (float) $row['center']) / 2.0,
                'runs' => $runs,
                'visualRtlOrder' => ($last['visualRtlOrder'] ?? false) === true
                    || ($row['visualRtlOrder'] ?? false) === true,
                'visualRtlProtectedClusters' => array_values(array_unique(array_merge(
                    is_array($last['visualRtlProtectedClusters'] ?? null) ? $last['visualRtlProtectedClusters'] : [],
                    is_array($row['visualRtlProtectedClusters'] ?? null) ? $row['visualRtlProtectedClusters'] : []
                ))),
            ];
        }

        return $merged;
    }

    /**
     * Same-baseline fragments are only one visual line when their content
     * stream runs are locally adjacent. A short formula label near a column
     * gutter otherwise looks like a styled continuation and can get joined to
     * unrelated body prose in the neighboring column.
     *
     * @param array{runs: list<array<string, mixed>>} $left
     * @param array{runs: list<array<string, mixed>>} $right
     */
    private function positionedProseRowsAreContiguousInSourceOrder(array $left, array $right): bool
    {
        $leftFirst = null;
        $leftLast = null;
        foreach ($left['runs'] as $run) {
            if (!isset($run['order'])) {
                return true;
            }
            $leftFirst = min($leftFirst ?? (int) $run['order'], (int) $run['order']);
            $leftLast = max($leftLast ?? (int) $run['order'], (int) ($run['lastOrder'] ?? $run['order']));
        }

        $rightFirst = null;
        $rightLast = null;
        foreach ($right['runs'] as $run) {
            if (!isset($run['order'])) {
                return true;
            }
            $rightFirst = min($rightFirst ?? (int) $run['order'], (int) $run['order']);
            $rightLast = max($rightLast ?? (int) $run['order'], (int) ($run['lastOrder'] ?? $run['order']));
        }

        if ($leftFirst === null || $leftLast === null || $rightFirst === null || $rightLast === null) {
            return false;
        }

        $forwardGap = $rightFirst - $leftLast;
        $reverseGap = $leftFirst - $rightLast;

        return ($forwardGap > 0 && $forwardGap <= 8)
            || ($reverseGap > 0
                && $reverseGap <= 8
                && ($this->positionedProseRowHasStrongRtlText($left)
                    || $this->positionedProseRowHasStrongRtlText($right)));
    }

    /** @param array{runs: list<array<string, mixed>>} $row */
    private function positionedProseRowHasStrongRtlText(array $row): bool
    {
        foreach ($row['runs'] as $run) {
            if (preg_match('/[\x{0590}-\x{08FF}\x{FB1D}-\x{FDFF}\x{FE70}-\x{FEFF}]/u', (string) ($run['text'] ?? '')) === 1) {
                return true;
            }
        }

        return false;
    }

    /**
     * A full-width RTL line can be split into false LTR columns after its
     * glyph fragments are separated for prose-lane inference. Recognize only
     * a sustained page flow whose source-adjacent fragments advance toward
     * the left on the same baseline without crossing a real gutter. This is
     * geometry and paint-order evidence; no language vocabulary is involved.
     *
     * @param list<array{center:float,runs:list<array<string,mixed>>}> $rows
     */
    private function positionedRowsHaveSustainedVisualRtlLineFlow(array $rows): bool
    {
        $rtlRows = 0;
        $continuousRows = 0;
        foreach ($rows as $row) {
            if (($row['code'] ?? false) === true
                || ($row['visualRtlOrder'] ?? false) !== true) {
                continue;
            }
            $rtlRows++;
            if ($this->positionedRowHasContinuousVisualRtlLineFlow($row)) {
                $continuousRows++;
            }
        }

        return $rtlRows >= 3
            && $continuousRows >= 3
            && $continuousRows / $rtlRows >= 0.60;
    }

    /** @param array{runs:list<array<string,mixed>>} $row */
    private function positionedRowHasContinuousVisualRtlLineFlow(array $row): bool
    {
        if (($row['visualRtlOrder'] ?? false) !== true || count($row['runs']) < 2) {
            return false;
        }

        $sourceOrdered = $row['runs'];
        foreach ($sourceOrdered as $run) {
            if (!isset($run['order'])) {
                return false;
            }
        }
        usort($sourceOrdered, static fn (array $left, array $right): int =>
            ((int) $left['order']) <=> ((int) $right['order'])
        );

        for ($index = 1, $count = count($sourceOrdered); $index < $count; $index++) {
            $previous = $sourceOrdered[$index - 1];
            $current = $sourceOrdered[$index];
            if ((int) ($previous['page'] ?? 0) !== (int) ($current['page'] ?? 0)) {
                return false;
            }
            $sourceGap = (int) $current['order']
                - (int) ($previous['lastOrder'] ?? $previous['order']);
            if ($sourceGap < 1 || $sourceGap > 8) {
                return false;
            }

            $previousCenter = ((float) ($previous['textX1'] ?? $previous['x1'] ?? 0.0)
                + (float) ($previous['textX2'] ?? $previous['x2'] ?? 0.0)) / 2.0;
            $currentCenter = ((float) ($current['textX1'] ?? $current['x1'] ?? 0.0)
                + (float) ($current['textX2'] ?? $current['x2'] ?? 0.0)) / 2.0;
            if ($previousCenter - $currentCenter <= 0.25) {
                return false;
            }

            $fontSize = max(
                1.0,
                (float) ($previous['fontSize'] ?? 1.0),
                (float) ($current['fontSize'] ?? 1.0)
            );
            $visualGap = (float) ($previous['textX1'] ?? $previous['x1'] ?? 0.0)
                - (float) ($current['textX2'] ?? $current['x2'] ?? 0.0);
            if ($visualGap > max(8.0, $fontSize * 0.75)) {
                return false;
            }
        }

        return true;
    }

    /**
     * Once a sustained RTL line flow is proven above, restore physical row
     * order after the ordinary column pass has performed its useful local
     * style grouping. Source order resolves fragments on one baseline; page
     * geometry resolves the baseline sequence.
     *
     * @param list<array<string,mixed>> $items
     * @return list<array<string,mixed>>
     */
    private function positionedItemsInProvenVisualRtlRowOrder(array $items): array
    {
        usort($items, static function (array $left, array $right): int {
            $pageOrder = (int) ($left['page'] ?? 0) <=> (int) ($right['page'] ?? 0);
            if ($pageOrder !== 0) {
                return $pageOrder;
            }

            $leftCenter = ((float) ($left['y1'] ?? 0.0) + (float) ($left['y2'] ?? 0.0)) / 2.0;
            $rightCenter = ((float) ($right['y1'] ?? 0.0) + (float) ($right['y2'] ?? 0.0)) / 2.0;
            $tolerance = max(
                1.0,
                (float) ($left['fontSize'] ?? 1.0) * 0.20,
                (float) ($right['fontSize'] ?? 1.0) * 0.20
            );
            if (abs($leftCenter - $rightCenter) > $tolerance) {
                return $rightCenter <=> $leftCenter;
            }

            $leftOrder = is_int($left['sourceOrderStart'] ?? null)
                ? $left['sourceOrderStart']
                : PHP_INT_MAX;
            $rightOrder = is_int($right['sourceOrderStart'] ?? null)
                ? $right['sourceOrderStart']
                : PHP_INT_MAX;

            return ($leftOrder <=> $rightOrder)
                ?: ((float) ($right['x2'] ?? 0.0) <=> (float) ($left['x2'] ?? 0.0));
        });

        return $items;
    }

    /**
     * Join only same-word RTL shards whose adjacent paint ranges meet at the
     * glyph edge. A normal inter-word boundary has either a larger advance or
     * a non-RTL boundary character, so headings and embedded Latin atoms stay
     * independent blocks.
     *
     * @param list<array<string,mixed>> $items
     * @return list<array<string,mixed>>
     */
    private function joinPositionedVisualRtlWordShards(array $items): array
    {
        $joined = [];
        foreach ($items as $item) {
            $lastIndex = array_key_last($joined);
            if ($lastIndex === null
                || !$this->positionedVisualRtlItemsAreWordShards($joined[$lastIndex], $item)) {
                $joined[] = $item;
                continue;
            }

            $previous = $joined[$lastIndex];
            $exactSourceRanges = $this->pdfPositionedExactSourceRangesForItems([$previous, $item]);
            $previous['text'] = $this->appendCellText(
                (string) ($previous['text'] ?? ''),
                (string) ($item['text'] ?? '')
            );
            $previous['logicalRtlTextCandidate'] = rtrim(
                (string) ($previous['logicalRtlTextCandidate'] ?? '')
            ) . ltrim((string) ($item['logicalRtlTextCandidate'] ?? ''));
            $previous['x1'] = min((float) $previous['x1'], (float) $item['x1']);
            $previous['y1'] = min((float) $previous['y1'], (float) $item['y1']);
            $previous['x2'] = max((float) $previous['x2'], (float) $item['x2']);
            $previous['y2'] = max((float) $previous['y2'], (float) $item['y2']);
            $previous['fontSize'] = max(
                (float) ($previous['fontSize'] ?? 0.0),
                (float) ($item['fontSize'] ?? 0.0)
            );
            $previous['endsWithWhitespace'] = (bool) ($item['endsWithWhitespace'] ?? false);
            $previous['sourceOrderEnd'] = (int) ($item['sourceOrderEnd'] ?? $item['sourceOrderStart']);
            $previous['visualRtlOrder'] = true;
            $previous['visualRtlWordShardJoin'] = true;
            $previous['visualRtlProtectedClusters'] = array_values(array_unique(array_merge(
                is_array($previous['visualRtlProtectedClusters'] ?? null)
                    ? $previous['visualRtlProtectedClusters']
                    : [],
                is_array($item['visualRtlProtectedClusters'] ?? null)
                    ? $item['visualRtlProtectedClusters']
                    : []
            )));
            unset(
                $previous['sourceVerifiedBoundarySeparators'],
                $previous['sourceCompactBoundaryOffsets'],
                $previous['positionedTextCandidate']
            );
            if ($exactSourceRanges !== []) {
                $previous['sourcePdfExactSourceRanges'] = $exactSourceRanges;
            }
            $joined[$lastIndex] = $previous;
        }

        return $joined;
    }

    /** @param array<string,mixed> $left @param array<string,mixed> $right */
    private function positionedVisualRtlItemsAreWordShards(array $left, array $right): bool
    {
        if (($left['visualRtlOrder'] ?? false) !== true
            || ($right['visualRtlOrder'] ?? false) !== true
            || ($left['code'] ?? false) === true
            || ($right['code'] ?? false) === true
            || (int) ($left['page'] ?? 0) !== (int) ($right['page'] ?? 0)
            || !is_int($left['sourceOrderEnd'] ?? null)
            || !is_int($right['sourceOrderStart'] ?? null)
            || $right['sourceOrderStart'] - $left['sourceOrderEnd'] !== 1) {
            return false;
        }

        $leftCandidate = rtrim((string) ($left['logicalRtlTextCandidate'] ?? ''));
        $rightCandidate = ltrim((string) ($right['logicalRtlTextCandidate'] ?? ''));
        if ($leftCandidate === ''
            || $rightCandidate === ''
            || preg_match('/[\x{0590}-\x{08FF}\x{FB1D}-\x{FDFF}\x{FE70}-\x{FEFF}]$/u', $leftCandidate) !== 1
            || preg_match('/^[\x{0590}-\x{08FF}\x{FB1D}-\x{FDFF}\x{FE70}-\x{FEFF}]/u', $rightCandidate) !== 1) {
            return false;
        }

        $fontSize = max(
            1.0,
            (float) ($left['fontSize'] ?? 1.0),
            (float) ($right['fontSize'] ?? 1.0)
        );
        $leftCenter = ((float) $left['y1'] + (float) $left['y2']) / 2.0;
        $rightCenter = ((float) $right['y1'] + (float) $right['y2']) / 2.0;
        if (abs($leftCenter - $rightCenter) > max(1.0, $fontSize * 0.20)) {
            return false;
        }

        $paintedGap = (float) $left['x1'] - (float) $right['x2'];

        return $paintedGap <= -max(3.5, $fontSize * 0.30)
            && $paintedGap >= -max(18.0, $fontSize * 1.50);
    }

    /**
     * PDF text operators frequently paint an RTL line in left-to-right visual
     * order. Geometry makes that distinguishable from a logical-order text
     * run: successive source fragments move toward larger x coordinates even
     * though most of their characters are RTL. Require several local moves so
     * a lone Arabic or Hebrew label never changes an otherwise LTR row.
     *
     * @param list<array<string, mixed>> $runs
     */
    private function positionedRunsUseVisualRtlOrder(array $runs): bool
    {
        if (count($runs) < 3) {
            return false;
        }

        $rtlCharacters = 0;
        $wordCharacters = 0;
        $sourceOrdered = [];
        foreach ($runs as $run) {
            $text = (string) ($run['text'] ?? '');
            $rtlCount = preg_match_all('/[\x{0590}-\x{08FF}\x{FB1D}-\x{FDFF}\x{FE70}-\x{FEFF}]/u', $text);
            $wordCount = preg_match_all('/[\p{L}\p{N}]/u', $text);
            $rtlCharacters += $rtlCount === false ? 0 : $rtlCount;
            $wordCharacters += $wordCount === false ? 0 : $wordCount;
            if (isset($run['order'])) {
                $sourceOrdered[] = $run;
            }
        }
        if ($rtlCharacters < 4
            || $wordCharacters === 0
            || $rtlCharacters / $wordCharacters < 0.35
            || count($sourceOrdered) < 3) {
            return false;
        }

        usort($sourceOrdered, static fn (array $left, array $right): int => ((int) $left['order']) <=> ((int) $right['order']));
        $movesRight = 0;
        $movesLeft = 0;
        for ($index = 1, $count = count($sourceOrdered); $index < $count; $index++) {
            $previous = $sourceOrdered[$index - 1];
            $current = $sourceOrdered[$index];
            if (preg_match('/[\x{0590}-\x{08FF}\x{FB1D}-\x{FDFF}\x{FE70}-\x{FEFF}]/u', (string) ($previous['text'] ?? '') . (string) ($current['text'] ?? '')) !== 1) {
                continue;
            }
            $previousCenter = ((float) ($previous['textX1'] ?? $previous['x1'] ?? 0.0)
                + (float) ($previous['textX2'] ?? $previous['x2'] ?? 0.0)) / 2.0;
            $currentCenter = ((float) ($current['textX1'] ?? $current['x1'] ?? 0.0)
                + (float) ($current['textX2'] ?? $current['x2'] ?? 0.0)) / 2.0;
            $delta = $currentCenter - $previousCenter;
            if ($delta > 0.25) {
                $movesRight++;
            } elseif ($delta < -0.25) {
                $movesLeft++;
            }
        }

        return $movesRight >= 2 && $movesRight >= ($movesLeft * 2);
    }

    /**
     * ToUnicode can expand one Arabic lam-alef glyph into two logical code
     * points. Remember only variants that arrived as one positioned run, so
     * visual-order reversal keeps the shaping cluster together without
     * treating the same letters elsewhere as a document-wide exception.
     *
     * @param list<array<string, mixed>> $runs
     * @return list<string>
     */
    private function positionedRtlShapingClusters(array $runs): array
    {
        $clusters = [];
        foreach ($runs as $run) {
            $text = trim((string) ($run['text'] ?? ''));
            if (preg_match('/^ل[اأإآ]$/u', $text) === 1) {
                $clusters[$text] = true;
            }
        }

        return array_keys($clusters);
    }

    /**
     * Convert visual-order RTL lines only on pages where positioned geometry
     * proved that storage order. Latin phrases and numbers are protected as
     * atomic LTR spans while grapheme clusters are reversed, which preserves
     * embedded identifiers without consulting any document vocabulary.
     *
     * @param list<array<string, mixed>> $items
     * @param list<array<string, mixed>> $positionedEvidenceItems
     * @return list<array<string, mixed>>
     */
    private function logicalTextFromVisualRtlItems(array $items, array $positionedEvidenceItems): array
    {
        $visualRtlPages = [];
        $protectedClustersByPage = [];
        foreach ($positionedEvidenceItems as $item) {
            if (($item['visualRtlOrder'] ?? false) === true) {
                $page = (int) ($item['page'] ?? 0);
                $visualRtlPages[$page] = true;
                foreach (is_array($item['visualRtlProtectedClusters'] ?? null) ? $item['visualRtlProtectedClusters'] : [] as $cluster) {
                    if (is_string($cluster) && $cluster !== '') {
                        $protectedClustersByPage[$page][$cluster] = true;
                    }
                }
            }
        }
        if ($visualRtlPages === []) {
            return $items;
        }

        foreach ($items as &$item) {
            $page = (int) ($item['page'] ?? 0);
            $text = (string) ($item['text'] ?? '');
            if (!isset($visualRtlPages[$page])) {
                continue;
            }
            $itemClusters = is_array($item['visualRtlProtectedClusters'] ?? null)
                ? $item['visualRtlProtectedClusters']
                : array_keys($protectedClustersByPage[$page] ?? []);
            $logicalCandidate = is_string($item['logicalRtlTextCandidate'] ?? null)
                ? $item['logicalRtlTextCandidate']
                : '';
            $visualCandidate = is_string($item['positionedTextCandidate'] ?? null)
                ? $item['positionedTextCandidate']
                : (($item['visualRtlOrder'] ?? false) === true ? $text : '');
            $hasExactLogicalCandidate = $logicalCandidate !== ''
                && $visualCandidate !== ''
                && $this->pdfComparableLineText($visualCandidate) === $this->pdfComparableLineText($text);
            if (!$hasExactLogicalCandidate && !$this->pdfTextIsRtlDominant($text)) {
                continue;
            }
            $logical = $hasExactLogicalCandidate
                ? $logicalCandidate
                : $this->logicalTextFromVisualRtlLine($text, $itemClusters);
            if ($logical !== $text) {
                $item['text'] = $logical;
                $item['visualRtlNormalized'] = true;
            }
        }
        unset($item);

        return $items;
    }

    private function pdfTextIsRtlDominant(string $text): bool
    {
        $rtlCharacters = preg_match_all('/[\x{0590}-\x{08FF}\x{FB1D}-\x{FDFF}\x{FE70}-\x{FEFF}]/u', $text);
        $wordCharacters = preg_match_all('/[\p{L}\p{N}]/u', $text);

        return $rtlCharacters !== false
            && $wordCharacters !== false
            && $rtlCharacters >= 2
            && $wordCharacters > 0
            && $rtlCharacters / $wordCharacters >= 0.35;
    }

    /** @param list<string> $protectedRtlClusters */
    private function logicalTextFromVisualRtlLine(string $text, array $protectedRtlClusters = []): string
    {
        $ltrAtom = "[\\p{Latin}\\p{N}][\\p{Latin}\\p{M}\\p{N}\\x{200C}\\x{200D}._:\\/@#%+?=&~'’\\-]*";
        $protectedAlternatives = [$ltrAtom . '(?:[ \t]+' . $ltrAtom . ')*'];
        $protectedAlternatives[] = preg_quote(self::PDF_RTL_SHAPING_CLUSTER_START, '/')
            . '[^' . preg_quote(self::PDF_RTL_SHAPING_CLUSTER_END, '/') . ']+'
            . preg_quote(self::PDF_RTL_SHAPING_CLUSTER_END, '/');
        foreach (array_values(array_unique($protectedRtlClusters)) as $cluster) {
            if ($cluster !== '') {
                $protectedAlternatives[] = preg_quote($cluster, '/');
            }
        }
        $protectedUnit = '(?:' . implode('|', $protectedAlternatives) . ')';
        $matched = preg_match_all('/' . $protectedUnit . '/u', $text, $matches, PREG_OFFSET_CAPTURE);
        if ($matched === false) {
            return $text;
        }

        $units = [];
        $offset = 0;
        $appendGraphemes = static function (string $segment) use (&$units): void {
            if ($segment === '') {
                return;
            }
            $count = preg_match_all('/\X/u', $segment, $graphemes);
            if ($count === false || $count === 0) {
                $units[] = $segment;
                return;
            }
            foreach ($graphemes[0] as $grapheme) {
                $units[] = $grapheme;
            }
        };

        foreach ($matches[0] as [$ltrText, $ltrOffset]) {
            $appendGraphemes(substr($text, $offset, $ltrOffset - $offset));
            $units[] = $ltrText;
            $offset = $ltrOffset + strlen($ltrText);
        }
        $appendGraphemes(substr($text, $offset));

        return str_replace(
            [self::PDF_RTL_SHAPING_CLUSTER_START, self::PDF_RTL_SHAPING_CLUSTER_END],
            '',
            implode('', array_reverse($units))
        );
    }

    /**
     * Monospaced listings expose a stable character pitch and baseline rhythm
     * even when the PDF does not carry semantic tags. Mark only sustained runs
     * that also contain generic programming punctuation; proportional prose
     * and ordinary aligned columns remain prose.
     *
     * @param list<array{center: float, runs: list<array<string, mixed>>}> $rows
     * @return list<array{center: float, runs: list<array<string, mixed>>}>
     */
    private function markPositionedCodeListingRows(array $rows): array
    {
        if (count($rows) < 4) {
            return $rows;
        }

        $signatures = array_map(fn (array $row): array => $this->positionedCodeRowSignature($row), $rows);
        foreach ($signatures as &$signature) {
            if ($signature['pitch'] !== null && $signature['codeEvidence'] >= 1) {
                // Missing separators make width/character-count overestimate
                // a monospaced pitch. The font em is an independent upper
                // bound; applying it only to syntax-bearing rows lets a short
                // listing remain a stable band without affecting prose.
                $signature['pitch'] = min(
                    (float) $signature['pitch'],
                    max(0.5, (float) $signature['fontSize'] * 0.70)
                );
            }
        }
        unset($signature);
        // A brace-only line has no measurable multi-character pitch, but it
        // should not split an otherwise stable monospaced listing. Borrow a
        // pitch only when matching pitched rows bracket the delimiter on the
        // adjacent baselines; isolated drawing punctuation remains prose.
        for ($signatureIndex = 1, $signatureCount = count($signatures) - 1; $signatureIndex < $signatureCount; $signatureIndex++) {
            if ($signatures[$signatureIndex]['pitch'] !== null
                || preg_match('/^\s*[}\])]+[;,]?\s*$/u', $this->positionedRowText($rows[$signatureIndex])) !== 1
                || $signatures[$signatureIndex - 1]['pitch'] === null
                || $signatures[$signatureIndex + 1]['pitch'] === null) {
                continue;
            }
            $previousPitch = (float) $signatures[$signatureIndex - 1]['pitch'];
            $nextPitch = (float) $signatures[$signatureIndex + 1]['pitch'];
            if (abs($previousPitch - $nextPitch) > max(0.45, max($previousPitch, $nextPitch) * 0.15)) {
                continue;
            }
            $inferred = $signatures[$signatureIndex];
            $inferred['pitch'] = ($previousPitch + $nextPitch) / 2.0;
            $inferred['codeCoverage'] = 1.0;
            if ($this->positionedCodeRowsShareBand($signatures[$signatureIndex - 1], $inferred)
                && $this->positionedCodeRowsShareBand($inferred, $signatures[$signatureIndex + 1])) {
                $signatures[$signatureIndex] = $inferred;
            }
        }
        $rowCount = count($rows);
        $index = 0;
        while ($index < $rowCount) {
            if ($signatures[$index]['pitch'] === null) {
                $index++;
                continue;
            }

            $end = $index;
            while ($end + 1 < $rowCount && $this->positionedCodeRowsShareBand($signatures[$end], $signatures[$end + 1])) {
                $end++;
            }

            $bandSignatures = array_slice($signatures, $index, $end - $index + 1);
            $firstCodeOffset = null;
            $lastCodeOffset = null;
            foreach ($bandSignatures as $offset => $signature) {
                if ($signature['codeEvidence'] < 1 || $signature['codeCoverage'] < 0.55) {
                    continue;
                }
                $firstCodeOffset ??= $offset;
                $lastCodeOffset = $offset;
            }
            if ($firstCodeOffset !== null && $lastCodeOffset !== null) {
                $candidateSignatures = array_slice(
                    $bandSignatures,
                    $firstCodeOffset,
                    $lastCodeOffset - $firstCodeOffset + 1
                );
            } else {
                $candidateSignatures = [];
            }
            if ($this->positionedBandLooksLikeCode($candidateSignatures)) {
                $pitch = $this->median(array_map(
                    static fn (array $signature): float => (float) $signature['pitch'],
                    $candidateSignatures
                ));
                $minimumX = min(array_map(
                    static fn (array $signature): float => (float) $signature['x1'],
                    $candidateSignatures
                ));
                $firstCodeRow = $index + $firstCodeOffset;
                $lastCodeRow = $index + $lastCodeOffset;
                for ($rowIndex = $firstCodeRow; $rowIndex <= $lastCodeRow; $rowIndex++) {
                    $rows[$rowIndex]['code'] = true;
                    $rows[$rowIndex]['codeText'] = $this->positionedCodeLineText($rows[$rowIndex], $minimumX, $pitch);
                }
            }

            $index = $end + 1;
        }

        return $rows;
    }

    /**
     * @param array{center: float, runs: list<array<string, mixed>>} $row
     * @return array{center: float, x1: float, y1: float, y2: float, fontSize: float, pitch: ?float, codeEvidence: int, leadingCodeEvidence: int, codeCoverage: float}
     */
    private function positionedCodeRowSignature(array $row): array
    {
        $bounds = $this->positionedProseRowBounds($row);
        $pitches = [];
        foreach ($row['runs'] as $run) {
            $text = trim((string) ($run['text'] ?? ''));
            $characters = $this->length($text);
            $width = abs((float) ($run['textX2'] ?? $run['x2'] ?? 0.0) - (float) ($run['textX1'] ?? $run['x1'] ?? 0.0));
            if ($characters >= 2 && $width > 0.0) {
                $pitches[] = $width / $characters;
            }
        }

        $pitch = $pitches === [] ? null : $this->median($pitches);
        if ($pitch !== null && count($pitches) >= 2) {
            $consistent = 0;
            foreach ($pitches as $candidate) {
                if (abs($candidate - $pitch) <= max(0.35, $pitch * 0.18)) {
                    $consistent++;
                }
            }
            if ($consistent / count($pitches) < 0.65) {
                $pitch = null;
            }
        }

        $totalWidth = 0.0;
        $codeWidth = 0.0;
        $codeEvidence = 0;
        foreach ($row['runs'] as $run) {
            $text = trim((string) ($run['text'] ?? ''));
            $width = max(0.0, (float) ($run['textX2'] ?? $run['x2'] ?? 0.0) - (float) ($run['textX1'] ?? $run['x1'] ?? 0.0));
            $evidence = $this->positionedCodeSyntaxEvidence($text);
            $totalWidth += $width;
            $codeEvidence += $evidence;
            if ($evidence >= 2) {
                $codeWidth += $width;
            }
        }

        $rowText = $this->positionedRowText($row);
        $rowEvidence = $this->positionedCodeSyntaxEvidence($rowText);
        $leadingText = $rowText;
        if (preg_match('/^.{0,48}/us', $rowText, $leadingMatch) === 1) {
            $leadingText = $leadingMatch[0];
        }
        $codeCoverage = $totalWidth > 0.0 ? $codeWidth / $totalWidth : 0.0;
        if ($rowEvidence >= 2) {
            $codeCoverage = 1.0;
        }

        return [
            'center' => (float) $row['center'],
            'x1' => $bounds['x1'],
            'y1' => $bounds['y1'],
            'y2' => $bounds['y2'],
            'fontSize' => $this->positionedRowMaxFontSize($row),
            'pitch' => $pitch,
            'codeEvidence' => max($codeEvidence, $rowEvidence),
            'leadingCodeEvidence' => $this->positionedCodeSyntaxEvidence($leadingText),
            'codeCoverage' => $codeCoverage,
        ];
    }

    /**
     * @param array{center: float, x1: float, y1: float, y2: float, fontSize: float, pitch: ?float, codeEvidence: int, codeCoverage: float} $upper
     * @param array{center: float, x1: float, y1: float, y2: float, fontSize: float, pitch: ?float, codeEvidence: int, codeCoverage: float} $lower
     */
    private function positionedCodeRowsShareBand(array $upper, array $lower): bool
    {
        if ($upper['pitch'] === null || $lower['pitch'] === null) {
            return false;
        }

        $fontSize = max($upper['fontSize'], $lower['fontSize'], 1.0);
        if (abs($upper['fontSize'] - $lower['fontSize']) > max(1.25, $fontSize * 0.18)) {
            return false;
        }
        $pitch = max($upper['pitch'], $lower['pitch'], 0.1);
        if (abs($upper['pitch'] - $lower['pitch']) > max(0.45, $pitch * 0.15)) {
            return false;
        }

        $height = max(
            1.0,
            $upper['y2'] - $upper['y1'],
            $lower['y2'] - $lower['y1'],
            $fontSize
        );
        $baselineGap = $upper['center'] - $lower['center'];

        return $baselineGap >= $height * 0.35 && $baselineGap <= $height * 2.2;
    }

    /**
     * @param list<array{center: float, x1: float, y1: float, y2: float, fontSize: float, pitch: ?float, codeEvidence: int, leadingCodeEvidence?: int, codeCoverage: float}> $signatures
     */
    private function positionedBandLooksLikeCode(array $signatures): bool
    {
        $count = count($signatures);
        if ($count < 4) {
            return false;
        }

        $evidenceRows = 0;
        $evidenceScore = 0;
        $leadingEvidenceRows = 0;
        $pitches = [];
        $xStarts = [];
        $fontSizes = [];
        foreach ($signatures as $signature) {
            $evidenceScore += $signature['codeEvidence'];
            if ($signature['codeEvidence'] >= 2 && $signature['codeCoverage'] >= 0.75) {
                $evidenceRows++;
            }
            if (($signature['leadingCodeEvidence'] ?? 0) >= 1) {
                $leadingEvidenceRows++;
            }
            if ($signature['pitch'] !== null) {
                $pitches[] = $signature['pitch'];
            }
            $xStarts[] = (float) $signature['x1'];
            $fontSizes[] = max(1.0, (float) $signature['fontSize']);
        }
        if (count($pitches) !== $count) {
            return false;
        }

        $medianPitch = $this->median($pitches);
        $stablePitchRows = 0;
        foreach ($pitches as $pitch) {
            if (abs($pitch - $medianPitch) <= max(0.4, $medianPitch * 0.14)) {
                $stablePitchRows++;
            }
        }

        $minimumEvidenceRows = $count < 6
            ? 2
            : max(3, (int) ceil($count * 0.50));
        $minimumEvidenceScore = $count < 6
            ? 4
            : max(4, (int) ceil($count * 0.35));

        if ($count < 6) {
            $medianFontSize = max(1.0, $this->median($fontSizes));
            $xSpan = max($xStarts) - min($xStarts);
            if ($leadingEvidenceRows < 2 || $xSpan > max(48.0, $medianFontSize * 8.0)) {
                return false;
            }
        }

        return $stablePitchRows / $count >= 0.80
            && $evidenceRows >= $minimumEvidenceRows
            && $evidenceScore >= $minimumEvidenceScore;
    }

    private function positionedCodeSyntaxEvidence(string $line): int
    {
        $line = trim($line);
        if ($line === '') {
            return 0;
        }

        $score = 0;
        if (preg_match('~(?:^|\s)(?://|/\*|\*/|#(?:include|define|if|else|endif)\b)~u', $line) === 1) {
            $score += 2;
        }
        if (preg_match('/(?::=|===?|!==?|<=|>=|=>|->|\+\+|--|&&|\|\|)/u', $line) === 1) {
            $score += 2;
        }
        if (preg_match('/[{};]|\[[^\]]*\]/u', $line) === 1) {
            $score++;
        }
        if (preg_match('/^[A-Za-z_.$][A-Za-z0-9_.$-]*:\s*(?:(?:\/\/|#).*)?$/u', $line) === 1) {
            $score += 2;
        }
        if (preg_match('/[A-Za-z_.$][A-Za-z0-9_.$-]*\s*\([^)]*\)/u', $line) === 1
            && preg_match('/[.!?]\s*$/u', $line) !== 1) {
            $score++;
        }
        return $score;
    }

    /**
     * @param array{center: float, runs: list<array<string, mixed>>} $row
     */
    private function positionedCodeLineText(array $row, float $minimumX, float $pitch): string
    {
        $pitch = max(0.5, $pitch);
        $line = '';
        foreach ($row['runs'] as $run) {
            $text = $this->positionedCodeTextWithGeometryOffsets($run);
            if ($text === '') {
                continue;
            }
            $startX = (float) ($run['textX1'] ?? $run['x1'] ?? $minimumX);
            $targetColumn = max(0, (int) round(($startX - $minimumX) / $pitch));
            $currentColumn = $this->length($line);
            if ($line === '') {
                $line = str_repeat(' ', $targetColumn);
            } else {
                $paddingColumns = max(1, $targetColumn - $currentColumn);
                // Code runs are trimmed before their grid positions are
                // reconstructed. A reported source/layout boundary is an
                // omitted separator in addition to any measured blank grid
                // cells, so retain it locally rather than inferring anything
                // from the text in either column.
                if (($run['startsWithWhitespace'] ?? false) === true
                    || (($run['hasWordBoundaryBefore'] ?? false) === true
                        && ($run['wordBoundaryBefore'] ?? false) === true)) {
                    $paddingColumns++;
                }
                $line .= str_repeat(' ', $paddingColumns);
            }
            $line .= $text;
        }

        return rtrim($line);
    }

    /** @param array<string, mixed> $run */
    private function positionedCodeTextWithGeometryOffsets(array $run): string
    {
        $text = trim((string) ($run['text'] ?? ''));
        $offsets = is_array($run['codeGeometryBoundaryOffsets'] ?? null)
            ? $run['codeGeometryBoundaryOffsets']
            : [];
        if ($text === '' || $offsets === []) {
            return $text;
        }

        $characters = preg_split('//u', $text, -1, PREG_SPLIT_NO_EMPTY);
        if (!is_array($characters)) {
            return $text;
        }
        $result = '';
        $compactOffset = 0;
        foreach ($characters as $character) {
            if (preg_match('/^\s$/u', $character) === 1) {
                if ($result !== '' && !str_ends_with($result, ' ')) {
                    $result .= ' ';
                }
                continue;
            }
            if (isset($offsets[$compactOffset]) && $result !== '' && !str_ends_with($result, ' ')) {
                $result .= ' ';
            }
            $result .= $character;
            $compactOffset++;
        }

        return trim($result);
    }

    /**
     * @param array{page: int, text: string, x1: float, y1: float, x2: float, y2: float, textX1: float, textY1: float, textX2: float, textY2: float, fontSize: float} $left
     * @param array{page: int, text: string, x1: float, y1: float, x2: float, y2: float, textX1: float, textY1: float, textX2: float, textY2: float, fontSize: float} $right
     */
    private function positionedProseRunsLookLikeLineContinuation(array $left, array $right, float $gap, float $pageWidth): bool
    {
        if ($pageWidth > 0.0 && (abs($gap) > $pageWidth * 0.45)) {
            return false;
        }
        if (($left['endsWithWhitespace'] ?? false) || ($right['startsWithWhitespace'] ?? false)) {
            return false;
        }
        // The extractor records whether the actual positioned transition was
        // a word boundary. Never infer a continuation from letter case or
        // fragment length: ordinary adjacent letter fragments can represent
        // either one word or two words.
        if (($right['hasWordBoundaryBefore'] ?? false) !== true
            || ($right['wordBoundaryBefore'] ?? false) === true) {
            return false;
        }

        $fontSize = max($left['fontSize'], $right['fontSize'], 1.0);
        $maxContinuationGap = max($fontSize * 3.0, $pageWidth > 0.0 ? $pageWidth * 0.45 : 24.0);

        return $gap <= $maxContinuationGap;
    }

    /**
     * Preserve an aligned code/comment column boundary until the listing
     * classifier has enough rows to decide that it is code. This intentionally
     * uses only the two adjacent physical runs: source adjacency, a shared
     * character pitch, a grid-aligned gap, and programming punctuation. It
     * does not depend on the spelling, case, or length of ordinary words.
     *
     * @param array<string, mixed> $left
     * @param array<string, mixed> $right
     */
    private function positionedProseRunsSpanCodeColumns(array $left, array $right, float $gap, float $pageWidth): bool
    {
        if ($gap <= 0.0
            || (int) ($left['page'] ?? 1) !== (int) ($right['page'] ?? 1)
            || !isset($left['lastOrder'], $right['order'])) {
            return false;
        }

        $sourceGap = (int) $right['order'] - (int) $left['lastOrder'];
        if ($sourceGap !== 1 || ($pageWidth > 0.0 && $gap > $pageWidth * 0.25)) {
            return false;
        }

        $leftPitch = $this->positionedRunCharacterPitch($left);
        $rightPitch = $this->positionedRunCharacterPitch($right);
        if ($leftPitch === null || $rightPitch === null) {
            return false;
        }

        $pitch = max($leftPitch, $rightPitch, 0.1);
        if (abs($leftPitch - $rightPitch) > max(0.35, $pitch * 0.12)) {
            return false;
        }

        $columns = $gap / $pitch;
        if ($columns < 1.5 || $columns > 24.0 || abs($columns - round($columns)) > 0.25) {
            return false;
        }

        return max(
            $this->positionedCodeSyntaxEvidence((string) ($left['text'] ?? '')),
            $this->positionedCodeSyntaxEvidence((string) ($right['text'] ?? '')),
            $this->positionedCodeSyntaxEvidence(
                trim((string) ($left['text'] ?? '')) . ' ' . trim((string) ($right['text'] ?? ''))
            )
        ) >= 2;
    }

    /**
     * @param array<string, mixed> $run
     */
    private function positionedRunCharacterPitch(array $run): ?float
    {
        $text = trim((string) ($run['text'] ?? ''));
        $characters = $this->length($text);
        $start = $this->numericValue($run['textX1'] ?? $run['x1'] ?? null);
        $end = $this->numericValue($run['textX2'] ?? $run['x2'] ?? null);
        if ($characters < 2 || $start === null || $end === null) {
            return null;
        }

        $width = abs($end - $start);

        return $width > 0.0 ? $width / $characters : null;
    }

    /**
     * @param list<array{center: float, runs: list<array{page: int, text: string, x1: float, y1: float, x2: float, y2: float, textX1: float, textY1: float, textX2: float, textY2: float, fontSize: float}>}> $rows
     * @return list<array{center: float, runs: list<array{page: int, text: string, x1: float, y1: float, x2: float, y2: float, textX1: float, textY1: float, textX2: float, textY2: float, fontSize: float}>}>
     */
    private function splitPositionedRowsIntoProseFragments(array $rows): array
    {
        $fragments = [];
        foreach ($rows as $row) {
            if (count($row['runs']) <= 1 || ($row['code'] ?? false) === true) {
                $fragments[] = $row;
                continue;
            }

            foreach ($row['runs'] as $run) {
                $fragments[] = [
                    'center' => $row['center'],
                    'runs' => [$run],
                    'visualRtlOrder' => ($row['visualRtlOrder'] ?? false) === true,
                    'visualRtlProtectedClusters' => is_array($row['visualRtlProtectedClusters'] ?? null)
                        ? $row['visualRtlProtectedClusters']
                        : [],
                ];
            }
        }

        usort($fragments, static fn (array $left, array $right): int => ($right['center'] <=> $left['center']) ?: ($left['runs'][0]['x1'] <=> $right['runs'][0]['x1']));

        return $fragments;
    }

    /**
     * @param list<array{center: float, runs: list<array{page: int, text: string, x1: float, y1: float, x2: float, y2: float, textX1: float, textY1: float, textX2: float, textY2: float, fontSize: float}>}> $rows
     * @return list<array{center: float, runs: list<array{page: int, text: string, x1: float, y1: float, x2: float, y2: float, textX1: float, textY1: float, textX2: float, textY2: float, fontSize: float}>}>
     */
    private function orderPositionedProseRows(array $rows, float $medianFontSize): array
    {
        if (count($rows) < 4) {
            return $rows;
        }

        $pageBounds = $this->positionedRowsBounds($rows);
        $pageWidth = max(0.0, $pageBounds['x2'] - $pageBounds['x1']);
        if ($pageWidth < max(120.0, $medianFontSize * 12.0)) {
            return $rows;
        }

        $ordered = [];
        $band = [];
        $flushBand = function () use (&$ordered, &$band, $pageBounds, $medianFontSize): void {
            if ($band === []) {
                return;
            }
            foreach ($this->orderPositionedProseBand($band, $pageBounds, $medianFontSize) as $row) {
                $ordered[] = $row;
            }
            $band = [];
        };

        foreach ($rows as $row) {
            if ($this->positionedProseRowIsFullWidth($row, $pageBounds, $medianFontSize)) {
                $flushBand();
                $ordered[] = $row;
                continue;
            }
            $band[] = $row;
        }
        $flushBand();

        return $ordered;
    }

    /**
     * @param list<array{center: float, runs: list<array{page: int, text: string, x1: float, y1: float, x2: float, y2: float, textX1: float, textY1: float, textX2: float, textY2: float, fontSize: float}>}> $rows
     * @param array{x1: float, y1: float, x2: float, y2: float} $pageBounds
     * @return list<array{center: float, runs: list<array{page: int, text: string, x1: float, y1: float, x2: float, y2: float, textX1: float, textY1: float, textX2: float, textY2: float, fontSize: float}>}>
     */
    private function orderPositionedProseBand(array $rows, array $pageBounds, float $medianFontSize): array
    {
        $columns = $this->splitPositionedProseBandIntoColumns($rows, $pageBounds, $medianFontSize);
        if ($columns === null) {
            return $rows;
        }

        $left = $this->orderPositionedProseBand(
            $columns['left'],
            $this->positionedRowsBounds($columns['left']),
            $medianFontSize
        );
        $right = $this->orderPositionedProseBand(
            $columns['right'],
            $this->positionedRowsBounds($columns['right']),
            $medianFontSize
        );

        return array_merge($left, $right);
    }

    /**
     * @param list<array{center: float, runs: list<array{page: int, text: string, x1: float, y1: float, x2: float, y2: float, textX1: float, textY1: float, textX2: float, textY2: float, fontSize: float}>}> $rows
     * @param array{x1: float, y1: float, x2: float, y2: float} $pageBounds
     * @return array{left: list<array{center: float, runs: list<array{page: int, text: string, x1: float, y1: float, x2: float, y2: float, textX1: float, textY1: float, textX2: float, textY2: float, fontSize: float}>}>, right: list<array{center: float, runs: list<array{page: int, text: string, x1: float, y1: float, x2: float, y2: float, textX1: float, textY1: float, textX2: float, textY2: float, fontSize: float}>}>}|null
     */
    private function splitPositionedProseBandIntoColumns(array $rows, array $pageBounds, float $medianFontSize): ?array
    {
        if (count($rows) < 4) {
            return null;
        }

        $pageMidpoint = ($pageBounds['x1'] + $pageBounds['x2']) / 2.0;
        foreach ($this->positionedProseColumnCutCandidates($rows, $pageMidpoint, $medianFontSize) as $candidate) {
            $cut = $candidate['cut'];
            $left = [];
            $right = [];
            $leftStarts = [];
            $rightStarts = [];
            $leftEnds = [];
            foreach ($rows as $row) {
                $bounds = $this->positionedProseRowBounds($row);
                if ($bounds['x1'] < $cut) {
                    $left[] = $row;
                    $leftStarts[] = $bounds['x1'];
                    $leftEnds[] = $bounds['x2'];
                    continue;
                }

                $right[] = $row;
                $rightStarts[] = $bounds['x1'];
            }

            if (count($left) < 2 || count($right) < 2) {
                continue;
            }
            if ($candidate['gap'] > 0.0 && (!$this->positionedProseColumnHasVerticalRhythm($left, $medianFontSize)
                || !$this->positionedProseColumnHasVerticalRhythm($right, $medianFontSize)
                || !$this->positionedProseColumnHasStableStart($left, $medianFontSize)
                || !$this->positionedProseColumnHasStableStart($right, $medianFontSize))) {
                continue;
            }

            $startGap = $this->median($rightStarts) - $this->median($leftStarts);
            if ($startGap < max(80.0, $medianFontSize * 8.0)) {
                continue;
            }

            $gutter = $this->median($rightStarts) - $this->median($leftEnds);
            if ($gutter < -max(24.0, $medianFontSize * 2.0)) {
                continue;
            }

            return ['left' => $left, 'right' => $right];
        }

        return null;
    }

    /**
     * @param list<array{center: float, runs: list<array{page: int, text: string, x1: float, y1: float, x2: float, y2: float, textX1: float, textY1: float, textX2: float, textY2: float, fontSize: float}>}> $rows
     */
    private function positionedProseColumnHasVerticalRhythm(array $rows, float $medianFontSize): bool
    {
        if (count($rows) < 2) {
            return false;
        }

        usort($rows, static fn (array $left, array $right): int => $right['center'] <=> $left['center']);
        $nearbyPairs = 0;
        $pairs = count($rows) - 1;
        foreach ($rows as $index => $row) {
            if (!isset($rows[$index + 1])) {
                break;
            }
            $upper = $this->positionedProseRowBounds($row);
            $lower = $this->positionedProseRowBounds($rows[$index + 1]);
            $fontSize = max(
                $this->positionedRowMaxFontSize($row),
                $this->positionedRowMaxFontSize($rows[$index + 1]),
                $medianFontSize,
                1.0
            );
            $gap = $upper['y1'] - $lower['y2'];
            if ($gap >= -$fontSize * 0.5 && $gap <= $fontSize * 2.4) {
                $nearbyPairs++;
            }
        }

        return $nearbyPairs >= max(1, (int) ceil($pairs * 0.50));
    }

    /**
     * @param list<array{center: float, runs: list<array{page: int, text: string, x1: float, y1: float, x2: float, y2: float, textX1: float, textY1: float, textX2: float, textY2: float, fontSize: float}>}> $rows
     */
    private function positionedProseColumnHasStableStart(array $rows, float $medianFontSize): bool
    {
        if (count($rows) < 2) {
            return false;
        }

        $starts = array_map(
            fn (array $row): float => $this->positionedProseRowBounds($row)['x1'],
            $rows
        );
        $medianStart = $this->median($starts);
        $tolerance = max(12.0, $medianFontSize * 1.5);
        $stableStarts = 0;
        foreach ($starts as $start) {
            if (abs($start - $medianStart) <= $tolerance) {
                $stableStarts++;
            }
        }

        return $stableStarts / count($starts) >= 0.75;
    }

    /**
     * A page midpoint catches conventional two-column papers but misses
     * label-plus-body layouts whose two columns both sit on one half of a
     * brochure page. Repeated left edges expose their gutter without relying
     * on language or document-specific content.
     *
     * @param list<array{center: float, runs: list<array{page: int, text: string, x1: float, y1: float, x2: float, y2: float, textX1: float, textY1: float, textX2: float, textY2: float, fontSize: float}>}> $rows
     * @return list<array{cut: float, gap: float}>
     */
    private function positionedProseColumnCutCandidates(array $rows, float $pageMidpoint, float $medianFontSize): array
    {
        $starts = [];
        foreach ($rows as $row) {
            $starts[] = $this->positionedProseRowBounds($row)['x1'];
        }
        sort($starts, SORT_NUMERIC);

        $minimumGap = max(80.0, $medianFontSize * 8.0);
        $candidates = [['cut' => $pageMidpoint, 'gap' => 0.0]];
        for ($index = 0, $count = count($starts) - 1; $index < $count; $index++) {
            $gap = $starts[$index + 1] - $starts[$index];
            if ($gap < $minimumGap) {
                continue;
            }
            $candidates[] = [
                'cut' => ($starts[$index] + $starts[$index + 1]) / 2.0,
                'gap' => $gap,
            ];
        }

        usort($candidates, static fn (array $left, array $right): int => $right['gap'] <=> $left['gap']);
        $cuts = [];
        foreach ($candidates as $candidate) {
            $cut = (float) $candidate['cut'];
            foreach ($cuts as $existing) {
                if (abs($existing['cut'] - $cut) < 1.0) {
                    continue 2;
                }
            }
            $cuts[] = ['cut' => $cut, 'gap' => (float) $candidate['gap']];
        }

        return $cuts;
    }

    /**
     * @param array{center: float, runs: list<array{page: int, text: string, x1: float, y1: float, x2: float, y2: float, textX1: float, textY1: float, textX2: float, textY2: float, fontSize: float}>} $row
     * @param array{x1: float, y1: float, x2: float, y2: float} $pageBounds
     */
    private function positionedProseRowIsFullWidth(array $row, array $pageBounds, float $medianFontSize): bool
    {
        if (($row['code'] ?? false) === true) {
            return true;
        }

        $bounds = $this->positionedProseRowBounds($row);
        $pageWidth = max(0.0, $pageBounds['x2'] - $pageBounds['x1']);
        if ($pageWidth <= 0.0) {
            return false;
        }

        $rowWidth = max(0.0, $bounds['x2'] - $bounds['x1']);
        if ($rowWidth >= $pageWidth * 0.72) {
            return true;
        }

        $pageCenter = ($pageBounds['x1'] + $pageBounds['x2']) / 2.0;
        $rowCenter = ($bounds['x1'] + $bounds['x2']) / 2.0;
        $text = $this->positionedRowText($row);

        return $this->positionedRowLooksStandaloneHeading($row, $medianFontSize)
            && abs($rowCenter - $pageCenter) <= max(36.0, $medianFontSize * 4.0)
            && $this->length($text) <= 100;
    }

    /**
     * @param array{center: float, runs: list<array{page: int, text: string, x1: float, y1: float, x2: float, y2: float, textX1: float, textY1: float, textX2: float, textY2: float, fontSize: float}>} $row
     * @return array{x1: float, y1: float, x2: float, y2: float}
     */
    private function positionedProseRowBounds(array $row): array
    {
        $bounds = ['x1' => INF, 'y1' => INF, 'x2' => -INF, 'y2' => -INF];
        foreach ($row['runs'] as $run) {
            $bounds['x1'] = min($bounds['x1'], $run['x1'], $run['textX1']);
            $bounds['y1'] = min($bounds['y1'], $run['y1'], $run['textY1']);
            $bounds['x2'] = max($bounds['x2'], $run['x2'], $run['textX2']);
            $bounds['y2'] = max($bounds['y2'], $run['y2'], $run['textY2']);
        }

        return is_finite($bounds['x1']) && is_finite($bounds['x2']) && is_finite($bounds['y1']) && is_finite($bounds['y2'])
            ? $bounds
            : ['x1' => 0.0, 'y1' => $row['center'], 'x2' => 0.0, 'y2' => $row['center']];
    }

    /**
     * @param list<string> $positionedLines
     * @param list<string> $textLines
     * @param list<array<string, mixed>> $positionedRuns
     */
    private function positionedProseLinesLookUsable(
        array $positionedLines,
        array $textLines,
        array $positionedRuns = [],
        ?bool $positionedRunsAreGlyphFragments = null
    ): bool
    {
        if (count($positionedLines) < 2) {
            return false;
        }
        if ($textLines === []) {
            return true;
        }

        $textTokens = $this->significantTextTokens(implode(' ', array_slice($textLines, 0, 500)));
        if (count($textTokens) < 4) {
            return true;
        }

        $textSpacingDamage = $this->genericSpacingDamageScore($textLines);
        $positionedSpacingDamage = $this->genericSpacingDamageScore($positionedLines);
        if ($positionedSpacingDamage >= $textSpacingDamage + 2) {
            return false;
        }
        if (
            ($positionedRunsAreGlyphFragments
                ?? $this->positionedRunsArePredominantlyGlyphFragments($positionedRuns, count($textLines)))
            && $textSpacingDamage <= $positionedSpacingDamage + 1
        ) {
            return false;
        }

        $positionedTokens = $this->significantTextTokenSet(
            implode(' ', array_slice($positionedLines, 0, 500))
        );
        if ($positionedTokens === []) {
            return false;
        }

        $matched = 0;
        foreach ($textTokens as $token) {
            if (isset($positionedTokens[$token])) {
                $matched++;
            }
        }

        return $matched / count($textTokens) >= 0.55;
    }

    /**
     * PDFs that paint nearly every glyph as an individual run can expose
     * imprecise placement order even when the ordinary text layer is coherent.
     * Keep geometry for actual words and phrases; otherwise prefer text order.
     *
     * @param list<array<string, mixed>> $runs
     */
    private function positionedRunsArePredominantlyGlyphFragments(array $runs, int $textLineCount): bool
    {
        if (count($runs) < 128 || $textLineCount < 24) {
            return false;
        }

        $runCount = 0;
        $singleGlyphRuns = 0;
        $shortRuns = 0;
        $characters = 0;
        foreach ($runs as $run) {
            $text = trim($this->normalizePdfTextEncoding((string) ($run['text'] ?? '')));
            if ($text === '') {
                continue;
            }

            $length = $this->length($text);
            $runCount++;
            $characters += $length;
            if ($length === 1) {
                $singleGlyphRuns++;
            }
            if ($length <= 2) {
                $shortRuns++;
            }
        }
        if ($runCount < 128 || $runCount / $textLineCount < 6.0) {
            return false;
        }

        return $singleGlyphRuns / $runCount >= 0.70
            && $shortRuns / $runCount >= 0.80
            && $characters / $runCount <= 1.75;
    }

    /**
     * @param list<string> $lines
     */
    private function genericSpacingDamageScore(array $lines): int
    {
        $score = 0;
        foreach (array_slice($lines, 0, 500) as $line) {
            if (preg_match_all('/\p{Ll}\p{Lu}|\p{L}\d|\d\p{L}|[,:;!?]\S|(?<!\d)\.[\p{Lu}]/u', $line, $matches) !== false) {
                $score += count($matches[0]);
            }
            if (preg_match_all('/\b[\p{L}]{28,}\b/u', $line, $matches) !== false) {
                $score += count($matches[0]);
            }
        }

        return $score;
    }

    /**
     * @param list<string> $lines
     * @param list<array{text: string, page: int, x1: float, y1: float, x2: float, y2: float, fontSize: float}> $lineLayouts
     * @param array<int,string>|null $outputPageProjections Exact significant
     *        output attributed to each conservative source page, or null when
     *        the post-pipeline records cannot prove a page-local projection.
     * @param array<int,array<string,mixed>>|null $outputLineSpans
     * @return list<string>
     */
    private function repairProseTextLines(
        array $lines,
        bool $repairGluedText = true,
        array $lineLayouts = [],
        ?array &$outputPageProjections = null,
        ?array &$outputLineSpans = null
    ): array
    {
        $collectOutputPageProjections = func_num_args() >= 4;
        $collectOutputLineSpans = func_num_args() >= 5;
        $outputPageProjections = null;
        $outputLineSpans = [];
        $cleaned = [];
        $pendingListMarker = null;
        $decorativeBraceEvidence = $lineLayouts === []
            ? []
            : $this->pdfDecorativeBracePairEvidence($lineLayouts);
        foreach ($lines as $index => $line) {
            $layout = $lineLayouts[$index] ?? null;
            $recordOutputPage = is_array($layout) && (int) ($layout['page'] ?? 0) > 0
                ? (int) $layout['page']
                : null;
            $sourceId = is_array($layout) && is_string($layout['id'] ?? null)
                ? $layout['id']
                : '';
            $chartCipherLayoutIsProven =
                $this->sourcePdfChartCipherLayoutIsProvenArtifact($layout, $line);
            if ($chartCipherLayoutIsProven) {
                continue;
            }
            if (is_array($layout)
                && (isset($decorativeBraceEvidence[$sourceId])
                    || is_array($layout['sourcePdfDecorativeBraceEvidence'] ?? null)
                    || is_array(
                        $layout['sourcePdfDuplicateTerminalPeriodArtifactEvidence'] ?? null
                    )
                    || (($layout['sourcePdfCrossLaneDisplayArtifactRole'] ?? null)
                        === 'whole-display-artifact'
                        && is_array(
                            $layout['sourcePdfCrossLaneDisplayArtifactEvidence'] ?? null
                        )))) {
                continue;
            }
            if (str_starts_with($line, self::PDF_CODE_BLOCK_PREFIX)) {
                $code = rtrim(substr($line, strlen(self::PDF_CODE_BLOCK_PREFIX)));
                if ($code !== '') {
                    $cleaned[] = [
                        'text' => $code,
                        'layout' => [
                            'code' => true,
                            'codeText' => $code,
                        ],
                        'sourcePdfOutputPage' => $recordOutputPage,
                    ];
                }
                continue;
            }
            $chunks = $this->splitPdfTextLineVisualChunks($line);
            $chunkLayout = count($chunks) === 1 ? $layout : null;
            foreach ($chunks as $chunk) {
                $chunkOutputPage = $recordOutputPage;
                $standaloneWrappedWordHyphen = trim($chunk) === '-'
                    && is_array($chunkLayout['sourcePdfStandaloneWrappedWordHyphenEvidence'] ?? null);
                $inlineStandaloneMarker = is_array($chunkLayout)
                    && $this->sourcePdfHasExactInlineStandaloneMarkerEvidence($chunkLayout);
                if ($this->lineIsStandalonePdfListMarker($chunk)
                    && !$standaloneWrappedWordHyphen
                    && !$inlineStandaloneMarker) {
                    $pendingListMarker = [
                        'text' => trim($chunk),
                        'page' => $recordOutputPage,
                    ];
                    continue;
                }
                if ($pendingListMarker !== null) {
                    $chunk = $pendingListMarker['text'] . ' ' . ltrim($chunk);
                    if ($pendingListMarker['page'] !== null
                        && $chunkOutputPage !== null
                        && $pendingListMarker['page'] !== $chunkOutputPage) {
                        $chunkOutputPage = null;
                    }
                    $pendingListMarker = null;
                }
                $chunk = $this->repairPdfInterGlyphSpacingCandidate($chunk, $chunkLayout);
                // A punctuation-only source record can be a closing brace,
                // operator, formula delimiter, or other meaningful syntax.
                // Geometry does not prove that it is disposable noise, so
                // keep it until a source-occurrence disposition can identify
                // an actual replacement or suppression.
                foreach ($this->splitPdfPositionedHeadingLead($chunk, $chunkLayout) as $part) {
                    $part['sourcePdfOutputPage'] = $chunkOutputPage;
                    $cleaned[] = $part;
                }
            }
        }
        $frontMatterProcessor = new PdfFrontMatterSemanticProcessor();
        $inlineMarkerProcessor = new PdfInlineMarkerSemanticProcessor($this->sourceSha256);
        $formulaProcessor = new PdfFormulaSemanticProcessor();
        // Classify structure before taking the recovery snapshot. Front-matter
        // classification can reorder records, inline markers can merge them,
        // and recurring furniture is an evidenced suppression. The snapshot
        // therefore describes the exact sequence that the destructive
        // heuristic stages actually receive, including its already-proved
        // heading and layout-label annotations.
        $preparationPipeline = new PdfSemanticRecordPipeline([
            new PdfCallableSemanticRecordProcessor(
                'flattened-numbered-code-listings',
                $this->reconstructFlattenedPdfNumberedCodeListingRecords(...)
            ),
            $frontMatterProcessor,
            new PdfCallableSemanticRecordProcessor(
                'front-matter-geometry-completion',
                $this->completePdfFrontMatterGeometryRecords(...)
            ),
            new PdfCallableSemanticRecordProcessor(
                'front-matter-final-order',
                $frontMatterProcessor->process(...)
            ),
            new PdfCallableSemanticRecordProcessor(
                'affiliation-email-delimiters',
                $this->repairPdfAffiliationEmailDelimiterRecords(...)
            ),
            new PdfCallableSemanticRecordProcessor(
                'exact-brace-delimited-lists',
                $this->foldExactPdfBraceDelimitedListRecords(...)
            ),
            $inlineMarkerProcessor,
            new PdfCallableSemanticRecordProcessor('repeated-page-furniture', $this->removeRepeatedPdfPageNumberRecords(...)),
            new PdfCallableSemanticRecordProcessor('display-headings', $this->markPdfDisplayHeadingRecords(...)),
            // Geometry-proven form/callout labels must gain their semantic
            // prefix before low-coherence fragment filters run. Otherwise
            // those filters can discard the exact editable labels that the
            // layout evidence was gathered to preserve.
            new PdfCallableSemanticRecordProcessor('layout-labels', $this->markPdfLayoutLabelRecords(...)),
        ]);
        // Each semantic phase owns the complete record graph only until the
        // next phase accepts it. Explicit ownership transfer prevents PHP's
        // function-scope locals from retaining every proof-enriched snapshot
        // through the final grouping pass.
        $semanticRecords = $cleaned;
        unset($cleaned);
        $preparationResult = $preparationPipeline->runOwned($semanticRecords);
        $pipelineTrace = $preparationResult['trace'];
        $semanticRecords = $preparationResult['records'];
        unset($preparationResult, $preparationPipeline);
        // Exact-geometry fallback flags are selection-time controls, not
        // semantic roles. Remove them before low-coherence filtering so they
        // cannot shield ordinary source rows or force one paragraph per row.
        // Independently proved front matter and inline markers retain their
        // semantic protection.
        $normalizationPipeline = new PdfSemanticRecordPipeline([
            new PdfCallableSemanticRecordProcessor(
                'exact-source-selection-normalization',
                $this->normalizePdfExactSourceSemanticRecoveryRecords(...)
            ),
        ]);
        $normalizationResult = $normalizationPipeline->runOwned($semanticRecords);
        $pipelineTrace = array_merge($pipelineTrace, $normalizationResult['trace']);
        $semanticRecords = $normalizationResult['records'];
        unset($normalizationResult, $normalizationPipeline);
        $exactSourceRecoverySnapshot = $this->pdfExactSourceSemanticRecoverySnapshot($semanticRecords);
        $destructivePipeline = new PdfSemanticRecordPipeline([
            new PdfCallableSemanticRecordProcessor('reference-confidence', $this->removeLowConfidencePdfReferenceEntries(...)),
            new PdfCallableSemanticRecordProcessor('map-regions', $this->removeLowCoherencePdfMapRegions(...)),
            new PdfCallableSemanticRecordProcessor('floating-regions', $this->removeLowCoherencePdfFloatingRegions(...)),
            new PdfCallableSemanticRecordProcessor('diagram-label-regions', $this->removeLowCoherencePdfDiagramLabelRegions(...)),
            new PdfCallableSemanticRecordProcessor('structured-floating-fragments', $this->removeLowCoherencePdfStructuredFloatingFragments(...)),
            new PdfCallableSemanticRecordProcessor('orphaned-source-continuations', $this->removeSourcePdfOrphanedInferredContinuations(...)),
            new PdfCallableSemanticRecordProcessor('unpositioned-label-regions', $this->removeLowCoherencePdfUnpositionedLabelRegions(...)),
            new PdfCallableSemanticRecordProcessor('complex-column-segments', $this->removeIncompletePdfComplexColumnSegments(...)),
            new PdfCallableSemanticRecordProcessor('interrupted-flow-segments', $this->removeIncompletePdfInterruptedFlowSegments(...)),
            new PdfCallableSemanticRecordProcessor('interrupted-sentence-tails', $this->trimIncompletePdfInterruptedSentenceTails(...)),
            new PdfCallableSemanticRecordProcessor('supplemental-segment-tails', $this->trimIncompletePdfSupplementalSegmentTails(...)),
            new PdfCallableSemanticRecordProcessor('unstructured-fragments', $this->trimIncompletePdfUnstructuredFragments(...)),
            new PdfCallableSemanticRecordProcessor('orphaned-page-openings', $this->removeOrphanedPdfPageOpeningFragments(...)),
            new PdfCallableSemanticRecordProcessor('isolated-diagram-flows', $this->removeIsolatedPdfDiagramFlowFragments(...)),
        ]);
        $destructiveResult = $destructivePipeline->runOwned($semanticRecords);
        $pipelineTrace = array_merge($pipelineTrace, $destructiveResult['trace']);
        $semanticRecords = $destructiveResult['records'];
        unset($destructiveResult, $destructivePipeline);
        $recoveryPipeline = new PdfSemanticRecordPipeline([
            new PdfCallableSemanticRecordProcessor(
                'exact-source-semantic-recovery',
                fn (array $records): array => $this->restoreDroppedExactSourceSemanticRecords(
                    $records,
                    $exactSourceRecoverySnapshot
                )
            ),
        ]);
        $recoveryResult = $recoveryPipeline->runOwned($semanticRecords);
        $pipelineTrace = array_merge($pipelineTrace, $recoveryResult['trace']);
        $semanticRecords = $recoveryResult['records'];
        unset($recoveryResult, $recoveryPipeline, $exactSourceRecoverySnapshot);
        // Formula grouping runs exactly once after recovery. It can merge
        // several source atoms into one semantic record without making the
        // recovery guard mistake those consumed atoms for dropped text.
        $formulaPipeline = new PdfSemanticRecordPipeline([$formulaProcessor]);
        $formulaResult = $formulaPipeline->runOwned($semanticRecords);
        $pipelineTrace = array_merge($pipelineTrace, $formulaResult['trace']);
        $semanticRecords = $formulaResult['records'];
        unset($formulaResult, $formulaPipeline);
        // Form tails are grouped only after every destructive pass and
        // exact-source recovery have finished. This pass is character
        // preserving and requires local occurrence/layout proof; it must never
        // become a generic short-line paragraph heuristic.
        $groupingPipeline = new PdfSemanticRecordPipeline([
            new PdfCallableSemanticRecordProcessor(
                'proven-form-tail-groups',
                $this->coalesceProvenPdfFormTailRecords(...)
            ),
        ]);
        $groupingResult = $groupingPipeline->runOwned($semanticRecords);
        $pipelineTrace = array_merge($pipelineTrace, $groupingResult['trace']);
        $cleaned = $groupingResult['records'];
        unset($semanticRecords, $groupingResult, $groupingPipeline);
        $this->frontMatterRecordCount = max($this->frontMatterRecordCount, $frontMatterProcessor->recordCount());
        $this->inlineMarkerRecordCount = max($this->inlineMarkerRecordCount, $inlineMarkerProcessor->markerCount());
        $this->formulaRegionCount = max($this->formulaRegionCount, $formulaProcessor->regionCount());
        $this->semanticPipelineTrace[] = [
            'run' => count($this->semanticPipelineTrace) + 1,
            'stages' => $pipelineTrace,
        ];
        unset($pipelineTrace);
        // Revalidate and restore any exact two-endpoint continuation which a
        // recovery stage displaced across unrelated page furniture.
        $cleaned = $this->restoreProvenPdfCrossPanelContinuationRecords($cleaned);
        // Infer line-oriented roles only after the conservative fragment
        // filters have finished. Otherwise a role marker can accidentally
        // turn extraction noise into content merely by making it look
        // structurally special.
        $cleaned = $this->markPdfLineOrientedRegionRecords($cleaned);
        // Credit/footer evidence is intentionally derived only after
        // destructive selection and exact-source recovery have fixed record
        // order. Stamping even a deferred semantic role before those stages
        // can change which cross-panel carrier is retained as the verified
        // continuation anchor.

        if ($collectOutputLineSpans) {
            $exactWholeSourceMergedLineSpans = [];
            $merged = $this->mergeRepairedPdfRecords(
                $cleaned,
                $exactWholeSourceMergedLineSpans
            );
            $retainedWholeSourceMergedLineSpans = [];
            $merged = $this->trimIncompletePdfMergedLinesBeforeStackedTables(
                $merged,
                $exactWholeSourceMergedLineSpans,
                $retainedWholeSourceMergedLineSpans
            );
            $finalWholeSourceMergedLineSpans = [];
            $repaired = $this->finalizedRepairedPdfLines(
                $merged,
                $repairGluedText,
                $retainedWholeSourceMergedLineSpans,
                $finalWholeSourceMergedLineSpans
            );
            $outputLineSpans = $finalWholeSourceMergedLineSpans;
        } else {
            $merged = $this->mergeRepairedPdfRecords($cleaned);
            $merged = $this->trimIncompletePdfMergedLinesBeforeStackedTables($merged);
            $repaired = $this->finalizedRepairedPdfLines($merged, $repairGluedText);
        }
        if ($collectOutputPageProjections) {
            $outputPageProjections = $this->pdfConservativeRepairedOutputPageProjections(
                $cleaned,
                $repairGluedText
            );
        }

        return $repaired;
    }

    /**
     * Recover a source listing whose PDF text layer flattened visually
     * separate, explicitly numbered rows into one line.  The row numbers
     * provide a strong local boundary proof: require a consecutive run from
     * one, several programming-language statement shapes, and balanced code
     * punctuation before interpreting whitespace as line breaks.
     *
     * The transformation changes whitespace only.  The exact source carrier
     * remains on the record, while codeText retains the visual row structure
     * used by the semantic code block.
     *
     * @param list<array{text:string,layout:array<string,mixed>|null}> $records
     * @return list<array{text:string,layout:array<string,mixed>|null}>
     */
    private function reconstructFlattenedPdfNumberedCodeListingRecords(array $records): array
    {
        foreach ($records as &$record) {
            $layout = is_array($record['layout'] ?? null) ? $record['layout'] : null;
            $text = trim((string) ($record['text'] ?? ''));
            if (($layout['code'] ?? false) === true) {
                continue;
            }
            $codeText = $this->flattenedPdfNumberedCodeListing($text);
            if ($codeText === null) {
                continue;
            }

            $layout ??= [];
            $layout['code'] = true;
            $layout['codeText'] = $codeText;
            $layout['sourcePdfProtectedSemanticContent'] = true;
            $record['layout'] = $layout;
        }
        unset($record);

        return $records;
    }

    /**
     * Restore the only syntactically valid delimiter between a brace-wrapped
     * affiliation mailbox list and an immediately adjacent DNS domain. This
     * shape is self-contained and unambiguous: braces delimit one or more
     * local parts, while the following dotted token supplies the domain.
     *
     * @param list<array{text:string,layout:array<string,mixed>|null}> $records
     * @return list<array{text:string,layout:array<string,mixed>|null}>
     */
    private function repairPdfAffiliationEmailDelimiterRecords(array $records): array
    {
        $braceRepairPages = [];
        foreach ($records as $recordIndex => &$record) {
            $text = (string) ($record['text'] ?? '');
            $repaired = preg_replace_callback(
                '/\{([\p{L}\p{N}._%+\-]+(?:\s*,\s*[\p{L}\p{N}._%+\-]+)*)\}([\p{L}\p{N}\-]+(?:\.[\p{L}\p{N}\-]+)+\b)/u',
                static function (array $match): string {
                    $localParts = preg_replace('/\s*,\s*/u', ', ', $match[1]) ?? $match[1];

                    return '{' . $localParts . '}@' . $match[2];
                },
                $text
            );
            if (!is_string($repaired) || $repaired === $text) {
                continue;
            }
            $layout = is_array($record['layout'] ?? null) ? $record['layout'] : [];
            $layout['sourcePdfSemanticEmailDelimiterRepair'] = [
                'version' => 1,
                'method' => 'brace-mailbox-list-adjacent-dns-domain',
                'sourceProjectionDigest' => hash('sha256', $this->pdfSourceOccurrenceComparableText($text)),
                'outputProjectionDigest' => hash('sha256', $this->pdfSourceOccurrenceComparableText($repaired)),
            ];
            $record['text'] = $repaired;
            $record['layout'] = $layout;
            $this->rememberPdfSemanticEmailDelimiterRepair(
                $record,
                $text,
                $repaired,
                $layout['sourcePdfSemanticEmailDelimiterRepair']
            );
            $page = max(1, (int) ($layout['page'] ?? 1));
            $braceRepairPages[$page][] = $recordIndex;
        }
        unset($record);

        if ($braceRepairPages === []) {
            return $records;
        }

        // A producer which omits the mailbox delimiter can also flatten
        // ordinary addresses into `localcs.example.edu`.  That spelling is
        // ambiguous in isolation, so recover it only from a complete local
        // proof: one unambiguous brace-mailbox repair above, at least two
        // aligned front-matter peers, author-derived local-part candidates,
        // and one shared leading DNS label across the peer rows.
        $authorLocalCandidatesByPage = [];
        foreach ($records as $recordIndex => $record) {
            $layout = is_array($record['layout'] ?? null) ? $record['layout'] : null;
            $text = trim((string) ($record['text'] ?? ''));
            if (($layout['sourcePdfFrontMatter'] ?? false) !== true
                || ($layout['sourcePdfFrontMatterRole'] ?? null) !== 'credits'
                || preg_match('/[,\x{2020}\x{2021}\x{2217}]/u', $text) !== 1
                || str_contains($text, '@')) {
                continue;
            }
            $page = max(1, (int) ($layout['page'] ?? 1));
            if (!isset($braceRepairPages[$page])) {
                continue;
            }
            $tokens = array_values(array_filter(
                $this->pdfLineWordTokens($text),
                static fn (string $token): bool => preg_match('/^[A-Za-z][A-Za-z0-9_-]{2,63}$/D', $token) === 1
            ));
            foreach ($tokens as $tokenIndex => $token) {
                $local = strtolower($token);
                $authorLocalCandidatesByPage[$page][$local][$recordIndex] = true;
                $next = $tokens[$tokenIndex + 1] ?? null;
                if (!is_string($next) || $next === '') {
                    continue;
                }
                $initial = strtolower(substr($next, 0, 1));
                if ($initial !== '') {
                    $authorLocalCandidatesByPage[$page][$local . $initial][$recordIndex] = true;
                }
            }
        }

        $candidateSplitsByPageAndDnsLabel = [];
        foreach ($records as $recordIndex => $record) {
            $layout = is_array($record['layout'] ?? null) ? $record['layout'] : null;
            $text = trim((string) ($record['text'] ?? ''));
            $page = max(1, (int) ($layout['page'] ?? 1));
            if (!isset($braceRepairPages[$page], $authorLocalCandidatesByPage[$page])
                || ($layout['sourcePdfFrontMatter'] ?? false) !== true
                || ($layout['sourcePdfFrontMatterRole'] ?? null) !== 'credits'
                || !$this->pdfLayoutHasGeometry($layout)
                || $text === ''
                || str_contains($text, '@')
                || preg_match('/\s/u', $text) === 1
                || preg_match('/^[A-Za-z0-9._%+\-]+(?:\.[A-Za-z0-9\-]+){2,}$/D', $text) !== 1) {
                continue;
            }
            $lower = strtolower($text);
            foreach ($authorLocalCandidatesByPage[$page] as $local => $originIndexes) {
                if (isset($originIndexes[$recordIndex])
                    || !str_starts_with($lower, $local)) {
                    continue;
                }
                $domain = substr($text, strlen($local));
                if (!is_string($domain)
                    || preg_match(
                        '/^(?<label>[A-Za-z][A-Za-z0-9\-]{1,14})(?:\.[A-Za-z0-9][A-Za-z0-9\-]{0,62}){2,}$/D',
                        $domain,
                        $domainMatch
                    ) !== 1) {
                    continue;
                }
                $dnsLabel = strtolower($domainMatch['label']);
                $candidateSplitsByPageAndDnsLabel[$page][$dnsLabel][$recordIndex][] = [
                    'local' => substr($text, 0, strlen($local)),
                    'domain' => $domain,
                    'authorOriginIndexes' => array_map('intval', array_keys($originIndexes)),
                ];
            }
        }

        foreach ($candidateSplitsByPageAndDnsLabel as $page => $groups) {
            foreach ($groups as $dnsLabel => $candidatesByRecordIndex) {
                if (count($candidatesByRecordIndex) < 2) {
                    continue;
                }
                $candidateIndexes = array_keys($candidatesByRecordIndex);
                $ambiguous = array_filter(
                    $candidatesByRecordIndex,
                    static fn (array $candidates): bool => count($candidates) !== 1
                );
                if ($ambiguous !== []) {
                    continue;
                }
                usort($candidateIndexes, fn (int $left, int $right): int =>
                    (int) ($records[$left]['layout']['sourceOrderStart'] ?? PHP_INT_MAX)
                        <=> (int) ($records[$right]['layout']['sourceOrderStart'] ?? PHP_INT_MAX)
                );
                $firstLayout = $records[$candidateIndexes[0]]['layout'];
                $fontSize = max(1.0, (float) $firstLayout['fontSize']);
                $previousOrder = null;
                $previousY = null;
                $proofPeers = [];
                foreach ($candidateIndexes as $candidateIndex) {
                    $layout = $records[$candidateIndex]['layout'];
                    $candidate = $candidatesByRecordIndex[$candidateIndex][0];
                    $order = (int) ($layout['sourceOrderStart'] ?? PHP_INT_MAX);
                    $y = (float) $layout['y1'];
                    if (abs((float) $layout['x1'] - (float) $firstLayout['x1']) > max(1.0, $fontSize * 0.20)
                        || abs((float) $layout['x2'] - (float) $firstLayout['x2']) > max(1.0, $fontSize * 0.20)
                        || abs((float) $layout['fontSize'] - $fontSize) > max(0.25, $fontSize * 0.04)
                        || ($previousOrder !== null && $order !== $previousOrder + 1)
                        || ($previousY !== null
                            && ($previousY - $y < $fontSize * 0.70
                                || $previousY - $y > $fontSize * 1.70))) {
                        $proofPeers = [];
                        break;
                    }
                    $proofPeers[] = [
                        'recordIndex' => $candidateIndex,
                        'sourceOrder' => $order,
                        'localDigest' => hash('sha256', strtolower($candidate['local'])),
                        'domainDigest' => hash('sha256', strtolower($candidate['domain'])),
                        'authorOriginIndexes' => $candidate['authorOriginIndexes'],
                        'bounds' => $this->pdfSourceEvidenceBounds($layout),
                    ];
                    $previousOrder = $order;
                    $previousY = $y;
                }
                if (count($proofPeers) !== count($candidateIndexes)) {
                    continue;
                }
                $proof = [
                    'version' => 1,
                    'method' => 'aligned-front-matter-mailboxes-with-shared-dns-label',
                    'sourceSha256' => $this->sourceSha256,
                    'page' => (int) $page,
                    'dnsLabelDigest' => hash('sha256', $dnsLabel),
                    'braceRepairRecordIndexes' => array_map('intval', $braceRepairPages[$page]),
                    'peers' => $proofPeers,
                ];
                $proof['proofDigest'] = hash('sha256', json_encode(
                    $proof,
                    JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_PRESERVE_ZERO_FRACTION
                ) ?: '');
                foreach ($candidateIndexes as $candidateIndex) {
                    $candidate = $candidatesByRecordIndex[$candidateIndex][0];
                    $sourceText = (string) $records[$candidateIndex]['text'];
                    $repaired = $candidate['local'] . '@' . $candidate['domain'];
                    $layout = $records[$candidateIndex]['layout'];
                    $layout['sourcePdfSemanticEmailDelimiterRepair'] = $proof + [
                        'sourceProjectionDigest' => hash(
                            'sha256',
                            $this->pdfSourceOccurrenceComparableText($sourceText)
                        ),
                        'outputProjectionDigest' => hash(
                            'sha256',
                            $this->pdfSourceOccurrenceComparableText($repaired)
                        ),
                    ];
                    $records[$candidateIndex]['text'] = $repaired;
                    $records[$candidateIndex]['layout'] = $layout;
                    $this->rememberPdfSemanticEmailDelimiterRepair(
                        $records[$candidateIndex],
                        $sourceText,
                        $repaired,
                        $layout['sourcePdfSemanticEmailDelimiterRepair']
                    );
                }
            }
        }

        return $records;
    }

    /**
     * Retain a record-local receipt for the only inserted byte. The semantic
     * pass may run on several candidate layouts, so final source dispositions
     * still revalidate the exact immutable occurrence and the unique emitted
     * projection before accepting this boundary repair.
     *
     * @param array{text:string,layout:array<string,mixed>|null} $record
     * @param array<string,mixed> $semanticProof
     */
    private function rememberPdfSemanticEmailDelimiterRepair(
        array $record,
        string $sourceText,
        string $outputText,
        array $semanticProof
    ): void {
        $layout = is_array($record['layout'] ?? null) ? $record['layout'] : null;
        if (!is_array($layout)) {
            return;
        }
        $ranges = $this->pdfPositionedExactSourceRanges($layout);
        $sourceIndexes = array_values(array_unique(array_column($ranges, 'sourceIndex')));
        $sourceProjection = $this->pdfSourceOccurrenceComparableText(
            $this->pdfTextWithoutSemanticPrefixes($sourceText)
        );
        $outputProjection = $this->pdfSourceOccurrenceComparableText(
            $this->pdfTextWithoutSemanticPrefixes($outputText)
        );
        $insertionOffset = strpos($outputProjection, '@');
        if (count($sourceIndexes) !== 1
            || $sourceProjection === ''
            || !is_int($insertionOffset)
            || substr_count($outputProjection, '@') !== 1
            || strlen($outputProjection) !== strlen($sourceProjection) + 1
            || !hash_equals(
                $sourceProjection,
                substr($outputProjection, 0, $insertionOffset)
                    . substr($outputProjection, $insertionOffset + 1)
            )) {
            return;
        }
        $identity = [
            'version' => 1,
            'method' => 'exact-semantic-email-delimiter-insertion',
            'sourceSha256' => $this->sourceSha256,
            'sourceIndex' => $sourceIndexes[0],
            'exactSourceRanges' => $ranges,
            'sourceProjectionDigest' => hash('sha256', $sourceProjection),
            'outputProjection' => $outputProjection,
            'outputText' => $this->pdfTextWithoutSemanticPrefixes($outputText),
            'outputProjectionDigest' => hash('sha256', $outputProjection),
            'insertionOffset' => $insertionOffset,
            'semanticProofDigest' => is_string($semanticProof['proofDigest'] ?? null)
                ? $semanticProof['proofDigest']
                : hash('sha256', json_encode(
                    $semanticProof,
                    JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE
                ) ?: ''),
        ];
        $identity['proofDigest'] = hash('sha256', json_encode(
            $identity,
            JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE
        ) ?: '');
        $this->pdfSemanticEmailDelimiterRepairProofCandidates[] = $identity;
    }

    /**
     * Complete an already identified first-page front-matter band from its
     * geometry. Some PDFs paint centered title continuations and affiliation
     * keys in a later content stream, so source order alone can place those
     * records in the body even though they occupy the exact visual band
     * between the title and summary heading.
     *
     * @param list<array{text:string,layout:array<string,mixed>|null}> $records
     * @return list<array{text:string,layout:array<string,mixed>|null}>
     */
    private function completePdfFrontMatterGeometryRecords(array $records): array
    {
        $bands = [];
        $geometryByPage = [];
        foreach ($records as $recordIndex => $record) {
            $layout = is_array($record['layout'] ?? null) ? $record['layout'] : null;
            if (!$this->pdfLayoutHasGeometry($layout)) {
                continue;
            }
            $page = (int) $layout['page'];
            $geometryByPage[$page][$recordIndex] = $record;
            $role = $layout['sourcePdfFrontMatterRole'] ?? null;
            if ($role === 'title') {
                $bands[$page]['titles'][] = $record;
            } elseif ($role === 'summary-heading') {
                $bands[$page]['summaryHeadings'][] = $record;
            }
        }

        foreach ($bands as $page => $band) {
            if (($band['titles'] ?? []) === [] || ($band['summaryHeadings'] ?? []) === []) {
                unset($bands[$page]);
                continue;
            }
            $title = $band['titles'][0];
            foreach ($band['titles'] as $candidate) {
                if ((float) $candidate['layout']['y1'] > (float) $title['layout']['y1']) {
                    $title = $candidate;
                }
            }
            $summary = $band['summaryHeadings'][0];
            foreach ($band['summaryHeadings'] as $candidate) {
                if ((float) $candidate['layout']['y1'] > (float) $summary['layout']['y1']) {
                    $summary = $candidate;
                }
            }
            $bands[$page] = [
                'titleIndex' => null,
                'titleY' => (float) $title['layout']['y1'],
                'titleFont' => max(1.0, (float) $title['layout']['fontSize']),
                'titleCenterX' => ((float) $title['layout']['x1'] + (float) $title['layout']['x2']) / 2.0,
                'summaryY' => (float) $summary['layout']['y1'],
                'pageWidth' => 0.0,
            ];
        }

        // Source-stream ordering can prevent the first classifier from
        // identifying any front matter at all. In that case, anchor only the
        // first page's top, multi-word display line and its centered visual
        // band; ordinary body columns sit far from that center axis.
        if ($geometryByPage !== []) {
            ksort($geometryByPage, SORT_NUMERIC);
            $firstPage = array_key_first($geometryByPage);
            if (!isset($bands[$firstPage])) {
                $pageRecords = $geometryByPage[$firstPage];
                $hasNumberedSectionBoundary = false;
                foreach ($pageRecords as $record) {
                    if (preg_match(
                        '/^\s*(?:\d+(?:\.\d+)*\.?\s+){1,2}\p{Lu}[\p{L}\p{N}]/u',
                        trim((string) ($record['text'] ?? ''))
                    ) === 1) {
                        $hasNumberedSectionBoundary = true;
                        break;
                    }
                }
                if ($hasNumberedSectionBoundary) {
                    $minX = INF;
                    $maxX = -INF;
                    $minY = INF;
                    $maxY = -INF;
                    foreach ($pageRecords as $record) {
                        $layout = $record['layout'];
                        $minX = min($minX, (float) $layout['x1']);
                        $maxX = max($maxX, (float) $layout['x2']);
                        $minY = min($minY, (float) $layout['y1']);
                        $maxY = max($maxY, (float) $layout['y2']);
                    }
                    $titleIndex = null;
                    $titleScore = -INF;
                    $topBand = $minY + max(1.0, $maxY - $minY) * 0.72;
                    foreach ($pageRecords as $recordIndex => $record) {
                        $layout = $record['layout'];
                        $text = trim((string) ($record['text'] ?? ''));
                        $font = max(1.0, (float) $layout['fontSize']);
                        if ((float) $layout['y1'] < $topBand
                            || $font < 14.0
                            || count($this->pdfLineWordTokens($text)) < 3
                            || count($this->pdfLineWordTokens($text)) > 20
                            || $this->length($text) < 15
                            || $this->length($text) > 180) {
                            continue;
                        }
                        $score = (float) $layout['y1'] + $font * 4.0;
                        if ($score > $titleScore) {
                            $titleIndex = $recordIndex;
                            $titleScore = $score;
                        }
                    }
                    if ($titleIndex !== null) {
                        $titleLayout = $pageRecords[$titleIndex]['layout'];
                        $titleFont = max(1.0, (float) $titleLayout['fontSize']);
                        $titleY = (float) $titleLayout['y1'];
                        $titleCenterX = ((float) $titleLayout['x1'] + (float) $titleLayout['x2']) / 2.0;
                        $hasTitleContinuation = false;
                        foreach ($pageRecords as $recordIndex => $record) {
                            if ($recordIndex === $titleIndex) {
                                continue;
                            }
                            $layout = $record['layout'];
                            $font = max(1.0, (float) $layout['fontSize']);
                            $centerX = ((float) $layout['x1'] + (float) $layout['x2']) / 2.0;
                            $gap = $titleY - (float) $layout['y1'];
                            if ($gap > 0.0
                                && $gap <= $titleFont * 1.65
                                && abs($font - $titleFont) <= max(0.75, $titleFont * 0.30)
                                && abs($centerX - $titleCenterX) <= $titleFont * 1.5) {
                                $hasTitleContinuation = true;
                                break;
                            }
                        }
                        if ($hasTitleContinuation) {
                            $bands[$firstPage] = [
                                'titleIndex' => $titleIndex,
                                'titleY' => $titleY,
                                'titleFont' => $titleFont,
                                'titleCenterX' => $titleCenterX,
                                'summaryY' => $titleY - $titleFont * 11.5,
                                'pageWidth' => max(1.0, $maxX - $minX),
                            ];
                        }
                    }
                }
            }
        }

        foreach ($records as $recordIndex => &$record) {
            $layout = is_array($record['layout'] ?? null) ? $record['layout'] : null;
            if (!$this->pdfLayoutHasGeometry($layout)) {
                continue;
            }
            $band = $bands[(int) $layout['page']] ?? null;
            $role = $layout['sourcePdfFrontMatterRole'] ?? null;
            if (!is_array($band)
                || in_array($role, ['summary-heading', 'summary-body'], true)
                || ($layout['code'] ?? false) === true
                || isset($layout['sourcePdfLineOrientedGroup'])) {
                continue;
            }
            $y = (float) $layout['y1'];
            $isPrimaryTitle = $recordIndex === ($band['titleIndex'] ?? null)
                || $role === 'title';
            if (!$isPrimaryTitle && ($y <= $band['summaryY'] || $y >= $band['titleY'])) {
                continue;
            }

            $font = max(1.0, (float) $layout['fontSize']);
            $centerX = ((float) $layout['x1'] + (float) $layout['x2']) / 2.0;
            $titleGap = $band['titleY'] - $y;
            $isTitleContinuation = $isPrimaryTitle || ($titleGap <= $band['titleFont'] * 1.65
                && abs($font - $band['titleFont']) <= max(0.75, $band['titleFont'] * 0.30)
                && abs($centerX - $band['titleCenterX']) <= $band['titleFont'] * 1.5);
            if (!$isTitleContinuation
                && (abs($centerX - $band['titleCenterX']) > max(
                    $band['titleFont'] * 5.0,
                    (float) $band['pageWidth'] * 0.12
                ) || $this->length(trim((string) ($record['text'] ?? ''))) > 220)) {
                continue;
            }

            $layout['sourcePdfFrontMatter'] = true;
            $layout['sourcePdfProtectedSemanticContent'] = true;
            $layout['sourcePdfFrontMatterRole'] = $isTitleContinuation ? 'title' : 'credits';
            if ($isTitleContinuation) {
                $layout['sourcePdfDisplayHeading'] = true;
            } else {
                unset($layout['sourcePdfDisplayHeading']);
            }
            $record['layout'] = $layout;
        }
        unset($record);

        return $records;
    }

    private function flattenedPdfNumberedCodeListing(string $text): ?string
    {
        $text = trim($text);
        if (preg_match('/^1\s+(?:for|if|while|switch)\s*\(/u', $text) !== 1) {
            return null;
        }
        $matched = preg_match_all(
            '/(?:^|\s)(\d{1,3})\s+(?=[\p{L}_{}])/u',
            $text,
            $matches,
            PREG_OFFSET_CAPTURE
        );
        if ($matched === false || $matched < 4) {
            return null;
        }

        $markers = [];
        foreach ($matches[1] as $match) {
            $markers[] = [
                'number' => (int) $match[0],
                'numberOffset' => (int) $match[1],
            ];
        }
        foreach ($markers as $index => $marker) {
            if ($marker['number'] !== $index + 1) {
                return null;
            }
        }

        $rows = [];
        foreach ($markers as $index => $marker) {
            $contentStart = $marker['numberOffset'] + strlen((string) $marker['number']);
            $contentEnd = isset($markers[$index + 1])
                ? $markers[$index + 1]['numberOffset']
                : strlen($text);
            $content = trim(substr($text, $contentStart, $contentEnd - $contentStart));
            if ($content === '') {
                return null;
            }
            // A separated unary not is a PDF word-spacing artifact, not
            // meaningful source indentation.
            $content = preg_replace('/!\s+(?=[\p{L}_$])/u', '!', $content) ?? $content;
            $indent = '';
            if ($index > 0) {
                $previous = $rows[$index - 1]['content'];
                if (preg_match('/^(?:if|for|while)\s*\(.*\)\s*$/u', $previous) === 1
                    && !str_ends_with($previous, '{')
                    && $content !== '}') {
                    $indent = '    ';
                }
            }
            $rows[] = [
                'content' => $content,
                'line' => $marker['number'] . ' ' . $indent . $content,
            ];
        }

        $codeText = implode("\n", array_column($rows, 'line'));
        $compactSource = preg_replace('/\s+/u', '', $text) ?? '';
        $compactCode = preg_replace('/\s+/u', '', $codeText) ?? '';
        $statementEvidence = preg_match_all(
            '/\b(?:for|if|while|continue|break|return)\b|[;{}]/u',
            $codeText,
            $unused
        );

        return $compactSource !== ''
            && $compactSource === $compactCode
            && $statementEvidence !== false
            && $statementEvidence >= 5
                ? $codeText
                : null;
    }

    /**
     * Apply the character-preserving presentation normalization shared by
     * the document-wide repair and each conservative page projection.
     *
     * @param list<string> $merged
     * @param array<int,array<string,mixed>> $exactWholeSourceMergedLineSpans
     * @param array<int,array<string,mixed>>|null $finalWholeSourceMergedLineSpans
     * @return list<string>
     */
    private function finalizedRepairedPdfLines(
        array $merged,
        bool $repairGluedText,
        array $exactWholeSourceMergedLineSpans = [],
        ?array &$finalWholeSourceMergedLineSpans = null
    ): array {
        $collectFinalSpans = func_num_args() >= 4;
        $finalWholeSourceMergedLineSpans = [];
        $repaired = [];
        $append = function (string $line, int $inputIndex) use (
            &$repaired,
            &$finalWholeSourceMergedLineSpans,
            $collectFinalSpans,
            $exactWholeSourceMergedLineSpans
        ): void {
            if ($line === '') {
                return;
            }
            $outputIndex = count($repaired);
            $repaired[] = $line;
            $span = $exactWholeSourceMergedLineSpans[$inputIndex] ?? null;
            if ($collectFinalSpans
                && $this->repairedPdfMergedLineHasExactWholeSourceSpan($line, $span)) {
                $finalWholeSourceMergedLineSpans[$outputIndex] = $span;
            }
        };
        foreach ($merged as $lineIndex => $line) {
            $chartProjection = $this->pdfChartFontCipherLineIsCandidate($line)
                ? $this->pdfSourceOccurrenceComparableText(
                    $this->pdfTextWithoutSemanticPrefixes($line)
                )
                : '';
            if ($chartProjection !== ''
                && (isset($this->sourcePdfChartCipherArtifactProjectionDigests[
                    hash('sha256', $chartProjection)
                ]) || $this->sourcePdfChartCipherMergedLineIsProvenArtifact(
                    $line,
                    $exactWholeSourceMergedLineSpans[$lineIndex] ?? null
                ))) {
                continue;
            }
            $flattenedCode = $this->flattenedPdfNumberedCodeListing($line);
            if ($flattenedCode !== null) {
                $append(self::PDF_CODE_BLOCK_PREFIX . $flattenedCode, $lineIndex);
                continue;
            }
            if (str_starts_with($line, self::PDF_CODE_BLOCK_PREFIX)) {
                $append($line, $lineIndex);
                continue;
            }
            if (str_starts_with($line, PdfFormulaSemanticProcessor::LINE_PREFIX)) {
                $formula = trim(substr($line, strlen(PdfFormulaSemanticProcessor::LINE_PREFIX)));
                if ($formula !== '') {
                    $append(PdfFormulaSemanticProcessor::LINE_PREFIX . $formula, $lineIndex);
                }
                continue;
            }
            if (str_starts_with($line, self::PDF_LINE_BLOCK_PREFIX)) {
                $lineBlock = $this->decodePdfLineBlock($line);
                if ($lineBlock === []) {
                    continue;
                }
                $lineBlock = array_values(array_filter(array_map(
                    fn (string $blockLine): string => $repairGluedText
                        ? $this->repairGluedProseLine($blockLine)
                        : trim($blockLine),
                    $lineBlock
                ), static fn (string $blockLine): bool => $blockLine !== ''));
                if ($lineBlock !== []) {
                    $append($this->encodePdfLineBlock($lineBlock), $lineIndex);
                }
                continue;
            }
            if (str_starts_with($line, self::PDF_MAP_LABEL_PREFIX)) {
                $label = substr($line, strlen(self::PDF_MAP_LABEL_PREFIX));
                $label = $repairGluedText
                    ? $this->repairGluedProseLine($label)
                    : trim($label);
                if ($label !== '') {
                    $append(self::PDF_MAP_LABEL_PREFIX . $label, $lineIndex);
                }
                continue;
            }
            if (str_starts_with($line, self::PDF_FRONT_MATTER_PREFIX)) {
                $credit = trim(substr($line, strlen(self::PDF_FRONT_MATTER_PREFIX)));
                if ($credit !== '') {
                    $append(self::PDF_FRONT_MATTER_PREFIX . $credit, $lineIndex);
                }
                continue;
            }
            if (str_starts_with($line, self::PDF_LAYOUT_LABEL_PREFIX)) {
                $label = substr($line, strlen(self::PDF_LAYOUT_LABEL_PREFIX));
                $label = $repairGluedText
                    ? $this->repairGluedProseLine($label)
                    : trim($label);
                if ($label !== '') {
                    $append(self::PDF_LAYOUT_LABEL_PREFIX . $label, $lineIndex);
                }
                continue;
            }
            if (str_starts_with($line, self::PDF_DISPLAY_HEADING_PREFIX)) {
                $heading = substr($line, strlen(self::PDF_DISPLAY_HEADING_PREFIX));
                $heading = $repairGluedText
                    ? $this->repairGluedProseLine($heading)
                    : trim($heading);
                if ($heading !== '') {
                    $append(self::PDF_DISPLAY_HEADING_PREFIX . $heading, $lineIndex);
                }
                continue;
            }
            $line = $repairGluedText
                ? $this->repairGluedProseLine($line)
                : trim($line);
            $line = $this->collapseProvenRepeatedPdfResourceUrl(
                $line,
                $exactWholeSourceMergedLineSpans[$lineIndex] ?? null
            );
            if ($line !== '') {
                $append($line, $lineIndex);
            }
        }

        return $repaired;
    }

    /**
     * @param list<string> $lines
     * @return array<int,true>
     */
    private function pdfChartFontCipherLineIndexes(array $lines): array
    {
        $indexes = [];
        $run = [];
        $flush = static function () use (&$indexes, &$run): void {
            // A single compact formula can have the same character ratios.
            // A sustained four-row run is evidence of a chart's substituted
            // symbol font rather than editable prose.
            if (count($run) >= 4) {
                foreach ($run as $index) {
                    $indexes[$index] = true;
                }
            }
            $run = [];
        };

        foreach ($lines as $index => $line) {
            if ($this->pdfChartFontCipherLineIsCandidate($line)) {
                $run[] = $index;
                continue;
            }
            $flush();
        }
        $flush();

        return $indexes;
    }

    private function pdfChartFontCipherLineIsCandidate(string $line): bool
    {
        $text = trim($this->pdfTextWithoutSemanticPrefixes($line));
        $compact = preg_replace('/\s+/u', '', $text) ?? '';
        $length = $this->length($compact);
        $garbledDelimiters = preg_match_all('/[#<>=]/u', $compact, $unused);
        $letters = preg_match_all('/\p{L}/u', $compact, $unused);

        return $length >= 8
            && preg_match('/\p{Ll}/u', $compact) !== 1
            && $garbledDelimiters !== false
            && $garbledDelimiters >= 2
            && $letters !== false
            && ($length - $letters) / $length >= 0.35
            && !$this->lineLooksLikeUrlOnly($text);
    }

    /** @param list<array<string,mixed>> $lineItems */
    private function markSourcePdfChartCipherArtifacts(array &$lineItems): void
    {
        $this->sourcePdfChartCipherArtifactProofsBySourceId =
            $this->sourcePdfChartCipherArtifactProofs($lineItems);
        $candidateSourceIdsByProjectionDigest = [];
        $sourceItemsByGlobalIndex = [];
        foreach ($lineItems as $localIndex => $item) {
            $sourceId = is_string($item['id'] ?? null) ? $item['id'] : '';
            $text = is_string($item['text'] ?? null) ? $item['text'] : '';
            $projection = $this->pdfSourceOccurrenceComparableText($text);
            $globalSourceIndex = is_int($item['sourcePdfGlobalSourceIndex'] ?? null)
                ? $item['sourcePdfGlobalSourceIndex']
                : $localIndex;
            if ($sourceId !== ''
                && $projection !== ''
                && is_int($globalSourceIndex)
                && $globalSourceIndex >= 0
                && !isset($sourceItemsByGlobalIndex[$globalSourceIndex])) {
                $sourceItemsByGlobalIndex[$globalSourceIndex] = [
                    'sourceId' => $sourceId,
                    'globalSourceIndex' => $globalSourceIndex,
                    'text' => $text,
                    'projection' => $projection,
                    'page' => (int) ($item['page'] ?? 0),
                    'stream' => (int) ($item['stream'] ?? 0),
                ];
            }
            if ($sourceId === ''
                || $projection === ''
                || !$this->pdfChartFontCipherLineIsCandidate($text)) {
                continue;
            }
            $candidateSourceIdsByProjectionDigest[hash('sha256', $projection)][$sourceId] = true;
        }
        $this->sourcePdfChartCipherArtifactProjectionDigests = [];
        foreach ($candidateSourceIdsByProjectionDigest as $projectionDigest => $sourceIds) {
            foreach (array_keys($sourceIds) as $sourceId) {
                if (!is_array($this->sourcePdfChartCipherArtifactProofsBySourceId[$sourceId] ?? null)) {
                    continue 2;
                }
            }
            $this->sourcePdfChartCipherArtifactProjectionDigests[$projectionDigest] = true;
        }
        ksort($sourceItemsByGlobalIndex, SORT_NUMERIC);
        $uniqueProofs = [];
        foreach ($this->sourcePdfChartCipherArtifactProofsBySourceId as $proof) {
            if (!is_array($proof)
                || !$this->sourcePdfSignedProofDigestMatches($proof)
                || !is_string($proof['proofDigest'] ?? null)) {
                continue;
            }
            $uniqueProofs[$proof['proofDigest']] = $proof;
        }
        $combinedArtifactProjectionDigests = [];
        $maximumProofLineCount = 0;
        foreach ($uniqueProofs as $proof) {
            $sourceIds = is_array($proof['sourceOccurrenceIds'] ?? null)
                ? array_values($proof['sourceOccurrenceIds'])
                : [];
            $globalIndexes = is_array($proof['globalSourceIndexes'] ?? null)
                ? array_values($proof['globalSourceIndexes'])
                : [];
            $proofLines = is_array($proof['lines'] ?? null)
                ? array_values($proof['lines'])
                : [];
            if ($sourceIds === []
                || count($sourceIds) !== count($globalIndexes)
                || count($sourceIds) !== count($proofLines)) {
                continue;
            }
            $projections = [];
            foreach ($sourceIds as $offset => $sourceId) {
                $globalSourceIndex = $globalIndexes[$offset] ?? null;
                $item = is_int($globalSourceIndex)
                    ? ($sourceItemsByGlobalIndex[$globalSourceIndex] ?? null)
                    : null;
                if (!is_string($sourceId)
                    || !is_array($item)
                    || $item['sourceId'] !== $sourceId
                    || ($proofLines[$offset]['globalSourceIndex'] ?? null)
                        !== $globalSourceIndex
                    || !hash_equals(
                        (string) ($proofLines[$offset]['projectionDigest'] ?? ''),
                        hash('sha256', $item['projection'])
                    )) {
                    $projections = [];
                    break;
                }
                $projections[] = $item['projection'];
            }
            if ($projections === []) {
                continue;
            }
            $maximumProofLineCount = max($maximumProofLineCount, count($projections));
            foreach ($projections as $start => $_projection) {
                $combinedProjection = '';
                for ($end = $start, $count = count($projections); $end < $count; $end++) {
                    $combinedProjection .= $projections[$end];
                    if ($end === $start
                        || !$this->pdfChartFontCipherLineIsCandidate($combinedProjection)) {
                        continue;
                    }
                    $combinedArtifactProjectionDigests[
                        hash('sha256', $combinedProjection)
                    ] = true;
                }
            }
        }
        if ($combinedArtifactProjectionDigests !== [] && $maximumProofLineCount >= 2) {
            foreach ($sourceItemsByGlobalIndex as $startGlobalIndex => $firstItem) {
                $combinedProjection = '';
                $sharedProof = null;
                $allMembersShareProof = true;
                for ($offset = 0; $offset < $maximumProofLineCount; $offset++) {
                    $item = $sourceItemsByGlobalIndex[$startGlobalIndex + $offset] ?? null;
                    if (!is_array($item)
                        || $item['page'] !== $firstItem['page']
                        || $item['stream'] !== $firstItem['stream']) {
                        break;
                    }
                    $combinedProjection .= $item['projection'];
                    $itemProof = $this->sourcePdfChartCipherArtifactProofsBySourceId[
                        $item['sourceId']
                    ] ?? null;
                    if (!is_array($itemProof)
                        || !$this->sourcePdfSignedProofDigestMatches($itemProof)
                        || ($sharedProof !== null && $itemProof !== $sharedProof)) {
                        $allMembersShareProof = false;
                    } elseif ($sharedProof === null) {
                        $sharedProof = $itemProof;
                    }
                    $projectionDigest = hash('sha256', $combinedProjection);
                    if (isset($combinedArtifactProjectionDigests[$projectionDigest])
                        && !$allMembersShareProof) {
                        unset($combinedArtifactProjectionDigests[$projectionDigest]);
                    }
                }
            }
            $this->sourcePdfChartCipherArtifactProjectionDigests +=
                $combinedArtifactProjectionDigests;
        }
        foreach ($lineItems as &$item) {
            $sourceId = is_string($item['id'] ?? null) ? $item['id'] : '';
            $proof = $sourceId !== ''
                ? ($this->sourcePdfChartCipherArtifactProofsBySourceId[$sourceId] ?? null)
                : null;
            if (is_array($proof)) {
                $item['sourcePdfChartCipherArtifactEvidence'] = $proof;
            }
        }
        unset($item);
    }

    /**
     * A substituted chart font presents a sustained same-stream group of
     * delimiter-heavy uppercase cipher rows. Axis/header labels can be split
     * into short fragments immediately before or after the full rows, so a
     * group admits those fragments only when the same exact consecutive run
     * contains at least four full cipher candidates. Sign the immutable source
     * identities before semantic repair so output suppression and the final
     * disposition ledger can independently revalidate the group.
     *
     * @param list<array<string,mixed>> $lineItems
     * @return array<string,array<string,mixed>>
     */
    private function sourcePdfChartCipherArtifactProofs(array $lineItems): array
    {
        $proofs = [];
        $run = [];
        $runPage = null;
        $runStream = null;
        $flush = function () use (&$proofs, &$run, &$runPage, &$runStream): void {
            $fullCandidateLineCount = count(array_filter(
                $run,
                static fn (array $line): bool => ($line['candidateKind'] ?? null) === 'full'
            ));
            if ($fullCandidateLineCount >= 4
                && is_int($runPage)
                && is_int($runStream)) {
                $sourceIds = array_column($run, 'sourceOccurrenceId');
                $globalIndexes = array_column($run, 'globalSourceIndex');
                if (count(array_unique($sourceIds, SORT_STRING)) === count($sourceIds)
                    && count(array_unique($globalIndexes, SORT_NUMERIC)) === count($globalIndexes)) {
                    $proof = [
                        'version' => 1,
                        'method' => 'exact-source-chart-font-cipher-line-group',
                        'sourceSha256' => $this->sourceSha256,
                        'page' => $runPage,
                        'stream' => $runStream,
                        'lineCount' => count($run),
                        'fullCandidateLineCount' => $fullCandidateLineCount,
                        'sourceOccurrenceIds' => $sourceIds,
                        'globalSourceIndexes' => $globalIndexes,
                        'lines' => $run,
                    ];
                    $proof['proofDigest'] = hash('sha256', json_encode(
                        $proof,
                        JSON_UNESCAPED_SLASHES
                            | JSON_UNESCAPED_UNICODE
                            | JSON_PRESERVE_ZERO_FRACTION
                    ) ?: '');
                    foreach ($sourceIds as $sourceId) {
                        $proofs[$sourceId] = $proof;
                    }
                }
            }
            $run = [];
            $runPage = null;
            $runStream = null;
        };

        foreach ($lineItems as $localIndex => $item) {
            $text = is_string($item['text'] ?? null) ? $item['text'] : '';
            $sourceId = is_string($item['id'] ?? null) ? $item['id'] : '';
            $page = (int) ($item['page'] ?? 0);
            $stream = (int) ($item['stream'] ?? 0);
            $globalSourceIndex = is_int($item['sourcePdfGlobalSourceIndex'] ?? null)
                ? $item['sourcePdfGlobalSourceIndex']
                : $localIndex;
            $projection = $this->pdfSourceOccurrenceComparableText($text);
            $fullCandidate = $sourceId !== ''
                && $page >= 1
                && $stream >= 1
                && $globalSourceIndex >= 0
                && $projection !== ''
                && $this->pdfChartFontCipherLineIsCandidate($text);
            $tailCandidate = !$fullCandidate
                && $sourceId !== ''
                && $page >= 1
                && $stream >= 1
                && $globalSourceIndex >= 0
                && $projection !== ''
                && $this->pdfChartFontCipherTailFragmentIsCandidate($text);
            if (!$fullCandidate && !$tailCandidate) {
                $flush();
                continue;
            }
            $previousGlobalIndex = $run === []
                ? null
                : $run[array_key_last($run)]['globalSourceIndex'];
            $scopeContinues = $run !== []
                && $runPage === $page
                && $runStream === $stream
                && is_int($previousGlobalIndex)
                && $globalSourceIndex === $previousGlobalIndex + 1;
            if ($run !== [] && !$scopeContinues) {
                $flush();
            }
            $runPage = $page;
            $runStream = $stream;
            $run[] = [
                'sourceOccurrenceId' => $sourceId,
                'globalSourceIndex' => $globalSourceIndex,
                'candidateKind' => $fullCandidate ? 'full' : 'short-fragment',
                'projectionDigest' => hash('sha256', $projection),
                'significantBytes' => strlen($projection),
                'exactRange' => [
                    'sourceIndex' => $globalSourceIndex,
                    'sourceStart' => 0,
                    'sourceEnd' => strlen($projection),
                ],
            ];
        }
        $flush();

        return $proofs;
    }

    private function pdfChartFontCipherTailFragmentIsCandidate(string $line): bool
    {
        $text = trim($this->pdfTextWithoutSemanticPrefixes($line));
        $compact = preg_replace('/\s+/u', '', $text) ?? '';
        $length = $this->length($compact);
        $garbledDelimiters = preg_match_all('/[#<>=]/u', $compact, $unused);
        $letters = preg_match_all('/\p{L}/u', $compact, $unused);

        return $length >= 3
            && $length < 8
            && preg_match('/\p{Ll}/u', $compact) !== 1
            && $garbledDelimiters !== false
            && $garbledDelimiters >= 1
            && $letters !== false
            && ($length - $letters) / $length >= 0.35
            && !$this->lineLooksLikeUrlOnly($text);
    }

    /** @param array<string,mixed>|null $layout */
    private function sourcePdfChartCipherLayoutIsProvenArtifact(
        ?array $layout,
        string $line
    ): bool {
        $sourceId = is_array($layout) && is_string($layout['id'] ?? null)
            ? $layout['id']
            : '';
        $proof = $sourceId !== ''
            ? ($this->sourcePdfChartCipherArtifactProofsBySourceId[$sourceId] ?? null)
            : null;
        if (!is_array($layout)
            || !is_array($proof)
            || !$this->sourcePdfSignedProofDigestMatches($proof)
            || ($proof['method'] ?? null) !== 'exact-source-chart-font-cipher-line-group'
            || ($proof['sourceSha256'] ?? null) !== $this->sourceSha256
            || (int) ($layout['page'] ?? 0) !== ($proof['page'] ?? null)) {
            return false;
        }
        $layoutStream = is_int($layout['sourceStream'] ?? null)
            ? $layout['sourceStream']
            : (is_int($layout['stream'] ?? null) ? $layout['stream'] : null);
        if (!is_int($layoutStream) || $layoutStream !== ($proof['stream'] ?? null)) {
            return false;
        }
        $sourceIds = is_array($proof['sourceOccurrenceIds'] ?? null)
            ? array_values($proof['sourceOccurrenceIds'])
            : [];
        $offset = array_search($sourceId, $sourceIds, true);
        $proofLine = is_int($offset) && is_array($proof['lines'][$offset] ?? null)
            ? $proof['lines'][$offset]
            : null;
        $projection = $this->pdfSourceOccurrenceComparableText(
            $this->pdfTextWithoutSemanticPrefixes($line)
        );
        if (!is_array($proofLine)
            || $projection === ''
            || !hash_equals(
                (string) ($proofLine['projectionDigest'] ?? ''),
                hash('sha256', $projection)
            )) {
            return false;
        }
        if (is_int($layout['sourcePdfGlobalSourceIndex'] ?? null)
            && $layout['sourcePdfGlobalSourceIndex']
                !== ($proofLine['globalSourceIndex'] ?? null)) {
            return false;
        }
        $stampedEvidence = $layout['sourcePdfChartCipherArtifactEvidence'] ?? null;

        return $stampedEvidence === null || $stampedEvidence === $proof;
    }

    /**
     * @param list<string> $lines
     * @param list<array<string,mixed>> $sourceItems
     * @return list<string>
     */
    private function sourcePdfPresentationLinesWithoutProvenChartCipherArtifacts(
        array $lines,
        array $sourceItems
    ): array {
        if (count($lines) !== count($sourceItems)) {
            return $lines;
        }
        $filtered = [];
        foreach ($lines as $index => $line) {
            $layout = is_array($sourceItems[$index] ?? null)
                ? $sourceItems[$index]
                : null;
            if (!$this->sourcePdfChartCipherLayoutIsProvenArtifact($layout, $line)) {
                $filtered[] = $line;
            }
        }

        return $filtered;
    }

    /**
     * Remove a positioned presentation run only when its complete significant
     * projection is reconstructed from exact source ranges and every covered
     * source occurrence belongs to the same signed chart-cipher group.
     *
     * @param list<array<string,mixed>> $runs
     * @param list<array<string,mixed>> $sourceItems
     * @return list<array<string,mixed>>
     */
    private function positionedPdfRunsWithoutProvenChartCipherArtifacts(
        array $runs,
        array $sourceItems
    ): array {
        if ($runs === [] || $this->sourcePdfChartCipherArtifactProofsBySourceId === []) {
            return $runs;
        }
        $sourceItemsByGlobalIndex = [];
        foreach ($sourceItems as $localIndex => $sourceItem) {
            $globalSourceIndex = is_int($sourceItem['sourcePdfGlobalSourceIndex'] ?? null)
                ? $sourceItem['sourcePdfGlobalSourceIndex']
                : $localIndex;
            if ($globalSourceIndex < 0 || isset($sourceItemsByGlobalIndex[$globalSourceIndex])) {
                return $runs;
            }
            $sourceItemsByGlobalIndex[$globalSourceIndex] = $sourceItem;
        }

        $filtered = [];
        foreach ($runs as $run) {
            $runProjection = $this->pdfSourceOccurrenceComparableText(
                (string) ($run['text'] ?? '')
            );
            $ranges = $this->pdfPositionedExactSourceRanges($run);
            $coveredProjection = '';
            $sharedProof = null;
            $failureReason = $runProjection === ''
                ? 'empty-run-projection'
                : ($ranges === [] ? 'no-exact-source-ranges' : null);
            foreach ($failureReason === null ? $ranges : [] as $range) {
                $sourceItem = $sourceItemsByGlobalIndex[$range['sourceIndex']] ?? null;
                $sourceId = is_array($sourceItem)
                    && is_string($sourceItem['id'] ?? null)
                        ? $sourceItem['id']
                        : '';
                $sourceProjection = is_array($sourceItem)
                    ? $this->pdfSourceOccurrenceComparableText(
                        (string) ($sourceItem['text'] ?? '')
                    )
                    : '';
                $proof = $sourceId !== ''
                    ? ($this->sourcePdfChartCipherArtifactProofsBySourceId[$sourceId] ?? null)
                    : null;
                if (!is_array($sourceItem)
                    || $sourceId === ''
                    || $sourceProjection === ''
                    || $range['sourceEnd'] > strlen($sourceProjection)
                    || (int) ($run['page'] ?? 0) !== (int) ($sourceItem['page'] ?? 0)
                    || !is_array($proof)
                    || !$this->sourcePdfSignedProofDigestMatches($proof)
                    || !in_array($sourceId, $proof['sourceOccurrenceIds'] ?? [], true)
                    || !in_array(
                        $range['sourceIndex'],
                        $proof['globalSourceIndexes'] ?? [],
                        true
                    )
                    || ($sharedProof !== null && $proof !== $sharedProof)) {
                    $failureReason = 'source-range-is-not-in-one-signed-chart-group';
                    break;
                }
                $sharedProof = $proof;
                $coveredProjection .= substr(
                    $sourceProjection,
                    $range['sourceStart'],
                    $range['sourceEnd'] - $range['sourceStart']
                );
            }
            if ($failureReason === null
                && ($sharedProof === null
                    || !hash_equals($runProjection, $coveredProjection))) {
                $failureReason = 'run-projection-does-not-equal-covered-source-ranges';
            }
            if ($failureReason !== null) {
                $filtered[] = $run;
            }
        }

        return $filtered;
    }

    private function sourcePdfChartCipherMergedLineIsProvenArtifact(
        string $line,
        mixed $span
    ): bool {
        if (!$this->repairedPdfMergedLineHasExactWholeSourceSpan($line, $span)
            || !is_array($span)) {
            return false;
        }
        $sourceIds = $span['sourceOccurrenceIds'] ?? [];
        $globalIndexes = $span['globalSourceIndexes'] ?? [];
        $proof = null;
        foreach ($sourceIds as $offset => $sourceId) {
            $candidateProof = is_string($sourceId)
                ? ($this->sourcePdfChartCipherArtifactProofsBySourceId[$sourceId] ?? null)
                : null;
            if (!is_array($candidateProof)
                || !$this->sourcePdfSignedProofDigestMatches($candidateProof)
                || !in_array($sourceId, $candidateProof['sourceOccurrenceIds'] ?? [], true)
                || !in_array(
                    $globalIndexes[$offset] ?? null,
                    $candidateProof['globalSourceIndexes'] ?? [],
                    true
                )
                || ($proof !== null && $candidateProof !== $proof)) {
                return false;
            }
            $proof = $candidateProof;
        }

        return $proof !== null;
    }

    /**
     * Convert a heuristic chart-font run into suppression authority only when
     * every merged line is an exact, consecutive union of immutable source
     * occurrences. A visually suspicious spelling without that sidecar stays
     * editable and will fail the ordinary fidelity gate instead of silently
     * disappearing.
     *
     * @param list<string> $lines
     * @param array<int,array<string,mixed>> $exactWholeSourceMergedLineSpans
     * @param array<int,true> $cipherIndexes
     * @return array<int,array<string,mixed>>
     */
    private function sourcePdfChartCipherArtifactProofsByLineIndex(
        array $lines,
        array $exactWholeSourceMergedLineSpans,
        array $cipherIndexes
    ): array {
        if ($cipherIndexes === []) {
            return [];
        }

        $proofsByLineIndex = [];
        $run = [];
        $flush = function () use (
            &$proofsByLineIndex,
            &$run,
            $lines,
            $exactWholeSourceMergedLineSpans
        ): void {
            if (count($run) < 4) {
                $run = [];
                return;
            }
            $lineProofs = [];
            $sourceOccurrenceIds = [];
            $globalSourceIndexes = [];
            foreach ($run as $lineIndex) {
                $line = $lines[$lineIndex] ?? null;
                $span = $exactWholeSourceMergedLineSpans[$lineIndex] ?? null;
                if (!is_string($line)
                    || !$this->pdfChartFontCipherLineIsCandidate($line)
                    || !$this->repairedPdfMergedLineHasExactWholeSourceSpan($line, $span)) {
                    $this->sourceOrderProofDiagnostics[] = [
                        'status' => 'trace',
                        'method' => 'chart-font-cipher-artifact-proof',
                        'reason' => 'cipher-line-has-no-exact-whole-source-span',
                        'lineIndex' => $lineIndex,
                        'spanMethod' => is_array($span) ? ($span['method'] ?? null) : null,
                    ];
                    $run = [];
                    return;
                }
                $lineSourceIds = array_values($span['sourceOccurrenceIds']);
                $lineGlobalIndexes = array_values($span['globalSourceIndexes']);
                $previousLineGlobalSourceIndex = null;
                foreach ($lineSourceIds as $sourceOffset => $sourceId) {
                    $globalSourceIndex = $lineGlobalIndexes[$sourceOffset] ?? null;
                    if (!is_string($sourceId)
                        || $sourceId === ''
                        || !is_int($globalSourceIndex)
                        || ($previousLineGlobalSourceIndex !== null
                            && $globalSourceIndex !== $previousLineGlobalSourceIndex + 1)) {
                        $this->sourceOrderProofDiagnostics[] = [
                            'status' => 'trace',
                            'method' => 'chart-font-cipher-artifact-proof',
                            'reason' => 'cipher-line-source-span-is-not-canonical',
                            'lineIndex' => $lineIndex,
                        ];
                        $run = [];
                        return;
                    }
                    $sourceOccurrenceIds[] = $sourceId;
                    $globalSourceIndexes[] = $globalSourceIndex;
                    $previousLineGlobalSourceIndex = $globalSourceIndex;
                }
                $lineProofs[] = [
                    'sourceOccurrenceIds' => $lineSourceIds,
                    'globalSourceIndexes' => $lineGlobalIndexes,
                    'projectionDigest' => $span['projectionDigest'],
                ];
            }
            if ($sourceOccurrenceIds === []
                || count(array_unique($sourceOccurrenceIds, SORT_STRING))
                    !== count($sourceOccurrenceIds)
                || count(array_unique($globalSourceIndexes, SORT_NUMERIC))
                    !== count($globalSourceIndexes)) {
                $this->sourceOrderProofDiagnostics[] = [
                    'status' => 'trace',
                    'method' => 'chart-font-cipher-artifact-proof',
                    'reason' => 'cipher-run-reuses-a-source-occurrence',
                    'lineCount' => count($run),
                ];
                $run = [];
                return;
            }
            $proof = [
                'version' => 1,
                'method' => 'exact-chart-font-cipher-line-run',
                'sourceSha256' => $this->sourceSha256,
                'lineCount' => count($lineProofs),
                'sourceOccurrenceIds' => $sourceOccurrenceIds,
                'globalSourceIndexes' => $globalSourceIndexes,
                'lines' => $lineProofs,
            ];
            $proof['proofDigest'] = hash('sha256', json_encode(
                $proof,
                JSON_UNESCAPED_SLASHES
                    | JSON_UNESCAPED_UNICODE
                    | JSON_PRESERVE_ZERO_FRACTION
            ) ?: '');
            foreach ($run as $lineIndex) {
                $proofsByLineIndex[$lineIndex] = $proof;
            }
            $this->sourceOrderProofDiagnostics[] = [
                'status' => 'accepted',
                'method' => 'chart-font-cipher-artifact-proof',
                'lineCount' => count($lineProofs),
                'sourceOccurrenceCount' => count($sourceOccurrenceIds),
            ];
            $run = [];
        };

        foreach ($lines as $lineIndex => $_line) {
            if (isset($cipherIndexes[$lineIndex])) {
                $run[] = $lineIndex;
                continue;
            }
            $flush();
        }
        $flush();

        return $proofsByLineIndex;
    }

    /** @param array<string,mixed> $proof */
    private function registerSourcePdfChartCipherArtifactProof(array $proof): void
    {
        foreach ($proof['sourceOccurrenceIds'] ?? [] as $sourceId) {
            if (!is_string($sourceId) || $sourceId === '') {
                continue;
            }
            if (!array_key_exists($sourceId, $this->sourcePdfChartCipherArtifactProofsBySourceId)) {
                $this->sourcePdfChartCipherArtifactProofsBySourceId[$sourceId] = $proof;
                continue;
            }
            if ($this->sourcePdfChartCipherArtifactProofsBySourceId[$sourceId] !== $proof) {
                // Conflicting late-merge groupings revoke suppression
                // authority for this occurrence.
                $this->sourcePdfChartCipherArtifactProofsBySourceId[$sourceId] = false;
            }
        }
    }

    /**
     * @param array<string,mixed> $proof
     * @param list<array<string,mixed>> $lineItems
     */
    private function sourcePdfChartCipherArtifactProofMatchesSourceItems(
        array $proof,
        array $lineItems
    ): bool {
        if (($proof['version'] ?? null) !== 1
            || ($proof['method'] ?? null) !== 'exact-chart-font-cipher-line-run'
            || ($proof['sourceSha256'] ?? null) !== $this->sourceSha256
            || !is_int($proof['lineCount'] ?? null)
            || $proof['lineCount'] < 4
            || !is_array($proof['sourceOccurrenceIds'] ?? null)
            || !array_is_list($proof['sourceOccurrenceIds'])
            || $proof['sourceOccurrenceIds'] === []
            || !is_array($proof['globalSourceIndexes'] ?? null)
            || !array_is_list($proof['globalSourceIndexes'])
            || count($proof['globalSourceIndexes']) !== count($proof['sourceOccurrenceIds'])
            || !is_array($proof['lines'] ?? null)
            || !array_is_list($proof['lines'])
            || count($proof['lines']) !== $proof['lineCount']
            || !$this->sourcePdfSignedProofDigestMatches($proof)) {
            return false;
        }

        $itemsByGlobalIndex = [];
        foreach ($lineItems as $localIndex => $item) {
            $globalSourceIndex = is_int($item['sourcePdfGlobalSourceIndex'] ?? null)
                ? $item['sourcePdfGlobalSourceIndex']
                : $localIndex;
            if ($globalSourceIndex < 0 || isset($itemsByGlobalIndex[$globalSourceIndex])) {
                return false;
            }
            $itemsByGlobalIndex[$globalSourceIndex] = $item;
        }

        $actualSourceIds = [];
        $actualGlobalIndexes = [];
        $pages = [];
        foreach ($proof['lines'] as $lineProof) {
            $lineSourceIds = is_array($lineProof['sourceOccurrenceIds'] ?? null)
                ? array_values($lineProof['sourceOccurrenceIds'])
                : [];
            $lineGlobalIndexes = is_array($lineProof['globalSourceIndexes'] ?? null)
                ? array_values($lineProof['globalSourceIndexes'])
                : [];
            $projectionDigest = is_string($lineProof['projectionDigest'] ?? null)
                ? $lineProof['projectionDigest']
                : '';
            if ($lineSourceIds === []
                || count($lineSourceIds) !== count($lineGlobalIndexes)
                || preg_match('/^[a-f0-9]{64}$/D', $projectionDigest) !== 1) {
                return false;
            }
            $lineProjection = '';
            $previousLineGlobalSourceIndex = null;
            foreach ($lineSourceIds as $sourceOffset => $sourceId) {
                $globalSourceIndex = $lineGlobalIndexes[$sourceOffset] ?? null;
                $item = is_int($globalSourceIndex)
                    ? ($itemsByGlobalIndex[$globalSourceIndex] ?? null)
                    : null;
                if (!is_string($sourceId)
                    || $sourceId === ''
                    || !is_int($globalSourceIndex)
                    || !is_array($item)
                    || ($item['id'] ?? null) !== $sourceId
                    || ($previousLineGlobalSourceIndex !== null
                        && $globalSourceIndex !== $previousLineGlobalSourceIndex + 1)) {
                    return false;
                }
                $itemProjection = $this->pdfSourceOccurrenceComparableText(
                    (string) ($item['text'] ?? '')
                );
                $page = (int) ($item['page'] ?? 0);
                if ($itemProjection === '' || $page < 1) {
                    return false;
                }
                $lineProjection .= $itemProjection;
                $pages[$page] = true;
                $actualSourceIds[] = $sourceId;
                $actualGlobalIndexes[] = $globalSourceIndex;
                $previousLineGlobalSourceIndex = $globalSourceIndex;
            }
            if (!hash_equals($projectionDigest, hash('sha256', $lineProjection))
                || !$this->pdfChartFontCipherLineIsCandidate($lineProjection)) {
                return false;
            }
        }

        return count($pages) === 1
            && $actualSourceIds === array_values($proof['sourceOccurrenceIds'])
            && $actualGlobalIndexes === array_values($proof['globalSourceIndexes'])
            && count(array_unique($actualSourceIds, SORT_STRING)) === count($actualSourceIds)
            && count(array_unique($actualGlobalIndexes, SORT_NUMERIC))
                === count($actualGlobalIndexes);
    }

    private function collapseRepeatedPdfResourceUrls(string $line): string
    {
        do {
            $before = $line;
            $line = preg_replace(
                '~\b((?:https?://|www\.)[^\s]+?)(?:\s*\1)+(?=\s|$)~iu',
                '$1',
                $line
            ) ?? $line;
        } while ($line !== $before);

        return $line;
    }

    private function collapseProvenRepeatedPdfResourceUrl(string $line, mixed $span): string
    {
        if (!$this->repairedPdfMergedLineHasExactWholeSourceSpan($line, $span)
            || !is_array($span)
            || count($span['sourceOccurrenceIds'] ?? []) !== 2
            || count($span['globalSourceIndexes'] ?? []) !== 2) {
            return $line;
        }
        $sourceIds = $span['sourceOccurrenceIds'];
        $sourceIndexes = $span['globalSourceIndexes'];
        $proof = $this->sourcePdfOverprintedDuplicateArtifactProofsBySourceId[
            $sourceIds[1]
        ] ?? null;
        if (!is_array($proof)
            || !$this->sourcePdfSignedProofDigestMatches($proof)
            || ($proof['retained']['sourceOccurrenceId'] ?? null) !== $sourceIds[0]
            || ($proof['artifact']['sourceOccurrenceId'] ?? null) !== $sourceIds[1]
            || ($proof['retained']['globalSourceIndex'] ?? null) !== $sourceIndexes[0]
            || ($proof['artifact']['globalSourceIndex'] ?? null) !== $sourceIndexes[1]) {
            return $line;
        }
        $collapsed = $this->collapseRepeatedPdfResourceUrls($line);
        if ($collapsed === $line) {
            return $line;
        }
        $sourceProjection = $this->pdfSourceOccurrenceComparableText($line);
        $collapsedProjection = $this->pdfSourceOccurrenceComparableText($collapsed);
        if ($collapsedProjection === ''
            || !hash_equals(
                (string) ($proof['projectionDigest'] ?? ''),
                hash('sha256', $collapsedProjection)
            )
            || !hash_equals($sourceProjection, $collapsedProjection . $collapsedProjection)) {
            return $line;
        }

        return $collapsed;
    }

    /**
     * Re-run only the final merge/render stage on the records which actually
     * survived semantic selection, grouped by their retained physical page.
     * This is compositor provenance, not a slice inferred from source byte
     * counts. A later gate accepts the sidecar only when these projections
     * concatenate exactly to the final transformed AST stream.
     *
     * @param list<array{text:string,layout:array<string,mixed>|null}> $records
     * @return array<int,string>|null
     */
    private function pdfConservativeRepairedOutputPageProjections(
        array $records,
        bool $repairGluedText
    ): ?array {
        if ($records === []) {
            return [];
        }

        $recordsByPage = [];
        $closedPages = [];
        $activePage = null;
        foreach ($records as $record) {
            $layout = is_array($record['layout'] ?? null) ? $record['layout'] : null;
            if (array_key_exists('sourcePdfOutputPage', $record)) {
                $page = is_int($record['sourcePdfOutputPage'])
                    ? $record['sourcePdfOutputPage']
                    : 0;
            } else {
                $page = is_int($layout['page'] ?? null)
                    ? $layout['page']
                    : (is_float($layout['page'] ?? null) ? (int) $layout['page'] : 0);
            }
            if ($page < 1) {
                return null;
            }
            if ($activePage !== null && $page !== $activePage) {
                $closedPages[$activePage] = true;
                if ($page < $activePage || isset($closedPages[$page])) {
                    return null;
                }
            }
            $activePage = $page;
            $recordsByPage[$page][] = $record;
        }

        $projections = [];
        foreach ($recordsByPage as $page => $pageRecords) {
            $exactWholeSourceMergedLineSpans = [];
            $merged = $this->mergeRepairedPdfRecords(
                $pageRecords,
                $exactWholeSourceMergedLineSpans
            );
            $retainedWholeSourceMergedLineSpans = [];
            $merged = $this->trimIncompletePdfMergedLinesBeforeStackedTables(
                $merged,
                $exactWholeSourceMergedLineSpans,
                $retainedWholeSourceMergedLineSpans
            );
            $finalWholeSourceMergedLineSpans = [];
            $lines = $this->finalizedRepairedPdfLines(
                $merged,
                $repairGluedText,
                $retainedWholeSourceMergedLineSpans,
                $finalWholeSourceMergedLineSpans
            );
            $blocks = $this->blocksFromLines($lines);
            $projection = $this->pdfSignificantProjectionFromBlocks($blocks);
            if ($projection !== '') {
                $projections[(int) $page] = $projection;
            }
        }
        ksort($projections, SORT_NUMERIC);

        return $projections;
    }

    /**
     * Remove flags which merely selected an exact source fallback. They must
     * not become a permanent semantic role or prevent ordinary paragraph and
     * table merging. Protection supplied independently by the front-matter or
     * inline-marker processors remains intact.
     *
     * @param list<array{text:string,layout:array<string,mixed>|null}> $records
     * @return list<array{text:string,layout:array<string,mixed>|null}>
     */
    private function normalizePdfExactSourceSemanticRecoveryRecords(array $records): array
    {
        foreach ($records as &$record) {
            $layout = is_array($record['layout'] ?? null) ? $record['layout'] : null;
            if (!is_array($layout)) {
                continue;
            }
            $fallbackSelected = ($layout['sourcePdfExactGeometryFallback'] ?? false) === true
                || ($layout['sourceUnmatchedFallback'] ?? false) === true
                || ($layout['sourcePdfFallbackOrderProjection'] ?? false) === true;
            unset(
                $layout['sourcePdfExactGeometryFallback'],
                $layout['sourcePdfPageExactInventoryPreserved'],
                $layout['sourceUnmatchedFallback'],
                $layout['sourcePdfFallbackOrderProjection']
            );
            if ($fallbackSelected
                && ($layout['sourcePdfFrontMatter'] ?? false) !== true
                && (int) ($layout['sourcePdfInlineMarkerCount'] ?? 0) < 1
                && !is_string($layout['sourcePdfRegionRole'] ?? null)) {
                unset($layout['sourcePdfProtectedSemanticContent']);
            }
            $record['layout'] = $layout;
        }
        unset($record);

        return $records;
    }

    /**
     * Join only repeated form-field tails whose source occurrences are exact
     * and consecutive.  This is deliberately directional: a currency glyph
     * attaches to the field identifier immediately before it, and a detached
     * identifier attaches backward only when a dotted form row and that
     * currency glyph form one consecutive triad.  Nothing is ever joined
     * forward from a currency field into the next instruction or notice.
     *
     * @param list<array{text:string,layout:array<string,mixed>|null}> $records
     * @return list<array{text:string,layout:array<string,mixed>|null}>
     */
    private function coalesceProvenPdfFormTailRecords(array $records): array
    {
        if (count($records) < 3) {
            return $records;
        }

        $hasStampedTailProof = static function (array $layout): bool {
            $wholeProof = is_array($layout['sourcePdfWholeExactOccurrenceProof'] ?? null)
                ? $layout['sourcePdfWholeExactOccurrenceProof']
                : null;
            $tailProof = is_array($layout['sourcePdfExactFormTailOccurrenceProof'] ?? null)
                ? $layout['sourcePdfExactFormTailOccurrenceProof']
                : null;

            return ($wholeProof !== null
                    && ($wholeProof['version'] ?? null) === 1
                    && ($wholeProof['method'] ?? null)
                        === 'source-inventory-whole-occurrence-union'
                    && is_array($wholeProof['occurrences'] ?? null)
                    && array_is_list($wholeProof['occurrences'])
                    && count($wholeProof['occurrences']) >= 2
                    && is_string($wholeProof['proofDigest'] ?? null)
                    && preg_match('/^[a-f0-9]{64}$/D', $wholeProof['proofDigest']) === 1)
                || ($tailProof !== null
                    && ($tailProof['version'] ?? null) === 1
                    && ($tailProof['method'] ?? null)
                        === 'source-inventory-exact-form-tail-occurrence'
                    && is_array($tailProof['ranges'] ?? null)
                    && array_is_list($tailProof['ranges'])
                    && count($tailProof['ranges']) >= 2
                    && is_array($tailProof['terminalOccurrence'] ?? null)
                    && is_string($tailProof['proofDigest'] ?? null)
                    && preg_match('/^[a-f0-9]{64}$/D', $tailProof['proofDigest']) === 1);
        };

        $tailCandidatesByPage = [];
        foreach ($records as $record) {
            $text = (string) ($record['text'] ?? '');
            $layout = is_array($record['layout'] ?? null) ? $record['layout'] : null;
            if (!is_array($layout)
                || preg_match(
                    '/\p{N}{1,3}(?:\p{L}|\(\p{L}\))?\s*\p{Sc}\s*$/u',
                    $text
                ) !== 1
                || !$hasStampedTailProof($layout)
                || $this->pdfSemanticRecordGlobalSourceIndexes($record) === []) {
                continue;
            }
            $page = max(1, (int) ($layout['page'] ?? 1));
            $tailCandidatesByPage[$page] = ($tailCandidatesByPage[$page] ?? 0) + 1;
        }
        for ($index = 1, $count = count($records); $index < $count; $index++) {
            $left = $records[$index - 1];
            $currency = $records[$index];
            $leftLayout = is_array($left['layout'] ?? null) ? $left['layout'] : null;
            $currencyLayout = is_array($currency['layout'] ?? null)
                ? $currency['layout']
                : null;
            if (!is_array($leftLayout)
                || !is_array($currencyLayout)
                || (int) ($leftLayout['page'] ?? 0)
                    !== (int) ($currencyLayout['page'] ?? 0)
                || ($currencyLayout['forceBlockBreakBefore'] ?? false) === true
                || ($leftLayout['code'] ?? false) === true
                || is_string($leftLayout['sourcePdfRegionRole'] ?? null)
                || preg_match(
                    '/\p{N}{1,3}(?:\p{L}|\(\p{L}\))?\s*$/u',
                    (string) ($left['text'] ?? '')
                ) !== 1
                || preg_match(
                    '/^\s*\p{Sc}\s*$/u',
                    (string) ($currency['text'] ?? '')
                ) !== 1) {
                continue;
            }
            $leftIndexes = $this->pdfSemanticRecordGlobalSourceIndexes($left);
            $currencyIndexes = $this->pdfSemanticRecordGlobalSourceIndexes($currency);
            if ($leftIndexes === []
                || $currencyIndexes === []
                || $leftIndexes[array_key_last($leftIndexes)] + 1 !== $currencyIndexes[0]) {
                continue;
            }
            $page = max(1, (int) ($currencyLayout['page'] ?? 1));
            $tailCandidatesByPage[$page] = ($tailCandidatesByPage[$page] ?? 0) + 1;
        }
        if (array_filter(
            $tailCandidatesByPage,
            static fn (int $count): bool => $count >= 3
        ) === []) {
            return $records;
        }

        return PdfExactFormRowTailRepair::coalesce($records, [
            'lineHasPdfListBlockEvidence' => $this->lineHasPdfListBlockEvidence(...),
            'lineIsOnlyPdfNoise' => $this->lineIsOnlyPdfNoise(...),
            'pdfLayoutHasGeometry' => $this->pdfLayoutHasGeometry(...),
            'pdfLineStartsWithSemanticPrefix' => $this->pdfLineStartsWithSemanticPrefix(...),
            'pdfLineWordTokens' => $this->pdfLineWordTokens(...),
            'pdfPositionedExactSourceRanges' => $this->pdfPositionedExactSourceRanges(...),
            'pdfSourceOccurrenceComparableText' =>
                $this->pdfSourceOccurrenceComparableText(...),
            'pdfTextWithoutSemanticPrefixes' => $this->pdfTextWithoutSemanticPrefixes(...),
            'positionedTableExactSourceRangesForItems' =>
                $this->positionedTableExactSourceRangesForItems(...),
            'repairedPdfWholeExactOccurrenceProofMatchesLayout' =>
                $this->repairedPdfWholeExactOccurrenceProofMatchesLayout(...),
        ]);
    }

    /**
     * A rebuilt form page assigns every consecutive source occurrence to the
     * currency tail which closes its row bundle. Attach only the immediate
     * final prose occurrence backward; ordinary prose repair can then consume
     * earlier wrapped lines from the left, while list delimiters and the next
     * row remain hard boundaries.
     *
     * @param array{text:string,layout:array<string,mixed>|null} $left
     * @param array{text:string,layout:array<string,mixed>|null} $tail
     */
    private function pdfRecordsShareExactFormRowBundleForBackwardTailAttachment(
        array $left,
        array $tail
    ): bool {
        $leftLayout = is_array($left['layout'] ?? null) ? $left['layout'] : null;
        $tailLayout = is_array($tail['layout'] ?? null) ? $tail['layout'] : null;
        if (!is_array($leftLayout)
            || !is_array($tailLayout)
            || ($leftLayout['sourcePdfFormTailEnd'] ?? false) === true
            || ($tailLayout['sourcePdfFormTailEnd'] ?? false) !== true
            || $this->pdfLineStartsWithSemanticPrefix((string) ($left['text'] ?? ''))
            || $this->lineHasPdfListBlockEvidence((string) ($left['text'] ?? ''))
            || $this->lineIsOnlyPdfNoise((string) ($left['text'] ?? ''))
            || $this->pdfPositionedExactSourceRanges($leftLayout) === []
            || $this->pdfPositionedExactSourceRanges($tailLayout) === []) {
            return false;
        }

        $leftProof = $this->pdfValidatedFormRowBundleProof($left);
        $tailProof = $this->pdfValidatedFormRowBundleProof($tail);
        if ($leftProof === null
            || $tailProof === null
            || !hash_equals($leftProof['proofDigest'], $tailProof['proofDigest'])) {
            return false;
        }
        $leftIndexes = $this->pdfSemanticRecordGlobalSourceIndexes($left);
        $tailIndexes = $this->pdfSemanticRecordGlobalSourceIndexes($tail);

        return $leftIndexes !== []
            && $tailIndexes !== []
            && $tailIndexes[0] === $leftIndexes[array_key_last($leftIndexes)] + 1
            && $tailIndexes[array_key_last($tailIndexes)] === $tailProof['sourceEndIndex'];
    }

    /**
     * @param array{text:string,layout:array<string,mixed>|null} $record
     * @return array<string,mixed>|null
     */
    private function pdfValidatedFormRowBundleProof(array $record): ?array
    {
        $layout = is_array($record['layout'] ?? null) ? $record['layout'] : null;
        $proof = is_array($layout['sourcePdfFormRowBundleProof'] ?? null)
            ? $layout['sourcePdfFormRowBundleProof']
            : null;
        if (!is_array($layout)
            || $proof === null
            || ($proof['version'] ?? null) !== 1
            || ($proof['method'] ?? null) !== 'exact-source-occurrence-form-row-bundle'
            || !is_int($proof['page'] ?? null)
            || !is_int($proof['sourceStartIndex'] ?? null)
            || !is_int($proof['sourceEndIndex'] ?? null)
            || $proof['sourceStartIndex'] < 0
            || $proof['sourceEndIndex'] < $proof['sourceStartIndex']
            || !is_float($proof['tailCenter'] ?? null)
            || !is_float($proof['tailX2'] ?? null)
            || !is_string($proof['proofDigest'] ?? null)
            || max(1, (int) ($layout['page'] ?? 1)) !== $proof['page']) {
            return null;
        }
        $payload = $proof;
        unset($payload['proofDigest']);
        $digest = hash('sha256', json_encode(
            $payload,
            JSON_UNESCAPED_SLASHES
                | JSON_UNESCAPED_UNICODE
                | JSON_PRESERVE_ZERO_FRACTION
        ) ?: '');
        if (!hash_equals($proof['proofDigest'], $digest)) {
            return null;
        }
        $sourceIndexes = $this->pdfSemanticRecordGlobalSourceIndexes($record);
        $ranges = $this->pdfPositionedExactSourceRanges($layout);
        $rangeIndexes = [];
        foreach ($ranges as $range) {
            $lastIndex = array_key_last($rangeIndexes);
            if ($lastIndex !== null && $rangeIndexes[$lastIndex] === $range['sourceIndex']) {
                continue;
            }
            if ($lastIndex !== null
                && $range['sourceIndex'] !== $rangeIndexes[$lastIndex] + 1) {
                return null;
            }
            $rangeIndexes[] = $range['sourceIndex'];
        }
        if ($sourceIndexes === [] || $rangeIndexes !== $sourceIndexes) {
            return null;
        }
        foreach ($sourceIndexes as $sourceIndex) {
            if ($sourceIndex < $proof['sourceStartIndex']
                || $sourceIndex > $proof['sourceEndIndex']) {
                return null;
            }
        }

        return $proof;
    }

    /**
     * Preserve recurring exact brace delimiters without emitting four
     * punctuation-only paragraphs. A proved `{`, two or more consecutive
     * bullet occurrences, and a proved `}` must occupy one immutable form-row
     * bundle; a second geometrically comparable pair on the page establishes
     * the visual convention. The opening brace joins the preceding lead and
     * the closer joins the final bullet, so source character order is retained
     * and the list-marker processor still sees one contiguous bullet run.
     *
     * @param list<array{text:string,layout:array<string,mixed>|null}> $records
     * @return list<array{text:string,layout:array<string,mixed>|null}>
     */
    private function foldExactPdfBraceDelimitedListRecords(array $records): array
    {
        $pairs = [];
        for ($openIndex = 1, $count = count($records); $openIndex < $count - 2; $openIndex++) {
            $open = $records[$openIndex];
            $openLayout = is_array($open['layout'] ?? null) ? $open['layout'] : null;
            $openProjection = $this->pdfSourceOccurrenceComparableText(
                (string) ($open['text'] ?? '')
            );
            if ($openProjection !== '{'
                || !is_array($openLayout)
                || !$this->pdfLayoutHasGeometry($openLayout)
                || !$this->repairedPdfWholeExactOccurrenceProofMatchesLayout(
                    $openLayout,
                    $openProjection
                )) {
                continue;
            }

            $closeIndex = null;
            $bulletIndexes = [];
            for ($candidateIndex = $openIndex + 1;
                $candidateIndex < min($count, $openIndex + 8);
                $candidateIndex++) {
                $candidateText = (string) ($records[$candidateIndex]['text'] ?? '');
                if (trim($candidateText) === '}') {
                    $closeIndex = $candidateIndex;
                    break;
                }
                if (preg_match(
                    '/^\h*[\x{2022}\x{25CF}\x{25AA}\x{25E6}\x{2023}\x{2043}]\h+\S/u',
                    $candidateText
                ) !== 1) {
                    $bulletIndexes = [];
                    break;
                }
                $bulletIndexes[] = $candidateIndex;
            }
            if ($closeIndex === null || count($bulletIndexes) < 2) {
                continue;
            }

            $close = $records[$closeIndex];
            $closeLayout = is_array($close['layout'] ?? null) ? $close['layout'] : null;
            $closeProjection = $this->pdfSourceOccurrenceComparableText(
                (string) ($close['text'] ?? '')
            );
            if ($closeProjection !== '}'
                || !is_array($closeLayout)
                || !$this->pdfLayoutHasGeometry($closeLayout)
                || !$this->repairedPdfWholeExactOccurrenceProofMatchesLayout(
                    $closeLayout,
                    $closeProjection
                )) {
                continue;
            }

            $memberIndexes = [$openIndex, ...$bulletIndexes, $closeIndex];
            $bundleDigest = null;
            $sourceIndexes = [];
            $membersAreExact = true;
            foreach ($memberIndexes as $memberIndex) {
                $member = $records[$memberIndex];
                $bundleProof = $this->pdfValidatedFormRowBundleProof($member);
                $memberSourceIndexes = $this->pdfSemanticRecordGlobalSourceIndexes($member);
                if ($bundleProof === null || $memberSourceIndexes === []) {
                    $membersAreExact = false;
                    break;
                }
                if ($bundleDigest === null) {
                    $bundleDigest = $bundleProof['proofDigest'];
                } elseif (!hash_equals($bundleDigest, $bundleProof['proofDigest'])) {
                    $membersAreExact = false;
                    break;
                }
                array_push($sourceIndexes, ...$memberSourceIndexes);
            }
            $leadIndexes = $this->pdfSemanticRecordGlobalSourceIndexes($records[$openIndex - 1]);
            if (!$membersAreExact
                || $leadIndexes === []
                || $sourceIndexes === []
                || $sourceIndexes[0] !== $leadIndexes[array_key_last($leadIndexes)] + 1) {
                continue;
            }
            for ($sourceOffset = 1; $sourceOffset < count($sourceIndexes); $sourceOffset++) {
                if ($sourceIndexes[$sourceOffset] !== $sourceIndexes[$sourceOffset - 1] + 1) {
                    $membersAreExact = false;
                    break;
                }
            }
            $leadProof = $this->pdfValidatedFormRowBundleProof($records[$openIndex - 1]);
            if (!$membersAreExact
                || $leadProof === null
                || !hash_equals($bundleDigest, $leadProof['proofDigest'])) {
                continue;
            }

            $fontSizes = [];
            foreach ($bulletIndexes as $bulletIndex) {
                $bulletLayout = is_array($records[$bulletIndex]['layout'] ?? null)
                    ? $records[$bulletIndex]['layout']
                    : null;
                if (!$this->pdfLayoutHasGeometry($bulletLayout)) {
                    $fontSizes = [];
                    break;
                }
                $fontSizes[] = max(1.0, (float) $bulletLayout['fontSize']);
            }
            if ($fontSizes === []) {
                continue;
            }
            $openHeight = max(1.0, (float) $openLayout['y2'] - (float) $openLayout['y1']);
            $closeHeight = max(1.0, (float) $closeLayout['y2'] - (float) $closeLayout['y1']);
            $height = max($openHeight, $closeHeight);
            $heightTolerance = max(2.0, $height * 0.08);
            $width = (float) $closeLayout['x2'] - (float) $openLayout['x1'];
            if ((int) ($openLayout['page'] ?? 0) !== (int) ($closeLayout['page'] ?? 0)
                || $this->pdfSemanticRecordSourceStreams($open)
                    !== $this->pdfSemanticRecordSourceStreams($close)
                || (float) $closeLayout['x1'] <= (float) $openLayout['x2']
                || abs((float) $openLayout['y1'] - (float) $closeLayout['y1']) > $heightTolerance
                || abs((float) $openLayout['y2'] - (float) $closeLayout['y2']) > $heightTolerance
                || $height < max(12.0, $this->median($fontSizes) * 1.35)
                || $width < $height * 4.0) {
                continue;
            }

            $pairs[] = [
                'openIndex' => $openIndex,
                'closeIndex' => $closeIndex,
                'page' => max(1, (int) ($openLayout['page'] ?? 1)),
                'streams' => $this->pdfSemanticRecordSourceStreams($open),
                'center' => ((float) $openLayout['y1'] + (float) $openLayout['y2']) / 2.0,
                'width' => $width,
                'height' => $height,
                'sourceIndexes' => $sourceIndexes,
                'bundleDigest' => $bundleDigest,
            ];
        }
        if (count($pairs) < 2) {
            return $records;
        }

        $provedPairs = [];
        foreach ($pairs as $pairIndex => $pair) {
            $recurring = 0;
            foreach ($pairs as $candidateIndex => $candidate) {
                if ($candidate['page'] !== $pair['page']
                    || $candidate['streams'] !== $pair['streams']
                    || abs($candidate['width'] - $pair['width']) > max(18.0, $pair['width'] * 0.20)
                    || abs($candidate['height'] - $pair['height']) > max(3.0, $pair['height'] * 0.12)
                    || ($candidateIndex !== $pairIndex
                        && abs($candidate['center'] - $pair['center']) < max(12.0, $pair['height']))) {
                    continue;
                }
                $recurring++;
            }
            if ($recurring >= 2) {
                $provedPairs[] = $pair + ['recurringPairCount' => $recurring];
            }
        }
        if ($provedPairs === []) {
            return $records;
        }

        $folds = [];
        foreach ($provedPairs as $pair) {
            $identity = [
                'method' => 'exact-recurring-brace-delimited-list-fold',
                'page' => $pair['page'],
                'streams' => $pair['streams'],
                'sourceIndexes' => $pair['sourceIndexes'],
                'bundleDigest' => $pair['bundleDigest'],
                'recurringPairCount' => $pair['recurringPairCount'],
            ];
            $identity['proofDigest'] = hash('sha256', json_encode(
                $identity,
                JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE
            ) ?: '');
            $folds[$pair['openIndex']] = $identity;
            $folds[$pair['closeIndex']] = $identity;
        }

        $folded = [];
        foreach ($records as $recordIndex => $record) {
            if (!isset($folds[$recordIndex])) {
                $folded[] = $record;
                continue;
            }
            $lastIndex = array_key_last($folded);
            if ($lastIndex === null) {
                return $records;
            }
            $merged = $this->mergeProvenPdfFormTailRecords($folded[$lastIndex], $record);
            unset(
                $merged['layout']['sourcePdfFormTailComposite'],
                $merged['layout']['sourcePdfFormTailEnd'],
                $merged['layout']['sourcePdfFormTailProof']
            );
            $merged['layout']['sourcePdfBraceDelimitedListFoldProof'] = $folds[$recordIndex];
            $folded[$lastIndex] = $merged;
        }

        return $folded;
    }

    /**
     * @param list<string> $lines
     * @param list<array<string,mixed>> $layouts
     * @param list<array<string,mixed>> $sourceItems
     * @return array{lines:list<string>,layouts:list<array<string,mixed>>,geometryPageNumbers:list<int>}
     */
    private function pdfRepairSourceInProvenNestedCautionCalloutOrder(
        array $lines,
        array $layouts,
        array $sourceItems
    ): array {
        $unchanged = static fn (): array => [
            'lines' => $lines,
            'layouts' => $layouts,
            'geometryPageNumbers' => [],
        ];
        if ($lines === []
            || count($lines) !== count($layouts)
            || $sourceItems === []) {
            return $unchanged();
        }
        foreach ($layouts as $index => $layout) {
            if (!is_array($layout)
                || (string) ($layout['text'] ?? '') !== (string) ($lines[$index] ?? '')) {
                return $unchanged();
            }
        }
        if ($this->sourcePdfStampedNestedCautionCalloutProofs($sourceItems) === []) {
            return $unchanged();
        }

        return $this->invokePdfNestedCautionCalloutRepair(
            'pdfRepairSourceInProvenNestedCautionCalloutOrder',
            [$lines, $layouts, $sourceItems]
        );
    }

    /**
     * Restore the canonical source-occurrence prefix on a page whose repeated
     * exact currency tails independently prove a vertically ordered form.
     * Positioned line construction may interleave the next row's left label
     * ahead of the prior row's right field, and it may combine two list items
     * painted on one baseline. Rebuilding only a completely covered source
     * prefix keeps each row bundle in logical source order while tail geometry
     * proves that those bundles already descend in visual order.
     *
     * The replacement happens before semantic repair and before source-order
     * proof layouts are captured. A later record-only permutation would leave
     * that proof sidecar stale and must remain fail-closed.
     *
     * @param list<string> $lines
     * @param list<array<string,mixed>> $layouts
     * @param list<array<string,mixed>> $sourceItems
     * @return array{lines:list<string>,layouts:list<array<string,mixed>>,geometryPageNumbers:list<int>}
     */
    private function pdfRepairSourceInProvenFormRowBundleOrder(
        array $lines,
        array $layouts,
        array $sourceItems
    ): array {
        $unchanged = static fn (): array => [
            'lines' => $lines,
            'layouts' => $layouts,
            'geometryPageNumbers' => [],
        ];
        if ($lines === []
            || count($lines) !== count($layouts)
            || $sourceItems === []) {
            return $unchanged();
        }

        $tailCandidatesByPage = [];
        foreach ($lines as $index => $line) {
            $layout = is_array($layouts[$index] ?? null) ? $layouts[$index] : null;
            if (!is_array($layout)
                || (string) ($layout['text'] ?? '') !== $line
                || preg_match(
                    '/\p{N}{1,3}(?:\p{L}|\(\p{L}\))?\s*\p{Sc}\s*$/u',
                    $line
                ) !== 1) {
                continue;
            }
            foreach (['x1', 'y1', 'x2', 'y2', 'fontSize'] as $geometryKey) {
                if (!is_numeric($layout[$geometryKey] ?? null)) {
                    continue 2;
                }
            }

            $sourceIndex = null;
            $wholeProof = is_array($layout['sourcePdfWholeExactOccurrenceProof'] ?? null)
                ? $layout['sourcePdfWholeExactOccurrenceProof']
                : null;
            if ($wholeProof !== null
                && ($wholeProof['version'] ?? null) === 1
                && ($wholeProof['method'] ?? null)
                    === 'source-inventory-whole-occurrence-union'
                && is_array($wholeProof['occurrences'] ?? null)
                && array_is_list($wholeProof['occurrences'])
                && count($wholeProof['occurrences']) >= 2
                && is_string($wholeProof['proofDigest'] ?? null)
                && preg_match('/^[a-f0-9]{64}$/D', $wholeProof['proofDigest']) === 1) {
                $terminal = $wholeProof['occurrences'][array_key_last(
                    $wholeProof['occurrences']
                )];
                $sourceIndex = is_array($terminal)
                    && is_int($terminal['sourceIndex'] ?? null)
                    ? $terminal['sourceIndex']
                    : null;
            }
            $tailProof = is_array($layout['sourcePdfExactFormTailOccurrenceProof'] ?? null)
                ? $layout['sourcePdfExactFormTailOccurrenceProof']
                : null;
            if ($sourceIndex === null
                && $tailProof !== null
                && ($tailProof['version'] ?? null) === 1
                && ($tailProof['method'] ?? null)
                    === 'source-inventory-exact-form-tail-occurrence'
                && is_array($tailProof['ranges'] ?? null)
                && array_is_list($tailProof['ranges'])
                && count($tailProof['ranges']) >= 2
                && is_array($tailProof['terminalOccurrence'] ?? null)
                && is_int($tailProof['terminalOccurrence']['sourceIndex'] ?? null)
                && is_string($tailProof['proofDigest'] ?? null)
                && preg_match('/^[a-f0-9]{64}$/D', $tailProof['proofDigest']) === 1) {
                $sourceIndex = $tailProof['terminalOccurrence']['sourceIndex'];
            }
            if ($sourceIndex === null) {
                continue;
            }

            $page = max(1, (int) ($layout['page'] ?? 1));
            $tailCandidatesByPage[$page] = ($tailCandidatesByPage[$page] ?? 0) + 1;
        }
        if (array_filter(
            $tailCandidatesByPage,
            static fn (int $count): bool => $count >= 3
        ) === []) {
            return $unchanged();
        }

        return PdfExactFormRowTailRepair::reorder(
            $lines,
            $layouts,
            $sourceItems,
            [
                'lineHasPdfListBlockEvidence' => $this->lineHasPdfListBlockEvidence(...),
                'markSourcePdfVerifiedGeometryText' =>
                    $this->markSourcePdfVerifiedGeometryText(...),
                'median' => $this->median(...),
                'pdfLayoutHasGeometry' => $this->pdfLayoutHasGeometry(...),
                'pdfLineStartsWithSemanticPrefix' =>
                    $this->pdfLineStartsWithSemanticPrefix(...),
                'pdfPositionedExactSourceRanges' =>
                    $this->pdfPositionedExactSourceRanges(...),
                'pdfSourceBoundsAreValid' => $this->pdfSourceBoundsAreValid(...),
                'pdfSourceEvidenceBounds' => $this->pdfSourceEvidenceBounds(...),
                'pdfSourceLayoutsWithWholeExactOccurrenceProofs' =>
                    $this->pdfSourceLayoutsWithWholeExactOccurrenceProofs(...),
                'pdfSourceOccurrenceComparableText' =>
                    $this->pdfSourceOccurrenceComparableText(...),
                'pdfTextWithoutSemanticPrefixes' =>
                    $this->pdfTextWithoutSemanticPrefixes(...),
                'repairedPdfWholeExactOccurrenceProofMatchesLayout' =>
                    $this->repairedPdfWholeExactOccurrenceProofMatchesLayout(...),
                'sourcePdfLineItem' => $this->sourcePdfLineItem(...),
                'sourcePdfSourceItemHasExactGeometry' =>
                    $this->sourcePdfSourceItemHasExactGeometry(...),
            ]
        );
    }

    /**
     * Recognize a form tail that an earlier exact-layout pass already rebuilt
     * as one record. The final currency glyph must still be its own complete
     * source occurrence; a text suffix that merely resembles a field is not
     * enough to establish the hard row boundary.
     *
     * @param array{text:string,layout:array<string,mixed>|null} $record
     * @return array<string,mixed>|null
     */
    private function pdfRecordProvenCompositeCurrencyTailProof(array $record): ?array
    {
        if (!$this->pdfRecordIsEligibleForExactFormTailMerge($record)) {
            return null;
        }
        $layout = $record['layout'];
        $projection = $this->pdfSourceOccurrenceComparableText(
            $this->pdfTextWithoutSemanticPrefixes((string) ($record['text'] ?? ''))
        );
        if ($projection === ''
            || preg_match('/\p{N}{1,3}(?:\p{L}|\(\p{L}\))?\p{Sc}$/u', $projection) !== 1) {
            return null;
        }

        $currencyOccurrence = null;
        $sourceProofDigest = null;
        if ($this->repairedPdfWholeExactOccurrenceProofMatchesLayout($layout, $projection)) {
            $wholeProof = $layout['sourcePdfWholeExactOccurrenceProof'];
            $occurrences = array_values($wholeProof['occurrences']);
            if (count($occurrences) >= 2) {
                $currencyOccurrence = $occurrences[array_key_last($occurrences)];
                $sourceProofDigest = $wholeProof['proofDigest'];
            }
        } elseif ($this->pdfExactFormTailOccurrenceProofMatchesLayout($layout, $projection)) {
            $exactTailProof = $layout['sourcePdfExactFormTailOccurrenceProof'];
            $currencyOccurrence = $exactTailProof['terminalOccurrence'];
            $sourceProofDigest = $exactTailProof['proofDigest'];
        }
        if (!is_array($currencyOccurrence) || !is_string($sourceProofDigest)) {
            return null;
        }
        $currencyBytes = $currencyOccurrence['significantBytes'];
        $currencyProjection = substr($projection, -$currencyBytes);
        $carrierProjection = substr($projection, 0, strlen($projection) - $currencyBytes);
        if ($currencyProjection === ''
            || $carrierProjection === ''
            || preg_match('/^\p{Sc}$/u', $currencyProjection) !== 1
            || preg_match('/\p{N}{1,3}(?:\p{L}|\(\p{L}\))?$/u', $carrierProjection) !== 1) {
            return null;
        }

        $proof = [
            'version' => 1,
            'method' => 'exact-source-composite-form-tail',
            'sourceIndexes' => $this->pdfSemanticRecordGlobalSourceIndexes($record),
            'currencySourceIndex' => $currencyOccurrence['sourceIndex'],
            'sourceOccurrenceProofDigest' => $sourceProofDigest,
            'tailProjectionDigest' => hash('sha256', $currencyProjection),
        ];
        $proof['proofDigest'] = hash('sha256', json_encode(
            $proof,
            JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE
        ) ?: '');

        return $proof;
    }

    /** @param array<string,mixed> $layout */
    private function pdfExactFormTailOccurrenceProofMatchesLayout(
        array $layout,
        string $carrierProjection
    ): bool {
        $proof = is_array($layout['sourcePdfExactFormTailOccurrenceProof'] ?? null)
            ? $layout['sourcePdfExactFormTailOccurrenceProof']
            : null;
        if ($proof === null
            || ($proof['version'] ?? null) !== 1
            || ($proof['method'] ?? null) !== 'source-inventory-exact-form-tail-occurrence'
            || !is_int($proof['page'] ?? null)
            || !is_array($proof['ranges'] ?? null)
            || !array_is_list($proof['ranges'])
            || !is_array($proof['terminalOccurrence'] ?? null)
            || !is_string($proof['projectionDigest'] ?? null)
            || !is_string($proof['proofDigest'] ?? null)
            || (int) ($layout['page'] ?? 0) !== $proof['page']
            || $this->pdfPositionedExactSourceRanges($layout) !== array_values($proof['ranges'])
            || !hash_equals($proof['projectionDigest'], hash('sha256', $carrierProjection))) {
            return false;
        }

        $terminal = $proof['terminalOccurrence'];
        $ranges = array_values($proof['ranges']);
        $terminalRange = $ranges[array_key_last($ranges)] ?? null;
        if (!is_array($terminalRange)
            || !is_int($terminal['sourceIndex'] ?? null)
            || !is_int($terminal['sourceLocalIndex'] ?? null)
            || ($terminal['page'] ?? null) !== $proof['page']
            || !is_int($terminal['stream'] ?? null)
            || $terminal['stream'] < 1
            || !is_int($terminal['significantBytes'] ?? null)
            || $terminal['significantBytes'] <= 0
            || !is_string($terminal['significantDigest'] ?? null)
            || preg_match('/^[a-f0-9]{64}$/D', $terminal['significantDigest']) !== 1
            || $terminalRange !== [
                'sourceIndex' => $terminal['sourceIndex'],
                'sourceStart' => 0,
                'sourceEnd' => $terminal['significantBytes'],
            ]) {
            return false;
        }
        $terminalProjection = substr($carrierProjection, -$terminal['significantBytes']);
        if (strlen($terminalProjection) !== $terminal['significantBytes']
            || preg_match('/^\p{Sc}$/u', $terminalProjection) !== 1
            || !hash_equals(
                $terminal['significantDigest'],
                hash('sha256', $terminalProjection)
            )) {
            return false;
        }

        $payload = [
            'version' => 1,
            'method' => 'source-inventory-exact-form-tail-occurrence',
            'page' => $proof['page'],
            'ranges' => $ranges,
            'terminalOccurrence' => $terminal,
            'projectionDigest' => $proof['projectionDigest'],
        ];
        $expectedDigest = hash('sha256', json_encode(
            $payload,
            JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE
        ) ?: '');

        return hash_equals($proof['proofDigest'], $expectedDigest);
    }

    /**
     * @param array{text:string,layout:array<string,mixed>|null} $left
     * @param array{text:string,layout:array<string,mixed>|null} $currency
     */
    private function pdfRecordsFormProvenCurrencyTail(array $left, array $currency): bool
    {
        $currencyLayout = is_array($currency['layout'] ?? null) ? $currency['layout'] : null;

        return preg_match('/^\p{Sc}$/u', trim((string) ($currency['text'] ?? ''))) === 1
            && is_array($currencyLayout)
            && (($currencyLayout['forceBlockBreakBefore'] ?? false) !== true)
            && $this->pdfRecordLooksLikeFormFieldCarrier($left)
            && $this->pdfRecordsHaveConsecutiveSourceOccurrences($left, $currency);
    }

    /** @param array{text:string,layout:array<string,mixed>|null} $record */
    private function pdfRecordLooksLikeFormFieldCarrier(array $record): bool
    {
        $text = trim((string) ($record['text'] ?? ''));

        return $this->pdfRecordIsEligibleForExactFormTailMerge($record)
            && preg_match('/\p{N}{1,3}(?:\p{L}|\(\p{L}\))?\h*$/u', $text) === 1;
    }

    /** @param array{text:string,layout:array<string,mixed>|null} $record */
    private function pdfRecordLooksLikeCompactFormFieldId(array $record): bool
    {
        return $this->pdfRecordIsEligibleForExactFormTailMerge($record)
            && preg_match(
                '/^\p{N}{1,3}(?:\p{L}|\(\p{L}\))?$/u',
                trim((string) ($record['text'] ?? ''))
            ) === 1;
    }

    /** @param array{text:string,layout:array<string,mixed>|null} $record */
    private function pdfRecordEndsWithDottedFormLeader(array $record): bool
    {
        if (!$this->pdfRecordIsEligibleForExactFormTailMerge($record)
            || count($this->pdfLineWordTokens((string) ($record['text'] ?? ''))) < 4) {
            return false;
        }

        return preg_match(
            '/(?:(?:\.\h*){4,}|(?:\.\h+){1,}\.)'
                . '(?:\h*\p{N}{1,3}(?:\p{L}|\(\p{L}\))?)?\h*$/u',
            trim((string) ($record['text'] ?? ''))
        ) === 1;
    }

    /** @param array{text:string,layout:array<string,mixed>|null} $record */
    private function pdfRecordIsEligibleForExactFormTailMerge(array $record): bool
    {
        $text = (string) ($record['text'] ?? '');
        $layout = is_array($record['layout'] ?? null) ? $record['layout'] : null;
        if ($text === ''
            || !is_array($layout)
            || $this->pdfLineStartsWithSemanticPrefix($text)
            || ($layout['code'] ?? false) === true
            || is_string($layout['sourcePdfRegionRole'] ?? null)
            || ($layout['sourcePdfLayoutLabel'] ?? false) === true
            || ($layout['sourcePdfFrontMatter'] ?? false) === true
            || ($layout['sourceSupplementalPositioned'] ?? false) === true
            || (int) ($layout['sourcePdfInlineMarkerCount'] ?? 0) > 0
            || $this->lineHasPdfListBlockEvidence($text)) {
            return false;
        }

        $layoutText = is_string($layout['text'] ?? null) ? $layout['text'] : '';

        return $layoutText !== ''
            && hash_equals(
                $this->pdfSourceOccurrenceComparableText($layoutText),
                $this->pdfSourceOccurrenceComparableText($text)
            )
            && $this->pdfSemanticRecordGlobalSourceIndexes($record) !== [];
    }

    /**
     * @param array{text:string,layout:array<string,mixed>|null} $left
     * @param array{text:string,layout:array<string,mixed>|null} $right
     */
    private function pdfRecordsHaveConsecutiveSourceOccurrences(array $left, array $right): bool
    {
        if (!$this->pdfRecordIsEligibleForExactFormTailMerge($left)
            || !$this->pdfRecordIsEligibleForExactFormTailMerge($right)) {
            return false;
        }
        $leftLayout = $left['layout'];
        $rightLayout = $right['layout'];
        if ((int) ($leftLayout['page'] ?? 0) !== (int) ($rightLayout['page'] ?? 0)) {
            return false;
        }
        $leftIndexes = $this->pdfSemanticRecordGlobalSourceIndexes($left);
        $rightIndexes = $this->pdfSemanticRecordGlobalSourceIndexes($right);
        if ($leftIndexes === []
            || $rightIndexes === []
            || $leftIndexes[array_key_last($leftIndexes)] + 1 !== $rightIndexes[0]) {
            return false;
        }

        $leftStreams = $this->pdfSemanticRecordSourceStreams($left);
        $rightStreams = $this->pdfSemanticRecordSourceStreams($right);
        if (count($leftStreams) === 1
            && count($rightStreams) === 1
            && $leftStreams[0] === $rightStreams[0]) {
            return true;
        }

        // A page can paint one form field through adjacent /Contents streams.
        // Crossing that boundary additionally requires exact inline geometry;
        // document-global adjacency by itself is not a visual-order proof.
        if (!$this->pdfLayoutHasGeometry($leftLayout)
            || !$this->pdfLayoutHasGeometry($rightLayout)) {
            return false;
        }
        $fontSize = max(1.0, (float) $leftLayout['fontSize'], (float) $rightLayout['fontSize']);
        $leftCenter = ((float) $leftLayout['y1'] + (float) $leftLayout['y2']) / 2.0;
        $rightCenter = ((float) $rightLayout['y1'] + (float) $rightLayout['y2']) / 2.0;
        $horizontalGap = (float) $rightLayout['x1'] - (float) $leftLayout['x2'];

        return abs($leftCenter - $rightCenter) <= max(2.0, $fontSize * 0.30)
            && (float) $rightLayout['x1'] >= (float) $leftLayout['x1']
            && $horizontalGap >= -max(2.0, $fontSize * 0.20)
            && $horizontalGap <= max(24.0, $fontSize * 2.0);
    }

    /**
     * @param array{text:string,layout:array<string,mixed>|null} $record
     * @return list<int>
     */
    private function pdfSemanticRecordGlobalSourceIndexes(array $record): array
    {
        $layout = is_array($record['layout'] ?? null) ? $record['layout'] : null;
        if (!is_array($layout)) {
            return [];
        }
        $candidates = [];
        if (is_array($layout['sourcePdfGlobalSourceIndexes'] ?? null)) {
            $candidates = $layout['sourcePdfGlobalSourceIndexes'];
        } else {
            $ranges = $this->pdfPositionedExactSourceRanges($layout);
            if ($ranges !== []) {
                foreach ($ranges as $range) {
                    if ($candidates === [] || $candidates[array_key_last($candidates)] !== $range['sourceIndex']) {
                        $candidates[] = $range['sourceIndex'];
                    }
                }
            } elseif (is_int($layout['sourcePdfGlobalSourceIndex'] ?? null)) {
                $candidates = [$layout['sourcePdfGlobalSourceIndex']];
            }
        }
        $indexes = [];
        foreach ($candidates as $candidate) {
            if (!is_int($candidate)
                || $candidate < 0
                || ($indexes !== [] && $candidate !== $indexes[array_key_last($indexes)] + 1)) {
                return [];
            }
            $indexes[] = $candidate;
        }

        return $indexes;
    }

    /**
     * @param array{text:string,layout:array<string,mixed>|null} $record
     * @return list<int>
     */
    private function pdfSemanticRecordSourceStreams(array $record): array
    {
        $layout = is_array($record['layout'] ?? null) ? $record['layout'] : null;
        if (!is_array($layout)) {
            return [];
        }
        $candidates = is_array($layout['sourcePdfStreams'] ?? null)
            ? $layout['sourcePdfStreams']
            : (isset($layout['sourceStream']) && is_numeric($layout['sourceStream'])
                ? [(int) $layout['sourceStream']]
                : (isset($layout['stream']) && is_numeric($layout['stream'])
                    ? [(int) $layout['stream']]
                    : []));
        $streams = [];
        foreach ($candidates as $candidate) {
            if (!is_int($candidate) && !is_numeric($candidate)) {
                return [];
            }
            $streams[(int) $candidate] = true;
        }
        $streams = array_keys($streams);
        sort($streams, SORT_NUMERIC);

        return $streams;
    }

    /**
     * @param array{text:string,layout:array<string,mixed>|null} $left
     * @param array{text:string,layout:array<string,mixed>|null} $right
     * @return array{text:string,layout:array<string,mixed>}
     */
    private function mergeProvenPdfFormTailRecords(array $left, array $right): array
    {
        $text = rtrim($left['text']) . ' ' . ltrim($right['text']);
        $leftLayout = is_array($left['layout'] ?? null) ? $left['layout'] : [];
        $rightLayout = is_array($right['layout'] ?? null) ? $right['layout'] : [];
        $layout = $leftLayout;
        $sourceIds = [];
        foreach ([$leftLayout, $rightLayout] as $sourceLayout) {
            $ids = is_array($sourceLayout['sourcePdfSourceIds'] ?? null)
                ? $sourceLayout['sourcePdfSourceIds']
                : (is_string($sourceLayout['id'] ?? null) && $sourceLayout['id'] !== ''
                    ? [$sourceLayout['id']]
                    : []);
            foreach ($ids as $id) {
                if (is_string($id) && $id !== '') {
                    $sourceIds[$id] = true;
                }
            }
        }

        $proofItems = [
            array_replace($leftLayout, ['text' => $left['text']]),
            array_replace($rightLayout, ['text' => $right['text']]),
        ];
        $exactRanges = $this->positionedTableExactSourceRangesForItems($proofItems);
        $indexCandidates = $exactRanges !== null && $exactRanges !== []
            ? array_column($exactRanges, 'sourceIndex')
            : array_merge(
                $this->pdfSemanticRecordGlobalSourceIndexes($left),
                $this->pdfSemanticRecordGlobalSourceIndexes($right)
            );
        $indexes = [];
        foreach ($indexCandidates as $sourceIndex) {
            $lastIndex = array_key_last($indexes);
            if ($lastIndex !== null && $indexes[$lastIndex] === $sourceIndex) {
                continue;
            }
            if (!is_int($sourceIndex)
                || $sourceIndex < 0
                || ($lastIndex !== null && $sourceIndex !== $indexes[$lastIndex] + 1)) {
                $indexes = [];
                break;
            }
            $indexes[] = $sourceIndex;
        }
        $streams = array_values(array_unique(array_merge(
            $this->pdfSemanticRecordSourceStreams($left),
            $this->pdfSemanticRecordSourceStreams($right)
        ), SORT_NUMERIC));
        sort($streams, SORT_NUMERIC);

        unset(
            $layout['id'],
            $layout['sourcePdfGlobalSourceIndex'],
            $layout['sourcePdfSourceIndex'],
            $layout['sourcePdfSourceIndexEnd'],
            $layout['sourcePdfSourceIndexes'],
            $layout['sourcePdfExactSourceIndex'],
            $layout['sourcePdfExactSourceStart'],
            $layout['sourcePdfExactSourceEnd'],
            $layout['sourcePdfExactSourceRanges'],
            $layout['sourcePdfWholeExactOccurrenceProof'],
            $layout['sourceStream'],
            $layout['stream']
        );
        $layout['text'] = $text;
        $layout['sourcePdfGlobalSourceIndexes'] = $indexes;
        if ($sourceIds !== []) {
            $layout['sourcePdfSourceIds'] = array_keys($sourceIds);
        }
        if ($exactRanges !== null && $exactRanges !== []) {
            $layout['sourcePdfExactSourceRanges'] = $exactRanges;
        }
        if ($streams !== []) {
            $layout['sourcePdfStreams'] = $streams;
            if (count($streams) === 1) {
                $layout['sourceStream'] = $streams[0];
            }
        }
        if ($this->pdfLayoutHasGeometry($leftLayout) && $this->pdfLayoutHasGeometry($rightLayout)) {
            $layout['x1'] = min((float) $leftLayout['x1'], (float) $rightLayout['x1']);
            $layout['y1'] = min((float) $leftLayout['y1'], (float) $rightLayout['y1']);
            $layout['x2'] = max((float) $leftLayout['x2'], (float) $rightLayout['x2']);
            $layout['y2'] = max((float) $leftLayout['y2'], (float) $rightLayout['y2']);
            $layout['fontSize'] = max(1.0, (float) $leftLayout['fontSize'], (float) $rightLayout['fontSize']);
        } else {
            unset($layout['x1'], $layout['y1'], $layout['x2'], $layout['y2'], $layout['fontSize']);
        }
        $layout['sourcePdfFormTailComposite'] = true;
        // The ordinary prose merger may still attach wrapped row text from
        // the left. Once this carrier becomes pending, however, the proved
        // form field is a hard right edge and must not absorb the next row,
        // Step instruction, or legal notice.
        $layout['sourcePdfFormTailEnd'] = true;
        $layout['sourcePdfFormTailProof'] = [
            'method' => 'consecutive-source-occurrence-form-tail',
            'sourceIndexes' => $indexes,
            'proofDigest' => hash('sha256', json_encode(
                [$indexes, $streams, array_keys($sourceIds), $text],
                JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE
            ) ?: ''),
        ];

        return ['text' => $text, 'layout' => $layout];
    }

    /**
     * Snapshot records whose complete semantic text is tied to exact source
     * occurrence identity. Page-local source indexes originate directly from
     * the source text inventory; page/stream character ranges are the stronger
     * form used by reconstructed visual fragments. Supplemental text,
     * evidenced artifacts, recurring furniture, and inline composites without
     * a complete union of their consumed ranges are never eligible.
     *
     * @param list<array{text:string,layout:array<string,mixed>|null}> $records
     * @return list<array{recordIndex:int,identity:string,text:string,visibleProjectionDigest:string,record:array{text:string,layout:array<string,mixed>}}>
     */
    private function pdfExactSourceSemanticRecoverySnapshot(array $records): array
    {
        $snapshot = [];
        $identityCounts = [];
        foreach ($records as $recordIndex => $record) {
            $layout = is_array($record['layout'] ?? null) ? $record['layout'] : null;
            $text = (string) ($record['text'] ?? '');
            $identity = is_array($layout)
                ? $this->pdfExactSourceSemanticRecoveryIdentity($layout, $text)
                : null;
            if (!is_string($identity)) {
                continue;
            }
            $identityCounts[$identity] = ($identityCounts[$identity] ?? 0) + 1;
            $snapshot[] = [
                'recordIndex' => $recordIndex,
                'identity' => $identity,
                'text' => $text,
                'visibleProjectionDigest' => $this->pdfSemanticRecoveryVisibleProjectionDigest($text),
                'record' => ['text' => $text, 'layout' => $layout],
            ];
        }

        // A complete source occurrence or exact subrange must have one
        // semantic carrier. Duplicate carriers are ambiguous and therefore
        // cannot authorize automatic recovery; the final source ledger will
        // keep the page fail-closed instead of silently duplicating text.
        return array_values(array_filter(
            $snapshot,
            static fn (array $entry): bool => ($identityCounts[$entry['identity']] ?? 0) === 1
        ));
    }

    private function pdfSemanticRecoveryVisibleProjectionDigest(string $text): string
    {
        return hash('sha256', $this->pdfSourceOccurrenceComparableText(
            $this->pdfTextWithoutSemanticPrefixes($text)
        ));
    }

    /** @param array<string,mixed> $layout */
    private function pdfExactSourceSemanticRecoveryIdentity(
        array $layout,
        string $recordText
    ): ?string
    {
        if (($layout['sourceSupplementalPositioned'] ?? false) === true
            || ($layout['sourceShortSupplementalCandidate'] ?? false) === true
            || is_array($layout['sourcePdfDecorativeBraceEvidence'] ?? null)
            || is_array(
                $layout['sourcePdfDuplicateTerminalPeriodArtifactEvidence'] ?? null
            )
            || is_array($layout['sourcePdfChartCipherArtifactEvidence'] ?? null)
            || ($layout['sourcePdfArtifact'] ?? false) === true
            || ($layout['sourcePdfRunningFurniture'] ?? false) === true
            // Inline-marker attachment deliberately merges records. Admit it
            // only when the processor rebuilt and signed the exact union of
            // every whole source occurrence consumed by the composite.
            || ((int) ($layout['sourcePdfInlineMarkerCount'] ?? 0) > 0
                && !$this->pdfInlineMarkerExactSourceUnionProofMatchesLayout(
                    $layout,
                    $recordText
                ))) {
            return null;
        }

        $page = max(1, (int) ($layout['page'] ?? 1));
        $stream = isset($layout['sourceStream'])
            ? (int) $layout['sourceStream']
            : (isset($layout['stream']) ? (int) $layout['stream'] : null);
        $identity = ['page' => $page, 'stream' => $stream];
        $exactRanges = $this->pdfPositionedExactSourceRanges($layout);
        if ($exactRanges !== []) {
            $identity['sourceRanges'] = $exactRanges;
        } elseif (is_array($layout['sourcePdfSourceIndexes'] ?? null)) {
            $indexes = [];
            foreach ($layout['sourcePdfSourceIndexes'] as $sourceIndex) {
                if (!is_int($sourceIndex) || $sourceIndex < 0) {
                    return null;
                }
                $indexes[] = $sourceIndex;
            }
            if ($indexes === [] || count($indexes) !== count(array_unique($indexes, SORT_NUMERIC))) {
                return null;
            }
            $identity['pageLocalSourceIndexes'] = $indexes;
        } elseif (is_int($layout['sourcePdfSourceIndex'] ?? null)) {
            $sourceStart = $layout['sourcePdfSourceIndex'];
            $sourceEnd = is_int($layout['sourcePdfSourceIndexEnd'] ?? null)
                ? $layout['sourcePdfSourceIndexEnd']
                : $sourceStart;
            if ($sourceStart < 0 || $sourceEnd < $sourceStart) {
                return null;
            }
            $identity['pageLocalSourceRange'] = [$sourceStart, $sourceEnd];
        } elseif (($layout['sourceGeometryMethod'] ?? null) === 'exact-page-stream-character-offset'
            && is_array($layout['sourceGeometry'] ?? null)
            && $this->pdfSourceBoundsAreValid($layout['sourceGeometry'])
            && isset($layout['sourceOrderStart'], $layout['sourceOrderEnd'])) {
            $identity['sourceOrderRange'] = [
                (int) $layout['sourceOrderStart'],
                (int) $layout['sourceOrderEnd'],
            ];
            $identity['sourceBounds'] = $this->pdfSourceEvidenceBounds($layout['sourceGeometry']);
        } else {
            return null;
        }

        $encoded = json_encode(
            $identity,
            JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_PRESERVE_ZERO_FRACTION
        );

        return hash('sha256', is_string($encoded) ? $encoded : serialize($identity));
    }

    /** @param array<string,mixed> $layout */
    private function pdfInlineMarkerExactSourceUnionProofMatchesLayout(
        array $layout,
        string $recordText
    ): bool {
        $proof = is_array($layout['sourcePdfInlineMarkerExactSourceUnionProof'] ?? null)
            ? $layout['sourcePdfInlineMarkerExactSourceUnionProof']
            : null;
        $projection = $this->pdfSourceOccurrenceComparableText(
            $this->pdfTextWithoutSemanticPrefixes($recordText)
        );
        $ranges = $this->pdfPositionedExactSourceRanges($layout);
        if ($proof === null
            || $projection === ''
            || ($proof['version'] ?? null) !== 1
            || ($proof['method'] ?? null) !== 'exact-source-inline-marker-union'
            || !is_string($proof['sourceSha256'] ?? null)
            || !hash_equals($this->sourceSha256, $proof['sourceSha256'])
            || !is_int($proof['page'] ?? null)
            || $proof['page'] !== (int) ($layout['page'] ?? 0)
            || !is_int($proof['layoutStream'] ?? null)
            || $proof['layoutStream'] !== (int) ($layout['sourceStream'] ?? 0)
            || !is_int($proof['markerCount'] ?? null)
            || $proof['markerCount'] < 1
            || $proof['markerCount'] !== (int) ($layout['sourcePdfInlineMarkerCount'] ?? 0)
            || !is_array($proof['components'] ?? null)
            || !array_is_list($proof['components'])
            || count($proof['components']) !== $proof['markerCount'] + 1
            || !is_array($proof['ranges'] ?? null)
            || !array_is_list($proof['ranges'])
            || !is_string($proof['projectionDigest'] ?? null)
            || !is_string($proof['proofDigest'] ?? null)
            || array_values($proof['ranges']) !== $ranges
            || !hash_equals($proof['projectionDigest'], hash('sha256', $projection))) {
            return false;
        }

        $coveredBytes = 0;
        $componentRanges = [];
        $sourceIndexes = [];
        $sourceIds = [];
        $previous = null;
        foreach ($proof['components'] as $component) {
            if (!is_array($component)
                || !$this->pdfInlineMarkerExactSourceUnionComponentIsValid(
                    $component,
                    $proof['sourceSha256'],
                    $proof['page'],
                    $proof['layoutStream']
                )) {
                return false;
            }
            if ($previous !== null
                && ($component['sourceIndex'] !== $previous['sourceIndex'] + 1
                    || $component['pageLocalSourceIndex']
                        !== $previous['pageLocalSourceIndex'] + 1)) {
                return false;
            }
            $componentProjection = substr(
                $projection,
                $coveredBytes,
                $component['significantBytes']
            );
            if (strlen($componentProjection) !== $component['significantBytes']
                || !hash_equals(
                    $component['projectionDigest'],
                    hash('sha256', $componentProjection)
                )) {
                return false;
            }
            $coveredBytes += $component['significantBytes'];
            $componentRanges[] = $component['range'];
            $sourceIndexes[] = $component['sourceIndex'];
            $sourceIds[] = $component['sourceId'];
            $previous = $component;
        }
        if ($coveredBytes !== strlen($projection)
            || $componentRanges !== $ranges
            || array_values($layout['sourcePdfGlobalSourceIndexes'] ?? [])
                !== $sourceIndexes
            || count($sourceIds) !== count(array_unique($sourceIds))
            || array_values($layout['sourcePdfSourceIds'] ?? []) !== $sourceIds
            || array_values($layout['sourcePdfStreams'] ?? [])
                !== [$proof['layoutStream']]) {
            return false;
        }

        $payload = $proof;
        unset($payload['proofDigest']);
        $expectedDigest = hash('sha256', json_encode(
            $payload,
            JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE
        ) ?: '');

        return hash_equals($proof['proofDigest'], $expectedDigest);
    }

    /** @param array<string,mixed> $component */
    private function pdfInlineMarkerExactSourceUnionComponentIsValid(
        array $component,
        string $sourceSha256,
        int $page,
        int $stream
    ): bool
    {
        $range = is_array($component['range'] ?? null) ? $component['range'] : null;
        if (($component['version'] ?? null) !== 1
            || !in_array($component['method'] ?? null, [
                'exact-source-geometry-fallback-occurrence',
                'exact-source-positioned-occurrence',
            ], true)
            || !is_string($component['sourceSha256'] ?? null)
            || !hash_equals($sourceSha256, $component['sourceSha256'])
            || !is_string($component['sourceId'] ?? null)
            || $component['sourceId'] === ''
            || !is_int($component['sourceIndex'] ?? null)
            || $component['sourceIndex'] < 0
            || !is_int($component['pageLocalSourceIndex'] ?? null)
            || $component['pageLocalSourceIndex'] < 0
            || ($component['page'] ?? null) !== $page
            || ($component['stream'] ?? null) !== $stream
            || !is_array($range)
            || $range !== [
                'sourceIndex' => $component['sourceIndex'],
                'sourceStart' => 0,
                'sourceEnd' => $component['significantBytes'] ?? null,
            ]
            || !is_int($component['significantBytes'] ?? null)
            || $component['significantBytes'] < 1) {
            return false;
        }
        foreach (['projectionDigest', 'geometryDigest', 'evidenceDigest'] as $digestKey) {
            if (!is_string($component[$digestKey] ?? null)
                || preg_match('/^[a-f0-9]{64}$/D', $component[$digestKey]) !== 1) {
                return false;
            }
        }
        $payload = $component;
        unset($payload['evidenceDigest']);

        return hash_equals($component['evidenceDigest'], hash('sha256', json_encode(
            $payload,
            JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE
        ) ?: ''));
    }

    /**
     * Restore a deleted exact-backed record and replace any partially trimmed
     * survivor with the complete pre-filter projection. Matching uses exact
     * occurrence identity, while equal-text candidates are consumed first so
     * duplicate spellings or ranges cannot authorize one another. Restored
     * records retain the first-phase semantic annotations and re-enter before
     * line-role inference and ordinary merging.
     *
     * @param list<array{text:string,layout:array<string,mixed>|null}> $records
     * @param list<array{recordIndex:int,identity:string,text:string,visibleProjectionDigest:string,record:array{text:string,layout:array<string,mixed>}}> $snapshot
     * @return list<array{text:string,layout:array<string,mixed>|null}>
     */
    private function restoreDroppedExactSourceSemanticRecords(array $records, array $snapshot): array
    {
        $candidatesByIdentity = [];
        foreach ($records as $recordIndex => $record) {
            $layout = is_array($record['layout'] ?? null) ? $record['layout'] : null;
            $identity = is_array($layout)
                ? $this->pdfExactSourceSemanticRecoveryIdentity(
                    $layout,
                    (string) ($record['text'] ?? '')
                )
                : null;
            if (is_string($identity)) {
                $candidatesByIdentity[$identity][] = $recordIndex;
            }
        }

        $consumedCandidates = [];
        $snapshotToCandidate = [];
        // Prefer an unchanged survivor. This keeps semantic annotations added
        // by a non-destructive stage without letting a similarly backed but
        // shortened record stand in for the complete source projection.
        foreach ($snapshot as $snapshotIndex => $entry) {
            foreach ($candidatesByIdentity[$entry['identity']] ?? [] as $candidateIndex) {
                if (isset($consumedCandidates[$candidateIndex])
                    || !hash_equals(
                        $entry['visibleProjectionDigest'],
                        $this->pdfSemanticRecoveryVisibleProjectionDigest(
                            (string) ($records[$candidateIndex]['text'] ?? '')
                        )
                    )) {
                    continue;
                }
                $consumedCandidates[$candidateIndex] = true;
                $snapshotToCandidate[$snapshotIndex] = $candidateIndex;
                break;
            }
        }
        // A remaining survivor with the same exact occurrence identity was
        // mutated by a destructive stage. Replace it rather than retaining a
        // truncated copy beside the restored original.
        foreach ($snapshot as $snapshotIndex => $entry) {
            if (isset($snapshotToCandidate[$snapshotIndex])) {
                continue;
            }
            foreach ($candidatesByIdentity[$entry['identity']] ?? [] as $candidateIndex) {
                if (isset($consumedCandidates[$candidateIndex])) {
                    continue;
                }
                $consumedCandidates[$candidateIndex] = true;
                $snapshotToCandidate[$snapshotIndex] = $candidateIndex;
                $records[$candidateIndex] = $entry['record'];
                break;
            }
        }

        $matchedSnapshotRecordIndexByCandidate = array_fill(0, count($records), null);
        foreach ($snapshotToCandidate as $snapshotIndex => $candidateIndex) {
            $matchedSnapshotRecordIndexByCandidate[$candidateIndex] = $snapshot[$snapshotIndex]['recordIndex'];
        }
        foreach ($snapshot as $snapshotIndex => $entry) {
            if (isset($snapshotToCandidate[$snapshotIndex])) {
                continue;
            }
            $insertAt = count($records);
            foreach ($records as $candidateIndex => $_candidate) {
                $candidateRecordIndex = $matchedSnapshotRecordIndexByCandidate[$candidateIndex] ?? null;
                if (is_int($candidateRecordIndex) && $candidateRecordIndex > $entry['recordIndex']) {
                    $insertAt = $candidateIndex;
                    break;
                }
            }
            array_splice($records, $insertAt, 0, [$entry['record']]);
            array_splice(
                $matchedSnapshotRecordIndexByCandidate,
                $insertAt,
                0,
                [$entry['recordIndex']]
            );
        }

        return array_values($this->normalizePdfExactSourceSemanticRecoveryRecords($records));
    }

    /**
     * Stable-move only the unique continuation whose two endpoint records
     * still reproduce the immutable proof stamped during source/layout
     * selection. Intervening furniture keeps its relative order after the
     * moved continuation, and a copied boolean role cannot authorize a move.
     *
     * @param list<array{text:string,layout:array<string,mixed>|null}> $records
     * @return list<array{text:string,layout:array<string,mixed>|null}>
     */
    private function restoreProvenPdfCrossPanelContinuationRecords(array $records): array
    {
        $proofDigests = [];
        foreach ($records as $record) {
            $layout = is_array($record['layout'] ?? null) ? $record['layout'] : null;
            $proof = is_array($layout['sourcePdfCrossPanelContinuationProof'] ?? null)
                ? $layout['sourcePdfCrossPanelContinuationProof']
                : null;
            if (is_string($proof['proofDigest'] ?? null)) {
                $proofDigests[$proof['proofDigest']] = true;
            }
        }

        foreach (array_keys($proofDigests) as $proofDigest) {
            $tailIndexes = [];
            $memberIndexesByOrdinal = [];
            $proofMemberCount = null;
            foreach ($records as $index => $record) {
                $layout = is_array($record['layout'] ?? null) ? $record['layout'] : null;
                $proof = is_array($layout['sourcePdfCrossPanelContinuationProof'] ?? null)
                    ? $layout['sourcePdfCrossPanelContinuationProof']
                    : null;
                if (($proof['proofDigest'] ?? null) !== $proofDigest) {
                    continue;
                }
                if (($layout['sourcePdfCrossPanelContinuationTail'] ?? false) === true) {
                    $tailIndexes[] = $index;
                }
                $members = is_array($proof['continuationMembers'] ?? null)
                    && array_is_list($proof['continuationMembers'])
                    ? $proof['continuationMembers']
                    : null;
                if (is_array($members)) {
                    $proofMemberCount = $proofMemberCount === null
                        ? count($members)
                        : ($proofMemberCount === count($members) ? $proofMemberCount : -1);
                }
                $ordinal = $layout['sourcePdfCrossPanelContinuationMemberOrdinal'] ?? null;
                if (is_int($ordinal) && $ordinal >= 0) {
                    $memberIndexesByOrdinal[$ordinal][] = $index;
                }
            }
            if (count($tailIndexes) !== 1 || !is_int($proofMemberCount) || $proofMemberCount < 1) {
                continue;
            }
            $tailIndex = $tailIndexes[0];
            $memberIndexes = [];
            $memberRecords = [];
            for ($ordinal = 0; $ordinal < $proofMemberCount; $ordinal++) {
                $ordinalIndexes = $memberIndexesByOrdinal[$ordinal] ?? [];
                if (count($ordinalIndexes) !== 1) {
                    continue 2;
                }
                $memberIndex = $ordinalIndexes[0];
                if ($memberIndex <= $tailIndex) {
                    continue 2;
                }
                $memberIndexes[] = $memberIndex;
                $memberRecords[] = $records[$memberIndex];
            }
            if (count($memberIndexesByOrdinal) !== $proofMemberCount
                || !$this->sourcePdfCrossPanelContinuationProofMatchesRecords(
                    $records[$tailIndex],
                    $memberRecords
                )) {
                continue;
            }
            $alreadyAdjacent = true;
            foreach ($memberIndexes as $ordinal => $memberIndex) {
                if ($memberIndex !== $tailIndex + 1 + $ordinal) {
                    $alreadyAdjacent = false;
                    break;
                }
            }
            if ($alreadyAdjacent) {
                continue;
            }

            $removalIndexes = $memberIndexes;
            rsort($removalIndexes, SORT_NUMERIC);
            foreach ($removalIndexes as $memberIndex) {
                array_splice($records, $memberIndex, 1);
            }
            $tailIndex = null;
            foreach ($records as $index => $record) {
                $layout = is_array($record['layout'] ?? null) ? $record['layout'] : null;
                $proof = is_array($layout['sourcePdfCrossPanelContinuationProof'] ?? null)
                    ? $layout['sourcePdfCrossPanelContinuationProof']
                    : null;
                if (($layout['sourcePdfCrossPanelContinuationTail'] ?? false) === true
                    && ($proof['proofDigest'] ?? null) === $proofDigest) {
                    if ($tailIndex !== null) {
                        $tailIndex = null;
                        break;
                    }
                    $tailIndex = $index;
                }
            }
            if ($tailIndex !== null) {
                array_splice($records, $tailIndex + 1, 0, $memberRecords);
            }
        }

        return array_values($records);
    }

    /**
     * @param array{text:string,layout:array<string,mixed>|null} $predecessor
     * @param list<array{text:string,layout:array<string,mixed>|null}> $continuationMembers
     */
    private function sourcePdfCrossPanelContinuationProofMatchesRecords(
        array $predecessor,
        array $continuationMembers
    ): bool {
        $predecessorLayout = is_array($predecessor['layout'] ?? null)
            ? $predecessor['layout']
            : null;
        $proof = is_array($predecessorLayout['sourcePdfCrossPanelContinuationProof'] ?? null)
            ? $predecessorLayout['sourcePdfCrossPanelContinuationProof']
            : null;
        if (!is_array($predecessorLayout)
            || $proof === null
            || ($proof['version'] ?? null) !== 1
            || ($proof['method'] ?? null) !== 'whole-source-positioned-column-wrap-continuation'
            || ($proof['sourceSha256'] ?? null) !== $this->sourceSha256
            || !is_int($proof['page'] ?? null)
            || !is_int($proof['sourceStream'] ?? null)
            || !is_array($proof['predecessor'] ?? null)
            || !is_array($proof['continuationMembers'] ?? null)
            || !array_is_list($proof['continuationMembers'])
            || $proof['continuationMembers'] === []
            || count($continuationMembers) !== count($proof['continuationMembers'])
            || !is_string($proof['proofDigest'] ?? null)) {
            return false;
        }
        $payload = $proof;
        unset($payload['proofDigest']);
        $expectedDigest = hash('sha256', json_encode(
            $payload,
            JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_PRESERVE_ZERO_FRACTION
        ) ?: '');
        if (!hash_equals($proof['proofDigest'], $expectedDigest)
            || !$this->sourcePdfCrossPanelContinuationProofEndpointMatchesRecord(
                $predecessor,
                $proof['predecessor'],
                $proof['page'],
                $proof['sourceStream']
            )
        ) {
            return false;
        }

        $predecessorEndpoint = $proof['predecessor'];
        $previousEndpoint = $predecessorEndpoint;
        $previousRecord = $predecessor;
        foreach ($continuationMembers as $ordinal => $member) {
            $memberLayout = is_array($member['layout'] ?? null) ? $member['layout'] : null;
            $memberProof = is_array($memberLayout['sourcePdfCrossPanelContinuationProof'] ?? null)
                ? $memberLayout['sourcePdfCrossPanelContinuationProof']
                : null;
            $endpoint = $proof['continuationMembers'][$ordinal];
            $range = is_array($endpoint['range'] ?? null) ? $endpoint['range'] : null;
            $previousRange = is_array($previousEndpoint['range'] ?? null)
                ? $previousEndpoint['range']
                : null;
            if (!is_array($memberLayout)
                || $memberProof !== $proof
                || ($memberLayout['sourcePdfCrossPanelContinuationMemberOrdinal'] ?? null) !== $ordinal
                || !is_array($range)
                || !is_array($previousRange)
                || !$this->sourcePdfCrossPanelContinuationProofEndpointMatchesRecord(
                    $member,
                    $endpoint,
                    $proof['page'],
                    $proof['sourceStream']
                )
                || $endpoint['pageLocalSourceIndex'] !== $previousEndpoint['pageLocalSourceIndex'] + 1
                || $range['sourceIndex'] !== $previousRange['sourceIndex'] + 1
                || $endpoint['sourceOrderStart'] !== $previousEndpoint['sourceOrderEnd'] + 1) {
                return false;
            }
            if ($ordinal === 0) {
                if (($predecessorLayout['sourceVerifiedGeometryText'] ?? false) !== true
                    || ($memberLayout['sourceVerifiedGeometryText'] ?? false) !== true
                    || !$this->sourcePdfPositionedColumnWrapGeometryMatches(
                        $predecessorLayout,
                        $memberLayout
                    )) {
                    return false;
                }
            } else {
                $previousLayout = $previousRecord['layout'];
                if (!$this->sourcePdfPositionedContinuationRunMembersAreAdjacent(
                    $previousLayout,
                    $memberLayout
                )) {
                    return false;
                }
            }
            $previousEndpoint = $endpoint;
            $previousRecord = $member;
        }

        return preg_match('/[.!?]\s*$/u', rtrim((string) ($previousRecord['text'] ?? ''))) === 1;
    }

    /**
     * @param array{text:string,layout:array<string,mixed>|null} $record
     * @param array<string,mixed> $endpoint
     */
    private function sourcePdfCrossPanelContinuationProofEndpointMatchesRecord(
        array $record,
        array $endpoint,
        int $page,
        int $sourceStream
    ): bool {
        $layout = is_array($record['layout'] ?? null) ? $record['layout'] : null;
        $range = is_array($endpoint['range'] ?? null) ? $endpoint['range'] : null;
        $projection = $this->pdfSourceOccurrenceComparableText(
            $this->pdfTextWithoutSemanticPrefixes((string) ($record['text'] ?? ''))
        );
        if (!$this->pdfLayoutHasGeometry($layout)
            || ($layout['sourcePdfExactPositionedText'] ?? false) !== true
            || ($layout['pdfPrimaryOrientation'] ?? false) !== true
            || !is_numeric($layout['pdfTextRotation'] ?? null)
            || abs((float) $layout['pdfTextRotation']) > 0.0001
            || ($layout['code'] ?? false) === true
            || isset($layout['sourcePdfTableGroup'])
            || ($layout['sourceSupplementalPositioned'] ?? false) === true
            || ($layout['forceBlockBreakBefore'] ?? false) === true
            || $this->lineHasPdfListBlockEvidence((string) ($record['text'] ?? ''))
            || $this->lineLooksLikeUrlOnly((string) ($record['text'] ?? ''))
            || !in_array((string) ($layout['pdfTextOrientation'] ?? 'horizontal'), ['', 'horizontal', 'r0'], true)
            || !is_string($endpoint['sourceOccurrenceId'] ?? null)
            || $endpoint['sourceOccurrenceId'] === ''
            || !is_int($endpoint['pageLocalSourceIndex'] ?? null)
            || !is_int($endpoint['pageLocalSourceIndexEnd'] ?? null)
            || !is_int($endpoint['globalSourceIndex'] ?? null)
            || !is_array($range)
            || !is_int($range['sourceIndex'] ?? null)
            || !is_int($range['sourceStart'] ?? null)
            || !is_int($range['sourceEnd'] ?? null)
            || !is_string($endpoint['projectionDigest'] ?? null)
            || !is_string($endpoint['geometryDigest'] ?? null)
            || !is_int($endpoint['sourceOrderStart'] ?? null)
            || !is_int($endpoint['sourceOrderEnd'] ?? null)
            || ($layout['id'] ?? null) !== $endpoint['sourceOccurrenceId']
            || (int) ($layout['page'] ?? 0) !== $page
            || (int) ($layout['sourceStream'] ?? 0) !== $sourceStream
            || ($layout['sourcePdfSourceIndex'] ?? null) !== $endpoint['pageLocalSourceIndex']
            || (is_int($layout['sourcePdfSourceIndexEnd'] ?? null)
                ? $layout['sourcePdfSourceIndexEnd']
                : $layout['sourcePdfSourceIndex'] ?? null) !== $endpoint['pageLocalSourceIndexEnd']
            || ($layout['sourcePdfGlobalSourceIndex'] ?? null) !== $endpoint['globalSourceIndex']
            || $endpoint['pageLocalSourceIndexEnd'] !== $endpoint['pageLocalSourceIndex']
            || $endpoint['globalSourceIndex'] !== $range['sourceIndex']
            || (int) ($layout['sourceOrderStart'] ?? -1) !== $endpoint['sourceOrderStart']
            || (int) ($layout['sourceOrderEnd'] ?? -1) !== $endpoint['sourceOrderEnd']
            || $this->pdfPositionedExactSourceRanges($layout) !== [$range]
            || $range['sourceStart'] !== 0
            || $range['sourceEnd'] !== strlen($projection)
            || !hash_equals($endpoint['projectionDigest'], hash('sha256', $projection))) {
            return false;
        }

        return hash_equals(
            $endpoint['geometryDigest'],
            $this->sourcePdfCrossPanelContinuationGeometryDigest($layout)
        );
    }

    /**
     * Preserve a geometry-proven form/furniture label as editable text while
     * preventing the later title-case fallback from certifying it as a
     * document-outline heading.
     *
     * @param list<array{text:string,layout:array<string,mixed>|null}> $records
     * @return list<array{text:string,layout:array<string,mixed>|null}>
     */
    private function markPdfLayoutLabelRecords(array $records): array
    {
        $fontSizesByPage = [];
        foreach ($records as $record) {
            $layout = is_array($record['layout'] ?? null) ? $record['layout'] : null;
            if (!$this->pdfLayoutHasGeometry($layout)) {
                continue;
            }
            $fontSizesByPage[(int) $layout['page']][] = max(1.0, (float) $layout['fontSize']);
        }
        $medianFontSizesByPage = [];
        foreach ($fontSizesByPage as $page => $fontSizes) {
            $medianFontSizesByPage[$page] = max(1.0, $this->median($fontSizes));
        }

        $displayHeadingsByPage = [];
        foreach ($records as $record) {
            $layout = is_array($record['layout'] ?? null) ? $record['layout'] : null;
            if (($layout['sourcePdfDisplayHeading'] ?? false) === true
                && $this->pdfLayoutHasGeometry($layout)) {
                $displayHeadingsByPage[(int) $layout['page']][] = $layout;
            }
        }
        foreach ($records as &$record) {
            $layout = is_array($record['layout'] ?? null) ? $record['layout'] : null;
            $text = trim((string) ($record['text'] ?? ''));
            $displayLetters = preg_replace('/[^\p{L}\p{M}]+/u', '', $text) ?? '';
            if (!$this->pdfLayoutHasGeometry($layout)
                || ($layout['sourcePdfDisplayHeading'] ?? false) === true
                || ($layout['sourcePdfLayoutLabel'] ?? false) === true
                || $this->length($displayLetters) < 3
                || preg_match('/^[^\p{L}\p{N}]*\p{Lu}/u', $text) !== 1
                || preg_match('/[.!?]\s*$/u', $text) === 1
                || $this->lineHasPdfListBlockEvidence($text)
                || $this->lineLooksLikeUrlOnly($text)
                || $this->lineLooksLikePdfReferenceEntry($text)
                || count($this->pdfLineWordTokens($text)) > 6
                || $this->length($text) > 88) {
                continue;
            }
            $page = (int) $layout['page'];
            $candidateFontSize = max(1.0, (float) $layout['fontSize']);
            $candidateHeight = max(1.0, (float) $layout['y2'] - (float) $layout['y1']);
            $pageMedian = $medianFontSizesByPage[$page] ?? 1.0;
            if ($candidateFontSize < $pageMedian * 1.25) {
                continue;
            }
            foreach ($displayHeadingsByPage[$page] ?? [] as $primaryLayout) {
                $primaryFontSize = max(1.0, (float) $primaryLayout['fontSize']);
                $verticalOverlap = min((float) $layout['y2'], (float) $primaryLayout['y2'])
                    - max((float) $layout['y1'], (float) $primaryLayout['y1']);
                if ($primaryFontSize < $candidateFontSize * 1.35
                    || $verticalOverlap < $candidateHeight * 0.50) {
                    continue;
                }
                // Two title-like records occupying the same masthead band
                // form one outline entry when one is substantially more
                // prominent. Keep the subordinate title editable, but stop
                // the lexical fallback from inventing a second peer heading.
                $record['layout']['sourcePdfLayoutLabel'] = true;
                break;
            }
        }
        unset($record);

        foreach ($records as &$record) {
            $layout = is_array($record['layout'] ?? null) ? $record['layout'] : null;
            $text = trim((string) ($record['text'] ?? ''));
            if (($layout['sourcePdfLayoutLabel'] ?? false) !== true
                || $text === ''
                || $this->pdfLineStartsWithSemanticPrefix($text)) {
                continue;
            }
            $record['text'] = self::PDF_LAYOUT_LABEL_PREFIX . $text;
        }
        unset($record);

        return $records;
    }

    /**
     * Derive immutable source-local photo-credit and footer proof candidates
     * without mutating semantic records. Their outline-ineligible role is
     * applied only to exact standalone lines after prose merging.
     *
     * @param list<array{text:string,layout:array<string,mixed>|null}> $records
     * @return list<array{text:string,proof:array<string,mixed>>>
     */
    private function pdfLocalCreditAndFooterLayoutLabelProofCandidates(array $records): array
    {
        $candidateEvidenceByRecordIndex = [];
        $geometryRecordsByPage = [];
        $recordIndexByGlobalSourceIndex = [];
        foreach ($records as $recordIndex => $record) {
            $layout = is_array($record['layout'] ?? null) ? $record['layout'] : null;
            if (!$this->pdfLayoutHasGeometry($layout)) {
                continue;
            }
            $page = max(1, (int) $layout['page']);
            $geometryRecordsByPage[$page][] = [
                'index' => $recordIndex,
                'stream' => max(1, (int) ($layout['sourceStream'] ?? 1)),
                'text' => (string) ($record['text'] ?? ''),
                'bounds' => $this->pdfSourceEvidenceBounds($layout),
                'orientation' => (string) ($layout['pdfTextOrientation'] ?? 'horizontal'),
            ];
            $globalSourceIndex = is_int($layout['sourcePdfGlobalSourceIndex'] ?? null)
                ? $layout['sourcePdfGlobalSourceIndex']
                : null;
            if ($globalSourceIndex !== null) {
                $recordIndexByGlobalSourceIndex[$globalSourceIndex] = array_key_exists(
                    $globalSourceIndex,
                    $recordIndexByGlobalSourceIndex
                ) ? null : $recordIndex;
            }
        }

        $pageEvidence = [];
        foreach ($geometryRecordsByPage as $page => $pageRecords) {
            $evidence = $this->sourcePdfLayoutLabelPageEvidence($pageRecords);
            if ($evidence !== null) {
                $pageEvidence[$page] = $evidence;
            }
        }

        $creditCompanionsByPageAndKey = [];
        foreach ($records as $recordIndex => $record) {
            $layout = is_array($record['layout'] ?? null) ? $record['layout'] : null;
            $text = trim((string) ($record['text'] ?? ''));
            $globalSourceIndex = is_array($layout)
                && is_int($layout['sourcePdfGlobalSourceIndex'] ?? null)
                    ? $layout['sourcePdfGlobalSourceIndex']
                    : null;
            $previousRecordIndex = $globalSourceIndex === null
                ? null
                : ($recordIndexByGlobalSourceIndex[$globalSourceIndex - 1] ?? null);
            $previous = is_int($previousRecordIndex) ? ($records[$previousRecordIndex] ?? null) : null;
            $previousLayout = is_array($previous['layout'] ?? null) ? $previous['layout'] : null;
            if (!$this->pdfLayoutHasGeometry($layout)
                || !$this->pdfLayoutHasGeometry($previousLayout)
                || $text === ''
                || preg_match('/^\p{Lu}[\p{Lu}\p{N}&.\/-]{2,11}$/u', $text) !== 1
                || !str_contains((string) ($previous['text'] ?? ''), "\u{00A9}")) {
                continue;
            }
            $page = max(1, (int) $layout['page']);
            $evidence = $pageEvidence[$page] ?? null;
            if (!is_array($evidence)
                || (int) ($previousLayout['page'] ?? 0) !== $page
                || (int) ($previousLayout['sourceStream'] ?? 0)
                    !== (int) ($layout['sourceStream'] ?? 0)) {
                continue;
            }
            $bounds = $this->pdfSourceEvidenceBounds($layout);
            $previousBounds = $this->pdfSourceEvidenceBounds($previousLayout);
            $height = max(0.0, (float) $bounds['y2'] - (float) $bounds['y1']);
            $centerY = ((float) $bounds['y1'] + (float) $bounds['y2']) / 2.0;
            $previousCenterY = ((float) $previousBounds['y1'] + (float) $previousBounds['y2']) / 2.0;
            if ($height <= 0.0
                || $height > $evidence['medianHeight'] * 0.80
                || abs($centerY - $previousCenterY) > max($height, 1.0)) {
                continue;
            }
            $targetEndpoint = $this->pdfLocalLayoutLabelProofEndpoint($record);
            $contextEndpoint = $this->pdfLocalLayoutLabelProofEndpoint($previous);
            if ($targetEndpoint === null || $contextEndpoint === null) {
                continue;
            }
            $key = $this->pdfDocumentProfileComparableText($text) . "\0"
                . $this->pdfDocumentProfileComparableText((string) $previous['text']);
            $creditCompanionsByPageAndKey[$page][$key][] = [
                'recordIndex' => $recordIndex,
                'contextRecordIndex' => $previousRecordIndex,
                'centerX' => ((float) $bounds['x1'] + (float) $bounds['x2']) / 2.0,
                'targetEndpoint' => $targetEndpoint,
                'contextEndpoint' => $contextEndpoint,
            ];
        }
        foreach ($creditCompanionsByPageAndKey as $page => $groups) {
            foreach ($groups as $companions) {
                if (count($companions) < 2) {
                    continue;
                }
                $centers = array_column($companions, 'centerX');
                if (max($centers) - min($centers) < $pageEvidence[$page]['width'] * 0.25) {
                    continue;
                }
                usort($companions, static function (array $left, array $right): int {
                    $sourceOrder = ($left['targetEndpoint']['sourceIndex'] ?? -1)
                        <=> ($right['targetEndpoint']['sourceIndex'] ?? -1);
                    if ($sourceOrder !== 0) {
                        return $sourceOrder;
                    }

                    return strcmp(
                        (string) ($left['targetEndpoint']['sourceOccurrenceId'] ?? ''),
                        (string) ($right['targetEndpoint']['sourceOccurrenceId'] ?? '')
                    );
                });
                $recurringPeers = array_map(static fn (array $companion): array => [
                    'target' => $companion['targetEndpoint'],
                    'context' => $companion['contextEndpoint'],
                    'centerX' => $companion['centerX'],
                ], $companions);
                $recurringGroupDigest = hash('sha256', json_encode([
                    'version' => 1,
                    'method' => 'ordered-exact-photo-credit-companion-peers',
                    'sourceSha256' => $this->sourceSha256,
                    'page' => $page,
                    'peers' => $recurringPeers,
                ], JSON_UNESCAPED_SLASHES
                    | JSON_UNESCAPED_UNICODE
                    | JSON_PRESERVE_ZERO_FRACTION) ?: '');
                foreach ($companions as $companion) {
                    $candidateEvidenceByRecordIndex[$companion['recordIndex']] = [
                        'method' => 'repeated-source-local-photo-credit-companion',
                        'contextRecordIndex' => $companion['contextRecordIndex'],
                        'recurringCandidateCount' => count($companions),
                        'horizontalCenterSpan' => max($centers) - min($centers),
                        'pageWidth' => $pageEvidence[$page]['width'],
                        'medianHeight' => $pageEvidence[$page]['medianHeight'],
                        'recurringPeers' => $recurringPeers,
                        'recurringGroupDigest' => $recurringGroupDigest,
                    ];
                }
            }
        }

        foreach ($records as $recordIndex => $record) {
            $layout = is_array($record['layout'] ?? null) ? $record['layout'] : null;
            $text = trim((string) ($record['text'] ?? ''));
            $globalSourceIndex = is_array($layout)
                && is_int($layout['sourcePdfGlobalSourceIndex'] ?? null)
                    ? $layout['sourcePdfGlobalSourceIndex']
                    : null;
            $previousRecordIndex = $globalSourceIndex === null
                ? null
                : ($recordIndexByGlobalSourceIndex[$globalSourceIndex - 1] ?? null);
            $previous = is_int($previousRecordIndex) ? ($records[$previousRecordIndex] ?? null) : null;
            $previousLayout = is_array($previous['layout'] ?? null) ? $previous['layout'] : null;
            if (!$this->pdfLayoutHasGeometry($layout)
                || !$this->pdfLayoutHasGeometry($previousLayout)
                || count($this->pdfLineWordTokens($text)) < 2
                || preg_match('/^\p{Lu}[\p{Lu}\p{N},;:&() \-]+$/u', $text) !== 1
                || !$this->repairedLineLooksLikeSectionLabel($text)
                || preg_match('/[.!?]\s*$/u', (string) ($previous['text'] ?? '')) !== 1) {
                continue;
            }
            $page = max(1, (int) $layout['page']);
            $evidence = $pageEvidence[$page] ?? null;
            if (!is_array($evidence)
                || (int) ($previousLayout['page'] ?? 0) !== $page
                || (int) ($previousLayout['sourceStream'] ?? 0)
                    !== (int) ($layout['sourceStream'] ?? 0)) {
                continue;
            }
            $bounds = $this->pdfSourceEvidenceBounds($layout);
            $previousBounds = $this->pdfSourceEvidenceBounds($previousLayout);
            $height = max(0.0, (float) $bounds['y2'] - (float) $bounds['y1']);
            $centerY = ((float) $bounds['y1'] + (float) $bounds['y2']) / 2.0;
            $verticalGap = (float) $previousBounds['y1'] - (float) $bounds['y2'];
            if ($height > 0.0
                && $height <= $evidence['medianHeight'] * 1.20
                && $centerY <= $evidence['y1'] + $evidence['height'] * 0.03
                && abs((float) $previousBounds['x1'] - (float) $bounds['x1'])
                    <= max(8.0, $evidence['medianHeight'])
                && $verticalGap >= -1.0
                && $verticalGap <= $evidence['medianHeight'] * 1.25) {
                $candidateEvidenceByRecordIndex[$recordIndex] = [
                    'method' => 'source-local-terminal-footer-tagline',
                    'contextRecordIndex' => $previousRecordIndex,
                    'pageHeight' => $evidence['height'],
                    'pageY1' => $evidence['y1'],
                    'medianHeight' => $evidence['medianHeight'],
                    'verticalGap' => $verticalGap,
                ];
            }
        }

        $proofCandidates = [];
        foreach ($candidateEvidenceByRecordIndex as $recordIndex => $candidateEvidence) {
            $contextRecordIndex = $candidateEvidence['contextRecordIndex'] ?? null;
            if (!is_int($contextRecordIndex)
                || !isset($records[$recordIndex], $records[$contextRecordIndex])) {
                continue;
            }
            $target = $this->pdfLocalLayoutLabelProofEndpoint($records[$recordIndex]);
            $context = $this->pdfLocalLayoutLabelProofEndpoint($records[$contextRecordIndex]);
            if ($target === null || $context === null) {
                continue;
            }
            $evidence = $candidateEvidence;
            unset($evidence['contextRecordIndex'], $evidence['method']);
            $proof = [
                'version' => 1,
                'method' => $candidateEvidence['method'],
                'sourceSha256' => $this->sourceSha256,
                'target' => $target,
                'context' => $context,
                'evidence' => $evidence,
            ];
            $proof['proofDigest'] = hash('sha256', json_encode(
                $proof,
                JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_PRESERVE_ZERO_FRACTION
            ) ?: '');
            $proofCandidates[] = [
                'text' => trim((string) $records[$recordIndex]['text']),
                'proof' => $proof,
            ];
        }

        return $proofCandidates;
    }

    /**
     * @param array{text:string,layout:array<string,mixed>|null} $record
     * @return array<string,mixed>|null
     */
    private function pdfLocalLayoutLabelProofEndpoint(array $record): ?array
    {
        $layout = is_array($record['layout'] ?? null) ? $record['layout'] : null;
        $text = trim((string) ($record['text'] ?? ''));
        $projection = $this->pdfSourceOccurrenceComparableText(
            $this->pdfTextWithoutSemanticPrefixes($text)
        );
        $sourceId = is_array($layout) && is_string($layout['id'] ?? null)
            ? $layout['id']
            : '';
        $sourceIndex = is_array($layout) && is_int($layout['sourcePdfGlobalSourceIndex'] ?? null)
            ? $layout['sourcePdfGlobalSourceIndex']
            : null;
        $ranges = is_array($layout) ? $this->pdfPositionedExactSourceRanges($layout) : [];
        if (!$this->pdfLayoutHasGeometry($layout)
            || $text === ''
            || $this->pdfLineStartsWithSemanticPrefix($text)
            || $projection === ''
            || $sourceId === ''
            || $sourceIndex === null
            || count($ranges) !== 1
            || $ranges[0] !== [
                'sourceIndex' => $sourceIndex,
                'sourceStart' => 0,
                'sourceEnd' => strlen($projection),
            ]) {
            return null;
        }

        return [
            'sourceOccurrenceId' => $sourceId,
            'sourceIndex' => $sourceIndex,
            'page' => (int) $layout['page'],
            'sourceStream' => (int) ($layout['sourceStream'] ?? 0),
            'range' => $ranges[0],
            'projectionDigest' => hash('sha256', $projection),
            'geometryDigest' => $this->sourcePdfCrossPanelContinuationGeometryDigest($layout),
        ];
    }

    /**
     * A positioned whole-occurrence carrier intentionally has no native ID
     * role, but page-furniture receipts still need to bind it back to the
     * immutable source occurrence. Resolve that identity only through the
     * live signed union proof and the source-inventory map minted with it.
     *
     * @param array{text:string,layout:array<string,mixed>|null} $record
     * @return array<string,mixed>|null
     */
    private function pdfPageNumberFurnitureRecordEndpoint(array $record): ?array
    {
        $native = $this->pdfLocalLayoutLabelProofEndpoint($record);
        if ($native !== null) {
            return $native;
        }
        $layout = is_array($record['layout'] ?? null) ? $record['layout'] : null;
        $text = trim((string) ($record['text'] ?? ''));
        $projection = $this->pdfSourceOccurrenceComparableText(
            $this->pdfTextWithoutSemanticPrefixes($text)
        );
        $proof = is_array($layout['sourcePdfWholeExactOccurrenceProof'] ?? null)
            ? $layout['sourcePdfWholeExactOccurrenceProof']
            : null;
        $proofDigest = is_array($proof) && is_string($proof['proofDigest'] ?? null)
            ? $proof['proofDigest']
            : '';
        $identity = $proofDigest !== ''
            ? ($this->sourceOccurrenceIdentityByWholeProofDigest[$proofDigest] ?? null)
            : null;
        $ranges = is_array($layout) ? $this->pdfPositionedExactSourceRanges($layout) : [];
        if (!$this->pdfLayoutHasGeometry($layout)
            || $text === ''
            || $this->pdfLineStartsWithSemanticPrefix($text)
            || $projection === ''
            || !is_array($proof)
            || !$this->repairedPdfWholeExactOccurrenceProofMatchesLayout($layout, $projection)
            || !is_array($identity)
            || !is_string($identity['sourceOccurrenceId'] ?? null)
            || $identity['sourceOccurrenceId'] === ''
            || !is_int($identity['globalSourceIndex'] ?? null)
            || !is_int($identity['page'] ?? null)
            || !is_int($identity['stream'] ?? null)
            || $identity['stream'] < 1
            || !is_array($identity['exactRange'] ?? null)
            || !is_string($identity['projectionDigest'] ?? null)
            || ($identity['occurrenceProofDigest'] ?? null) !== $proofDigest
            || count($ranges) !== 1
            || $identity['exactRange'] !== $ranges[0]
            || $identity['globalSourceIndex'] !== $ranges[0]['sourceIndex']
            || $identity['page'] !== (int) $layout['page']
            || !hash_equals($identity['projectionDigest'], hash('sha256', $projection))) {
            return null;
        }

        return [
            'sourceOccurrenceId' => $identity['sourceOccurrenceId'],
            'sourceIndex' => $identity['globalSourceIndex'],
            'page' => $identity['page'],
            'sourceStream' => $identity['stream'],
            'range' => $ranges[0],
            'projectionDigest' => hash('sha256', $projection),
            'geometryDigest' => $this->sourcePdfCrossPanelContinuationGeometryDigest($layout),
        ];
    }

    /**
     * @param array<string,mixed> $proof
     * @param list<array{text:string,layout:array<string,mixed>|null}> $records
     */
    private function pdfLocalLayoutLabelProofMatchesRecords(array $proof, array $records): bool
    {
        if (($proof['version'] ?? null) !== 1
            || !in_array($proof['method'] ?? null, [
                'repeated-source-local-photo-credit-companion',
                'source-local-terminal-footer-tagline',
            ], true)
            || ($proof['sourceSha256'] ?? null) !== $this->sourceSha256
            || !is_array($proof['target'] ?? null)
            || !is_array($proof['context'] ?? null)
            || !is_array($proof['evidence'] ?? null)
            || !is_string($proof['proofDigest'] ?? null)) {
            return false;
        }
        $payload = $proof;
        unset($payload['proofDigest']);
        $expectedDigest = hash('sha256', json_encode(
            $payload,
            JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_PRESERVE_ZERO_FRACTION
        ) ?: '');
        if (!hash_equals($proof['proofDigest'], $expectedDigest)) {
            return false;
        }

        // Rebuild the complete canonical proof graph from the current record
        // set. This uniquely rebinds both endpoints and, for recurring photo
        // credits, recomputes the endpoint-eligible peer count, horizontal
        // span, ordered peer descriptors, and signed group digest. A missing
        // or altered peer therefore invalidates every proof in that group.
        $canonicalMatches = 0;
        foreach ($this->pdfLocalCreditAndFooterLayoutLabelProofCandidates($records) as $candidate) {
            if (($candidate['proof'] ?? null) === $proof) {
                $canonicalMatches++;
            }
        }

        return $canonicalMatches === 1;
    }

    /**
     * Resolve all exact target carriers against the untouched final-merge
     * input. Any malformed, duplicate, or unresolved proof fails the whole
     * local proof set closed so a repeated credit group cannot be half typed.
     *
     * @param list<array{text:string,layout:array<string,mixed>|null}> $records
     * @param list<array{text:string,proof:array<string,mixed>>> $proofCandidates
     * @return array<int,true>
     */
    private function pdfLocalLayoutLabelProofTargetRecordIndexes(
        array $records,
        array $proofCandidates
    ): array {
        if ($proofCandidates === []) {
            return [];
        }
        $targetIndexes = [];
        $targetDigests = [];
        foreach ($proofCandidates as $candidate) {
            $text = is_string($candidate['text'] ?? null) ? trim($candidate['text']) : '';
            $proof = is_array($candidate['proof'] ?? null) ? $candidate['proof'] : null;
            if ($text === ''
                || $proof === null
                || !$this->pdfLocalLayoutLabelProofMatchesRecords($proof, $records)) {
                return [];
            }
            $targetDigest = hash('sha256', json_encode(
                $proof['target'],
                JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_PRESERVE_ZERO_FRACTION
            ) ?: '');
            if (isset($targetDigests[$targetDigest])) {
                return [];
            }
            $targetDigests[$targetDigest] = true;
            $resolvedIndex = null;
            foreach ($records as $recordIndex => $record) {
                if ($this->pdfLocalLayoutLabelProofEndpoint($record) !== $proof['target']) {
                    continue;
                }
                if ($resolvedIndex !== null) {
                    return [];
                }
                $resolvedIndex = $recordIndex;
            }
            if ($resolvedIndex === null
                || trim((string) ($records[$resolvedIndex]['text'] ?? '')) !== $text
                || isset($targetIndexes[$resolvedIndex])) {
                return [];
            }
            $targetIndexes[$resolvedIndex] = true;
        }
        ksort($targetIndexes, SORT_NUMERIC);

        return $targetIndexes;
    }

    /**
     * Prefer the positioned candidate only when it proves the same characters
     * with fewer separators across a sustained run of one-letter fragments.
     * This is deliberately geometry/candidate based: it does not know which
     * word the letters spell, and it leaves genuinely tracked display text
     * alone when the positioned candidate retains those visible gaps.
     *
     * @param array<string, mixed>|null $layout
     */
    private function repairPdfInterGlyphSpacingCandidate(string $text, ?array $layout): string
    {
        if (!is_array($layout)) {
            return $text;
        }

        $candidate = trim((string) ($layout['positionedTextCandidate'] ?? ''));
        if ($candidate === '' || $candidate === trim($text)) {
            return $text;
        }

        $sourceCompact = preg_replace('/\s+/u', '', $this->pdfExactLayoutText($text)) ?? '';
        $candidateCompact = preg_replace('/\s+/u', '', $this->pdfExactLayoutText($candidate)) ?? '';
        if ($sourceCompact === '' || $sourceCompact !== $candidateCompact) {
            return $text;
        }

        $fragmentRuns = preg_match_all(
            '/(?<![\p{L}\p{M}])(?:[\p{L}\p{M}]\h+){3,}[\p{L}\p{M}](?![\p{L}\p{M}])/u',
            $text,
            $matches
        );
        if ($fragmentRuns === false || $fragmentRuns === 0) {
            return $text;
        }

        $sourceSpaces = preg_match_all('/\s/u', $text, $sourceSpaceMatches);
        $candidateSpaces = preg_match_all('/\s/u', $candidate, $candidateSpaceMatches);
        if ($sourceSpaces === false || $candidateSpaces === false || $sourceSpaces - $candidateSpaces < 3) {
            return $text;
        }

        // A candidate that merely trades inter-letter spaces for other common
        // extraction damage is not an improvement. The score is language
        // neutral and examines punctuation/character transitions only.
        if ($this->genericSpacingDamageScore([$candidate]) > $this->genericSpacingDamageScore([$text])) {
            return $text;
        }

        $key = implode(':', [
            (string) ($layout['page'] ?? 0),
            (string) ($layout['sourceStream'] ?? 0),
            hash('sha256', $text . "\0" . $candidate),
        ]);
        $this->interGlyphSpacingRepairKeys[$key] = true;
        $this->interGlyphSpacingRepairCount = count($this->interGlyphSpacingRepairKeys);

        return $candidate;
    }

    /**
     * A source text line can concatenate a visual heading and the first body
     * line even though the positioned reconstruction proves that its initial
     * phrase occupied a separate box. Split only an exact positioned prefix
     * with a heading-like shape and a substantial prose remainder. This uses
     * local geometry as evidence and never depends on the phrase's spelling.
     *
     * @param array<string, mixed>|null $layout
     * @return list<array{text: string, layout: array<string, mixed>|null}>
     */
    private function splitPdfPositionedHeadingLead(string $text, ?array $layout): array
    {
        if (!is_array($layout) || !$this->pdfLayoutHasGeometry($layout)) {
            return [['text' => $text, 'layout' => $layout]];
        }

        $candidate = trim((string) ($layout['positionedTextCandidate'] ?? ''));
        $normalizedText = trim($this->pdfExactLayoutText($text));
        $normalizedCandidate = trim($this->pdfExactLayoutText($candidate));
        if ($normalizedCandidate === ''
            || $normalizedCandidate === $normalizedText
            || !$this->repairedLineLooksLikeSectionLabel($normalizedCandidate)
            || count($this->pdfLineWordTokens($normalizedCandidate)) > 8
            || $this->length($normalizedCandidate) > 88) {
            return [['text' => $text, 'layout' => $layout]];
        }

        $pattern = '/^' . preg_quote($normalizedCandidate, '/') . '\h+(.+)$/u';
        if (preg_match($pattern, $normalizedText, $match) !== 1) {
            return [['text' => $text, 'layout' => $layout]];
        }
        $body = trim($match[1]);
        if (count($this->pdfLineWordTokens($body)) < 4
            || $this->length($body) < 24
            || preg_match('/\p{Ll}/u', $body) !== 1) {
            return [['text' => $text, 'layout' => $layout]];
        }

        $headingLayout = $layout;
        unset($headingLayout['sourcePdfWholeExactOccurrenceProof']);
        $headingLayout['sourcePdfDisplayHeading'] = true;
        $headingLayout['sourcePdfPositionedHeadingBoundary'] = true;
        $this->inferredHeadingBoundaryCount++;

        return [
            ['text' => $normalizedCandidate, 'layout' => $headingLayout],
            // The positioned rectangle describes the heading, not the body
            // suffix. Avoid assigning false coordinates to that suffix.
            ['text' => $body, 'layout' => null],
        ];
    }

    /**
     * Infer recurring cue-and-utterance regions from document-wide evidence.
     * The cue spelling is irrelevant: candidates must recur in one aligned
     * column, use compact all-capital/digit labels, and introduce sentence-
     * case content. This covers theatre dialogue and similarly formatted
     * transcripts without asking for a document type or matching character
     * names from a dictionary.
     *
     * @param list<array{text: string, layout: array<string, mixed>|null}> $records
     * @return list<array{text: string, layout: array<string, mixed>|null}>
     */
    private function markPdfLineOrientedRegionRecords(array $records): array
    {
        $candidates = [];
        $keysByColumn = [];
        foreach ($records as $index => $record) {
            $layout = is_array($record['layout'] ?? null) ? $record['layout'] : null;
            $split = $this->pdfDialogueCueAndBody((string) ($record['text'] ?? ''));
            if ($split === null
                || !$this->pdfLayoutHasGeometry($layout)
                || ($layout['code'] ?? false) === true
                || $this->lineHasPdfListBlockEvidence((string) $record['text'])
                || $this->lineLooksLikeUrlOnly((string) $record['text'])) {
                continue;
            }

            $fontSize = max(1.0, (float) $layout['fontSize']);
            $column = (int) round((float) $layout['x1'] / max(12.0, $fontSize * 2.0));
            $columnKey = (int) $layout['page'] . ':' . $column;
            // Page-local evidence catches distinct panels while the normalized
            // cue key below still groups numbered speakers such as SPEAKER 1.
            $cueKey = $this->pdfDialogueCueKey($split['cue']);
            $candidates[$index] = [
                'cue' => $split['cue'],
                'body' => $split['body'],
                'cueKey' => $cueKey,
                'columnKey' => $columnKey,
            ];
            $keysByColumn[$columnKey][$cueKey] = ($keysByColumn[$columnKey][$cueKey] ?? 0) + 1;
        }

        $accepted = [];
        foreach ($candidates as $index => $candidate) {
            $columnCounts = $keysByColumn[$candidate['columnKey']] ?? [];
            $recurringCount = 0;
            foreach ($columnCounts as $count) {
                if ($count >= 2) {
                    $recurringCount += $count;
                }
            }
            if (($columnCounts[$candidate['cueKey']] ?? 0) >= 2 && $recurringCount >= 4) {
                $accepted[$index] = $candidate;
            }
        }
        if ($accepted === []) {
            return $records;
        }

        $group = 0;
        foreach ($accepted as $index => $candidate) {
            $layout = is_array($records[$index]['layout'] ?? null) ? $records[$index]['layout'] : [];
            $group++;
            $layout['sourcePdfRegionRole'] = 'dialogue';
            $layout['sourcePdfLineOrientedGroup'] = $group;
            $layout['sourcePdfDialogueCue'] = $candidate['cue'];
            $layout['sourcePdfDialogueBody'] = $candidate['body'];
            $records[$index]['layout'] = $layout;

            $previousLayout = $layout;
            for ($nextIndex = $index + 1, $count = count($records); $nextIndex < $count; $nextIndex++) {
                if (isset($accepted[$nextIndex])) {
                    break;
                }
                $nextLayout = is_array($records[$nextIndex]['layout'] ?? null) ? $records[$nextIndex]['layout'] : null;
                if (!$this->pdfLayoutHasGeometry($nextLayout)
                    || (int) $nextLayout['page'] !== (int) $layout['page']
                    || ($nextLayout['code'] ?? false) === true
                    || $this->lineHasPdfListBlockEvidence((string) ($records[$nextIndex]['text'] ?? ''))) {
                    break;
                }

                $fontSize = max(1.0, (float) $layout['fontSize'], (float) $nextLayout['fontSize']);
                $verticalGap = (float) $previousLayout['y1'] - (float) $nextLayout['y2'];
                $indented = (float) $nextLayout['x1'] >= (float) $layout['x1'] + max(18.0, $fontSize * 2.25)
                    && (float) $nextLayout['x1'] <= (float) $layout['x1'] + max(180.0, $fontSize * 16.0);
                $continuesVertically = $verticalGap >= -$fontSize * 0.5 && $verticalGap <= $fontSize * 1.8;
                if (!$indented || !$continuesVertically) {
                    break;
                }

                $nextLayout['sourcePdfRegionRole'] = 'dialogue-continuation';
                $nextLayout['sourcePdfLineOrientedGroup'] = $group;
                $records[$nextIndex]['layout'] = $nextLayout;
                $previousLayout = $nextLayout;
            }
        }

        $this->lineOrientedRegionCount = max($this->lineOrientedRegionCount, $group);

        return $records;
    }

    /** @return array{cue: string, body: string}|null */
    private function pdfDialogueCueAndBody(string $text): ?array
    {
        $text = trim($text);
        if ($text === '') {
            return null;
        }

        // A printed cue delimiter is stronger than a guessed whitespace
        // boundary. Accept both attached and spaced colons, but keep the
        // delimiter out of the editable cue/body. The rule is typographic:
        // it does not depend on a character name, language, or document type.
        $delimitedCue = '/^([\p{Lu}\p{Lt}\p{N}][\p{Lu}\p{Lt}\p{N}\p{M}\'’._-]*(?:\h+[\p{Lu}\p{Lt}\p{N}][\p{Lu}\p{Lt}\p{N}\p{M}\'’._-]*){0,3})\h*[:：]\h*(.+)$/u';
        if (preg_match($delimitedCue, $text, $match) === 1) {
            $cue = trim($match[1]);
            $body = trim($match[2]);
            if ($this->length($cue) <= 32
                && preg_match_all('/[\p{L}\p{M}]/u', $cue, $letters) !== false
                && count($letters[0]) >= 2
                && preg_match('/\p{Ll}/u', $body) === 1) {
                return ['cue' => $cue, 'body' => $body];
            }
        }

        // A terminal number is a strong cue boundary (SPEAKER 2, WITNESS 7).
        // Prefer it before the general all-capital-prefix pattern so a body
        // beginning with an uppercase one-letter token is not absorbed into
        // the cue. The rule is purely typographic and works for any label.
        $numericCue = '/^([\p{Lu}\p{Lt}][\p{Lu}\p{Lt}\p{N}\p{M}\'’._-]*(?:\h+[\p{Lu}\p{Lt}\p{N}][\p{Lu}\p{Lt}\p{N}\p{M}\'’._-]*){0,2}\h+\p{N}+)\h+(.+)$/u';
        $generalCue = '/^([\p{Lu}\p{Lt}\p{N}][\p{Lu}\p{Lt}\p{N}\p{M}\'’._-]*(?:\h+[\p{Lu}\p{Lt}\p{N}][\p{Lu}\p{Lt}\p{N}\p{M}\'’._-]*){0,3})\h+(.+)$/u';
        if (preg_match($numericCue, $text, $match) !== 1
            && preg_match($generalCue, $text, $match) !== 1) {
            return null;
        }

        $cue = trim($match[1]);
        $body = trim($match[2]);
        if ($this->length($cue) > 32
            || preg_match_all('/[\p{L}\p{M}]/u', $cue, $letters) === false
            || count($letters[0]) < 2
            || preg_match('/\p{Ll}/u', $body) !== 1) {
            return null;
        }

        return ['cue' => $cue, 'body' => $body];
    }

    private function pdfDialogueCueKey(string $cue): string
    {
        $key = preg_replace('/\p{N}+/u', '#', $cue) ?? $cue;
        $key = preg_replace('/\s+/u', ' ', trim($key)) ?? trim($key);

        return $this->pdfLowercaseToken($key);
    }

    /**
     * Preserve compact visual display labels as headings before text repair
     * discards their font information. This requires a substantial font-size
     * contrast within the same page, avoiding a lexical guess about ordinary
     * short prose or list introductions.
     *
     * @param list<array{text: string, layout: array<string, mixed>|null}> $records
     * @return list<array{text: string, layout: array<string, mixed>|null}>
     */
    private function markPdfDisplayHeadingRecords(array $records): array
    {
        $fontSizesByPage = [];
        foreach ($records as $record) {
            $layout = $record['layout'];
            if (!$this->pdfLayoutHasGeometry($layout) || ($layout['code'] ?? false) === true) {
                continue;
            }
            $fontSizesByPage[(int) $layout['page']][] = max(1.0, (float) $layout['fontSize']);
        }

        $medianFontSizesByPage = [];
        foreach ($fontSizesByPage as $page => $fontSizes) {
            $medianFontSizesByPage[$page] = max(1.0, $this->median($fontSizes));
        }

        foreach ($records as &$record) {
            $layout = $record['layout'];
            $text = trim($record['text']);
            $displayLetters = preg_replace('/[^\p{L}\p{M}]+/u', '', $text) ?? '';
            if (!$this->pdfLayoutHasGeometry($layout)
                || ($layout['code'] ?? false) === true
                || isset($layout['sourcePdfLineOrientedGroup'])
                || $text === ''
                // Font size alone cannot prove that an isolated map glyph or
                // two-letter diagram fragment is a document heading. Tagged
                // structure and other explicit paths remain available for
                // genuinely compact headings.
                || $this->length($displayLetters) < 3
                || preg_match('/^[^\p{L}\p{N}]*\p{Lu}/u', $text) !== 1
                || !$this->pdfLineHasDisplayHeadingTitleShape($text)
                || $this->lineHasPdfListBlockEvidence($text)
                || $this->lineLooksLikeUrlOnly($text)
                || $this->lineLooksLikePdfReferenceEntry($text)
                || count($this->pdfLineWordTokens($text)) > 6
                || $this->length($text) > 88) {
                continue;
            }

            $pageMedian = $medianFontSizesByPage[(int) $layout['page']] ?? 1.0;
            $fontSize = max(1.0, (float) $layout['fontSize']);
            if ($fontSize >= max(16.0, $pageMedian * 1.65)) {
                if (($record['layout']['sourcePdfDisplayHeading'] ?? false) !== true) {
                    $this->inferredHeadingBoundaryCount++;
                }
                $record['layout']['sourcePdfDisplayHeading'] = true;
            }
        }
        unset($record);

        return $records;
    }

    private function pdfLineHasDisplayHeadingTitleShape(string $line): bool
    {
        $words = $this->pdfLineWordTokens($line);
        if (count($words) === 1) {
            // Oversized interrogative guide labels ("Why?", "When?") are
            // genuine one-word display headings even though the ordinary
            // section-label gate conservatively rejects terminal question
            // punctuation. Keep the proof shape lexical and generic.
            return preg_match(
                '/^[^\p{L}\p{N}]*\p{Lu}[\p{L}\p{M}]*(?:[?:])?$/u',
                trim($line)
            ) === 1;
        }
        if (!$this->repairedLineLooksLikeSectionLabel($line)) {
            return false;
        }
        $titleInitials = 0;
        foreach ($words as $word) {
            if (preg_match('/^\p{Lu}/u', $word) === 1) {
                $titleInitials++;
            }
        }

        return $titleInitials >= 2 && $titleInitials / count($words) >= 0.60;
    }

    /**
     * Repeated isolated numbers in the bottom page band are page furniture,
     * not document paragraphs. Require the same horizontal slot on at least
     * two pages so an ordinary numeric line in the body is never enough to be
     * discarded. The test is entirely geometric and works with any digits.
     *
     * @param list<array{text: string, layout: array<string, mixed>|null}> $records
     * @return list<array{text: string, layout: array<string, mixed>|null}>
     */
    private function removeRepeatedPdfPageNumberRecords(array $records): array
    {
        $boundsByPage = [];
        foreach ($records as $record) {
            $layout = is_array($record['layout'] ?? null) ? $record['layout'] : null;
            if (!$this->pdfLayoutHasGeometry($layout)) {
                continue;
            }
            $page = (int) $layout['page'];
            $y1 = (float) $layout['y1'];
            $y2 = (float) $layout['y2'];
            $x1 = (float) $layout['x1'];
            $x2 = (float) $layout['x2'];
            $boundsByPage[$page]['minY'] = min($boundsByPage[$page]['minY'] ?? $y1, $y1);
            $boundsByPage[$page]['maxY'] = max($boundsByPage[$page]['maxY'] ?? $y2, $y2);
            $boundsByPage[$page]['minX'] = min($boundsByPage[$page]['minX'] ?? $x1, $x1);
            $boundsByPage[$page]['maxX'] = max($boundsByPage[$page]['maxX'] ?? $x2, $x2);
        }

        $candidates = [];
        foreach ($records as $index => $record) {
            $text = trim((string) ($record['text'] ?? ''));
            $layout = is_array($record['layout'] ?? null) ? $record['layout'] : null;
            $exactEndpoint = $this->pdfPageNumberFurnitureRecordEndpoint($record);
            if (preg_match('/^\p{N}{1,4}$/u', $text) !== 1
                || !$this->pdfLayoutHasGeometry($layout)
                || $exactEndpoint === null) {
                continue;
            }
            $page = (int) $layout['page'];
            $bounds = $boundsByPage[$page] ?? null;
            if (!is_array($bounds)) {
                continue;
            }
            $fontSize = max(1.0, (float) $layout['fontSize']);
            $pageTextHeight = max(1.0, (float) $bounds['maxY'] - (float) $bounds['minY']);
            $bottomLimit = (float) $bounds['minY'] + max($fontSize * 3.0, $pageTextHeight * 0.15);
            if ((float) $layout['y2'] > $bottomLimit) {
                continue;
            }
            $projection = $this->pdfSourceOccurrenceComparableText($text);
            $candidates[$index] = [
                'page' => $page,
                'text' => $text,
                'centerX' => ((float) $layout['x1'] + (float) $layout['x2']) / 2.0,
                'fontSize' => $fontSize,
                'endpoint' => [
                    'sourceOccurrenceId' => $exactEndpoint['sourceOccurrenceId'],
                    'sourceIndex' => $exactEndpoint['sourceIndex'],
                    'page' => $page,
                    'sourceStream' => $exactEndpoint['sourceStream'],
                    'projectionDigest' => hash('sha256', $projection),
                    'exactRange' => $exactEndpoint['range'],
                    'bounds' => $this->pdfSourceEvidenceBounds($layout),
                    'centerX' => ((float) $layout['x1'] + (float) $layout['x2']) / 2.0,
                    'height' => max(0.0, (float) $layout['y2'] - (float) $layout['y1']),
                ],
            ];
        }
        $proofsByRecordIndex = [];
        $deferredProofsByRecordIndex = [];
        foreach (count($candidates) >= 2 ? $candidates : [] as $index => $candidate) {
            $peers = [$index => $candidate];
            foreach ($candidates as $otherIndex => $other) {
                if ($otherIndex === $index) {
                    continue;
                }
                $horizontalTolerance = max(30.0, max($candidate['fontSize'], $other['fontSize']) * 3.0);
                if (abs($candidate['centerX'] - $other['centerX']) <= $horizontalTolerance) {
                    $peers[$otherIndex] = $other;
                }
            }
            $peersByPage = [];
            foreach ($peers as $peerIndex => $peer) {
                $peersByPage[$peer['page']][$peerIndex] = $peer;
            }
            if (count($peersByPage) < 2
                || count(array_filter(
                    $peersByPage,
                    static fn (array $pagePeers): bool => count($pagePeers) !== 1
                )) > 0) {
                continue;
            }
            $peerList = array_values($peers);
            $isClique = true;
            foreach ($peerList as $leftIndex => $left) {
                foreach (array_slice($peerList, $leftIndex + 1) as $right) {
                    $tolerance = max(30.0, max($left['fontSize'], $right['fontSize']) * 3.0);
                    if (abs($left['centerX'] - $right['centerX']) > $tolerance) {
                        $isClique = false;
                        break 2;
                    }
                }
            }
            if (!$isClique) {
                continue;
            }
            $peerEndpoints = array_column($peerList, 'endpoint');
            usort($peerEndpoints, static fn (array $left, array $right): int =>
                ($left['page'] <=> $right['page'])
                    ?: ($left['sourceIndex'] <=> $right['sourceIndex'])
                    ?: strcmp($left['sourceOccurrenceId'], $right['sourceOccurrenceId'])
            );
            $payload = [
                'version' => 1,
                'method' => 'exact-repeated-bottom-slot-page-number-removal',
                'sourceSha256' => $this->sourceSha256,
                'targetSourceOccurrenceId' => $candidate['endpoint']['sourceOccurrenceId'],
                'peers' => $peerEndpoints,
            ];
            $payload['proofDigest'] = hash('sha256', json_encode(
                $payload,
                JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_PRESERVE_ZERO_FRACTION
            ) ?: '');
            $proofsByRecordIndex[$index] = $payload;
        }

        // A one-page source cannot prove a folio by recurrence. It can still
        // prove one when an isolated bottom-band number occupies the extreme
        // right slot opposite a long, exact footer line on the same baseline.
        // Require one uniquely qualifying source-bound footer companion and a
        // wide empty gutter so an ordinary numeric cell is never sufficient.
        foreach ($candidates as $index => $candidate) {
            if (isset($proofsByRecordIndex[$index])) {
                continue;
            }
            $pageBounds = $boundsByPage[$candidate['page']] ?? null;
            if (!is_array($pageBounds)) {
                continue;
            }
            $contexts = [];
            foreach ($records as $contextIndex => $contextRecord) {
                if ($contextIndex === $index) {
                    continue;
                }
                $contextLayout = is_array($contextRecord['layout'] ?? null)
                    ? $contextRecord['layout']
                    : null;
                $contextText = trim((string) ($contextRecord['text'] ?? ''));
                $contextProjection = $this->pdfSourceOccurrenceComparableText($contextText);
                $contextEndpoint = $this->pdfPageNumberFurnitureRecordEndpoint($contextRecord);
                if (!$this->pdfLayoutHasGeometry($contextLayout)
                    || (int) $contextLayout['page'] !== $candidate['page']
                    || $contextEndpoint === null
                    || preg_match('/^\p{N}{1,4}$/u', $contextText) === 1
                    || mb_strlen($contextProjection, 'UTF-8') < 12
                    || count($this->pdfLineWordTokens($contextProjection)) < 3) {
                    continue;
                }
                $contextFontSize = max(1.0, (float) $contextLayout['fontSize']);
                $pageTextHeight = max(
                    1.0,
                    (float) $pageBounds['maxY'] - (float) $pageBounds['minY']
                );
                $bottomLimit = (float) $pageBounds['minY']
                    + max($contextFontSize * 3.0, $pageTextHeight * 0.15);
                if ((float) $contextLayout['y2'] > $bottomLimit) {
                    continue;
                }
                $contextSourceEndpoint = [
                    'sourceOccurrenceId' => $contextEndpoint['sourceOccurrenceId'],
                    'sourceIndex' => $contextEndpoint['sourceIndex'],
                    'page' => $contextEndpoint['page'],
                    'sourceStream' => $contextEndpoint['sourceStream'],
                    'projectionDigest' => hash('sha256', $contextProjection),
                    'exactRange' => $contextEndpoint['range'],
                    'bounds' => $this->pdfSourceEvidenceBounds($contextLayout),
                    'centerX' => ((float) $contextLayout['x1'] + (float) $contextLayout['x2']) / 2.0,
                    'height' => max(0.0, (float) $contextLayout['y2'] - (float) $contextLayout['y1']),
                ];
                if (!$this->pdfBottomFooterCompanionGeometryIsValid(
                    $candidate['endpoint'],
                    $contextSourceEndpoint,
                    $pageBounds
                )) {
                    continue;
                }
                $contexts[] = $contextSourceEndpoint;
            }
            if (count($contexts) !== 1) {
                continue;
            }
            $payload = [
                'version' => 1,
                'method' => 'exact-single-page-bottom-footer-companion-page-number-removal',
                'sourceSha256' => $this->sourceSha256,
                'targetSourceOccurrenceId' => $candidate['endpoint']['sourceOccurrenceId'],
                'targetText' => (string) ($candidate['text'] ?? ''),
                'peers' => [$candidate['endpoint']],
                'footerContext' => $contexts[0],
            ];
            $payload['proofDigest'] = hash('sha256', json_encode(
                $payload,
                JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_PRESERVE_ZERO_FRACTION
            ) ?: '');
            $deferredProofsByRecordIndex[$index] = $payload;
        }
        if ($proofsByRecordIndex === [] && $deferredProofsByRecordIndex === []) {
            return $records;
        }

        foreach ($proofsByRecordIndex as $index => $proof) {
            $sourceId = $proof['targetSourceOccurrenceId'];
            if (is_string($sourceId) && $sourceId !== '') {
                $this->removedPageNumberFurnitureProofsBySourceId[$sourceId] = $proof;
            }
        }
        foreach ($deferredProofsByRecordIndex as $index => $proof) {
            $sourceId = $proof['targetSourceOccurrenceId'];
            if (is_string($sourceId)
                && $sourceId !== ''
                && !isset($this->removedPageNumberFurnitureProofsBySourceId[$sourceId])) {
                $this->deferredSinglePageNumberFurnitureProofsBySourceId[$sourceId] = $proof;
            }
        }

        if ($proofsByRecordIndex === []) {
            return $records;
        }

        return array_values(array_filter(
            $records,
            static fn (array $_record, int $index): bool => !isset($proofsByRecordIndex[$index]),
            ARRAY_FILTER_USE_BOTH
        ));
    }

    /**
     * Removing the one-page folio during semantic-record preparation changes
     * which fallback candidate owns the page. Defer only that signed case
     * until the final AST exists, then require one unique standalone paragraph
     * with the exact source text. Repeated multi-page folios keep their
     * established record-stage removal path.
     *
     * @param list<AstNode> $blocks
     * @return array{
     *     blocks:list<AstNode>,
     *     removedCount:int,
     *     pageProjectionReplacements:array<int,string>,
     *     pageProjectionProofPreserved:bool
     * }
     */
    private function pdfBlocksWithoutProvenSinglePageNumberParagraphs(array $blocks): array
    {
        $proofCountsByText = [];
        foreach ($this->deferredSinglePageNumberFurnitureProofsBySourceId as $proof) {
            if (($proof['method'] ?? null)
                    !== 'exact-single-page-bottom-footer-companion-page-number-removal'
                || !is_string($proof['targetText'] ?? null)
                || preg_match('/^\p{N}{1,4}$/u', $proof['targetText']) !== 1) {
                continue;
            }
            $proofCountsByText[$proof['targetText']] =
                ($proofCountsByText[$proof['targetText']] ?? 0) + 1;
        }
        if ($proofCountsByText === []) {
            return ['blocks' => $blocks, 'removedCount' => 0];
        }

        $paragraphIndexesByText = [];
        foreach ($blocks as $index => $block) {
            if ($block->type !== 'paragraph') {
                continue;
            }
            $text = trim((string) $block->attr('text', ''));
            if (isset($proofCountsByText[$text])) {
                $paragraphIndexesByText[$text][] = $index;
            }
        }
        $removeIndexes = [];
        foreach ($proofCountsByText as $text => $proofCount) {
            $indexes = $paragraphIndexesByText[$text] ?? [];
            if ($proofCount === 1 && count($indexes) === 1) {
                $removeIndexes[$indexes[0]] = true;
            }
        }
        if ($removeIndexes === []) {
            return ['blocks' => $blocks, 'removedCount' => 0];
        }

        return [
            'blocks' => array_values(array_filter(
                $blocks,
                static fn (AstNode $_block, int $index): bool => !isset($removeIndexes[$index]),
                ARRAY_FILTER_USE_BOTH
            )),
            'removedCount' => count($removeIndexes),
        ];
    }

    /**
     * @param array<string,mixed> $proof
     * @param list<array<string,mixed>> $lineItems
     */
    private function pdfRepeatedPageNumberFurnitureProofMatchesSourceItems(
        array $proof,
        string $targetSourceId,
        array $lineItems
    ): bool {
        $method = $proof['method'] ?? null;
        $singlePageFooterCompanion = $method
            === 'exact-single-page-bottom-footer-companion-page-number-removal';
        if (($proof['version'] ?? null) !== 1
            || !in_array($method, [
                'exact-repeated-bottom-slot-page-number-removal',
                'exact-single-page-bottom-footer-companion-page-number-removal',
            ], true)
            || ($proof['sourceSha256'] ?? null) !== $this->sourceSha256
            || ($proof['targetSourceOccurrenceId'] ?? null) !== $targetSourceId
            || !is_array($proof['peers'] ?? null)
            || !array_is_list($proof['peers'])
            || ($singlePageFooterCompanion
                ? count($proof['peers']) !== 1
                    || !is_array($proof['footerContext'] ?? null)
                    || !is_string($proof['targetText'] ?? null)
                    || preg_match('/^\p{N}{1,4}$/u', $proof['targetText']) !== 1
                : count($proof['peers']) < 2)
            || !is_string($proof['proofDigest'] ?? null)) {
            return false;
        }
        $payload = $proof;
        unset($payload['proofDigest']);
        if (!hash_equals($proof['proofDigest'], hash('sha256', json_encode(
            $payload,
            JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_PRESERVE_ZERO_FRACTION
        ) ?: ''))) {
            return false;
        }

        $pageBounds = [];
        $itemsById = [];
        foreach ($lineItems as $globalSourceIndex => $item) {
            if (!is_int($item['sourcePdfGlobalSourceIndex'] ?? null)) {
                $item['sourcePdfGlobalSourceIndex'] = $globalSourceIndex;
            }
            $id = is_string($item['id'] ?? null) ? $item['id'] : '';
            if ($id !== '') {
                if (isset($itemsById[$id])) {
                    return false;
                }
                $itemsById[$id] = $item;
            }
            $geometry = is_array($item['sourceGeometry'] ?? null)
                ? $item['sourceGeometry']
                : null;
            if (!$this->pdfSourceBoundsAreValid(is_array($geometry) ? $geometry : [])) {
                continue;
            }
            $page = max(1, (int) ($item['page'] ?? 1));
            $pageBounds[$page]['minY'] = min(
                $pageBounds[$page]['minY'] ?? (float) $geometry['y1'],
                (float) $geometry['y1']
            );
            $pageBounds[$page]['maxY'] = max(
                $pageBounds[$page]['maxY'] ?? (float) $geometry['y2'],
                (float) $geometry['y2']
            );
            $pageBounds[$page]['minX'] = min(
                $pageBounds[$page]['minX'] ?? (float) $geometry['x1'],
                (float) $geometry['x1']
            );
            $pageBounds[$page]['maxX'] = max(
                $pageBounds[$page]['maxX'] ?? (float) $geometry['x2'],
                (float) $geometry['x2']
            );
        }

        $canonicalPeers = [];
        $pages = [];
        $targetFound = false;
        foreach ($proof['peers'] as $peer) {
            $sourceId = is_array($peer) && is_string($peer['sourceOccurrenceId'] ?? null)
                ? $peer['sourceOccurrenceId']
                : '';
            $item = $itemsById[$sourceId] ?? null;
            if ($sourceId === '' || !is_array($item)) {
                return false;
            }
            $endpoint = $this->pdfRepeatedPageNumberSourceEndpoint(
                $item,
                $pageBounds[(int) ($item['page'] ?? 0)] ?? null
            );
            if ($endpoint === null || $endpoint !== $peer || isset($pages[$endpoint['page']])) {
                return false;
            }
            $pages[$endpoint['page']] = true;
            $canonicalPeers[] = $endpoint;
            $targetFound = $targetFound || $sourceId === $targetSourceId;
        }
        if (!$targetFound || ($singlePageFooterCompanion ? count($pages) !== 1 : count($pages) < 2)) {
            return false;
        }
        if ($singlePageFooterCompanion) {
            $contextProof = $proof['footerContext'];
            $contextSourceId = is_string($contextProof['sourceOccurrenceId'] ?? null)
                ? $contextProof['sourceOccurrenceId']
                : '';
            $contextItem = $itemsById[$contextSourceId] ?? null;
            $targetItem = $itemsById[$targetSourceId] ?? null;
            $target = $canonicalPeers[0] ?? null;
            if ($contextSourceId === ''
                || !is_array($contextItem)
                || !is_array($targetItem)
                || trim((string) ($targetItem['text'] ?? '')) !== $proof['targetText']
                || !is_array($target)
                || ($context = $this->pdfBottomFooterCompanionSourceEndpoint(
                    $contextItem,
                    $pageBounds[(int) ($contextItem['page'] ?? 0)] ?? null
                )) === null
                || $context !== $contextProof
                || !$this->pdfBottomFooterCompanionGeometryIsValid(
                    $target,
                    $context,
                    $pageBounds[(int) $target['page']] ?? null
                )) {
                return false;
            }

            return true;
        }
        foreach ($canonicalPeers as $leftIndex => $left) {
            foreach (array_slice($canonicalPeers, $leftIndex + 1) as $right) {
                $tolerance = max(30.0, max($left['height'], $right['height']) * 3.0);
                if (abs($left['centerX'] - $right['centerX']) > $tolerance) {
                    return false;
                }
            }
        }

        return true;
    }

    /**
     * @param array<string,mixed> $item
     * @param array{minX:float,maxX:float,minY:float,maxY:float}|null $pageBounds
     * @return array<string,mixed>|null
     */
    private function pdfBottomFooterCompanionSourceEndpoint(
        array $item,
        ?array $pageBounds
    ): ?array {
        $text = trim((string) ($item['text'] ?? ''));
        $projection = $this->pdfSourceOccurrenceComparableText($text);
        $geometry = is_array($item['sourceGeometry'] ?? null) ? $item['sourceGeometry'] : null;
        $sourceId = is_string($item['id'] ?? null) ? $item['id'] : '';
        $sourceIndex = is_int($item['sourcePdfGlobalSourceIndex'] ?? null)
            ? $item['sourcePdfGlobalSourceIndex']
            : null;
        if ($sourceId === ''
            || $sourceIndex === null
            || $projection === ''
            || mb_strlen($projection, 'UTF-8') < 12
            || count($this->pdfLineWordTokens($projection)) < 3
            || preg_match('/^\p{N}{1,4}$/u', $text) === 1
            || !$this->pdfSourceBoundsAreValid(is_array($geometry) ? $geometry : [])
            || !is_array($pageBounds)) {
            return null;
        }
        $fontSize = max(1.0, (float) ($geometry['fontSize'] ?? 1.0));
        $pageTextHeight = max(1.0, $pageBounds['maxY'] - $pageBounds['minY']);
        $bottomLimit = $pageBounds['minY'] + max($fontSize * 3.0, $pageTextHeight * 0.15);
        if ((float) $geometry['y2'] > $bottomLimit) {
            return null;
        }

        return [
            'sourceOccurrenceId' => $sourceId,
            'sourceIndex' => $sourceIndex,
            'page' => max(1, (int) ($item['page'] ?? 1)),
            'sourceStream' => max(1, (int) ($item['stream'] ?? 1)),
            'projectionDigest' => hash('sha256', $projection),
            'exactRange' => [
                'sourceIndex' => $sourceIndex,
                'sourceStart' => 0,
                'sourceEnd' => strlen($projection),
            ],
            'bounds' => $this->pdfSourceEvidenceBounds($geometry),
            'centerX' => ((float) $geometry['x1'] + (float) $geometry['x2']) / 2.0,
            'height' => max(0.0, (float) $geometry['y2'] - (float) $geometry['y1']),
        ];
    }

    /**
     * @param array<string,mixed> $target
     * @param array<string,mixed> $context
     * @param array{minX:float,maxX:float,minY:float,maxY:float}|null $pageBounds
     */
    private function pdfBottomFooterCompanionGeometryIsValid(
        array $target,
        array $context,
        ?array $pageBounds
    ): bool {
        $targetBounds = is_array($target['bounds'] ?? null) ? $target['bounds'] : null;
        $contextBounds = is_array($context['bounds'] ?? null) ? $context['bounds'] : null;
        if (!is_array($pageBounds)
            || !is_array($targetBounds)
            || !is_array($contextBounds)
            || (int) ($target['page'] ?? 0) !== (int) ($context['page'] ?? -1)) {
            return false;
        }
        foreach (['minX', 'maxX', 'minY', 'maxY'] as $key) {
            if (!is_numeric($pageBounds[$key] ?? null)) {
                return false;
            }
        }
        foreach ([$targetBounds, $contextBounds] as $bounds) {
            foreach (['x1', 'y1', 'x2', 'y2'] as $key) {
                if (!is_numeric($bounds[$key] ?? null)) {
                    return false;
                }
            }
        }
        $pageWidth = max(1.0, (float) $pageBounds['maxX'] - (float) $pageBounds['minX']);
        $targetHeight = max(0.1, (float) ($target['height'] ?? 0.0));
        $contextHeight = max(0.1, (float) ($context['height'] ?? 0.0));
        $targetMidY = ((float) $targetBounds['y1'] + (float) $targetBounds['y2']) / 2.0;
        $contextMidY = ((float) $contextBounds['y1'] + (float) $contextBounds['y2']) / 2.0;
        $gap = (float) $targetBounds['x1'] - (float) $contextBounds['x2'];
        $contextWidth = (float) $contextBounds['x2'] - (float) $contextBounds['x1'];

        return (float) ($target['centerX'] ?? 0.0)
                >= (float) $pageBounds['minX'] + $pageWidth * 0.85
            && (float) $contextBounds['x1']
                <= (float) $pageBounds['minX'] + $pageWidth * 0.15
            && $gap >= max(36.0, max($targetHeight, $contextHeight) * 8.0)
            && $contextWidth >= max(72.0, $contextHeight * 12.0)
            && abs($targetMidY - $contextMidY)
                <= max(1.0, max($targetHeight, $contextHeight) * 0.4)
            && min($targetHeight, $contextHeight) / max($targetHeight, $contextHeight) >= 0.75;
    }

    /**
     * @param array<string,mixed> $item
     * @param array{minY:float,maxY:float}|null $pageBounds
     * @return array<string,mixed>|null
     */
    private function pdfRepeatedPageNumberSourceEndpoint(array $item, ?array $pageBounds): ?array
    {
        $text = trim((string) ($item['text'] ?? ''));
        $geometry = is_array($item['sourceGeometry'] ?? null) ? $item['sourceGeometry'] : null;
        $sourceId = is_string($item['id'] ?? null) ? $item['id'] : '';
        $sourceIndex = is_int($item['sourcePdfGlobalSourceIndex'] ?? null)
            ? $item['sourcePdfGlobalSourceIndex']
            : null;
        if ($sourceId === ''
            || $sourceIndex === null
            || preg_match('/^\p{N}{1,4}$/u', $text) !== 1
            || !$this->pdfSourceBoundsAreValid(is_array($geometry) ? $geometry : [])
            || !is_array($pageBounds)) {
            return null;
        }
        $fontSize = max(1.0, (float) ($geometry['fontSize'] ?? 1.0));
        $pageTextHeight = max(1.0, $pageBounds['maxY'] - $pageBounds['minY']);
        $bottomLimit = $pageBounds['minY'] + max($fontSize * 3.0, $pageTextHeight * 0.15);
        if ((float) $geometry['y2'] > $bottomLimit) {
            return null;
        }
        $projection = $this->pdfSourceOccurrenceComparableText($text);

        return [
            'sourceOccurrenceId' => $sourceId,
            'sourceIndex' => $sourceIndex,
            'page' => max(1, (int) ($item['page'] ?? 1)),
            'sourceStream' => max(1, (int) ($item['stream'] ?? 1)),
            'projectionDigest' => hash('sha256', $projection),
            'exactRange' => [
                'sourceIndex' => $sourceIndex,
                'sourceStart' => 0,
                'sourceEnd' => strlen($projection),
            ],
            'bounds' => $this->pdfSourceEvidenceBounds($geometry),
            'centerX' => ((float) $geometry['x1'] + (float) $geometry['x2']) / 2.0,
            'height' => max(0.0, (float) $geometry['y2'] - (float) $geometry['y1']),
        ];
    }

    /**
     * Stacked-table recognition happens after prose records are merged. The
     * record immediately before a confirmed table therefore has no table
     * boundary while it is being merged. Revisit only that structural shape
     * and drop an unresolved tail rather than presenting it as prose.
     *
     * @param list<string> $lines
     * @param array<int,array<string,mixed>> $exactWholeSourceMergedLineSpans
     * @param array<int,array<string,mixed>>|null $retainedWholeSourceMergedLineSpans
     * @return list<string>
     */
    private function trimIncompletePdfMergedLinesBeforeStackedTables(
        array $lines,
        array $exactWholeSourceMergedLineSpans = [],
        ?array &$retainedWholeSourceMergedLineSpans = null
    ): array {
        $collectRetainedSpans = func_num_args() >= 3;
        $retainedWholeSourceMergedLineSpans = [];
        $occurrences = [];
        foreach ($lines as $line) {
            $key = $this->pdfSourceOccurrenceComparableText(
                $this->pdfTextWithoutSemanticPrefixes(trim($line))
            );
            if ($key !== '') {
                $occurrences[$key] = ($occurrences[$key] ?? 0) + 1;
            }
        }

        $trimmed = [];
        foreach ($lines as $index => $line) {
            $line = trim($line);
            $followingTable = isset($lines[$index + 1])
                && $this->stackedTableRowsAt($lines, $index + 1)['rows'] !== [];
            $lineKey = $this->pdfSourceOccurrenceComparableText(
                $this->pdfTextWithoutSemanticPrefixes($line)
            );
            // Payroll and rate tables can repeat one long, punctuation-free
            // column header before several stacked grids. Recurrence makes
            // that source line table structure, not an unresolved prose tail;
            // retain the existing one-off tail cleanup for nonrecurring text.
            $repeatedTableHeader = $followingTable
                && $lineKey !== ''
                && (int) ($occurrences[$lineKey] ?? 0) >= 2;
            if (!$followingTable
                || $repeatedTableHeader
                || str_starts_with($line, self::PDF_CODE_BLOCK_PREFIX)
                || str_starts_with($line, PdfFormulaSemanticProcessor::LINE_PREFIX)
                || str_starts_with($line, self::PDF_LINE_BLOCK_PREFIX)
                || str_starts_with($line, self::PDF_MAP_LABEL_PREFIX)
                || str_starts_with($line, self::PDF_FRONT_MATTER_PREFIX)
                || str_starts_with($line, self::PDF_LAYOUT_LABEL_PREFIX)
                || $this->repairedPdfMergedLineHasExactWholeSourceSpan(
                    $line,
                    $exactWholeSourceMergedLineSpans[$index] ?? null
                )
                || $this->lineHasPdfListBlockEvidence($line)
                || $this->lineLooksLikeUrlOnly($line)
                || $this->repairedLineLooksLikeSectionLabel($line)
                || preg_match('/[.!?;:]\s*$/u', $line) === 1
                || preg_match('/[-\x{00AD}\x{2010}-\x{2015}]\s*$/u', $line) === 1) {
                if ($line !== '') {
                    $outputIndex = count($trimmed);
                    $trimmed[] = $line;
                    $span = $exactWholeSourceMergedLineSpans[$index] ?? null;
                    if ($collectRetainedSpans
                        && $this->repairedPdfMergedLineHasExactWholeSourceSpan(
                            $line,
                            $span
                        )) {
                        $retainedWholeSourceMergedLineSpans[$outputIndex] = $span;
                    }
                }
                continue;
            }

            $prefix = $this->completePdfSentencePrefix($line);
            if ($prefix !== '' && count($this->pdfLineWordTokens($prefix)) >= 5) {
                $trimmed[] = $prefix;
                continue;
            }
            if (count($this->pdfLineWordTokens($line)) < 5 && $line !== '') {
                $trimmed[] = $line;
            }
        }

        return $trimmed;
    }

    /**
     * Mark only a uniquely adjacent pair of identical URL occurrences whose
     * exact horizontal paint boxes substantially coincide. The later source
     * occurrence is the redundant overprint; ordinary repeated links at
     * distinct positions remain content.
     *
     * @param list<array<string,mixed>> $lineItems
     */
    private function markSourcePdfOverprintedDuplicateArtifacts(array &$lineItems): void
    {
        $this->sourcePdfOverprintedDuplicateArtifactProofsBySourceId = [];
        foreach ($this->sourcePdfOverprintedDuplicateArtifactProofs($lineItems) as $sourceId => $proof) {
            foreach ($lineItems as &$item) {
                if (($item['id'] ?? null) !== $sourceId) {
                    continue;
                }
                $item['sourcePdfOverprintedDuplicateArtifactEvidence'] = $proof;
                $this->sourcePdfOverprintedDuplicateArtifactProofsBySourceId[$sourceId] = $proof;
                break;
            }
            unset($item);
        }
    }

    /**
     * @param list<array<string,mixed>> $lineItems
     * @return array<string,array<string,mixed>>
     */
    private function sourcePdfOverprintedDuplicateArtifactProofs(array $lineItems): array
    {
        $candidatesByIdentity = [];
        for ($index = 0, $count = count($lineItems) - 1; $index < $count; $index++) {
            $retained = $this->sourcePdfOverprintedDuplicateEndpoint(
                $lineItems[$index],
                $index
            );
            $artifact = $this->sourcePdfOverprintedDuplicateEndpoint(
                $lineItems[$index + 1],
                $index + 1
            );
            if ($retained === null
                || $artifact === null
                || $artifact['globalSourceIndex'] !== $retained['globalSourceIndex'] + 1
                || $artifact['page'] !== $retained['page']
                || $artifact['stream'] !== $retained['stream']
                || !hash_equals($artifact['projectionDigest'], $retained['projectionDigest'])
                || $artifact['significantBytes'] !== $retained['significantBytes']
                || !$this->sourcePdfOverprintedDuplicateBoundsCoincide(
                    $retained['bounds'],
                    $artifact['bounds']
                )) {
                continue;
            }
            $identity = implode("\0", [
                (string) $retained['page'],
                (string) $retained['stream'],
                $retained['projectionDigest'],
            ]);
            $candidatesByIdentity[$identity][] = [
                'retained' => $retained,
                'artifact' => $artifact,
            ];
        }

        $proofs = [];
        foreach ($candidatesByIdentity as $candidates) {
            if (count($candidates) !== 1) {
                continue;
            }
            $candidate = $candidates[0];
            $retained = $candidate['retained'];
            $artifact = $candidate['artifact'];
            $proof = [
                'version' => 1,
                'method' => 'exact-adjacent-overprinted-source-occurrences',
                'sourceSha256' => $this->sourceSha256,
                'page' => $retained['page'],
                'stream' => $retained['stream'],
                'significantBytes' => $retained['significantBytes'],
                'projectionDigest' => $retained['projectionDigest'],
                'retained' => $this->sourcePdfOverprintedDuplicateSignedEndpoint($retained),
                'artifact' => $this->sourcePdfOverprintedDuplicateSignedEndpoint($artifact),
            ];
            $proof['proofDigest'] = hash('sha256', json_encode(
                $proof,
                JSON_UNESCAPED_SLASHES
                    | JSON_UNESCAPED_UNICODE
                    | JSON_PRESERVE_ZERO_FRACTION
            ) ?: '');
            $proofs[$artifact['sourceOccurrenceId']] = $proof;
        }

        return $proofs;
    }

    /**
     * @param array<string,mixed> $item
     * @return array<string,mixed>|null
     */
    private function sourcePdfOverprintedDuplicateEndpoint(array $item, int $localIndex): ?array
    {
        $sourceId = is_string($item['id'] ?? null) ? $item['id'] : '';
        $text = trim((string) ($item['text'] ?? ''));
        $projection = $this->pdfSourceOccurrenceComparableText($text);
        $page = (int) ($item['page'] ?? 0);
        $stream = (int) ($item['stream'] ?? 0);
        $geometry = is_array($item['sourceGeometry'] ?? null)
            ? $item['sourceGeometry']
            : null;
        $globalSourceIndex = is_int($item['sourcePdfGlobalSourceIndex'] ?? null)
            ? $item['sourcePdfGlobalSourceIndex']
            : $localIndex;
        if ($sourceId === ''
            || $projection === ''
            || !$this->lineLooksLikeUrlOnly($text)
            || $page < 1
            || $stream < 1
            || $globalSourceIndex < 0
            || ($item['sourceGeometryMethod'] ?? null)
                !== 'exact-page-stream-character-offset'
            || $geometry === null
            || !$this->pdfSourceBoundsAreValid($geometry)
            || ($geometry['orientation'] ?? null) !== 'horizontal'
            || (int) ($geometry['page'] ?? 0) !== $page
            || (int) ($geometry['stream'] ?? 0) !== $stream) {
            return null;
        }
        $bounds = $this->pdfSourceEvidenceBounds($geometry);
        if ($bounds['x2'] <= $bounds['x1'] || $bounds['y2'] <= $bounds['y1']) {
            return null;
        }

        return [
            'sourceOccurrenceId' => $sourceId,
            'globalSourceIndex' => $globalSourceIndex,
            'localIndex' => $localIndex,
            'page' => $page,
            'stream' => $stream,
            'significantBytes' => strlen($projection),
            'projectionDigest' => hash('sha256', $projection),
            'exactRange' => [
                'sourceIndex' => $globalSourceIndex,
                'sourceStart' => 0,
                'sourceEnd' => strlen($projection),
            ],
            'bounds' => $bounds,
        ];
    }

    /** @param array<string,mixed> $endpoint @return array<string,mixed> */
    private function sourcePdfOverprintedDuplicateSignedEndpoint(array $endpoint): array
    {
        return [
            'sourceOccurrenceId' => $endpoint['sourceOccurrenceId'],
            'globalSourceIndex' => $endpoint['globalSourceIndex'],
            'exactRange' => $endpoint['exactRange'],
            'bounds' => $endpoint['bounds'],
        ];
    }

    /** @param array<string,mixed> $left @param array<string,mixed> $right */
    private function sourcePdfOverprintedDuplicateBoundsCoincide(array $left, array $right): bool
    {
        if (!$this->pdfSourceBoundsAreValid($left) || !$this->pdfSourceBoundsAreValid($right)) {
            return false;
        }
        $leftWidth = (float) $left['x2'] - (float) $left['x1'];
        $leftHeight = (float) $left['y2'] - (float) $left['y1'];
        $rightWidth = (float) $right['x2'] - (float) $right['x1'];
        $rightHeight = (float) $right['y2'] - (float) $right['y1'];
        if (min($leftWidth, $leftHeight, $rightWidth, $rightHeight) <= 0.0) {
            return false;
        }
        $intersectionWidth = max(0.0, min((float) $left['x2'], (float) $right['x2'])
            - max((float) $left['x1'], (float) $right['x1']));
        $intersectionHeight = max(0.0, min((float) $left['y2'], (float) $right['y2'])
            - max((float) $left['y1'], (float) $right['y1']));
        $overlap = ($intersectionWidth * $intersectionHeight)
            / min($leftWidth * $leftHeight, $rightWidth * $rightHeight);
        $widthRatio = min($leftWidth, $rightWidth) / max($leftWidth, $rightWidth);
        $heightRatio = min($leftHeight, $rightHeight) / max($leftHeight, $rightHeight);

        return $overlap >= 0.80 && $widthRatio >= 0.90 && $heightRatio >= 0.90;
    }

    /**
     * @param array<string,mixed> $proof
     * @param list<array<string,mixed>> $lineItems
     */
    private function sourcePdfOverprintedDuplicateArtifactProofMatchesSourceItems(
        array $proof,
        array $lineItems
    ): bool {
        $artifactId = is_string($proof['artifact']['sourceOccurrenceId'] ?? null)
            ? $proof['artifact']['sourceOccurrenceId']
            : '';
        if ($artifactId === '' || !$this->sourcePdfSignedProofDigestMatches($proof)) {
            return false;
        }
        $expected = $this->sourcePdfOverprintedDuplicateArtifactProofs($lineItems)[$artifactId]
            ?? null;

        return is_array($expected) && $expected === $proof;
    }

    /**
     * Figure captions and other free-positioned text can be emitted as one
     * source line even when a later visual run is missing. Unlike a body
     * column, there is no reliable line rhythm to reconstruct that omission.
     * That uncertainty is evidence for preserving the source fragment, not
     * for deleting it. A future suppression may remove it only after binding
     * the exact source occurrence to a local replacement or artifact fact.
     *
     * @param list<array{text: string, layout: array<string, mixed>|null}> $records
     * @return list<array{text: string, layout: array<string, mixed>|null}>
     */
    private function trimIncompletePdfUnstructuredFragments(array $records): array
    {
        return $records;
    }

    /**
     * Mark a duplicated display sentence which is interleaved with an
     * unrelated prose lane in the source stream. Two consecutive source rows
     * must split at the same geometric lane boundary, use distinct and stable
     * font resources on each side, and reproduce one unique semantic phrase
     * elsewhere on the same page. A short same-font lead on the first display
     * baseline is then part of the redundant display, while each right-hand
     * suffix remains editable prose.
     *
     * @param list<array<string,mixed>> $sourceItems
     * @param list<array<string,mixed>> $positionedRuns
     */
    private function markSourcePdfCrossLaneDuplicateDisplayArtifacts(
        array &$sourceItems,
        array $positionedRuns
    ): void {
        if (count($sourceItems) < 4 || $positionedRuns === []) {
            return;
        }
        $runsBySourceIndex = [];
        foreach ($positionedRuns as $run) {
            $ranges = $this->pdfPositionedExactSourceRanges($run);
            $range = count($ranges) === 1 ? $ranges[0] : null;
            $sourceIndex = is_array($range) ? $range['sourceIndex'] : null;
            if (!is_int($sourceIndex)
                || $sourceIndex < 0
                || !isset($sourceItems[$sourceIndex])
                || !$this->pdfLayoutHasGeometry($run)) {
                continue;
            }
            $runsBySourceIndex[$sourceIndex][] = $run;
        }

        $splits = [];
        foreach ($runsBySourceIndex as $sourceIndex => $runs) {
            $split = $this->pdfCrossLaneDisplaySplitForSourceItem(
                $sourceIndex,
                $sourceItems[$sourceIndex],
                $runs
            );
            if ($split !== null) {
                $splits[$sourceIndex] = $split;
            }
        }

        $proofs = [];
        $claimedIndexes = [];
        foreach ($splits as $firstIndex => $first) {
            $secondIndex = $firstIndex + 1;
            $artifactIndex = $firstIndex - 1;
            $second = $splits[$secondIndex] ?? null;
            $artifactItem = $sourceItems[$artifactIndex] ?? null;
            $artifactRuns = $runsBySourceIndex[$artifactIndex] ?? [];
            if (!is_array($second)
                || !is_array($artifactItem)
                || $artifactRuns === []
                || isset(
                    $claimedIndexes[$artifactIndex],
                    $claimedIndexes[$firstIndex],
                    $claimedIndexes[$secondIndex]
                )
                || $first['page'] !== $second['page']
                || $first['stream'] !== $second['stream']
                || !hash_equals($first['leftFontDigest'], $second['leftFontDigest'])
                || !hash_equals($first['rightFontDigest'], $second['rightFontDigest'])
                || hash_equals($first['leftFontDigest'], $first['rightFontDigest'])) {
                continue;
            }
            $rowHeight = max(
                1.0,
                $first['bounds']['y2'] - $first['bounds']['y1'],
                $second['bounds']['y2'] - $second['bounds']['y1']
            );
            $rowStep = $first['bounds']['y1'] - $second['bounds']['y1'];
            if ($rowStep < $rowHeight * 0.55
                || $rowStep > $rowHeight * 1.55
                || abs($first['rightBounds']['x1'] - $second['rightBounds']['x1'])
                    > max(2.0, $rowHeight * 0.20)) {
                continue;
            }
            $artifact = $this->pdfWholeExactPositionedSourceItemEvidence(
                $artifactIndex,
                $artifactItem,
                $artifactRuns
            );
            if ($artifact === null
                || $artifact['page'] !== $first['page']
                || $artifact['stream'] !== $first['stream']
                || !hash_equals($artifact['fontDigest'], $first['leftFontDigest'])
                || count($this->pdfLineWordTokens($artifact['text'])) > 2
                || $this->length($artifact['projection']) > 16
                || abs($artifact['bounds']['y1'] - $first['leftBounds']['y1'])
                    > max(1.0, $rowHeight * 0.20)
                || $artifact['bounds']['x1'] >= $first['leftBounds']['x1']
                || $first['leftBounds']['x1'] - $artifact['bounds']['x2']
                    > max(3.0, $rowHeight * 0.45)) {
                continue;
            }

            $displayTokens = array_merge(
                $this->pdfComparableWordTokens($first['prefixText']),
                $this->pdfComparableWordTokens($second['prefixText'])
            );
            if (count($displayTokens) < 5 || count($displayTokens) > 18) {
                continue;
            }
            $counterpart = $this->pdfCrossLaneDisplayUniqueCounterpart(
                $sourceItems,
                $displayTokens,
                $first['page'],
                $first['stream'],
                [$artifactIndex, $firstIndex, $secondIndex],
                $first['leftBounds']
            );
            if ($counterpart === null) {
                continue;
            }

            $payload = [
                'version' => 1,
                'method' => 'exact-cross-lane-duplicate-display-prefix',
                'sourceSha256' => $this->sourceSha256,
                'page' => $first['page'],
                'stream' => $first['stream'],
                'artifact' => $artifact,
                'splitRows' => [$first, $second],
                'displayTokenDigest' => hash('sha256', implode("\0", $displayTokens)),
                'counterpart' => $counterpart,
            ];
            $payload['proofDigest'] = hash('sha256', json_encode(
                $payload,
                JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_PRESERVE_ZERO_FRACTION
            ) ?: '');
            $proofs[] = $payload;
            foreach ([$artifactIndex, $firstIndex, $secondIndex] as $claimedIndex) {
                $claimedIndexes[$claimedIndex] = true;
            }
        }

        foreach ($proofs as $proof) {
            $artifactIndex = $proof['artifact']['sourceIndex'];
            $sourceItems[$artifactIndex]['sourcePdfCrossLaneDisplayArtifactRole'] =
                'whole-display-artifact';
            $sourceItems[$artifactIndex]['sourcePdfCrossLaneDisplayArtifactEvidence'] = $proof;
            foreach ($proof['splitRows'] as $row) {
                $sourceIndex = $row['sourceIndex'];
                $sourceItems[$sourceIndex]['sourcePdfCrossLaneDisplayArtifactRole'] =
                    'display-prefix-projection';
                $sourceItems[$sourceIndex]['sourcePdfCrossLaneDisplayArtifactEvidence'] = $proof;
            }
        }
        $this->markSourcePdfMirroredDuplicateMapPairArtifacts(
            $sourceItems,
            $runsBySourceIndex
        );
    }

    /**
     * Detect two spatially translated copies of the same compact map label
     * pair when four consecutive source atoms are emitted in mirrored order
     * (A, B, B, A). One atom must be a decimal measurement and the other a
     * terminal label. A unique longer prose occurrence elsewhere must contain
     * the measurement before the label, proving that the two compact copies
     * are redundant display fragments rather than the only semantic text.
     *
     * @param list<array<string,mixed>> $sourceItems
     * @param array<int,list<array<string,mixed>>> $runsBySourceIndex
     */
    private function markSourcePdfMirroredDuplicateMapPairArtifacts(
        array &$sourceItems,
        array $runsBySourceIndex
    ): void {
        $claimed = [];
        for ($start = 0, $count = count($sourceItems) - 3; $start < $count; $start++) {
            $indexes = [$start, $start + 1, $start + 2, $start + 3];
            if (array_filter($indexes, static fn (int $index): bool => isset($claimed[$index])) !== []) {
                continue;
            }
            $members = [];
            foreach ($indexes as $index) {
                $runs = $runsBySourceIndex[$index] ?? [];
                $member = $runs === [] ? null : $this->pdfWholeExactPositionedSourceItemEvidence(
                    $index,
                    $sourceItems[$index],
                    $runs,
                    true
                );
                if ($member === null) {
                    continue 2;
                }
                $members[] = $member;
            }
            if (!hash_equals($members[0]['projection'], $members[3]['projection'])
                || !hash_equals($members[1]['projection'], $members[2]['projection'])
                || hash_equals($members[0]['projection'], $members[1]['projection'])
                || preg_match('/^\s*\d+(?:[.,]\d+)?\s*$/u', $members[1]['text']) !== 1
                || preg_match('/\p{L}/u', $members[0]['text']) !== 1
                || preg_match('/[.!?]\s*$/u', $members[0]['text']) !== 1
                || count($this->pdfLineWordTokens($members[0]['text'])) > 2
                || count($this->pdfLineWordTokens($members[1]['text'])) > 2
                || $this->length($members[0]['projection']) > 20
                || $this->length($members[1]['projection']) > 12) {
                continue;
            }
            $pages = array_values(array_unique(array_column($members, 'page'), SORT_NUMERIC));
            $streams = array_values(array_unique(array_column($members, 'stream'), SORT_NUMERIC));
            $fonts = array_values(array_unique(array_column($members, 'fontDigest')));
            if (count($pages) !== 1 || count($streams) !== 1 || count($fonts) !== 1) {
                continue;
            }

            $a0 = $members[0]['bounds'];
            $b0 = $members[1]['bounds'];
            $b1 = $members[2]['bounds'];
            $a1 = $members[3]['bounds'];
            $height = max(
                1.0,
                $a0['y2'] - $a0['y1'],
                $b0['y2'] - $b0['y1'],
                $b1['y2'] - $b1['y1'],
                $a1['y2'] - $a1['y1']
            );
            $translationX = $a1['x1'] - $a0['x1'];
            $translationY = $a1['y1'] - $a0['y1'];
            $translationTolerance = max(2.0, $height * 0.30);
            $bTranslationX = $b1['x1'] - $b0['x1'];
            $bTranslationY = $b1['y1'] - $b0['y1'];
            $pairDistance = static function (array $left, array $right): float {
                $leftX = ($left['x1'] + $left['x2']) / 2.0;
                $leftY = ($left['y1'] + $left['y2']) / 2.0;
                $rightX = ($right['x1'] + $right['x2']) / 2.0;
                $rightY = ($right['y1'] + $right['y2']) / 2.0;

                return hypot($rightX - $leftX, $rightY - $leftY);
            };
            if (abs($translationX - $bTranslationX) > $translationTolerance
                || abs($translationY - $bTranslationY) > $translationTolerance
                || $pairDistance($a0, $b0) > max(48.0, $height * 6.0)
                || $pairDistance($a1, $b1) > max(48.0, $height * 6.0)
                || hypot($translationX, $translationY) < max(48.0, $height * 6.0)) {
                continue;
            }
            $counterpart = $this->pdfMirroredDuplicateMapPairUniqueCounterpart(
                $sourceItems,
                $members[0]['projection'],
                $members[1]['projection'],
                $indexes
            );
            if ($counterpart === null) {
                continue;
            }

            $proof = [
                'version' => 1,
                'method' => 'exact-mirrored-translated-map-label-pairs',
                'sourceSha256' => $this->sourceSha256,
                'page' => $pages[0],
                'stream' => $streams[0],
                'members' => $members,
                'labelProjectionDigest' => hash('sha256', $members[0]['projection']),
                'measurementProjectionDigest' => hash('sha256', $members[1]['projection']),
                'translationX' => round($translationX, 6),
                'translationY' => round($translationY, 6),
                'translationTolerance' => round($translationTolerance, 6),
                'counterpart' => $counterpart,
            ];
            $proof['proofDigest'] = hash('sha256', json_encode(
                $proof,
                JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_PRESERVE_ZERO_FRACTION
            ) ?: '');
            foreach ($indexes as $index) {
                $sourceItems[$index]['sourcePdfMirroredMapPairArtifactRole'] =
                    'mirrored-duplicate-map-pair-artifact';
                $sourceItems[$index]['sourcePdfMirroredMapPairArtifactEvidence'] = $proof;
                $claimed[$index] = true;
            }
        }
    }

    /**
     * @param list<array<string,mixed>> $sourceItems
     * @param list<int> $excludedIndexes
     * @return array<string,mixed>|null
     */
    private function pdfMirroredDuplicateMapPairUniqueCounterpart(
        array $sourceItems,
        string $labelProjection,
        string $measurementProjection,
        array $excludedIndexes
    ): ?array {
        $labelTokens = $this->pdfComparableWordTokens($labelProjection);
        $measurementTokens = $this->pdfComparableWordTokens($measurementProjection);
        if ($labelTokens === [] || count($labelTokens) > 2 || count($measurementTokens) !== 1) {
            return null;
        }
        $subsequenceOffsets = static function (array $tokens, array $needle): array {
            $offsets = [];
            $needleCount = count($needle);
            for ($offset = 0, $limit = count($tokens) - $needleCount; $offset <= $limit; $offset++) {
                if (array_slice($tokens, $offset, $needleCount) === $needle) {
                    $offsets[] = $offset;
                }
            }

            return $offsets;
        };
        $excluded = array_fill_keys($excludedIndexes, true);
        $matches = [];
        foreach ($sourceItems as $sourceIndex => $item) {
            if (isset($excluded[$sourceIndex])
                || !$this->sourcePdfSourceItemHasExactGeometry($item)
                || count($this->pdfLineWordTokens((string) ($item['text'] ?? ''))) < 5) {
                continue;
            }
            $projection = $this->pdfSourceOccurrenceComparableText(
                (string) ($item['text'] ?? '')
            );
            $tokens = $this->pdfComparableWordTokens((string) ($item['text'] ?? ''));
            $measurementOffsets = $subsequenceOffsets($tokens, $measurementTokens);
            $labelOffsets = $subsequenceOffsets($tokens, $labelTokens);
            if ($projection === ''
                || count($measurementOffsets) !== 1
                || count($labelOffsets) !== 1) {
                continue;
            }
            $measurementOffset = $measurementOffsets[0];
            $labelOffset = $labelOffsets[0];
            if ($measurementOffset >= $labelOffset
                || $labelOffset - ($measurementOffset + count($measurementTokens)) > 3) {
                continue;
            }
            $matches[] = [
                'sourceIndex' => $sourceIndex,
                'sourceOccurrenceId' => (string) ($item['id'] ?? ''),
                'page' => max(1, (int) ($item['page'] ?? 1)),
                'stream' => max(1, (int) ($item['stream'] ?? 1)),
                'projectionDigest' => hash('sha256', $projection),
                'measurementTokenIndex' => $measurementOffset,
                'labelTokenIndex' => $labelOffset,
                'measurementTokenDigest' => hash('sha256', implode("\0", $measurementTokens)),
                'labelTokenDigest' => hash('sha256', implode("\0", $labelTokens)),
                'bounds' => $this->pdfSourceEvidenceBounds($item['sourceGeometry']),
            ];
        }

        return count($matches) === 1 ? $matches[0] : null;
    }

    /**
     * @param array<string,mixed> $proof
     * @param list<array<string,mixed>> $sourceItems
     */
    private function pdfMirroredDuplicateMapPairEvidenceMatchesSourceItems(
        array $proof,
        array $sourceItems
    ): bool {
        $digest = is_string($proof['proofDigest'] ?? null) ? $proof['proofDigest'] : '';
        $unsigned = $proof;
        unset($unsigned['proofDigest']);
        if (($proof['version'] ?? null) !== 1
            || ($proof['method'] ?? null) !== 'exact-mirrored-translated-map-label-pairs'
            || !is_string($proof['sourceSha256'] ?? null)
            || !hash_equals($this->sourceSha256, $proof['sourceSha256'])
            || $digest === ''
            || !hash_equals($digest, hash('sha256', json_encode(
                $unsigned,
                JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_PRESERVE_ZERO_FRACTION
            ) ?: ''))
            || !is_array($proof['members'] ?? null)
            || count($proof['members']) !== 4) {
            return false;
        }
        $members = $proof['members'];
        $projections = [];
        foreach ($members as $offset => $member) {
            $sourceIndex = $member['sourceIndex'] ?? null;
            $item = is_int($sourceIndex) ? ($sourceItems[$sourceIndex] ?? null) : null;
            $projection = is_array($item)
                ? $this->pdfSourceOccurrenceComparableText((string) ($item['text'] ?? ''))
                : '';
            if (!is_int($sourceIndex)
                || $sourceIndex !== (int) $members[0]['sourceIndex'] + $offset
                || !is_array($item)
                || ($member['sourceOccurrenceId'] ?? null) !== ($item['id'] ?? null)
                || ($member['page'] ?? null) !== (int) ($item['page'] ?? 0)
                || ($member['stream'] ?? null) !== (int) ($item['stream'] ?? 0)
                || $member['page'] !== ($proof['page'] ?? null)
                || $member['stream'] !== ($proof['stream'] ?? null)
                || !$this->sourcePdfSourceItemHasExactNearHorizontalGeometry($item)
                || !hash_equals(
                    (string) ($member['projectionDigest'] ?? ''),
                    hash('sha256', $projection)
                )
                || !is_array($member['bounds'] ?? null)
                || !$this->pdfClippedDisplayArtifactBoundsMatch(
                    $member['bounds'],
                    $this->pdfSourceEvidenceBounds($item['sourceGeometry'])
                )) {
                return false;
            }
            $projections[] = $projection;
        }
        if (!hash_equals($projections[0], $projections[3])
            || !hash_equals($projections[1], $projections[2])
            || hash_equals($projections[0], $projections[1])
            || !hash_equals(
                (string) ($proof['labelProjectionDigest'] ?? ''),
                hash('sha256', $projections[0])
            )
            || !hash_equals(
                (string) ($proof['measurementProjectionDigest'] ?? ''),
                hash('sha256', $projections[1])
            )) {
            return false;
        }
        $translationX = (float) $members[3]['bounds']['x1'] - (float) $members[0]['bounds']['x1'];
        $translationY = (float) $members[3]['bounds']['y1'] - (float) $members[0]['bounds']['y1'];
        $bTranslationX = (float) $members[2]['bounds']['x1'] - (float) $members[1]['bounds']['x1'];
        $bTranslationY = (float) $members[2]['bounds']['y1'] - (float) $members[1]['bounds']['y1'];
        $tolerance = (float) ($proof['translationTolerance'] ?? 0.0);
        if ($tolerance <= 0.0
            || abs($translationX - (float) ($proof['translationX'] ?? INF)) > 0.000001
            || abs($translationY - (float) ($proof['translationY'] ?? INF)) > 0.000001
            || abs($translationX - $bTranslationX) > $tolerance
            || abs($translationY - $bTranslationY) > $tolerance) {
            return false;
        }
        $counterpart = $this->pdfMirroredDuplicateMapPairUniqueCounterpart(
            $sourceItems,
            $projections[0],
            $projections[1],
            array_column($members, 'sourceIndex')
        );

        return is_array($counterpart) && $counterpart === ($proof['counterpart'] ?? null);
    }

    /**
     * @param list<AstNode> $blocks
     * @param list<array<string,mixed>> $sourceItems
     * @return array{
     *     blocks:list<AstNode>,
     *     removedCount:int,
     *     pageProjectionReplacements:array<int,string>,
     *     pageProjectionProofPreserved:bool
     * }
     */
    private function pdfBlocksWithoutProvenMirroredDuplicateMapPairs(
        array $blocks,
        array $sourceItems
    ): array {
        $proofs = [];
        foreach ($sourceItems as $item) {
            $proof = is_array($item['sourcePdfMirroredMapPairArtifactEvidence'] ?? null)
                ? $item['sourcePdfMirroredMapPairArtifactEvidence']
                : null;
            if (($item['sourcePdfMirroredMapPairArtifactRole'] ?? null)
                    === 'mirrored-duplicate-map-pair-artifact'
                && $proof !== null
                && $this->pdfMirroredDuplicateMapPairEvidenceMatchesSourceItems(
                    $proof,
                    $sourceItems
                )) {
                $proofs[(string) $proof['proofDigest']] = $proof;
            }
        }
        if ($proofs === [] || $blocks === []) {
            return [
                'blocks' => $blocks,
                'removedCount' => 0,
                'pageProjectionReplacements' => [],
                'pageProjectionProofPreserved' => true,
            ];
        }

        $remove = [];
        foreach ($proofs as $proof) {
            $label = (string) $proof['members'][0]['projection'];
            $measurement = (string) $proof['members'][1]['projection'];
            $forward = $label . $measurement;
            $reverse = $measurement . $label;
            $matches = [];
            foreach ($blocks as $index => $block) {
                if ($block->type !== 'paragraph') {
                    continue;
                }
                $projection = $this->pdfSourceOccurrenceComparableText(
                    (string) $block->attr('text', '')
                );
                if (hash_equals($projection, $forward) || hash_equals($projection, $reverse)) {
                    $matches[] = $index;
                }
            }
            if ($matches === [] || count($matches) > 2) {
                continue;
            }
            foreach ($matches as $index) {
                $remove[$index] = true;
            }
        }
        if ($remove === []) {
            return ['blocks' => $blocks, 'removedCount' => 0];
        }

        return [
            'blocks' => array_values(array_filter(
                $blocks,
                static fn (AstNode $_block, int $index): bool => !isset($remove[$index]),
                ARRAY_FILTER_USE_BOTH
            )),
            'removedCount' => count($remove),
        ];
    }

    /**
     * @param array<string,mixed> $sourceItem
     * @param list<array<string,mixed>> $runs
     * @return array<string,mixed>|null
     */
    private function pdfCrossLaneDisplaySplitForSourceItem(
        int $sourceIndex,
        array $sourceItem,
        array $runs
    ): ?array {
        $projection = $this->pdfSourceOccurrenceComparableText(
            (string) ($sourceItem['text'] ?? '')
        );
        if ($projection === ''
            || !$this->sourcePdfSourceItemHasExactGeometry($sourceItem)) {
            return null;
        }
        usort($runs, function (array $left, array $right): int {
            $leftRange = $this->pdfPositionedExactSourceRanges($left)[0] ?? [];
            $rightRange = $this->pdfPositionedExactSourceRanges($right)[0] ?? [];

            return ((int) ($leftRange['sourceStart'] ?? -1)
                    <=> (int) ($rightRange['sourceStart'] ?? -1))
                ?: ((int) ($leftRange['sourceEnd'] ?? -1)
                    <=> (int) ($rightRange['sourceEnd'] ?? -1));
        });
        $cursor = 0;
        foreach ($runs as $run) {
            $ranges = $this->pdfPositionedExactSourceRanges($run);
            $range = count($ranges) === 1 ? $ranges[0] : null;
            if (!is_array($range)
                || $range['sourceIndex'] !== $sourceIndex
                || (int) $run['page'] !== (int) ($sourceItem['page'] ?? 0)
                || (int) $run['stream'] !== (int) ($sourceItem['stream'] ?? 0)
                || $range['sourceStart'] !== $cursor
                || $range['sourceEnd'] <= $cursor) {
                return null;
            }
            $cursor = $range['sourceEnd'];
        }
        if ($cursor !== strlen($projection)) {
            return null;
        }

        $candidates = [];
        for ($splitRun = 1, $runCount = count($runs); $splitRun < $runCount; $splitRun++) {
            $leftRuns = array_slice($runs, 0, $splitRun);
            $rightRuns = array_slice($runs, $splitRun);
            $rightRange = $this->pdfPositionedExactSourceRanges($rightRuns[0])[0] ?? null;
            if (!is_array($rightRange)) {
                continue;
            }
            $split = $rightRange['sourceStart'];
            $rawSplit = $this->pdfRawTextSplitAtComparableOffset(
                (string) $sourceItem['text'],
                $split
            );
            if ($rawSplit === null
                || count($this->pdfLineWordTokens($rawSplit['prefix'])) < 2
                || count($this->pdfLineWordTokens($rawSplit['suffix'])) < 2) {
                continue;
            }
            $leftBounds = $this->pdfPositionedRunGroupBounds($leftRuns);
            $rightBounds = $this->pdfPositionedRunGroupBounds($rightRuns);
            $height = max(
                1.0,
                $leftBounds['y2'] - $leftBounds['y1'],
                $rightBounds['y2'] - $rightBounds['y1']
            );
            $gap = $rightBounds['x1'] - $leftBounds['x2'];
            $leftFontDigest = $this->pdfPositionedRunGroupFontDigest($leftRuns);
            $rightFontDigest = $this->pdfPositionedRunGroupFontDigest($rightRuns);
            if ($gap < max(24.0, $height * 1.45)
                || $leftFontDigest === null
                || $rightFontDigest === null
                || hash_equals($leftFontDigest, $rightFontDigest)
                || abs($leftBounds['y1'] - $rightBounds['y1']) > max(1.0, $height * 0.12)) {
                continue;
            }
            $candidates[] = [
                'sourceOccurrenceId' => (string) ($sourceItem['id'] ?? ''),
                'sourceIndex' => $sourceIndex,
                'page' => (int) $sourceItem['page'],
                'stream' => (int) $sourceItem['stream'],
                'sourceProjectionDigest' => hash('sha256', $projection),
                'prefixRange' => [
                    'sourceIndex' => $sourceIndex,
                    'sourceStart' => 0,
                    'sourceEnd' => $split,
                ],
                'retainedRange' => [
                    'sourceIndex' => $sourceIndex,
                    'sourceStart' => $split,
                    'sourceEnd' => strlen($projection),
                ],
                'prefixText' => $rawSplit['prefix'],
                'retainedText' => $rawSplit['suffix'],
                'prefixProjectionDigest' => hash('sha256', substr($projection, 0, $split)),
                'retainedProjectionDigest' => hash('sha256', substr($projection, $split)),
                'bounds' => $this->pdfSourceEvidenceBounds($sourceItem['sourceGeometry']),
                'leftBounds' => $leftBounds,
                'rightBounds' => $rightBounds,
                'leftFontDigest' => $leftFontDigest,
                'rightFontDigest' => $rightFontDigest,
            ];
        }

        return count($candidates) === 1 ? $candidates[0] : null;
    }

    /**
     * @param array<string,mixed> $sourceItem
     * @param list<array<string,mixed>> $runs
     * @return array<string,mixed>|null
     */
    private function pdfWholeExactPositionedSourceItemEvidence(
        int $sourceIndex,
        array $sourceItem,
        array $runs,
        bool $allowNearHorizontal = false
    ): ?array {
        $projection = $this->pdfSourceOccurrenceComparableText(
            (string) ($sourceItem['text'] ?? '')
        );
        if ($projection === ''
            || !($allowNearHorizontal
                ? $this->sourcePdfSourceItemHasExactNearHorizontalGeometry($sourceItem)
                : $this->sourcePdfSourceItemHasExactGeometry($sourceItem))) {
            return null;
        }
        usort($runs, function (array $left, array $right): int {
            $leftRange = $this->pdfPositionedExactSourceRanges($left)[0] ?? [];
            $rightRange = $this->pdfPositionedExactSourceRanges($right)[0] ?? [];

            return ((int) ($leftRange['sourceStart'] ?? -1)
                    <=> (int) ($rightRange['sourceStart'] ?? -1))
                ?: ((int) ($leftRange['sourceEnd'] ?? -1)
                    <=> (int) ($rightRange['sourceEnd'] ?? -1));
        });
        $cursor = 0;
        foreach ($runs as $run) {
            $ranges = $this->pdfPositionedExactSourceRanges($run);
            $range = count($ranges) === 1 ? $ranges[0] : null;
            if (!is_array($range)
                || $range['sourceIndex'] !== $sourceIndex
                || (int) ($run['page'] ?? 0) !== (int) ($sourceItem['page'] ?? 0)
                || (int) ($run['stream'] ?? 0) !== (int) ($sourceItem['stream'] ?? 0)
                || $range['sourceStart'] !== $cursor
                || $range['sourceEnd'] <= $cursor) {
                return null;
            }
            $cursor = $range['sourceEnd'];
        }
        $fontDigest = $this->pdfPositionedRunGroupFontDigest($runs);
        if ($cursor !== strlen($projection) || $fontDigest === null) {
            return null;
        }

        return [
            'sourceOccurrenceId' => (string) ($sourceItem['id'] ?? ''),
            'sourceIndex' => $sourceIndex,
            'page' => (int) $sourceItem['page'],
            'stream' => (int) $sourceItem['stream'],
            'text' => (string) $sourceItem['text'],
            'projection' => $projection,
            'range' => [
                'sourceIndex' => $sourceIndex,
                'sourceStart' => 0,
                'sourceEnd' => strlen($projection),
            ],
            'projectionDigest' => hash('sha256', $projection),
            'bounds' => $this->pdfPositionedRunGroupBounds($runs),
            'fontDigest' => $fontDigest,
        ];
    }

    /**
     * @param list<array<string,mixed>> $runs
     * @return array{x1:float,y1:float,x2:float,y2:float}
     */
    private function pdfPositionedRunGroupBounds(array $runs): array
    {
        return [
            'x1' => min(array_map(static fn (array $run): float => (float) $run['x1'], $runs)),
            'y1' => min(array_map(static fn (array $run): float => (float) $run['y1'], $runs)),
            'x2' => max(array_map(static fn (array $run): float => (float) $run['x2'], $runs)),
            'y2' => max(array_map(static fn (array $run): float => (float) $run['y2'], $runs)),
        ];
    }

    /** @param list<array<string,mixed>> $runs */
    private function pdfPositionedRunGroupFontDigest(array $runs): ?string
    {
        $fonts = [];
        foreach ($runs as $run) {
            $resource = is_string($run['fontResource'] ?? null)
                ? trim($run['fontResource'])
                : '';
            $baseFont = is_string($run['baseFont'] ?? null)
                ? trim($run['baseFont'])
                : '';
            if ($resource === '' && $baseFont === '') {
                return null;
            }
            $fonts[$resource . "\0" . $baseFont] = true;
        }
        if (count($fonts) !== 1) {
            return null;
        }

        return hash('sha256', (string) array_key_first($fonts));
    }

    /** @return array{prefix:string,suffix:string}|null */
    private function pdfRawTextSplitAtComparableOffset(string $text, int $offset): ?array
    {
        $projection = $this->pdfSourceOccurrenceComparableText($text);
        if ($offset <= 0 || $offset >= strlen($projection)
            || preg_match_all('/./us', $text, $matches, PREG_OFFSET_CAPTURE) === false) {
            return null;
        }
        $cursor = 0;
        foreach ($matches[0] as [$character, $rawOffset]) {
            if ($cursor === $offset) {
                $prefix = trim(substr($text, 0, (int) $rawOffset));
                $suffix = trim(substr($text, (int) $rawOffset));
                if (hash_equals(
                    substr($projection, 0, $offset),
                    $this->pdfSourceOccurrenceComparableText($prefix)
                ) && hash_equals(
                    substr($projection, $offset),
                    $this->pdfSourceOccurrenceComparableText($suffix)
                )) {
                    return ['prefix' => $prefix, 'suffix' => $suffix];
                }
                return null;
            }
            $characterProjection = $this->pdfSourceOccurrenceComparableText((string) $character);
            $next = $cursor + strlen($characterProjection);
            if ($next > $offset) {
                return null;
            }
            $cursor = $next;
        }

        return null;
    }

    /** @return list<string> */
    private function pdfComparableWordTokens(string $text): array
    {
        return array_values(array_filter(array_map(
            fn (string $token): string => $this->pdfLowercaseToken($token),
            $this->pdfLineWordTokens($text)
        ), static fn (string $token): bool => $token !== ''));
    }

    /**
     * @param list<array<string,mixed>> $sourceItems
     * @param list<string> $targetTokens
     * @param list<int> $excludedIndexes
     * @param array{x1:float,y1:float,x2:float,y2:float} $displayBounds
     * @return array<string,mixed>|null
     */
    private function pdfCrossLaneDisplayUniqueCounterpart(
        array $sourceItems,
        array $targetTokens,
        int $page,
        int $stream,
        array $excludedIndexes,
        array $displayBounds
    ): ?array {
        $excluded = array_fill_keys($excludedIndexes, true);
        $tokens = [];
        foreach ($sourceItems as $sourceIndex => $item) {
            if ((int) ($item['page'] ?? 0) !== $page
                || (int) ($item['stream'] ?? 0) !== $stream
                || isset($excluded[$sourceIndex])) {
                continue;
            }
            foreach ($this->pdfComparableWordTokens((string) ($item['text'] ?? '')) as $tokenOffset => $token) {
                $tokens[] = [
                    'token' => $token,
                    'sourceIndex' => $sourceIndex,
                    'tokenOffset' => $tokenOffset,
                ];
            }
        }
        $matches = [];
        $targetCount = count($targetTokens);
        for ($index = 0, $tokenCount = count($tokens); $index + $targetCount <= $tokenCount; $index++) {
            for ($offset = 0; $offset < $targetCount; $offset++) {
                if ($tokens[$index + $offset]['token'] !== $targetTokens[$offset]) {
                    continue 2;
                }
            }
            $matched = array_slice($tokens, $index, $targetCount);
            $sourceIndexes = array_values(array_unique(array_column($matched, 'sourceIndex')));
            sort($sourceIndexes, SORT_NUMERIC);
            if ($sourceIndexes === []
                || end($sourceIndexes) - $sourceIndexes[0] > 3
                || $sourceIndexes !== range($sourceIndexes[0], (int) end($sourceIndexes))) {
                continue;
            }
            $items = array_map(static fn (int $sourceIndex): array => $sourceItems[$sourceIndex], $sourceIndexes);
            if (array_filter($items, fn (array $item): bool =>
                !$this->sourcePdfSourceItemHasExactGeometry($item)
            ) !== []) {
                continue;
            }
            $bounds = [
                'x1' => min(array_map(fn (array $item): float => (float) $item['sourceGeometry']['x1'], $items)),
                'y1' => min(array_map(fn (array $item): float => (float) $item['sourceGeometry']['y1'], $items)),
                'x2' => max(array_map(fn (array $item): float => (float) $item['sourceGeometry']['x2'], $items)),
                'y2' => max(array_map(fn (array $item): float => (float) $item['sourceGeometry']['y2'], $items)),
            ];
            $displayCenterX = ($displayBounds['x1'] + $displayBounds['x2']) / 2.0;
            $counterpartCenterX = ($bounds['x1'] + $bounds['x2']) / 2.0;
            if (abs($counterpartCenterX - $displayCenterX) < 24.0) {
                continue;
            }
            $matches[] = [
                'sourceIndexes' => $sourceIndexes,
                'sourceOccurrenceIds' => array_map(
                    static fn (array $item): string => (string) ($item['id'] ?? ''),
                    $items
                ),
                'sourceProjectionDigests' => array_map(
                    fn (array $item): string => hash('sha256', $this->pdfSourceOccurrenceComparableText(
                        (string) ($item['text'] ?? '')
                    )),
                    $items
                ),
                'firstTokenOffset' => $matched[0]['tokenOffset'],
                'lastTokenOffset' => $matched[array_key_last($matched)]['tokenOffset'],
                'tokenDigest' => hash('sha256', implode("\0", $targetTokens)),
                'bounds' => $bounds,
            ];
        }

        return count($matches) === 1 ? $matches[0] : null;
    }

    /**
     * Apply only a previously signed source proof to the corresponding whole
     * source-backed layout. The whole display lead remains present solely as
     * disposition evidence; the two mixed rows retain their exact right-lane
     * source ranges and geometry.
     *
     * @param list<array<string,mixed>> $layouts
     * @param list<array<string,mixed>> $sourceItems
     * @return list<array<string,mixed>>
     */
    private function pdfSourceLayoutsWithCrossLaneDisplayArtifactProjections(
        array $layouts,
        array $sourceItems
    ): array {
        $proofBySourceIndex = [];
        foreach ($sourceItems as $sourceIndex => $sourceItem) {
            $proof = is_array($sourceItem['sourcePdfCrossLaneDisplayArtifactEvidence'] ?? null)
                ? $sourceItem['sourcePdfCrossLaneDisplayArtifactEvidence']
                : null;
            if ($proof !== null
                && $this->pdfCrossLaneDisplayArtifactEvidenceMatchesSourceItems(
                    $proof,
                    $sourceItems
                )) {
                $proofBySourceIndex[$sourceIndex] = $proof;
            }
        }
        if ($proofBySourceIndex === []) {
            return $layouts;
        }

        foreach ($layouts as &$layout) {
            $ranges = $this->pdfPositionedExactSourceRanges($layout);
            if (count($ranges) !== 1) {
                continue;
            }
            $range = $ranges[0];
            $sourceIndex = $range['sourceIndex'];
            $sourceItem = $sourceItems[$sourceIndex] ?? null;
            $proof = $proofBySourceIndex[$sourceIndex] ?? null;
            $role = is_array($sourceItem)
                ? ($sourceItem['sourcePdfCrossLaneDisplayArtifactRole'] ?? null)
                : null;
            $sourceProjection = is_array($sourceItem)
                ? $this->pdfSourceOccurrenceComparableText((string) ($sourceItem['text'] ?? ''))
                : '';
            if (!is_array($proof)
                || $sourceProjection === ''
                || $range !== [
                    'sourceIndex' => $sourceIndex,
                    'sourceStart' => 0,
                    'sourceEnd' => strlen($sourceProjection),
                ]) {
                continue;
            }
            $layout['sourcePdfCrossLaneDisplayArtifactRole'] = $role;
            $layout['sourcePdfCrossLaneDisplayArtifactEvidence'] = $proof;
            if ($role === 'whole-display-artifact') {
                $layout['sourcePdfArtifact'] = true;
                continue;
            }
            if ($role !== 'display-prefix-projection') {
                continue;
            }
            $rows = array_values(array_filter(
                $proof['splitRows'],
                static fn (array $row): bool => $row['sourceIndex'] === $sourceIndex
            ));
            if (count($rows) !== 1) {
                continue;
            }
            $row = $rows[0];
            $layout['text'] = $row['retainedText'];
            if (array_key_exists('positionedTextCandidate', $layout)) {
                $layout['positionedTextCandidate'] = $row['retainedText'];
            }
            foreach (['x1', 'y1', 'x2', 'y2'] as $key) {
                $layout[$key] = $row['rightBounds'][$key];
            }
            $layout['sourcePdfExactSourceRanges'] = [$row['retainedRange']];
            $layout['sourcePdfExactSourceIndex'] = $sourceIndex;
            $layout['sourcePdfExactSourceStart'] = $row['retainedRange']['sourceStart'];
            $layout['sourcePdfExactSourceEnd'] = $row['retainedRange']['sourceEnd'];
            $layout['sourcePdfExactPositionedText'] = true;
            $layout['sourceVerifiedGeometryText'] = true;
            unset($layout['sourcePdfWholeExactOccurrenceProof']);
        }
        unset($layout);

        return $layouts;
    }

    /**
     * @param array<string,mixed> $proof
     * @param list<array<string,mixed>> $sourceItems
     */
    private function pdfCrossLaneDisplayArtifactEvidenceMatchesSourceItems(
        array $proof,
        array $sourceItems
    ): bool {
        $proofDigest = is_string($proof['proofDigest'] ?? null)
            ? $proof['proofDigest']
            : '';
        $payload = $proof;
        unset($payload['proofDigest']);
        if (($proof['version'] ?? null) !== 1
            || ($proof['method'] ?? null) !== 'exact-cross-lane-duplicate-display-prefix'
            || !is_string($proof['sourceSha256'] ?? null)
            || !hash_equals($this->sourceSha256, $proof['sourceSha256'])
            || $proofDigest === ''
            || !hash_equals($proofDigest, hash('sha256', json_encode(
                $payload,
                JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_PRESERVE_ZERO_FRACTION
            ) ?: ''))
            || !is_array($proof['artifact'] ?? null)
            || !is_array($proof['splitRows'] ?? null)
            || count($proof['splitRows']) !== 2) {
            return false;
        }
        $artifact = $proof['artifact'];
        $artifactIndex = $artifact['sourceIndex'] ?? null;
        $rows = $proof['splitRows'];
        if (!is_int($artifactIndex)
            || !is_int($rows[0]['sourceIndex'] ?? null)
            || !is_int($rows[1]['sourceIndex'] ?? null)
            || $rows[0]['sourceIndex'] !== $artifactIndex + 1
            || $rows[1]['sourceIndex'] !== $artifactIndex + 2) {
            return false;
        }
        $displayTokens = [];
        foreach ([$artifact, ...$rows] as $memberOffset => $member) {
            $sourceIndex = $member['sourceIndex'];
            $sourceItem = $sourceItems[$sourceIndex] ?? null;
            $sourceProjection = is_array($sourceItem)
                ? $this->pdfSourceOccurrenceComparableText((string) ($sourceItem['text'] ?? ''))
                : '';
            if (!is_array($sourceItem)
                || ($member['sourceOccurrenceId'] ?? null) !== ($sourceItem['id'] ?? null)
                || ($member['page'] ?? null) !== (int) ($sourceItem['page'] ?? 0)
                || ($member['stream'] ?? null) !== (int) ($sourceItem['stream'] ?? 0)
                || $member['page'] !== ($proof['page'] ?? null)
                || $member['stream'] !== ($proof['stream'] ?? null)
                || !$this->sourcePdfSourceItemHasExactGeometry($sourceItem)
                || !is_string($member['sourceProjectionDigest'] ?? $member['projectionDigest'] ?? null)
                || !hash_equals(
                    (string) ($member['sourceProjectionDigest'] ?? $member['projectionDigest']),
                    hash('sha256', $sourceProjection)
                )) {
                return false;
            }
            if ($memberOffset === 0) {
                if (($member['range'] ?? null) !== [
                    'sourceIndex' => $sourceIndex,
                    'sourceStart' => 0,
                    'sourceEnd' => strlen($sourceProjection),
                ] || !is_array($member['bounds'] ?? null)
                    || !$this->pdfClippedDisplayArtifactBoundsMatch(
                        $member['bounds'],
                        $this->pdfSourceEvidenceBounds($sourceItem['sourceGeometry'])
                    )) {
                    return false;
                }
                continue;
            }
            $prefixRange = $member['prefixRange'] ?? null;
            $retainedRange = $member['retainedRange'] ?? null;
            if (!is_array($prefixRange)
                || !is_array($retainedRange)
                || $prefixRange['sourceIndex'] !== $sourceIndex
                || $prefixRange['sourceStart'] !== 0
                || !is_int($prefixRange['sourceEnd'] ?? null)
                || $retainedRange !== [
                    'sourceIndex' => $sourceIndex,
                    'sourceStart' => $prefixRange['sourceEnd'],
                    'sourceEnd' => strlen($sourceProjection),
                ]) {
                return false;
            }
            $rawSplit = $this->pdfRawTextSplitAtComparableOffset(
                (string) $sourceItem['text'],
                $prefixRange['sourceEnd']
            );
            if ($rawSplit === null
                || $rawSplit['prefix'] !== ($member['prefixText'] ?? null)
                || $rawSplit['suffix'] !== ($member['retainedText'] ?? null)
                || !hash_equals(
                    (string) ($member['prefixProjectionDigest'] ?? ''),
                    hash('sha256', substr($sourceProjection, 0, $prefixRange['sourceEnd']))
                )
                || !hash_equals(
                    (string) ($member['retainedProjectionDigest'] ?? ''),
                    hash('sha256', substr($sourceProjection, $prefixRange['sourceEnd']))
                )
                || !is_array($member['leftBounds'] ?? null)
                || !is_array($member['rightBounds'] ?? null)) {
                return false;
            }
            $unionBounds = [
                'x1' => min($member['leftBounds']['x1'], $member['rightBounds']['x1']),
                'y1' => min($member['leftBounds']['y1'], $member['rightBounds']['y1']),
                'x2' => max($member['leftBounds']['x2'], $member['rightBounds']['x2']),
                'y2' => max($member['leftBounds']['y2'], $member['rightBounds']['y2']),
            ];
            if (!$this->pdfClippedDisplayArtifactBoundsMatch(
                $unionBounds,
                $this->pdfSourceEvidenceBounds($sourceItem['sourceGeometry'])
            )) {
                return false;
            }
            array_push($displayTokens, ...$this->pdfComparableWordTokens($rawSplit['prefix']));
        }
        if (!is_string($proof['displayTokenDigest'] ?? null)
            || !hash_equals(
                $proof['displayTokenDigest'],
                hash('sha256', implode("\0", $displayTokens))
            )) {
            return false;
        }
        $counterpart = $this->pdfCrossLaneDisplayUniqueCounterpart(
            $sourceItems,
            $displayTokens,
            (int) $proof['page'],
            (int) $proof['stream'],
            [$artifactIndex, $rows[0]['sourceIndex'], $rows[1]['sourceIndex']],
            $rows[0]['leftBounds']
        );

        return is_array($counterpart) && $counterpart === ($proof['counterpart'] ?? null);
    }

    /**
     * Reify the exact retained subrange from a signed cross-lane disposition
     * as a source-to-projection character map. A generic minimum-edit map can
     * be ambiguous when the removed prefix and retained suffix share letters;
     * the signed positioned range is stronger evidence and names every kept
     * source byte directly.
     *
     * @param array<string,mixed> $sourceItem
     * @param array<string,mixed> $disposition
     * @param list<array<string,mixed>> $sourceItems
     * @return list<array{
     *     sourceStart:int,
     *     sourceEnd:int,
     *     projectionStart:int,
     *     projectionEnd:int
     * }>|null
     */
    private function pdfCrossLaneDisplayDispositionProjectionMap(
        int $sourceIndex,
        array $sourceItem,
        array $disposition,
        array $sourceItems
    ): ?array {
        $evidence = is_array($disposition['evidence'] ?? null)
            ? ($disposition['evidence']['crossLaneDisplayArtifactProjection'] ?? null)
            : null;
        if (!is_array($evidence)
            || !$this->pdfCrossLaneDisplayArtifactEvidenceMatchesSourceItems(
                $evidence,
                $sourceItems
            )) {
            return null;
        }
        $rows = array_values(array_filter(
            $evidence['splitRows'],
            static fn (array $row): bool =>
                ($row['sourceIndex'] ?? null) === $sourceIndex
        ));
        if (count($rows) !== 1 || !is_array($rows[0]['retainedRange'] ?? null)) {
            return null;
        }
        $row = $rows[0];
        $range = $row['retainedRange'];
        $sourceProjection = $this->pdfSourceOccurrenceComparableText(
            (string) ($sourceItem['text'] ?? '')
        );
        $dispositionProjection = $this->pdfSourceOccurrenceComparableText(
            (string) ($disposition['textProjection'] ?? '')
        );
        $start = $range['sourceStart'] ?? null;
        $end = $range['sourceEnd'] ?? null;
        if (!is_int($start)
            || !is_int($end)
            || $range['sourceIndex'] !== $sourceIndex
            || $start < 0
            || $end <= $start
            || $end > strlen($sourceProjection)
            || $dispositionProjection === ''
            || !hash_equals(
                $dispositionProjection,
                substr($sourceProjection, $start, $end - $start)
            )
            || !hash_equals(
                $dispositionProjection,
                $this->pdfSourceOccurrenceComparableText(
                    (string) ($row['retainedText'] ?? '')
                )
            )) {
            return null;
        }

        $matched = preg_match_all(
            '/./us',
            $dispositionProjection,
            $characters,
            PREG_OFFSET_CAPTURE
        );
        if (!is_int($matched) || $matched < 1) {
            return null;
        }
        $map = [];
        foreach ($characters[0] as $character) {
            $text = is_string($character[0] ?? null) ? $character[0] : '';
            $projectionStart = is_int($character[1] ?? null) ? $character[1] : -1;
            if ($text === '' || $projectionStart < 0) {
                return null;
            }
            $projectionEnd = $projectionStart + strlen($text);
            $map[] = [
                'sourceStart' => $start + $projectionStart,
                'sourceEnd' => $start + $projectionEnd,
                'projectionStart' => $projectionStart,
                'projectionEnd' => $projectionEnd,
            ];
        }

        return $map;
    }

    /**
     * A selected full-page table/layout candidate is materialized before the
     * source-range projection pass. Remove its stale display-only paragraph
     * only when the immutable source graph proves the same phrase and exactly
     * one final paragraph consists of that phrase. Perpendicular paint can
     * split the tiny lead into reversed glyph tokens (for example `o T`), so
     * the lead is compared by exact character inventory while the multi-word
     * display suffix must remain in exact token order.
     *
     * @param list<AstNode> $blocks
     * @param list<array<string,mixed>> $sourceItems
     * @param array<int,string> $composedOutputPageProjections
     * @return array{blocks:list<AstNode>,removedCount:int}
     */
    private function pdfBlocksWithoutProvenCrossLaneDuplicateDisplays(
        array $blocks,
        array $sourceItems,
        array $composedOutputPageProjections = []
    ): array {
        $proofs = [];
        foreach ($sourceItems as $item) {
            if (($item['sourcePdfCrossLaneDisplayArtifactRole'] ?? null)
                    !== 'whole-display-artifact'
                || !is_array($item['sourcePdfCrossLaneDisplayArtifactEvidence'] ?? null)) {
                continue;
            }
            $proof = $item['sourcePdfCrossLaneDisplayArtifactEvidence'];
            if (!$this->pdfCrossLaneDisplayArtifactEvidenceMatchesSourceItems(
                $proof,
                $sourceItems
            )) {
                continue;
            }
            $digest = is_string($proof['proofDigest'] ?? null)
                ? $proof['proofDigest']
                : '';
            if ($digest !== '') {
                $proofs[$digest] = $proof;
            }
        }
        if ($proofs === [] || $blocks === []) {
            return [
                'blocks' => $blocks,
                'removedCount' => 0,
                'pageProjectionReplacements' => [],
                'pageProjectionProofPreserved' => true,
            ];
        }

        $removeIndexes = [];
        foreach ($proofs as $proof) {
            $displayTokens = [];
            foreach ($proof['splitRows'] as $row) {
                array_push(
                    $displayTokens,
                    ...$this->pdfComparableWordTokens((string) ($row['prefixText'] ?? ''))
                );
            }
            $artifactTokens = $this->pdfComparableWordTokens(
                (string) ($proof['artifact']['text'] ?? '')
            );
            if ($displayTokens === []
                || $artifactTokens === []
                || !hash_equals(
                    (string) ($proof['displayTokenDigest'] ?? ''),
                    hash('sha256', implode("\0", $displayTokens))
                )) {
                continue;
            }
            $matches = [];
            foreach ($blocks as $blockIndex => $block) {
                if ($block->type !== 'paragraph') {
                    continue;
                }
                $tokens = $this->pdfComparableWordTokens(
                    (string) $block->attr('text', '')
                );
                $prefixCount = count($tokens) - count($displayTokens);
                if ($prefixCount < 1
                    || $prefixCount > max(3, count($artifactTokens) + 1)
                    || array_slice($tokens, $prefixCount) !== $displayTokens) {
                    continue;
                }
                $lead = implode('', array_slice($tokens, 0, $prefixCount));
                $artifact = implode('', $artifactTokens);
                if ($this->pdfExactCharacterInventory($lead)
                    !== $this->pdfExactCharacterInventory($artifact)) {
                    continue;
                }
                $matches[] = $blockIndex;
            }
            if (count($matches) === 1 && !isset($removeIndexes[$matches[0]])) {
                $removeIndexes[$matches[0]] = (int) ($proof['page'] ?? 0);
            }
        }
        if ($removeIndexes === []) {
            return [
                'blocks' => $blocks,
                'removedCount' => 0,
                'pageProjectionReplacements' => [],
                'pageProjectionProofPreserved' => true,
            ];
        }

        // Candidate-page blocks carry an independent, exact page projection
        // envelope. Removing a proved display-only paragraph must update that
        // envelope rather than discard it: otherwise the source ledger loses
        // the page partition for every unrelated paragraph. Re-sign only a
        // complete affected page group which validated before the removal.
        $originalPageProofs = $this->pdfFinalOutputPageProofs($blocks);
        $affectedPages = [];
        $pageProjectionProofPreserved = true;
        $removedBlocksHaveOutputPageProofs = $originalPageProofs !== [];
        foreach ($removeIndexes as $removeIndex => $provedPage) {
            $outputPageProof = $blocks[$removeIndex]->attr(self::PDF_OUTPUT_PAGE_PROOF_ATTR);
            $page = is_array($outputPageProof) && is_int($outputPageProof['page'] ?? null)
                ? $outputPageProof['page']
                : $provedPage;
            if ($page < 1 || $page !== $provedPage) {
                $pageProjectionProofPreserved = false;
                break;
            }
            if (!is_array($outputPageProof) || !isset($originalPageProofs[$page])) {
                $removedBlocksHaveOutputPageProofs = false;
            }
            $affectedPages[$page] = true;
        }

        $filteredBlocks = array_values(array_filter(
            $blocks,
            static fn (AstNode $_block, int $index): bool => !isset($removeIndexes[$index]),
            ARRAY_FILTER_USE_BOTH
        ));
        $pageProjectionReplacements = [];
        if ($pageProjectionProofPreserved && $removedBlocksHaveOutputPageProofs) {
            $restampedBlocks = [];
            for ($index = 0, $count = count($filteredBlocks); $index < $count;) {
                $block = $filteredBlocks[$index];
                $outputPageProof = $block->attr(self::PDF_OUTPUT_PAGE_PROOF_ATTR);
                $page = is_array($outputPageProof) && is_int($outputPageProof['page'] ?? null)
                    ? $outputPageProof['page']
                    : 0;
                if ($page < 1 || !isset($affectedPages[$page])) {
                    $restampedBlocks[] = $block;
                    $index++;
                    continue;
                }

                $pageBlocks = [];
                while ($index < $count) {
                    $candidate = $filteredBlocks[$index];
                    $candidateProof = $candidate->attr(self::PDF_OUTPUT_PAGE_PROOF_ATTR);
                    if (!is_array($candidateProof)
                        || ($candidateProof['page'] ?? null) !== $page) {
                        break;
                    }
                    $pageBlocks[] = $candidate;
                    $index++;
                }
                if ($pageBlocks === [] || isset($pageProjectionReplacements[$page])) {
                    $pageProjectionProofPreserved = false;
                    break;
                }
                $projection = '';
                foreach ($pageBlocks as $pageBlock) {
                    $leaves = [];
                    $this->appendPdfSourceBindingLeafText($pageBlock, $leaves);
                    $projection .= implode('', $leaves);
                }
                if ($projection === '') {
                    $pageProjectionProofPreserved = false;
                    break;
                }
                $pageProjectionReplacements[$page] = $projection;
                array_push(
                    $restampedBlocks,
                    ...$this->pdfBlocksWithOutputPageProof($page, $pageBlocks)
                );
            }
            if ($pageProjectionProofPreserved
                && array_fill_keys(array_keys($pageProjectionReplacements), true)
                    === $affectedPages) {
                $updatedPageProofs = $this->pdfFinalOutputPageProofs($restampedBlocks);
                foreach ($pageProjectionReplacements as $page => $projection) {
                    if (!isset($updatedPageProofs[$page])
                        || !hash_equals($updatedPageProofs[$page]['projection'], $projection)) {
                        $pageProjectionProofPreserved = false;
                        break;
                    }
                }
                if ($pageProjectionProofPreserved) {
                    $filteredBlocks = $restampedBlocks;
                }
            } else {
                $pageProjectionProofPreserved = false;
            }
        }

        // Conservative pages do not carry candidate AST markers, but their
        // compositor projection is still an exact, complete page-local byte
        // stream. In that case, bind each uniquely matched removed paragraph
        // to the page named by the signed source graph and subtract its exact
        // significant projection. A missing page or repeated byte sequence
        // fails closed and invalidates the page proof.
        if ($pageProjectionProofPreserved && !$removedBlocksHaveOutputPageProofs) {
            $pageProjectionReplacements = $composedOutputPageProjections;
            foreach ($removeIndexes as $removeIndex => $page) {
                $pageProjection = $pageProjectionReplacements[$page] ?? null;
                $leaves = [];
                $this->appendPdfSourceBindingLeafText($blocks[$removeIndex], $leaves);
                $removedProjection = implode('', $leaves);
                if (!is_string($pageProjection)
                    || $pageProjection === ''
                    || $removedProjection === ''
                    || substr_count($pageProjection, $removedProjection) !== 1) {
                    $pageProjectionProofPreserved = false;
                    break;
                }
                $offset = strpos($pageProjection, $removedProjection);
                if (!is_int($offset)) {
                    $pageProjectionProofPreserved = false;
                    break;
                }
                $pageProjectionReplacements[$page] = substr($pageProjection, 0, $offset)
                    . substr($pageProjection, $offset + strlen($removedProjection));
            }
            if ($pageProjectionProofPreserved) {
                $pageProjectionReplacements = array_intersect_key(
                    $pageProjectionReplacements,
                    $affectedPages
                );
                foreach ($pageProjectionReplacements as $projection) {
                    if ($projection === '') {
                        $pageProjectionProofPreserved = false;
                        break;
                    }
                }
            }
        }

        return [
            'blocks' => $filteredBlocks,
            'removedCount' => count($removeIndexes),
            'pageProjectionReplacements' => $pageProjectionProofPreserved
                ? $pageProjectionReplacements
                : [],
            'pageProjectionProofPreserved' => $pageProjectionProofPreserved,
        ];
    }

    /**
     * Bind a visually incomplete oversized display fragment to one immutable
     * source occurrence before semantic recovery takes its snapshot. The
     * source item receives the same signed proof so the final disposition
     * ledger can account for the omitted characters even though the semantic
     * record itself is intentionally absent.
     *
     * @param list<array<string,mixed>> $layouts
     * @param list<array<string,mixed>> $sourceItems
     * @return list<array<string,mixed>>
     */
    private function pdfSourceLayoutsWithClippedDisplayArtifactEvidence(
        array $layouts,
        array &$sourceItems
    ): array {
        $fontSizesByPage = [];
        foreach ($layouts as $layout) {
            if (!$this->pdfLayoutHasGeometry($layout)) {
                continue;
            }
            $fontSizesByPage[max(1, (int) $layout['page'])][] = max(
                1.0,
                (float) $layout['fontSize']
            );
        }
        $medianFontSizesByPage = [];
        foreach ($fontSizesByPage as $page => $fontSizes) {
            $medianFontSizesByPage[$page] = max(1.0, $this->median($fontSizes));
        }

        $candidates = [];
        $candidateCountsBySourceIndex = [];
        foreach ($layouts as $layoutIndex => $layout) {
            $page = max(1, (int) ($layout['page'] ?? 1));
            $evidence = $this->pdfClippedDisplayArtifactEvidence(
                $layout,
                $sourceItems,
                $medianFontSizesByPage[$page] ?? 1.0
            );
            if ($evidence === null) {
                continue;
            }
            $sourceIndex = $evidence['sourceIndex'];
            $candidates[$layoutIndex] = $evidence;
            $candidateCountsBySourceIndex[$sourceIndex] =
                ($candidateCountsBySourceIndex[$sourceIndex] ?? 0) + 1;
        }

        foreach ($candidates as $layoutIndex => $evidence) {
            $sourceIndex = $evidence['sourceIndex'];
            $sourceLocalIndex = $evidence['sourceLocalIndex'];
            if (($candidateCountsBySourceIndex[$sourceIndex] ?? 0) !== 1
                || !isset($layouts[$layoutIndex], $sourceItems[$sourceLocalIndex])) {
                continue;
            }
            $layouts[$layoutIndex]['sourcePdfArtifact'] = true;
            $layouts[$layoutIndex]['sourcePdfClippedDisplayArtifactEvidence'] = $evidence;
            $sourceItems[$sourceLocalIndex]['sourcePdfClippedDisplayArtifactEvidence'] = $evidence;
        }

        return $layouts;
    }

    /**
     * @param array<string,mixed> $layout
     * @param list<array<string,mixed>> $sourceItems
     * @return array<string,mixed>|null
     */
    private function pdfClippedDisplayArtifactEvidence(
        array $layout,
        array $sourceItems,
        float $pageMedianFontSize
    ): ?array {
        $text = (string) ($layout['text'] ?? '');
        if (!$this->pdfUnstructuredDisplayFragmentLooksIncomplete(
            ['text' => $text, 'layout' => $layout],
            $pageMedianFontSize
        )) {
            return null;
        }
        $projection = $this->pdfSourceOccurrenceComparableText(
            $this->pdfTextWithoutSemanticPrefixes($text)
        );
        $proof = is_array($layout['sourcePdfWholeExactOccurrenceProof'] ?? null)
            ? $layout['sourcePdfWholeExactOccurrenceProof']
            : null;
        if ($projection === ''
            || !$this->repairedPdfWholeExactOccurrenceProofMatchesLayout($layout, $projection)
            || !is_array($proof)
            || count($proof['occurrences'] ?? []) !== 1
            || count($proof['ranges'] ?? []) !== 1) {
            return null;
        }
        $occurrence = $proof['occurrences'][0];
        $range = $proof['ranges'][0];
        $sourceIndex = $occurrence['sourceIndex'];
        $sourceLocalIndex = $occurrence['sourceLocalIndex'];
        $sourceItem = $sourceItems[$sourceLocalIndex] ?? null;
        $sourceId = is_array($sourceItem) && is_string($sourceItem['id'] ?? null)
            ? $sourceItem['id']
            : '';
        $sourceProjection = is_array($sourceItem)
            ? $this->pdfSourceOccurrenceComparableText((string) ($sourceItem['text'] ?? ''))
            : '';
        $sourceGlobalIndex = is_array($sourceItem)
            && is_int($sourceItem['sourcePdfGlobalSourceIndex'] ?? null)
                ? $sourceItem['sourcePdfGlobalSourceIndex']
                : $sourceLocalIndex;
        $sourceGeometry = is_array($sourceItem['sourceGeometry'] ?? null)
            ? $sourceItem['sourceGeometry']
            : null;
        $layoutBounds = $this->pdfSourceEvidenceBounds($layout);
        if (!is_array($sourceItem)
            || $sourceId === ''
            || !$this->sourcePdfSourceItemHasExactGeometry($sourceItem)
            || $sourceGeometry === null
            || $sourceGlobalIndex !== $sourceIndex
            || !hash_equals($sourceProjection, $projection)
            || (int) ($sourceItem['page'] ?? 0) !== (int) ($layout['page'] ?? 0)
            || (int) ($sourceItem['stream'] ?? 0) !== (int) ($layout['sourceStream'] ?? 0)
            || $range !== [
                'sourceIndex' => $sourceIndex,
                'sourceStart' => 0,
                'sourceEnd' => strlen($sourceProjection),
            ]
            || !$this->pdfClippedDisplayArtifactBoundsMatch(
                $layoutBounds,
                $this->pdfSourceEvidenceBounds($sourceGeometry)
            )) {
            return null;
        }

        $fontSize = max(1.0, (float) $layout['fontSize']);
        $counterpart = $this->pdfClippedDisplayArtifactCounterpartEvidence(
            (string) ($sourceItem['text'] ?? ''),
            $sourceItems,
            $sourceIndex
        );
        if ($counterpart === null) {
            return null;
        }
        $evidence = [
            'version' => 1,
            'method' => 'whole-source-clipped-display-artifact',
            'sourceSha256' => $this->sourceSha256,
            'sourceOccurrenceId' => $sourceId,
            'sourceIndex' => $sourceIndex,
            'sourceLocalIndex' => $sourceLocalIndex,
            'page' => (int) $layout['page'],
            'stream' => (int) $layout['sourceStream'],
            'range' => $range,
            'significantBytes' => strlen($sourceProjection),
            'projectionDigest' => hash('sha256', $sourceProjection),
            'sourceBounds' => $this->pdfSourceEvidenceBounds($sourceGeometry),
            'layoutBounds' => $layoutBounds,
            'pageMedianFontSize' => $pageMedianFontSize,
            'fontSize' => $fontSize,
            'fontSizeRatio' => $fontSize / max(1.0, $pageMedianFontSize),
            'wholeOccurrenceProofDigest' => $proof['proofDigest'],
            'completeDisplayCounterpart' => $counterpart,
        ];
        $evidence['proofDigest'] = hash('sha256', json_encode(
            $evidence,
            JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_PRESERVE_ZERO_FRACTION
        ) ?: '');

        return $evidence;
    }

    /** @param array<string,mixed> $left @param array<string,mixed> $right */
    private function pdfClippedDisplayArtifactBoundsMatch(array $left, array $right): bool
    {
        foreach (['x1', 'y1', 'x2', 'y2'] as $key) {
            if (!is_numeric($left[$key] ?? null)
                || !is_numeric($right[$key] ?? null)
                || abs((float) $left[$key] - (float) $right[$key]) > 0.01) {
                return false;
            }
        }

        return true;
    }

    /**
     * A missing initial glyph is corroborated without a vocabulary list when
     * another exact source occurrence contains the same short token sequence
     * with a longer, initially capitalized first token. Require one unique
     * same-page occurrence so a coincidental suffix elsewhere cannot turn
     * stylized lower-case copy into an artifact.
     *
     * @param list<array<string,mixed>> $sourceItems
     * @return array<string,mixed>|null
     */
    private function pdfClippedDisplayArtifactCounterpartEvidence(
        string $text,
        array $sourceItems,
        int $targetSourceIndex
    ): ?array {
        $targetTokens = $this->pdfLineWordTokens($text);
        if (count($targetTokens) < 2
            || count($targetTokens) > 4
            || preg_match('/^\p{Ll}/u', $targetTokens[0]) !== 1) {
            return null;
        }
        $targetTokenKeys = array_map(
            fn (string $token): string => $this->pdfLowercaseToken($token),
            $targetTokens
        );
        $targetItem = null;
        foreach ($sourceItems as $localIndex => $sourceItem) {
            $globalIndex = is_int($sourceItem['sourcePdfGlobalSourceIndex'] ?? null)
                ? $sourceItem['sourcePdfGlobalSourceIndex']
                : $localIndex;
            if ($globalIndex === $targetSourceIndex) {
                $targetItem = $sourceItem;
                break;
            }
        }
        if (!is_array($targetItem)) {
            return null;
        }
        $targetPage = max(1, (int) ($targetItem['page'] ?? 1));
        $matches = [];
        foreach ($sourceItems as $localIndex => $candidate) {
            $candidateGlobalIndex = is_int($candidate['sourcePdfGlobalSourceIndex'] ?? null)
                ? $candidate['sourcePdfGlobalSourceIndex']
                : $localIndex;
            $candidateId = is_string($candidate['id'] ?? null) ? $candidate['id'] : '';
            if ($candidateGlobalIndex === $targetSourceIndex
                || $candidateId === ''
                || max(1, (int) ($candidate['page'] ?? 1)) !== $targetPage) {
                continue;
            }
            $candidateTokens = $this->pdfLineWordTokens((string) ($candidate['text'] ?? ''));
            $windowLength = count($targetTokens);
            for ($offset = 0; $offset + $windowLength <= count($candidateTokens); $offset++) {
                $first = $candidateTokens[$offset];
                $firstKey = $this->pdfLowercaseToken($first);
                if (preg_match('/^\p{Lu}/u', $first) !== 1
                    || $this->length($firstKey) <= $this->length($targetTokenKeys[0])
                    || !str_ends_with($firstKey, $targetTokenKeys[0])) {
                    continue;
                }
                for ($tokenOffset = 1; $tokenOffset < $windowLength; $tokenOffset++) {
                    if ($this->pdfLowercaseToken($candidateTokens[$offset + $tokenOffset])
                        !== $targetTokenKeys[$tokenOffset]) {
                        continue 2;
                    }
                }
                $projection = $this->pdfSourceOccurrenceComparableText(
                    (string) ($candidate['text'] ?? '')
                );
                if ($projection === '') {
                    continue;
                }
                $matches[] = [
                    'sourceOccurrenceId' => $candidateId,
                    'sourceIndex' => $candidateGlobalIndex,
                    'sourceLocalIndex' => (int) $localIndex,
                    'page' => $targetPage,
                    'stream' => max(1, (int) ($candidate['stream'] ?? 1)),
                    'projectionDigest' => hash('sha256', $projection),
                    'matchedTokenOffset' => $offset,
                    'matchedTokenDigest' => hash('sha256', implode("\0", array_slice(
                        $candidateTokens,
                        $offset,
                        $windowLength
                    ))),
                ];
            }
        }

        return count($matches) === 1 ? $matches[0] : null;
    }

    /**
     * @param array<string,mixed> $evidence
     * @param array<string,mixed> $sourceItem
     */
    private function pdfClippedDisplayArtifactEvidenceMatchesSourceItem(
        array $evidence,
        array $sourceItem,
        int $sourceLocalIndex,
        array $sourceItems
    ): bool {
        $proofDigest = is_string($evidence['proofDigest'] ?? null)
            ? $evidence['proofDigest']
            : '';
        $payload = $evidence;
        unset($payload['proofDigest']);
        $expectedProofDigest = hash('sha256', json_encode(
            $payload,
            JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_PRESERVE_ZERO_FRACTION
        ) ?: '');
        $sourceProjection = $this->pdfSourceOccurrenceComparableText(
            (string) ($sourceItem['text'] ?? '')
        );
        $sourceGeometry = is_array($sourceItem['sourceGeometry'] ?? null)
            ? $sourceItem['sourceGeometry']
            : null;
        $sourceGlobalIndex = is_int($sourceItem['sourcePdfGlobalSourceIndex'] ?? null)
            ? $sourceItem['sourcePdfGlobalSourceIndex']
            : $sourceLocalIndex;
        $range = [
            'sourceIndex' => $sourceGlobalIndex,
            'sourceStart' => 0,
            'sourceEnd' => strlen($sourceProjection),
        ];
        if (($evidence['version'] ?? null) !== 1
            || ($evidence['method'] ?? null) !== 'whole-source-clipped-display-artifact'
            || $proofDigest === ''
            || !hash_equals($proofDigest, $expectedProofDigest)
            || ($evidence['sourceSha256'] ?? null) !== $this->sourceSha256
            || ($evidence['sourceOccurrenceId'] ?? null) !== ($sourceItem['id'] ?? null)
            || ($evidence['sourceIndex'] ?? null) !== $sourceGlobalIndex
            || ($evidence['sourceLocalIndex'] ?? null) !== $sourceLocalIndex
            || ($evidence['page'] ?? null) !== (int) ($sourceItem['page'] ?? 0)
            || ($evidence['stream'] ?? null) !== (int) ($sourceItem['stream'] ?? 0)
            || ($evidence['range'] ?? null) !== $range
            || ($evidence['significantBytes'] ?? null) !== strlen($sourceProjection)
            || !is_string($evidence['projectionDigest'] ?? null)
            || !hash_equals($evidence['projectionDigest'], hash('sha256', $sourceProjection))
            || !$this->sourcePdfSourceItemHasExactGeometry($sourceItem)
            || $sourceGeometry === null
            || !is_array($evidence['sourceBounds'] ?? null)
            || !is_array($evidence['layoutBounds'] ?? null)
            || !$this->pdfClippedDisplayArtifactBoundsMatch(
                $evidence['sourceBounds'],
                $this->pdfSourceEvidenceBounds($sourceGeometry)
            )
            || !$this->pdfClippedDisplayArtifactBoundsMatch(
                $evidence['layoutBounds'],
                $this->pdfSourceEvidenceBounds($sourceGeometry)
            )
            || !is_numeric($evidence['pageMedianFontSize'] ?? null)
            || !is_numeric($evidence['fontSize'] ?? null)
            || !is_numeric($evidence['fontSizeRatio'] ?? null)
            || !is_array($evidence['completeDisplayCounterpart'] ?? null)
            || $evidence['completeDisplayCounterpart']
                !== $this->pdfClippedDisplayArtifactCounterpartEvidence(
                    (string) ($sourceItem['text'] ?? ''),
                    $sourceItems,
                    $sourceGlobalIndex
                )
            || (float) $evidence['fontSize'] < max(
                18.0,
                (float) $evidence['pageMedianFontSize'] * 2.20
            )) {
            return false;
        }

        return $this->pdfUnstructuredDisplayFragmentLooksIncomplete([
            'text' => (string) ($sourceItem['text'] ?? ''),
            'layout' => $this->pdfSourceEvidenceBounds($sourceGeometry) + [
                'page' => (int) $sourceItem['page'],
                'fontSize' => (float) $evidence['fontSize'],
            ],
        ], (float) $evidence['pageMedianFontSize']);
    }

    private function completePdfSentencePrefix(string $text): string
    {
        if (preg_match_all('/(?<!\p{Lu})[.!?](?=\s+\p{Lu}|\p{Lu}|$)/u', $text, $matches, PREG_OFFSET_CAPTURE) === false
            || $matches[0] === []) {
            return '';
        }

        $last = $matches[0][array_key_last($matches[0])];

        return trim(substr($text, 0, $last[1] + strlen($last[0])));
    }

    /**
     * A dense page can contain a regular prose column plus text painted inside
     * a figure. Geometry identifies the prose column by recurring left edges
     * and a line-height rhythm. Short items outside that structure are kept
     * only when they look like a list, URL, heading, or a visibly larger label.
     *
     * @param list<array{text: string, layout: array<string, mixed>|null}> $records
     * @return list<array{text: string, layout: array<string, mixed>|null}>
     */
    private function removeLowCoherencePdfFloatingRegions(array $records): array
    {
        $recordIndexesByPage = [];
        foreach ($records as $index => $record) {
            $layout = is_array($record['layout'] ?? null) ? $record['layout'] : null;
            if (!$this->pdfLayoutHasGeometry($layout)) {
                continue;
            }
            $recordIndexesByPage[(int) $layout['page']][] = $index;
        }

        $drop = [];
        foreach ($recordIndexesByPage as $indexes) {
            $pageRecords = array_map(static fn (int $index): array => $records[$index], $indexes);
            $medianFontSize = $this->median(array_map(
                static fn (array $record): float => max(1.0, (float) $record['layout']['fontSize']),
                $pageRecords
            ));
            foreach ($indexes as $index) {
                if (($records[$index]['layout']['sourcePdfProtectedSemanticContent'] ?? false) === true) {
                    continue;
                }
                if ($this->pdfUnstructuredDisplayFragmentLooksIncomplete($records[$index], $medianFontSize)) {
                    $drop[$index] = true;
                }
            }
            $anchors = $this->pdfProseLayoutAnchors($pageRecords);
            if (count($anchors) < 2) {
                continue;
            }
            $longLines = 0;
            foreach ($pageRecords as $record) {
                if ($this->length(trim($record['text'])) >= 32) {
                    $longLines++;
                }
            }
            if ($longLines < max(6, (int) ceil(count($pageRecords) * 0.25))) {
                continue;
            }

            foreach ($indexes as $index) {
                $record = $records[$index];
                $layout = $record['layout'];
                $line = trim($record['text']);
                if (($layout['sourcePdfProtectedSemanticContent'] ?? false) === true
                    || $this->pdfLineStartsWithSemanticPrefix($line)
                    || ($layout['code'] ?? false) === true
                    || ($layout['sourceFootnotePrefixedGeometry'] ?? false) === true
                    || $this->lineHasPdfListBlockEvidence($line)
                    || $this->lineLooksLikeUrlOnly($line)
                    || $this->lineLooksLikePdfAllCapsDisplayText($line)
                    || $this->lineLooksLikeCompletePdfCaption($line)
                    || $this->length($line) > 42
                    || count($this->pdfLineWordTokens($line)) > 7
                    || (float) $layout['fontSize'] > $medianFontSize * 1.35) {
                    continue;
                }

                $anchor = $this->nearestPdfProseLayoutAnchor($layout, $anchors);
                if ($anchor === null) {
                    continue;
                }
                $startTolerance = max(10.0, $medianFontSize * 1.25);
                $onAnchor = abs((float) $layout['x1'] - $anchor['x']) <= $startTolerance;
                $hasRhythmNeighbor = $this->pdfLayoutHasProseRhythmNeighbor(
                    $layout,
                    $pageRecords,
                    $anchor['x'],
                    $startTolerance,
                    $medianFontSize
                );
                if ($this->pdfRecordHasWrappedSourceContinuationAbove($record, $pageRecords, $medianFontSize)) {
                    continue;
                }
                if ($this->pdfRecordHasCoherentSourceContinuationBelow($record, $pageRecords, $medianFontSize)) {
                    continue;
                }
                if ($this->pdfRecordContinuesInlineTerminalLead($record, $pageRecords)) {
                    continue;
                }
                if (!$onAnchor || !$hasRhythmNeighbor) {
                    $drop[$index] = true;
                }
            }
        }

        if ($drop === []) {
            return $records;
        }

        return array_values(array_filter(
            $records,
            static fn (array $_record, int $index): bool => !isset($drop[$index]),
            ARRAY_FILTER_USE_BOTH
        ));
    }

    /**
     * Decorative PDF text can lose its first glyph while retaining a large
     * display fragment such as a lower-case word followed by a capitalized
     * word. It is not reliable prose or a complete label. Drop only this
     * unstructured oversized shape; ordinary headings retain their initial
     * capital and source-structured body text is never considered here.
     *
     * @param array{text: string, layout: array<string, mixed>|null} $record
     */
    private function pdfUnstructuredDisplayFragmentLooksIncomplete(array $record, float $medianFontSize): bool
    {
        $layout = is_array($record['layout'] ?? null) ? $record['layout'] : null;
        $line = trim((string) ($record['text'] ?? ''));
        if (!$this->pdfLayoutHasGeometry($layout)
            || ($layout['sourceStructuredGeometry'] ?? false) === true
            || ($layout['code'] ?? false) === true
            || $this->lineHasPdfListBlockEvidence($line)
            || $this->lineLooksLikeUrlOnly($line)
            || preg_match('/[.!?;:]\s*$/u', $line) === 1
            || count($this->pdfLineWordTokens($line)) < 2
            || count($this->pdfLineWordTokens($line)) > 4
            || $this->length($line) > 36
            || (float) $layout['fontSize'] < max(18.0, $medianFontSize * 2.20)) {
            return false;
        }

        return preg_match('/^[^\p{L}\p{N}]*\p{Ll}\p{L}*(?:\s+\p{Lu}\p{L}*)/u', $line) === 1;
    }

    /**
     * A display callout can place a short phrase to the right of a short
     * colon-ended lead, then continue on the lead's next baseline. The PDF
     * stream frequently paints that right-hand phrase later than the wrapped
     * continuation, so it looks like a floating fragment unless the baseline,
     * font, and narrow inline gap are considered together.
     *
     * @param array{text: string, layout: array<string, mixed>|null} $record
     * @param list<array{text: string, layout: array<string, mixed>|null}> $pageRecords
     */
    private function pdfRecordContinuesInlineTerminalLead(array $record, array $pageRecords): bool
    {
        $layout = is_array($record['layout'] ?? null) ? $record['layout'] : null;
        if (!$this->pdfLayoutHasGeometry($layout)) {
            return false;
        }

        foreach ($pageRecords as $candidate) {
            $candidateLayout = is_array($candidate['layout'] ?? null) ? $candidate['layout'] : null;
            if (!$this->pdfLayoutHasGeometry($candidateLayout)
                || (float) $candidateLayout['x1'] > (float) $layout['x1']) {
                continue;
            }
            if ($this->pdfLayoutsFormInlineTerminalLead(
                (string) ($candidate['text'] ?? ''),
                (string) ($record['text'] ?? ''),
                $candidateLayout,
                $layout
            )) {
                return true;
            }
        }

        return false;
    }

    /**
     * @param array<string, mixed>|null $leftLayout
     * @param array<string, mixed>|null $rightLayout
     */
    private function pdfLayoutsFormInlineTerminalLead(
        string $left,
        string $right,
        ?array $leftLayout,
        ?array $rightLayout
    ): bool {
        $left = trim($left);
        $right = ltrim($right);
        if (!$this->pdfLayoutHasGeometry($leftLayout)
            || !$this->pdfLayoutHasGeometry($rightLayout)
            || ($leftLayout['page'] ?? null) !== ($rightLayout['page'] ?? null)
            || ($leftLayout['code'] ?? false) === true
            || ($rightLayout['code'] ?? false) === true
            || $this->lineHasPdfListBlockEvidence($left)
            || $this->lineHasPdfListBlockEvidence($right)
            || count($this->pdfLineWordTokens($left)) > 4
            || count($this->pdfLineWordTokens($right)) > 4
            || preg_match('/:\s*$/u', $left) !== 1
            || preg_match('/^[^\p{L}\p{N}]*\p{Lu}/u', $right) !== 1) {
            return false;
        }

        $fontSize = max(1.0, (float) $leftLayout['fontSize'], (float) $rightLayout['fontSize']);
        if (abs((float) $leftLayout['fontSize'] - (float) $rightLayout['fontSize']) > max(1.5, $fontSize * 0.22)) {
            return false;
        }
        $leftCenter = ((float) $leftLayout['y1'] + (float) $leftLayout['y2']) / 2.0;
        $rightCenter = ((float) $rightLayout['y1'] + (float) $rightLayout['y2']) / 2.0;
        $gap = (float) $rightLayout['x1'] - (float) $leftLayout['x2'];

        return abs($leftCenter - $rightCenter) <= max(2.5, $fontSize * 0.35)
            && (float) $rightLayout['x1'] >= (float) $leftLayout['x1']
            && $gap >= -max(2.0, $fontSize * 0.20)
            && $gap <= max(18.0, $fontSize * 1.5);
    }

    private function lineLooksLikePdfAllCapsDisplayText(string $line): bool
    {
        $words = $this->pdfLineWordTokens($line);
        if (count($words) < 2) {
            return false;
        }
        foreach ($words as $word) {
            if (preg_match('/^\p{Lu}[\p{Lu}\p{N}.-]*$/u', $word) !== 1) {
                return false;
            }
        }

        return true;
    }

    private function lineLooksLikeCompletePdfCaption(string $line): bool
    {
        return count($this->pdfLineWordTokens($line)) >= 4
            && preg_match('/[.!?]\s*$/u', trim($line)) === 1;
    }

    /**
     * @param list<array{text: string, layout: array<string, mixed>|null}> $records
     * @return list<array{x: float, count: int}>
     */
    private function pdfProseLayoutAnchors(array $records): array
    {
        if (count($records) < 12) {
            return [];
        }
        $fontSizes = array_map(
            static fn (array $record): float => max(1.0, (float) $record['layout']['fontSize']),
            $records
        );
        $medianFontSize = $this->median($fontSizes);
        $startTolerance = max(10.0, $medianFontSize * 1.25);
        usort($records, static fn (array $left, array $right): int => $left['layout']['x1'] <=> $right['layout']['x1']);

        $groups = [];
        foreach ($records as $record) {
            $start = (float) $record['layout']['x1'];
            $groupIndex = null;
            foreach ($groups as $index => $group) {
                if (abs($start - $group['x']) <= $startTolerance) {
                    $groupIndex = $index;
                    break;
                }
            }
            if ($groupIndex === null) {
                $groups[] = ['x' => $start, 'records' => [$record]];
                continue;
            }
            $groups[$groupIndex]['records'][] = $record;
            $groups[$groupIndex]['x'] = $this->median(array_map(
                static fn (array $entry): float => (float) $entry['layout']['x1'],
                $groups[$groupIndex]['records']
            ));
        }

        $anchors = [];
        foreach ($groups as $group) {
            $groupRecords = $group['records'];
            if (count($groupRecords) < 4) {
                continue;
            }
            usort($groupRecords, static fn (array $left, array $right): int => $right['layout']['y1'] <=> $left['layout']['y1']);
            $rhythmPairs = 0;
            foreach ($groupRecords as $index => $record) {
                if (!isset($groupRecords[$index + 1])) {
                    break;
                }
                $upper = $record['layout'];
                $lower = $groupRecords[$index + 1]['layout'];
                $fontSize = max((float) $upper['fontSize'], (float) $lower['fontSize'], $medianFontSize, 1.0);
                $step = (float) $upper['y1'] - (float) $lower['y1'];
                if ($step >= $fontSize * 0.30 && $step <= $fontSize * 3.0) {
                    $rhythmPairs++;
                }
            }
            if ($rhythmPairs < 2) {
                continue;
            }
            $anchors[] = ['x' => (float) $group['x'], 'count' => count($groupRecords)];
        }

        return $anchors;
    }

    /**
     * @param array<string, mixed> $layout
     * @param list<array{x: float, count: int}> $anchors
     * @return array{x: float, count: int}|null
     */
    private function nearestPdfProseLayoutAnchor(array $layout, array $anchors): ?array
    {
        $nearest = null;
        $distance = INF;
        foreach ($anchors as $anchor) {
            $candidateDistance = abs((float) $layout['x1'] - $anchor['x']);
            if ($candidateDistance < $distance) {
                $nearest = $anchor;
                $distance = $candidateDistance;
            }
        }

        return $nearest;
    }

    /**
     * @param array<string, mixed> $layout
     * @param list<array{text: string, layout: array<string, mixed>|null}> $records
     */
    private function pdfLayoutHasProseRhythmNeighbor(
        array $layout,
        array $records,
        float $anchorX,
        float $startTolerance,
        float $medianFontSize
    ): bool {
        foreach ($records as $record) {
            $candidate = $record['layout'];
            if ($candidate === $layout || abs((float) $candidate['x1'] - $anchorX) > $startTolerance) {
                continue;
            }
            $fontSize = max((float) $candidate['fontSize'], (float) $layout['fontSize'], $medianFontSize, 1.0);
            $distance = abs((float) $candidate['y1'] - (float) $layout['y1']);
            if ($distance >= $fontSize * 0.30 && $distance <= $fontSize * 3.0) {
                return true;
            }
        }

        return false;
    }

    /**
     * Some PDFs indent the first line of a text run differently from its
     * wrapped continuation. Retain a short lowercase continuation when a
     * substantially longer source-stream line sits directly above it, even if
     * the continuation begins at a different visual edge.
     *
     * @param array{text: string, layout: array<string, mixed>|null} $record
     * @param list<array{text: string, layout: array<string, mixed>|null}> $records
     */
    private function pdfRecordHasWrappedSourceContinuationAbove(array $record, array $records, float $medianFontSize): bool
    {
        $layout = $record['layout'];
        if (!$this->pdfLayoutHasGeometry($layout)
            || !isset($layout['sourceStream'])
            || preg_match('/^\s*\p{Ll}/u', $record['text']) !== 1) {
            return false;
        }
        $lineLength = max(1, $this->length(trim($record['text'])));
        foreach ($records as $candidate) {
            $candidateLayout = $candidate['layout'];
            if (!$this->pdfLayoutHasGeometry($candidateLayout)
                || ($candidateLayout['sourceStream'] ?? null) !== $layout['sourceStream']) {
                continue;
            }
            $fontSize = max((float) $candidateLayout['fontSize'], (float) $layout['fontSize'], $medianFontSize, 1.0);
            $step = (float) $candidateLayout['y1'] - (float) $layout['y1'];
            if ($step < $fontSize * 0.30 || $step > $fontSize * 3.0) {
                continue;
            }
            if ($this->length(trim($candidate['text'])) < max(42, $lineLength * 1.5)
                || preg_match('/[.!?]\s*$/u', trim($candidate['text'])) === 1) {
                continue;
            }

            return true;
        }

        return false;
    }

    /**
     * A source run can start after a styled heading or an omitted glyph run
     * and therefore have an indented visual left edge. Keep that short run
     * when the next source line proves it continues into the ordinary body
     * rhythm. This is stronger than treating every off-anchor short line as a
     * figure label.
     *
     * @param array{text: string, layout: array<string, mixed>|null} $record
     * @param list<array{text: string, layout: array<string, mixed>|null}> $records
     */
    private function pdfRecordHasCoherentSourceContinuationBelow(array $record, array $records, float $medianFontSize): bool
    {
        $layout = $record['layout'];
        $text = trim($record['text']);
        if (!$this->pdfLayoutHasGeometry($layout)
            || !isset($layout['sourceStream'], $layout['sourcePdfSourceIndex'])
            || $text === ''
            || ($layout['code'] ?? false) === true
            || $this->lineHasPdfListBlockEvidence($text)
            || preg_match('/[.!?;:]\s*$/u', $text) === 1
            || preg_match('/^[^\p{L}\p{N}]*\p{Ll}/u', $text) === 1) {
            return false;
        }

        foreach ($records as $candidate) {
            $candidateLayout = $candidate['layout'];
            $candidateText = ltrim($candidate['text']);
            if (!$this->pdfLayoutHasGeometry($candidateLayout)
                || ($candidateLayout['page'] ?? null) !== ($layout['page'] ?? null)
                || ($candidateLayout['sourceStream'] ?? null) !== $layout['sourceStream']
                || ($candidateLayout['sourcePdfSourceIndex'] ?? null) !== $layout['sourcePdfSourceIndex'] + 1
                || ($candidateLayout['sourceGeometryColumn'] ?? null) !== ($layout['sourceGeometryColumn'] ?? null)
                || ($candidateLayout['code'] ?? false) === true
                || $this->lineHasPdfListBlockEvidence($candidateText)
                || preg_match('/^[^\p{L}\p{N}]*\p{Ll}/u', $candidateText) !== 1) {
                continue;
            }

            $fontSize = max((float) $layout['fontSize'], (float) $candidateLayout['fontSize'], $medianFontSize, 1.0);
            $step = (float) $layout['y1'] - (float) $candidateLayout['y1'];
            if ($step >= $fontSize * 0.30 && $step <= max(18.0, $fontSize * 2.0)) {
                return true;
            }
        }

        return false;
    }

    /**
     * @return list<string>
     */
    private function splitPdfTextLineVisualChunks(string $line): array
    {
        if (!str_contains($line, "\t")) {
            return [$line];
        }

        $chunks = [];
        foreach (preg_split('/\t+/u', $line) ?: [] as $chunk) {
            $chunk = trim($chunk);
            if ($chunk !== '') {
                $chunks[] = $chunk;
            }
        }

        return $chunks === [] ? [$line] : $chunks;
    }

    private function lineIsStandalonePdfListMarker(string $line): bool
    {
        return preg_match('/^\s*(?:[-*]|\x{2022}|\d{1,2}[.)])\s*$/u', $line) === 1;
    }

    /**
     * @param list<array{text: string, layout: array{text: string, page: int, x1: float, y1: float, x2: float, y2: float, fontSize: float}|null}> $records
     */
    private function pdfLinesLookLikeDenseListLayout(array $records): bool
    {
        $count = count($records);
        if ($count < 20) {
            return false;
        }

        $listItems = 0;
        $shortLines = 0;
        $totalLength = 0;
        foreach ($records as $record) {
            $line = trim($record['text']);
            $length = $this->length($line);
            $totalLength += $length;
            if ($length <= 42) {
                $shortLines++;
            }
            if ($this->lineHasPdfListBlockEvidence($line)) {
                $listItems++;
            }
        }

        $listRatio = $listItems / $count;
        $shortRatio = $shortLines / $count;
        $averageLength = $totalLength / $count;

        return $listItems >= 6
            && $listRatio >= 0.08
            && $shortRatio >= 0.45
            && $averageLength <= 48.0;
    }

    /**
     * @param list<array{text: string, layout: array{text: string, page: int, x1: float, y1: float, x2: float, y2: float, fontSize: float}|null}> $records
     */
    private function pdfLinesLookLikeSparseLongTextChunks(array $records): bool
    {
        $count = count($records);
        if ($count < 8 || $count > 60) {
            return false;
        }

        $longLines = 0;
        $shortLines = 0;
        $listItems = 0;
        $totalLength = 0;
        foreach ($records as $record) {
            $line = trim($record['text']);
            $length = $this->length($line);
            $totalLength += $length;
            if ($length >= 70) {
                $longLines++;
            }
            if ($length <= 42) {
                $shortLines++;
            }
            if ($this->lineHasPdfListBlockEvidence($line)) {
                $listItems++;
            }
        }

        return $longLines / $count >= 0.60
            && $shortLines / $count <= 0.25
            && $totalLength / $count >= 80.0
            && $listItems <= 2;
    }

    /**
     * Some scan-front-matter OCR uses a leading plus as the only surviving
     * list marker and attaches it directly to a title-cased item lead. A lone
     * plus can be ordinary editable syntax, so require at least three such
     * long-text records in one exact page/stream scope before preserving their
     * source boundaries as reviewable paragraphs. Text and source order stay
     * byte-for-byte unchanged.
     *
     * @param list<array{text:string,layout:array<string,mixed>|null}> $records
     * @return list<array{text:string,layout:array<string,mixed>|null}>
     */
    private function pdfRecordsWithSparseOcrPlusBoundaries(array $records): array
    {
        if (!$this->pdfLinesLookLikeSparseLongTextChunks($records)) {
            return $records;
        }

        $candidateIndexesByScope = [];
        foreach ($records as $index => $record) {
            $text = trim((string) ($record['text'] ?? ''));
            $layout = is_array($record['layout'] ?? null) ? $record['layout'] : null;
            $page = is_array($layout) ? (int) ($layout['page'] ?? 0) : 0;
            $stream = is_array($layout)
                ? (int) ($layout['sourceStream'] ?? $layout['stream'] ?? 0)
                : 0;
            if ($page < 1
                || $stream < 1
                || ($layout['code'] ?? false) === true
                || isset($layout['sourcePdfTableGroup'])
                || isset($layout['sourcePdfLineOrientedGroup'])
                || preg_match('/^\+\p{Lu}[\p{L}\p{M}\p{Pd}]*\s+/u', $text) !== 1
                || count($this->pdfLineWordTokens($text)) < 6) {
                continue;
            }
            $candidateIndexesByScope[$page . "\0" . $stream][] = $index;
        }

        foreach ($candidateIndexesByScope as $indexes) {
            if (count($indexes) < 3) {
                continue;
            }
            $firstLayout = is_array($records[$indexes[0]]['layout'] ?? null)
                ? $records[$indexes[0]]['layout']
                : null;
            $introIndex = $indexes[0] - 1;
            $introLayout = $introIndex >= 0
                && is_array($records[$introIndex]['layout'] ?? null)
                    ? $records[$introIndex]['layout']
                    : null;
            $introText = $introIndex >= 0
                ? trim((string) ($records[$introIndex]['text'] ?? ''))
                : '';
            $introWordCount = count($this->pdfLineWordTokens($introText));
            if (is_array($firstLayout)
                && is_array($introLayout)
                && (int) ($introLayout['page'] ?? 0)
                    === (int) ($firstLayout['page'] ?? -1)
                && (int) ($introLayout['sourceStream'] ?? $introLayout['stream'] ?? 0)
                    === (int) ($firstLayout['sourceStream'] ?? $firstLayout['stream'] ?? -1)
                && $introWordCount >= 3
                && $introWordCount <= 12
                && preg_match('/:\s*$/u', $introText) === 1) {
                $introLayout['forceBlockBreakBefore'] = true;
                $records[$introIndex]['layout'] = $introLayout;
            }
            foreach ($indexes as $index) {
                $layout = is_array($records[$index]['layout'] ?? null)
                    ? $records[$index]['layout']
                    : [];
                $layout['forceBlockBreakBefore'] = true;
                $records[$index]['layout'] = $layout;
            }
        }

        return $records;
    }

    /**
     * @param list<array{text: string, layout: array{text: string, page: int, x1: float, y1: float, x2: float, y2: float, fontSize: float}|null}> $records
     * @return list<array{text: string, layout: array{text: string, page: int, x1: float, y1: float, x2: float, y2: float, fontSize: float}|null}>
     */
    private function removeLowCoherencePdfMapRegions(array $records): array
    {
        $filtered = [];
        $candidate = [];
        $candidatePage = null;
        $flushCandidate = function () use (&$filtered, &$candidate, &$candidatePage): void {
            if ($candidate === []) {
                $candidatePage = null;
                return;
            }
            if (!$this->pdfMapNoiseClusterShouldBeDropped($candidate)) {
                foreach ($candidate as $record) {
                    $filtered[] = $record;
                }
            } else {
                foreach ($this->atomicPdfMapLegendRecords($candidate) as $record) {
                    $filtered[] = $record;
                }
            }
            $candidate = [];
            $candidatePage = null;
        };

        foreach ($records as $record) {
            $layout = is_array($record['layout'] ?? null) ? $record['layout'] : null;
            $recordPage = is_numeric($layout['page'] ?? null) && (int) $layout['page'] > 0
                ? (int) $layout['page']
                : null;
            if ($candidate !== [] && $recordPage !== $candidatePage) {
                // Map-region geometry and its source proof are page-local.
                // Never let a short display tail borrow the next physical
                // page's sustained-map evidence (or poison its proof identity).
                $flushCandidate();
            }

            $line = $record['text'];
            if ($this->lineLooksLikePdfMapLabelNoise($line, $layout)
                || $this->lineLooksLikePdfMapLabelBridge($record, $candidate)) {
                if ($candidate === []) {
                    $candidatePage = $recordPage;
                }
                $candidate[] = $record;
                continue;
            }

            $flushCandidate();
            $filtered[] = $record;
        }
        $flushCandidate();

        return $filtered;
    }

    /**
     * @param list<array{text: string, layout: array<string, mixed>|null}> $records
     * @return list<array{text: string, layout: array<string, mixed>|null}>
     */
    private function atomicPdfMapLegendRecords(array $records): array
    {
        if ($this->pdfRecordsSharePageMapLabelGeometryEvidence($records)) {
            // Every carrier belongs to the same source-identified page whose
            // independent positioned layer proved a sustained map region.
            // Preserve the exact source characters and their source order as
            // one line-oriented block; the proof deliberately supplies no
            // fabricated per-record coordinates.
            $this->registerSourcePdfMapGlyphLadderArtifactProofs($records);
            return $this->atomicPdfMapLabelRecords($records);
        }

        $atomic = [];
        $positionedRun = [];
        $flushRun = function () use (&$atomic, &$positionedRun): void {
            if ($this->pdfMapLabelClusterLooksLikeLegend($positionedRun)) {
                foreach ($this->atomicPdfMapLabelRecords($positionedRun) as $record) {
                    $atomic[] = $record;
                }
            }
            $positionedRun = [];
        };

        foreach ($records as $record) {
            if ($this->pdfLayoutHasGeometry($record['layout'])) {
                $positionedRun[] = $record;
                continue;
            }
            $flushRun();
        }
        $flushRun();

        return $atomic;
    }

    /**
     * @param list<array{text:string,layout:array<string,mixed>|null}> $records
     */
    private function pdfRecordsSharePageMapLabelGeometryEvidence(array $records): bool
    {
        if (count($records) < 8) {
            return false;
        }

        $proofIdentity = null;
        foreach ($records as $record) {
            $layout = is_array($record['layout'] ?? null) ? $record['layout'] : null;
            $evidence = is_array($layout['sourcePdfPageMapLabelGeometryEvidence'] ?? null)
                ? $layout['sourcePdfPageMapLabelGeometryEvidence']
                : null;
            if ($evidence === null
                || ($evidence['kind'] ?? null) !== 'positioned-sustained-map-label-region'
                || (int) ($evidence['page'] ?? 0) < 1
                || (int) ($layout['page'] ?? 0) !== (int) $evidence['page']
                || (string) ($evidence['sourceSha256'] ?? '') === ''
                || (string) $evidence['sourceSha256'] !== $this->sourceSha256
                || (int) ($evidence['mapLabelRecordCount'] ?? 0) < 8
                || (int) ($evidence['positionedRecordCount'] ?? 0) < (int) $evidence['mapLabelRecordCount']) {
                return false;
            }

            $identity = implode(':', [
                (string) $evidence['sourceSha256'],
                (string) $evidence['page'],
                (string) $evidence['positionedRecordCount'],
                (string) $evidence['mapLabelRecordCount'],
            ]);
            if ($proofIdentity !== null && $identity !== $proofIdentity) {
                return false;
            }
            $proofIdentity = $identity;
        }

        return $proofIdentity !== null;
    }

    /**
     * Sign only the exact source occurrences that the map-label renderer will
     * omit under its existing greater-than-sixteen compact-line bound. The
     * independently positioned page evidence establishes a sustained spatial
     * map region; consecutive immutable source IDs and full occurrence ranges
     * keep an unrelated short prose run from borrowing that classification.
     *
     * @param list<array{text:string,layout:array<string,mixed>|null}> $records
     */
    private function registerSourcePdfMapGlyphLadderArtifactProofs(array $records): void
    {
        $run = [];
        $flush = function () use (&$run): void {
            if (count($run) <= 16) {
                $run = [];
                return;
            }

            $firstLayout = is_array($run[0]['layout'] ?? null)
                ? $run[0]['layout']
                : null;
            $pageEvidence = is_array(
                $firstLayout['sourcePdfPageMapLabelGeometryEvidence'] ?? null
            ) ? $firstLayout['sourcePdfPageMapLabelGeometryEvidence'] : null;
            $page = is_array($firstLayout) ? (int) ($firstLayout['page'] ?? 0) : 0;
            $stream = is_array($firstLayout)
                ? (int) ($firstLayout['sourceStream'] ?? $firstLayout['stream'] ?? 0)
                : 0;
            if ($pageEvidence === null
                || ($pageEvidence['kind'] ?? null)
                    !== 'positioned-sustained-map-label-region'
                || ($pageEvidence['sourceSha256'] ?? null) !== $this->sourceSha256
                || ($pageEvidence['page'] ?? null) !== $page
                || (int) ($pageEvidence['mapLabelRecordCount'] ?? 0) < 8
                || (int) ($pageEvidence['positionedRecordCount'] ?? 0)
                    < (int) $pageEvidence['mapLabelRecordCount']
                || $page < 1
                || $stream < 1) {
                $run = [];
                return;
            }

            $lines = [];
            $sourceIds = [];
            $globalIndexes = [];
            $previousGlobalIndex = null;
            foreach ($run as $record) {
                $layout = is_array($record['layout'] ?? null)
                    ? $record['layout']
                    : null;
                $text = trim((string) ($record['text'] ?? ''));
                $projection = $this->pdfSourceOccurrenceComparableText($text);
                $sourceId = is_array($layout) && is_string($layout['id'] ?? null)
                    ? $layout['id']
                    : '';
                $globalIndex = is_array($layout)
                    && is_int($layout['sourcePdfGlobalSourceIndex'] ?? null)
                        ? $layout['sourcePdfGlobalSourceIndex']
                        : -1;
                $ranges = is_array($layout)
                    ? $this->pdfPositionedExactSourceRanges($layout)
                    : [];
                if ($sourceId === ''
                    || $globalIndex < 0
                    || $projection === ''
                    || $this->length($text) > 3
                    || (int) ($layout['page'] ?? 0) !== $page
                    || (int) ($layout['sourceStream'] ?? $layout['stream'] ?? 0)
                        !== $stream
                    || ($layout['sourcePdfPageMapLabelGeometryEvidence'] ?? null)
                        !== $pageEvidence
                    || ($previousGlobalIndex !== null
                        && $globalIndex !== $previousGlobalIndex + 1)
                    || $ranges !== [[
                        'sourceIndex' => $globalIndex,
                        'sourceStart' => 0,
                        'sourceEnd' => strlen($projection),
                    ]]) {
                    $run = [];
                    return;
                }
                $sourceIds[] = $sourceId;
                $globalIndexes[] = $globalIndex;
                $lines[] = [
                    'sourceOccurrenceId' => $sourceId,
                    'globalSourceIndex' => $globalIndex,
                    'projectionDigest' => hash('sha256', $projection),
                    'significantBytes' => strlen($projection),
                    'exactRange' => $ranges[0],
                ];
                $previousGlobalIndex = $globalIndex;
            }
            if (count(array_unique($sourceIds, SORT_STRING)) !== count($sourceIds)
                || count(array_unique($globalIndexes, SORT_NUMERIC))
                    !== count($globalIndexes)) {
                $run = [];
                return;
            }

            $proof = [
                'version' => 1,
                'method' => 'exact-source-sustained-map-glyph-ladder',
                'sourceSha256' => $this->sourceSha256,
                'page' => $page,
                'stream' => $stream,
                'boundedShortRunLimit' => 16,
                'lineCount' => count($lines),
                'sourceOccurrenceIds' => $sourceIds,
                'globalSourceIndexes' => $globalIndexes,
                'pageMapLabelGeometryEvidence' => $pageEvidence,
                'lines' => $lines,
            ];
            $proof['proofDigest'] = hash('sha256', json_encode(
                $proof,
                JSON_UNESCAPED_SLASHES
                    | JSON_UNESCAPED_UNICODE
                    | JSON_PRESERVE_ZERO_FRACTION
            ) ?: '');
            foreach ($sourceIds as $sourceId) {
                $existing = $this->sourcePdfMapGlyphLadderArtifactProofsBySourceId[
                    $sourceId
                ] ?? null;
                if (is_array($existing) && $existing !== $proof) {
                    $run = [];
                    return;
                }
            }
            foreach ($sourceIds as $sourceId) {
                $this->sourcePdfMapGlyphLadderArtifactProofsBySourceId[$sourceId] =
                    $proof;
            }
            $run = [];
        };

        foreach ($records as $record) {
            if ($this->length(trim((string) ($record['text'] ?? ''))) <= 3) {
                $run[] = $record;
                continue;
            }
            $flush();
        }
        $flush();
    }

    /**
     * @param array<string,mixed> $proof
     * @param list<array<string,mixed>> $lineItems
     */
    private function sourcePdfMapGlyphLadderArtifactProofMatchesSourceItems(
        array $proof,
        array $lineItems
    ): bool {
        $sourceIds = $proof['sourceOccurrenceIds'] ?? null;
        $globalIndexes = $proof['globalSourceIndexes'] ?? null;
        $lines = $proof['lines'] ?? null;
        $pageEvidence = $proof['pageMapLabelGeometryEvidence'] ?? null;
        if (!$this->sourcePdfSignedProofDigestMatches($proof)
            || ($proof['method'] ?? null)
                !== 'exact-source-sustained-map-glyph-ladder'
            || ($proof['boundedShortRunLimit'] ?? null) !== 16
            || !is_int($proof['lineCount'] ?? null)
            || $proof['lineCount'] <= 16
            || !is_array($sourceIds)
            || !array_is_list($sourceIds)
            || !is_array($globalIndexes)
            || !array_is_list($globalIndexes)
            || !is_array($lines)
            || !array_is_list($lines)
            || count($sourceIds) !== $proof['lineCount']
            || count($globalIndexes) !== $proof['lineCount']
            || count($lines) !== $proof['lineCount']
            || count(array_unique($sourceIds, SORT_STRING)) !== count($sourceIds)
            || count(array_unique($globalIndexes, SORT_NUMERIC))
                !== count($globalIndexes)
            || !is_array($pageEvidence)
            || ($pageEvidence['kind'] ?? null)
                !== 'positioned-sustained-map-label-region'
            || ($pageEvidence['sourceSha256'] ?? null) !== $this->sourceSha256
            || ($pageEvidence['page'] ?? null) !== ($proof['page'] ?? null)
            || (int) ($pageEvidence['mapLabelRecordCount'] ?? 0) < 8
            || (int) ($pageEvidence['positionedRecordCount'] ?? 0)
                < (int) $pageEvidence['mapLabelRecordCount']) {
            return false;
        }

        $previousGlobalIndex = null;
        foreach ($globalIndexes as $offset => $globalIndex) {
            $sourceId = $sourceIds[$offset] ?? null;
            $line = $lines[$offset] ?? null;
            $item = is_int($globalIndex) ? ($lineItems[$globalIndex] ?? null) : null;
            $projection = is_array($item)
                ? $this->pdfSourceOccurrenceComparableText(
                    (string) ($item['text'] ?? '')
                )
                : '';
            if (!is_int($globalIndex)
                || $globalIndex < 0
                || !is_string($sourceId)
                || $sourceId === ''
                || !is_array($line)
                || !is_array($item)
                || ($item['id'] ?? null) !== $sourceId
                || (int) ($item['page'] ?? 0) !== ($proof['page'] ?? null)
                || (int) ($item['stream'] ?? 0) !== ($proof['stream'] ?? null)
                || $projection === ''
                || $this->length(trim((string) ($item['text'] ?? ''))) > 3
                || ($previousGlobalIndex !== null
                    && $globalIndex !== $previousGlobalIndex + 1)
                || $line !== [
                    'sourceOccurrenceId' => $sourceId,
                    'globalSourceIndex' => $globalIndex,
                    'projectionDigest' => hash('sha256', $projection),
                    'significantBytes' => strlen($projection),
                    'exactRange' => [
                        'sourceIndex' => $globalIndex,
                        'sourceStart' => 0,
                        'sourceEnd' => strlen($projection),
                    ],
                ]) {
                return false;
            }
            $previousGlobalIndex = $globalIndex;
        }

        return true;
    }

    /**
     * Keep a true map legend available as isolated text, rather than letting
     * its labels masquerade as document headings or list continuations. A
     * legend has multiple recurring label columns; free-positioned diagram
     * labels do not meet this geometric condition and remain suppressed.
     *
     * @param list<array{text: string, layout: array<string, mixed>|null}> $records
     */
    private function pdfMapLabelClusterLooksLikeLegend(array $records): bool
    {
        if (count($records) < 8) {
            return false;
        }

        $columns = [];
        foreach ($records as $record) {
            $layout = $record['layout'];
            if (!$this->pdfLayoutHasGeometry($layout)
                || ($layout['sourceDetachedDiagramEvidencePage'] ?? false) === true) {
                return false;
            }

            $fontSize = max(1.0, (float) $layout['fontSize']);
            $matchedColumn = null;
            foreach ($columns as $index => $column) {
                if (abs((float) $layout['x1'] - $column['x']) <= max(16.0, $fontSize * 3.0)) {
                    $matchedColumn = $index;
                    break;
                }
            }
            if ($matchedColumn === null) {
                $columns[] = ['x' => (float) $layout['x1'], 'count' => 1];
                continue;
            }
            $columns[$matchedColumn]['count']++;
        }

        $repeatedColumns = array_filter(
            $columns,
            static fn (array $column): bool => $column['count'] >= 3
        );

        if (count($repeatedColumns) >= 2) {
            return true;
        }
        if (count($repeatedColumns) !== 1) {
            return false;
        }

        // A map key can be a single, vertically stacked label column rather
        // than a two-column legend. Keep it only when the same geometry shows
        // a sustained baseline rhythm; a scattered one-column diagram does
        // not meet this condition.
        $column = array_values($repeatedColumns)[0];
        if ($column['count'] < 5) {
            return false;
        }
        $columnRecords = array_values(array_filter(
            $records,
            static fn (array $record): bool => abs((float) $record['layout']['x1'] - $column['x'])
                <= max(16.0, (float) $record['layout']['fontSize'] * 3.0)
        ));
        usort($columnRecords, static fn (array $left, array $right): int => $right['layout']['y1'] <=> $left['layout']['y1']);
        $rhythmPairs = 0;
        foreach ($columnRecords as $index => $record) {
            if (!isset($columnRecords[$index + 1])) {
                break;
            }
            $next = $columnRecords[$index + 1];
            $fontSize = max(1.0, (float) $record['layout']['fontSize'], (float) $next['layout']['fontSize']);
            $step = (float) $record['layout']['y1'] - (float) $next['layout']['y1'];
            if ($step >= $fontSize * 0.30 && $step <= $fontSize * 3.0) {
                $rhythmPairs++;
            }
        }

        return $rhythmPairs >= 4;
    }

    /**
     * @param list<array{text: string, layout: array<string, mixed>|null}> $records
     * @return list<array{text: string, layout: array<string, mixed>|null}>
     */
    private function atomicPdfMapLabelRecords(array $records): array
    {
        $atomic = [];
        foreach ($records as $record) {
            $text = trim($record['text']);
            if ($text === '') {
                continue;
            }
            $record['text'] = self::PDF_MAP_LABEL_PREFIX . $text;
            if (is_array($record['layout'])) {
                $record['layout']['forceBlockBreakBefore'] = true;
            }
            $atomic[] = $record;
        }

        return $atomic;
    }

    /**
     * A broken text layer can insert spaces into a compact map label, causing
     * it to look like ordinary short prose. Keep it with an adjacent map-label
     * run only when the geometry proves it occupies the same small, regular
     * label column. This avoids folding it into an unrelated list or paragraph.
     *
     * @param array{text: string, layout: array<string, mixed>|null} $record
     * @param list<array{text: string, layout: array<string, mixed>|null}> $candidate
     */
    private function lineLooksLikePdfMapLabelBridge(array $record, array $candidate): bool
    {
        if ($candidate === [] || $this->lineLooksLikePdfListItem($record['text']) || $this->lineLooksLikeUrlOnly($record['text'])) {
            return false;
        }

        $line = trim($record['text']);
        $layout = $record['layout'];
        if (!$this->pdfLayoutHasGeometry($layout)
            || preg_match('/[.!?;:]\s*$/u', $line) === 1
            || $this->length(preg_replace('/\s+/u', '', $line) ?? '') > 36
            || count($this->pdfLineWordTokens($line)) > 7) {
            return false;
        }

        for ($index = count($candidate) - 1; $index >= max(0, count($candidate) - 2); $index--) {
            $previousLayout = $candidate[$index]['layout'];
            if (!$this->pdfLayoutHasGeometry($previousLayout)
                || ($previousLayout['page'] ?? null) !== ($layout['page'] ?? null)) {
                continue;
            }

            $fontSize = max((float) $previousLayout['fontSize'], (float) $layout['fontSize'], 1.0);
            if ((float) $layout['fontSize'] > (float) $previousLayout['fontSize'] * 1.35
                || abs((float) $layout['x1'] - (float) $previousLayout['x1']) > max(18.0, $fontSize * 3.0)
                || abs((float) $layout['y1'] - (float) $previousLayout['y1']) > max(18.0, $fontSize * 2.8)) {
                continue;
            }

            return true;
        }

        return false;
    }

    /**
     * Diagram labels are frequently emitted as individual glyph fragments in
     * reading order. They can look like a stacked table after text extraction,
     * even though their only reliable semantic counterpart is the surrounding
     * figure caption. Drop only sustained clusters that contain repeated word
     * fragments; ordinary short headings and compact data grids remain intact.
     *
     * @param list<array{text: string, layout: array{text: string, page: int, x1: float, y1: float, x2: float, y2: float, fontSize: float}|null}> $records
     * @return list<array{text: string, layout: array{text: string, page: int, x1: float, y1: float, x2: float, y2: float, fontSize: float}|null}>
     */
    private function removeLowCoherencePdfDiagramLabelRegions(array $records): array
    {
        $filtered = [];
        $candidate = [];
        $flushCandidate = function () use (&$filtered, &$candidate): void {
            if ($candidate === []) {
                return;
            }
            if (!$this->pdfDiagramLabelClusterShouldBeDropped($candidate)) {
                foreach ($candidate as $record) {
                    $filtered[] = $record;
                }
            }
            $candidate = [];
        };

        foreach ($records as $record) {
            $layout = is_array($record['layout'] ?? null) ? $record['layout'] : null;
            if (str_starts_with($record['text'], self::PDF_MAP_LABEL_PREFIX)
                || ($layout['code'] ?? false) === true
                || !$this->pdfLayoutHasGeometry($layout)
                || !$this->lineLooksLikePdfDiagramLabel($record['text'])) {
                $flushCandidate();
                $filtered[] = $record;
                continue;
            }
            $candidate[] = $record;
        }
        $flushCandidate();

        return $filtered;
    }

    /**
     * A line that could not be assigned to one of a complex page's stable
     * prose columns has no reliable reading position. Keep explicit content
     * such as lists, URLs, complete captions, and substantial captions; drop
     * the small unfinished fragments commonly painted inside diagrams.
     *
     * @param list<array{text: string, layout: array<string, mixed>|null}> $records
     * @return list<array{text: string, layout: array<string, mixed>|null}>
     */
    private function removeLowCoherencePdfStructuredFloatingFragments(array $records): array
    {
        $filtered = [];
        foreach ($records as $record) {
            $layout = is_array($record['layout'] ?? null) ? $record['layout'] : null;
            if (str_starts_with($record['text'], self::PDF_MAP_LABEL_PREFIX)
                || ($layout['sourceFloatingGeometry'] ?? false) !== true
                || (($layout['sourceComplexGeometryPage'] ?? false) !== true
                    && ($layout['sourceDetachedDiagramEvidencePage'] ?? false) !== true)) {
                $filtered[] = $record;
                continue;
            }

            $line = trim($record['text']);
            if (($layout['code'] ?? false) === true
                || $this->lineHasPdfListBlockEvidence($line)
                || $this->lineLooksLikeUrlOnly($line)
                || $this->lineLooksLikePdfAllCapsDisplayText($line)
                || $this->lineLooksLikeCompletePdfCaption($line)) {
                $filtered[] = $record;
                continue;
            }
            if (preg_match('/^[\]\)}.,;:]/u', $line) === 1) {
                continue;
            }
            if ($this->length($line) >= 48 && count($this->pdfLineWordTokens($line)) >= 8) {
                $filtered[] = $record;
            }
        }

        return $filtered;
    }

    /**
     * A source-only fragment with a skipped source prefix cannot be promoted
     * to prose merely because a neighboring line supplied coordinates. The
     * marker is assigned only by source-stream and geometry evidence above.
     *
     * @param list<array{text: string, layout: array<string, mixed>|null}> $records
     * @return list<array{text: string, layout: array<string, mixed>|null}>
     */
    private function removeSourcePdfOrphanedInferredContinuations(array $records): array
    {
        $filtered = [];
        $orphanedFlowLayout = null;
        foreach ($records as $record) {
            $layout = is_array($record['layout'] ?? null) ? $record['layout'] : null;
            $text = (string) ($record['text'] ?? '');
            if (($layout['sourceInlineInferredFragment'] ?? false) === true) {
                continue;
            }
            if (($layout['sourceCrossColumnContinuation'] ?? false) === true
                || ($layout['sourceCrossColumnContinuationLead'] ?? false) === true) {
                $orphanedFlowLayout = null;
                $filtered[] = $record;
                continue;
            }
            if (($layout['sourceVerifiedGeometryText'] ?? false) === true
                && $this->length($this->pdfComparableLineText($text)) >= 24
                && count($this->pdfLineWordTokens($text)) >= 4) {
                $orphanedFlowLayout = null;
                $filtered[] = $record;
                continue;
            }
            $startsOrphanedFlow = ($layout['sourceOrphanedInferredContinuation'] ?? false) === true
                || ($layout['sourceUnresolvedInterruptedFlow'] ?? false) === true;
            $continuesOrphanedFlow = !$startsOrphanedFlow
                && $orphanedFlowLayout !== null
                && $this->sourcePdfRecordContinuesOrphanedInferredFlow($layout, $orphanedFlowLayout);
            if ($continuesOrphanedFlow
                && ($orphanedFlowLayout['sourceUnresolvedInterruptedFlow'] ?? false) !== true
                && preg_match('/^[^\p{L}\p{N}]*\p{Lu}/u', ltrim($text)) === 1
                && preg_match('/[.!?]\s*$/u', rtrim($text)) === 1) {
                $continuesOrphanedFlow = false;
            }
            if (!$startsOrphanedFlow && !$continuesOrphanedFlow) {
                $orphanedFlowLayout = null;
            }
            if (!$startsOrphanedFlow && $orphanedFlowLayout === null) {
                $filtered[] = $record;
                continue;
            }

            if ($startsOrphanedFlow || $continuesOrphanedFlow) {
                $orphanedFlowLayout = $layout;
            }
            if ($startsOrphanedFlow) {
                $this->trimSourcePdfFlowBeforeOrphanedContinuation($filtered, $layout);
            }
            $previousIndex = array_key_last($filtered);
            if ($previousIndex === null || $layout === null) {
                continue;
            }
            $previousLayout = is_array($filtered[$previousIndex]['layout'] ?? null)
                ? $filtered[$previousIndex]['layout']
                : null;
            $previousText = rtrim((string) ($filtered[$previousIndex]['text'] ?? ''));
            if (!$this->pdfLayoutHasGeometry($previousLayout)
                || ($previousLayout['page'] ?? null) !== ($layout['page'] ?? null)
                || ($previousLayout['sourceGeometryColumn'] ?? null) !== ($layout['sourceGeometryColumn'] ?? null)
                || preg_match('/[.!?;:]\s*$/u', $previousText) === 1) {
                continue;
            }

            $prefix = $this->completePdfSentencePrefix($previousText);
            if ($prefix !== '' && count($this->pdfLineWordTokens($prefix)) >= 5) {
                $filtered[$previousIndex]['text'] = $prefix;
            }
        }

        return $filtered;
    }

    /**
     * @param list<array{text: string, layout: array<string, mixed>|null}> $records
     * @param array<string, mixed>|null $layout
     */
    private function trimSourcePdfFlowBeforeOrphanedContinuation(array &$records, ?array $layout): void
    {
        if (!$this->pdfLayoutHasGeometry($layout)) {
            return;
        }

        $limit = max(0, count($records) - 10);
        $nextSourceIndex = null;
        for ($index = count($records) - 1; $index >= $limit; $index--) {
            $candidateLayout = is_array($records[$index]['layout'] ?? null) ? $records[$index]['layout'] : null;
            $candidateStart = (int) ($candidateLayout['sourcePdfSourceIndex'] ?? -1);
            $candidateEnd = (int) ($candidateLayout['sourcePdfSourceIndexEnd'] ?? $candidateStart);
            if (!$this->pdfLayoutHasGeometry($candidateLayout)
                || ($candidateLayout['page'] ?? null) !== ($layout['page'] ?? null)
                || !isset($candidateLayout['sourceStream'], $layout['sourceStream'])
                || (int) $candidateLayout['sourceStream'] !== (int) $layout['sourceStream']
                || $candidateStart < 0
                || ($nextSourceIndex !== null && $candidateEnd + 1 !== $nextSourceIndex)
                || isset($candidateLayout['sourcePdfTableGroup'])
                || ($candidateLayout['code'] ?? false) === true) {
                break;
            }
            $nextSourceIndex = $candidateStart;
            $prefix = $this->completePdfSentencePrefix((string) ($records[$index]['text'] ?? ''));
            if ($prefix === '' || count($this->pdfLineWordTokens($prefix)) < 5) {
                continue;
            }
            $records[$index]['text'] = $prefix;
            $records = array_slice($records, 0, $index + 1);

            return;
        }
    }

    /**
     * @param array<string, mixed>|null $layout
     * @param array<string, mixed> $orphanedLayout
     */
    private function sourcePdfRecordContinuesOrphanedInferredFlow(?array $layout, array $orphanedLayout): bool
    {
        if (!$this->pdfLayoutHasGeometry($layout)
            || !$this->pdfLayoutHasGeometry($orphanedLayout)
            || ($layout['page'] ?? null) !== ($orphanedLayout['page'] ?? null)
            || ($layout['sourceGeometryColumn'] ?? null) !== ($orphanedLayout['sourceGeometryColumn'] ?? null)
            || isset($layout['sourcePdfTableGroup'])
            || ($layout['code'] ?? false) === true) {
            return false;
        }

        $fontSize = max(1.0, (float) $layout['fontSize'], (float) $orphanedLayout['fontSize']);
        if (abs((float) $layout['fontSize'] - (float) $orphanedLayout['fontSize']) > max(1.5, $fontSize * 0.22)) {
            return false;
        }
        $verticalStep = (float) $orphanedLayout['y1'] - (float) $layout['y1'];

        return (($orphanedLayout['sourceOrphanedMissingSourceText'] ?? false) === true
                || $this->pdfComparableLineText((string) ($orphanedLayout['text'] ?? '')) !== '')
            && $verticalStep >= -$fontSize * 0.35
            && $verticalStep <= max(18.0, $fontSize * 2.2);
    }

    /**
     * A damaged figure can leave a column-shaped run with its ending words
     * omitted. On a page already proven to contain detached diagram text, do
     * not emit such a run as a fabricated paragraph. Complete sentences and
     * labels remain; only a spatially isolated, unfinished flow is removed.
     *
     * @param list<array{text: string, layout: array<string, mixed>|null}> $records
     * @return list<array{text: string, layout: array<string, mixed>|null}>
     */
    private function removeIncompletePdfComplexColumnSegments(array $records): array
    {
        $filtered = [];
        $segment = [];
        $visualPreceding = null;
        $discardedFlowLayout = null;
        $flushSegment = function (?array $following = null, ?array $afterFollowing = null) use (&$filtered, &$segment, &$visualPreceding, &$discardedFlowLayout): void {
            if ($segment === []) {
                return;
            }
            $segment = $this->trimLeadingIncompletePdfComplexSegment($segment);
            $preceding = $filtered === [] ? null : $filtered[array_key_last($filtered)];
            if ($this->pdfComplexColumnSegmentShouldBeDropped(
                $segment,
                $preceding,
                $following,
                $afterFollowing,
                $visualPreceding
            )) {
                $lastLayout = is_array($segment[array_key_last($segment)]['layout'] ?? null)
                    ? $segment[array_key_last($segment)]['layout']
                    : null;
                $completePrefix = $this->completePdfComplexSegmentPrefix($segment);
                if ($this->pdfComplexSegmentPrefixLooksComplete($completePrefix)) {
                    foreach ($completePrefix as $record) {
                        $filtered[] = $record;
                    }
                } else {
                    $completeSuffix = $this->completePdfComplexSegmentSuffix($segment);
                    if ($this->pdfComplexSegmentPrefixLooksComplete($completeSuffix)) {
                        foreach ($completeSuffix as $record) {
                            $filtered[] = $record;
                        }
                    }
                }
                $discardedFlowLayout = $this->pdfLayoutHasGeometry($lastLayout) ? $lastLayout : null;
            } else {
                foreach ($segment as $record) {
                    $filtered[] = $record;
                }
                $discardedFlowLayout = null;
            }
            $segment = [];
            $visualPreceding = null;
        };

        foreach ($records as $recordIndex => $record) {
            $afterRecord = $records[$recordIndex + 1] ?? null;
            $layout = is_array($record['layout'] ?? null) ? $record['layout'] : null;
            if (!$this->pdfLayoutHasGeometry($layout)
                || ($layout['sourceStructuredGeometry'] ?? false) !== true
                || isset($layout['sourcePdfTableGroup'])
                || ($layout['sourcePdfReferenceEntry'] ?? false) === true
                || ($layout['code'] ?? false) === true) {
                $flushSegment($record, $afterRecord);
                $filtered[] = $record;
                continue;
            }

            $last = $segment === [] ? null : $segment[array_key_last($segment)];
            if ($last === null) {
                if ($this->pdfComplexColumnRecordContinuesDroppedFlow($record, $discardedFlowLayout)) {
                    $layout['sourceInterruptedColumnRegion'] = true;
                    $record['layout'] = $layout;
                } else {
                    $discardedFlowLayout = null;
                }
            }
            $recordHasDamageEvidence = $this->pdfComplexColumnRecordHasDamageEvidence($record);
            $recoverableSentenceSuffix = ($layout['sourceSupplementalRecoverableSentenceSuffix'] ?? false) === true;
            if ($recordHasDamageEvidence
                && ($last === null
                    || ($layout['forceBlockBreakBefore'] ?? false) === true
                    || $recoverableSentenceSuffix)) {
                $record = $this->trimLeadingIncompletePdfComplexRecord($record);
            }
            $startsOrphanPunctuation = $recordHasDamageEvidence
                && preg_match('/^[,.;:\)\]\}]/u', ltrim($record['text'])) === 1;
            $forceDamagedBoundary = $last !== null
                && ($layout['forceBlockBreakBefore'] ?? false) === true
                && $recordHasDamageEvidence;
            $lastLayout = is_array($last['layout'] ?? null) ? $last['layout'] : null;
            $forcedSectionBoundary = $last !== null
                && ($lastLayout['forceBlockBreakBefore'] ?? false) === true
                && ($this->repairedLineLooksLikeSectionLabel($last['text'])
                    || $this->pdfComplexColumnRecordLooksLikeForcedDisplayHeading($last, $record));
            if ($last === null || (!$recoverableSentenceSuffix
                && !$forceDamagedBoundary
                && !$forcedSectionBoundary
                && !$this->pdfComplexColumnRecordsHaveDamagedFlowBoundary($last, $record)
                && $this->pdfComplexColumnRecordsShareFlow($last, $record)
                && !$this->pdfComplexColumnRecordsHaveSentenceBoundary($last, $record)
                && !$startsOrphanPunctuation)) {
                $segment[] = $record;
                continue;
            }
            $flushSegment($record, $afterRecord);
            $visualPreceding = $last;
            $layout = is_array($record['layout'] ?? null) ? $record['layout'] : null;
            if ($this->pdfComplexColumnRecordContinuesDroppedFlow($record, $discardedFlowLayout)) {
                $layout['sourceInterruptedColumnRegion'] = true;
                $record['layout'] = $layout;
            } else {
                $discardedFlowLayout = null;
            }
            $segment[] = $record;
        }
        $flushSegment();

        return $filtered;
    }

    /**
     * A complex page can expose a short run whose geometry has already proved
     * interrupted. When that run begins as a lower-case continuation after a
     * completed visual block and ends at a forced new block, it has no valid
     * paragraph start. Remove the entire unresolved run rather than retaining
     * a coincidental sentence from a formula, figure, or text overlay.
     *
     * @param list<array{text: string, layout: array<string, mixed>|null}> $records
     * @return list<array{text: string, layout: array<string, mixed>|null}>
     */
    private function removeIncompletePdfInterruptedFlowSegments(array $records): array
    {
        $drop = [];
        $count = count($records);
        for ($start = 0; $start < $count; $start++) {
            if (isset($drop[$start])) {
                continue;
            }
            $layout = is_array($records[$start]['layout'] ?? null) ? $records[$start]['layout'] : null;
            $text = ltrim((string) ($records[$start]['text'] ?? ''));
            $startsLowercaseContinuation = preg_match('/^[^\p{L}\p{N}]*\p{Ll}/u', $text) === 1;
            $startsShortUnfinishedLead = preg_match('/^[^\p{L}\p{N}]*\p{Lu}/u', $text) === 1
                && preg_match('/[.!?;:]\s*$/u', $text) !== 1
                && count($this->pdfLineWordTokens($text)) <= 5;
            $startsInterruptedSupplementLead = ($layout['sourceSupplementalPositioned'] ?? false) === true
                && preg_match('/[.!?;:]\s*$/u', $text) !== 1;
            if (!$this->pdfLayoutHasGeometry($layout)
                || ($layout['sourceVerifiedGeometryText'] ?? false) === true
                || ($layout['sourceInterruptedColumnRegion'] ?? false) !== true
                || (($layout['forceBlockBreakBefore'] ?? false) === true && !$startsInterruptedSupplementLead)
                || $this->lineHasPdfListBlockEvidence($text)
                || $this->lineLooksLikeUrlOnly($text)
                || (!$startsLowercaseContinuation && !$startsShortUnfinishedLead && !$startsInterruptedSupplementLead)) {
                continue;
            }

            $end = $start;
            while (isset($records[$end + 1])) {
                $nextLayout = is_array($records[$end + 1]['layout'] ?? null) ? $records[$end + 1]['layout'] : null;
                $nextText = ltrim((string) ($records[$end + 1]['text'] ?? ''));
                if (!$this->pdfLayoutHasGeometry($nextLayout)
                    || ($nextLayout['sourceInterruptedColumnRegion'] ?? false) !== true
                    || ($nextLayout['forceBlockBreakBefore'] ?? false) === true
                    || ($nextLayout['page'] ?? null) !== ($layout['page'] ?? null)
                    || ($nextLayout['sourceGeometryColumn'] ?? null) !== ($layout['sourceGeometryColumn'] ?? null)
                    || (isset($nextLayout['sourceStream'], $layout['sourceStream'])
                        && $nextLayout['sourceStream'] !== $layout['sourceStream'])
                    || $this->lineHasPdfListBlockEvidence($nextText)
                    || $this->lineLooksLikeUrlOnly($nextText)
                    || preg_match('/^[^\p{L}\p{N}]*\p{Ll}/u', $nextText) !== 1
                    || !$this->pdfInterruptedFlowRecordsShareBaselineRhythm($records[$end], $records[$end + 1])) {
                    break;
                }
                $end++;
            }

            if (!isset($records[$start - 1], $records[$end + 1])) {
                continue;
            }
            $preceding = $records[$start - 1];
            $following = $records[$end + 1];
            $precedingLayout = is_array($preceding['layout'] ?? null) ? $preceding['layout'] : null;
            $followingLayout = is_array($following['layout'] ?? null) ? $following['layout'] : null;
            $followingText = ltrim((string) ($following['text'] ?? ''));
            if (!$this->pdfLayoutHasGeometry($precedingLayout)
                || !$this->pdfLayoutHasGeometry($followingLayout)
                || ($precedingLayout['page'] ?? null) !== ($layout['page'] ?? null)
                || ($followingLayout['page'] ?? null) !== ($layout['page'] ?? null)
                || ($precedingLayout['sourceGeometryColumn'] ?? null) !== ($layout['sourceGeometryColumn'] ?? null)
                || ($followingLayout['sourceGeometryColumn'] ?? null) !== ($layout['sourceGeometryColumn'] ?? null)
                || preg_match('/[.!?;:]\s*$/u', rtrim((string) ($preceding['text'] ?? ''))) !== 1
                || ($followingLayout['forceBlockBreakBefore'] ?? false) !== true
                || preg_match('/^[^\p{L}\p{N}]*\p{Lu}/u', $followingText) !== 1) {
                continue;
            }

            for ($index = $start; $index <= $end; $index++) {
                $drop[$index] = true;
            }
            $start = $end;
        }

        if ($drop === []) {
            return $records;
        }

        return array_values(array_filter(
            $records,
            static fn (array $_record, int $index): bool => !isset($drop[$index]),
            ARRAY_FILTER_USE_BOTH
        ));
    }

    /**
     * @param array{text: string, layout: array<string, mixed>|null} $upper
     * @param array{text: string, layout: array<string, mixed>|null} $lower
     */
    private function pdfInterruptedFlowRecordsShareBaselineRhythm(array $upper, array $lower): bool
    {
        $upperLayout = is_array($upper['layout'] ?? null) ? $upper['layout'] : null;
        $lowerLayout = is_array($lower['layout'] ?? null) ? $lower['layout'] : null;
        if (!$this->pdfLayoutHasGeometry($upperLayout)
            || !$this->pdfLayoutHasGeometry($lowerLayout)) {
            return false;
        }

        $fontSize = max(1.0, (float) $upperLayout['fontSize'], (float) $lowerLayout['fontSize']);
        $step = (float) $upperLayout['y1'] - (float) $lowerLayout['y1'];

        return $step >= $fontSize * 0.30 && $step <= $fontSize * 2.2;
    }

    /**
     * A damaged source run can retain a complete sentence followed by one or
     * two stranded glyphs from the next line. When the next visual record
     * starts a new sentence in the same body column, retain the complete
     * prefix and make the visual break explicit instead of fabricating one
     * combined paragraph.
     *
     * @param list<array{text: string, layout: array<string, mixed>|null}> $records
     * @return list<array{text: string, layout: array<string, mixed>|null}>
     */
    private function trimIncompletePdfInterruptedSentenceTails(array $records): array
    {
        $count = count($records);
        for ($index = 0; $index < $count - 1; $index++) {
            $layout = is_array($records[$index]['layout'] ?? null) ? $records[$index]['layout'] : null;
            $nextLayout = is_array($records[$index + 1]['layout'] ?? null) ? $records[$index + 1]['layout'] : null;
            $text = rtrim($records[$index]['text']);
            $nextText = ltrim($records[$index + 1]['text']);
            if (!$this->pdfLayoutHasGeometry($layout)
                || !$this->pdfLayoutHasGeometry($nextLayout)
                || ($layout['sourceRecoveredPartialSupplemental'] ?? false) === true
                || ($layout['sourceInterruptedColumnRegion'] ?? false) !== true
                || ($layout['page'] ?? null) !== ($nextLayout['page'] ?? null)
                || ($layout['sourceGeometryColumn'] ?? null) !== ($nextLayout['sourceGeometryColumn'] ?? null)
                || preg_match('/[.!?]\s*$/u', $text) === 1
                || preg_match('/^[^\p{L}\p{N}]*\p{Lu}/u', $nextText) !== 1) {
                continue;
            }

            $tail = $this->lastWordToken($text);
            if ($tail === '' || $this->length($tail) > 3) {
                continue;
            }
            $fontSize = max(1.0, (float) $layout['fontSize'], (float) $nextLayout['fontSize']);
            $verticalStep = (float) $layout['y1'] - (float) $nextLayout['y1'];
            if ($verticalStep < -$fontSize * 0.5 || $verticalStep > max(20.0, $fontSize * 2.4)) {
                continue;
            }
            if (preg_match_all('/[.!?](?=\s|$)/u', $text, $matches, PREG_OFFSET_CAPTURE) === false
                || $matches[0] === []) {
                continue;
            }

            $last = $matches[0][array_key_last($matches[0])];
            $records[$index]['text'] = substr($text, 0, $last[1] + strlen($last[0]));
            $nextLayout['forceBlockBreakBefore'] = true;
            $records[$index + 1]['layout'] = $nextLayout;
        }

        return $records;
    }

    /**
     * A damaged figure can leave several positioned supplements inside one
     * source column. When that region ends in an unfinished tail before a
     * forced visual block, retain the last complete sentence rather than
     * merging the figure residue into prose.
     *
     * @param list<array{text: string, layout: array<string, mixed>|null}> $records
     * @return list<array{text: string, layout: array<string, mixed>|null}>
     */
    private function trimIncompletePdfSupplementalSegmentTails(array $records): array
    {
        $trimmed = [];
        $segment = [];
        $flush = function () use (&$trimmed, &$segment): void {
            if ($segment === []) {
                return;
            }

            $supplements = 0;
            $interrupted = false;
            foreach ($segment as $record) {
                $layout = is_array($record['layout'] ?? null) ? $record['layout'] : null;
                if ($layout === null) {
                    continue;
                }
                $supplements += ($layout['sourceSupplementalPositioned'] ?? false) === true ? 1 : 0;
                $interrupted = $interrupted || (($layout['sourceInterruptedColumnRegion'] ?? false) === true);
            }
            $lastText = rtrim((string) ($segment[array_key_last($segment)]['text'] ?? ''));
            $lastLayout = is_array($segment[array_key_last($segment)]['layout'] ?? null)
                ? $segment[array_key_last($segment)]['layout']
                : null;
            $hasInferredTail = is_array($lastLayout)
                && ($lastLayout['sourceInferredNeighborLayout'] ?? false) === true;
            if ((($interrupted && $supplements >= 3) || $hasInferredTail)
                && preg_match('/[.!?]\s*$/u', $lastText) !== 1) {
                $lastComplete = null;
                $truncatedRecord = null;
                for ($index = count($segment) - 1; $index >= 0; $index--) {
                    if (preg_match('/[.!?]\s*$/u', rtrim($segment[$index]['text'])) === 1) {
                        $lastComplete = $index;
                        break;
                    }
                    $prefix = $this->completePdfSentencePrefix($segment[$index]['text']);
                    if ($prefix !== '' && count($this->pdfLineWordTokens($prefix)) >= 5) {
                        $lastComplete = $index;
                        $truncatedRecord = array_replace($segment[$index], ['text' => $prefix]);
                        break;
                    }
                }
                if ($lastComplete !== null) {
                    foreach (array_slice($segment, 0, $lastComplete + 1) as $recordIndex => $record) {
                        if ($truncatedRecord !== null && $recordIndex === $lastComplete) {
                            $record = $truncatedRecord;
                        }
                        $trimmed[] = $record;
                    }
                    $segment = [];
                    return;
                }
            }

            foreach ($segment as $record) {
                $trimmed[] = $record;
            }
            $segment = [];
        };

        foreach ($records as $record) {
            $layout = is_array($record['layout'] ?? null) ? $record['layout'] : null;
            $previous = $segment === [] ? null : $segment[array_key_last($segment)];
            $previousLayout = is_array($previous['layout'] ?? null) ? $previous['layout'] : null;
            $startsNewSegment = $previous !== null && (
                !$this->pdfLayoutHasGeometry($layout)
                || !$this->pdfLayoutHasGeometry($previousLayout)
                || ($layout['page'] ?? null) !== ($previousLayout['page'] ?? null)
                || ($layout['sourceGeometryColumn'] ?? null) !== ($previousLayout['sourceGeometryColumn'] ?? null)
                || ($layout['forceBlockBreakBefore'] ?? false) === true
                || isset($layout['sourcePdfTableGroup'])
                || ($layout['sourcePdfReferenceEntry'] ?? false) === true
                || ($layout['code'] ?? false) === true
            );
            if ($startsNewSegment) {
                $flush();
            }
            $segment[] = $record;
        }
        $flush();

        return $trimmed;
    }

    /**
     * Some PDFs encode numbered section headings as ordinary text instead of
     * semantic headings. A forced, short line in a larger font immediately
     * before smaller body text is still a reliable visual block boundary.
     *
     * @param array{text: string, layout: array<string, mixed>|null} $record
     * @param array{text: string, layout: array<string, mixed>|null} $following
     */
    private function pdfComplexColumnRecordLooksLikeForcedDisplayHeading(array $record, array $following): bool
    {
        $layout = is_array($record['layout'] ?? null) ? $record['layout'] : null;
        $followingLayout = is_array($following['layout'] ?? null) ? $following['layout'] : null;
        $text = trim($record['text']);
        if (!$this->pdfLayoutHasGeometry($layout)
            || !$this->pdfLayoutHasGeometry($followingLayout)
            || ($layout['page'] ?? null) !== ($followingLayout['page'] ?? null)
            || ($layout['sourceGeometryColumn'] ?? null) !== ($followingLayout['sourceGeometryColumn'] ?? null)
            || ($layout['forceBlockBreakBefore'] ?? false) !== true
            || $text === ''
            || count($this->pdfLineWordTokens($text)) > 8
            || preg_match('/[.!?;:]\s*$/u', $text) === 1
            || (float) $layout['fontSize'] <= (float) $followingLayout['fontSize'] * 1.05) {
            return false;
        }

        return preg_match('/^(?:\p{N}+(?:\.\p{N}+)*\.?\s+|[^\p{L}\p{N}]*\p{Lu})/u', $text) === 1;
    }

    /**
     * References are often emitted in source order even when italic titles or
     * other font subsets fail to decode. Keep entries whose source and visual
     * geometry agree, but omit an entry once a missing visual run leaves a
     * continuation stranded in the middle of its column. This is deliberately
     * structural: titles, authors, and language are never inspected.
     *
     * @param list<array{text: string, layout: array<string, mixed>|null}> $records
     * @return list<array{text: string, layout: array<string, mixed>|null}>
     */
    private function removeLowConfidencePdfReferenceEntries(array $records): array
    {
        $referenceCount = 0;
        foreach ($records as $record) {
            if ($this->lineLooksLikePdfReferenceEntry($record['text'])) {
                $referenceCount++;
            }
        }
        if ($referenceCount < 3) {
            return $records;
        }

        $filtered = [];
        $entry = [];
        $flushEntry = function () use (&$filtered, &$entry): void {
            if ($entry !== [] && !$this->pdfReferenceEntryHasUnresolvedVisualFragment($entry)) {
                foreach ($entry as $record) {
                    $filtered[] = $record;
                }
            }
            $entry = [];
        };

        foreach ($records as $record) {
            if ($this->lineLooksLikePdfReferenceEntry($record['text'])) {
                $flushEntry();
                $entry[] = $record;
                continue;
            }
            if ($entry !== []) {
                $entry[] = $record;
                continue;
            }
            $filtered[] = $record;
        }
        $flushEntry();

        return $filtered;
    }

    /**
     * @param list<array{text: string, layout: array<string, mixed>|null}> $entry
     */
    private function pdfReferenceEntryHasUnresolvedVisualFragment(array $entry): bool
    {
        if ($entry === []) {
            return false;
        }

        $last = rtrim($entry[array_key_last($entry)]['text']);
        if ($last === '' || preg_match('/[-\x{2010}-\x{2015}]\s*$/u', $last) === 1) {
            return true;
        }

        $leftEdge = null;
        $previous = null;
        foreach ($entry as $record) {
            $text = ltrim($record['text']);
            if ($text !== '' && preg_match('/^[,;:]/u', $text) === 1) {
                return true;
            }

            $layout = $record['layout'];
            if ($previous !== null
                && preg_match('/[-\x{2010}-\x{2015}]\s*$/u', rtrim($previous['text'])) === 1
                && preg_match('/^[^\p{L}\p{N}]*\p{Lu}/u', $text) === 1) {
                return true;
            }
            if (!$this->pdfLayoutHasGeometry($layout)) {
                $previous = $record;
                continue;
            }

            $leftEdge = $leftEdge === null ? (float) $layout['x1'] : min($leftEdge, (float) $layout['x1']);
            if ($previous !== null
                && $this->pdfLayoutHasGeometry($previous['layout'])
                && ($previous['layout']['page'] ?? null) === ($layout['page'] ?? null)
                && !$this->lineLooksLikeUrlOnly($text)
                && preg_match('/[-\x{2010}-\x{2015}]\s*$/u', rtrim($previous['text'])) !== 1) {
                $fontSize = max(1.0, (float) $layout['fontSize'], (float) $previous['layout']['fontSize']);
                if ((float) $layout['x1'] > $leftEdge + max(32.0, $fontSize * 4.0)) {
                    return true;
                }
            }
            $previous = $record;
        }

        return false;
    }

    /**
     * Once an incomplete page-end flow has been removed, its lower-case tail
     * can survive at the opening of the next page. A complete retained
     * sentence before the page break proves that this tail cannot belong to
     * the preceding block, so omit it rather than emit a fabricated sentence.
     *
     * @param list<array{text: string, layout: array<string, mixed>|null}> $records
     * @return list<array{text: string, layout: array<string, mixed>|null}>
     */
    private function removeOrphanedPdfPageOpeningFragments(array $records): array
    {
        $filtered = [];
        $previous = null;
        $droppingPage = null;
        foreach ($records as $record) {
            $layout = $record['layout'];
            $page = is_array($layout) && isset($layout['page']) ? (int) $layout['page'] : null;
            $previousPage = is_array($previous['layout'] ?? null) && isset($previous['layout']['page'])
                ? (int) $previous['layout']['page']
                : null;
            $text = ltrim($record['text']);
            $startsContinuation = preg_match('/^(?:[^\p{L}\p{N}]*\p{Ll}|[,;:\)\]\}])/u', $text) === 1;
            $startsFormulaAssignment = $this->sourcePdfTextContainsCompactAssignmentLabel($text);
            if ($page !== null
                && $page !== $previousPage
                && $previous !== null
                && preg_match('/[.!?]\s*$/u', rtrim($previous['text'])) === 1
                && $startsContinuation
                && !$startsFormulaAssignment
                && !$this->lineHasPdfListBlockEvidence($text)
                && !$this->lineLooksLikeUrlOnly($text)) {
                $droppingPage = $page;
            }

            if ($page !== null
                && $droppingPage === $page
                && $startsContinuation
                && !$this->lineHasPdfListBlockEvidence($text)
                && !$this->lineLooksLikeUrlOnly($text)) {
                continue;
            }
            if ($page !== null && $droppingPage === $page) {
                $droppingPage = null;
            }

            $filtered[] = $record;
            $previous = $record;
        }

        return $filtered;
    }

    /**
     * @param list<array{text: string, layout: array<string, mixed>|null}> $records
     */
    private function pdfComplexSegmentPrefixLooksComplete(array $records): bool
    {
        if ($records === []) {
            return false;
        }

        $first = trim($records[0]['text']);
        $last = trim($records[array_key_last($records)]['text']);

        return preg_match('/^[^\p{L}\p{N}]*(?:\p{Lu}|\p{N})/u', $first) === 1
            && count($this->pdfLineWordTokens(implode(' ', array_column($records, 'text')))) >= 5
            && preg_match('/[.!?]\s*$/u', $last) === 1;
    }

    /**
     * Keep the recoverable sentence prefix of a damaged flow. This is useful
     * when a missing visual run occurs after one or more complete sentences:
     * emitting the prefix is more faithful than either joining the missing
     * tail or discarding the entire paragraph.
     *
     * @param list<array{text: string, layout: array<string, mixed>|null}> $records
     * @return list<array{text: string, layout: array<string, mixed>|null}>
     */
    private function completePdfComplexSegmentPrefix(array $records): array
    {
        $records = $this->pdfComplexSegmentBeforeVisualCollision($records);
        for ($index = count($records) - 1; $index >= 0; $index--) {
            $text = $records[$index]['text'];
            if (preg_match_all('/[.!?](?=\s|$)/u', $text, $matches, PREG_OFFSET_CAPTURE) !== false
                && $matches[0] !== []) {
                $last = $matches[0][array_key_last($matches[0])];
                $records[$index]['text'] = substr($text, 0, $last[1] + strlen($last[0]));

                return array_slice($records, 0, $index + 1);
            }
        }

        return [];
    }

    /**
     * Source text from a malformed figure can contain two incompatible runs
     * on the same baseline. Once that collision appears, later punctuation is
     * not evidence that the preceding body flow is complete. Preserve only
     * the records before the collision for sentence-prefix recovery.
     *
     * @param list<array{text: string, layout: array<string, mixed>|null}> $records
     * @return list<array{text: string, layout: array<string, mixed>|null}>
     */
    private function pdfComplexSegmentBeforeVisualCollision(array $records): array
    {
        for ($index = 1, $count = count($records); $index < $count; $index++) {
            $previousLayout = is_array($records[$index - 1]['layout'] ?? null)
                ? $records[$index - 1]['layout']
                : null;
            $layout = is_array($records[$index]['layout'] ?? null)
                ? $records[$index]['layout']
                : null;
            if (!$this->pdfLayoutHasGeometry($previousLayout)
                || !$this->pdfLayoutHasGeometry($layout)
                || ($previousLayout['page'] ?? null) !== ($layout['page'] ?? null)
                || ($previousLayout['sourceGeometryColumn'] ?? null) !== ($layout['sourceGeometryColumn'] ?? null)) {
                continue;
            }

            $fontSize = max(1.0, (float) $previousLayout['fontSize'], (float) $layout['fontSize']);
            if (abs((float) $previousLayout['y1'] - (float) $layout['y1']) <= max(2.0, $fontSize * 0.45)
                && abs((float) $previousLayout['x1'] - (float) $layout['x1']) <= max(12.0, $fontSize * 1.25)) {
                return array_slice($records, 0, $index);
            }
        }

        return $records;
    }

    /**
     * Preserve complete sentences that follow an observable missing prefix.
     * The segment is already known to be unsafe, so this requires a sentence
     * boundary followed by a capitalized sentence start and trims any final
     * unresolved tail. It relies only on punctuation and visual damage marks,
     * not document language or vocabulary.
     *
     * @param list<array{text: string, layout: array<string, mixed>|null}> $records
     * @return list<array{text: string, layout: array<string, mixed>|null}>
     */
    private function completePdfComplexSegmentSuffix(array $records): array
    {
        if ($records === []) {
            return [];
        }

        $first = ltrim($records[0]['text']);
        if (preg_match('/^(?:[^\p{L}\p{N}]*\p{Ll}|[,.;:\)\]\}])/u', $first) !== 1) {
            return [];
        }

        foreach ($records as $index => $record) {
            if (preg_match('/[.!?]\s*((?:(?:[\(\[]\s*)?(?:\p{N}+\s*[\)\]]\s*)?)?\p{Lu}[\s\S]*)$/u', $record['text'], $matches) !== 1) {
                continue;
            }

            $suffix = array_slice($records, $index);
            $suffix[0]['text'] = $matches[1];
            $suffix = $this->completePdfComplexSegmentPrefix($suffix);
            if (!$this->pdfComplexSegmentPrefixLooksComplete($suffix)) {
                continue;
            }

            return $suffix;
        }

        return [];
    }

    /**
     * A damaged visual line can still contain a complete sentence after its
     * missing prefix. Split at that punctuation boundary before assessing the
     * surrounding geometric flow, so a broken lead-in does not discard the
     * independently complete sentence that follows.
     *
     * @param array{text: string, layout: array<string, mixed>|null} $record
     * @return array{text: string, layout: array<string, mixed>|null}
     */
    private function trimLeadingIncompletePdfComplexRecord(array $record): array
    {
        $text = ltrim($record['text']);
        $layout = is_array($record['layout'] ?? null) ? $record['layout'] : [];
        $hasRecoverableSentenceSuffix = ($layout['sourceSupplementalRecoverableSentenceSuffix'] ?? false) === true;
        if ((preg_match('/^[^\p{L}\p{N}]*\p{Ll}/u', $text) === 1
                || preg_match('/^[,.;:]\s+/u', $text) === 1
                || $hasRecoverableSentenceSuffix)
            && preg_match('/[.!?]\s*((?:(?:[\(\[]\s*)?(?:\p{N}+\s*[\)\]]\s*)?)?\p{Lu}[\s\S]*)$/u', $text, $matches) === 1) {
            if (count($this->pdfLineWordTokens($matches[1])) < 5) {
                return $record;
            }
            $record['text'] = $matches[1];
        }

        return $record;
    }

    /**
     * @param array{text: string, layout: array<string, mixed>|null} $record
     */
    private function pdfComplexColumnRecordHasDamageEvidence(array $record): bool
    {
        $layout = is_array($record['layout'] ?? null) ? $record['layout'] : [];
        if (($layout['sourceVerifiedGeometryText'] ?? false) === true) {
            return false;
        }
        if (($layout['sourceInterruptedColumnRegion'] ?? false) === true
            || ($layout['sourceMinorFontFlow'] ?? false) === true) {
            return true;
        }

        return ($layout['forceBlockBreakBefore'] ?? false) === true
            && preg_match('/^(?:[,.;:\)\]\}]|\(|[^\p{L}\p{N}]*\p{Ll})/u', ltrim($record['text'])) === 1;
    }

    /**
     * Keep a segment unless its own geometry makes the missing content
     * observable. A page with a chart or a figure may still contain ordinary
     * body prose, so a page-wide complexity marker alone cannot justify
     * deleting text.
     *
     * @param list<array{text: string, layout: array<string, mixed>|null}> $records
     * @param array{text: string, layout: array<string, mixed>|null}|null $preceding
     * @param array{text: string, layout: array<string, mixed>|null}|null $following
     * @param array{text: string, layout: array<string, mixed>|null}|null $afterFollowing
     * @param array{text: string, layout: array<string, mixed>|null}|null $visualPreceding
     */
    private function pdfComplexColumnSegmentShouldBeDropped(
        array $records,
        ?array $preceding,
        ?array $following,
        ?array $afterFollowing = null,
        ?array $visualPreceding = null
    ): bool
    {
        foreach ($records as $record) {
            if (($record['layout']['sourceCrossColumnContinuationTail'] ?? false) === true) {
                return false;
            }
        }
        if ($this->pdfComplexColumnSegmentIsIsolatedInterruptedSupplement($records, $following)) {
            return true;
        }
        if ($this->pdfComplexColumnSegmentIsFollowedByRecoverableSentenceSuffix($records, $following)) {
            return true;
        }
        if ($this->pdfComplexColumnSegmentHasInterruptedVisualCollision($records)) {
            return true;
        }
        if ($this->pdfComplexColumnSegmentHasDetachedInterruptedStart(
            $records,
            $visualPreceding ?? $preceding
        )) {
            return true;
        }
        if ($this->pdfComplexColumnSegmentHasIsolatedContinuationFragment($records, $preceding, $following)
            || $this->pdfComplexColumnSegmentHasIsolatedContinuationFragment($records, $visualPreceding, $following)) {
            return true;
        }

        if (!$this->pdfComplexColumnSegmentLooksIncomplete($records)) {
            return false;
        }

        if ($this->pdfComplexColumnSegmentEndsAtForcedInterruptedHyphen($records, $following)) {
            return true;
        }

        if ($this->pdfComplexColumnSegmentIsIsolatedUnresolvedForcedLine($records, $following)) {
            return true;
        }

        if ($this->pdfComplexColumnSegmentHasInterruptedLeadingFragment(
            $records,
            $visualPreceding ?? $preceding
        )
            || $this->pdfComplexColumnSegmentIsFollowedByInterruptedSuffix($records, $following)) {
            return true;
        }

        $hasComplexPage = false;
        foreach ($records as $record) {
            $layout = is_array($record['layout'] ?? null) ? $record['layout'] : [];
            $hasComplexPage = $hasComplexPage
                || ($layout['sourceComplexGeometryPage'] ?? false) === true
                || ($layout['sourceDetachedDiagramEvidencePage'] ?? false) === true;
        }

        $endsAtUnresolvedBoundary = $this->pdfComplexColumnSegmentEndsAtUnresolvedVisualBoundary(
            $records,
            $following,
            $afterFollowing
        );
        if (count($records) >= 2
            && $endsAtUnresolvedBoundary
            && ($hasComplexPage || $this->pdfComplexColumnSegmentHasForcedSameColumnBoundary(
                $records,
                $following,
                $afterFollowing
            ))) {
            return true;
        }

        if ($this->pdfComplexColumnSegmentIsVisuallyDetachedComplexFragment($records, $preceding, $following)) {
            return true;
        }
        return $this->pdfComplexColumnSegmentIsFollowedByDamagedGap($records, $following);
    }

    /**
     * A normal wrapped paragraph advances by at least one line height. When
     * an explicitly interrupted flow has two records in the same body column
     * on one baseline, they are incompatible visual layers rather than a
     * readable sentence. Formula subscripts and diagram labels commonly have
     * this shape.
     *
     * @param list<array{text: string, layout: array<string, mixed>|null}> $records
     */
    private function pdfComplexColumnSegmentHasInterruptedVisualCollision(array $records): bool
    {
        $interrupted = false;
        foreach ($records as $record) {
            if (($record['layout']['sourceInterruptedColumnRegion'] ?? false) === true) {
                $interrupted = true;
                break;
            }
        }
        if (!$interrupted || count($records) < 2) {
            return false;
        }

        return count($this->pdfComplexSegmentBeforeVisualCollision($records)) < count($records);
    }

    /**
     * A visual line with a recoverable sentence suffix proves that the run
     * immediately before it is a display or formula prefix, not ordinary
     * prose. A colon-ended predecessor has no independently complete text to
     * merge into that suffix; retain an earlier full sentence if present and
     * start the recovered suffix as its own flow.
     *
     * @param list<array{text: string, layout: array<string, mixed>|null}> $records
     * @param array{text: string, layout: array<string, mixed>|null}|null $following
     */
    private function pdfComplexColumnSegmentIsFollowedByRecoverableSentenceSuffix(
        array $records,
        ?array $following
    ): bool {
        if ($records === [] || $following === null) {
            return false;
        }

        $last = $records[array_key_last($records)];
        $layout = is_array($last['layout'] ?? null) ? $last['layout'] : null;
        $followingLayout = is_array($following['layout'] ?? null) ? $following['layout'] : null;
        if (($followingLayout['sourceSupplementalRecoverableSentenceSuffix'] ?? false) !== true
            || !$this->pdfLayoutHasGeometry($layout)
            || !$this->pdfLayoutHasGeometry($followingLayout)
            || ($layout['page'] ?? null) !== ($followingLayout['page'] ?? null)
            || ($layout['sourceGeometryColumn'] ?? null) !== ($followingLayout['sourceGeometryColumn'] ?? null)
            || preg_match('/:\s*$/u', rtrim($last['text'])) !== 1) {
            return false;
        }

        $fontSize = max(1.0, (float) $layout['fontSize'], (float) $followingLayout['fontSize']);

        return (float) $layout['y1'] - (float) $followingLayout['y1'] <= max(24.0, $fontSize * 3.0);
    }

    /**
     * A short positioned fallback can start at the body edge even when its
     * missing formula or diagram prefix makes it unsafe prose. If the next
     * same-column record is explicitly interrupted and begins as a
     * continuation, discard the isolated fallback rather than promoting it to
     * a heading or a paragraph.
     *
     * @param list<array{text: string, layout: array<string, mixed>|null}> $records
     * @param array{text: string, layout: array<string, mixed>|null}|null $following
     */
    private function pdfComplexColumnSegmentIsIsolatedInterruptedSupplement(
        array $records,
        ?array $following
    ): bool {
        if (count($records) !== 1 || $following === null) {
            return false;
        }

        $record = $records[0];
        $layout = is_array($record['layout'] ?? null) ? $record['layout'] : null;
        $followingLayout = is_array($following['layout'] ?? null) ? $following['layout'] : null;
        $text = trim($record['text']);
        $followingText = ltrim($following['text']);
        if (!$this->pdfLayoutHasGeometry($layout)
            || !$this->pdfLayoutHasGeometry($followingLayout)
            || ($layout['sourceSupplementalPositioned'] ?? false) !== true
            || ($layout['sourceInterruptedColumnRegion'] ?? false) !== true
            || ($layout['forceBlockBreakBefore'] ?? false) !== true
            || ($layout['page'] ?? null) !== ($followingLayout['page'] ?? null)
            || ($layout['sourceGeometryColumn'] ?? null) !== ($followingLayout['sourceGeometryColumn'] ?? null)
            || $this->lineHasPdfListBlockEvidence($text)
            || $this->lineLooksLikeUrlOnly($text)
            || preg_match('/[.!?]\s*$/u', $text) === 1
            || (($followingLayout['sourceInterruptedColumnRegion'] ?? false) !== true)
            || preg_match('/^(?:[^\p{L}\p{N}]*\p{Ll}|[\)\]\},;:])/u', $followingText) !== 1) {
            return false;
        }

        $fontSize = max(1.0, (float) $layout['fontSize'], (float) $followingLayout['fontSize']);

        return (float) $layout['y1'] - (float) $followingLayout['y1'] <= max(24.0, $fontSize * 3.0);
    }

    /**
     * A punctuated or lower-case line at a forced boundary normally belongs
     * to the end of an omitted visual run. The interruption marker comes from
     * geometry, so this rejects the entire malformed run without relying on
     * vocabulary or a document-specific phrase.
     *
     * @param list<array{text: string, layout: array<string, mixed>|null}> $records
     * @param array{text: string, layout: array<string, mixed>|null}|null $preceding
     */
    private function pdfComplexColumnSegmentHasInterruptedLeadingFragment(array $records, ?array $preceding = null): bool
    {
        if ($records === []) {
            return false;
        }

        $first = $records[0];
        $layout = is_array($first['layout'] ?? null) ? $first['layout'] : [];
        $text = ltrim($first['text']);

        if (($layout['forceBlockBreakBefore'] ?? false) !== true
            || preg_match('/^(?:[,.;:\)\]\}]|[^\p{L}\p{N}]*\p{Ll})/u', $text) !== 1) {
            return false;
        }
        if (($layout['sourceInterruptedColumnRegion'] ?? false) === true) {
            return true;
        }

        $precedingLayout = is_array($preceding['layout'] ?? null) ? $preceding['layout'] : null;
        if (!$this->pdfLayoutHasGeometry($layout)
            || !$this->pdfLayoutHasGeometry($precedingLayout)
            || ($layout['page'] ?? null) !== ($precedingLayout['page'] ?? null)
            || ($layout['sourceGeometryColumn'] ?? null) !== ($precedingLayout['sourceGeometryColumn'] ?? null)) {
            return false;
        }

        $fontSize = max(1.0, (float) $layout['fontSize'], (float) $precedingLayout['fontSize']);

        return (float) $precedingLayout['y1'] - (float) $layout['y1'] > max(18.0, $fontSize * 1.8)
            && abs((float) $layout['x1'] - (float) $precedingLayout['x1']) >= max(48.0, $fontSize * 5.0);
    }

    /**
     * A one-line interrupted run followed immediately by another forced,
     * interrupted lower-case or punctuated suffix has no complete reading
     * order. Treat both starts as fragments rather than turning either into
     * a paragraph.
     *
     * @param list<array{text: string, layout: array<string, mixed>|null}> $records
     * @param array{text: string, layout: array<string, mixed>|null}|null $following
     */
    private function pdfComplexColumnSegmentIsFollowedByInterruptedSuffix(array $records, ?array $following): bool
    {
        if (count($records) !== 1 || $following === null) {
            return false;
        }

        $record = $records[0];
        $layout = is_array($record['layout'] ?? null) ? $record['layout'] : null;
        $followingLayout = is_array($following['layout'] ?? null) ? $following['layout'] : null;
        $text = rtrim($record['text']);
        $followingText = ltrim($following['text']);
        if (!$this->pdfLayoutHasGeometry($layout)
            || !$this->pdfLayoutHasGeometry($followingLayout)
            || ($layout['page'] ?? null) !== ($followingLayout['page'] ?? null)
            || ($layout['sourceGeometryColumn'] ?? null) !== ($followingLayout['sourceGeometryColumn'] ?? null)
            || ($layout['forceBlockBreakBefore'] ?? false) !== true
            || ($followingLayout['forceBlockBreakBefore'] ?? false) !== true
            || preg_match('/[.!?;:]\s*$/u', $text) === 1
            || preg_match('/^(?:[,.;:\)\]\}]|[^\p{L}\p{N}]*\p{Ll})/u', $followingText) !== 1) {
            return false;
        }

        $fontSize = max(1.0, (float) $layout['fontSize'], (float) $followingLayout['fontSize']);
        $hasDamageEvidence = ($layout['sourceInterruptedColumnRegion'] ?? false) === true
            || ($followingLayout['sourceInterruptedColumnRegion'] ?? false) === true
            || abs((float) $layout['x1'] - (float) $followingLayout['x1']) >= max(32.0, $fontSize * 3.5);
        if (!$hasDamageEvidence) {
            return false;
        }
        $verticalGap = (float) $layout['y1'] - (float) $followingLayout['y2'];

        return $verticalGap <= max(24.0, $fontSize * 3.0);
    }

    /**
     * A line-end hyphen normally continues directly at the body edge. When
     * its next source record is forcibly separated, marked as interrupted,
     * and shifted deep into the same column, the missing visual run is
     * observable. Keep a complete sentence prefix rather than inventing a
     * hyphenated word across that gap.
     *
     * @param list<array{text: string, layout: array<string, mixed>|null}> $records
     * @param array{text: string, layout: array<string, mixed>|null}|null $following
     */
    private function pdfComplexColumnSegmentEndsAtForcedInterruptedHyphen(array $records, ?array $following): bool
    {
        if ($records === [] || $following === null) {
            return false;
        }

        $last = $records[array_key_last($records)];
        $layout = is_array($last['layout'] ?? null) ? $last['layout'] : null;
        $followingLayout = is_array($following['layout'] ?? null) ? $following['layout'] : null;
        if (!$this->pdfLayoutHasGeometry($layout)
            || !$this->pdfLayoutHasGeometry($followingLayout)
            || ($layout['page'] ?? null) !== ($followingLayout['page'] ?? null)
            || ($layout['sourceGeometryColumn'] ?? null) !== ($followingLayout['sourceGeometryColumn'] ?? null)
            || preg_match('/[-\x{2010}-\x{2015}]\s*$/u', rtrim($last['text'])) !== 1
            || ($layout['sourceInterruptedColumnRegion'] ?? false) !== true
            || ($followingLayout['forceBlockBreakBefore'] ?? false) !== true
            || !$this->pdfComplexColumnRecordHasDamageEvidence($following)) {
            return false;
        }

        $fontSize = max(1.0, (float) $layout['fontSize'], (float) $followingLayout['fontSize']);

        return abs((float) $followingLayout['x1'] - (float) $layout['x1']) >= max(24.0, $fontSize * 2.4);
    }

    /**
     * A complex figure may leave one indented source line between otherwise
     * complete body blocks. Its missing bullet, prefix, or continuation means
     * it cannot safely become prose. The evidence is purely geometric: the
     * line is isolated, begins after a completed body sentence, is indented,
     * and is followed by another detached visual region.
     *
     * @param list<array{text: string, layout: array<string, mixed>|null}> $records
     * @param array{text: string, layout: array<string, mixed>|null}|null $preceding
     * @param array{text: string, layout: array<string, mixed>|null}|null $following
     */
    private function pdfComplexColumnSegmentIsVisuallyDetachedComplexFragment(
        array $records,
        ?array $preceding,
        ?array $following
    ): bool {
        if (count($records) !== 1) {
            return false;
        }

        $record = $records[0];
        $layout = is_array($record['layout'] ?? null) ? $record['layout'] : null;
        $text = ltrim($record['text']);
        if (!$this->pdfLayoutHasGeometry($layout)
            || (($layout['sourceComplexGeometryPage'] ?? false) !== true
                && ($layout['sourceDetachedDiagramEvidencePage'] ?? false) !== true)
            || $text === ''
            || preg_match('/[.!?;:]\s*$/u', rtrim($text)) === 1) {
            return false;
        }

        if (preg_match('/^[,.;:\)\]\}]/u', $text) === 1) {
            return true;
        }
        if (($layout['forceBlockBreakBefore'] ?? false) !== true || $preceding === null || $following === null) {
            return false;
        }

        $precedingLayout = is_array($preceding['layout'] ?? null) ? $preceding['layout'] : null;
        $followingLayout = is_array($following['layout'] ?? null) ? $following['layout'] : null;
        if (!$this->pdfLayoutHasGeometry($precedingLayout)
            || !$this->pdfLayoutHasGeometry($followingLayout)
            || ($precedingLayout['page'] ?? null) !== ($layout['page'] ?? null)
            || ($followingLayout['page'] ?? null) !== ($layout['page'] ?? null)
            || ($precedingLayout['sourceGeometryColumn'] ?? null) !== ($layout['sourceGeometryColumn'] ?? null)
            || ($followingLayout['sourceGeometryColumn'] ?? null) !== ($layout['sourceGeometryColumn'] ?? null)
            || preg_match('/[.!?;:]\s*$/u', rtrim($preceding['text'])) !== 1
            || preg_match('/^[^\p{L}\p{N}]*\p{Lu}/u', $text) !== 1
            || preg_match('/^[^\p{L}\p{N}]*\p{Lu}/u', ltrim($following['text'])) !== 1
            || ($followingLayout['forceBlockBreakBefore'] ?? false) !== true) {
            return false;
        }

        $fontSize = max(1.0, (float) $precedingLayout['fontSize'], (float) $layout['fontSize']);

        return (float) $layout['x1'] - (float) $precedingLayout['x1'] >= max(7.0, $fontSize * 0.80);
    }

    /**
     * A source line can be stranded between two visual regions even on a
     * page without a detected figure. The interrupted marker, large gap from
     * the preceding body flow, and a forced block boundary together prove a
     * missing run. A lower-case suffix with the same displaced shape is the
     * trailing half of that fragment, not an independent paragraph.
     *
     * @param list<array{text: string, layout: array<string, mixed>|null}> $records
     * @param array{text: string, layout: array<string, mixed>|null}|null $preceding
     */
    private function pdfComplexColumnSegmentHasDetachedInterruptedStart(array $records, ?array $preceding): bool
    {
        if (count($records) !== 1 || $preceding === null) {
            return false;
        }

        $record = $records[0];
        $layout = is_array($record['layout'] ?? null) ? $record['layout'] : null;
        $precedingLayout = is_array($preceding['layout'] ?? null) ? $preceding['layout'] : null;
        $text = ltrim($record['text']);
        if (!$this->pdfLayoutHasGeometry($layout)
            || !$this->pdfLayoutHasGeometry($precedingLayout)
            || ($layout['page'] ?? null) !== ($precedingLayout['page'] ?? null)
            || ($layout['sourceGeometryColumn'] ?? null) !== ($precedingLayout['sourceGeometryColumn'] ?? null)) {
            return false;
        }

        $fontSize = max(1.0, (float) $layout['fontSize'], (float) $precedingLayout['fontSize']);
        $gap = (float) $precedingLayout['y1'] - (float) $layout['y2'];
        if (($layout['sourceInterruptedColumnRegion'] ?? false) === true
            && $gap > max(22.0, $fontSize * 3.3)) {
            return true;
        }

        return ($layout['forceBlockBreakBefore'] ?? false) === true
            && preg_match('/^[,.;:\)\]\}]|^[^\p{L}\p{N}]*\p{Ll}/u', $text) === 1
            && abs((float) $layout['x1'] - (float) $precedingLayout['x1']) >= max(24.0, $fontSize * 2.4);
    }

    /**
     * A lower-case or punctuation-led record after a large empty band cannot
     * safely begin a new prose block. If it has no nearby continuation in the
     * same visual column, the omitted material is observable from geometry;
     * retain a later complete sentence if one exists, otherwise omit it.
     *
     * @param list<array{text: string, layout: array<string, mixed>|null}> $records
     * @param array{text: string, layout: array<string, mixed>|null}|null $preceding
     * @param array{text: string, layout: array<string, mixed>|null}|null $following
     */
    private function pdfComplexColumnSegmentHasIsolatedContinuationFragment(
        array $records,
        ?array $preceding,
        ?array $following
    ): bool {
        if (count($records) !== 1 || $preceding === null) {
            return false;
        }

        $record = $records[0];
        $layout = is_array($record['layout'] ?? null) ? $record['layout'] : null;
        $precedingLayout = is_array($preceding['layout'] ?? null) ? $preceding['layout'] : null;
        $text = ltrim($record['text']);
        if (!$this->pdfLayoutHasGeometry($layout)
            || !$this->pdfLayoutHasGeometry($precedingLayout)
            || ($layout['sourceStructuredGeometry'] ?? false) !== true
            || ($layout['page'] ?? null) !== ($precedingLayout['page'] ?? null)
            || ($layout['sourceGeometryColumn'] ?? null) !== ($precedingLayout['sourceGeometryColumn'] ?? null)
            || $this->lineHasPdfListBlockEvidence($text)
            || $this->lineLooksLikeUrlOnly($text)
            || preg_match('/^(?:[^\p{L}\p{N}]*\p{Ll}|[,.;:\)\]\}])/u', $text) !== 1) {
            return false;
        }

        $fontSize = max(1.0, (float) $layout['fontSize'], (float) $precedingLayout['fontSize']);
        $verticalGap = (float) $precedingLayout['y1'] - (float) $layout['y2'];
        if ($verticalGap <= max(18.0, $fontSize * 2.2)) {
            return false;
        }

        if ($following === null) {
            return true;
        }

        $followingLayout = is_array($following['layout'] ?? null) ? $following['layout'] : null;
        return !$this->pdfLayoutHasGeometry($followingLayout)
            || ($followingLayout['page'] ?? null) !== ($layout['page'] ?? null)
            || ($followingLayout['sourceGeometryColumn'] ?? null) !== ($layout['sourceGeometryColumn'] ?? null)
            || !$this->pdfComplexColumnRecordsShareFlow($record, $following);
    }

    /**
     * A lone unfinished body line followed by a distant forced block cannot be
     * a wrapped continuation. This removes clipped prose tails while keeping
     * headings, lists, and ordinary paragraph boundaries intact.
     *
     * @param list<array{text: string, layout: array<string, mixed>|null}> $records
     * @param array{text: string, layout: array<string, mixed>|null}|null $following
     */
    private function pdfComplexColumnSegmentIsIsolatedUnresolvedForcedLine(array $records, ?array $following): bool
    {
        if (count($records) !== 1 || $following === null) {
            return false;
        }

        $record = $records[0];
        $layout = is_array($record['layout'] ?? null) ? $record['layout'] : null;
        $followingLayout = is_array($following['layout'] ?? null) ? $following['layout'] : null;
        $text = trim($record['text']);
        $followingText = ltrim($following['text']);
        if (!$this->pdfLayoutHasGeometry($layout)
            || !$this->pdfLayoutHasGeometry($followingLayout)
            || ($layout['sourceStructuredGeometry'] ?? false) !== true
            || ($layout['page'] ?? null) !== ($followingLayout['page'] ?? null)
            || ($layout['sourceGeometryColumn'] ?? null) !== ($followingLayout['sourceGeometryColumn'] ?? null)
            || ($layout['forceBlockBreakBefore'] ?? false) !== true
            || ($followingLayout['forceBlockBreakBefore'] ?? false) !== true
            || $this->lineHasPdfListBlockEvidence($text)
            || $this->lineLooksLikeUrlOnly($text)
            || $this->repairedLineLooksLikeSectionLabel($text)
            || $this->lineLooksLikePdfAllCapsDisplayText($text)
            || count($this->pdfLineWordTokens($text)) < 8
            || preg_match('/[.!?;:]\s*$/u', $text) === 1
            || preg_match('/[-\x{2010}-\x{2015}]\s*$/u', $text) === 1
            || preg_match('/^[^\p{L}\p{N}]*\p{Lu}/u', $followingText) !== 1) {
            return false;
        }

        $fontSize = max(1.0, (float) $layout['fontSize'], (float) $followingLayout['fontSize']);

        return (float) $layout['y1'] - (float) $followingLayout['y1'] > max(24.0, $fontSize * 2.6);
    }

    /**
     * @param array{text: string, layout: array<string, mixed>|null} $record
     * @param array<string, mixed>|null $discardedLayout
     */
    private function pdfComplexColumnRecordContinuesDroppedFlow(array $record, ?array $discardedLayout): bool
    {
        $layout = is_array($record['layout'] ?? null) ? $record['layout'] : null;
        $text = ltrim($record['text']);
        $continuesForcedInterruption = is_array($discardedLayout)
            && ($discardedLayout['sourceInterruptedColumnRegion'] ?? false) === true
            && ($discardedLayout['forceBlockBreakBefore'] ?? false) === true;
        if ($this->pdfLayoutHasGeometry($layout)
            && $this->pdfLayoutHasGeometry($discardedLayout)
            && $continuesForcedInterruption
            && ($layout['page'] ?? null) === ($discardedLayout['page'] ?? null)
            && ($layout['sourceGeometryColumn'] ?? null) === ($discardedLayout['sourceGeometryColumn'] ?? null)
            && !$this->lineHasPdfListBlockEvidence($text)
            && !$this->lineLooksLikeUrlOnly($text)
            && preg_match('/^[^\p{L}\p{N}]*\p{Lu}/u', $text) === 1) {
            $fontSize = max(1.0, (float) $layout['fontSize'], (float) $discardedLayout['fontSize']);
            if (abs((float) $layout['y1'] - (float) $discardedLayout['y1']) <= max(3.0, $fontSize * 0.45)
                && abs((float) $layout['x1'] - (float) $discardedLayout['x1']) <= max(12.0, $fontSize * 1.25)) {
                return true;
            }
        }
        if (!$this->pdfLayoutHasGeometry($layout)
            || !$this->pdfLayoutHasGeometry($discardedLayout)
            || ($layout['page'] ?? null) !== ($discardedLayout['page'] ?? null)
            || ($layout['sourceGeometryColumn'] ?? null) !== ($discardedLayout['sourceGeometryColumn'] ?? null)
            || (($layout['forceBlockBreakBefore'] ?? false) !== true && !$continuesForcedInterruption)
            || $this->lineHasPdfListBlockEvidence($text)
            || $this->lineLooksLikeUrlOnly($text)
            || preg_match('/^(?:[^\p{L}\p{N}]*\p{Ll}|[,.;:\)\]\}])/u', $text) !== 1) {
            return false;
        }

        $fontSize = max(1.0, (float) $layout['fontSize'], (float) $discardedLayout['fontSize']);
        $step = (float) $discardedLayout['y1'] - (float) $layout['y1'];

        return $step >= $fontSize * 0.30 && $step <= max(24.0, $fontSize * 3.0)
            && abs((float) $layout['x1'] - (float) $discardedLayout['x1']) >= max(32.0, $fontSize * 3.5);
    }

    /**
     * A short visual region may have a missing line between it and the next
     * source line. This is a local signal: the next line is independently
     * marked as interrupted and the observed vertical gap is much larger than
     * the normal text rhythm. It is stronger evidence than a generic column
     * break, which is common in ordinary papers.
     *
     * @param list<array{text: string, layout: array<string, mixed>|null}> $records
     * @param array{text: string, layout: array<string, mixed>|null}|null $following
     */
    private function pdfComplexColumnSegmentIsFollowedByDamagedGap(array $records, ?array $following): bool
    {
        if ($records === [] || $following === null) {
            return false;
        }

        $record = $records[array_key_last($records)];
        $layout = is_array($record['layout'] ?? null) ? $record['layout'] : null;
        $followingLayout = is_array($following['layout'] ?? null) ? $following['layout'] : null;
        if (!$this->pdfLayoutHasGeometry($layout)
            || !$this->pdfLayoutHasGeometry($followingLayout)
            || ($layout['page'] ?? null) !== ($followingLayout['page'] ?? null)
            || ($layout['sourceGeometryColumn'] ?? null) !== ($followingLayout['sourceGeometryColumn'] ?? null)
            || !$this->pdfComplexColumnRecordHasDamageEvidence($following)) {
            return false;
        }

        $fontSize = max(1.0, (float) $layout['fontSize'], (float) $followingLayout['fontSize']);
        $verticalGap = (float) $layout['y1'] - (float) $followingLayout['y2'];

        return $verticalGap > max(18.0, $fontSize * 2.2);
    }

    /**
     * A figure can replace the opening words of a visual flow while leaving a
     * later, complete sentence on the same physical line. Retain that sentence
     * when punctuation makes the boundary explicit; otherwise leave the
     * fragment for the ordinary incomplete-flow rejection below.
     *
     * @param list<array{text: string, layout: array<string, mixed>|null}> $records
     * @return list<array{text: string, layout: array<string, mixed>|null}>
     */
    private function trimLeadingIncompletePdfComplexSegment(array $records): array
    {
        if ($records === []) {
            return $records;
        }

        $first = ltrim($records[0]['text']);
        if (preg_match('/^[,.;:]\s+(\p{Lu}[\s\S]*)$/u', $first, $matches) === 1) {
            $records[0]['text'] = $matches[1];

            return $records;
        }
        if (preg_match('/^[^\p{L}\p{N}]*\p{Ll}/u', $first) !== 1
            || ($records[0]['layout']['sourceInterruptedColumnRegion'] ?? false) !== true
            || ($records[0]['layout']['forceBlockBreakBefore'] ?? false) !== true) {
            return $records;
        }

        foreach ($records as $index => $record) {
            if (preg_match('/[.!?]\s+((?:(?:[\(\[]\s*)?(?:\p{N}+\s*[\)\]]\s*)?)?\p{Lu}[\s\S]*)$/u', $record['text'], $matches) !== 1
                || count($this->pdfLineWordTokens($matches[1])) < 5) {
                continue;
            }

            $trimmed = array_slice($records, $index);
            $trimmed[0]['text'] = $matches[1];

            return $trimmed;
        }

        return $records;
    }

    /**
     * @param array{text: string, layout: array<string, mixed>|null} $previous
     * @param array{text: string, layout: array<string, mixed>|null} $current
     */
    private function pdfComplexColumnRecordsShareFlow(array $previous, array $current): bool
    {
        $previousLayout = $previous['layout'];
        $currentLayout = $current['layout'];
        if (!$this->pdfLayoutHasGeometry($previousLayout) || !$this->pdfLayoutHasGeometry($currentLayout)
            || ($previousLayout['page'] ?? null) !== ($currentLayout['page'] ?? null)) {
            return false;
        }

        $fontSize = max((float) $previousLayout['fontSize'], (float) $currentLayout['fontSize'], 1.0);
        $previousColumn = $previousLayout['sourceGeometryColumn'] ?? null;
        $currentColumn = $currentLayout['sourceGeometryColumn'] ?? null;
        if ($previousColumn !== null || $currentColumn !== null) {
            if ($previousColumn === null || $currentColumn === null || $previousColumn !== $currentColumn) {
                return false;
            }
        } elseif (abs((float) $previousLayout['x1'] - (float) $currentLayout['x1']) > max(16.0, $fontSize * 1.5)) {
            return false;
        }
        $step = (float) $previousLayout['y1'] - (float) $currentLayout['y1'];

        return $step >= -$fontSize * 0.35 && $step <= max(16.0, $fontSize * 1.75);
    }

    /**
     * Figure-heavy pages may lose the last visual lines of one paragraph
     * while leaving the preceding paragraph intact. Treat a terminal line
     * followed by a new capitalized visual line as a hard boundary before
     * deciding whether either flow is incomplete.
     *
     * @param array{text: string, layout: array<string, mixed>|null} $previous
     * @param array{text: string, layout: array<string, mixed>|null} $current
     */
    private function pdfComplexColumnRecordsHaveSentenceBoundary(array $previous, array $current): bool
    {
        return preg_match('/[.!?;:]\s*$/u', rtrim($previous['text'])) === 1
            && preg_match('/^[^\p{L}\p{N}]*\p{Lu}/u', ltrim($current['text'])) === 1;
    }

    /**
     * A broken visual line can be followed immediately by an otherwise normal
     * paragraph. Once the next line starts a new capitalized flow, retaining
     * both would invent a sentence across the missing glyphs. The earlier line
     * already has structural damage evidence; this only makes that boundary
     * explicit to the segmenter.
     *
     * @param array{text: string, layout: array<string, mixed>|null} $previous
     * @param array{text: string, layout: array<string, mixed>|null} $current
     */
    private function pdfComplexColumnRecordsHaveDamagedFlowBoundary(array $previous, array $current): bool
    {
        if (!$this->pdfComplexColumnRecordHasDamageEvidence($previous)) {
            return false;
        }

        $previousText = rtrim($previous['text']);
        $currentText = ltrim($current['text']);
        if ($previousText === '' || $currentText === ''
            || preg_match('/[.!?;:]\s*$/u', $previousText) === 1
            || preg_match('/^[^\p{L}\p{N}]*\p{Lu}/u', $currentText) !== 1) {
            return false;
        }

        $previousLayout = $previous['layout'];
        $currentLayout = $current['layout'];

        return $this->pdfLayoutHasGeometry($previousLayout)
            && $this->pdfLayoutHasGeometry($currentLayout)
            && ($previousLayout['page'] ?? null) === ($currentLayout['page'] ?? null)
            && ($previousLayout['sourceGeometryColumn'] ?? null) === ($currentLayout['sourceGeometryColumn'] ?? null);
    }

    /**
     * An offset inline fragment followed by a normal lower-case body line is
     * an explicit visual boundary. The preceding flow cannot safely cross it
     * when it ends mid-sentence. This deliberately excludes ordinary forced
     * paragraph and cross-column boundaries.
     *
     * @param list<array{text: string, layout: array<string, mixed>|null}> $records
     * @param array{text: string, layout: array<string, mixed>|null}|null $following
     * @param array{text: string, layout: array<string, mixed>|null}|null $afterFollowing
     */
    private function pdfComplexColumnSegmentHasForcedSameColumnBoundary(
        array $records,
        ?array $following,
        ?array $afterFollowing
    ): bool
    {
        if ($records === [] || $following === null || $afterFollowing === null) {
            return false;
        }

        $last = $records[array_key_last($records)];
        $lastLayout = is_array($last['layout'] ?? null) ? $last['layout'] : null;
        $followingLayout = is_array($following['layout'] ?? null) ? $following['layout'] : null;
        $afterFollowingLayout = is_array($afterFollowing['layout'] ?? null) ? $afterFollowing['layout'] : null;
        if (!$this->pdfLayoutHasGeometry($lastLayout)
            || !$this->pdfLayoutHasGeometry($followingLayout)
            || !$this->pdfLayoutHasGeometry($afterFollowingLayout)
            || ($lastLayout['page'] ?? null) !== ($followingLayout['page'] ?? null)
            || ($lastLayout['page'] ?? null) !== ($afterFollowingLayout['page'] ?? null)
            || ($lastLayout['sourceGeometryColumn'] ?? null) !== ($followingLayout['sourceGeometryColumn'] ?? null)
            || ($lastLayout['sourceGeometryColumn'] ?? null) !== ($afterFollowingLayout['sourceGeometryColumn'] ?? null)
            || ($followingLayout['forceBlockBreakBefore'] ?? false) !== true
            || abs((float) $followingLayout['x1'] - (float) $lastLayout['x1']) < max(
                32.0,
                max((float) $lastLayout['fontSize'], (float) $followingLayout['fontSize'], 1.0) * 3.5
            )) {
            return false;
        }

        $followingText = trim($following['text']);
        return preg_match('/^[^\p{L}\p{N}]*\p{Lu}/u', $followingText) === 1
            && preg_match('/[.!?;:]\s*$/u', $followingText) !== 1
            && count($this->pdfLineWordTokens($followingText)) <= 7
            && preg_match('/^[^\p{L}\p{N}]*\p{Ll}/u', ltrim($afterFollowing['text'])) === 1
            && $this->pdfComplexColumnRecordsShareFlow($following, $afterFollowing);
    }

    /**
     * A stable text flow that stops mid-sentence at a forced visual break has
     * lost content. This catches clipped paragraph tails beside figures, code,
     * and section boundaries even when the extractor did not leave a separate
     * orphan glyph fragment to mark the prior line as damaged.
     *
     * @param list<array{text: string, layout: array<string, mixed>|null}> $records
     * @param array{text: string, layout: array<string, mixed>|null}|null $following
     * @param array{text: string, layout: array<string, mixed>|null}|null $afterFollowing
     */
    private function pdfComplexColumnSegmentEndsAtUnresolvedVisualBoundary(
        array $records,
        ?array $following,
        ?array $afterFollowing = null
    ): bool
    {
        if ($records === [] || $following === null) {
            return false;
        }

        $last = $records[array_key_last($records)];
        $lastLayout = $last['layout'];
        $lastText = rtrim($last['text']);
        if (!$this->pdfLayoutHasGeometry($lastLayout)
            || $lastText === ''
            || $this->lineHasPdfListBlockEvidence($lastText)
            || $this->lineLooksLikeUrlOnly($lastText)
            || $this->repairedLineLooksLikeSectionLabel($lastText)
            || $this->lineLooksLikePdfAllCapsDisplayText($lastText)
            || preg_match('/[.!?;:]\s*$/u', $lastText) === 1
            || preg_match('/[-\x{2010}-\x{2015}]\s*$/u', $lastText) === 1) {
            return false;
        }
        if (count($records) < 2 && $this->length($lastText) < 32) {
            return false;
        }

        $followingLayout = $following['layout'];
        $followingText = ltrim($following['text']);
        if (($followingLayout['code'] ?? false) === true) {
            return true;
        }
        if (($followingLayout['forceBlockBreakBefore'] ?? false) === true
            && $this->pdfComplexColumnRecordHasDamageEvidence($following)) {
            return true;
        }
        if (!$this->pdfLayoutHasGeometry($followingLayout)
            || ($followingLayout['page'] ?? null) !== ($lastLayout['page'] ?? null)) {
            return false;
        }

        $fontSize = max(1.0, (float) $lastLayout['fontSize'], (float) $followingLayout['fontSize']);
        $lastColumn = $lastLayout['sourceGeometryColumn'] ?? null;
        $followingColumn = $followingLayout['sourceGeometryColumn'] ?? null;
        if ($lastColumn !== null || $followingColumn !== null) {
            if ($lastColumn === null || $followingColumn === null) {
                return ($lastLayout['sourceStructuredGeometry'] ?? false) === true
                    && ($followingLayout['code'] ?? false) !== true
                    && !isset($followingLayout['sourcePdfTableGroup']);
            }
            if ($lastColumn !== $followingColumn) {
                if ($this->lineLooksLikeCompletePdfCaption($followingText)) {
                    return true;
                }
                if (preg_match('/^[^\p{L}\p{N}]*\p{Lu}/u', $followingText) === 1
                    && (float) $followingLayout['y1'] - (float) $lastLayout['y1'] > max(24.0, $fontSize * 3.0)) {
                    return true;
                }
                if ($this->pdfComplexColumnRecordHasCodeSyntax($following)
                    || ($afterFollowing !== null && $this->pdfComplexColumnRecordHasCodeSyntax($afterFollowing))) {
                    return true;
                }

                return preg_match('/^[^\p{L}\p{N}]*\p{Ll}/u', $followingText) === 1
                    && $this->pdfComplexColumnContinuationIsIsolated($following, $afterFollowing);
            }
        } elseif (abs((float) $lastLayout['x1'] - (float) $followingLayout['x1']) > max(16.0, $fontSize * 1.5)) {
            return false;
        }
        if ($followingText === ''
            || preg_match('/^[^\p{L}\p{N}]*\p{Lu}/u', $followingText) !== 1) {
            return false;
        }
        if (($followingLayout['forceBlockBreakBefore'] ?? false) === true) {
            return true;
        }
        $verticalGap = (float) $lastLayout['y1'] - (float) $followingLayout['y2'];

        return $verticalGap > max(18.0, $fontSize * 2.2);
    }

    /**
     * A code listing in an adjacent visual column is a hard semantic boundary
     * for prose. The signal is punctuation-based so it also works for code in
     * languages other than the document's natural language.
     *
     * @param array{text: string, layout: array<string, mixed>|null} $record
     */
    private function pdfComplexColumnRecordHasCodeSyntax(array $record): bool
    {
        $layout = is_array($record['layout'] ?? null) ? $record['layout'] : [];

        return ($layout['code'] ?? false) === true
            || $this->positionedCodeSyntaxEvidence((string) ($record['text'] ?? '')) >= 1;
    }

    /**
     * The first line in a neighboring column can be a real continuation only
     * when it itself leads into the next local visual line. A lone lower-case
     * fragment followed by a new block proves that the cross-column paragraph
     * was clipped between the two regions.
     *
     * @param array{text: string, layout: array<string, mixed>|null} $continuation
     * @param array{text: string, layout: array<string, mixed>|null}|null $next
     */
    private function pdfComplexColumnContinuationIsIsolated(array $continuation, ?array $next): bool
    {
        if ($next === null) {
            return false;
        }

        $continuationLayout = $continuation['layout'];
        $nextLayout = $next['layout'];
        if (($nextLayout['code'] ?? false) === true) {
            return true;
        }
        $continuationText = rtrim($continuation['text']);
        $nextText = ltrim($next['text']);
        if ($continuationText === '' || $nextText === '') {
            return true;
        }
        if (($nextLayout['forceBlockBreakBefore'] ?? false) === true
            && preg_match('/^[^\p{L}\p{N}]*\p{Lu}/u', $nextText) === 1) {
            return true;
        }

        return !$this->pdfComplexColumnRecordsShareFlow($continuation, $next)
            && !$this->pdfComplexColumnRecordsHaveSentenceBoundary($continuation, $next);
    }

    /**
     * Positioned captions and figure-adjacent prose occasionally survive as a
     * lone, unfinished line at the end of a page. Unlike a structured body
     * column, there is no neighboring flow that can prove a cross-page
     * continuation, so emitting that line would fabricate a dangling sentence.
     *
     * @param list<array{text: string, layout: array<string, mixed>|null}> $records
     * @param array{text: string, layout: array<string, mixed>|null}|null $following
     */
    private function pdfComplexColumnSegmentIsStandaloneUnstructuredFragment(array $records, ?array $following): bool
    {
        if ($records === []) {
            return false;
        }

        $last = $records[array_key_last($records)];
        $layout = $last['layout'];
        $text = rtrim($last['text']);
        if (!$this->pdfLayoutHasGeometry($layout)
            || ($layout['sourceStructuredGeometry'] ?? false) === true
            || ($layout['forceBlockBreakBefore'] ?? false) !== true
            || $text === ''
            || $this->lineHasPdfListBlockEvidence($text)
            || $this->lineLooksLikeUrlOnly($text)
            || $this->lineLooksLikeCompletePdfCaption($text)
            || $this->repairedLineLooksLikeSectionLabel($text)
            || preg_match('/[.!?;:]\s*$/u', $text) === 1
            || $this->length($text) < 48
            || count($this->pdfLineWordTokens($text)) < 8) {
            return false;
        }

        if ($following === null) {
            return true;
        }

        $followingLayout = $following['layout'];

        return $this->pdfLayoutHasGeometry($followingLayout)
            && ($followingLayout['page'] ?? null) !== ($layout['page'] ?? null);
    }

    /**
     * @param list<array{text: string, layout: array<string, mixed>|null}> $records
     */
    private function pdfComplexColumnSegmentLooksIncomplete(array $records): bool
    {
        $first = trim($records[0]['text']);
        $last = trim($records[array_key_last($records)]['text']);
        if ($first === '' || $last === '') {
            return true;
        }
        $interruptedColumnRegion = count(array_filter(
            $records,
            static fn (array $record): bool => ($record['layout']['sourceInterruptedColumnRegion'] ?? false) === true
        )) > 0;
        if ($this->lineHasPdfListBlockEvidence($first)
            || $this->lineLooksLikeUrlOnly($first)
            || $this->lineLooksLikePdfAllCapsDisplayText($first)) {
            return false;
        }
        if ($this->repairedLineLooksLikeSectionLabel($first)
            && count($records) === 1) {
            return false;
        }
        if (preg_match('/^(?:[,.;:\)\]\}]|\()/u', $first) === 1) {
            return true;
        }
        if (preg_match('/^[^\p{L}\p{N}]*\p{Ll}/u', $first) === 1) {
            return true;
        }
        if (preg_match('/[.!?]\s*$/u', $last) === 1) {
            return false;
        }
        if (preg_match('/[;:]\s*$/u', $last) === 1) {
            return $interruptedColumnRegion;
        }
        if (preg_match('/[-\x{2010}-\x{2015}]\s*$/u', $last) === 1) {
            return $interruptedColumnRegion;
        }

        return true;
    }

    /**
     * Diagram-heavy pages can leave one or two body-looking lines stranded
     * between a figure and the next paragraph. Without their missing visual
     * neighbors they read as a fabricated sentence, so retain only complete
     * flows and ordinary multi-line prose.
     *
     * @param list<array{text: string, layout: array<string, mixed>|null}> $records
     * @return list<array{text: string, layout: array<string, mixed>|null}>
     */
    private function removeIsolatedPdfDiagramFlowFragments(array $records): array
    {
        $filtered = [];
        $segment = [];
        $flushSegment = function () use (&$filtered, &$segment): void {
            if ($segment === []) {
                return;
            }
            if (!$this->pdfDetachedDiagramFlowFragmentShouldBeDropped($segment)) {
                foreach ($segment as $record) {
                    $filtered[] = $record;
                }
            }
            $segment = [];
        };

        foreach ($records as $record) {
            $layout = is_array($record['layout'] ?? null) ? $record['layout'] : null;
            if (($layout['sourceStructuredGeometry'] ?? false) !== true
                || ($layout['sourceDetachedDiagramEvidencePage'] ?? false) !== true) {
                $flushSegment();
                $filtered[] = $record;
                continue;
            }

            $last = $segment === [] ? null : $segment[array_key_last($segment)];
            if ($last === null
                || (($layout['forceBlockBreakBefore'] ?? false) !== true
                    && $this->pdfComplexColumnRecordsShareFlow($last, $record))) {
                $segment[] = $record;
                continue;
            }
            $flushSegment();
            $segment[] = $record;
        }
        $flushSegment();

        return $filtered;
    }

    /**
     * @param list<array{text: string, layout: array<string, mixed>|null}> $records
     */
    private function pdfDetachedDiagramFlowFragmentShouldBeDropped(array $records): bool
    {
        if (count($records) === 0 || count($records) > 2) {
            return false;
        }

        $first = trim($records[0]['text']);
        $last = trim($records[array_key_last($records)]['text']);
        if ($first === '' || $last === ''
            || $this->lineHasPdfListBlockEvidence($first)
            || $this->lineLooksLikeUrlOnly($first)
            || $this->repairedLineLooksLikeSectionLabel($first)
            || $this->lineLooksLikePdfAllCapsDisplayText($first)) {
            return false;
        }

        $startsLowercase = preg_match('/^[^\p{L}\p{N}]*\p{Ll}/u', $first) === 1;
        $endsComplete = preg_match('/[.!?;:]\s*$/u', $last) === 1
            || preg_match('/[-\x{2010}-\x{2015}]\s*$/u', $last) === 1;

        return $startsLowercase || !$endsComplete;
    }

    /**
     * Source text that could not be matched to a positioned line is normally
     * retained. On a geometry-confirmed page, however, a run of repeated,
     * compact, unplaceable labels is almost certainly diagram text rather
     * than a prose paragraph. Drop only that narrow shape; regular source
     * text and lists have no such marker and remain untouched.
     *
     * @param list<array{text: string, layout: array<string, mixed>|null}> $records
     * @return list<array{text: string, layout: array<string, mixed>|null}>
     */
    private function removeLowCoherencePdfUnpositionedLabelRegions(array $records): array
    {
        $filtered = [];
        $candidate = [];
        $flushCandidate = function () use (&$filtered, &$candidate): void {
            if ($candidate === []) {
                return;
            }
            if (!$this->pdfUnpositionedLabelClusterShouldBeDropped($candidate)) {
                foreach ($candidate as $record) {
                    $filtered[] = $record;
                }
            }
            $candidate = [];
        };

        foreach ($records as $record) {
            $layout = is_array($record['layout'] ?? null) ? $record['layout'] : null;
            if (($layout['sourceUnmatchedFallback'] ?? false) !== true
                || (($layout['sourceComplexGeometryPage'] ?? false) !== true
                    && ($layout['sourceDetachedDiagramEvidencePage'] ?? false) !== true)) {
                $flushCandidate();
                $filtered[] = $record;
                continue;
            }
            $candidate[] = $record;
        }
        $flushCandidate();

        return $filtered;
    }

    /**
     * @param list<array{text: string, layout: array<string, mixed>|null}> $records
     */
    private function pdfUnpositionedLabelClusterShouldBeDropped(array $records): bool
    {
        if (count($records) < 5) {
            return false;
        }

        $shortLabels = 0;
        $repeated = [];
        foreach ($records as $record) {
            $line = trim($record['text']);
            if ($this->lineHasPdfListBlockEvidence($line)
                || $this->lineLooksLikeUrlOnly($line)
                || preg_match('/[.!?;:]\s*$/u', $line) === 1) {
                return false;
            }
            $compact = preg_replace('/\s+/u', '', $line) ?? '';
            if ($this->length($compact) <= 18 && count($this->pdfLineWordTokens($line)) <= 4) {
                $shortLabels++;
            }
            $key = $this->pdfComparableLineText($line);
            if ($key !== '') {
                $repeated[$key] = ($repeated[$key] ?? 0) + 1;
            }
        }

        return $shortLabels / count($records) >= 0.80
            && ($repeated === [] ? 0 : max($repeated)) >= 3;
    }

    private function lineLooksLikePdfDiagramLabel(string $line): bool
    {
        $line = trim($line);
        if ($line === '' || $this->length($line) > 36 || preg_match('/[.!?]\s*$/u', $line) === 1) {
            return false;
        }
        if (preg_match('/[{};]|:=|=>|->|\/\//u', $line) === 1) {
            return false;
        }

        return count($this->pdfLineWordTokens($line)) <= 5;
    }

    /**
     * @param list<array{text: string, layout: array<string, mixed>|null}> $records
     */
    private function pdfDiagramLabelClusterShouldBeDropped(array $records): bool
    {
        $count = count($records);
        if ($count < 6) {
            return false;
        }

        $shortLabels = 0;
        $singleLetterFragments = 0;
        $lowercaseFragments = 0;
        $fragmentTransitions = 0;
        $previousWasShortPrefix = false;
        foreach ($records as $record) {
            $line = trim($record['text']);
            if ($this->length($line) <= 24) {
                $shortLabels++;
            }

            $startsLowercaseFragment = preg_match('/^\p{Ll}{1,8}(?=\s|$)/u', $line) === 1;
            $isShortPrefix = preg_match('/^\p{L}{1,2}$/u', $line) === 1;
            if ($isShortPrefix) {
                $singleLetterFragments++;
            }
            if ($startsLowercaseFragment) {
                $lowercaseFragments++;
            }
            if ($previousWasShortPrefix && $startsLowercaseFragment) {
                $fragmentTransitions++;
            }
            $previousWasShortPrefix = $isShortPrefix || $startsLowercaseFragment;
        }

        return $shortLabels / $count >= 0.80
            && $singleLetterFragments >= 2
            && $lowercaseFragments >= 2
            && $fragmentTransitions >= 2;
    }

    /**
     * @param list<array{text: string, layout: array{text: string, page: int, x1: float, y1: float, x2: float, y2: float, fontSize: float}|null}> $records
     */
    private function pdfMapNoiseClusterShouldBeDropped(array $records): bool
    {
        $count = count($records);
        if ($count < 8) {
            return false;
        }

        $shortLabels = 0;
        $letterSpacedLabels = 0;
        $edgeFragments = 0;
        $numericOnlyValues = 0;
        $hasGeometryEvidence = false;
        foreach ($records as $record) {
            $line = $record['text'];
            $layout = is_array($record['layout'] ?? null) ? $record['layout'] : null;
            if ($this->pdfLayoutHasGeometry($layout)
                || is_array($layout['sourcePdfPageMapLabelGeometryEvidence'] ?? null)) {
                $hasGeometryEvidence = true;
            }
            if ($this->lineLooksLikeShortPdfMapLabel($line)) {
                $shortLabels++;
            }
            if ($this->lineLooksLikeLetterSpacedPdfMapLabel($line)) {
                $letterSpacedLabels++;
            }
            if ($this->lineLooksLikePdfMapEdgeFragment($line, $record['layout'])) {
                $edgeFragments++;
            }
            $compact = preg_replace('/[^\p{L}\p{N}]+/u', '', $line) ?? '';
            if ($compact !== ''
                && preg_match('/\p{N}/u', $compact) === 1
                && preg_match('/\p{L}/u', $compact) !== 1) {
                $numericOnlyValues++;
            }
        }
        if (!$hasGeometryEvidence) {
            // A metadata carrier is not spatial evidence. In particular,
            // source-order fallbacks can have stable IDs, streams, and page
            // numbers but no coordinates at all. Never suppress such visible
            // records merely because many happen to be short.
            return false;
        }
        if ($numericOnlyValues >= 8 && $numericOnlyValues / $count >= 0.72) {
            // A sustained run of amounts, ranges, years, or other compact
            // numeric values is data-grid evidence even when the surrounding
            // table hypothesis is rejected. Maps may contain an occasional
            // route number; numeric dominance is the important distinction.
            return false;
        }

        if ($shortLabels >= 6 && $edgeFragments > 0) {
            return true;
        }

        return $count >= 18 && $shortLabels / $count >= 0.72;
    }

    /**
     * @param array{text: string, page: int, x1: float, y1: float, x2: float, y2: float, fontSize: float}|null $layout
     */
    private function lineLooksLikePdfMapLabelNoise(string $line, ?array $layout): bool
    {
        $hasPageMapLabelGeometryEvidence = is_array(
            $layout['sourcePdfPageMapLabelGeometryEvidence'] ?? null
        );
        if (($layout['code'] ?? false) === true
            || (!$this->pdfLayoutHasGeometry($layout) && !$hasPageMapLabelGeometryEvidence)) {
            return false;
        }

        $line = trim($line);
        if ($line === '') {
            return false;
        }
        if ($this->lineLooksLikePdfListItem($line) || $this->lineLooksLikeUrlOnly($line)) {
            return false;
        }

        return $this->lineLooksLikeShortPdfMapLabel($line)
            || $this->lineLooksLikeLetterSpacedPdfMapLabel($line)
            || $this->lineLooksLikePdfMapEdgeFragment($line, $layout);
    }

    /**
     * @param array{text: string, page: int, x1: float, y1: float, x2: float, y2: float, fontSize: float}|null $layout
     */
    private function lineLooksLikePdfMapEdgeFragment(string $line, ?array $layout): bool
    {
        if (!$this->pdfLayoutHasGeometry($layout) || $this->lineLooksLikePdfListItem($line) || $this->lineLooksLikeUrlOnly($line)) {
            return false;
        }

        $compact = preg_replace('/\s+/u', '', trim($line)) ?? '';
        if ($this->length($compact) < 80 || count($this->pdfLineWordTokens($line)) < 6) {
            return false;
        }

        return $layout['y1'] < 24.0 && $layout['x1'] < 48.0;
    }

    private function lineLooksLikeShortPdfMapLabel(string $line): bool
    {
        $line = trim($line);
        if ($line === '' || $this->lineLooksLikePdfListItem($line) || $this->lineLooksLikeUrlOnly($line)) {
            return false;
        }

        $compact = preg_replace('/[^\p{L}\p{N}]+/u', '', $line) ?? '';
        $length = $this->length($compact);
        if ($length <= 3) {
            return true;
        }
        if ($length > 35 || preg_match('/[.!?;:]$/u', $line) === 1) {
            return false;
        }

        $words = $this->pdfLineWordTokens($line);
        if (count($words) > 4) {
            return false;
        }

        return preg_match('/^[\p{L}\p{N},&()\/ .-]+$/u', $line) === 1;
    }

    private function lineLooksLikeLetterSpacedPdfMapLabel(string $line): bool
    {
        $line = trim($line);
        if ($line === ''
            || preg_match('/\p{L}/u', $line) !== 1
            || $this->lineLooksLikePdfListItem($line)
            || $this->lineLooksLikeUrlOnly($line)) {
            return false;
        }

        $tokens = preg_split('/\s+/u', $line) ?: [];
        if (count($tokens) < 4 || count($tokens) > 24) {
            return false;
        }

        $singleGlyphTokens = 0;
        foreach ($tokens as $token) {
            $token = trim($token, " \t\n\r\0\x0B,.;:()[]{}'\"’‘“”-");
            if ($this->length($token) === 1 && preg_match('/^[\p{L}\p{N}]$/u', $token) === 1) {
                $singleGlyphTokens++;
            }
        }

        return $singleGlyphTokens >= 4 && $singleGlyphTokens / count($tokens) >= 0.75;
    }

    /**
     * @return list<string>
     */
    private function pdfLineWordTokens(string $line): array
    {
        $tokens = [];
        $offset = 0;
        $byteLength = strlen($line);
        while ($offset < $byteLength
            && preg_match(
                '/[\p{L}\p{N}][\p{L}\p{N}.-]*/u',
                $line,
                $match,
                PREG_OFFSET_CAPTURE,
                $offset
            ) === 1) {
            $matched = (string) $match[0][0];
            $word = trim($matched, ".-");
            if ($word !== '') {
                $tokens[] = $word;
            }
            $nextOffset = (int) $match[0][1] + strlen($matched);
            $offset = $nextOffset > $offset ? $nextOffset : $offset + 1;
        }

        return $tokens;
    }

    private function lineLooksLikePdfListItem(string $line): bool
    {
        return $this->listItem($line) !== null;
    }

    private function lineLooksLikeUrlOnly(string $line): bool
    {
        return preg_match('/^(?:https?:\/\/|www\.)\S+$/i', trim($line)) === 1;
    }


    private function repairGluedProseLine(string $line): string
    {
        $line = trim($line);
        if ($line === '') {
            return '';
        }

        $line = $this->repairPdfMisorderedDiacritics($line);
        $line = $this->repairSplitUrlWhitespace($line);
        // Source whitespace beside a soft hyphen is not, by itself, proof
        // that the hyphen was a discretionary line break. The merge stage
        // deletes one only when the two exact source/layout records share a
        // sourcePdfWrappedHyphenPairAfter/Before markers. Every remaining
        // soft hyphen is therefore rendered as a visible separator,
        // including extractor whitespace around the same in-word boundary.
        $line = preg_replace('/\s*\x{00AD}\s*/u', '-', $line) ?? $line;
        $lineHasWordSpacing = preg_match('/\p{L}\s+\p{L}/u', $line) === 1;
        $line = preg_replace('/(?<=\S) +(?=[.,!?\)\]])/u', '', $line) ?? $line;
        // A valid thousands separator or clock colon is not punctuation
        // followed by a missing prose space (for example "10,000" or
        // "12:30"). Check the full numeric form instead of preserving every
        // digit-to-digit comma or colon: "2019,2020" still needs a space.
        $line = preg_replace_callback(
            '/([,;:!?])(?=\S)/u',
            function (array $matches) use ($line): string {
                $punctuation = $matches[1][0];
                $offset = $matches[1][1];

                return $this->pdfCompactNumericPunctuationAt($line, $offset, $punctuation)
                    ? $punctuation
                    : $punctuation . ' ';
            },
            $line,
            -1,
            $count,
            PREG_OFFSET_CAPTURE
        ) ?? $line;
        // A decimal point is followed by a digit, not a capitalized prose
        // token. Restore missing sentence/label boundaries, except where the
        // matched punctuation itself belongs to an explicit URL.
        $line = preg_replace_callback(
            '/(?<=\S)\.(?=\p{Lu})/u',
            function (array $matches) use ($line): string {
                $text = $matches[0][0];
                $offset = $matches[0][1];
                if ($this->pdfOffsetIsWithinExplicitUrl($line, $offset)
                    || $this->pdfPeriodIsWithinInitialism($line, $offset)) {
                    return $text;
                }

                return '. ';
            },
            $line,
            -1,
            $count,
            PREG_OFFSET_CAPTURE
        ) ?? $line;
        if ($lineHasWordSpacing) {
            // An all-caps acronym surrounded by ordinary prose is a reliable
            // glued-word boundary. Camel-case words and short plural suffixes
            // are intentionally left alone because they are identifiers.
            $line = preg_replace('/([\p{Ll}])(\p{Lu}{2,})(?=\p{Ll})/u', '$1 $2', $line) ?? $line;
            $line = preg_replace('/(?<!\p{Lu})(\p{Lu}{2})(\p{Ll}{3,})/u', '$1 $2', $line) ?? $line;
        }
        $line = preg_replace_callback(
            '/(\d)([\p{Latin}]{2,})/u',
            function (array $matches) use ($line): string {
                $text = $matches[0][0];
                $offset = $matches[0][1];
                $suffix = $matches[2][0];
                // This glued-prose heuristic is grounded in Latin word and
                // ordinal boundaries. Other scripts commonly attach native
                // counters or units to numbers, so their source spelling is
                // retained unless independent layout evidence repairs it.
                if (preg_match('/^(?:st|nd|rd|th)(?!\p{L})/iu', $suffix) === 1) {
                    return $text;
                }
                if ($this->pdfOffsetIsWithinUrlOrDomain($line, $offset, strlen($text))) {
                    return $text;
                }

                return $matches[1][0] . ' ' . $matches[2][0];
            },
            $line,
            -1,
            $count,
            PREG_OFFSET_CAPTURE
        ) ?? $line;
        // In scientific and technical PDFs a Greek glyph often represents an
        // inline variable. A following Latin word belongs to prose, not the
        // variable name, even when a font switch omitted the space.
        $line = preg_replace('/([\p{Greek}])(?=[A-Za-z])/u', '$1 ', $line) ?? $line;
        $line = preg_replace('/\/\/(?=[A-Za-z])/', '// ', $line) ?? $line;
        $line = $this->repairSplitUrlWhitespace($line);
        $line = preg_replace('/([\x{2019}\']t)(?=[A-Za-z])/u', '$1 ', $line) ?? $line;

        $line = preg_replace('/\s+/u', ' ', $line) ?? $line;
        $line = str_replace(self::PDF_SOURCE_COMPACT_IDENTIFIER_BOUNDARY, '', $line);

        return trim($line);
    }

    /**
     * Some PDF producers paint an accent before the base glyph. When that
     * sequence sits inside a word, restore the normal Unicode order before
     * applying NFC normalization. The surrounding-letter requirement keeps
     * standalone notation and punctuation unchanged.
     */
    private function repairPdfMisorderedDiacritics(string $text): string
    {
        $combiningMarks = [
            "\u{00A8}" => "\u{0308}",
            "\u{00AF}" => "\u{0304}",
            "\u{00B4}" => "\u{0301}",
            "\u{00B8}" => "\u{0327}",
            "\u{02C7}" => "\u{030C}",
            "\u{02D8}" => "\u{0306}",
            "\u{02D9}" => "\u{0307}",
            "\u{02DA}" => "\u{030A}",
            "\u{02DC}" => "\u{0303}",
        ];
        $text = preg_replace_callback(
            '/(?<=\p{L})([\x{00A8}\x{00AF}\x{00B4}\x{00B8}\x{02C7}\x{02D8}\x{02D9}\x{02DA}\x{02DC}])([\p{L}])/u',
            static function (array $matches) use ($combiningMarks): string {
                $base = match ($matches[2]) {
                    "\u{0131}" => 'i',
                    "\u{0237}" => 'j',
                    default => $matches[2],
                };

                return $base . $combiningMarks[$matches[1]];
            },
            $text
        ) ?? $text;

        if (class_exists(\Normalizer::class)) {
            $normalized = \Normalizer::normalize($text, \Normalizer::FORM_C);
            if (is_string($normalized)) {
                return $normalized;
            }
        }

        return $text;
    }

    /**
     * Keep conventional numeric grouping plus ambiguous compact colon
     * notation. Commas still require a valid thousands shape; a colon between
     * digits may be a time, ratio, or scale and is preserved without guessing.
     */
    private function pdfCompactNumericPunctuationAt(string $line, int $offset, string $punctuation): bool
    {
        if ($offset <= 0) {
            return false;
        }

        $before = substr($line, 0, $offset);
        $after = substr($line, $offset + strlen($punctuation));
        if ($punctuation === ',') {
            return preg_match('/(?:^|[^\d])\d{1,3}(?:,\d{3})*$/D', $before) === 1
                && preg_match('/^\d{3}(?!\d)/', $after) === 1;
        }
        if ($punctuation === ':') {
            // A compact numeric colon can be a time, ratio, scale, or other
            // mathematical notation. Without local boundary evidence, keep
            // the source notation rather than choosing one prose meaning.
            return preg_match('/\d$/D', $before) === 1
                && preg_match('/^\d/', $after) === 1;
        }

        return false;
    }

    private function pdfPeriodIsWithinInitialism(string $line, int $offset): bool
    {
        if ($offset <= 0) {
            return false;
        }
        $before = substr($line, 0, $offset);
        $after = substr($line, $offset + 1);

        return preg_match('/(?:^|[^\p{L}])(?:\p{Lu}\.)*\p{Lu}$/u', $before) === 1
            && preg_match('/^\p{Lu}(?:\.|$)/u', $after) === 1;
    }

    private function pdfOffsetIsWithinUrlOrDomain(string $line, int $offset, int $length): bool
    {
        $before = substr($line, 0, $offset);
        $after = substr($line, $offset + $length);
        preg_match('/[^\s]+$/u', $before, $leftMatch);
        preg_match('/^[^\s]+/u', $after, $rightMatch);
        $token = ($leftMatch[0] ?? '') . substr($line, $offset, $length) . ($rightMatch[0] ?? '');
        $token = trim($token, "()[]{}<>,.;:'\"”’");

        return $this->lineLooksLikeUrlOnly($token) || $this->lineLooksLikeBareDomain($token);
    }

    private function pdfOffsetIsWithinExplicitUrl(string $line, int $offset): bool
    {
        $prefix = substr($line, 0, $offset);

        return preg_match('~(?:https?://|www\.)[^\s]*$~iu', $prefix) === 1;
    }

    private function repairSplitUrlWhitespace(string $line): string
    {
        $line = preg_replace('/\b(https?):\s*\/\/\s*/iu', '$1://', $line) ?? $line;
        $line = preg_replace('/\b(www)\s+\.(?=[A-Za-z0-9-])/iu', '$1.', $line) ?? $line;
        $line = preg_replace_callback(
            '/\b((?:https?:\/\/|www\.)\S*[A-Za-z])\s+(\d[\w.-]*)(?=[\/.)?#]|$)/iu',
            static function (array $matches): string {
                $left = $matches[1];
                $right = $matches[2];
                // A domain-shaped, digit-leading token is often a second
                // visible URL in a compact resource list, not a continuation
                // of the preceding host. Slash and hyphen paths remain safe
                // to join in the dedicated rule below.
                if (!str_ends_with($left, '/')
                    && !str_ends_with($left, '-')
                    && preg_match('/^\d[\w-]*\.[A-Za-z]{2,}$/u', $right) === 1) {
                    return $matches[0];
                }

                return $left . $right;
            },
            $line
        ) ?? $line;
        $line = preg_replace('/\b((?:https?:\/\/|www\.)\S*[-\/])\s+([A-Za-z0-9][\w.-]*)(?=[\/.)?#]|$)/iu', '$1$2', $line) ?? $line;

        return preg_replace_callback(
            '/\b((?:https?:\/\/|www\.)[A-Za-z0-9.-]*[A-Za-z0-9])\s+((?!www(?=\.))[A-Za-z0-9-]{1,24})(?=\.)/iu',
            static function (array $matches): string {
                $left = $matches[1];
                $right = $matches[2];
                if (preg_match('/^\d/u', $right) === 1
                    && preg_match('~(?:https?://|www\.)[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*\.[A-Za-z]{2,}$~iu', $left) === 1) {
                    return $matches[0];
                }

                return $left . $right;
            },
            $line
        ) ?? $line;
    }

    /**
     * @param list<string> $lines
     */
    private function looksLikeProseRepairCandidate(array $lines): bool
    {
        foreach (array_slice($lines, 0, 200) as $line) {
            if ($this->genericSpacingDamageScore([$line]) > 0) {
                return true;
            }
        }

        return false;
    }

    private function lineIsOnlyPdfNoise(string $line): bool
    {
        $line = trim($line);
        if ($line === '') {
            return false;
        }

        // A standalone Unicode ellipsis is visible semantic punctuation. In
        // compact tables it can occupy its own painted run between adjacent
        // header fragments, so treating every punctuation-only row as noise
        // silently removes a real source character before reconciliation.
        if (preg_match('/^\x{2026}+$/u', $line) === 1) {
            return false;
        }

        if (preg_match('/^[^\p{L}\p{N}]+$/u', $line) === 1) {
            return true;
        }
        if (preg_match('/^[,.;:()\[\]{}|_~`\'"’‘“”\-#!$%&*+=<>?@\\\\\/]+$/u', $line) === 1) {
            return true;
        }

        $compact = preg_replace('/\s+/u', '', $line) ?? '';
        $length = $this->length($compact);
        if ($length < 8) {
            return false;
        }
        $letters = preg_match_all('/\p{L}/u', $compact, $matches);
        $wordTokens = $this->pdfLineWordTokens($line);
        $longestWord = 0;
        foreach ($wordTokens as $word) {
            $longestWord = max($longestWord, $this->length($word));
        }
        $garbledDelimiterCount = preg_match_all('/[<>#]/u', $compact);

        if ($letters !== false
            && $garbledDelimiterCount !== false
            && $garbledDelimiterCount >= 3
            && $letters / $length <= 0.35
            && $longestWord <= 8) {
            return true;
        }

        return $letters !== false
            && $letters / $length <= 0.25
            && $longestWord <= 4
            && count($wordTokens) <= 12;
    }

    /**
     * Preserve geometry-confirmed code lines as one multiline block while
     * retaining the existing prose, list, and stacked-table merge behavior
     * for every surrounding record.
     *
     * @param list<array{text: string, layout: array<string,mixed>|null}> $records
     * @param array<int,array<string,mixed>>|null $exactWholeSourceMergedLineSpans
     * @return list<string>
     */
    private function mergeRepairedPdfRecords(
        array $records,
        ?array &$exactWholeSourceMergedLineSpans = null
    ): array {
        $collectExactWholeSourceMergedLineSpans = func_num_args() >= 2;
        $exactWholeSourceMergedLineSpans = [];
        $records = $this->pdfRecordsWithSparseOcrPlusBoundaries($records);
        $localLayoutLabelProofs = $this->pdfLocalCreditAndFooterLayoutLabelProofCandidates($records);
        $localLayoutLabelTargetIndexes = $this->pdfLocalLayoutLabelProofTargetRecordIndexes(
            $records,
            $localLayoutLabelProofs
        );
        $localLayoutLabelTextsByOrigin = [];
        $exactWholeSourceReceiptsByOrigin = [];
        foreach ($records as $recordIndex => &$record) {
            $layout = is_array($record['layout'] ?? null) ? $record['layout'] : null;
            $originDigest = hash('sha256', json_encode([
                'version' => 1,
                'method' => 'final-prose-merge-input-origin',
                'sourceSha256' => $this->sourceSha256,
                'recordIndex' => $recordIndex,
                'text' => (string) ($record['text'] ?? ''),
                'sourceOccurrenceId' => is_string($layout['id'] ?? null) ? $layout['id'] : null,
                'globalSourceIndex' => is_int($layout['sourcePdfGlobalSourceIndex'] ?? null)
                    ? $layout['sourcePdfGlobalSourceIndex']
                    : null,
            ], JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE) ?: '');
            // This sidecar is deliberately outside text and layout: merge
            // heuristics cannot observe it, while every natural output can
            // retain the exact set of input carriers that produced it.
            // Keep the common singleton as one string; the accessor expands
            // it only while a merge actually needs set arithmetic.
            $record['sourcePdfMergeOriginSet'] = $originDigest;
            $carrierProjection = $this->pdfSourceOccurrenceComparableText(
                $this->pdfTextWithoutSemanticPrefixes((string) ($record['text'] ?? ''))
            );
            $inlineStyleProof = is_array($layout['sourcePdfInlineFontStyleProof'] ?? null)
                ? $this->validatedPdfInlineFontStyleProof(
                    $layout['sourcePdfInlineFontStyleProof']
                )
                : null;
            if ($collectExactWholeSourceMergedLineSpans
                && is_array($layout)
                && $carrierProjection !== ''
                && is_array($inlineStyleProof)
                && hash_equals(
                    (string) $inlineStyleProof['projectionDigest'],
                    hash('sha256', $carrierProjection)
                )) {
                $exactWholeSourceReceiptsByOrigin[$originDigest] = [
                    'recordIndex' => $recordIndex,
                    'sourceOccurrenceIds' => $inlineStyleProof['sourceOccurrenceIds'],
                    'globalSourceIndexes' => $inlineStyleProof['globalSourceIndexes'],
                    'projection' => $carrierProjection,
                ];
            } elseif ($collectExactWholeSourceMergedLineSpans
                && is_array($layout)
                && $carrierProjection !== ''
                && $this->repairedPdfWholeExactSourceOccurrenceProofMatchesLayout(
                    $layout,
                    $carrierProjection
                )) {
                $wholeSourceProof = $layout['sourcePdfWholeExactSourceOccurrenceProof'];
                $exactWholeSourceReceiptsByOrigin[$originDigest] = [
                    'recordIndex' => $recordIndex,
                    'sourceOccurrenceId' => $wholeSourceProof['sourceOccurrenceId'],
                    'globalSourceIndex' => $wholeSourceProof['globalSourceIndex'],
                    'projection' => $carrierProjection,
                ];
            }
            if (isset($localLayoutLabelTargetIndexes[$recordIndex])) {
                $localLayoutLabelTextsByOrigin[$originDigest] = trim(
                    (string) ($record['text'] ?? '')
                );
            }
        }
        unset($record);
        $merged = [];
        $mergedOriginSets = [];
        $prose = [];
        $code = [];
        $codeOriginSet = [];
        $formula = [];
        $formulaOriginSet = [];
        $lineBlock = [];
        $lineBlockOriginSet = [];
        $lineBlockGroup = null;
        $flushProse = function () use (&$merged, &$mergedOriginSets, &$prose): void {
            if ($prose === []) {
                return;
            }
            $hasLayout = false;
            $hasProvenFormTails = false;
            foreach ($prose as $record) {
                $recordLayout = is_array($record['layout'] ?? null) ? $record['layout'] : null;
                if ($this->pdfLayoutHasGeometry($recordLayout)) {
                    $hasLayout = true;
                }
                if (($recordLayout['sourcePdfFormTailComposite'] ?? false) === true) {
                    $hasProvenFormTails = true;
                }
                if ($hasLayout && $hasProvenFormTails) {
                    break;
                }
            }
            $originSets = [];
            if (!$hasLayout
                && !$hasProvenFormTails
                && ($this->pdfLinesLookLikeDenseListLayout($prose)
                    || $this->pdfLinesLookLikeSparseLongTextChunks($prose))) {
                $lines = array_map(static fn (array $record): string => $record['text'], $prose);
                $originSets = array_map(
                    fn (array $record): ?array => $this->repairedPdfMergeOriginSetForRecord($record),
                    $prose
                );
            } else {
                $lines = $this->mergeRepairedProseLinesPreservingStackedTables(
                    $prose,
                    $originSets
                );
            }
            foreach ($lines as $lineIndex => $line) {
                $merged[] = $line;
                $mergedOriginSets[] = $originSets[$lineIndex] ?? null;
            }
            $prose = [];
        };
        $flushCode = function () use (
            &$merged,
            &$mergedOriginSets,
            &$code,
            &$codeOriginSet
        ): void {
            if ($code === []) {
                return;
            }
            $text = rtrim(implode("\n", $code));
            if ($text !== '') {
                $merged[] = self::PDF_CODE_BLOCK_PREFIX . $text;
                $mergedOriginSets[] = $codeOriginSet;
            }
            $code = [];
            $codeOriginSet = [];
        };
        $flushFormula = function () use (
            &$merged,
            &$mergedOriginSets,
            &$formula,
            &$formulaOriginSet
        ): void {
            if ($formula === []) {
                return;
            }
            $text = trim(implode(' ', $formula));
            if ($text !== '') {
                $merged[] = PdfFormulaSemanticProcessor::LINE_PREFIX . $text;
                $mergedOriginSets[] = $formulaOriginSet;
            }
            $formula = [];
            $formulaOriginSet = [];
        };
        $flushLineBlock = function () use (
            &$merged,
            &$mergedOriginSets,
            &$lineBlock,
            &$lineBlockOriginSet,
            &$lineBlockGroup
        ): void {
            if ($lineBlock !== []) {
                $merged[] = $this->encodePdfLineBlock($lineBlock);
                $mergedOriginSets[] = $lineBlockOriginSet;
            }
            $lineBlock = [];
            $lineBlockOriginSet = [];
            $lineBlockGroup = null;
        };

        foreach ($records as $record) {
            $layout = is_array($record['layout'] ?? null) ? $record['layout'] : null;
            $recordText = (string) ($record['text'] ?? '');
            // Semantic markers are an internal line protocol, not prose. A
            // map-label record followed by ordinary text used to enter the
            // prose merger, where the numbered-heading heuristic could wrap
            // it in a second marker. blocksFromLines() decoded only the outer
            // marker and leaked the inner C0-delimited sentinel into the
            // WordPress post. WordPress correctly strips those controls,
            // which then made publication verification fail after every PDF
            // page had already been checkpointed. Keep every already-typed
            // record atomic so semantic roles cannot be nested accidentally.
            if ($this->pdfLineStartsWithSemanticPrefix($recordText)) {
                $flushProse();
                $flushCode();
                $flushFormula();
                $flushLineBlock();
                $merged[] = $recordText;
                $mergedOriginSets[] = $this->repairedPdfMergeOriginSetForRecord($record);
                continue;
            }
            if (($layout['code'] ?? false) === true) {
                $flushProse();
                $flushLineBlock();
                $flushFormula();
                $code[] = (string) ($layout['codeText'] ?? $record['text']);
                $codeOriginSet = $this->repairedPdfMergeOriginSetsUnion(
                    $codeOriginSet,
                    $this->repairedPdfMergeOriginSetForRecord($record)
                );
                continue;
            }

            if (($layout['sourcePdfRegionRole'] ?? null) === 'formula') {
                $flushProse();
                $flushCode();
                $flushLineBlock();
                $formula[] = (string) ($layout['sourcePdfFormulaText'] ?? $record['text']);
                $formulaOriginSet = $this->repairedPdfMergeOriginSetsUnion(
                    $formulaOriginSet,
                    $this->repairedPdfMergeOriginSetForRecord($record)
                );
                continue;
            }

            if (($layout['sourcePdfFrontMatterRole'] ?? null) === 'credits') {
                $flushProse();
                $flushCode();
                $flushLineBlock();
                $flushFormula();
                $credit = trim((string) ($record['text'] ?? ''));
                if ($credit !== '') {
                    $merged[] = self::PDF_FRONT_MATTER_PREFIX . $credit;
                    $mergedOriginSets[] = $this->repairedPdfMergeOriginSetForRecord($record);
                }
                continue;
            }

            $group = isset($layout['sourcePdfLineOrientedGroup'])
                ? (int) $layout['sourcePdfLineOrientedGroup']
                : null;
            if ($group !== null) {
                $flushCode();
                $flushProse();
                $flushFormula();
                if ($lineBlockGroup !== null && $lineBlockGroup !== $group) {
                    $flushLineBlock();
                }
                $lineBlockGroup = $group;
                $lineBlockOriginSet = $this->repairedPdfMergeOriginSetsUnion(
                    $lineBlockOriginSet,
                    $this->repairedPdfMergeOriginSetForRecord($record)
                );
                if (($layout['sourcePdfRegionRole'] ?? null) === 'dialogue') {
                    $cue = trim((string) ($layout['sourcePdfDialogueCue'] ?? ''));
                    $body = trim((string) ($layout['sourcePdfDialogueBody'] ?? ''));
                    if ($cue !== '') {
                        $lineBlock[] = $cue;
                    }
                    if ($body !== '') {
                        $lineBlock[] = $body;
                    }
                } else {
                    $continuation = trim((string) ($record['text'] ?? ''));
                    if ($continuation !== '') {
                        $last = array_key_last($lineBlock);
                        if ($last === null) {
                            $lineBlock[] = $continuation;
                        } else {
                            $lineBlock[$last] = rtrim($lineBlock[$last]) . ' ' . ltrim($continuation);
                        }
                    }
                }
                continue;
            }

            $flushCode();
            $flushLineBlock();
            $flushFormula();
            $prose[] = $record;
        }
        $flushCode();
        $flushFormula();
        $flushLineBlock();
        $flushProse();

        if (count($mergedOriginSets) !== count($merged)) {
            // Provenance is an authorization sidecar, never a recovery hint.
            // Any alignment defect must leave natural merged text untouched.
            return $merged;
        }
        $originOutputCounts = [];
        foreach ($mergedOriginSets as $originSet) {
            if (!is_array($originSet)) {
                continue;
            }
            foreach ($originSet as $originDigest => $_) {
                $originOutputCounts[$originDigest] = ($originOutputCounts[$originDigest] ?? 0) + 1;
            }
        }
        foreach ($merged as $lineIndex => $line) {
            $originSet = $mergedOriginSets[$lineIndex] ?? null;
            if (!is_array($originSet) || count($originSet) !== 1) {
                continue;
            }
            $originDigest = array_key_first($originSet);
            $targetText = is_string($originDigest)
                ? ($localLayoutLabelTextsByOrigin[$originDigest] ?? null)
                : null;
            if (is_string($targetText)
                && $targetText !== ''
                && ($originOutputCounts[$originDigest] ?? 0) === 1
                && $line === $targetText
                && !$this->pdfLineStartsWithSemanticPrefix($line)) {
                $merged[$lineIndex] = self::PDF_LAYOUT_LABEL_PREFIX . $line;
            }
        }

        if ($collectExactWholeSourceMergedLineSpans) {
            foreach ($merged as $lineIndex => $line) {
                $span = $this->repairedPdfExactWholeSourceMergedLineSpan(
                    $line,
                    $mergedOriginSets[$lineIndex] ?? null,
                    $exactWholeSourceReceiptsByOrigin,
                    $originOutputCounts
                );
                if ($span !== null) {
                    $exactWholeSourceMergedLineSpans[$lineIndex] = $span;
                }
            }
        }

        return $merged;
    }

    /** @param list<string> $lines */
    private function encodePdfLineBlock(array $lines): string
    {
        return self::PDF_LINE_BLOCK_PREFIX . json_encode(
            array_values($lines),
            JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_INVALID_UTF8_SUBSTITUTE
        );
    }

    /** @return list<string> */
    private function decodePdfLineBlock(string $encoded): array
    {
        if (!str_starts_with($encoded, self::PDF_LINE_BLOCK_PREFIX)) {
            return [];
        }
        $decoded = json_decode(substr($encoded, strlen(self::PDF_LINE_BLOCK_PREFIX)), true);
        if (!is_array($decoded)) {
            return [];
        }

        return array_values(array_filter(
            array_map(
                fn (mixed $line): string => is_string($line)
                    ? trim($this->pdfTextWithoutSemanticPrefixes($line))
                    : '',
                $decoded
            ),
            static fn (string $line): bool => $line !== ''
        ));
    }

    /**
     * @param array<string,mixed> $record
     * @return array<string,true>|null
     */
    private function repairedPdfMergeOriginSetForRecord(array $record): ?array
    {
        $originSet = $record['sourcePdfMergeOriginSet'] ?? null;
        if (is_string($originSet)) {
            return preg_match('/^[a-f0-9]{64}$/D', $originSet) === 1
                ? [$originSet => true]
                : null;
        }
        if (!is_array($originSet) || $originSet === []) {
            return null;
        }
        foreach ($originSet as $originDigest => $present) {
            if (!is_string($originDigest)
                || preg_match('/^[a-f0-9]{64}$/D', $originDigest) !== 1
                || $present !== true) {
                return null;
            }
        }
        ksort($originSet, SORT_STRING);

        return $originSet;
    }

    /**
     * @param array<string,true>|null $left
     * @param array<string,true>|null $right
     * @return array<string,true>|null
     */
    private function repairedPdfMergeOriginSetsUnion(?array $left, ?array $right): ?array
    {
        if ($left === null || $right === null) {
            return null;
        }
        $union = $left + $right;
        ksort($union, SORT_STRING);

        return $union;
    }

    /**
     * @param list<array<string,mixed>> $records
     * @return array<string,true>|null
     */
    private function repairedPdfMergeOriginSetForRecords(array $records): ?array
    {
        $originSet = [];
        foreach ($records as $record) {
            $originSet = $this->repairedPdfMergeOriginSetsUnion(
                $originSet,
                $this->repairedPdfMergeOriginSetForRecord($record)
            );
            if ($originSet === null) {
                return null;
            }
        }

        return $originSet;
    }

    /**
     * Build a narrow late-merge receipt only when every contributing record
     * was independently validated as one whole immutable source occurrence,
     * each occurrence contributes once, and their source indexes are unique
     * and consecutive in the emitted order.
     *
     * @param array<string,true>|null $originSet
     * @param array<string,array{
     *   recordIndex:int,
     *   sourceOccurrenceIds:list<string>,
     *   globalSourceIndexes:list<int>,
     *   projection:string
     * }> $receiptsByOrigin
     * @param array<string,int> $originOutputCounts
     * @return array<string,mixed>|null
     */
    private function repairedPdfExactWholeSourceMergedLineSpan(
        string $line,
        ?array $originSet,
        array $receiptsByOrigin,
        array $originOutputCounts
    ): ?array {
        if ($originSet === [] || $originSet === null) {
            return null;
        }
        $receipts = [];
        foreach ($originSet as $originDigest => $present) {
            $receipt = is_string($originDigest)
                ? ($receiptsByOrigin[$originDigest] ?? null)
                : null;
            if ($present !== true
                || !is_array($receipt)
                || ($originOutputCounts[$originDigest] ?? 0) !== 1) {
                return null;
            }
            $receipts[] = $receipt;
        }
        usort(
            $receipts,
            static fn (array $left, array $right): int =>
                $left['recordIndex'] <=> $right['recordIndex']
        );

        $sourceOccurrenceIds = [];
        $globalSourceIndexes = [];
        $projection = '';
        $seenSourceIds = [];
        foreach ($receipts as $receipt) {
            $receiptSourceIds = isset($receipt['sourceOccurrenceId'])
                ? [$receipt['sourceOccurrenceId']]
                : ($receipt['sourceOccurrenceIds'] ?? null);
            $receiptGlobalIndexes = isset($receipt['globalSourceIndex'])
                ? [$receipt['globalSourceIndex']]
                : ($receipt['globalSourceIndexes'] ?? null);
            $part = $receipt['projection'] ?? null;
            if (!is_array($receiptSourceIds)
                || !array_is_list($receiptSourceIds)
                || $receiptSourceIds === []
                || !is_array($receiptGlobalIndexes)
                || !array_is_list($receiptGlobalIndexes)
                || count($receiptGlobalIndexes) !== count($receiptSourceIds)
                || !is_string($part)
                || $part === '') {
                return null;
            }
            foreach ($receiptSourceIds as $receiptIndex => $sourceId) {
                $globalSourceIndex = $receiptGlobalIndexes[$receiptIndex] ?? null;
                $previousGlobalIndex = $globalSourceIndexes === []
                    ? null
                    : $globalSourceIndexes[array_key_last($globalSourceIndexes)];
                if (!is_string($sourceId)
                    || $sourceId === ''
                    || isset($seenSourceIds[$sourceId])
                    || !is_int($globalSourceIndex)
                    || $globalSourceIndex < 0
                    || ($previousGlobalIndex !== null
                        && $globalSourceIndex !== $previousGlobalIndex + 1)) {
                    return null;
                }
                $seenSourceIds[$sourceId] = true;
                $sourceOccurrenceIds[] = $sourceId;
                $globalSourceIndexes[] = $globalSourceIndex;
            }
            $projection .= $part;
        }
        $lineProjection = $this->pdfSourceOccurrenceComparableText(
            $this->pdfTextWithoutSemanticPrefixes($line)
        );
        if ($projection === ''
            || $lineProjection === ''
            || !hash_equals($projection, $lineProjection)) {
            return null;
        }

        $span = [
            'version' => 1,
            'method' => 'exact-consecutive-whole-source-merged-line',
            'sourceSha256' => $this->sourceSha256,
            'sourceOccurrenceIds' => $sourceOccurrenceIds,
            'globalSourceIndexes' => $globalSourceIndexes,
            'projectionDigest' => hash('sha256', $lineProjection),
        ];
        $span['proofDigest'] = hash('sha256', json_encode(
            $span,
            JSON_UNESCAPED_SLASHES
                | JSON_UNESCAPED_UNICODE
                | JSON_PRESERVE_ZERO_FRACTION
        ) ?: '');

        return $span;
    }

    private function repairedPdfMergedLineHasExactWholeSourceSpan(
        string $line,
        mixed $span
    ): bool {
        if (!is_array($span)
            || ($span['version'] ?? null) !== 1
            || ($span['method'] ?? null) !== 'exact-consecutive-whole-source-merged-line'
            || !is_string($span['sourceSha256'] ?? null)
            || preg_match('/^[a-f0-9]{64}$/D', $span['sourceSha256']) !== 1
            || preg_match('/^[a-f0-9]{64}$/D', $this->sourceSha256) !== 1
            || !hash_equals($this->sourceSha256, $span['sourceSha256'])
            || !is_array($span['sourceOccurrenceIds'] ?? null)
            || !array_is_list($span['sourceOccurrenceIds'])
            || $span['sourceOccurrenceIds'] === []
            || count(array_unique($span['sourceOccurrenceIds'], SORT_STRING))
                !== count($span['sourceOccurrenceIds'])
            || !is_array($span['globalSourceIndexes'] ?? null)
            || !array_is_list($span['globalSourceIndexes'])
            || count($span['globalSourceIndexes']) !== count($span['sourceOccurrenceIds'])
            || !is_string($span['projectionDigest'] ?? null)
            || preg_match('/^[a-f0-9]{64}$/D', $span['projectionDigest']) !== 1
            || !is_string($span['proofDigest'] ?? null)
            || preg_match('/^[a-f0-9]{64}$/D', $span['proofDigest']) !== 1) {
            return false;
        }
        foreach ($span['sourceOccurrenceIds'] as $sourceId) {
            if (!is_string($sourceId) || $sourceId === '') {
                return false;
            }
        }
        foreach ($span['globalSourceIndexes'] as $index => $globalSourceIndex) {
            if (!is_int($globalSourceIndex)
                || $globalSourceIndex < 0
                || ($index > 0
                    && $globalSourceIndex !== $span['globalSourceIndexes'][$index - 1] + 1)) {
                return false;
            }
        }
        $projection = $this->pdfSourceOccurrenceComparableText(
            $this->pdfTextWithoutSemanticPrefixes($line)
        );
        if ($projection === ''
            || !hash_equals($span['projectionDigest'], hash('sha256', $projection))) {
            return false;
        }
        $payload = $span;
        unset($payload['proofDigest']);

        return hash_equals($span['proofDigest'], hash('sha256', json_encode(
            $payload,
            JSON_UNESCAPED_SLASHES
                | JSON_UNESCAPED_UNICODE
                | JSON_PRESERVE_ZERO_FRACTION
        ) ?: ''));
    }

    /**
     * @param list<array{text: string, layout: array{text: string, page: int, x1: float, y1: float, x2: float, y2: float, fontSize: float}|null}> $records
     * @param list<array<string,true>|null>|null $outputOriginSets
     * @return list<string>
     */
    private function mergeRepairedProseLinesPreservingStackedTables(
        array $records,
        ?array &$outputOriginSets = null
    ): array
    {
        $merged = [];
        $outputOriginSets = [];
        $pending = [];
        $sideTableCarriesByContinuationIndex = [];
        $texts = array_map(static fn (array $record): string => $record['text'], $records);
        for ($index = 0, $count = count($records); $index < $count;) {
            if (isset($sideTableCarriesByContinuationIndex[$index])) {
                $carry = $sideTableCarriesByContinuationIndex[$index];
                $records[$index]['text'] = rtrim($carry['tail'])
                    . ' '
                    . ltrim($records[$index]['text']);
                $records[$index]['sourcePdfMergeOriginSet'] =
                    $this->repairedPdfMergeOriginSetsUnion(
                        $this->repairedPdfMergeOriginSetForRecord($records[$index]),
                        $carry['originSet']
                    );
                $texts[$index] = $records[$index]['text'];
            }
            $stackedTable = $this->stackedTableRowsAt($texts, $index);
            if ($stackedTable['rows'] === []) {
                $pending[] = $records[$index];
                $index++;
                continue;
            }

            $sideTableCarry = $pending !== []
                ? $this->repairedPdfExactSideTableContinuationCarry(
                    $pending,
                    $records,
                    $index,
                    $stackedTable['consumed']
                )
                : null;
            $sideTableCarryOriginSet = $sideTableCarry !== null
                ? $this->repairedPdfMergeOriginSetForRecords($pending)
                : null;
            if ($sideTableCarry !== null) {
                $pending[array_key_last($pending)]['text'] = $sideTableCarry['prefix'];
            }
            if ($pending !== []) {
                $pendingOutputOriginSets = [];
                foreach ($this->mergeRepairedProseLines(
                    $pending,
                    $records[$index],
                    $pendingOutputOriginSets
                ) as $lineIndex => $line) {
                    $merged[] = $line;
                    $outputOriginSets[] = $pendingOutputOriginSets[$lineIndex] ?? null;
                }
                $pending = [];
            }
            for ($offset = 0; $offset < $stackedTable['consumed']; $offset++) {
                $merged[] = $records[$index + $offset]['text'];
                $outputOriginSets[] = $this->repairedPdfMergeOriginSetForRecord(
                    $records[$index + $offset]
                );
            }
            $index += $stackedTable['consumed'];
            if ($sideTableCarry !== null) {
                $sideTableCarriesByContinuationIndex[$sideTableCarry['continuationRecordIndex']] = [
                    'tail' => $sideTableCarry['tail'],
                    'originSet' => $sideTableCarryOriginSet,
                ];
            }
        }
        if ($pending !== []) {
            $pendingOutputOriginSets = [];
            foreach ($this->mergeRepairedProseLines(
                $pending,
                null,
                $pendingOutputOriginSets
            ) as $lineIndex => $line) {
                $merged[] = $line;
                $outputOriginSets[] = $pendingOutputOriginSets[$lineIndex] ?? null;
            }
        }

        return $merged;
    }

    /**
     * Consume only the occurrence-local proof stamped before semantic
     * normalization. The table and every intervening source carrier must
     * still form one exact, consecutive range, so a merely similar sentence
     * elsewhere on the page cannot borrow this cross-column continuation.
     *
     * @param list<array{text:string,layout:array<string,mixed>|null}> $pending
     * @param list<array{text:string,layout:array<string,mixed>|null}> $records
     * @return array{prefix:string,tail:string,continuationRecordIndex:int}|null
     */
    private function repairedPdfExactSideTableContinuationCarry(
        array $pending,
        array $records,
        int $tableRecordIndex,
        int $tableRecordCount
    ): ?array {
        $previousRecord = $pending[array_key_last($pending)] ?? null;
        $previousLayout = is_array($previousRecord['layout'] ?? null)
            ? $previousRecord['layout']
            : null;
        $proof = is_array($previousLayout['sourcePdfExactSideTableContinuationAfter'] ?? null)
            ? $previousLayout['sourcePdfExactSideTableContinuationAfter']
            : null;
        if (!is_array($previousRecord)
            || !is_array($previousLayout)
            || $proof === null
            || !$this->repairedPdfExactSideTableContinuationProofIsValid($proof)
            || $tableRecordCount !== $proof['tableSourceEnd'] - $proof['tableSourceStart'] + 1
            || !$this->repairedPdfRecordMatchesExactSideTableSourceOccurrence(
                $previousRecord,
                $proof['previousSourceIndex'],
                $proof['page'],
                $proof['stream'],
                $proof['previousProjectionDigest'],
                $proof['previousGeometryDigest']
            )) {
            return null;
        }

        $tail = $this->sourcePdfExactSideTableContinuationTail(
            (string) ($previousRecord['text'] ?? '')
        );
        if ($tail === null
            || !hash_equals(
                $proof['tailProjectionDigest'],
                hash('sha256', $this->pdfSourceOccurrenceComparableText($tail['tail']))
            )) {
            return null;
        }

        $candidateRecordIndexes = [];
        $searchStart = $tableRecordIndex + $tableRecordCount;
        $searchEnd = min(count($records) - 1, $searchStart + 7);
        for ($candidateRecordIndex = $searchStart + 2; $candidateRecordIndex <= $searchEnd; $candidateRecordIndex++) {
            $candidateRecord = $records[$candidateRecordIndex] ?? null;
            $candidateLayout = is_array($candidateRecord['layout'] ?? null)
                ? $candidateRecord['layout']
                : null;
            $beforeProof = is_array($candidateLayout['sourcePdfExactSideTableContinuationBefore'] ?? null)
                ? $candidateLayout['sourcePdfExactSideTableContinuationBefore']
                : null;
            if (!is_array($candidateRecord)
                || !is_array($candidateLayout)
                || $beforeProof !== $proof
                || !$this->repairedPdfRecordMatchesExactSideTableContinuationEndpoint(
                    $candidateRecord,
                    $proof['continuationExactRanges'],
                    $proof['page'],
                    $proof['stream'],
                    $proof['continuationProjectionDigest'],
                    $proof['continuationGeometryDigest']
                )) {
                continue;
            }
            $candidateRecordIndexes[] = $candidateRecordIndex;
        }
        if (count($candidateRecordIndexes) !== 1) {
            return null;
        }

        $candidateRecordIndex = $candidateRecordIndexes[0];
        $expectedSourceIndex = $proof['tableSourceStart'];
        for ($recordIndex = $tableRecordIndex; $recordIndex <= $candidateRecordIndex; $recordIndex++) {
            $record = $records[$recordIndex] ?? null;
            if ($recordIndex === $candidateRecordIndex) {
                $expectedSourceIndex = $proof['continuationSourceEnd'] + 1;
                continue;
            }
            if (!is_array($record)
                || !$this->repairedPdfRecordMatchesExactSideTableSourceOccurrence(
                    $record,
                    $expectedSourceIndex,
                    $proof['page'],
                    $proof['stream']
                )) {
                return null;
            }
            $expectedSourceIndex++;
        }
        if ($expectedSourceIndex - 1 !== $proof['continuationSourceEnd']) {
            return null;
        }

        $candidatePredecessor = $records[$candidateRecordIndex - 1] ?? null;
        if (!is_array($candidatePredecessor)
            || !$this->repairedPdfRecordMatchesExactSideTableSourceOccurrence(
                $candidatePredecessor,
                $proof['candidatePredecessorSourceIndex'],
                $proof['page'],
                $proof['stream']
            )
            || preg_match('/[.!?]\s*$/u', rtrim((string) ($candidatePredecessor['text'] ?? ''))) !== 1) {
            return null;
        }

        return [
            'prefix' => $tail['prefix'],
            'tail' => $tail['tail'],
            'continuationRecordIndex' => $candidateRecordIndex,
        ];
    }

    /** @param array<string,mixed> $proof */
    private function repairedPdfExactSideTableContinuationProofIsValid(array $proof): bool
    {
        foreach ([
            'sourceSha256',
            'previousProjectionDigest',
            'tailProjectionDigest',
            'continuationProjectionDigest',
            'previousGeometryDigest',
            'continuationGeometryDigest',
            'proofDigest',
        ] as $digestKey) {
            if (!is_string($proof[$digestKey] ?? null)
                || preg_match('/^[a-f0-9]{64}$/D', $proof[$digestKey]) !== 1) {
                return false;
            }
        }
        foreach ([
            'page',
            'stream',
            'previousSourceIndex',
            'tableSourceStart',
            'tableSourceEnd',
            'candidatePredecessorSourceIndex',
            'continuationSourceIndex',
            'continuationSourceEnd',
        ] as $integerKey) {
            if (!is_int($proof[$integerKey] ?? null)) {
                return false;
            }
        }
        if (($proof['version'] ?? null) !== 3
            || ($proof['method'] ?? null) !== 'exact-source-side-table-continuation'
            || !hash_equals($this->sourceSha256, $proof['sourceSha256'])
            || $proof['page'] < 1
            || $proof['stream'] < 1
            || $proof['tableSourceStart'] !== $proof['previousSourceIndex'] + 1
            || $proof['tableSourceEnd'] < $proof['tableSourceStart']
            || $proof['candidatePredecessorSourceIndex'] < $proof['tableSourceEnd'] + 2
            || $proof['continuationSourceIndex'] !== $proof['candidatePredecessorSourceIndex'] + 1
            || $proof['continuationSourceEnd'] < $proof['continuationSourceIndex']
            || $proof['continuationSourceIndex'] > $proof['tableSourceEnd'] + 8) {
            return false;
        }
        $continuationExactRanges = $proof['continuationExactRanges'] ?? null;
        if (!is_array($continuationExactRanges)
            || !array_is_list($continuationExactRanges)
            || count($continuationExactRanges)
                !== $proof['continuationSourceEnd'] - $proof['continuationSourceIndex'] + 1) {
            return false;
        }
        foreach ($continuationExactRanges as $offset => $range) {
            if (!is_array($range)
                || array_keys($range) !== [
                    'sourceIndex',
                    'sourceStart',
                    'sourceEnd',
                    'projectionDigest',
                ]
                || !is_int($range['sourceIndex'] ?? null)
                || $range['sourceIndex'] !== $proof['continuationSourceIndex'] + $offset
                || ($range['sourceStart'] ?? null) !== 0
                || !is_int($range['sourceEnd'] ?? null)
                || $range['sourceEnd'] <= 0
                || !is_string($range['projectionDigest'] ?? null)
                || preg_match('/^[a-f0-9]{64}$/D', $range['projectionDigest']) !== 1) {
                return false;
            }
        }

        $payload = [
            'version' => 3,
            'method' => 'exact-source-side-table-continuation',
            'sourceSha256' => $proof['sourceSha256'],
            'page' => $proof['page'],
            'stream' => $proof['stream'],
            'previousSourceIndex' => $proof['previousSourceIndex'],
            'tableSourceStart' => $proof['tableSourceStart'],
            'tableSourceEnd' => $proof['tableSourceEnd'],
            'candidatePredecessorSourceIndex' => $proof['candidatePredecessorSourceIndex'],
            'continuationSourceIndex' => $proof['continuationSourceIndex'],
            'continuationSourceEnd' => $proof['continuationSourceEnd'],
            'previousProjectionDigest' => $proof['previousProjectionDigest'],
            'tailProjectionDigest' => $proof['tailProjectionDigest'],
            'continuationProjectionDigest' => $proof['continuationProjectionDigest'],
            'continuationExactRanges' => $continuationExactRanges,
            'previousGeometryDigest' => $proof['previousGeometryDigest'],
            'continuationGeometryDigest' => $proof['continuationGeometryDigest'],
        ];
        $expectedProofDigest = hash('sha256', json_encode(
            $payload,
            JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE
        ) ?: '');

        return hash_equals($proof['proofDigest'], $expectedProofDigest);
    }

    /**
     * @param array{text:string,layout:array<string,mixed>|null} $record
     */
    private function repairedPdfRecordMatchesExactSideTableContinuationEndpoint(
        array $record,
        array $exactRanges,
        int $page,
        int $stream,
        string $projectionDigest,
        string $geometryDigest
    ): bool {
        if ($exactRanges === [] || !array_is_list($exactRanges)) {
            return false;
        }
        $globalSourceStart = $exactRanges[0]['sourceIndex'] ?? null;
        $globalSourceEnd = $exactRanges[array_key_last($exactRanges)]['sourceIndex'] ?? null;
        if (!is_int($globalSourceStart) || !is_int($globalSourceEnd)) {
            return false;
        }
        if ($globalSourceStart === $globalSourceEnd) {
            $projection = $this->pdfSourceOccurrenceComparableText((string) ($record['text'] ?? ''));

            return ($exactRanges[0]['sourceStart'] ?? null) === 0
                && ($exactRanges[0]['sourceEnd'] ?? null) === strlen($projection)
                && is_string($exactRanges[0]['projectionDigest'] ?? null)
                && hash_equals($exactRanges[0]['projectionDigest'], hash('sha256', $projection))
                && $this->repairedPdfRecordMatchesExactSideTableSourceOccurrence(
                    $record,
                    $globalSourceStart,
                    $page,
                    $stream,
                    $projectionDigest,
                    $geometryDigest
                );
        }
        $layout = is_array($record['layout'] ?? null) ? $record['layout'] : null;
        if (!is_array($layout)
            || ($layout['sourcePdfExactRangeFragmentSequence'] ?? false) !== true
            || ($layout['sourcePdfExactPositionedText'] ?? false) !== true
            || (int) ($layout['page'] ?? 0) !== $page
            || (int) ($layout['sourceStream'] ?? 0) !== $stream
            || !$this->pdfLayoutHasGeometry($layout)) {
            return false;
        }
        $ranges = $this->pdfPositionedExactSourceRanges($layout);
        if (count($ranges) !== count($exactRanges)
            || array_values($layout['sourcePdfGlobalSourceIndexes'] ?? [])
                !== array_column($exactRanges, 'sourceIndex')) {
            return false;
        }
        $projection = $this->pdfSourceOccurrenceComparableText((string) ($record['text'] ?? ''));
        $coveredBytes = 0;
        foreach ($ranges as $offset => $range) {
            $expectedRange = $exactRanges[$offset] ?? null;
            if (!is_array($expectedRange)
                || $range !== [
                    'sourceIndex' => $expectedRange['sourceIndex'] ?? null,
                    'sourceStart' => $expectedRange['sourceStart'] ?? null,
                    'sourceEnd' => $expectedRange['sourceEnd'] ?? null,
                ]
                || !is_string($expectedRange['projectionDigest'] ?? null)) {
                return false;
            }
            $rangeLength = $range['sourceEnd'] - $range['sourceStart'];
            $rangeProjection = substr($projection, $coveredBytes, $rangeLength);
            if (strlen($rangeProjection) !== $rangeLength
                || !hash_equals(
                    $expectedRange['projectionDigest'],
                    hash('sha256', $rangeProjection)
                )) {
                return false;
            }
            $coveredBytes += $rangeLength;
        }
        if (strlen($projection) !== $coveredBytes
            || !hash_equals($projectionDigest, hash('sha256', $projection))) {
            return false;
        }
        $geometry = [
            'page' => $page,
            'stream' => $stream,
            'x1' => (float) $layout['x1'],
            'y1' => (float) $layout['y1'],
            'x2' => (float) $layout['x2'],
            'y2' => (float) $layout['y2'],
            'orientation' => 'horizontal',
        ];

        return hash_equals(
            $geometryDigest,
            $this->sourcePdfExactGeometryProofDigest($geometry)
        );
    }

    /**
     * @param array{text:string,layout:array<string,mixed>|null} $record
     */
    private function repairedPdfRecordMatchesExactSideTableSourceOccurrence(
        array $record,
        int $globalSourceIndex,
        int $page,
        int $stream,
        ?string $projectionDigest = null,
        ?string $geometryDigest = null
    ): bool {
        $layout = is_array($record['layout'] ?? null) ? $record['layout'] : null;
        $projection = $this->pdfSourceOccurrenceComparableText(
            (string) ($record['text'] ?? '')
        );
        $ranges = is_array($layout)
            ? $this->pdfPositionedExactSourceRanges($layout)
            : [];
        $geometry = is_array($layout['sourceGeometry'] ?? null)
            ? $layout['sourceGeometry']
            : null;
        if (!is_array($layout)
            || $projection === ''
            || !is_int($layout['sourcePdfGlobalSourceIndex'] ?? null)
            || $layout['sourcePdfGlobalSourceIndex'] !== $globalSourceIndex
            || (int) ($layout['page'] ?? 0) !== $page
            || (int) ($layout['sourceStream'] ?? 0) !== $stream
            || ($layout['sourceGeometryMethod'] ?? null) !== 'exact-page-stream-character-offset'
            || $geometry === null
            || !$this->pdfSourceBoundsAreValid($geometry)
            || ($geometry['orientation'] ?? null) !== 'horizontal'
            || (int) ($geometry['page'] ?? 0) !== $page
            || (int) ($geometry['stream'] ?? 0) !== $stream
            || count($ranges) !== 1
            || $ranges[0]['sourceIndex'] !== $globalSourceIndex
            || $ranges[0]['sourceStart'] !== 0
            || $ranges[0]['sourceEnd'] !== strlen($projection)) {
            return false;
        }
        if ($projectionDigest !== null
            && !hash_equals($projectionDigest, hash('sha256', $projection))) {
            return false;
        }

        return $geometryDigest === null
            || hash_equals($geometryDigest, $this->sourcePdfExactGeometryProofDigest($geometry));
    }

    /**
     * @param list<array{text: string, layout: array{text: string, page: int, x1: float, y1: float, x2: float, y2: float, fontSize: float}|null}> $records
     * @param array{text: string, layout: array<string, mixed>|null}|null $followingRecord
     * @param list<array<string,true>|null>|null $outputOriginSets
     * @return list<string>
     */
    private function mergeRepairedProseLines(
        array $records,
        ?array $followingRecord = null,
        ?array &$outputOriginSets = null
    ): array
    {
        $merged = [];
        $outputOriginSets = [];
        $pending = '';
        $pendingLayout = null;
        $pendingOriginSet = [];
        $pendingWholeExactPositionedCarrierProjection = null;
        foreach ($records as $record) {
            $line = $record['text'];
            $layout = $record['layout'];
            $lineOriginSet = $this->repairedPdfMergeOriginSetForRecord($record);
            $pendingOriginSetBeforeLine = $pendingOriginSet;
            $pendingWasEmpty = $pending === '';
            $mergedCountBeforeLine = count($merged);
            try {
            if ($line === '') {
                continue;
            }
            $lineWholeExactPositionedCarrierProjection = $this->repairedPdfWholeExactPositionedCarrierProjection(
                $line,
                $layout
            );
            if (($layout['sourcePdfDisplayHeading'] ?? false) === true) {
                if (($layout['sourcePdfFrontMatterRole'] ?? null) === 'title'
                    && ($pendingLayout['sourcePdfFrontMatterRole'] ?? null) === 'title'
                    && str_starts_with($pending, self::PDF_DISPLAY_HEADING_PREFIX)) {
                    $pending = self::PDF_DISPLAY_HEADING_PREFIX
                        . trim(substr($pending, strlen(self::PDF_DISPLAY_HEADING_PREFIX)))
                        . ' '
                        . ltrim($line);
                    // Both source carriers remain represented by the merge
                    // origin union. A multi-occurrence title is not one exact
                    // positioned carrier, so do not manufacture such a proof.
                    $pendingWholeExactPositionedCarrierProjection = null;
                    continue;
                }
                if ($pending !== '') {
                    $merged[] = $pending;
                }
                $pending = self::PDF_DISPLAY_HEADING_PREFIX . $line;
                $pendingLayout = $layout;
                $pendingWholeExactPositionedCarrierProjection = $lineWholeExactPositionedCarrierProjection;
                continue;
            }
            if ($pending === '') {
                $pending = $line;
                $pendingLayout = $layout;
                $pendingWholeExactPositionedCarrierProjection = $lineWholeExactPositionedCarrierProjection;
                continue;
            }
            if (($pendingLayout['sourcePdfDisplayHeading'] ?? false) === true) {
                $merged[] = $pending;
                $pending = $line;
                $pendingLayout = $layout;
                $pendingWholeExactPositionedCarrierProjection = $lineWholeExactPositionedCarrierProjection;
                continue;
            }
            if (($pendingLayout['sourcePdfFormTailEnd'] ?? false) === true) {
                // A source-proven form tail may consume wrapped text on its
                // left, but the field itself terminates that row. Keeping the
                // boundary directional prevents a final "$" field from
                // swallowing the next worksheet row or a following notice.
                $merged[] = $pending;
                $pending = $line;
                $pendingLayout = $layout;
                $pendingWholeExactPositionedCarrierProjection = $lineWholeExactPositionedCarrierProjection;
                continue;
            }
            if (trim($line) === '-'
                && $this->repairedPdfStandaloneWrappedWordHyphenAttachesToPrevious(
                    $pendingLayout,
                    $layout
            )) {
                $pending = rtrim($pending) . '-';
                $pendingWholeExactPositionedCarrierProjection = $this->repairedPdfJoinedWholeExactPositionedCarrierProjection(
                    $pendingWholeExactPositionedCarrierProjection,
                    $lineWholeExactPositionedCarrierProjection,
                    $pending
                );
                // The carrier owns the outgoing pair proof used to join the
                // exact lower-baseline continuation on the next iteration.
                $pendingLayout = $layout;
                continue;
            }
            if ($this->repairedPdfLayoutsHaveStandaloneWrappedWordHyphenPair(
                $pendingLayout,
                $layout
            )) {
                $pending = rtrim($pending) . ltrim($line);
                $pendingLayout = $layout;
                $pendingWholeExactPositionedCarrierProjection = $this->repairedPdfJoinedWholeExactPositionedCarrierProjection(
                    $pendingWholeExactPositionedCarrierProjection,
                    $lineWholeExactPositionedCarrierProjection,
                    $pending
                );
                continue;
            }
            if ($this->repairedPdfExactClosingDelimiterContinuesPrevious(
                $pending,
                $line,
                $pendingLayout,
                $layout
            )) {
                $pending = rtrim($pending) . trim($line);
                $pendingLayout = $layout;
                $pendingWholeExactPositionedCarrierProjection = $this->repairedPdfJoinedWholeExactPositionedCarrierProjection(
                    $pendingWholeExactPositionedCarrierProjection,
                    $lineWholeExactPositionedCarrierProjection,
                    $pending
                );
                continue;
            }
            if ($this->lineIsOnlyPdfNoise($pending) || $this->lineIsOnlyPdfNoise($line)) {
                // Punctuation-only syntax has no safe prose-join rule. Keep
                // the exact source record atomic so a closing delimiter does
                // not become either invisible or attached to unrelated prose.
                $merged[] = $pending;
                $pending = $line;
                $pendingLayout = $layout;
                $pendingWholeExactPositionedCarrierProjection = $lineWholeExactPositionedCarrierProjection;
                continue;
            }
            if ($this->pdfLayoutsFormInlineTerminalLead($pending, $line, $pendingLayout, $layout)) {
                $pending = rtrim($pending) . ' ' . ltrim($line);
                $pendingWholeExactPositionedCarrierProjection = $this->repairedPdfJoinedWholeExactPositionedCarrierProjection(
                    $pendingWholeExactPositionedCarrierProjection,
                    $lineWholeExactPositionedCarrierProjection,
                    $pending
                );
                // Keep the left-hand lead's geometry so its wrapped lines
                // still align with the paragraph's actual visual start.
                continue;
            }
            if ($this->lineLooksLikePdfReferenceEntry($pending)
                && !$this->lineLooksLikePdfReferenceEntry($line)) {
                $pendingBeforeDiscretionaryHyphenRemoval = null;
                if ($this->pdfReferenceEntryEndsWithUrl($pending)
                    && preg_match('/^[^\p{L}\p{N}]*\p{Lu}/u', ltrim($line)) === 1) {
                    $merged[] = $pending;
                    $pending = $line;
                    $pendingLayout = $layout;
                    $pendingWholeExactPositionedCarrierProjection = $lineWholeExactPositionedCarrierProjection;
                    continue;
                }
                if ($this->lineLooksLikeUrlOnly($line)
                    && preg_match('/-\s*$/u', $pending) === 1) {
                    $pending = rtrim($pending) . ' ' . ltrim($line);
                } elseif (preg_match('~(?:https?://|www\.)\S*-\s*$~iu', $pending) === 1
                    && preg_match('/^[A-Za-z0-9][A-Za-z0-9._~\/-]*/u', ltrim($line)) === 1) {
                    // The URL scheme/path and adjacent path-shaped source
                    // record are local syntactic evidence for continuation.
                    // Retain the painted hyphen because they do not prove it
                    // was merely discretionary.
                    $pending = rtrim($pending) . ltrim($line);
                } elseif (preg_match('/\x{00AD}\s*$/u', $pending) === 1
                    && $this->repairedPdfLayoutsHaveLocalWrappedSemanticHyphenPair($pendingLayout, $layout)) {
                    $pending = rtrim(preg_replace('/\x{00AD}\s*$/u', '-', $pending) ?? $pending) . ltrim($line);
                } elseif (preg_match('/[-\x{2010}\x{2011}]\s*$/u', $pending) === 1) {
                    if ($this->repairedLineShouldRemoveHyphenatedBreak($pending, $line, $pendingLayout, $layout)) {
                        $pendingBeforeDiscretionaryHyphenRemoval = $pending;
                        $pending = rtrim(preg_replace('/[-\x{2010}\x{2011}]\s*$/u', '', $pending) ?? rtrim(substr($pending, 0, -1))) . ltrim($line);
                    } elseif ($this->repairedPdfLayoutContinuesWrappedLine($pendingLayout, $layout)) {
                        $pending = rtrim($pending) . ' ' . ltrim($line);
                    } else {
                        $merged[] = $pending;
                        $pending = $line;
                        $pendingLayout = $layout;
                        $pendingWholeExactPositionedCarrierProjection = $lineWholeExactPositionedCarrierProjection;
                        continue;
                    }
                } elseif (preg_match('/(?:https?:\/\/|www\.)\S*-\s*$/i', $pending) === 1
                    && preg_match('/^[A-Za-z0-9]/', ltrim($line)) === 1) {
                    $pending = rtrim($pending) . ltrim($line);
                } else {
                    $pending = rtrim($pending) . ' ' . ltrim($line);
                }
                $pendingWholeExactPositionedCarrierProjection =
                    $pendingBeforeDiscretionaryHyphenRemoval !== null
                    ? $this->repairedPdfJoinedWholeExactPositionedCarrierProjectionAfterDiscretionaryHyphenRemoval(
                        $pendingWholeExactPositionedCarrierProjection,
                        $lineWholeExactPositionedCarrierProjection,
                        $pending,
                        $pendingBeforeDiscretionaryHyphenRemoval,
                        $line,
                        $pendingLayout,
                        $layout
                    )
                    : $this->repairedPdfJoinedWholeExactPositionedCarrierProjection(
                        $pendingWholeExactPositionedCarrierProjection,
                        $lineWholeExactPositionedCarrierProjection,
                        $pending
                    );
                $pendingLayout = $layout;
                continue;
            }
            if (($layout['forceBlockBreakBefore'] ?? false) === true) {
                if ($this->repairedPdfForcedBoundaryContinuesWrappedText($pending, $line, $pendingLayout, $layout)) {
                    $pendingBeforeDiscretionaryHyphenRemoval = null;
                    if (preg_match('/\x{00AD}\s*$/u', $pending) === 1) {
                        if ($this->repairedPdfLayoutsHaveLocalWrappedSemanticHyphenPair($pendingLayout, $layout)) {
                            $pending = rtrim(preg_replace('/\x{00AD}\s*$/u', '-', $pending) ?? $pending) . ltrim($line);
                        } else {
                            $pending = $this->repairedPdfLayoutsHaveLocalWrappedHyphenPair($pendingLayout, $layout)
                                ? rtrim(preg_replace('/\x{00AD}\s*$/u', '', $pending) ?? $pending) . ltrim($line)
                                : rtrim($pending) . ' ' . ltrim($line);
                        }
                    } elseif (preg_match('/[-\x{2010}\x{2011}]\s*$/u', $pending) === 1) {
                        $removedDiscretionaryHyphen = $this->repairedLineShouldRemoveHyphenatedBreak(
                            $pending,
                            $line,
                            $pendingLayout,
                            $layout
                        );
                        if ($removedDiscretionaryHyphen) {
                            $pendingBeforeDiscretionaryHyphenRemoval = $pending;
                        }
                        $pending = $removedDiscretionaryHyphen
                            ? rtrim(preg_replace('/[-\x{2010}\x{2011}]\s*$/u', '', $pending) ?? rtrim(substr($pending, 0, -1))) . ltrim($line)
                            : rtrim($pending) . ' ' . ltrim($line);
                    } else {
                        $pending = rtrim($pending) . ' ' . ltrim($line);
                    }
                    $pendingWholeExactPositionedCarrierProjection =
                        $pendingBeforeDiscretionaryHyphenRemoval !== null
                        ? $this->repairedPdfJoinedWholeExactPositionedCarrierProjectionAfterDiscretionaryHyphenRemoval(
                            $pendingWholeExactPositionedCarrierProjection,
                            $lineWholeExactPositionedCarrierProjection,
                            $pending,
                            $pendingBeforeDiscretionaryHyphenRemoval,
                            $line,
                            $pendingLayout,
                            $layout
                        )
                        : $this->repairedPdfJoinedWholeExactPositionedCarrierProjection(
                            $pendingWholeExactPositionedCarrierProjection,
                            $lineWholeExactPositionedCarrierProjection,
                            $pending
                        );
                    $pendingLayout = $layout;
                    continue;
                }
                if (($layout['sourceSupplementalRecoverableSentenceSuffix'] ?? false) === true
                    && preg_match('/:\s*$/u', $pending) === 1) {
                    // The following positioned record began with an omitted
                    // formula or diagram prefix. Its colon introduced that
                    // display content, so preserve a readable sentence once
                    // the independently recoverable prose suffix starts.
                    $pending = rtrim(preg_replace('/:\s*$/u', '.', $pending) ?? $pending);
                    $pendingWholeExactPositionedCarrierProjection = null;
                }
                $pending = $this->trimIncompletePdfTailBeforeForcedBlockBoundary(
                    $pending,
                    $line,
                    $pendingLayout,
                    $layout,
                    $pendingWholeExactPositionedCarrierProjection !== null
                );
                if ($pending !== '') {
                    $merged[] = $pending;
                }
                $pending = $line;
                $pendingLayout = $layout;
                $pendingWholeExactPositionedCarrierProjection = $lineWholeExactPositionedCarrierProjection;
                continue;
            }
            if (($layout['sourcePdfCrossPanelContinuation'] ?? false) === true) {
                $separator = preg_match('/^[\)\]\},.;:]/u', ltrim($line)) === 1
                    || preg_match('/[-\x{00AD}\x{2010}-\x{2015}]\s*$/u', $pending) === 1
                    ? ''
                    : ' ';
                $pending = rtrim($pending) . $separator . ltrim($line);
                $pendingLayout = $layout;
                $pendingWholeExactPositionedCarrierProjection = $this->repairedPdfJoinedWholeExactPositionedCarrierProjection(
                    $pendingWholeExactPositionedCarrierProjection,
                    $lineWholeExactPositionedCarrierProjection,
                    $pending
                );
                continue;
            }
            if (($layout['sourceSupplementalRecoverableSentenceSuffix'] ?? false) === true
                && preg_match('/:\s*$/u', $pending) === 1) {
                // A colon preceding a recoverable suffix introduced visual
                // formula/diagram content that is not safe body prose. End
                // the prior sentence before retaining the verified suffix.
                $merged[] = rtrim(preg_replace('/:\s*$/u', '.', $pending) ?? $pending);
                $pending = $line;
                $pendingLayout = $layout;
                $pendingWholeExactPositionedCarrierProjection = $lineWholeExactPositionedCarrierProjection;
                continue;
            }
            $numberedSubheading = $this->repairedPdfEqualFontOutdentedNumberedHeading(
                $pending,
                $line,
                $pendingLayout,
                $layout
            );
            if ($this->repairedPdfNumberedDisplayHeadingPrecedesBody($pending, $line, $pendingLayout, $layout)) {
                $merged[] = ($numberedSubheading
                    ? self::PDF_NUMBERED_SUBHEADING_PREFIX
                    : self::PDF_NUMBERED_HEADING_PREFIX) . $pending;
                $pending = $line;
                $pendingLayout = $layout;
                $pendingWholeExactPositionedCarrierProjection = $lineWholeExactPositionedCarrierProjection;
                continue;
            }
            if ($this->repairedPdfPageBoundaryLeavesUnresolvedTail($pending, $line, $pendingLayout, $layout)) {
                $pending = $this->trimIncompletePdfTailBeforeUnconfirmedPageBoundary(
                    $pending,
                    $line,
                    $pendingLayout,
                    $layout,
                    $pendingWholeExactPositionedCarrierProjection !== null
                );
                if ($pending !== '') {
                    $merged[] = $pending;
                }
                $pending = $line;
                $pendingLayout = $layout;
                $pendingWholeExactPositionedCarrierProjection = $lineWholeExactPositionedCarrierProjection;
                continue;
            }
            if ($this->repairedPdfSourceStreamStartsNewBlock($pending, $line, $pendingLayout, $layout)) {
                $tail = $pendingWholeExactPositionedCarrierProjection !== null
                    && $this->repairedPdfPendingEndsWithWholeExactPositionedCarrier(
                        $pending,
                        $pendingLayout
                    )
                    && $this->repairedPdfWholeExactSourceOccurrencesFormAdjacentPageBoundary(
                        $pending,
                        $line,
                        $pendingLayout,
                        $layout
                    )
                        ? $pending
                        : $this->repairedPdfSourceStreamTailText($pending);
                if ($tail !== '') {
                    $merged[] = $tail;
                }
                $pending = $line;
                $pendingLayout = $layout;
                $pendingWholeExactPositionedCarrierProjection = $lineWholeExactPositionedCarrierProjection;
                continue;
            }
            if (preg_match('/(?:https?:\/\/|www\.)\S*-\s*$/i', $pending) === 1 && preg_match('/^[A-Za-z0-9]/', ltrim($line)) === 1) {
                $pending = rtrim($pending) . ltrim($line);
                $pendingLayout = $layout;
                $pendingWholeExactPositionedCarrierProjection = $this->repairedPdfJoinedWholeExactPositionedCarrierProjection(
                    $pendingWholeExactPositionedCarrierProjection,
                    $lineWholeExactPositionedCarrierProjection,
                    $pending
                );
                continue;
            }
            // A soft hyphen is removed only when source/positioned matching
            // identified this exact wrapped pair. Otherwise keep it visible
            // and preserve the record boundary unless geometry proves flow.
            if (preg_match('/\x{00AD}\s*$/u', $pending) === 1) {
                if ($this->repairedPdfLayoutsHaveLocalWrappedSemanticHyphenPair($pendingLayout, $layout)) {
                    $pending = rtrim(preg_replace('/\x{00AD}\s*$/u', '-', $pending) ?? $pending) . ltrim($line);
                    $pendingLayout = $layout;
                    $pendingWholeExactPositionedCarrierProjection = $this->repairedPdfJoinedWholeExactPositionedCarrierProjection(
                        $pendingWholeExactPositionedCarrierProjection,
                        $lineWholeExactPositionedCarrierProjection,
                        $pending,
                        true
                    );
                    continue;
                }
                if ($this->repairedPdfLayoutsHaveLocalWrappedHyphenPair($pendingLayout, $layout)) {
                    $pending = rtrim(preg_replace('/\x{00AD}\s*$/u', '', $pending) ?? $pending) . ltrim($line);
                    $pendingLayout = $layout;
                    $pendingWholeExactPositionedCarrierProjection = $this->repairedPdfJoinedWholeExactPositionedCarrierProjection(
                        $pendingWholeExactPositionedCarrierProjection,
                        $lineWholeExactPositionedCarrierProjection,
                        $pending
                    );
                    continue;
                }
                if ($this->repairedPdfLayoutContinuesWrappedLine($pendingLayout, $layout)) {
                    $pending = rtrim($pending) . ' ' . ltrim($line);
                    $pendingLayout = $layout;
                    $pendingWholeExactPositionedCarrierProjection = $this->repairedPdfJoinedWholeExactPositionedCarrierProjection(
                        $pendingWholeExactPositionedCarrierProjection,
                        $lineWholeExactPositionedCarrierProjection,
                        $pending
                    );
                    continue;
                }
                $merged[] = $pending;
                $pending = $line;
                $pendingLayout = $layout;
                $pendingWholeExactPositionedCarrierProjection = $lineWholeExactPositionedCarrierProjection;
                continue;
            }
            // A dash separated from the preceding token is punctuation, not
            // a wrapped word fragment. Preserve its visible separator when
            // the next visual line begins; this fixes references and other
            // source text without treating URLs or names specially.
            if (preg_match('/\s[-\x{2010}\x{2011}]\s*$/u', $pending) === 1
                && $this->repairedPdfLayoutsHaveLocalTerminalDashSeparatorPair($pendingLayout, $layout)) {
                $pending = rtrim($pending) . ' ' . ltrim($line);
                $pendingLayout = $layout;
                $pendingWholeExactPositionedCarrierProjection = $this->repairedPdfJoinedWholeExactPositionedCarrierProjection(
                    $pendingWholeExactPositionedCarrierProjection,
                    $lineWholeExactPositionedCarrierProjection,
                    $pending
                );
                continue;
            }
            if (preg_match('/-\s*$/', $pending) === 1 && $this->lineLooksLikeUrlOnly($line)) {
                $pending = rtrim($pending) . ' ' . ltrim($line);
                $pendingLayout = $layout;
                $pendingWholeExactPositionedCarrierProjection = $this->repairedPdfJoinedWholeExactPositionedCarrierProjection(
                    $pendingWholeExactPositionedCarrierProjection,
                    $lineWholeExactPositionedCarrierProjection,
                    $pending
                );
                continue;
            }
            if (preg_match('/[-\x{2010}\x{2011}]\s*$/u', $pending) === 1) {
                if ($this->repairedLineShouldRemoveHyphenatedBreak($pending, $line, $pendingLayout, $layout)) {
                    $pendingBeforeDiscretionaryHyphenRemoval = $pending;
                    $pending = rtrim(preg_replace('/[-\x{2010}\x{2011}]\s*$/u', '', $pending) ?? rtrim(substr($pending, 0, -1))) . ltrim($line);
                    $pendingWholeExactPositionedCarrierProjection = $this->repairedPdfJoinedWholeExactPositionedCarrierProjectionAfterDiscretionaryHyphenRemoval(
                        $pendingWholeExactPositionedCarrierProjection,
                        $lineWholeExactPositionedCarrierProjection,
                        $pending,
                        $pendingBeforeDiscretionaryHyphenRemoval,
                        $line,
                        $pendingLayout,
                        $layout
                    );
                    $pendingLayout = $layout;
                    continue;
                }
                if ($this->repairedPdfLayoutContinuesWrappedLine($pendingLayout, $layout)
                    || $this->repairedPdfLayoutContinuesAcrossPageBoundary(
                        $pending,
                        $line,
                        $pendingLayout,
                        $layout
                    )) {
                    $pending = rtrim($pending) . ' ' . ltrim($line);
                    $pendingLayout = $layout;
                    $pendingWholeExactPositionedCarrierProjection = $this->repairedPdfJoinedWholeExactPositionedCarrierProjection(
                        $pendingWholeExactPositionedCarrierProjection,
                        $lineWholeExactPositionedCarrierProjection,
                        $pending
                    );
                    continue;
                }
                // Without a matched source/geometry pair, the dash may be a
                // semantic terminal character. Preserve both it and the
                // source record boundary rather than guessing a wrapped word.
                $merged[] = $pending;
                $pending = $line;
                $pendingLayout = $layout;
                $pendingWholeExactPositionedCarrierProjection = $lineWholeExactPositionedCarrierProjection;
                continue;
            }
            if ($this->repairedLineShouldStartNewBlock($pending, $line, $pendingLayout, $layout)) {
                $merged[] = $pending;
                $pending = $line;
                $pendingLayout = $layout;
                $pendingWholeExactPositionedCarrierProjection = $lineWholeExactPositionedCarrierProjection;
                continue;
            }
            $pending .= ' ' . $line;
            $pendingLayout = $layout;
            $pendingWholeExactPositionedCarrierProjection = $this->repairedPdfJoinedWholeExactPositionedCarrierProjection(
                $pendingWholeExactPositionedCarrierProjection,
                $lineWholeExactPositionedCarrierProjection,
                $pending
            );
            } finally {
                $newOutputCount = count($merged) - $mergedCountBeforeLine;
                for ($outputOffset = 0; $outputOffset < $newOutputCount; $outputOffset++) {
                    $outputOriginSets[] = $pendingOriginSetBeforeLine;
                }
                if ($line !== '') {
                    $currentLineBecamePending = $pendingWasEmpty
                        || $newOutputCount > 0
                        || ($pending === $line && $pendingLayout === $layout);
                    $pendingOriginSet = $currentLineBecamePending
                        ? $lineOriginSet
                        : $this->repairedPdfMergeOriginSetsUnion(
                            $pendingOriginSetBeforeLine,
                            $lineOriginSet
                        );
                }
            }
        }
        if ($pending !== '') {
            if ($followingRecord !== null) {
                $followingLayout = is_array($followingRecord['layout'] ?? null)
                    ? $followingRecord['layout']
                    : null;
                $pending = $this->trimIncompletePdfTailBeforeForcedBlockBoundary(
                    $pending,
                    (string) ($followingRecord['text'] ?? ''),
                    $pendingLayout,
                    $followingLayout,
                    $pendingWholeExactPositionedCarrierProjection !== null
                );
            }
            if ($pending !== '') {
                $merged[] = $pending;
                $outputOriginSets[] = $pendingOriginSet;
            }
        }

        return $merged;
    }

    /**
     * A closing delimiter can be painted as its own source occurrence beside
     * a subscript or other compact inline atom. Join it only when an unmatched
     * opener, two consecutive complete source occurrences, and their exact
     * character geometry all prove the local continuation. This narrow proof
     * runs before the generic punctuation-noise guard without weakening it.
     *
     * @param array<string, mixed>|null $previousLayout
     * @param array<string, mixed>|null $closingLayout
     */
    private function repairedPdfExactClosingDelimiterContinuesPrevious(
        string $pending,
        string $closing,
        ?array $previousLayout,
        ?array $closingLayout
    ): bool {
        $delimiter = trim($closing);
        $opener = match ($delimiter) {
            ')' => '(',
            ']' => '[',
            '}' => '{',
            '|' => '|',
            default => null,
        };
        if ($opener === null
            || ($delimiter === '|'
                ? substr_count($pending, '|') % 2 !== 1
                : substr_count($pending, $opener) <= substr_count($pending, $delimiter))) {
            return false;
        }

        $identity = function (?array $layout): ?array {
            $geometry = is_array($layout['sourceGeometry'] ?? null)
                ? $layout['sourceGeometry']
                : null;
            $globalSourceIndex = $layout['sourcePdfGlobalSourceIndex'] ?? null;
            $localSourceIndex = $layout['sourcePdfSourceIndex'] ?? null;
            $page = $layout['page'] ?? null;
            $stream = $layout['sourceStream'] ?? null;
            $text = (string) ($layout['text'] ?? '');
            $projection = $this->pdfSourceOccurrenceComparableText($text);
            $ranges = is_array($layout)
                ? $this->pdfPositionedExactSourceRanges($layout)
                : [];
            if (!is_array($layout)
                || ($layout['code'] ?? false) === true
                || isset($layout['sourcePdfTableGroup'])
                || isset($layout['sourcePdfLineOrientedGroup'])
                || !is_int($globalSourceIndex)
                || !is_int($localSourceIndex)
                || !is_int($page)
                || !is_int($stream)
                || $projection === ''
                || ($layout['sourceGeometryMethod'] ?? null) !== 'exact-page-stream-character-offset'
                || !is_array($geometry)
                || !$this->pdfSourceBoundsAreValid($geometry)
                || ($geometry['orientation'] ?? null) !== 'horizontal'
                || (int) ($geometry['page'] ?? 0) !== $page
                || (int) ($geometry['stream'] ?? 0) !== $stream
                || count($ranges) !== 1
                || $ranges[0] !== [
                    'sourceIndex' => $globalSourceIndex,
                    'sourceStart' => 0,
                    'sourceEnd' => strlen($projection),
                ]) {
                return null;
            }

            return [
                'globalSourceIndex' => $globalSourceIndex,
                'localSourceIndex' => $localSourceIndex,
                'page' => $page,
                'stream' => $stream,
                'geometry' => $geometry,
                'projection' => $projection,
            ];
        };

        $previous = $identity($previousLayout);
        $candidate = $identity($closingLayout);
        $pendingProjection = $this->pdfSourceOccurrenceComparableText(
            $this->pdfTextWithoutSemanticPrefixes($pending)
        );
        $closingProjection = $this->pdfSourceOccurrenceComparableText(
            $this->pdfTextWithoutSemanticPrefixes($closing)
        );
        if ($previous === null
            || $candidate === null
            || $pendingProjection === ''
            || $closingProjection === ''
            || !str_ends_with($pendingProjection, $previous['projection'])
            || !hash_equals($closingProjection, $candidate['projection'])
            || $candidate['globalSourceIndex'] !== $previous['globalSourceIndex'] + 1
            || $candidate['localSourceIndex'] !== $previous['localSourceIndex'] + 1
            || $candidate['page'] !== $previous['page']
            || $candidate['stream'] !== $previous['stream']) {
            return false;
        }

        $previousGeometry = $previous['geometry'];
        $candidateGeometry = $candidate['geometry'];
        $minimumHeight = min(
            (float) $previousGeometry['y2'] - (float) $previousGeometry['y1'],
            (float) $candidateGeometry['y2'] - (float) $candidateGeometry['y1']
        );
        $verticalOverlap = min(
            (float) $previousGeometry['y2'],
            (float) $candidateGeometry['y2']
        ) - max(
            (float) $previousGeometry['y1'],
            (float) $candidateGeometry['y1']
        );
        if ($minimumHeight <= 0.0
            || $verticalOverlap < $minimumHeight * 0.70
            || (float) $candidateGeometry['x1'] < (float) $previousGeometry['x1'] - 0.75
            || (float) $candidateGeometry['x1']
                > (float) $previousGeometry['x2'] + max(1.5, $minimumHeight * 0.25)
            || (float) $candidateGeometry['x2'] <= (float) $previousGeometry['x2'] + 0.25
            || (float) $candidateGeometry['x2'] - (float) $previousGeometry['x2']
                > max(12.0, $minimumHeight * 1.5)) {
            return false;
        }

        return true;
    }

    /**
     * @param array<string, mixed>|null $previousLayout
     * @param array<string, mixed>|null $hyphenLayout
     */
    private function repairedPdfStandaloneWrappedWordHyphenAttachesToPrevious(
        ?array $previousLayout,
        ?array $hyphenLayout
    ): bool {
        $evidence = is_array($hyphenLayout['sourcePdfStandaloneWrappedWordHyphenEvidence'] ?? null)
            ? $hyphenLayout['sourcePdfStandaloneWrappedWordHyphenEvidence']
            : null;
        if ($evidence === null
            || ($evidence['kind'] ?? null) !== 'exact-standalone-wrapped-word-hyphen'
            || (string) ($evidence['sourceSha256'] ?? '') !== $this->sourceSha256) {
            return false;
        }

        return is_string($previousLayout['id'] ?? null)
            && is_string($hyphenLayout['id'] ?? null)
            && hash_equals((string) $evidence['precedingId'], (string) $previousLayout['id'])
            && hash_equals((string) $evidence['hyphenId'], (string) $hyphenLayout['id']);
    }

    /**
     * @param array<string, mixed>|null $hyphenLayout
     * @param array<string, mixed>|null $followingLayout
     */
    private function repairedPdfLayoutsHaveStandaloneWrappedWordHyphenPair(
        ?array $hyphenLayout,
        ?array $followingLayout
    ): bool {
        $pair = $hyphenLayout['sourcePdfStandaloneWrappedWordHyphenPairAfter'] ?? null;
        $followingPair = $followingLayout['sourcePdfStandaloneWrappedWordHyphenPairBefore'] ?? null;

        return is_string($pair)
            && $pair !== ''
            && is_string($followingPair)
            && hash_equals($pair, $followingPair);
    }

    /**
     * Some positioned PDF sources mark each wrapped display line as a block
     * even though its alignment, line rhythm, and lower-case continuation
     * prove it is one visual phrase. Preserve that phrase before honoring the
     * ordinary forced block boundary. This is useful for wrapped titles and
     * quotations as well as regular prose.
     *
     * @param array<string, mixed>|null $previousLayout
     * @param array<string, mixed>|null $lineLayout
     */
    private function repairedPdfForcedBoundaryContinuesWrappedText(
        string $previous,
        string $line,
        ?array $previousLayout,
        ?array $lineLayout
    ): bool {
        $exactDirectionalHyphenPair = $this->repairedPdfLayoutsHaveExactDirectionalWrappedHyphenPair(
            $previousLayout,
            $lineLayout
        );
        if (!$this->pdfLayoutHasGeometry($previousLayout)
            || !$this->pdfLayoutHasGeometry($lineLayout)
            || ($previousLayout['page'] ?? null) !== ($lineLayout['page'] ?? null)
            || ($previousLayout['code'] ?? false) === true
            || ($lineLayout['code'] ?? false) === true
            || (!$exactDirectionalHyphenPair
                && ($this->lineHasPdfListBlockEvidence($previous)
                    || $this->lineHasPdfListBlockEvidence($line)))
            || preg_match('/[.!?;:]\s*$/u', rtrim($previous)) === 1
            || preg_match('/^[^\p{L}\p{N}]*\p{Ll}/u', ltrim($line)) !== 1) {
            return false;
        }

        $fontSize = max(1.0, (float) $previousLayout['fontSize'], (float) $lineLayout['fontSize']);
        // A source-overlap supplement can supply a clipped body-line suffix.
        // Its explicit source provenance and normal line rhythm are stronger
        // evidence than the display-font threshold used for ordinary callouts.
        $sourceSupplementalContinuation = ($lineLayout['sourceSupplementalPositioned'] ?? false) === true
            && ($lineLayout['sourceSupplementalSourceOverlap'] ?? false) === true
            && (($previousLayout['sourceVerifiedGeometryText'] ?? false) === true
                || isset($previousLayout['sourceStream']))
            && ($previousLayout['sourceDetachedDiagramEvidencePage'] ?? false) !== true
            && ($lineLayout['sourceDetachedDiagramEvidencePage'] ?? false) !== true;
        if ($fontSize < 12.0 && !$sourceSupplementalContinuation && !$exactDirectionalHyphenPair) {
            return false;
        }
        if (abs((float) $previousLayout['fontSize'] - (float) $lineLayout['fontSize']) > max(1.5, $fontSize * 0.25)) {
            return false;
        }
        $verticalStep = (float) $previousLayout['y1'] - (float) $lineLayout['y1'];
        if ($verticalStep < $fontSize * 0.30 || $verticalStep > $fontSize * 2.20) {
            return false;
        }

        return abs((float) $previousLayout['x1'] - (float) $lineLayout['x1']) <= max(16.0, $fontSize * 1.5);
    }

    /**
     * @param array<string, mixed>|null $previousLayout
     * @param array<string, mixed>|null $lineLayout
     */
    private function repairedPdfLayoutsHaveLocalWrappedHyphenPair(?array $previousLayout, ?array $lineLayout): bool
    {
        // A middle physical line can finish one wrapped word and begin the
        // next. Keep those two occurrence-local decisions directional so the
        // later pair cannot overwrite the prior line's incoming provenance.
        // The scalar fallback accepts records created by older in-memory
        // callers, while all source matching now emits the directional form.
        $pair = $previousLayout['sourcePdfWrappedHyphenPairAfter']
            ?? $previousLayout['sourcePdfWrappedHyphenPair']
            ?? null;
        $followingPair = $lineLayout['sourcePdfWrappedHyphenPairBefore']
            ?? $lineLayout['sourcePdfWrappedHyphenPair']
            ?? null;

        if (!is_string($pair)
            || $pair === ''
            || !is_string($followingPair)
            || !hash_equals($pair, $followingPair)) {
            return false;
        }
        $previousProof = is_array($previousLayout)
            ? ($previousLayout['sourcePdfWholeExactRangeWrappedHyphenProofAfter'] ?? null)
            : null;
        $followingProof = is_array($lineLayout)
            ? ($lineLayout['sourcePdfWholeExactRangeWrappedHyphenProofBefore'] ?? null)
            : null;
        if ($previousProof === null && $followingProof === null) {
            return true;
        }

        return $this->repairedPdfWholeExactRangeWrappedHyphenProofMatchesLayouts(
            $previousLayout,
            $lineLayout,
            $pair
        );
    }

    /**
     * @param array<string,mixed>|null $previousLayout
     * @param array<string,mixed>|null $followingLayout
     */
    private function repairedPdfWholeExactRangeWrappedHyphenProofMatchesLayouts(
        ?array $previousLayout,
        ?array $followingLayout,
        string $pair
    ): bool {
        if (!is_array($previousLayout) || !is_array($followingLayout)) {
            return false;
        }
        $previousProof = $previousLayout['sourcePdfWholeExactRangeWrappedHyphenProofAfter'] ?? null;
        $followingProof = $followingLayout['sourcePdfWholeExactRangeWrappedHyphenProofBefore'] ?? null;
        if (!is_array($previousProof)
            || !is_array($followingProof)
            || $previousProof !== $followingProof
            || ($previousProof['version'] ?? null) !== 1
            || ($previousProof['method'] ?? null) !== 'whole-exact-range-wrapped-hyphen-pair'
            || ($previousProof['sourceSha256'] ?? null) !== $this->sourceSha256
            || !is_int($previousProof['page'] ?? null)
            || !is_int($previousProof['stream'] ?? null)
            || !is_array($previousProof['previous'] ?? null)
            || !is_array($previousProof['following'] ?? null)
            || !is_string($previousProof['proofDigest'] ?? null)
            || preg_match('/^[a-f0-9]{64}$/D', $previousProof['proofDigest']) !== 1
            || !hash_equals(
                'whole-exact-range-wrapped-hyphen' . "\0" . $previousProof['proofDigest'],
                $pair
            )) {
            return false;
        }
        $payload = [
            'version' => 1,
            'method' => 'whole-exact-range-wrapped-hyphen-pair',
            'sourceSha256' => $previousProof['sourceSha256'],
            'page' => $previousProof['page'],
            'stream' => $previousProof['stream'],
            'previous' => $previousProof['previous'],
            'following' => $previousProof['following'],
        ];
        $expectedDigest = hash('sha256', json_encode(
            $payload,
            JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE
        ) ?: '');
        if (!hash_equals($previousProof['proofDigest'], $expectedDigest)) {
            return false;
        }
        $previousOccurrence = $previousProof['previous'];
        $followingOccurrence = $previousProof['following'];
        if (($previousOccurrence['page'] ?? null) !== $previousProof['page']
            || ($followingOccurrence['page'] ?? null) !== $previousProof['page']
            || ($previousOccurrence['stream'] ?? null) !== $previousProof['stream']
            || ($followingOccurrence['stream'] ?? null) !== $previousProof['stream']
            || !is_int($previousOccurrence['localSourceIndex'] ?? null)
            || !is_int($followingOccurrence['localSourceIndex'] ?? null)
            || $followingOccurrence['localSourceIndex']
                !== $previousOccurrence['localSourceIndex'] + 1
            || !is_int($previousOccurrence['globalSourceIndex'] ?? null)
            || !is_int($followingOccurrence['globalSourceIndex'] ?? null)
            || $followingOccurrence['globalSourceIndex']
                !== $previousOccurrence['globalSourceIndex'] + 1) {
            return false;
        }

        return $this->repairedPdfWholeExactRangeOccurrenceProofMatchesLayout(
            $previousOccurrence,
            $previousLayout
        ) && $this->repairedPdfWholeExactRangeOccurrenceProofMatchesLayout(
            $followingOccurrence,
            $followingLayout
        );
    }

    /**
     * @param array<string,mixed> $proof
     * @param array<string,mixed> $layout
     */
    private function repairedPdfWholeExactRangeOccurrenceProofMatchesLayout(
        array $proof,
        array $layout
    ): bool {
        $range = $proof['exactRange'] ?? null;
        if (($proof['version'] ?? null) !== 1
            || ($proof['method'] ?? null) !== 'whole-exact-range-source-geometry-occurrence'
            || ($proof['sourceSha256'] ?? null) !== $this->sourceSha256
            || !is_int($proof['page'] ?? null)
            || !is_int($proof['stream'] ?? null)
            || !is_int($proof['globalSourceIndex'] ?? null)
            || !is_int($proof['localSourceIndex'] ?? null)
            || !is_array($range)
            || $range !== [
                'sourceIndex' => $proof['globalSourceIndex'],
                'sourceStart' => 0,
                'sourceEnd' => $range['sourceEnd'] ?? null,
            ]
            || !is_int($range['sourceEnd'] ?? null)
            || $range['sourceEnd'] <= 0
            || !is_string($proof['projectionDigest'] ?? null)
            || preg_match('/^[a-f0-9]{64}$/D', $proof['projectionDigest']) !== 1
            || !is_string($proof['geometryDigest'] ?? null)
            || preg_match('/^[a-f0-9]{64}$/D', $proof['geometryDigest']) !== 1
            || !is_string($proof['proofDigest'] ?? null)
            || preg_match('/^[a-f0-9]{64}$/D', $proof['proofDigest']) !== 1) {
            return false;
        }
        $payload = [
            'version' => 1,
            'method' => 'whole-exact-range-source-geometry-occurrence',
            'sourceSha256' => $proof['sourceSha256'],
            'page' => $proof['page'],
            'stream' => $proof['stream'],
            'globalSourceIndex' => $proof['globalSourceIndex'],
            'localSourceIndex' => $proof['localSourceIndex'],
            'exactRange' => $range,
            'projectionDigest' => $proof['projectionDigest'],
            'geometryDigest' => $proof['geometryDigest'],
        ];
        $expectedDigest = hash('sha256', json_encode(
            $payload,
            JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE
        ) ?: '');
        $layoutRanges = $this->pdfPositionedExactSourceRanges($layout);
        $projection = $this->pdfSourceOccurrenceComparableText((string) ($layout['text'] ?? ''));
        if (!hash_equals($proof['proofDigest'], $expectedDigest)
            || (int) ($layout['page'] ?? 0) !== $proof['page']
            || (isset($layout['sourceStream'])
                && (int) $layout['sourceStream'] !== $proof['stream'])
            || (isset($layout['sourcePdfGlobalSourceIndex'])
                && $layout['sourcePdfGlobalSourceIndex'] !== $proof['globalSourceIndex'])
            || (isset($layout['sourcePdfSourceIndex'])
                && $layout['sourcePdfSourceIndex'] !== $proof['localSourceIndex'])
            || $layoutRanges !== [$range]
            || strlen($projection) !== $range['sourceEnd']
            || !hash_equals($proof['projectionDigest'], hash('sha256', $projection))
            || !$this->pdfLayoutHasGeometry($layout)) {
            return false;
        }
        $layoutGeometry = [
            'page' => $proof['page'],
            'stream' => $proof['stream'],
            'x1' => (float) $layout['x1'],
            'y1' => (float) $layout['y1'],
            'x2' => (float) $layout['x2'],
            'y2' => (float) $layout['y2'],
            'orientation' => 'horizontal',
        ];

        return hash_equals(
            $proof['geometryDigest'],
            $this->sourcePdfExactGeometryProofDigest($layoutGeometry)
        );
    }

    /**
     * Boundary preservation needs the current layouts to name the exact
     * directional source pair, not merely repeat the same opaque marker.
     * Older scalar markers may still guide ordinary dehyphenation, but they
     * cannot authorize retaining an otherwise incomplete paragraph tail.
     *
     * @param array<string,mixed>|null $previousLayout
     * @param array<string,mixed>|null $lineLayout
     */
    private function repairedPdfLayoutsHaveExactDirectionalWrappedHyphenPair(
        ?array $previousLayout,
        ?array $lineLayout
    ): bool {
        $pair = null;
        if ($this->repairedPdfLayoutsHaveLocalWrappedHyphenPair($previousLayout, $lineLayout)) {
            $pair = $previousLayout['sourcePdfWrappedHyphenPairAfter']
                ?? $previousLayout['sourcePdfWrappedHyphenPair']
                ?? null;
        } elseif ($this->repairedPdfLayoutsHaveLocalWrappedSemanticHyphenPair($previousLayout, $lineLayout)) {
            $pair = $previousLayout['sourcePdfWrappedSemanticHyphenPairAfter']
                ?? $previousLayout['sourcePdfWrappedSemanticHyphenPair']
                ?? null;
        }
        if (!is_string($pair)
            || $pair === ''
            || !is_array($previousLayout)
            || !is_array($lineLayout)) {
            return false;
        }
        if ($this->repairedPdfWholeExactRangeWrappedHyphenProofMatchesLayouts(
            $previousLayout,
            $lineLayout,
            $pair
        )) {
            return true;
        }
        if (!is_int($previousLayout['sourcePdfSourceIndex'] ?? null)
            || !is_int($lineLayout['sourcePdfSourceIndex'] ?? null)
            || (int) ($previousLayout['page'] ?? 0) < 1
            || (int) ($previousLayout['page'] ?? 0) !== (int) ($lineLayout['page'] ?? 0)
            || (int) ($previousLayout['sourceStream'] ?? 0) < 1
            || (int) ($previousLayout['sourceStream'] ?? 0)
                !== (int) ($lineLayout['sourceStream'] ?? 0)) {
            return false;
        }

        $expectedPair = (int) $previousLayout['page'] . "\0"
            . (int) $previousLayout['sourceStream'] . "\0"
            . $previousLayout['sourcePdfSourceIndex'] . "\0"
            . $lineLayout['sourcePdfSourceIndex'];

        return hash_equals($expectedPair, $pair);
    }

    /**
     * @param array<string, mixed>|null $previousLayout
     * @param array<string, mixed>|null $lineLayout
     */
    private function repairedPdfLayoutsHaveLocalWrappedSemanticHyphenPair(
        ?array $previousLayout,
        ?array $lineLayout
    ): bool {
        $pair = $previousLayout['sourcePdfWrappedSemanticHyphenPairAfter']
            ?? $previousLayout['sourcePdfWrappedSemanticHyphenPair']
            ?? null;
        $followingPair = $lineLayout['sourcePdfWrappedSemanticHyphenPairBefore']
            ?? $lineLayout['sourcePdfWrappedSemanticHyphenPair']
            ?? null;

        if (!is_string($pair)
            || $pair === ''
            || !is_string($followingPair)
            || !hash_equals($pair, $followingPair)) {
            return false;
        }
        $previousProof = is_array($previousLayout)
            ? ($previousLayout['sourcePdfWholeExactRangeWrappedHyphenProofAfter'] ?? null)
            : null;
        $followingProof = is_array($lineLayout)
            ? ($lineLayout['sourcePdfWholeExactRangeWrappedHyphenProofBefore'] ?? null)
            : null;
        if ($previousProof === null && $followingProof === null) {
            return true;
        }

        return $this->repairedPdfWholeExactRangeWrappedHyphenProofMatchesLayouts(
            $previousLayout,
            $lineLayout,
            $pair
        );
    }

    /**
     * @param array<string, mixed>|null $previousLayout
     * @param array<string, mixed>|null $lineLayout
     */
    private function repairedPdfLayoutsHaveLocalTerminalDashSeparatorPair(?array $previousLayout, ?array $lineLayout): bool
    {
        $pair = $previousLayout['sourcePdfTerminalDashSeparatorPairAfter']
            ?? $previousLayout['sourcePdfTerminalDashSeparatorPair']
            ?? null;
        $followingPair = $lineLayout['sourcePdfTerminalDashSeparatorPairBefore']
            ?? $lineLayout['sourcePdfTerminalDashSeparatorPair']
            ?? null;

        return is_string($pair) && $pair !== '' && $pair === $followingPair;
    }

    /**
     * @param array{text: string, page: int, x1: float, y1: float, x2: float, y2: float, fontSize: float}|null $previousLayout
     * @param array{text: string, page: int, x1: float, y1: float, x2: float, y2: float, fontSize: float}|null $lineLayout
     */
    private function repairedLineShouldRemoveHyphenatedBreak(
        string $previous,
        string $line,
        ?array $previousLayout,
        ?array $lineLayout
    ): bool
    {
        // A hyphen at the end of an explicit URL is URL syntax, not a word
        // break. Keep it at this adjacent continuation boundary before the
        // exact source/positioned pair below considers ordinary wrapped prose.
        if (preg_match('~(?:https?://|www\.)\S*-\s*$~iu', $previous) === 1
            && preg_match('/^[A-Za-z0-9]/u', ltrim($line)) === 1) {
            return false;
        }

        // The marker is attached while source and positioned records still
        // identify this exact adjacent line pair. Never infer the decision
        // from a matching token elsewhere in the final prose stream.
        if ($this->repairedPdfLayoutsHaveLocalWrappedHyphenPair($previousLayout, $lineLayout)) {
            return true;
        }

        // A matching line rhythm can prove that two records continue, but it
        // cannot prove whether a painted hard hyphen is discretionary or
        // semantic. Only the occurrence-local source/positioned pair above
        // authorizes deleting it; callers may still join the records while
        // retaining the hyphen when geometry proves continuity.
        return false;
    }

    /**
     * @param array{text: string, page: int, x1: float, y1: float, x2: float, y2: float, fontSize: float}|null $previousLayout
     * @param array{text: string, page: int, x1: float, y1: float, x2: float, y2: float, fontSize: float}|null $lineLayout
     */
    private function repairedLineShouldStartNewBlock(string $previous, string $line, ?array $previousLayout = null, ?array $lineLayout = null): bool
    {
        if ($previousLayout !== null && $lineLayout !== null
            && isset($previousLayout['page'], $lineLayout['page'])
            && $previousLayout['page'] !== $lineLayout['page']) {
            return !$this->repairedPdfLayoutContinuesAcrossPageBoundary($previous, $line, $previousLayout, $lineLayout);
        }
        if (($lineLayout['forceBlockBreakBefore'] ?? false) === true) {
            return true;
        }
        if ($this->repairedPdfAdjacentSourceContinuationAcrossRegions($previous, $line, $previousLayout, $lineLayout)) {
            return false;
        }
        if ($this->repairedPdfSourceStreamStartsNewBlock($previous, $line, $previousLayout, $lineLayout)) {
            return true;
        }
        if ($this->lineHasPdfListBlockEvidence($line)) {
            return true;
        }
        if ($this->repairedPdfLayoutContinuesAcrossColumnBoundary($previous, $line, $previousLayout, $lineLayout)) {
            return false;
        }
        if ($this->repairedPdfLayoutStartsNewBlock($previousLayout, $lineLayout)) {
            return true;
        }
        if ($previousLayout === null && $lineLayout === null) {
            $previousLetters = preg_replace('/[^\p{L}\p{M}]+/u', '', trim($previous)) ?? '';
            if ($previousLetters !== ''
                && $this->length($previousLetters) <= 2
                && preg_match('/^[\p{L}\p{M}]+$/u', trim($previous)) === 1) {
                // With no occurrence geometry, a compact standalone record
                // might be a real word ("We") or a detached label, and there
                // is no evidence that it is the prefix of the next record.
                // Preserve the boundary without promoting the fragment to a
                // heading; looksLikeHeading() applies the stricter label gate.
                return true;
            }
        }
        // A title-like capitalized phrase can be ordinary prose at the start
        // of a wrapped visual line. When geometry keeps it in the same body
        // lane and the preceding line is unfinished, preserve that flow
        // before applying lexical heading heuristics.
        if (!$this->repairedLineLooksLikeSectionLabel($previous)
            && count($this->pdfLineWordTokens($previous)) >= 4
            && preg_match('/[.!?;:]\s*$/u', rtrim($previous)) !== 1
            && $this->repairedPdfLayoutContinuesWrappedLine($previousLayout, $lineLayout)) {
            return false;
        }
        if ($this->repairedLineLooksLikeSectionLabel($previous)) {
            if ($this->repairedSectionLabelContinuesOnNextVisualLine($previous, $line, $previousLayout, $lineLayout)) {
                return false;
            }
            return true;
        }
        if ($this->repairedLineLooksLikeSectionLabel($line)) {
            if ($this->repairedSectionLabelContinuesOnNextVisualLine($previous, $line, $previousLayout, $lineLayout)) {
                return false;
            }
            return true;
        }
        if ($this->lineHasPdfListBlockEvidence($previous) && !$this->lineHasPdfListBlockEvidence($line)) {
            if (preg_match('/[.!?]\s*$/u', $previous) !== 1 && preg_match('/^\p{Ll}/u', $line) === 1) {
                return false;
            }
            if ($previousLayout === null && $lineLayout === null && preg_match('/[.!?]\s*$/u', $previous) === 1 && preg_match('/^\p{Lu}/u', $line) === 1) {
                return true;
            }
            if ($this->repairedPdfLayoutLeavesListItem($previousLayout, $lineLayout)) {
                return true;
            }
        }
        if ($this->repairedPdfLayoutContinuesWrappedLine($previousLayout, $lineLayout)) {
            return false;
        }
        if ($this->looksLikeRepairedPdfTitle($this->repairGluedProseLine($previous))) {
            return true;
        }
        if ($previousLayout === null && $lineLayout === null && $this->lineEndsWithUrl($previous)) {
            return true;
        }

        $wordCount = str_word_count($line);
        if ($wordCount <= 6 && preg_match('/^[A-Z0-9][A-Za-z0-9,;:() \-]+$/', $line) === 1 && preg_match('/[.!?]$/', $previous) === 1) {
            return true;
        }
        if (preg_match('/[.!?]$/', $previous) === 1 && preg_match('/^[A-Z]/', $line) === 1 && $wordCount <= 10) {
            return true;
        }

        return false;
    }

    /**
     * Some maps and multi-panel handouts paint the continuation of one source
     * sentence in a distant panel. Preserve it only when consecutive source
     * records, matching font metrics, and lower-case syntax jointly prove the
     * flow. This excludes detached diagram labels and ordinary column order.
     *
     * @param array<string, mixed>|null $previousLayout
     * @param array<string, mixed>|null $lineLayout
     */
    private function repairedPdfAdjacentSourceContinuationAcrossRegions(
        string $previous,
        string $line,
        ?array $previousLayout,
        ?array $lineLayout
    ): bool {
        if (!$this->pdfLayoutHasGeometry($previousLayout)
            || !$this->pdfLayoutHasGeometry($lineLayout)
            || ($previousLayout['page'] ?? null) !== ($lineLayout['page'] ?? null)
            || ($previousLayout['sourceStream'] ?? null) !== ($lineLayout['sourceStream'] ?? null)
            || !isset($previousLayout['sourcePdfSourceIndex'], $lineLayout['sourcePdfSourceIndex'])
            || ($previousLayout['sourceVerifiedGeometryText'] ?? false) !== true
            || ($lineLayout['sourceVerifiedGeometryText'] ?? false) !== true
            || ($previousLayout['sourceDetachedDiagramEvidencePage'] ?? false) === true
            || ($lineLayout['sourceDetachedDiagramEvidencePage'] ?? false) === true
            || ($previousLayout['code'] ?? false) === true
            || ($lineLayout['code'] ?? false) === true) {
            return false;
        }

        $previousEnd = (int) ($previousLayout['sourcePdfSourceIndexEnd'] ?? $previousLayout['sourcePdfSourceIndex']);
        if ((int) $lineLayout['sourcePdfSourceIndex'] !== $previousEnd + 1) {
            return false;
        }

        $previous = rtrim($previous);
        $line = ltrim($line);
        if ($previous === '' || $line === ''
            || preg_match('/[.!?;:]\s*$/u', $previous) === 1
            || preg_match('/^[^\p{L}\p{N}]*\p{Ll}/u', $line) !== 1
            || $this->lineHasPdfListBlockEvidence($previous)
            || $this->lineHasPdfListBlockEvidence($line)
            || count($this->pdfLineWordTokens($previous)) < 4
            || count($this->pdfLineWordTokens($line)) < 4
            || $this->repairedPdfLayoutContinuesWrappedLine($previousLayout, $lineLayout)) {
            return false;
        }

        $fontSize = max(1.0, (float) $previousLayout['fontSize'], (float) $lineLayout['fontSize']);
        if (abs((float) $previousLayout['fontSize'] - (float) $lineLayout['fontSize']) > max(1.25, $fontSize * 0.20)) {
            return false;
        }

        return abs((float) $previousLayout['x1'] - (float) $lineLayout['x1']) > max(24.0, $fontSize * 3.0)
            || abs((float) $previousLayout['y1'] - (float) $lineLayout['y1']) > max(24.0, $fontSize * 3.0);
    }

    /**
     * Separate source content streams often correspond to adjacent visual
     * regions. Without usable coordinates, a stream transition can still
     * prove that an uppercase fresh line must not be appended to an unfinished
     * sentence from a different region. Lowercase and hyphenated continuations
     * remain eligible for the normal wrapped-line merge.
     *
     * @param array<string, mixed>|null $previousLayout
     * @param array<string, mixed>|null $lineLayout
     */
    private function repairedPdfSourceStreamStartsNewBlock(
        string $previous,
        string $line,
        ?array $previousLayout,
        ?array $lineLayout
    ): bool {
        if ($this->pdfLayoutHasGeometry($previousLayout) || $this->pdfLayoutHasGeometry($lineLayout)) {
            return false;
        }
        if ($previousLayout === null || $lineLayout === null
            || !isset($previousLayout['sourceStream'], $lineLayout['sourceStream'])) {
            return false;
        }
        if (($previousLayout['page'] ?? null) !== ($lineLayout['page'] ?? null)) {
            return true;
        }
        if ((int) $previousLayout['sourceStream'] === (int) $lineLayout['sourceStream']) {
            return false;
        }

        $previous = rtrim($previous);
        $line = ltrim($line);
        if ($previous === '' || $line === '' || preg_match('/[-\x{2010}-\x{2015}]$/u', $previous) === 1) {
            return false;
        }
        if (preg_match('/[.!?]\s*$/u', $previous) === 1) {
            return true;
        }

        return preg_match('/^[^\p{L}\p{N}]*\p{Lu}/u', $line) === 1;
    }

    /**
     * A compact numbered display heading can sit immediately above its body
     * text in the same source stream. Preserve that visual boundary before
     * line merging so block parsing does not mistake the result for a list.
     *
     * @param array<string, mixed>|null $previousLayout
     * @param array<string, mixed>|null $lineLayout
     */
    private function repairedPdfNumberedDisplayHeadingPrecedesBody(
        string $previous,
        string $line,
        ?array $previousLayout,
        ?array $lineLayout
    ): bool {
        if (!$this->pdfLayoutHasGeometry($previousLayout)
            || !$this->pdfLayoutHasGeometry($lineLayout)
            || ($previousLayout['page'] ?? null) !== ($lineLayout['page'] ?? null)
            || preg_match('/^\s*\d+(?:\.\d+)*(?:\.)?\s+\p{Lu}/u', $previous) !== 1
            || preg_match('/[.!?;:]\s*$/u', trim($previous)) === 1
            || count($this->pdfLineWordTokens($previous)) > 8
            || preg_match('/^[^\p{L}\p{N}]*\p{Lu}/u', ltrim($line)) !== 1
            || $this->lineHasPdfListBlockEvidence($line)) {
            return false;
        }

        $previousFont = max(1.0, (float) $previousLayout['fontSize']);
        $lineFont = max(1.0, (float) $lineLayout['fontSize']);
        if ($previousFont <= $lineFont * 1.10
            && !$this->repairedPdfEqualFontOutdentedNumberedHeading(
                $previous,
                $line,
                $previousLayout,
                $lineLayout
            )) {
            return false;
        }

        $verticalStep = (float) $previousLayout['y1'] - (float) $lineLayout['y1'];

        return $verticalStep >= $lineFont * 0.30
            && $verticalStep <= max(24.0, $previousFont * 2.5);
    }

    /**
     * Equal-font section labels are distinguishable from hanging list items
     * when the numbered all-caps display core is materially outdented from
     * the following sentence-case body lane.
     *
     * @param array<string,mixed>|null $previousLayout
     * @param array<string,mixed>|null $lineLayout
     */
    private function repairedPdfEqualFontOutdentedNumberedHeading(
        string $previous,
        string $line,
        ?array $previousLayout,
        ?array $lineLayout
    ): bool {
        if (!$this->pdfLayoutHasGeometry($previousLayout)
            || !$this->pdfLayoutHasGeometry($lineLayout)
            || ($previousLayout['page'] ?? null) !== ($lineLayout['page'] ?? null)
            || preg_match('/^\s*\d+(?:\.\d+)*(?:\.)?\s+\p{Lu}/u', $previous) !== 1
            || preg_match('/^[^\p{L}\p{N}]*\p{Lu}/u', ltrim($line)) !== 1
            || $this->lineHasPdfListBlockEvidence($line)) {
            return false;
        }
        $previousFont = max(1.0, (float) $previousLayout['fontSize']);
        $lineFont = max(1.0, (float) $lineLayout['fontSize']);
        $displayText = preg_replace(
            '/^\s*\d+(?:\.\d+)*(?:\.)?\s+/u',
            '',
            trim($previous)
        ) ?? '';
        $displayCore = preg_replace('/\s*\([^()]++\)\s*$/u', '', $displayText) ?? $displayText;
        $uppercaseLetters = preg_match_all('/\p{Lu}/u', $displayCore, $unusedUppercase);
        return abs($previousFont - $lineFont) <= max(0.75, $lineFont * 0.12)
            && (float) $lineLayout['x1'] - (float) $previousLayout['x1'] >= max(18.0, $lineFont * 2.0)
            && preg_match('/\p{Ll}/u', $displayCore) !== 1
            && $uppercaseLetters !== false
            && $uppercaseLetters >= 5
            && (!isset($previousLayout['sourceStream'], $lineLayout['sourceStream'])
                || (int) $previousLayout['sourceStream'] === (int) $lineLayout['sourceStream']);
    }

    private function repairedPdfSourceStreamTailText(string $text): string
    {
        $text = trim($text);
        if ($text === ''
            || $this->lineHasPdfListBlockEvidence($text)
            || $this->lineLooksLikeUrlOnly($text)
            || $this->repairedLineLooksLikeSectionLabel($text)
            || $this->looksLikeRepairedPdfTitle($this->repairGluedProseLine($text))
            || count($this->pdfLineWordTokens($text)) < 14
            || preg_match('/[.!?;:]\s*$/u', $text) === 1
            || preg_match('/[-\x{00AD}\x{2010}-\x{2015}]\s*$/u', $text) === 1) {
            return $text;
        }

        $completePrefix = $this->completePdfSentencePrefix($text);
        if ($completePrefix !== '' && count($this->pdfLineWordTokens($completePrefix)) >= 5) {
            return $completePrefix;
        }

        return '';
    }

    /**
     * A forced visual boundary proves that the next record is an independent
     * block. If the preceding prose run has no terminal punctuation, its
     * missing continuation must not be emitted as a complete paragraph. Keep
     * any verified sentence prefix and otherwise omit only that unresolved
     * run. This relies on layout provenance, not vocabulary.
     *
     * @param array<string, mixed>|null $previousLayout
     * @param array<string, mixed>|null $followingLayout
     */
    private function trimIncompletePdfTailBeforeForcedBlockBoundary(
        string $previous,
        string $following,
        ?array $previousLayout,
        ?array $followingLayout,
        bool $previousIsWholeExactPositionedCarrierChain
    ): string {
        $previous = trim($previous);
        $following = ltrim($following);
        if ($previous === ''
            || !$this->pdfLayoutHasGeometry($previousLayout)
            || !$this->pdfLayoutHasGeometry($followingLayout)
            || ($previousLayout['sourceStructuredGeometry'] ?? false) !== true
            || ($followingLayout['sourceStructuredGeometry'] ?? false) !== true
            || ($followingLayout['forceBlockBreakBefore'] ?? false) !== true
            || ($previousLayout['code'] ?? false) === true
            || ($followingLayout['code'] ?? false) === true
            || $this->lineHasPdfListBlockEvidence($previous)
            || $this->lineLooksLikeUrlOnly($previous)
            || $this->repairedLineLooksLikeSectionLabel($previous)
            || preg_match('/[.!?;:]\s*$/u', $previous) === 1
            || preg_match('/[-\x{00AD}\x{2010}-\x{2015}]\s*$/u', $previous) === 1
            || ($following !== ''
                && preg_match('/^[^\p{L}\p{N}]*\p{Ll}/u', $following) === 1
                && !$this->repairedLineLooksLikeSectionLabel($following))) {
            return $previous;
        }

        if ($previousIsWholeExactPositionedCarrierChain
            && $this->repairedPdfPendingEndsWithWholeExactPositionedCarrier(
            $previous,
            $previousLayout
        )) {
            // The forced boundary can prove that the next visual block is
            // independent, but it cannot invalidate a source occurrence whose
            // entire significant byte range was matched exactly in positioned
            // text. Preserve that terminal carrier even when it is an
            // unfinished suffix of a larger pending paragraph.
            return $previous;
        }

        $prefix = $this->completePdfSentencePrefix($previous);
        if ($prefix !== '' && count($this->pdfLineWordTokens($prefix)) >= 5) {
            return $prefix;
        }

        return count($this->pdfLineWordTokens($previous)) >= 5 ? '' : $previous;
    }

    /** @param array<string, mixed>|null $layout */
    private function repairedPdfWholeExactPositionedCarrierProjection(
        string $line,
        ?array $layout
    ): ?string {
        if (!$this->repairedPdfPendingEndsWithWholeExactPositionedCarrier($line, $layout)) {
            return null;
        }

        $lineProjection = $this->pdfSourceOccurrenceComparableText(
            $this->pdfTextWithoutSemanticPrefixes($line)
        );
        $layoutProjection = $this->pdfSourceOccurrenceComparableText(
            $this->pdfTextWithoutSemanticPrefixes((string) ($layout['text'] ?? ''))
        );

        return $lineProjection !== '' && hash_equals($layoutProjection, $lineProjection)
            ? $lineProjection
            : null;
    }

    private function repairedPdfJoinedWholeExactPositionedCarrierProjection(
        ?string $pendingProjection,
        ?string $lineProjection,
        string $pending
    ): ?string {
        if ($pendingProjection === null || $lineProjection === null) {
            return null;
        }

        $joinedProjection = $pendingProjection . $lineProjection;
        $actualProjection = $this->pdfSourceOccurrenceComparableText(
            $this->pdfTextWithoutSemanticPrefixes($pending)
        );

        return $actualProjection !== '' && hash_equals($joinedProjection, $actualProjection)
            ? $joinedProjection
            : null;
    }

    /**
     * Carry the ephemeral exact-source projection through the one-character
     * rewrite authorized by an exact directional discretionary-hyphen pair.
     * Immutable occurrence proofs remain raw, and every other character
     * mutation still invalidates the chain in the strict join helper.
     *
     * @param array<string,mixed>|null $pendingLayout
     * @param array<string,mixed>|null $lineLayout
     */
    private function repairedPdfJoinedWholeExactPositionedCarrierProjectionAfterDiscretionaryHyphenRemoval(
        ?string $pendingProjection,
        ?string $lineProjection,
        string $joinedPending,
        string $pendingBeforeJoin,
        string $line,
        ?array $pendingLayout,
        ?array $lineLayout
    ): ?string {
        if ($pendingProjection === null
            || $lineProjection === null
            || !$this->repairedPdfLayoutsHaveExactDirectionalWrappedHyphenPair(
                $pendingLayout,
                $lineLayout
            )
            || !$this->repairedLineShouldRemoveHyphenatedBreak(
                $pendingBeforeJoin,
                $line,
                $pendingLayout,
                $lineLayout
            )) {
            return null;
        }

        $removedCount = 0;
        $transformedPendingProjection = preg_replace(
            '/[-\x{2010}\x{2011}]$/u',
            '',
            $pendingProjection,
            1,
            $removedCount
        );
        if (!is_string($transformedPendingProjection) || $removedCount !== 1) {
            return null;
        }

        return $this->repairedPdfJoinedWholeExactPositionedCarrierProjection(
            $transformedPendingProjection,
            $lineProjection,
            $joinedPending
        );
    }

    /** @param array<string, mixed>|null $layout */
    private function repairedPdfPendingEndsWithWholeExactPositionedCarrier(
        string $pending,
        ?array $layout
    ): bool {
        if (!is_array($layout)
            || ($layout['sourceSupplementalPositioned'] ?? false) === true
            || ($layout['sourceShortSupplementalCandidate'] ?? false) === true
            || ($layout['sourceSupplementalRecoverableSentenceSuffix'] ?? false) === true) {
            return false;
        }

        $carrier = $this->pdfSourceOccurrenceComparableText(
            $this->pdfTextWithoutSemanticPrefixes((string) ($layout['text'] ?? ''))
        );
        if ($carrier === ''
            || (!$this->repairedPdfWholeExactOccurrenceProofMatchesLayout($layout, $carrier)
                && !$this->repairedPdfWholeExactSourceOccurrenceProofMatchesLayout(
                    $layout,
                    $carrier
                ))) {
            return false;
        }

        $pendingProjection = $this->pdfSourceOccurrenceComparableText(
            $this->pdfTextWithoutSemanticPrefixes($pending)
        );

        return $pendingProjection !== '' && str_ends_with($pendingProjection, $carrier);
    }

    /**
     * A native source-stream transition may preserve an unfinished page tail
     * only when the live carriers bind two consecutive immutable source
     * occurrences on adjacent physical pages. A copied receipt, skipped
     * occurrence, same-page stream change, or nonlocal page jump remains on
     * the conservative sentence-prefix path.
     *
     * @param array<string,mixed>|null $previousLayout
     * @param array<string,mixed>|null $followingLayout
     */
    private function repairedPdfWholeExactSourceOccurrencesFormAdjacentPageBoundary(
        string $previous,
        string $following,
        ?array $previousLayout,
        ?array $followingLayout
    ): bool {
        if (!is_array($previousLayout) || !is_array($followingLayout)) {
            return false;
        }
        $previousCarrier = $this->pdfSourceOccurrenceComparableText(
            $this->pdfTextWithoutSemanticPrefixes(
                (string) ($previousLayout['text'] ?? '')
            )
        );
        $followingCarrier = $this->pdfSourceOccurrenceComparableText(
            $this->pdfTextWithoutSemanticPrefixes(
                (string) ($followingLayout['text'] ?? '')
            )
        );
        $previousProjection = $this->pdfSourceOccurrenceComparableText(
            $this->pdfTextWithoutSemanticPrefixes($previous)
        );
        $followingProjection = $this->pdfSourceOccurrenceComparableText(
            $this->pdfTextWithoutSemanticPrefixes($following)
        );
        if ($previousCarrier === ''
            || $followingCarrier === ''
            || $previousProjection === ''
            || !str_ends_with($previousProjection, $previousCarrier)
            || !hash_equals($followingCarrier, $followingProjection)
            || !$this->repairedPdfWholeExactSourceOccurrenceProofMatchesLayout(
                $previousLayout,
                $previousCarrier
            )
            || !$this->repairedPdfWholeExactSourceOccurrenceProofMatchesLayout(
                $followingLayout,
                $followingCarrier
            )) {
            return false;
        }

        $previousProof = $previousLayout['sourcePdfWholeExactSourceOccurrenceProof'];
        $followingProof = $followingLayout['sourcePdfWholeExactSourceOccurrenceProof'];

        return $followingProof['globalSourceIndex']
                === $previousProof['globalSourceIndex'] + 1
            && $followingProof['page'] === $previousProof['page'] + 1
            && $followingProof['stream'] !== $previousProof['stream'];
    }

    /** @param array<string,mixed> $layout */
    private function repairedPdfWholeExactSourceOccurrenceProofMatchesLayout(
        array $layout,
        string $carrierProjection
    ): bool {
        $proof = is_array($layout['sourcePdfWholeExactSourceOccurrenceProof'] ?? null)
            ? $layout['sourcePdfWholeExactSourceOccurrenceProof']
            : null;
        $range = is_array($proof['exactRange'] ?? null) ? $proof['exactRange'] : null;
        if ($proof === null
            || ($proof['version'] ?? null) !== 1
            || ($proof['method'] ?? null)
                !== 'source-inventory-whole-source-occurrence'
            || !is_string($proof['sourceSha256'] ?? null)
            || preg_match('/^[a-f0-9]{64}$/D', $proof['sourceSha256']) !== 1
            || preg_match('/^[a-f0-9]{64}$/D', $this->sourceSha256) !== 1
            || !hash_equals($this->sourceSha256, $proof['sourceSha256'])
            || !is_string($proof['sourceOccurrenceId'] ?? null)
            || $proof['sourceOccurrenceId'] === ''
            || !is_int($proof['globalSourceIndex'] ?? null)
            || $proof['globalSourceIndex'] < 0
            || !is_int($proof['page'] ?? null)
            || $proof['page'] < 1
            || !is_int($proof['stream'] ?? null)
            || $proof['stream'] < 1
            || !is_array($range)
            || $range !== [
                'sourceIndex' => $proof['globalSourceIndex'],
                'sourceStart' => 0,
                'sourceEnd' => $range['sourceEnd'] ?? null,
            ]
            || !is_int($range['sourceEnd'] ?? null)
            || $range['sourceEnd'] < 1
            || !is_string($proof['projectionDigest'] ?? null)
            || preg_match('/^[a-f0-9]{64}$/D', $proof['projectionDigest']) !== 1
            || !is_string($proof['proofDigest'] ?? null)
            || preg_match('/^[a-f0-9]{64}$/D', $proof['proofDigest']) !== 1
            || ($layout['id'] ?? null) !== $proof['sourceOccurrenceId']
            || (int) ($layout['page'] ?? 0) !== $proof['page']
            || (int) ($layout['sourceStream'] ?? 0) !== $proof['stream']
            || (isset($layout['sourcePdfGlobalSourceIndex'])
                && $layout['sourcePdfGlobalSourceIndex'] !== $proof['globalSourceIndex'])
            || $this->pdfPositionedExactSourceRanges($layout) !== [$range]
            || strlen($carrierProjection) !== $range['sourceEnd']
            || !hash_equals(
                $proof['projectionDigest'],
                hash('sha256', $carrierProjection)
            )) {
            return false;
        }
        $payload = $proof;
        unset($payload['proofDigest']);

        return hash_equals($proof['proofDigest'], hash('sha256', json_encode(
            $payload,
            JSON_UNESCAPED_SLASHES
                | JSON_UNESCAPED_UNICODE
                | JSON_PRESERVE_ZERO_FRACTION
        ) ?: ''));
    }

    /** @param array<string,mixed> $layout */
    private function repairedPdfWholeExactOccurrenceProofMatchesLayout(
        array $layout,
        string $carrierProjection
    ): bool {
        $proof = is_array($layout['sourcePdfWholeExactOccurrenceProof'] ?? null)
            ? $layout['sourcePdfWholeExactOccurrenceProof']
            : null;
        if ($proof === null
            || ($proof['version'] ?? null) !== 1
            || ($proof['method'] ?? null) !== 'source-inventory-whole-occurrence-union'
            || !is_int($proof['page'] ?? null)
            || (!is_int($proof['layoutStream'] ?? null) && ($proof['layoutStream'] ?? null) !== null)
            || !is_array($proof['occurrences'] ?? null)
            || $proof['occurrences'] === []
            || !array_is_list($proof['occurrences'])
            || !is_array($proof['ranges'] ?? null)
            || !array_is_list($proof['ranges'])
            || !is_string($proof['projectionDigest'] ?? null)
            || !is_string($proof['proofDigest'] ?? null)
            || (int) ($layout['page'] ?? 0) !== $proof['page']
            || (is_int($proof['layoutStream'])
                && (int) ($layout['sourceStream'] ?? 0) !== $proof['layoutStream'])
            || !hash_equals($proof['projectionDigest'], hash('sha256', $carrierProjection))) {
            return false;
        }

        $proofOccurrences = array_values($proof['occurrences']);
        $ranges = [];
        $sourceIndexes = [];
        $coveredLength = 0;
        foreach ($proofOccurrences as $offset => $occurrence) {
            if (!is_array($occurrence)
                || !is_int($occurrence['sourceIndex'] ?? null)
                || !is_int($occurrence['sourceLocalIndex'] ?? null)
                || ($occurrence['page'] ?? null) !== $proof['page']
                || !is_int($occurrence['stream'] ?? null)
                || $occurrence['stream'] < 1
                || !is_int($occurrence['significantBytes'] ?? null)
                || $occurrence['significantBytes'] <= 0
                || !is_string($occurrence['significantDigest'] ?? null)
                || preg_match('/^[a-f0-9]{64}$/D', $occurrence['significantDigest']) !== 1
                || ($offset > 0
                    && ($occurrence['sourceIndex'] !== $sourceIndexes[$offset - 1] + 1
                        || $occurrence['sourceLocalIndex']
                            !== $proofOccurrences[$offset - 1]['sourceLocalIndex'] + 1))) {
                return false;
            }
            $occurrenceProjection = substr(
                $carrierProjection,
                $coveredLength,
                $occurrence['significantBytes']
            );
            if (strlen($occurrenceProjection) !== $occurrence['significantBytes']
                || !hash_equals(
                    $occurrence['significantDigest'],
                    hash('sha256', $occurrenceProjection)
                )) {
                return false;
            }
            $sourceIndexes[] = $occurrence['sourceIndex'];
            $coveredLength += $occurrence['significantBytes'];
            $ranges[] = [
                'sourceIndex' => $occurrence['sourceIndex'],
                'sourceStart' => 0,
                'sourceEnd' => $occurrence['significantBytes'],
            ];
        }
        if ($coveredLength !== strlen($carrierProjection)
            || array_values($proof['ranges']) !== $ranges
            || $this->pdfPositionedExactSourceRanges($layout) !== $ranges
            || (count($ranges) === 1
                && is_int($layout['sourcePdfGlobalSourceIndex'] ?? null)
                && $layout['sourcePdfGlobalSourceIndex'] !== $sourceIndexes[0])
            || (is_array($layout['sourcePdfGlobalSourceIndexes'] ?? null)
                && array_values($layout['sourcePdfGlobalSourceIndexes']) !== $sourceIndexes)) {
            return false;
        }

        $proofPayload = [
            'version' => 1,
            'method' => 'source-inventory-whole-occurrence-union',
            'page' => $proof['page'],
            'layoutStream' => $proof['layoutStream'],
            'occurrences' => $proofOccurrences,
            'ranges' => array_values($proof['ranges']),
            'projectionDigest' => $proof['projectionDigest'],
        ];
        $expectedProofDigest = hash('sha256', json_encode(
            $proofPayload,
            JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE
        ) ?: '');

        return hash_equals($proof['proofDigest'], $expectedProofDigest);
    }

    /**
     * A normal page-spanning paragraph is retained by the cross-page layout
     * continuation check. When that check fails, an unfinished structured
     * body tail cannot safely survive as its own paragraph: the next page may
     * begin with a figure, caption, or unrelated column. Keep only a verified
     * complete sentence prefix.
     *
     * @param array<string, mixed>|null $previousLayout
     * @param array<string, mixed>|null $followingLayout
     */
    private function repairedPdfPageBoundaryLeavesUnresolvedTail(
        string $previous,
        string $following,
        ?array $previousLayout,
        ?array $followingLayout
    ): bool {
        if (!$this->pdfLayoutHasGeometry($previousLayout)
            || !$this->pdfLayoutHasGeometry($followingLayout)
            || ($previousLayout['sourceStructuredGeometry'] ?? false) !== true
            || ($followingLayout['sourceStructuredGeometry'] ?? false) !== true
            || ($previousLayout['page'] ?? null) === ($followingLayout['page'] ?? null)) {
            return false;
        }

        return !$this->repairedPdfLayoutContinuesAcrossPageBoundary(
            $previous,
            $following,
            $previousLayout,
            $followingLayout
        );
    }

    /**
     * @param array<string, mixed>|null $previousLayout
     * @param array<string, mixed>|null $followingLayout
     */
    private function trimIncompletePdfTailBeforeUnconfirmedPageBoundary(
        string $previous,
        string $following,
        ?array $previousLayout,
        ?array $followingLayout,
        bool $previousIsWholeExactPositionedCarrierChain
    ): string {
        $previous = trim($previous);
        $following = ltrim($following);
        if ($previous === ''
            || !$this->repairedPdfPageBoundaryLeavesUnresolvedTail(
                $previous,
                $following,
                $previousLayout,
                $followingLayout
            )
            || ($previousLayout['code'] ?? false) === true
            || ($followingLayout['code'] ?? false) === true
            || $this->lineHasPdfListBlockEvidence($previous)
            || $this->lineLooksLikeUrlOnly($previous)
            || $this->repairedLineLooksLikeSectionLabel($previous)
            || preg_match('/[.!?;:]\s*$/u', $previous) === 1
            || preg_match('/[-\x{00AD}\x{2010}-\x{2015}]\s*$/u', $previous) === 1) {
            return $previous;
        }

        if ($previousIsWholeExactPositionedCarrierChain
            && $this->repairedPdfPendingEndsWithWholeExactPositionedCarrier(
                $previous,
                $previousLayout
            )) {
            // An unconfirmed page boundary separates independent blocks, but
            // it cannot erase an unfinished paragraph whose complete emitted
            // projection is an ordered chain of whole exact source ranges.
            return $previous;
        }

        $prefix = $this->completePdfSentencePrefix($previous);
        if ($prefix !== '' && count($this->pdfLineWordTokens($prefix)) >= 5) {
            return $prefix;
        }

        return count($this->pdfLineWordTokens($previous)) >= 5 ? '' : $previous;
    }

    /**
     * @param array<string, mixed>|null $layout
     */
    private function pdfLayoutHasGeometry(?array $layout): bool
    {
        if ($layout === null) {
            return false;
        }
        foreach (['x1', 'y1', 'x2', 'y2', 'fontSize'] as $key) {
            if (!isset($layout[$key]) || !is_numeric($layout[$key])) {
                return false;
            }
        }

        return true;
    }

    /**
     * @param array{text: string, page: int, x1: float, y1: float, x2: float, y2: float, fontSize: float}|null $previousLayout
     * @param array{text: string, page: int, x1: float, y1: float, x2: float, y2: float, fontSize: float}|null $lineLayout
     */
    private function repairedSectionLabelContinuesOnNextVisualLine(
        string $previous,
        string $line,
        ?array $previousLayout,
        ?array $lineLayout
    ): bool {
        if (!$this->repairedPdfLayoutContinuesWrappedLine($previousLayout, $lineLayout)) {
            return false;
        }
        if (preg_match('/^[^\p{L}\p{N}]*\p{Ll}/u', ltrim($line)) === 1
            && preg_match('/[.!?;:]\s*$/u', trim($previous)) !== 1) {
            return true;
        }
        $previousWords = $this->pdfLineWordTokens($previous);
        if (preg_match('/[.!?]\s*$/u', trim($previous)) === 1
            || count($previousWords) > 6
            || count($this->pdfLineWordTokens($previous . ' ' . $line)) > 9) {
            return false;
        }

        $previousWidth = max(1.0, $previousLayout['x2'] - $previousLayout['x1']);
        $lineWidth = max(1.0, $lineLayout['x2'] - $lineLayout['x1']);

        return $lineWidth <= $previousWidth * 1.35;
    }

    /**
     * A paragraph can continue from the bottom of the left body column to
     * the top of the right column. The large coordinate jump is expected in
     * that reading order, so preserve it only when the column provenance,
     * font metrics, and unfinished lower-case continuation all agree.
     *
     * @param array<string, mixed>|null $previousLayout
     * @param array<string, mixed>|null $lineLayout
     */
    private function repairedPdfLayoutContinuesAcrossColumnBoundary(
        string $previous,
        string $line,
        ?array $previousLayout,
        ?array $lineLayout
    ): bool {
        if (!$this->pdfLayoutHasGeometry($previousLayout) || !$this->pdfLayoutHasGeometry($lineLayout)
            || ($previousLayout['sourceStructuredGeometry'] ?? false) !== true
            || ($lineLayout['sourceStructuredGeometry'] ?? false) !== true
            || ($previousLayout['page'] ?? null) !== ($lineLayout['page'] ?? null)
            || !isset($previousLayout['sourceGeometryColumn'], $lineLayout['sourceGeometryColumn'])) {
            return false;
        }

        if ((int) $lineLayout['sourceGeometryColumn'] !== (int) $previousLayout['sourceGeometryColumn'] + 1) {
            return false;
        }

        $previous = rtrim($previous);
        $line = ltrim($line);
        if ($previous === '' || $line === ''
            || preg_match('/[.!?;:]\s*$/u', $previous) === 1
            || preg_match('/^[^\p{L}\p{N}]*\p{Ll}/u', $line) !== 1) {
            return false;
        }

        $fontSize = max(1.0, (float) $previousLayout['fontSize'], (float) $lineLayout['fontSize']);
        if (abs((float) $previousLayout['fontSize'] - (float) $lineLayout['fontSize']) > max(1.25, $fontSize * 0.20)) {
            return false;
        }

        return (float) $lineLayout['y1'] - (float) $previousLayout['y1'] > max(24.0, $fontSize * 3.0);
    }

    /**
     * A page break is normally a paragraph boundary, but a two-column flow
     * can end at the bottom of one page and continue at the top of the next.
     * Preserve that continuation only when the baseline positions, font, and
     * unfinished lower-case syntax all agree. This avoids joining unrelated
     * page headers or a new paragraph that merely happens to start lower-case.
     *
     * @param array<string, mixed>|null $previousLayout
     * @param array<string, mixed>|null $lineLayout
     */
    private function repairedPdfLayoutContinuesAcrossPageBoundary(
        string $previous,
        string $line,
        ?array $previousLayout,
        ?array $lineLayout
    ): bool {
        if (!$this->pdfLayoutHasGeometry($previousLayout) || !$this->pdfLayoutHasGeometry($lineLayout)
            || (int) ($lineLayout['page'] ?? 0) !== (int) ($previousLayout['page'] ?? 0) + 1) {
            return false;
        }

        $previous = rtrim($previous);
        $line = ltrim($line);
        if ($previous === '' || $line === ''
            || preg_match('/[.!?;:]\s*$/u', $previous) === 1
            || preg_match('/^[^\p{L}\p{N}]*\p{Ll}/u', $line) !== 1) {
            return false;
        }

        $fontSize = max(1.0, (float) $previousLayout['fontSize'], (float) $lineLayout['fontSize']);
        if (abs((float) $previousLayout['fontSize'] - (float) $lineLayout['fontSize']) > max(1.25, $fontSize * 0.20)) {
            return false;
        }

        return (float) $previousLayout['y1'] <= max(96.0, $fontSize * 12.0)
            && (float) $lineLayout['y1'] >= max(180.0, $fontSize * 20.0);
    }

    /**
     * @param array{text: string, page: int, x1: float, y1: float, x2: float, y2: float, fontSize: float}|null $previousLayout
     * @param array{text: string, page: int, x1: float, y1: float, x2: float, y2: float, fontSize: float}|null $lineLayout
     */
    private function repairedPdfLayoutStartsNewBlock(?array $previousLayout, ?array $lineLayout): bool
    {
        if (!$this->pdfLayoutHasGeometry($previousLayout) || !$this->pdfLayoutHasGeometry($lineLayout)) {
            return false;
        }
        if ($previousLayout['page'] !== $lineLayout['page']) {
            return true;
        }

        $previousHeight = max(1.0, $previousLayout['y2'] - $previousLayout['y1']);
        $lineHeight = max(1.0, $lineLayout['y2'] - $lineLayout['y1']);
        $referenceHeight = max($previousHeight, $lineHeight, $previousLayout['fontSize'], $lineLayout['fontSize'], 1.0);
        $verticalGap = $previousLayout['y1'] - $lineLayout['y2'];
        if ($verticalGap < -$referenceHeight * 1.5 || $verticalGap > $referenceHeight * 0.80) {
            return true;
        }

        $leftDelta = abs($previousLayout['x1'] - $lineLayout['x1']);
        if ($leftDelta > max(30.0, $referenceHeight * 3.0) && $verticalGap > $referenceHeight * 0.75) {
            return true;
        }

        // Text that starts far away on the same baseline, without sharing a
        // horizontal extent, belongs to a neighboring layout region. Keeping
        // it in the pending paragraph would splice columns, captions, or
        // samples into each other. Overlapping fragments remain eligible for
        // the ordinary same-line reconstruction path.
        $sameBaseline = abs((($previousLayout['y1'] + $previousLayout['y2']) / 2.0)
            - (($lineLayout['y1'] + $lineLayout['y2']) / 2.0)) <= max(2.0, $referenceHeight * 0.35);
        $horizontalOverlap = min($previousLayout['x2'], $lineLayout['x2'])
            - max($previousLayout['x1'], $lineLayout['x1']);
        if ($sameBaseline
            && $leftDelta > max(50.0, $referenceHeight * 4.0)
            && $horizontalOverlap <= max(2.0, $referenceHeight * 0.35)) {
            return true;
        }

        return false;
    }

    /**
     * @param array{text: string, page: int, x1: float, y1: float, x2: float, y2: float, fontSize: float}|null $previousLayout
     * @param array{text: string, page: int, x1: float, y1: float, x2: float, y2: float, fontSize: float}|null $lineLayout
     */
    private function repairedPdfLayoutContinuesWrappedLine(?array $previousLayout, ?array $lineLayout): bool
    {
        if (!$this->pdfLayoutHasGeometry($previousLayout) || !$this->pdfLayoutHasGeometry($lineLayout)
            || $previousLayout['page'] !== $lineLayout['page']) {
            return false;
        }

        $previousHeight = max(1.0, $previousLayout['y2'] - $previousLayout['y1']);
        $lineHeight = max(1.0, $lineLayout['y2'] - $lineLayout['y1']);
        $referenceHeight = max($previousHeight, $lineHeight, $previousLayout['fontSize'], $lineLayout['fontSize'], 1.0);
        $largerFont = max($previousLayout['fontSize'], $lineLayout['fontSize'], 1.0);
        $smallerFont = max(1.0, min($previousLayout['fontSize'], $lineLayout['fontSize']));
        if ($largerFont / $smallerFont > 1.35) {
            return false;
        }
        $verticalGap = $previousLayout['y1'] - $lineLayout['y2'];
        if ($verticalGap < -$referenceHeight * 0.4 || $verticalGap > $referenceHeight * 1.45) {
            return false;
        }

        // First lines are often indented while wrapped continuation lines
        // return to the column edge. Bibliographies additionally use a
        // hanging indent after the numbered marker. The source stream plus
        // reference provenance makes that wider allowance structural rather
        // than a guess based on the words themselves.
        $leftTolerance = max(16.0, $referenceHeight * 1.5);
        if (($previousLayout['sourcePdfReferenceEntry'] ?? false) === true
            && ($lineLayout['sourcePdfReferenceEntry'] ?? false) === true
            && isset($previousLayout['sourceStream'], $lineLayout['sourceStream'])
            && (int) $previousLayout['sourceStream'] === (int) $lineLayout['sourceStream']) {
            $leftTolerance = max($leftTolerance, 28.0, $referenceHeight * 3.5);
        }

        return abs($previousLayout['x1'] - $lineLayout['x1']) <= $leftTolerance;
    }

    /**
     * @param array{text: string, page: int, x1: float, y1: float, x2: float, y2: float, fontSize: float}|null $previousLayout
     * @param array{text: string, page: int, x1: float, y1: float, x2: float, y2: float, fontSize: float}|null $lineLayout
     */
    private function repairedPdfLayoutLeavesListItem(?array $previousLayout, ?array $lineLayout): bool
    {
        if (!$this->pdfLayoutHasGeometry($previousLayout) || !$this->pdfLayoutHasGeometry($lineLayout)) {
            return false;
        }
        if ($previousLayout['page'] !== $lineLayout['page']) {
            return true;
        }

        $previousHeight = max(1.0, $previousLayout['y2'] - $previousLayout['y1']);
        $lineHeight = max(1.0, $lineLayout['y2'] - $lineLayout['y1']);
        $referenceHeight = max($previousHeight, $lineHeight, $previousLayout['fontSize'], $lineLayout['fontSize'], 1.0);
        $verticalGap = $previousLayout['y1'] - $lineLayout['y2'];
        if ($verticalGap < -$referenceHeight * 0.4 || $verticalGap > $referenceHeight * 1.45) {
            return false;
        }

        return $lineLayout['x1'] <= $previousLayout['x1'] + max(8.0, $referenceHeight * 0.75);
    }

    private function lineEndsWithUrl(string $line): bool
    {
        return preg_match('/(?:https?:\/\/|www\.)\S+$/i', trim($line)) === 1;
    }

    private function repairedLineLooksLikeSectionLabel(string $line): bool
    {
        $line = trim($line);
        $letters = preg_replace('/[^\p{L}\p{M}]+/u', '', $line) ?? '';
        if ($line === ''
            || $this->length($letters) < 3
            || preg_match('/[.!?]$/u', $line) === 1) {
            return false;
        }
        if (preg_match('/^\d+(?:\.\d+)+(?:\.)?\s+(.+)$/u', $line, $numbered) === 1) {
            return preg_match('/^\p{Lu}/u', $numbered[1]) === 1
                && $this->repairedLineLooksLikeSectionLabel($numbered[1]);
        }
        $words = $this->pdfLineWordTokens($line);
        if (count($words) === 0 || count($words) > 6) {
            return false;
        }
        if (preg_match('/^\p{Lu}[\p{Lu}\p{N},;:() \-]+$/u', $line) === 1) {
            return true;
        }
        if (count($words) <= 3 && preg_match('/^\p{Lu}[\p{L}\p{N}&()\/ .-]*$/u', $line) === 1) {
            return true;
        }

        return $this->looksLikeRepairedPdfTitle($line)
            && (preg_match('/[:：]$/u', $line) !== 1 || $this->looksLikeRepairedPdfTitle(rtrim($line, ":：")));
    }

    private function looksLikeRepairedPdfTitle(string $line): bool
    {
        $wordCount = str_word_count($line);
        if ($wordCount < 3 || $wordCount > 12 || preg_match('/[.!?]$/', $line) === 1) {
            return false;
        }

        if (preg_match('/^[A-Z][A-Za-z0-9,;:() \-]+$/', $line) !== 1) {
            return false;
        }

        $words = preg_split('/\s+/', $line) ?: [];
        $titleLike = 0;
        $significant = 0;
        foreach ($words as $word) {
            $word = trim($word, " \t\n\r\0\x0B,;:()");
            if ($word === '') {
                continue;
            }
            $significant++;
            if (preg_match('/^[\p{Lu}\p{N}]/u', $word) === 1) {
                $titleLike++;
            }
        }

        return $significant > 0 && $titleLike / $significant >= 0.6;
    }

    /** @return list<string> */
    private function pdfSemanticLinePrefixes(): array
    {
        return [
            self::PDF_CODE_BLOCK_PREFIX,
            PdfFormulaSemanticProcessor::LINE_PREFIX,
            self::PDF_LINE_BLOCK_PREFIX,
            self::PDF_MAP_LABEL_PREFIX,
            self::PDF_FRONT_MATTER_PREFIX,
            self::PDF_LAYOUT_LABEL_PREFIX,
            self::PDF_DISPLAY_HEADING_PREFIX,
            self::PDF_NUMBERED_HEADING_PREFIX,
            self::PDF_NUMBERED_SUBHEADING_PREFIX,
        ];
    }

    private function pdfLineStartsWithSemanticPrefix(string $line): bool
    {
        foreach ($this->pdfSemanticLinePrefixes() as $prefix) {
            if (str_starts_with($line, $prefix)) {
                return true;
            }
        }

        return false;
    }

    /**
     * Decode any accidentally nested semantic roles defensively. The outer
     * role still determines the block type, while every inner marker is
     * removed from user-visible text. This is intentionally prefix-only: an
     * ordinary code block or paragraph may discuss the marker names without
     * being rewritten.
     */
    private function pdfTextWithoutSemanticPrefixes(string $text): string
    {
        do {
            $removed = false;
            foreach ($this->pdfSemanticLinePrefixes() as $prefix) {
                if (!str_starts_with($text, $prefix)) {
                    continue;
                }
                $text = substr($text, strlen($prefix));
                $removed = true;
                break;
            }
        } while ($removed);

        return $text;
    }

    /**
     * A map may expose rotated words as one editable record per painted
     * glyph. A sustained run of more than sixteen one-to-three-character
     * records is not a credible sequence of independent labels; omit that
     * ladder while retaining every surrounding multi-character place name,
     * trail label, legend entry, and short structural run.
     *
     * @param list<string> $labels
     * @return list<string>
     */
    private function boundedPdfMapLabelLines(array $labels): array
    {
        $bounded = [];
        $shortRun = [];
        $flush = static function () use (&$bounded, &$shortRun): void {
            if (count($shortRun) <= 16) {
                array_push($bounded, ...$shortRun);
            }
            $shortRun = [];
        };

        foreach ($labels as $label) {
            if ($this->length($label) <= 3) {
                $shortRun[] = $label;
                continue;
            }
            $flush();
            $bounded[] = $label;
        }
        $flush();

        return $bounded;
    }

    /**
     * @param list<string> $lines
     * @param array<int,array<string,mixed>> $exactWholeSourceMergedLineSpans
     * @return list<AstNode>
     */
    private function blocksFromLines(
        array $lines,
        bool $allowStackedTables = true,
        array $exactWholeSourceMergedLineSpans = []
    ): array {
        $blocks = [];
        $pendingItems = [];
        $pendingOrdered = false;
        $pendingOrderedStart = null;
        $pendingOrderedNext = null;

        $flushList = function () use (
            &$blocks,
            &$pendingItems,
            &$pendingOrdered,
            &$pendingOrderedStart,
            &$pendingOrderedNext
        ): void {
            if ($pendingItems === []) {
                return;
            }
            $attrs = [];
            if ($pendingOrdered && is_int($pendingOrderedStart) && $pendingOrderedStart !== 1) {
                $attrs['start'] = $pendingOrderedStart;
            }
            $blocks[] = new AstNode($pendingOrdered ? 'ordered_list' : 'bullet_list', $attrs, $pendingItems);
            $pendingItems = [];
            $pendingOrdered = false;
            $pendingOrderedStart = null;
            $pendingOrderedNext = null;
        };

        $index = 0;
        $lineCount = count($lines);
        while ($index < $lineCount) {
            $line = $lines[$index];
            $lineSpan = $exactWholeSourceMergedLineSpans[$index] ?? null;
            $lineSourceAttrs = $this->repairedPdfMergedLineHasExactWholeSourceSpan(
                $line,
                $lineSpan
            ) ? ['sourcePdfExactMergedLineSpan' => $lineSpan] : [];
            if (str_starts_with($line, self::PDF_CODE_BLOCK_PREFIX)) {
                $flushList();
                $code = $this->pdfTextWithoutSemanticPrefixes(
                    substr($line, strlen(self::PDF_CODE_BLOCK_PREFIX))
                );
                if ($code !== '') {
                    $blocks[] = new AstNode('code_block', ['text' => $code]);
                }
                $index++;
                continue;
            }
            if (str_starts_with($line, PdfFormulaSemanticProcessor::LINE_PREFIX)) {
                $flushList();
                $formula = trim($this->pdfTextWithoutSemanticPrefixes(
                    substr($line, strlen(PdfFormulaSemanticProcessor::LINE_PREFIX))
                ));
                if ($formula !== '') {
                    $blocks[] = new AstNode(
                        'paragraph',
                        ['classes' => ['pdf-formula'], 'sourceRole' => 'formula'],
                        [new AstNode('text', ['text' => $formula])]
                    );
                }
                $index++;
                continue;
            }
            if (str_starts_with($line, self::PDF_LINE_BLOCK_PREFIX)) {
                $flushList();
                $dialogueLines = $this->decodePdfLineBlock($line);
                if ($dialogueLines !== []) {
                    $cue = array_shift($dialogueLines);
                    $inlines = [
                        new AstNode('strong', ['sourceRole' => 'speaker'], $this->inlines($cue)),
                    ];
                    foreach ($dialogueLines as $dialogueLine) {
                        $inlines[] = new AstNode('linebreak');
                        array_push($inlines, ...$this->inlines($dialogueLine));
                    }
                    $blocks[] = new AstNode(
                        'paragraph',
                        ['sourceRole' => 'dialogue'],
                        $inlines
                    );
                }
                $index++;
                continue;
            }
            if (str_starts_with($line, self::PDF_MAP_LABEL_PREFIX)) {
                $flushList();
                $mapLabelTexts = [];
                while ($index < $lineCount
                    && str_starts_with($lines[$index], self::PDF_MAP_LABEL_PREFIX)) {
                    $label = trim($this->pdfTextWithoutSemanticPrefixes(
                        substr($lines[$index], strlen(self::PDF_MAP_LABEL_PREFIX))
                    ));
                    if ($label !== '') {
                        $mapLabelTexts[] = $label;
                    }
                    $index++;
                }
                $mapLabelLines = array_map(
                    fn (string $label): AstNode => new AstNode(
                            'line',
                            ['sourceRole' => 'map-label'],
                            $this->inlines($label)
                    ),
                    $this->boundedPdfMapLabelLines($mapLabelTexts)
                );
                if (count($mapLabelLines) === 1) {
                    $blocks[] = new AstNode(
                        'paragraph',
                        ['classes' => ['pdf-map-label'], 'sourceRole' => 'map-label'],
                        $mapLabelLines[0]->children
                    );
                } elseif ($mapLabelLines !== []) {
                    // A spatial map does not define a trustworthy paragraph
                    // order. Keep every extracted label editable and ordered
                    // by the conservative geometry fallback, but represent the
                    // sustained label region as one line-oriented block rather
                    // than certifying dozens of glyph fragments as prose.
                    $blocks[] = new AstNode(
                        'line_block',
                        ['classes' => ['pdf-map-labels'], 'sourceRole' => 'map-labels'],
                        $mapLabelLines
                    );
                }
                continue;
            }
            if (str_starts_with($line, self::PDF_FRONT_MATTER_PREFIX)) {
                $flushList();
                $credit = trim($this->pdfTextWithoutSemanticPrefixes(
                    substr($line, strlen(self::PDF_FRONT_MATTER_PREFIX))
                ));
                if ($credit !== '') {
                    $blocks[] = new AstNode(
                        'paragraph',
                        ['classes' => ['pdf-front-matter'], 'sourceRole' => 'credits'],
                        $this->inlines($credit)
                    );
                }
                $index++;
                continue;
            }
            if (str_starts_with($line, self::PDF_LAYOUT_LABEL_PREFIX)) {
                $flushList();
                $label = trim($this->pdfTextWithoutSemanticPrefixes(
                    substr($line, strlen(self::PDF_LAYOUT_LABEL_PREFIX))
                ));
                if ($label !== '') {
                    $blocks[] = $this->paragraph($label, [
                        'classes' => ['pdf-layout-label'],
                        'sourceRole' => 'layout-label',
                    ] + $lineSourceAttrs);
                }
                $index++;
                continue;
            }
            if (str_starts_with($line, self::PDF_DISPLAY_HEADING_PREFIX)) {
                $flushList();
                $heading = trim($this->pdfTextWithoutSemanticPrefixes(
                    substr($line, strlen(self::PDF_DISPLAY_HEADING_PREFIX))
                ));
                if ($heading !== '') {
                    $blocks[] = new AstNode(
                        'heading',
                        ['level' => $index === 0 ? 1 : 2, 'text' => $heading]
                            + $lineSourceAttrs,
                        $this->inlines($heading)
                    );
                }
                $index++;
                continue;
            }
            if (str_starts_with($line, self::PDF_NUMBERED_HEADING_PREFIX)) {
                $flushList();
                $heading = trim($this->pdfTextWithoutSemanticPrefixes(
                    substr($line, strlen(self::PDF_NUMBERED_HEADING_PREFIX))
                ));
                if ($heading !== '') {
                    $blocks[] = new AstNode(
                        'heading',
                        ['level' => $index === 0 ? 1 : 2, 'text' => $heading]
                            + $lineSourceAttrs,
                        $this->inlines($heading)
                    );
                }
                $index++;
                continue;
            }
            if (str_starts_with($line, self::PDF_NUMBERED_SUBHEADING_PREFIX)) {
                $flushList();
                $heading = trim($this->pdfTextWithoutSemanticPrefixes(
                    substr($line, strlen(self::PDF_NUMBERED_SUBHEADING_PREFIX))
                ));
                if ($heading !== '') {
                    $blocks[] = new AstNode(
                        'heading',
                        ['level' => 2, 'text' => $heading] + $lineSourceAttrs,
                        $this->inlines($heading)
                    );
                }
                $index++;
                continue;
            }
            $tableRun = $this->tableRowsAt($lines, $index);
            if ($tableRun['rows'] !== []) {
                $flushList();
                $blocks[] = $this->table($tableRun['rows']);
                $index += $tableRun['consumed'];
                continue;
            }
            if ($allowStackedTables) {
                $stackedTableRun = $this->stackedTableRowsAt($lines, $index);
                if ($stackedTableRun['rows'] !== []) {
                    $candidate = $this->table($stackedTableRun['rows']);
                    // Stacked-table inference consumes already annotated
                    // semantic lines.  A table cell does not interpret those
                    // internal prefixes, so accepting the candidate blindly
                    // can expose a marker as visible text and manufacture a
                    // table from form-field atoms.  Compare against the same
                    // bounded lines with stacked inference disabled; headings,
                    // lists, and layout labels may change structure, but their
                    // complete visible character inventory must not change.
                    $baseline = $this->blocksFromLines(
                        array_slice($lines, $index, $stackedTableRun['consumed']),
                        false
                    );
                    if ($this->pdfAstBlocksHaveEqualSignificantCharacterInventory(
                        $baseline,
                        [$candidate]
                    )) {
                        $flushList();
                        $blocks[] = $candidate;
                        $index += $stackedTableRun['consumed'];
                        continue;
                    }
                }
            }

            if ($this->numberedPdfLineLooksLikeSectionHeading($lines, $index)) {
                $flushList();
                $blocks[] = new AstNode(
                    'heading',
                    ['level' => $index === 0 ? 1 : 2, 'text' => $line]
                        + $lineSourceAttrs,
                    $this->inlines($line)
                );
                $index++;
                continue;
            }

            $listItem = $this->listItemAt($lines, $index);
            if ($listItem !== null) {
                [$ordered, $text, $ordinal] = $listItem;
                if ($pendingItems !== []
                    && ($pendingOrdered !== $ordered
                        || ($ordered
                            && is_int($ordinal)
                            && is_int($pendingOrderedNext)
                            && $ordinal !== $pendingOrderedNext))) {
                    $flushList();
                }
                $pendingOrdered = $ordered;
                if ($ordered && is_int($ordinal)) {
                    $pendingOrderedStart ??= $ordinal;
                    $pendingOrderedNext = $ordinal + 1;
                }
                $pendingItems[] = new AstNode('list_item', [], [$this->paragraph($text)]);
                $index++;
                continue;
            }

            $flushList();
            $embeddedListBlocks = $this->blocksFromLineWithEmbeddedLists($line);
            if ($embeddedListBlocks !== null) {
                foreach ($embeddedListBlocks as $block) {
                    $blocks[] = $block;
                }
                $index++;
                continue;
            }

            if ($this->looksLikeHeading($line, $index, count($lines))) {
                $blocks[] = new AstNode(
                    'heading',
                    ['level' => $index === 0 ? 1 : 2, 'text' => $line]
                        + $lineSourceAttrs,
                    $this->inlines($line)
                );
                $index++;
                continue;
            }
            $blocks[] = $this->paragraph($line, $lineSourceAttrs);
            $index++;
        }
        $flushList();

        return $blocks;
    }

    /**
     * @param list<array<string, mixed>> $runs
     * @param list<array<string, mixed>> $filledRectangles
     * @param array<int, list<AstNode>>|null $tableBlocksByPage
     * @return list<AstNode>
     */
    private function blocksFromPositionedTables(array $runs, array $filledRectangles = [], ?array &$tableBlocksByPage = null): array
    {
        $tableBlocksByPage = [];
        if ($runs === []) {
            return [];
        }

        $filledRectanglesByPage = [];
        foreach ($filledRectangles as $rectangle) {
            $normalized = $this->positionedFillRectangle($rectangle);
            if ($normalized !== null) {
                $filledRectanglesByPage[$normalized['page']][] = $normalized;
            }
        }

        if (!$this->positionedTextRunsArePageOrdered($runs)) {
            return $this->blocksFromPositionedTablesByPageMap($runs, $filledRectanglesByPage, $tableBlocksByPage);
        }

        $blocks = [];
        $pageRuns = [];
        $page = null;
        $flush = function () use (&$blocks, &$pageRuns, &$tableBlocksByPage, &$page, $filledRectanglesByPage): void {
            if ($page === null || $pageRuns === []) {
                return;
            }
            $pageBlocks = $this->blocksFromPositionedPageTables(
                $pageRuns,
                $filledRectanglesByPage[$page] ?? []
            );
            if ($this->countNodesOfType($pageBlocks, 'table') > 0) {
                $tableBlocksByPage[$page] = $pageBlocks;
                foreach ($pageBlocks as $block) {
                    $blocks[] = $block;
                }
            }
            $pageRuns = [];
        };
        foreach ($this->positionedRunsWithLiteralWhitespaceProvenance($runs) as $normalized) {
            $runPage = (int) $normalized['page'];
            if ($page !== null && $runPage !== $page) {
                $flush();
            }
            $page = $runPage;
            $pageRuns[] = $normalized;
        }
        $flush();

        return $blocks;
    }

    /**
     * Preserve the global source-order index before dense table runs are
     * released. Page-at-a-time reconstruction can then use the established
     * normalization and table inference without retaining the complete glyph
     * array beside its transient row graphs.
     *
     * @param list<array<string, mixed>> $runs
     * @return resource
     */
    private function deferPositionedTableRuns(array $runs): mixed
    {
        $stream = $this->deferPdfRecordArray([], 'positioned table runs');
        try {
            foreach ($runs as $index => $run) {
                $run['_order'] = array_key_exists('_order', $run) ? $run['_order'] : $index;
                $this->writePdfRecordToTempStream($stream, $run, 'positioned table runs');
            }
            fflush($stream);
            rewind($stream);

            return $stream;
        } catch (\Throwable $error) {
            fclose($stream);
            throw $error;
        }
    }

    /**
     * @param resource $runsFile
     * @param list<array<string, mixed>> $filledRectangles
     * @param array<int, list<AstNode>> $tableBlocksByPage
     * @return list<AstNode>
     */
    private function blocksFromDeferredPositionedTables(
        mixed $runsFile,
        array $filledRectangles,
        array &$tableBlocksByPage
    ): array {
        $tableBlocksByPage = [];
        $filledRectanglesByPage = [];
        foreach ($filledRectangles as $rectangle) {
            $normalized = $this->positionedFillRectangle($rectangle);
            if ($normalized !== null) {
                $filledRectanglesByPage[$normalized['page']][] = $normalized;
            }
        }

        $blocks = [];
        $pageRuns = [];
        $page = null;
        $flush = function () use (&$blocks, &$pageRuns, &$tableBlocksByPage, &$page, $filledRectanglesByPage): void {
            if ($page === null || $pageRuns === []) {
                return;
            }
            $normalizedRuns = [];
            foreach ($this->positionedRunsWithLiteralWhitespaceProvenance($pageRuns) as $normalized) {
                $normalizedRuns[] = $normalized;
            }
            $pageBlocks = $this->blocksFromPositionedPageTables(
                $normalizedRuns,
                $filledRectanglesByPage[$page] ?? []
            );
            if ($this->countNodesOfType($pageBlocks, 'table') > 0) {
                $tableBlocksByPage[$page] = $pageBlocks;
                foreach ($pageBlocks as $block) {
                    $blocks[] = $block;
                }
            }
            $pageRuns = [];
        };

        rewind($runsFile);
        while (($run = $this->readPdfRecordFromTempStream($runsFile, 'positioned table runs')) !== null) {
            $runPage = max(1, (int) ($run['page'] ?? 1));
            if ($page !== null && $runPage !== $page) {
                $flush();
            }
            $page = $runPage;
            $pageRuns[] = $run;
        }
        $flush();

        return $blocks;
    }

    /**
     * @param list<array<string, mixed>> $runs
     * @param array<int, list<array<string, mixed>>> $filledRectanglesByPage
     * @param array<int, list<AstNode>> $tableBlocksByPage
     * @return list<AstNode>
     */
    private function blocksFromPositionedTablesByPageMap(
        array $runs,
        array $filledRectanglesByPage,
        array &$tableBlocksByPage
    ): array {

        $runsByPage = [];
        foreach ($this->positionedRunsWithLiteralWhitespaceProvenance($runs) as $normalized) {
            $runsByPage[$normalized['page']][] = $normalized;
        }
        if ($runsByPage === []) {
            return [];
        }

        ksort($runsByPage);
        $blocksByPage = [];
        $hasTable = false;
        foreach ($runsByPage as $page => $pageRuns) {
            $pageBlocks = $this->blocksFromPositionedPageTables($pageRuns, $filledRectanglesByPage[$page] ?? []);
            if ($this->countNodesOfType($pageBlocks, 'table') > 0) {
                $hasTable = true;
            }
            $blocksByPage[$page] = $pageBlocks;
        }
        if (!$hasTable) {
            return [];
        }

        $blocks = [];
        foreach ($runsByPage as $page => $_pageRuns) {
            $pageBlocks = $blocksByPage[$page] ?? [];
            if ($this->countNodesOfType($pageBlocks, 'table') === 0) {
                continue;
            }
            $tableBlocksByPage[(int) $page] = $pageBlocks;
            foreach ($pageBlocks as $block) {
                $blocks[] = $block;
            }
        }

        return $blocks;
    }

    /**
     * Select only page candidates which can already pass the same exact
     * occurrence binding required of the final document.  A rejected candidate
     * is simply omitted from the map; the compositor below will then use the
     * conservative source/repaired-text path for that page.
     *
     * @param array<int, list<AstNode>> $candidatesByPage
     * @param list<array<string,mixed>> $sourceItems
     * @param list<array<string,mixed>> $sourceLayouts
     * @return array<int, list<AstNode>>
     */
    private function positionedPdfCandidatePagesWithExactSourceBinding(
        array $candidatesByPage,
        array $sourceItems,
        array $sourceLayouts,
        string $candidateKind
    ): array {
        $accepted = [];
        ksort($candidatesByPage, SORT_NUMERIC);
        foreach ($candidatesByPage as $page => $candidateBlocks) {
            $page = max(1, (int) $page);
            $inputs = $this->pdfPageLocalSourceBindingInputs(
                $page,
                $sourceItems,
                $sourceLayouts
            );
            if ($inputs === null || $candidateBlocks === []) {
                $this->sourceOrderProofDiagnostics[] = [
                    'status' => 'rejected',
                    'method' => 'preselection-page-source-binding',
                    'candidateKind' => $candidateKind,
                    'page' => $page,
                    'reason' => $inputs === null
                        ? 'page-source-inventory-could-not-be-localized'
                        : 'candidate-page-has-no-blocks',
                ];
                unset($inputs, $validation, $recovered, $recoveredValidation);
                continue;
            }

            $validation = $this->validatePositionedPdfPageCandidateSourceBinding(
                $page,
                $candidateBlocks,
                $inputs
            );
            $recoveryMethod = null;
            if (!$validation['complete']) {
                $recovered = $this->positionedPdfCandidateWithUniquePartialSourceLeafRecovery(
                    $candidateBlocks,
                    $inputs['sourceItems'],
                    $validation['explicitDispositions']
                );
                if ($recovered !== null) {
                    $recoveredValidation = $this->validatePositionedPdfPageCandidateSourceBinding(
                        $page,
                        $recovered,
                        $inputs
                    );
                    if ($recoveredValidation['complete']) {
                        $candidateBlocks = $recovered;
                        $validation = $recoveredValidation;
                        $recoveryMethod = 'unique-partial-source-leaf-restoration';
                    }
                }
            }
            if (!$validation['complete']) {
                $recovered = $this->positionedPdfCandidateWithUniqueStandaloneMarkerPrefixRecovery(
                    $candidateBlocks,
                    $inputs['sourceItems'],
                    $validation['explicitDispositions']
                );
                if ($recovered !== null) {
                    $recoveredValidation = $this->validatePositionedPdfPageCandidateSourceBinding(
                        $page,
                        $recovered,
                        $inputs
                    );
                    if ($recoveredValidation['complete']) {
                        $candidateBlocks = $recovered;
                        $validation = $recoveredValidation;
                        $recoveryMethod = 'unique-standalone-marker-prefix-restoration';
                    }
                }
            }

            $diagnostic = [
                'status' => $validation['complete'] ? 'accepted' : 'rejected',
                'method' => 'preselection-page-source-binding',
                'candidateKind' => $candidateKind,
                'page' => $page,
                'sourceOccurrenceCount' => count($inputs['sourceItems']),
            ];
            if ($recoveryMethod !== null) {
                $diagnostic['recoveryMethod'] = $recoveryMethod;
            }
            if (!$validation['complete']) {
                $diagnostic['reason'] = $validation['failureReason']
                    ?? 'page-source-binding-was-not-exact';
            }
            $this->sourceOrderProofDiagnostics[] = $diagnostic;
            if ($validation['complete']) {
                $accepted[$page] = $candidateBlocks;
                $this->sourceProofCandidateBlocksByPage[$page] = $candidateBlocks;
            }
            unset($inputs, $validation, $recovered, $recoveredValidation, $diagnostic);
        }

        return $accepted;
    }

    /**
     * Native source-line layouts identify one immutable occurrence by ID but
     * do not normally repeat the positioned character-range attributes.  Add
     * a complete range only for a unique ID whose visible projection is still
     * byte-for-byte equal to that source occurrence.  Repaired or ambiguous
     * layouts remain unproven.
     *
     * @param list<array<string,mixed>> $sourceLayouts
     * @param list<array<string,mixed>> $sourceItems
     * @return list<array<string,mixed>>
     */
    private function pdfSourceLayoutsWithExactWholeOccurrenceRanges(
        array $sourceLayouts,
        array $sourceItems
    ): array {
        $this->pdfSourceLayoutsWithExactWholeOccurrenceRangesInPlace(
            $sourceLayouts,
            $sourceItems
        );

        return $sourceLayouts;
    }

    /**
     * @param list<array<string,mixed>> $sourceLayouts
     * @param list<array<string,mixed>> $sourceItems
     */
    private function pdfSourceLayoutsWithExactWholeOccurrenceRangesInPlace(
        array &$sourceLayouts,
        array $sourceItems
    ): void {
        $globalIndexBySourceId = [];
        foreach ($sourceItems as $globalIndex => $sourceItem) {
            $sourceId = is_string($sourceItem['id'] ?? null)
                ? $sourceItem['id']
                : '';
            if ($sourceId !== '') {
                $globalIndexBySourceId[$sourceId] = array_key_exists(
                    $sourceId,
                    $globalIndexBySourceId
                ) ? null : $globalIndex;
            }
        }

        // Most native layouts already carry either a document-global index or
        // one unique source ID. Build the substantially larger text-tuple
        // fallback only when at least one unresolved layout can actually use
        // it, rather than retaining it beside every exact-range proof.
        $needsSourceTupleLookup = false;
        foreach ($sourceLayouts as $layout) {
            if (!is_array($layout)
                || $this->pdfPositionedExactSourceRanges($layout) !== []
                || is_int($layout['sourcePdfGlobalSourceIndex'] ?? null)) {
                continue;
            }
            $sourceId = is_string($layout['id'] ?? null) ? $layout['id'] : '';
            $idIndex = $sourceId !== ''
                && array_key_exists($sourceId, $globalIndexBySourceId)
                    ? $globalIndexBySourceId[$sourceId]
                    : null;
            if (!is_int($idIndex)
                && is_numeric($layout['sourceStream'] ?? null)
                && (string) ($layout['text'] ?? '') !== '') {
                $needsSourceTupleLookup = true;
                break;
            }
        }
        $globalIndexBySourceTuple = [];
        if ($needsSourceTupleLookup) {
            foreach ($sourceItems as $globalIndex => $sourceItem) {
                $sourceSignificant = $this->pdfSourceOccurrenceComparableText(
                    (string) ($sourceItem['text'] ?? '')
                );
                if ($sourceSignificant === '') {
                    continue;
                }
                $tuple = max(1, (int) ($sourceItem['page'] ?? 1)) . "\0"
                    . max(1, (int) ($sourceItem['stream'] ?? 1)) . "\0"
                    . hash('sha256', $sourceSignificant);
                $globalIndexBySourceTuple[$tuple] = array_key_exists(
                    $tuple,
                    $globalIndexBySourceTuple
                ) ? null : $globalIndex;
            }
        }

        foreach ($sourceLayouts as &$layout) {
            if (!is_array($layout)
                || $this->pdfPositionedExactSourceRanges($layout) !== []) {
                continue;
            }
            $sourceId = is_string($layout['id'] ?? null)
                ? $layout['id']
                : '';
            $globalIndex = is_int($layout['sourcePdfGlobalSourceIndex'] ?? null)
                ? $layout['sourcePdfGlobalSourceIndex']
                : ($sourceId !== ''
                && array_key_exists($sourceId, $globalIndexBySourceId)
                ? $globalIndexBySourceId[$sourceId]
                : null);
            $layoutSignificant = $this->pdfSourceOccurrenceComparableText(
                (string) ($layout['text'] ?? '')
            );
            // sourcePdfLineItem() intentionally keeps only compact layout
            // fields.  Recover its occurrence identity only when page,
            // native stream, and significant text form one unique source
            // tuple; repeated spellings therefore remain unproven.
            if (!is_int($globalIndex)
                && $layoutSignificant !== ''
                && is_numeric($layout['sourceStream'] ?? null)) {
                $tuple = max(1, (int) ($layout['page'] ?? 1)) . "\0"
                    . max(1, (int) $layout['sourceStream']) . "\0"
                    . hash('sha256', $layoutSignificant);
                $globalIndex = array_key_exists($tuple, $globalIndexBySourceTuple)
                    ? $globalIndexBySourceTuple[$tuple]
                    : null;
            }
            $sourceItem = is_int($globalIndex)
                ? ($sourceItems[$globalIndex] ?? null)
                : null;
            $sourceSignificant = is_array($sourceItem)
                ? $this->pdfSourceOccurrenceComparableText(
                    (string) ($sourceItem['text'] ?? '')
                )
                : '';
            if ($layoutSignificant === ''
                || $sourceSignificant === ''
                || !hash_equals($sourceSignificant, $layoutSignificant)) {
                continue;
            }
            $layout['sourcePdfExactSourceRanges'] = [[
                'sourceIndex' => $globalIndex,
                'sourceStart' => 0,
                'sourceEnd' => strlen($sourceSignificant),
            ]];
        }
        unset($layout);
        unset($globalIndexBySourceTuple);

        // A compact native source-line fallback has no positioned-layout
        // role, but its unique ID still binds one complete immutable source
        // occurrence. Sign that narrower fact separately so later boundary
        // cleanup can preserve its bytes without treating it as geometry.
        foreach ($sourceLayouts as &$layout) {
            if (!is_array($layout)) {
                continue;
            }
            unset($layout['sourcePdfWholeExactSourceOccurrenceProof']);
            $sourceId = is_string($layout['id'] ?? null) ? $layout['id'] : '';
            $globalIndex = $sourceId !== ''
                && array_key_exists($sourceId, $globalIndexBySourceId)
                && is_int($globalIndexBySourceId[$sourceId])
                    ? $globalIndexBySourceId[$sourceId]
                    : null;
            $sourceItem = is_int($globalIndex)
                ? ($sourceItems[$globalIndex] ?? null)
                : null;
            $sourceProjection = is_array($sourceItem)
                ? $this->pdfSourceOccurrenceComparableText(
                    (string) ($sourceItem['text'] ?? '')
                )
                : '';
            $layoutProjection = $this->pdfSourceOccurrenceComparableText(
                (string) ($layout['text'] ?? '')
            );
            $page = is_array($sourceItem) ? (int) ($sourceItem['page'] ?? 0) : 0;
            $stream = is_array($sourceItem) ? (int) ($sourceItem['stream'] ?? 0) : 0;
            $range = is_int($globalIndex) ? [[
                'sourceIndex' => $globalIndex,
                'sourceStart' => 0,
                'sourceEnd' => strlen($sourceProjection),
            ]] : [];
            if (!is_array($sourceItem)
                || $sourceId === ''
                || ($sourceItem['id'] ?? null) !== $sourceId
                || $sourceProjection === ''
                || !hash_equals($sourceProjection, $layoutProjection)
                || $page < 1
                || $stream < 1
                || (int) ($layout['page'] ?? 0) !== $page
                || (int) ($layout['sourceStream'] ?? 0) !== $stream
                || (isset($layout['sourcePdfGlobalSourceIndex'])
                    && $layout['sourcePdfGlobalSourceIndex'] !== $globalIndex)
                || $this->pdfPositionedExactSourceRanges($layout) !== $range) {
                continue;
            }
            $proof = [
                'version' => 1,
                'method' => 'source-inventory-whole-source-occurrence',
                'sourceSha256' => $this->sourceSha256,
                'sourceOccurrenceId' => $sourceId,
                'globalSourceIndex' => $globalIndex,
                'page' => $page,
                'stream' => $stream,
                'exactRange' => $range[0],
                'projectionDigest' => hash('sha256', $sourceProjection),
            ];
            $proof['proofDigest'] = hash('sha256', json_encode(
                $proof,
                JSON_UNESCAPED_SLASHES
                    | JSON_UNESCAPED_UNICODE
                    | JSON_PRESERVE_ZERO_FRACTION
            ) ?: '');
            $layout['sourcePdfWholeExactSourceOccurrenceProof'] = $proof;
        }
        unset($layout);

    }

    /**
     * @param list<array<string,mixed>> $sourceLayouts
     * @param list<array<string,mixed>> $sourceItems
     * @return list<array<string,mixed>>
     */
    private function pdfSourceLayoutsWithWholeExactOccurrenceProofs(
        array $sourceLayouts,
        array $sourceItems
    ): array {
        $sourceItemsByGlobalIndex = [];
        foreach ($sourceItems as $localIndex => $sourceItem) {
            if (!is_array($sourceItem)) {
                continue;
            }
            $globalIndex = is_int($sourceItem['sourcePdfGlobalSourceIndex'] ?? null)
                ? $sourceItem['sourcePdfGlobalSourceIndex']
                : $localIndex;
            $sourceItemsByGlobalIndex[$globalIndex] = array_key_exists(
                $globalIndex,
                $sourceItemsByGlobalIndex
            ) ? null : $sourceItem;
        }
        foreach ($sourceLayouts as &$layout) {
            if (!is_array($layout)) {
                continue;
            }
            unset($layout['sourcePdfWholeExactOccurrenceProof']);
            $proof = $this->pdfSourceLayoutWholeExactOccurrenceProof($layout, $sourceItems);
            if ($proof !== null) {
                // Coverage canonicalizes adjacent subranges and global order.
                // Store that exact sequence so a reordered or fragmented
                // union cannot later masquerade as the stamped proof.
                $layout['sourcePdfExactSourceRanges'] = $proof['ranges'];
                $layout['sourcePdfWholeExactOccurrenceProof'] = $proof;
                $occurrences = is_array($proof['occurrences'] ?? null)
                    ? $proof['occurrences']
                    : [];
                $ranges = is_array($proof['ranges'] ?? null) ? $proof['ranges'] : [];
                $occurrence = count($occurrences) === 1 && is_array($occurrences[0] ?? null)
                    ? $occurrences[0]
                    : null;
                $range = count($ranges) === 1 && is_array($ranges[0] ?? null)
                    ? $ranges[0]
                    : null;
                $globalIndex = is_array($occurrence)
                    && is_int($occurrence['sourceIndex'] ?? null)
                        ? $occurrence['sourceIndex']
                        : null;
                $sourceItem = is_int($globalIndex)
                    ? ($sourceItemsByGlobalIndex[$globalIndex] ?? null)
                    : null;
                $sourceProjection = is_array($sourceItem)
                    ? $this->pdfSourceOccurrenceComparableText(
                        (string) ($sourceItem['text'] ?? '')
                    )
                    : '';
                $sourceId = is_array($sourceItem) && is_string($sourceItem['id'] ?? null)
                    ? $sourceItem['id']
                    : '';
                $sourceStream = is_array($sourceItem) ? (int) ($sourceItem['stream'] ?? 0) : 0;
                // The degenerate one-occurrence union is also an exact
                // identity proof. Retain the source-inventory binding beside
                // the proof digest, not on the visual carrier itself: adding
                // a native ID role would change exact-source recovery.
                if ($sourceId !== ''
                    && $sourceProjection !== ''
                    && $sourceStream >= 1
                    && is_array($range)
                    && $range === [
                        'sourceIndex' => $globalIndex,
                        'sourceStart' => 0,
                        'sourceEnd' => strlen($sourceProjection),
                    ]
                    && (int) ($occurrence['page'] ?? 0) === (int) ($sourceItem['page'] ?? -1)
                    && (int) ($occurrence['stream'] ?? 0) === $sourceStream
                    && hash_equals(
                        (string) ($occurrence['significantDigest'] ?? ''),
                        hash('sha256', $sourceProjection)
                    )) {
                    $identity = [
                        'sourceOccurrenceId' => $sourceId,
                        'globalSourceIndex' => $globalIndex,
                        'page' => (int) $sourceItem['page'],
                        'stream' => $sourceStream,
                        'exactRange' => $range,
                        'projectionDigest' => hash('sha256', $sourceProjection),
                        'occurrenceProofDigest' => $proof['proofDigest'] ?? null,
                    ];
                    $proofDigest = is_string($proof['proofDigest'] ?? null)
                        ? $proof['proofDigest']
                        : '';
                    if ($proofDigest !== '') {
                        $existingIdentity = $this->sourceOccurrenceIdentityByWholeProofDigest[
                            $proofDigest
                        ] ?? null;
                        $this->sourceOccurrenceIdentityByWholeProofDigest[$proofDigest] =
                            $existingIdentity === null || $existingIdentity === $identity
                                ? $identity
                                : false;
                    }
                }
            }
        }
        unset($layout);

        return $sourceLayouts;
    }

    /**
     * A positioned form row may begin at a proved suffix of one source
     * occurrence and end with complete adjacent field-ID and currency
     * occurrences. It is therefore ineligible for the whole-union proof
     * above even though its terminal currency occurrence is exact. Stamp the
     * narrower immutable fact while the complete source inventory is still
     * available; later semantic repair can validate it without retaining that
     * inventory in memory.
     *
     * @param list<array<string,mixed>> $sourceLayouts
     * @param list<array<string,mixed>> $sourceItems
     * @return list<array<string,mixed>>
     */
    private function pdfSourceLayoutsWithExactFormTailOccurrenceProofs(
        array $sourceLayouts,
        array $sourceItems
    ): array {
        $hasCandidate = false;
        foreach ($sourceLayouts as &$layout) {
            if (!is_array($layout)) {
                continue;
            }
            unset($layout['sourcePdfExactFormTailOccurrenceProof']);
            $ranges = $layout['sourcePdfExactSourceRanges'] ?? null;
            if ($sourceItems === []
                || !is_numeric($layout['page'] ?? null)
                || ($layout['sourcePdfExactGeometryFallback'] ?? false) === true
                || ($layout['sourceUnmatchedFallback'] ?? false) === true
                || ($layout['sourceSupplementalPositioned'] ?? false) === true
                || ($layout['sourceShortSupplementalCandidate'] ?? false) === true
                || ($layout['sourceSupplementalRecoverableSentenceSuffix'] ?? false) === true
                || !is_array($ranges)
                || !array_is_list($ranges)
                || count($ranges) < 2
                || preg_match(
                    '/\p{N}{1,3}(?:\p{L}|\(\p{L}\))?\s*\p{Sc}\s*$/u',
                    (string) ($layout['text'] ?? '')
                ) !== 1) {
                continue;
            }
            foreach (['x1', 'y1', 'x2', 'y2', 'fontSize'] as $geometryKey) {
                if (!is_numeric($layout[$geometryKey] ?? null)) {
                    continue 2;
                }
            }
            $previousSourceIndex = null;
            foreach ($ranges as $offset => $range) {
                if (!is_array($range)
                    || !is_int($range['sourceIndex'] ?? null)
                    || !is_int($range['sourceStart'] ?? null)
                    || !is_int($range['sourceEnd'] ?? null)
                    || $range['sourceIndex'] < 0
                    || $range['sourceStart'] < 0
                    || $range['sourceEnd'] <= $range['sourceStart']
                    || ($offset > 0 && $range['sourceStart'] !== 0)
                    || ($previousSourceIndex !== null
                        && $range['sourceIndex'] !== $previousSourceIndex + 1)) {
                    continue 2;
                }
                $previousSourceIndex = $range['sourceIndex'];
            }
            $hasCandidate = true;
        }
        unset($layout);
        if (!$hasCandidate) {
            return $sourceLayouts;
        }

        return PdfExactFormRowTailRepair::decorateLayouts(
            $sourceLayouts,
            $sourceItems,
            [
                'pdfLayoutHasGeometry' => $this->pdfLayoutHasGeometry(...),
                'pdfPositionedExactSourceRanges' =>
                    $this->pdfPositionedExactSourceRanges(...),
                'pdfSourceOccurrenceComparableText' =>
                    $this->pdfSourceOccurrenceComparableText(...),
                'pdfTextWithoutSemanticPrefixes' =>
                    $this->pdfTextWithoutSemanticPrefixes(...),
                'sourcePdfSourceItemHasExactGeometry' =>
                    $this->sourcePdfSourceItemHasExactGeometry(...),
            ]
        );
    }

    /**
     * @param array<string,mixed> $layout
     * @param list<array<string,mixed>> $sourceItems
     * @return array<string,mixed>|null
     */
    private function pdfSourceLayoutExactFormTailOccurrenceProof(
        array $layout,
        array $sourceItems
    ): ?array {
        if (!$this->pdfLayoutHasGeometry($layout)
            || ($layout['sourcePdfExactGeometryFallback'] ?? false) === true
            || ($layout['sourceUnmatchedFallback'] ?? false) === true
            || ($layout['sourceSupplementalPositioned'] ?? false) === true
            || ($layout['sourceShortSupplementalCandidate'] ?? false) === true
            || ($layout['sourceSupplementalRecoverableSentenceSuffix'] ?? false) === true
            || !is_numeric($layout['page'] ?? null)) {
            return null;
        }
        $projection = $this->pdfSourceOccurrenceComparableText(
            $this->pdfTextWithoutSemanticPrefixes((string) ($layout['text'] ?? ''))
        );
        $ranges = $this->pdfPositionedExactSourceRanges($layout);
        if ($projection === ''
            || count($ranges) < 2
            || preg_match('/\p{N}{1,3}(?:\p{L}|\(\p{L}\))?\p{Sc}$/u', $projection) !== 1) {
            return null;
        }

        $localIndexByGlobalIndex = [];
        foreach ($sourceItems as $localIndex => $sourceItem) {
            $globalIndex = is_int($sourceItem['sourcePdfGlobalSourceIndex'] ?? null)
                ? $sourceItem['sourcePdfGlobalSourceIndex']
                : $localIndex;
            if (isset($localIndexByGlobalIndex[$globalIndex])) {
                return null;
            }
            $localIndexByGlobalIndex[$globalIndex] = $localIndex;
        }

        $page = max(1, (int) $layout['page']);
        $sourceProjection = '';
        $previousGlobalIndex = null;
        $previousLocalIndex = null;
        $terminalOccurrence = null;
        foreach ($ranges as $offset => $range) {
            $globalIndex = $range['sourceIndex'];
            $localIndex = $localIndexByGlobalIndex[$globalIndex] ?? null;
            $sourceItem = is_int($localIndex) ? ($sourceItems[$localIndex] ?? null) : null;
            $sourceSignificant = is_array($sourceItem)
                ? $this->pdfSourceOccurrenceComparableText((string) ($sourceItem['text'] ?? ''))
                : '';
            if (!is_array($sourceItem)
                || $sourceSignificant === ''
                || !$this->sourcePdfSourceItemHasExactGeometry($sourceItem)
                || (int) ($sourceItem['page'] ?? 0) !== $page
                || $range['sourceEnd'] !== strlen($sourceSignificant)
                || ($offset > 0 && $range['sourceStart'] !== 0)
                || ($previousGlobalIndex !== null && $globalIndex !== $previousGlobalIndex + 1)
                || ($previousLocalIndex !== null && $localIndex !== $previousLocalIndex + 1)) {
                return null;
            }
            $sourceProjection .= substr(
                $sourceSignificant,
                $range['sourceStart'],
                $range['sourceEnd'] - $range['sourceStart']
            );
            $previousGlobalIndex = $globalIndex;
            $previousLocalIndex = $localIndex;
            if ($offset === array_key_last($ranges)) {
                $terminalOccurrence = [
                    'sourceIndex' => $globalIndex,
                    'sourceLocalIndex' => $localIndex,
                    'page' => $page,
                    'stream' => max(1, (int) ($sourceItem['stream'] ?? 1)),
                    'significantBytes' => strlen($sourceSignificant),
                    'significantDigest' => hash('sha256', $sourceSignificant),
                ];
            }
        }
        if (!hash_equals($sourceProjection, $projection)
            || !is_array($terminalOccurrence)
            || preg_match(
                '/^\p{Sc}$/u',
                substr($projection, -$terminalOccurrence['significantBytes'])
            ) !== 1) {
            return null;
        }

        $proof = [
            'version' => 1,
            'method' => 'source-inventory-exact-form-tail-occurrence',
            'page' => $page,
            'ranges' => $ranges,
            'terminalOccurrence' => $terminalOccurrence,
            'projectionDigest' => hash('sha256', $projection),
        ];
        $proof['proofDigest'] = hash('sha256', json_encode(
            $proof,
            JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE
        ) ?: '');

        return $proof;
    }

    /**
     * Stamp immutable source-inventory facts only after every exact range has
     * been checked against its actual occurrence. Boundary repair can then
     * distinguish a whole multi-occurrence carrier from a merely plausible
     * range-length sum without retaining the full source inventory.
     *
     * @param array<string,mixed> $layout
     * @param list<array<string,mixed>> $sourceItems
     * @return array<string,mixed>|null
     */
    private function pdfSourceLayoutWholeExactOccurrenceProof(
        array $layout,
        array $sourceItems
    ): ?array {
        $hasExactPositionedText = ($layout['sourcePdfExactPositionedText'] ?? false) === true;
        $hasPageExactSourceInventory =
            ($layout['sourcePdfPageExactInventoryPreserved'] ?? false) === true;
        if ((!$hasExactPositionedText && !$hasPageExactSourceInventory)
            || ($layout['sourcePdfExactGeometryFallback'] ?? false) === true
            || ($layout['sourceUnmatchedFallback'] ?? false) === true
            || ($layout['sourceSupplementalPositioned'] ?? false) === true
            || ($layout['sourceShortSupplementalCandidate'] ?? false) === true
            || ($layout['sourceSupplementalRecoverableSentenceSuffix'] ?? false) === true
            || !is_numeric($layout['page'] ?? null)) {
            return null;
        }

        $ranges = $this->pdfPositionedExactSourceRanges($layout);
        $page = max(1, (int) $layout['page']);
        $coverage = $this->sourcePdfExactRangeCoverage(
            $sourceItems,
            $ranges,
            $page,
            true
        );
        $layoutProjection = $this->pdfSourceOccurrenceComparableText(
            $this->pdfTextWithoutSemanticPrefixes((string) ($layout['text'] ?? ''))
        );
        if ($coverage === null
            || $layoutProjection === ''
            || !hash_equals($coverage['projection'], $layoutProjection)) {
            return null;
        }

        $occurrences = [];
        foreach ($coverage['globalIndexes'] as $offset => $sourceIndex) {
            $localIndex = $coverage['localIndexes'][$offset] ?? null;
            $sourceItem = is_int($localIndex) ? ($sourceItems[$localIndex] ?? null) : null;
            $sourceSignificant = is_array($sourceItem)
                ? $this->pdfSourceOccurrenceComparableText((string) ($sourceItem['text'] ?? ''))
                : '';
            if (!is_array($sourceItem) || $sourceSignificant === '') {
                return null;
            }
            $occurrences[] = [
                'sourceIndex' => $sourceIndex,
                'sourceLocalIndex' => $localIndex,
                'page' => $page,
                'stream' => max(1, (int) ($sourceItem['stream'] ?? 1)),
                'significantBytes' => strlen($sourceSignificant),
                'significantDigest' => hash('sha256', $sourceSignificant),
            ];
        }

        $proof = [
            'version' => 1,
            'method' => 'source-inventory-whole-occurrence-union',
            'page' => $page,
            'layoutStream' => is_numeric($layout['sourceStream'] ?? null)
                ? max(1, (int) $layout['sourceStream'])
                : null,
            'occurrences' => $occurrences,
            'ranges' => $coverage['ranges'],
            'projectionDigest' => hash('sha256', $coverage['projection']),
        ];
        $proof['proofDigest'] = hash('sha256', json_encode(
            $proof,
            JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE
        ) ?: '');

        return $proof;
    }

    /**
     * Convert document-global positioned range indexes to the compact page-local
     * index space used by an isolated binding proof.  Page-local source indexes
     * remain unchanged; only fields explicitly documented as global are
     * rewritten.
     *
     * @param list<array<string,mixed>> $sourceItems
     * @param list<array<string,mixed>> $sourceLayouts
     * @return array{sourceItems:list<array<string,mixed>>,sourceLayouts:list<array<string,mixed>>,localByGlobal:array<int,int>}|null
     */
    private function pdfPageLocalSourceBindingInputs(
        int $page,
        array $sourceItems,
        array $sourceLayouts
    ): ?array {
        // Every caller supplies the proof inventory produced by the main
        // exact-range enrichment pass. Repeating that whole-document pass for
        // each speculative page retained two global ID indexes beside the
        // localized candidate and could not add any new evidence.
        $pageSourceItems = [];
        $localByGlobal = [];
        foreach ($sourceItems as $globalIndex => $sourceItem) {
            if (max(1, (int) ($sourceItem['page'] ?? 1)) !== $page) {
                continue;
            }
            $localByGlobal[$globalIndex] = count($pageSourceItems);
            $pageSourceItems[] = $sourceItem;
        }
        if ($pageSourceItems === []) {
            return null;
        }

        $pageLayouts = [];
        foreach ($sourceLayouts as $layout) {
            if (!is_array($layout)
                || max(1, (int) ($layout['page'] ?? 1)) !== $page) {
                continue;
            }
            $localized = $this->pdfPageLocalSourceBindingLayout($layout, $localByGlobal);
            if ($localized === null) {
                return null;
            }
            $pageLayouts[] = $localized;
        }

        return [
            'sourceItems' => $pageSourceItems,
            'sourceLayouts' => $pageLayouts,
            'localByGlobal' => $localByGlobal,
        ];
    }

    /**
     * @param array<string,mixed> $layout
     * @param array<int,int> $localByGlobal
     * @return array<string,mixed>|null
     */
    private function pdfPageLocalSourceBindingLayout(array $layout, array $localByGlobal): ?array
    {
        // This proof is document-global and exists only for destructive prose
        // boundary repair. Exact page-candidate binding localizes occurrence
        // indexes below and must not retain a stale global proof payload.
        unset($layout['sourcePdfWholeExactOccurrenceProof']);
        if (isset($layout['sourcePdfGlobalSourceIndex'])) {
            $globalIndex = $layout['sourcePdfGlobalSourceIndex'];
            if (!is_int($globalIndex) || !isset($localByGlobal[$globalIndex])) {
                return null;
            }
            $layout['sourcePdfGlobalSourceIndex'] = $localByGlobal[$globalIndex];
        }
        if (isset($layout['sourcePdfExactSourceIndex'])) {
            $globalIndex = $layout['sourcePdfExactSourceIndex'];
            if (!is_int($globalIndex) || !isset($localByGlobal[$globalIndex])) {
                return null;
            }
            $layout['sourcePdfExactSourceIndex'] = $localByGlobal[$globalIndex];
        }
        if (isset($layout['sourcePdfExactSourceRanges'])) {
            if (!is_array($layout['sourcePdfExactSourceRanges'])) {
                return null;
            }
            $localizedRanges = [];
            foreach ($layout['sourcePdfExactSourceRanges'] as $range) {
                $globalIndex = is_array($range) ? ($range['sourceIndex'] ?? null) : null;
                if (!is_int($globalIndex) || !isset($localByGlobal[$globalIndex])) {
                    return null;
                }
                $range['sourceIndex'] = $localByGlobal[$globalIndex];
                $localizedRanges[] = $range;
            }
            $layout['sourcePdfExactSourceRanges'] = $localizedRanges;
        }

        return $layout;
    }

    /**
     * @param list<AstNode> $candidateBlocks
     * @param array{sourceItems:list<array<string,mixed>>,sourceLayouts:list<array<string,mixed>>,localByGlobal:array<int,int>} $inputs
     * @return array{complete:bool,failureReason:?string,explicitDispositions:array<string,array<string,mixed>|string>}
     */
    private function validatePositionedPdfPageCandidateSourceBinding(
        int $page,
        array $candidateBlocks,
        array $inputs
    ): array {
        // Disposition/order-proof construction records diagnostics and counters.
        // Run the speculative proof on a clone so a rejected candidate cannot
        // alter the final document's evidence.
        $validator = clone $this;
        $validator->sourceOrderProofDiagnostics = [];
        // A mixed page can contain a selected independent-column region and
        // a real table.  Its complete candidate is the only final page output
        // available to the existing exact independent-scope proof.
        $validator->sourceProofCandidateBlocksByPage[$page] = $candidateBlocks;
        $candidateLayouts = $validator->positionedPdfCandidateSourceLayouts(
            $candidateBlocks,
            $inputs['sourceLayouts'],
            $inputs['localByGlobal']
        );
        $candidateOrderProofLayouts = $candidateLayouts ?? $inputs['sourceLayouts'];
        $explicit = $validator->explicitPdfSourceDispositions(
            $inputs['sourceItems'],
            $candidateBlocks,
            [$page],
            $candidateOrderProofLayouts
        );
        unset($validator, $candidateLayouts, $candidateOrderProofLayouts);
        $binding = PdfSourceDispositionLedger::validateSourceLineItemsToOutput(
            $inputs['sourceItems'],
            $candidateBlocks,
            $explicit
        );

        $complete = ($binding['complete'] ?? false) === true;
        $failureReason = is_string($binding['failureReason'] ?? null)
            ? $binding['failureReason']
            : null;
        unset($binding);

        return [
            'complete' => $complete,
            'failureReason' => $failureReason,
            'explicitDispositions' => $explicit,
        ];
    }

    /**
     * Recreate the exact layout sequence represented by final semantic
     * carriers. Table cells use their retained source subranges; ordinary
     * paragraphs/headings reuse one unique source layout with the same visible
     * projection. Returning null leaves the established conservative proof
     * fallbacks in charge.
     *
     * @param list<AstNode> $candidateBlocks
     * @param list<array<string,mixed>> $sourceLayouts
     * @param array<int,int> $localByGlobal
     * @return list<array<string,mixed>>|null
     */
    private function positionedPdfCandidateSourceLayouts(
        array $candidateBlocks,
        array $sourceLayouts,
        array $localByGlobal
    ): ?array {
        $carriers = [];
        foreach ($candidateBlocks as $block) {
            $this->appendPositionedPdfCandidateLayoutCarriers($block, $carriers);
        }
        if ($carriers === []) {
            return null;
        }

        $usedLayouts = [];
        $layouts = [];
        foreach ($carriers as $carrier) {
            if ($carrier['tableCell']) {
                $layout = $this->pdfPageLocalSourceBindingLayout(
                    $carrier['attrs'],
                    $localByGlobal
                );
                if ($layout === null
                    || $this->pdfPositionedExactSourceRanges($layout) === []) {
                    return null;
                }
                $layout['page'] = max(1, (int) (
                    $layout['sourcePdfGeometryPage'] ?? $layout['page'] ?? 1
                ));
                $layout['text'] = $carrier['text'];
                $layouts[] = $layout;
                continue;
            }

            $key = $this->pdfSourceOccurrenceComparableText($carrier['text']);
            $matches = [];
            foreach ($sourceLayouts as $layoutIndex => $sourceLayout) {
                if (isset($usedLayouts[$layoutIndex])) {
                    continue;
                }
                $layoutText = $this->pdfTextWithoutSemanticPrefixes(
                    (string) ($sourceLayout['text'] ?? '')
                );
                if ($key !== ''
                    && $this->pdfSourceOccurrenceComparableText($layoutText) === $key) {
                    $matches[] = $layoutIndex;
                }
            }
            if (count($matches) !== 1) {
                return null;
            }
            $layoutIndex = $matches[0];
            $usedLayouts[$layoutIndex] = true;
            $layout = $sourceLayouts[$layoutIndex];
            $layout['text'] = $carrier['text'];
            $layouts[] = $layout;
        }

        return $layouts;
    }

    /**
     * Replace proof layouts only on pages whose semantic candidate was already
     * accepted.  Other pages retain the established source/repaired layout
     * sequence byte for byte.
     *
     * @param list<array<string,mixed>> $sourceLayouts
     * @param array<int,list<AstNode>> $candidatePages
     * @return list<array<string,mixed>>
     */
    private function positionedPdfSourceOrderProofLayoutsWithCandidatePages(
        array $sourceLayouts,
        array $candidatePages,
        int $sourceItemCount
    ): array {
        $layoutsByPage = [];
        foreach ($sourceLayouts as $layout) {
            $page = max(1, (int) ($layout['page'] ?? 1));
            $layoutsByPage[$page][] = $layout;
        }
        $pages = array_fill_keys(array_keys($layoutsByPage), true);
        foreach (array_keys($candidatePages) as $page) {
            $pages[(int) $page] = true;
        }
        ksort($pages, SORT_NUMERIC);
        $identityIndexes = [];
        for ($index = 0; $index < $sourceItemCount; $index++) {
            $identityIndexes[$index] = $index;
        }

        $layouts = [];
        foreach (array_keys($pages) as $page) {
            $pageLayouts = $layoutsByPage[$page] ?? [];
            if (isset($candidatePages[$page])) {
                $candidateLayouts = $this->positionedPdfCandidateSourceLayouts(
                    $candidatePages[$page],
                    $pageLayouts,
                    $identityIndexes
                );
                if ($candidateLayouts !== null) {
                    $pageLayouts = $candidateLayouts;
                }
            }
            array_push($layouts, ...$pageLayouts);
        }

        return $layouts;
    }

    /**
     * Geometry wins a same-page collision, while accepted candidates on every
     * other page remain in the one map shared by proofing and composition.
     *
     * @param array<int,list<AstNode>> $independentPages
     * @param array<int,list<AstNode>> $geometryPages
     * @return array<int,list<AstNode>>
     */
    private function pdfCanonicalSelectedCandidatePages(
        array $independentPages,
        array $geometryPages
    ): array {
        $selected = array_replace($independentPages, $geometryPages);
        ksort($selected, SORT_NUMERIC);

        return $selected;
    }

    /**
     * @param list<array{text:string,attrs:array<string,mixed>,tableCell:bool}> $carriers
     */
    private function appendPositionedPdfCandidateLayoutCarriers(
        AstNode $node,
        array &$carriers
    ): void {
        $text = is_string($node->attr('text', null))
            ? (string) $node->attr('text')
            : '';
        if ($node->type === 'table_cell') {
            if ($this->pdfSourceOccurrenceComparableText($text) !== '') {
                $carriers[] = [
                    'text' => $text,
                    'attrs' => $node->baseAttrs(),
                    'tableCell' => true,
                ];
            }

            return;
        }
        if (in_array(
            $node->type,
            ['paragraph', 'heading', 'code_block', 'line'],
            true
        ) && $this->pdfSourceOccurrenceComparableText($text) !== '') {
            $carriers[] = [
                'text' => $text,
                'attrs' => $node->baseAttrs(),
                'tableCell' => false,
            ];

            return;
        }
        foreach ($node->children as $child) {
            $this->appendPositionedPdfCandidateLayoutCarriers($child, $carriers);
        }
    }

    /**
     * Recover a shortened carrier only when one exact source occurrence and
     * one final AST leaf explain the complete page inventory difference.  This
     * is deliberately different from appending a missing atom as a new block:
     * the surviving carrier fixes the destination, and the full page binding is
     * rerun before the candidate can be accepted.
     *
     * @param list<AstNode> $candidateBlocks
     * @param list<array<string,mixed>> $sourceItems
     * @param array<string,array<string,mixed>|string> $explicitDispositions
     * @return list<AstNode>|null
     */
    private function positionedPdfCandidateWithUniquePartialSourceLeafRecovery(
        array $candidateBlocks,
        array $sourceItems,
        array $explicitDispositions
    ): ?array {
        $sourceProjection = '';
        $projectedRecords = [];
        foreach ($sourceItems as $sourceItem) {
            $id = is_string($sourceItem['id'] ?? null) ? $sourceItem['id'] : '';
            $explicitValue = $id !== '' ? ($explicitDispositions[$id] ?? null) : null;
            $explicit = is_array($explicitValue)
                ? $explicitValue
                : (is_string($explicitValue) ? ['disposition' => $explicitValue] : []);
            $kind = (string) ($explicit['disposition'] ?? 'emitted');
            if (!in_array($kind, ['emitted', 'boundary-repair', 'semantic-structure'], true)) {
                continue;
            }
            $projection = is_string($explicit['textProjection'] ?? null)
                ? $explicit['textProjection']
                : (string) ($sourceItem['text'] ?? '');
            $significant = $this->pdfSourceOccurrenceComparableText($projection);
            if ($significant === '') {
                continue;
            }
            $sourceProjection .= $significant;
            $projectedRecords[] = [
                'projection' => $projection,
                'significant' => $significant,
                'sourceItem' => $sourceItem,
            ];
        }

        $candidateLeaves = [];
        foreach ($candidateBlocks as $block) {
            $this->appendPositionedPdfRecoverableTextLeaves($block, $candidateLeaves);
        }
        // Protected leaves remain ineligible as replacement targets, but
        // their text must still participate in whole-page conservation.
        $candidateProjection = $this->pdfSignificantProjectionFromBlocks($candidateBlocks);
        $sourceInventory = $this->pdfExactCharacterInventory($sourceProjection);
        $candidateInventory = $this->pdfExactCharacterInventory($candidateProjection);
        $inventoryDelta = $this->pdfExactCharacterInventoryDelta(
            $sourceInventory,
            $candidateInventory
        );
        $sourceOnly = $inventoryDelta['leftOnly'];
        $missingCharacters = array_sum($sourceOnly);
        if ($inventoryDelta['rightOnly'] !== []
            || $missingCharacters < 1
            || $missingCharacters > 8) {
            return null;
        }

        $matches = [];
        foreach ($projectedRecords as $record) {
            $sourceItem = $record['sourceItem'];
            if (($sourceItem['sourceGeometryMethod'] ?? null)
                    !== 'exact-page-stream-character-offset'
                || !is_array($sourceItem['sourceGeometry'] ?? null)
                || !$this->pdfSourceBoundsAreValid($sourceItem['sourceGeometry'])) {
                continue;
            }
            $recordInventory = $this->pdfExactCharacterInventory($record['significant']);
            foreach ($candidateLeaves as $leaf) {
                $leafSignificant = $this->pdfSourceOccurrenceComparableText($leaf['text']);
                if (strlen($leafSignificant) < 4
                    || strlen($leafSignificant) >= strlen($record['significant'])
                    || !$this->pdfUtf8StringIsSubsequence(
                        $leafSignificant,
                        $record['significant']
                    )) {
                    continue;
                }
                $difference = $this->pdfExactCharacterInventoryDifference(
                    $recordInventory,
                    $this->pdfExactCharacterInventory($leafSignificant)
                );
                if ($difference === $sourceOnly) {
                    $matches[] = [
                        'leaf' => $leaf['node'],
                        'oldText' => $leaf['text'],
                        'replacement' => trim($record['projection']),
                    ];
                    if (count($matches) > 1) {
                        return null;
                    }
                }
            }
        }
        if (count($matches) !== 1 || $matches[0]['replacement'] === '') {
            return null;
        }

        $replacementCount = 0;
        $recovered = [];
        foreach ($candidateBlocks as $block) {
            $recovered[] = $this->positionedPdfAstNodeWithReplacedTextLeaf(
                $block,
                $matches[0]['leaf'],
                $matches[0]['oldText'],
                $matches[0]['replacement'],
                $replacementCount
            );
        }

        return $replacementCount === 1 ? $recovered : null;
    }

    /**
     * A geometry page can retain every table cell while omitting one painted
     * standalone marker from adjacent prose. Restore it as literal text only
     * when it is the complete candidate/source inventory difference, has no
     * semantic disposition, its exact occurrence bbox leads the consecutive
     * source line on the same baseline, and that line begins one unique final
     * text leaf. The caller reruns complete page binding before selection.
     *
     * @param list<AstNode> $candidateBlocks
     * @param list<array<string,mixed>> $sourceItems
     * @param array<string,array<string,mixed>|string> $explicitDispositions
     * @return list<AstNode>|null
     */
    private function positionedPdfCandidateWithUniqueStandaloneMarkerPrefixRecovery(
        array $candidateBlocks,
        array $sourceItems,
        array $explicitDispositions
    ): ?array {
        $sourceProjection = '';
        foreach ($sourceItems as $sourceItem) {
            $id = is_string($sourceItem['id'] ?? null) ? $sourceItem['id'] : '';
            $explicitValue = $id !== '' ? ($explicitDispositions[$id] ?? null) : null;
            $explicit = is_array($explicitValue)
                ? $explicitValue
                : (is_string($explicitValue) ? ['disposition' => $explicitValue] : []);
            $kind = (string) ($explicit['disposition'] ?? 'emitted');
            if (!in_array($kind, ['emitted', 'boundary-repair', 'semantic-structure'], true)) {
                continue;
            }
            $projection = is_string($explicit['textProjection'] ?? null)
                ? $explicit['textProjection']
                : (string) ($sourceItem['text'] ?? '');
            $sourceProjection .= $this->pdfSourceOccurrenceComparableText($projection);
        }

        $candidateLeaves = [];
        foreach ($candidateBlocks as $block) {
            $this->appendPositionedPdfRecoverableTextLeaves($block, $candidateLeaves);
        }
        // Protected leaves are ineligible as the replacement target, but
        // their existing text still participates in whole-page conservation.
        $candidateProjection = $this->pdfSignificantProjectionFromBlocks($candidateBlocks);
        $inventoryDelta = $this->pdfExactCharacterInventoryDelta(
            $this->pdfExactCharacterInventory($sourceProjection),
            $this->pdfExactCharacterInventory($candidateProjection)
        );
        $sourceOnly = $inventoryDelta['leftOnly'];
        if ($sourceOnly === []
            || $inventoryDelta['rightOnly'] !== []
            || array_sum($sourceOnly) > 4) {
            return null;
        }

        $matches = [];
        foreach ($sourceItems as $sourceIndex => $markerItem) {
            $marker = trim((string) ($markerItem['text'] ?? ''));
            $markerId = is_string($markerItem['id'] ?? null)
                ? $markerItem['id']
                : '';
            $explicitValue = $markerId !== ''
                ? ($explicitDispositions[$markerId] ?? null)
                : null;
            $explicit = is_array($explicitValue)
                ? $explicitValue
                : (is_string($explicitValue) ? ['disposition' => $explicitValue] : []);
            $projectedMarker = is_string($explicit['textProjection'] ?? null)
                ? $explicit['textProjection']
                : $marker;
            if (!$this->lineIsStandalonePdfListMarker($marker)
                || (string) ($explicit['disposition'] ?? 'emitted') !== 'emitted'
                || $this->pdfExactCharacterInventory(
                    $this->pdfSourceOccurrenceComparableText($projectedMarker)
                ) !== $sourceOnly) {
                continue;
            }
            $successor = $sourceItems[$sourceIndex + 1] ?? null;
            if (!is_array($successor)
                || !$this->sourcePdfExactInlineMarkerLeadsSuccessor(
                    $markerItem,
                    $successor
                )) {
                continue;
            }
            $successorProjection = $this->pdfSourceOccurrenceComparableText(
                (string) ($successor['text'] ?? '')
            );
            if ($successorProjection === '') {
                continue;
            }
            foreach ($candidateLeaves as $leaf) {
                $leafProjection = $this->pdfSourceOccurrenceComparableText($leaf['text']);
                if (!str_starts_with($leafProjection, $successorProjection)) {
                    continue;
                }
                $matches[] = [
                    'leaf' => $leaf['node'],
                    'oldText' => $leaf['text'],
                    'replacement' => $marker . ' ' . ltrim($leaf['text']),
                ];
                if (count($matches) > 1) {
                    return null;
                }
            }
        }
        if (count($matches) !== 1) {
            return null;
        }

        $replacementCount = 0;
        $recovered = [];
        foreach ($candidateBlocks as $block) {
            $recovered[] = $this->positionedPdfAstNodeWithReplacedTextLeaf(
                $block,
                $matches[0]['leaf'],
                $matches[0]['oldText'],
                $matches[0]['replacement'],
                $replacementCount
            );
        }

        return $replacementCount === 1 ? $recovered : null;
    }

    /** @param array<string,mixed> $marker @param array<string,mixed> $successor */
    private function sourcePdfExactInlineMarkerLeadsSuccessor(
        array $marker,
        array $successor
    ): bool {
        $markerGeometry = is_array($marker['sourceGeometry'] ?? null)
            ? $marker['sourceGeometry']
            : null;
        $successorGeometry = is_array($successor['sourceGeometry'] ?? null)
            ? $successor['sourceGeometry']
            : null;
        if (($marker['sourceGeometryMethod'] ?? null)
                !== 'exact-page-stream-character-offset'
            || ($successor['sourceGeometryMethod'] ?? null)
                !== 'exact-page-stream-character-offset'
            || !is_array($markerGeometry)
            || !is_array($successorGeometry)
            || !$this->pdfSourceBoundsAreValid($markerGeometry)
            || !$this->pdfSourceBoundsAreValid($successorGeometry)
            || !isset(
                $marker['page'],
                $marker['stream'],
                $successor['page'],
                $successor['stream'],
                $markerGeometry['page'],
                $markerGeometry['stream'],
                $successorGeometry['page'],
                $successorGeometry['stream']
            )
            || !is_numeric($marker['page'])
            || !is_numeric($marker['stream'])
            || !is_numeric($successor['page'])
            || !is_numeric($successor['stream'])
            || !is_numeric($markerGeometry['page'])
            || !is_numeric($markerGeometry['stream'])
            || !is_numeric($successorGeometry['page'])
            || !is_numeric($successorGeometry['stream'])
            || (int) $markerGeometry['page'] !== (int) $marker['page']
            || (int) $markerGeometry['stream'] !== (int) $marker['stream']
            || (int) $successorGeometry['page'] !== (int) $successor['page']
            || (int) $successorGeometry['stream'] !== (int) $successor['stream']
            || ($marker['page'] ?? null) !== ($successor['page'] ?? null)
            || ($marker['stream'] ?? null) !== ($successor['stream'] ?? null)
            || ($markerGeometry['orientation'] ?? null) !== 'horizontal'
            || ($successorGeometry['orientation'] ?? null) !== 'horizontal') {
            return false;
        }
        $minimumHeight = min(
            (float) $markerGeometry['y2'] - (float) $markerGeometry['y1'],
            (float) $successorGeometry['y2'] - (float) $successorGeometry['y1']
        );
        $verticalOverlap = min(
            (float) $markerGeometry['y2'],
            (float) $successorGeometry['y2']
        ) - max(
            (float) $markerGeometry['y1'],
            (float) $successorGeometry['y1']
        );

        return $minimumHeight > 0.0
            && $verticalOverlap >= $minimumHeight * 0.70
            && (float) $successorGeometry['x1'] >= (float) $markerGeometry['x1'] - 0.75
            && (float) $successorGeometry['x1']
                <= (float) $markerGeometry['x2'] + max(6.0, $minimumHeight * 0.75)
            && (float) $successorGeometry['x2'] > (float) $markerGeometry['x2'] + 0.25;
    }

    /**
     * @param list<array{node:AstNode,text:string}> $leaves
     */
    private function appendPositionedPdfRecoverableTextLeaves(
        AstNode $node,
        array &$leaves,
        bool $protected = false
    ): void {
        $protected = $protected || in_array(
            $node->type,
            ['code_block', 'link', 'image', 'formula'],
            true
        );
        if ($node->children === []) {
            $text = (string) $node->attr('text', '');
            if (!$protected && $node->type === 'text'
                && $this->pdfSourceOccurrenceComparableText($text) !== '') {
                $leaves[] = ['node' => $node, 'text' => $text];
            }

            return;
        }
        foreach ($node->children as $child) {
            $this->appendPositionedPdfRecoverableTextLeaves($child, $leaves, $protected);
        }
    }

    private function pdfUtf8StringIsSubsequence(string $candidate, string $source): bool
    {
        $candidateCharacters = preg_split('//u', $candidate, -1, PREG_SPLIT_NO_EMPTY);
        $sourceCharacters = preg_split('//u', $source, -1, PREG_SPLIT_NO_EMPTY);
        if ($candidateCharacters === false || $sourceCharacters === false) {
            return false;
        }
        $candidateIndex = 0;
        foreach ($sourceCharacters as $sourceCharacter) {
            if (($candidateCharacters[$candidateIndex] ?? null) === $sourceCharacter) {
                $candidateIndex++;
            }
        }

        return $candidateIndex === count($candidateCharacters);
    }

    private function positionedPdfAstNodeWithReplacedTextLeaf(
        AstNode $node,
        AstNode $target,
        string $oldText,
        string $replacement,
        int &$replacementCount
    ): AstNode {
        if ($node === $target) {
            $attrs = $node->baseAttrs();
            $attrs['text'] = $replacement;
            $replacementCount++;

            return new AstNode($node->type, $attrs);
        }
        if ($node->children === []) {
            return $node;
        }

        $changed = false;
        $children = [];
        foreach ($node->children as $child) {
            $updated = $this->positionedPdfAstNodeWithReplacedTextLeaf(
                $child,
                $target,
                $oldText,
                $replacement,
                $replacementCount
            );
            $changed = $changed || $updated !== $child;
            $children[] = $updated;
        }
        if (!$changed) {
            return $node;
        }

        $attrs = $node->baseAttrs();
        if (is_string($attrs['text'] ?? null)) {
            $count = substr_count($attrs['text'], $oldText);
            if ($oldText !== '' && $count === 1) {
                $attrs['text'] = str_replace($oldText, $replacement, $attrs['text']);
            } elseif ($this->pdfSourceOccurrenceComparableText($attrs['text'])
                === $this->pdfSourceOccurrenceComparableText($oldText)) {
                $attrs['text'] = $replacement;
            }
        }

        return new AstNode(
            $node->type,
            $attrs,
            $children,
            $node->attributeResolver()
        );
    }

    /**
     * Geometry is authoritative for a page with a verified table, but using
     * it for every other page can scramble ordinary multi-column prose. Keep
     * source-reconciled text on those pages and replace only the table pages.
     *
     * @param list<string> $sourceLines
     * @param list<array<string, mixed>> $sourceLayouts
     * @param array<int, list<AstNode>> $tableBlocksByPage
     * @param array<int,string>|null $outputPageProjections
     * @return list<AstNode>
     */
    private function blocksWithPositionedPdfTablePages(
        array $sourceLines,
        array $sourceLayouts,
        array $tableBlocksByPage,
        ?array &$outputPageProjections = null
    ): array {
        $outputPageProjections = [];
        $pageProjectionAvailable = true;
        $linesByPage = [];
        $layoutsByPage = [];
        foreach ($sourceLines as $index => $line) {
            $layout = is_array($sourceLayouts[$index] ?? null) ? $sourceLayouts[$index] : [];
            $page = max(1, (int) ($layout['page'] ?? 1));
            $linesByPage[$page][] = $line;
            $layoutsByPage[$page][] = $layout;
        }
        $layoutLabelTextCountsByPage = [];
        foreach ($sourceLines as $index => $line) {
            $layout = is_array($sourceLayouts[$index] ?? null) ? $sourceLayouts[$index] : [];
            if (($layout['sourcePdfLayoutLabel'] ?? false) !== true) {
                continue;
            }
            $key = $this->pdfComparableLineText($this->pdfTextWithoutSemanticPrefixes((string) $line));
            if ($key === '') {
                continue;
            }
            $page = max(1, (int) ($layout['page'] ?? 1));
            $layoutLabelTextCountsByPage[$page][$key] =
                ($layoutLabelTextCountsByPage[$page][$key] ?? 0) + 1;
        }

        $pages = array_fill_keys(array_keys($linesByPage), true);
        foreach (array_keys($tableBlocksByPage) as $page) {
            $pages[(int) $page] = true;
        }
        ksort($pages, SORT_NUMERIC);
        $acceptedCandidatePages = array_fill_keys(
            array_map('intval', array_keys($tableBlocksByPage)),
            true
        );
        $displayHeadingReferences = $this->positionedPdfAcceptedDisplayHeadingReferences(
            $tableBlocksByPage,
            $acceptedCandidatePages
        );

        $blocks = [];
        $pendingLines = [];
        $pendingLayouts = [];
        $flushPendingProse = function () use (
            &$blocks,
            &$pendingLines,
            &$pendingLayouts,
            &$outputPageProjections,
            &$pageProjectionAvailable
        ): void {
            if ($pendingLines === []) {
                return;
            }
            $pendingPageProjections = null;
            $pendingLineSpans = [];
            if ($this->proseTextRepairEnabled()) {
                $repaired = $this->repairProseTextLines(
                    $pendingLines,
                    $this->looksLikeProseRepairCandidate($pendingLines),
                    $pendingLayouts,
                    $pendingPageProjections,
                    $pendingLineSpans
                );
            } else {
                $repaired = $pendingLines;
            }
            foreach ($this->blocksFromLines($repaired, true, $pendingLineSpans) as $block) {
                $blocks[] = $block;
            }
            if (!is_array($pendingPageProjections)) {
                $pageProjectionAvailable = false;
            } else {
                foreach ($pendingPageProjections as $page => $projection) {
                    $page = (int) $page;
                    if ($page < 1
                        || !is_string($projection)
                        || $projection === ''
                        || isset($outputPageProjections[$page])) {
                        $pageProjectionAvailable = false;
                        break;
                    }
                    $outputPageProjections[$page] = $projection;
                }
            }
            $pendingLines = [];
            $pendingLayouts = [];
        };
        foreach (array_keys($pages) as $page) {
            if (isset($tableBlocksByPage[$page])) {
                $flushPendingProse();
                $acceptedPageBlocks = $this->positionedPdfBlocksWithAcceptedTablePageRoles(
                    (int) $page,
                    $tableBlocksByPage[$page],
                    $acceptedCandidatePages,
                    $displayHeadingReferences
                );
                $pageBlocks = $this->pdfBlocksWithOutputPageProof(
                    (int) $page,
                    $acceptedPageBlocks
                );
                $pageProjection = $this->pdfSignificantProjectionFromBlocks($pageBlocks);
                if ($pageProjection === '' || isset($outputPageProjections[(int) $page])) {
                    $pageProjectionAvailable = false;
                } else {
                    $outputPageProjections[(int) $page] = $pageProjection;
                }
                foreach ($pageBlocks as $block) {
                    if ($block->type === 'heading') {
                        $key = $this->pdfComparableLineText((string) $block->attr('text', ''));
                        $remaining = (int) ($layoutLabelTextCountsByPage[$page][$key] ?? 0);
                        if ($key !== '' && $remaining > 0) {
                            $classes = is_array($block->attr('classes', null))
                                ? $block->attr('classes')
                                : [];
                            $classes[] = 'pdf-layout-label';
                            $block = new AstNode(
                                'paragraph',
                                array_replace($block->baseAttrs(), [
                                    'text' => (string) $block->attr('text', ''),
                                    'classes' => array_values(array_unique($classes)),
                                    'sourceRole' => 'layout-label',
                                ]),
                                $block->children()
                            );
                            $layoutLabelTextCountsByPage[$page][$key] = $remaining - 1;
                        }
                    }
                    $blocks[] = $block;
                }
                continue;
            }

            $pageLines = $linesByPage[$page] ?? [];
            if ($pageLines === []) {
                continue;
            }
            $pageLayouts = $layoutsByPage[$page] ?? [];
            array_push($pendingLines, ...$pageLines);
            array_push($pendingLayouts, ...$pageLayouts);
        }
        $flushPendingProse();
        if (!$pageProjectionAvailable) {
            $outputPageProjections = null;
        } else {
            ksort($outputPageProjections, SORT_NUMERIC);
        }

        return $blocks;
    }

    /**
     * Role receipts are generated while table geometry is still available,
     * but become authoritative only here, after exact page-source binding has
     * selected both the candidate and (for homology) its supporting page.
     * This changes structure only; the accepted page text projection remains
     * byte-for-byte identical.
     *
     * @param list<AstNode> $blocks
     * @param array<int,true> $acceptedCandidatePages
     * @param list<array<string,mixed>> $displayHeadingReferences
     * @return list<AstNode>
     */
    private function positionedPdfBlocksWithAcceptedTablePageRoles(
        int $page,
        array $blocks,
        array $acceptedCandidatePages,
        array $displayHeadingReferences = []
    ): array {
        foreach ($blocks as &$block) {
            $attrs = $block->baseAttrs();
            $layoutProof = is_array($attrs['sourcePdfTableLayoutRoleProof'] ?? null)
                ? $attrs['sourcePdfTableLayoutRoleProof']
                : null;
            $displayProof = is_array($attrs['sourcePdfTableDisplayHeadingProof'] ?? null)
                ? $attrs['sourcePdfTableDisplayHeadingProof']
                : null;
            unset(
                $attrs['sourcePdfTableLayoutRoleProof'],
                $attrs['sourcePdfTableDisplayHeadingProof']
            );

            $type = $block->type;
            if ($layoutProof !== null
                && $type === 'heading'
                && $this->positionedPdfTablePageRoleProofIsValid(
                    $layoutProof,
                    $page,
                    (string) $block->attr('text', ''),
                    $acceptedCandidatePages,
                    ['column-header-label', 'summary-label', 'homologous-table-label']
                )) {
                $type = 'paragraph';
                unset($attrs['level']);
                $classes = is_array($attrs['classes'] ?? null) ? $attrs['classes'] : [];
                $classes[] = 'pdf-layout-label';
                $attrs['classes'] = array_values(array_unique($classes));
                $attrs['sourceRole'] = 'layout-label';
            } elseif ($displayProof !== null
                && in_array($type, ['paragraph', 'heading'], true)
                && $this->positionedPdfTablePageRoleProofIsValid(
                    $displayProof,
                    $page,
                    (string) $block->attr('text', ''),
                    $acceptedCandidatePages,
                    ['display-heading']
                )) {
                $repair = $this->positionedPdfDisplayHeadingLeadingTokenRepair(
                    (string) $block->attr('text', ''),
                    $displayProof,
                    $displayHeadingReferences,
                    $page
                );
                if ($repair !== null) {
                    $attrs['text'] = $repair['text'];
                    $attrs['sourcePdfDisplayTokenRepairProof'] = $repair['proof'];
                    $block = new AstNode(
                        $block->type,
                        array_replace($block->baseAttrs(), [
                            'text' => $repair['text'],
                            'sourcePdfDisplayTokenRepairProof' => $repair['proof'],
                        ]),
                        $this->inlines($repair['text']),
                        $block->attributeResolver()
                    );
                    $this->positionedPdfDisplayTokenRepairProofs[] = $repair['proof'];
                }
                $type = 'heading';
                $attrs['level'] = 2;
            }

            if ($type === $block->type
                && $attrs === $block->baseAttrs()) {
                continue;
            }
            $block = new AstNode(
                $type,
                $attrs,
                $block->children(),
                $block->attributeResolver()
            );
        }
        unset($block);

        return $blocks;
    }

    /**
     * @param array<string,mixed> $proof
     * @param array<int,true> $acceptedCandidatePages
     * @param list<string> $allowedRoles
     */
    private function positionedPdfTablePageRoleProofIsValid(
        array $proof,
        int $page,
        string $text,
        array $acceptedCandidatePages,
        array $allowedRoles
    ): bool {
        $proofDigest = is_string($proof['proofDigest'] ?? null)
            ? $proof['proofDigest']
            : '';
        $unsigned = $proof;
        unset($unsigned['proofDigest']);
        $encoded = json_encode(
            $unsigned,
            JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_PRESERVE_ZERO_FRACTION
        );
        $expectedDigest = hash(
            'sha256',
            is_string($encoded) ? $encoded : serialize($unsigned)
        );
        $key = $this->pdfComparableLineText($text);
        $role = is_string($proof['role'] ?? null) ? $proof['role'] : '';
        $supportPage = is_int($proof['supportPage'] ?? null)
            ? $proof['supportPage']
            : 0;
        if (($proof['version'] ?? null) !== 1
            || !is_string($proof['sourceSha256'] ?? null)
            || !hash_equals($this->sourceSha256, $proof['sourceSha256'])
            || !is_int($proof['page'] ?? null)
            || $proof['page'] !== $page
            || $key === ''
            || !is_string($proof['targetTextDigest'] ?? null)
            || !hash_equals(hash('sha256', $key), $proof['targetTextDigest'])
            || $proofDigest === ''
            || !hash_equals($expectedDigest, $proofDigest)
            || !in_array($role, $allowedRoles, true)
            || $supportPage < 1
            || !isset($acceptedCandidatePages[$page], $acceptedCandidatePages[$supportPage])) {
            return false;
        }
        if ($role === 'homologous-table-label') {
            return $supportPage < $page
                && is_int($proof['matchedRowCount'] ?? null)
                && $proof['matchedRowCount'] >= 3
                && is_int($proof['matchedCellCount'] ?? null)
                && $proof['matchedCellCount'] >= 6
                && is_numeric($proof['coverage'] ?? null)
                && (float) $proof['coverage'] >= 0.70
                && is_string($proof['tableBandDigest'] ?? null)
                && preg_match('/^[a-f0-9]{64}$/D', $proof['tableBandDigest']) === 1;
        }
        if ($role === 'display-heading') {
            return $supportPage === $page
                && is_numeric($proof['fontSize'] ?? null)
                && is_numeric($proof['medianFontSize'] ?? null)
                && (float) $proof['fontSize'] >= 18.0
                && (float) $proof['fontSize'] >= (float) $proof['medianFontSize'] * 2.0;
        }

        return $supportPage === $page
            && is_string($proof['tableBandDigest'] ?? null)
            && preg_match('/^[a-f0-9]{64}$/D', $proof['tableBandDigest']) === 1;
    }

    /**
     * @param array<int,list<AstNode>> $blocksByPage
     * @param array<int,true> $acceptedCandidatePages
     * @return list<array<string,mixed>>
     */
    private function positionedPdfAcceptedDisplayHeadingReferences(
        array $blocksByPage,
        array $acceptedCandidatePages
    ): array {
        $references = [];
        foreach ($blocksByPage as $page => $blocks) {
            $page = (int) $page;
            foreach ($blocks as $block) {
                $proof = $block->attr('sourcePdfTableDisplayHeadingProof');
                $text = (string) $block->attr('text', '');
                if (!is_array($proof)
                    || !$this->positionedPdfTablePageRoleProofIsValid(
                        $proof,
                        $page,
                        $text,
                        $acceptedCandidatePages,
                        ['display-heading']
                    )) {
                    continue;
                }
                $matched = preg_match_all(
                    '/\p{L}[\p{L}\p{M}]*/u',
                    $text,
                    $tokens,
                    PREG_OFFSET_CAPTURE
                );
                if (!is_int($matched) || $matched < 1) {
                    continue;
                }
                foreach ($tokens[0] as $token) {
                    $tokenText = (string) ($token[0] ?? '');
                    if ($this->length($tokenText) < 4) {
                        continue;
                    }
                    $references[] = [
                        'page' => $page,
                        'token' => $tokenText,
                        'tokenKey' => $this->pdfLowercaseToken($tokenText),
                        'fontSize' => (float) $proof['fontSize'],
                        'displayProofDigest' => (string) $proof['proofDigest'],
                    ];
                }
            }
        }

        return $references;
    }

    /**
     * Restore one missing leading title glyph only from another accepted
     * display heading in the same document. The damaged token must begin in
     * lower case, be the complete suffix of exactly one one-grapheme-longer
     * title token, and share the same display font size. This admits a local
     * extraction gap without applying a dictionary or fixture vocabulary.
     *
     * @param array<string,mixed> $displayProof
     * @param list<array<string,mixed>> $references
     * @return array{text:string,proof:array<string,mixed>,insertionOffset:int,insertedText:string}|null
     */
    private function positionedPdfDisplayHeadingLeadingTokenRepair(
        string $text,
        array $displayProof,
        array $references,
        int $page
    ): ?array {
        $matched = preg_match_all(
            '/\p{L}[\p{L}\p{M}]*/u',
            $text,
            $tokens,
            PREG_OFFSET_CAPTURE
        );
        if (!is_int($matched) || $matched < 1) {
            return null;
        }

        $repairs = [];
        foreach ($tokens[0] as $token) {
            $tokenText = (string) ($token[0] ?? '');
            $offset = (int) ($token[1] ?? -1);
            if ($offset < 0
                || $this->length($tokenText) < 4
                || preg_match('/^\p{Ll}/u', $tokenText) !== 1) {
                continue;
            }
            $tokenKey = $this->pdfLowercaseToken($tokenText);
            $candidateByKey = [];
            foreach ($references as $reference) {
                $referenceToken = (string) ($reference['token'] ?? '');
                $referenceKey = (string) ($reference['tokenKey'] ?? '');
                $referencePage = (int) ($reference['page'] ?? 0);
                $referenceFontSize = max(1.0, (float) ($reference['fontSize'] ?? 1.0));
                $fontSize = max(1.0, (float) ($displayProof['fontSize'] ?? 1.0));
                if ($referencePage < 1
                    || $referencePage === $page
                    || preg_match('/^\p{Lu}/u', $referenceToken) !== 1
                    || $this->length($referenceToken) !== $this->length($tokenText) + 1
                    || !str_ends_with($referenceKey, $tokenKey)
                    || abs($referenceFontSize - $fontSize)
                        > max(0.75, max($referenceFontSize, $fontSize) * 0.05)) {
                    continue;
                }
                $candidateByKey[$referenceKey] ??= $reference;
            }
            if (count($candidateByKey) !== 1) {
                continue;
            }
            $reference = array_values($candidateByKey)[0];
            $referenceToken = (string) $reference['token'];
            $referenceCharacters = preg_split(
                '//u',
                $referenceToken,
                -1,
                PREG_SPLIT_NO_EMPTY
            );
            if (!is_array($referenceCharacters) || count($referenceCharacters) < 2) {
                continue;
            }
            $insertedText = (string) $referenceCharacters[0];
            $repairs[] = [
                'offset' => $offset,
                'sourceToken' => $tokenText,
                'replacementToken' => $referenceToken,
                'insertedText' => $insertedText,
                'reference' => $reference,
            ];
        }
        if (count($repairs) !== 1) {
            return null;
        }

        $repair = $repairs[0];
        $repairedText = substr($text, 0, $repair['offset'])
            . $repair['replacementToken']
            . substr($text, $repair['offset'] + strlen($repair['sourceToken']));
        $proof = $this->signedPositionedPdfTablePageRoleProof([
            'role' => 'display-heading-leading-token-repair',
            'page' => $page,
            'supportPage' => (int) $repair['reference']['page'],
            'sourceText' => $text,
            'repairedText' => $repairedText,
            'sourceTextDigest' => hash('sha256', $text),
            'repairedTextDigest' => hash('sha256', $repairedText),
            'sourceTokenDigest' => hash('sha256', $repair['sourceToken']),
            'referenceTokenDigest' => hash('sha256', $repair['replacementToken']),
            'displayProofDigest' => (string) $displayProof['proofDigest'],
            'referenceDisplayProofDigest' => (string) $repair['reference']['displayProofDigest'],
            'insertionOffset' => (int) $repair['offset'],
            'insertedText' => $repair['insertedText'],
        ]);

        return [
            'text' => $repairedText,
            'proof' => $proof,
            'insertionOffset' => (int) $repair['offset'],
            'insertedText' => (string) $repair['insertedText'],
        ];
    }

    /**
     * A document-wide text-table fallback does not emit any page candidate,
     * even when one was independently validated during preselection. Restore
     * the conservative proof inputs and remove those un-emitted expectations.
     *
     * @param list<array<string,mixed>> $candidateProofSourceLayouts
     * @return list<array<string,mixed>>
     */
    private function sourceOrderProofLayoutsAfterPdfTextTableFallback(
        array $candidateProofSourceLayouts
    ): array {
        $this->sourceProofCandidateBlocksByPage = [];
        $this->independentColumnBlocksByPage = [];

        return $candidateProofSourceLayouts;
    }

    /**
     * Stamp each accepted candidate block with one immutable page-group
     * identity. The marker carries no text and is removed before public source
     * binding; it exists only so later transforms can prove that the final
     * bytes still occupy the candidate page which produced them.
     *
     * @param list<AstNode> $blocks
     * @return list<AstNode>
     */
    private function pdfBlocksWithOutputPageProof(int $page, array $blocks): array
    {
        if ($page < 1 || $blocks === []) {
            return $blocks;
        }
        $projection = '';
        foreach ($blocks as $block) {
            $leaves = [];
            $this->appendPdfSourceBindingLeafText($block, $leaves);
            $projection .= implode('', $leaves);
        }
        if ($projection === '') {
            return $blocks;
        }

        $blockCount = count($blocks);
        $digest = hash('sha256', $projection);
        $proved = [];
        foreach ($blocks as $blockIndex => $block) {
            $attrs = $block->baseAttrs();
            $attrs[self::PDF_OUTPUT_PAGE_PROOF_ATTR] = [
                'version' => 1,
                'sourceSha256' => $this->sourceSha256,
                'page' => $page,
                'blockIndex' => $blockIndex,
                'blockCount' => $blockCount,
                'pageProjectionDigest' => $digest,
            ];
            $proved[] = new AstNode(
                $block->type,
                $attrs,
                $block->children(),
                $block->attributeResolver()
            );
        }

        return $proved;
    }

    /**
     * Recover actual candidate-page byte spans from the final transformed AST.
     * Untagged blocks form opaque gaps, but every tagged page group is checked
     * against the compositor's original digest and exact block sequence. Thus
     * a proof can never borrow compensating bytes from an adjacent page.
     *
     * @param list<AstNode> $blocks
     * @param array<int,string> $composedPageProjections Actual page-local
     *        projections emitted by the conservative/candidate compositor.
     * @return array<int,array{start:int,end:int,projection:string,leafEnds:list<int>}>
     */
    private function pdfFinalOutputPageProofs(
        array $blocks,
        array $composedPageProjections = []
    ): array
    {
        $proofs = [];
        $active = null;
        $cursor = 0;
        foreach ($blocks as $block) {
            $leaves = [];
            $this->appendPdfSourceBindingLeafText($block, $leaves);
            $blockProjection = implode('', $leaves);
            $proof = $block->attr(self::PDF_OUTPUT_PAGE_PROOF_ATTR);
            if (!is_array($proof)) {
                if ($active !== null) {
                    return [];
                }
                $cursor += strlen($blockProjection);
                continue;
            }

            $page = is_int($proof['page'] ?? null) ? $proof['page'] : 0;
            $blockIndex = is_int($proof['blockIndex'] ?? null) ? $proof['blockIndex'] : -1;
            $blockCount = is_int($proof['blockCount'] ?? null) ? $proof['blockCount'] : 0;
            $digest = is_string($proof['pageProjectionDigest'] ?? null)
                ? $proof['pageProjectionDigest']
                : '';
            if (($proof['version'] ?? null) !== 1
                || !is_string($proof['sourceSha256'] ?? null)
                || !hash_equals($this->sourceSha256, $proof['sourceSha256'])
                || $page < 1
                || $blockIndex < 0
                || $blockCount < 1
                || $blockIndex >= $blockCount
                || $digest === ''
                || isset($proofs[$page])) {
                return [];
            }

            if ($active === null) {
                if ($blockIndex !== 0) {
                    return [];
                }
                $active = [
                    'page' => $page,
                    'blockCount' => $blockCount,
                    'nextBlockIndex' => 0,
                    'digest' => $digest,
                    'start' => $cursor,
                    'projection' => '',
                    'leafEnds' => [],
                ];
            }
            if ($active['page'] !== $page
                || $active['blockCount'] !== $blockCount
                || $active['nextBlockIndex'] !== $blockIndex
                || !hash_equals($active['digest'], $digest)) {
                return [];
            }

            $localCursor = strlen($active['projection']);
            foreach ($leaves as $leaf) {
                $localCursor += strlen($leaf);
                $active['leafEnds'][] = $localCursor;
            }
            $active['projection'] .= $blockProjection;
            $active['nextBlockIndex']++;
            $cursor += strlen($blockProjection);

            if ($active['nextBlockIndex'] !== $active['blockCount']) {
                continue;
            }
            if ($active['projection'] === ''
                || !hash_equals($active['digest'], hash('sha256', $active['projection']))) {
                return [];
            }
            $proofs[$page] = [
                'start' => $active['start'],
                'end' => $cursor,
                'projection' => $active['projection'],
                'leafEnds' => array_values(array_unique($active['leafEnds'])),
            ];
            $active = null;
        }

        if ($active !== null) {
            return [];
        }
        ksort($proofs, SORT_NUMERIC);

        if ($composedPageProjections === []) {
            return $proofs;
        }
        $composedProofs = $this->pdfFinalOutputPageProofsFromComposedProjections(
            $blocks,
            $composedPageProjections
        );
        if ($composedProofs === []) {
            return [];
        }
        // Candidate-page AST markers are an independent integrity envelope.
        // When the final document mixes candidate and conservative pages,
        // both proofs must name the exact same candidate bytes and offsets.
        foreach (array_keys($this->sourceProofCandidateBlocksByPage) as $candidatePage) {
            $candidatePage = (int) $candidatePage;
            if (!isset($proofs[$candidatePage], $composedProofs[$candidatePage])
                || $proofs[$candidatePage] !== $composedProofs[$candidatePage]) {
                return [];
            }
        }

        return $composedProofs;
    }

    /**
     * Sign the complete final significant stream without claiming that any
     * byte belongs to a particular physical page. Some semantic carriers join
     * text across a page boundary and therefore cannot produce a sound page
     * partition, while the complete final AST projection remains exact.
     *
     * @param list<AstNode> $blocks
     * @return array<string,mixed>|null
     */
    private function pdfFinalOutputRangeProof(array $blocks): ?array
    {
        if (preg_match('/\A[a-f0-9]{64}\z/D', $this->sourceSha256) !== 1) {
            return null;
        }
        $whole = $this->pdfWholeOutputPageProof($blocks);
        if ($whole === null || $whole['start'] !== 0) {
            return null;
        }
        $encodedLeafEnds = json_encode(
            $whole['leafEnds'],
            JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE
        );
        $identity = [
            'version' => 1,
            'method' => 'exact-final-output-range-projection',
            'sourceSha256' => $this->sourceSha256,
            'start' => 0,
            'end' => $whole['end'],
            'projectionDigest' => hash('sha256', $whole['projection']),
            'leafEndCount' => count($whole['leafEnds']),
            'leafEndsDigest' => hash(
                'sha256',
                is_string($encodedLeafEnds) ? $encodedLeafEnds : serialize($whole['leafEnds'])
            ),
        ];
        $encoded = json_encode(
            $identity,
            JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE
        );
        $identity['proofDigest'] = hash(
            'sha256',
            is_string($encoded) ? $encoded : serialize($identity)
        );

        return $identity;
    }

    /**
     * @param list<AstNode> $blocks
     * @param array<string,mixed>|null $proof
     * @return array{start:int,end:int,projection:string,leafEnds:list<int>,proofDigest:string}|null
     */
    private function pdfValidatedFinalOutputRangeProof(
        array $blocks,
        ?array $proof
    ): ?array {
        if ($proof === null) {
            return null;
        }
        $expected = $this->pdfFinalOutputRangeProof($blocks);
        if ($expected === null || $expected !== $proof) {
            return null;
        }
        $whole = $this->pdfWholeOutputPageProof($blocks);
        if ($whole === null
            || $whole['end'] !== ($proof['end'] ?? null)
            || !hash_equals(
                (string) ($proof['projectionDigest'] ?? ''),
                hash('sha256', $whole['projection'])
            )) {
            return null;
        }

        return $whole + ['proofDigest' => $proof['proofDigest']];
    }

    /**
     * Turn a complete compositor-owned page projection sequence into exact
     * final-output byte spans. The complete concatenation gate prevents any
     * page from borrowing compensating bytes from an adjacent page, including
     * when one final AST text leaf crosses the physical page boundary.
     *
     * @param list<AstNode> $blocks
     * @param array<int,string> $pageProjections
     * @return array<int,array{start:int,end:int,projection:string,leafEnds:list<int>}>
     */
    private function pdfFinalOutputPageProofsFromComposedProjections(
        array $blocks,
        array $pageProjections
    ): array {
        if ($pageProjections === []) {
            return [];
        }
        $normalized = [];
        $previousPage = 0;
        foreach ($pageProjections as $page => $projection) {
            $page = (int) $page;
            if ($page < 1
                || $page <= $previousPage
                || !is_string($projection)
                || $projection === ''
                || $this->pdfSourceOccurrenceComparableText($projection) !== $projection) {
                return [];
            }
            $normalized[$page] = $projection;
            $previousPage = $page;
        }

        $leaves = [];
        foreach ($blocks as $block) {
            $this->appendPdfSourceBindingLeafText($block, $leaves);
        }
        $globalLeafEnds = [];
        $leafCursor = 0;
        foreach ($leaves as $leaf) {
            $leafCursor += strlen($leaf);
            $globalLeafEnds[] = $leafCursor;
        }
        if ($leafCursor === 0) {
            return [];
        }

        $proofs = [];
        $cursor = 0;
        foreach ($normalized as $page => $pageProjection) {
            $start = $cursor;
            $cursor += strlen($pageProjection);
            if ($cursor > $leafCursor
                || $this->pdfLeafStreamProjection(
                    $leaves,
                    $start,
                    $cursor,
                    $pageProjection
                ) === null) {
                return [];
            }
            $leafEnds = [];
            foreach ($globalLeafEnds as $leafEnd) {
                if ($leafEnd <= $start) {
                    continue;
                }
                if ($leafEnd > $cursor) {
                    break;
                }
                $leafEnds[] = $leafEnd - $start;
            }
            $proofs[$page] = [
                'start' => $start,
                'end' => $cursor,
                'projection' => $pageProjection,
                'leafEnds' => $leafEnds,
            ];
        }
        if ($cursor !== $leafCursor) {
            return [];
        }

        return $proofs;
    }

    /**
     * Revalidate every supplied span against the current final significant
     * leaf stream. Gaps are opaque, unproved output regions; overlap, stale
     * bytes, or an out-of-range span invalidates the complete sidecar.
     *
     * @param list<AstNode> $blocks
     * @param array<int,array{start:int,end:int,projection?:string,leafEnds?:list<int>}> $proofs
     * @return array<int,array{start:int,end:int,projection:string,leafEnds:list<int>}>
     */
    private function pdfValidatedFinalOutputPageProofs(array $blocks, array $proofs): array
    {
        if ($proofs === []) {
            return [];
        }
        $leaves = [];
        foreach ($blocks as $block) {
            $this->appendPdfSourceBindingLeafText($block, $leaves);
        }
        $globalLeafEnds = [];
        $leafCursor = 0;
        foreach ($leaves as $leaf) {
            $leafCursor += strlen($leaf);
            $globalLeafEnds[] = $leafCursor;
        }
        if ($leafCursor === 0) {
            return [];
        }

        $ordered = [];
        foreach ($proofs as $page => $proof) {
            $page = (int) $page;
            $start = is_int($proof['start'] ?? null) ? $proof['start'] : -1;
            $end = is_int($proof['end'] ?? null) ? $proof['end'] : -1;
            if ($page < 1 || $start < 0 || $end <= $start || $end > $leafCursor) {
                return [];
            }
            $declaredProjection = is_string($proof['projection'] ?? null)
                ? $proof['projection']
                : null;
            $projection = $this->pdfLeafStreamProjection(
                $leaves,
                $start,
                $end,
                $declaredProjection
            );
            if ($projection === null || $projection === '') {
                return [];
            }
            $ordered[] = [
                'page' => $page,
                'start' => $start,
                'end' => $end,
                'projection' => $projection,
            ];
        }
        usort($ordered, static fn (array $left, array $right): int =>
            $left['start'] <=> $right['start'] ?: $left['page'] <=> $right['page']
        );

        $validated = [];
        $previousEnd = 0;
        foreach ($ordered as $proof) {
            if ($proof['start'] < $previousEnd || isset($validated[$proof['page']])) {
                return [];
            }
            $leafEnds = [];
            foreach ($globalLeafEnds as $leafEnd) {
                if ($leafEnd <= $proof['start']) {
                    continue;
                }
                if ($leafEnd > $proof['end']) {
                    break;
                }
                $leafEnds[] = $leafEnd - $proof['start'];
            }
            $validated[$proof['page']] = [
                'start' => $proof['start'],
                'end' => $proof['end'],
                'projection' => $proof['projection'],
                'leafEnds' => $leafEnds,
            ];
            $previousEnd = $proof['end'];
        }
        ksort($validated, SORT_NUMERIC);

        return $validated;
    }

    /**
     * Return one exact concatenated-leaf slice without first joining the whole
     * document. A supplied projection is compared byte-for-byte and reused.
     *
     * @param list<string> $leaves
     */
    private function pdfLeafStreamProjection(
        array $leaves,
        int $start,
        int $end,
        ?string $declaredProjection
    ): ?string {
        $length = $end - $start;
        if ($length < 1
            || ($declaredProjection !== null && strlen($declaredProjection) !== $length)) {
            return null;
        }
        $parts = [];
        $streamOffset = 0;
        $projectionOffset = 0;
        foreach ($leaves as $leaf) {
            $leafEnd = $streamOffset + strlen($leaf);
            if ($leafEnd <= $start) {
                $streamOffset = $leafEnd;
                continue;
            }
            if ($streamOffset >= $end) {
                break;
            }
            $leafStart = max(0, $start - $streamOffset);
            $take = min($leafEnd, $end) - ($streamOffset + $leafStart);
            if ($take > 0) {
                if ($declaredProjection === null) {
                    $parts[] = substr($leaf, $leafStart, $take);
                } else {
                    for ($offset = 0; $offset < $take; $offset++) {
                        if ($leaf[$leafStart + $offset]
                            !== $declaredProjection[$projectionOffset + $offset]) {
                            return null;
                        }
                    }
                }
                $projectionOffset += $take;
            }
            $streamOffset = $leafEnd;
        }
        if ($projectionOffset !== $length) {
            return null;
        }

        return $declaredProjection ?? implode('', $parts);
    }

    /** @param list<AstNode> $blocks @return array{start:int,end:int,projection:string,leafEnds:list<int>}|null */
    private function pdfWholeOutputPageProof(array $blocks): ?array
    {
        $leaves = [];
        foreach ($blocks as $block) {
            $this->appendPdfSourceBindingLeafText($block, $leaves);
        }
        $projection = implode('', $leaves);
        if ($projection === '') {
            return null;
        }
        $leafEnds = [];
        $cursor = 0;
        foreach ($leaves as $leaf) {
            $cursor += strlen($leaf);
            $leafEnds[] = $cursor;
        }

        return [
            'start' => 0,
            'end' => strlen($projection),
            'projection' => $projection,
            'leafEnds' => $leafEnds,
        ];
    }

    /**
     * @param array<int,array{start:int,end:int,projection:string,leafEnds:list<int>}> $proofs
     * @return array{start:int,end:int,projection:string,leafEnds:list<int>}|null
     */
    private function pdfNormalizedOutputPageProof(array $proofs, int $page): ?array
    {
        $proof = $proofs[$page] ?? null;

        return is_array($proof)
            && is_int($proof['start'] ?? null)
            && is_int($proof['end'] ?? null)
            && is_string($proof['projection'] ?? null)
            && is_array($proof['leafEnds'] ?? null)
                ? $proof
                : null;
    }

    /** @param list<AstNode> $blocks @return list<AstNode> */
    private function pdfBlocksWithoutOutputPageProofs(array $blocks): array
    {
        return array_map($this->pdfNodeWithoutOutputPageProof(...), $blocks);
    }

    private function pdfNodeWithoutOutputPageProof(AstNode $node): AstNode
    {
        $attrs = $node->baseAttrs();
        $changed = array_key_exists(self::PDF_OUTPUT_PAGE_PROOF_ATTR, $attrs);
        unset($attrs[self::PDF_OUTPUT_PAGE_PROOF_ATTR]);
        $children = [];
        foreach ($node->children() as $child) {
            $clean = $this->pdfNodeWithoutOutputPageProof($child);
            $changed = $changed || $clean !== $child;
            $children[] = $clean;
        }
        if (!$changed) {
            return $node;
        }

        return new AstNode(
            $node->type,
            $attrs,
            $children,
            $node->attributeResolver()
        );
    }

    /**
     * Link physical page tables only when an exact repeated header, column
     * geometry, adjacent pages, and clear page boundaries all agree. The
     * physical tables remain independently editable; the identity is compact
     * semantic provenance for import UIs and resumable reconciliation.
     *
     * @param array<int, list<AstNode>> $blocksByPage
     * @return array{blocksByPage:array<int,list<AstNode>>,continuations:list<array<string,mixed>>}
     */
    private function geometryTableBlocksWithContinuationIdentity(array $blocksByPage): array
    {
        if (count($blocksByPage) < 2) {
            return ['blocksByPage' => $blocksByPage, 'continuations' => []];
        }
        ksort($blocksByPage, SORT_NUMERIC);
        $tablesByPage = [];
        foreach ($blocksByPage as $page => $blocks) {
            foreach ($blocks as $blockIndex => $block) {
                if ($block->type !== 'table') {
                    continue;
                }
                $header = $this->pdfTableHeaderIdentity($block);
                if ($header === null || $this->pdfTableBodyRowCount($block) < 1) {
                    continue;
                }
                $tablesByPage[(int) $page][] = [
                    'page' => (int) $page,
                    'blockIndex' => (int) $blockIndex,
                    'node' => $block,
                    'header' => $header,
                ];
            }
        }
        if (count($tablesByPage) < 2) {
            return ['blocksByPage' => $blocksByPage, 'continuations' => []];
        }

        $links = [];
        $pages = array_keys($tablesByPage);
        sort($pages, SORT_NUMERIC);
        for ($index = 0, $count = count($pages) - 1; $index < $count; $index++) {
            $leftPage = $pages[$index];
            $rightPage = $pages[$index + 1];
            if ($rightPage !== $leftPage + 1) {
                continue;
            }
            $leftTables = $tablesByPage[$leftPage];
            $rightTables = $tablesByPage[$rightPage];
            $left = $leftTables[array_key_last($leftTables)];
            $right = $rightTables[0];
            if (!$this->pdfTableContinuationBoundaryIsClear(
                $blocksByPage[$leftPage],
                $left['blockIndex'],
                false
            ) || !$this->pdfTableContinuationBoundaryIsClear(
                $blocksByPage[$rightPage],
                $right['blockIndex'],
                true
            )) {
                continue;
            }
            if ($left['header'] !== $right['header']) {
                continue;
            }
            $links[] = [$left, $right];
        }
        if ($links === []) {
            return ['blocksByPage' => $blocksByPage, 'continuations' => []];
        }

        // Connected adjacent pairs form a continuation chain. Object IDs are
        // local implementation keys only; public IDs are deterministic from
        // source digest, first page, and the exact normalized header.
        $parent = [];
        $records = [];
        $find = static function (int $id) use (&$find, &$parent): int {
            $parent[$id] ??= $id;
            if ($parent[$id] !== $id) {
                $parent[$id] = $find($parent[$id]);
            }

            return $parent[$id];
        };
        $union = static function (int $left, int $right) use (&$parent, $find): void {
            $leftRoot = $find($left);
            $rightRoot = $find($right);
            if ($leftRoot !== $rightRoot) {
                $parent[$rightRoot] = $leftRoot;
            }
        };
        foreach ($links as [$left, $right]) {
            $leftId = spl_object_id($left['node']);
            $rightId = spl_object_id($right['node']);
            $records[$leftId] = $left;
            $records[$rightId] = $right;
            $union($leftId, $rightId);
        }
        $chains = [];
        foreach ($records as $id => $record) {
            $chains[$find($id)][] = $record;
        }

        $replacement = [];
        $continuations = [];
        foreach ($chains as $chain) {
            usort($chain, static fn (array $left, array $right): int =>
                ($left['page'] <=> $right['page'])
                    ?: ($left['blockIndex'] <=> $right['blockIndex'])
            );
            if (count($chain) < 2) {
                continue;
            }
            $first = $chain[0];
            $last = $chain[array_key_last($chain)];
            $identityPayload = $this->sourceSha256 . "\0"
                . $first['page'] . "\0"
                . implode("\x1f", $first['header']['cells']);
            $logicalId = 'pdf-table-' . substr(hash('sha256', $identityPayload), 0, 20);
            $partCount = count($chain);
            foreach ($chain as $partIndex => $record) {
                $position = $partIndex === 0
                    ? 'start'
                    : ($partIndex === $partCount - 1 ? 'end' : 'continue');
                $node = $record['node'];
                $replacement[spl_object_id($node)] = new AstNode(
                    'table',
                    array_replace($node->baseAttrs(), [
                        'pdfLogicalTableId' => $logicalId,
                        'pdfTableContinuation' => $position,
                        'pdfTableContinuationPage' => $record['page'],
                        'pdfTableRepeatedHeader' => $partIndex > 0,
                        'pdfTablePhysicalPart' => $partIndex + 1,
                        'pdfTablePhysicalParts' => $partCount,
                    ]),
                    $node->children()
                );
            }
            $continuations[] = [
                'id' => $logicalId,
                'pages' => array_values(array_map(
                    static fn (array $record): int => $record['page'],
                    $chain
                )),
                'physicalParts' => $partCount,
                'columnCount' => $first['header']['columnCount'],
                'repeatedHeader' => $first['header']['displayCells'],
                'firstPage' => $first['page'],
                'lastPage' => $last['page'],
            ];
        }
        if ($replacement === []) {
            return ['blocksByPage' => $blocksByPage, 'continuations' => []];
        }

        foreach ($blocksByPage as &$blocks) {
            foreach ($blocks as &$block) {
                $block = $replacement[spl_object_id($block)] ?? $block;
            }
            unset($block);
        }
        unset($blocks);

        return [
            'blocksByPage' => $blocksByPage,
            'continuations' => $continuations,
        ];
    }

    /**
     * Describe a repeated multi-section table as one logical family without
     * merging any of its independently editable physical tables.
     *
     * This pass deliberately runs after ordinary repeated-header continuation
     * identity. A continuation part is ineligible here, so the two meanings
     * cannot overwrite each other. Composite evidence is intentionally much
     * narrower than ordinary table detection: two adjacent pages in the same
     * deterministic eight-page semantic window must each contain at least
     * three eligible sibling tables, and their header sequences must have one
     * unique contiguous run of at least two distinct exact signatures. Short
     * labels may sit between sections; prose, lists, code, or another table
     * stop expansion.
     *
     * @param array<int, list<AstNode>> $blocksByPage
     * @return array{blocksByPage:array<int,list<AstNode>>,families:list<array<string,mixed>>}
     */
    private function geometryTableBlocksWithCompositeFamilyIdentity(array $blocksByPage): array
    {
        if (count($blocksByPage) < 2) {
            return ['blocksByPage' => $blocksByPage, 'families' => []];
        }
        ksort($blocksByPage, SORT_NUMERIC);

        $tablesByPage = [];
        foreach ($blocksByPage as $page => $blocks) {
            foreach ($blocks as $blockIndex => $block) {
                if ($block->type !== 'table'
                    || $block->attr('pdfLogicalTableId') !== null
                    || $block->attr('pdfLogicalTableFamilyId') !== null) {
                    continue;
                }
                $header = $this->pdfTableHeaderIdentity($block);
                if ($header === null || $this->pdfTableBodyRowCount($block) < 1) {
                    continue;
                }
                $signaturePayload = json_encode(
                    [$header['columnCount'], $header['cells']],
                    JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE
                );
                $signaturePayload = is_string($signaturePayload)
                    ? $signaturePayload
                    : serialize([$header['columnCount'], $header['cells']]);
                $tablesByPage[(int) $page][] = [
                    'page' => (int) $page,
                    'blockIndex' => (int) $blockIndex,
                    'node' => $block,
                    'header' => $header,
                    'signature' => hash('sha256', $signaturePayload),
                    'signatureKey' => $signaturePayload,
                ];
            }
        }
        if (count($tablesByPage) < 2) {
            return ['blocksByPage' => $blocksByPage, 'families' => []];
        }

        $links = [];
        $pages = array_keys($tablesByPage);
        sort($pages, SORT_NUMERIC);
        for ($pageIndex = 0, $pageCount = count($pages) - 1; $pageIndex < $pageCount; $pageIndex++) {
            $leftPage = $pages[$pageIndex];
            $rightPage = $pages[$pageIndex + 1];
            if ($rightPage !== $leftPage + 1
                || intdiv($leftPage - 1, PdfSemanticChunkReconciler::DEFAULT_SEMANTIC_WINDOW_PAGES)
                    !== intdiv($rightPage - 1, PdfSemanticChunkReconciler::DEFAULT_SEMANTIC_WINDOW_PAGES)) {
                continue;
            }
            $leftTables = $tablesByPage[$leftPage];
            $rightTables = $tablesByPage[$rightPage];
            // Keep the exact-run comparison strictly page-bounded. Dozens of
            // independent table siblings are more likely a catalogue/grid
            // than one composite business form and would make pair scoring
            // needlessly quadratic.
            if (count($leftTables) < 3 || count($rightTables) < 3
                || count($leftTables) > 32 || count($rightTables) > 32) {
                continue;
            }

            $commonRun = $this->pdfCompositeTableUniqueCommonHeaderRun($leftTables, $rightTables);
            if ($commonRun === null
                || ($commonRun['length'] / max(count($leftTables), count($rightTables))) < 0.5) {
                continue;
            }
            $leftRange = $this->pdfCompositeTableExpandedRange(
                $blocksByPage[$leftPage],
                $leftTables,
                $commonRun['leftStart'],
                $commonRun['leftStart'] + $commonRun['length'] - 1
            );
            $rightRange = $this->pdfCompositeTableExpandedRange(
                $blocksByPage[$rightPage],
                $rightTables,
                $commonRun['rightStart'],
                $commonRun['rightStart'] + $commonRun['length'] - 1
            );
            if ($leftRange === null || $rightRange === null) {
                continue;
            }

            $commonHeaders = [];
            $commonSignatures = [];
            for ($offset = 0; $offset < $commonRun['length']; $offset++) {
                $record = $leftTables[$commonRun['leftStart'] + $offset];
                $commonHeaders[] = $record['header']['displayCells'];
                $commonSignatures[] = $record['signature'];
            }
            $links[] = [
                'leftPage' => $leftPage,
                'rightPage' => $rightPage,
                'leftTables' => array_slice(
                    $leftTables,
                    $leftRange['start'],
                    $leftRange['end'] - $leftRange['start'] + 1
                ),
                'rightTables' => array_slice(
                    $rightTables,
                    $rightRange['start'],
                    $rightRange['end'] - $rightRange['start'] + 1
                ),
                'commonHeaders' => $commonHeaders,
                'commonSignatures' => $commonSignatures,
                'overlap' => $commonRun['length'] / max(count($leftTables), count($rightTables)),
            ];
        }
        if ($links === []) {
            return ['blocksByPage' => $blocksByPage, 'families' => []];
        }

        // A middle page may extend a family only when both adjacent matches
        // select the exact same physical siblings and exact common run.
        $acceptedLinks = [];
        $pageSelections = [];
        foreach ($links as $link) {
            $selectionKeys = [];
            foreach ([
                $link['leftPage'] => $link['leftTables'],
                $link['rightPage'] => $link['rightTables'],
            ] as $page => $records) {
                $selectionKeys[$page] = implode(',', array_map(
                    static fn (array $record): string => (string) spl_object_id($record['node']),
                    $records
                )) . "\0" . implode(',', $link['commonSignatures']);
            }
            $conflict = false;
            foreach ($selectionKeys as $page => $selectionKey) {
                if (isset($pageSelections[$page]) && $pageSelections[$page] !== $selectionKey) {
                    $conflict = true;
                    break;
                }
            }
            if ($conflict) {
                continue;
            }
            foreach ($selectionKeys as $page => $selectionKey) {
                $pageSelections[$page] = $selectionKey;
            }
            $acceptedLinks[] = $link;
        }
        if ($acceptedLinks === []) {
            return ['blocksByPage' => $blocksByPage, 'families' => []];
        }

        $parent = [];
        $find = static function (int $page) use (&$find, &$parent): int {
            $parent[$page] ??= $page;
            if ($parent[$page] !== $page) {
                $parent[$page] = $find($parent[$page]);
            }

            return $parent[$page];
        };
        $union = static function (int $left, int $right) use (&$parent, $find): void {
            $leftRoot = $find($left);
            $rightRoot = $find($right);
            if ($leftRoot !== $rightRoot) {
                $parent[$rightRoot] = $leftRoot;
            }
        };
        foreach ($acceptedLinks as $link) {
            $union($link['leftPage'], $link['rightPage']);
        }
        $linksByFamily = [];
        foreach ($acceptedLinks as $link) {
            $linksByFamily[$find($link['leftPage'])][] = $link;
        }

        $replacement = [];
        $families = [];
        foreach ($linksByFamily as $familyLinks) {
            $instancesByPage = [];
            $overlaps = [];
            foreach ($familyLinks as $link) {
                $instancesByPage[$link['leftPage']] = $link['leftTables'];
                $instancesByPage[$link['rightPage']] = $link['rightTables'];
                $overlaps[] = (float) $link['overlap'];
            }
            ksort($instancesByPage, SORT_NUMERIC);
            $familyPages = array_keys($instancesByPage);
            if (count($familyPages) < 2) {
                continue;
            }
            $firstLink = $familyLinks[0];
            $windowStart = (intdiv($familyPages[0] - 1, PdfSemanticChunkReconciler::DEFAULT_SEMANTIC_WINDOW_PAGES)
                * PdfSemanticChunkReconciler::DEFAULT_SEMANTIC_WINDOW_PAGES) + 1;
            $identityPayload = $this->sourceSha256 . "\0composite-table-family\0"
                . $windowStart . "\0" . implode(',', $familyPages) . "\0"
                . implode(',', $firstLink['commonSignatures']);
            $familyId = 'pdf-table-family-' . substr(hash('sha256', $identityPayload), 0, 20);
            $instances = [];
            $physicalParts = 0;
            foreach ($instancesByPage as $page => $records) {
                $instanceId = 'pdf-table-instance-' . substr(
                    hash('sha256', $familyId . "\0" . $page),
                    0,
                    20
                );
                $partCount = count($records);
                $physicalParts += $partCount;
                foreach ($records as $partIndex => $record) {
                    $node = $record['node'];
                    $dataAttributes = [
                        'data-pdf-logical-table-family-id' => $familyId,
                        'data-pdf-logical-table-instance-id' => $instanceId,
                        'data-pdf-logical-table-part' => (string) ($partIndex + 1),
                        'data-pdf-logical-table-parts' => (string) $partCount,
                    ];
                    $htmlAttributes = $node->attr('htmlAttributes', []);
                    $attributes = $node->attr('attributes', []);
                    $replacement[spl_object_id($node)] = new AstNode(
                        'table',
                        array_replace($node->baseAttrs(), [
                            'pdfLogicalTableFamilyId' => $familyId,
                            'pdfLogicalTableInstanceId' => $instanceId,
                            'pdfLogicalTableInstancePage' => (int) $page,
                            'pdfLogicalTablePart' => $partIndex + 1,
                            'pdfLogicalTableParts' => $partCount,
                            'htmlAttributes' => array_replace(
                                is_array($htmlAttributes) ? $htmlAttributes : [],
                                $dataAttributes
                            ),
                            'attributes' => array_replace(
                                is_array($attributes) ? $attributes : [],
                                $dataAttributes
                            ),
                        ]),
                        $node->children()
                    );
                }
                $instances[] = [
                    'id' => $instanceId,
                    'page' => (int) $page,
                    'physicalParts' => $partCount,
                ];
            }
            $families[] = [
                'id' => $familyId,
                'pages' => array_values(array_map(static fn (mixed $page): int => (int) $page, $familyPages)),
                'firstPage' => (int) $familyPages[0],
                'lastPage' => (int) $familyPages[array_key_last($familyPages)],
                'semanticWindowStart' => $windowStart,
                'semanticWindowEnd' => $windowStart + PdfSemanticChunkReconciler::DEFAULT_SEMANTIC_WINDOW_PAGES - 1,
                'instances' => $instances,
                'instanceCount' => count($instances),
                'physicalParts' => $physicalParts,
                'commonHeaders' => $firstLink['commonHeaders'],
                'commonHeaderSignatures' => $firstLink['commonSignatures'],
                'minimumOverlap' => $overlaps === [] ? 0.0 : min($overlaps),
            ];
        }
        if ($replacement === []) {
            return ['blocksByPage' => $blocksByPage, 'families' => []];
        }

        foreach ($blocksByPage as &$blocks) {
            foreach ($blocks as &$block) {
                $block = $replacement[spl_object_id($block)] ?? $block;
            }
            unset($block);
        }
        unset($blocks);
        usort($families, static fn (array $left, array $right): int =>
            ((int) ($left['firstPage'] ?? 0) <=> (int) ($right['firstPage'] ?? 0))
                ?: ((string) ($left['id'] ?? '') <=> (string) ($right['id'] ?? ''))
        );

        return ['blocksByPage' => $blocksByPage, 'families' => $families];
    }

    /**
     * @param list<array<string,mixed>> $leftTables
     * @param list<array<string,mixed>> $rightTables
     * @return array{leftStart:int,rightStart:int,length:int}|null
     */
    private function pdfCompositeTableUniqueCommonHeaderRun(array $leftTables, array $rightTables): ?array
    {
        $bestLength = 0;
        $best = [];
        foreach ($leftTables as $leftStart => $_leftTable) {
            foreach ($rightTables as $rightStart => $_rightTable) {
                $length = 0;
                $distinct = [];
                while (isset($leftTables[$leftStart + $length], $rightTables[$rightStart + $length])
                    && $leftTables[$leftStart + $length]['signatureKey']
                        === $rightTables[$rightStart + $length]['signatureKey']) {
                    $signature = (string) $leftTables[$leftStart + $length]['signature'];
                    $distinct[$signature] = true;
                    $length++;
                    if ($length < 2 || count($distinct) !== $length) {
                        continue;
                    }
                    if ($length > $bestLength) {
                        $bestLength = $length;
                        $best = [[
                            'leftStart' => (int) $leftStart,
                            'rightStart' => (int) $rightStart,
                            'length' => $length,
                        ]];
                    } elseif ($length === $bestLength) {
                        $best[] = [
                            'leftStart' => (int) $leftStart,
                            'rightStart' => (int) $rightStart,
                            'length' => $length,
                        ];
                    }
                }
            }
        }
        if ($bestLength < 2) {
            return null;
        }
        $unique = [];
        foreach ($best as $candidate) {
            $unique[$candidate['leftStart'] . ':' . $candidate['rightStart'] . ':' . $candidate['length']] = $candidate;
        }

        return count($unique) === 1 ? array_values($unique)[0] : null;
    }

    /**
     * Expand one evidenced common run only over neighboring table siblings
     * separated by at most four compact labels.
     *
     * @param list<AstNode> $blocks
     * @param list<array<string,mixed>> $tables
     * @return array{start:int,end:int}|null
     */
    private function pdfCompositeTableExpandedRange(array $blocks, array $tables, int $start, int $end): ?array
    {
        for ($index = $start; $index < $end; $index++) {
            if (!$this->pdfCompositeTableGapAllowsExpansion(
                $blocks,
                (int) $tables[$index]['blockIndex'],
                (int) $tables[$index + 1]['blockIndex']
            )) {
                return null;
            }
        }
        while ($start > 0 && $this->pdfCompositeTableGapAllowsExpansion(
            $blocks,
            (int) $tables[$start - 1]['blockIndex'],
            (int) $tables[$start]['blockIndex']
        )) {
            $start--;
        }
        while ($end + 1 < count($tables) && $this->pdfCompositeTableGapAllowsExpansion(
            $blocks,
            (int) $tables[$end]['blockIndex'],
            (int) $tables[$end + 1]['blockIndex']
        )) {
            $end++;
        }

        return ['start' => $start, 'end' => $end];
    }

    /** @param list<AstNode> $blocks */
    private function pdfCompositeTableGapAllowsExpansion(array $blocks, int $leftIndex, int $rightIndex): bool
    {
        $start = min($leftIndex, $rightIndex) + 1;
        $end = max($leftIndex, $rightIndex);
        $labels = 0;
        for ($index = $start; $index < $end; $index++) {
            $block = $blocks[$index] ?? null;
            if (!$block instanceof AstNode
                || !in_array($block->type, ['heading', 'paragraph', 'plain'], true)) {
                return false;
            }
            $text = trim((string) $block->attr('text', ''));
            if ($text === ''
                || mb_strlen($text, 'UTF-8') > 64
                || preg_match('/[.!?;:]\s*$/u', $text) === 1
                || preg_match_all('/[\p{L}\p{N}]+/u', $text, $matches) === false
                || count($matches[0]) > 8
                || ($block->type !== 'heading' && count($matches[0]) > 3)) {
                return false;
            }
            $labels++;
            if ($labels > 4) {
                return false;
            }
        }

        return true;
    }

    /** @param list<AstNode> $nodes */
    private function pdfLogicalTableCount(array $nodes): int
    {
        $logicalIds = [];
        $standalone = 0;
        $visit = function (array $children) use (&$visit, &$logicalIds, &$standalone): void {
            foreach ($children as $node) {
                if (!$node instanceof AstNode) {
                    continue;
                }
                if ($node->type === 'table') {
                    $familyId = $node->attr('pdfLogicalTableFamilyId');
                    $continuationId = $node->attr('pdfLogicalTableId');
                    if (is_string($familyId) && $familyId !== '') {
                        $logicalIds['family:' . $familyId] = true;
                    } elseif (is_string($continuationId) && $continuationId !== '') {
                        $logicalIds['continuation:' . $continuationId] = true;
                    } else {
                        $standalone++;
                    }
                }
                $visit($node->children());
            }
        };
        $visit($nodes);

        return count($logicalIds) + $standalone;
    }

    /**
     * @return array{cells:list<string>,displayCells:list<string>,columnCount:int}|null
     */
    private function pdfTableHeaderIdentity(AstNode $table): ?array
    {
        $headerRow = null;
        foreach ($table->children() as $section) {
            if ($section->type !== 'table_head') {
                continue;
            }
            foreach ($section->children() as $row) {
                if ($row->type === 'table_row') {
                    $headerRow = $row;
                    break 2;
                }
            }
        }
        if (!$headerRow instanceof AstNode) {
            return null;
        }

        $cells = [];
        $displayCells = [];
        $columnCount = 0;
        foreach ($headerRow->children() as $cell) {
            if ($cell->type !== 'table_cell') {
                continue;
            }
            $display = trim((string) $cell->attr('text', ''));
            $identity = $this->pdfComparableLineText($display);
            if ($identity === '') {
                return null;
            }
            $cells[] = $identity;
            $displayCells[] = $display;
            $columnCount += max(1, (int) $cell->attr('colspan', 1));
        }
        if (count($cells) < 2 || $columnCount < 2) {
            return null;
        }

        return [
            'cells' => $cells,
            'displayCells' => $displayCells,
            'columnCount' => $columnCount,
        ];
    }

    private function pdfTableBodyRowCount(AstNode $table): int
    {
        $rows = 0;
        foreach ($table->children() as $section) {
            if ($section->type !== 'table_body') {
                continue;
            }
            foreach ($section->children() as $row) {
                if ($row->type === 'table_row') {
                    $rows++;
                }
            }
        }

        return $rows;
    }

    /** @param list<AstNode> $blocks */
    private function pdfTableContinuationBoundaryIsClear(array $blocks, int $tableIndex, bool $before): bool
    {
        $candidates = $before
            ? array_slice($blocks, 0, $tableIndex)
            : array_slice($blocks, $tableIndex + 1);
        foreach ($candidates as $candidate) {
            if ($this->pdfComparableLineText((string) $candidate->attr('text', '')) !== '') {
                return false;
            }
        }

        return true;
    }

    /**
     * Normalize visible positioned runs while carrying a literal whitespace
     * operator to the next visible run from the same page content stream.
     *
     * A whitespace-only text-showing operator has no cell text after
     * normalization, so it must not become a zero-width prose/table cell.
     * It is nevertheless direct, per-occurrence evidence for the separator
     * immediately before the next painted text run. Keep that fact on the
     * following run instead of guessing from word spelling, case, or another
     * occurrence elsewhere in the document.
     *
     * @param list<array<string, mixed>> $runs
     * @return \Generator<int, array<string, mixed>>
     */
    private function positionedRunsWithLiteralWhitespaceProvenance(array $runs): \Generator
    {
        $pendingWhitespace = [];
        $lastVisibleRun = [];
        foreach ($runs as $index => $run) {
            $run['_order'] = array_key_exists('_order', $run) ? $run['_order'] : $index;
            $page = max(1, (int) ($run['page'] ?? 1));
            $whitespaceKey = $page . ':' . max(0, (int) ($run['stream'] ?? 0));
            $rawText = $this->normalizePdfTextEncoding((string) ($run['text'] ?? ''));
            if ($rawText !== '' && preg_match('/^\s+$/u', $rawText) === 1) {
                $pendingWhitespace[$whitespaceKey] = [
                    'hardBoundary' => (bool) (($pendingWhitespace[$whitespaceKey]['hardBoundary'] ?? false)
                        || preg_match('/[\t\r\n]/u', $rawText) === 1),
                    'run' => $run,
                    'previousVisibleRun' => $pendingWhitespace[$whitespaceKey]['previousVisibleRun']
                        ?? ($lastVisibleRun[$whitespaceKey] ?? null),
                ];
                continue;
            }

            $normalized = $this->positionedRun($run);
            if ($normalized === null) {
                continue;
            }
            if (isset($pendingWhitespace[$whitespaceKey])) {
                $pending = $pendingWhitespace[$whitespaceKey];
                unset($pendingWhitespace[$whitespaceKey]);
                // A whitespace-only Tj may be followed by another text line
                // in the same content stream. It proves a separator only at
                // the same visual baseline; otherwise it must not leak into
                // the first word of that next line.
                if ($this->pendingLiteralWhitespaceSharesVisualBaseline($pending, $normalized)) {
                    $normalized['startsWithWhitespace'] = true;
                    $normalized['startsAfterTextBoundary'] = (bool) (
                        ($normalized['startsAfterTextBoundary'] ?? false)
                        || $pending['hardBoundary']
                    );
                }
            }
            $lastVisibleRun[$whitespaceKey] = $normalized;
            yield $normalized;
        }
    }

    /**
     * A literal whitespace operator is local to the painted line that
     * contains it. Use its own bounds when available, then its immediately
     * preceding visible run as a safe fallback for producers that omit
     * whitespace glyph geometry.
     *
     * @param array<string, mixed> $pending
     * @param array<string, mixed> $followingRun
     */
    private function pendingLiteralWhitespaceSharesVisualBaseline(array $pending, array $followingRun): bool
    {
        $whitespaceRun = $pending['run'] ?? null;
        if (is_array($whitespaceRun)
            && $this->positionedRunsShareVisualBaseline($whitespaceRun, $followingRun)) {
            return true;
        }

        $previousVisibleRun = $pending['previousVisibleRun'] ?? null;

        return is_array($previousVisibleRun)
            && $this->positionedRunsShareVisualBaseline($previousVisibleRun, $followingRun);
    }

    /**
     * @param array<string, mixed> $left
     * @param array<string, mixed> $right
     */
    private function positionedRunsShareVisualBaseline(array $left, array $right): bool
    {
        $leftAxisX = $this->numericValue($left['axisX'] ?? null);
        $leftAxisY = $this->numericValue($left['axisY'] ?? null);
        $rightAxisX = $this->numericValue($right['axisX'] ?? null);
        $rightAxisY = $this->numericValue($right['axisY'] ?? null);
        if ($leftAxisX !== null && $leftAxisY !== null
            && $rightAxisX !== null && $rightAxisY !== null) {
            $leftAxisLength = hypot($leftAxisX, $leftAxisY);
            $rightAxisLength = hypot($rightAxisX, $rightAxisY);
            if ($leftAxisLength > 0.000001 && $rightAxisLength > 0.000001) {
                $leftAxisX /= $leftAxisLength;
                $leftAxisY /= $leftAxisLength;
                $rightAxisX /= $rightAxisLength;
                $rightAxisY /= $rightAxisLength;
                $axisAgreement = abs($leftAxisX * $rightAxisX + $leftAxisY * $rightAxisY);
                $leftCenterX = (($this->numericValue($left['textX1'] ?? $left['x1'] ?? null) ?? 0.0)
                    + ($this->numericValue($left['textX2'] ?? $left['x2'] ?? null) ?? 0.0)) / 2.0;
                $leftCenterY = (($this->numericValue($left['textY1'] ?? $left['y1'] ?? null) ?? 0.0)
                    + ($this->numericValue($left['textY2'] ?? $left['y2'] ?? null) ?? 0.0)) / 2.0;
                $rightCenterX = (($this->numericValue($right['textX1'] ?? $right['x1'] ?? null) ?? 0.0)
                    + ($this->numericValue($right['textX2'] ?? $right['x2'] ?? null) ?? 0.0)) / 2.0;
                $rightCenterY = (($this->numericValue($right['textY1'] ?? $right['y1'] ?? null) ?? 0.0)
                    + ($this->numericValue($right['textY2'] ?? $right['y2'] ?? null) ?? 0.0)) / 2.0;
                $leftFontSize = $this->numericValue($left['fontSize'] ?? null) ?? 1.0;
                $rightFontSize = $this->numericValue($right['fontSize'] ?? null) ?? 1.0;
                $tolerance = max(1.5, max($leftFontSize, $rightFontSize, 1.0) * 0.35);
                $normalX = -$leftAxisY;
                $normalY = $leftAxisX;
                if ($axisAgreement >= cos(deg2rad(12.0))) {
                    return abs(
                        ($leftCenterX - $rightCenterX) * $normalX
                        + ($leftCenterY - $rightCenterY) * $normalY
                    ) <= $tolerance;
                }
            }
        }

        $leftY1 = $this->numericValue($left['textY1'] ?? $left['y1'] ?? null);
        $leftY2 = $this->numericValue($left['textY2'] ?? $left['y2'] ?? null);
        $rightY1 = $this->numericValue($right['textY1'] ?? $right['y1'] ?? null);
        $rightY2 = $this->numericValue($right['textY2'] ?? $right['y2'] ?? null);
        if ($leftY1 === null || $leftY2 === null || $rightY1 === null || $rightY2 === null) {
            return false;
        }

        $leftFontSize = $this->numericValue($left['fontSize'] ?? null) ?? abs($leftY2 - $leftY1);
        $rightFontSize = $this->numericValue($right['fontSize'] ?? null) ?? abs($rightY2 - $rightY1);
        $tolerance = max(1.5, max($leftFontSize, $rightFontSize, 1.0) * 0.35);

        return abs((($leftY1 + $leftY2) / 2.0) - (($rightY1 + $rightY2) / 2.0)) <= $tolerance;
    }

    /**
     * @param array<string, mixed> $run
     * @return array{page: int, text: string, x1: float, y1: float, x2: float, y2: float, textX1: float, textY1: float, textX2: float, textY2: float, fontSize: float, rotation: float, axisX: float, axisY: float, startsWithWhitespace: bool, endsWithWhitespace: bool, wordBoundaryBefore: bool, hasWordBoundaryBefore: bool, wordBoundarySource: ?string}|null
     */
    private function positionedRun(array $run): ?array
    {
        $rawText = $this->normalizePdfTextEncoding((string) ($run['text'] ?? ''));
        $text = $this->positionedCellText($rawText);
        $x1 = $this->numericValue($run['x1'] ?? null);
        $y1 = $this->numericValue($run['y1'] ?? null);
        $x2 = $this->numericValue($run['x2'] ?? null);
        $y2 = $this->numericValue($run['y2'] ?? null);
        $textX1 = $this->numericValue($run['textX1'] ?? null) ?? $x1;
        $textY1 = $this->numericValue($run['textY1'] ?? null) ?? $y1;
        $textX2 = $this->numericValue($run['textX2'] ?? null) ?? $x2;
        $textY2 = $this->numericValue($run['textY2'] ?? null) ?? $y2;
        if ($text === '' || $x1 === null || $y1 === null || $x2 === null || $y2 === null) {
            return null;
        }

        $fontSize = $this->numericValue($run['fontSize'] ?? null);
        $axisX = $this->numericValue($run['axisX'] ?? null);
        $axisY = $this->numericValue($run['axisY'] ?? null);
        if ($axisX === null || $axisY === null || hypot($axisX, $axisY) <= 0.000001) {
            $deltaX = $textX2 - $textX1;
            $deltaY = $textY2 - $textY1;
            if (abs($deltaY) > max(0.5, abs($deltaX) * 1.5)) {
                $axisX = 0.0;
                $axisY = 1.0;
            } else {
                $axisX = 1.0;
                $axisY = 0.0;
            }
        }
        $axisLength = max(0.000001, hypot($axisX, $axisY));
        $axisX /= $axisLength;
        $axisY /= $axisLength;
        $axisX = abs($axisX) <= 0.000000001 ? 0.0 : $axisX;
        $axisY = abs($axisY) <= 0.000000001 ? 0.0 : $axisY;
        $rotation = $this->numericValue($run['rotation'] ?? null);
        $rotation = $this->normalizedPdfTextRotation(
            $rotation ?? rad2deg(atan2($axisY, $axisX))
        );
        $wordBoundarySource = is_string($run['wordBoundarySource'] ?? null)
            ? $run['wordBoundarySource']
            : null;
        $derivedWordBoundary = $this->pdfDerivedWordBoundaryBefore($wordBoundarySource);
        $hasExplicitWordBoundary = array_key_exists('wordBoundaryBefore', $run);
        $rtlVisualUnitText = preg_replace_callback(
            // A plain lam-alef at the start of a multi-character positioned
            // run is one run-local shaping unit. A visual-order definite
            // article appears at the opposite edge of its word/run, so this
            // bounded start condition does not freeze ordinary visual "لا"
            // sequences which must still reverse to logical "ال".
            '/(?:ل[أإآ]|(?<=ل)لا|^لا(?=\p{Arabic}))/u',
            static fn (array $match): string => self::PDF_RTL_SHAPING_CLUSTER_START
                . $match[0]
                . self::PDF_RTL_SHAPING_CLUSTER_END,
            $text
        ) ?? $text;

        $normalized = [
            'page' => max(1, (int) ($run['page'] ?? 1)),
            'stream' => max(1, (int) ($run['stream'] ?? 1)),
            'text' => $text,
            'rtlVisualUnitText' => $rtlVisualUnitText,
            'x1' => min($x1, $x2),
            'y1' => min($y1, $y2),
            'x2' => max($x1, $x2),
            'y2' => max($y1, $y2),
            'textX1' => min($textX1, $textX2),
            'textY1' => min($textY1, $textY2),
            'textX2' => max($textX1, $textX2),
            'textY2' => max($textY1, $textY2),
            'fontSize' => max(1.0, $fontSize ?? abs($y2 - $y1)),
            'nominalFontSize' => max(1.0, $fontSize ?? abs($y2 - $y1)),
            'rotation' => $rotation,
            'axisX' => $axisX,
            'axisY' => $axisY,
            'startsWithWhitespace' => preg_match('/^\s/u', $rawText) === 1,
            'endsWithWhitespace' => preg_match('/\s$/u', $rawText) === 1,
            'wordBoundaryBefore' => $hasExplicitWordBoundary
                ? ($run['wordBoundaryBefore'] ?? false) === true
                : ($derivedWordBoundary ?? false),
            'hasWordBoundaryBefore' => $hasExplicitWordBoundary || $derivedWordBoundary !== null,
            'wordBoundarySource' => $wordBoundarySource,
            'startsAfterTextBoundary' => false,
            'order' => max(0, (int) ($run['_order'] ?? 0)),
            'lastOrder' => max(0, (int) ($run['_order'] ?? 0)),
        ];
        if (is_string($run['fontResource'] ?? null)
            && $run['fontResource'] !== ''
            && is_string($run['baseFont'] ?? null)
            && $run['baseFont'] !== '') {
            $normalized['fontResource'] = $run['fontResource'];
            $normalized['baseFont'] = $run['baseFont'];
        }
        $exactSourceRanges = $this->pdfPositionedExactSourceRanges($run);
        if (count($exactSourceRanges) === 1) {
            $normalized['sourcePdfExactSourceIndex'] = $exactSourceRanges[0]['sourceIndex'];
            $normalized['sourcePdfExactSourceStart'] = $exactSourceRanges[0]['sourceStart'];
            $normalized['sourcePdfExactSourceEnd'] = $exactSourceRanges[0]['sourceEnd'];
        } elseif ($exactSourceRanges !== []) {
            $normalized['sourcePdfExactSourceRanges'] = $exactSourceRanges;
        }

        return $normalized;
    }

    private function normalizedPdfTextRotation(float $rotation): float
    {
        $rotation = fmod($rotation, 360.0);
        if ($rotation < 0.0) {
            $rotation += 360.0;
        }
        foreach ([0.0, 90.0, 180.0, 270.0, 360.0] as $orthogonal) {
            if (abs($rotation - $orthogonal) <= 0.000000001) {
                return $orthogonal === 360.0 ? 0.0 : $orthogonal;
            }
        }

        return $rotation;
    }

    /**
     * @param array<string, mixed> $rectangle
     * @return array{page: int, x1: float, y1: float, x2: float, y2: float, fillColor: string}|null
     */
    private function positionedFillRectangle(array $rectangle): ?array
    {
        $x1 = $this->numericValue($rectangle['x1'] ?? null);
        $y1 = $this->numericValue($rectangle['y1'] ?? null);
        $x2 = $this->numericValue($rectangle['x2'] ?? null);
        $y2 = $this->numericValue($rectangle['y2'] ?? null);
        $fillColor = $rectangle['fillColor'] ?? null;
        if ($x1 === null || $y1 === null || $x2 === null || $y2 === null || !is_string($fillColor) || preg_match('/^#[0-9a-f]{6}$/i', $fillColor) !== 1) {
            return null;
        }

        return [
            'page' => max(1, (int) ($rectangle['page'] ?? 1)),
            'x1' => min($x1, $x2),
            'y1' => min($y1, $y2),
            'x2' => max($x1, $x2),
            'y2' => max($y1, $y2),
            'fillColor' => strtolower($fillColor),
        ];
    }

    /**
     * @param list<array{page: int, text: string, x1: float, y1: float, x2: float, y2: float, textX1: float, textY1: float, textX2: float, textY2: float, fontSize: float}> $runs
     * @return list<list<string>>
     */
    private function positionedTableRowsForPage(array $runs, array $filledRectangles = []): array
    {
        if (count($runs) < 4) {
            return [];
        }

        $medianFontSize = $this->positionedRunsMedianFontSize($runs);
        $rowTolerance = max(3.0, $medianFontSize * 0.55);
        $columnTolerance = max(8.0, $medianFontSize * 1.10);
        $rows = $this->mergePositionedRowFragments($this->clusterPositionedRows($runs, $rowTolerance));
        if (count($rows) < 2) {
            return [];
        }

        $columns = $this->positionedTableColumns($rows, $columnTolerance);
        if (count($columns) < 2) {
            return [];
        }

        $physicalRows = $this->positionedRowsWithCells($rows, $columns);
        $logicalRows = $this->trimSparsePositionedRows($this->compactSparsePositionedColumns($this->mergePositionedContinuationRows($physicalRows)));
        $logicalRows = $this->withPositionedCellBackgrounds($logicalRows, $filledRectangles);

        if (!$this->isPositionedTableCandidate($logicalRows, count($logicalRows[0] ?? [])) || $this->positionedRenderedRowsLookLikeFragmentGrid($logicalRows)) {
            return [];
        }

        return $logicalRows;
    }

    /**
     * @param list<array{page: int, text: string, x1: float, y1: float, x2: float, y2: float, textX1: float, textY1: float, textX2: float, textY2: float, fontSize: float}> $runs
     * @return list<AstNode>
     */
    private function blocksFromPositionedPageTables(array $runs, array $filledRectangles = []): array
    {
        if (count($runs) < 4) {
            return [];
        }

        $groups = $this->positionedPdfTableOrientationGroups($runs);
        if ($groups === []) {
            return [];
        }

        $requiresOrientationSpace = false;
        foreach ($groups as $group) {
            if (($group['requiresOrientationSpace'] ?? false) === true) {
                $requiresOrientationSpace = true;
                break;
            }
        }
        if (!$requiresOrientationSpace) {
            return $this->blocksFromPositionedPageTablesInOneOrientation($runs, $filledRectangles);
        }

        // Trying a perpendicular group must not change diagnostics when it
        // turns out to be a side note, watermark, or other non-table region.
        // Keep the established all-runs path byte-for-byte in that case.
        $state = [
            'lowConfidence' => $this->lowConfidenceGeometryTableCandidates,
            'hypothesisCount' => $this->geometryLayoutHypothesisCount,
            'hypothesisTruncatedCount' => $this->geometryLayoutHypothesisTruncatedCount,
            'hypotheses' => $this->geometryLayoutHypotheses,
            'independentCount' => $this->independentColumnHypothesisCount,
            'independentBlocks' => $this->independentColumnBlocksByPage,
            'lastHypothesis' => $this->lastGeometryLayoutHypothesis,
        ];

        $descriptors = [];
        $hasOrientedTable = false;
        $orientedIntervals = [];
        foreach ($groups as $groupIndex => $group) {
            $groupRuns = $group['runs'];
            $basis = $group['basis'];
            $orientedRuns = ($group['requiresOrientationSpace'] ?? false) === true
                ? array_map(
                    fn (array $run): array => $this->positionedPdfRunInOrientationSpace($run, $basis),
                    $groupRuns
                )
                : $groupRuns;
            $orientedRectangles = ($group['requiresOrientationSpace'] ?? false) === true
                ? $this->positionedPdfRectanglesInOrientationSpace($filledRectangles, $basis)
                : $filledRectangles;
            $groupBlocks = ($group['requiresOrientationSpace'] ?? false) === true
                ? $this->blocksFromPositionedPageTablesInOneOrientation(
                    $orientedRuns,
                    $orientedRectangles
                )
                : [];
            $tableCount = $this->countNodesOfType($groupBlocks, 'table');
            if (($group['requiresOrientationSpace'] ?? false) === true && $tableCount > 0) {
                $hasOrientedTable = true;
                $orientedIntervals[] = [
                    'start' => $group['startOrder'],
                    'end' => $group['endOrder'],
                ];
            }
            $descriptors[] = [
                'groupIndex' => $groupIndex,
                'startOrder' => $group['startOrder'],
                'endOrder' => $group['endOrder'],
                'requiresOrientationSpace' => ($group['requiresOrientationSpace'] ?? false) === true,
                'runs' => $orientedRuns,
                'rectangles' => $orientedRectangles,
                'blocks' => $groupBlocks,
                'tableCount' => $tableCount,
            ];
        }

        if (!$hasOrientedTable) {
            $this->lowConfidenceGeometryTableCandidates = $state['lowConfidence'];
            $this->geometryLayoutHypothesisCount = $state['hypothesisCount'];
            $this->geometryLayoutHypothesisTruncatedCount = $state['hypothesisTruncatedCount'];
            $this->geometryLayoutHypotheses = $state['hypotheses'];
            $this->independentColumnHypothesisCount = $state['independentCount'];
            $this->independentColumnBlocksByPage = $state['independentBlocks'];
            $this->lastGeometryLayoutHypothesis = $state['lastHypothesis'];

            return $this->blocksFromPositionedPageTablesInOneOrientation($runs, $filledRectangles);
        }

        // A normal-orientation flow can surround an in-page rotated table in
        // source order. Split that flow at the rotated region's exact source
        // interval, so a paragraph painted after the table is not pulled in
        // front merely because both paragraphs share an orientation.
        $expanded = [];
        foreach ($descriptors as $descriptor) {
            if ($descriptor['requiresOrientationSpace']) {
                $expanded[] = $descriptor;
                continue;
            }
            $bands = $this->positionedPdfRunsSplitAroundOrderIntervals(
                $descriptor['runs'],
                $orientedIntervals
            );
            foreach ($bands as $band) {
                $bandBlocks = $this->blocksFromPositionedPageTablesInOneOrientation(
                    $band,
                    $descriptor['rectangles']
                );
                if ($this->countNodesOfType($bandBlocks, 'table') === 0) {
                    $bandBlocks = $this->blocksFromPositionedPageProse($band);
                }
                if ($bandBlocks === []) {
                    continue;
                }
                $orders = array_map(static fn (array $run): int => (int) ($run['order'] ?? 0), $band);
                $expanded[] = [
                    'startOrder' => min($orders),
                    'endOrder' => max($orders),
                    'blocks' => $bandBlocks,
                ];
            }
        }
        usort($expanded, static fn (array $left, array $right): int =>
            ($left['startOrder'] <=> $right['startOrder'])
                ?: ($left['endOrder'] <=> $right['endOrder'])
        );

        $blocks = [];
        foreach ($expanded as $descriptor) {
            $descriptorBlocks = $descriptor['blocks'];
            if ($descriptorBlocks === [] && isset($descriptor['runs'])) {
                $descriptorBlocks = $this->blocksFromPositionedPageProse($descriptor['runs']);
            }
            foreach ($descriptorBlocks as $block) {
                $blocks[] = $block;
            }
        }

        return $blocks;
    }

    /**
     * Partition only coherent orthogonal/opposite flows. Tiny rotated marks
     * remain with the dominant orientation, matching prose reconstruction and
     * preventing superscripts from becoming independent table regions.
     *
     * @param list<array<string, mixed>> $runs
     * @return list<array{runs:list<array<string,mixed>>,basis:array{uX:float,uY:float,nX:float,nY:float},requiresOrientationSpace:bool,startOrder:int,endOrder:int}>
     */
    private function positionedPdfTableOrientationGroups(array $runs): array
    {
        $byOrientation = [];
        foreach ($runs as $run) {
            $byOrientation[$this->positionedPdfOrientationBucket($run)][] = $run;
        }
        if ($byOrientation === []) {
            return [];
        }

        $scores = [];
        foreach ($byOrientation as $key => $groupRuns) {
            $scores[$key] = $this->positionedPdfOrientationGroupScore($groupRuns);
        }
        uksort($byOrientation, static function (string $left, string $right) use ($scores): int {
            return ($scores[$right] <=> $scores[$left]) ?: strcmp($left, $right);
        });
        $primaryKey = (string) array_key_first($byOrientation);
        $primaryRotation = $this->positionedPdfOrientationBucketRotation($primaryKey);
        $partitioned = [$primaryKey => $byOrientation[$primaryKey]];
        foreach ($byOrientation as $key => $groupRuns) {
            if ($key === $primaryKey) {
                continue;
            }
            $rotation = $this->positionedPdfOrientationBucketRotation((string) $key);
            $difference = abs($rotation - $primaryRotation);
            $difference = min($difference, 360.0 - $difference);
            $isPerpendicularOrOpposite = abs($difference - 90.0) <= 12.0
                || abs($difference - 180.0) <= 12.0;
            if ($isPerpendicularOrOpposite
                && count($groupRuns) >= 2
                && $this->positionedPdfOrientationGroupScore($groupRuns) >= 4) {
                $partitioned[$key] = $groupRuns;
                continue;
            }
            array_push($partitioned[$primaryKey], ...$groupRuns);
        }

        $groups = [];
        foreach ($partitioned as $key => $groupRuns) {
            $basis = $this->positionedPdfOrientationBasis($groupRuns, true);
            $orders = [];
            $endOrders = [];
            foreach ($groupRuns as $run) {
                $orders[] = max(0, (int) ($run['order'] ?? 0));
                $endOrders[] = max(0, (int) ($run['lastOrder'] ?? $run['order'] ?? 0));
            }
            $groups[] = [
                'runs' => $groupRuns,
                'basis' => $basis,
                // Page /Rotate metadata can change the reported text angle
                // while the extracted coordinate axis remains ordinary +X.
                // Project only when the actual progression vector needs it.
                'requiresOrientationSpace' => $basis['uX'] < 0.95 || abs($basis['uY']) > 0.30,
                'startOrder' => min($orders),
                'endOrder' => max($endOrders),
            ];
        }
        usort($groups, static fn (array $left, array $right): int =>
            ($left['startOrder'] <=> $right['startOrder'])
                ?: ($left['endOrder'] <=> $right['endOrder'])
        );

        return $groups;
    }

    /**
     * @param list<array<string,mixed>> $rectangles
     * @param array{uX:float,uY:float,nX:float,nY:float} $basis
     * @return list<array<string,mixed>>
     */
    private function positionedPdfRectanglesInOrientationSpace(array $rectangles, array $basis): array
    {
        $oriented = [];
        foreach ($rectangles as $rectangle) {
            $x1 = $this->numericValue($rectangle['x1'] ?? null);
            $y1 = $this->numericValue($rectangle['y1'] ?? null);
            $x2 = $this->numericValue($rectangle['x2'] ?? null);
            $y2 = $this->numericValue($rectangle['y2'] ?? null);
            if ($x1 === null || $y1 === null || $x2 === null || $y2 === null) {
                continue;
            }
            $bounds = $this->positionedPdfProjectedBounds($x1, $y1, $x2, $y2, $basis);
            $rectangle['x1'] = $bounds['x1'];
            $rectangle['y1'] = $bounds['y1'];
            $rectangle['x2'] = $bounds['x2'];
            $rectangle['y2'] = $bounds['y2'];
            $oriented[] = $rectangle;
        }

        return $oriented;
    }

    /**
     * @param list<array<string,mixed>> $runs
     * @param list<array{start:int,end:int}> $intervals
     * @return list<list<array<string,mixed>>>
     */
    private function positionedPdfRunsSplitAroundOrderIntervals(array $runs, array $intervals): array
    {
        if ($runs === [] || $intervals === []) {
            return $runs === [] ? [] : [$runs];
        }
        usort($intervals, static fn (array $left, array $right): int =>
            ($left['start'] <=> $right['start']) ?: ($left['end'] <=> $right['end'])
        );
        usort($runs, static fn (array $left, array $right): int =>
            ((int) ($left['order'] ?? 0) <=> (int) ($right['order'] ?? 0))
        );

        $bands = [];
        $currentBand = null;
        foreach ($runs as $run) {
            $order = (int) ($run['order'] ?? 0);
            $band = count($intervals) * 2;
            foreach ($intervals as $index => $interval) {
                if ($order < $interval['start']) {
                    $band = $index * 2;
                    break;
                }
                if ($order <= $interval['end']) {
                    $band = ($index * 2) + 1;
                    break;
                }
            }
            if ($currentBand !== $band) {
                $bands[] = [];
                $currentBand = $band;
            }
            $bands[array_key_last($bands)][] = $run;
        }

        return $bands;
    }

    /**
     * Keep geometry-table inference itself orientation-agnostic. The wrapper
     * above projects only a coherent perpendicular region into this ordinary
     * horizontal coordinate system.
     *
     * @param list<array{page: int, text: string, x1: float, y1: float, x2: float, y2: float, textX1: float, textY1: float, textX2: float, textY2: float, fontSize: float}> $runs
     * @return list<AstNode>
     */
    private function blocksFromPositionedPageTablesInOneOrientation(array $runs, array $filledRectangles = []): array
    {
        if (count($runs) < 4) {
            return [];
        }

        // Dense PDFs can contain tens of thousands of positioned runs on one
        // page. Building and then sorting a second full-size float array here
        // needlessly doubles the page peak. Font sizes normally have very few
        // distinct values, so compute the exact weighted median from a compact
        // frequency map instead.
        $medianFontSize = $this->positionedRunsMedianFontSize($runs);
        $rowTolerance = max(3.0, $medianFontSize * 0.55);
        $columnTolerance = max(8.0, $medianFontSize * 1.10);
        $rows = $this->mergePositionedRowFragments($this->clusterPositionedRows($runs, $rowTolerance));
        $lowConfidenceCandidatesBefore = $this->lowConfidenceGeometryTableCandidates;
        $independentColumnsBefore = $this->independentColumnHypothesisCount;
        $segments = $this->positionedTableSegments($rows, $columnTolerance, $filledRectangles, $medianFontSize);
        if ($segments === []) {
            if ($this->independentColumnHypothesisCount > $independentColumnsBefore) {
                $page = max(1, (int) ($runs[0]['page'] ?? 1));
                $pageBlocks = $this->blocksFromPositionedPageProse($runs);
                if ($pageBlocks !== []) {
                    $this->independentColumnBlocksByPage[$page] = $pageBlocks;
                }
            }
            if ($this->lowConfidenceGeometryTableCandidates > $lowConfidenceCandidatesBefore) {
                return [];
            }
            $pageRows = $this->positionedTableRowsForPage($runs, $filledRectangles);

            return $pageRows === [] ? [] : [$this->table($pageRows)];
        }

        $page = max(1, (int) ($runs[0]['page'] ?? 1));
        $layoutRoleProofs = $this->positionedPdfTableAdjacentLayoutRoleProofs(
            $rows,
            $segments,
            $medianFontSize,
            $page
        );
        $homologyProofs = $this->positionedPdfRejectedTableBandHomologyProofs(
            $rows,
            $segments,
            $medianFontSize,
            $page
        );
        foreach ($homologyProofs as $key => $proofs) {
            $layoutRoleProofs[$key] ??= [];
            array_push($layoutRoleProofs[$key], ...$proofs);
        }
        $displayHeadingProofs = $this->positionedPdfTablePageDisplayHeadingProofs(
            $rows,
            $segments,
            $layoutRoleProofs,
            $medianFontSize,
            $page
        );
        $this->rememberPositionedPdfTableBandHomologyTemplates(
            $rows,
            $segments,
            $medianFontSize,
            $page
        );

        $blocks = [];
        $pendingRows = [];
        $rowIndex = 0;
        $flushPendingRows = function () use (
            &$blocks,
            &$pendingRows,
            &$layoutRoleProofs,
            &$displayHeadingProofs
        ): void {
            if ($pendingRows === []) {
                return;
            }
            $pendingBlocks = $this->positionedPdfBlocksWithTablePageRoleProofs(
                $this->blocksFromPositionedClusteredProseRows($pendingRows),
                $layoutRoleProofs,
                $displayHeadingProofs
            );
            foreach ($pendingBlocks as $block) {
                $blocks[] = $block;
            }
            $pendingRows = [];
        };

        foreach ($segments as $segment) {
            while ($rowIndex < $segment['start']) {
                $pendingRows[] = $rows[$rowIndex];
                $rowIndex++;
            }

            $flushPendingRows();
            $blocks[] = $this->table($segment['rows']);
            $rowIndex = $segment['end'] + 1;
        }

        while ($rowIndex < count($rows)) {
            $pendingRows[] = $rows[$rowIndex];
            $rowIndex++;
        }
        $flushPendingRows();

        return $blocks;
    }

    /**
     * @param list<array{page: int, text: string, x1: float, y1: float, x2: float, y2: float, textX1: float, textY1: float, textX2: float, textY2: float, fontSize: float}> $runs
     * @return list<AstNode>
     */
    private function blocksFromPositionedPageProse(array $runs): array
    {
        $items = $this->positionedProseLineItemsForPage($runs);
        $lines = $this->positionedLineItemTexts($items);
        if ($lines === []) {
            return [];
        }
        if ($this->proseTextRepairEnabled()) {
            $lines = $this->repairProseTextLines(
                $lines,
                $this->looksLikeProseRepairCandidate($lines),
                $items
            );
        }

        return $this->blocksFromLines($lines, false);
    }

    /**
     * @param list<array{center: float, runs: list<array<string, mixed>>}> $rows
     * @return list<AstNode>
     */
    private function blocksFromPositionedClusteredProseRows(array $rows): array
    {
        $runs = [];
        foreach ($rows as $row) {
            foreach ($row['runs'] as $run) {
                $runs[] = $run;
            }
        }

        return $this->blocksFromPositionedPageProse($runs);
    }

    /**
     * A rejected prose band can still contain labels which are structurally
     * owned by an accepted neighboring table.  Admit only two local shapes:
     * a multi-column header aligned with the following table columns, or a
     * same-baseline label/value total inside the preceding table envelope.
     * The result is evidence attached to the candidate AST; it is not acted
     * on until the complete page candidate passes exact source binding.
     *
     * @param list<array{center:float,runs:list<array<string,mixed>>}> $rows
     * @param list<array{start:int,end:int,rows:list<list<string>>}> $segments
     * @return array<string,list<array<string,mixed>>>
     */
    private function positionedPdfTableAdjacentLayoutRoleProofs(
        array $rows,
        array $segments,
        float $medianFontSize,
        int $page
    ): array {
        $proofs = [];
        $occupied = [];
        foreach ($segments as $segment) {
            for ($index = (int) $segment['start']; $index <= (int) $segment['end']; $index++) {
                $occupied[$index] = true;
            }
        }

        foreach ($segments as $segment) {
            $start = (int) $segment['start'];
            $end = (int) $segment['end'];
            $segmentRows = array_slice($rows, $start, $end - $start + 1);
            if (count($segmentRows) < 2) {
                continue;
            }
            $segmentBounds = $this->positionedRowsBounds($segmentRows);
            $bandDigest = $this->positionedPdfTableBandDigest($segmentRows);
            $tolerance = max(8.0, $medianFontSize * 1.10);

            $headerIndex = $start - 1;
            $header = $rows[$headerIndex] ?? null;
            if (is_array($header)
                && !isset($occupied[$headerIndex])
                && count($header['runs'] ?? []) >= 3
                && count($header['runs']) <= 12
                && $this->positionedRowGap($header, $segmentRows[0])
                    <= max(72.0, $medianFontSize * 7.0)
                && $this->positionedRowMaxFontSize($header)
                    <= max(16.0, $medianFontSize * 1.55)) {
                $columns = $this->positionedTableColumns($segmentRows, $tolerance);
                $matchedColumns = [];
                $validRuns = [];
                $labelRuns = [];
                foreach ($header['runs'] as $run) {
                    $text = trim((string) ($run['text'] ?? ''));
                    if ($text === '' || $this->positionedCellIsNumericValue($text)) {
                        continue;
                    }
                    $labelRuns[] = $run;
                    $nearest = null;
                    $distance = INF;
                    foreach ($columns as $columnIndex => $column) {
                        $candidateDistance = abs((float) ($run['textX1'] ?? $run['x1'] ?? 0.0) - $column);
                        if ($candidateDistance < $distance) {
                            $nearest = $columnIndex;
                            $distance = $candidateDistance;
                        }
                    }
                    if ($nearest === null
                        || $distance > max(18.0, $medianFontSize * 2.0)
                        || isset($matchedColumns[$nearest])) {
                        continue;
                    }
                    $matchedColumns[$nearest] = true;
                    $validRuns[] = $run;
                }
                $headerBounds = $this->positionedProseRowBounds($header);
                $required = max(3, (int) ceil(count($header['runs']) * 0.70));
                if (count($validRuns) >= $required
                    && $headerBounds['x1'] >= $segmentBounds['x1'] - max(18.0, $medianFontSize * 2.0)
                    && $headerBounds['x2'] <= $segmentBounds['x2'] + max(18.0, $medianFontSize * 2.0)) {
                    $base = [
                        'role' => 'column-header-label',
                        'supportPage' => $page,
                        'tableBandDigest' => $bandDigest,
                        'rowIndex' => $headerIndex,
                        'matchedColumnCount' => count($validRuns),
                        'columnCount' => count($columns),
                    ];
                    foreach ($labelRuns as $run) {
                        $this->appendPositionedPdfTablePageRoleProof(
                            $proofs,
                            (string) $run['text'],
                            $base,
                            $page
                        );
                    }
                }
            }

            $summaryIndex = $end + 1;
            $summary = $rows[$summaryIndex] ?? null;
            if (!is_array($summary)
                || isset($occupied[$summaryIndex])
                || count($summary['runs'] ?? []) < 2
                || count($summary['runs']) > 6
                || $this->positionedRowGap($segmentRows[array_key_last($segmentRows)], $summary)
                    > max(72.0, $medianFontSize * 7.0)) {
                continue;
            }
            $numericRuns = [];
            $labelRuns = [];
            foreach ($summary['runs'] as $run) {
                $text = trim((string) ($run['text'] ?? ''));
                if ($text === '') {
                    continue;
                }
                if ($this->positionedCellIsNumericValue($text)) {
                    $numericRuns[] = $run;
                } else {
                    $labelRuns[] = $run;
                }
            }
            if ($numericRuns === [] || $labelRuns === []) {
                continue;
            }
            $matchedLabelRuns = array_values(array_filter(
                $labelRuns,
                static function (array $label) use ($numericRuns): bool {
                    $labelFont = max(1.0, (float) ($label['fontSize'] ?? 1.0));
                    foreach ($numericRuns as $numeric) {
                        $numericFont = max(1.0, (float) ($numeric['fontSize'] ?? 1.0));
                        if (abs($labelFont - $numericFont)
                            <= max(0.75, max($labelFont, $numericFont) * 0.12)) {
                            return true;
                        }
                    }

                    return false;
                }
            ));
            if ($matchedLabelRuns === []) {
                continue;
            }
            $summaryBounds = $this->positionedProseRowBounds($summary);
            $rightmostNumericX = max(array_map(
                static fn (array $run): float => (float) ($run['textX1'] ?? $run['x1'] ?? 0.0),
                $numericRuns
            ));
            $labelsLeadValues = array_reduce(
                $matchedLabelRuns,
                static fn (bool $valid, array $run): bool => $valid
                    && (float) ($run['textX1'] ?? $run['x1'] ?? 0.0) < $rightmostNumericX,
                true
            );
            if (!$labelsLeadValues
                || $this->positionedRowMaxFontSize($summary) > max(22.0, $medianFontSize * 2.25)
                || $summaryBounds['x1'] < $segmentBounds['x1'] - max(18.0, $medianFontSize * 2.0)
                || $summaryBounds['x2'] > $segmentBounds['x2'] + max(18.0, $medianFontSize * 2.0)) {
                continue;
            }
            $base = [
                'role' => 'summary-label',
                'supportPage' => $page,
                'tableBandDigest' => $bandDigest,
                'rowIndex' => $summaryIndex,
                'numericPeerCount' => count($numericRuns),
            ];
            foreach ($matchedLabelRuns as $run) {
                $this->appendPositionedPdfTablePageRoleProof(
                    $proofs,
                    (string) $run['text'],
                    $base,
                    $page
                );
            }
        }

        return $proofs;
    }

    /**
     * Match a rejected multi-row band to an accepted band on an earlier page.
     * Exact cell text, font metrics, one rigid translation, broad coverage,
     * and two horizontal lanes are all required. A merely similar two-row
     * phrase therefore cannot classify an unrelated heading as a form label.
     *
     * @param list<array{center:float,runs:list<array<string,mixed>>}> $rows
     * @param list<array{start:int,end:int,rows:list<list<string>>}> $segments
     * @return array<string,list<array<string,mixed>>>
     */
    private function positionedPdfRejectedTableBandHomologyProofs(
        array $rows,
        array $segments,
        float $medianFontSize,
        int $page
    ): array {
        if ($this->positionedPdfTableBandHomologyTemplates === []) {
            return [];
        }
        $occupied = [];
        foreach ($segments as $segment) {
            for ($index = (int) $segment['start']; $index <= (int) $segment['end']; $index++) {
                $occupied[$index] = true;
            }
        }

        $candidates = [];
        foreach ($this->positionedPdfTableBandHomologyTemplates as $template) {
            if ((int) ($template['page'] ?? 0) >= $page
                || !is_array($template['rows'] ?? null)
                || count($template['rows']) < 3) {
                continue;
            }
            $rowCount = count($template['rows']);
            for ($start = 0; $start + $rowCount <= count($rows); $start++) {
                for ($offset = 0; $offset < $rowCount; $offset++) {
                    if (isset($occupied[$start + $offset])) {
                        continue 2;
                    }
                }
                $match = $this->positionedPdfTableBandHomologyMatch(
                    $template,
                    array_slice($rows, $start, $rowCount),
                    $medianFontSize
                );
                if ($match === null) {
                    continue;
                }
                $match['start'] = $start;
                $match['template'] = $template;
                $candidates[] = $match;
            }
        }
        if ($candidates === []) {
            return [];
        }
        usort($candidates, static fn (array $left, array $right): int =>
            ($right['matchedCellCount'] <=> $left['matchedCellCount'])
                ?: ($right['coverage'] <=> $left['coverage'])
        );
        if (isset($candidates[1])
            && $candidates[1]['matchedCellCount'] === $candidates[0]['matchedCellCount']
            && abs((float) $candidates[1]['coverage'] - (float) $candidates[0]['coverage']) < 0.000001) {
            return [];
        }

        $best = $candidates[0];
        $template = $best['template'];
        $base = [
            'role' => 'homologous-table-label',
            'supportPage' => (int) $template['page'],
            'tableBandDigest' => (string) $template['digest'],
            'rowIndex' => (int) $best['start'],
            'matchedRowCount' => (int) $best['matchedRowCount'],
            'matchedCellCount' => (int) $best['matchedCellCount'],
            'templateCellCount' => (int) $template['cellCount'],
            'coverage' => round((float) $best['coverage'], 6),
            'translationX' => round((float) $best['translationX'], 4),
            'translationY' => round((float) $best['translationY'], 4),
        ];
        $proofs = [];
        foreach ($best['matches'] as $match) {
            $this->appendPositionedPdfTablePageRoleProof(
                $proofs,
                (string) $match['run']['text'],
                $base,
                $page
            );
        }
        $matchesByLane = [];
        foreach ($best['matches'] as $match) {
            $x1 = (float) $match['templateCell']['x1'];
            $lane = null;
            foreach ($matchesByLane as $laneIndex => $laneMatches) {
                $laneX1 = (float) $laneMatches[0]['templateCell']['x1'];
                if (abs($laneX1 - $x1) <= max(12.0, $medianFontSize * 1.5)) {
                    $lane = $laneIndex;
                    break;
                }
            }
            if ($lane === null) {
                $matchesByLane[] = [$match];
            } else {
                $matchesByLane[$lane][] = $match;
            }
        }
        foreach ($matchesByLane as $laneMatches) {
            if (count($laneMatches) < 2) {
                continue;
            }
            usort(
                $laneMatches,
                static fn (array $left, array $right): int => $left['rowOffset'] <=> $right['rowOffset']
            );
            $laneText = '';
            foreach ($laneMatches as $laneMatch) {
                $laneText = $this->appendCellText(
                    $laneText,
                    (string) $laneMatch['run']['text']
                );
            }
            $this->appendPositionedPdfTablePageRoleProof(
                $proofs,
                $laneText,
                $base + ['matchedLaneCellCount' => count($laneMatches)],
                $page
            );
        }

        return $proofs;
    }

    /** @return array<string,mixed>|null */
    private function positionedPdfTableBandHomologyMatch(
        array $template,
        array $candidateRows,
        float $medianFontSize
    ): ?array {
        $matches = [];
        $candidateCellCount = 0;
        foreach ($candidateRows as $rowOffset => $candidateRow) {
            $templateRow = $template['rows'][$rowOffset] ?? null;
            if (!is_array($templateRow)) {
                return null;
            }
            $candidateCellCount += count($candidateRow['runs'] ?? []);
            $used = [];
            foreach ($templateRow as $templateCell) {
                $bestIndex = null;
                $bestDistance = INF;
                foreach ($candidateRow['runs'] ?? [] as $candidateIndex => $run) {
                    if (isset($used[$candidateIndex])) {
                        continue;
                    }
                    $key = $this->pdfComparableLineText((string) ($run['text'] ?? ''));
                    if ($key === '' || !hash_equals((string) $templateCell['key'], $key)) {
                        continue;
                    }
                    $fontSize = max(1.0, (float) ($run['fontSize'] ?? 1.0));
                    $templateFontSize = max(1.0, (float) $templateCell['fontSize']);
                    if (abs($fontSize - $templateFontSize)
                        > max(0.75, max($fontSize, $templateFontSize) * 0.12)) {
                        continue;
                    }
                    $distance = abs(
                        (float) ($run['textX1'] ?? $run['x1'] ?? 0.0)
                        - (float) $templateCell['x1']
                    );
                    if ($distance < $bestDistance) {
                        $bestIndex = $candidateIndex;
                        $bestDistance = $distance;
                    }
                }
                if ($bestIndex === null) {
                    continue;
                }
                $used[$bestIndex] = true;
                $run = $candidateRow['runs'][$bestIndex];
                $matches[] = [
                    'run' => $run,
                    'templateCell' => $templateCell,
                    'rowOffset' => $rowOffset,
                    'dx' => (float) ($run['textX1'] ?? $run['x1'] ?? 0.0)
                        - (float) $templateCell['x1'],
                    'dy' => (float) ($candidateRow['center'] ?? 0.0)
                        - (float) $templateCell['rowCenter'],
                ];
            }
        }
        if (count($matches) < 6) {
            return null;
        }
        $translationX = $this->median(array_column($matches, 'dx'));
        $translationY = $this->median(array_column($matches, 'dy'));
        $xTolerance = max(3.0, $medianFontSize * 0.35);
        $yTolerance = max(3.0, $medianFontSize * 0.35);
        $matches = array_values(array_filter(
            $matches,
            static fn (array $match): bool => abs((float) $match['dx'] - $translationX) <= $xTolerance
                && abs((float) $match['dy'] - $translationY) <= $yTolerance
        ));
        $matchedRows = array_values(array_unique(array_column($matches, 'rowOffset'), SORT_NUMERIC));
        $templateCellCount = max(1, (int) ($template['cellCount'] ?? 0));
        $coverage = count($matches) / $templateCellCount;
        $candidateCoverage = count($matches) / max(1, $candidateCellCount);
        $lanePositions = array_map(
            static fn (array $match): float => (float) $match['templateCell']['x1'],
            $matches
        );
        if (count($matches) < 6
            || count($matchedRows) < 3
            || $coverage < 0.70
            || $candidateCoverage < 0.70
            || $lanePositions === []
            || max($lanePositions) - min($lanePositions) < max(60.0, $medianFontSize * 6.0)) {
            return null;
        }

        return [
            'matches' => $matches,
            'matchedRowCount' => count($matchedRows),
            'matchedCellCount' => count($matches),
            'coverage' => min($coverage, $candidateCoverage),
            'translationX' => $translationX,
            'translationY' => $translationY,
        ];
    }

    /**
     * @param list<array{center:float,runs:list<array<string,mixed>>}> $rows
     * @param list<array{start:int,end:int,rows:list<list<string>>}> $segments
     */
    private function rememberPositionedPdfTableBandHomologyTemplates(
        array $rows,
        array $segments,
        float $medianFontSize,
        int $page
    ): void {
        foreach ($segments as $segment) {
            $start = (int) $segment['start'];
            $end = (int) $segment['end'];
            $segmentRows = array_slice($rows, $start, $end - $start + 1);
            if (count($segmentRows) < 3 || count($segmentRows) > 12) {
                continue;
            }
            $templateRows = [];
            $cellCount = 0;
            $positions = [];
            foreach ($segmentRows as $row) {
                $templateRow = [];
                foreach ($row['runs'] ?? [] as $run) {
                    $key = $this->pdfComparableLineText((string) ($run['text'] ?? ''));
                    if ($key === '') {
                        continue;
                    }
                    $x1 = (float) ($run['textX1'] ?? $run['x1'] ?? 0.0);
                    $templateRow[] = [
                        'key' => $key,
                        'x1' => $x1,
                        'fontSize' => max(1.0, (float) ($run['fontSize'] ?? 1.0)),
                        'rowCenter' => (float) ($row['center'] ?? 0.0),
                    ];
                    $positions[] = $x1;
                    $cellCount++;
                }
                $templateRows[] = $templateRow;
            }
            if ($cellCount < 6
                || $positions === []
                || max($positions) - min($positions) < max(60.0, $medianFontSize * 6.0)) {
                continue;
            }
            $identity = ['page' => $page, 'rows' => $templateRows, 'cellCount' => $cellCount];
            $encoded = json_encode(
                $identity,
                JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_PRESERVE_ZERO_FRACTION
            );
            $identity['digest'] = hash('sha256', is_string($encoded) ? $encoded : serialize($identity));
            $this->positionedPdfTableBandHomologyTemplates[] = $identity;
            if (count($this->positionedPdfTableBandHomologyTemplates) > 64) {
                array_shift($this->positionedPdfTableBandHomologyTemplates);
            }
        }
    }

    /**
     * @param list<array{center:float,runs:list<array<string,mixed>>}> $rows
     * @param list<array{start:int,end:int,rows:list<list<string>>}> $segments
     * @param array<string,list<array<string,mixed>>> $layoutRoleProofs
     * @return array<string,list<array<string,mixed>>>
     */
    private function positionedPdfTablePageDisplayHeadingProofs(
        array $rows,
        array $segments,
        array $layoutRoleProofs,
        float $medianFontSize,
        int $page
    ): array {
        $occupied = [];
        foreach ($segments as $segment) {
            for ($index = (int) $segment['start']; $index <= (int) $segment['end']; $index++) {
                $occupied[$index] = true;
            }
        }
        $proofs = [];
        foreach ($rows as $index => $row) {
            if (isset($occupied[$index]) || count($row['runs'] ?? []) !== 1) {
                continue;
            }
            $text = trim($this->positionedRowText($row));
            $key = $this->pdfComparableLineText($text);
            if ($key === ''
                || isset($layoutRoleProofs[$key])
                || $this->length($text) > 88
                || count($this->pdfLineWordTokens($text)) > 8
                || preg_match('/^[^\p{L}\p{N}]*\p{Lu}/u', $text) !== 1
                || preg_match('/\p{L}/u', $text) !== 1
                || $this->lineHasPdfListBlockEvidence($text)
                || $this->lineLooksLikeUrlOnly($text)
                || $this->positionedRowMaxFontSize($row) < max(18.0, $medianFontSize * 2.0)) {
                continue;
            }
            $aboveGap = $index > 0
                ? $this->positionedRowGap($rows[$index - 1], $row)
                : INF;
            $belowGap = $index + 1 < count($rows)
                ? $this->positionedRowGap($row, $rows[$index + 1])
                : INF;
            if (max($aboveGap, $belowGap) < max(20.0, $medianFontSize * 2.0)) {
                continue;
            }
            $proof = $this->signedPositionedPdfTablePageRoleProof([
                'role' => 'display-heading',
                'page' => $page,
                'supportPage' => $page,
                'rowIndex' => $index,
                'fontSize' => round($this->positionedRowMaxFontSize($row), 4),
                'medianFontSize' => round($medianFontSize, 4),
                'targetTextDigest' => hash('sha256', $key),
            ]);
            $proofs[$key][] = $proof;
        }

        return $proofs;
    }

    /**
     * @param array<string,list<array<string,mixed>>> $proofs
     * @param array<string,mixed> $base
     */
    private function appendPositionedPdfTablePageRoleProof(
        array &$proofs,
        string $text,
        array $base,
        int $page
    ): void {
        $key = $this->pdfComparableLineText($text);
        if ($key === '') {
            return;
        }
        $proofs[$key][] = $this->signedPositionedPdfTablePageRoleProof($base + [
            'page' => $page,
            'targetTextDigest' => hash('sha256', $key),
        ]);
    }

    /** @param array<string,mixed> $proof @return array<string,mixed> */
    private function signedPositionedPdfTablePageRoleProof(array $proof): array
    {
        $proof = ['version' => 1, 'sourceSha256' => $this->sourceSha256] + $proof;
        $encoded = json_encode(
            $proof,
            JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_PRESERVE_ZERO_FRACTION
        );
        $proof['proofDigest'] = hash(
            'sha256',
            is_string($encoded) ? $encoded : serialize($proof)
        );

        return $proof;
    }

    /** @param list<array{center:float,runs:list<array<string,mixed>>}> $rows */
    private function positionedPdfTableBandDigest(array $rows): string
    {
        $identity = [];
        foreach ($rows as $row) {
            $cells = [];
            foreach ($row['runs'] ?? [] as $run) {
                $key = $this->pdfComparableLineText((string) ($run['text'] ?? ''));
                if ($key === '') {
                    continue;
                }
                $cells[] = [
                    'key' => $key,
                    'x1' => round((float) ($run['textX1'] ?? $run['x1'] ?? 0.0), 3),
                    'fontSize' => round(max(1.0, (float) ($run['fontSize'] ?? 1.0)), 3),
                ];
            }
            $identity[] = $cells;
        }
        $encoded = json_encode(
            $identity,
            JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_PRESERVE_ZERO_FRACTION
        );

        return hash('sha256', is_string($encoded) ? $encoded : serialize($identity));
    }

    /**
     * @param list<AstNode> $blocks
     * @param array<string,list<array<string,mixed>>> $layoutRoleProofs
     * @param array<string,list<array<string,mixed>>> $displayHeadingProofs
     * @return list<AstNode>
     */
    private function positionedPdfBlocksWithTablePageRoleProofs(
        array $blocks,
        array &$layoutRoleProofs,
        array &$displayHeadingProofs
    ): array {
        foreach ($blocks as &$block) {
            if (!in_array($block->type, ['heading', 'paragraph'], true)) {
                continue;
            }
            $key = $this->pdfComparableLineText((string) $block->attr('text', ''));
            if ($key === '') {
                continue;
            }
            $attrs = $block->baseAttrs();
            if (($layoutRoleProofs[$key] ?? []) !== []) {
                $attrs['sourcePdfTableLayoutRoleProof'] = array_shift($layoutRoleProofs[$key]);
            } elseif (($displayHeadingProofs[$key] ?? []) !== []) {
                $attrs['sourcePdfTableDisplayHeadingProof'] = array_shift($displayHeadingProofs[$key]);
            } else {
                continue;
            }
            $block = new AstNode(
                $block->type,
                $attrs,
                $block->children(),
                $block->attributeResolver()
            );
        }
        unset($block);

        return $blocks;
    }

    /**
     * @param list<array{center: float, runs: list<array{page: int, text: string, x1: float, y1: float, x2: float, y2: float, textX1: float, textY1: float, textX2: float, textY2: float, fontSize: float}>}> $rows
     * @return list<array{start: int, end: int, rows: list<list<string>>}>
     */
    private function positionedTableSegments(array $rows, float $columnTolerance, array $filledRectangles = [], ?float $medianFontSize = null): array
    {
        $segments = [];
        $rowCount = count($rows);
        $index = 0;
        $medianFontSize ??= 10.0;
        $regularRowGap = $this->positionedTypicalRowGap($rows);
        while ($index < $rowCount) {
            if (!$this->positionedRowLooksMultiColumn($rows[$index]) || $this->positionedRowLooksStandaloneHeading($rows[$index], $medianFontSize)) {
                $index++;
                continue;
            }

            $end = $index;
            while ($end + 1 < $rowCount && !$this->positionedRowsHaveTableSegmentBreak($rows[$end], $rows[$end + 1], $medianFontSize, $regularRowGap)) {
                $end++;
            }

            if ($end === $index) {
                $index++;
                continue;
            }

            $logicalRows = $this->positionedTableRowsFromClusteredRows(
                array_slice($rows, $index, $end - $index + 1),
                $columnTolerance,
                $filledRectangles
            );
            if ($logicalRows === []) {
                // A high-margin independent-flow decision explains this
                // entire bounded band. Do not rescore every suffix as another
                // "region"; the segment-break scan has already stopped before
                // a later heading/table transition.
                if (($this->lastGeometryLayoutHypothesis['selected'] ?? null) === 'independent-columns') {
                    $index = $end + 1;
                    continue;
                }
                $index++;
                continue;
            }

            $segments[] = [
                'start' => $index,
                'end' => $end,
                'rows' => $logicalRows,
            ];
            $index = $end + 1;
        }

        return $segments;
    }

    /**
     * @param list<array{center: float, runs: list<array{page: int, text: string, x1: float, y1: float, x2: float, y2: float, textX1: float, textY1: float, textX2: float, textY2: float, fontSize: float}>}> $rows
     * @return list<list<string>>
     */
    private function positionedTableRowsFromClusteredRows(array $rows, float $columnTolerance, array $filledRectangles = []): array
    {
        $columns = $this->positionedTableColumns($rows, $columnTolerance);
        if (count($columns) < 2) {
            return [];
        }

        $logicalRows = $this->compactSparsePositionedColumns($this->mergePositionedContinuationRows($this->positionedRowsWithCells($rows, $columns)));
        $logicalRows = $this->withPositionedCellBackgrounds($logicalRows, $filledRectangles);

        if (!$this->isPositionedTableCandidate($logicalRows, count($logicalRows[0] ?? [])) || $this->positionedRenderedRowsLookLikeFragmentGrid($logicalRows)) {
            return [];
        }

        return $logicalRows;
    }

    /**
     * @param array{center: float, runs: list<array{page: int, text: string, x1: float, y1: float, x2: float, y2: float, textX1: float, textY1: float, textX2: float, textY2: float, fontSize: float}>} $row
     */
    private function positionedRowLooksMultiColumn(array $row): bool
    {
        return count($row['runs']) >= 2;
    }

    /**
     * @param array{center: float, runs: list<array{page: int, text: string, x1: float, y1: float, x2: float, y2: float, textX1: float, textY1: float, textX2: float, textY2: float, fontSize: float}>} $current
     * @param array{center: float, runs: list<array{page: int, text: string, x1: float, y1: float, x2: float, y2: float, textX1: float, textY1: float, textX2: float, textY2: float, fontSize: float}>} $next
     */
    private function positionedRowsHaveTableSegmentBreak(
        array $current,
        array $next,
        float $medianFontSize,
        ?float $regularRowGap = null
    ): bool
    {
        $gap = $this->positionedRowGap($current, $next);
        $currentRuns = count($current['runs']);
        $nextRuns = count($next['runs']);
        $regularRowGap ??= max(1.0, $medianFontSize);

        if ($this->positionedRowLooksStandaloneHeading($current, $medianFontSize) || $this->positionedRowLooksStandaloneHeading($next, $medianFontSize)) {
            return true;
        }

        if ($gap >= max(24.0, $medianFontSize * 3.0)) {
            return true;
        }

        if ($currentRuns <= 1 && $nextRuns >= 3 && $gap >= max(12.0, $medianFontSize * 1.7)) {
            return true;
        }

        if ($currentRuns >= 3 && $nextRuns <= 1 && $gap >= max(20.0, $medianFontSize * 2.6)) {
            return true;
        }

        $structuralGap = max($medianFontSize * 2.6, $regularRowGap * 1.45);
        if ($currentRuns >= 3 && $nextRuns <= 1 && $gap >= $structuralGap) {
            return true;
        }

        if ($currentRuns <= 2 && $nextRuns === 1 && $gap >= max($medianFontSize * 2.6, $regularRowGap * 1.55)) {
            return true;
        }

        return false;
    }

    /**
     * @param list<array{center: float, runs: list<array{page: int, text: string, x1: float, y1: float, x2: float, y2: float, textX1: float, textY1: float, textX2: float, textY2: float, fontSize: float}>}> $rows
     */
    private function positionedTypicalRowGap(array $rows): float
    {
        $gaps = [];
        for ($index = 0, $count = count($rows) - 1; $index < $count; $index++) {
            $gap = $this->positionedRowGap($rows[$index], $rows[$index + 1]);
            if ($gap > 0.0 && $gap <= 72.0) {
                $gaps[] = $gap;
            }
        }

        return $gaps === [] ? 1.0 : max(1.0, $this->median($gaps));
    }

    /**
     * @param array{center: float, runs: list<array{page: int, text: string, x1: float, y1: float, x2: float, y2: float, textX1: float, textY1: float, textX2: float, textY2: float, fontSize: float}>} $upper
     * @param array{center: float, runs: list<array{page: int, text: string, x1: float, y1: float, x2: float, y2: float, textX1: float, textY1: float, textX2: float, textY2: float, fontSize: float}>} $lower
     */
    private function positionedRowGap(array $upper, array $lower): float
    {
        return max(0.0, $upper['center'] - $lower['center']);
    }

    /**
     * @param array{center: float, runs: list<array{page: int, text: string, x1: float, y1: float, x2: float, y2: float, textX1: float, textY1: float, textX2: float, textY2: float, fontSize: float}>} $row
     */
    private function positionedRowMaxFontSize(array $row): float
    {
        $fontSize = 0.0;
        foreach ($row['runs'] as $run) {
            $fontSize = max($fontSize, (float) $run['fontSize']);
        }

        return $fontSize;
    }

    /**
     * Form XObjects can apply a large coordinate transform to nominally tiny
     * text. Keep that original text-state size separate from the expanded
     * visual bounds when deciding whether operator-level spacing is reliable.
     *
     * @param array{runs: list<array<string, mixed>>} $row
     */
    private function positionedRowMaxNominalFontSize(array $row): float
    {
        $fontSize = 0.0;
        foreach ($row['runs'] as $run) {
            $fontSize = max($fontSize, (float) ($run['nominalFontSize'] ?? $run['fontSize'] ?? 0.0));
        }

        return max(1.0, $fontSize);
    }

    /**
     * @param array{center: float, runs: list<array{page: int, text: string, x1: float, y1: float, x2: float, y2: float, textX1: float, textY1: float, textX2: float, textY2: float, fontSize: float}>} $row
     */
    private function positionedRowLooksStandaloneHeading(array $row, float $medianFontSize): bool
    {
        if (count($row['runs']) !== 1) {
            return false;
        }

        $text = trim($this->positionedRowText($row));
        if ($text === '' || $this->length($text) > 80) {
            return false;
        }

        return $this->positionedRowMaxFontSize($row) >= max(9.0, $medianFontSize * 1.25);
    }

    /**
     * @param array{center: float, runs: list<array{page: int, text: string, x1: float, y1: float, x2: float, y2: float, textX1: float, textY1: float, textX2: float, textY2: float, fontSize: float}>} $row
     */
    private function positionedRowText(array $row): string
    {
        $text = '';
        foreach ($row['runs'] as $run) {
            $text = $this->appendCellText($text, $run['text']);
        }

        return $text;
    }

    /**
     * Preserve a font-style receipt independently of text decoding. A
     * subsetted BaseFont is useful evidence for presentation, but it must not
     * alter the extractor's encoding or metric decisions.
     *
     * @param array<string,mixed> $run
     * @return list<array<string,mixed>>
     */
    private function positionedRunInlineFontStyleSpans(array $run): array
    {
        $text = $this->positionedCellText((string) ($run['text'] ?? ''));
        if ($text === '') {
            return [];
        }

        if (is_array($run['sourcePdfInlineFontStyleSpans'] ?? null)) {
            return $this->normalizedPositionedInlineFontStyleSpans(
                $text,
                $run['sourcePdfInlineFontStyleSpans']
            );
        }

        $fontResource = $run['fontResource'] ?? null;
        $baseFont = $run['baseFont'] ?? null;
        if (!is_string($fontResource)
            || $fontResource === ''
            || !is_string($baseFont)
            || $baseFont === '') {
            return [];
        }

        $fontKey = strtolower($baseFont);
        $bold = str_contains($fontKey, 'bold');
        $italic = str_contains($fontKey, 'ital') || str_contains($fontKey, 'oblique');
        if (!$bold && !$italic) {
            return [];
        }

        return [[
            'start' => 0,
            'end' => strlen($text),
            'bold' => $bold,
            'italic' => $italic,
            'fontResources' => [$fontResource],
            'baseFonts' => [$baseFont],
        ]];
    }

    /**
     * @param list<array<string,mixed>> $runs
     * @return list<array<string,mixed>>
     */
    private function positionedInlineFontStyleSpansForJoinedText(
        string $joinedText,
        array $runs
    ): array {
        $joinedText = $this->positionedCellText($joinedText);
        if ($joinedText === '') {
            return [];
        }

        $spans = [];
        $cursor = 0;
        foreach ($runs as $run) {
            $part = $this->positionedCellText((string) ($run['text'] ?? ''));
            if ($part === '') {
                continue;
            }
            $partStart = strpos($joinedText, $part, $cursor);
            if ($partStart === false) {
                return [];
            }
            foreach ($this->positionedRunInlineFontStyleSpans($run) as $span) {
                $spans[] = array_replace($span, [
                    'start' => $partStart + (int) $span['start'],
                    'end' => $partStart + (int) $span['end'],
                ]);
            }
            $cursor = $partStart + strlen($part);
        }

        return $this->normalizedPositionedInlineFontStyleSpans($joinedText, $spans);
    }

    /**
     * @param array{runs:list<array<string,mixed>>} $row
     * @param list<array{sourceIndex:int,sourceStart:int,sourceEnd:int}> $exactSourceRanges
     * @return array<string,mixed>|null
     */
    private function positionedProseRowInlineFontStyleProof(
        array $row,
        string $line,
        array $exactSourceRanges
    ): ?array {
        $line = $this->positionedCellText($line);
        $spans = $this->positionedInlineFontStyleSpansForJoinedText(
            $line,
            $row['runs']
        );
        if ($spans === []) {
            return null;
        }

        // A producer commonly switches back to its regular font for terminal
        // punctuation. Bind that punctuation to the preceding styled word
        // only when it is immediately followed by whitespace or line end.
        foreach ($spans as &$span) {
            $end = (int) $span['end'];
            if ($end >= strlen($line)) {
                continue;
            }
            if (preg_match('/^[.!?,;:\x{2026}]+(?=\s|$)/u', substr($line, $end), $match) === 1) {
                $span['end'] = $end + strlen($match[0]);
            }
        }
        unset($span);
        $spans = $this->normalizedPositionedInlineFontStyleSpans($line, $spans);
        if ($spans === [] || $exactSourceRanges === []) {
            return null;
        }

        $proof = [
            'version' => 2,
            'method' => 'positioned-font-resource-base-font-exact-source',
            'sourceSha256' => $this->sourceSha256,
            'text' => $line,
            'textDigest' => hash('sha256', $line),
            'projectionDigest' => hash(
                'sha256',
                $this->pdfSourceOccurrenceComparableText($line)
            ),
            'exactSourceRanges' => $exactSourceRanges,
            'spans' => $spans,
        ];
        $proof['proofDigest'] = hash(
            'sha256',
            json_encode($proof, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE) ?: ''
        );

        return $proof;
    }

    /**
     * Resolve positioned range indexes to immutable source occurrence IDs
     * while the complete line inventory is still live. Only whole,
     * consecutive occurrences can cross the prose merge boundary into an AST
     * style identity; partial or reordered ranges remain unstyled.
     *
     * @param list<array<string,mixed>> $proofCandidates
     * @param list<array<string,mixed>> $lineItems
     * @return list<array<string,mixed>>
     */
    private function pdfInlineFontStyleProofCandidatesWithSourceIdentity(
        array $proofCandidates,
        array $lineItems
    ): array {
        $resolved = [];
        foreach ($proofCandidates as $proof) {
            $ranges = is_array($proof['exactSourceRanges'] ?? null)
                && array_is_list($proof['exactSourceRanges'])
                    ? $proof['exactSourceRanges']
                    : [];
            $text = is_string($proof['text'] ?? null) ? $proof['text'] : '';
            if (($proof['version'] ?? null) !== 2
                || ($proof['method'] ?? null)
                    !== 'positioned-font-resource-base-font-exact-source'
                || ($proof['sourceSha256'] ?? null) !== $this->sourceSha256
                || $ranges === []
                || $text === '') {
                continue;
            }
            $projection = '';
            $sourceOccurrenceIds = [];
            $globalSourceIndexes = [];
            $previousSourceIndex = null;
            $previousEnd = null;
            $valid = true;
            foreach ($ranges as $range) {
                $sourceIndex = $range['sourceIndex'] ?? null;
                $sourceStart = $range['sourceStart'] ?? null;
                $sourceEnd = $range['sourceEnd'] ?? null;
                $item = is_int($sourceIndex) ? ($lineItems[$sourceIndex] ?? null) : null;
                $sourceText = is_array($item)
                    ? $this->pdfSourceOccurrenceComparableText(
                        (string) ($item['text'] ?? '')
                    )
                    : '';
                if (!is_int($sourceIndex)
                    || !is_int($sourceStart)
                    || !is_int($sourceEnd)
                    || !is_array($item)
                    || $sourceText === ''
                    || $sourceStart < 0
                    || $sourceEnd <= $sourceStart
                    || $sourceEnd > strlen($sourceText)
                    || ($previousSourceIndex === $sourceIndex
                        && $sourceStart !== $previousEnd)
                    || ($previousSourceIndex !== null
                        && $previousSourceIndex !== $sourceIndex
                        && ($sourceIndex !== $previousSourceIndex + 1
                            || $sourceStart !== 0
                            || $previousEnd !== strlen($this->pdfSourceOccurrenceComparableText(
                                (string) ($lineItems[$previousSourceIndex]['text'] ?? '')
                            ))))) {
                    $valid = false;
                    break;
                }
                if ($previousSourceIndex !== $sourceIndex) {
                    $sourceId = is_string($item['id'] ?? null) ? $item['id'] : '';
                    $globalSourceIndex = is_int($item['sourcePdfGlobalSourceIndex'] ?? null)
                        ? $item['sourcePdfGlobalSourceIndex']
                        : $sourceIndex;
                    if ($sourceId === ''
                        || ($globalSourceIndexes !== []
                            && $globalSourceIndex !== $globalSourceIndexes[array_key_last(
                                $globalSourceIndexes
                            )] + 1)) {
                        $valid = false;
                        break;
                    }
                    $sourceOccurrenceIds[] = $sourceId;
                    $globalSourceIndexes[] = $globalSourceIndex;
                }
                $projection .= substr($sourceText, $sourceStart, $sourceEnd - $sourceStart);
                $previousSourceIndex = $sourceIndex;
                $previousEnd = $sourceEnd;
            }
            if (!$valid
                || $previousSourceIndex === null
                || $previousEnd !== strlen($this->pdfSourceOccurrenceComparableText(
                    (string) ($lineItems[$previousSourceIndex]['text'] ?? '')
                ))
                || !hash_equals(
                    $projection,
                    $this->pdfSourceOccurrenceComparableText($text)
                )) {
                continue;
            }
            $proof['sourceOccurrenceIds'] = $sourceOccurrenceIds;
            $proof['globalSourceIndexes'] = $globalSourceIndexes;
            $proof['projectionDigest'] = hash('sha256', $projection);
            unset($proof['proofDigest']);
            $proof['proofDigest'] = hash('sha256', json_encode(
                $proof,
                JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE
            ) ?: '');
            $resolved[] = $proof;
        }

        return $resolved;
    }

    /**
     * @param list<array<string,mixed>> $layouts
     * @param list<array<string,mixed>> $lineItems
     * @return list<array<string,mixed>>
     */
    private function pdfSourceLayoutsWithResolvedInlineFontStyleProofs(
        array $layouts,
        array $lineItems
    ): array {
        foreach ($layouts as &$layout) {
            $candidate = is_array($layout['sourcePdfInlineFontStyleProof'] ?? null)
                ? $layout['sourcePdfInlineFontStyleProof']
                : null;
            if ($candidate === null) {
                continue;
            }
            $resolved = $this->pdfInlineFontStyleProofCandidatesWithSourceIdentity(
                [$candidate],
                $lineItems
            );
            if (count($resolved) === 1) {
                $layout['sourcePdfInlineFontStyleProof'] = $resolved[0];
            } else {
                unset($layout['sourcePdfInlineFontStyleProof']);
            }
        }
        unset($layout);

        return $layouts;
    }

    /**
     * @param list<array<string,mixed>> $spans
     * @return list<array<string,mixed>>
     */
    private function normalizedPositionedInlineFontStyleSpans(
        string $text,
        array $spans
    ): array {
        $length = strlen($text);
        $normalized = [];
        foreach ($spans as $span) {
            $start = $span['start'] ?? null;
            $end = $span['end'] ?? null;
            $bold = ($span['bold'] ?? false) === true;
            $italic = ($span['italic'] ?? false) === true;
            if (!is_int($start)
                || !is_int($end)
                || $start < 0
                || $end <= $start
                || $end > $length
                || (!$bold && !$italic)) {
                return [];
            }
            $resources = array_values(array_unique(array_filter(
                is_array($span['fontResources'] ?? null) ? $span['fontResources'] : [],
                static fn (mixed $value): bool => is_string($value) && $value !== ''
            )));
            $baseFonts = array_values(array_unique(array_filter(
                is_array($span['baseFonts'] ?? null) ? $span['baseFonts'] : [],
                static fn (mixed $value): bool => is_string($value) && $value !== ''
            )));
            if ($resources === [] || $baseFonts === []) {
                return [];
            }
            $normalized[] = [
                'start' => $start,
                'end' => $end,
                'bold' => $bold,
                'italic' => $italic,
                'fontResources' => $resources,
                'baseFonts' => $baseFonts,
            ];
        }
        usort(
            $normalized,
            static fn (array $left, array $right): int => ($left['start'] <=> $right['start'])
                ?: ($left['end'] <=> $right['end'])
        );

        $merged = [];
        foreach ($normalized as $span) {
            $lastIndex = array_key_last($merged);
            if ($lastIndex === null) {
                $merged[] = $span;
                continue;
            }
            $last = $merged[$lastIndex];
            if ($span['start'] < $last['end']) {
                return [];
            }
            $between = substr($text, $last['end'], $span['start'] - $last['end']);
            if ($span['bold'] === $last['bold']
                && $span['italic'] === $last['italic']
                && preg_match('/^\s*$/u', $between) === 1) {
                $merged[$lastIndex]['end'] = $span['end'];
                $merged[$lastIndex]['fontResources'] = array_values(array_unique(array_merge(
                    $last['fontResources'],
                    $span['fontResources']
                )));
                $merged[$lastIndex]['baseFonts'] = array_values(array_unique(array_merge(
                    $last['baseFonts'],
                    $span['baseFonts']
                )));
                continue;
            }
            $merged[] = $span;
        }

        return $merged;
    }

    /**
     * @param list<array{page: int, text: string, x1: float, y1: float, x2: float, y2: float, textX1: float, textY1: float, textX2: float, textY2: float, fontSize: float}> $runs
     * @return list<array{center: float, runs: list<array{page: int, text: string, x1: float, y1: float, x2: float, y2: float, textX1: float, textY1: float, textX2: float, textY2: float, fontSize: float}>}>
     */
    private function clusterPositionedRows(array $runs, float $tolerance): array
    {
        usort($runs, static function (array $left, array $right): int {
            $leftCenter = self::positionedRunRowCenter($left);
            $rightCenter = self::positionedRunRowCenter($right);

            return ($rightCenter <=> $leftCenter) ?: ($left['x1'] <=> $right['x1']);
        });

        $rows = [];
        foreach ($runs as $run) {
            $center = self::positionedRunRowCenter($run);
            $matchedIndex = null;
            foreach ($rows as $index => $row) {
                $minCenter = min((float) ($row['minCenter'] ?? $row['center']), $center);
                $maxCenter = max((float) ($row['maxCenter'] ?? $row['center']), $center);
                if (abs($center - $row['center']) <= $tolerance
                    && ($maxCenter - $minCenter) <= $tolerance
                    && !$this->positionedRunStartsDistinctStyledBaseline($run, $row)) {
                    $matchedIndex = $index;
                    break;
                }
            }

            if ($matchedIndex === null) {
                $rows[] = [
                    'center' => $center,
                    'minCenter' => $center,
                    'maxCenter' => $center,
                    'runs' => [$run],
                ];
                continue;
            }

            $count = count($rows[$matchedIndex]['runs']);
            $rows[$matchedIndex]['center'] = (($rows[$matchedIndex]['center'] * $count) + $center) / ($count + 1);
            $rows[$matchedIndex]['minCenter'] = min((float) ($rows[$matchedIndex]['minCenter'] ?? $center), $center);
            $rows[$matchedIndex]['maxCenter'] = max((float) ($rows[$matchedIndex]['maxCenter'] ?? $center), $center);
            $rows[$matchedIndex]['runs'][] = $run;
        }

        usort($rows, static fn (array $left, array $right): int => $right['center'] <=> $left['center']);
        foreach ($rows as &$row) {
            $row['runs'] = $this->removeOverprintedPositionedRuns($row['runs']);
            usort($row['runs'], static fn (array $left, array $right): int => $left['x1'] <=> $right['x1']);
            $row['visualRtlOrder'] = $this->positionedRunsUseVisualRtlOrder($row['runs']);
            $row['visualRtlProtectedClusters'] = $this->positionedRtlShapingClusters($row['runs']);
            unset($row['minCenter'], $row['maxCenter']);
        }
        unset($row);

        return $rows;
    }

    /**
     * Overlapping display text can put a large title and a smaller tagline
     * inside one global row tolerance even though each begins a distinct PDF
     * text line. Keep that local baseline boundary only when the size contrast
     * and baseline displacement agree; ordinary same-baseline font changes
     * and superscript continuations remain eligible for composition.
     *
     * @param array<string,mixed> $run
     * @param array{center:float,runs:list<array<string,mixed>>} $row
     */
    private function positionedRunStartsDistinctStyledBaseline(array $run, array $row): bool
    {
        if (($run['wordBoundarySource'] ?? null) !== 'line-break') {
            return false;
        }
        $rowStartsAtLineBreak = false;
        $rowFontSize = 1.0;
        foreach ($row['runs'] as $rowRun) {
            $rowStartsAtLineBreak = $rowStartsAtLineBreak
                || ($rowRun['wordBoundarySource'] ?? null) === 'line-break';
            $rowFontSize = max($rowFontSize, (float) ($rowRun['fontSize'] ?? 1.0));
        }
        if (!$rowStartsAtLineBreak) {
            return false;
        }

        $runFontSize = max(1.0, (float) ($run['fontSize'] ?? 1.0));
        $smallerFontSize = min($runFontSize, $rowFontSize);
        $largerFontSize = max($runFontSize, $rowFontSize);
        $baselineDistance = abs(self::positionedRunRowCenter($run) - (float) $row['center']);
        if ($this->positionedRowIsExactFollowingScriptContinuation(
            $run,
            $row,
            $runFontSize,
            $rowFontSize
        )) {
            return false;
        }

        return $largerFontSize / $smallerFontSize >= 1.8
            && $baselineDistance >= max(2.0, $smallerFontSize * 0.25);
    }

    /**
     * A raised numerator can be encountered before the ordinary run which
     * precedes it in source order. Keep that exact compact script on the body
     * row; a later free-standing tagline has no such occurrence-local proof.
     *
     * @param array<string,mixed> $run
     * @param array{center:float,runs:list<array<string,mixed>>} $row
     */
    private function positionedRowIsExactFollowingScriptContinuation(
        array $run,
        array $row,
        float $runFontSize,
        float $rowFontSize
    ): bool {
        if ($runFontSize / max(1.0, $rowFontSize) < 1.8
            || (float) $row['center'] <= self::positionedRunRowCenter($run)
            || preg_match_all('/[\p{L}\p{M}]+/u', (string) ($run['text'] ?? '')) < 2) {
            return false;
        }
        $runRanges = $this->pdfPositionedExactSourceRanges($run);
        if ($runRanges === []) {
            return false;
        }
        $runLastSourceIndex = max(array_column($runRanges, 'sourceIndex'));
        $runLastOrder = (int) ($run['lastOrder'] ?? $run['order'] ?? -1);
        $runPage = (int) ($run['page'] ?? 0);
        $runStream = (int) ($run['stream'] ?? 0);
        if ($runLastOrder < 0 || $runPage < 1 || $runStream < 1) {
            return false;
        }
        $script = '';
        $scriptX1 = null;
        $scriptX2 = null;
        $scriptSourceIndexes = [];
        $scriptOrders = [];
        foreach ($row['runs'] as $rowRun) {
            $rowRanges = $this->pdfPositionedExactSourceRanges($rowRun);
            $compact = preg_replace('/\s+/u', '', (string) ($rowRun['text'] ?? '')) ?? '';
            if ($rowRanges === []
                || $compact === ''
                || preg_match('/^[\p{N}\p{P}\p{S}]+$/uD', $compact) !== 1
                || (int) ($rowRun['page'] ?? 0) !== $runPage
                || (int) ($rowRun['stream'] ?? 0) !== $runStream
                || (float) ($rowRun['fontSize'] ?? 1.0) >= $runFontSize) {
                return false;
            }
            array_push($scriptSourceIndexes, ...array_column($rowRanges, 'sourceIndex'));
            $scriptOrders[] = (int) ($rowRun['order'] ?? -1);
            $script .= $compact;
            $scriptX1 = min($scriptX1 ?? (float) $rowRun['x1'], (float) $rowRun['x1']);
            $scriptX2 = max($scriptX2 ?? (float) $rowRun['x2'], (float) $rowRun['x2']);
        }
        if ($script === '' || $this->length($script) > 4 || $scriptX1 === null || $scriptX2 === null) {
            return false;
        }
        $scriptSourceIndexes = array_values(array_unique($scriptSourceIndexes, SORT_NUMERIC));
        sort($scriptSourceIndexes, SORT_NUMERIC);
        sort($scriptOrders, SORT_NUMERIC);
        if (($scriptSourceIndexes[0] ?? null) !== $runLastSourceIndex + 1
            || ($scriptOrders[0] ?? null) !== $runLastOrder + 1) {
            return false;
        }
        for ($index = 1, $count = count($scriptSourceIndexes); $index < $count; $index++) {
            if ($scriptSourceIndexes[$index] !== $scriptSourceIndexes[$index - 1] + 1) {
                return false;
            }
        }
        $horizontalTolerance = max(2.0, $rowFontSize * 0.5);

        return $scriptX1 <= (float) $run['x2'] + $horizontalTolerance
            && $scriptX2 >= (float) $run['x1'] - $horizontalTolerance;
    }

    /**
     * @param list<array{page: int, text: string, x1: float, y1: float, x2: float, y2: float, textX1: float, textY1: float, textX2: float, textY2: float, fontSize: float, order?: int}> $runs
     * @return list<array{page: int, text: string, x1: float, y1: float, x2: float, y2: float, textX1: float, textY1: float, textX2: float, textY2: float, fontSize: float, order?: int}>
     */
    private function removeOverprintedPositionedRuns(array $runs): array
    {
        if (count($runs) < 4) {
            return $runs;
        }

        $ordered = $runs;
        usort($ordered, static fn (array $left, array $right): int => ((int) ($left['order'] ?? 0)) <=> ((int) ($right['order'] ?? 0)));

        $layers = [];
        $current = [];
        $currentRight = null;
        foreach ($ordered as $run) {
            if ($current !== [] && $currentRight !== null && $run['x1'] < $currentRight - max(6.0, $run['fontSize'] * 2.0)) {
                $layers[] = $current;
                $current = [];
                $currentRight = null;
            }
            $current[] = $run;
            $currentRight = max($currentRight ?? $run['x2'], $run['x2']);
        }
        if ($current !== []) {
            $layers[] = $current;
        }

        if (count($layers) < 2) {
            return $runs;
        }

        $kept = [];
        foreach ($layers as $layer) {
            $duplicateIndex = null;
            foreach ($kept as $index => $keptLayer) {
                if ($this->positionedRunLayersLookOverprinted($keptLayer, $layer)) {
                    $duplicateIndex = $index;
                    break;
                }
            }
            if ($duplicateIndex === null) {
                $kept[] = $layer;
                continue;
            }
            $keptText = $this->normalizedPositionedLayerText($kept[$duplicateIndex]);
            $layerText = $this->normalizedPositionedLayerText($layer);
            if ($keptText !== '' && $layerText !== '' && str_ends_with($keptText, $layerText)) {
                continue;
            }
            if (($keptText === '' || !str_ends_with($layerText, $keptText))
                && $this->positionedRunLayerArea($layer) >= $this->positionedRunLayerArea($kept[$duplicateIndex])) {
                continue;
            }
            if ($layerText !== '' && ($keptText === '' || str_ends_with($layerText, $keptText) || $this->positionedRunLayerArea($layer) < $this->positionedRunLayerArea($kept[$duplicateIndex]))) {
                $kept[$duplicateIndex] = $layer;
            }
        }

        if (count($kept) === count($layers)) {
            return $runs;
        }

        return array_merge(...$kept);
    }

    /**
     * @param list<array{page: int, text: string, x1: float, y1: float, x2: float, y2: float, textX1: float, textY1: float, textX2: float, textY2: float, fontSize: float}> $left
     * @param list<array{page: int, text: string, x1: float, y1: float, x2: float, y2: float, textX1: float, textY1: float, textX2: float, textY2: float, fontSize: float}> $right
     */
    private function positionedRunLayersLookOverprinted(array $left, array $right): bool
    {
        $leftText = $this->normalizedPositionedLayerText($left);
        $rightText = $this->normalizedPositionedLayerText($right);
        if ($leftText === '' || $rightText === '') {
            return false;
        }
        if ($leftText !== $rightText && !str_ends_with($leftText, $rightText) && !str_ends_with($rightText, $leftText)) {
            return false;
        }

        $leftBounds = $this->positionedRunsBounds($left);
        $rightBounds = $this->positionedRunsBounds($right);
        $overlapWidth = min($leftBounds['x2'], $rightBounds['x2']) - max($leftBounds['x1'], $rightBounds['x1']);
        $overlapHeight = min($leftBounds['y2'], $rightBounds['y2']) - max($leftBounds['y1'], $rightBounds['y1']);
        if ($overlapWidth <= 0.0 || $overlapHeight < -2.0) {
            return false;
        }

        $leftWidth = max(1.0, $leftBounds['x2'] - $leftBounds['x1']);
        $rightWidth = max(1.0, $rightBounds['x2'] - $rightBounds['x1']);

        return $overlapWidth / min($leftWidth, $rightWidth) >= 0.82;
    }

    /**
     * @param list<array{page: int, text: string, x1: float, y1: float, x2: float, y2: float, textX1: float, textY1: float, textX2: float, textY2: float, fontSize: float}> $runs
     */
    private function positionedRunLayerArea(array $runs): float
    {
        $bounds = $this->positionedRunsBounds($runs);

        return max(1.0, $bounds['x2'] - $bounds['x1']) * max(1.0, $bounds['y2'] - $bounds['y1']);
    }

    /**
     * @param list<array{page: int, text: string, x1: float, y1: float, x2: float, y2: float, textX1: float, textY1: float, textX2: float, textY2: float, fontSize: float}> $runs
     * @return array{x1: float, y1: float, x2: float, y2: float}
     */
    private function positionedRunsBounds(array $runs): array
    {
        $bounds = ['x1' => INF, 'y1' => INF, 'x2' => -INF, 'y2' => -INF];
        foreach ($runs as $run) {
            $bounds['x1'] = min($bounds['x1'], $run['x1'], $run['textX1']);
            $bounds['y1'] = min($bounds['y1'], $run['y1'], $run['textY1']);
            $bounds['x2'] = max($bounds['x2'], $run['x2'], $run['textX2']);
            $bounds['y2'] = max($bounds['y2'], $run['y2'], $run['textY2']);
        }

        return is_finite($bounds['x1']) && is_finite($bounds['x2']) && is_finite($bounds['y1']) && is_finite($bounds['y2'])
            ? $bounds
            : ['x1' => 0.0, 'y1' => 0.0, 'x2' => 0.0, 'y2' => 0.0];
    }

    /**
     * @param list<array{text: string, x1: float}> $runs
     */
    private function positionedRunsText(array $runs): string
    {
        usort($runs, static fn (array $left, array $right): int => $left['x1'] <=> $right['x1']);
        $text = '';
        foreach ($runs as $run) {
            $text = $this->appendCellText($text, $run['text']);
        }

        return $text;
    }

    /**
     * @param list<array{text: string, x1: float}> $runs
     */
    private function normalizedPositionedLayerText(array $runs): string
    {
        return preg_replace('/\s+/u', '', $this->positionedRunsText($runs)) ?? '';
    }

    /**
     * @param array{textY1: float, textY2: float, y1: float, y2: float} $run
     */
    private static function positionedRunRowCenter(array $run): float
    {
        $textY1 = (float) $run['textY1'];
        $textY2 = (float) $run['textY2'];
        if (abs($textY2 - $textY1) <= max(0.5, abs($run['y2'] - $run['y1']) * 0.35)) {
            return ($textY1 + $textY2) / 2.0;
        }

        return ((float) $run['y1'] + (float) $run['y2']) / 2.0;
    }

    /**
     * @param list<array{center: float, runs: list<array{page: int, text: string, x1: float, y1: float, x2: float, y2: float, textX1: float, textY1: float, textX2: float, textY2: float, fontSize: float}>}> $rows
     * @return list<array{center: float, runs: list<array{page: int, text: string, x1: float, y1: float, x2: float, y2: float, textX1: float, textY1: float, textX2: float, textY2: float, fontSize: float}>}>
     */
    private function mergePositionedRowFragments(array $rows): array
    {
        foreach ($rows as &$row) {
            $merged = [];
            foreach ($row['runs'] as $run) {
                $lastIndex = array_key_last($merged);
                if ($lastIndex === null) {
                    $merged[] = $run;
                    continue;
                }

                $last = $merged[$lastIndex];
                $gap = $run['textX1'] - $last['textX2'];
                $mergeGap = max(4.0, max($run['fontSize'], $last['fontSize']) * 1.25);
                if ($gap <= $mergeGap) {
                    $sourceVerifiedBoundarySeparators = $this->positionedJoinedSourceVerifiedBoundarySeparators(
                        $last,
                        $run,
                        $gap,
                        max($run['fontSize'], $last['fontSize']),
                        (bool) ($last['endsWithWhitespace'] ?? false),
                        (bool) ($run['startsWithWhitespace'] ?? false),
                        (bool) ($run['hasWordBoundaryBefore'] ?? false),
                        (bool) ($run['wordBoundaryBefore'] ?? false),
                        is_string($run['wordBoundarySource'] ?? null)
                            ? $run['wordBoundarySource']
                            : null
                    );
                    $sourceCompactBoundaryOffsets = $this->positionedJoinedSourceCompactBoundaryOffsets(
                        $last,
                        $run,
                        $gap,
                        max($run['fontSize'], $last['fontSize']),
                        (bool) ($last['endsWithWhitespace'] ?? false),
                        (bool) ($run['startsWithWhitespace'] ?? false),
                        (bool) ($run['hasWordBoundaryBefore'] ?? false),
                        (bool) ($run['wordBoundaryBefore'] ?? false),
                        is_string($run['wordBoundarySource'] ?? null)
                            ? $run['wordBoundarySource']
                            : null
                    );
                    $mergedRun = [
                        'page' => $last['page'],
                        'text' => $this->joinPositionedCellText(
                            $last['text'],
                            $run['text'],
                            $gap,
                            max($run['fontSize'], $last['fontSize']),
                            (bool) ($last['endsWithWhitespace'] ?? false),
                            (bool) ($run['startsWithWhitespace'] ?? false),
                            (bool) ($run['hasWordBoundaryBefore'] ?? false),
                            (bool) ($run['wordBoundaryBefore'] ?? false),
                            is_string($run['wordBoundarySource'] ?? null)
                                ? $run['wordBoundarySource']
                                : null
                        ),
                        'x1' => min($last['x1'], $run['x1']),
                        'y1' => min($last['y1'], $run['y1']),
                        'x2' => max($last['x2'], $run['x2']),
                        'y2' => max($last['y2'], $run['y2']),
                        'textX1' => min($last['textX1'], $run['textX1']),
                        'textY1' => min($last['textY1'], $run['textY1']),
                        'textX2' => max($last['textX2'], $run['textX2']),
                        'textY2' => max($last['textY2'], $run['textY2']),
                        'fontSize' => max($run['fontSize'], $last['fontSize']),
                        'startsWithWhitespace' => (bool) ($last['startsWithWhitespace'] ?? false),
                        'endsWithWhitespace' => (bool) ($run['endsWithWhitespace'] ?? false),
                        'hasWordBoundaryBefore' => (bool) ($last['hasWordBoundaryBefore'] ?? false),
                        'wordBoundaryBefore' => (bool) ($last['wordBoundaryBefore'] ?? false),
                        'wordBoundarySource' => $last['wordBoundarySource'] ?? null,
                        'sourceVerifiedBoundarySeparators' => $sourceVerifiedBoundarySeparators,
                        'sourceCompactBoundaryOffsets' => $sourceCompactBoundaryOffsets,
                        'startsAfterTextBoundary' => (bool) ($last['startsAfterTextBoundary'] ?? false),
                        'order' => min((int) ($last['order'] ?? 0), (int) ($run['order'] ?? 0)),
                        'lastOrder' => max((int) ($last['lastOrder'] ?? $last['order'] ?? 0), (int) ($run['lastOrder'] ?? $run['order'] ?? 0)),
                    ];
                    $sourceStreams = $this->positionedTableSourceStreamsForItems([$last, $run]);
                    if ($sourceStreams !== null && $sourceStreams !== []) {
                        $mergedRun['sourcePdfStreams'] = $sourceStreams;
                        if (count($sourceStreams) === 1) {
                            $mergedRun['stream'] = $sourceStreams[0];
                        }
                    }
                    $sourceOrder = $this->positionedTableSourceOrderBoundsForItems([$last, $run]);
                    if ($sourceOrder !== null) {
                        $mergedRun['sourceOrderStart'] = $sourceOrder['start'];
                        $mergedRun['sourceOrderEnd'] = $sourceOrder['end'];
                    }
                    $exactSourceRanges = $this->positionedTableExactSourceRangesForItems([$last, $run]);
                    if ($exactSourceRanges !== null && $exactSourceRanges !== []) {
                        $mergedRun['sourcePdfExactSourceRanges'] = $exactSourceRanges;
                    }
                    $merged[$lastIndex] = $mergedRun;
                    continue;
                }

                $merged[] = $run;
            }
            $row['runs'] = $merged;
        }
        unset($row);

        return $rows;
    }

    /**
     * Preserve only a complete, non-overlapping exact range union for table
     * text. A fragment with visible text but missing or malformed provenance
     * invalidates the combined proof instead of leaving a plausible partial
     * range on the reconstructed cell.
     *
     * @param list<array<string, mixed>> $items
     * @return list<array{sourceIndex:int,sourceStart:int,sourceEnd:int}>|null
     */
    private function positionedTableExactSourceRangesForItems(array $items): ?array
    {
        $ranges = [];
        $coveredBySourceIndex = [];
        $pages = [];
        foreach ($items as $item) {
            if (trim((string) ($item['text'] ?? '')) === '') {
                continue;
            }
            $page = isset($item['page']) && is_numeric($item['page'])
                ? max(1, (int) $item['page'])
                : null;
            if ($page !== null) {
                $pages[$page] = true;
            }
            $declaresExactRanges = array_key_exists('sourcePdfExactSourceRanges', $item)
                || array_key_exists('sourcePdfExactSourceIndex', $item)
                || array_key_exists('sourcePdfExactSourceStart', $item)
                || array_key_exists('sourcePdfExactSourceEnd', $item);
            $itemRanges = $this->pdfPositionedExactSourceRanges($item);
            if (!$declaresExactRanges || $itemRanges === []) {
                return null;
            }
            foreach ($itemRanges as $range) {
                $sourceIndex = $range['sourceIndex'];
                foreach ($coveredBySourceIndex[$sourceIndex] ?? [] as $covered) {
                    if ($range['sourceStart'] < $covered['end']
                        && $range['sourceEnd'] > $covered['start']) {
                        return null;
                    }
                }
                $coveredBySourceIndex[$sourceIndex][] = [
                    'start' => $range['sourceStart'],
                    'end' => $range['sourceEnd'],
                ];
                $lastIndex = array_key_last($ranges);
                if ($lastIndex !== null
                    && $ranges[$lastIndex]['sourceIndex'] === $sourceIndex
                    && $ranges[$lastIndex]['sourceEnd'] === $range['sourceStart']) {
                    $ranges[$lastIndex]['sourceEnd'] = $range['sourceEnd'];
                    continue;
                }
                $ranges[] = $range;
            }
        }

        return count($pages) > 1 ? null : $ranges;
    }

    /**
     * @param list<array<string, mixed>> $items
     * @return list<int>|null
     */
    private function positionedTableSourceStreamsForItems(array $items): ?array
    {
        $streams = [];
        foreach ($items as $item) {
            if (trim((string) ($item['text'] ?? '')) === '') {
                continue;
            }
            $candidates = is_array($item['sourcePdfStreams'] ?? null)
                ? $item['sourcePdfStreams']
                : (isset($item['stream']) ? [$item['stream']] : []);
            if ($candidates === []) {
                return null;
            }
            foreach ($candidates as $candidate) {
                if ((!is_int($candidate) && !(is_string($candidate) && ctype_digit($candidate)))
                    || (int) $candidate < 1) {
                    return null;
                }
                $stream = (int) $candidate;
                $streams[$stream] = $stream;
            }
        }

        return array_values($streams);
    }

    /**
     * @param list<array<string, mixed>> $items
     * @return array{start:int,end:int}|null
     */
    private function positionedTableSourceOrderBoundsForItems(array $items): ?array
    {
        $start = null;
        $end = null;
        foreach ($items as $item) {
            if (trim((string) ($item['text'] ?? '')) === '') {
                continue;
            }
            $itemStart = $item['sourceOrderStart'] ?? $item['order'] ?? null;
            $itemEnd = $item['sourceOrderEnd'] ?? $item['lastOrder'] ?? $itemStart;
            if ((!is_int($itemStart) && !(is_string($itemStart) && ctype_digit($itemStart)))
                || (!is_int($itemEnd) && !(is_string($itemEnd) && ctype_digit($itemEnd)))
                || (int) $itemStart < 0
                || (int) $itemEnd < (int) $itemStart) {
                return null;
            }
            $start = min($start ?? (int) $itemStart, (int) $itemStart);
            $end = max($end ?? (int) $itemEnd, (int) $itemEnd);
        }

        return $start === null || $end === null ? null : ['start' => $start, 'end' => $end];
    }

    /**
     * @param list<array{center: float, runs: list<array{page: int, text: string, x1: float, y1: float, x2: float, y2: float, textX1: float, textY1: float, textX2: float, textY2: float, fontSize: float}>}> $rows
     * @return list<float>
     */
    private function positionedTableColumns(array $rows, float $tolerance): array
    {
        $positions = [];
        foreach ($rows as $row) {
            foreach ($row['runs'] as $run) {
                $positions[] = $run['textX1'];
            }
        }
        sort($positions, SORT_NUMERIC);

        $clusters = [];
        foreach ($positions as $x) {
            $matchedIndex = null;
            foreach ($clusters as $index => $cluster) {
                if (abs($x - $cluster['center']) <= $tolerance) {
                    $matchedIndex = $index;
                    break;
                }
            }
            if ($matchedIndex === null) {
                $clusters[] = ['center' => $x, 'count' => 1];
                continue;
            }

            $count = $clusters[$matchedIndex]['count'];
            $clusters[$matchedIndex]['center'] = (($clusters[$matchedIndex]['center'] * $count) + $x) / ($count + 1);
            $clusters[$matchedIndex]['count'] = $count + 1;
        }

        $columns = array_map(static fn (array $cluster): float => $cluster['center'], $clusters);
        sort($columns, SORT_NUMERIC);

        return $columns;
    }

    /**
     * @param list<array{center: float, runs: list<array{page: int, text: string, x1: float, y1: float, x2: float, y2: float, textX1: float, textY1: float, textX2: float, textY2: float, fontSize: float}>}> $rows
     * @param list<float> $columns
     * @return list<list<string>>
     */
    private function positionedRowsWithCells(array $rows, array $columns): array
    {
        $tableBounds = $this->positionedRowsBounds($rows);
        $columnBounds = $this->positionedColumnBounds($columns, $tableBounds['x1'], $tableBounds['x2']);
        $cellRows = [];
        foreach ($rows as $row) {
            $rowBounds = $this->positionedRowBounds($row);
            $cells = [];
            foreach ($columns as $index => $_column) {
                $cells[$index] = $this->emptyPositionedCell($rowBounds, $columnBounds[$index] ?? null);
            }
            foreach ($row['runs'] as $run) {
                $columnIndex = $this->nearestPositionedColumn($columns, $run['textX1']);
                $cells[$columnIndex] = $this->mergePositionedCells($cells[$columnIndex], $this->positionedCellFromRun($run));
            }
            $cellRows[] = array_map(fn (mixed $cell): array => is_array($cell) ? $cell : $this->emptyPositionedCell(), $cells);
        }

        return $cellRows;
    }

    /**
     * @param list<array{center: float, runs: list<array{page: int, text: string, x1: float, y1: float, x2: float, y2: float, textX1: float, textY1: float, textX2: float, textY2: float, fontSize: float}>}> $rows
     * @return array{x1: float, y1: float, x2: float, y2: float}
     */
    private function positionedRowsBounds(array $rows): array
    {
        $bounds = ['x1' => INF, 'y1' => INF, 'x2' => -INF, 'y2' => -INF];
        foreach ($rows as $row) {
            foreach ($row['runs'] as $run) {
                $bounds['x1'] = min($bounds['x1'], $run['x1'], $run['textX1']);
                $bounds['y1'] = min($bounds['y1'], $run['y1'], $run['textY1']);
                $bounds['x2'] = max($bounds['x2'], $run['x2'], $run['textX2']);
                $bounds['y2'] = max($bounds['y2'], $run['y2'], $run['textY2']);
            }
        }

        return is_finite($bounds['x1']) && is_finite($bounds['x2']) && is_finite($bounds['y1']) && is_finite($bounds['y2'])
            ? $bounds
            : ['x1' => 0.0, 'y1' => 0.0, 'x2' => 0.0, 'y2' => 0.0];
    }

    /**
     * @param array{center: float, runs: list<array{page: int, text: string, x1: float, y1: float, x2: float, y2: float, textX1: float, textY1: float, textX2: float, textY2: float, fontSize: float}>} $row
     * @return array{y1: float, y2: float}
     */
    private function positionedRowBounds(array $row): array
    {
        $y1 = INF;
        $y2 = -INF;
        foreach ($row['runs'] as $run) {
            $y1 = min($y1, $run['y1'], $run['textY1']);
            $y2 = max($y2, $run['y2'], $run['textY2']);
        }

        return is_finite($y1) && is_finite($y2)
            ? ['y1' => $y1, 'y2' => $y2]
            : ['y1' => $row['center'], 'y2' => $row['center']];
    }

    /**
     * @param list<float> $columns
     * @return list<array{x1: float, x2: float}>
     */
    private function positionedColumnBounds(array $columns, float $tableX1, float $tableX2): array
    {
        $bounds = [];
        $count = count($columns);
        for ($index = 0; $index < $count; $index++) {
            $left = $index === 0
                ? min($tableX1, $columns[$index])
                : ($columns[$index - 1] + $columns[$index]) / 2.0;
            $right = $index + 1 < $count
                ? ($columns[$index] + $columns[$index + 1]) / 2.0
                : max($tableX2, $columns[$index]);

            if ($right <= $left) {
                $left = $columns[$index] - 4.0;
                $right = $columns[$index] + 4.0;
            }

            $bounds[] = ['x1' => $left, 'x2' => $right];
        }

        return $bounds;
    }

    /**
     * @param array{page: int, text: string, x1: float, y1: float, x2: float, y2: float, textX1: float, textY1: float, textX2: float, textY2: float, fontSize: float} $run
     * @return array{text: string, x1: float, y1: float, x2: float, y2: float, contentX1: float, contentX2: float}
     */
    private function positionedCellFromRun(array $run): array
    {
        $cell = [
            'page' => $run['page'],
            'text' => $run['text'],
            'x1' => $run['textX1'],
            'y1' => $run['y1'],
            'x2' => $run['textX2'],
            'y2' => $run['y2'],
            'contentX1' => $run['textX1'],
            'contentX2' => $run['textX2'],
            'fontSize' => $run['fontSize'],
        ];
        $sourceStreams = $this->positionedTableSourceStreamsForItems([$run]);
        if ($sourceStreams !== null && $sourceStreams !== []) {
            $cell['sourcePdfStreams'] = $sourceStreams;
            if (count($sourceStreams) === 1) {
                $cell['stream'] = $sourceStreams[0];
            }
        }
        $sourceOrder = $this->positionedTableSourceOrderBoundsForItems([$run]);
        if ($sourceOrder !== null) {
            $cell['sourceOrderStart'] = $sourceOrder['start'];
            $cell['sourceOrderEnd'] = $sourceOrder['end'];
        }
        $exactSourceRanges = $this->positionedTableExactSourceRangesForItems([$run]);
        if ($exactSourceRanges !== null && $exactSourceRanges !== []) {
            $cell['sourcePdfExactSourceRanges'] = $exactSourceRanges;
        }

        return $cell;
    }

    /**
     * @param array{y1: float, y2: float}|null $rowBounds
     * @param array{x1: float, x2: float}|null $columnBounds
     * @return array<string, mixed>
     */
    private function emptyPositionedCell(?array $rowBounds = null, ?array $columnBounds = null): array
    {
        $cell = ['text' => ''];
        if ($rowBounds !== null && $columnBounds !== null) {
            $cell['x1'] = $columnBounds['x1'];
            $cell['y1'] = $rowBounds['y1'];
            $cell['x2'] = $columnBounds['x2'];
            $cell['y2'] = $rowBounds['y2'];
        }

        return $cell;
    }

    /**
     * @param array<string, mixed>|null $left
     * @param array<string, mixed> $right
     * @return array<string, mixed>
     */
    private function mergePositionedCells(?array $left, array $right): array
    {
        if ($left === null) {
            $left = ['text' => ''];
        }

        $leftText = $this->cellTextValue($left);
        $rightText = $this->cellTextValue($right);
        $merged = array_replace($left, array_diff_key($right, array_flip([
            'text',
            'page',
            'stream',
            'sourcePdfStreams',
            'sourceOrderStart',
            'sourceOrderEnd',
            'sourcePdfExactSourceRanges',
            'sourcePdfExactSourceIndex',
            'sourcePdfExactSourceStart',
            'sourcePdfExactSourceEnd',
            'x1',
            'y1',
            'x2',
            'y2',
            'contentX1',
            'contentX2',
            'fontSize',
        ])));
        $merged['text'] = $leftText === ''
            ? $rightText
            : ($rightText === '' ? $leftText : $this->appendCellText($leftText, $rightText));

        foreach (['x1', 'y1', 'x2', 'y2', 'contentX1', 'contentX2'] as $key) {
            $leftValue = $this->numericValue($left[$key] ?? null);
            $rightValue = $this->numericValue($right[$key] ?? null);
            if ($leftValue === null && $rightValue === null) {
                continue;
            }
            if ($leftValue === null) {
                $merged[$key] = $rightValue;
                continue;
            }
            if ($rightValue === null) {
                $merged[$key] = $leftValue;
                continue;
            }
            $merged[$key] = in_array($key, ['x1', 'y1', 'contentX1'], true)
                ? min($leftValue, $rightValue)
                : max($leftValue, $rightValue);
        }

        $leftFontSize = $this->numericValue($left['fontSize'] ?? null);
        $rightFontSize = $this->numericValue($right['fontSize'] ?? null);
        if ($leftFontSize !== null || $rightFontSize !== null) {
            $merged['fontSize'] = max($leftFontSize ?? 0.0, $rightFontSize ?? 0.0);
        }
        $pages = [];
        foreach ([$left, $right] as $item) {
            if (trim((string) ($item['text'] ?? '')) !== '' && is_numeric($item['page'] ?? null)) {
                $page = max(1, (int) $item['page']);
                $pages[$page] = $page;
            }
        }
        if (count($pages) === 1) {
            $merged['page'] = array_values($pages)[0];
        } elseif (count($pages) > 1) {
            unset($merged['page']);
        }
        $sourceStreams = $this->positionedTableSourceStreamsForItems([$left, $right]);
        if ($sourceStreams !== null && $sourceStreams !== []) {
            $merged['sourcePdfStreams'] = $sourceStreams;
            if (count($sourceStreams) === 1) {
                $merged['stream'] = $sourceStreams[0];
            } else {
                unset($merged['stream']);
            }
        } else {
            unset($merged['sourcePdfStreams'], $merged['stream']);
        }
        $sourceOrder = $this->positionedTableSourceOrderBoundsForItems([$left, $right]);
        if ($sourceOrder !== null) {
            $merged['sourceOrderStart'] = $sourceOrder['start'];
            $merged['sourceOrderEnd'] = $sourceOrder['end'];
        } else {
            unset($merged['sourceOrderStart'], $merged['sourceOrderEnd']);
        }
        unset(
            $merged['sourcePdfExactSourceRanges'],
            $merged['sourcePdfExactSourceIndex'],
            $merged['sourcePdfExactSourceStart'],
            $merged['sourcePdfExactSourceEnd']
        );
        $exactSourceRanges = $this->positionedTableExactSourceRangesForItems([$left, $right]);
        if ($exactSourceRanges !== null && $exactSourceRanges !== []) {
            $merged['sourcePdfExactSourceRanges'] = $exactSourceRanges;
        }

        return $merged;
    }

    /**
     * @param list<list<mixed>> $rows
     * @param list<array{page: int, x1: float, y1: float, x2: float, y2: float, fillColor: string}> $filledRectangles
     * @return list<list<mixed>>
     */
    private function withPositionedCellBackgrounds(array $rows, array $filledRectangles): array
    {
        if ($filledRectangles === []) {
            return $rows;
        }

        foreach ($rows as &$row) {
            foreach ($row as &$cell) {
                if (!is_array($cell)) {
                    continue;
                }

                $fill = $this->positionedCellBackgroundMatch($cell, $filledRectangles);
                if ($fill === null) {
                    continue;
                }
                $fillColor = $fill['color'];

                $htmlAttributes = is_array($cell['htmlAttributes'] ?? null) ? $cell['htmlAttributes'] : [];
                $style = trim((string) ($htmlAttributes['style'] ?? ''));
                if (preg_match('/(?:^|;)\s*background(?:-color)?\s*:/i', $style) !== 1) {
                    $style = trim($style === '' ? 'background-color:' . $fillColor : rtrim($style, ';') . '; background-color:' . $fillColor);
                }
                $contrastColor = $this->pdfTableCellContrastColor($fillColor);
                if ($contrastColor !== null && preg_match('/(?:^|;)\s*color\s*:/i', $style) !== 1) {
                    // PDF geometry exposes filled rectangles independently of
                    // text paint. Keep a dark cell readable when no reliable
                    // foreground color survived extraction; an explicit text
                    // color, when available, always wins.
                    $style = trim($style === '' ? 'color:' . $contrastColor : rtrim($style, ';') . '; color:' . $contrastColor);
                    $htmlAttributes['data-pdf-contrast-color'] = $contrastColor;
                }
                $htmlAttributes['style'] = $style;
                $htmlAttributes['data-pdf-fill-color'] = $fillColor;
                $cell['htmlAttributes'] = $htmlAttributes;
                // Keep classification evidence internal. A page or panel
                // background can overlap every inferred cell, but only paint
                // whose height is local to one visual row discriminates a
                // table row/cell from independent columns.
                $cell['pdfFillRowDiscriminating'] = $fill['rowDiscriminating'];
            }
            unset($cell);
        }
        unset($row);

        return $rows;
    }

    private function pdfTableCellContrastColor(string $fillColor): ?string
    {
        if (preg_match('/^#([0-9a-f]{2})([0-9a-f]{2})([0-9a-f]{2})$/i', $fillColor, $matches) !== 1) {
            return null;
        }

        $channels = [];
        for ($index = 1; $index <= 3; $index++) {
            $channel = hexdec($matches[$index]) / 255.0;
            $channels[] = $channel <= 0.04045
                ? $channel / 12.92
                : (($channel + 0.055) / 1.055) ** 2.4;
        }
        $luminance = (0.2126 * $channels[0]) + (0.7152 * $channels[1]) + (0.0722 * $channels[2]);
        $whiteContrast = 1.05 / ($luminance + 0.05);

        return $whiteContrast >= 4.5 ? '#ffffff' : null;
    }

    /**
     * @param array<string, mixed> $cell
     * @param list<array{page: int, x1: float, y1: float, x2: float, y2: float, fillColor: string}> $filledRectangles
     * @return array{color:string,rowDiscriminating:bool}|null
     */
    private function positionedCellBackgroundMatch(array $cell, array $filledRectangles): ?array
    {
        $x1 = $this->numericValue($cell['x1'] ?? null);
        $y1 = $this->numericValue($cell['y1'] ?? null);
        $x2 = $this->numericValue($cell['x2'] ?? null);
        $y2 = $this->numericValue($cell['y2'] ?? null);
        if ($x1 === null || $y1 === null || $x2 === null || $y2 === null) {
            return null;
        }

        $cellX1 = min($x1, $x2);
        $cellY1 = min($y1, $y2);
        $cellX2 = max($x1, $x2);
        $cellY2 = max($y1, $y2);
        $cellArea = ($cellX2 - $cellX1) * ($cellY2 - $cellY1);
        if ($cellArea <= 0.0) {
            return null;
        }

        $bestMatch = null;
        $bestArea = INF;
        foreach ($filledRectangles as $rectangle) {
            $overlapWidth = max(0.0, min($cellX2, $rectangle['x2']) - max($cellX1, $rectangle['x1']));
            $overlapHeight = max(0.0, min($cellY2, $rectangle['y2']) - max($cellY1, $rectangle['y1']));
            $coverage = ($overlapWidth * $overlapHeight) / $cellArea;
            // A table rule can cross a cell center without being its fill.
            if ($coverage < 0.6) {
                continue;
            }

            $area = max(0.0, ($rectangle['x2'] - $rectangle['x1']) * ($rectangle['y2'] - $rectangle['y1']));
            if ($area < $bestArea) {
                $bestArea = $area;
                $cellHeight = max(0.0, $cellY2 - $cellY1);
                $rectangleHeight = max(0.0, $rectangle['y2'] - $rectangle['y1']);
                $bestMatch = [
                    'color' => $rectangle['fillColor'],
                    // Normal PDF table fills usually extend a little beyond
                    // glyph bounds. A rectangle several row-heights tall is a
                    // shared region/background, not cell or row evidence.
                    'rowDiscriminating' => $cellHeight > 0.0
                        && $rectangleHeight <= max($cellHeight * 2.6, $cellHeight + 8.0),
                ];
            }
        }

        return $bestMatch;
    }

    /**
     * @param list<float> $columns
     */
    private function nearestPositionedColumn(array $columns, float $x): int
    {
        $nearestIndex = 0;
        $nearestDistance = INF;
        foreach ($columns as $index => $columnX) {
            $distance = abs($x - $columnX);
            if ($distance < $nearestDistance) {
                $nearestDistance = $distance;
                $nearestIndex = $index;
            }
        }

        return $nearestIndex;
    }

    /**
     * @param list<list<string>> $rows
     * @return list<list<string>>
     */
    private function mergePositionedContinuationRows(array $rows): array
    {
        $logicalRows = [];
        foreach ($rows as $row) {
            $populated = $this->populatedCellIndexes($row);
            if ($populated === []) {
                continue;
            }

            if (count($populated) === 1 && $logicalRows !== []) {
                $lastIndex = array_key_last($logicalRows);
                $columnIndex = $populated[0];
                $logicalRows[$lastIndex][$columnIndex] = $this->mergePositionedCells(
                    is_array($logicalRows[$lastIndex][$columnIndex]) ? $logicalRows[$lastIndex][$columnIndex] : ['text' => (string) $logicalRows[$lastIndex][$columnIndex]],
                    is_array($row[$columnIndex]) ? $row[$columnIndex] : ['text' => (string) $row[$columnIndex]]
                );
                continue;
            }

            $logicalRows[] = $row;
        }

        return $logicalRows;
    }

    /**
     * @param list<list<mixed>> $rows
     * @return list<list<mixed>>
     */
    private function compactSparsePositionedColumns(array $rows): array
    {
        if ($rows === []) {
            return [];
        }

        $columnCount = 0;
        foreach ($rows as $row) {
            $columnCount = max($columnCount, count($row));
        }
        if ($columnCount < 2) {
            return $rows;
        }

        foreach ($rows as &$row) {
            while (count($row) < $columnCount) {
                $row[] = $this->emptyPositionedCell();
            }
        }
        unset($row);

        $columnIndex = 0;
        while ($columnIndex < $columnCount - 1) {
            if (!$this->canMergeSparsePositionedColumns($rows, $columnIndex, $columnIndex + 1)) {
                $columnIndex++;
                continue;
            }

            foreach ($rows as &$row) {
                $left = is_array($row[$columnIndex]) ? $row[$columnIndex] : ['text' => (string) $row[$columnIndex]];
                $right = is_array($row[$columnIndex + 1]) ? $row[$columnIndex + 1] : ['text' => (string) $row[$columnIndex + 1]];
                $row[$columnIndex] = $this->mergePositionedCells($left, $right);
                array_splice($row, $columnIndex + 1, 1);
            }
            unset($row);
            $columnCount--;
        }

        return $rows;
    }

    /**
     * @param list<list<mixed>> $rows
     */
    private function canMergeSparsePositionedColumns(array $rows, int $leftColumn, int $rightColumn): bool
    {
        $leftHasContent = false;
        $rightHasContent = false;

        foreach ($rows as $row) {
            $leftText = $this->cellTextValue($row[$leftColumn] ?? '');
            $rightText = $this->cellTextValue($row[$rightColumn] ?? '');
            if ($leftText !== '' && $rightText !== '') {
                return false;
            }
            $leftHasContent = $leftHasContent || $leftText !== '';
            $rightHasContent = $rightHasContent || $rightText !== '';
        }

        return $leftHasContent && $rightHasContent;
    }

    /**
     * @param list<list<string>> $rows
     * @return list<list<string>>
     */
    private function trimSparsePositionedRows(array $rows): array
    {
        while ($rows !== [] && count($this->populatedCellIndexes($rows[0])) < 2) {
            array_shift($rows);
        }
        while ($rows !== [] && count($this->populatedCellIndexes($rows[array_key_last($rows)])) < 2) {
            array_pop($rows);
        }

        return array_values($rows);
    }

    /**
     * @param list<list<string>> $rows
     */
    private function isPositionedTableCandidate(array $rows, int $columnCount): bool
    {
        if ($columnCount < 2 || count($rows) < 2) {
            return false;
        }

        $multiCellRows = 0;
        $columnOccupancy = array_fill(0, $columnCount, 0);
        foreach ($rows as $row) {
            $populated = $this->populatedCellIndexes($row);
            if (count($populated) >= 2) {
                $multiCellRows++;
            }
            foreach ($populated as $columnIndex) {
                $columnOccupancy[$columnIndex]++;
            }
        }

        $recurringColumns = 0;
        foreach ($columnOccupancy as $count) {
            if ($count >= 2) {
                $recurringColumns++;
            }
        }

        $hypothesis = $this->positionedTableVsColumnHypothesis(
            $rows,
            $columnCount,
            $multiCellRows,
            $recurringColumns,
            $columnOccupancy
        );

        $lowConfidenceReason = null;
        $selectedFallback = ($hypothesis['selected'] ?? null) === 'independent-columns'
            ? 'independent-columns'
            : 'text';
        if (count($rows) === 2 && !$this->positionedTableHasHorizontalCellText($rows)) {
            $lowConfidenceReason = 'non-horizontal-two-row-grid';
        } elseif ($this->positionedRowsLookLikeSparseProseGrid($rows, $columnCount)) {
            $this->recordPositionedLayoutHypothesis($hypothesis, 'text', 'sparse-prose-grid');

            return false;
        } elseif ($this->positionedRowsLookLikeNarrativeColumnLayout($rows, $columnCount)) {
            $lowConfidenceReason = 'narrative-column-layout';
        } elseif ($this->positionedRowsHavePredominantlyNonHorizontalText($rows)) {
            $lowConfidenceReason = 'predominantly-non-horizontal';
        } elseif ($this->positionedRowsLookLikeCompactLabelGrid($rows, $columnCount)) {
            $lowConfidenceReason = 'compact-label-grid';
        } elseif ($this->positionedRowsLookLikeShortLabelGrid($rows, $columnCount)) {
            $lowConfidenceReason = 'short-label-grid';
        } elseif ($this->positionedRowsLookLikeTitleMetadataGrid($rows, $columnCount)) {
            $lowConfidenceReason = 'title-metadata-grid';
        } elseif ($this->positionedRowsAreUndersizedNonNumericGrid($rows, $columnCount)) {
            $lowConfidenceReason = 'undersized-nonnumeric-grid';
        } elseif ($this->positionedRowsHaveSparsePlaceholderColumns($rows, $columnCount)) {
            $lowConfidenceReason = 'sparse-placeholder-grid';
        } elseif ($this->positionedRowsLookLikeFormLayout($rows, $columnCount)) {
            $lowConfidenceReason = 'form-layout';
        }
        if ($lowConfidenceReason !== null) {
            $this->lowConfidenceGeometryTableCandidates++;
            if ($selectedFallback === 'independent-columns') {
                $this->independentColumnHypothesisCount++;
            }
            $this->recordPositionedLayoutHypothesis($hypothesis, $selectedFallback, $lowConfidenceReason);

            return false;
        }

        if ($multiCellRows < 2 || $recurringColumns < 2) {
            $this->recordPositionedLayoutHypothesis($hypothesis, 'text', 'insufficient-row-correspondence');

            return false;
        }

        if (($hypothesis['selected'] ?? null) === 'independent-columns') {
            $this->lowConfidenceGeometryTableCandidates++;
            $this->independentColumnHypothesisCount++;
            $this->recordPositionedLayoutHypothesis($hypothesis, 'independent-columns', 'column-score-margin');

            return false;
        }

        // The adjusted table score exists to compare two explanations; it is
        // intentionally not a replacement for the established acceptance
        // threshold. If columns did not win by the evidence margin, preserve
        // the incumbent raw confidence so sparse/borderless tables do not
        // regress during rollout.
        $confidence = (float) ($hypothesis['rawTableScore'] ?? 0.0);
        if ($confidence < 0.72) {
            $this->lowConfidenceGeometryTableCandidates++;
            $this->recordPositionedLayoutHypothesis($hypothesis, 'text', 'table-score-below-threshold');

            return false;
        }

        $this->recordPositionedLayoutHypothesis($hypothesis, 'table', 'table-score');

        return true;
    }

    /**
     * Score the two layout explanations independently. The table score starts
     * with the established geometry confidence and is then discounted when
     * there is no row-schema evidence. The column score uses only typography
     * and geometry: it never matches a title, character name, or language.
     *
     * @param list<list<mixed>> $rows
     * @param list<int> $columnOccupancy
     * @return array<string, mixed>
     */
    private function positionedTableVsColumnHypothesis(
        array $rows,
        int $columnCount,
        int $multiCellRows,
        int $recurringColumns,
        array $columnOccupancy
    ): array {
        $rowCount = count($rows);
        $populatedCells = 0;
        $numericCells = 0;
        $structuredNumericCells = 0;
        $structuredNumericCellsByColumn = [];
        $filledCells = 0;
        $rowDiscriminatingFilledCells = 0;
        $cueCells = 0;
        $localCueKeys = [];
        $sentenceCells = 0;
        $narrativeCells = 0;
        $wideCells = 0;
        $wrappedCells = 0;
        $cellHeights = [];
        $page = null;
        $bounds = ['x1' => INF, 'y1' => INF, 'x2' => -INF, 'y2' => -INF];
        foreach ($rows as $row) {
            foreach ($row as $columnIndex => $cell) {
                $text = trim($this->cellTextValue($cell));
                if ($text === '') {
                    continue;
                }
                $populatedCells++;
                if ($this->positionedCellLooksNumericAnchor($text)) {
                    $numericCells++;
                }
                if ($this->positionedCellLooksStructuredNumericValue($text)) {
                    $structuredNumericCells++;
                    $structuredNumericCellsByColumn[(int) $columnIndex] =
                        ($structuredNumericCellsByColumn[(int) $columnIndex] ?? 0) + 1;
                }
                $cueAndBody = $this->pdfDialogueCueAndBody($text);
                if ($cueAndBody !== null) {
                    $cueCells++;
                    $localCueKeys[$this->pdfDialogueCueKey($cueAndBody['cue'])] = true;
                }
                if (preg_match('/\p{Ll}/u', $text) === 1
                    && (preg_match('/[.!?;:]\s*$/u', $text) === 1
                        || $this->positionedCellWordCount($text) >= 5)) {
                    $sentenceCells++;
                }
                if ($this->positionedCellWordCount($text) >= 7 || $this->length($text) >= 48) {
                    $narrativeCells++;
                }
                if (!is_array($cell)) {
                    continue;
                }
                $attributes = is_array($cell['htmlAttributes'] ?? null) ? $cell['htmlAttributes'] : [];
                if (is_string($attributes['data-pdf-fill-color'] ?? null)
                    && $attributes['data-pdf-fill-color'] !== '') {
                    $filledCells++;
                    if (($cell['pdfFillRowDiscriminating'] ?? false) === true) {
                        $rowDiscriminatingFilledCells++;
                    }
                }
                $x1 = $this->numericValue($cell['contentX1'] ?? $cell['x1'] ?? null);
                $x2 = $this->numericValue($cell['contentX2'] ?? $cell['x2'] ?? null);
                $y1 = $this->numericValue($cell['y1'] ?? null);
                $y2 = $this->numericValue($cell['y2'] ?? null);
                if ($x1 !== null && $x2 !== null && abs($x2 - $x1) >= 80.0) {
                    $wideCells++;
                }
                if ($x1 !== null && $x2 !== null && $y1 !== null && $y2 !== null) {
                    $bounds['x1'] = min($bounds['x1'], $x1);
                    $bounds['y1'] = min($bounds['y1'], $y1);
                    $bounds['x2'] = max($bounds['x2'], $x2);
                    $bounds['y2'] = max($bounds['y2'], $y2);
                    $cellHeights[] = max(0.0, $y2 - $y1);
                }
                if ($page === null && isset($cell['page'])) {
                    $page = max(1, (int) $cell['page']);
                }
            }
        }

        $medianHeight = $cellHeights === [] ? 0.0 : $this->median($cellHeights);
        if ($medianHeight > 0.0) {
            foreach ($rows as $row) {
                foreach ($row as $cell) {
                    if (trim($this->cellTextValue($cell)) === '' || !is_array($cell)) {
                        continue;
                    }
                    $y1 = $this->numericValue($cell['y1'] ?? null);
                    $y2 = $this->numericValue($cell['y2'] ?? null);
                    if ($y1 !== null && $y2 !== null && $y2 - $y1 >= $medianHeight * 1.55) {
                        $wrappedCells++;
                    }
                }
            }
        }

        $fillRatio = $populatedCells / max(1, $rowCount * $columnCount);
        $numericRatio = $numericCells / max(1, $populatedCells);
        $structuredNumericRatio = $structuredNumericCells / max(1, $populatedCells);
        $cueRatio = $cueCells / max(1, $populatedCells);
        $sentenceRatio = $sentenceCells / max(1, $populatedCells);
        $narrativeRatio = $narrativeCells / max(1, $populatedCells);
        $wideRatio = $wideCells / max(1, $populatedCells);
        $wrappedRatio = $wrappedCells / max(1, $populatedCells);
        $activeOccupancy = array_values(array_filter($columnOccupancy, static fn (int $count): bool => $count > 0));
        $occupancyImbalance = count($activeOccupancy) < 2
            ? 0.0
            : (max($activeOccupancy) - min($activeOccupancy)) / max(1, max($activeOccupancy));
        $regularRows = 0;
        $dominantPopulation = 0;
        $rowPopulationCounts = [];
        foreach ($rows as $row) {
            $population = count($this->populatedCellIndexes($row));
            if ($population > 0) {
                $rowPopulationCounts[$population] = ($rowPopulationCounts[$population] ?? 0) + 1;
            }
        }
        if ($rowPopulationCounts !== []) {
            $dominantPopulation = max($rowPopulationCounts);
            $regularRows = $dominantPopulation;
        }
        $rowSchemaRatio = $regularRows / max(1, $rowCount);
        $recurringNumericColumns = 0;
        $recurringNumericCells = 0;
        foreach ($structuredNumericCellsByColumn as $count) {
            if ($count < 2) {
                continue;
            }
            $recurringNumericColumns++;
            $recurringNumericCells += $count;
        }
        $documentCueMatches = 0;
        $documentColumnStartCount = 0;
        if ($page !== null && $this->documentLayoutProfile !== []) {
            $pageEvidence = $this->documentLayoutProfile['pageEvidence'][(string) $page] ?? null;
            if (is_array($pageEvidence)) {
                $documentColumnStartCount = count(array_filter(
                    is_array($pageEvidence['lineStarts'] ?? null) ? $pageEvidence['lineStarts'] : [],
                    static fn (mixed $count): bool => (int) $count >= 2
                ));
            }
            foreach ($this->documentLayoutProfile['cueProfile'] ?? [] as $cueEvidence) {
                if (!is_array($cueEvidence)
                    || !is_string($cueEvidence['cue'] ?? null)
                    || !isset($localCueKeys[$cueEvidence['cue']])
                    || (int) ($cueEvidence['count'] ?? 0) < 2) {
                    continue;
                }
                $documentCueMatches += (int) $cueEvidence['count'];
            }
        }
        $compactHeader = $this->positionedRowLooksLikeCompactTableHeader($rows[0] ?? []);
        $hardFillEvidence = $rowDiscriminatingFilledCells >= 2;
        // A year, line number, or numbered speaker in one visual row is not a
        // table schema. Require strict numeric/date/currency values to recur in
        // a stable column, with a dense strict-value matrix as the only
        // schema-free exception for genuinely numeric tables.
        $overwhelmingNumericEvidence = $structuredNumericCells >= 4
            && $structuredNumericRatio >= 0.60
            && $rowSchemaRatio >= 0.75;
        $hardNumericEvidence = $recurringNumericColumns >= 1 || $overwhelmingNumericEvidence;
        $hardTableEvidence = $hardFillEvidence
            || $hardNumericEvidence
            || ($compactHeader && $rowSchemaRatio >= 0.65 && $cueCells === 0 && $sentenceRatio < 0.55);

        $rawTableScore = $this->positionedTableConfidence(
            $rows,
            $columnCount,
            $multiCellRows,
            $recurringColumns
        );
        $tableScore = $rawTableScore;
        if (!$hardTableEvidence) {
            $tableScore -= 0.16;
        }
        $tableScore -= min(0.24, $cueRatio * 1.20);
        if ($sentenceRatio >= 0.50) {
            $tableScore -= 0.08;
        }
        if ($occupancyImbalance >= 0.25) {
            $tableScore -= 0.08;
        }
        $tableScore = round(max(0.0, min(1.0, $tableScore)), 4);

        $columnScore = 0.0;
        $columnScore += $rowCount >= 4 ? 0.12 : 0.08;
        $columnScore += $columnCount >= 2 && $columnCount <= 4 ? 0.08 : 0.02;
        // Incidental digits should not count against a column hypothesis, but
        // neither should they receive the clean no-number bonus. This keeps
        // dense technical pages on their established conservative boundary.
        $columnScore += $numericCells === 0 ? 0.10 : 0.0;
        $columnScore += $filledCells === 0 ? 0.08 : 0.0;
        $columnScore += $cueCells >= 2 ? 0.30 : ($cueCells === 1 ? 0.16 : 0.0);
        $columnScore += $sentenceRatio >= 0.35 ? 0.12 : ($narrativeRatio >= 0.35 ? 0.10 : 0.0);
        $columnScore += $occupancyImbalance >= 0.20 ? 0.08 : 0.0;
        $columnScore += $wrappedRatio >= 0.12 ? 0.08 : 0.0;
        $columnScore += $wideRatio >= 0.55 && $narrativeRatio >= 0.30 ? 0.12 : 0.0;
        $columnScore += $documentCueMatches >= 2 ? 0.06 : 0.0;
        $columnScore += $documentColumnStartCount >= $columnCount ? 0.04 : 0.0;
        if ($hardTableEvidence) {
            $columnScore -= 0.35;
        }
        if ($hardNumericEvidence && $structuredNumericRatio >= 0.20) {
            $columnScore -= 0.20;
        }
        $columnScore = round(max(0.0, min(1.0, $columnScore)), 4);
        $margin = round($columnScore - $tableScore, 4);

        return [
            'page' => $page,
            'bounds' => is_finite($bounds['x1']) ? array_map(static fn (float $value): float => round($value, 2), $bounds) : null,
            'rowCount' => $rowCount,
            'columnCount' => $columnCount,
            'tableScore' => $tableScore,
            'rawTableScore' => $rawTableScore,
            'columnFlowScore' => $columnScore,
            'columnMinusTableMargin' => $margin,
            'selected' => !$hardTableEvidence && $columnScore >= 0.68 && $margin >= 0.12
                ? 'independent-columns'
                : 'table',
            'features' => [
                'populatedCells' => $populatedCells,
                'multiCellRows' => $multiCellRows,
                'recurringColumns' => $recurringColumns,
                'fillRatio' => round($fillRatio, 4),
                'numericRatio' => round($numericRatio, 4),
                'structuredNumericRatio' => round($structuredNumericRatio, 4),
                'structuredNumericCells' => $structuredNumericCells,
                'recurringNumericColumns' => $recurringNumericColumns,
                'recurringNumericCells' => $recurringNumericCells,
                'cueRatio' => round($cueRatio, 4),
                'sentenceRatio' => round($sentenceRatio, 4),
                'narrativeRatio' => round($narrativeRatio, 4),
                'wideCellRatio' => round($wideRatio, 4),
                'wrappedCellRatio' => round($wrappedRatio, 4),
                'columnOccupancyImbalance' => round($occupancyImbalance, 4),
                'rowSchemaRatio' => round($rowSchemaRatio, 4),
                'compactHeader' => $compactHeader,
                'filledCells' => $filledCells,
                'rowDiscriminatingFilledCells' => $rowDiscriminatingFilledCells,
                'hardFillEvidence' => $hardFillEvidence,
                'hardNumericEvidence' => $hardNumericEvidence,
                'hardTableEvidence' => $hardTableEvidence,
                'documentCueMatches' => $documentCueMatches,
                'documentColumnStartCount' => $documentColumnStartCount,
            ],
        ];
    }

    /** @param array<string, mixed> $hypothesis */
    private function recordPositionedLayoutHypothesis(array $hypothesis, string $selected, string $reason): void
    {
        $hypothesis['selected'] = $selected;
        $hypothesis['reason'] = $reason;
        $this->lastGeometryLayoutHypothesis = $hypothesis;
        $this->geometryLayoutHypothesisCount++;
        // Diagnostics must stay bounded on dense technical documents. The
        // total and truncation counters still prove that more candidates were
        // evaluated without retaining page-sized or unbounded metadata.
        if (count($this->geometryLayoutHypotheses) >= 64) {
            $this->geometryLayoutHypothesisTruncatedCount++;

            return;
        }
        $this->geometryLayoutHypotheses[] = $hypothesis;
    }

    /**
     * Side-by-side narrative columns share the visual alignment of a table,
     * but neither column has row-wise data semantics. Prefer editable prose
     * when most cells contain long text in wide columns. This deliberately
     * handles brochure panels with more than two columns as well as ordinary
     * two-column prose.
     *
     * @param list<list<mixed>> $rows
     */
    private function positionedRowsLookLikeNarrativeColumnLayout(array $rows, int $columnCount): bool
    {
        // Brochures can lay out several independent prose panels on one
        // baseline. They may look like a wide table, but long narrative cells
        // and recurring wide prose are the relevant evidence. Do not stop
        // evaluating that evidence merely because the layout has more than
        // six columns.
        if ($columnCount < 2 || $columnCount > 10 || count($rows) < 2) {
            return false;
        }

        $columnPresence = array_fill(0, $columnCount, 0);
        foreach ($rows as $row) {
            for ($index = 0; $index < $columnCount; $index++) {
                if (trim($this->cellTextValue($row[$index] ?? '')) !== '') {
                    $columnPresence[$index]++;
                }
            }
        }
        $minimumPresence = max(2, (int) ceil(count($rows) * 0.20));
        $activeColumns = [];
        foreach ($columnPresence as $index => $presence) {
            if ($presence >= $minimumPresence) {
                $activeColumns[] = $index;
            }
        }
        if (count($activeColumns) < 2 || count($activeColumns) > 10) {
            return false;
        }

        $multiCellRows = 0;
        $narrativeCells = 0;
        $wideCells = 0;
        $populatedCells = 0;
        foreach ($rows as $row) {
            $populated = 0;
            foreach ($activeColumns as $columnIndex) {
                $cell = $row[$columnIndex] ?? '';
                $text = trim($this->cellTextValue($cell));
                if ($text === '') {
                    continue;
                }
                $populated++;
                $populatedCells++;
                if ($this->positionedCellWordCount($text) >= 7 || $this->length($text) >= 48) {
                    $narrativeCells++;
                }
                $width = $this->positionedCellContentWidth($cell);
                if ($width !== null && $width >= 80.0) {
                    $wideCells++;
                }
            }
            if ($populated >= 2) {
                $multiCellRows++;
            }
        }

        if ($multiCellRows < max(2, (int) ceil(count($rows) * 0.50)) || $populatedCells === 0) {
            return false;
        }

        // In a broad panel layout, many perfectly ordinary prose lines are
        // short continuations. Requiring every panel to meet the longer-line
        // threshold misclassifies that layout as a table. The stronger wide
        // cell requirement keeps this limited to genuine side-by-side prose,
        // not a many-column data grid.
        $broadPanelLayout = count($activeColumns) >= 5;
        $requiredNarrativeRatio = $broadPanelLayout ? 0.30 : 0.40;
        $requiredWideCellRatio = $broadPanelLayout ? 0.75 : 0.65;

        return $narrativeCells / $populatedCells >= $requiredNarrativeRatio
            && $wideCells / $populatedCells >= $requiredWideCellRatio;
    }

    /**
     * @param list<list<mixed>> $rows
     */
    private function positionedRowsHavePredominantlyNonHorizontalText(array $rows): bool
    {
        $measuredCells = 0;
        $horizontalCells = 0;
        foreach ($rows as $row) {
            foreach ($row as $cell) {
                if (trim($this->cellTextValue($cell)) === '') {
                    continue;
                }
                $width = $this->positionedCellContentWidth($cell);
                if ($width === null) {
                    continue;
                }
                $measuredCells++;
                if ($width > 1.0) {
                    $horizontalCells++;
                }
            }
        }

        return $measuredCells >= 6 && $horizontalCells / $measuredCells < 0.30;
    }

    /**
     * Map legends can expose rotated or diagonally arranged label fragments
     * as a regular grid. Without readable data values or horizontal words,
     * that geometry is not sufficient evidence of a semantic table.
     *
     * @param list<list<mixed>> $rows
     */
    private function positionedRowsLookLikeCompactLabelGrid(array $rows, int $columnCount): bool
    {
        if ($columnCount < 2 || count($rows) < 2) {
            return false;
        }

        $widths = [];
        $populatedCells = 0;
        foreach ($rows as $row) {
            foreach ($row as $cell) {
                $text = trim($this->cellTextValue($cell));
                if ($text === '') {
                    continue;
                }
                if ($this->positionedCellLooksNumericAnchor($text)
                    || preg_match('/[\pL\pN]{3,}/u', $text) === 1) {
                    return false;
                }
                $populatedCells++;
                $width = $this->positionedCellContentWidth($cell);
                if ($width !== null) {
                    $widths[] = $width;
                }
            }
        }

        return $populatedCells >= 4
            && count($widths) >= 4
            && $this->median($widths) <= 8.0;
    }

    /**
     * @param list<list<mixed>> $rows
     */
    private function positionedRowsLookLikeShortLabelGrid(array $rows, int $columnCount): bool
    {
        if ($columnCount < 2 || count($rows) < 2) {
            return false;
        }

        $populatedCells = 0;
        $shortCells = 0;
        $numericCells = 0;
        $wideCells = 0;
        foreach ($rows as $row) {
            foreach ($row as $cell) {
                $text = trim($this->cellTextValue($cell));
                if ($text === '') {
                    continue;
                }
                $populatedCells++;
                if ($this->positionedCellWordCount($text) <= 2) {
                    $shortCells++;
                }
                if ($this->positionedCellLooksNumericAnchor($text)) {
                    $numericCells++;
                }
                $width = $this->positionedCellContentWidth($cell);
                if ($width !== null && $width >= 80.0) {
                    $wideCells++;
                }
            }
        }

        $rowGap = $this->positionedLogicalRowsMedianGap($rows);

        return $populatedCells >= 4
            && $shortCells / $populatedCells >= 0.70
            && $numericCells / $populatedCells <= 0.30
            && $wideCells / $populatedCells <= 0.10
            && $rowGap !== null
            && $rowGap <= 12.0;
    }

    /**
     * @param list<list<mixed>> $rows
     */
    private function positionedLogicalRowsMedianGap(array $rows): ?float
    {
        $centers = [];
        foreach ($rows as $row) {
            $cellCenters = [];
            foreach ($row as $cell) {
                if (trim($this->cellTextValue($cell)) === '' || !is_array($cell)) {
                    continue;
                }
                $y1 = $this->numericValue($cell['contentY1'] ?? $cell['y1'] ?? null);
                $y2 = $this->numericValue($cell['contentY2'] ?? $cell['y2'] ?? null);
                if ($y1 !== null && $y2 !== null) {
                    $cellCenters[] = ($y1 + $y2) / 2.0;
                }
            }
            if ($cellCenters !== []) {
                $centers[] = $this->median($cellCenters);
            }
        }
        if (count($centers) < 2) {
            return null;
        }

        $gaps = [];
        for ($index = 0, $count = count($centers) - 1; $index < $count; $index++) {
            $gap = abs($centers[$index] - $centers[$index + 1]);
            if ($gap > 0.0) {
                $gaps[] = $gap;
            }
        }

        return $gaps === [] ? null : $this->median($gaps);
    }

    private function positionedCellContentWidth(mixed $cell): ?float
    {
        if (!is_array($cell)) {
            return null;
        }
        $x1 = $this->numericValue($cell['contentX1'] ?? $cell['x1'] ?? null);
        $x2 = $this->numericValue($cell['contentX2'] ?? $cell['x2'] ?? null);

        return $x1 === null || $x2 === null ? null : max(0.0, $x2 - $x1);
    }

    /**
     * A two-row, two-column title and qualifier pair is common in forms and
     * page headers. It is not enough evidence to turn the surrounding page
     * into a data table.
     *
     * @param list<list<mixed>> $rows
     */
    private function positionedRowsLookLikeTitleMetadataGrid(array $rows, int $columnCount): bool
    {
        if ($columnCount !== 2 || count($rows) !== 2) {
            return false;
        }

        $texts = [];
        foreach ($rows as $row) {
            $populated = [];
            foreach ($row as $cell) {
                $text = trim($this->cellTextValue($cell));
                if ($text !== '') {
                    $populated[] = $text;
                }
            }
            if (count($populated) !== 2) {
                return false;
            }
            $texts[] = $populated;
        }

        foreach ([...$texts[0], ...$texts[1]] as $text) {
            if ($this->positionedCellIsNumericValue($text)) {
                return false;
            }
        }

        $firstRowCompact = $this->positionedCellWordCount($texts[0][0]) <= 5
            && $this->positionedCellWordCount($texts[0][1]) <= 5;
        $secondRowHasNarrative = max(
            $this->positionedCellWordCount($texts[1][0]),
            $this->positionedCellWordCount($texts[1][1])
        ) >= 5;

        return $firstRowCompact && $secondRowHasNarrative;
    }

    /**
     * A small three-or-more-column grid needs data values before it is safer
     * to call it a table than to preserve it as a form or visual layout.
     *
     * @param list<list<mixed>> $rows
     */
    private function positionedRowsAreUndersizedNonNumericGrid(array $rows, int $columnCount): bool
    {
        if (count($rows) >= 5 || $columnCount < 3) {
            return false;
        }
        if (count($rows) === 2 && $this->positionedRowsHaveFilledEmptyCell($rows)) {
            return false;
        }

        $numericValues = 0;
        foreach ($rows as $row) {
            foreach ($row as $cell) {
                if ($this->positionedCellIsNumericValue(trim($this->cellTextValue($cell)))) {
                    $numericValues++;
                }
            }
        }

        return $numericValues < 2;
    }

    /**
     * @param list<list<mixed>> $rows
     */
    private function positionedRowsHaveFilledEmptyCell(array $rows): bool
    {
        foreach ($rows as $row) {
            foreach ($row as $cell) {
                if (!is_array($cell) || trim($this->cellTextValue($cell)) !== '') {
                    continue;
                }
                $attributes = is_array($cell['htmlAttributes'] ?? null) ? $cell['htmlAttributes'] : [];
                if (is_string($attributes['data-pdf-fill-color'] ?? null) && $attributes['data-pdf-fill-color'] !== '') {
                    return true;
                }
            }
        }

        return false;
    }

    /**
     * @param list<list<mixed>> $rows
     */
    private function positionedRowsHaveSparsePlaceholderColumns(array $rows, int $columnCount): bool
    {
        if ($columnCount < 12 || $rows === []) {
            return false;
        }

        $populated = 0;
        $placeholders = 0;
        foreach ($rows as $row) {
            foreach ($row as $cell) {
                $text = trim($this->cellTextValue($cell));
                if ($text === '') {
                    continue;
                }

                $populated++;
                if (preg_match('/^[._\x{00B7}\x{2026}\x{2013}\x{2014}-]+$/u', $text) === 1) {
                    $placeholders++;
                }
            }
        }
        if ($populated === 0) {
            return true;
        }

        $fillRatio = $populated / (count($rows) * $columnCount);

        return $fillRatio < 0.50 && $placeholders / $populated >= 0.20;
    }

    /**
     * A short matrix of stacked labels beside prose is usually a printable
     * form layout, not a semantic table. Prefer document text for that
     * ambiguous case unless the first row has an ordinary compact header.
     *
     * @param list<list<mixed>> $rows
     */
    private function positionedRowsLookLikeFormLayout(array $rows, int $columnCount): bool
    {
        $rowCount = count($rows);
        if ($rowCount < 2 || $rowCount > 8 || $columnCount < 3) {
            return false;
        }
        if ($this->positionedRowLooksLikeCompactTableHeader($rows[0] ?? [])) {
            return false;
        }

        $leadingCells = 0;
        $shortLeadingCells = 0;
        $detailRows = 0;
        $numericValueCells = 0;
        $populatedCells = 0;
        foreach ($rows as $row) {
            $firstCell = true;
            $hasDetail = false;
            foreach ($row as $cell) {
                $text = trim($this->cellTextValue($cell));
                if ($text === '') {
                    continue;
                }

                $populatedCells++;
                if ($this->positionedCellIsNumericValue($text)) {
                    $numericValueCells++;
                }
                if ($firstCell) {
                    $leadingCells++;
                    if ($this->positionedCellWordCount($text) <= 4) {
                        $shortLeadingCells++;
                    }
                    $firstCell = false;
                    continue;
                }
                if ($this->positionedCellWordCount($text) >= 8) {
                    $hasDetail = true;
                }
            }
            if ($hasDetail) {
                $detailRows++;
            }
        }

        if ($leadingCells < (int) ceil($rowCount * 0.75) || $populatedCells === 0) {
            return false;
        }

        return $shortLeadingCells / $leadingCells >= 0.60
            && $detailRows >= max(1, (int) ceil($rowCount * 0.35))
            && $numericValueCells / $populatedCells < 0.15;
    }

    /**
     * @param list<mixed> $row
     */
    private function positionedRowLooksLikeCompactTableHeader(array $row): bool
    {
        $compactCells = 0;
        $populatedCells = 0;
        foreach ($row as $cell) {
            $text = trim($this->cellTextValue($cell));
            if ($text === '') {
                continue;
            }

            $populatedCells++;
            if ($this->positionedCellWordCount($text) <= 4) {
                $compactCells++;
            }
        }

        return $populatedCells >= 3 && $compactCells / $populatedCells >= 0.80;
    }

    /**
     * @param list<list<mixed>> $rows
     */
    private function positionedTableConfidence(array $rows, int $columnCount, int $multiCellRows, int $recurringColumns): float
    {
        $rowCount = count($rows);
        if ($rowCount === 0 || $columnCount === 0) {
            return 0.0;
        }

        $populatedCells = 0;
        $numericAnchors = 0;
        $wideCells = 0;
        foreach ($rows as $row) {
            foreach ($row as $cell) {
                $text = trim($this->cellTextValue($cell));
                if ($text === '') {
                    continue;
                }
                $populatedCells++;
                if ($this->positionedCellLooksNumericAnchor($text)) {
                    $numericAnchors++;
                }
                if (is_array($cell)) {
                    $x1 = $this->numericValue($cell['contentX1'] ?? $cell['x1'] ?? null);
                    $x2 = $this->numericValue($cell['contentX2'] ?? $cell['x2'] ?? null);
                    if ($x1 !== null && $x2 !== null && abs($x2 - $x1) > 1.0) {
                        $wideCells++;
                    }
                }
            }
        }

        $totalCells = max(1, $rowCount * $columnCount);
        $fillRatio = $populatedCells / $totalCells;
        $multiCellRowRatio = $multiCellRows / max(1, $rowCount);
        $recurringColumnRatio = $recurringColumns / max(1, $columnCount);
        $numericRatio = $numericAnchors / max(1, $populatedCells);
        $wideCellRatio = $wideCells / max(1, $populatedCells);
        $compactTwoColumnGrid = $rowCount === 2
            && $columnCount === 2
            && $numericAnchors < 2
            && $this->positionedRowsFormCompactTwoColumnGrid($rows);

        $score = 0.0;
        $score += $rowCount >= 3 ? 0.18 : 0.08;
        $score += $columnCount >= 3 ? 0.18 : 0.08;
        $score += 0.20 * min(1.0, $multiCellRowRatio);
        $score += 0.20 * min(1.0, $recurringColumnRatio);
        $score += $fillRatio >= 0.70 ? 0.16 : ($fillRatio >= 0.50 ? 0.08 : 0.0);
        $score += $numericRatio >= 0.20 ? 0.14 : ($numericAnchors >= 2 ? 0.10 : 0.0);
        $score += $wideCellRatio >= 0.75 ? 0.08 : ($wideCellRatio >= 0.50 ? 0.04 : 0.0);

        if ($rowCount <= 2 && $columnCount <= 2 && $numericAnchors < 2) {
            $score = min($score, $compactTwoColumnGrid ? 0.76 : 0.55);
        }
        if ($columnCount === 2 && $rowCount < 4 && $numericAnchors < 2) {
            $score = min($score, $compactTwoColumnGrid ? 0.76 : 0.65);
        }

        return round(min(1.0, $score), 4);
    }

    /**
     * A fully populated 2x2 grid whose rendered cell contents are small
     * compared with its gutter is structural evidence, unlike two prose
     * columns that merely happen to have two lines.
     *
     * @param list<list<mixed>> $rows
     */
    private function positionedRowsFormCompactTwoColumnGrid(array $rows): bool
    {
        if (count($rows) !== 2) {
            return false;
        }

        $leftStarts = [];
        $rightStarts = [];
        $widestCell = 0.0;
        foreach ($rows as $row) {
            $populated = [];
            foreach ($row as $cell) {
                if ($this->cellTextValue($cell) !== '') {
                    $populated[] = $cell;
                }
            }
            if (count($populated) !== 2) {
                return false;
            }

            $left = $populated[0];
            $right = $populated[1];
            if (!is_array($left) || !is_array($right)) {
                return false;
            }
            $leftStart = $this->numericValue($left['contentX1'] ?? $left['x1'] ?? null);
            $rightStart = $this->numericValue($right['contentX1'] ?? $right['x1'] ?? null);
            $leftEnd = $this->numericValue($left['contentX2'] ?? $left['x2'] ?? null);
            $rightEnd = $this->numericValue($right['contentX2'] ?? $right['x2'] ?? null);
            if ($leftStart === null || $rightStart === null || $leftEnd === null || $rightEnd === null || $rightStart <= $leftStart) {
                return false;
            }

            $leftStarts[] = $leftStart;
            $rightStarts[] = $rightStart;
            $widestCell = max($widestCell, $leftEnd - $leftStart, $rightEnd - $rightStart);
        }

        $columnGutter = $this->median($rightStarts) - $this->median($leftStarts);

        return $columnGutter > 0.0 && $widestCell <= $columnGutter * 0.42;
    }

    /**
     * @param list<list<mixed>> $rows
     */
    private function positionedRowsLookLikeSparseProseGrid(array $rows, int $columnCount): bool
    {
        if ($columnCount < 5 || count($rows) < 2) {
            return false;
        }

        $totalCells = 0;
        $populatedCells = 0;
        $shortWordCells = 0;
        $numericCells = 0;
        $numericRows = 0;
        foreach ($rows as $row) {
            $rowNumericCells = 0;
            for ($index = 0; $index < $columnCount; $index++) {
                $totalCells++;
                $text = trim($this->cellTextValue($row[$index] ?? ''));
                if ($text === '') {
                    continue;
                }
                $populatedCells++;
                if ($this->positionedCellLooksNumericAnchor($text)) {
                    $numericCells++;
                    $rowNumericCells++;
                }
                if ($this->positionedCellWordCount($text) <= 2 && !$this->positionedCellLooksNumericAnchor($text)) {
                    $shortWordCells++;
                }
            }
            if ($rowNumericCells >= 2) {
                $numericRows++;
            }
        }

        if ($populatedCells < 4 || $totalCells === 0) {
            return true;
        }

        $emptyRatio = 1.0 - ($populatedCells / $totalCells);
        $shortWordRatio = $shortWordCells / max(1, $populatedCells);
        $numericRatio = $numericCells / max(1, $populatedCells);

        if ($emptyRatio >= 0.35 && $shortWordRatio >= 0.45 && $numericRatio < 0.18 && $numericRows < 2) {
            return true;
        }

        if ($columnCount >= 5 && $shortWordRatio >= 0.65 && $numericRows < 2) {
            return true;
        }

        if ($columnCount >= 4 && $shortWordRatio >= 0.75 && $numericCells === 0) {
            return true;
        }

        return $columnCount >= 8
            && $emptyRatio >= 0.20
            && $numericRatio < 0.12
            && $numericRows < 2;
    }

    private function positionedCellLooksNumericAnchor(string $text): bool
    {
        return preg_match('/(?:[$€£¥]\s*\d|\d[\d,]*(?:\.\d+)?\s*(?:%|[$€£¥])?|\b\d{1,2}[\/.-]\d{1,2}(?:[\/.-]\d{2,4})?\b)/u', $text) === 1;
    }

    /**
     * Strict value evidence for a repeated numeric table column. Unlike the
     * broad anchor above, this deliberately rejects digits embedded in prose,
     * identifiers, line numbers attached to speaker cues, and mixed labels.
     */
    private function positionedCellLooksStructuredNumericValue(string $text): bool
    {
        if ($this->positionedCellIsNumericValue($text)) {
            return true;
        }

        return preg_match(
            '/^\s*(?:\d{4}[\/.-]\d{1,2}[\/.-]\d{1,2}|\d{1,2}[\/.-]\d{1,2}(?:[\/.-]\d{2,4})?)\s*$/u',
            $text
        ) === 1;
    }

    private function positionedCellIsNumericValue(string $text): bool
    {
        return preg_match('/^\s*[-+]?(?:[$€£¥]\s*)?\d+(?:[,\s]\d{3})*(?:[.,]\d+)?\s*(?:[%$€£¥])?\s*$/u', $text) === 1;
    }

    private function positionedCellWordCount(string $text): int
    {
        preg_match_all('/[\pL\pN]+/u', $text, $matches);

        return count($matches[0] ?? []);
    }

    /**
     * @param list<list<mixed>> $rows
     */
    private function positionedRenderedRowsLookLikeFragmentGrid(array $rows): bool
    {
        $columnCount = 0;
        foreach ($rows as $row) {
            $columnCount = max($columnCount, count($row));
        }
        if ($columnCount < 4) {
            return false;
        }

        $wordCounts = [];
        $numericAnchors = 0;
        $oneWordCells = 0;
        foreach ($rows as $row) {
            foreach ($row as $cell) {
                $text = trim($this->cellTextValue($cell));
                if ($text === '') {
                    continue;
                }
                if ($this->positionedCellLooksNumericAnchor($text)) {
                    $numericAnchors++;
                }
                $wordCount = $this->positionedCellWordCount($text);
                if ($wordCount <= 1) {
                    $oneWordCells++;
                }
                $wordCounts[] = $wordCount;
            }
        }
        if (count($wordCounts) < 4) {
            return false;
        }

        sort($wordCounts, SORT_NUMERIC);
        $median = $wordCounts[intdiv(count($wordCounts), 2)] ?? 0;
        if ($numericAnchors > 0 && $columnCount < 18) {
            return false;
        }
        if ($numericAnchors > 0) {
            $oneWordRatio = $oneWordCells / max(1, count($wordCounts));
            $numericRatio = $numericAnchors / max(1, count($wordCounts));
            if ($median <= 1 && $oneWordRatio >= 0.80 && $numericRatio < 0.55) {
                return true;
            }

            return false;
        }

        return $median <= 2;
    }

    /**
     * @param list<list<mixed>> $rows
     */
    private function positionedTableHasHorizontalCellText(array $rows): bool
    {
        $wideCells = 0;
        foreach ($rows as $row) {
            foreach ($row as $cell) {
                if (!is_array($cell) || $this->cellTextValue($cell) === '') {
                    continue;
                }
                $x1 = $this->numericValue($cell['contentX1'] ?? $cell['x1'] ?? null);
                $x2 = $this->numericValue($cell['contentX2'] ?? $cell['x2'] ?? null);
                if ($x1 !== null && $x2 !== null && abs($x2 - $x1) > 1.0) {
                    $wideCells++;
                }
            }
        }

        return $wideCells >= 2;
    }

    /**
     * @param list<list<list<string>>> $tables
     * @param list<string> $limitedLines
     */
    private function positionedTablesLikelyCoverText(array $tables, array $limitedLines): bool
    {
        if ($limitedLines === []) {
            return true;
        }

        $tableText = '';
        foreach ($tables as $table) {
            foreach ($table as $row) {
                $tableText .= ' ' . implode(' ', $row);
            }
        }

        $lineTokens = $this->significantTextTokens(implode(' ', $limitedLines));
        if (count($lineTokens) < 4) {
            return true;
        }

        $tableTokens = $this->significantTextTokenSet($tableText);
        $matched = 0;
        foreach ($lineTokens as $token) {
            if (isset($tableTokens[$token])) {
                $matched++;
            }
        }

        return $matched / count($lineTokens) >= 0.60;
    }

    /**
     * @return list<string>
     */
    private function significantTextTokens(string $text): array
    {
        if (preg_match('//u', $text) !== 1) {
            $scrubbed = @iconv('UTF-8', 'UTF-8//IGNORE', $text);
            $text = is_string($scrubbed) ? $scrubbed : (preg_replace('/[^\x20-\x7E]+/', ' ', $text) ?? $text);
        }

        $normalized = function_exists('mb_strtolower') ? mb_strtolower($text, 'UTF-8') : strtolower($text);
        $tokens = $this->significantTextTokensForPattern(
            $normalized,
            '/[\p{L}\p{N}][\p{L}\p{N}._-]*/u'
        );
        if ($tokens !== null) {
            return $tokens;
        }

        return $this->significantTextTokensForPattern(
            strtolower($text),
            '/[A-Za-z0-9][A-Za-z0-9._-]*/'
        ) ?? [];
    }

    /**
     * @return array<string, true>
     */
    private function significantTextTokenSet(string $text): array
    {
        if (preg_match('//u', $text) !== 1) {
            $scrubbed = @iconv('UTF-8', 'UTF-8//IGNORE', $text);
            $text = is_string($scrubbed) ? $scrubbed : (preg_replace('/[^\x20-\x7E]+/', ' ', $text) ?? $text);
        }

        $normalized = function_exists('mb_strtolower') ? mb_strtolower($text, 'UTF-8') : strtolower($text);
        $tokens = $this->significantTextTokensForPattern(
            $normalized,
            '/[\p{L}\p{N}][\p{L}\p{N}._-]*/u',
            true
        );
        if ($tokens !== null) {
            return $tokens;
        }

        return $this->significantTextTokensForPattern(
            strtolower($text),
            '/[A-Za-z0-9][A-Za-z0-9._-]*/',
            true
        ) ?? [];
    }

    /**
     * @return list<string>|array<string, true>|null Null only when the regular expression fails.
     */
    private function significantTextTokensForPattern(
        string $text,
        string $pattern,
        bool $asSet = false
    ): ?array
    {
        $tokens = [];
        $offset = 0;
        $byteLength = strlen($text);
        while ($offset < $byteLength) {
            $matched = preg_match($pattern, $text, $match, PREG_OFFSET_CAPTURE, $offset);
            if ($matched === false) {
                return null;
            }
            if ($matched === 0) {
                break;
            }

            $token = (string) $match[0][0];
            if (strlen($token) >= 2) {
                if ($asSet) {
                    $tokens[$token] = true;
                } else {
                    $tokens[] = $token;
                }
            }
            $nextOffset = (int) $match[0][1] + strlen($token);
            $offset = $nextOffset > $offset ? $nextOffset : $offset + 1;
        }

        return $tokens;
    }

    private function positionedCellText(string $text): string
    {
        $text = str_replace("\0", '', $text);
        $text = preg_replace('/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/u', ' ', $text) ?? $text;
        $text = preg_replace('/\s+/u', ' ', $text) ?? $text;

        return trim($text);
    }

    private function joinPositionedCellText(
        string $left,
        string $right,
        float $gap,
        float $fontSize,
        bool $leftEndsWithWhitespace = false,
        bool $rightStartsWithWhitespace = false,
        bool $rightHasWordBoundaryBefore = false,
        bool $rightWordBoundaryBefore = false,
        ?string $rightWordBoundarySource = null
    ): string
    {
        $separator = $this->positionedBoundarySeparator(
            $gap,
            $fontSize,
            $leftEndsWithWhitespace,
            $rightStartsWithWhitespace,
            $rightHasWordBoundaryBefore,
            $rightWordBoundaryBefore,
            $rightWordBoundarySource
        );

        return $this->positionedCellText($left . $separator . $right);
    }

    /**
     * Decide one painted run boundary from its local provenance and rendered
     * endpoints. This never consults the text of either fragment: a false
     * text-position continuation can still have a visible word gap, while a
     * producer can mark a touching reset as a line break.
     */
    private function positionedBoundarySeparator(
        float $gap,
        float $fontSize,
        bool $leftEndsWithWhitespace,
        bool $rightStartsWithWhitespace,
        bool $rightHasWordBoundaryBefore,
        bool $rightWordBoundaryBefore,
        ?string $rightWordBoundarySource
    ): string {
        // A literal text-showing whitespace operand is direct evidence and
        // deliberately wins over any coordinate or line-break estimate.
        if ($leftEndsWithWhitespace || $rightStartsWithWhitespace) {
            return ' ';
        }

        $fontSize = max(1.0, $fontSize);
        $substantialGap = $gap > max(0.75, $fontSize * 0.18);
        $touchingOrOverlap = $gap <= max(0.50, $fontSize * 0.08);

        if ($rightHasWordBoundaryBefore) {
            if (!$rightWordBoundaryBefore) {
                // Incomplete font metrics can make the extractor label this
                // transition a continuation. Its rendered endpoints still
                // prove a separator at this one occurrence when a material
                // gap remains.
                return $rightWordBoundarySource === 'text-position-continuation'
                    && $substantialGap
                    ? ' '
                    : '';
            }

            // A real line break normally starts a new word, but some PDF
            // producers reset the line matrix between pieces of one painted
            // word. Touching or overlapping glyph endpoints are stronger
            // local evidence than that bookkeeping boundary.
            if ($rightWordBoundarySource === 'line-break' && $touchingOrOverlap) {
                return '';
            }

            return ' ';
        }

        return $gap > max(1.0, $fontSize * 0.35) ? ' ' : '';
    }

    /**
     * A boundary decision is locally safe to reconcile with source text only
     * when it came from an explicit extractor provenance or a literal text
     * whitespace operand. The decision may be an empty separator: a touching
     * line-matrix reset can prove that a source-space belongs inside one word.
     */
    private function positionedBoundaryHasSourceVerifiedDecision(
        bool $leftEndsWithWhitespace,
        bool $rightStartsWithWhitespace,
        bool $rightHasWordBoundaryBefore,
        ?string $rightWordBoundarySource
    ): bool {
        if ($leftEndsWithWhitespace || $rightStartsWithWhitespace) {
            return true;
        }

        return $rightHasWordBoundaryBefore && in_array(
            $rightWordBoundarySource,
            ['text-position-continuation', 'text-position-layout', 'tj-layout', 'line-break'],
            true
        );
    }

    /**
     * @param array<string, mixed> $left
     * @param array<string, mixed> $right
     * @return array<int, string> Compact-character offset => required separator.
     */
    private function positionedJoinedSourceVerifiedBoundarySeparators(
        array $left,
        array $right,
        float $gap,
        float $fontSize,
        bool $leftEndsWithWhitespace,
        bool $rightStartsWithWhitespace,
        bool $rightHasWordBoundaryBefore,
        bool $rightWordBoundaryBefore,
        ?string $rightWordBoundarySource
    ): array {
        $separators = $this->positionedSourceVerifiedBoundarySeparators($left);
        $leftLength = $this->positionedCompactTextLength((string) ($left['text'] ?? ''));
        if ($this->positionedBoundaryHasSourceVerifiedDecision(
            $leftEndsWithWhitespace,
            $rightStartsWithWhitespace,
            $rightHasWordBoundaryBefore,
            $rightWordBoundarySource
        )) {
            $separators[$leftLength] = $this->positionedBoundarySeparator(
                $gap,
                $fontSize,
                $leftEndsWithWhitespace,
                $rightStartsWithWhitespace,
                $rightHasWordBoundaryBefore,
                $rightWordBoundaryBefore,
                $rightWordBoundarySource
            );
        }
        foreach ($this->positionedSourceVerifiedBoundarySeparators($right) as $offset => $separator) {
            $separators[$leftLength + $offset] = $separator;
        }

        foreach ($separators as $offset => $separator) {
            if ($offset <= 0 || ($separator !== '' && $separator !== ' ')) {
                unset($separators[$offset]);
            }
        }
        ksort($separators, SORT_NUMERIC);

        return $separators;
    }

    /**
     * Carry a narrowly-scoped compact-boundary candidate separately from the
     * normal visual separator. It is not a text decision by itself: later
     * source reconciliation must prove the exact local fragment sequence.
     *
     * @param array<string, mixed> $left
     * @param array<string, mixed> $right
     * @return array<int, true>
     */
    private function positionedJoinedSourceCompactBoundaryOffsets(
        array $left,
        array $right,
        float $gap,
        float $fontSize,
        bool $leftEndsWithWhitespace,
        bool $rightStartsWithWhitespace,
        bool $rightHasWordBoundaryBefore,
        bool $rightWordBoundaryBefore,
        ?string $rightWordBoundarySource
    ): array {
        $offsets = $this->positionedSourceCompactBoundaryOffsets($left);
        $leftLength = $this->positionedCompactTextLength((string) ($left['text'] ?? ''));
        if ($this->positionedBoundaryIsSourceCompactCandidate(
            $left,
            $right,
            $gap,
            $fontSize,
            $leftEndsWithWhitespace,
            $rightStartsWithWhitespace,
            $rightHasWordBoundaryBefore,
            $rightWordBoundaryBefore,
            $rightWordBoundarySource
        )) {
            $offsets[$leftLength] = true;
        }
        foreach ($this->positionedSourceCompactBoundaryOffsets($right) as $offset => $_) {
            $offsets[$leftLength + $offset] = true;
        }

        $totalLength = $leftLength + $this->positionedCompactTextLength((string) ($right['text'] ?? ''));
        foreach ($offsets as $offset => $_) {
            if (!is_int($offset) || $offset <= 0 || $offset >= $totalLength) {
                unset($offsets[$offset]);
            }
        }
        ksort($offsets, SORT_NUMERIC);

        return $offsets;
    }

    /**
     * Retain very wide glyph gaps as code-only candidates. They are not safe
     * prose separators by themselves (display tracking can look identical),
     * but once a sustained monospaced syntax band proves a code listing they
     * restore operator and token spaces without consulting identifier words.
     *
     * @param array<string, mixed> $left
     * @param array<string, mixed> $right
     * @return array<int, true>
     */
    private function positionedJoinedCodeGeometryBoundaryOffsets(
        array $left,
        array $right,
        float $gap,
        float $fontSize
    ): array {
        $offsets = [];
        foreach (($left['codeGeometryBoundaryOffsets'] ?? []) as $offset => $candidate) {
            if (is_int($offset) && $offset > 0 && $candidate === true) {
                $offsets[$offset] = true;
            }
        }
        $leftLength = $this->positionedCompactTextLength((string) ($left['text'] ?? ''));
        if ($gap > max(1.5, max(1.0, $fontSize) * 0.70)) {
            $offsets[$leftLength] = true;
        }
        foreach (($right['codeGeometryBoundaryOffsets'] ?? []) as $offset => $candidate) {
            if (is_int($offset) && $offset > 0 && $candidate === true) {
                $offsets[$leftLength + $offset] = true;
            }
        }

        $totalLength = $leftLength + $this->positionedCompactTextLength((string) ($right['text'] ?? ''));
        foreach ($offsets as $offset => $_) {
            if ($offset <= 0 || $offset >= $totalLength) {
                unset($offsets[$offset]);
            }
        }
        ksort($offsets, SORT_NUMERIC);

        return $offsets;
    }

    /**
     * A close line-matrix reset can be an intra-word split, but only retain
     * that possibility for a short source-order prefix followed by a
     * multi-word continuation. This structural shape excludes two compact
     * independent labels; no spelling or vocabulary is consulted.
     *
     * @param array<string, mixed> $left
     * @param array<string, mixed> $right
     */
    private function positionedBoundaryIsSourceCompactCandidate(
        array $left,
        array $right,
        float $gap,
        float $fontSize,
        bool $leftEndsWithWhitespace,
        bool $rightStartsWithWhitespace,
        bool $rightHasWordBoundaryBefore,
        bool $rightWordBoundaryBefore,
        ?string $rightWordBoundarySource
    ): bool {
        if ($leftEndsWithWhitespace
            || $rightStartsWithWhitespace
            || !$rightHasWordBoundaryBefore
            || !$rightWordBoundaryBefore
            || $rightWordBoundarySource !== 'line-break'
            || $this->positionedBoundarySeparator(
                $gap,
                $fontSize,
                $leftEndsWithWhitespace,
                $rightStartsWithWhitespace,
                $rightHasWordBoundaryBefore,
                $rightWordBoundaryBefore,
                $rightWordBoundarySource
            ) !== ' ') {
            return false;
        }

        $leftLength = $this->positionedCompactTextLength((string) ($left['text'] ?? ''));
        $rightText = trim((string) ($right['text'] ?? ''));
        $rightLength = $this->positionedCompactTextLength($rightText);

        return $leftLength >= 1
            && $leftLength <= 2
            && $rightLength >= 4
            && preg_match('/\S\s+\S/u', $rightText) === 1
            && $gap <= max(1.25, max(1.0, $fontSize) * 0.25);
    }

    /**
     * @param array<string, mixed> $item
     * @return array<int, string>
     */
    private function positionedSourceVerifiedBoundarySeparators(array $item): array
    {
        $separators = [];
        foreach (($item['sourceVerifiedBoundarySeparators'] ?? []) as $offset => $separator) {
            if (is_int($offset)
                && $offset > 0
                && ($separator === '' || $separator === ' ')) {
                $separators[$offset] = $separator;
            }
        }
        ksort($separators, SORT_NUMERIC);

        return $separators;
    }

    /**
     * @param array<string, mixed> $item
     * @return array<int, true>
     */
    private function positionedSourceCompactBoundaryOffsets(array $item): array
    {
        $offsets = [];
        foreach (($item['sourceCompactBoundaryOffsets'] ?? []) as $offset => $candidate) {
            if (is_int($offset) && $offset > 0 && $candidate === true) {
                $offsets[$offset] = true;
            }
        }
        ksort($offsets, SORT_NUMERIC);

        return $offsets;
    }

    private function positionedCompactTextLength(string $text): int
    {
        return $this->length(preg_replace('/\s+/u', '', $text) ?? $text);
    }

    private function lastWordToken(string $text): string
    {
        if (preg_match('/[\p{L}\p{N}]+$/u', rtrim($text), $match) !== 1) {
            return '';
        }

        return $match[0];
    }

    private function firstWordToken(string $text): string
    {
        if (preg_match('/^[^\p{L}\p{N}]*([\p{L}\p{N}]+)/u', ltrim($text), $match) !== 1) {
            return '';
        }

        return $match[1];
    }

    private function appendCellText(string $left, string $right): string
    {
        $left = trim($left);
        $right = trim($right);
        if ($left === '') {
            return $right;
        }
        if ($right === '') {
            return $left;
        }

        return $this->positionedCellText($left . ' ' . $right);
    }

    /**
     * @param list<string> $row
     * @return list<int>
     */
    private function populatedCellIndexes(array $row): array
    {
        $indexes = [];
        foreach ($row as $index => $cell) {
            if ($this->cellTextValue($cell) !== '') {
                $indexes[] = $index;
            }
        }

        return $indexes;
    }

    private function cellTextValue(mixed $cell): string
    {
        if (is_array($cell)) {
            return $this->positionedCellText((string) ($cell['text'] ?? ''));
        }

        return $this->positionedCellText((string) $cell);
    }

    private function numericValue(mixed $value): ?float
    {
        if (is_int($value) || is_float($value)) {
            return (float) $value;
        }
        if (is_string($value) && is_numeric($value)) {
            return (float) $value;
        }

        return null;
    }

    /**
     * Return the exact median font size without retaining one value per run.
     *
     * @param list<array<string, mixed>> $runs
     */
    private function positionedRunsMedianFontSize(array $runs): float
    {
        if ($runs === []) {
            return 0.0;
        }

        $frequencies = [];
        $values = [];
        $count = 0;
        foreach ($runs as $run) {
            $value = max(1.0, (float) ($run['fontSize'] ?? 1.0));
            // 17 significant digits round-trip an IEEE-754 double. Keeping a
            // separate numeric value avoids depending on PHP's numeric-string
            // key coercion when sizes happen to be integral.
            $key = sprintf('%.17g', $value);
            if (!isset($frequencies[$key])) {
                $frequencies[$key] = 0;
                $values[$key] = $value;
            }
            $frequencies[$key]++;
            $count++;
        }

        $keys = array_keys($frequencies);
        usort($keys, static fn (string $left, string $right): int => $values[$left] <=> $values[$right]);
        $leftRank = intdiv($count - 1, 2);
        $rightRank = intdiv($count, 2);
        $seen = 0;
        $leftValue = null;
        foreach ($keys as $key) {
            $next = $seen + $frequencies[$key];
            if ($leftValue === null && $leftRank < $next) {
                $leftValue = $values[$key];
            }
            if ($rightRank < $next) {
                return ((float) $leftValue + $values[$key]) / 2.0;
            }
            $seen = $next;
        }

        return (float) ($leftValue ?? 0.0);
    }

    /**
     * @param list<float> $values
     */
    private function median(array $values): float
    {
        if ($values === []) {
            return 0.0;
        }

        sort($values, SORT_NUMERIC);
        $middle = intdiv(count($values), 2);
        if (count($values) % 2 === 1) {
            return (float) $values[$middle];
        }

        return ((float) $values[$middle - 1] + (float) $values[$middle]) / 2.0;
    }

    private function length(string $text): int
    {
        if (function_exists('mb_strlen')) {
            return mb_strlen($text, 'UTF-8');
        }

        if (preg_match_all('/./us', $text, $matches) === 1) {
            return count($matches[0]);
        }

        return strlen($text);
    }

    /**
     * Select document-global tagged facts for one bounded source-page range.
     *
     * @param list<array<string, mixed>> $structures
     * @return list<array<string, mixed>>
     */
    private function taggedStructuresForPageRange(
        array $structures,
        int $startPage,
        int $endPage
    ): array {
        if ($structures === []) {
            return [];
        }

        return $this->invokePdfTaggedStructureImporter(
            'taggedStructuresForPageRange',
            [$structures, $startPage, $endPage]
        );
    }

    /**
     * @param list<array<string, mixed>> $structureBlocks
     * @param list<string> $limitedLines
     * @return list<AstNode>
     */
    private function blocksFromTaggedStructureBlocks(
        array $structureBlocks,
        array $limitedLines
    ): array {
        if ($structureBlocks === [] || $limitedLines === []) {
            return [];
        }

        return $this->invokePdfTaggedStructureImporter(
            'blocksFromTaggedStructureBlocks',
            [$structureBlocks, $limitedLines]
        );
    }

    /**
     * @param list<array<string, mixed>> $structureBlocks
     * @param list<string> $limitedLines
     * @return array{complete:bool,regions:list<array{block:array<string,mixed>,lines:list<string>,sourceStart:int,sourceEnd:int,pageNumbers:list<int>,role:string}>,groupCount:int,failureReason:?string,failedGroupIndex:?int,candidateCount:?int}
     */
    private function taggedStructureBlockCoverage(
        array $structureBlocks,
        array $limitedLines
    ): array {
        if ($structureBlocks === []) {
            return [
                'complete' => false,
                'regions' => [],
                'groupCount' => 0,
                'failureReason' => null,
                'failedGroupIndex' => null,
                'candidateCount' => null,
            ];
        }

        return $this->invokePdfTaggedStructureImporter(
            'taggedStructureBlockCoverage',
            [$structureBlocks, $limitedLines]
        );
    }

    /**
     * @param array{complete?:bool,regions?:list<array{block:array<string,mixed>,lines:list<string>,sourceStart:int,sourceEnd:int,pageNumbers:list<int>,role:string}>,groupCount?:int,failureReason?:string|null,failedGroupIndex?:int|null,candidateCount?:int|null} $coverage
     * @return list<array{taggedBlocks:list<AstNode>,lines:list<string>,sourceStart:int,sourceEnd:int,pageNumbers:list<int>,role:string}>
     */
    private function partialTaggedRegionsFromCoverage(array $coverage): array
    {
        $rawRegions = is_array($coverage['regions'] ?? null)
            ? $coverage['regions']
            : [];
        if ($rawRegions === []) {
            return [];
        }

        return $this->invokePdfTaggedStructureImporter(
            'partialTaggedRegionsFromCoverage',
            [$coverage]
        );
    }

    /**
     * @param list<AstNode> $blocks
     * @param list<array{taggedBlocks:list<AstNode>,lines:list<string>,sourceStart:int,sourceEnd:int,pageNumbers:list<int>,role:string}> $regions
     * @return array{blocks:list<AstNode>,diagnostics:list<array<string,mixed>>,complete:bool,appliedCount:int}
     */
    private function blocksWithTaggedRegionArbitration(
        array $blocks,
        array $regions
    ): array {
        if ($regions === []) {
            return [
                'blocks' => $blocks,
                'diagnostics' => [],
                'complete' => true,
                'appliedCount' => 0,
            ];
        }

        return $this->invokePdfTaggedStructureImporter(
            'blocksWithTaggedRegionArbitration',
            [$blocks, $regions]
        );
    }

    /**
     * @param list<array<string, mixed>> $tables
     * @param list<string> $limitedLines
     * @return list<AstNode>
     */
    private function blocksFromTaggedTables(
        array $tables,
        array $limitedLines
    ): array {
        if ($tables === []) {
            return [];
        }

        return $this->invokePdfTaggedStructureImporter(
            'blocksFromTaggedTables',
            [$tables, $limitedLines]
        );
    }

    /**
     * @param array<string, mixed> $table
     * @return list<list<array<string, mixed>>>
     */
    private function taggedTableRows(array $table): array
    {
        return PdfTaggedStructureImporter::tableRows($table);
    }

    /**
     * @param array<string, mixed> $table
     * @return list<array<string, mixed>>
     */
    private function taggedTableSections(array $table): array
    {
        return PdfTaggedStructureImporter::tableSections($table);
    }

    /**
     * @param list<array<string, mixed>> $items
     * @param list<string> $limitedLines
     * @return list<AstNode>
     */
    private function blocksFromTaggedStructureItems(
        array $items,
        array $limitedLines
    ): array {
        if ($items === []) {
            return [];
        }

        return $this->invokePdfTaggedStructureImporter(
            'blocksFromTaggedStructureItems',
            [$items, $limitedLines]
        );
    }

    /**
     * @param list<mixed> $arguments
     */
    private function invokePdfTaggedStructureImporter(
        string $method,
        array $arguments
    ): mixed {
        return PdfTaggedStructureImporter::invoke(
            $method,
            $arguments,
            $this->blocksFromLines(...),
            $this->tableFromTaggedTable(...),
            $this->paragraph(...),
            $this->inlines(...),
            $this->pdfAstNodeVisibleText(...),
            $this->pdfComparableLineText(...),
            $this->taggedTableCellText(...),
            $this->taggedStructureItemRole(...),
            $this->taggedAstAttrs(...)
        );
    }

    /**
     * @param array<string, mixed> $cell
     */
    private function taggedTableCellText(array $cell): string
    {
        $text = $cell['text'] ?? '';
        if (!is_string($text)) {
            return '';
        }

        $text = str_replace("\0", '', $text);
        $text = preg_replace('/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/u', ' ', $text) ?? $text;

        return trim(preg_replace('/\s+/u', ' ', $text) ?? $text);
    }

    /**
     * @param array<string, mixed> $item
     */
    private function taggedStructureItemRole(array $item): string
    {
        foreach (['resolvedRole', 'role'] as $key) {
            $role = $item[$key] ?? '';
            if (is_string($role) && $role !== '') {
                return strtoupper($role);
            }
        }

        return '';
    }

    /**
     * @param array<string, mixed> $item
     * @return array<string, mixed>
     */
    private function taggedAstAttrs(array $item): array
    {
        $classes = [];
        foreach ($this->taggedClassNames($item) as $className) {
            $classToken = $this->taggedHtmlToken($className);
            if ($classToken !== '') {
                $classes[] = 'pdf-class-' . $classToken;
            }
        }
        $classes = array_values(array_unique($classes));

        $attributes = [];
        $language = $item['language'] ?? null;
        if (is_string($language) && $this->isSafeLanguageTag($language)) {
            $attributes['lang'] = $language;
        }

        foreach (['role' => 'data-pdf-role', 'resolvedRole' => 'data-pdf-resolved-role'] as $itemKey => $attrName) {
            $value = $item[$itemKey] ?? null;
            if (is_string($value) && trim($value) !== '') {
                $attributes[$attrName] = trim($value);
            }
        }

        $objectNumber = $item['objectNumber'] ?? null;
        if (is_int($objectNumber) || is_float($objectNumber) || (is_string($objectNumber) && ctype_digit($objectNumber))) {
            $attributes['data-pdf-struct-object'] = (string) (int) $objectNumber;
        }

        $identifier = $item['id'] ?? null;
        if (is_string($identifier) && trim($identifier) !== '') {
            $attributes['data-pdf-struct-id'] = trim($identifier);
        }

        $classNames = $this->taggedClassNames($item);
        if ($classNames !== []) {
            $attributes['data-pdf-classes'] = implode(' ', $classNames);
        }

        foreach ($this->taggedAttributeDictionaries($item) as $attributeDictionary) {
            $owner = $this->taggedHtmlToken((string) ($attributeDictionary['O'] ?? 'attribute'));
            if ($owner === '') {
                $owner = 'attribute';
            }
            foreach ($attributeDictionary as $key => $value) {
                if ($key === 'O') {
                    continue;
                }
                $name = $this->taggedHtmlToken((string) $key);
                $htmlValue = $this->taggedAttributeHtmlValue($value);
                if ($name === '' || $htmlValue === '') {
                    continue;
                }
                $htmlName = 'data-pdf-' . $owner . '-' . $name;
                if (isset($attributes[$htmlName]) && $attributes[$htmlName] !== $htmlValue) {
                    $attributes[$htmlName] .= ' ' . $htmlValue;
                } else {
                    $attributes[$htmlName] = $htmlValue;
                }
            }
        }

        $attrs = [];
        if ($classes !== []) {
            $attrs['classes'] = $classes;
        }
        if ($attributes !== []) {
            $attrs['attributes'] = $attributes;
        }

        $htmlAttributes = $attributes;
        if ($classes !== []) {
            $htmlAttributes['class'] = implode(' ', $classes);
        }
        if ($htmlAttributes !== []) {
            $attrs['htmlAttributes'] = $htmlAttributes;
        }

        return $attrs;
    }

    /**
     * @param array<string, mixed> $item
     * @return list<string>
     */
    private function taggedClassNames(array $item): array
    {
        $classes = $item['classes'] ?? [];
        if (!is_array($classes)) {
            return [];
        }

        $normalized = [];
        foreach ($classes as $className) {
            if (!is_scalar($className)) {
                continue;
            }
            $className = trim((string) $className);
            if ($className !== '') {
                $normalized[] = $className;
            }
        }

        return array_values(array_unique($normalized));
    }

    /**
     * @param array<string, mixed> $item
     * @return list<array<string, mixed>>
     */
    private function taggedAttributeDictionaries(array $item): array
    {
        $attributes = $item['attributes'] ?? [];
        if (!is_array($attributes)) {
            return [];
        }

        $dictionaries = [];
        foreach ($attributes as $attributeDictionary) {
            if (is_array($attributeDictionary)) {
                $dictionaries[] = $attributeDictionary;
            }
        }

        return $dictionaries;
    }

    private function taggedHtmlToken(string $value): string
    {
        $value = preg_replace('/([a-z])([A-Z])/', '$1-$2', $value) ?? $value;
        $value = strtolower(trim($value));
        $value = preg_replace('/[^a-z0-9_.:-]+/', '-', $value) ?? $value;
        $value = trim($value, '-');

        return $value;
    }

    private function isSafeLanguageTag(string $language): bool
    {
        return preg_match('/^[A-Za-z]{2,8}(?:-[A-Za-z0-9]{1,8})*$/', $language) === 1;
    }

    private function taggedAttributeHtmlValue(mixed $value): string
    {
        if (is_bool($value)) {
            return $value ? 'true' : 'false';
        }
        if (is_int($value) || is_float($value) || is_string($value)) {
            return trim((string) $value);
        }
        if (!is_array($value)) {
            return '';
        }

        $parts = [];
        foreach ($value as $item) {
            if (is_bool($item)) {
                $parts[] = $item ? 'true' : 'false';
                continue;
            }
            if (is_int($item) || is_float($item) || is_string($item)) {
                $part = trim((string) $item);
                if ($part !== '') {
                    $parts[] = $part;
                }
            }
        }

        return implode(' ', $parts);
    }

    /**
     * @param list<string> $lines
     * @return array{rows: list<list<string>>, consumed: int}
     */
    private function tableRowsAt(array $lines, int $start): array
    {
        $rows = [];
        $columnCount = null;
        $consumed = 0;
        for ($index = $start, $count = count($lines); $index < $count; $index++) {
            $cells = $this->tableCells($lines[$index]);
            if ($cells === null) {
                break;
            }
            if ($this->isTableSeparatorRow($cells)) {
                $consumed++;
                continue;
            }
            $rowColumnCount = count($cells);
            if ($columnCount === null) {
                $columnCount = $rowColumnCount;
            } elseif ($rowColumnCount !== $columnCount) {
                break;
            }
            $rows[] = $cells;
            $consumed++;
        }

        if (count($rows) < 2 || $this->tableRowsLookLikeFragmentedLabelGrid($rows)) {
            return ['rows' => [], 'consumed' => 0];
        }

        return ['rows' => $rows, 'consumed' => $consumed];
    }

    /**
     * Detects tables whose cells were extracted as one line per visual cell.
     *
     * @param list<string> $lines
     * @return array{rows: list<list<string>>, consumed: int}
     */
    private function stackedTableRowsAt(array $lines, int $start): array
    {
        $lineCount = count($lines);
        foreach ([3, 4, 5] as $columnCount) {
            if ($start + ($columnCount * 4) > $lineCount) {
                continue;
            }
            $header = [];
            for ($offset = 0; $offset < $columnCount; $offset++) {
                $headerLine = trim($lines[$start + $offset] ?? '');
                if (!$this->stackedTableHeaderCell($headerLine)) {
                    $header = [];
                    break;
                }
                $header[] = $headerLine;
            }
            if ($header === []) {
                continue;
            }

            $rows = [$header];
            $index = $start + $columnCount;
            while ($index + $columnCount - 1 < $lineCount && $this->stackedTableRowKeyCell((string) ($lines[$index] ?? ''))) {
                $row = [];
                for ($column = 0; $column < $columnCount; $column++) {
                    $cell = trim((string) ($lines[$index + $column] ?? ''));
                    if ($cell === '' || ($column > 0 && !$this->stackedTableBodyCell($cell))) {
                        break 2;
                    }
                    $row[] = $cell;
                }
                $index += $columnCount;

                $continuations = 0;
                while (
                    $index < $lineCount
                    && !$this->stackedTableRowKeyCell((string) ($lines[$index] ?? ''))
                    && $this->stackedTableContinuationCell((string) ($lines[$index] ?? ''))
                ) {
                    $row[$columnCount - 1] .= ' ' . trim((string) $lines[$index]);
                    $index++;
                    $continuations++;
                    if ($continuations >= 2) {
                        break;
                    }
                }

                $rows[] = $row;
            }

            if (count($rows) >= 4) {
                if (!$this->stackedTableRowsLookLikeDataGrid($rows, $columnCount)
                    || $this->tableRowsLookLikeFragmentedLabelGrid($rows)) {
                    continue;
                }

                return ['rows' => $rows, 'consumed' => $index - $start];
            }
        }

        return ['rows' => [], 'consumed' => 0];
    }

    /**
     * Stacked grids are prone to false positives when diagram labels and
     * single-glyph markers survive as a regular sequence. Require each grid
     * to carry repeated textual values or substantial numeric values; a run of
     * isolated one-digit markers is preserved as prose instead.
     *
     * @param list<list<string>> $rows
     */
    private function stackedTableRowsLookLikeDataGrid(array $rows, int $columnCount): bool
    {
        $bodyCells = 0;
        $numericCells = 0;
        $semanticRows = 0;
        foreach (array_slice($rows, 1) as $row) {
            $rowHasSemanticValue = false;
            foreach ($row as $cell) {
                $text = trim($cell);
                if ($text === '') {
                    continue;
                }
                $bodyCells++;
                if ($this->positionedCellIsNumericValue($text)) {
                    $numericCells++;
                }
                if (preg_match('/\p{L}{3,}/u', $text) === 1
                    || preg_match('/(?:[$€£¥]|\d[\d,]*\.\d+|\d{2,})/u', $text) === 1) {
                    $rowHasSemanticValue = true;
                }
            }
            if ($rowHasSemanticValue) {
                $semanticRows++;
            }
        }

        $bodyRows = max(1, count($rows) - 1);
        if ($semanticRows >= (int) ceil($bodyRows * 0.50)) {
            return true;
        }

        return $columnCount > 3
            && $numericCells >= max(3, (int) ceil($bodyCells * 0.20));
    }

    /**
     * A columnar text stream such as "T / r / ace" is a split label, not
     * three data cells. This occurs in vector diagrams where each word is
     * painted in separate fragments. It is intentionally rejected before the
     * generic stacked-table parser can promote the diagram to a data table.
     *
     * @param list<list<string>> $rows
     */
    private function tableRowsLookLikeFragmentedLabelGrid(array $rows): bool
    {
        if (count($rows) < 2 || count($rows[0] ?? []) < 3) {
            return false;
        }

        $fragmentedRows = 0;
        $repeatedFragmentPairs = [];
        $shiftedFragmentPairs = [];
        foreach ($rows as $rowIndex => $row) {
            $fragments = 0;
            $rowPairs = [];
            $rowPairColumns = [];
            $rowHasNumericValue = false;
            foreach ($row as $cell) {
                if ($this->positionedCellIsNumericValue((string) $cell)) {
                    $rowHasNumericValue = true;
                    break;
                }
            }
            for ($index = 0, $limit = count($row) - 1; $index < $limit; $index++) {
                $left = $this->lastWordToken((string) $row[$index]);
                $right = $this->firstWordToken((string) $row[$index + 1]);
                if (preg_match('/^\p{L}{1,2}$/u', $left) !== 1
                    || preg_match('/^\p{Ll}{1,8}$/u', $right) !== 1) {
                    continue;
                }
                $fragments++;
                if ($rowIndex > 0 && !$rowHasNumericValue) {
                    $pair = $this->pdfLowercaseToken($left) . "\0" . $this->pdfLowercaseToken($right);
                    $rowPairColumns[$pair][$index] = true;
                }
                if ($rowIndex > 0
                    && !$rowHasNumericValue
                    && trim((string) $row[$index]) === $left
                    && trim((string) $row[$index + 1]) === $right
                    && preg_match('/^\p{L}$/u', $left) === 1
                    && preg_match('/^\p{Ll}{3,8}$/u', $right) === 1
                    && $this->length($left . $right) >= 4) {
                    $rowPairs[$pair] = true;
                }
            }
            if ($fragments >= 2) {
                $fragmentedRows++;
            }
            foreach (array_keys($rowPairs) as $pair) {
                $repeatedFragmentPairs[$pair] = ($repeatedFragmentPairs[$pair] ?? 0) + 1;
            }
            foreach ($rowPairColumns as $pair => $columns) {
                $shiftedFragmentPairs[$pair] ??= ['rows' => 0, 'columns' => []];
                $shiftedFragmentPairs[$pair]['rows']++;
                foreach (array_keys($columns) as $column) {
                    $shiftedFragmentPairs[$pair]['columns'][$column] = true;
                }
            }
        }

        if ($fragmentedRows >= 2 && $fragmentedRows / count($rows) >= 0.50) {
            return true;
        }

        $bodyRows = count($rows) - 1;
        foreach ($repeatedFragmentPairs as $count) {
            if ($count >= 3 && $count / $bodyRows >= 0.50) {
                return true;
            }
        }
        foreach ($shiftedFragmentPairs as $evidence) {
            if ($evidence['rows'] >= 3
                && $evidence['rows'] / $bodyRows >= 0.50
                && count($evidence['columns']) >= 2) {
                return true;
            }
        }

        return false;
    }

    private function stackedTableHeaderCell(string $line): bool
    {
        $line = trim($line);
        if ($line === '' || $this->listItem($line) !== null || $this->length($line) > 40) {
            return false;
        }
        if (preg_match('/[.!?]\s*$/u', $line) === 1 || preg_match('/^\d+$/u', $line) === 1) {
            return false;
        }

        return preg_match('/\p{L}/u', $line) === 1;
    }

    private function stackedTableRowKeyCell(string $line): bool
    {
        $line = trim($line);
        if ($line === '' || str_contains($line, ' ') || $this->length($line) > 10) {
            return false;
        }
        if (preg_match('/[.!?,:;]$/u', $line) === 1) {
            return false;
        }

        return preg_match('/\d/u', $line) === 1 || preg_match('/^[\p{Lu}]{1,4}$/u', $line) === 1;
    }

    private function stackedTableBodyCell(string $line): bool
    {
        $line = trim($line);
        if ($line === '' || $this->listItem($line) !== null || $this->length($line) > 120) {
            return false;
        }

        return preg_match('/[.!?]\s*$/u', $line) !== 1;
    }

    private function stackedTableContinuationCell(string $line): bool
    {
        $line = trim($line);
        if ($line === '' || $this->listItem($line) !== null || $this->length($line) > 50) {
            return false;
        }
        if (preg_match('/[.!?]\s*$/u', $line) === 1) {
            return false;
        }
        $tokens = preg_split('/\s+/u', $line) ?: [];

        return count($tokens) <= 4;
    }

    /**
     * @param list<string> $lines
     * @return list<AstNode>
     */
    private function blocksFromCurrencyRecordLines(array $lines): array
    {
        $rows = [];
        $recordRows = 0;
        $pending = [];
        foreach ($lines as $line) {
            $line = trim(preg_replace('/\s+/u', ' ', $line) ?? $line);
            if ($line === '') {
                continue;
            }

            $totalRow = $this->currencyRecordTotalRow($line);
            if ($totalRow !== null) {
                $rows[] = $totalRow;
                $pending = [];
                continue;
            }

            $amountOnlyRow = $this->currencyRecordAmountOnlyRow($line);
            if ($amountOnlyRow !== null) {
                $rows[] = $amountOnlyRow;
                $pending = [];
                continue;
            }

            $pending[] = $line;
            $candidate = implode(' ', $pending);
            $recordRow = $this->currencyRecordDataRow($candidate);
            if ($recordRow === null) {
                if (count($pending) > 5 || strlen($candidate) > 260) {
                    $pending = [];
                }
                continue;
            }

            $rows[] = $recordRow;
            $recordRows++;
            $pending = [];
        }

        if ($recordRows < 4 || count($rows) < 6) {
            return [];
        }

        array_unshift($rows, ['Name', 'Location', 'Category', 'Amount']);

        return [$this->table($rows)];
    }

    /**
     * @return list<string>|null
     */
    private function currencyRecordDataRow(string $line): ?array
    {
        if (preg_match('/^(?<beforeAmount>.+?)\s*(?<amount>[$€£¥]\s*\d[\d,]*(?:\.\d{2})?)$/u', $line, $amountMatch) !== 1) {
            return null;
        }

        $beforeAmount = trim($amountMatch['beforeAmount']);
        if (preg_match('/^(?<beforeCategory>.+,\s*[A-Z]{2})(?<category>[A-Z][A-Z &\/-]*)$/u', $beforeAmount, $categoryMatch) !== 1) {
            return null;
        }

        $nameAndLocation = $this->splitCurrencyRecordNameAndLocation(trim($categoryMatch['beforeCategory']));
        if ($nameAndLocation === null) {
            return null;
        }
        [$name, $location] = $nameAndLocation;
        $category = trim($categoryMatch['category']);
        $amount = trim($amountMatch['amount']);
        if ($name === '' || $location === '' || $category === '' || $amount === '' || preg_match('/[A-Z]{3,}/', $category) !== 1) {
            return null;
        }

        return [
            $this->repairCurrencyRecordName($name),
            $this->repairCurrencyRecordLocation($location),
            $this->positionedCellText($category),
            preg_replace('/\s+/', '', $amount) ?? $amount,
        ];
    }

    /**
     * @return array{0: string, 1: string}|null
     */
    private function splitCurrencyRecordNameAndLocation(string $text): ?array
    {
        if (preg_match('/^(?<prefix>.+),\s*(?<state>[A-Z]{2})$/u', $text, $stateMatch) !== 1) {
            return null;
        }

        $prefix = trim($stateMatch['prefix']);
        $state = $stateMatch['state'];
        $tokens = preg_split('/\s+/u', $prefix) ?: [];
        if (count($tokens) < 3) {
            return null;
        }

        $best = null;
        $bestScore = -INF;
        $tokenCount = count($tokens);
        for ($split = 1; $split < $tokenCount; $split++) {
            $name = trim(implode(' ', array_slice($tokens, 0, $split)));
            $cityTokens = array_slice($tokens, $split);
            $city = trim(implode(' ', $cityTokens));
            if ($name === '' || $city === '' || !str_contains($name, ',') || preg_match('/^[A-Z]{2,}/u', $cityTokens[0] ?? '') !== 1) {
                continue;
            }

            $score = $this->currencyRecordNameLocationSplitScore($name, $cityTokens);
            if ($score > $bestScore) {
                $bestScore = $score;
                $best = [$name, $city . ', ' . $state];
            }
        }

        return $bestScore > 0 && $best !== null ? $best : null;
    }

    /**
     * @param list<string> $cityTokens
     */
    private function currencyRecordNameLocationSplitScore(string $name, array $cityTokens): int
    {
        $score = 0;
        $commaCount = substr_count($name, ',');
        $score += $commaCount >= 2 ? 4 : 2;

        $afterLastComma = trim(substr($name, strrpos($name, ',') + 1));
        $afterCommaTokens = $afterLastComma === '' ? [] : (preg_split('/\s+/u', $afterLastComma) ?: []);
        $afterCommaCount = count($afterCommaTokens);
        if ($afterCommaCount === 1) {
            $score += 3;
        } elseif ($afterCommaCount === 2) {
            $score += 2;
        } elseif ($afterCommaCount > 3) {
            $score -= 3;
        }

        if ($commaCount >= 2 && $afterCommaCount > 0 && preg_match('/^[A-Z]$/', $afterCommaTokens[0]) === 1) {
            $score += 2;
        }

        $cityTokenCount = count($cityTokens);
        if ($cityTokenCount === 2) {
            $score += 2;
        } elseif ($cityTokenCount === 3) {
            $score += 1;
        } elseif ($cityTokenCount > 4) {
            $score -= 6;
        }

        $city = implode(' ', $cityTokens);
        if (str_contains($city, '&') || preg_match('/\b(?:MEDICINE|PULMONARY|REGIONAL|SLEEP|CENTER|ASSOCIATES|GROUP)\b/u', $city) === 1) {
            $score -= 4;
        }

        return $score;
    }

    /**
     * @return list<string>|null
     */
    private function currencyRecordTotalRow(string $line): ?array
    {
        if (preg_match('/^TOTAL\s+(?<amount>[$€£¥]\s*\d[\d,]*(?:\.\d{2})?)$/u', $line, $match) !== 1) {
            return null;
        }

        return ['TOTAL', '', '', preg_replace('/\s+/', '', trim($match['amount'])) ?? trim($match['amount'])];
    }

    /**
     * @return list<string>|null
     */
    private function currencyRecordAmountOnlyRow(string $line): ?array
    {
        if (preg_match('/^(?<amount>[$€£¥]\s*\d[\d,]*(?:\.\d{2})?)$/u', $line, $match) !== 1) {
            return null;
        }

        return ['TOTAL', '', '', preg_replace('/\s+/', '', trim($match['amount'])) ?? trim($match['amount'])];
    }

    private function repairCurrencyRecordName(string $name): string
    {
        return $this->positionedCellText(preg_replace('/\s*,\s*/u', ', ', $name) ?? $name);
    }

    private function repairCurrencyRecordLocation(string $location): string
    {
        return $this->positionedCellText(preg_replace('/\s*,\s*/u', ', ', $location) ?? $location);
    }

    /**
     * @return list<string>|null
     */
    private function tableCells(string $line): ?array
    {
        if (str_contains($line, '|')) {
            $cells = array_map('trim', explode('|', trim($line)));
            if (($cells[0] ?? '') === '') {
                array_shift($cells);
            }
            if (($cells[array_key_last($cells)] ?? '') === '') {
                array_pop($cells);
            }
        } elseif (str_contains($line, "\t")) {
            $cells = preg_split('/\t+/u', $line) ?: [];
            $cells = array_map('trim', $cells);
        } elseif (preg_match('/ {2,}/u', $line) === 1) {
            $cells = preg_split('/ {2,}/u', $line) ?: [];
            $cells = array_map('trim', $cells);
        } else {
            return null;
        }

        $cells = array_values(array_filter($cells, static fn (string $cell): bool => $cell !== ''));

        return count($cells) >= 2 ? $cells : null;
    }

    /**
     * @param list<string> $cells
     */
    private function isTableSeparatorRow(array $cells): bool
    {
        foreach ($cells as $cell) {
            if (preg_match('/^:?-{2,}:?$/', $cell) !== 1) {
                return false;
            }
        }

        return true;
    }

    /**
     * @param list<list<mixed>> $rows
     */
    private function table(array $rows, array $attrs = []): AstNode
    {
        $header = array_shift($rows) ?? [];

        return new AstNode('table', $attrs, [
            new AstNode('table_head', [], [new AstNode('table_row', [], array_map(fn (mixed $cell): AstNode => $this->tableCellFromValue($cell), $header))]),
            new AstNode('table_body', [], array_map(fn (array $row): AstNode => new AstNode('table_row', [], array_map(fn (mixed $cell): AstNode => $this->tableCellFromValue($cell), $row)), $rows)),
        ]);
    }

    /**
     * @param array<string, mixed> $table
     */
    private function tableFromTaggedTable(array $table, array $attrs = []): AstNode
    {
        $sections = $this->taggedTableSections($table);
        if ($sections === []) {
            $rows = $this->taggedTableRows($table);
            if (is_array($table['rangeSelection'] ?? null)
                && isset($rows[0])
                && !$this->taggedTableRowHasHeaderCell($rows[0])
            ) {
                return new AstNode('table', $attrs, [
                    new AstNode('table_body', [], array_map(
                        fn (array $row): AstNode => new AstNode(
                            'table_row',
                            [],
                            array_map(fn (mixed $cell): AstNode => $this->tableCellFromValue($cell), $row)
                        ),
                        $rows
                    )),
                ]);
            }

            return $this->table($rows, $attrs);
        }

        $headRows = [];
        $headAttrs = [];
        $bodyNodes = [];
        $footRows = [];
        $footAttrs = [];

        foreach ($sections as $section) {
            $rows = $this->taggedTableRows($section);
            if ($rows === []) {
                continue;
            }

            $rowNodes = array_map(
                fn (array $row): AstNode => new AstNode('table_row', [], array_map(fn (mixed $cell): AstNode => $this->tableCellFromValue($cell), $row)),
                $rows
            );
            $role = strtoupper($this->taggedStructureItemRole($section));
            if ($role === 'THEAD') {
                if ($headRows === []) {
                    $headAttrs = $this->taggedAstAttrs($section);
                }
                foreach ($rowNodes as $rowNode) {
                    $headRows[] = $rowNode;
                }
                continue;
            }
            if ($role === 'TFOOT') {
                if ($footRows === []) {
                    $footAttrs = $this->taggedAstAttrs($section);
                }
                foreach ($rowNodes as $rowNode) {
                    $footRows[] = $rowNode;
                }
                continue;
            }

            $bodyNodes[] = new AstNode('table_body', $this->taggedAstAttrs($section), $rowNodes);
        }

        $children = [];
        if ($headRows !== []) {
            $children[] = new AstNode('table_head', $headAttrs, $headRows);
        }
        foreach ($bodyNodes as $bodyNode) {
            $children[] = $bodyNode;
        }
        if ($footRows !== []) {
            $children[] = new AstNode('table_foot', $footAttrs, $footRows);
        }

        return $children === [] ? $this->table($this->taggedTableRows($table), $attrs) : new AstNode('table', $attrs, $children);
    }

    /** @param list<array<string, mixed>> $row */
    private function taggedTableRowHasHeaderCell(array $row): bool
    {
        foreach ($row as $cell) {
            if (strtoupper($this->taggedStructureItemRole($cell)) === 'TH') {
                return true;
            }
        }

        return false;
    }

    private function tableCellFromValue(mixed $cell): AstNode
    {
        if (is_array($cell)) {
            $attrs = $this->taggedAstAttrs($cell);
            $attrs = array_replace($attrs, $this->positionedTableCellInternalSourceAttrs($cell));
            foreach (['classes', 'attributes', 'htmlAttributes'] as $attrKey) {
                if (isset($cell[$attrKey]) && is_array($cell[$attrKey])) {
                    $attrs[$attrKey] = array_replace(is_array($attrs[$attrKey] ?? null) ? $attrs[$attrKey] : [], $cell[$attrKey]);
                }
            }
            if (strtoupper($this->taggedStructureItemRole($cell)) === 'TH') {
                $attrs['header'] = true;
                $headerId = $this->taggedTableHeaderHtmlId($cell['id'] ?? null);
                if ($headerId !== '') {
                    $attrs = $this->withTableCellHtmlAttribute($attrs, 'id', $headerId);
                }
                $scope = $this->taggedTableHeaderScope($cell);
                if ($scope !== '') {
                    $attrs = $this->withTableCellHtmlAttribute($attrs, 'scope', $scope);
                }
            }
            $headers = $this->taggedTableHeadersAttribute($cell);
            if ($headers !== '') {
                $attrs = $this->withTableCellHtmlAttribute($attrs, 'headers', $headers);
            }

            return $this->tableCell(
                $this->taggedTableCellText($cell),
                $this->positiveSpan($cell['rowSpan'] ?? 1),
                $this->positiveSpan($cell['colSpan'] ?? 1),
                $attrs
            );
        }

        return $this->tableCell((string) $cell);
    }

    /**
     * Keep occurrence geometry available to internal reconciliation without
     * exposing it through the table cell's HTML attribute dictionaries.
     *
     * @param array<string, mixed> $cell
     * @return array<string, mixed>
     */
    private function positionedTableCellInternalSourceAttrs(array $cell): array
    {
        $exactSourceRanges = $this->positionedTableExactSourceRangesForItems([$cell]);
        if ($exactSourceRanges === null || $exactSourceRanges === []) {
            return [];
        }

        $attrs = ['sourcePdfExactSourceRanges' => $exactSourceRanges];
        if (is_numeric($cell['page'] ?? null) && (int) $cell['page'] > 0) {
            $attrs['sourcePdfGeometryPage'] = (int) $cell['page'];
        }
        $sourceStreams = $this->positionedTableSourceStreamsForItems([$cell]);
        if ($sourceStreams !== null && $sourceStreams !== []) {
            $attrs['sourcePdfGeometryStreams'] = $sourceStreams;
        }
        $sourceOrder = $this->positionedTableSourceOrderBoundsForItems([$cell]);
        if ($sourceOrder !== null) {
            $attrs['sourcePdfSourceOrderStart'] = $sourceOrder['start'];
            $attrs['sourcePdfSourceOrderEnd'] = $sourceOrder['end'];
        }

        $bounds = [];
        foreach (['x1', 'y1', 'x2', 'y2'] as $key) {
            $value = $this->numericValue($cell[$key] ?? null);
            if ($value === null || !is_finite($value)) {
                $bounds = [];
                break;
            }
            $bounds[$key] = $value;
        }
        if ($bounds !== []
            && $bounds['x2'] >= $bounds['x1']
            && $bounds['y2'] >= $bounds['y1']) {
            $attrs['sourcePdfGeometryBounds'] = $bounds;
        }
        $fontSize = $this->numericValue($cell['fontSize'] ?? null);
        if ($fontSize !== null && is_finite($fontSize) && $fontSize > 0.0) {
            $attrs['sourcePdfGeometryFontSize'] = $fontSize;
        }

        return $attrs;
    }

    private function withTableCellHtmlAttribute(array $attrs, string $name, string $value): array
    {
        if (!isset($attrs['attributes']) || !is_array($attrs['attributes'])) {
            $attrs['attributes'] = [];
        }
        if (!isset($attrs['htmlAttributes']) || !is_array($attrs['htmlAttributes'])) {
            $attrs['htmlAttributes'] = [];
        }

        $attrs['attributes'][$name] = $value;
        $attrs['htmlAttributes'][$name] = $value;

        return $attrs;
    }

    private function taggedTableHeaderHtmlId(mixed $identifier): string
    {
        if (!is_scalar($identifier)) {
            return '';
        }

        $token = $this->taggedHtmlToken((string) $identifier);
        if ($token === '') {
            return '';
        }

        return 'pdf-' . $token;
    }

    /**
     * @param array<string, mixed> $cell
     */
    private function taggedTableHeadersAttribute(array $cell): string
    {
        $headers = [];
        foreach ($this->taggedAttributeDictionaries($cell) as $attributeDictionary) {
            $owner = $attributeDictionary['O'] ?? null;
            if (is_string($owner) && strcasecmp($owner, 'Table') !== 0) {
                continue;
            }

            foreach ($this->taggedTableHeaderReferences($attributeDictionary['Headers'] ?? null) as $headerReference) {
                $headerId = $this->taggedTableHeaderHtmlId($headerReference);
                if ($headerId !== '') {
                    $headers[$headerId] = $headerId;
                }
            }
        }

        return implode(' ', array_values($headers));
    }

    /**
     * @return list<string>
     */
    private function taggedTableHeaderReferences(mixed $value): array
    {
        if (is_string($value) || is_int($value) || is_float($value)) {
            $value = trim((string) $value);
            return $value === '' ? [] : [$value];
        }

        if (!is_array($value)) {
            return [];
        }

        $references = [];
        foreach ($value as $item) {
            foreach ($this->taggedTableHeaderReferences($item) as $reference) {
                $references[] = $reference;
            }
        }

        return $references;
    }

    /**
     * @param array<string, mixed> $cell
     */
    private function taggedTableHeaderScope(array $cell): string
    {
        foreach ($this->taggedAttributeDictionaries($cell) as $attributeDictionary) {
            $owner = $attributeDictionary['O'] ?? null;
            if (is_string($owner) && strcasecmp($owner, 'Table') !== 0) {
                continue;
            }

            $scope = $attributeDictionary['Scope'] ?? null;
            if (!is_string($scope)) {
                continue;
            }

            $normalized = strtolower(trim($scope));
            if ($normalized === 'column') {
                return 'col';
            }
            if ($normalized === 'row') {
                return 'row';
            }
        }

        return '';
    }

    private function tableCell(string $text, int $rowspan = 1, int $colspan = 1, array $attrs = []): AstNode
    {
        $text = $this->repairPdfTableCellText($text);
        $attrs = array_replace($attrs, ['text' => $text]);
        if ($rowspan > 1) {
            $attrs['rowspan'] = $rowspan;
        }
        if ($colspan > 1) {
            $attrs['colspan'] = $colspan;
        }

        return new AstNode('table_cell', $attrs, [
            new AstNode('plain', ['text' => $text], $this->inlines($text)),
        ]);
    }

    private function repairPdfTableCellText(string $text): string
    {
        $text = trim($text);
        if ($text === '') {
            return '';
        }

        $text = preg_replace('/(?<=[\p{L}])([:;])(?=[\p{L}\d])/u', '$1 ', $text) ?? $text;
        $text = preg_replace('/(?<!\d)\.(?=[A-Z][a-z])/u', '. ', $text) ?? $text;
        $text = preg_replace('/(?<=[\p{Ll}])(\d+)(?=[:;])/u', ' $1', $text) ?? $text;
        $text = preg_replace('/(?<=\d)\s+,(?=\d)/u', ',', $text) ?? $text;
        $text = preg_replace('/(?<=\d,)\s+(?=\d{3}(?:\.\d{2})?\b)/u', '', $text) ?? $text;
        $text = preg_replace('/(?<=\d)(?=[\p{L}]{2,}\s+\d)/u', ' ', $text) ?? $text;
        $text = preg_replace('/\s+/u', ' ', $text) ?? $text;
        if ($this->looksLikePdfProseTableCell($text)) {
            $text = preg_replace('/(?<=[\p{Ll}])(?=\d{1,4}[\p{L}])/u', ' ', $text) ?? $text;
            $text = preg_replace('/(?<=\d)(?=[\p{L}]{3,})/u', ' ', $text) ?? $text;
            $text = $this->repairGluedProseLine($text);
        }

        return trim($text);
    }

    private function looksLikePdfProseTableCell(string $text): bool
    {
        if (strlen($text) < 28) {
            return false;
        }

        if (preg_match_all('/\p{L}/u', $text, $letters) === false) {
            return false;
        }
        $letterCount = count($letters[0]);
        $nonSpaceCount = strlen(preg_replace('/\s+/u', '', $text) ?? $text);
        if ($nonSpaceCount === 0 || $letterCount / $nonSpaceCount < 0.55) {
            return false;
        }

        if (preg_match_all('/[\p{L}]{3,}/u', $text, $words) === false) {
            return false;
        }
        $longAlphaRun = false;
        foreach ($words[0] as $word) {
            if (strlen($word) >= 18) {
                $longAlphaRun = true;
                break;
            }
        }
        if (count($words[0]) < 3 && !$longAlphaRun) {
            return false;
        }

        return preg_match('/(?:[a-z]{2,}(?:of|in|to|as|and|the|with|from|for|by)[a-z]{2,}|[a-z]\d+[a-z]|[a-z]{12,})/iu', $text) === 1;
    }

    private function positiveSpan(mixed $value): int
    {
        if (is_int($value) || is_float($value) || (is_string($value) && is_numeric($value))) {
            return max(1, (int) $value);
        }

        return 1;
    }

    /**
     * @return array{bool, string, ?int}|null
     */
    private function listItem(string $line): ?array
    {
        if (preg_match('/^\s*(?:[-*]|[\x{2022}\x{25CF}\x{25AA}\x{25A0}\x{2043}])\s+(.+)$/u', $line, $match)) {
            return [false, trim($match[1]), null];
        }
        if (preg_match('/^\s*(\d+)([.)])\s+(.+)$/u', $line, $match)) {
            // A four-digit value followed by either conventional list
            // delimiter is ordinarily a citation year starting prose, not an
            // ordered-list marker. Genuine high-ordinal lists are recovered
            // by listItemAt() only when an adjacent sibling proves the
            // numeric sequence.
            if (strlen($match[1]) === 4) {
                return null;
            }

            return [true, trim($match[3]), (int) $match[1]];
        }

        return null;
    }

    /**
     * @param list<string> $lines
     * @return array{bool, string, ?int}|null
     */
    private function listItemAt(array $lines, int $index): ?array
    {
        $line = $lines[$index] ?? '';
        $item = $this->listItem($line);
        if ($item !== null) {
            return $item;
        }

        $candidate = $this->ambiguousFourDigitListItem($line);
        if ($candidate === null) {
            return null;
        }
        $ordinal = $candidate[2];
        foreach ([$index - 1 => $ordinal - 1, $index + 1 => $ordinal + 1] as $siblingIndex => $expected) {
            if ($siblingIndex < 0) {
                continue;
            }
            $sibling = $this->ambiguousFourDigitListItem($lines[$siblingIndex] ?? '');
            if ($sibling !== null && $sibling[2] === $expected) {
                return $candidate;
            }
        }

        return null;
    }

    /** @return array{true, string, int}|null */
    private function ambiguousFourDigitListItem(string $line): ?array
    {
        if (preg_match('/^\s*(\d{4})[.)]\s+(.+)$/u', $line, $match) !== 1) {
            return null;
        }

        return [true, trim($match[2]), (int) $match[1]];
    }

    /**
     * @param list<string> $lines
     */
    private function numberedPdfLineLooksLikeSectionHeading(array $lines, int $index): bool
    {
        $line = $lines[$index] ?? '';
        if (preg_match('/^\s*(\d+(?:\.\d+)*)(?:\.)?\s+(.+)$/u', $line, $matches) !== 1
            || preg_match('/^\p{Lu}/u', $matches[2]) !== 1
            || !$this->repairedLineLooksLikeSectionLabel($matches[2])) {
            return false;
        }

        if ($this->listItemAt($lines, $index) !== null
            && $this->ambiguousFourDigitListItem($line) !== null) {
            return false;
        }

        // A final item has no following sibling to inspect, so also retain a
        // list when its immediately preceding item proves the sequence.
        $previous = $lines[$index - 1] ?? null;
        if ($previous !== null
            && preg_match('/^\s*(\d+)\.\s+/', $previous, $previousMatches) === 1
            && preg_match('/^\d+$/', $matches[1]) === 1
            && (int) $matches[1] === (int) $previousMatches[1] + 1) {
            return false;
        }

        $next = $lines[$index + 1] ?? null;
        if ($next === null) {
            return false;
        }
        $nextItem = $this->listItemAt($lines, $index + 1);
        if ($nextItem === null || $nextItem[0] !== true) {
            return true;
        }
        if (preg_match('/^\s*(\d+)\./u', $next, $nextMatches) !== 1) {
            return true;
        }

        return (int) $nextMatches[1] !== (int) $matches[1] + 1;
    }

    /**
     * @return list<AstNode>|null
     */
    private function blocksFromLineWithEmbeddedLists(string $line): ?array
    {
        $markers = $this->embeddedListMarkers($line);
        [$allowBullets, $allowOrdered] = $this->embeddedListMarkerPermissions($markers);
        if (!$allowBullets && !$allowOrdered) {
            return null;
        }

        $markers = array_values(array_filter(
            $markers,
            static fn (array $marker): bool => $marker['type'] === 'bullet' ? $allowBullets : $allowOrdered
        ));
        if (count($markers) < 2) {
            return null;
        }

        $blocks = [];
        $prefix = trim(substr($line, 0, $markers[0]['offset']));
        if ($prefix !== '') {
            $blocks[] = $this->paragraph($this->repairGluedProseLine($prefix));
        }

        $index = 0;
        $markerCount = count($markers);
        while ($index < $markerCount) {
            $type = $markers[$index]['type'];
            $ordered = $type === 'ordered';
            $items = [];
            $start = $ordered ? $markers[$index]['number'] : null;
            while ($index < $markerCount && $markers[$index]['type'] === $type) {
                $nextOffset = $markers[$index + 1]['offset'] ?? strlen($line);
                $text = trim(substr($line, $markers[$index]['contentOffset'], $nextOffset - $markers[$index]['contentOffset']));
                if ($text !== '') {
                    $items[] = new AstNode('list_item', [], [$this->paragraph($this->repairGluedProseLine($text))]);
                }
                $index++;
            }
            if ($items === []) {
                continue;
            }

            $attrs = [];
            if ($ordered && $start !== null && $start !== 1) {
                $attrs['start'] = $start;
            }
            $blocks[] = new AstNode($ordered ? 'ordered_list' : 'bullet_list', $attrs, $items);
        }

        return count($blocks) >= 2 ? $blocks : null;
    }

    private function lineHasPdfListBlockEvidence(string $line): bool
    {
        if ($this->listItem($line) !== null || $this->lineLooksLikePdfReferenceEntry($line)) {
            return true;
        }

        [$allowBullets, $allowOrdered] = $this->embeddedListMarkerPermissions($this->embeddedListMarkers($line));

        return $allowBullets || $allowOrdered;
    }

    private function lineLooksLikePdfReferenceEntry(string $line): bool
    {
        return preg_match('/^\s*\[\d+(?:[,.\-\x{2013}\x{2014}]\d+)*\]\s+/u', $line) === 1;
    }

    private function pdfReferenceEntryEndsWithUrl(string $line): bool
    {
        return preg_match('/(?:https?:\/\/|www\.)\S+[.)]\s*$/i', rtrim($line)) === 1;
    }

    /**
     * @param list<array{type: string, number: ?int, offset: int, contentOffset: int}> $markers
     * @return array{bool, bool}
     */
    private function embeddedListMarkerPermissions(array $markers): array
    {
        if ($markers === []) {
            return [false, false];
        }

        $bulletCount = 0;
        $orderedNumbers = [];
        foreach ($markers as $marker) {
            if ($marker['type'] === 'bullet') {
                $bulletCount++;
                continue;
            }
            $orderedNumbers[] = $marker['number'];
        }

        return [$bulletCount >= 2, $this->embeddedOrderedMarkersLookSequential($orderedNumbers)];
    }

    /**
     * @return list<array{type: string, number: ?int, offset: int, contentOffset: int}>
     */
    private function embeddedListMarkers(string $line): array
    {
        $markers = [];
        if (preg_match_all('/(?:^|(?<=\s))[\x{2022}\x{25CF}\x{25AA}\x{25A0}\x{2043}]\s+/u', $line, $matches, PREG_OFFSET_CAPTURE) !== false) {
            foreach ($matches[0] as $match) {
                $markers[] = [
                    'type' => 'bullet',
                    'number' => null,
                    'offset' => $match[1],
                    'contentOffset' => $match[1] + strlen($match[0]),
                ];
            }
        }
        if (preg_match_all('/(?:^|(?<![\p{L}\p{N}\(\p{Pd}]))(\d{1,2})[.)]\s+(?=\S)/u', $line, $matches, PREG_OFFSET_CAPTURE) !== false) {
            foreach ($matches[0] as $index => $match) {
                $markers[] = [
                    'type' => 'ordered',
                    'number' => (int) $matches[1][$index][0],
                    'offset' => $match[1],
                    'contentOffset' => $match[1] + strlen($match[0]),
                ];
            }
        }

        usort($markers, static fn (array $left, array $right): int => $left['offset'] <=> $right['offset']);

        return $markers;
    }

    /**
     * @param list<int|null> $numbers
     */
    private function embeddedOrderedMarkersLookSequential(array $numbers): bool
    {
        if (count($numbers) < 2) {
            return false;
        }

        $previous = null;
        $hasProgression = false;
        foreach ($numbers as $number) {
            if (!is_int($number) || $number < 1) {
                return false;
            }
            if ($previous !== null) {
                if ($number === 1) {
                    $previous = $number;
                    continue;
                }
                if ($number !== $previous + 1) {
                    return false;
                }
                $hasProgression = true;
            }
            $previous = $number;
        }

        return $hasProgression;
    }

    private function looksLikeHeading(string $line, int $index, int $lineCount): bool
    {
        if ($lineCount < 2 || strlen($line) > 96) {
            return false;
        }
        if (preg_match('/[.!?,;]\s*$/u', $line)) {
            return false;
        }
        if ($index === 0) {
            return true;
        }

        // A capitalized first word is normal sentence prose. Without tagged
        // PDF structure or retained style metadata, require a real title
        // pattern before promoting a line to a heading. This keeps wrapped
        // sentence fragments out of the document outline.
        return $this->repairedLineLooksLikeSectionLabel($line);
    }

    /**
     * Apply only one-to-one, byte-exact positioned-font receipts. Text
     * changed by semantic repair, duplicated source text, or competing layout
     * candidates is deliberately left unstyled.
     *
     * @param list<AstNode> $blocks
     * @param list<array<string,mixed>> $proofCandidates
     * @return list<AstNode>
     */
    private function blocksWithPdfInlineFontStyles(
        array $blocks,
        array $proofCandidates
    ): array {
        $proofsByIdentity = [];
        $seenDigests = [];
        foreach ($proofCandidates as $candidate) {
            $proof = $this->validatedPdfInlineFontStyleProof($candidate);
            if ($proof === null || isset($seenDigests[$proof['proofDigest']])) {
                continue;
            }
            $seenDigests[$proof['proofDigest']] = true;
            $identity = $this->pdfInlineFontStyleSourceIdentityKey($proof);
            if ($identity !== null) {
                $proofsByIdentity[$identity][] = $proof;
            }
        }
        foreach ($proofsByIdentity as $identity => $proofs) {
            if (count($proofs) !== 1) {
                unset($proofsByIdentity[$identity]);
            }
        }
        $targetNodeIdsByIdentity = [];
        $collectTargets = function (array $nodes) use (
            &$collectTargets,
            &$targetNodeIdsByIdentity,
            $proofsByIdentity
        ): void {
            foreach ($nodes as $node) {
                if (in_array($node->type, ['paragraph', 'heading', 'plain'], true)) {
                    $text = $node->attr('text');
                    $span = $node->attr('sourcePdfExactMergedLineSpan');
                    $identity = is_string($text) && is_array($span)
                        && $this->repairedPdfMergedLineHasExactWholeSourceSpan($text, $span)
                            ? $this->pdfInlineFontStyleSourceIdentityKey($span)
                            : null;
                    $proof = is_string($identity)
                        ? ($proofsByIdentity[$identity][0] ?? null)
                        : null;
                    if (is_array($proof)
                        && hash_equals((string) $proof['text'], $text)
                        && hash_equals(
                            (string) $proof['projectionDigest'],
                            hash('sha256', $this->pdfSourceOccurrenceComparableText($text))
                        )) {
                        $targetNodeIdsByIdentity[$identity][] = spl_object_id($node);
                    }
                }
                if ($node->children !== []) {
                    $collectTargets($node->children);
                }
            }
        };
        $collectTargets($blocks);
        $proofsByNodeId = [];
        foreach ($proofsByIdentity as $identity => $proofs) {
            $nodeIds = $targetNodeIdsByIdentity[$identity] ?? [];
            if (count($nodeIds) === 1) {
                $proofsByNodeId[$nodeIds[0]] = $proofs[0];
            }
        }

        return $this->pdfAstNodesWithInlineFontStyleProofs($blocks, $proofsByNodeId);
    }

    /** @return array<string,mixed>|null */
    private function validatedPdfInlineFontStyleProof(array $proof): ?array
    {
        $text = $proof['text'] ?? null;
        $digest = $proof['proofDigest'] ?? null;
        if (($proof['version'] ?? null) !== 2
            || ($proof['method'] ?? null)
                !== 'positioned-font-resource-base-font-exact-source'
            || ($proof['sourceSha256'] ?? null) !== $this->sourceSha256
            || !is_string($text)
            || $text === ''
            || ($proof['textDigest'] ?? null) !== hash('sha256', $text)
            || ($proof['projectionDigest'] ?? null) !== hash(
                'sha256',
                $this->pdfSourceOccurrenceComparableText($text)
            )
            || !is_array($proof['exactSourceRanges'] ?? null)
            || !array_is_list($proof['exactSourceRanges'])
            || $proof['exactSourceRanges'] === []
            || !is_array($proof['sourceOccurrenceIds'] ?? null)
            || !array_is_list($proof['sourceOccurrenceIds'])
            || $proof['sourceOccurrenceIds'] === []
            || count(array_unique($proof['sourceOccurrenceIds'], SORT_STRING))
                !== count($proof['sourceOccurrenceIds'])
            || !is_array($proof['globalSourceIndexes'] ?? null)
            || !array_is_list($proof['globalSourceIndexes'])
            || count($proof['globalSourceIndexes'])
                !== count($proof['sourceOccurrenceIds'])
            || !is_array($proof['spans'] ?? null)
            || !is_string($digest)
            || preg_match('/^[a-f0-9]{64}$/D', $digest) !== 1) {
            return null;
        }
        foreach ($proof['sourceOccurrenceIds'] as $sourceId) {
            if (!is_string($sourceId) || $sourceId === '') {
                return null;
            }
        }
        $rangeSourceIndexes = [];
        $rangeBytes = 0;
        $previousRange = null;
        foreach ($proof['exactSourceRanges'] as $range) {
            if (!is_array($range)
                || !is_int($range['sourceIndex'] ?? null)
                || !is_int($range['sourceStart'] ?? null)
                || !is_int($range['sourceEnd'] ?? null)
                || $range['sourceIndex'] < 0
                || $range['sourceStart'] < 0
                || $range['sourceEnd'] <= $range['sourceStart']
                || ($previousRange !== null
                    && ($range['sourceIndex'] < $previousRange['sourceIndex']
                        || ($range['sourceIndex'] === $previousRange['sourceIndex']
                            && $range['sourceStart'] !== $previousRange['sourceEnd'])))) {
                return null;
            }
            $rangeSourceIndexes[$range['sourceIndex']] = true;
            $rangeBytes += $range['sourceEnd'] - $range['sourceStart'];
            $previousRange = $range;
        }
        if ($rangeBytes !== strlen($this->pdfSourceOccurrenceComparableText($text))
            || count($rangeSourceIndexes) !== count($proof['sourceOccurrenceIds'])) {
            return null;
        }
        $previousGlobalIndex = null;
        foreach ($proof['globalSourceIndexes'] as $globalSourceIndex) {
            if (!is_int($globalSourceIndex)
                || $globalSourceIndex < 0
                || ($previousGlobalIndex !== null
                    && $globalSourceIndex !== $previousGlobalIndex + 1)) {
                return null;
            }
            $previousGlobalIndex = $globalSourceIndex;
        }
        $digestPayload = $proof;
        unset($digestPayload['proofDigest']);
        if (!hash_equals(
            $digest,
            hash(
                'sha256',
                json_encode($digestPayload, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE) ?: ''
            )
        )) {
            return null;
        }
        $spans = $this->normalizedPositionedInlineFontStyleSpans($text, $proof['spans']);
        if ($spans === []) {
            return null;
        }
        $proof['spans'] = $spans;

        return $proof;
    }

    /** @param array<string,mixed> $identity */
    private function pdfInlineFontStyleSourceIdentityKey(array $identity): ?string
    {
        $sourceSha256 = $identity['sourceSha256'] ?? null;
        $sourceOccurrenceIds = $identity['sourceOccurrenceIds'] ?? null;
        $globalSourceIndexes = $identity['globalSourceIndexes'] ?? null;
        $projectionDigest = $identity['projectionDigest'] ?? null;
        if (!is_string($sourceSha256)
            || !hash_equals($this->sourceSha256, $sourceSha256)
            || !is_array($sourceOccurrenceIds)
            || !array_is_list($sourceOccurrenceIds)
            || $sourceOccurrenceIds === []
            || !is_array($globalSourceIndexes)
            || !array_is_list($globalSourceIndexes)
            || count($globalSourceIndexes) !== count($sourceOccurrenceIds)
            || !is_string($projectionDigest)
            || preg_match('/^[a-f0-9]{64}$/D', $projectionDigest) !== 1) {
            return null;
        }
        $encoded = json_encode([
            'sourceSha256' => $sourceSha256,
            'sourceOccurrenceIds' => $sourceOccurrenceIds,
            'globalSourceIndexes' => $globalSourceIndexes,
            'projectionDigest' => $projectionDigest,
        ], JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);

        return is_string($encoded) ? hash('sha256', $encoded) : null;
    }

    /**
     * @param list<AstNode> $nodes
     * @param array<int,array<string,mixed>> $proofsByNodeId
     * @return list<AstNode>
     */
    private function pdfAstNodesWithInlineFontStyleProofs(
        array $nodes,
        array $proofsByNodeId
    ): array {
        $styled = [];
        foreach ($nodes as $node) {
            $text = in_array($node->type, ['paragraph', 'heading', 'plain'], true)
                ? $node->attr('text')
                : null;
            $proof = $proofsByNodeId[spl_object_id($node)] ?? null;
            $attrs = $node->baseAttrs();
            unset($attrs['sourcePdfExactMergedLineSpan']);
            if (is_array($proof)
                && $this->pdfAstInlineText($node->children) === $text) {
                $offset = 0;
                $children = $this->pdfAstInlineNodesWithFontStyleSpans(
                    $node->children,
                    $proof['spans'],
                    $offset
                );
                if ($offset === strlen($text)) {
                    $styled[] = new AstNode(
                        $node->type,
                        $attrs,
                        $children,
                        $node->attributeResolver()
                    );
                    continue;
                }
            }

            $children = $node->children === []
                ? []
                : $this->pdfAstNodesWithInlineFontStyleProofs(
                    $node->children,
                    $proofsByNodeId
                );
            $styled[] = new AstNode(
                    $node->type,
                    $attrs,
                    $children,
                    $node->attributeResolver()
                );
        }

        return $styled;
    }

    /** @param list<AstNode> $nodes */
    private function pdfAstInlineText(array $nodes): string
    {
        $text = '';
        foreach ($nodes as $node) {
            if ($node->type === 'text') {
                $text .= (string) $node->attr('text', '');
                continue;
            }
            $text .= $this->pdfAstInlineText($node->children);
        }

        return $text;
    }

    /**
     * @param list<AstNode> $nodes
     * @param list<array<string,mixed>> $spans
     * @return list<AstNode>
     */
    private function pdfAstInlineNodesWithFontStyleSpans(
        array $nodes,
        array $spans,
        int &$offset,
        bool $insideBold = false,
        bool $insideItalic = false
    ): array {
        $styled = [];
        foreach ($nodes as $node) {
            if ($node->type !== 'text') {
                $children = $this->pdfAstInlineNodesWithFontStyleSpans(
                    $node->children,
                    $spans,
                    $offset,
                    $insideBold || $node->type === 'strong',
                    $insideItalic || $node->type === 'emph'
                );
                $styled[] = new AstNode(
                    $node->type,
                    $node->baseAttrs(),
                    $children,
                    $node->attributeResolver()
                );
                continue;
            }

            $leafText = (string) $node->attr('text', '');
            $leafStart = $offset;
            $leafEnd = $leafStart + strlen($leafText);
            $cuts = [$leafStart, $leafEnd];
            foreach ($spans as $span) {
                $start = (int) $span['start'];
                $end = (int) $span['end'];
                if ($start > $leafStart && $start < $leafEnd) {
                    $cuts[] = $start;
                }
                if ($end > $leafStart && $end < $leafEnd) {
                    $cuts[] = $end;
                }
            }
            $cuts = array_values(array_unique($cuts));
            sort($cuts, SORT_NUMERIC);
            for ($cutIndex = 0, $cutCount = count($cuts) - 1; $cutIndex < $cutCount; $cutIndex++) {
                $start = $cuts[$cutIndex];
                $end = $cuts[$cutIndex + 1];
                if ($end <= $start) {
                    continue;
                }
                $piece = substr($leafText, $start - $leafStart, $end - $start);
                $bold = false;
                $italic = false;
                foreach ($spans as $span) {
                    if ($start >= (int) $span['start'] && $end <= (int) $span['end']) {
                        $bold = ($span['bold'] ?? false) === true;
                        $italic = ($span['italic'] ?? false) === true;
                        break;
                    }
                }
                $pieceNode = new AstNode('text', ['text' => $piece]);
                if ($italic && !$insideItalic) {
                    $pieceNode = new AstNode('emph', [], [$pieceNode]);
                }
                if ($bold && !$insideBold) {
                    $pieceNode = new AstNode('strong', [], [$pieceNode]);
                }
                $styled[] = $pieceNode;
            }
            $offset = $leafEnd;
        }

        return $styled;
    }

    private function paragraph(string $text, array $attrs = []): AstNode
    {
        return new AstNode('paragraph', array_replace($attrs, ['text' => $text]), $this->inlines($text));
    }

    /**
     * Internal PDF destinations remain useful only when the editable output
     * contains their targets. Attach each requested page id to the first
     * semantic block carrying text from that page; unresolved destinations
     * stay in diagnostics but are not applied as broken links.
     *
     * @param list<AstNode> $blocks
     * @param list<array<string, mixed>> $annotations
     * @param list<array<string, mixed>> $lineItems
     * @return array{blocks:list<AstNode>,anchors:array<string,true>}
     */
    private function blocksWithInternalPdfPageAnchors(array $blocks, array $annotations, array $lineItems): array
    {
        $targetPages = [];
        foreach ($annotations as $annotation) {
            $uri = is_array($annotation) ? (string) ($annotation['uri'] ?? '') : '';
            if (preg_match('/^#pdf-page-([1-9][0-9]*)$/', $uri, $match) === 1) {
                $targetPages[(int) $match[1]] = true;
            }
        }
        if ($targetPages === []) {
            return ['blocks' => $blocks, 'anchors' => []];
        }
        ksort($targetPages);

        $candidateTextsByPage = [];
        foreach ($lineItems as $item) {
            $page = max(1, (int) ($item['page'] ?? 1));
            if (!isset($targetPages[$page])) {
                continue;
            }
            $text = trim((string) ($item['text'] ?? ''));
            $key = $this->pdfComparableLineText($text);
            if ($key !== '') {
                $candidateTextsByPage[$page][$key] = true;
            }
        }

        $anchors = [];
        foreach (array_keys($targetPages) as $page) {
            $id = 'pdf-page-' . $page;
            $candidateKeys = array_keys($candidateTextsByPage[$page] ?? []);
            foreach ($blocks as $index => $block) {
                if ((string) $block->attr('id', '') !== '') {
                    continue;
                }
                $blockKey = $this->pdfComparableLineText($this->pdfAstNodeVisibleText($block));
                if ($blockKey === '') {
                    continue;
                }
                $matchesPageText = false;
                foreach ($candidateKeys as $candidateKey) {
                    $candidateKey = (string) $candidateKey;
                    if ($candidateKey === $blockKey
                        || ($this->length($candidateKey) >= 4 && str_contains($blockKey, $candidateKey))
                        || ($this->length($blockKey) >= 8 && str_contains($candidateKey, $blockKey))) {
                        $matchesPageText = true;
                        break;
                    }
                }
                if (!$matchesPageText) {
                    continue;
                }

                $attrs = $block->attrs;
                $attrs['id'] = $id;
                $htmlAttributes = is_array($attrs['htmlAttributes'] ?? null) ? $attrs['htmlAttributes'] : [];
                $htmlAttributes['id'] = $id;
                $attrs['htmlAttributes'] = $htmlAttributes;
                $blocks[$index] = new AstNode($block->type, $attrs, $block->children);
                $anchors['#' . $id] = true;
                break;
            }
        }

        return ['blocks' => $blocks, 'anchors' => $anchors];
    }

    private function pdfAstNodeVisibleText(AstNode $node): string
    {
        if ($node->children === []) {
            return (string) $node->attr('text', '');
        }

        $parts = [];
        foreach ($node->children as $child) {
            $text = $this->pdfAstNodeVisibleText($child);
            if ($text !== '') {
                $parts[] = $text;
            }
        }

        return implode(' ', $parts);
    }

    /**
     * @param list<array<string, mixed>> $annotations
     * @param list<AstNode> $blocks
     * @return list<array<string, mixed>>
     */
    private function unambiguousLinkAnnotations(array $annotations, array $blocks): array
    {
        $normalized = [];
        foreach ($annotations as $annotation) {
            if (!is_array($annotation)) {
                continue;
            }
            $text = trim(preg_replace('/\s+/u', ' ', (string) ($annotation['text'] ?? '')) ?? (string) ($annotation['text'] ?? ''));
            $uri = trim((string) ($annotation['uri'] ?? ''));
            if ($text === '' || $uri === '') {
                continue;
            }
            // Prefer an exact final-text match. Annotation geometry can have
            // a different idea of word spacing than the text stream, so a
            // unique whitespace-only reconciliation is also safe. Never
            // reconcile across nodes or accept a duplicate label.
            $matchedText = $this->uniqueLinkAnnotationTextMatch($blocks, $text)
                ?? $this->uniqueWhitespaceReconciledLinkAnnotationTextMatch($blocks, $text);
            if ($matchedText === null) {
                continue;
            }

            $normalizedAnnotation = $annotation;
            $normalizedAnnotation['text'] = $matchedText;
            $normalizedAnnotation['uri'] = $uri;
            if ($matchedText !== $text) {
                $normalizedAnnotation['annotationText'] = $text;
            }
            $normalized[] = $normalizedAnnotation + [
                'text' => $matchedText,
                'uri' => $uri,
            ];
        }

        return $normalized;
    }

    /**
     * @param list<AstNode> $blocks
     */
    private function uniqueLinkAnnotationTextMatch(array $blocks, string $label): ?string
    {
        if ($label === '') {
            return null;
        }

        $matches = 0;
        foreach ($this->linkAnnotationTextNodes($blocks) as $text) {
            $offset = 0;
            while (($position = strpos($text, $label, $offset)) !== false) {
                $matches++;
                if ($matches > 1) {
                    return null;
                }
                $offset = $position + strlen($label);
            }
        }

        return $matches === 1 ? $label : null;
    }

    /**
     * @param list<AstNode> $blocks
     */
    private function uniqueWhitespaceReconciledLinkAnnotationTextMatch(array $blocks, string $label): ?string
    {
        $compact = preg_replace('/\s+/u', '', $label) ?? $label;
        if ($this->length($compact) < 5 || preg_match('/[\p{L}\p{N}]/u', $compact) !== 1) {
            return null;
        }

        $characters = preg_split('//u', $compact, -1, PREG_SPLIT_NO_EMPTY);
        if ($characters === false || $characters === []) {
            return null;
        }
        $startsWithWord = preg_match('/^[\p{L}\p{N}]$/u', $characters[0]) === 1;
        $endsWithWord = preg_match('/[\p{L}\p{N}]$/u', $characters[array_key_last($characters)]) === 1;
        $pattern = '/'
            . ($startsWithWord ? '(?<![\p{L}\p{N}])' : '')
            . implode('\\s*', array_map(static fn (string $character): string => preg_quote($character, '/'), $characters))
            . ($endsWithWord ? '(?![\p{L}\p{N}])' : '')
            . '/u';

        $matches = [];
        foreach ($this->linkAnnotationTextNodes($blocks) as $text) {
            $foundCount = preg_match_all($pattern, $text, $found);
            if ($foundCount === false || $foundCount === 0) {
                continue;
            }
            foreach ($found[0] ?? [] as $match) {
                if ((preg_replace('/\s+/u', '', $match) ?? $match) !== $compact) {
                    continue;
                }
                $matches[] = $match;
                if (count($matches) > 1) {
                    return null;
                }
            }
        }

        return $matches[0] ?? null;
    }

    /**
     * @param list<AstNode> $nodes
     * @return list<string>
     */
    private function linkAnnotationTextNodes(array $nodes): array
    {
        $texts = [];
        foreach ($nodes as $node) {
            $text = $node->attr('text');
            if (is_string($text) && in_array($node->type, ['paragraph', 'heading', 'plain'], true)) {
                $texts[] = $text;
            }
            if ($node->children !== []) {
                array_push($texts, ...$this->linkAnnotationTextNodes($node->children));
            }
        }

        return $texts;
    }

    /**
     * @param list<AstNode> $blocks
     * @param list<array<string, mixed>> $annotations
     * @return list<AstNode>
     */
    private function applyLinkAnnotationsToBlocks(array $blocks, array $annotations): array
    {
        return array_map(fn (AstNode $block): AstNode => $this->applyLinkAnnotationsToNode($block, $annotations), $blocks);
    }

    /**
     * @param list<array<string, mixed>> $annotations
     */
    private function applyLinkAnnotationsToNode(AstNode $node, array $annotations): AstNode
    {
        $children = array_map(fn (AstNode $child): AstNode => $this->applyLinkAnnotationsToNode($child, $annotations), $node->children);
        $text = $node->attr('text');
        if (is_string($text) && in_array($node->type, ['paragraph', 'heading', 'plain'], true)) {
            return new AstNode($node->type, $node->attrs, $this->inlinesWithLinkAnnotations($text, $annotations));
        }

        return $children === $node->children ? $node : new AstNode($node->type, $node->attrs, $children);
    }

    /**
     * @param list<array<string, mixed>> $annotations
     * @return list<AstNode>
     */
    private function inlinesWithLinkAnnotations(string $text, array $annotations): array
    {
        $matches = [];
        foreach ($annotations as $annotation) {
            $label = (string) ($annotation['text'] ?? '');
            $uri = (string) ($annotation['uri'] ?? '');
            if ($label === '' || $uri === '') {
                continue;
            }
            $position = strpos($text, $label);
            if ($position === false) {
                continue;
            }
            $matches[] = [
                'start' => $position,
                'end' => $position + strlen($label),
                'text' => $label,
                'uri' => $uri,
            ];
        }
        if ($matches === []) {
            return $this->inlines($text);
        }

        usort($matches, static fn (array $a, array $b): int => $a['start'] <=> $b['start']);
        $nodes = [];
        $offset = 0;
        foreach ($matches as $match) {
            if ($match['start'] < $offset) {
                continue;
            }
            $before = substr($text, $offset, $match['start'] - $offset);
            if ($before !== '') {
                array_push($nodes, ...$this->inlines($before));
            }

            $nodes[] = new AstNode('link', ['url' => $match['uri'], 'title' => ''], [
                new AstNode('text', ['text' => $match['text']]),
            ]);
            $offset = $match['end'];
        }

        $after = substr($text, $offset);
        if ($after !== '') {
            array_push($nodes, ...$this->inlines($after));
        }

        return $nodes === [] ? $this->inlines($text) : $nodes;
    }

    /**
     * @return list<AstNode>
     */
    private function inlines(string $text): array
    {
        if (!preg_match_all('/https?:\/\/[^\s<>"\']+/i', $text, $matches, PREG_OFFSET_CAPTURE)) {
            return [new AstNode('text', ['text' => $text])];
        }

        $nodes = [];
        $offset = 0;
        foreach ($matches[0] as [$url, $position]) {
            $before = substr($text, $offset, $position - $offset);
            if ($before !== '') {
                $nodes[] = new AstNode('text', ['text' => $before]);
            }

            $trimmedUrl = rtrim($url, '.,);]');
            $trailing = substr($url, strlen($trimmedUrl));
            $nodes[] = new AstNode('link', ['url' => $trimmedUrl, 'title' => ''], [
                new AstNode('text', ['text' => $trimmedUrl]),
            ]);
            if ($trailing !== '') {
                $nodes[] = new AstNode('text', ['text' => $trailing]);
            }
            $offset = $position + strlen($url);
        }

        $after = substr($text, $offset);
        if ($after !== '') {
            $nodes[] = new AstNode('text', ['text' => $after]);
        }

        return $nodes;
    }

    /**
     * @param list<AstNode> $nodes
     */
    private function countNodesOfType(array $nodes, string $type): int
    {
        $count = 0;
        foreach ($nodes as $node) {
            if ($node->type === $type) {
                $count++;
            }
            $count += $this->countNodesOfType($node->children, $type);
        }

        return $count;
    }

    /**
     * @param list<AstNode> $nodes
     */
    private function blocksHaveSuspiciousPdfTableText(array $nodes): bool
    {
        foreach ($nodes as $node) {
            if ($node->type === 'table_cell') {
                $text = trim($this->pdfAstNodeTextWithoutAttributeCache($node));
                if ($text !== '' && preg_match('/\b[A-Za-z]{24,}\b/u', $text) === 1) {
                    return true;
                }
            }
            if ($node->children !== [] && $this->blocksHaveSuspiciousPdfTableText($node->children)) {
                return true;
            }
        }

        return false;
    }

    /**
     * Dense figures can produce many cell-like regions even when they contain
     * ordinary prose. A document with several such large prose grids is not a
     * trustworthy geometry-table result, so let the text-table path decide
     * whether there is a real table instead.
     *
     * @param list<AstNode> $nodes
     */
    private function geometryPdfTableBlocksLookOversegmented(array $nodes): bool
    {
        $tableCount = 0;
        $proseGrids = 0;
        foreach ($this->geometryPdfTableNodes($nodes) as $table) {
            $tableCount++;
            $cellCount = 0;
            $longProseCells = 0;
            $veryLongProseCells = 0;
            $bulletCells = 0;
            $emptyCells = 0;
            $numericValueCells = 0;
            $rowCount = 0;
            $columnCount = 0;
            $this->accumulateGeometryPdfTableSegmentation(
                $table,
                $cellCount,
                $longProseCells,
                $veryLongProseCells,
                $bulletCells,
                $emptyCells,
                $numericValueCells,
                $rowCount,
                $columnCount
            );
            $emptyRatio = $cellCount === 0 ? 0.0 : $emptyCells / $cellCount;
            $numericValueRatio = $numericValueCells / max(1, $cellCount - $emptyCells);
            if ($rowCount >= 4
                && $columnCount >= 4
                && $emptyRatio >= 0.35
                && $veryLongProseCells >= 1
                && $numericValueRatio < 0.15) {
                // Magazine sidebars and parallel narrative columns can align
                // into a sparse grid with one enormous continuation cell.
                // One incidental number must not protect that page-layout
                // grid; a real data table has a recurring, substantial value
                // schema rather than a tiny fraction of numeric cells.
                return true;
            }
            if ($rowCount >= 10
                && $columnCount >= 4
                && $emptyRatio >= 0.35
                && $longProseCells >= 3
                && $bulletCells >= 5) {
                // This is a sparse multi-column page layout: narrative lines
                // and bullets happen to align on a grid, but empty spacer
                // columns dominate it. Treating it as a semantic table makes
                // reading order and list structure much worse.
                return true;
            }
            if ($longProseCells >= 3) {
                $proseGrids++;
            }
        }

        if ($tableCount < 6) {
            return false;
        }

        return $proseGrids >= max(3, (int) ceil($tableCount * 0.25));
    }

    /** @param list<AstNode> $nodes @return iterable<AstNode> */
    private function geometryPdfTableNodes(array $nodes): iterable
    {
        foreach ($nodes as $node) {
            if ($node->type === 'table') {
                yield $node;
            }
            $children = $node->children();
            if ($children !== []) {
                yield from $this->geometryPdfTableNodes($children);
            }
        }
    }

    private function accumulateGeometryPdfTableSegmentation(
        AstNode $candidate,
        int &$cellCount,
        int &$longProseCells,
        int &$veryLongProseCells,
        int &$bulletCells,
        int &$emptyCells,
        int &$numericValueCells,
        int &$rowCount,
        int &$columnCount
    ): void {
        $children = $candidate->children();
        if ($candidate->type === 'table_cell') {
            $cellCount++;
            $text = trim($this->pdfAstNodeTextWithoutAttributeCache($candidate));
            if ($text === '') {
                $emptyCells++;
            } else {
                $length = $this->length($text);
                $wordCount = count($this->pdfLineWordTokens($text));
                if ($length >= 72 || $wordCount >= 12) {
                    $longProseCells++;
                }
                if ($length >= 200 || $wordCount >= 30) {
                    $veryLongProseCells++;
                }
                if ($this->positionedCellIsNumericValue($text)) {
                    $numericValueCells++;
                }
                if (preg_match(
                    '/(?:^|\s)[\x{2022}\x{25CF}\x{25AA}\x{25A0}\x{2043}]\s*/u',
                    $text
                ) === 1) {
                    $bulletCells++;
                }
            }
        }
        if ($candidate->type === 'table_row') {
            $rowCount++;
            $width = 0;
            foreach ($children as $child) {
                if ($child->type === 'table_cell') {
                    $width++;
                }
            }
            $columnCount = max($columnCount, $width);
        }
        foreach ($children as $child) {
            $this->accumulateGeometryPdfTableSegmentation(
                $child,
                $cellCount,
                $longProseCells,
                $veryLongProseCells,
                $bulletCells,
                $emptyCells,
                $numericValueCells,
                $rowCount,
                $columnCount
            );
        }
    }

    private function pdfAstNodeTextWithoutAttributeCache(AstNode $node): string
    {
        $attrs = $node->baseAttrs();
        $resolver = $node->attributeResolver();
        if ($resolver !== null) {
            $attrs = $resolver->materialize($attrs, $node);
        }

        return is_string($attrs['text'] ?? null) ? $attrs['text'] : '';
    }

    /**
     * @return array<string, mixed>
     */
    private function documentStructuralMetadata(string $pdfBytes): array
    {
        if (!class_exists(PdfMetadataExtractor::class)) {
            return [];
        }

        try {
            return (new PdfMetadataExtractor())->extractReaderStructuralMetadata($pdfBytes);
        } catch (\Throwable) {
            // Structural provenance is optional. Do not fall back to scanning
            // arbitrary PDF bytes when the parser cannot establish it.
            return [];
        }
    }

    /**
     * @return array<string, mixed>
     */
    private function documentMetadata(string $pdfBytes): array
    {
        if (!class_exists(PdfMetadataExtractor::class)) {
            return [];
        }

        try {
            return (new PdfMetadataExtractor())->extractReaderMetadata($pdfBytes);
        } catch (\Throwable) {
            // Metadata is optional import provenance.  Do not fall back to
            // scanning arbitrary PDF bytes when the parser cannot establish
            // a bounded Info dictionary or Metadata stream.
            return [];
        }
    }

    /**
     * @param array<string, mixed> $metadata
     */
    private function metadataString(array $metadata, string $key): string
    {
        return is_string($metadata[$key] ?? null)
            ? $this->clipMetadataValue($metadata[$key])
            : '';
    }

    private function firstMetadataString(mixed $value): string
    {
        if (!is_array($value)) {
            return '';
        }

        foreach ($value as $item) {
            if (is_string($item) && $item !== '') {
                return $this->clipMetadataValue($item);
            }
        }

        return '';
    }

    private function clipMetadataValue(string $value): string
    {
        $value = trim(preg_replace('/\s+/', ' ', $value) ?? $value);
        if (strlen($value) <= 240) {
            return $value;
        }

        return rtrim(substr($value, 0, 237)) . '...';
    }
}
